import type { JSX } from "react";
import type { IntentBreakdown } from "../intentBreakdown";

export interface IntentConditionalBodyProps {
  breakdown: IntentBreakdown;
}

export function IntentConditionalBody({
  breakdown,
}: IntentConditionalBodyProps): JSX.Element {
  const asset = breakdown.slots.assets.label || "asset";
  const trigger = breakdown.slots.trigger.label;

  return (
    <div className="intent-conditional-body">
      <div className="intent-conditional-row">
        <span className="terminal-label">WHEN</span>
        <span className="intent-conditional-chip">${asset} · {trigger}</span>
      </div>
      <div className="intent-conditional-row">
        <span className="terminal-label">THEN</span>
        <span className="intent-conditional-chip">
          {breakdown.slots.direction.label} ${asset} · size 20%
        </span>
      </div>
      <div className="intent-conditional-sources">
        <span className="terminal-label">Sources</span>
        <span className="intent-source-chip">CPI</span>
        <span className="intent-source-chip">News</span>
        <span className="intent-source-chip">Macro</span>
      </div>
    </div>
  );
}
