import React from "react";
import "./layout.css";

export interface ModalTab<T extends string = string> {
  id: T;
  label: string;
}

export interface ModalTabBarProps<T extends string = string> {
  tabs: readonly ModalTab<T>[];
  activeTabId: T;
  onTabChange: (id: T) => void;
  disabled?: boolean;
  "aria-label"?: string;
}

export function ModalTabBar<T extends string = string>({
  tabs,
  activeTabId,
  onTabChange,
  disabled = false,
  "aria-label": ariaLabel,
}: ModalTabBarProps<T>): JSX.Element {
  const activeIndex = Math.max(
    0,
    tabs.findIndex((tab) => tab.id === activeTabId),
  );

  return (
    <div
      className="modal-tab-bar"
      role="tablist"
      aria-label={ariaLabel}
      style={
        {
          "--tab-count": tabs.length,
          "--active-index": activeIndex,
        } as React.CSSProperties
      }
    >
      {tabs.map((tab) => {
        const isActive = activeTabId === tab.id;
        return (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={isActive}
            className={`modal-tab${isActive ? " active" : ""}`}
            onClick={() => onTabChange(tab.id)}
            disabled={disabled}
          >
            {tab.label}
          </button>
        );
      })}
      <span className="modal-tab-indicator" aria-hidden />
    </div>
  );
}
