import { WELCOME_TOUR_STORAGE_KEY } from "../../mormv1/tutorials/welcome-tour/constants";

export function hasSeenWelcome(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(WELCOME_TOUR_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markWelcomeSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(WELCOME_TOUR_STORAGE_KEY, "1");
  } catch {
    // ignore
  }
}

export function clearWelcomeSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(WELCOME_TOUR_STORAGE_KEY);
  } catch {
    // ignore
  }
}
