function markerTimeUnix(marker: ChartExecutionMarker): number {
  return marker.time as number;
}

/** First index where marker time >= lo. */
function lowerBoundByTime(markers: ChartExecutionMarker[], lo: number): number {
  let left = 0;
  let right = markers.length;
  while (left < right) {
    const mid = (left + right) >> 1;
    if (markerTimeUnix(markers[mid]!) < lo) left = mid + 1;
    else right = mid;
  }
  return left;
}

/** First index where marker time > hi. */
function upperBoundByTime(markers: ChartExecutionMarker[], hi: number): number {
  let left = 0;
  let right = markers.length;
  while (left < right) {
    const mid = (left + right) >> 1;
    if (markerTimeUnix(markers[mid]!) <= hi) left = mid + 1;
    else right = mid;
  }
  return left;
}

/**
 * Markers whose unix time falls in [lo, hi], assuming `sortedMarkers` is sorted by time ascending.
 * Used to avoid laying out off-viewport markers on large token-taker charts.
 */
export function markersInVisibleTimeSlice(
  sortedMarkers: ChartExecutionMarker[],
  lo: number,
  hi: number,
): ChartExecutionMarker[] {
  if (sortedMarkers.length === 0 || lo > hi) return [];
  const start = lowerBoundByTime(sortedMarkers, lo);
  const end = upperBoundByTime(sortedMarkers, hi);
  if (start >= end) return [];
  return sortedMarkers.slice(start, end);
}

function visibleTimeBoundsFromLogicalRange(
  series: ISeriesApi<"Candlestick">,
  visibleRange: LogicalRange,
): { lo: number; hi: number } | null {
  const barsInfo = series.barsInLogicalRange({
    from: Math.floor(visibleRange.from) - 1,
    to: Math.ceil(visibleRange.to) + 1,
  });
  if (barsInfo?.from != null && barsInfo?.to != null) {
    const lo = barsInfo.from as number;
    const hi = barsInfo.to as number;
    return lo <= hi ? { lo, hi } : { lo: hi, hi: lo };
  }

  const data = series.data();
  if (data.length === 0) return null;
  return {
    lo: data[0]!.time as number,
    hi: data[data.length - 1]!.time as number,
  };
}

function sortMarkersByTime(markers: ChartExecutionMarker[]): ChartExecutionMarker[] {
  if (markers.length <= 1) return markers.slice();
  return [...markers].sort((a, b) => markerTimeUnix(a) - markerTimeUnix(b));
}

/** True when a marker timestamp falls inside loaded series data (may still be off-screen). */
function markersInLoadedSeriesRange(
  series: ISeriesApi<"Candlestick">,
  markers: ChartExecutionMarker[],
): boolean {
  if (markers.length === 0) return false;
  const data = series.data();
  if (data.length === 0) return false;
  const lo = data[0]!.time as number;
  const hi = data[data.length - 1]!.time as number;
  return markers.some((marker) => {
    const t = marker.time as number;
    return t >= lo && t <= hi;
  });
}

const TEXT_MARGIN = 0.1;
const MAX_RETRY_FRAMES = 10;
const MAX_RETRY_MS = 500;
export const MARKER_STACK_OVERLAP_RATIO = 0.2;
export const MARKER_STACK_MAX_PER_GROUP = 10;

export interface ExecutionMarkerLayoutItem {
  tradeId: string;
  x: number;
  y: number;
  fillSize: number;
  hitTestDiameter: number;
  shape: ChartExecutionMarker["shape"];
  color: string;
  label: string;
  imageUrl?: string;
  position: ChartExecutionMarker["position"];
  textX: number;
  textY: number;
  textWidth: number;
  textHeight: number;
  stackRank?: number;
}

interface LayoutItem extends ExecutionMarkerLayoutItem {}

interface RendererData {
  items: LayoutItem[];
  visibleFrom: number;
  visibleTo: number;
  barSpacing: number;
}

function getBarPrice(
  bar: CandlestickData,
  position: ChartExecutionMarker["position"],
  invertScale: boolean,
): number | undefined {
  if (position === "aboveBar") {
    return invertScale ? bar.low : bar.high;
  }
  if (position === "belowBar") {
    return invertScale ? bar.high : bar.low;
  }
  return undefined;
}

function layoutMarker(
  marker: ChartExecutionMarker,
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  barSpacing: number,
  fontSize: number,
): LayoutItem | null {
  const timeScale = chart.timeScale();
  const bar = resolveBarAtMarkerTime(chart, series, marker.time);
  if (!bar) return null;

  const x = timeScale.timeToCoordinate(bar.time) ?? timeScale.timeToCoordinate(marker.time);
  if (x === null) return null;

  const price = getBarPrice(bar, marker.position, series.priceScale().options().invertScale);
  if (price === undefined) return null;

  let y = series.priceToCoordinate(price);
  if (y === null) return null;

  const margin = executionMarkerShapeMargin(barSpacing);
  const fillSize = calculateMarkerShapeHeight(barSpacing, EXECUTION_MARKER_FILL_SIZE);
  const { borderDiameter } = calculateExecutionMarkerDrawSizes(barSpacing, marker.shape);
  const halfFill = fillSize / 2;

  if (marker.position === "aboveBar") {
    y -= halfFill + margin;
  } else {
    y += halfFill + margin;
  }

  const textHeight = fontSize;
  let textY = y;
  if (marker.position === "aboveBar") {
    textY = y - halfFill - textHeight * (0.5 + TEXT_MARGIN);
  } else {
    textY = y + halfFill + margin + textHeight * (0.5 + TEXT_MARGIN);
  }

  return {
    tradeId: marker.tradeId,
    x,
    y,
    fillSize,
    hitTestDiameter: borderDiameter,
    shape: marker.imageUrl ? "circle" : marker.shape,
    color: marker.color,
    label: marker.imageUrl ? "" : marker.label,
    imageUrl: marker.imageUrl,
    position: marker.position,
    textX: x,
    textY,
    textWidth: 0,
    textHeight,
    stackRank: marker.stackRank,
  };
}

function compareStackRankDesc(
  a: { stackRank?: number; tradeId: string },
  b: { stackRank?: number; tradeId: string },
): number {
  const rankA = a.stackRank ?? Number.NEGATIVE_INFINITY;
  const rankB = b.stackRank ?? Number.NEGATIVE_INFINITY;
  if (rankB !== rankA) return rankB - rankA;
  return a.tradeId.localeCompare(b.tradeId);
}

/** Offset avatar markers that share the same bar anchor so they stack with limited overlap. */
export function applyMarkerStackOffsets(items: ExecutionMarkerLayoutItem[]): ExecutionMarkerLayoutItem[] {
  const stackable = items.filter((item) => item.imageUrl);
  if (stackable.length === 0) return items;

  const dropIds = new Set<string>();
  const yDeltaByTradeId = new Map<string, number>();
  const groups = new Map<string, ExecutionMarkerLayoutItem[]>();

  for (const item of stackable) {
    const key = `${Math.round(item.x)}:${item.position}`;
    const group = groups.get(key) ?? [];
    group.push(item);
    groups.set(key, group);
  }

  for (const group of groups.values()) {
    group.sort(compareStackRankDesc);
    const capped = group.slice(0, MARKER_STACK_MAX_PER_GROUP);
    for (const extra of group.slice(MARKER_STACK_MAX_PER_GROUP)) {
      dropIds.add(extra.tradeId);
    }

    const stepPx = capped[0]!.hitTestDiameter * (1 - MARKER_STACK_OVERLAP_RATIO);
    capped.forEach((item, stackIndex) => {
      if (stackIndex === 0) return;
      const sign = item.position === "aboveBar" ? -1 : 1;
      yDeltaByTradeId.set(item.tradeId, sign * stepPx * stackIndex);
    });
  }

  return items
    .filter((item) => !dropIds.has(item.tradeId))
    .map((item) => {
      const delta = yDeltaByTradeId.get(item.tradeId);
      if (delta == null) return item;
      return { ...item, y: item.y + delta, textY: item.textY + delta };
    });
}

/** Layout markers using the same rules as resolveMarkerAnchorPoint (bubble overlay). */
export function layoutExecutionMarkerItems(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  markers: ChartExecutionMarker[],
  barSpacing: number,
  fontSize: number,
): ExecutionMarkerLayoutItem[] {
  const items: LayoutItem[] = [];
  let hasAvatarMarkers = false;
  for (const marker of markers) {
    const item = layoutMarker(marker, chart, series, barSpacing, fontSize);
    if (item) {
      items.push(item);
      if (marker.imageUrl) hasAvatarMarkers = true;
    }
  }
  return hasAvatarMarkers ? applyMarkerStackOffsets(items) : items;
}

/** Canvas center of a painted marker (includes stack offsets). */
export function resolveLaidOutMarkerAnchorPoint(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  tradeId: string,
  markers: ChartExecutionMarker[],
  barSpacing: number,
): MarkerAnchorPoint | null {
  const fontSize = chart.options().layout.fontSize;
  const items = layoutExecutionMarkerItems(chart, series, markers, barSpacing, fontSize);
  const item = items.find((entry) => entry.tradeId === tradeId);
  return item ? { x: item.x, y: item.y } : null;
}

function bitmapCoords(
  x: number,
  y: number,
  horizontalPixelRatio: number,
  verticalPixelRatio: number,
): { x: number; y: number; pixelRatio: number } {
  const tickWidth = Math.max(1, Math.floor(horizontalPixelRatio));
  const correction = (tickWidth % 2) / 2;
  return {
    x: Math.round(x * horizontalPixelRatio) + correction,
    y: y * verticalPixelRatio,
    pixelRatio: horizontalPixelRatio,
  };
}

function drawCircle(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  pixelDiameter: number,
): void {
  const halfSize = (pixelDiameter - 1) / 2;
  ctx.beginPath();
  ctx.arc(coords.x, coords.y, halfSize * coords.pixelRatio, 0, 2 * Math.PI, false);
  ctx.fill();
}

function drawSquare(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  pixelDiameter: number,
): void {
  const halfSize = ((pixelDiameter - 1) * coords.pixelRatio) / 2;
  const left = coords.x - halfSize;
  const top = coords.y - halfSize;
  ctx.fillRect(left, top, pixelDiameter * coords.pixelRatio, pixelDiameter * coords.pixelRatio);
}

function drawShape(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  pixelDiameter: number,
  shape: ChartExecutionMarker["shape"],
): void {
  if (shape === "circle") {
    drawCircle(ctx, coords, pixelDiameter);
  } else {
    drawSquare(ctx, coords, pixelDiameter);
  }
}

function drawMarkerBrandBorder(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  fillDiameter: number,
  shape: ChartExecutionMarker["shape"],
): void {
  const borderDiameter = fillDiameter + 2 * EXECUTION_MARKER_BORDER_WIDTH_PX;
  const borderWidth = EXECUTION_MARKER_BORDER_WIDTH_PX * coords.pixelRatio;
  ctx.strokeStyle = TERMINAL_COLORS.brand;
  ctx.lineWidth = borderWidth;

  if (shape === "circle") {
    const outerRadius = ((borderDiameter - 1) / 2) * coords.pixelRatio;
    ctx.beginPath();
    ctx.arc(coords.x, coords.y, outerRadius + borderWidth / 2, 0, 2 * Math.PI, false);
    ctx.stroke();
    return;
  }

  const halfSize = ((borderDiameter - 1) * coords.pixelRatio) / 2;
  const left = coords.x - halfSize;
  const top = coords.y - halfSize;
  const size = borderDiameter * coords.pixelRatio;
  ctx.strokeRect(left, top, size, size);
}

function drawMarkerBackgroundLayers(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  fillDiameter: number,
  shape: ChartExecutionMarker["shape"],
  color: string,
): void {
  const borderDiameter = fillDiameter + 2 * EXECUTION_MARKER_BORDER_WIDTH_PX;

  ctx.save();
  ctx.globalAlpha = EXECUTION_MARKER_BACKGROUND_OPACITY;
  ctx.fillStyle = "#ffffff";
  drawShape(ctx, coords, borderDiameter, shape);
  ctx.fillStyle = color;
  drawShape(ctx, coords, fillDiameter, shape);
  ctx.restore();

  drawMarkerBrandBorder(ctx, coords, fillDiameter, shape);
}

type MarkerImageCacheEntry = HTMLImageElement | "loading" | "error";
type MarkerImageLoadListener = () => void;

const markerImageCache = new Map<string, MarkerImageCacheEntry>();
const markerImageListeners = new Map<string, Set<MarkerImageLoadListener>>();

function getLoadedMarkerImage(url: string): HTMLImageElement | null {
  const cached = markerImageCache.get(url);
  if (cached instanceof HTMLImageElement && cached.complete && cached.naturalWidth > 0) {
    return cached;
  }
  return null;
}

function ensureMarkerImage(url: string, onLoad: MarkerImageLoadListener): HTMLImageElement | null {
  const loaded = getLoadedMarkerImage(url);
  if (loaded) return loaded;

  const cached = markerImageCache.get(url);
  if (cached === "loading") {
    markerImageListeners.get(url)?.add(onLoad);
    return null;
  }
  if (cached === "error") return null;

  markerImageCache.set(url, "loading");
  markerImageListeners.set(url, new Set([onLoad]));

  const img = new Image();
  img.onload = () => {
    markerImageCache.set(url, img);
    const listeners = markerImageListeners.get(url);
    markerImageListeners.delete(url);
    listeners?.forEach((listener) => listener());
  };
  img.onerror = () => {
    markerImageCache.set(url, "error");
    markerImageListeners.delete(url);
  };
  img.src = url;
  return null;
}

function drawAvatarMarker(
  ctx: CanvasRenderingContext2D,
  coords: { x: number; y: number; pixelRatio: number },
  fillDiameter: number,
  color: string,
  image: HTMLImageElement,
): void {
  const borderDiameter = fillDiameter + 2 * EXECUTION_MARKER_BORDER_WIDTH_PX;
  const fillRadius = ((fillDiameter - 1) / 2) * coords.pixelRatio;
  const haloRadius = ((borderDiameter - 1) / 2) * coords.pixelRatio;
  const innerRadius = Math.max(coords.pixelRatio, fillRadius - coords.pixelRatio);

  ctx.save();
  ctx.globalAlpha = EXECUTION_MARKER_BACKGROUND_OPACITY;
  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(coords.x, coords.y, haloRadius, 0, 2 * Math.PI, false);
  ctx.fill();

  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(coords.x, coords.y, fillRadius, 0, 2 * Math.PI, false);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.arc(coords.x, coords.y, innerRadius, 0, 2 * Math.PI, false);
  ctx.clip();
  const size = innerRadius * 2;
  ctx.drawImage(image, coords.x - innerRadius, coords.y - innerRadius, size, size);
  ctx.restore();

  drawMarkerBrandBorder(ctx, coords, fillDiameter, "circle");
}

function hitTestCircle(
  centerX: number,
  centerY: number,
  pixelDiameter: number,
  x: number,
  y: number,
): boolean {
  const tolerance = 2 + pixelDiameter / 2;
  const dx = centerX - x;
  const dy = centerY - y;
  return Math.sqrt(dx * dx + dy * dy) <= tolerance;
}

function hitTestSquare(
  centerX: number,
  centerY: number,
  pixelDiameter: number,
  x: number,
  y: number,
): boolean {
  const halfSize = (pixelDiameter - 1) / 2;
  const left = centerX - halfSize;
  const top = centerY - halfSize;
  return x >= left && x <= left + pixelDiameter && y >= top && y <= top + pixelDiameter;
}

function hitTestText(
  textX: number,
  textY: number,
  textWidth: number,
  textHeight: number,
  x: number,
  y: number,
): boolean {
  const halfHeight = textHeight / 2;
  return (
    x >= textX - textWidth / 2 &&
    x <= textX + textWidth / 2 &&
    y >= textY - halfHeight &&
    y <= textY + halfHeight
  );
}

function hitTestItem(item: LayoutItem, x: number, y: number): boolean {
  if (item.imageUrl) {
    return hitTestCircle(item.x, item.y, item.hitTestDiameter, x, y);
  }
  if (item.label && hitTestText(item.textX, item.textY, item.textWidth, item.textHeight, x, y)) {
    return true;
  }
  if (item.shape === "circle") {
    return hitTestCircle(item.x, item.y, item.hitTestDiameter, x, y);
  }
  return hitTestSquare(item.x, item.y, item.hitTestDiameter, x, y);
}

class ExecutionMarkersRenderer implements IPrimitivePaneRenderer {
  private _data: RendererData | null = null;
  private _font = "";

  setData(data: RendererData): void {
    this._data = data;
  }

  setFont(font: string): void {
    this._font = font;
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    if (!this._data) return null;
    for (let i = this._data.visibleFrom; i < this._data.visibleTo; i++) {
      const item = this._data.items[i];
      if (item && hitTestItem(item, x, y)) {
        return {
          zOrder: "top",
          externalId: item.tradeId,
          itemType: "marker",
          hitTestPriority: 2,
        };
      }
    }
    return null;
  }

  draw(target: import("fancy-canvas").CanvasRenderingTarget2D): void {
    target.useBitmapCoordinateSpace((scope) => {
      if (!this._data) return;
      const { context: ctx, horizontalPixelRatio, verticalPixelRatio } = scope;
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.font = this._font;

      const barSpacing = this._data.barSpacing;

      for (let i = this._data.visibleFrom; i < this._data.visibleTo; i++) {
        const item = this._data.items[i];
        if (!item) continue;

        if (item.label) {
          item.textWidth = ctx.measureText(item.label).width;
        }

        const coords = bitmapCoords(item.x, item.y, horizontalPixelRatio, verticalPixelRatio);
        const { fillDiameter } = calculateExecutionMarkerDrawSizes(
          barSpacing,
          item.shape,
        );

        if (item.imageUrl) {
          const image = getLoadedMarkerImage(item.imageUrl);
          if (image) {
            drawAvatarMarker(ctx, coords, fillDiameter, item.color, image);
          } else {
            drawMarkerBackgroundLayers(
              ctx,
              coords,
              fillDiameter,
              "circle",
              item.color,
            );
          }
          continue;
        }

        drawMarkerBackgroundLayers(
          ctx,
          coords,
          fillDiameter,
          item.shape,
          item.color,
        );

        if (item.label) {
          ctx.fillStyle = item.color;
          ctx.save();
          ctx.scale(horizontalPixelRatio, verticalPixelRatio);
          ctx.fillText(item.label, item.textX, item.textY);
          ctx.restore();
        }
      }
    });
  }
}

class ExecutionMarkersPaneView implements IPrimitivePaneView {
  private _chart: IChartApiBase<Time> | null = null;
  private _series: ISeriesApi<"Candlestick"> | null = null;
  private _markers: ChartExecutionMarker[] = [];
  private _markersInputRef: ChartExecutionMarker[] | null = null;
  private _renderer = new ExecutionMarkersRenderer();
  private _data: RendererData = { items: [], visibleFrom: 0, visibleTo: 0, barSpacing: 6 };
  private _invalidated = true;
  private _retryScheduled = false;
  private _retryCount = 0;
  private _retryStartTime = 0;
  private _requestUpdate: (() => void) | null = null;

  constructor(private _isPanningRef?: RefObject<boolean>) {}

  setContext(chart: IChartApiBase<Time>, series: ISeriesApi<"Candlestick">): void {
    this._chart = chart;
    this._series = series;
    this._invalidated = true;
  }

  bindRequestUpdate(requestUpdate: () => void): void {
    this._requestUpdate = requestUpdate;
  }

  private _resetRetryState(): void {
    this._retryCount = 0;
    this._retryStartTime = 0;
  }

  private _scheduleRetryRebuild(): void {
    if (this._isPanningRef?.current) return;
    if (this._retryScheduled || !this._requestUpdate) return;

    if (this._retryCount === 0) {
      this._retryStartTime = performance.now();
    }
    if (
      this._retryCount >= MAX_RETRY_FRAMES ||
      performance.now() - this._retryStartTime > MAX_RETRY_MS
    ) {
      this._resetRetryState();
      return;
    }

    this._retryScheduled = true;
    this._retryCount += 1;
    requestAnimationFrame(() => {
      this._retryScheduled = false;
      this._requestUpdate?.();
    });
  }

  setMarkers(markers: ChartExecutionMarker[]): void {
    if (markers === this._markersInputRef) return;
    this._markersInputRef = markers;
    this._markers = sortMarkersByTime(markers);
    this._invalidated = true;
    this._resetRetryState();
  }

  invalidate(): void {
    this._invalidated = true;
  }

  zOrder(): "top" {
    return "top";
  }

  private _invalidateIfBarSpacingChanged(): void {
    const chart = this._chart;
    if (!chart || this._markers.length === 0) return;
    const liveSpacing = chart.timeScale().options().barSpacing;
    if (liveSpacing !== this._data.barSpacing) {
      this._invalidated = true;
    }
  }

  renderer(): IPrimitivePaneRenderer | null {
    if (!this._series?.options().visible) return null;
    this._invalidateIfBarSpacingChanged();
    if (this._invalidated) {
      if (this._rebuild()) {
        this._invalidated = false;
      }
    }
    return this._renderer;
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    if (!this._series?.options().visible) return null;
    this._invalidateIfBarSpacingChanged();
    if (this._invalidated) {
      if (this._rebuild()) {
        this._invalidated = false;
      }
    }
    return this._renderer.hitTest(x, y);
  }

  private _rebuild(): boolean {
    const chart = this._chart;
    const series = this._series;
    if (!chart || !series) {
      this._data = { items: [], visibleFrom: 0, visibleTo: 0, barSpacing: 6 };
      this._renderer.setData(this._data);
      this._scheduleRetryRebuild();
      return false;
    }

    const visibleRange = chart.timeScale().getVisibleLogicalRange();
    if (visibleRange === null) {
      this._data = { items: [], visibleFrom: 0, visibleTo: 0, barSpacing: 6 };
      this._renderer.setData(this._data);
      this._scheduleRetryRebuild();
      return false;
    }

    if (this._markers.length === 0) {
      this._data = { items: [], visibleFrom: 0, visibleTo: 0, barSpacing: 6 };
      this._renderer.setData(this._data);
      this._resetRetryState();
      return true;
    }

    const barSpacing = chart.timeScale().options().barSpacing;
    const fontSize = chart.options().layout.fontSize;
    const fontFamily = chart.options().layout.fontFamily;
    this._renderer.setFont(`${fontSize}px ${fontFamily}`);

    const timeBounds = visibleTimeBoundsFromLogicalRange(series, visibleRange);
    const markersToLayout =
      timeBounds != null
        ? markersInVisibleTimeSlice(this._markers, timeBounds.lo, timeBounds.hi)
        : this._markers;

    for (const marker of markersToLayout) {
      if (marker.imageUrl) {
        ensureMarkerImage(marker.imageUrl, () => {
          this._invalidated = true;
          this._requestUpdate?.();
        });
      }
    }

    const items = layoutExecutionMarkerItems(
      chart,
      series,
      markersToLayout,
      barSpacing,
      fontSize,
    );

    this._data = { items, visibleFrom: 0, visibleTo: items.length, barSpacing };
    this._renderer.setData(this._data);

    if (
      items.length === 0 &&
      markersToLayout.length > 0 &&
      markersInLoadedSeriesRange(series, markersToLayout)
    ) {
      this._scheduleRetryRebuild();
      return false;
    }

    this._resetRetryState();
    return true;
  }
}

export class ExecutionMarkersPrimitive implements ISeriesPrimitive<Time> {
  private _paneView: ExecutionMarkersPaneView;
  private _requestUpdate: (() => void) | null = null;
  private _chart: IChartApiBase<Time> | null = null;
  private _series: ISeriesApi<"Candlestick"> | null = null;
  private _invalidationHandle: SeriesPrimitiveInvalidationHandle | null = null;

  constructor(private _isPanningRef?: RefObject<boolean>) {
    this._paneView = new ExecutionMarkersPaneView(_isPanningRef);
  }

  attached(param: SeriesAttachedParameter<Time, "Candlestick">): void {
    this._chart = param.chart;
    this._series = param.series;
    this._requestUpdate = param.requestUpdate;
    this._paneView.setContext(param.chart, param.series);
    this._paneView.bindRequestUpdate(() => this._requestUpdate?.());
    this._invalidationHandle = subscribeSeriesPrimitiveInvalidation(
      param.chart,
      param.series,
      () => this._paneView.invalidate(),
      () => this._requestUpdate?.(),
      this._isPanningRef,
    );
    this._paneView.invalidate();
    this._requestUpdate?.();
  }

  flushPanInvalidation(): void {
    this._invalidationHandle?.flush();
  }

  detached(): void {
    this._invalidationHandle?.unsubscribe();
    this._invalidationHandle = null;
    this._chart = null;
    this._series = null;
    this._requestUpdate = null;
  }

  setMarkers(markers: ChartExecutionMarker[]): void {
    this._paneView.setMarkers(markers);
    this._requestUpdate?.();
    requestAnimationFrame(() => this._requestUpdate?.());
  }

  paneViews(): readonly IPrimitivePaneView[] {
    return [this._paneView];
  }

  updateAllViews(): void {
    this._paneView.invalidate();
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    return this._paneView.hitTest(x, y);
  }

  autoscaleInfo(_startTimePoint: Logical, _endTimePoint: Logical) {
    if (!this._chart || this._paneView === null) return null;
    const barSpacing = this._chart.timeScale().options().barSpacing;
    const margin =
      calculateMarkerShapeHeight(barSpacing, EXECUTION_MARKER_FILL_SIZE) * 1.5 +
      executionMarkerShapeMargin(barSpacing) * 2;
    return {
      priceRange: null,
      margins: { above: margin, below: margin },
    };
  }
}
