import React, { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import type { AgentMemoryItem, TradingAgent } from "../../store/types";
import { shortHashId } from "../../utils/hashId";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import "../tables/agentTasks.css";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import "./agentConsole.css";

export type MemorySortOrder = "newest" | "oldest";

export interface AgentMemoryDetailPaneProps {
  agent: TradingAgent | null;
  taskCount: number;
  showAddNote?: boolean;
  onAddNote?: (text: string) => void;
  memorySectionRef?: React.RefObject<HTMLDivElement>;
  className?: string;
  /** When set, show only the last N memory items until the user opts in to View all. */
  previewLimit?: number;
}

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function formatRevenue(value?: number): string {
  if (value == null) return "—";
  if (value >= 1000) return `$${Math.round(value / 1000)}k`;
  return `$${value}`;
}

function agentStatusConfig(agent: TradingAgent) {
  const mapped =
    agent.status === "active"
      ? "executing"
      : agent.status === "paused"
        ? "paused"
        : "watching";
  return (
    AGENT_TASK_STATUS_CONFIG[mapped] ?? {
      label: agent.status,
      tone: "muted" as const,
    }
  );
}

function sortMemory(
  items: AgentMemoryItem[],
  order: MemorySortOrder,
): AgentMemoryItem[] {
  const sorted = [...items].sort(
    (a, b) => new Date(b.at).getTime() - new Date(a.at).getTime(),
  );
  return order === "newest" ? sorted : sorted.reverse();
}

function AgentMemoryDetailPane({
  agent,
  taskCount,
  showAddNote = true,
  onAddNote,
  memorySectionRef,
  className,
  previewLimit,
}: AgentMemoryDetailPaneProps): JSX.Element {
  const [sortOrder, setSortOrder] = useState<MemorySortOrder>("newest");
  const [noteDraft, setNoteDraft] = useState("");
  const [memoryExpanded, setMemoryExpanded] = useState(false);

  const sortedMemory = useMemo(
    () => (agent ? sortMemory(agent.memory, sortOrder) : []),
    [agent, sortOrder],
  );

  const usePreview =
    previewLimit != null && previewLimit > 0 && !memoryExpanded;
  const visibleMemory = usePreview
    ? sortedMemory.slice(0, previewLimit)
    : sortedMemory;
  const hiddenMemoryCount = usePreview
    ? Math.max(0, sortedMemory.length - previewLimit)
    : 0;

  const statusCfg = agent ? agentStatusConfig(agent) : null;

  const handleCopyId = useCallback(async () => {
    if (!agent) return;
    try {
      await navigator.clipboard.writeText(agent.id);
      toast.success("Agent ID copied");
    } catch {
      toast.error("Could not copy agent ID");
    }
  }, [agent]);

  const handleSubmitNote = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      const trimmed = noteDraft.trim();
      if (!trimmed || !onAddNote) return;
      onAddNote(trimmed);
      setNoteDraft("");
      toast.success("Memory note added");
    },
    [noteDraft, onAddNote],
  );

  const rootClass = ["agent-console-memory-pane", className]
    .filter(Boolean)
    .join(" ");

  if (!agent) {
    return (
      <div className={rootClass}>
        <p className="agent-console-empty terminal-text-muted">
          Select an agent to view memory.
        </p>
      </div>
    );
  }

  return (
    <div className={rootClass}>
      <div className="agent-console-memory-header">
        <div className="agent-console-memory-identity">
          <span className="task-id-chip" title={agent.id}>
            {shortHashId(agent.id)}
          </span>
          <span className="agent-console-memory-name">
            {agent.icon ? (
              <span className="agent-parent-chip-icon">{agent.icon}</span>
            ) : null}
            {agent.displayName}
          </span>
          {statusCfg ? (
            <span
              className={`agent-task-status-pill agent-task-status-pill--${statusCfg.tone}`}
            >
              {statusCfg.label}
            </span>
          ) : null}
        </div>
        <div className="agent-console-memory-meta terminal-text-muted">
          <span>Updated {formatRelativeTime(agent.updatedAt)}</span>
          <span aria-hidden>·</span>
          <span>
            {taskCount} intent{taskCount === 1 ? "" : "s"}
          </span>
          {agent.riskScore ? (
            <>
              <span aria-hidden>·</span>
              <span>Risk {agent.riskScore}</span>
            </>
          ) : null}
          {agent.revenue30d != null ? (
            <>
              <span aria-hidden>·</span>
              <span>Rev 30d {formatRevenue(agent.revenue30d)}</span>
            </>
          ) : null}
        </div>
      </div>

      <div className="agent-console-memory-stream-toolbar">
        <span className="agent-task-expanded-label">Memory log</span>
        <button
          type="button"
          className="agent-console-memory-sort-btn"
          onClick={() =>
            setSortOrder((prev) => (prev === "newest" ? "oldest" : "newest"))
          }
          aria-label={`Sort memory ${sortOrder === "newest" ? "oldest first" : "newest first"}`}
        >
          {sortOrder === "newest" ? "Newest" : "Oldest"}{" "}
          <ExpandCollapseIcon expanded={false} size={12} />
        </button>
      </div>

      <div
        ref={memorySectionRef}
        className="agent-console-memory-stream"
        data-agent-memory-section={agent.id}
      >
        {sortedMemory.length === 0 ? (
          <p className="terminal-text-muted agent-console-empty">
            No memory recorded yet.
          </p>
        ) : (
          <>
            <ul className="agent-memory-side-panel-memory-list">
              {visibleMemory.map((item) => (
                <li key={item.id} className="agent-memory-side-panel-memory-item">
                  <div>{item.text}</div>
                  <div className="agent-console-memory-item-time terminal-text-muted">
                    {formatRelativeTime(item.at)} · {formatDateTime(item.at)}
                  </div>
                </li>
              ))}
            </ul>
            {hiddenMemoryCount > 0 ? (
              <button
                type="button"
                className="agent-expanded-memory-link"
                onClick={() => setMemoryExpanded(true)}
              >
                View all ({sortedMemory.length})
              </button>
            ) : null}
          </>
        )}
      </div>

      <div className="agent-console-memory-footer">
        {showAddNote && onAddNote ? (
          <form
            className="agent-console-memory-note-form"
            onSubmit={handleSubmitNote}
          >
            <input
              type="text"
              className="form-input agent-console-memory-note-input"
              placeholder="Add memory note…"
              value={noteDraft}
              onChange={(e) => setNoteDraft(e.target.value)}
              aria-label="Add memory note"
            />
            <button
              type="submit"
              className="btn"
              disabled={!noteDraft.trim()}
            >
              Add
            </button>
          </form>
        ) : null}
        <button type="button" className="btn btn-secondary" onClick={handleCopyId}>
          Copy full ID
        </button>
      </div>
    </div>
  );
}

export default React.memo(AgentMemoryDetailPane);
