import React, { useMemo } from "react";

export interface TrackSliderStop {
  value: number;
  label: string;
}

interface TrackSliderProps {
  id: string;
  label: string;
  min: number;
  max: number;
  step: number;
  value: number;
  onChange: (value: number) => void;
  stops?: TrackSliderStop[];
  valueDisplay?: React.ReactNode;
}

export default function TrackSlider({
  id,
  label,
  min,
  max,
  step,
  value,
  onChange,
  stops,
  valueDisplay,
}: TrackSliderProps): React.JSX.Element {
  const progress = useMemo(() => {
    if (max === min) return 0;
    return ((value - min) / (max - min)) * 100;
  }, [value, min, max]);

  return (
    <div className="nh-track-slider">
      <div className="nh-track-slider-header">
        <label htmlFor={id} className="nh-track-slider-label">
          {label}
        </label>
        {valueDisplay ? <div className="nh-track-slider-value">{valueDisplay}</div> : null}
      </div>
      <input
        id={id}
        type="range"
        className="nh-track-slider-input"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        style={{ "--slider-progress": `${progress}%` } as React.CSSProperties}
      />
      {stops && stops.length > 0 ? (
        <div
          className="nh-track-slider-stops"
          style={{ gridTemplateColumns: `repeat(${stops.length}, minmax(0, 1fr))` }}
        >
          {stops.map((stop) => (
            <span
              key={stop.value}
              className={`nh-track-slider-stop${value === stop.value ? " active" : ""}`}
            >
              {stop.label}
            </span>
          ))}
        </div>
      ) : null}
    </div>
  );
}
