import React from "react";

import { formatCurrency } from "../../sdk/utils/display";
import { autonomyBadgeCopy, autonomyPolicyForPreset } from "../tradeagent/autonomyPolicy";
import type { CopyAutonomyPreset } from "../../../offline/mock_data/fleetCopyRelations";
import { NestedConfirmDialog } from "../ui/NestedConfirmDialog";

export interface CopyAgentHighAgencyConfirmProps {
  isOpen: boolean;
  capitalAtRisk: number;
  onCancel: () => void;
  onConfirm: () => void;
}

export function CopyAgentHighAgencyConfirm({
  isOpen,
  capitalAtRisk,
  onCancel,
  onConfirm,
}: CopyAgentHighAgencyConfirmProps): JSX.Element | null {
  const badge = autonomyBadgeCopy(autonomyPolicyForPreset("highAgency"));

  return (
    <NestedConfirmDialog
      isOpen={isOpen}
      title="Enable High-Agency for this mirror?"
      titleId="copy-high-agency-confirm-title"
      confirmLabel="Yes, enable High-Agency"
      onCancel={onCancel}
      onConfirm={onConfirm}
    >
      <p className="nested-confirm-body">
        Copied trades can execute silently when confidence and risk stay in
        band, using up to {formatCurrency(capitalAtRisk)} in this bucket.
      </p>
      <p className="nested-confirm-body">
        {badge.headline}. This raises autonomy — confirm only if you want
        hands-off copy execution.
      </p>
    </NestedConfirmDialog>
  );
}

export interface CopyAgentExistingBucketConfirmProps {
  isOpen: boolean;
  bucketLabel: string;
  bucketEquity: number;
  autonomyPreset: CopyAutonomyPreset;
  onCancel: () => void;
  onConfirm: () => void;
}

export function CopyAgentExistingBucketConfirm({
  isOpen,
  bucketLabel,
  bucketEquity,
  autonomyPreset,
  onCancel,
  onConfirm,
}: CopyAgentExistingBucketConfirmProps): JSX.Element | null {
  const presetLabel =
    autonomyPreset === "highAgency"
      ? "High-Agency"
      : autonomyPreset === "manual"
        ? "Manual"
        : "Guarded";

  return (
    <NestedConfirmDialog
      isOpen={isOpen}
      title="Share this cross bucket?"
      titleId="copy-existing-bucket-confirm-title"
      confirmLabel="Yes, use this bucket"
      onCancel={onCancel}
      onConfirm={onConfirm}
    >
      <p className="nested-confirm-body">
        Bucket <strong>{bucketLabel}</strong> already holds{" "}
        {formatCurrency(bucketEquity)}. Copied trades will share the same margin
        pool with anything else in this bucket.
      </p>
      <p className="nested-confirm-body">
        Setting <strong>{presetLabel}</strong> also overwrites this bucket&apos;s
        autonomy policy for every agent using it — not just this mirror.
      </p>
    </NestedConfirmDialog>
  );
}
