import React from "react";
import "./layout.css";

export interface TableHeaderLabelProps {
  full: string;
  short?: string;
  title?: string;
}

export interface TableHeaderCellProps<T extends string> {
  field: T;
  currentSortField: T | null;
  sortDirection: "asc" | "desc";
  onSort: (field: T) => void;
  children: React.ReactNode;
  center?: boolean;
  left?: boolean;
  right?: boolean;
}

export interface TableHeaderCellStaticProps {
  children: React.ReactNode;
  center?: boolean;
  left?: boolean;
  right?: boolean;
}

function getTableHeaderCellAlignClass({
  center = false,
  left = false,
  right = false,
}: {
  center?: boolean;
  left?: boolean;
  right?: boolean;
}): string {
  if (center) return "center";
  if (right) return "right";
  return "left";
}

/**
 * Responsive table header label: shows `full` by default, `short` when the table container is narrow.
 */
export function TableHeaderLabel({
  full,
  short,
  title,
}: TableHeaderLabelProps): JSX.Element {
  const tooltip = title ?? full;
  const hasShort = short != null && short !== full;

  if (!hasShort) {
    return (
      <span className="table-header-label" title={tooltip}>
        <span className="table-header-label--full">{full}</span>
      </span>
    );
  }

  return (
    <span className="table-header-label" title={tooltip}>
      <span className="table-header-label--full">{full}</span>
      <span className="table-header-label--short" aria-hidden="true">
        {short}
      </span>
    </span>
  );
}

/**
 * Returns a sort icon based on the current sort field and direction
 */
export function getSortIcon<T extends string>(
  field: T,
  currentSortField: T | null,
  sortDirection: "asc" | "desc",
): React.ReactNode {
  if (currentSortField !== field) {
    return (
      <span className="table-header-sort-icon inactive" aria-hidden="true">
        ▼
      </span>
    );
  }
  return (
    <span className="table-header-sort-icon" aria-hidden="true">
      {sortDirection === "asc" ? "▲" : "▼"}
    </span>
  );
}

/**
 * Table header cell with sorting functionality
 */
export function TableHeaderCell<T extends string>({
  field,
  currentSortField,
  sortDirection,
  onSort,
  children,
  center = false,
  left = false,
  right = false,
}: TableHeaderCellProps<T>): JSX.Element {
  return (
    <div
      className={`table-header-cell terminal-label ${getTableHeaderCellAlignClass({ center, left, right })}`}
      onClick={() => onSort(field)}
    >
      <span className="table-header-cell-text">{children}</span>
      {getSortIcon(field, currentSortField, sortDirection)}
    </div>
  );
}

/**
 * Table header cell without sorting (for static headers)
 */
export function TableHeaderCellStatic({
  children,
  center = false,
  left = false,
  right = false,
}: TableHeaderCellStaticProps): JSX.Element {
  return (
    <div
      className={`table-header-cell table-header-cell--static terminal-label ${getTableHeaderCellAlignClass({ center, left, right })}`}
    >
      <span className="table-header-cell-text">{children}</span>
    </div>
  );
}
