import React, { useState } from "react";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";

export interface SafetyAuditLogRowActionsProps {
  taskId: string;
  sizePct: number;
  onSizePctChange: (value: number) => void;
  onApprove: () => void;
  onReject: () => void;
  /** Short Appr/Rej labels for narrow table columns (md). */
  abbreviated?: boolean;
  /** Helper copy when the size slider is expanded (review sheet). */
  showSizeExplanation?: boolean;
}

function SafetyAuditLogRowActions({
  taskId,
  sizePct,
  onSizePctChange,
  onApprove,
  onReject,
  abbreviated = false,
  showSizeExplanation = false,
}: SafetyAuditLogRowActionsProps): JSX.Element {
  const [tweakOpen, setTweakOpen] = useState(false);

  const approveLabel = abbreviated
    ? "Appr"
    : sizePct === 100
      ? "Approve"
      : `Approve ${sizePct}%`;

  return (
    <div className="safety-audit-log-actions">
      <button
        type="button"
        className="guardrail-intent-tweak-toggle"
        aria-expanded={tweakOpen}
        onClick={() => setTweakOpen((v) => !v)}
      >
        {tweakOpen ? "Hide tweak" : "Approve with tweak"}
      </button>
      {tweakOpen ? (
        <div className="guardrail-intent-tweak-row">
          <label className="guardrail-intent-tweak-label" htmlFor={`audit-tweak-${taskId}`}>
            Size {sizePct}%
          </label>
          {showSizeExplanation ? (
            <p className="guardrail-intent-tweak-help">
              Execute at a percentage of the agent&apos;s planned position size (10–100%).
              Lower values reduce exposure while approving the same intent.
            </p>
          ) : null}
          <FilledRangeSlider
            id={`audit-tweak-${taskId}`}
            variant="brand"
            size="sm"
            min={10}
            max={100}
            step={5}
            value={sizePct}
            onChange={onSizePctChange}
          />
        </div>
      ) : null}
      <div className="trade-agent-deck-card-actions">
        <button
          type="button"
          className="trade-agent-deck-btn trade-agent-deck-btn--primary"
          onClick={onApprove}
        >
          {approveLabel}
        </button>
        <button
          type="button"
          className="trade-agent-deck-btn trade-agent-deck-btn--danger"
          onClick={onReject}
        >
          {abbreviated ? "Rej" : "Reject"}
        </button>
      </div>
    </div>
  );
}

export default React.memo(SafetyAuditLogRowActions);
