import type { MockBucket } from "./bucketdata";
import {
  jellyBucketSnapshotToRawBucket,
  type JellyBucketSnapshot,
} from "./jellyevent";

/** Map offline bucket source to input accepted by rawInputToBucket. */
export function offlineBucketSourceToRawInput(
  bucket: MockBucket | JellyBucketSnapshot,
  jellyOverride: boolean,
): unknown {
  if (jellyOverride) {
    return jellyBucketSnapshotToRawBucket(bucket as JellyBucketSnapshot);
  }
  return bucket;
}
