import { parseCompareIds } from "./agentCompareIds";

export const AGENT_COMPARE_SAVED_LISTS_KEY = "agent_compare_saved_lists";

export interface SavedCompareList {
  id: string;
  agentIds: string[];
  savedAt: string;
}

function migrateSavedCompareList(raw: unknown): SavedCompareList | null {
  if (!raw || typeof raw !== "object") return null;
  const record = raw as Record<string, unknown>;
  if (typeof record.id !== "string" || !Array.isArray(record.agentIds)) return null;

  const agentIds = normalizeCompareSet(
    record.agentIds.filter((entry): entry is string => typeof entry === "string"),
  );
  if (agentIds.length === 0) return null;

  const savedAt =
    typeof record.savedAt === "string" ? record.savedAt : new Date().toISOString();

  return {
    id: buildSavedCompareListId(agentIds),
    agentIds,
    savedAt,
  };
}

export function normalizeCompareSet(ids: string[]): string[] {
  return parseCompareIds(ids.join(","));
}

export function buildSavedCompareListId(agentIds: string[]): string {
  return [...agentIds].sort().join(",");
}

export function compareSetsEqual(left: string[], right: string[]): boolean {
  const normalizedLeft = normalizeCompareSet(left);
  const normalizedRight = normalizeCompareSet(right);
  if (normalizedLeft.length !== normalizedRight.length) return false;
  const rightSet = new Set(normalizedRight);
  return normalizedLeft.every((id) => rightSet.has(id));
}

export function loadSavedCompareLists(): SavedCompareList[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(AGENT_COMPARE_SAVED_LISTS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as unknown[];
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((entry) => migrateSavedCompareList(entry))
      .filter((entry): entry is SavedCompareList => entry !== null);
  } catch {
    return [];
  }
}

export function persistSavedCompareLists(lists: SavedCompareList[]): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(AGENT_COMPARE_SAVED_LISTS_KEY, JSON.stringify(lists));
}

export function findSavedListIndex(
  lists: SavedCompareList[],
  agentIds: string[],
): number {
  return lists.findIndex((entry) => compareSetsEqual(entry.agentIds, agentIds));
}

export function isCompareSetSaved(
  lists: SavedCompareList[],
  agentIds: string[],
): boolean {
  return findSavedListIndex(lists, agentIds) >= 0;
}

export function sortSavedCompareListsNewestFirst(
  lists: SavedCompareList[],
): SavedCompareList[] {
  return [...lists].sort(
    (left, right) =>
      new Date(right.savedAt).getTime() - new Date(left.savedAt).getTime(),
  );
}

export function addSavedCompareList(
  lists: SavedCompareList[],
  agentIds: string[],
  savedAt: string = new Date().toISOString(),
): SavedCompareList[] {
  const normalized = normalizeCompareSet(agentIds);
  if (normalized.length === 0) return lists;
  if (isCompareSetSaved(lists, normalized)) return lists;

  const entry: SavedCompareList = {
    id: buildSavedCompareListId(normalized),
    agentIds: normalized,
    savedAt,
  };

  return [...lists, entry];
}

export function removeSavedCompareList(
  lists: SavedCompareList[],
  id: string,
): SavedCompareList[] {
  return lists.filter((entry) => entry.id !== id);
}
