export type AgentSettingsTabId = "skills" | "envVars" | "mcpServers";

export type EnvVarScope = "agentTools" | "x402Endpoints";

export type McpTransport = "streamableHttp" | "sse";

export type SkillFileKind = "skill" | "reference" | "resource";

export interface SkillFile {
  path: string;
  kind: SkillFileKind;
  content: string;
}

export interface AgentSkill {
  id: string;
  catalogId?: string;
  name: string;
  description: string;
  files: SkillFile[];
  installedAt: string;
  source: "catalog" | "custom";
}

export interface AgentEnvVar {
  id: string;
  key: string;
  value: string;
  scope: EnvVarScope;
}

export interface McpServerHeader {
  name: string;
  value: string;
}

export interface McpServer {
  id: string;
  name: string;
  url: string;
  transport: McpTransport;
  headers: McpServerHeader[];
  createdAt: string;
}

export interface AgentSettingsState {
  skills: AgentSkill[];
  envVars: AgentEnvVar[];
  mcpServers: McpServer[];
}

export const DEFAULT_AGENT_SETTINGS: AgentSettingsState = {
  skills: [],
  envVars: [],
  mcpServers: [],
};
