import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import type { Bucket } from "../../sdk";
import type { AgentTask } from "../../store/types";
import {
  autonomyPolicyForPreset,
  cloneAutonomyPolicy,
  isRaisingAutonomy,
  type AutonomyPolicy,
  type AutonomyPreset,
  validateAutonomyPolicy,
} from "../tradeagent/autonomyPolicy";
import {
  countNeedsYouResolved,
  getTaskReportingMetaResolved,
} from "../tradeagent/reportTier";
import {
  useBucketPolicyStore,
  createTaskPolicyResolver,
} from "../../store/bucketPolicyStore";

export type SaveRulesResult = "saved" | "needs_confirm" | "invalid";

export interface UseBucketRulesEditorOptions {
  isActive: boolean;
  bucketId: string | null;
  bucket: Bucket | null;
  onSaved?: (bucketId: string) => void;
  /** @deprecated Save no longer closes the modal; kept for BucketRulesModal compat. */
  onClose?: () => void;
}

export function useBucketRulesEditor({
  isActive,
  bucketId,
  bucket,
  onSaved,
  onClose,
}: UseBucketRulesEditorOptions) {
  const { tasks } = useAgentTasks();
  const storedPolicy = useBucketPolicyStore((s) =>
    bucketId ? s.policies[bucketId] : undefined,
  );
  const setPolicy = useBucketPolicyStore((s) => s.setPolicy);

  const [draft, setDraft] = useState<AutonomyPolicy | null>(null);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saveSuccessMessage, setSaveSuccessMessage] = useState<string | null>(
    null,
  );

  useEffect(() => {
    if (!isActive || !bucketId) {
      if (!isActive) {
        setAdvancedOpen(false);
        setSaveSuccessMessage(null);
      }
      return;
    }
    const current =
      storedPolicy ?? useBucketPolicyStore.getState().getPolicy(bucketId);
    setDraft(cloneAutonomyPolicy(current));
    setError(null);
    setSaveSuccessMessage(null);
  }, [isActive, bucketId, storedPolicy]);

  const bucketTasks = useMemo(() => {
    if (!bucketId) return [];
    return tasks.filter(
      (task) =>
        task.bucketId?.toString() === bucketId.toString() &&
        task.status !== "completed" &&
        task.status !== "rejected",
    );
  }, [tasks, bucketId]);

  const previewResolver = useMemo(() => {
    if (!draft) return createTaskPolicyResolver("highAgency");
    return (task: AgentTask) => {
      if (bucketId && task.bucketId?.toString() === bucketId.toString()) {
        return draft;
      }
      return createTaskPolicyResolver("highAgency")(task);
    };
  }, [draft, bucketId]);

  const impactRows = useMemo(() => {
    if (!draft) return [];
    return bucketTasks.slice(0, 6).map((task) => {
      const meta = getTaskReportingMetaResolved(task, previewResolver);
      return { task, meta };
    });
  }, [bucketTasks, draft, previewResolver]);

  const needsYouPreview = useMemo(
    () => countNeedsYouResolved(bucketTasks, previewResolver),
    [bucketTasks, previewResolver],
  );

  const autoExecutePreview = useMemo(() => {
    if (!draft) return 0;
    return bucketTasks.filter((task) => {
      const tier = getTaskReportingMetaResolved(task, previewResolver).reportTier;
      return tier === "T0" || tier === "T1";
    }).length;
  }, [bucketTasks, draft, previewResolver]);

  const storedForCompare = useMemo(() => {
    if (!bucketId) return null;
    return (
      storedPolicy ?? useBucketPolicyStore.getState().getPolicy(bucketId)
    );
  }, [bucketId, storedPolicy]);

  const persistDraft = useCallback(() => {
    if (!bucketId || !draft) return;
    setPolicy(bucketId, draft);
    onSaved?.(bucketId);
    setSaveSuccessMessage("Rules saved for this bucket.");
    onClose?.();
  }, [bucketId, draft, setPolicy, onSaved, onClose]);

  const handlePresetSelect = useCallback((preset: AutonomyPreset) => {
    setDraft(autonomyPolicyForPreset(preset));
    setError(null);
    setSaveSuccessMessage(null);
    if (preset === "manual") {
      setAdvancedOpen(false);
    }
  }, []);

  const handleSave = useCallback((): SaveRulesResult => {
    if (!bucketId || !draft || !storedForCompare) return "invalid";
    const validationError = validateAutonomyPolicy(draft);
    if (validationError) {
      setError(validationError);
      return "invalid";
    }
    if (isRaisingAutonomy(storedForCompare, draft)) {
      return "needs_confirm";
    }
    persistDraft();
    toast.success("Autonomy rules updated");
    return "saved";
  }, [bucketId, draft, storedForCompare, persistDraft]);

  const commitSaveAfterConfirm = useCallback(() => {
    if (!bucketId || !draft) return;
    const validationError = validateAutonomyPolicy(draft);
    if (validationError) {
      setError(validationError);
      return;
    }
    persistDraft();
    toast.success("Autonomy rules updated");
  }, [bucketId, draft, persistDraft]);

  const handleReset = useCallback(() => {
    if (!draft) return;
    setDraft(autonomyPolicyForPreset(draft.preset));
    setError(null);
    setSaveSuccessMessage(null);
  }, [draft]);

  const resetEditor = useCallback(() => {
    setDraft(null);
    setAdvancedOpen(false);
    setError(null);
    setSaveSuccessMessage(null);
  }, []);

  return {
    draft,
    setDraft,
    advancedOpen,
    setAdvancedOpen,
    error,
    saveSuccessMessage,
    bucket,
    bucketTasks,
    impactRows,
    needsYouPreview,
    autoExecutePreview,
    handlePresetSelect,
    handleSave,
    commitSaveAfterConfirm,
    handleReset,
    resetEditor,
  };
}
