import { useCallback, useEffect, useRef, useState } from "react";
import type { LayoutStyle } from "../preference/settingsRegistry";
import type { ShortcutActionId } from "../../utils/keyboardShortcuts";

export type LayoutSwitchHint = {
  layout: LayoutStyle;
  actionId: ShortcutActionId;
};

export type LayoutSwitchHintPhase = "visible" | "fading";

const HOLD_MS = 1000;
const FADE_MS = 300;

export function useLayoutSwitchHint(): {
  hint: LayoutSwitchHint | null;
  phase: LayoutSwitchHintPhase | null;
  showHint: (hint: LayoutSwitchHint) => void;
} {
  const [hint, setHint] = useState<LayoutSwitchHint | null>(null);
  const [phase, setPhase] = useState<LayoutSwitchHintPhase | null>(null);
  const holdTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearTimers = useCallback(() => {
    if (holdTimerRef.current) {
      clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
    if (fadeTimerRef.current) {
      clearTimeout(fadeTimerRef.current);
      fadeTimerRef.current = null;
    }
  }, []);

  const showHint = useCallback(
    (next: LayoutSwitchHint) => {
      clearTimers();
      setHint(next);
      setPhase("visible");

      holdTimerRef.current = setTimeout(() => {
        holdTimerRef.current = null;
        setPhase("fading");

        fadeTimerRef.current = setTimeout(() => {
          fadeTimerRef.current = null;
          setHint(null);
          setPhase(null);
        }, FADE_MS);
      }, HOLD_MS);
    },
    [clearTimers],
  );

  useEffect(() => clearTimers, [clearTimers]);

  return { hint, phase, showHint };
}

export { FADE_MS };
