import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the index list page layout */
export const INDEX_LIST_SLOT_INDICES = {
  hero: 0,
  table: 1,
  metrics: 5,
} as const;

export const INDEX_LIST_TABLE_SLOT_INDEX = INDEX_LIST_SLOT_INDICES.table;

/** Slots collapsed on all breakpoints */
export const INDEX_LIST_COLLAPSED_SLOTS = [2, 3, 4, 6, 7, 8] as const;

export const INDEX_LIST_ROW_HEIGHT = 30;
export const INDEX_LIST_MENUBAR_HEIGHT = 54;
export const INDEX_LIST_LAYOUT_MARGIN = 10;
export const INDEX_LIST_VIEWPORT_FUDGE_PX = 4;

export const INDEX_LIST_TITLE_ROWS = 2;
export const INDEX_LIST_METRICS_ROWS = 2;
export const INDEX_LIST_BASE_TABLE_ROWS = 12;
export const INDEX_LIST_SCROLL_TABLE_ROWS = 20;

export const INDEX_LIST_TITLE_COLS_LG = 4;
export const INDEX_LIST_METRICS_COLS_LG = 8;

export const INDEX_LIST_TABLE_START_ROW = INDEX_LIST_TITLE_ROWS;
export const INDEX_LIST_STACKED_METRICS_START_ROW = INDEX_LIST_TITLE_ROWS;
export const INDEX_LIST_STACKED_TABLE_START_ROW =
  INDEX_LIST_STACKED_METRICS_START_ROW + INDEX_LIST_METRICS_ROWS;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_MID: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function splitTitleMetricsCols(cols: number): {
  titleW: number;
  metricsW: number;
  metricsX: number;
} {
  const titleW = Math.round(cols / 3);
  const metricsW = cols - titleW;
  return { titleW, metricsW, metricsX: titleW };
}

function titleMetricsSlot5(
  cols: number,
  stacked: boolean,
): [LayoutDefinition, LayoutDefinition] {
  if (stacked) {
    return [
      [0, 0, cols, INDEX_LIST_TITLE_ROWS],
      [0, INDEX_LIST_STACKED_METRICS_START_ROW, cols, INDEX_LIST_METRICS_ROWS],
    ];
  }

  if (cols === 12) {
    return [
      [0, 0, INDEX_LIST_TITLE_COLS_LG, INDEX_LIST_TITLE_ROWS],
      [
        INDEX_LIST_TITLE_COLS_LG,
        0,
        INDEX_LIST_METRICS_COLS_LG,
        INDEX_LIST_METRICS_ROWS,
      ],
    ];
  }

  const { titleW, metricsW, metricsX } = splitTitleMetricsCols(cols);
  return [
    [0, 0, titleW, INDEX_LIST_TITLE_ROWS],
    [metricsX, 0, metricsW, INDEX_LIST_METRICS_ROWS],
  ];
}

function indexListLayout(cols: number, stackedMetrics: boolean): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, stackedMetrics);
  const tableStart = stackedMetrics
    ? INDEX_LIST_STACKED_TABLE_START_ROW
    : INDEX_LIST_TABLE_START_ROW;

  return [
    titleSlot,
    [0, tableStart, cols, INDEX_LIST_BASE_TABLE_ROWS],
    COLLAPSED,
    COLLAPSED,
    COLLAPSED_MID,
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

export const indexListLayoutLg: LayoutConfigLest = indexListLayout(12, false);
export const indexListLayoutMd: LayoutConfigLest = indexListLayout(10, false);
export const indexListLayoutSm: LayoutConfigLest = indexListLayout(6, false);
export const indexListLayoutXs: LayoutConfigLest = indexListLayout(4, true);
export const indexListLayoutXxs: LayoutConfigLest = indexListLayout(2, true);

export function buildIndexListResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, INDEX_LIST_COLLAPSED_SLOTS);

  return {
    lg: collapseAll(indexListLayoutLg),
    md: collapseAll(indexListLayoutMd),
    sm: collapseAll(indexListLayoutSm),
    xs: collapseAll(indexListLayoutXs),
    xxs: collapseAll(indexListLayoutXxs),
  };
}

export function generateIndexListResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

function patchTableSlotHeight(
  layout: LayoutConfigLest,
  tableRows: number,
): LayoutConfigLest {
  const tableSlot = layout[INDEX_LIST_TABLE_SLOT_INDEX];
  if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) return layout;

  const nextTable: LayoutDefinition = [
    tableSlot[0],
    tableSlot[1],
    tableSlot[2],
    tableRows,
  ];

  return layout.map((item, index) =>
    index === INDEX_LIST_TABLE_SLOT_INDEX ? nextTable : item,
  );
}

export function patchIndexListScrollTableHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTableSlotHeight(layout, INDEX_LIST_SCROLL_TABLE_ROWS);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/** Fixed table rows on all breakpoints; page scrolls vertically. */
export function applyIndexListLayoutSizing(
  config: ResponsiveLayoutConfig,
  _viewportHeight?: number,
): ResponsiveLayoutConfig {
  return patchIndexListScrollTableHeights(config);
}

export function assertIndexListLayoutValid(
  config: ResponsiveLayoutConfig,
): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `index-list ${bp}`);
  }
}
