function sparklineToPriceSeries(row: PropertyIndexRow): number[] {
  const anchor = row.sparkline[row.sparkline.length - 1] ?? 1;
  return row.sparkline.map((value) => row.price * (value / anchor));
}

const DEFAULT_INDEX_PERFORMANCE_METRICS: IndexPerformanceMetrics = {
  change24h: 0.28,
  roi7d: -4.35,
  roi1m: -12.18,
  roi3m: -8.17,
  roi1y: -16.01,
  roiYtd: -35.13,
  roi1yVsBtc: 48.81,
};

function buildPerformanceMetrics(
  change24h: number,
  overrides: Partial<Omit<IndexPerformanceMetrics, "change24h">> = {},
): IndexPerformanceMetrics {
  return {
    ...DEFAULT_INDEX_PERFORMANCE_METRICS,
    change24h,
    ...overrides,
  };
}

function buildBasisLabel(price: number, nav: number): string {
  const basis = ((price - nav) / nav) * 100;
  const sign = basis >= 0 ? "+" : "";
  const label = basis >= 0 ? "premium" : "discount";
  return `${sign}${basis.toFixed(2)}% ${label}`;
}

function buildIndexProfileVariant(
  base: PropertyIndexProfile,
  row: PropertyIndexRow,
  copy: Pick<PropertyIndexProfile, "subtitle" | "ceoLine" | "narrativeBeat" | "priority">,
): PropertyIndexProfile {
  const nav = Number((row.price * 0.993).toFixed(2));
  const premiumDiscountBasis = Math.round(((row.price - nav) / nav) * 10000);

  return {
    ...base,
    id: row.id,
    name: row.name,
    ticker: row.id,
    subtitle: copy.subtitle,
    ceoLine: copy.ceoLine,
    narrativeBeat: copy.narrativeBeat,
    priority: copy.priority,
    change24h: row.change24h,
    performanceMetrics: buildPerformanceMetrics(row.change24h),
    pricing: {
      ...base.pricing,
      price: row.price,
      nav,
      premiumDiscountBasis,
      basisLabel: buildBasisLabel(row.price, nav),
    },
    chartSeries: sparklineToPriceSeries(row),
    portfolioMock: {
      mint: {
        ...base.portfolioMock.mint,
        outputMultiplier: 1 / nav,
      },
      redeem: {
        ...base.portfolioMock.redeem,
        outputMultiplier: nav,
      },
    },
  };
}

