export {
  waitAnimationFrames,
  waitForTourTarget,
} from "../welcome-tour/welcomeTourDom";

import { waitForTourTarget } from "../welcome-tour/welcomeTourDom";

export async function prepareCopyTourTarget(
  selector: string,
  maxMs = 800,
): Promise<boolean> {
  await waitForTourTarget(selector, maxMs);
  const el = document.querySelector(selector);
  return Boolean(el && el.getBoundingClientRect().width > 0);
}
