import React, { type JSX } from "react";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

export interface KlineChartNavToolbarProps {
  onCoarserInterval: () => void;
  onFinerInterval: () => void;
  coarserDisabled?: boolean;
  finerDisabled?: boolean;
  onScrollOlder: () => void;
  onScrollNewer: () => void;
  showPendingViewButton?: boolean;
  pendingViewDisabled?: boolean;
  onViewPendings: () => void;
  onReset: () => void;
}

function KlineChartNavToolbar({
  onCoarserInterval,
  onFinerInterval,
  coarserDisabled = false,
  finerDisabled = false,
  onScrollOlder,
  onScrollNewer,
  showPendingViewButton = false,
  pendingViewDisabled = false,
  onViewPendings,
  onReset,
}: KlineChartNavToolbarProps): JSX.Element {
  return (
    <BubbleTip id={BUBBLE_TIP_IDS.chartToolbar} side="bottom" align="end">
      <div className="kline-chart-nav-toolbar" role="toolbar" aria-label="Chart navigation">
        <button
          type="button"
          className="kline-chart-nav-btn"
          onClick={onCoarserInterval}
          disabled={coarserDisabled}
          aria-disabled={coarserDisabled}
          aria-label="Coarser interval"
        >
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
          <path d="M2 7h10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      </button>
      <button
        type="button"
        className="kline-chart-nav-btn"
        onClick={onFinerInterval}
        disabled={finerDisabled}
        aria-disabled={finerDisabled}
        aria-label="Finer interval"
      >
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
          <path d="M7 2v10M2 7h10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      </button>
      <button
        type="button"
        className="kline-chart-nav-btn"
        onClick={onScrollOlder}
        aria-label="Scroll to older candles"
      >
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
          <path
            d="M8.5 3.5L4.5 7l4 3.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
      <button
        type="button"
        className="kline-chart-nav-btn"
        onClick={onScrollNewer}
        aria-label="Scroll to newer candles"
      >
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
          <path
            d="M5.5 3.5L9.5 7l-4 3.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>

      {showPendingViewButton ? (
        <button
          type="button"
          className="kline-chart-nav-btn"
          onClick={onViewPendings}
          disabled={pendingViewDisabled}
          aria-disabled={pendingViewDisabled}
          aria-label="Fit chart to pending order lines"
        >
          <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
            <circle
              cx="6"
              cy="6"
              r="3.25"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
            />
            <path
              d="M8.5 8.5L12 12"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        </button>
      ) : null}

      <button
        type="button"
        className="kline-chart-nav-btn"
        onClick={onReset}
        aria-label="Return to latest candle"
      >
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden>
          <path
            d="M3.5 7a3.5 3.5 0 1 0 1.5-2.87"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M3.5 4v3h3"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
      </div>
    </BubbleTip>
  );
}

export default KlineChartNavToolbar;
