import type { Bucket, Position, TradeHistoryRow } from "../sdk/types/data";
import { toNumberFromSatoshi } from "../sdk/utils/math";
import { formatPortfolioCurrency } from "../components/portfolio/portfolioFormat";
import type {
  PerformanceMarket,
  PerformanceTimeRange,
  PortfolioPerformanceMetricRow,
} from "../components/portfolio/portfolioPerformanceMock";
import type { PortfolioTimeRange } from "./portfolioChartData";

const DAY_MS = 24 * 60 * 60 * 1000;

const RANGE_MS: Record<Exclude<PortfolioTimeRange, "all">, number> = {
  "30d": 30 * DAY_MS,
  "7d": 7 * DAY_MS,
  "24h": DAY_MS,
};

function tradeMatchesFleetFilter(
  trade: TradeHistoryRow,
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
): boolean {
  if (filterAgentIds.length === 0) return true;

  const agentId = trade.agentTaskId
    ? taskAgentMap.get(trade.agentTaskId)
    : undefined;

  if (agentId) return filterAgentIds.includes(agentId);
  return false;
}

export function filterPerformanceTrades(
  trades: TradeHistoryRow[],
  market: PerformanceMarket,
  timeRange: PerformanceTimeRange,
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
): TradeHistoryRow[] {
  let scoped = trades.filter((trade) =>
    tradeMatchesFleetFilter(trade, filterAgentIds, taskAgentMap),
  );

  if (market === "spot") {
    return [];
  }

  if (timeRange !== "all") {
    const cutoff = Date.now() - RANGE_MS[timeRange];
    scoped = scoped.filter((trade) => trade.time >= cutoff);
  }

  return scoped;
}

export function computePerformanceVolume(trades: TradeHistoryRow[]): number {
  let total = 0;
  for (const trade of trades) {
    total += trade.size * trade.price;
  }
  return total;
}

export function computePerformanceRealizedPnl(trades: TradeHistoryRow[]): number {
  let total = 0;
  for (const trade of trades) {
    if (trade.closedPnl != null) total += trade.closedPnl;
  }
  return total;
}

export function computeMaxDrawdownPct(
  trades: TradeHistoryRow[],
  endingEquity: number,
): number {
  const sorted = [...trades]
    .filter((trade) => trade.closedPnl != null)
    .sort((a, b) => a.time - b.time);

  if (sorted.length === 0) return 0;

  const totalPnl = sorted.reduce((sum, trade) => sum + (trade.closedPnl ?? 0), 0);
  let equity = Math.max(endingEquity - totalPnl, 1);
  let peak = equity;
  let maxDrawdown = 0;

  for (const trade of sorted) {
    equity += trade.closedPnl ?? 0;
    if (equity > peak) peak = equity;
    if (peak > 0) {
      const drawdown = ((peak - equity) / peak) * 100;
      if (drawdown > maxDrawdown) maxDrawdown = drawdown;
    }
  }

  return maxDrawdown;
}

function sumUnrealizedPnl(positions: Position[]): number {
  return positions.reduce((sum, position) => sum + (position.unrealizedPnL ?? 0), 0);
}

function sumBucketEquity(collections: Bucket[]): number {
  return collections.reduce((sum, bucket) => sum + bucket.totalEquity, 0);
}

function isCrossMargin(value: string | undefined): boolean {
  return !value?.toLowerCase().includes("isolated");
}

function positionNotional(position: Position): number {
  return Math.abs(position.size) * (position.markPrice || position.entryPrice || 0);
}

function positionMaintenanceMargin(position: Position): number {
  const rawMmr = position.raw?.mmr;
  if (rawMmr != null && rawMmr !== "") {
    return toNumberFromSatoshi(String(rawMmr));
  }
  return position.margin > 0 ? position.margin / 20 : 0;
}

export interface PerformanceMetricsInput {
  trades: TradeHistoryRow[];
  taskAgentMap: Map<string, string>;
  filterAgentIds: string[];
  accountEquity: number;
  spotWalletBalance: number;
  collections: Bucket[];
  positions: Position[];
  market: PerformanceMarket;
  timeRange: PerformanceTimeRange;
}

export function buildPerformanceMetricRows(
  input: PerformanceMetricsInput,
): PortfolioPerformanceMetricRow[] {
  const {
    trades,
    taskAgentMap,
    filterAgentIds,
    accountEquity,
    spotWalletBalance,
    collections,
    positions,
    market,
    timeRange,
  } = input;

  const filteredTrades = filterPerformanceTrades(
    trades,
    market,
    timeRange,
    filterAgentIds,
    taskAgentMap,
  );

  const tradingEquity = sumBucketEquity(collections);
  const unrealizedPnl = market === "perps" ? sumUnrealizedPnl(positions) : 0;
  const realizedPnl = computePerformanceRealizedPnl(filteredTrades);
  const pnl = realizedPnl + (timeRange === "all" ? unrealizedPnl : 0);
  const volume = computePerformanceVolume(filteredTrades);
  const drawdownEquity = market === "perps" ? accountEquity : spotWalletBalance;
  const maxDrawdown = computeMaxDrawdownPct(filteredTrades, drawdownEquity);

  const totalEquity =
    market === "spot" ? spotWalletBalance : accountEquity;

  return [
    {
      label: "PNL",
      value: formatPortfolioCurrency(pnl),
      valueClassName: pnl < 0 ? "negative" : undefined,
    },
    {
      label: "Volume",
      value: formatPortfolioCurrency(volume),
    },
    {
      label: "Max Drawdown",
      value: `${maxDrawdown.toFixed(2)}%`,
    },
    {
      label: "Total Equity",
      value: formatPortfolioCurrency(totalEquity),
    },
    {
      label: "Trading Equity",
      value: formatPortfolioCurrency(market === "spot" ? 0 : tradingEquity),
    },
    {
      label: "Vault Equity",
      value: formatPortfolioCurrency(0),
    },
    {
      label: "Earn Balance",
      value: formatPortfolioCurrency(0),
    },
    {
      label: "Staking Account",
      value: "0 MORM",
    },
  ];
}

export interface PerformanceAccountsInput {
  accountEquity: number;
  spotWalletBalance: number;
  collections: Bucket[];
  positions: Position[];
}

export function buildPerformanceAccountsRows(
  input: PerformanceAccountsInput,
): PortfolioPerformanceMetricRow[] {
  const { accountEquity, spotWalletBalance, collections } = input;
  const perpsEquity = sumBucketEquity(collections);

  return [
    { label: "Total Equity", value: formatPortfolioCurrency(accountEquity) },
    {
      label: "Perpetuals Equity",
      value: formatPortfolioCurrency(perpsEquity),
    },
    { label: "Spot Equity", value: formatPortfolioCurrency(spotWalletBalance) },
    { label: "Bucket Equity", value: formatPortfolioCurrency(0) },
    { label: "Staking Equity", value: formatPortfolioCurrency(0) },
    { label: "Cred in MORM", value: formatPortfolioCurrency(0) },
  ];
}

export function buildPerpetualsOverviewRows(
  collections: Bucket[],
  positions: Position[],
): PortfolioPerformanceMetricRow[] {
  const crossBuckets = collections.filter((bucket) =>
    isCrossMargin(bucket.marginType ?? bucket.marginMode),
  );
  const crossPositions = positions.filter((position) =>
    isCrossMargin(position.marginMode),
  );

  const unrealizedPnl = sumUnrealizedPnl(crossPositions);
  const crossEquity = sumBucketEquity(crossBuckets);
  const crossNotional = crossPositions.reduce(
    (sum, position) => sum + positionNotional(position),
    0,
  );
  const crossUsedMargin = crossBuckets.reduce(
    (sum, bucket) => sum + bucket.usedMargin,
    0,
  );
  const maintenanceMargin = crossPositions.reduce(
    (sum, position) => sum + positionMaintenanceMargin(position),
    0,
  );

  const crossLeverage =
    crossEquity > 0 ? crossNotional / crossEquity : 0;
  const crossMarginUsage =
    crossEquity > 0 ? (crossUsedMargin / crossEquity) * 100 : 0;
  const crossMarginRatio =
    crossEquity > 0 ? (maintenanceMargin / crossEquity) * 100 : 0;

  return [
    {
      label: "Unrealized PnL",
      value: formatPortfolioCurrency(unrealizedPnl),
      valueClassName: unrealizedPnl < 0 ? "negative" : undefined,
    },
    {
      label: "Cross Leverage",
      value: `${crossLeverage.toFixed(2)}x`,
    },
    {
      label: "Cross Margin Usage",
      value: `${crossMarginUsage.toFixed(2)}%`,
    },
    {
      label: "Maintenance Margin",
      value: formatPortfolioCurrency(maintenanceMargin),
    },
    {
      label: "Cross Margin Ratio",
      value: `${crossMarginRatio.toFixed(2)}%`,
    },
  ];
}
