import React, { useState, useMemo, useRef, useEffect } from "react";
import { useMarkets } from "../hooks/useMarkets";
import { useRates } from "../hooks/useRates";
import { useTradePrice } from "../hooks/useTradePrice";
import { formatPriceFlexible, formatPercentage, formatLargeNumber, formatCurrency } from "../sdk/utils/display";
import { DEFAULT_BASE_URL } from "../constants";
import { useSubscription } from "../context/SubscriptionContext";
import { toNumberFromSatoshi } from "../sdk/utils/math";
import { useFundingCountdown } from "../hooks/useFundingCountdown";
import { getTickerPickerMeta, getMockMarketPriceByTicker } from "../../offline/mock_data";
import { LIVE_MAEX_INDEX_BASE_ASSETS } from "../../offline/mock_data/maexIndexCatalog";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { BubbleTip, BUBBLE_TIP_IDS } from "../tutorials/bubble-tip";
import { ExpandCollapseIcon } from "./ui/ExpandCollapseIcon";
import "./smartlayout/layout.css";

interface TickerBarProps {
  baseURL: string;
  selectedMarketId: string;
  height: string;
  onMarketSelect?: (marketId: string) => void;
  onOpenTickerSelection?: () => void;
  favorites?: string[]; // Array of market IDs that are favorited
  onFavoriteToggle?: (marketId: string) => void;
  isMobile?: boolean;
  detailsExpanded?: boolean;
  onDetailsExpandedChange?: (expanded: boolean) => void;
  compact?: boolean;
  showFavoritesBar?: boolean;
  tickerSelectionOpen?: boolean;
  selectionAnchorRef?: React.RefObject<HTMLDivElement | null>;
  containerRef?: React.RefObject<HTMLElement | null>;
}

interface TickerItem {
  marketId: string;
  symbol: string;
  price: number | null;
  priceChangePercent: number | null;
  isClosed: boolean;
  isFavorite: boolean;
}

type Timeframe = "1H" | "4H" | "1D" | "1W" | "1M";

function TickerBar({
  baseURL = DEFAULT_BASE_URL,
  selectedMarketId: propSelectedMarketId,
  height,
  onMarketSelect,
  onOpenTickerSelection,
  favorites = [],
  onFavoriteToggle,
  isMobile = false,
  detailsExpanded = false,
  onDetailsExpandedChange,
  compact = false,
  showFavoritesBar = true,
  tickerSelectionOpen = false,
  selectionAnchorRef,
  containerRef,
}: TickerBarProps): JSX.Element {
  const { markets, tickers, selectedMarketId, setSelectedMarketId } =
    useMarkets({
      baseURL,
      autoFetchMarkets: true,
    });

  const { subscribe, unsubscribe, isConnected, getRetainedDataByKey } = useSubscription();

  const favoritesSet = useMemo(() => new Set(favorites), [favorites]);
  const [timeframe, setTimeframe] = useState<Timeframe>("1H");
  const [priceFeed, setPriceFeed] = useState<number | null>(null);
  const [shouldAnimate, setShouldAnimate] = useState(false);
  const tickerScrollRef = useRef<HTMLDivElement>(null);
  const tickerTrackRef = useRef<HTMLDivElement>(null);
  const priceFeedCallbackRef = useRef<((data: any) => void) | null>(null);

  // Use prop or internal state for selected market
  const effectiveSelectedMarketId =
    propSelectedMarketId || selectedMarketId || null;

  const { displayPrice: tradeDisplayPrice } = useTradePrice({
    baseURL,
    marketId: effectiveSelectedMarketId || "",
  });

  // Use useRates hook for funding rate (and other rate data); hook uses context when inside SubscriptionProvider
  const {
    latestFundingRate,
  } = useRates({
    baseURL,
    marketId: effectiveSelectedMarketId || "",
    historyDepth: 1, // Only need latest value
  });

  // Extract and convert funding rate from useRates
  const fundingRate = useMemo(() => {
    if (!latestFundingRate?.fundingRate) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.fundingRate);
    } catch (error) {
      console.error("[TickerBar] Error converting funding rate:", error);
      return null;
    }
  }, [latestFundingRate]);

  // Index price from funding_rate feed (useRates)
  const indexPrice = useMemo(() => {
    if (!latestFundingRate?.indexPrice) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.indexPrice);
    } catch (error) {
      console.error("[TickerBar] Error converting index price:", error);
      return null;
    }
  }, [latestFundingRate]);

  // Open interest long/short from funding_rate feed (useRates; wire: open_interest_long, open_interest_short)
  const openInterestLong = useMemo(() => {
    if (!latestFundingRate?.openInterestLong) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.openInterestLong);
    } catch (error) {
      console.error("[TickerBar] Error converting open interest long:", error);
      return null;
    }
  }, [latestFundingRate]);

  const openInterestShort = useMemo(() => {
    if (!latestFundingRate?.openInterestShort) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.openInterestShort);
    } catch (error) {
      console.error("[TickerBar] Error converting open interest short:", error);
      return null;
    }
  }, [latestFundingRate]);

  // Skew from long/short percentage (ratioScale 1e8)
  const skewDisplay = useMemo(() => {
    const longPct = latestFundingRate?.longPercentage != null
      ? toNumberFromSatoshi(latestFundingRate.longPercentage)
      : null;
    const shortPct = latestFundingRate?.shortPercentage != null
      ? toNumberFromSatoshi(latestFundingRate.shortPercentage)
      : null;
    if (longPct != null && shortPct != null) {
      return `${formatPercentage(longPct)} / ${formatPercentage(shortPct)}`;
    }
    return null;
  }, [latestFundingRate]);

  // Extract mark_price from funding rate as fallback for oracle price
  const markPriceFromRates = useMemo(() => {
    if (!latestFundingRate?.markPrice) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.markPrice);
    } catch (error) {
      console.error("[TickerBar] Error converting mark_price:", error);
      return null;
    }
  }, [latestFundingRate]);

  // Oracle price: prefer priceFeed, fallback to mark_price from funding rate
  const oraclePrice = useMemo(() => {
    return priceFeed !== null ? priceFeed : markPriceFromRates;
  }, [priceFeed, markPriceFromRates]);

  const openInterestRatio = useMemo(() => {
    if (!latestFundingRate?.longShortRatio) return null;
    try {
      return toNumberFromSatoshi(latestFundingRate.longShortRatio);
    } catch (error) {
      console.error("[TickerBar] Error converting long short ratio:", error);
      return null;
    }
  }, [latestFundingRate]);

  const openInterestRatioDisplay = useMemo(() => {
    if (openInterestRatio === null) return null;
    return openInterestRatio.toFixed(2);
  }, [openInterestRatio]);

  // Build ticker items from markets and tickers
  const tickerItems = useMemo((): TickerItem[] => {
    return markets
      .map((market) => {
        const marketId = market.index ?? market.marketIndex ?? "";
        const ticker = tickers.get(marketId);
        const symbol =
          market.moniker ||
          market.symbol ||
          (market.baseAsset && market.quoteAsset
            ? `${market.baseAsset}/${market.quoteAsset}`
            : "Unknown");

        // Determine if market is closed (no active price or market inactive)
        const isClosed =
          !market.active ||
          !ticker?.lastPrice ||
          (typeof ticker.lastPrice === "string" && ticker.lastPrice === "0");

        // Get price
        let price: number | null = null;
        if (ticker?.lastPrice) {
          if (typeof ticker.lastPrice === "string") {
            price = parseFloat(ticker.lastPrice);
          } else {
            price = ticker.lastPrice;
          }
        }

        // Get price change percent
        let priceChangePercent: number | null = null;
        if (ticker?.priceChangePercent24h) {
          if (typeof ticker.priceChangePercent24h === "string") {
            priceChangePercent = parseFloat(ticker.priceChangePercent24h);
          } else {
            priceChangePercent = ticker.priceChangePercent24h;
          }
        }

        return {
          marketId,
          symbol,
          price,
          priceChangePercent,
          isClosed,
          isFavorite: favoritesSet.has(marketId),
        };
      })
      .filter((item) => item.marketId); // Filter out invalid items
  }, [markets, tickers, favoritesSet]);

  const favoriteTickerItems = useMemo(
    () => tickerItems.filter((item) => item.isFavorite),
    [tickerItems],
  );

  const showTopBar = !compact || showFavoritesBar;

  const topBarDisplay = useMemo(() => {
    if (favoriteTickerItems.length > 0) {
      return { items: favoriteTickerItems, isDemo: false };
    }
    if (compact && showTopBar) {
      const indexAssetOrder = new Map(
        LIVE_MAEX_INDEX_BASE_ASSETS.map((asset, index) => [asset, index]),
      );
      const indexItems = tickerItems
        .filter((item) => {
          const base = item.symbol.split("/")[0]?.trim().toUpperCase() ?? "";
          return getTickerPickerMeta(base).category === "index";
        })
        .sort((a, b) => {
          const baseA = a.symbol.split("/")[0]?.trim().toUpperCase() ?? "";
          const baseB = b.symbol.split("/")[0]?.trim().toUpperCase() ?? "";
          return (
            (indexAssetOrder.get(baseA) ?? Number.MAX_SAFE_INTEGER) -
            (indexAssetOrder.get(baseB) ?? Number.MAX_SAFE_INTEGER)
          );
        });
      return { items: indexItems, isDemo: true };
    }
    return { items: [], isDemo: false };
  }, [favoriteTickerItems, tickerItems, compact, showTopBar]);

  // Get selected market details
  const selectedMarket = useMemo(() => {
    if (!effectiveSelectedMarketId) return null;
    return markets.find(
      (m) =>
        m.index === effectiveSelectedMarketId ||
        m.marketIndex === effectiveSelectedMarketId,
    );
  }, [markets, effectiveSelectedMarketId]);

  const selectedTicker = useMemo(() => {
    if (!effectiveSelectedMarketId) return null;
    return tickers.get(effectiveSelectedMarketId);
  }, [tickers, effectiveSelectedMarketId]);

  // Get selected market symbol
  const selectedSymbol = useMemo(() => {
    if (!selectedMarket) return "Select Market";
    return (
      selectedMarket.moniker ||
      selectedMarket.symbol ||
      (selectedMarket.baseAsset && selectedMarket.quoteAsset
        ? `${selectedMarket.baseAsset}/${selectedMarket.quoteAsset}`
        : "Unknown")
    );
  }, [selectedMarket]);

  // Get selected market description
  const selectedDescription = useMemo(() => {
    if (!selectedMarket) return "";
    const base = selectedMarket.baseAsset || "";
    const quote = selectedMarket.quoteAsset || "";
    if (base && quote) {
      return `${base} to ${quote}`;
    }
    return selectedMarket.moniker || selectedMarket.symbol || "";
  }, [selectedMarket]);

  // Get selected market price and change
  const selectedPrice = useMemo(() => {
    if (!selectedTicker?.lastPrice) return null;
    if (typeof selectedTicker.lastPrice === "string") {
      return parseFloat(selectedTicker.lastPrice);
    }
    return selectedTicker.lastPrice;
  }, [selectedTicker]);

  const selectedPriceChange = useMemo(() => {
    if (!selectedTicker?.priceChangePercent24h) return null;
    if (typeof selectedTicker.priceChangePercent24h === "string") {
      return parseFloat(selectedTicker.priceChangePercent24h);
    }
    return selectedTicker.priceChangePercent24h;
  }, [selectedTicker]);

  const priceChange24hAbs = useMemo(() => {
    if (!selectedTicker?.priceChange24h) return null;
    if (typeof selectedTicker.priceChange24h === "string") {
      return parseFloat(selectedTicker.priceChange24h);
    }
    return selectedTicker.priceChange24h;
  }, [selectedTicker]);

  const volume24h = useMemo(() => {
    if (!selectedTicker?.volume) return null;
    const raw = selectedTicker.volume;
    try {
      return toNumberFromSatoshi(typeof raw === "string" ? raw : String(raw));
    } catch {
      const parsed = typeof raw === "number" ? raw : parseFloat(String(raw));
      return Number.isFinite(parsed) ? parsed : null;
    }
  }, [selectedTicker]);

  const assetBadgeLabel = useMemo(() => {
    const base = selectedSymbol.split("/")[0]?.trim();
    return base ? base.toLowerCase() : selectedSymbol.toLowerCase();
  }, [selectedSymbol]);

  const baseAsset = useMemo(
    () =>
      selectedMarket?.baseAsset ||
      selectedSymbol.split("/")[0]?.split("-")[0] ||
      "",
    [selectedMarket, selectedSymbol],
  );

  const pickerMeta = useMemo(
    () => getTickerPickerMeta(baseAsset),
    [baseAsset],
  );
  const maxMarketLeverage = pickerMeta.leverage;
  const showLeverageBadge = maxMarketLeverage > 1;
  const showBetaBadge = pickerMeta.isBeta === true;

  const openInterestNotional = useMemo(() => {
    if (
      openInterestLong === null ||
      openInterestShort === null ||
      markPriceFromRates === null
    ) {
      return null;
    }
    return (openInterestLong + openInterestShort) * markPriceFromRates;
  }, [openInterestLong, openInterestShort, markPriceFromRates]);

  const offline = isOfflineMode(baseURL);
  const mockBasePrice = getMockMarketPriceByTicker(baseAsset);

  const compactMetrics = useMemo(() => {
    const mockChangePct = pickerMeta.change24h;
    const mockChangeAbs = mockBasePrice * (mockChangePct / 100);
    const mockMark = mockBasePrice * 1.0004;
    const mockOracle = mockBasePrice;

    const mark =
      !offline && markPriceFromRates !== null ? markPriceFromRates : mockMark;
    const oracle =
      !offline && oraclePrice !== null ? oraclePrice : mockOracle;

    const changePct =
      !offline && selectedPriceChange !== null
        ? selectedPriceChange
        : mockChangePct;
    const changeAbs =
      !offline && priceChange24hAbs !== null
        ? priceChange24hAbs
        : mockChangeAbs;

    const volume =
      !offline && volume24h !== null ? volume24h : pickerMeta.volume24h;
    const openInterest =
      !offline && openInterestNotional !== null
        ? openInterestNotional
        : pickerMeta.openInterest;

    const fundingDisplay =
      !offline && fundingRate !== null
        ? formatPercentage(fundingRate)
        : `${pickerMeta.annFunding.toFixed(1)}%`;

    const fundingForClass =
      !offline && fundingRate !== null ? fundingRate : pickerMeta.annFunding;

    const changeDisplay = `${formatPriceFlexible(changeAbs)} / ${formatPercentage(changePct / 100)}`;

    return {
      mark,
      oracle,
      changePct,
      changeDisplay,
      volume,
      openInterest,
      fundingDisplay,
      fundingForClass,
    };
  }, [
    offline,
    mockBasePrice,
    pickerMeta,
    markPriceFromRates,
    oraclePrice,
    selectedPriceChange,
    priceChange24hAbs,
    volume24h,
    openInterestNotional,
    fundingRate,
  ]);

  const change24hDisplay = useMemo(() => {
    if (priceChange24hAbs === null && selectedPriceChange === null) return null;
    const absPart =
      priceChange24hAbs !== null ? formatPriceFlexible(priceChange24hAbs) : "--";
    const pctPart =
      selectedPriceChange !== null
        ? formatPercentage(selectedPriceChange / 100)
        : "--";
    return `${absPart} / ${pctPart}`;
  }, [priceChange24hAbs, selectedPriceChange]);

  const nextFundingTimeUnix = useMemo(() => {
    const raw = latestFundingRate as Record<string, unknown> | undefined;
    if (!raw) return null;
    const next = raw.nextFundingTime ?? raw.next_funding_time_unix;
    if (next == null) return null;
    return typeof next === "number" ? next : parseFloat(String(next));
  }, [latestFundingRate]);

  const fundingIntervalSeconds = useMemo(() => {
    const raw = latestFundingRate as Record<string, unknown> | undefined;
    const interval = raw?.fundingIntervalSeconds ?? raw?.funding_interval_seconds;
    if (interval == null) return 28800;
    return typeof interval === "number" ? interval : parseFloat(String(interval));
  }, [latestFundingRate]);

  const fundingCountdown = useFundingCountdown(
    nextFundingTimeUnix,
    fundingIntervalSeconds,
  );

  const detailPrice = tradeDisplayPrice ?? selectedPrice;

  // Subscribe to priceFeed for selected market via key-based API (one subscription per priceFeed:marketId)
  useEffect(() => {
    if (!effectiveSelectedMarketId || !isConnected) {
      setPriceFeed(null);
      return;
    }

    const marketId = effectiveSelectedMarketId;
    const key = `priceFeed:${marketId}`;

    // Check for retained data first
    const retained = getRetainedDataByKey?.(key);
    if (retained && typeof retained === "object" && "price" in (retained as object)) {
      try {
        const price = toNumberFromSatoshi((retained as { price: string }).price);
        setPriceFeed(price);
      } catch (error) {
        console.error("[TickerBar] Error processing retained priceFeed:", error);
      }
    }

    const handlePriceFeedUpdate = (data: unknown) => {
      try {
        if (data && typeof data === "object" && data !== null && "price" in data) {
          const price = toNumberFromSatoshi((data as { price: string }).price);
          setPriceFeed(price);
        }
      } catch (error) {
        console.error("[TickerBar] Error processing priceFeed update:", error);
      }
    };

    priceFeedCallbackRef.current = handlePriceFeedUpdate;
    subscribe(key, handlePriceFeedUpdate);

    return () => {
      if (priceFeedCallbackRef.current) {
        unsubscribe(key, priceFeedCallbackRef.current);
        priceFeedCallbackRef.current = null;
      }
    };
  }, [effectiveSelectedMarketId, isConnected, subscribe, unsubscribe, getRetainedDataByKey]);

  useEffect(() => {
    if (!showTopBar) {
      setShouldAnimate(false);
      return;
    }

    const container = tickerScrollRef.current;
    const track = tickerTrackRef.current;
    if (!container || !track || topBarDisplay.items.length === 0) {
      setShouldAnimate(false);
      return;
    }

    const updateMarquee = () => {
      const containerWidth = container.clientWidth;
      const trackWidth = track.scrollWidth;
      const overflowThreshold = 4;

      if (!shouldAnimate) {
        if (trackWidth > containerWidth + overflowThreshold) {
          setShouldAnimate(true);
        }
        return;
      }

      const halfWidth = trackWidth / 2;
      if (halfWidth <= containerWidth + overflowThreshold) {
        setShouldAnimate(false);
        return;
      }

      track.style.setProperty(
        "--ticker-scroll-duration",
        `${halfWidth / 45}s`,
      );
    };

    updateMarquee();

    const observer = new ResizeObserver(updateMarquee);
    observer.observe(container);
    observer.observe(track);

    return () => observer.disconnect();
  }, [showTopBar, topBarDisplay.items, shouldAnimate]);

  // Handle market selection
  const handleMarketSelect = (marketId: string) => {
    if (onMarketSelect) {
      onMarketSelect(marketId);
    } else {
      setSelectedMarketId(marketId);
    }
  };

  const handleFavoriteToggle = (marketId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    onFavoriteToggle?.(marketId);
  };

  // Get asset icon (simple fallback - can be enhanced with actual icon mapping)
  const getAssetIcon = (symbol: string): string => {
    const baseAsset = symbol.split("/")[0]?.toUpperCase() || "";
    // Return a simple emoji or icon based on asset
    const iconMap: Record<string, string> = {
      BTC: "₿",
      ETH: "Ξ",
      EUR: "€",
      USD: "$",
      USDC: "$",
      USDT: "$",
    };
    return iconMap[baseAsset] || baseAsset.charAt(0) || "?";
  };

  const handleOpenTickerSelection = (e: React.MouseEvent | React.KeyboardEvent) => {
    if (!onOpenTickerSelection) return;
    e.stopPropagation();
    onOpenTickerSelection();
  };

  const handlePriceToggle = (e: React.MouseEvent | React.KeyboardEvent) => {
    if (!isMobile || !onDetailsExpandedChange) return;
    e.stopPropagation();
    onDetailsExpandedChange(!detailsExpanded);
  };

  const showDetailMetrics = !isMobile || detailsExpanded;
  const useSelectionAnchor = !isMobile && onOpenTickerSelection && selectionAnchorRef;

  const getCompactLabel = (symbol: string): string => {
    const base = symbol.split("/")[0]?.trim() ?? "";
    const meta = getTickerPickerMeta(base);
    return meta.tickerLabel ?? base;
  };

  const containerClassName = [
    "ticker-bar-container layout-container",
    compact ? "ticker-bar-container--compact" : "",
    compact && showFavoritesBar ? "ticker-bar-container--compact-with-top" : "",
    isMobile && detailsExpanded ? "ticker-bar-container--details-expanded" : "",
    isMobile && !detailsExpanded ? "ticker-bar-container--details-collapsed" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const renderTickerItem = (
    item: TickerItem,
    keySuffix: string,
    index: number,
    total: number,
    ariaHidden = false,
  ) => (
    <React.Fragment key={`${item.marketId}-${keySuffix}`}>
      <div
        className={`ticker-item ${
          item.marketId === effectiveSelectedMarketId ? "active" : ""
        }`}
        onClick={() => handleMarketSelect(item.marketId)}
        aria-hidden={ariaHidden || undefined}
      >
        <span
          className="ticker-favorite-star"
          onClick={(e) => handleFavoriteToggle(item.marketId, e)}
          style={{
            cursor: "pointer",
            opacity: item.isFavorite ? 1 : 0.3,
          }}
        >
          ★
        </span>
        <span className="ticker-asset-icon">
          {getAssetIcon(item.symbol)}
        </span>
        <span className="ticker-symbol">{item.symbol}</span>
        {item.marketId === effectiveSelectedMarketId ? (
          <BubbleTip id={BUBBLE_TIP_IDS.currentPrice}>
            <span className="ticker-value">
              {item.isClosed ? (
                <span className="ticker-closed">CLOSED</span>
              ) : item.price !== null ? (
                formatPriceFlexible(item.price)
              ) : (
                "--"
              )}
            </span>
          </BubbleTip>
        ) : (
          <span className="ticker-value">
            {item.isClosed ? (
              <span className="ticker-closed">CLOSED</span>
            ) : item.price !== null ? (
              formatPriceFlexible(item.price)
            ) : (
              "--"
            )}
          </span>
        )}
      </div>
      {index < total - 1 && (
        <div className="ticker-separator" aria-hidden={ariaHidden || undefined} />
      )}
    </React.Fragment>
  );

  const renderCompactTickerItem = (
    item: TickerItem,
    keySuffix: string,
    index: number,
    total: number,
    ariaHidden = false,
  ) => (
    <React.Fragment key={`${item.marketId}-${keySuffix}`}>
      <div
        className={`ticker-item ticker-item--compact ${
          item.marketId === effectiveSelectedMarketId ? "active" : ""
        }`}
        onClick={() => handleMarketSelect(item.marketId)}
        aria-hidden={ariaHidden || undefined}
      >
        <span className="ticker-symbol">{getCompactLabel(item.symbol)}</span>
        <span className="ticker-value">
          {item.isClosed ? (
            <span className="ticker-closed">CLOSED</span>
          ) : item.price !== null ? (
            formatPriceFlexible(item.price)
          ) : (
            "--"
          )}
        </span>
        {item.priceChangePercent !== null ? (
          <span
            className={`ticker-change ${
              item.priceChangePercent >= 0 ? "positive" : "negative"
            }`}
          >
            {formatPercentage(item.priceChangePercent / 100)}
          </span>
        ) : null}
      </div>
      {index < total - 1 && (
        <div className="ticker-separator" aria-hidden={ariaHidden || undefined} />
      )}
    </React.Fragment>
  );

  const renderTopBarItem = (
    item: TickerItem,
    keySuffix: string,
    index: number,
    total: number,
    ariaHidden = false,
  ) =>
    compact
      ? renderCompactTickerItem(item, keySuffix, index, total, ariaHidden)
      : renderTickerItem(item, keySuffix, index, total, ariaHidden);

  return (
    <div
      ref={containerRef}
      className={containerClassName}
      style={height ? { height } : undefined}
      data-tour="welcome-market-selector"
    >
      {/* Top Scrolling Ticker Bar */}
      {showTopBar ? (
      <div
        className={`ticker-bar-top${compact ? " ticker-bar-top--compact" : ""}`}
        ref={tickerScrollRef}
      >
        {topBarDisplay.items.length === 0 ? (
          <div
            className={`ticker-bar-empty${
              onOpenTickerSelection ? " ticker-bar-empty-clickable" : ""
            }`}
            role={onOpenTickerSelection ? "button" : undefined}
            tabIndex={onOpenTickerSelection ? 0 : undefined}
            onClick={onOpenTickerSelection ? handleOpenTickerSelection : undefined}
            onKeyDown={
              onOpenTickerSelection
                ? (e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      handleOpenTickerSelection(e);
                    }
                  }
                : undefined
            }
          >
            No favorites — open market selector to add
          </div>
        ) : (
          <div
            className={`ticker-bar-scroll${
              shouldAnimate ? " ticker-bar-scroll--animated" : ""
            }`}
          >
            <div
              className="ticker-bar-track"
              ref={tickerTrackRef}
              aria-label={topBarDisplay.isDemo ? "Index market tickers" : "Favorite tickers"}
            >
              {topBarDisplay.items.map((item, index) =>
                renderTopBarItem(
                  item,
                  `a-${index}`,
                  index,
                  topBarDisplay.items.length,
                ),
              )}
              {shouldAnimate &&
                topBarDisplay.items.map((item, index) =>
                  renderTopBarItem(
                    item,
                    `b-${index}`,
                    index,
                    topBarDisplay.items.length,
                    true,
                  ),
                )}
            </div>
          </div>
        )}
      </div>
      ) : null}

      {/* Bottom Detailed View */}
      <div className="ticker-bar-bottom">
        {compact && !isMobile ? (
          <>
            <div
              className={`ticker-compact-badges${onOpenTickerSelection ? " ticker-compact-badges--clickable" : ""}`}
              ref={useSelectionAnchor ? selectionAnchorRef : undefined}
              role={onOpenTickerSelection ? "button" : undefined}
              tabIndex={onOpenTickerSelection ? 0 : undefined}
              aria-expanded={onOpenTickerSelection ? tickerSelectionOpen : undefined}
              onClick={onOpenTickerSelection ? handleOpenTickerSelection : undefined}
              onKeyDown={
                onOpenTickerSelection
                  ? (e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        handleOpenTickerSelection(e);
                      }
                    }
                  : undefined
              }
            >
              <span className="ticker-compact-symbol-group">
                <span className="ticker-compact-symbol">{assetBadgeLabel}</span>
                {onOpenTickerSelection ? (
                  <ExpandCollapseIcon
                    expanded={tickerSelectionOpen}
                    className="ticker-compact-chevron"
                    size={14}
                  />
                ) : null}
              </span>
              {showLeverageBadge ? (
                <span className="ticker-compact-badge">{maxMarketLeverage}x</span>
              ) : null}
              {showBetaBadge ? (
                <span className="ticker-compact-badge ticker-compact-badge--beta">
                  Beta
                </span>
              ) : null}
            </div>
            <div className="ticker-detail-metrics ticker-detail-metrics--compact">
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.markPrice}>
                  <label className="ticker-metric-label">Mark</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {formatPriceFlexible(compactMetrics.mark)}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.oraclePrice}>
                  <label className="ticker-metric-label">Oracle</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {formatPriceFlexible(compactMetrics.oracle)}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.change24h}>
                  <label className="ticker-metric-label">24h Change</label>
                </BubbleTip>
                <span
                  className={`ticker-metric-value ${
                    compactMetrics.changePct >= 0 ? "positive" : "negative"
                  }`}
                >
                  {compactMetrics.changeDisplay}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.largeMetrics}>
                  <label className="ticker-metric-label">24h Volume</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {`$${formatCurrency(compactMetrics.volume)}`}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.largeMetrics}>
                  <label className="ticker-metric-label">Open Interest</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {`$${formatCurrency(compactMetrics.openInterest)}`}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.fundingCountdown}>
                  <label className="ticker-metric-label">Funding / Countdown</label>
                </BubbleTip>
                <span className="ticker-metric-value ticker-metric-value--funding">
                  <span
                    className={
                      compactMetrics.fundingForClass < 0
                        ? "negative"
                        : compactMetrics.fundingForClass > 0
                          ? "positive"
                          : ""
                    }
                  >
                    {compactMetrics.fundingDisplay}
                  </span>
                  <span className="ticker-funding-countdown">
                    {fundingCountdown}
                  </span>
                </span>
              </div>
            </div>
          </>
        ) : (
          <>
        {/* Left: Asset Info */}
        <div
          className={`ticker-detail-left ${onOpenTickerSelection ? "ticker-detail-left-clickable" : ""}`}
          ref={useSelectionAnchor && !compact ? selectionAnchorRef : undefined}
          role={onOpenTickerSelection ? "button" : undefined}
          tabIndex={onOpenTickerSelection ? 0 : undefined}
          onClick={onOpenTickerSelection ? handleOpenTickerSelection : undefined}
          onKeyDown={
            onOpenTickerSelection
              ? (e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    handleOpenTickerSelection(e);
                  }
                }
              : undefined
          }
        >
          <div className="ticker-detail-icon-large">
            {selectedMarket ? getAssetIcon(selectedSymbol) : "?"}
          </div>
          <div className="ticker-detail-symbol-group">
            <div className="ticker-detail-symbol-row">
              <span className="ticker-detail-symbol">{selectedSymbol}</span>
            </div>
            <div className="ticker-detail-description">
              {selectedDescription}
            </div>
          </div>
          <div
            className={`ticker-detail-price-group${isMobile && onDetailsExpandedChange ? " ticker-detail-price-group--tappable" : ""}`}
            role={isMobile && onDetailsExpandedChange ? "button" : undefined}
            tabIndex={isMobile && onDetailsExpandedChange ? 0 : undefined}
            aria-expanded={isMobile ? detailsExpanded : undefined}
            aria-label={isMobile ? "Toggle market details" : undefined}
            onClick={isMobile && onDetailsExpandedChange ? handlePriceToggle : undefined}
            onKeyDown={
              isMobile && onDetailsExpandedChange
                ? (e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      handlePriceToggle(e);
                    }
                  }
                : undefined
            }
          >
            <BubbleTip id={BUBBLE_TIP_IDS.currentPrice}>
              <div className="ticker-detail-price">
                {detailPrice !== null
                  ? formatPriceFlexible(detailPrice)
                  : "--"}
              </div>
            </BubbleTip>
            {selectedPriceChange !== null && (
              <div
                className={`ticker-detail-change ${
                  selectedPriceChange >= 0 ? "positive" : "negative"
                }`}
              >
                {selectedPriceChange >= 0 ? "+" : ""}
                {formatPercentage(selectedPriceChange / 100)}
              </div>
            )}
            {isMobile && onDetailsExpandedChange ? (
              <ExpandCollapseIcon
                expanded={detailsExpanded}
                className="ticker-detail-expand-hint"
                size={14}
              />
            ) : null}
          </div>
        </div>

        {showDetailMetrics ? (
          compact ? (
            <div className="ticker-detail-metrics ticker-detail-metrics--compact">
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.openInterestRatio}>
                  <label className="ticker-metric-label">Open Interest Ratio</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {openInterestRatioDisplay ?? "--"}
                </span>
              </div>
              <div className="ticker-metric">
                <BubbleTip id={BUBBLE_TIP_IDS.oraclePrice}>
                  <label className="ticker-metric-label">Oracle Price</label>
                </BubbleTip>
                <span className="ticker-metric-value">
                  {oraclePrice !== null
                    ? formatPriceFlexible(oraclePrice)
                    : "--"}
                </span>
              </div>
            </div>
          ) : (
          <>
        {/* Middle: Market Metrics */}
        <div className="ticker-detail-metrics">
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.indexPrice}>
              <label className="ticker-metric-label">Index Price</label>
            </BubbleTip>
            <span className="ticker-metric-value">
              {indexPrice !== null
                ? formatPriceFlexible(indexPrice)
                : "--"}
            </span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.oraclePrice}>
              <label className="ticker-metric-label">Oracle Price</label>
            </BubbleTip>
            <span className="ticker-metric-value">
              {oraclePrice !== null
                ? formatPriceFlexible(oraclePrice)
                : "--"}
            </span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.openInterestLong}>
              <label className="ticker-metric-label">Open Interest (L)</label>
            </BubbleTip>
            <span className="ticker-metric-value">
              {openInterestLong !== null
                ? formatLargeNumber(openInterestLong)
                : "--"}
            </span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.openInterestShort}>
              <label className="ticker-metric-label">Open Interest (S)</label>
            </BubbleTip>
            <span className="ticker-metric-value">
              {openInterestShort !== null
                ? formatLargeNumber(openInterestShort)
                : "--"}
            </span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.skew}>
              <label className="ticker-metric-label">Skew</label>
            </BubbleTip>
            <span className="ticker-metric-value">
              {skewDisplay ?? "--"}
            </span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.fundingRate}>
              <label className="ticker-metric-label">Funding Rate</label>
            </BubbleTip>
            <span className={`ticker-metric-value ${
              fundingRate !== null && fundingRate < 0 ? "negative" : fundingRate !== null && fundingRate > 0 ? "positive" : ""
            }`}>
              {fundingRate !== null
                ? formatPercentage(fundingRate)
                : "--"}
            </span>
          </div>
        </div>

        {/* Right: Holdings & Timeframe */}
        <div className="ticker-detail-right">
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.holdingLong}>
              <label className="ticker-metric-label">Holding (L)</label>
            </BubbleTip>
            <span className="ticker-metric-value positive">0.0012%</span>
          </div>
          <div className="ticker-metric">
            <BubbleTip id={BUBBLE_TIP_IDS.holdingShort}>
              <label className="ticker-metric-label">Holding (S)</label>
            </BubbleTip>
            <span className="ticker-metric-value negative">0.0021%</span>
          </div>
        </div>
        <div className="ticker-timeframe-selector">
          <select
            className="ticker-timeframe-select"
            value={timeframe}
            onChange={(e) => setTimeframe(e.target.value as Timeframe)}
          >
            <option value="1H">1H</option>
            <option value="4H">4H</option>
            <option value="1D">1D</option>
            <option value="1W">1W</option>
            <option value="1M">1M</option>
          </select>
        </div>
          </>
          )
        ) : null}
          </>
        )}
      </div>
    </div>
  );
}

export default React.memo(TickerBar);
