import React, { useCallback, useEffect, useMemo, useState } from "react";

import type { CopyAutonomyPreset } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { Bucket } from "../../sdk";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import { formatCurrency } from "../../sdk/utils/display";
import CopyAgentModalShell, { useCopyAgentModalShell } from "./CopyAgentModalShell";
import {
  CopyAgentExistingBucketConfirm,
  CopyAgentHighAgencyConfirm,
} from "./CopyAgentConfirmSheets";
import {
  CopyAgentAutonomyCards,
  CopyAgentDestinationCards,
  CopyAgentLeaderHeader,
  CopyAgentMdSummaryCard,
  CopyAgentMiniSummary,
  CopyAgentSummaryRail,
} from "./CopyAgentModalParts";
import { buildCopyAgentRiskPreview } from "./copyAgentRiskPreview";
import { ConnectWalletPanel } from "../wallet";
import {
  buildCopyAgentConfirmParams,
  buildCopyAgentFormState,
  COPY_AGENT_DEFAULT_SIZE_PCT,
  COPY_AGENT_DEFAULT_STARTING_MARGIN,
  COPY_AGENT_MIN_MARGIN,
  COPY_AGENT_MIN_SIZE_PCT,
  COPY_AGENT_MAX_SIZE_PCT,
  isCopyAgentFormBasicsValid,
  isCopyAgentConfirmValid,
  needsExistingBucketShareConfirm,
  type CopyAgentConfirmParams,
  type CopyAgentFormState,
} from "./copyAgentModalValidation";
import { COPY_TOUR_TARGETS } from "../../tutorials/copy-tour/constants";
import { useOptionalCopyTour } from "../../tutorials/copy-tour";
import "../smartlayout/layout.css";
import "./agent.css";

export type { CopyAgentConfirmParams };

export interface CopyAgentModalProps {
  open: boolean;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  walletConnected: boolean;
  isCopying: boolean;
  crossBuckets: Bucket[];
  spotWalletBalance: number;
  onClose: () => void;
  onConfirm: (params: CopyAgentConfirmParams) => void | Promise<void>;
}

function CopyAgentModalBody({
  profile,
  fleet,
  walletConnected,
  isCopying,
  crossBuckets,
  spotWalletBalance,
  onClose,
  onConfirm,
}: Omit<CopyAgentModalProps, "open">): JSX.Element {
  const { layout, isSheet, overlay } = useCopyAgentModalShell();
  const isClosing = overlay.isClosing;
  const [destinationMode, setDestinationMode] = useState<"new" | "existing">("new");
  const [startingMargin, setStartingMargin] = useState(() =>
    Math.min(
      COPY_AGENT_DEFAULT_STARTING_MARGIN,
      Math.max(COPY_AGENT_MIN_MARGIN, spotWalletBalance),
    ),
  );
  const [existingBucketId, setExistingBucketId] = useState(
    () => crossBuckets[0]?.bucketId ?? "",
  );
  const [copySizePct, setCopySizePct] = useState(COPY_AGENT_DEFAULT_SIZE_PCT);
  const [autonomyPreset, setAutonomyPreset] =
    useState<CopyAutonomyPreset>("guarded");
  const [highAgencyConfirmed, setHighAgencyConfirmed] = useState(false);
  const [existingBucketShareAcknowledged, setExistingBucketShareAcknowledged] =
    useState(false);
  const [riskAcknowledged, setRiskAcknowledged] = useState(false);
  const [mdSummaryOpen, setMdSummaryOpen] = useState(false);
  const [sheetSummaryExpanded, setSheetSummaryExpanded] = useState(false);
  const [pendingHighAgencyConfirm, setPendingHighAgencyConfirm] = useState(false);
  const [pendingExistingBucketConfirm, setPendingExistingBucketConfirm] =
    useState(false);
  const copyTour = useOptionalCopyTour();
  const copyTourActive = Boolean(copyTour?.runTour);

  useEffect(() => {
    if (!copyTourActive) return;
    setDestinationMode("new");
    setStartingMargin(COPY_AGENT_DEFAULT_STARTING_MARGIN);
    setCopySizePct(COPY_AGENT_DEFAULT_SIZE_PCT);
    setAutonomyPreset("highAgency");
    setHighAgencyConfirmed(true);
    setRiskAcknowledged(true);
  }, [copyTourActive, open]);

  useEffect(() => {
    if (copyTourActive) return;
    setHighAgencyConfirmed(false);
    setExistingBucketShareAcknowledged(false);
    setRiskAcknowledged(false);
    setPendingHighAgencyConfirm(false);
    setPendingExistingBucketConfirm(false);
  }, [
    autonomyPreset,
    copyTourActive,
    destinationMode,
    existingBucketId,
    startingMargin,
    copySizePct,
  ]);

  const selectedBucket = useMemo(
    () => crossBuckets.find((bucket) => bucket.bucketId === existingBucketId),
    [crossBuckets, existingBucketId],
  );

  const maxStartingMargin = Math.max(COPY_AGENT_MIN_MARGIN, spotWalletBalance);

  const formState = buildCopyAgentFormState({
    walletConnected,
    destinationMode,
    startingMargin,
    existingBucketId,
    copySizePct,
    spotWalletBalance,
    autonomyPreset,
    highAgencyConfirmed,
    existingBucketShareAcknowledged,
    riskAcknowledged,
    selectedBucket,
  });

  const preview = useMemo(
    () =>
      buildCopyAgentRiskPreview(
        {
          destinationMode,
          startingMargin,
          existingBucket: selectedBucket,
          copySizePct,
          autonomyPreset,
        },
        profile,
      ),
    [
      destinationMode,
      startingMargin,
      selectedBucket,
      copySizePct,
      autonomyPreset,
      profile,
    ],
  );

  const canConfirm =
    isCopyAgentFormBasicsValid(formState) &&
    riskAcknowledged &&
    !isCopying;

  const runConfirm = useCallback(
    (
      overrides?: Partial<
        Pick<
          CopyAgentFormState,
          | "highAgencyConfirmed"
          | "existingBucketShareAcknowledged"
          | "riskAcknowledged"
        >
      >,
    ) => {
      const nextState = buildCopyAgentFormState({
        walletConnected,
        destinationMode,
        startingMargin,
        existingBucketId,
        copySizePct,
        spotWalletBalance,
        autonomyPreset,
        highAgencyConfirmed:
          overrides?.highAgencyConfirmed ?? highAgencyConfirmed,
        existingBucketShareAcknowledged:
          overrides?.existingBucketShareAcknowledged ??
          existingBucketShareAcknowledged,
        riskAcknowledged: overrides?.riskAcknowledged ?? riskAcknowledged,
        selectedBucket,
      });
      if (!isCopyAgentConfirmValid(nextState)) return;
      void onConfirm(
        buildCopyAgentConfirmParams(
          profile.id,
          profile.name,
          profile.perpBaseAsset,
          nextState,
          autonomyPreset,
        ),
      );
    },
    [
      autonomyPreset,
      copySizePct,
      destinationMode,
      existingBucketId,
      existingBucketShareAcknowledged,
      highAgencyConfirmed,
      riskAcknowledged,
      onConfirm,
      profile,
      selectedBucket,
      spotWalletBalance,
      startingMargin,
      walletConnected,
    ],
  );

  const handleConfirm = () => {
    if (!canConfirm) return;
    if (autonomyPreset === "highAgency" && !highAgencyConfirmed) {
      setPendingHighAgencyConfirm(true);
      return;
    }
    if (
      needsExistingBucketShareConfirm(
        destinationMode,
        Number(selectedBucket?.totalEquity ?? 0),
      ) &&
      !existingBucketShareAcknowledged
    ) {
      setPendingExistingBucketConfirm(true);
      return;
    }
    runConfirm();
  };

  const handleHighAgencyConfirm = () => {
    setHighAgencyConfirmed(true);
    setPendingHighAgencyConfirm(false);
    if (
      needsExistingBucketShareConfirm(
        destinationMode,
        Number(selectedBucket?.totalEquity ?? 0),
      ) &&
      !existingBucketShareAcknowledged
    ) {
      setPendingExistingBucketConfirm(true);
      return;
    }
    runConfirm({ highAgencyConfirmed: true });
  };

  const handleExistingBucketConfirm = () => {
    setExistingBucketShareAcknowledged(true);
    setPendingExistingBucketConfirm(false);
    runConfirm({
      highAgencyConfirmed:
        autonomyPreset === "highAgency" ? true : highAgencyConfirmed,
      existingBucketShareAcknowledged: true,
    });
  };

  const summaryRail = (
    <div data-tour={COPY_TOUR_TARGETS.modalRiskRail}>
      <CopyAgentSummaryRail
        copySizePct={copySizePct}
        autonomyPreset={autonomyPreset}
        preview={preview}
        fleet={fleet}
        compact={isSheet && !sheetSummaryExpanded}
      />
    </div>
  );

  const formColumn = (
    <div className="agent-copy-form-column">
      <label className="terminal-label transfer-field-label">
              Cross margin only
      </label>
   
      <CopyAgentDestinationCards
        destinationMode={destinationMode}
        onSelect={setDestinationMode}
        hasExistingBuckets={crossBuckets.length > 0}
      />

      {destinationMode === "new" ? (
        <div className="transfer-field-group" data-tour={COPY_TOUR_TARGETS.modalCapital}>
          <div className="transfer-amount-header">
            <label className="terminal-label transfer-field-label">
              Starting margin
            </label>
            <div className="transfer-available-balance">
              <span className="terminal-label">Spot available</span>
              <span className="terminal-value">
                {formatCurrency(spotWalletBalance)}
              </span>
            </div>
          </div>
          <div className="transfer-amount-display">
            <span className="terminal-price transfer-amount-value">
              {formatCurrency(startingMargin)}
            </span>
          </div>
          <div className="transfer-amount-container">
            <FilledRangeSlider
              variant="info"
              min={COPY_AGENT_MIN_MARGIN}
              max={maxStartingMargin}
              step={10}
              value={Math.min(startingMargin, maxStartingMargin)}
              onChange={setStartingMargin}
              disabled={spotWalletBalance < COPY_AGENT_MIN_MARGIN}
            />
            <div className="transfer-amount-labels">
              <span className="terminal-value">
                {formatCurrency(COPY_AGENT_MIN_MARGIN)}
              </span>
              <span className="terminal-value">
                {formatCurrency(maxStartingMargin)}
              </span>
            </div>
          </div>
          {spotWalletBalance < COPY_AGENT_MIN_MARGIN ? (
            <p className="agent-copy-warning">
              Insufficient spot balance. Minimum{" "}
              {formatCurrency(COPY_AGENT_MIN_MARGIN)} required.
            </p>
          ) : null}
        </div>
      ) : (
        <div className="transfer-field-group">
          <label className="terminal-label transfer-field-label">Cross bucket</label>
          <select
            className="form-input transfer-select"
            value={existingBucketId}
            onChange={(event) => setExistingBucketId(event.target.value)}
          >
            {crossBuckets.length === 0 ? (
              <option value="">No cross buckets available</option>
            ) : (
              crossBuckets.map((bucket) => (
                <option key={bucket.bucketId} value={bucket.bucketId}>
                  {bucket.bucketId.slice(0, 10)}… (
                  {formatCurrency(bucket.totalEquity ?? 0)})
                </option>
              ))
            )}
          </select>
          {selectedBucket && Number(selectedBucket.totalEquity ?? 0) > 0 ? (
            <p className="agent-copy-bucket-warning">
              This bucket already has capital — copied trades share the same margin
              pool. Confirm applies your autonomy preset to the whole bucket.
            </p>
          ) : null}
        </div>
      )}

      <label className="agent-copy-field">
        <span>Mirror size (% of leader)</span>
        <FilledRangeSlider
          variant="info"
          min={COPY_AGENT_MIN_SIZE_PCT}
          max={COPY_AGENT_MAX_SIZE_PCT}
          step={5}
          value={copySizePct}
          onChange={setCopySizePct}
        />
        <strong>{copySizePct}%</strong>
      </label>

      <div data-tour={COPY_TOUR_TARGETS.modalAutonomy}>
        <CopyAgentAutonomyCards
          autonomyPreset={autonomyPreset}
          onSelect={setAutonomyPreset}
        />
      </div>

      {!walletConnected ? (
        <ConnectWalletPanel variant="inline" layout="inline" />
      ) : null}
    </div>
  );

  return (
    <>
      <CopyAgentLeaderHeader
        profile={profile}
        fleet={fleet}
        onClose={onClose}
        closeDisabled={isClosing}
      />

      <div className="modal-body agent-copy-modal-body">
        {layout === "md" ? (
          <CopyAgentMdSummaryCard
            open={mdSummaryOpen}
            onToggle={() => setMdSummaryOpen((value) => !value)}
            copySizePct={copySizePct}
            capitalAtRisk={preview.capitalAtRisk}
            autonomyPreset={autonomyPreset}
          >
            {summaryRail}
          </CopyAgentMdSummaryCard>
        ) : null}

        <div
          className={`agent-copy-modal-body-inner${
            layout === "lg" ? " agent-copy-modal-body--two-col" : ""
          }`}
        >
          {formColumn}
          {layout === "lg" ? summaryRail : null}
          {isSheet && sheetSummaryExpanded ? (
            <div className="agent-copy-sheet-expanded-rail">{summaryRail}</div>
          ) : null}
        </div>
      </div>

      {isSheet ? (
        <CopyAgentMiniSummary
          copySizePct={copySizePct}
          capitalAtRisk={preview.capitalAtRisk}
          autonomyPreset={autonomyPreset}
          expanded={sheetSummaryExpanded}
          onToggleExpand={() => setSheetSummaryExpanded((value) => !value)}
        />
      ) : null}

      <div className="modal-footer agent-copy-modal-footer">
        <label className="agent-copy-risk-ack">
          <input
            type="checkbox"
            checked={riskAcknowledged}
            onChange={(event) => setRiskAcknowledged(event.target.checked)}
            disabled={isClosing}
          />
          <span>
            I understood and reviewed the risk involved from copy trades.
          </span>
        </label>
        <div className="agent-copy-modal-footer-actions">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={onClose}
            disabled={isClosing}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-primary"
            data-tour={COPY_TOUR_TARGETS.modalConfirm}
            disabled={!canConfirm || isClosing}
            onClick={handleConfirm}
          >
            {isCopying ? "Copying…" : "Start copy (demo)"}
          </button>
        </div>
      </div>

      <CopyAgentHighAgencyConfirm
        isOpen={pendingHighAgencyConfirm}
        capitalAtRisk={preview.capitalAtRisk}
        onCancel={() => setPendingHighAgencyConfirm(false)}
        onConfirm={handleHighAgencyConfirm}
      />
      <CopyAgentExistingBucketConfirm
        isOpen={pendingExistingBucketConfirm}
        bucketLabel={existingBucketId.slice(0, 10) + "…"}
        bucketEquity={Number(selectedBucket?.totalEquity ?? 0)}
        autonomyPreset={autonomyPreset}
        onCancel={() => setPendingExistingBucketConfirm(false)}
        onConfirm={handleExistingBucketConfirm}
      />
    </>
  );
}

export default function CopyAgentModal({
  open,
  profile,
  fleet,
  walletConnected,
  isCopying,
  crossBuckets,
  spotWalletBalance,
  onClose,
  onConfirm,
}: CopyAgentModalProps): JSX.Element {
  return (
    <CopyAgentModalShell
      open={open}
      onClose={onClose}
      ariaLabel={`Copy ${profile.name}`}
      variant="setup"
    >
      <CopyAgentModalBody
        key={`${profile.id}-${spotWalletBalance}-${crossBuckets.map((b) => b.bucketId).join(",")}`}
        profile={profile}
        fleet={fleet}
        walletConnected={walletConnected}
        isCopying={isCopying}
        crossBuckets={crossBuckets}
        spotWalletBalance={spotWalletBalance}
        onClose={onClose}
        onConfirm={onConfirm}
      />
    </CopyAgentModalShell>
  );
}
