import {
  ADVANCED_ORDER_GROUPS,
  type AdvancedOrderTypeId,
} from "../../configs/advancedOrderTypes";
import React from "react";
export interface AdvancedOrderPanelProps {
  selected: AdvancedOrderTypeId | null;
  onSelect: (type: AdvancedOrderTypeId) => void;
}

export function AdvancedOrderPanel({
  selected,
  onSelect,
}: AdvancedOrderPanelProps): JSX.Element {
  return (
    <div className="trade-op-advanced-panel" role="listbox" aria-label="Advanced order types">
      {ADVANCED_ORDER_GROUPS.map((group) => (
        <div key={group.id} className="trade-op-advanced-group">
          <div className="terminal-label trade-op-advanced-group-label">
            {group.label}
          </div>
          <div className="trade-op-advanced-items">
            {group.items.map((item) => {
              const isActive = selected === item.id;
              return (
                <button
                  key={item.id}
                  type="button"
                  role="option"
                  aria-selected={isActive}
                  disabled={!item.enabled}
                  className={[
                    "trade-op-advanced-item",
                    isActive ? "active" : "",
                    !item.enabled ? "is-disabled" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                  onClick={() => item.enabled && onSelect(item.id)}
                  title={!item.enabled ? "Coming soon" : undefined}
                >
                  <span>{item.label}</span>
                  {!item.enabled ? (
                    <span className="trade-op-advanced-soon">Soon</span>
                  ) : null}
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}
