import React from "react";
import "./portfolio.css";

export interface PortfolioLedgerRowProps {
  label: string;
  value: string;
  valueClassName?: string;
}

function PortfolioLedgerRow({
  label,
  value,
  valueClassName,
}: PortfolioLedgerRowProps): JSX.Element {
  return (
    <div className="portfolio-ledger-row">
      <span className="portfolio-ledger-row-label">{label}</span>
      <span
        className={`portfolio-ledger-row-value${valueClassName ? ` ${valueClassName}` : ""}`}
      >
        {value}
      </span>
    </div>
  );
}

export default React.memo(PortfolioLedgerRow);
