import React, { type JSX } from "react";
import { createPortal } from "react-dom";
import { LAYOUT_LABELS, type LayoutStyle } from "../preference/settingsRegistry";
import {
  detectPlatform,
  formatKeyboardBinding,
  getDefaultBindingForAction,
  type KeyboardBinding,
  type ShortcutActionId,
} from "../../utils/keyboardShortcuts";
import {
  FADE_MS,
  type LayoutSwitchHint,
  type LayoutSwitchHintPhase,
} from "./useLayoutSwitchHint";
import "./layoutSwitchHintOverlay.css";

export interface LayoutSwitchHintOverlayProps {
  hint: LayoutSwitchHint | null;
  phase: LayoutSwitchHintPhase | null;
  binding: KeyboardBinding | null;
}

function BindingKeys({ binding }: { binding: KeyboardBinding }): JSX.Element {
  const platform = detectPlatform();
  const tokens = formatKeyboardBinding(binding, platform);

  return (
    <span className="layout-switch-hint-keys">
      {tokens.map((token, index) => (
        <React.Fragment key={`${token}-${index}`}>
          {index > 0 ? (
            <span className="layout-switch-hint-key-sep" aria-hidden>
              +
            </span>
          ) : null}
          <kbd className="layout-switch-hint-kbd">{token}</kbd>
        </React.Fragment>
      ))}
    </span>
  );
}

export function LayoutSwitchHintOverlay({
  hint,
  phase,
  binding,
}: LayoutSwitchHintOverlayProps): JSX.Element | null {
  if (!hint || !phase || !binding) return null;
  if (typeof document === "undefined") return null;

  const label = LAYOUT_LABELS[hint.layout as LayoutStyle] ?? hint.layout;
  const className = [
    "layout-switch-hint",
    phase === "fading" ? "layout-switch-hint--fading" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return createPortal(
    <div
      className={className}
      role="status"
      aria-live="polite"
      aria-atomic="true"
      aria-label={`Switched to ${label} layout`}
      style={{ "--layout-switch-hint-fade-ms": `${FADE_MS}ms` } as React.CSSProperties}
    >
      <div className="layout-switch-hint-panel">
        <p className="layout-switch-hint-label">{label}</p>
        <BindingKeys binding={binding} />
      </div>
    </div>,
    document.body,
  );
}

export function resolveLayoutShortcutBinding(
  actionId: ShortcutActionId,
  shortcuts: Record<ShortcutActionId, KeyboardBinding> | undefined,
): KeyboardBinding {
  return shortcuts?.[actionId] ?? getDefaultBindingForAction(actionId);
}
