import React, { useCallback, useEffect, useMemo, useState } from "react";
import { SubscriptionClient } from "../../sdk";
import { useSubscription } from "../../context/SubscriptionContext";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import { TAB_SECTION_BUBBLE_MAP } from "../../tutorials/bubble-tip";
import TradeHistory from "./TradeHistory";
import BucketPositions from "./Position";
import BucketCollections from "./BucketCollection";
import OrderHistory from "./OrderHistory";
import FundingHistory from "./FundingHistory";
import OpenOrders from "./OpenOrders";
import AgentTasks from "./AgentTasks";
import MemoryAuditPanel from "../portfolio/MemoryAuditPanel";
import SafetyAuditLogPanel from "../tradeagent/SafetyAuditLogPanel";
import { TabHeaderActionsMenu } from "./TabHeaderActionsMenu";
import RawProDataToggle from "./RawProDataToggle";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import TokenTakerActivityTab from "../agent/TokenTakerActivityTab";
import type { ChartTradeFocusRequest } from "../finchartview/chartMarkers";
import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import type { TradingMode } from "../../configs/tradeLayoutMode";
import {
  POSITION_VIEW_MODE_ALL,
  POSITION_VIEW_MODE_BY_BUCKET,
  PositionViewMode,
} from "../../constants";
import { ConnectWalletPanel } from "../wallet";
import {
  isWalletConnected,
  tabRequiresWallet,
} from "../../utils/walletConnection";
import "../smartlayout/layout.css";
import "./TabSection.css";

export type TabSectionTabId =
  | "agentTasks"
  | "buckets"
  | "positions"
  | "openOrders"
  | "tradeHistory"
  | "tokenTakers"
  | "history"
  | "fundingHistory"
  | "memoryAudit";

export interface TabSectionProps {
  baseURL: string;
  /** Optional: when inside SubscriptionProvider, children use context. */
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress: string;
  mnemonic?: string;
  height?: string;
  refreshInterval?: number;
  /** Passed to Positions and used when view is "by bucket". */
  selectedBucketId?: string | null;
  /** Called when a bucket is selected in Bucket Collections (e.g. to sync with Positions). */
  onBucketSelect?: (bucketId: string, totalEquity: number) => void;
  /** Called when Transfer button is clicked in Bucket Collections (opens transfer modal at page level). */
  onRequestOpenTransferModal?: (anchor?: HTMLElement) => void;
  /** Called when Send to Address button is clicked (opens wallet transfer modal). */
  onRequestOpenWalletTransferModal?: () => void;
  /** Opens cross-chain deposit when spot balance is empty. */
  onRequestFundAccount?: () => void;
  /** Starts guided deposit tour from buckets empty state. */
  onRequestDepositTour?: () => void;
  /** Optional controlled active tab; when provided with onTabChange, uses controlled mode */
  activeTab?: TabSectionTabId;
  /** Called when tab changes; use with activeTab for controlled mode */
  onTabChange?: (tabId: TabSectionTabId) => void;
  /** When true, header actions open in a bottom sheet instead of a dropdown */
  isMobile?: boolean;
  /** Current grid breakpoint from GridViewerLayout (e.g. lg, md, sm) */
  layoutBreakpoint?: string;
  /** Switch chart to the task's market */
  onRequestViewOnChart?: (marketId: string) => void;
  /** Switch chart to a trade fill and scroll to its execution marker */
  onRequestViewTradeOnChart?: (req: Omit<ChartTradeFocusRequest, "requestId">) => void;
  /** Re-open NL intent in trade panel for editing */
  onRequestEditAgentTask?: (taskId: string, description: string) => void;
  /** Desktop: show expand chevron on Agent Tasks tab */
  showAgentConsoleTrigger?: boolean;
  agentConsoleOpen?: boolean;
  onRequestExpandAgentConsole?: () => void;
  /** Default tab when uncontrolled */
  defaultTab?: TabSectionTabId;
  /** Override tab order (portfolio page uses agent-first ordering) */
  tabOrder?: TabSectionTabId[];
  /** When set, agent-scoped tables filter to these agents (empty = all). */
  filterAgentIds?: string[];
  /** Agent layout modes: show Raw Pro Data toggle in tab header */
  showRawProDataToggle?: boolean;
  /** Controlled Raw Pro Data mode */
  rawProDataActive?: boolean;
  onRawProDataChange?: (active: boolean) => void;
  /** Tab order when raw pro data is active */
  rawProDataTabOrder?: TabSectionTabId[];
  /** Agent layout mode for HIL-specific tab labels and panels */
  tradingMode?: TradingMode;
  /** When false, HIL uses legacy MemoryAuditPanel */
  hilPolishActive?: boolean;
  /** When set, show Token takers tab for this agent-token market catalog id */
  agentTokenCatalogId?: string | null;
  /** Switch chart to a token taker fill and scroll to its marker */
  onRequestViewTakerOnChart?: (event: AgentTokenTakerTradeEvent) => void;
  activeTakerEventId?: string | null;
}

const TAB_LABELS: Record<TabSectionTabId, string> = {
  agentTasks: "Agents & Intents",
  buckets: "Buckets",
  positions: "Positions",
  openOrders: "Open Orders",
  tradeHistory: "Trade History",
  tokenTakers: "Token takers",
  history: "Order History",
  fundingHistory: "Funding History",
  memoryAudit: "Memory & Audit",
};

const TAB_LABELS_MOBILE: Record<TabSectionTabId, string> = {
  agentTasks: "Intents",
  buckets: "Buckets",
  positions: "Positions",
  openOrders: "Orders",
  tradeHistory: "Trades",
  tokenTakers: "Takers",
  history: "History",
  fundingHistory: "Funding",
  memoryAudit: "Audit",
};

function TabSection({
  baseURL,
  subscriptionClient: subscriptionClientProp,
  authToken,
  walletAddress,
  mnemonic,
  height = "400px",
  refreshInterval,
  selectedBucketId = null,
  onBucketSelect,
  onRequestOpenTransferModal,
  onRequestOpenWalletTransferModal,
  onRequestFundAccount,
  onRequestDepositTour,
  activeTab: controlledTab,
  onTabChange,
  isMobile = false,
  layoutBreakpoint = "lg",
  onRequestViewOnChart,
  onRequestViewTradeOnChart,
  onRequestEditAgentTask,
  showAgentConsoleTrigger = false,
  agentConsoleOpen = false,
  onRequestExpandAgentConsole,
  defaultTab = "buckets",
  tabOrder,
  filterAgentIds = [],
  showRawProDataToggle = false,
  rawProDataActive: controlledRawPro,
  onRawProDataChange,
  rawProDataTabOrder,
  tradingMode = "proTerminal",
  hilPolishActive = true,
  agentTokenCatalogId = null,
  onRequestViewTakerOnChart,
  activeTakerEventId = null,
}: TabSectionProps): JSX.Element {
  const { client: contextClient } = useSubscription();
  const subscriptionClient = subscriptionClientProp ?? contextClient;
  const { activeCount, hasUnreadUpdates, markAllSeen } = useAgentTasks();

  const [internalTab, setInternalTab] = useState<TabSectionTabId>(defaultTab);
  const [internalRawPro, setInternalRawPro] = useState(false);
  const isControlled = controlledTab != null && onTabChange != null;
  const activeTab = isControlled ? controlledTab : internalTab;
  const setActiveTab = isControlled ? onTabChange : setInternalTab;
  const rawProDataActive =
    controlledRawPro != null && onRawProDataChange != null
      ? controlledRawPro
      : internalRawPro;
  const setRawProDataActive =
    onRawProDataChange != null ? onRawProDataChange : setInternalRawPro;

  const handleRawProDataChange = useCallback(
    (next: boolean) => {
      setRawProDataActive(next);
      if (next) {
        setActiveTab("openOrders");
      } else if (tradingMode === "humanInLoop") {
        setActiveTab("memoryAudit");
      } else {
        setActiveTab("agentTasks");
      }
    },
    [setRawProDataActive, setActiveTab, tradingMode],
  );

  const [headerActions, setHeaderActions] = useState<React.ReactNode>(null);
  const [positionViewMode, setPositionViewMode] =
    useState<PositionViewMode>(POSITION_VIEW_MODE_ALL);

  const handleRequestViewPositions = (
    bucketId: string,
    totalEquity: number,
  ) => {
    onBucketSelect?.(bucketId, totalEquity);
    setPositionViewMode(POSITION_VIEW_MODE_BY_BUCKET);
    setActiveTab("positions");
  };

  const tabs = useMemo(() => {
    const baseLabels = isMobile ? TAB_LABELS_MOBILE : TAB_LABELS;
    const labels =
      tradingMode === "humanInLoop" && hilPolishActive
        ? {
            ...baseLabels,
            memoryAudit: isMobile ? "Safety" : "Safety Log",
          }
        : baseLabels;
    let effectiveOrder =
      rawProDataActive && rawProDataTabOrder
        ? rawProDataTabOrder
        : tabOrder ?? (Object.keys(labels) as TabSectionTabId[]);

    if (agentTokenCatalogId) {
      if (!effectiveOrder.includes("tokenTakers")) {
        const tradeIdx = effectiveOrder.indexOf("tradeHistory");
        effectiveOrder =
          tradeIdx >= 0
            ? [
                ...effectiveOrder.slice(0, tradeIdx + 1),
                "tokenTakers",
                ...effectiveOrder.slice(tradeIdx + 1),
              ]
            : [...effectiveOrder, "tokenTakers"];
      }
    } else {
      effectiveOrder = effectiveOrder.filter((id) => id !== "tokenTakers");
    }

    return effectiveOrder.map((id) => ({
      id,
      label: labels[id],
      bubbleTipId: TAB_SECTION_BUBBLE_MAP[id],
      ...(id === "agentTasks"
        ? {
            badgeCount: activeCount,
            badgePulse: hasUnreadUpdates,
          }
        : {}),
    }));
  }, [
    activeCount,
    hasUnreadUpdates,
    isMobile,
    tabOrder,
    rawProDataActive,
    rawProDataTabOrder,
    tradingMode,
    hilPolishActive,
    agentTokenCatalogId,
  ]);

  useEffect(() => {
    if (activeTab === "tokenTakers" && !agentTokenCatalogId) {
      setActiveTab(defaultTab);
    }
  }, [activeTab, agentTokenCatalogId, defaultTab, setActiveTab]);

  useEffect(() => {
    setHeaderActions(null);
  }, [activeTab]);

  useEffect(() => {
    if (activeTab === "agentTasks") {
      markAllSeen();
    }
  }, [activeTab, markAllSeen]);

  const showWalletGate =
    tabRequiresWallet(activeTab) && !isWalletConnected(walletAddress);

  return (
    <div
      className={`layout-container tab-section-root${isMobile ? " tab-section-root--mobile" : ""}`}
      style={{ height }}
      data-tour="welcome-portfolio-tabs"
    >
      <TabLayoutHeaderToolBar
        tabs={tabs}
        activeTabId={activeTab}
        onTabChange={(id) => setActiveTab(id as TabSectionTabId)}
        scrollActiveTabIntoView={isMobile}
      >
        {showRawProDataToggle ? (
          <RawProDataToggle
            active={rawProDataActive}
            onChange={handleRawProDataChange}
            tradingMode={tradingMode}
          />
        ) : null}
        <div
          className={`tab-header-actions-menu-slot${
            showRawProDataToggle ? " tab-header-actions-menu-slot--with-toggle" : ""
          }${
            headerActions != null && headerActions !== false
              ? " is-visible"
              : ""
          }`}
        >
          <TabHeaderActionsMenu isMobile={isMobile} activeTabId={activeTab}>
            {headerActions}
          </TabHeaderActionsMenu>
        </div>
      </TabLayoutHeaderToolBar>
      <div className="tab-section-content">
        {showWalletGate ? (
          <ConnectWalletPanel variant="portfolio" height="100%" align="top" />
        ) : (
          <>
        {activeTab === "agentTasks" && (
          <div data-tour="welcome-agent-layer">
            <AgentTasks
            baseURL={baseURL}
            authToken={authToken}
            height="100%"
            selectedBucketId={selectedBucketId}
            hide_header
            isMobile={isMobile}
            layoutBreakpoint={layoutBreakpoint}
            onRequestHeaderActions={setHeaderActions}
            onRequestViewOnChart={onRequestViewOnChart}
            onRequestEditAgentTask={onRequestEditAgentTask}
            showAgentConsoleTrigger={showAgentConsoleTrigger && !isMobile}
            agentConsoleOpen={agentConsoleOpen}
            onRequestExpandAgentConsole={onRequestExpandAgentConsole}
            filterAgentIds={filterAgentIds}
            walletAddress={walletAddress}
            tradingMode={tradingMode}
          />
          </div>
        )}
        {activeTab === "memoryAudit" &&
        tradingMode === "humanInLoop" &&
        hilPolishActive ? (
          <SafetyAuditLogPanel
            height="100%"
            filterAgentIds={filterAgentIds}
            isMobile={isMobile}
            layoutBreakpoint={layoutBreakpoint}
            baseURL={baseURL}
            onRequestViewOnChart={onRequestViewOnChart}
          />
        ) : activeTab === "memoryAudit" ? (
          <MemoryAuditPanel
            height="100%"
            filterAgentIds={filterAgentIds}
          />
        ) : null}
        {activeTab === "tradeHistory" && (
          <TradeHistory
            baseURL={baseURL}
            authToken={authToken}
            walletAddress={walletAddress}
            height="100%"
            refreshInterval={refreshInterval}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            onRequestViewTradeOnChart={onRequestViewTradeOnChart}
            filterAgentIds={filterAgentIds}
          />
        )}
        {activeTab === "tokenTakers" && agentTokenCatalogId ? (
          <TokenTakerActivityTab
            marketCatalogAgentId={agentTokenCatalogId}
            height="100%"
            onViewEventOnChart={onRequestViewTakerOnChart}
            activeEventId={activeTakerEventId}
          />
        ) : null}
        {activeTab === "history" && (
          <OrderHistory
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            authToken={authToken}
            walletAddress={walletAddress}
            height="100%"
            refreshInterval={refreshInterval}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            filterAgentIds={filterAgentIds}
          />
        )}
        {activeTab === "fundingHistory" && (
          <FundingHistory
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            authToken={authToken}
            walletAddress={walletAddress}
            height="100%"
            refreshInterval={refreshInterval}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            filterAgentIds={filterAgentIds}
          />
        )}
        {activeTab === "openOrders" && (
          <OpenOrders
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            authToken={authToken}
            walletAddress={walletAddress}
            mnemonic={mnemonic}
            height="100%"
            refreshInterval={refreshInterval}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            onRequestViewOnChart={onRequestViewOnChart}
            filterAgentIds={filterAgentIds}
          />
        )}
        {activeTab === "positions" && (
          <BucketPositions
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            authToken={authToken}
            walletAddress={walletAddress}
            mnemonic={mnemonic}
            height="100%"
            refreshInterval={refreshInterval}
            selectedBucketId={selectedBucketId}
            viewMode={positionViewMode}
            onViewModeChange={setPositionViewMode}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            filterAgentIds={filterAgentIds}
          />
        )}
        {activeTab === "buckets" && (
          <BucketCollections
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            walletAddress={walletAddress}
            mnemonic={mnemonic ?? ""}
            authToken={authToken}
            height="100%"
            refreshInterval={refreshInterval}
            onBucketSelect={onBucketSelect}
            onRequestOpenTransferModal={onRequestOpenTransferModal}
            onRequestOpenWalletTransferModal={onRequestOpenWalletTransferModal}
            onRequestFundAccount={onRequestFundAccount}
            onRequestDepositTour={onRequestDepositTour}
            onRequestViewPositions={handleRequestViewPositions}
            hide_header
            onRequestHeaderActions={setHeaderActions}
            filterAgentIds={filterAgentIds}
            isMobile={isMobile}
            layoutBreakpoint={layoutBreakpoint}
          />
        )}
          </>
        )}
      </div>
    </div>
  );
}

export default React.memo(TabSection);
