import React, { useCallback, useMemo, useState } from "react";

import type { CopyRelation } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import { formatCurrency } from "../../sdk/utils/display";
import CopyAgentModalShell from "../agent/CopyAgentModalShell";
import { useOverlayContentLatch } from "../tables/useBucketModalOverlay";
import "../agent/agent.css";

export interface StopCopyWizardModalProps {
  open: boolean;
  relation: CopyRelation | null;
  profile: PropertyProfile | null;
  isPending: boolean;
  onClose: () => void;
  onConfirm: () => void | Promise<void>;
}

type WizardStep = "explain" | "confirm" | "done";

type StopCopyLatch = {
  relation: CopyRelation;
  profile: PropertyProfile;
};

export default function StopCopyWizardModal({
  open,
  relation,
  profile,
  isPending,
  onClose,
  onConfirm,
}: StopCopyWizardModalProps): JSX.Element {
  const [step, setStep] = useState<WizardStep>("explain");

  const latchValue = useMemo((): StopCopyLatch | null => {
    if (!relation || !profile) return null;
    return { relation, profile };
  }, [relation, profile]);

  const { latched, clearLatch } = useOverlayContentLatch(open, latchValue);

  const handleAfterUnmount = useCallback(() => {
    clearLatch();
    setStep("explain");
  }, [clearLatch]);

  const handleClose = () => {
    onClose();
  };

  const handleConfirm = async () => {
    await onConfirm();
    setStep("done");
  };

  const isDedicated =
    latched?.relation.copySettings.bucketMode === "new";
  const capital =
    latched?.relation.copySettings.bucketMode === "new"
      ? latched.relation.copySettings.startingMargin ?? 0
      : 0;

  return (
    <CopyAgentModalShell
      open={open}
      onClose={handleClose}
      onAfterUnmount={handleAfterUnmount}
      ariaLabel={
        latched ? `Stop mirroring ${latched.profile.name}` : "Stop mirroring"
      }
      variant="status"
    >
      {latched ? (
        <>
          <div className="modal-header">
            <h3 className="terminal-panel-title">
              Stop mirroring {latched.profile.name}
            </h3>
          </div>
          <div className="modal-body copied-agent-status-body">
            {step === "explain" ? (
              <>
                <p className="agent-copy-modal-sub">
                  Stopping removes this mirror from your portfolio
                  {isDedicated
                    ? " and clears autonomy policy on your dedicated copy bucket (demo)."
                    : ". Your shared bucket keeps its policy and any open positions."}
                </p>
                <ul className="agent-copy-stop-list">
                  <li>Mirror relation will be removed locally.</li>
                  {isDedicated ? (
                    <li>
                      Bucket policy reset so silent High-Agency cannot linger on
                      reuse.
                    </li>
                  ) : (
                    <li>
                      Shared bucket policy is unchanged — other agents may still
                      use it.
                    </li>
                  )}
                  <li>Full position teardown is deferred — demo scope only.</li>
                </ul>
              </>
            ) : null}
            {step === "confirm" ? (
              <>
                <p className="agent-copy-modal-sub">
                  Confirm stop for {latched.profile.name} at{" "}
                  {latched.relation.copySettings.copySizePct}% mirror
                  {isDedicated && capital > 0
                    ? ` · ${formatCurrency(capital)} allocated`
                    : ""}
                  .
                </p>
              </>
            ) : null}
            {step === "done" ? (
              <p className="agent-copy-modal-sub">
                Mirror stopped. Check your portfolio — this agent no longer
                appears under Mirrored agents.
              </p>
            ) : null}
          </div>
          <div className="modal-footer agent-copy-modal-footer">
            {step === "done" ? (
              <div className="agent-copy-modal-footer-actions">
                <button
                  type="button"
                  className="agent-secondary-btn agent-secondary-btn--primary"
                  onClick={handleClose}
                >
                  Done
                </button>
              </div>
            ) : (
              <div className="agent-copy-modal-footer-actions">
                <button
                  type="button"
                  className="agent-secondary-btn"
                  onClick={handleClose}
                >
                  Cancel
                </button>
                {step === "explain" ? (
                  <button
                    type="button"
                    className="agent-secondary-btn agent-secondary-btn--primary"
                    onClick={() => setStep("confirm")}
                  >
                    Continue
                  </button>
                ) : (
                  <button
                    type="button"
                    className="agent-secondary-btn agent-secondary-btn--primary"
                    disabled={isPending}
                    onClick={() => void handleConfirm()}
                  >
                    {isPending ? "Stopping…" : "Stop mirroring"}
                  </button>
                )}
              </div>
            )}
          </div>
        </>
      ) : null}
    </CopyAgentModalShell>
  );
}
