export type MentionKind = "agent" | "ticker";

export interface MentionTrigger {
  kind: MentionKind;
  query: string;
  range: [number, number];
}

/** Active `@` or `$` mention token at caret (not money literals like `$100`). */
export function getMentionTrigger(
  text: string,
  caret: number,
): MentionTrigger | null {
  const before = text.slice(0, caret);

  const agentMatch = before.match(/@([a-zA-Z0-9_-]*)$/);
  if (agentMatch) {
    const token = agentMatch[0] ?? "@";
    return {
      kind: "agent",
      query: agentMatch[1] ?? "",
      range: [caret - token.length, caret],
    };
  }

  const tickerMatch = before.match(/\$([A-Za-z][A-Za-z0-9]*)$/);
  if (tickerMatch) {
    const token = tickerMatch[0] ?? "$";
    return {
      kind: "ticker",
      query: tickerMatch[1] ?? "",
      range: [caret - token.length, caret],
    };
  }

  return null;
}

export function replaceMentionAtCaret(
  text: string,
  caret: number,
  replacement: string,
): { nextText: string; nextCaret: number } {
  const trigger = getMentionTrigger(text, caret);
  if (!trigger) {
    const before = text.slice(0, caret);
    const after = text.slice(caret);
    const prefix = before.length > 0 && !/\s$/.test(before) ? " " : "";
    const nextText = `${before}${prefix}${replacement}${after}`;
    const nextCaret = before.length + prefix.length + replacement.length;
    return { nextText, nextCaret };
  }

  const [start, end] = trigger.range;
  const needsSpace =
    replacement.length > 0 && end < text.length && !/\s/.test(text[end] ?? "");
  const suffix = needsSpace ? " " : "";
  const nextText =
    text.slice(0, start) + replacement + suffix + text.slice(end);
  const nextCaret = start + replacement.length + suffix.length;
  return { nextText, nextCaret };
}

const AGENT_MENTION_RE = /@([a-zA-Z0-9_-]+)/g;
const TICKER_MENTION_RE = /\$([A-Za-z][A-Za-z0-9]*)/g;

export function extractAgentMentions(text: string): string[] {
  const matches = [...text.matchAll(AGENT_MENTION_RE)];
  return [...new Set(matches.map((m) => m[1] ?? "").filter(Boolean))];
}

export function extractTickerMentions(text: string): string[] {
  const matches = [...text.matchAll(TICKER_MENTION_RE)];
  return [...new Set(matches.map((m) => m[1] ?? "").filter(Boolean))];
}
