import type { JSX } from "react";

export interface IntentParkedBannerProps {
  reason?: string;
  onOpenManual?: () => void;
}

export function IntentParkedBanner({
  reason,
  onOpenManual,
}: IntentParkedBannerProps): JSX.Element {
  return (
    <div className="intent-parked-banner" role="status">
      <span className="intent-parked-icon" aria-hidden>
        ⚠
      </span>
      <div className="intent-parked-body">
        <p className="intent-parked-title">Strategy not supported via intent deploy</p>
        <p className="intent-parked-reason">
          {reason ??
            "This objective is outside the intent composer scope. Use the Manual order form instead."}
        </p>
        {onOpenManual ? (
          <button type="button" className="intent-parked-link" onClick={onOpenManual}>
            Use Manual order form →
          </button>
        ) : null}
      </div>
    </div>
  );
}
