import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";

import { getFleetAgentByCatalogId, mockAgentProfiles } from "../../../offline/mock_data";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import { buildComparePerformanceMetrics } from "./agentFocusMetrics";
import "../smartlayout/layout.css";
import "./agent.css";

const ANCHOR_GAP_PX = 6;
const BOTTOM_INSET_PX = 0;
const PANEL_MAX_WIDTH_PX = 56 * 16;
const PANEL_HORIZONTAL_INSET_PX = 32;

type AnchoredPanelStyle = {
  top: number;
  left: number;
  width: number;
  maxHeight: number;
};

export interface AgentCompareSelectorProps {
  isOpen: boolean;
  onClose: () => void;
  compareIds: string[];
  onSelect: (id: string) => void;
  closeOnSelect?: boolean;
  anchorRef?: React.RefObject<HTMLElement | null>;
}

function filterAgentCatalog(search: string): PropertyProfile[] {
  const query = search.trim().toLowerCase();
  if (!query) return mockAgentProfiles;

  return mockAgentProfiles.filter((entry) => {
    const haystack = `${entry.name} ${entry.ticker} ${entry.strategy}`.toLowerCase();
    return haystack.includes(query);
  });
}

function sortAgentsForCompare(
  agents: PropertyProfile[],
  compareIds: string[],
): PropertyProfile[] {
  const selected = new Set(compareIds);
  return [...agents].sort((left, right) => {
    const leftSelected = selected.has(left.id);
    const rightSelected = selected.has(right.id);
    if (leftSelected === rightSelected) return 0;
    return leftSelected ? 1 : -1;
  });
}

function AgentDetailPane({ profile }: { profile: PropertyProfile }): JSX.Element {
  const fleet = getFleetAgentByCatalogId(profile.id);
  const metrics = buildComparePerformanceMetrics(profile).slice(0, 3);
  const avatarSrc = resolveAgentAvatarSvgUrl(profile.id);
  const changeTone = profile.change24h >= 0 ? "positive" : "negative";
  const changeLabel = `${profile.change24h >= 0 ? "+" : ""}${profile.change24h.toFixed(1)}%`;

  return (
    <div className="agent-compare-selector-detail-pane">
      <div className="agent-compare-selector-detail-header">
        <span className="agent-compare-selector-detail-avatar" aria-hidden>
          <span
            className="agent-compare-selector-detail-avatar-image"
            style={{
              maskImage: `url(${avatarSrc})`,
              WebkitMaskImage: `url(${avatarSrc})`,
            }}
          />
        </span>
        <div className="agent-compare-selector-detail-heading">
          <h3 className="agent-compare-selector-detail-title">{profile.name}</h3>
          <p className="agent-compare-selector-detail-meta">
            <span className="agent-ticker">{profile.ticker}</span>
            <span className={`agent-compare-selector-detail-change ${changeTone}`}>
              {changeLabel}
            </span>
          </p>
        </div>
      </div>

      <p className="agent-compare-selector-detail-strategy">{profile.strategy}</p>

      {profile.description ? (
        <p className="agent-compare-selector-detail-description">{profile.description}</p>
      ) : null}

      <dl className="agent-compare-selector-detail-metrics">
        {metrics.map((metric) => (
          <div key={metric.label} className="agent-compare-selector-detail-metric">
            <dt className="terminal-label">{metric.label}</dt>
            <dd
              className={[
                "terminal-value",
                metric.tone === "positive" ? "positive" : "",
                metric.tone === "negative" ? "negative" : "",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              {metric.value}
            </dd>
          </div>
        ))}
        {fleet ? (
          <div className="agent-compare-selector-detail-metric">
            <dt className="terminal-label">Win rate</dt>
            <dd className="terminal-value">{fleet.winRatePct.toFixed(0)}%</dd>
          </div>
        ) : null}
      </dl>
    </div>
  );
}

function AgentCompareSelector({
  isOpen,
  onClose,
  compareIds,
  onSelect,
  closeOnSelect = true,
  anchorRef,
}: AgentCompareSelectorProps): JSX.Element | null {
  const [search, setSearch] = useState("");
  const [highlightedIndex, setHighlightedIndex] = useState(0);
  const [anchoredPanelStyle, setAnchoredPanelStyle] = useState<AnchoredPanelStyle | null>(
    null,
  );
  const searchInputRef = useRef<HTMLInputElement>(null);

  const resetOverlayState = useCallback(() => {
    setAnchoredPanelStyle(null);
    setSearch("");
  }, []);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen, { onAfterUnmount: resetOverlayState });

  useOverlayEscapeKey(isOpen, onClose);

  const updateAnchoredPosition = useCallback(() => {
    const anchorEl = anchorRef?.current;
    if (!anchorEl) {
      setAnchoredPanelStyle(null);
      return;
    }

    const rect = anchorEl.getBoundingClientRect();
    const top = rect.bottom + ANCHOR_GAP_PX;
    const width = Math.min(
      PANEL_MAX_WIDTH_PX,
      window.innerWidth - PANEL_HORIZONTAL_INSET_PX,
    );
    const left = (window.innerWidth - width) / 2;
    const maxHeight = Math.max(200, window.innerHeight - top - BOTTOM_INSET_PX);

    setAnchoredPanelStyle({ top, left, width, maxHeight });
  }, [anchorRef]);

  useEffect(() => {
    if (!isOpen) return;

    if (!anchorRef) {
      setAnchoredPanelStyle(null);
      return;
    }

    const measure = () => updateAnchoredPosition();
    measure();
    const frame = window.requestAnimationFrame(measure);

    window.addEventListener("resize", measure);
    window.addEventListener("scroll", measure, true);

    const anchorEl = anchorRef.current;
    const resizeObserver =
      anchorEl && typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(measure)
        : null;
    if (resizeObserver && anchorEl) {
      resizeObserver.observe(anchorEl);
    }

    return () => {
      window.cancelAnimationFrame(frame);
      window.removeEventListener("resize", measure);
      window.removeEventListener("scroll", measure, true);
      resizeObserver?.disconnect();
    };
  }, [isOpen, anchorRef, updateAnchoredPosition]);

  const filteredAgents = useMemo(() => {
    const filtered = filterAgentCatalog(search);
    return sortAgentsForCompare(filtered, compareIds);
  }, [compareIds, search]);

  const detailProfile = filteredAgents[highlightedIndex] ?? filteredAgents[0];

  useEffect(() => {
    if (!isOpen) return;

    setHighlightedIndex(0);

    const frame = window.requestAnimationFrame(() => {
      searchInputRef.current?.focus();
    });
    return () => window.cancelAnimationFrame(frame);
  }, [isOpen]);

  useEffect(() => {
    if (highlightedIndex >= filteredAgents.length) {
      setHighlightedIndex(Math.max(0, filteredAgents.length - 1));
    }
  }, [filteredAgents.length, highlightedIndex]);

  const selectAgent = useCallback(
    (profile: PropertyProfile) => {
      onSelect(profile.id);
      if (closeOnSelect) {
        onClose();
      }
    },
    [closeOnSelect, onClose, onSelect],
  );

  const handleListKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (filteredAgents.length === 0) return;

    if (event.key === "ArrowDown") {
      event.preventDefault();
      setHighlightedIndex((current) =>
        Math.min(current + 1, filteredAgents.length - 1),
      );
      return;
    }

    if (event.key === "ArrowUp") {
      event.preventDefault();
      setHighlightedIndex((current) => Math.max(current - 1, 0));
      return;
    }

    if (event.key === "Enter") {
      event.preventDefault();
      const profile = filteredAgents[highlightedIndex];
      if (profile) {
        selectAgent(profile);
      }
    }
  };

  if (!mounted) return null;

  const isAnchored = anchoredPanelStyle !== null;

  const overlayClassName = [
    "agent-compare-selector-overlay",
    isAnchored ? "agent-compare-selector-overlay--anchored" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const panelClassName = [
    "agent-compare-selector-panel",
    "staggered-overlay-panel--scale",
    "terminal-overlay-panel-shell",
    isAnchored ? "agent-compare-selector-panel--anchored" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const panelStyle = isAnchored
    ? ({
        top: anchoredPanelStyle.top,
        left: anchoredPanelStyle.left,
        width: anchoredPanelStyle.width,
        height: anchoredPanelStyle.maxHeight,
        maxHeight: anchoredPanelStyle.maxHeight,
        transformOrigin: "top center",
      } as React.CSSProperties)
    : undefined;

  const modalContent = (
    <StaggeredOverlayRoot className={overlayClassName}>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={panelClassName}
        style={panelStyle}
        aria-label="Agent compare selector"
      >
        <div className="agent-compare-selector-toolbar">
          <div className="terminal-search-field agent-compare-selector-search">
            <span className="agent-compare-selector-search-icon" aria-hidden>
              ⌕
            </span>
            <input
              ref={searchInputRef}
              type="search"
              className="terminal-search-input"
              placeholder="Search agents"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              aria-label="Search agents"
            />
          </div>
          <span className="agent-compare-selector-count terminal-label">
            {filteredAgents.length} agent{filteredAgents.length === 1 ? "" : "s"}
          </span>
        </div>

        <div className="agent-compare-selector-body">
          <div
            className="agent-compare-selector-list-pane"
            role="listbox"
            aria-label="Catalog agents"
            aria-activedescendant={
              filteredAgents[highlightedIndex]
                ? `agent-compare-option-${filteredAgents[highlightedIndex].id}`
                : undefined
            }
            tabIndex={0}
            onKeyDown={handleListKeyDown}
          >
            <p className="terminal-label agent-compare-selector-group-label">
              Demo agents
            </p>

            {filteredAgents.length === 0 ? (
              <p className="agent-compare-selector-empty">No agents match your search.</p>
            ) : (
              filteredAgents.map((profile, index) => {
                const isSelected = compareIds.includes(profile.id);
                const isHighlighted = index === highlightedIndex;
                const avatarSrc = resolveAgentAvatarSvgUrl(profile.id);
                const changeTone = profile.change24h >= 0 ? "positive" : "negative";
                const changeLabel = `${profile.change24h >= 0 ? "+" : ""}${profile.change24h.toFixed(1)}%`;

                return (
                  <button
                    key={profile.id}
                    id={`agent-compare-option-${profile.id}`}
                    type="button"
                    role="option"
                    aria-selected={isSelected}
                    className={[
                      "agent-compare-selector-row",
                      isSelected ? "agent-compare-selector-row--active" : "",
                      isHighlighted ? "agent-compare-selector-row--highlighted" : "",
                    ]
                      .filter(Boolean)
                      .join(" ")}
                    onMouseEnter={() => setHighlightedIndex(index)}
                    onClick={() => selectAgent(profile)}
                  >
                    <span className="agent-compare-selector-row-avatar" aria-hidden>
                      <span
                        className="agent-compare-selector-row-avatar-image"
                        style={{
                          maskImage: `url(${avatarSrc})`,
                          WebkitMaskImage: `url(${avatarSrc})`,
                        }}
                      />
                    </span>
                    <span className="agent-compare-selector-row-body">
                      <span className="agent-compare-selector-row-label">
                        {profile.name}
                      </span>
                      <span className="agent-compare-selector-row-meta">
                        <span className="agent-ticker">{profile.ticker}</span>
                        <span className={`agent-compare-selector-row-change ${changeTone}`}>
                          {changeLabel}
                        </span>
                      </span>
                    </span>
                  </button>
                );
              })
            )}
          </div>

          {detailProfile ? <AgentDetailPane profile={detailProfile} /> : null}
        </div>

        <div className="agent-compare-selector-footer">
          <button type="button" className="agent-secondary-btn" onClick={onClose}>
            Close
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default AgentCompareSelector;
