import type { Market } from "../../store/types";
import type { AgentTokenPriceHistoryManifestAgent } from "../../../offline/mock_data/agentTokenPriceHistory.types";
import {
  agentTokenMarketId,
  stripAgentTicker,
} from "../sdk/api/agentTokenPrice/agentTokenPriceClient";

export function buildVirtualAgentTokenMarket(
  agent: AgentTokenPriceHistoryManifestAgent,
): Market {
  const baseAsset = stripAgentTicker(agent.ticker);
  const pair = `${baseAsset}-USDT`;
  return {
    marketIndex: agentTokenMarketId(agent.catalogAgentId),
    index: agentTokenMarketId(agent.catalogAgentId),
    symbol: pair,
    moniker: pair,
    baseAsset,
    quoteAsset: "USDT",
    status: "MARKET_STATUS_ACTIVE",
    active: true,
    maxSizeLimit: 500,
    minSizeLimit: 0.01,
  };
}

export function isVirtualAgentTokenMarket(market: Pick<Market, "marketIndex">): boolean {
  return market.marketIndex.startsWith("agent-token:");
}

export function manifestAgentsMissingFromMarkets(
  agents: AgentTokenPriceHistoryManifestAgent[],
  markets: Market[],
): AgentTokenPriceHistoryManifestAgent[] {
  const coveredCatalogIds = new Set<string>();
  const coveredBaseAssets = new Set<string>();

  for (const market of markets) {
    if (market.marketIndex.startsWith("agent-token:")) {
      coveredCatalogIds.add(market.marketIndex.slice("agent-token:".length).toLowerCase());
    }
    if (market.baseAsset) {
      coveredBaseAssets.add(market.baseAsset.toUpperCase());
    }
  }

  return agents.filter((agent) => {
    const catalogId = agent.catalogAgentId.toLowerCase();
    const baseAsset = stripAgentTicker(agent.ticker);
    if (coveredCatalogIds.has(catalogId)) return false;
    if (coveredBaseAssets.has(baseAsset)) return false;
    return true;
  });
}

export function mergeVirtualAgentTokenMarkets(
  markets: Market[],
  agents: AgentTokenPriceHistoryManifestAgent[],
): Market[] {
  const missing = manifestAgentsMissingFromMarkets(agents, markets);
  if (missing.length === 0) return markets;
  return [...markets, ...missing.map(buildVirtualAgentTokenMarket)];
}
