import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import {
  getAgentProfileById,
  getFleetAgentByCatalogId,
} from "../../../offline/mock_data";
import type { CopyRelation } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { filterCrossDisplayableBuckets } from "../../hooks/useCopyAgentConfirm";
import { useStopCopyMirror } from "../../hooks/useStopCopyMirror";
import {
  COPY_TOUR_AGENT_ID,
  COPY_TOUR_TARGETS,
} from "../../tutorials/copy-tour/constants";
import {
  useOptionalCopyTour,
  type CopyTourContextValue,
} from "../../tutorials/copy-tour";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { APP_ROUTES } from "../../routes";
import BucketDetailModal from "../tables/BucketDetailModal";
import type { BucketDetailTabId } from "../tables/bucketDetailTypes";
import CopiedAgentStatusModal from "./CopiedAgentStatusModal";
import StopCopyWizardModal from "./StopCopyWizardModal";

const OFFLINE_BASE_URL = "offline://local";

type ResolvedCopyRelation = {
  relation: CopyRelation;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
};

function resolveCopyRelations(relations: CopyRelation[]): ResolvedCopyRelation[] {
  return relations.flatMap((relation) => {
    const profile = getAgentProfileById(relation.targetCatalogAgentId);
    const fleet = getFleetAgentByCatalogId(relation.targetCatalogAgentId);
    if (!profile || !fleet) return [];
    return [{ relation, profile, fleet }];
  });
}

function pickTourCopyRelation(
  resolved: ResolvedCopyRelation[],
  copyTour: Pick<CopyTourContextValue, "tourBucketId">,
): ResolvedCopyRelation | null {
  if (resolved.length === 0) return null;

  const tourBucketId = copyTour.tourBucketId?.trim();
  if (tourBucketId) {
    const byBucket = resolved.find(
      (entry) => entry.relation.copySettings.bucketId === tourBucketId,
    );
    if (byBucket) return byBucket;
  }

  const tourAgentId = COPY_TOUR_AGENT_ID.trim().toLowerCase();
  const byAgent = resolved.find(
    (entry) =>
      entry.relation.targetCatalogAgentId.trim().toLowerCase() === tourAgentId,
  );
  return byAgent ?? resolved[0] ?? null;
}

export interface CopiedAgentsStripProps {
  relations: CopyRelation[];
  walletAddress?: string;
  height?: string;
}

export default function CopiedAgentsStrip({
  relations,
  walletAddress,
  height = "100%",
}: CopiedAgentsStripProps): JSX.Element | null {
  const navigate = useNavigate();
  const copyTour = useOptionalCopyTour();
  const { collections } = useBucketCollections({
    baseURL: OFFLINE_BASE_URL,
    walletAddress: walletAddress ?? "",
  });
  const crossBuckets = useMemo(
    () => filterCrossDisplayableBuckets(collections),
    [collections],
  );
  const { stopMirror, isPending: stopPending } = useStopCopyMirror();
  const tourStatusPinned = Boolean(
    copyTour?.runTour && copyTour.openStatusModal,
  );
  const [selectedRelationId, setSelectedRelationId] = useState<string | null>(
    null,
  );
  const [stopTarget, setStopTarget] = useState<ResolvedCopyRelation | null>(
    null,
  );
  const [bucketDetail, setBucketDetail] = useState<{
    bucketId: string;
    initialTab: BucketDetailTabId;
  } | null>(null);

  const resolvedRelations = useMemo(
    () => resolveCopyRelations(relations),
    [relations],
  );

  const selected = useMemo(
    () =>
      resolvedRelations.find((entry) => entry.relation.id === selectedRelationId) ??
      null,
    [resolvedRelations, selectedRelationId],
  );

  const selectedBucket = useMemo(
    () =>
      crossBuckets.find(
        (bucket) => bucket.bucketId === selected?.relation.copySettings.bucketId,
      ) ?? null,
    [crossBuckets, selected],
  );

  const bucketDetailBucket = useMemo(
    () =>
      bucketDetail
        ? crossBuckets.find((bucket) => bucket.bucketId === bucketDetail.bucketId) ??
          null
        : null,
    [bucketDetail, crossBuckets],
  );

  const handleStopCopy = useCallback((relationId: string) => {
    const target =
      resolvedRelations.find((entry) => entry.relation.id === relationId) ?? null;
    if (!target) return;
    setSelectedRelationId(null);
    setStopTarget(target);
  }, [resolvedRelations]);

  const handleStopConfirm = useCallback(async () => {
    if (!stopTarget) return;
    const ok = await stopMirror(stopTarget.relation, stopTarget.profile.name);
    if (ok) setStopTarget(null);
  }, [stopMirror, stopTarget]);

  const handleStatusClose = useCallback(() => {
    if (tourStatusPinned) return;
    setSelectedRelationId(null);
  }, [tourStatusPinned]);

  useEffect(() => {
    if (!copyTour?.runTour || !copyTour.openStatusModal) return;
    const tourRelation = pickTourCopyRelation(resolvedRelations, copyTour);
    if (!tourRelation) return;
    setSelectedRelationId(tourRelation.relation.id);
  }, [
    copyTour?.runTour,
    copyTour?.openStatusModal,
    copyTour?.tourBucketId,
    resolvedRelations,
  ]);

  if (!walletAddress?.trim() || resolvedRelations.length === 0) {
    return null;
  }

  return (
    <>
      <section
        className="copied-agents-strip portfolio-slot"
        style={{ height }}
        aria-label="Mirrored agents"
        data-tour={COPY_TOUR_TARGETS.mirroredStrip}
      >
        <h3 className="terminal-panel-title copied-agents-strip-label">
          Mirrored agents
        </h3>
        <div className="copied-agents-strip-row">
          {resolvedRelations.map(({ relation, profile }) => {
            const avatarSrc = resolveAgentAvatarSvgUrl(relation.targetCatalogAgentId);
            const pnl30d = profile.stats.find((stat) => stat.label === "30d PnL");

            return (
              <button
                key={relation.id}
                type="button"
                className="copied-agents-card"
                aria-label={`${profile.name}, copying at ${relation.copySettings.copySizePct}%`}
                onClick={() => setSelectedRelationId(relation.id)}
              >
                <span className="copied-agents-avatar" aria-hidden>
                  <span
                    className="copied-agents-avatar-image"
                    style={{
                      maskImage: `url(${avatarSrc})`,
                      WebkitMaskImage: `url(${avatarSrc})`,
                    }}
                  />
                </span>
                <span className="copied-agents-card-primary">
                  <strong>{profile.name}</strong>
                  {pnl30d ? (
                    <span
                      className={
                        pnl30d.tone === "positive"
                          ? "copied-agents-pnl copied-agents-pnl--positive"
                          : pnl30d.tone === "negative"
                            ? "copied-agents-pnl copied-agents-pnl--negative"
                            : "copied-agents-pnl"
                      }
                    >
                      {pnl30d.value}
                    </span>
                  ) : null}
                </span>
                <span className="copied-agents-card-signal">
                  {relation.copySettings.copySizePct}%
                </span>
              </button>
            );
          })}
          <button
            type="button"
            className="copied-agents-browse"
            onClick={() => navigate(APP_ROUTES.markets)}
          >
            Browse more agents
          </button>
        </div>
      </section>

      <CopiedAgentStatusModal
        open={selected != null}
        relation={selected?.relation ?? null}
        profile={selected?.profile ?? null}
        fleet={selected?.fleet ?? null}
        bucket={selectedBucket}
        onClose={handleStatusClose}
        onViewAgent={(catalogAgentId) => {
          if (tourStatusPinned) return;
          setSelectedRelationId(null);
          navigate(`/agents/${catalogAgentId}`);
        }}
        onManageBucket={(bucketId) => {
          if (tourStatusPinned) return;
          setSelectedRelationId(null);
          setBucketDetail({ bucketId, initialTab: "manage" });
        }}
        onAdjustSettings={(bucketId) => {
          if (tourStatusPinned) return;
          setSelectedRelationId(null);
          setBucketDetail({ bucketId, initialTab: "rules" });
        }}
        onStopCopy={(relationId) => {
          if (tourStatusPinned) return;
          handleStopCopy(relationId);
        }}
      />

      <StopCopyWizardModal
        open={stopTarget != null}
        relation={stopTarget?.relation ?? null}
        profile={stopTarget?.profile ?? null}
        isPending={stopPending}
        onClose={() => setStopTarget(null)}
        onConfirm={handleStopConfirm}
      />

      <BucketDetailModal
        isOpen={bucketDetail != null}
        bucketId={bucketDetail?.bucketId ?? null}
        bucket={bucketDetailBucket}
        initialTab={bucketDetail?.initialTab ?? "overview"}
        baseURL={OFFLINE_BASE_URL}
        walletAddress={walletAddress}
        onClose={() => setBucketDetail(null)}
      />
    </>
  );
}
