import type { Step } from "react-joyride";
import { DEPOSIT_TOUR_STEPS_CONTENT } from "./content";
import {
  DEPOSIT_TOUR_TARGETS,
  type DepositTourEntryPath,
} from "./constants";

function tourTarget(value: string): string {
  return `[data-tour="${value}"]`;
}

const STEP_TARGETS: Record<string, string> = {
  "wallet-btn": DEPOSIT_TOUR_TARGETS.walletBtn,
  "wallet-deposit": DEPOSIT_TOUR_TARGETS.walletDeposit,
  "form-asset": DEPOSIT_TOUR_TARGETS.formAsset,
  "form-chain": DEPOSIT_TOUR_TARGETS.formChain,
  "form-amount": DEPOSIT_TOUR_TARGETS.formAmount,
  "form-review": DEPOSIT_TOUR_TARGETS.formReview,
  "review-verify": DEPOSIT_TOUR_TARGETS.reviewVerify,
  "review-confirm": DEPOSIT_TOUR_TARGETS.reviewConfirm,
  "authorize-btn": DEPOSIT_TOUR_TARGETS.authorizeBtn,
  "submit-btn": DEPOSIT_TOUR_TARGETS.submitBtn,
  tracking: DEPOSIT_TOUR_TARGETS.tracking,
  success: DEPOSIT_TOUR_TARGETS.success,
  "fund-bucket": DEPOSIT_TOUR_TARGETS.fundBucket,
};

type DepositTourStepContent = (typeof DEPOSIT_TOUR_STEPS_CONTENT)[number];

export interface DepositTourStepMeta {
  stepId: string;
  stepNumber: number;
  targetSelector: string;
  requiresClick: boolean;
  syncFlowStep?: DepositTourStepContent["syncFlowStep"];
  gateNextUntilFlowStep?: DepositTourStepContent["gateNextUntilFlowStep"];
  entryPath: DepositTourEntryPath;
}

const FORM_STEP_PLACEMENT: Partial<Record<string, Step["placement"]>> = {
  "form-asset": "bottom",
  "form-chain": "top",
  "form-amount": "bottom",
  "form-review": "top",
};

export function buildDepositTourSteps(
  entryPath: DepositTourEntryPath,
): Step[] {
  const filtered = DEPOSIT_TOUR_STEPS_CONTENT.filter((step) =>
    step.entryPaths.includes(entryPath),
  );

  return filtered.map((step, index) => {
    const targetSelector = tourTarget(STEP_TARGETS[step.id] ?? step.id);
    const requiresClick = Boolean(step.requiresClick);
    const isBridgeFormStep = step.id.startsWith("form-");
    const placement =
      FORM_STEP_PLACEMENT[step.id] ?? (isBridgeFormStep ? "bottom" : "auto");

    return {
      target: targetSelector,
      title: step.title,
      content: step.content,
      placement: placement as "bottom" | "top" | "auto",
      skipBeacon: true,
      isFixed: isBridgeFormStep ? false : true,
      spotlightClicks: requiresClick,
      disableOverlay: requiresClick,
      disableOverlayClose: true,
      hideBackButton: requiresClick,
      hideCloseButton: true,
      showSkipButton: true,
      buttons: requiresClick
        ? (["skip"] as ("back" | "skip" | "primary")[])
        : (["skip", "primary"] as ("back" | "skip" | "primary")[]),
      blockTargetInteraction: false,
      skipScroll: true,
      ...(isBridgeFormStep
        ? {
            floaterProps: { disableAnimation: true, disableScrollParentFix: true },
          }
        : {}),
      data: {
        stepId: step.id,
        stepNumber: index + 1,
        targetSelector,
        requiresClick,
        syncFlowStep: step.syncFlowStep,
        gateNextUntilFlowStep: step.gateNextUntilFlowStep,
        entryPath,
      } satisfies DepositTourStepMeta,
    };
  });
}

export function getDepositTourStepCount(entryPath: DepositTourEntryPath): number {
  return DEPOSIT_TOUR_STEPS_CONTENT.filter((step) =>
    step.entryPaths.includes(entryPath),
  ).length;
}
