import type { Bucket } from "../../sdk";

export interface BucketCapitalSummary {
  totalEquity: number;
  withdrawable: number;
  lockedInPositions: number;
  reservedByOrders: number;
  pendingSettlement: number;
  lockedTotal: number;
}

/** Client-side v1 capital breakdown until API exposes encumbrance DTO. */
export function getBucketCapitalSummary(bucket: Bucket): BucketCapitalSummary {
  const totalEquity = bucket.totalEquity || 0;
  const withdrawable = Math.max(0, bucket.availableMargin || 0);
  const lockedInPositions = Math.max(0, bucket.usedMargin || 0);
  const deposited = bucket.depositedMargin || 0;
  const reservedByOrders = Math.max(
    0,
    deposited - withdrawable - lockedInPositions,
  );
  const pendingSettlement = 0;
  const lockedTotal =
    lockedInPositions + reservedByOrders + pendingSettlement;

  return {
    totalEquity,
    withdrawable,
    lockedInPositions,
    reservedByOrders,
    pendingSettlement,
    lockedTotal,
  };
}
