import type { TabSectionTabId } from "../components/tables/TabSection";

/** True when a non-empty wallet address is available. */
export function isWalletConnected(
  walletAddress?: string | null,
): boolean {
  return Boolean(walletAddress?.trim());
}

/** Tabs that do not require a connected wallet (public / fleet activity). */
export const WALLET_OPTIONAL_TABS: readonly TabSectionTabId[] = ["tokenTakers"];

/** Whether the given TabSection tab should show wallet-scoped content. */
export function tabRequiresWallet(tabId: TabSectionTabId): boolean {
  return !WALLET_OPTIONAL_TABS.includes(tabId);
}
