/**
 * Index detail terminal page — slug-driven grid layout.
 */
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { Navigate, useInRouterContext, useParams } from "react-router-dom";

import { getIndexProfileBySlug } from "../../offline/mock_data";
import IndexListPage from "./IndexListPage";
import { GridViewerLayout, GRID_COLS } from "../components";
import {
  IndexConstituentsPanel,
  IndexConstituentXNewsPanel,
  IndexHeroHeader,
  IndexModeTabSection,
  IndexNavPriceChart,
  IndexOverviewPanel,
  IndexPerformanceMetricsBar,
  IndexShareModal,
} from "../components/index/index";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  applyIndexLayoutSizing,
  buildIndexResponsiveLayoutConfig,
  generateIndexResponsiveLayouts,
  INDEX_LAYOUT_MARGIN,
  INDEX_ROW_HEIGHT,
} from "../configs/indexLayoutConfig";
import { useIndexPageData } from "../hooks/useIndexPageData";
import { useSettings } from "../context/SettingsContext";
import { APP_ROUTES } from "../routes";
import "./IndexPage.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [INDEX_LAYOUT_MARGIN, INDEX_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = INDEX_ROW_HEIGHT;

function getIndexSlugFromPath(): string {
  const parts = window.location.pathname.split("/").filter(Boolean);
  return parts[0] === "cindex" && parts[1] ? parts[1] : "";
}

function buildLayouts(viewportHeight?: number) {
  const base = buildIndexResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyIndexLayoutSizing(base, height);
  return generateIndexResponsiveLayouts(sized, 0);
}

export default function IndexDetailPage(): JSX.Element {
  const inRouter = useInRouterContext();
  const { baseAsset: routeSlug = "" } = useParams<{ baseAsset: string }>();
  const baseAsset = routeSlug || getIndexSlugFromPath();

  if (!getIndexProfileBySlug(baseAsset)) {
    if (inRouter) {
      return <Navigate to={APP_ROUTES.index} replace />;
    }
    window.history.replaceState({}, "", APP_ROUTES.index);
    return <IndexListPage />;
  }

  return <IndexDetailPageContent key={baseAsset} baseAsset={baseAsset} />;
}

function IndexDetailPageContent({
  baseAsset,
}: {
  baseAsset: string;
}): JSX.Element {
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const [shareOpen, setShareOpen] = useState(false);
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);
  const { settings } = useSettings();
  const showXPulse = settings.index.showXPulse;

  const {
    profile,
    row,
    activeMode,
    setActiveMode,
    activeModeMeta,
    constituents,
    xPulseConstituents,
    nav,
    price,
    chartSeries,
    performanceMetrics,
  } = useIndexPageData(baseAsset);

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(window.innerHeight);
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };

    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, []);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const slotContent = useMemo(
    () => [
      <IndexHeroHeader
        key="title"
        height={slotDimensions[0]?.height}
        profile={profile}
      />,
      <IndexNavPriceChart
        key="chart"
        height={slotDimensions[1]?.height}
        price={price}
        nav={nav}
        series={chartSeries}
      />,
      <IndexConstituentsPanel
        key="constituents"
        height={slotDimensions[2]?.height}
        constituents={constituents}
        activeMode={activeMode}
        modeLabel={activeModeMeta?.label}
      />,
      <IndexOverviewPanel
        key="overview"
        height={slotDimensions[3]?.height}
        profile={profile}
        icon={row.icon}
        price={price}
        change24h={profile.change24h}
        activeModeMeta={activeModeMeta}
        onShareClick={() => setShareOpen(true)}
      />,
      <IndexModeTabSection
        key="tabs"
        height={slotDimensions[4]?.height ?? "100%"}
        profile={profile}
        activeMode={activeMode}
        onModeChange={setActiveMode}
      />,
      <IndexPerformanceMetricsBar
        key="metrics"
        height={slotDimensions[5]?.height}
        metrics={performanceMetrics}
        sparkline={row.sparkline}
      />,
      showXPulse &&
      (currentBreakpoint === "lg" || currentBreakpoint === "md") ? (
        <IndexConstituentXNewsPanel
          key="x-pulse"
          height={slotDimensions[6]?.height}
          constituents={xPulseConstituents}
          pulseLabel={`${profile.name} pulse`}
          enabled
        />
      ) : (
        null
      ),
      null,
      null,
    ],
    [
      slotDimensions,
      profile,
      row.icon,
      price,
      nav,
      chartSeries,
      constituents,
      xPulseConstituents,
      activeMode,
      activeModeMeta,
      setActiveMode,
      performanceMetrics,
      row.sparkline,
      currentBreakpoint,
      showXPulse,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--index">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
      <IndexShareModal
        isOpen={shareOpen}
        onClose={() => setShareOpen(false)}
        payload={{
          profile,
          modeLabel: activeModeMeta?.label,
          constituents,
          performanceMetrics,
        }}
      />
    </div>
  );
}
