export interface AgentHeroHeaderProps {
  height?: string;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  focus?: AgentHeroFocus;
  columnLayout?: AgentHeroColumnLayout;
  onOpenAgentSettings?: () => void;
}

function AgentHeroHeader({
  height = "100%",
  profile,
  fleet,
  focus: focusOverride,
  columnLayout = "narrow",
  onOpenAgentSettings,
}: AgentHeroHeaderProps): JSX.Element {
  const settingsContext = useOptionalSettings();
  const agentPrefs = settingsContext?.settings.agent ?? DEFAULT_AGENT_PREFS;
  const focus =
    focusOverride ??
    agentPrefs.heroFocus ??
    DEFAULT_AGENT_HERO_FOCUS;
  const content = buildAgentHeroFocusContent(
    focus,
    profile,
    fleet,
    columnLayout,
  );
  const agentAvatarSrc = resolveAgentAvatarSvgUrl(profile.id);

  return (
    <div
      className={`agent-slot agent-header-band agent-header-band--title agent-hero-header agent-hero-header--${columnLayout}`}
      style={{ height }}
    >
      <div className="terminal-header-band-actions">
        {onOpenAgentSettings ? (
          <button
            type="button"
            className="terminal-settings-button terminal-settings-button--compact"
            onClick={onOpenAgentSettings}
            aria-label="Agent settings"
          >
            <AgentSettingsIcon />
          </button>
        ) : null}
        <TerminalCompactSettingsButton
          focusSection="agentHeroFocus"
          ariaLabel="Display preferences"
        />
      </div>
      <div className="agent-hero-header-content">
        <p className="eyebrow-text-wrap" title={content.eyebrowTitle ?? content.eyebrow}>
          <Typewriter
            text={content.eyebrow}
            className="eyebrow-text"
            multiline={false}
          />
        </p>
        <div className="agent-hero-title-row">
          <span className="agent-hero-avatar" aria-hidden>
            <span
              className="agent-hero-avatar-image"
              style={{
                maskImage: `url(${agentAvatarSrc})`,
                WebkitMaskImage: `url(${agentAvatarSrc})`,
              }}
            />
          </span>
          <h1 className="agent-hero-title">{profile.name}</h1>
          {content.titleChip?.kind === "ticker" ? (
            <span className="agent-ticker">{content.titleChip.value}</span>
          ) : null}
          {content.titleChip?.kind === "verified" ? (
            <span className="agent-verified-chip">{content.titleChip.value}</span>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export { resolveAgentHeroColumnLayout };

export default AgentHeroHeader;
