import React, { type ReactNode } from "react";
import { isWalletConnected } from "../../utils/walletConnection";
import ConnectWalletPanel, {
  type ConnectWalletPanelLayout,
} from "./ConnectWalletPanel";
import type { ConnectWalletVariant } from "./connectWalletCopy";

export interface WalletConnectedGateProps {
  walletAddress?: string | null;
  variant: ConnectWalletVariant;
  layout?: ConnectWalletPanelLayout;
  height?: string;
  className?: string;
  onConnect?: () => void;
  children: ReactNode;
}

function WalletConnectedGate({
  walletAddress,
  variant,
  layout = "panel",
  height = "100%",
  className,
  onConnect,
  children,
}: WalletConnectedGateProps): JSX.Element {
  if (isWalletConnected(walletAddress)) {
    return <>{children}</>;
  }

  return (
    <ConnectWalletPanel
      variant={variant}
      layout={layout}
      height={height}
      className={className}
      onConnect={onConnect}
    />
  );
}

export default React.memo(WalletConnectedGate);
