export type XNewsSentiment = "bull" | "bear" | "neutral";

export type XNewsGenContext = {
  symbol: string;
  peer: string;
  params: Record<string, number | string>;
};

export type XNewsTemplate = {
  templateId: string;
  handle: string;
  sentiment: XNewsSentiment | ((ctx: XNewsGenContext) => XNewsSentiment);
  buildHeadline: (ctx: XNewsGenContext) => string;
};

export type GeneratedXNews = {
  instanceId: string;
  templateId: string;
  handle: string;
  headline: string;
  sentiment: XNewsSentiment;
  createdAt: number;
};

function randomInRange(min: number, max: number, decimals = 1): number {
  const value = min + Math.random() * (max - min);
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function pickOne<T>(items: readonly T[]): T {
  return items[Math.floor(Math.random() * items.length)]!;
}

