function randomizeNewsParams(templateId: string): Record<string, number | string> {
  switch (templateId) {
    case "earnings-whisper":
      return {
        quarter: Math.round(randomInRange(1, 4, 0)),
        direction: pickOne(["above", "below", "inline with"] as const),
        movePct: randomInRange(3, 12),
      };
    case "etf-flow":
      return {
        flowM: Math.round(randomInRange(80, 450, 0)),
        weeks: Math.round(randomInRange(2, 8, 0)),
      };
    case "macro-headline":
      return {
        bps: Math.round(randomInRange(4, 18, 0)),
      };
    case "analyst-note":
      return {
        pt: Math.round(randomInRange(120, 280, 0)),
        upside: Math.round(randomInRange(8, 25, 0)),
        theme: pickOne([
          "AI capex cycle",
          "margin expansion",
          "market share gains",
          "regulatory clarity",
        ] as const),
      };
    case "vol-spike":
      return {
        ivMove: Math.round(randomInRange(12, 35, 0)),
        level: pickOne(["prior day high", "weekly VWAP", "200 DMA"] as const),
      };
    case "social-momentum":
      return {
        mentionPct: Math.round(randomInRange(40, 180, 0)),
      };
    case "sector-rotation":
      return {
        spreadPct: randomInRange(1.2, 4.5),
      };
    case "breaking-headline":
      return {
        eventType: pickOne([
          "guidance update hitting wires",
          "exec departure confirmed",
          "regulatory filing disclosed",
          "partnership rumor gaining traction",
        ] as const),
        repricePct: randomInRange(5, 18),
      };
    default:
      return {};
  }
}

function resolveSentiment(
  template: XNewsTemplate,
  ctx: XNewsGenContext,
): XNewsSentiment {
  return typeof template.sentiment === "function"
    ? template.sentiment(ctx)
    : template.sentiment;
}

function createInstanceId(): string {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return `xnews-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function pickRandomXNewsTemplate(): XNewsTemplate {
  return pickOne(X_NEWS_TEMPLATES);
}

export function generateXNews(baseAsset: string): GeneratedXNews {
  const template = pickRandomXNewsTemplate();
  const symbol = resolveDisplaySymbol(baseAsset);
  const peer = resolvePeerSymbol(baseAsset);
  const params = randomizeNewsParams(template.templateId);
  const ctx: XNewsGenContext = { symbol, peer, params };

  return {
    instanceId: createInstanceId(),
    templateId: template.templateId,
    handle: template.handle,
    headline: template.buildHeadline(ctx),
    sentiment: resolveSentiment(template, ctx),
    createdAt: Date.now(),
  };
}

export function formatRelativeTime(createdAt: number, now = Date.now()): string {
  const diffMs = Math.max(0, now - createdAt);
  const diffSec = Math.floor(diffMs / 1000);
  if (diffSec < 60) return `${diffSec || 1}s`;
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m`;
  const diffHr = Math.floor(diffMin / 60);
  return `${diffHr}h`;
}

/** Minimum items seeded on first ticker appearance. */
export const MIN_X_NEWS_SEED_COUNT = 4;

/** Vertical gap between news cards — matches var(--terminal-space-3). */
export const X_NEWS_CARD_GAP_PX = 8;

/** Fallback card height before first layout measure. */
export const X_NEWS_ESTIMATED_CARD_HEIGHT_PX = 96;

export function computeEstimatedVisibleCapacity(
  availableHeightPx: number,
): number {
  if (availableHeightPx <= 0) return MIN_X_NEWS_SEED_COUNT;
  const unit = X_NEWS_ESTIMATED_CARD_HEIGHT_PX + X_NEWS_CARD_GAP_PX;
  return Math.max(
    MIN_X_NEWS_SEED_COUNT,
    Math.floor((availableHeightPx + X_NEWS_CARD_GAP_PX) / unit),
  );
}

/** How many full cards fit in the viewport (newest-first order). */
export function computeVisibleNewsCapacity(
  availableHeightPx: number,
  cardHeightsPx: number[],
): number {
  if (availableHeightPx <= 0) return MIN_X_NEWS_SEED_COUNT;
  if (cardHeightsPx.length === 0) {
    return computeEstimatedVisibleCapacity(availableHeightPx);
  }

  let used = 0;
  let fit = 0;
  for (const height of cardHeightsPx) {
    const gap = fit > 0 ? X_NEWS_CARD_GAP_PX : 0;
    if (used + gap + height > availableHeightPx + 0.5) break;
    used += gap + height;
    fit += 1;
  }

  return Math.max(MIN_X_NEWS_SEED_COUNT, fit);
}

