const ICON_MAP: Record<string, string> = {
  BTC: "₿",
  ETH: "Ξ",
  XRP: "✕",
  BNB: "◆",
  EUR: "€",
  USD: "$",
  USDC: "$",
  USDT: "$",
  XAU: "Au",
  XAG: "Ag",
  OIL: "🛢",
  OPENAI: "◎",
  ANTHROPICS: "◈",
  SPACX: "✦",
  TSLA: "T",
  AAPL: "A",
  NVDA: "N",
  HYPE: "H",
  ALPHA: "🤖",
  HEDGE: "🧠",
  OWL: "🦉",
  MEME: "🐭",
  MAEXGEN: "◎",
  MAEXALP: "◌",
  MAEXSOC: "◉",
  MAEXCORE: "◎",
  MAEXINF: "⬡",
  MAEXPRD: "◆",
  MAEXDEFI: "◇",
  MAEXARN: "✦",
  MAEXBRD: "◍",
  SP500: "S",
  NDAQ100: "N",
};

export function getAssetIcon(symbol: string, displayName?: string): string {
  const base = symbol.split("-")[0]?.split("/")[0]?.toUpperCase() || "";
  if (ICON_MAP[base]) {
    return ICON_MAP[base];
  }
  if (displayName) {
    return displayName.charAt(0).toUpperCase();
  }
  return base.charAt(0) || "?";
}
