import React, { useEffect, useRef } from "react";

import { getAgentProfileById } from "../../../offline/mock_data";
import {
  ORDER_SIDE_COLOR_BUY_LONG,
  ORDER_SIDE_COLOR_SELL_SHORT,
  TOKEN_TAKER_ACTIVITY_GRID_TEMPLATE_COLUMNS,
} from "../../constants";
import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import { useAgentTokenTakerHistory } from "../../hooks/useAgentTokenTakerHistory";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import { TableHeaderCellStatic } from "../smartlayout";
import "../smartlayout/layout.css";
import "./agent.css";

function shortId(id: string): string {
  if (!id || id.length < 12) return id;
  return `${id.slice(0, 8)}…`;
}

function shortWallet(address: string): string {
  if (!address || address.length < 12) return address;
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

function formatTime(iso: string): string {
  const date = new Date(iso);
  return date.toISOString().replace("T", " ").slice(0, 16);
}

function useInfiniteScrollSentinel(
  sentinelRef: React.RefObject<HTMLDivElement | null>,
  onLoadMore: () => void,
  hasMore: boolean,
): void {
  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel || !hasMore) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          onLoadMore();
        }
      },
      { root: sentinel.parentElement, rootMargin: "120px", threshold: 0 },
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [sentinelRef, onLoadMore, hasMore]);
}

export interface TokenTakerActivityTabProps {
  marketCatalogAgentId: string;
  height?: string;
  emptyMessage?: string;
  onViewEventOnChart?: (event: AgentTokenTakerTradeEvent) => void;
  activeEventId?: string | null;
}

export default function TokenTakerActivityTab({
  marketCatalogAgentId,
  height = "100%",
  emptyMessage = "No taker activity for this token yet.",
  onViewEventOnChart,
  activeEventId = null,
}: TokenTakerActivityTabProps): JSX.Element {
  const {
    visibleEvents,
    loading,
    error,
    hasMarket,
    hasMore,
    loadMore,
  } = useAgentTokenTakerHistory(marketCatalogAgentId);

  const sentinelRef = useRef<HTMLDivElement>(null);
  useInfiniteScrollSentinel(sentinelRef, loadMore, hasMore);

  if (loading) {
    return (
      <div className="agent-fleet-activity agent-fleet-activity--loading">
        <MorpheumInlineLoading message="Loading token taker activity…" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="agent-fleet-activity agent-fleet-activity--error">
        <p>{error}</p>
      </div>
    );
  }

  if (!hasMarket || visibleEvents.length === 0) {
    return (
      <div className="agent-fleet-activity agent-fleet-activity--empty">
        <p>{emptyMessage}</p>
      </div>
    );
  }

  return (
    <div
      className="layout-container agent-fleet-activity-table"
      style={{ height, borderRadius: 0, background: "transparent" }}
    >
      <div className="table-container shrinkable">
        <div
          className="table-header"
          style={{
            gridTemplateColumns: TOKEN_TAKER_ACTIVITY_GRID_TEMPLATE_COLUMNS,
          }}
        >
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Action</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Taker</TableHeaderCellStatic>
          <TableHeaderCellStatic right>USD</TableHeaderCellStatic>
          <TableHeaderCellStatic right>PnL</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Tx</TableHeaderCellStatic>
        </div>
        {visibleEvents.map((event, index) => {
          const pnlColor =
            event.closedPnl == null
              ? undefined
              : event.closedPnl > 0
                ? ORDER_SIDE_COLOR_BUY_LONG
                : event.closedPnl < 0
                  ? ORDER_SIDE_COLOR_SELL_SHORT
                  : undefined;

          const takerProfile = getAgentProfileById(event.takerCatalogAgentId);
          const takerLabel =
            takerProfile?.name ?? shortId(event.takerCatalogAgentId);
          const isActiveEvent = activeEventId === event.id;
          const rowClassName = `table-row ${index % 2 === 0 ? "even" : ""}${
            onViewEventOnChart ? " clickable" : ""
          }${isActiveEvent ? " agent-fleet-activity-row--active" : ""}`;

          const rowContent = (
            <>
              <div className="table-cell primary">
                {formatTime(event.timestamp)}
              </div>
              <div className="table-cell">
                <span
                  className={`agent-fleet-action agent-fleet-action--${event.action.toLowerCase()}`}
                >
                  {event.action}
                </span>
              </div>
              <div className="table-cell" title={event.takerCatalogAgentId}>
                {takerLabel}
              </div>
              <div className="table-cell right">
                ${event.amountUsd.toFixed(0)}
              </div>
              <div
                className="table-cell right"
                style={{ color: pnlColor, fontWeight: pnlColor ? 500 : 400 }}
              >
                {event.closedPnl != null
                  ? `${event.closedPnl >= 0 ? "+" : ""}$${event.closedPnl.toFixed(2)}`
                  : "—"}
              </div>
              <div className="table-cell" title={event.txSimHash}>
                {shortWallet(event.txSimHash)}
              </div>
            </>
          );

          if (onViewEventOnChart) {
            return (
              <button
                key={event.id}
                type="button"
                className={`${rowClassName} agent-fleet-activity-row-btn`}
                style={{
                  gridTemplateColumns: TOKEN_TAKER_ACTIVITY_GRID_TEMPLATE_COLUMNS,
                }}
                aria-current={isActiveEvent ? "true" : undefined}
                onClick={() => onViewEventOnChart(event)}
              >
                {rowContent}
              </button>
            );
          }

          return (
            <div
              key={event.id}
              className={rowClassName}
              style={{
                gridTemplateColumns: TOKEN_TAKER_ACTIVITY_GRID_TEMPLATE_COLUMNS,
              }}
            >
              {rowContent}
            </div>
          );
        })}
        {hasMore ? (
          <div
            ref={sentinelRef}
            className="agent-fleet-activity-sentinel"
            aria-hidden
          />
        ) : null}
      </div>
    </div>
  );
}
