import { useQuery } from "@tanstack/react-query";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import { generateNetworkKpis } from "./mockData";

/** Simulated chain-truth KPIs, polled on a gentle interval. */
export function useNetworkKpis() {
  const { throughputTier, validatorCount } = useNetworkHealthDemo();

  return useQuery({
    queryKey: ["network-health", "kpis", throughputTier, validatorCount],
    queryFn: async () =>
      generateNetworkKpis({ throughputTier, validatorCount }),
    refetchInterval: 5_000,
  });
}
