export const REFERENCE_DEPOSIT = 1_200_000;

export type JellyDemoConfig = {
  depositUsd: number;
  safePct: number;
  memePct: number;
  hedgePct: number;
  insurancePct: number;
};

export const DEFAULT_JELLY_DEMO_CONFIG: JellyDemoConfig = {
  depositUsd: REFERENCE_DEPOSIT,
  safePct: 50,
  memePct: 25,
  hedgePct: 16.67,
  insurancePct: 8.33,
};

export function bucketAmount(config: JellyDemoConfig, pct: number): number {
  return (config.depositUsd * pct) / 100;
}

export function scaleTimelineAmount(config: JellyDemoConfig, baseUsd: number): number {
  return baseUsd * (config.depositUsd / REFERENCE_DEPOSIT);
}
