import { useCallback, useState } from "react";
import { toast } from "sonner";

import type { CopyRelation } from "../../offline/mock_data/fleetCopyRelations";
import { stopCopyMirrorReplaySession } from "../services/copyMirrorOrchestrator";
import { useAgentTaskStore } from "../store/agentTaskStore";
import { useBucketPolicyStore } from "../store/bucketPolicyStore";
import { useFleetCopyStore } from "../store/fleetCopyStore";

export function useStopCopyMirror(): {
  isPending: boolean;
  stopMirror: (relation: CopyRelation, profileName: string) => Promise<boolean>;
} {
  const removeCopyRelation = useFleetCopyStore((state) => state.removeCopyRelation);
  const clearPolicy = useBucketPolicyStore((state) => state.clearPolicy);
  const pauseActiveTasksForBucket = useAgentTaskStore(
    (state) => state.pauseActiveTasksForBucket,
  );
  const rejectAllPendingForBucket = useAgentTaskStore(
    (state) => state.rejectAllPendingForBucket,
  );
  const [isPending, setIsPending] = useState(false);

  const stopMirror = useCallback(
    async (relation: CopyRelation, profileName: string): Promise<boolean> => {
      setIsPending(true);
      try {
        const { bucketId, bucketMode } = relation.copySettings;
        stopCopyMirrorReplaySession(relation.id);
        pauseActiveTasksForBucket(bucketId);
        rejectAllPendingForBucket(bucketId);
        removeCopyRelation(relation.id);
        if (bucketMode === "new") {
          clearPolicy(bucketId);
        }
        toast.success("Mirror stopped", {
          description:
            bucketMode === "new"
              ? `${profileName} — relation removed and bucket policy cleared (demo).`
              : `${profileName} — relation removed. Shared bucket policy and positions remain.`,
        });
        return true;
      } catch (err) {
        const message =
          err instanceof Error ? err.message : "Failed to stop mirror";
        toast.error("Stop mirror failed", { description: message });
        return false;
      } finally {
        setIsPending(false);
      }
    },
    [
      clearPolicy,
      pauseActiveTasksForBucket,
      rejectAllPendingForBucket,
      removeCopyRelation,
    ],
  );

  return { isPending, stopMirror };
}
