import React, {
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import type { AgentTask } from "../../store/types";
import { shortHashId } from "../../utils/hashId";
import { useFlipListInsert } from "../tradeops/useFlipListInsert";
import type { FeedEnterState } from "../tradeops/feedAnimation";
import { DECK_DEFAULT_VISIBLE_INTENTS } from "./deckCapacity";
import { sortLiveIntents } from "./deckIntents";
import GuardrailIntentCardExtras from "./GuardrailIntentCardExtras";
import IntentGateCountdownRing from "./IntentGateCountdownRing";
import { TradeAgentIntentCard } from "./TradeAgentIntentCard";
import { useDeckBottomFade } from "./useDeckBottomFade";
import { useDeckCardCapacity } from "./useDeckCardCapacity";
import { useDeckTaskListAnimation } from "./useDeckTaskListAnimation";
import { useIntentGateTimer } from "./useIntentGateTimer";
import type { GateIntentTimerPrefs } from "./gateIntentTimerPrefs";
import type { AutonomyPolicy } from "./autonomyPolicy";
import { getTaskReportingMeta } from "./reportTier";
import { AnimatedCollapse } from "../ui/AnimatedCollapse";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import "./tradeAgentDeck.css";

export interface ManualTradeAccordionProps {
  children: React.ReactNode;
  defaultOpen?: boolean;
  label?: string;
}

export function ManualTradeAccordion({
  children,
  defaultOpen = false,
  label = "Manual Override",
}: ManualTradeAccordionProps): JSX.Element {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className="trade-agent-deck-accordion">
      <button
        type="button"
        className="trade-agent-deck-accordion-toggle"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
      >
        <span className="trade-agent-deck-accordion-label">{label}</span>
        <ExpandCollapseIcon expanded={open} size={14} />
      </button>
      <AnimatedCollapse
        open={open}
        timing="deck"
        innerClassName="trade-agent-deck-accordion-inner"
      >
        {children}
      </AnimatedCollapse>
    </div>
  );
}

function mergeRenderTasks(
  visibleTasks: AgentTask[],
  allTasks: AgentTask[],
  exitingId: string | null,
): AgentTask[] {
  if (!exitingId || visibleTasks.some((t) => t.id === exitingId)) {
    return visibleTasks;
  }
  const exitingTask = allTasks.find((t) => t.id === exitingId);
  if (!exitingTask) return visibleTasks;
  return [...visibleTasks, exitingTask];
}

export interface AgentCommandDeckProps {
  height?: string;
  onRequestExpandConsole?: () => void;
  /** Escalated High-Agency: additional gated intents below spotlight. */
  escalatedQueue?: AgentTask[];
  policy?: AutonomyPolicy;
  resolvePolicy?: (task: AgentTask) => AutonomyPolicy;
  gateIntentTimer?: GateIntentTimerPrefs;
}

interface GatedIntentDeckCardProps {
  task: AgentTask;
  gateTimerPrefs: GateIntentTimerPrefs;
  enterState: FeedEnterState | null;
  exitingId: string | null;
  setFlipRef: (id: string) => (el: HTMLElement | null) => void;
  onExitAnimationEnd: (taskId: string) => void;
  onApprove: (taskId: string, sizePct: number) => void;
  onReject: (taskId: string) => void;
}

function GatedIntentDeckCard({
  task,
  gateTimerPrefs,
  enterState,
  exitingId,
  setFlipRef,
  onExitAnimationEnd,
  onApprove,
  onReject,
}: GatedIntentDeckCardProps): JSX.Element {
  const { getAgentById } = useTradingAgents();
  const [sizePct, setSizePct] = useState(100);
  const timerEnabled = gateTimerPrefs.enabled;
  const agent = getAgentById(task.agentId);
  const agentLabel = agent?.displayName ?? shortHashId(task.agentId);

  const timer = useIntentGateTimer({
    enabled: timerEnabled,
    waitSeconds: gateTimerPrefs.waitSeconds,
    onTimeout: gateTimerPrefs.onTimeout,
    taskId: task.id,
    sizePct,
    onApprove,
    onReject,
  });

  const headerLeading =
    timerEnabled ? (
      <>
        <span className="task-id-chip" title={task.agentId}>
          {agentLabel}
        </span>
        <BubbleTip id={BUBBLE_TIP_IDS.gateIntentAutoTimer}>
          <IntentGateCountdownRing
            waitSeconds={gateTimerPrefs.waitSeconds}
            runKey={task.id}
            isPaused={timer.manualOverride}
            isComplete={timer.isComplete}
            onClockClick={timer.pauseForManual}
          />
        </BubbleTip>
      </>
    ) : undefined;

  return (
    <TradeAgentIntentCard
      task={task}
      enterState={enterState}
      exitingId={exitingId}
      setFlipRef={setFlipRef}
      onExitAnimationEnd={onExitAnimationEnd}
      headerLeading={headerLeading}
      isGateTimeoutComplete={
        timerEnabled && timer.isComplete && !timer.manualOverride
      }
    >
      <GuardrailIntentCardExtras
        task={task}
        onApprove={onApprove}
        onReject={onReject}
        hideGateActions={timerEnabled && !timer.manualOverride}
        onSizePctChange={setSizePct}
        tooltipGroup="AgentCommandDeck"
      />
    </TradeAgentIntentCard>
  );
}

function AgentCommandDeck({
  height,
  onRequestExpandConsole,
  escalatedQueue,
  policy,
  resolvePolicy,
  gateIntentTimer,
}: AgentCommandDeckProps): JSX.Element {
  const { tasks, activeCount, pauseActiveTasks, forceExecute, rejectTask } =
    useAgentTasks();
  const isQueueMode = escalatedQueue != null;
  const prevCardCountRef = useRef(0);
  const cardsViewportRef = useRef<HTMLDivElement>(null);
  const [visibleCapacity, setVisibleCapacity] = useState(
    DECK_DEFAULT_VISIBLE_INTENTS,
  );

  const handleCapacityChange = useCallback((next: number) => {
    setVisibleCapacity((prev) => (prev === next ? prev : next));
  }, []);

  const liveIntents = useMemo(() => {
    if (isQueueMode) return escalatedQueue ?? [];
    return sortLiveIntents(tasks);
  }, [isQueueMode, escalatedQueue, tasks]);

  const topIntents = useMemo(
    () => liveIntents.slice(0, visibleCapacity),
    [liveIntents, visibleCapacity],
  );

  const overflowCount = Math.max(0, liveIntents.length - topIntents.length);

  const measureCardIds = useMemo(
    () => topIntents.map((task) => task.id),
    [topIntents],
  );

  const { enterState, exitingId, onExitAnimationEnd } =
    useDeckTaskListAnimation(measureCardIds);

  const renderTasks = useMemo(
    () => mergeRenderTasks(topIntents, tasks, exitingId),
    [topIntents, tasks, exitingId],
  );

  const renderTaskIds = useMemo(
    () => renderTasks.map((task) => task.id),
    [renderTasks],
  );

  const enteringId =
    enterState?.phase === "push" ? enterState.instanceId : null;

  const setFlipRef = useFlipListInsert({
    itemIds: renderTaskIds,
    enteringId,
  });

  const setCardRef = useDeckCardCapacity({
    cardsViewportRef,
    measureCardIds,
    setFlipRef,
    onCapacityChange: handleCapacityChange,
  });

  const showBottomFade = useDeckBottomFade(
    cardsViewportRef,
    overflowCount,
    renderTaskIds.join("\0"),
  );

  useLayoutEffect(() => {
    if (renderTasks.length > prevCardCountRef.current && cardsViewportRef.current) {
      cardsViewportRef.current.scrollTop = 0;
    }
    prevCardCountRef.current = renderTasks.length;
  }, [renderTasks.length, cardsViewportRef]);

  const handlePauseAll = () => {
    pauseActiveTasks();
  };

  const handleApprove = useCallback(
    (taskId: string, sizePct: number) => {
      forceExecute(taskId, { sizePct });
    },
    [forceExecute],
  );

  return (
    <div
      className="trade-agent-deck"
      style={{ height, minHeight: 0 }}
      data-tour="welcome-agent-deck"
      data-deck-mode={isQueueMode ? "queue" : "full"}
    >
      <div className="trade-agent-deck-head">
        <BubbleTip id={BUBBLE_TIP_IDS.commandDeckHeader}>
          <div className="trade-agent-deck-head-inner">
            <h2 className="trade-agent-deck-title">Command Deck</h2>
            <p className="trade-agent-deck-sub">
              {isQueueMode
                ? `+${liveIntents.length} more need you`
                : `${activeCount} active intent${activeCount === 1 ? "" : "s"}`}
            </p>
          </div>
        </BubbleTip>
      </div>
      <div className="trade-agent-deck-body">
        <BubbleTip id={BUBBLE_TIP_IDS.commandDeckIntentCards}>
          <div className="trade-agent-deck-cards-shell">
            <div ref={cardsViewportRef} className="trade-agent-deck-cards">
              {renderTasks.map((task) => {
                const taskPolicy = resolvePolicy?.(task) ?? policy;
                const tier = taskPolicy
                  ? getTaskReportingMeta(task, taskPolicy).reportTier
                  : null;
                const showGateActions =
                  isQueueMode &&
                  taskPolicy &&
                  (tier === "T3" || tier === "T4") &&
                  (task.status === "pending" || task.status === "watching");

                return showGateActions && gateIntentTimer ? (
                  <GatedIntentDeckCard
                    key={task.id}
                    task={task}
                    gateTimerPrefs={gateIntentTimer}
                    enterState={enterState}
                    exitingId={exitingId}
                    setFlipRef={setCardRef}
                    onExitAnimationEnd={onExitAnimationEnd}
                    onApprove={handleApprove}
                    onReject={rejectTask}
                  />
                ) : (
                  <TradeAgentIntentCard
                    key={task.id}
                    task={task}
                    enterState={enterState}
                    exitingId={exitingId}
                    setFlipRef={setCardRef}
                    onExitAnimationEnd={onExitAnimationEnd}
                  >
                    {showGateActions ? (
                      <GuardrailIntentCardExtras
                        task={task}
                        onApprove={handleApprove}
                        onReject={rejectTask}
                        tooltipGroup="AgentCommandDeck"
                      />
                    ) : null}
                  </TradeAgentIntentCard>
                );
              })}
            </div>
            <div
              className={[
                "trade-agent-deck-cards-fade",
                showBottomFade ? "is-visible" : "",
              ]
                .filter(Boolean)
                .join(" ")}
              aria-hidden
            />
          </div>
        </BubbleTip>
        {topIntents.length === 0 && !exitingId ? (
          <p className="trade-agent-reasoning-item">
            {isQueueMode
              ? "No additional gated intents."
              : "No live intents — deploy a swarm to begin."}
          </p>
        ) : null}
        {onRequestExpandConsole ? (
          <BubbleTip id={BUBBLE_TIP_IDS.commandDeckOverflow}>
            <span className="trade-agent-deck-overflow-trigger">
              <button
                type="button"
                className={[
                  "trade-agent-deck-overflow-btn",
                  overflowCount > 0 ? "" : "trade-agent-deck-overflow-btn--placeholder",
                ]
                  .filter(Boolean)
                  .join(" ")}
                onClick={overflowCount > 0 ? onRequestExpandConsole : undefined}
                disabled={overflowCount === 0}
                aria-hidden={overflowCount === 0}
                tabIndex={overflowCount === 0 ? -1 : undefined}
              >
                {overflowCount > 0
                  ? `+${overflowCount} more intent${overflowCount === 1 ? "" : "s"}`
                  : "\u00a0"}
              </button>
            </span>
          </BubbleTip>
        ) : null}
        {!isQueueMode ? (
          <div className="trade-agent-deck-actions">
            <BubbleTip id={BUBBLE_TIP_IDS.commandDeckDeploySwarm}>
              <button type="button" className="trade-agent-deck-btn trade-agent-deck-btn--primary">
                Deploy Swarm
              </button>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.commandDeckSimulate}>
              <button type="button" className="trade-agent-deck-btn">
                Simulate
              </button>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.commandDeckPauseAll}>
              <button
                type="button"
                className="trade-agent-deck-btn trade-agent-deck-btn--danger"
                onClick={handlePauseAll}
              >
                Pause All
              </button>
            </BubbleTip>
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default React.memo(AgentCommandDeck);
