import React from "react";
import { formatCurrency } from "../../../sdk/utils/display";
import type { CrossChainTransferRecord } from "../../../types/crossChainFlow";
import { CrossChainSecurityStepper } from "./CrossChainSecurityStepper";
import "./cross-chain.css";

export interface CrossChainSuccessPanelProps {
  record: CrossChainTransferRecord;
  newBalance?: number | null;
  showBucketHandoff: boolean;
  onFundBucket: () => void;
  onNewTransfer: () => void;
  onDemoLinkClick?: () => void;
}

function shortHash(hash?: string): string {
  if (!hash) return "—";
  return `${hash.slice(0, 8)}…${hash.slice(-4)}`;
}

function balanceLabel(
  record: CrossChainTransferRecord,
  newBalance: number,
): string {
  if (record.mode === "deposit" && record.assetId === "USDC") {
    return `Spot balance: ${formatCurrency(newBalance)} USDC`;
  }
  return `Balance: ${formatCurrency(newBalance)} ${record.assetId}`;
}

export function CrossChainSuccessPanel({
  record,
  newBalance = null,
  showBucketHandoff,
  onFundBucket,
  onNewTransfer,
  onDemoLinkClick,
}: CrossChainSuccessPanelProps): JSX.Element {
  return (
    <div data-tour="deposit-tour-success">
      <CrossChainSecurityStepper activeStage="complete" />
      <div className="cross-chain-success-amount">
        ✅ {formatCurrency(record.amount)} {record.assetId} delivered to{" "}
        {record.mode === "deposit" ? "Morpheum" : record.chain}
      </div>
      {newBalance != null ? (
        <p className="cross-chain-success-balance">
          {balanceLabel(record, newBalance)}
        </p>
      ) : null}
      <div className="cross-chain-tx-links">
        {record.originTxHash && (
          <p>
            Origin tx{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={onDemoLinkClick}
            >
              {shortHash(record.originTxHash)} ↗
            </button>
          </p>
        )}
        {record.destinationTxHash && (
          <p>
            Destination tx{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={onDemoLinkClick}
            >
              {shortHash(record.destinationTxHash)} ↗
            </button>
          </p>
        )}
        {record.messageId && (
          <p>
            Hyperlane msg{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={onDemoLinkClick}
            >
              {shortHash(record.messageId)} ↗
            </button>
          </p>
        )}
      </div>
      <div className="cross-chain-success-actions">
        {showBucketHandoff && record.mode === "deposit" && record.assetId === "USDC" ? (
          <button
            type="button"
            className="btn btn-primary"
            onClick={onFundBucket}
            data-tour="deposit-tour-fund-bucket"
          >
            Fund a bucket →
          </button>
        ) : null}
        <button type="button" className="btn btn-secondary" onClick={onNewTransfer}>
          New transfer
        </button>
      </div>
    </div>
  );
}
