import type { PropertyChartEvent, PropertyCharts, PropertyReceipt } from "./types";
import type { AgentKpiHistoryFile } from "./agentKpiHistory.types";
import type { FleetTradeEvent } from "./fleetTradeHistory.types";
import { getFleetAgentByCatalogId } from "./fleetCatalog";

const BASE_EQUITY = 100;

export function buildFleetPnlCurve(events: FleetTradeEvent[]): number[] {
  const sorted = [...events].sort((a, b) =>
    a.timestamp.localeCompare(b.timestamp),
  );
  let cumulative = BASE_EQUITY;
  const curve = [cumulative];
  for (const event of sorted) {
    if (event.closedPnl != null) {
      cumulative = Math.round((cumulative + event.closedPnl) * 100) / 100;
    }
    curve.push(cumulative);
  }
  if (curve.length < 8) {
    while (curve.length < 11) {
      curve.push(curve.at(-1) ?? BASE_EQUITY);
    }
  }
  return curve.slice(-11);
}

function formatUsd(value: number): string {
  const sign = value >= 0 ? "+" : "";
  if (Math.abs(value) >= 1000) {
    return `${sign}$${(value / 1000).toFixed(1)}k`;
  }
  return `${sign}$${value.toFixed(0)}`;
}

export function fleetEventsToExecutionFeed(
  events: FleetTradeEvent[],
): PropertyChartEvent[] {
  return [...events]
    .sort((a, b) => b.timestamp.localeCompare(a.timestamp))
    .slice(0, 12)
    .map((event) => {
      const time = new Date(event.timestamp);
      const hh = String(time.getUTCHours()).padStart(2, "0");
      const mm = String(time.getUTCMinutes()).padStart(2, "0");
      const pnl =
        event.closedPnl != null ? formatUsd(event.closedPnl) : formatUsd(0);
      return {
        time: `${hh}:${mm}`,
        event: `${event.action} ${event.coin} · ${event.amountUsd.toFixed(0)} USD`,
        result: pnl,
      };
    });
}

export function fleetEventsToReceipts(
  events: FleetTradeEvent[],
  catalogAgentId: string,
): PropertyReceipt[] {
  const fleet = getFleetAgentByCatalogId(catalogAgentId);
  const recent = [...events]
    .sort((a, b) => b.timestamp.localeCompare(a.timestamp))
    .slice(0, 4);

  const txReceipts: PropertyReceipt[] = recent.map((event) => ({
    title: `Tx ${event.txSimHash.slice(0, 14)}…`,
    description: `${event.action} ${event.coin} signed by agent wallet · simulated on-chain`,
  }));

  return [
    {
      title: "Agent wallet proof",
      description: `Deployer ${fleet?.agentWallet.slice(0, 10)}… acts autonomously on simulated chain.`,
    },
    {
      title: "Master disclosure",
      description: `Supervised by ${fleet?.masterWallet.slice(0, 10)}… (view-only transparency).`,
    },
    ...txReceipts,
  ];
}

export function buildFleetCharts(
  events: FleetTradeEvent[],
  catalogAgentId: string,
  kpiHistory?: AgentKpiHistoryFile | null,
): PropertyCharts {
  const fleetCharts = buildFleetChartsFromTrades(events, catalogAgentId);
  if (!kpiHistory) return fleetCharts;

  const pnlCurve = kpiHistory.series.equityUsd.map((point) => point.value);
  const revenueHistory = kpiHistory.series.cumulativeRevenueUsd.map(
    (point) => point.value,
  );

  return {
    ...fleetCharts,
    pnlCurve,
    revenueHistory,
  };
}

function buildFleetChartsFromTrades(
  events: FleetTradeEvent[],
  catalogAgentId: string,
): PropertyCharts {
  const pnlCurve = buildFleetPnlCurve(events);
  const last = pnlCurve.at(-1) ?? BASE_EQUITY;
  const first = pnlCurve[0] ?? BASE_EQUITY;
  const delta = last - first;

  const revenueHistory = pnlCurve.map((point, index) =>
    Math.max(1, Math.round((point - BASE_EQUITY) * 0.35 + index * 0.8)),
  );

  const forecast = Array.from({ length: 7 }, (_, index) => {
    const slope = delta / Math.max(pnlCurve.length - 1, 1);
    return Math.round(last + slope * (index + 1) * 0.6);
  });

  return {
    pnlCurve,
    revenueHistory,
    forecast,
    executionFeed: fleetEventsToExecutionFeed(events),
    receiptsFeed: fleetEventsToReceipts(events, catalogAgentId),
  };
}
