import { mockAgentProfiles } from "../../offline/mock_data";
import type {
  PropertyIndexConstituent,
  PropertyIndexMode,
  PropertyIndexProfile,
  PropertyProfile,
} from "../../offline/mock_data/types";

export type ResolvedIndexConstituent = PropertyIndexConstituent;

function parseRevenue30d(agent: PropertyProfile): number {
  const stat = agent.quickStats.find((item) => item.label === "30d revenue");
  if (!stat) return 0;
  const numeric = Number(stat.value.replace(/[^\d.]/g, "") ?? 0);
  return numeric * 1000;
}

function synthesizeConstituent(
  agent: PropertyProfile,
  weight: number,
): PropertyIndexConstituent {
  return {
    agentId: agent.id,
    name: agent.name,
    ticker: agent.ticker,
    icon: agent.avatar,
    sector: agent.sector,
    weight,
    revenue30d: parseRevenue30d(agent),
    liquidityScore: 75,
    navContribution: 0,
    rationale: agent.strategySummary.slice(0, 80),
  };
}

function lookupAgent(agentId: string, agentProfiles: PropertyProfile[]): PropertyProfile | undefined {
  return agentProfiles.find((agent) => agent.id === agentId);
}

function resolveConstituentsByAgentIds(
  profile: PropertyIndexProfile,
  agentIds: readonly string[],
  agentProfiles: PropertyProfile[] = mockAgentProfiles,
): ResolvedIndexConstituent[] {
  const profileById = new Map(
    profile.constituents.map((item) => [item.agentId, item]),
  );

  const raw: PropertyIndexConstituent[] = [];
  for (const agentId of agentIds) {
    const existing = profileById.get(agentId);
    if (existing) {
      raw.push(existing);
      continue;
    }
    const agent = lookupAgent(agentId, agentProfiles);
    if (agent) {
      raw.push(synthesizeConstituent(agent, 0));
    }
  }

  if (raw.length === 0) return profile.constituents;

  const weightTotal = raw.reduce((sum, item) => sum + item.weight, 0);
  if (weightTotal <= 0) {
    const evenWeight = Math.round(100 / raw.length);
    return raw.map((item, index) => ({
      ...item,
      weight:
        index === raw.length - 1
          ? 100 - evenWeight * (raw.length - 1)
          : evenWeight,
    }));
  }

  return raw.map((item) => ({
    ...item,
    weight: Math.round((item.weight / weightTotal) * 1000) / 10,
  }));
}

/**
 * Resolve constituents for an index mode, synthesizing missing agents and
 * re-normalizing weights to sum to 100%.
 */
export function resolveConstituentsForMode(
  profile: PropertyIndexProfile,
  modeId: PropertyIndexMode["id"],
  agentProfiles: PropertyProfile[] = mockAgentProfiles,
): ResolvedIndexConstituent[] {
  const mode = profile.modes.find((entry) => entry.id === modeId);
  if (!mode) return profile.constituents;

  return resolveConstituentsByAgentIds(
    profile,
    mode.constituentIds,
    agentProfiles,
  );
}

/**
 * Union of every constituent id across all index modes — for index-wide feeds
 * (e.g. X pulse) that should not change when the active mode tab changes.
 */
export function resolveConstituentsUnion(
  profile: PropertyIndexProfile,
  agentProfiles: PropertyProfile[] = mockAgentProfiles,
): ResolvedIndexConstituent[] {
  const unionIds = [
    ...new Set(profile.modes.flatMap((mode) => mode.constituentIds)),
  ];

  if (unionIds.length === 0) return profile.constituents;

  return resolveConstituentsByAgentIds(profile, unionIds, agentProfiles);
}
