import { useCallback, useState } from "react";
import { toast } from "sonner";
import { useFiClient } from "../../hooks/useFiClient";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import { applyDemoWithdrawFromBucket } from "../../../offline/mock_data";

export interface UseBucketWithdrawOptions {
  baseURL: string;
  walletAddress?: string;
  mnemonic?: string;
}

export function useBucketWithdraw({
  baseURL,
  walletAddress,
  mnemonic,
}: UseBucketWithdrawOptions) {
  const { client: exchangeClient, isReady: exchangeReady } = useFiClient({
    baseURL,
    mnemonic: mnemonic ?? "",
  });
  const [isWithdrawing, setIsWithdrawing] = useState(false);
  const isOffline = isOfflineMode(baseURL);

  const withdrawToSpot = useCallback(
    async (bucketId: string, amount: number) => {
      if (!Number.isFinite(amount) || amount <= 0) {
        throw new Error("Withdraw amount must be greater than zero");
      }

      setIsWithdrawing(true);
      try {
        if (isOffline) {
          if (!walletAddress?.trim()) {
            throw new Error("Wallet address is required");
          }
          const transferId = `offline:withdraw:${bucketId}:${Date.now()}`;
          const result = applyDemoWithdrawFromBucket(walletAddress, {
            bucketId,
            amount,
            transferId,
          });
          toast.success("Withdrawal complete", {
            description: `$${amount.toFixed(2)} sent to your spot account`,
          });
          return result;
        }

        if (!exchangeClient || !exchangeReady) {
          throw new Error("Exchange client is not ready");
        }

        const result = await exchangeClient.withdrawFromBucket({
          bucketId,
          assetId: "USDC",
          amount,
        });
        if (!result.success) {
          throw new Error("Withdrawal failed");
        }
        toast.success("Withdrawal complete", {
          description: `$${amount.toFixed(2)} sent to your spot account`,
        });
        return result;
      } finally {
        setIsWithdrawing(false);
      }
    },
    [isOffline, walletAddress, exchangeClient, exchangeReady],
  );

  return { withdrawToSpot, isWithdrawing, isOffline };
}
