import type { ControlDepth } from "../intentwindow/adaptive";
import {
  applyAgentToBreakdown,
  applyAssetToBreakdown,
  applyStickyArchetype,
  canDeployBreakdown,
  resolveIntentBreakdown,
} from "../intentwindow/resolveIntentBreakdown";
import {
  buildExecutionContract,
  serializeExecutionContract,
  serializeIntentBreakdown,
  type ContractOverrides,
  type ExecutionContract,
} from "../intentwindow/executionContract";
import { enrichIntentBreakdown } from "../../services/intentEnrich";
import { shortHashId } from "../../utils/hashId";
import { getDisplayMarginType } from "../../sdk/types/data";
import { WalletConnectedGate } from "../wallet";
import {
  DEFAULT_BASE_URL,
  DEFAULT_MNEMONIC,
  LEVERAGE_MIN,
  LEVERAGE_MAX,
  SIZE_PERCENT_MIN,
  SIZE_PERCENT_MAX,
  SIZE_PERCENT_STEP,
  SIZE_PERCENT_PRESETS,
  PRICE_STEP,
  PRICE_MIN,
  CURRENCY_MIN_FRACTION_DIGITS,
  SIZE_DISPLAY_DECIMALS,
  ORDER_TYPE_MARKET,
  ORDER_TYPE_LIMIT,
  MARGIN_MODE_CROSS,
  MARGIN_MODE_ISOLATED,
  ORDER_SIDE_LONG,
  ORDER_SIDE_SHORT,
  
} from "../../constants";
import { useSubscription } from "../../context/SubscriptionContext";
import { useOptionalSettings } from "../../context/SettingsContext";
import {
  formatKeyboardBindingLabel,
  getDefaultBindingForAction,
} from "../../utils/keyboardShortcuts";
import { useAgentTaskStore } from "../../store/agentTaskStore";
import { useTradingAgentStore } from "../../store/tradingAgentStore";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import { OrderTypeSelector } from "./OrderTypeSelector";
import { AdvancedOrderFields } from "./AdvancedOrderFields";
import {
  DEFAULT_ADVANCED_ORDER_PARAMS,
  type AdvancedOrderParams,
  type AdvancedOrderTypeId,
} from "../../configs/advancedOrderTypes";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./tradepanel.css";

export interface TradeOperationRef {
  leverage: number;
  setLeverage: (leverage: number) => void;
  calculateMaxRatio: (tempLeverage: number) => string;
  changeLeverage: (
    newLeverage: number,
    options?: {
      bucketId?: string;
      leverageType?: string;
      reason?: string;
    },
  ) => Promise<void>;
  setPrice: (price: number | string) => void;
  setSizeInput: (size: number) => void;
  getSizeInput: () => number;
  getAvailableTradeAmount: () => number;
}

type TradeMode = "manual" | "agent";
type TradeSide = typeof ORDER_SIDE_LONG | typeof ORDER_SIDE_SHORT;

const TRADE_MODE_TABS = [
  { id: "manual", label: "Manual", bubbleTipId: BUBBLE_TIP_IDS.tradeModeManual },
  { id: "agent", label: "Intent", bubbleTipId: BUBBLE_TIP_IDS.tradeModeIntent },
] as const;

type TradeOperationPanelVariant = "full" | "override";

interface TradeOperationProps {
  baseURL?: string;
  mnemonic?: string;
  marketId?: string;
  marketSymbol?: string; // Optional - will be auto-derived from selected market if not provided
  selectedBucketBalance?: number; // Balance from selected bucket (nominalValue)
  selectedBucketId?: string | null; // Bucket ID for display in label
  onLeverageClick?: () => void; // Callback when leverage badge is clicked
  onNumberCalculatorClick?: () => void; // Callback when number calculator icon is clicked
  authToken?: string; // Auth token for API calls
  walletAddress?: string; // Wallet address for fetching bucket data
  isDesktop?: boolean;
  height?: string;
  /** Deck accordion: manual orders only — no Manual/Intent tabs or intent composer */
  panelVariant?: TradeOperationPanelVariant;
  /** Opens bucket autonomy rules for the active bucket. */
  onOpenBucketRules?: (bucketId: string) => void;
  /** Opens cross-chain deposit when balance is insufficient. */
  onRequestFundAccount?: () => void;
  /** Starts guided deposit tour from the order panel. */
  onRequestDepositTour?: () => void;
}

const TradeOperation = forwardRef<TradeOperationRef, TradeOperationProps>(
  function TradeOperation(
    {
      baseURL = DEFAULT_BASE_URL,
      mnemonic = DEFAULT_MNEMONIC,
      marketId,
      marketSymbol,
      selectedBucketBalance,
      selectedBucketId,
      onLeverageClick,
      onNumberCalculatorClick,
      authToken,
      walletAddress,
      isDesktop = true,
      height,
      panelVariant = "full",
      onOpenBucketRules,
      onRequestFundAccount,
      onRequestDepositTour,
    },
    ref,
  ): JSX.Element {
    const isOverridePanel = panelVariant === "override";
    const { client: subscriptionClient } = useSubscription();
    const settingsContext = useOptionalSettings();
    // Get selected market info from useMarkets hook
    const { selectedMarketId, selectedMarketSymbol, selectedMarket, markets } = useMarkets({
      baseURL,
      autoFetchMarkets: true,
    });
    const { agents } = useTradingAgents();

    // Determine the market ID to use (prop takes precedence, then selectedMarketId)
    const effectiveMarketId = marketId || selectedMarketId || "";

    // Derive market symbol: prop > selectedMarketSymbol > fallback
    const effectiveMarketSymbol = marketSymbol || selectedMarketSymbol || "";

    // Get trade price from useTradePrice hook for market orders
    const { lastPrice: tradePriceData } = useTradePrice({
      subscriptionClient,
      baseURL,
      marketId: effectiveMarketId,
    });

    // Extract trade price for market orders
    const tradePrice = tradePriceData?.price || 0;
    // Ref to store the loading toast ID so we can dismiss it later
    const sizeInputRef = useRef<HTMLInputElement>(null);
    const loadingToastIdRef = useRef<ToastId | null>(null);
    // Ref to store the leverage change loading toast ID
    const leverageLoadingToastIdRef = useRef<ToastId | null>(null);
    // Ref to track if we're currently changing leverage (to distinguish from order results)
    const isChangingLeverageRef = useRef<boolean>(false);

    const [tradeMode, setTradeMode] = useState<TradeMode>("agent");
    const [tradeSide, setTradeSide] = useState<TradeSide>(ORDER_SIDE_LONG);
    const [advancedPanelOpen, setAdvancedPanelOpen] = useState(false);
    const [selectedAdvancedType, setSelectedAdvancedType] =
      useState<AdvancedOrderTypeId | null>(null);
    const [advancedParams, setAdvancedParams] = useState<AdvancedOrderParams>(
      DEFAULT_ADVANCED_ORDER_PARAMS,
    );
    const [agentIntentText, setAgentIntentText] = useState("");
    const [agentIntentValidated, setAgentIntentValidated] = useState(false);
    const [intentResolution, setIntentResolution] =
      useState<IntentResolution | null>(null);
    const [intentBreakdown, setIntentBreakdown] =
      useState<IntentBreakdown | null>(null);
    const [executionContract, setExecutionContract] =
      useState<ExecutionContract | null>(null);
    const [contractOverrides, setContractOverrides] = useState<ContractOverrides>(
      {},
    );
    const [controlDepth, setControlDepth] = useState<ControlDepth>("simple");
    const [stickyArchetype, setStickyArchetype] = useState<
      import("../intentwindow/intentBreakdown").IntentArchetype | undefined
    >(undefined);
    const [intentWindowOpen, setIntentWindowOpen] = useState(false);
    const validateDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(
      null,
    );
    const pendingEdit = useAgentTaskStore((s) => s.pendingEdit);
    const setPendingEdit = useAgentTaskStore((s) => s.setPendingEdit);
    const addAgentTask = useAgentTaskStore((s) => s.addTask);
    const resolveDefaultAgentId = useTradingAgentStore(
      (s) => s.resolveDefaultAgentId,
    );

    useEffect(() => {
      if (isOverridePanel || !pendingEdit) return;
      setTradeMode("agent");
      setAgentIntentText(pendingEdit.description);
      const breakdown = resolveIntentBreakdown({
        text: pendingEdit.description,
        agents,
        markets,
        context: {
          defaultAgentId: resolveDefaultAgentId(),
          defaultMarketId: effectiveMarketId || null,
          chartMarketId: effectiveMarketId || null,
        },
      });
      setIntentBreakdown(breakdown);
      setIntentResolution(breakdown.resolution);
      setAgentIntentValidated(canDeployBreakdown(breakdown));
      setPendingEdit(null);
    }, [
      isOverridePanel,
      pendingEdit,
      setPendingEdit,
      agents,
      markets,
      resolveDefaultAgentId,
      effectiveMarketId,
    ]);

    // Get bucket collections data if walletAddress and authToken are provided
    const { collections, spotWalletBalance } = useBucketCollections({
      subscriptionClient,
      baseURL,
      walletAddress: walletAddress || "",
      authToken: authToken || "",
      useWebSocket: !!walletAddress && !!authToken, // Only use WebSocket if we have both
    });

    // Find the selected bucket from collections
    const selectedBucket = useMemo(() => {
      if (!selectedBucketId || !collections.length) return null;
      return (
        collections.find(
          (collection) => collection.bucketId === selectedBucketId,
        ) || null
      );
    }, [collections, selectedBucketId]);

    const {
      orderType,
      setOrderType,
      fundPercent,
      sizeInput,
      price,
      leverage,
      marginMode,
      availableBalance,
      currentPrice,
      isReady,
      loading,
      result,
      setFundPercent,
      setSizeInput,
      setPrice,
      setMarginMode,
      setLeverage,
      placeBuyOrder,
      placeSellOrder,
      changeLeverage: changeLeverageAPI,
      calculateValue,
      calculateMargin,
      calculateSizeUSD,
      getOrderPrice,
      getAvailableTradeAmount,
    } = useTradeOperation({
      baseURL,
      mnemonic,
      marketId: effectiveMarketId,
      marketSymbol: effectiveMarketSymbol,
      selectedBucketBalance,
      selectedBucketId: selectedBucketId || undefined, // Pass bucket ID for order placement
      tradePrice, // Pass trade price for market orders
    });

    // Memoize calculations from hook - depend on actual state values for proper updates
    const orderPrice = useMemo(
      () => getOrderPrice(),
      [getOrderPrice, orderType, price, currentPrice],
    );
    const availableTradeAmount = useMemo(
      () => getAvailableTradeAmount(),
      [getAvailableTradeAmount, availableBalance, leverage],
    );
    const value = useMemo(
      () => calculateValue(),
      [
        calculateValue,
        sizeInput,
        fundPercent,
        availableBalance,
        orderPrice,
        leverage,
      ],
    );
    const margin = useMemo(
      () => calculateMargin(),
      [calculateMargin, leverage, value],
    );

    // Convert value and margin from satoshi to decimal for display
    const valueDecimal = useMemo(() => {
      return fromSatoshi(String(value));
    }, [value]);

    const marginDecimal = useMemo(() => {
      return fromSatoshi(String(margin));
    }, [margin]);

    // Memoize current price display
    const currentPriceDisplay = useMemo(
      () => currentPrice.toFixed(CURRENCY_MIN_FRACTION_DIGITS),
      [currentPrice],
    );

    // Automatically switch margin mode based on selected bucket
    useEffect(() => {
      if (selectedBucket) {
        const bucketMarginType = getDisplayMarginType(selectedBucket);
        if (
          bucketMarginType === MARGIN_MODE_CROSS ||
          bucketMarginType === MARGIN_MODE_ISOLATED
        ) {
          setMarginMode(bucketMarginType);
        }
      }
    }, [selectedBucket, setMarginMode]);



    const handleSelectMarket = useCallback(() => {
      setOrderType(ORDER_TYPE_MARKET);
      setSelectedAdvancedType(null);
      setAdvancedPanelOpen(false);
    }, [setOrderType]);

    const handleSelectLimit = useCallback(() => {
      setOrderType(ORDER_TYPE_LIMIT);
      setSelectedAdvancedType(null);
      setAdvancedPanelOpen(false);
    }, [setOrderType]);

    const handleToggleAdvancedPanel = useCallback(() => {
      setAdvancedPanelOpen((prev) => !prev);
    }, []);

    const handleSelectAdvancedType = useCallback((type: AdvancedOrderTypeId) => {
      setSelectedAdvancedType(type);
      setAdvancedPanelOpen(true);
    }, []);

    const handleAdvancedParamsChange = useCallback(
      (patch: Partial<AdvancedOrderParams>) => {
        setAdvancedParams((prev) => ({ ...prev, ...patch }));
      },
      [],
    );

    const handleTradeSideLong = useCallback(() => {
      setTradeSide(ORDER_SIDE_LONG);
    }, []);

    const handleTradeSideShort = useCallback(() => {
      setTradeSide(ORDER_SIDE_SHORT);
    }, []);

    const handleFundPercentIncrease = useCallback(() => {
      setFundPercent(
        Math.min(SIZE_PERCENT_MAX, fundPercent + SIZE_PERCENT_STEP),
      );
    }, [fundPercent, setFundPercent]);

    const handleFundPercentDecrease = useCallback(() => {
      setFundPercent(
        Math.max(SIZE_PERCENT_MIN, fundPercent - SIZE_PERCENT_STEP),
      );
    }, [fundPercent, setFundPercent]);

    const handlePriceChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        setPrice(parseFloat(e.target.value));
      },
      [setPrice],
    );

    // Track if size input is focused and the value while user is typing
    const [isSizeInputFocused, setIsSizeInputFocused] = useState(false);
    const [sizeInputDisplayValue, setSizeInputDisplayValue] =
      useState<string>("");

    const handleSizePresetClick = useCallback(
      (percent: number) => {
        setIsSizeInputFocused(false);
        setSizeInputDisplayValue("");
        sizeInputRef.current?.blur();
        setFundPercent(percent);
      },
      [setFundPercent],
    );

    const isPresetActive = useCallback(
      (preset: number) => !isSizeInputFocused && fundPercent === preset,
      [isSizeInputFocused, fundPercent],
    );

    const handleSizeInputChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        const inputValue = e.target.value;
        // Store what user is typing (allows partial input like "1." or "1.12")
        setSizeInputDisplayValue(inputValue);
        // Update the actual sizeInput value (for calculations)
        const val = parseFloat(inputValue);
        const roundedVal = isNaN(val) ? 0 : Math.round(val * 1000000) / 1000000;
        setSizeInput(roundedVal); // This will update fundPercent via the hook
      },
      [setSizeInput],
    );

    const handleSizeInputFocus = useCallback(() => {
      setIsSizeInputFocused(true);
      // When focusing, initialize with current formatted value
      setSizeInputDisplayValue(formatSizeInputValue(sizeInput));
    }, [sizeInput]);

    const handleSizeInputBlur = useCallback(() => {
      setIsSizeInputFocused(false);
      // When blurring, parse and format the final value
      const val = parseFloat(sizeInputDisplayValue);
      //const roundedVal = isNaN(val) ? 0 : Math.round(val * 1000000) / 1000000;
      setSizeInput(val);
      // Clear display value so it will use formatted sizeInput when not focused
      setSizeInputDisplayValue("");
    }, [sizeInputDisplayValue, setSizeInput]);

    const handlePlaceOrder = useCallback(() => {
      const isLong = tradeSide === ORDER_SIDE_LONG;
      const loadingId = toastLoading("Submit transaction...", {
        description: isLong ? "Placing long order" : "Placing short order",
      });
      loadingToastIdRef.current = loadingId;
      if (isLong) {
        placeBuyOrder();
      } else {
        placeSellOrder();
      }
    }, [tradeSide, placeBuyOrder, placeSellOrder]);

    const baseAsset = resolveBaseAsset(
      selectedMarket,
      effectiveMarketSymbol || selectedMarketSymbol,
    );

    const bucketLabel =
      selectedBucketId && selectedBucketId !== "--"
        ? shortHashId(selectedBucketId)
        : undefined;

    const runIntentBreakdown = useCallback(
      (text: string): IntentBreakdown => {
        return resolveIntentBreakdown({
          text,
          agents,
          markets,
          context: {
            defaultAgentId: resolveDefaultAgentId(),
            defaultMarketId: effectiveMarketId || null,
            chartMarketId: effectiveMarketId || null,
          },
          stickyArchetype,
          bucketLabel,
        });
      },
      [
        agents,
        markets,
        resolveDefaultAgentId,
        effectiveMarketId,
        stickyArchetype,
        bucketLabel,
      ],
    );

    const refreshContract = useCallback(
      (
        breakdown: IntentBreakdown,
        overrides: ContractOverrides = contractOverrides,
      ) => {
        const agentId = breakdown.resolution.agent.value?.id;
        const agent = agentId
          ? agents.find((a) => a.id === agentId) ?? null
          : null;
        const contract = buildExecutionContract(breakdown, {
          entryPrice: tradePrice || 0,
          bucketLabel,
          marginMode: marginMode === MARGIN_MODE_CROSS ? "CROSS" : "ISOLATED",
          defaultLeverage: leverage,
          defaultSizePct: 20,
          bucketBalance: availableBalance,
          agent,
          assetSymbol:
            breakdown.resolution.asset.value?.symbol ??
            breakdown.resolution.asset.label,
        }, overrides);
        setExecutionContract(contract);
      },
      [
        agents,
        tradePrice,
        bucketLabel,
        marginMode,
        leverage,
        availableBalance,
        contractOverrides,
      ],
    );

    const applyBreakdownState = useCallback(
      (breakdown: IntentBreakdown, overrides?: ContractOverrides) => {
        setIntentBreakdown(breakdown);
        setIntentResolution(breakdown.resolution);
        setAgentIntentValidated(
          breakdown.deployState !== "resolve" &&
            breakdown.qualification === "qualified" &&
            !breakdown.isParked,
        );
        refreshContract(breakdown, overrides ?? contractOverrides);
      },
      [contractOverrides, refreshContract],
    );

    const runIntentResolution = useCallback(
      (text: string): IntentResolution => {
        return runIntentBreakdown(text).resolution;
      },
      [runIntentBreakdown],
    );

    const handleAgentIntentTextChange = useCallback((value: string) => {
      setAgentIntentText(value);
      setAgentIntentValidated(false);
      setIntentResolution(null);
      setIntentBreakdown(null);
      setExecutionContract(null);
    }, []);

    const handleAgentIntentValidate = useCallback(async () => {
      const trimmed = agentIntentText.trim();
      if (!trimmed) {
        toast.error("Intent required", {
          description: "Enter a trade intent before parsing.",
        });
        return;
      }
      setAgentIntentText(trimmed);
      let breakdown = runIntentBreakdown(trimmed);
      breakdown = await enrichIntentBreakdown(breakdown, {
        baseURL,
        authToken,
      });
      applyBreakdownState(breakdown);

      if (breakdown.isParked) {
        toast.info("Strategy parked", {
          description: breakdown.parkedReason,
        });
        return;
      }

      if (breakdown.qualification === "non-intent") {
        toast.info("Not a trade intent", {
          description: "This looks like a question or navigation command.",
        });
        return;
      }

      if (breakdown.deployState === "resolve") {
        const facet = breakdown.blockingFacet ?? breakdown.blockingSlot;
        toast.error(`Resolve ${facet ?? "slots"}`, {
          description: breakdown.clarifyPrompt ?? "Pick missing values before deploying.",
        });
        return;
      }

      toast.success("Intent validated", {
        description: getResolutionSummary(breakdown.resolution),
      });
    }, [
      agentIntentText,
      runIntentBreakdown,
      applyBreakdownState,
      baseURL,
      authToken,
    ]);

    const scheduleBlurValidate = useCallback(() => {
      if (validateDebounceRef.current) {
        clearTimeout(validateDebounceRef.current);
      }
      validateDebounceRef.current = setTimeout(() => {
        if (agentIntentText.trim()) {
          void handleAgentIntentValidate();
        }
      }, 400);
    }, [agentIntentText, handleAgentIntentValidate]);

    const handleValidateIntentText = useCallback(
      async (text: string, instanceId?: string | null) => {
        const trimmed = text.trim();
        if (!trimmed) {
          toast.error("Intent required", {
            description: "Enter a trade intent before parsing.",
          });
          return;
        }
        setAgentIntentText(trimmed);
        let breakdown = runIntentBreakdown(trimmed);
        breakdown = await enrichIntentBreakdown(breakdown, {
          baseURL,
          authToken,
        });
        applyBreakdownState(breakdown);
        if (
          breakdown.deployState !== "resolve" &&
          !breakdown.isParked &&
          breakdown.qualification === "qualified"
        ) {
          toast.success("Intent validated", {
            description: getResolutionSummary(breakdown.resolution),
          });
        }
        return instanceId;
      },
      [runIntentBreakdown, applyBreakdownState, baseURL, authToken],
    );

    const openIntentWindow = useCallback(() => {
      setTradeMode("agent");
      setIntentWindowOpen(true);
    }, []);

    const openIntentWindowIfClosed = useCallback(() => {
      if (!intentWindowOpen) {
        openIntentWindow();
      }
    }, [intentWindowOpen, openIntentWindow]);

    const handleResolveAgent = useCallback(
      (agent: ResolvedAgent) => {
        setIntentBreakdown((prev) => {
          if (!prev) return prev;
          const next = applyAgentToBreakdown(
            prev,
            agent,
            effectiveMarketId || null,
          );
          setIntentResolution(next.resolution);
          setAgentIntentValidated(canDeployBreakdown(next));
          refreshContract(next);
          return next;
        });
      },
      [effectiveMarketId, refreshContract],
    );

    const handleResolveAsset = useCallback(
      (asset: ResolvedAsset) => {
        setIntentBreakdown((prev) => {
          if (!prev) return prev;
          const next = applyAssetToBreakdown(
            prev,
            asset,
            effectiveMarketId || null,
          );
          setIntentResolution(next.resolution);
          setAgentIntentValidated(canDeployBreakdown(next));
          refreshContract(next);
          return next;
        });
      },
      [effectiveMarketId, refreshContract],
    );

    const handleArchetypeOverride = useCallback(
      (archetype: import("../intentwindow/intentBreakdown").IntentArchetype) => {
        setStickyArchetype(archetype);
        setIntentBreakdown((prev) => {
          if (!prev) return prev;
          const next = applyStickyArchetype(prev, archetype);
          refreshContract(next);
          return next;
        });
      },
      [refreshContract],
    );

    const handleContractOverride = useCallback(
      (patch: ContractOverrides) => {
        setContractOverrides((prev) => {
          const next = { ...prev, ...patch };
          if (intentBreakdown) {
            refreshContract(intentBreakdown, next);
          }
          return next;
        });
      },
      [intentBreakdown, refreshContract],
    );

    const deployButtonLabel = intentBreakdown
      ? getDeployButtonLabel(intentBreakdown.deployState)
      : intentResolution
        ? getDeployButtonLabel(intentResolution.deployState)
        : getDeployButtonLabel("review");

    const deployDisabled =
      !agentIntentText.trim() ||
      !(intentBreakdown
        ? canDeployBreakdown(intentBreakdown)
        : canDeploy(intentResolution));

    useIntentWindowShortcut({
      enabled: isDesktop,
      isOpen: intentWindowOpen,
      onOpen: openIntentWindow,
    });

    const intentShortcutLabel = useMemo(() => {
      const binding =
        settingsContext?.settings.keyboardShortcuts.openIntentComposer ??
        getDefaultBindingForAction("openIntentComposer");
      return `${formatKeyboardBindingLabel(binding)} agent intent`;
    }, [settingsContext?.settings.keyboardShortcuts.openIntentComposer]);

    const handleDeployToAgent = useCallback(() => {
      const trimmed = agentIntentText.trim();
      if (!trimmed) {
        toast.error("Intent required", {
          description: "Enter a trade intent before deploying.",
        });
        return;
      }

      const breakdown = intentBreakdown;
      const resolution = breakdown?.resolution ?? intentResolution;

      if (breakdown && !canDeployBreakdown(breakdown)) {
        toast.error("Resolve before deploy", {
          description: "Parse & validate, then resolve any ambiguous slots.",
        });
        return;
      }

      if (!canDeploy(resolution)) {
        toast.error("Resolve before deploy", {
          description: "Parse & validate, then resolve any ambiguous slots.",
        });
        return;
      }

      const agentId =
        resolution?.agent.value?.id ?? resolveDefaultAgentId();
      const marketId =
        resolution?.asset.value?.marketId ?? (effectiveMarketId || null);

      const bucketId =
        selectedBucketId && selectedBucketId !== "--"
          ? selectedBucketId
          : null;

      const breakdownJson = breakdown
        ? serializeIntentBreakdown(breakdown)
        : null;
      const contractJson = executionContract
        ? serializeExecutionContract(executionContract)
        : null;
      const objectiveId = breakdown?.execution.groupId ?? null;
      const objectiveSummary =
        breakdown?.slots.objective.label ?? trimmed.slice(0, 80);
      const compositeLegsJson =
        breakdown?.execution.legs != null
          ? JSON.stringify(breakdown.execution.legs)
          : null;

      const baseTask = {
        description: trimmed,
        status: "pending" as const,
        bucketId,
        trigger: "Awaiting agent evaluation",
        eta: null,
        intentBreakdownJson: breakdownJson,
        executionContractJson: contractJson,
        objectiveId,
        objectiveSummary,
        compositeLegsJson,
      };

      if (breakdown?.execution.kind === "fanout" && breakdown.slots.assets.value) {
        for (const asset of breakdown.slots.assets.value) {
          const m = markets.find(
            (mk) => mk.baseAsset?.toUpperCase() === asset.toUpperCase(),
          );
          addAgentTask({
            ...baseTask,
            agentId,
            marketId: m ? (m.index ?? m.marketIndex ?? marketId) : marketId,
          });
        }
      } else {
        addAgentTask({
          ...baseTask,
          agentId,
          marketId,
        });
      }

      setAgentIntentText("");
      setAgentIntentValidated(false);
      setIntentResolution(null);
      setIntentBreakdown(null);
      setExecutionContract(null);
      setContractOverrides({});
      toast.success("Deployed to autonomous agent", {
        description: "Task added to Agent Tasks tab.",
      });
    }, [
      agentIntentText,
      intentBreakdown,
      intentResolution,
      executionContract,
      addAgentTask,
      resolveDefaultAgentId,
      effectiveMarketId,
      selectedBucketId,
      markets,
    ]);

    // Handle leverage change with API call
    const handleChangeLeverage = useCallback(
      async (
        newLeverage: number,
        options?: {
          bucketId?: string;
          leverageType?: string;
          reason?: string;
        },
      ) => {
        // Set flag to indicate we're changing leverage
        isChangingLeverageRef.current = true;

        // Show loading toast
        const loadingId = toastLoading("Changing leverage...", {
          description: `Updating leverage to ${newLeverage}x`,
        });
        leverageLoadingToastIdRef.current = loadingId;

        try {
          // Determine leverage type from margin mode if not provided
          const leverageType =
            options?.leverageType ||
            (marginMode === MARGIN_MODE_CROSS ? "cross" : "isolated");

          // Use selectedBucketId if bucketId is not provided
          const bucketId = options?.bucketId || selectedBucketId || "";

          await changeLeverageAPI(newLeverage, {
            ...options,
            bucketId,
            leverageType,
          });

          // The result will be handled by the useEffect below
        } catch (error) {
          // Reset flag on error
          isChangingLeverageRef.current = false;

          const errorMessage =
            error instanceof Error ? error.message : "Unknown error";
          toastCompleteError(loadingId, "Leverage Change Failed", {
            description: errorMessage,
            action: createErrorCopyAction(errorMessage),
          });
          leverageLoadingToastIdRef.current = null;
        }
      },
      [changeLeverageAPI, marginMode, selectedBucketId],
    );

    // Expose leverage and setLeverage via ref
    useImperativeHandle(
      ref,
      () => ({
        leverage,
        setLeverage,
        calculateMaxRatio: (tempLeverage: number) => {
          const sizeUSD = calculateSizeUSD();
          const orderValueAtLeverage = sizeUSD;
          return availableBalance > 0 && orderValueAtLeverage > 0
            ? (orderValueAtLeverage / availableBalance).toFixed(
                CURRENCY_MIN_FRACTION_DIGITS,
              )
            : tempLeverage.toFixed(CURRENCY_MIN_FRACTION_DIGITS);
        },
        changeLeverage: handleChangeLeverage,
        setPrice: (price: number | string) => {
          const numPrice =
            typeof price === "number" ? price : parseFloat(price);
          if (!isNaN(numPrice)) {
            setPrice(numPrice);
          }
        },
        setSizeInput: (size: number) => {
          setSizeInput(size);
        },
        getSizeInput: () => sizeInput,
        getAvailableTradeAmount: () => availableTradeAmount,
      }),
      [
        leverage,
        setLeverage,
        calculateSizeUSD,
        getOrderPrice,
        availableBalance,
        handleChangeLeverage,
        setPrice,
        setSizeInput,
        sizeInput,
        availableTradeAmount,
      ],
    );

    // Show toast notifications when result changes (handles both orders and leverage changes)
    useEffect(() => {
      if (!result) return;

      // Check if this is a leverage change result
      if (isChangingLeverageRef.current) {
        // Reset flag
        isChangingLeverageRef.current = false;

        const leverageId = leverageLoadingToastIdRef.current;
        leverageLoadingToastIdRef.current = null;

        if (leverageId != null) {
          if (result.success) {
            const description = result.orderId
              ? `Transaction: ${result.orderId}`
              : result.message || "Leverage changed successfully";
            toastCompleteSuccess(leverageId, "Leverage Changed Successfully", {
              description,
            });
          } else if (result.error) {
            toastCompleteError(leverageId, "Leverage Change Failed", {
              description: result.error,
              action: createErrorCopyAction(result.error || ""),
            });
          }
        }
      } else {
        const orderId = loadingToastIdRef.current;
        loadingToastIdRef.current = null;

        if (orderId != null) {
          if (result.success) {
            const description = result.orderId
              ? `Order ID: ${result.orderId}`
              : result.message || "Order placed successfully";
            toastCompleteSuccess(orderId, "Order Placed Successfully", {
              description,
            });
          } else if (result.error) {
            toastCompleteError(orderId, "Order Failed", {
              description: result.error,
              action: createErrorCopyAction(result.error || ""),
            });
          }
        }
      }
    }, [result]);

    const showManualPanel = isOverridePanel || tradeMode === "manual";
    const showAgentPanel = !isOverridePanel && tradeMode === "agent";

    return (
      <div
        className={[
          "layout-container",
          "component",
          isOverridePanel ? "trade-op--override" : "",
          isDesktop && showAgentPanel ? "trade-op--agent-desktop" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        style={height ? { height } : undefined}
        data-tour="welcome-order-panel"
      >
        {!isOverridePanel ? (
          <TabLayoutHeaderToolBar
            tabs={[...TRADE_MODE_TABS]}
            activeTabId={tradeMode}
            onTabChange={(id) => setTradeMode(id as TradeMode)}
          />
        ) : null}
        <WalletConnectedGate walletAddress={walletAddress} variant="trade">
        {showManualPanel ? (
          <>
        {/* Trade Configuration Panel */}
        <div className="trade-op-config" data-tour="welcome-risk-controls">
          <BubbleTip id={BUBBLE_TIP_IDS.marginMode}>
            <div className="trade-op-badge">
              <span className="trade-op-badge-label">{marginMode}</span>
              {bucketLabel ? (
                <span
                  className="trade-op-badge-label trade-op-bucket-tag"
                  title={selectedBucketId ?? undefined}
                >
                  {bucketLabel}
                </span>
              ) : null}
            </div>
          </BubbleTip>
          <BubbleTip id={BUBBLE_TIP_IDS.leverageControl}>
            <div
              className="trade-op-badge"
              onClick={onLeverageClick}
              style={{ cursor: "pointer" }}
            >
              <span className="trade-op-badge-label">{leverage}x</span>
            </div>
          </BubbleTip>
        </div>
        {/* Order Type Selection */}
        <OrderTypeSelector
          orderType={orderType}
          selectedAdvancedType={selectedAdvancedType}
          advancedPanelOpen={advancedPanelOpen}
          onSelectMarket={handleSelectMarket}
          onSelectLimit={handleSelectLimit}
          onToggleAdvancedPanel={handleToggleAdvancedPanel}
          onSelectAdvancedType={handleSelectAdvancedType}
        />
        <BubbleTip id={BUBBLE_TIP_IDS.tradeSideSelector}>
          <div className="trade-op-side-selector">
          <button
            type="button"
            onClick={handleTradeSideLong}
            className={`btn-toggle ${tradeSide === ORDER_SIDE_LONG ? "active-long" : ""}`}
          >
            LONG
          </button>
          <button
            type="button"
            onClick={handleTradeSideShort}
            className={`btn-toggle ${tradeSide === ORDER_SIDE_SHORT ? "active-short" : ""}`}
          >
            SHORT
          </button>
        </div>
        </BubbleTip>
        {/* Limit Price Input (only for limit orders) */}
        {orderType === ORDER_TYPE_LIMIT && !selectedAdvancedType && (
          <div className="trade-op-form-group">
            <BubbleTip id={BUBBLE_TIP_IDS.limitPrice}>
              <div className="trade-op-form-row">
                <label htmlFor="price" className="trade-op-label">
                  Price:
                </label>
                <input
                  id="price"
                  type="number"
                  className="form-input trade-op-input"
                  value={price}
                  onChange={handlePriceChange}
                  placeholder={currentPriceDisplay}
                  step={PRICE_STEP}
                  min={PRICE_MIN}
                />
              </div>
            </BubbleTip>
          </div>
        )}

        {selectedAdvancedType ? (
          <AdvancedOrderFields
            selectedType={selectedAdvancedType}
            params={advancedParams}
            onParamsChange={handleAdvancedParamsChange}
            pricePlaceholder={currentPriceDisplay}
          />
        ) : null}

        {/* Order Size Input and Presets */}
        <div className="trade-op-form-group">
          {/* Size controls - on a new row */}
          <div className="trade-op-form-row" style={{ marginBottom: "0.5rem" }}>
            <BubbleTip id={BUBBLE_TIP_IDS.orderSize}>
              <label htmlFor="size" className="trade-op-label">
                Size:
              </label>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.sizeCalculator}>
              <span className="trade-op-icon" onClick={onNumberCalculatorClick}>
                <img src="cal.svg" />
              </span>
            </BubbleTip>
            <div className="trade-op-size-controls">
              <input
                ref={sizeInputRef}
                id="size"
                type="number"
                step="0.000001"
                value={isSizeInputFocused ? sizeInputDisplayValue : sizeInput}
                onChange={handleSizeInputChange}
                onFocus={handleSizeInputFocus}
                onBlur={handleSizeInputBlur}
                placeholder="0"
                min={PRICE_MIN}
                max={availableTradeAmount}
                className="form-input trade-op-input"
              />
              <div className="trade-op-size-buttons">
                <button
                  onClick={handleFundPercentIncrease}
                  className="btn-small"
                >
                  ▲
                </button>
                <button
                  onClick={handleFundPercentDecrease}
                  className="btn-small"
                >
                  ▼
                </button>
              </div>
            </div>
          </div>
          <BubbleTip id={BUBBLE_TIP_IDS.sizeSlider}>
            <div className="trade-op-size-presets">
              {SIZE_PERCENT_PRESETS.map((preset) => (
                <button
                  key={preset}
                  type="button"
                  onClick={() => handleSizePresetClick(preset)}
                  className={`btn-toggle${isPresetActive(preset) ? " active" : ""}`}
                >
                  {preset}%
                </button>
              ))}
            </div>
          </BubbleTip>
        </div>

        {/* Order action */}
        <div className="trade-op-action-panel">
          <div
            className={`trade-op-panel-title ${tradeSide === ORDER_SIDE_LONG ? "buy" : "sell"}`}
          >
            {tradeSide}
          </div>
          <div className="trade-op-panel-size">
            {sizeInput.toFixed(3)}/100.000
          </div>
          <BubbleTip id={BUBBLE_TIP_IDS.placeOrder}>
            <button
              type="button"
              onClick={handlePlaceOrder}
              disabled={
                loading ||
                !isReady ||
                value <= 0 ||
                selectedAdvancedType !== null
              }
              className={
                tradeSide === ORDER_SIDE_LONG
                  ? "btn-buy terminal-execution-button button-buy-long"
                  : "btn-sell terminal-execution-button button-sell-short"
              }
            >
              {loading ? "PLACING..." : "PLACE ORDER"}
            </button>
          </BubbleTip>
          {selectedAdvancedType ? (
            <div className="terminal-label trade-op-advanced-submit-note">
              Advanced order submission coming soon.
            </div>
          ) : null}
          <div className="trade-op-panel-details">
            <BubbleTip id={BUBBLE_TIP_IDS.orderValue}>
              <div>
                Value {valueDecimal.toFixed(CURRENCY_MIN_FRACTION_DIGITS)}
              </div>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.orderMargin}>
              <div>
                Margin {marginDecimal.toFixed(CURRENCY_MIN_FRACTION_DIGITS)}
              </div>
            </BubbleTip>
          </div>
        </div>
        <TradeOperationInfoPanel
          spotWalletBalance={spotWalletBalance}
          collections={collections}
          selectedBucketId={selectedBucketId}
          selectedBucket={selectedBucket}
          onOpenBucketRules={onOpenBucketRules}
          onRequestFundAccount={onRequestFundAccount}
          onRequestDepositTour={onRequestDepositTour}
          availableTradeBalance={availableBalance}
        />
          </>
        ) : null}
        {showAgentPanel ? (
          <AgentIntentSection
            selectedMarket={selectedMarket}
            selectedMarketSymbol={effectiveMarketSymbol || selectedMarketSymbol}
            spotWalletBalance={spotWalletBalance}
            collections={collections}
            selectedBucketId={selectedBucketId}
            selectedBucket={selectedBucket}
            agentIntentText={agentIntentText}
            agentIntentValidated={agentIntentValidated}
            onAgentIntentTextChange={handleAgentIntentTextChange}
            onParseValidate={handleAgentIntentValidate}
            onValidateIntentText={handleValidateIntentText}
            onDeployToAgent={handleDeployToAgent}
            onBlurValidate={scheduleBlurValidate}
            isDesktop={isDesktop}
            agents={agents}
            markets={markets}
            intentResolution={intentResolution}
            intentBreakdown={intentBreakdown}
            executionContract={executionContract}
            contractOverrides={contractOverrides}
            controlDepth={controlDepth}
            stickyArchetype={stickyArchetype}
            onArchetypeOverride={handleArchetypeOverride}
            onContractOverride={handleContractOverride}
            onControlDepthChange={setControlDepth}
            onOpenManual={() => setTradeMode("manual")}
            deployButtonLabel={deployButtonLabel}
            deployDisabled={deployDisabled}
            onResolveAgent={handleResolveAgent}
            onResolveAsset={handleResolveAsset}
            onOpenIntentWindow={
              isDesktop ? openIntentWindowIfClosed : undefined
            }
          />
        ) : null}
        {isDesktop && showAgentPanel ? (
          <BubbleTip id={BUBBLE_TIP_IDS.cmdAIntent}>
            <p className="intent-window-desktop-hint">{intentShortcutLabel}</p>
          </BubbleTip>
        ) : null}
        </WalletConnectedGate>
        {isDesktop && !isOverridePanel ? (
          <IntentWindowModal
            isOpen={intentWindowOpen}
            onClose={() => setIntentWindowOpen(false)}
            text={agentIntentText}
            onTextChange={handleAgentIntentTextChange}
            validated={agentIntentValidated}
            onValidate={handleAgentIntentValidate}
            onDeploy={handleDeployToAgent}
            baseAsset={baseAsset}
            marketSymbol={effectiveMarketSymbol || selectedMarketSymbol || undefined}
            bucketLabel={bucketLabel}
            marginMode={marginMode}
            agents={agents}
            markets={markets}
            intentResolution={intentResolution}
            intentBreakdown={intentBreakdown}
            executionContract={executionContract}
            contractOverrides={contractOverrides}
            controlDepth={controlDepth}
            stickyArchetype={stickyArchetype}
            onArchetypeOverride={handleArchetypeOverride}
            onContractOverride={handleContractOverride}
            onControlDepthChange={setControlDepth}
            onOpenManual={() => {
              setTradeMode("manual");
              setIntentWindowOpen(false);
            }}
            deployButtonLabel={deployButtonLabel}
            deployDisabled={deployDisabled}
            onResolveAgent={handleResolveAgent}
            onResolveAsset={handleResolveAsset}
          />
        ) : null}
      </div>
    );
  },
);

export type TradeOperationComponent = typeof TradeOperation;

export default TradeOperation;
