import type { JSX } from "react";
import type { IntentBreakdown } from "../intentBreakdown";
import { IntentAmbiguityPrompt } from "../IntentAmbiguityPrompt";

export interface IntentClarifyPromptProps {
  breakdown: IntentBreakdown;
  onSelectAgent?: (agent: import("../intentResolution").ResolvedAgent) => void;
  onSelectAsset?: (asset: import("../intentResolution").ResolvedAsset) => void;
}

export function IntentClarifyPrompt({
  breakdown,
  onSelectAgent,
  onSelectAsset,
}: IntentClarifyPromptProps): JSX.Element | null {
  if (breakdown.qualification === "underspecified" && breakdown.clarifyPrompt) {
    return (
      <div className="intent-clarify-prompt" role="alert">
        <span className="intent-clarify-icon" aria-hidden>
          ⚠
        </span>
        <span>{breakdown.clarifyPrompt}</span>
      </div>
    );
  }

  if (breakdown.qualification === "non-intent") {
    return (
      <div className="intent-clarify-prompt intent-clarify-prompt--info" role="status">
        This looks like a question or navigation command — not a deployable trade intent.
      </div>
    );
  }

  if (breakdown.deployState === "resolve" && breakdown.resolution) {
    return (
      <IntentAmbiguityPrompt
        resolution={breakdown.resolution}
        onSelectAgent={onSelectAgent ?? (() => {})}
        onSelectAsset={onSelectAsset ?? (() => {})}
      />
    );
  }

  return null;
}
