import { detectPlatform, type Platform } from "./platform";
import type { KeyboardBinding } from "./types";
import { formatKeyLabel } from "./normalizeKey";

function formatModifier(modifier: keyof Pick<KeyboardBinding, "meta" | "ctrl" | "alt" | "shift">, platform: Platform): string {
  switch (modifier) {
    case "meta":
      if (platform === "macos") return "⌘";
      if (platform === "windows") return "Win";
      return "Super";
    case "ctrl":
      return platform === "macos" ? "⌃" : "Ctrl";
    case "alt":
      return platform === "macos" ? "⌥" : "Alt";
    case "shift":
      return platform === "macos" ? "⇧" : "Shift";
  }
}

export function formatKeyboardBinding(
  binding: KeyboardBinding,
  platform: Platform = detectPlatform(),
): string[] {
  const tokens: string[] = [];

  if (binding.meta) tokens.push(formatModifier("meta", platform));
  if (binding.ctrl) tokens.push(formatModifier("ctrl", platform));
  if (binding.alt) tokens.push(formatModifier("alt", platform));
  if (binding.shift) tokens.push(formatModifier("shift", platform));

  tokens.push(formatKeyLabel(binding.key));
  return tokens;
}

export function formatKeyboardBindingLabel(
  binding: KeyboardBinding,
  platform: Platform = detectPlatform(),
): string {
  return formatKeyboardBinding(binding, platform).join(" + ");
}
