import React from "react";

import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import AgentAddressField, {
  formatAgentMetadataDate,
} from "./AgentAddressField";
import { formatManagedAum, shortWalletAddress } from "./agentHeroFocus";
import "./agent.css";

export interface AgentAboutTabProps {
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  hasAgentToken?: boolean;
}

function AgentAboutTab({
  profile,
  fleet,
  hasAgentToken = false,
}: AgentAboutTabProps): JSX.Element {
  const aum = formatManagedAum(profile, fleet);
  const tokenRef = shortWalletAddress(fleet.tokenAddress);

  return (
    <div className="agent-about-tab">
      {profile.verifiedLabel ? (
        <div className="agent-about-verified-row">
          <span className="agent-verified-chip">{profile.verifiedLabel}</span>
        </div>
      ) : null}

      {profile.badges.length > 0 ? (
        <div className="agent-about-badges">
          {profile.badges.map((badge) => (
            <span key={badge} className="agent-wallet-badge">
              {badge}
            </span>
          ))}
        </div>
      ) : null}

      <div className="agent-about-field">
        <span className="agent-about-label">Managed AUM</span>
        <strong className="agent-about-value">{aum}</strong>
      </div>

      <AgentAddressField label="Master address" address={fleet.masterWallet} />
      <AgentAddressField label="Deployer address" address={fleet.deployer} />

      <div className="agent-about-field">
        <span className="agent-about-label">Agent deployment date</span>
        <strong className="agent-about-value">
          {formatAgentMetadataDate(fleet.agentDeployedAt)}
        </strong>
      </div>

      {profile.receipts.length > 0 ? (
        <div className="agent-about-field">
          <span className="agent-about-label">Compliance</span>
          <ul className="agent-about-compliance-list">
            {profile.receipts.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        </div>
      ) : null}

      {!hasAgentToken ? (
        <>
          <div className="agent-about-field">
            <span className="agent-about-label">Agent token</span>
            <span className="agent-token-chip">{tokenRef}</span>
          </div>

          {profile.links.length > 0 ? (
            <div className="agent-about-links">
              {profile.links.map((link) => (
                <button
                  key={link}
                  type="button"
                  className="agent-secondary-btn agent-secondary-btn--block"
                  disabled
                  title="Demo link"
                >
                  {link}
                </button>
              ))}
            </div>
          ) : null}
        </>
      ) : null}
    </div>
  );
}

export default AgentAboutTab;
