/**
 * Agent detail terminal page — slug-driven grid layout.
 */
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { Navigate, useParams, useSearchParams } from "react-router-dom";

import { getAgentProfileById } from "../../offline/mock_data";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import type { AgentTokenTakerTradeEvent } from "../../offline/mock_data/agentTokenTakerHistory.types";
import {
  AgentActionTabSection,
  AgentChartSection,
  AgentDetailTabSection,
  type AgentDetailTabId,
  AgentDiscoveryRail,
  AgentHeroHeader,
  AgentMetricsBar,
  AgentSettingsModal,
} from "../components/agent";
import { agentAssetChartFocusFromEvent, type AgentAssetChartFocus } from "../components/agent/agentAssetChartFocus";
import type { TokenTakerChartFocus } from "../components/agent/AgentChartSection";
import { useAgentTokenTakerHistory } from "../hooks/useAgentTokenTakerHistory";
import { isBinanceKlineSupported } from "../components/tradingview/symbols";
import { GridViewerLayout, GRID_COLS } from "../components";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  applyAgentLayoutSizing,
  buildAgentResponsiveLayoutConfig,
  generateAgentResponsiveLayouts,
  AGENT_LAYOUT_MARGIN,
  AGENT_ROW_HEIGHT,
} from "../configs/agentLayoutConfig";
import { useAgentPageData } from "../hooks/useAgentPageData";
import { useFleetAgentTrades } from "../hooks/useFleetAgentTrades";
import { useFleetCopyRelations } from "../hooks/useFleetCopyRelations";
import { useAgentKpiHistory } from "../hooks/useAgentKpiHistory";
import { useOnboard } from "../hooks/useOnboard";
import { DEFAULT_AGENT_HERO_FOCUS, parseAgentActionTabParam, resolveAgentHeroColumnLayout, AGENT_HERO_FOCUS_LOOP_MS, nextAgentHeroFocus } from "../components/agent/agentHeroFocus";
import { useOptionalSettings } from "../context/SettingsContext";
import { DEFAULT_AGENT_PREFS } from "../components/preference/SettingsModal";
import MorpheumInlineLoading from "../components/ui/MorpheumInlineLoading";
import { APP_ROUTES } from "../routes";
import { PRE_NAVIGATE_CLEANUP_EVENT } from "../utils/preNavigateCleanup";
import "./AgentPage.css";

const OFFLINE_BASE_URL = "offline://local";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [AGENT_LAYOUT_MARGIN, AGENT_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = AGENT_ROW_HEIGHT;

function buildLayouts(viewportHeight?: number) {
  const base = buildAgentResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyAgentLayoutSizing(base, height);
  return generateAgentResponsiveLayouts(sized, 0);
}

function getAgentIdFromPath(): string {
  const parts = window.location.pathname.split("/").filter(Boolean);
  if (parts[0] === "agents" && parts[1] && parts[1] !== "compare") {
    return decodeURIComponent(parts[1]);
  }
  return "";
}

function AgentPageLoading(): JSX.Element {
  return (
    <div className="App-dex-content App-dex-content--agent">
      <MorpheumInlineLoading message="Loading agent data…" />
    </div>
  );
}

export default function AgentPage(): JSX.Element {
  const { id: routeAgentId = "" } = useParams<{ id: string }>();
  const agentId = routeAgentId || getAgentIdFromPath();

  if (!getAgentProfileById(agentId)) {
    return <Navigate to={APP_ROUTES.markets} replace />;
  }

  return <AgentPageContent key={agentId} agentId={agentId} />;
}

function AgentPageContent({ agentId }: { agentId: string }): JSX.Element {
  const { trades: fleetTrades, loading: fleetTradesLoading } =
    useFleetAgentTrades(agentId);
  const { kpi: kpiHistory } = useAgentKpiHistory(agentId);

  if (fleetTradesLoading) {
    return <AgentPageLoading />;
  }

  return (
    <AgentPageLoaded
      agentId={agentId}
      fleetTrades={fleetTrades}
      kpiHistory={kpiHistory}
    />
  );
}

function AgentPageLoaded({
  agentId,
  fleetTrades,
  kpiHistory,
}: {
  agentId: string;
  fleetTrades: FleetTradeEvent[];
  kpiHistory: ReturnType<typeof useAgentKpiHistory>["kpi"];
}): JSX.Element {
  const [searchParams] = useSearchParams();
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);
  const chartSlotRef = useRef<HTMLDivElement>(null);
  const settingsContext = useOptionalSettings();
  const agentPrefs = settingsContext?.settings.agent ?? DEFAULT_AGENT_PREFS;
  const savedHeroFocus = agentPrefs.heroFocus ?? DEFAULT_AGENT_HERO_FOCUS;
  const heroFocusLoop = agentPrefs.heroFocusLoop ?? false;
  const [loopedFocus, setLoopedFocus] = useState(savedHeroFocus);
  const [assetChartFocus, setAssetChartFocus] = useState<AgentAssetChartFocus | null>(
    null,
  );
  const [detailActiveTab, setDetailActiveTab] = useState<AgentDetailTabId>("activity");
  const [tokenTakerChartFocus, setTokenTakerChartFocus] =
    useState<TokenTakerChartFocus | null>(null);
  const [agentSettingsOpen, setAgentSettingsOpen] = useState(false);
  const heroFocus = heroFocusLoop ? loopedFocus : savedHeroFocus;
  const heroColumnLayout = useMemo(
    () => resolveAgentHeroColumnLayout(currentBreakpoint),
    [currentBreakpoint],
  );
  const pageData = useAgentPageData(agentId, fleetTrades, heroFocus, kpiHistory);
  const { events: takerEvents, loading: takerEventsLoading } =
    useAgentTokenTakerHistory(agentId);

  useEffect(() => {
    setAssetChartFocus(null);
    setTokenTakerChartFocus(null);
    setDetailActiveTab(pageData?.hasAgentToken ? "tokenTakers" : "activity");
  }, [agentId, pageData?.hasAgentToken]);

  useEffect(() => {
    const onPreNavigate = () => {
      setAssetChartFocus(null);
      setTokenTakerChartFocus(null);
    };
    window.addEventListener(PRE_NAVIGATE_CLEANUP_EVENT, onPreNavigate);
    return () => {
      window.removeEventListener(PRE_NAVIGATE_CLEANUP_EVENT, onPreNavigate);
    };
  }, []);

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(window.innerHeight);
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };

    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, []);

  useEffect(() => {
    if (!heroFocusLoop) {
      setLoopedFocus(savedHeroFocus);
      return;
    }

    setLoopedFocus(savedHeroFocus);
    const intervalId = window.setInterval(() => {
      setLoopedFocus((current) => nextAgentHeroFocus(current));
    }, AGENT_HERO_FOCUS_LOOP_MS);

    return () => window.clearInterval(intervalId);
  }, [heroFocusLoop, savedHeroFocus]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const { walletAddress } = useOnboard(OFFLINE_BASE_URL);
  const { getRelationForAgent } = useFleetCopyRelations(walletAddress);
  const copyRelation = useMemo(
    () => getRelationForAgent(agentId),
    [getRelationForAgent, agentId],
  );

  const initialActionTab = parseAgentActionTabParam(
    searchParams.get("tab"),
    pageData?.hasAgentToken ?? false,
  );

  const handleViewAssetOnChart = useCallback((event: FleetTradeEvent) => {
    if (!isBinanceKlineSupported(event.coin)) return;
    setAssetChartFocus(agentAssetChartFocusFromEvent(event));
    requestAnimationFrame(() => {
      chartSlotRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "nearest",
      });
    });
  }, []);

  const handleClearAssetFocus = useCallback(() => {
    setAssetChartFocus(null);
  }, []);

  const handleDetailTabChange = useCallback((tabId: AgentDetailTabId) => {
    setDetailActiveTab(tabId);
    if (tabId !== "tokenTakers") {
      setTokenTakerChartFocus(null);
    }
  }, []);

  const handleViewTakerOnChart = useCallback((event: AgentTokenTakerTradeEvent) => {
    setTokenTakerChartFocus({
      eventId: event.id,
      timeMs: Date.parse(event.timestamp),
    });
    requestAnimationFrame(() => {
      chartSlotRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "nearest",
      });
    });
  }, []);

  const handleClearTokenTakerFocus = useCallback(() => {
    setTokenTakerChartFocus(null);
    setDetailActiveTab((current) =>
      current === "tokenTakers" ? "activity" : current,
    );
  }, []);

  const slotContent = useMemo(() => {
    if (!pageData) return [];

    const { profile, fleet, charts, metricsByFocus, hasAgentToken, tokenProfile } =
      pageData;
    const equityValue = charts.pnlCurve.at(-1) ?? profile.price;
    const tokenTakersActive = detailActiveTab === "tokenTakers" && hasAgentToken;

    return [
      <AgentHeroHeader
        key="hero"
        height={slotDimensions[0]?.height}
        profile={profile}
        fleet={fleet}
        focus={heroFocus}
        columnLayout={heroColumnLayout}
        onOpenAgentSettings={() => setAgentSettingsOpen(true)}
      />,
      <div
        key={
          assetChartFocus?.tradeId ??
          (tokenTakersActive ? "token-takers" : "equity")
        }
        ref={chartSlotRef}
        className="agent-chart-slot-anchor"
        style={{ height: slotDimensions[1]?.height }}
      >
        <AgentChartSection
          height="100%"
          series={charts.pnlCurve}
          currentValue={equityValue}
          fleetTrades={fleetTrades}
          agentTicker={profile.ticker}
          profile={profile}
          fleet={fleet}
          assetFocus={assetChartFocus}
          onClearAssetFocus={handleClearAssetFocus}
          copyRelation={copyRelation}
          tokenTakersActive={tokenTakersActive}
          marketCatalogAgentId={profile.id}
          takerEvents={takerEvents}
          takerEventsLoading={takerEventsLoading}
          tokenTakerFocus={tokenTakerChartFocus}
          onClearTokenTakerFocus={handleClearTokenTakerFocus}
          tokenTicker={tokenProfile?.ticker ?? profile.ticker}
        />
      </div>,
      null,
      <AgentActionTabSection
        key="action"
        height={slotDimensions[3]?.height}
        profile={profile}
        fleet={fleet}
        walletAddress={walletAddress}
        heroFocus={heroFocus}
        hasAgentToken={hasAgentToken}
        tokenProfile={tokenProfile}
        initialActionTab={initialActionTab}
      />,
      <AgentDetailTabSection
        key="tabs"
        height={slotDimensions[4]?.height ?? "100%"}
        profile={profile}
        charts={charts}
        fleetTrades={fleetTrades}
        hasAgentToken={hasAgentToken}
        onViewAssetOnChart={handleViewAssetOnChart}
        activeAssetCoin={assetChartFocus?.coin ?? null}
        activeTab={detailActiveTab}
        onTabChange={handleDetailTabChange}
        onViewTakerOnChart={handleViewTakerOnChart}
        activeTakerEventId={tokenTakerChartFocus?.eventId ?? null}
      />,
      <AgentMetricsBar
        key="metrics"
        height={slotDimensions[5]?.height}
        metricsByFocus={metricsByFocus}
        focusKey={heroFocus}
        announceChanges={heroFocusLoop}
      />,
      <AgentDiscoveryRail
        key="discovery"
        variant="discover"
        height={slotDimensions[6]?.height}
        activeAgentId={agentId}
      />,
      null,
      null,
    ];
  }, [
    pageData,
    slotDimensions,
    agentId,
    fleetTrades,
    walletAddress,
    copyRelation,
    heroFocus,
    heroColumnLayout,
    initialActionTab,
    heroFocusLoop,
    assetChartFocus,
    handleViewAssetOnChart,
    handleClearAssetFocus,
    detailActiveTab,
    takerEvents,
    takerEventsLoading,
    tokenTakerChartFocus,
    handleDetailTabChange,
    handleViewTakerOnChart,
    handleClearTokenTakerFocus,
  ]);

  if (!pageData) {
    return <AgentPageLoading />;
  }

  return (
    <div className="App-dex-content App-dex-content--agent">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
      <AgentSettingsModal
        open={agentSettingsOpen}
        onClose={() => setAgentSettingsOpen(false)}
        catalogAgentId={agentId}
        agentName={pageData.profile.name}
      />
    </div>
  );
}
