import React, { useCallback, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import { useCopyAgentConfirm } from "../../hooks/useCopyAgentConfirm";
import { useFleetCopyRelations } from "../../hooks/useFleetCopyRelations";
import { useOnboard } from "../../hooks/useOnboard";
import { useStopCopyMirror } from "../../hooks/useStopCopyMirror";
import {
  buildCompareMatrixGridColumns,
  type CompareAgentColumn,
} from "../../utils/agentCompareMatrix";
import type { AgentCompareFocus } from "./agentCompareFocus";
import { resolveCompareFocusCta } from "./agentCompareFocusCta";
import { APP_ROUTES } from "../../routes";
import BucketDetailModal from "../tables/BucketDetailModal";
import type { BucketDetailTabId } from "../tables/bucketDetailTypes";
import CopiedAgentStatusModal from "../portfolio/CopiedAgentStatusModal";
import StopCopyWizardModal from "../portfolio/StopCopyWizardModal";
import CopyAgentModal, { type CopyAgentConfirmParams } from "./CopyAgentModal";
import "./agent.css";

const OFFLINE_BASE_URL = "offline://local";

export interface AgentCompareMatrixActionsProps {
  agents: CompareAgentColumn[];
  columnCount: number;
  compareFocus: AgentCompareFocus;
  showAddSlot: boolean;
}

function AgentCompareMatrixActions({
  agents,
  columnCount,
  compareFocus,
  showAddSlot,
}: AgentCompareMatrixActionsProps): JSX.Element {
  const navigate = useNavigate();
  const { walletAddress } = useOnboard(OFFLINE_BASE_URL);
  const { hasActiveCopy, getRelationForAgent } = useFleetCopyRelations(walletAddress);
  const {
    crossBuckets,
    spotWalletBalance,
    isPending: copyPending,
    confirmCopy,
  } = useCopyAgentConfirm(OFFLINE_BASE_URL);
  const { stopMirror, isPending: stopPending } = useStopCopyMirror();
  const [copyTarget, setCopyTarget] = useState<CompareAgentColumn | null>(null);
  const [statusTarget, setStatusTarget] = useState<CompareAgentColumn | null>(null);
  const [stopTarget, setStopTarget] = useState<CompareAgentColumn | null>(null);
  const [bucketDetail, setBucketDetail] = useState<{
    bucketId: string;
    initialTab: BucketDetailTabId;
  } | null>(null);

  const walletConnected = Boolean(walletAddress?.trim());

  const statusRelation = useMemo(
    () =>
      statusTarget ? getRelationForAgent(statusTarget.id) ?? null : null,
    [getRelationForAgent, statusTarget],
  );

  const statusBucket = useMemo(
    () =>
      statusRelation
        ? crossBuckets.find(
            (bucket) => bucket.bucketId === statusRelation.copySettings.bucketId,
          ) ?? null
        : null,
    [crossBuckets, statusRelation],
  );

  const stopRelation = useMemo(
    () => (stopTarget ? getRelationForAgent(stopTarget.id) ?? null : null),
    [getRelationForAgent, stopTarget],
  );

  const bucketDetailBucket = useMemo(
    () =>
      bucketDetail
        ? crossBuckets.find((bucket) => bucket.bucketId === bucketDetail.bucketId) ??
          null
        : null,
    [bucketDetail, crossBuckets],
  );

  const handleCopyConfirm = useCallback(
    async (params: CopyAgentConfirmParams) => {
      if (!walletConnected || !copyTarget) return;
      const relation = await confirmCopy(params);
      if (relation) {
        setCopyTarget(null);
        navigate(APP_ROUTES.portfolio);
      }
    },
    [confirmCopy, copyTarget, navigate, walletConnected],
  );

  const handleStopConfirm = useCallback(async () => {
    if (!stopTarget || !stopRelation) return;
    const ok = await stopMirror(stopRelation, stopTarget.profile.name);
    if (ok) {
      setStopTarget(null);
      setStatusTarget(null);
    }
  }, [stopMirror, stopRelation, stopTarget]);

  return (
    <>
      <div
        className="agent-compare-matrix-actions"
        style={{
          gridTemplateColumns: buildCompareMatrixGridColumns(columnCount, showAddSlot),
        }}
      >
        <div className="agent-compare-matrix-actions-gutter" aria-hidden />
        {showAddSlot ? (
          <div className="agent-compare-matrix-add-spacer" aria-hidden />
        ) : null}
        {Array.from({ length: columnCount }, (_, index) => {
          const agent = agents[index];
          if (!agent) {
            return (
              <div
                key={`placeholder-action-${index}`}
                className="agent-compare-matrix-actions-cell agent-compare-matrix-actions-cell--placeholder"
              />
            );
          }

          const alreadyCopying = hasActiveCopy(agent.id);
          const cta = resolveCompareFocusCta(
            compareFocus,
            agent,
            alreadyCopying,
          );

          return (
            <div key={agent.id} className="agent-compare-matrix-actions-cell">
              <button
                type="button"
                className="agent-secondary-btn agent-secondary-btn--primary"
                onClick={() => {
                  if (cta.kind === "copy") {
                    if (alreadyCopying) {
                      setStatusTarget(agent);
                      return;
                    }
                    setCopyTarget(agent);
                    return;
                  }
                  navigate(cta.path);
                }}
              >
                {cta.label}
              </button>
            </div>
          );
        })}
      </div>

      {copyTarget ? (
        <CopyAgentModal
          open={Boolean(copyTarget)}
          profile={copyTarget.profile}
          fleet={copyTarget.fleet}
          walletConnected={walletConnected}
          isCopying={copyPending}
          crossBuckets={crossBuckets}
          spotWalletBalance={spotWalletBalance}
          onClose={() => setCopyTarget(null)}
          onConfirm={handleCopyConfirm}
        />
      ) : null}

      {statusTarget ? (
        <CopiedAgentStatusModal
          open={Boolean(statusTarget) && statusRelation != null}
          relation={statusRelation}
          profile={statusTarget.profile}
          fleet={statusTarget.fleet}
          bucket={statusBucket}
          onClose={() => setStatusTarget(null)}
          onViewAgent={() => {
            setStatusTarget(null);
            navigate(`/agents/${statusTarget.id}`);
          }}
          onManageBucket={(bucketId) => {
            setStatusTarget(null);
            setBucketDetail({ bucketId, initialTab: "manage" });
          }}
          onAdjustSettings={(bucketId) => {
            setStatusTarget(null);
            setBucketDetail({ bucketId, initialTab: "rules" });
          }}
          onStopCopy={() => {
            setStopTarget(statusTarget);
            setStatusTarget(null);
          }}
        />
      ) : null}

      <StopCopyWizardModal
        open={stopTarget != null}
        relation={stopRelation}
        profile={stopTarget?.profile ?? null}
        isPending={stopPending}
        onClose={() => setStopTarget(null)}
        onConfirm={handleStopConfirm}
      />

      <BucketDetailModal
        isOpen={bucketDetail != null}
        bucketId={bucketDetail?.bucketId ?? null}
        bucket={bucketDetailBucket}
        initialTab={bucketDetail?.initialTab ?? "overview"}
        baseURL={OFFLINE_BASE_URL}
        walletAddress={walletAddress ?? undefined}
        onClose={() => setBucketDetail(null)}
      />
    </>
  );
}

export default AgentCompareMatrixActions;
