import { useEffect, useState } from "react";

export type CopyAgentModalLayout = "lg" | "md" | "sheet";

const LG_BREAKPOINT_PX = 1024;
const MD_BREAKPOINT_PX = 768;

export function resolveCopyAgentModalLayout(width: number): CopyAgentModalLayout {
  if (width >= LG_BREAKPOINT_PX) return "lg";
  if (width >= MD_BREAKPOINT_PX) return "md";
  return "sheet";
}

export function useCopyAgentModalLayout(): CopyAgentModalLayout {
  const [layout, setLayout] = useState<CopyAgentModalLayout>(() =>
    typeof window !== "undefined"
      ? resolveCopyAgentModalLayout(window.innerWidth)
      : "lg",
  );

  useEffect(() => {
    const sync = () => setLayout(resolveCopyAgentModalLayout(window.innerWidth));
    sync();
    window.addEventListener("resize", sync);
    return () => window.removeEventListener("resize", sync);
  }, []);

  return layout;
}
