import React from "react";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import type { AgentTaskStatus, AgentTaskStatusEvent } from "../../store/types";
import "./agentTasks.css";

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function getStatusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

function statusPillClassName(tone: string): string {
  return `agent-task-status-pill agent-task-status-pill--${tone}`;
}

export interface AgentTaskTimelineProps {
  history: AgentTaskStatusEvent[];
  className?: string;
}

function AgentTaskTimeline({
  history,
  className,
}: AgentTaskTimelineProps): JSX.Element {
  const rootClass = ["agent-task-timeline", className].filter(Boolean).join(" ");

  return (
    <ol className={rootClass} aria-label="Task status history">
      {history.map((event, index) => {
        const eventCfg = getStatusConfig(event.status);
        const isLatest = index === history.length - 1;
        return (
          <li
            key={`${event.status}-${event.at}-${index}`}
            className={`agent-task-timeline-item${isLatest ? " is-latest" : ""}`}
          >
            <div className="agent-task-timeline-track">
              <span className="agent-task-timeline-dot" aria-hidden />
            </div>
            <div className="agent-task-timeline-body">
              <div className="agent-task-timeline-meta">
                <span className="terminal-value">{formatDateTime(event.at)}</span>
                <span className={statusPillClassName(eventCfg.tone)}>
                  {eventCfg.label}
                </span>
              </div>
              {event.note ? (
                <div className="agent-task-timeline-note">{event.note}</div>
              ) : null}
            </div>
          </li>
        );
      })}
    </ol>
  );
}

export default React.memo(AgentTaskTimeline);
