import { useCallback, useEffect, useRef, useState } from "react";
import type { CrossChainConfirmParams } from "../components/smartlayout/cross-chain-modal";
import type { WalletTransferAssetId } from "../components/smartlayout/wallet-transfer-modal";
import {
  DEMO_STAGE_DELAYS_MS,
  type CrossChainDemoConfig,
  type CrossChainFlowStep,
  type CrossChainTransferRecord,
  type DemoOutcome,
  type SecurityStage,
} from "../types/crossChainFlow";
import {
  generateDemoTxHash,
  generateTransferId,
  upsertCrossChainTransfer,
  clearCrossChainTransfer,
} from "../stores/crossChainTransferStore";
import { markWithdrawAddressSeen } from "../utils/crossChainAddressValidation";

function needsAuthorizeStep(assetId: WalletTransferAssetId): boolean {
  return assetId !== "BTC";
}

export interface UseCrossChainDemoOrchestratorResult {
  flowStep: CrossChainFlowStep;
  transferRecord: CrossChainTransferRecord | null;
  demoConfig: CrossChainDemoConfig;
  isSimulatingSignature: boolean;
  trackingStageIndex: number;
  validatorCount: number;
  setFailOnNextConfirm: (stage?: SecurityStage) => void;
  previewFailure: (stage?: SecurityStage) => void;
  resetDemoConfig: () => void;
  goToReview: () => void;
  goBackToForm: () => void;
  confirmReview: (params: CrossChainConfirmParams) => void;
  simulateAuthorize: () => void;
  simulateSubmit: () => void;
  retryFromFailure: () => void;
  keepPollingFromFailure: () => void;
  completeToSuccess: () => void;
  resetFlow: () => void;
  reopenTracking: (record: CrossChainTransferRecord) => void;
}

const DEFAULT_DEMO_CONFIG: CrossChainDemoConfig = {
  outcome: "success",
  failureStage: "attested",
};

export function useCrossChainDemoOrchestrator(
  onFlowComplete?: (record: CrossChainTransferRecord) => void,
): UseCrossChainDemoOrchestratorResult {
  const [flowStep, setFlowStep] = useState<CrossChainFlowStep>("form");
  const [transferRecord, setTransferRecord] =
    useState<CrossChainTransferRecord | null>(null);
  const [demoConfig, setDemoConfig] =
    useState<CrossChainDemoConfig>(DEFAULT_DEMO_CONFIG);
  const [isSimulatingSignature, setIsSimulatingSignature] = useState(false);
  const [trackingStageIndex, setTrackingStageIndex] = useState(0);
  const [validatorCount, setValidatorCount] = useState(0);
  const pendingParamsRef = useRef<CrossChainConfirmParams | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const transferRecordRef = useRef<CrossChainTransferRecord | null>(null);

  useEffect(() => {
    transferRecordRef.current = transferRecord;
  }, [transferRecord]);

  const clearTimers = useCallback(() => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  useEffect(() => () => clearTimers(), [clearTimers]);

  const persistRecord = useCallback((record: CrossChainTransferRecord) => {
    setTransferRecord(record);
    transferRecordRef.current = record;
    upsertCrossChainTransfer(record);
  }, []);

  const resetFlow = useCallback(() => {
    clearTimers();
    const id = transferRecordRef.current?.id;
    if (id) clearCrossChainTransfer(id);
    setFlowStep("form");
    setTransferRecord(null);
    transferRecordRef.current = null;
    setDemoConfig(DEFAULT_DEMO_CONFIG);
    setIsSimulatingSignature(false);
    setTrackingStageIndex(0);
    setValidatorCount(0);
    pendingParamsRef.current = null;
  }, [clearTimers]);

  const setFailOnNextConfirm = useCallback((stage: SecurityStage = "attested") => {
    setDemoConfig({ outcome: "failure", failureStage: stage });
  }, []);

  const previewFailure = useCallback(
    (stage: SecurityStage = "attested") => {
      clearTimers();
      const params = pendingParamsRef.current;
      const existing = transferRecordRef.current;
      const record: CrossChainTransferRecord = existing ?? {
        id: generateTransferId(),
        mode: params?.mode ?? "deposit",
        assetId: params?.assetId ?? "USDC",
        amount: params?.amount ?? 250,
        chain: params?.chain ?? "ethereum",
        currentStage: stage,
        originTxHash: generateDemoTxHash("7f3a"),
        messageId: generateDemoTxHash("4caa"),
        bridgeId: `bridge_${Date.now().toString(36)}`,
        validatorCount: 4,
        validatorTotal: 9,
        startedAt: Date.now(),
      };
      persistRecord({ ...record, failedStage: stage, currentStage: stage });
      setFlowStep("failure");
    },
    [clearTimers, persistRecord],
  );

  const resetDemoConfig = useCallback(() => {
    setDemoConfig(DEFAULT_DEMO_CONFIG);
  }, []);

  const goToReview = useCallback(() => setFlowStep("review"), []);
  const goBackToForm = useCallback(() => setFlowStep("form"), []);

  const startTrackingAnimation = useCallback(
    (
      record: CrossChainTransferRecord,
      outcome: DemoOutcome,
      failStage: SecurityStage,
    ) => {
      setFlowStep("tracking");
      setTrackingStageIndex(0);
      setValidatorCount(0);

      const stages: SecurityStage[] = [
        "authorize",
        "submit",
        "locked",
        "attested",
        "delivered",
      ];
      const skipAuthorize = !needsAuthorizeStep(record.assetId);
      const activeStages = skipAuthorize
        ? stages.filter((s) => s !== "authorize")
        : stages;

      let index = 0;
      const working = { ...record };

      const failAtStage = (stage: SecurityStage) => {
        persistRecord({
          ...working,
          currentStage: stage,
          failedStage: stage,
          validatorCount: stage === "attested" ? 4 : working.validatorCount,
          validatorTotal: 9,
        });
        setFlowStep("failure");
        setDemoConfig(DEFAULT_DEMO_CONFIG);
      };

      const runStage = () => {
        if (index >= activeStages.length) {
          if (outcome === "failure") {
            failAtStage(failStage);
            return;
          }
          const destinationTxHash = generateDemoTxHash("9c84");
          const completedRecord = {
            ...working,
            currentStage: "complete" as const,
            destinationTxHash,
            completedAt: Date.now(),
            validatorCount: 9,
            validatorTotal: 9,
          };
          persistRecord(completedRecord);
          setFlowStep("success");
          setDemoConfig(DEFAULT_DEMO_CONFIG);
          onFlowComplete?.(completedRecord);
          return;
        }

        const stage = activeStages[index];
        setTrackingStageIndex(index);

        if (outcome === "failure" && failStage === stage) {
          failAtStage(stage);
          return;
        }

        if (stage === "attested") {
          let count = working.validatorCount ?? 0;
          intervalRef.current = setInterval(() => {
            count += 1;
            setValidatorCount(count);
            working.validatorCount = count;
            working.validatorTotal = 9;
            working.currentStage = stage;
            working.messageId = working.messageId ?? generateDemoTxHash("4caa");
            persistRecord({ ...working });
            const target = outcome === "failure" && failStage === "attested" ? 4 : 9;
            if (count >= target) {
              if (intervalRef.current) clearInterval(intervalRef.current);
              if (outcome === "failure" && failStage === "attested") {
                failAtStage("attested");
                return;
              }
              index += 1;
              timerRef.current = setTimeout(runStage, DEMO_STAGE_DELAYS_MS.delivered);
            }
          }, 280);
          return;
        }

        working.currentStage = stage;
        if (stage === "submit" || stage === "locked") {
          working.originTxHash = working.originTxHash ?? generateDemoTxHash("7f3a");
        }
        if (stage === "delivered") {
          working.messageId = working.messageId ?? generateDemoTxHash("4caa");
        }
        persistRecord({ ...working });
        index += 1;
        timerRef.current = setTimeout(runStage, DEMO_STAGE_DELAYS_MS[stage] ?? 1000);
      };

      timerRef.current = setTimeout(runStage, 300);
    },
    [onFlowComplete, persistRecord],
  );

  const confirmReview = useCallback(
    (params: CrossChainConfirmParams) => {
      pendingParamsRef.current = params;
      if (params.mode === "withdraw" && params.toAddress) {
        markWithdrawAddressSeen(params.chain, params.toAddress);
      }

      const record: CrossChainTransferRecord = {
        id: generateTransferId(),
        mode: params.mode,
        assetId: params.assetId,
        amount: params.amount,
        chain: params.chain,
        currentStage: "authorize",
        bridgeId: `bridge_${Date.now().toString(36)}`,
        startedAt: Date.now(),
      };
      persistRecord(record);

      setFlowStep(needsAuthorizeStep(params.assetId) ? "authorize" : "submit");
    },
    [persistRecord],
  );

  const advanceAfterSignature = useCallback(
    (from: "authorize" | "submit") => {
      setIsSimulatingSignature(true);
      timerRef.current = setTimeout(() => {
        setIsSimulatingSignature(false);
        const outcome = demoConfig.outcome;
        const failStage = demoConfig.failureStage;
        const record = transferRecordRef.current;

        if (from === "authorize") {
          if (outcome === "failure" && failStage === "authorize") {
            if (record) persistRecord({ ...record, failedStage: "authorize", currentStage: "authorize" });
            setFlowStep("failure");
            setDemoConfig(DEFAULT_DEMO_CONFIG);
            return;
          }
          setFlowStep("submit");
          return;
        }

        if (outcome === "failure" && failStage === "submit") {
          if (record) persistRecord({ ...record, failedStage: "submit", currentStage: "submit" });
          setFlowStep("failure");
          setDemoConfig(DEFAULT_DEMO_CONFIG);
          return;
        }

        if (record) {
          const updated = {
            ...record,
            currentStage: "locked" as SecurityStage,
            originTxHash: generateDemoTxHash("9b22"),
          };
          persistRecord(updated);
          startTrackingAnimation(updated, outcome, failStage);
        }
      }, from === "authorize" ? 800 : 1000);
    },
    [demoConfig, persistRecord, startTrackingAnimation],
  );

  const simulateAuthorize = useCallback(() => {
    advanceAfterSignature("authorize");
  }, [advanceAfterSignature]);

  const simulateSubmit = useCallback(() => {
    advanceAfterSignature("submit");
  }, [advanceAfterSignature]);

  const retryFromFailure = useCallback(() => {
    resetDemoConfig();
    setFlowStep("form");
  }, [resetDemoConfig]);

  const keepPollingFromFailure = useCallback(() => {
    const record = transferRecordRef.current;
    if (!record) return;
    resetDemoConfig();
    const resumed = { ...record, failedStage: undefined, currentStage: "attested" as SecurityStage };
    persistRecord(resumed);
    startTrackingAnimation(resumed, "success", "attested");
  }, [persistRecord, resetDemoConfig, startTrackingAnimation]);

  const completeToSuccess = useCallback(() => setFlowStep("form"), []);

  const reopenTracking = useCallback(
    (record: CrossChainTransferRecord) => {
      persistRecord(record);
      if (record.currentStage === "complete" || record.completedAt) {
        setFlowStep("success");
      } else if (record.failedStage) {
        setFlowStep("failure");
      } else {
        startTrackingAnimation(record, "success", "attested");
      }
    },
    [persistRecord, startTrackingAnimation],
  );

  return {
    flowStep,
    transferRecord,
    demoConfig,
    isSimulatingSignature,
    trackingStageIndex,
    validatorCount,
    setFailOnNextConfirm,
    previewFailure,
    resetDemoConfig,
    goToReview,
    goBackToForm,
    confirmReview,
    simulateAuthorize,
    simulateSubmit,
    retryFromFailure,
    keepPollingFromFailure,
    completeToSuccess,
    resetFlow,
    reopenTracking,
  };
}
