import React from "react";
import type { DailyPnlDay, DailyPnlSummary } from "../../utils/portfolioChartData";
import DailyPnlCalendar from "./DailyPnlCalendar";
import "./portfolio.css";

export interface PortfolioDailyPnlCardProps {
  summary: DailyPnlSummary;
  days: DailyPnlDay[];
  layoutBreakpoint?: string;
  focusAgentId?: string | null;
}

function formatCurrency(value: number): string {
  const sign = value < 0 ? "-" : "+";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000) return `${sign}$${(abs / 1_000).toFixed(2)}K`;
  return `${sign}$${abs.toFixed(2)}`;
}

function formatPct(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(2)}%`;
}

function PortfolioDailyPnlCard({
  summary,
  days,
  layoutBreakpoint,
  focusAgentId = null,
}: PortfolioDailyPnlCardProps): JSX.Element {
  const isFocused = focusAgentId != null;
  const isDesktopLayout =
    layoutBreakpoint === "lg" ||
    layoutBreakpoint === "md" ||
    layoutBreakpoint === "sm";

  return (
    <div
      className={`portfolio-daily-pnl-card${
        isDesktopLayout ? " portfolio-daily-pnl-card--desktop" : ""
      }`}
    >
      <div className="portfolio-daily-pnl-metrics">
        <div className="portfolio-daily-pnl-metric portfolio-daily-pnl-metric--primary">
          <span className="portfolio-daily-pnl-metric-label">
            7D Realized PnL
            {isFocused ? " · Agent" : null}
            <span className="portfolio-daily-pnl-currency">USD</span>
          </span>
          <div className="portfolio-daily-pnl-metric-values">
            <span
              className={
                summary.realizedPnl7d >= 0 ? "positive" : "negative"
              }
            >
              {formatPct(summary.realizedPnl7dPct)}
            </span>
            <span
              className={`portfolio-daily-pnl-metric-sub ${
                summary.realizedPnl7d >= 0 ? "positive" : "negative"
              }`}
            >
              {formatCurrency(summary.realizedPnl7d)}
            </span>
          </div>
        </div>
        <div className="portfolio-daily-pnl-metric portfolio-daily-pnl-metric--secondary">
          <span className="portfolio-daily-pnl-metric-label">Win Rate</span>
          <span className="portfolio-daily-pnl-win-rate">
            {summary.winRatePct.toFixed(2)}%
          </span>
          <div className="portfolio-daily-pnl-sub-rows">
            <div className="portfolio-daily-pnl-sub-row">
              <span>Total PnL</span>
              <span className={summary.totalPnl >= 0 ? "positive" : "negative"}>
                {formatCurrency(summary.totalPnl)} ({formatPct(summary.totalPnlPct)})
              </span>
            </div>
            {isFocused && summary.agentPctOfFleetTotal != null ? (
              <div className="portfolio-daily-pnl-sub-row">
                <span>vs Fleet</span>
                <span className="terminal-text-muted">
                  {summary.agentPctOfFleetTotal.toFixed(1)}% of fleet
                </span>
              </div>
            ) : null}
            <div className="portfolio-daily-pnl-sub-row">
              <span>Unrealized Profits</span>
              <span
                className={
                  summary.unrealizedProfits >= 0 ? "positive" : "negative"
                }
              >
                {summary.unrealizedProfits === 0
                  ? "$0"
                  : formatCurrency(summary.unrealizedProfits)}
              </span>
            </div>
          </div>
        </div>
      </div>

      <DailyPnlCalendar days={days} />
    </div>
  );
}

export default React.memo(PortfolioDailyPnlCard);
