import React, { type JSX, useCallback, useState } from "react";
import { useIntentHints } from "./useIntentHints";
import type { IntentTemplateSuggestion } from "./intentKeywords";
import "./intentWindow.css";

export interface IntentWindowInlineHintsProps {
  text: string;
  baseAsset: string;
  caret: number;
  onSelectSuggestion: (intentText: string) => void;
  onInsertKeyword: (keyword: string) => void;
}

export function IntentWindowInlineHints({
  text,
  baseAsset,
  caret,
  onSelectSuggestion,
  onInsertKeyword,
}: IntentWindowInlineHintsProps): JSX.Element {
  const { detectedKeywords, chipKeywords, suggestions } = useIntentHints(
    text,
    baseAsset,
    caret,
    true,
  );
  const [activeSuggestion, setActiveSuggestion] = useState(0);

  const handleSelect = useCallback(
    (suggestion: IntentTemplateSuggestion) => {
      onSelectSuggestion(suggestion.intentText);
    },
    [onSelectSuggestion],
  );

  const showKeywordRail =
    detectedKeywords.length > 0 || chipKeywords.length > 0;

  return (
    <div className="intent-window-inline" data-intent-window-root>
      <div className="intent-window-mention-hint" aria-hidden="true">
        <button
          type="button"
          className="intent-window-chip intent-window-chip--mention"
          onClick={() => onInsertKeyword("@")}
        >
          @ agent
        </button>
        <button
          type="button"
          className="intent-window-chip intent-window-chip--mention"
          onClick={() => onInsertKeyword("$")}
        >
          $ market
        </button>
      </div>

      {showKeywordRail ? (
        <div className="intent-window-chip-rail" role="list">
          {chipKeywords.slice(0, 8).map((keyword) => {
            const isMatch = detectedKeywords.some(
              (k) => k.toLowerCase() === keyword.toLowerCase(),
            );
            return (
              <button
                key={keyword}
                type="button"
                role="listitem"
                className={`intent-window-chip${isMatch ? " is-match" : ""}`}
                onClick={() => onInsertKeyword(keyword)}
              >
                {keyword}
              </button>
            );
          })}
        </div>
      ) : null}

      {suggestions.length > 0 ? (
        <div
          className="intent-window-suggestions"
          aria-label="Intent suggestions"
        >
          <div className="intent-window-suggestions-label">Suggestions</div>
          {suggestions.map((suggestion, index) => (
            <button
              key={suggestion.id}
              type="button"
              className={`intent-window-suggestion${index === activeSuggestion ? " is-active" : ""}`}
              onMouseEnter={() => setActiveSuggestion(index)}
              onClick={() => handleSelect(suggestion)}
            >
              <span className="intent-window-suggestion-title">
                {suggestion.label}
              </span>
              <span className="intent-window-suggestion-summary">
                {suggestion.summary}
              </span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}
