import {
  ALL_OBJECTIVES,
  G0_CHITCHAT,
  G0_NAV_PATTERNS,
  G0_QUESTION_PATTERNS,
  OBJECTIVE_UNSUPPORTED,
  PORTFOLIO_SCOPE,
  POSITION_REF,
} from "./intentLexicon";
import type { QualifyResult } from "./intentBreakdown";
import { extractTickerMentions } from "./intentMentions";

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function wordBoundaryMatch(text: string, term: string): boolean {
  const pattern = new RegExp(
    `(?:^|[\\s,.;:!?'"([{])${escapeRegExp(term.toLowerCase())}(?:$|[\\s,.;:!?'")\\]}])`,
    "i",
  );
  return pattern.test(text.toLowerCase());
}

function hasAnyTerm(text: string, terms: readonly string[]): boolean {
  const normalized = text.toLowerCase();
  return terms.some(
    (term) =>
      wordBoundaryMatch(normalized, term) || normalized.includes(term.toLowerCase()),
  );
}

const ASSET_NL_ALIASES: Record<string, string[]> = {
  BTC: ["bitcoin"],
  ETH: ["ethereum", "ether"],
  SOL: ["solana"],
  XAU: ["gold"],
  XAG: ["silver"],
};

function hasNlAsset(text: string): boolean {
  const normalized = text.toLowerCase();
  for (const aliases of Object.values(ASSET_NL_ALIASES)) {
    for (const alias of aliases) {
      if (wordBoundaryMatch(normalized, alias)) return true;
    }
  }
  for (const ticker of ["btc", "eth", "sol", "xau", "xag", "usdc", "usdt"]) {
    if (wordBoundaryMatch(normalized, ticker)) return true;
  }
  return false;
}

function hasSubject(text: string): boolean {
  if (extractTickerMentions(text).length > 0) return true;
  if (hasNlAsset(text)) return true;
  if (hasAnyTerm(text, PORTFOLIO_SCOPE)) return true;
  if (hasAnyTerm(text, POSITION_REF)) return true;
  if (/\bmy\s+(?:eth|btc|sol|position|exposure|book)\b/i.test(text)) {
    return true;
  }
  return false;
}

function hasObjective(text: string): boolean {
  return hasAnyTerm(text, ALL_OBJECTIVES);
}

function isG0Fail(text: string): boolean {
  const trimmed = text.trim();
  if (!trimmed) return true;
  if (G0_QUESTION_PATTERNS.some((re) => re.test(trimmed))) return true;
  if (G0_NAV_PATTERNS.some((re) => re.test(trimmed))) return true;
  const lower = trimmed.toLowerCase();
  if (G0_CHITCHAT.some((c) => lower === c || lower.startsWith(`${c} `))) {
    return true;
  }
  return false;
}

function isReject(text: string): string | null {
  const trimmed = text.trim();
  if (!trimmed) return "Empty intent";
  if (/\b\d{3,}x\b/i.test(trimmed)) return "Leverage exceeds safe limits";
  return null;
}

export function qualifyIntent(text: string): QualifyResult {
  const trimmed = text.trim();
  const rejectReason = isReject(trimmed);
  if (rejectReason) {
    return {
      qualification: "reject",
      hasObjective: false,
      hasSubject: false,
      rejectReason,
    };
  }

  if (isG0Fail(trimmed)) {
    return {
      qualification: "non-intent",
      hasObjective: false,
      hasSubject: false,
    };
  }

  const objective = hasObjective(trimmed);
  const subject = hasSubject(trimmed);

  if (objective && subject) {
    return {
      qualification: "qualified",
      hasObjective: true,
      hasSubject: true,
    };
  }

  if (objective && !subject) {
    return {
      qualification: "underspecified",
      hasObjective: true,
      hasSubject: false,
      clarifyPrompt: "Which asset or scope should this apply to?",
    };
  }

  if (!objective && subject) {
    return {
      qualification: "underspecified",
      hasObjective: false,
      hasSubject: true,
      clarifyPrompt: "What action do you want to take? (long, short, hedge, rebalance…)",
    };
  }

  return {
    qualification: "underspecified",
    hasObjective: false,
    hasSubject: false,
    clarifyPrompt: "Describe a trading action and target asset or scope.",
  };
}

export function isUnsupportedObjective(text: string): boolean {
  return hasAnyTerm(text, OBJECTIVE_UNSUPPORTED);
}
