import React from "react";

import { formatPercent } from "../index/indexFormat";
import CompactMiniLineChart from "./CompactMiniLineChart";
import CompactSparkline from "./CompactSparkline";
import type { CompactMetricDefinition } from "./types";
import {
  metricToneClassName,
  metricToneFromValue,
} from "./types";
import "./metrics.css";

export interface CompactMetricCellProps {
  metric: CompactMetricDefinition;
  showLabel?: boolean;
  layout?: "inline" | "background";
  labelNode?: React.ReactNode;
  className?: string;
}

function resolveSignedTone(
  metric: CompactMetricDefinition,
): ReturnType<typeof metricToneFromValue> {
  if (metric.valueTone === "signed") {
    const parsed = Number.parseFloat(metric.value.replace(/[^0-9.-]+/g, ""));
    if (Number.isFinite(parsed)) {
      return metricToneFromValue(parsed);
    }
  }

  if (typeof metric.changePercent === "number") {
    return metricToneFromValue(metric.changePercent);
  }

  return "neutral";
}

function renderChart(
  metric: CompactMetricDefinition,
  signedTone: ReturnType<typeof metricToneFromValue>,
  chartTone: ReturnType<typeof metricToneFromValue>,
): React.ReactNode {
  if (metric.chart?.kind === "sparkline") {
    return <CompactSparkline values={metric.chart.values} tone={chartTone} />;
  }

  if (metric.chart?.kind === "line") {
    return (
      <CompactMiniLineChart
        data={metric.chart.data}
        tone={signedTone}
        color={metric.chart.color}
        formatValue={metric.chart.formatValue}
      />
    );
  }

  return null;
}

function CompactMetricCell({
  metric,
  showLabel = true,
  layout = "inline",
  labelNode,
  className = "",
}: CompactMetricCellProps): JSX.Element {
  const signedTone = resolveSignedTone(metric);
  const valueClassName =
    metric.valueTone === "signed"
      ? `compact-metric-cell-value ${metricToneClassName(signedTone)}`.trim()
      : "compact-metric-cell-value";

  const chartTone =
    metric.chart?.kind === "sparkline" && metric.chart.tone === "signed"
      ? signedTone
      : typeof metric.changePercent === "number"
        ? metricToneFromValue(metric.changePercent)
        : signedTone;

  const chart = renderChart(metric, signedTone, chartTone);

  if (layout === "background") {
    const cellClassName = [
      "compact-metric-cell",
      "compact-metric-cell--background",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <div className={cellClassName}>
        {chart ? (
          <div className="compact-metric-cell-chart-bg">{chart}</div>
        ) : null}
        <div className="compact-metric-cell-foreground">
          {labelNode ??
            (showLabel ? (
              <span className="compact-metric-cell-label">{metric.label}</span>
            ) : null)}
          <span className={valueClassName}>{metric.value}</span>
        </div>
      </div>
    );
  }

  const cellClassName = [
    "compact-metric-cell",
    showLabel ? "" : "compact-metric-cell--table",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={cellClassName}>
      {showLabel ? (
        <span className="compact-metric-cell-label">{metric.label}</span>
      ) : null}
      <div className="compact-metric-cell-body">
        <div className="compact-metric-cell-text">
          <span className={valueClassName}>{metric.value}</span>
          {typeof metric.changePercent === "number" &&
          metric.valueTone !== "signed" ? (
            <span
              className={`compact-metric-cell-change ${metricToneClassName(
                metricToneFromValue(metric.changePercent),
              )}`.trim()}
            >
              {formatPercent(metric.changePercent)}
            </span>
          ) : null}
        </div>
        {chart}
      </div>
    </div>
  );
}

export default React.memo(CompactMetricCell);
