import { useMemo } from "react";

import type { AgentKpiHistoryFile } from "../../offline/mock_data/agentKpiHistory.types";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import {
  buildCompareMatrixSections,
  loadCompareAgents,
  resolveCompareMatrixColumnCount,
  type CompareAgentColumn,
  type CompareMatrixSection,
} from "../utils/agentCompareMatrix";
import { useAgentKpiHistoryForAgents } from "./useAgentKpiHistoryForAgents";
import { useFleetTradesForAgents } from "./useFleetTradesForAgents";

export interface UseCompareAgentsDataResult {
  agents: CompareAgentColumn[];
  columnCount: number;
  sections: CompareMatrixSection[];
  tradesByAgentId: Map<string, FleetTradeEvent[]>;
  kpiByAgentId: Map<string, AgentKpiHistoryFile>;
  loading: boolean;
  error: string | null;
}

export type CompareAgentsData = Pick<
  UseCompareAgentsDataResult,
  | "agents"
  | "columnCount"
  | "sections"
  | "tradesByAgentId"
  | "kpiByAgentId"
  | "loading"
  | "error"
>;

export function useCompareAgentsData(compareIds: string[]): UseCompareAgentsDataResult {
  const { tradesByAgentId, loading: tradesLoading, error: tradesError } =
    useFleetTradesForAgents(compareIds);
  const {
    kpiByAgentId,
    loading: kpiLoading,
    error: kpiError,
  } = useAgentKpiHistoryForAgents(compareIds);

  const loading = tradesLoading || kpiLoading;
  const error = tradesError ?? kpiError;

  const agents = useMemo(() => loadCompareAgents(compareIds), [compareIds]);
  const columnCount = useMemo(
    () => resolveCompareMatrixColumnCount(compareIds.length),
    [compareIds.length],
  );
  const sections = useMemo(
    () => buildCompareMatrixSections(agents, columnCount, tradesByAgentId),
    [agents, columnCount, tradesByAgentId],
  );

  return {
    agents,
    columnCount,
    sections,
    tradesByAgentId,
    kpiByAgentId,
    loading,
    error,
  };
}
