import React, { useMemo } from "react";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import {
  FLEET_EDGE_TIER_COLORS,
  FLEET_EDGE_TIER_LABELS,
  type AgentCompetitivenessRow,
  type AgentCompetitivenessTier,
  type FleetEdgeSummary,
} from "../../utils/portfolioFleetEdgeMetrics";
import "./portfolio.css";

export interface PortfolioFleetEdgeChartProps {
  summary: FleetEdgeSummary;
  focusAgentId?: string | null;
}

const MIN_STD = 1e-6;
const CHART_WIDTH = 560;
const CHART_HEIGHT = 168;
const PADDING_X = 28;
const PADDING_TOP = 12;
const PADDING_BOTTOM = 36;

const TIER_ORDER: AgentCompetitivenessTier[] = [
  "elite",
  "strong",
  "core",
  "lagging",
];

function formatSharpe(value: number): string {
  return value.toFixed(2);
}

function formatZScore(value: number): string {
  const sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}σ`;
}

function formatCurrency(value: number): string {
  const sign = value < 0 ? "-" : "";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000) return `${sign}$${(abs / 1_000).toFixed(1)}k`;
  return `${sign}$${abs.toFixed(0)}`;
}

function buildAgentTipTitle(agent: AgentCompetitivenessRow): string {
  return `${agent.icon ? `${agent.icon} ` : ""}${agent.label}`;
}

function buildAgentTipContent(agent: AgentCompetitivenessRow): string {
  return [
    `Sharpe ${formatSharpe(agent.sharpe)} (${formatZScore(agent.zScore)}, ${agent.percentile.toFixed(0)}th pct).`,
    `${FLEET_EDGE_TIER_LABELS[agent.tier]} tier · ${formatCurrency(agent.revenue30d)} 30d revenue.`,
    "Risk-adjusted edge vs your fleet — right of center beats peers on return per unit of volatility.",
  ].join(" ");
}

function buildBellPath(
  mean: number,
  std: number,
  xMin: number,
  xMax: number,
  mapX: (value: number) => number,
  mapY: (density: number) => number,
): string {
  const points: string[] = [];
  const steps = 80;

  for (let index = 0; index <= steps; index += 1) {
    const sharpe = xMin + ((xMax - xMin) * index) / steps;
    const z = (sharpe - mean) / std;
    const density = Math.exp(-0.5 * z * z);
    const x = mapX(sharpe);
    const y = mapY(density);
    points.push(`${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`);
  }

  return points.join(" ");
}

function PortfolioFleetEdgeChart({
  summary,
  focusAgentId = null,
}: PortfolioFleetEdgeChartProps): JSX.Element {
  const layout = useMemo(() => {
    const plotWidth = CHART_WIDTH - PADDING_X * 2;
    const plotHeight = CHART_HEIGHT - PADDING_TOP - PADDING_BOTTOM;
    const mean = summary.fleetMeanSharpe;
    const std = summary.fleetStdSharpe;
    const sharpeValues = summary.agents.map((agent) => agent.sharpe);
    const minSharpe = Math.min(...sharpeValues, mean - std * 2.5);
    const maxSharpe = Math.max(...sharpeValues, mean + std * 2.5);
    const xMin = minSharpe - std * 0.35;
    const xMax = maxSharpe + std * 0.35;
    const xSpan = Math.max(xMax - xMin, MIN_STD);

    const mapX = (sharpe: number) =>
      PADDING_X + ((sharpe - xMin) / xSpan) * plotWidth;
    const mapY = (density: number) =>
      PADDING_TOP + plotHeight - density * plotHeight * 0.92;

    const medianX = mapX(summary.fleetMedianSharpe);
    const meanX = mapX(mean);
    const bellPath = buildBellPath(mean, std, xMin, xMax, mapX, mapY);

    const grouped = new Map<number, typeof summary.agents>();
    for (const agent of summary.agents) {
      const bucket = Math.round(agent.sharpe * 20) / 20;
      const group = grouped.get(bucket) ?? [];
      group.push(agent);
      grouped.set(bucket, group);
    }

    const markers = summary.agents.map((agent) => {
      const bucket = Math.round(agent.sharpe * 20) / 20;
      const group = grouped.get(bucket) ?? [agent];
      const slot = group.findIndex((entry) => entry.id === agent.id);
      const stackOffset = (slot - (group.length - 1) / 2) * 10;
      return {
        agent,
        x: mapX(agent.sharpe),
        y: mapY(Math.exp(-0.5 * agent.zScore * agent.zScore)) + 14 + stackOffset,
      };
    });

    const axisTicks = [xMin, mean, xMax].map((value) => ({
      value,
      x: mapX(value),
      label:
        value === mean
          ? `μ ${formatSharpe(value)}`
          : formatSharpe(value),
    }));

    return {
      bellPath,
      markers,
      medianX,
      meanX,
      axisTicks,
      plotBottom: PADDING_TOP + plotHeight,
    };
  }, [summary]);

  const hasAgents = summary.agents.length > 0;

  return (
    <div className="portfolio-fleet-edge-chart">
      <div className="portfolio-fleet-edge-kpis">
        <div className="portfolio-fleet-edge-kpi">
          <span className="portfolio-fleet-edge-kpi-label">Fleet median Sharpe</span>
          <span className="portfolio-fleet-edge-kpi-value">
            {formatSharpe(summary.fleetMedianSharpe)}
          </span>
        </div>
        <div className="portfolio-fleet-edge-kpi">
          <span className="portfolio-fleet-edge-kpi-label">Above fleet avg</span>
          <span className="portfolio-fleet-edge-kpi-value">
            {summary.aboveAveragePct.toFixed(0)}%
          </span>
        </div>
        <div className="portfolio-fleet-edge-kpi">
          <span className="portfolio-fleet-edge-kpi-label">Top edge</span>
          <span className="portfolio-fleet-edge-kpi-value">
            {summary.topAgent
              ? `${summary.topAgent.icon ? `${summary.topAgent.icon} ` : ""}${summary.topAgent.label} · ${formatZScore(summary.topAgent.zScore)}`
              : "—"}
          </span>
        </div>
      </div>

      <div className="portfolio-fleet-edge-tier-strip">
        {TIER_ORDER.map((tier) => (
          <span
            key={tier}
            className="portfolio-fleet-edge-tier-chip"
            style={{ borderColor: FLEET_EDGE_TIER_COLORS[tier] }}
          >
            <i
              className="portfolio-fleet-edge-tier-dot"
              style={{ background: FLEET_EDGE_TIER_COLORS[tier] }}
            />
            {summary.tierCounts[tier]} {FLEET_EDGE_TIER_LABELS[tier]}
          </span>
        ))}
      </div>

      {hasAgents ? (
        <div className="portfolio-fleet-edge-svg-wrap">
          <svg
            viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
            className="portfolio-fleet-edge-svg"
            role="img"
            aria-label="Agent Sharpe competitiveness distribution"
          >
            <defs>
              <linearGradient id="fleetEdgeBellFill" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0%" stopColor="rgba(200, 245, 168, 0.18)" />
                <stop offset="100%" stopColor="rgba(200, 245, 168, 0.02)" />
              </linearGradient>
            </defs>

            <path
              d={`${layout.bellPath} L ${CHART_WIDTH - PADDING_X} ${layout.plotBottom} L ${PADDING_X} ${layout.plotBottom} Z`}
              fill="url(#fleetEdgeBellFill)"
            />
            <path
              d={layout.bellPath}
              fill="none"
              stroke="rgba(200, 245, 168, 0.55)"
              strokeWidth="1.5"
            />

            <line
              x1={layout.medianX}
              x2={layout.medianX}
              y1={PADDING_TOP}
              y2={layout.plotBottom}
              stroke="rgba(255, 255, 255, 0.22)"
              strokeDasharray="4 4"
            />
            <line
              x1={layout.meanX}
              x2={layout.meanX}
              y1={PADDING_TOP}
              y2={layout.plotBottom}
              stroke="rgba(6, 182, 212, 0.55)"
              strokeDasharray="2 5"
            />

            {layout.markers.map(({ agent, x, y }) => {
              const isFocused = focusAgentId === agent.id;
              const isDimmed = focusAgentId != null && !isFocused;
              const radius = isFocused ? 10 : 6;
              return (
                <g
                  key={agent.id}
                  className={`portfolio-fleet-edge-marker${isFocused ? " is-focused" : ""}${isDimmed ? " is-dimmed" : ""}`}
                  aria-hidden="true"
                  opacity={isDimmed ? 0.45 : 1}
                >
                  <circle
                    cx={x}
                    cy={y}
                    r={radius}
                    fill={FLEET_EDGE_TIER_COLORS[agent.tier]}
                    stroke={
                      isFocused
                        ? "var(--terminal-brand)"
                        : "rgba(10, 14, 23, 0.9)"
                    }
                    strokeWidth={isFocused ? 2.5 : 1.5}
                  />
                  <text
                    x={x}
                    y={y + 16}
                    textAnchor="middle"
                    className="portfolio-fleet-edge-marker-label"
                  >
                    {agent.icon ?? agent.label.slice(0, 2)}
                  </text>
                </g>
              );
            })}

            {layout.axisTicks.map((tick) => (
              <text
                key={`${tick.label}-${tick.x}`}
                x={tick.x}
                y={CHART_HEIGHT - 8}
                textAnchor="middle"
                className="portfolio-fleet-edge-axis-label"
              >
                {tick.label}
              </text>
            ))}
          </svg>

          <div className="portfolio-fleet-edge-marker-layer">
            {layout.markers.map(({ agent, x, y }) => {
              if (focusAgentId != null && focusAgentId !== agent.id) {
                return null;
              }
              return (
                <BubbleTip
                  key={agent.id}
                  id={BUBBLE_TIP_IDS.fleetEdgeAgent}
                  title={buildAgentTipTitle(agent)}
                  content={buildAgentTipContent(agent)}
                  side="top"
                >
                  <button
                    type="button"
                    className="portfolio-fleet-edge-marker-hit"
                    style={{
                      left: `${(x / CHART_WIDTH) * 100}%`,
                      top: `${(y / CHART_HEIGHT) * 100}%`,
                    }}
                    aria-label={`${agent.label} fleet edge details`}
                  />
                </BubbleTip>
              );
            })}
          </div>
        </div>
      ) : (
        <p className="terminal-text-muted portfolio-fleet-edge-empty">
          No agent competitiveness data.
        </p>
      )}

      <div className="portfolio-fleet-edge-legend">
        {TIER_ORDER.map((tier) => (
          <span key={tier} className="portfolio-fleet-edge-legend-item">
            <i
              className="portfolio-fleet-edge-tier-dot"
              style={{ background: FLEET_EDGE_TIER_COLORS[tier] }}
            />
            {FLEET_EDGE_TIER_LABELS[tier]}
          </span>
        ))}
        <span className="portfolio-fleet-edge-legend-note">
          Dashed line = fleet median · cyan = mean
        </span>
      </div>
    </div>
  );
}

export default React.memo(PortfolioFleetEdgeChart);
