import {
  AGENT_TASK_GRID_COLUMNS,
  AGENT_TASK_GRID_COLUMNS_MD,
  AGENT_TASK_GRID_COLUMNS_MD_NO_MARKET,
  AGENT_TASK_GRID_COLUMNS_NO_MARKET,
  AGENT_TASK_GRID_COLUMNS_SM,
} from "../../constants";
import { isMobileBreakpoint } from "../../configs/terminalLayoutConfig";

export type AgentTasksTableLayout =
  | "full"
  | "md"
  | "sm"
  | "cards"
  | "cardsTight";

export interface AgentTasksColumnConfig {
  showTaskId: boolean;
  showStatus: boolean;
  showMarketBucket: boolean;
  showIntent: boolean;
  showParentAgent: boolean;
  showMemory: boolean;
  mergeMarketAgent: boolean;
  actionsMode: "inline" | "menu";
  gridColumns: string;
}

export interface AgentTasksColumnPrefs {
  showMarketBucket: boolean;
}

const COLUMN_CONFIGS: Record<AgentTasksTableLayout, AgentTasksColumnConfig> = {
  full: {
    showTaskId: true,
    showStatus: true,
    showMarketBucket: false,
    showIntent: true,
    showParentAgent: true,
    showMemory: true,
    mergeMarketAgent: false,
    actionsMode: "inline",
    gridColumns: AGENT_TASK_GRID_COLUMNS_NO_MARKET,
  },
  md: {
    showTaskId: false,
    showStatus: true,
    showMarketBucket: false,
    showIntent: true,
    showParentAgent: true,
    showMemory: false,
    mergeMarketAgent: false,
    actionsMode: "inline",
    gridColumns: AGENT_TASK_GRID_COLUMNS_MD_NO_MARKET,
  },
  sm: {
    showTaskId: false,
    showStatus: true,
    showMarketBucket: false,
    showIntent: true,
    showParentAgent: false,
    showMemory: false,
    mergeMarketAgent: true,
    actionsMode: "menu",
    gridColumns: AGENT_TASK_GRID_COLUMNS_SM,
  },
  cards: {
    showTaskId: false,
    showStatus: true,
    showMarketBucket: false,
    showIntent: true,
    showParentAgent: false,
    showMemory: false,
    mergeMarketAgent: true,
    actionsMode: "menu",
    gridColumns: "",
  },
  cardsTight: {
    showTaskId: false,
    showStatus: true,
    showMarketBucket: false,
    showIntent: true,
    showParentAgent: false,
    showMemory: false,
    mergeMarketAgent: true,
    actionsMode: "menu",
    gridColumns: "",
  },
};

function resolveGridColumns(
  layout: AgentTasksTableLayout,
  showMarketBucket: boolean,
): string {
  switch (layout) {
    case "full":
      return showMarketBucket
        ? AGENT_TASK_GRID_COLUMNS
        : AGENT_TASK_GRID_COLUMNS_NO_MARKET;
    case "md":
      return showMarketBucket
        ? AGENT_TASK_GRID_COLUMNS_MD
        : AGENT_TASK_GRID_COLUMNS_MD_NO_MARKET;
    default:
      return COLUMN_CONFIGS[layout].gridColumns;
  }
}

export function getAgentTasksTableLayout(breakpoint: string): AgentTasksTableLayout {
  if (breakpoint === "xxs") return "cardsTight";
  if (isMobileBreakpoint(breakpoint)) return "cards";
  if (breakpoint === "sm") return "sm";
  if (breakpoint === "md") return "md";
  return "full";
}

export function getAgentTasksColumnConfig(
  layout: AgentTasksTableLayout,
): AgentTasksColumnConfig {
  return COLUMN_CONFIGS[layout];
}

export function applyAgentTasksColumnPrefs(
  layout: AgentTasksTableLayout,
  prefs: AgentTasksColumnPrefs,
): AgentTasksColumnConfig {
  const base = COLUMN_CONFIGS[layout];
  if (base.mergeMarketAgent) {
    return base;
  }

  const showMarketBucket = prefs.showMarketBucket;
  return {
    ...base,
    showMarketBucket,
    gridColumns: resolveGridColumns(layout, showMarketBucket),
  };
}

export function isAgentTasksCardLayout(layout: AgentTasksTableLayout): boolean {
  return layout === "cards" || layout === "cardsTight";
}

export function supportsAgentTasksMarketBucketColumn(
  layout: AgentTasksTableLayout,
): boolean {
  return layout === "full" || layout === "md";
}
