import React from "react";

const SIZE = 20;
const STROKE = 2.95;
const RADIUS = (SIZE - STROKE) / 2;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

export interface IntentGateCountdownRingProps {
  waitSeconds: number;
  runKey: string;
  isPaused: boolean;
  isComplete: boolean;
  onClockClick: () => void;
  ariaLabel?: string;
}

function IntentGateCountdownRing({
  waitSeconds,
  runKey,
  isPaused,
  isComplete,
  onClockClick,
  ariaLabel = "Intent auto-timer — click to show approve and reject",
}: IntentGateCountdownRingProps): JSX.Element {
  const isActive = waitSeconds > 0 && !isComplete;

  return (
    <button
      type="button"
      className={[
        "intent-gate-countdown-ring",
        isActive ? "intent-gate-countdown-ring--active" : "",
        isPaused && isActive ? "intent-gate-countdown-ring--paused" : "",
        isComplete ? "intent-gate-countdown-ring--complete" : "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={
        {
          "--intent-gate-wait": `${waitSeconds}s`,
          "--intent-gate-circumference": CIRCUMFERENCE,
        } as React.CSSProperties
      }
      onClick={onClockClick}
      aria-label={ariaLabel}
    >
      <svg
        width={SIZE}
        height={SIZE}
        viewBox={`0 0 ${SIZE} ${SIZE}`}
        aria-hidden
        className="intent-gate-countdown-ring-svg"
      >
        <circle
          className="intent-gate-countdown-ring-track"
          cx={SIZE / 2}
          cy={SIZE / 2}
          r={RADIUS}
          fill="none"
          strokeWidth={STROKE}
        />
        <circle
          key={runKey}
          className="intent-gate-countdown-ring-progress"
          cx={SIZE / 2}
          cy={SIZE / 2}
          r={RADIUS}
          fill="none"
          strokeWidth={STROKE}
          strokeLinecap="round"
          strokeDasharray={CIRCUMFERENCE}
          transform={`rotate(-90 ${SIZE / 2} ${SIZE / 2})`}
        />
      </svg>
      <span className="intent-gate-countdown-ring-icon" aria-hidden>
        <svg
          viewBox="0 0 30.393 30.393"
          className="intent-gate-countdown-ring-clock"
          aria-hidden
        >
          <path
            fill="currentColor"
            d="M14.49,14.623c0,0-3.553-3.459-4.939-7.436V6.105H20.84v1.082c-1.8,4.391-4.939,7.436-4.939,7.436H14.49z"
          />
          <path
            fill="currentColor"
            d="M24.91,4.961V3.254h1.619V0H3.864v3.254h1.618v1.707c0,2.607,4.678,9.727,4.899,10.24c-0.217,0.514-4.899,7.633-4.899,10.229v1.705H3.864v3.258h22.665v-3.258H24.91V25.43c0-2.609-4.682-9.682-4.929-10.234C20.228,14.643,24.91,7.568,24.91,4.961z M23.291,25.43v1.705H7.1V25.43c0-1.873,4.961-9.295,4.961-10.234S7.1,6.836,7.1,4.961V3.254h16.19v1.707c0,1.875-5.001,9.295-5.001,10.234S23.291,23.557,23.291,25.43z"
          />
        </svg>
      </span>
    </button>
  );
}

export default React.memo(IntentGateCountdownRing);
