import type { LineData, UTCTimestamp } from "lightweight-charts";
import type { TradeHistoryRow } from "../sdk/types/data";

export type PortfolioTimeRange = "all" | "30d" | "7d" | "24h";

const DAY_MS = 24 * 60 * 60 * 1000;

const RANGE_MS: Record<Exclude<PortfolioTimeRange, "all">, number> = {
  "30d": 30 * DAY_MS,
  "7d": 7 * DAY_MS,
  "24h": DAY_MS,
};

export interface PortfolioPnlSeries {
  id: string;
  label: string;
  color: string;
  data: LineData<UTCTimestamp>[];
}

function toUtcTimestamp(ms: number): UTCTimestamp {
  return Math.floor(ms / 1000) as UTCTimestamp;
}

/**
 * Lightweight Charts requires strictly ascending UTCTimestamp values.
 * Multiple fills in the same second update the last point instead of pushing.
 */
export function appendAscendingLinePoint(
  data: LineData<UTCTimestamp>[],
  time: UTCTimestamp,
  value: number,
): void {
  const last = data[data.length - 1];
  if (last) {
    if (last.time === time) {
      last.value = value;
      return;
    }
    if (last.time > time) {
      return;
    }
  }
  data.push({ time, value });
}

export function sanitizeLineDataForChart(
  data: LineData<UTCTimestamp>[],
): LineData<UTCTimestamp>[] {
  const result: LineData<UTCTimestamp>[] = [];
  for (const point of data) {
    appendAscendingLinePoint(result, point.time, point.value);
  }
  return result;
}

export function buildEquityCurveData(
  values: number[],
): LineData<UTCTimestamp>[] {
  if (values.length === 0) return [];

  const now = Date.now();
  return values.map((value, index) => ({
    time: toUtcTimestamp(now - (values.length - 1 - index) * DAY_MS),
    value,
  }));
}

/** Scale a seed curve so its last point equals targetEndEquity (preserves shape). */
export function scaleEquityCurveSeed(
  seed: number[],
  targetEndEquity: number,
): number[] {
  if (seed.length === 0) {
    return targetEndEquity > 0 ? [targetEndEquity] : [0];
  }
  if (!Number.isFinite(targetEndEquity) || targetEndEquity <= 0) {
    return seed.map(() => 0);
  }
  const seedEnd = seed[seed.length - 1]!;
  if (seedEnd <= 0) {
    return seed.map(() => targetEndEquity);
  }
  const factor = targetEndEquity / seedEnd;
  return seed.map((value) => value * factor);
}

export function buildAnchoredEquityCurveData(
  seed: number[],
  targetEndEquity: number,
): LineData<UTCTimestamp>[] {
  return buildEquityCurveData(scaleEquityCurveSeed(seed, targetEndEquity));
}

export function filterLineDataByRange(
  data: LineData<UTCTimestamp>[],
  range: PortfolioTimeRange,
): LineData<UTCTimestamp>[] {
  if (range === "all" || data.length === 0) return data;

  const cutoff = toUtcTimestamp(Date.now() - RANGE_MS[range]);
  const filtered = data.filter((point) => point.time >= cutoff);
  if (filtered.length === 0) return data.slice(-1);

  const lastBeforeCutoff = [...data].reverse().find((point) => point.time < cutoff);
  if (lastBeforeCutoff && filtered[0]!.time > cutoff) {
    return [{ time: cutoff, value: lastBeforeCutoff.value }, ...filtered];
  }

  return filtered;
}

export function filterPnlSeriesByRange(
  series: PortfolioPnlSeries[],
  range: PortfolioTimeRange,
): PortfolioPnlSeries[] {
  return series.map((entry) => ({
    ...entry,
    data: filterLineDataByRange(entry.data, range),
  }));
}

export function buildCumulativePnlSeries(
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  filterAgentIds: string[],
  getAgentLabel: (agentId: string) => string,
  agentColor: (index: number) => string,
): PortfolioPnlSeries[] {
  const sorted = [...trades].sort((a, b) => a.time - b.time);
  const agentTotals = new Map<string, number>();
  const agentData = new Map<string, LineData<UTCTimestamp>[]>();
  let manualTotal = 0;
  const manualData: LineData<UTCTimestamp>[] = [];
  let colorIdx = 0;
  const agentColorMap = new Map<string, string>();

  for (const trade of sorted) {
    const pnl = trade.closedPnl ?? 0;
    const agentId = trade.agentTaskId
      ? taskAgentMap.get(trade.agentTaskId)
      : undefined;

    if (
      filterAgentIds.length > 0 &&
      agentId &&
      !filterAgentIds.includes(agentId)
    ) {
      continue;
    }

    const time = toUtcTimestamp(trade.time);

    if (agentId) {
      const nextTotal = (agentTotals.get(agentId) ?? 0) + pnl;
      agentTotals.set(agentId, nextTotal);
      if (!agentData.has(agentId)) {
        agentData.set(agentId, []);
        agentColorMap.set(agentId, agentColor(colorIdx++));
      }
      appendAscendingLinePoint(agentData.get(agentId)!, time, nextTotal);
      continue;
    }

    if (filterAgentIds.length > 0) continue;

    manualTotal += pnl;
    appendAscendingLinePoint(manualData, time, manualTotal);
  }

  const result: PortfolioPnlSeries[] = [];

  for (const [id, data] of agentData) {
    if (data.length === 0) continue;
    result.push({
      id,
      label: getAgentLabel(id),
      color: agentColorMap.get(id) ?? agentColor(0),
      data,
    });
  }

  if (manualData.length > 0) {
    result.push({
      id: "manual",
      label: "Manual (M)",
      color: "#94a3b8",
      data: manualData,
    });
  }

  return result;
}

export type PnlChartViewMode = "master" | "topAgents" | "bottomAgents" | "manual";

export const PNL_CHART_VIEW_OPTIONS: {
  value: PnlChartViewMode;
  label: string;
}[] = [
  { value: "master", label: "Master PnL" },
  { value: "topAgents", label: "Top 5 agents" },
  { value: "bottomAgents", label: "Bottom 5 agents" },
  { value: "manual", label: "Manual" },
];

const DEFAULT_MASTER_COLOR = "#38bdf8";

export function getSeriesFinalPnl(series: PortfolioPnlSeries): number {
  if (series.data.length === 0) return 0;
  return series.data[series.data.length - 1]!.value;
}

export function rankAgentSeries(
  series: PortfolioPnlSeries[],
  order: "asc" | "desc",
  limit: number,
): PortfolioPnlSeries[] {
  const agents = series.filter((entry) => entry.id !== "manual");
  if (agents.length === 0) return [];

  const takeCount = agents.length <= limit ? agents.length : limit;
  const sorted = [...agents].sort((a, b) => {
    const diff = getSeriesFinalPnl(a) - getSeriesFinalPnl(b);
    return order === "desc" ? -diff : diff;
  });

  return sorted.slice(0, takeCount);
}

export function buildMasterPnlSeries(
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  filterAgentIds: string[],
  label = "Master PnL",
  color = DEFAULT_MASTER_COLOR,
): PortfolioPnlSeries {
  const sorted = [...trades].sort((a, b) => a.time - b.time);
  const data: LineData<UTCTimestamp>[] = [];
  let total = 0;

  for (const trade of sorted) {
    const pnl = trade.closedPnl ?? 0;
    const agentId = trade.agentTaskId
      ? taskAgentMap.get(trade.agentTaskId)
      : undefined;

    if (
      filterAgentIds.length > 0 &&
      agentId &&
      !filterAgentIds.includes(agentId)
    ) {
      continue;
    }

    if (!agentId && filterAgentIds.length > 0) continue;

    total += pnl;
    appendAscendingLinePoint(data, toUtcTimestamp(trade.time), total);
  }

  return { id: "master", label, color, data };
}

export function selectPnlChartSeries(
  allSeries: PortfolioPnlSeries[],
  mode: PnlChartViewMode,
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  filterAgentIds: string[],
): PortfolioPnlSeries[] {
  switch (mode) {
    case "master":
      return [buildMasterPnlSeries(trades, taskAgentMap, filterAgentIds)];
    case "topAgents":
      return rankAgentSeries(allSeries, "desc", 5);
    case "bottomAgents":
      return rankAgentSeries(allSeries, "asc", 5);
    case "manual": {
      const manual = allSeries.find((entry) => entry.id === "manual");
      return manual ? [manual] : [];
    }
    default:
      return allSeries;
  }
}

export interface DailyPnlDay {
  dateKey: string;
  dayOfMonth: number;
  pnl: number | null;
  isEmpty: boolean;
}

function toDateKey(ms: number): string {
  const d = new Date(ms);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function startOfDayMs(ms: number): number {
  const d = new Date(ms);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

export function buildDailyPnlByDay(
  trades: TradeHistoryRow[],
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
  year: number,
  month: number,
): DailyPnlDay[] {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const buckets = new Map<string, number>();

  for (const trade of trades) {
    const pnl = trade.closedPnl;
    if (pnl == null) continue;

    const agentId = trade.agentTaskId
      ? taskAgentMap.get(trade.agentTaskId)
      : undefined;

    if (
      filterAgentIds.length > 0 &&
      agentId &&
      !filterAgentIds.includes(agentId)
    ) {
      continue;
    }
    if (!agentId && filterAgentIds.length > 0) continue;

    const tradeDate = new Date(trade.time);
    if (tradeDate.getFullYear() !== year || tradeDate.getMonth() !== month) {
      continue;
    }

    const key = toDateKey(trade.time);
    buckets.set(key, (buckets.get(key) ?? 0) + pnl);
  }

  const todayStart = startOfDayMs(Date.now());
  const result: DailyPnlDay[] = [];

  for (let day = 1; day <= daysInMonth; day++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const dayStart = startOfDayMs(new Date(year, month, day).getTime());

    if (dayStart > todayStart) {
      result.push({ dateKey, dayOfMonth: day, pnl: null, isEmpty: true });
      continue;
    }

    const pnl = buckets.get(dateKey);
    if (pnl === undefined) {
      result.push({ dateKey, dayOfMonth: day, pnl: null, isEmpty: true });
    } else {
      result.push({ dateKey, dayOfMonth: day, pnl, isEmpty: false });
    }
  }

  return result;
}

export interface DailyPnlSummary {
  realizedPnl7d: number;
  realizedPnl7dPct: number;
  winRatePct: number;
  totalPnl: number;
  totalPnlPct: number;
  unrealizedProfits: number;
  /** Agent share of fleet total PnL when in focus comparison mode. */
  agentPctOfFleetTotal?: number;
  /** Fleet-wide total PnL for vs-fleet comparison row. */
  fleetTotalPnl?: number;
}

const FOCUS_EQUITY_COLOR = "#c8f5a8";
const REST_FLEET_EQUITY_COLOR = "#64748b";

function pnlDataToEquityCurve(
  pnlData: LineData<UTCTimestamp>[],
  baseline: number,
): LineData<UTCTimestamp>[] {
  return pnlData.map((point) => ({
    time: point.time,
    value: baseline + point.value,
  }));
}

function buildFocusRestPnlFromTrades(
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  focusAgentId: string,
): { focus: LineData<UTCTimestamp>[]; rest: LineData<UTCTimestamp>[] } {
  const sorted = [...trades].sort((a, b) => a.time - b.time);
  const focusData: LineData<UTCTimestamp>[] = [];
  const restData: LineData<UTCTimestamp>[] = [];
  let focusTotal = 0;
  let restTotal = 0;

  for (const trade of sorted) {
    const pnl = trade.closedPnl;
    if (pnl == null) continue;

    const agentId = trade.agentTaskId
      ? taskAgentMap.get(trade.agentTaskId)
      : undefined;
    if (!agentId) continue;

    const time = toUtcTimestamp(trade.time);
    if (agentId === focusAgentId) {
      focusTotal += pnl;
      appendAscendingLinePoint(focusData, time, focusTotal);
    } else {
      restTotal += pnl;
      appendAscendingLinePoint(restData, time, restTotal);
    }
  }

  return { focus: focusData, rest: restData };
}

export function buildFocusEquityComparisonSeries(
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  focusAgentId: string,
  accountEquity: number,
  agentBucketEquity: number,
  getAgentLabel: (agentId: string) => string,
  offlineSeed?: number[],
): PortfolioPnlSeries[] {
  const focusShare =
    accountEquity > 0 ? agentBucketEquity / accountEquity : 0.5;
  const focusBaseline = accountEquity * focusShare;
  const restBaseline = Math.max(accountEquity - focusBaseline, 0);

  if (offlineSeed && offlineSeed.length > 0) {
    const anchoredSeed = scaleEquityCurveSeed(offlineSeed, accountEquity);
    const focusValues = anchoredSeed.map((v) => v * focusShare);
    const restValues = anchoredSeed.map((v, i) =>
      Math.max(v - focusValues[i]!, 0),
    );
    return [
      {
        id: focusAgentId,
        label: getAgentLabel(focusAgentId),
        color: FOCUS_EQUITY_COLOR,
        data: buildEquityCurveData(focusValues),
      },
      {
        id: "rest",
        label: "Rest of fleet",
        color: REST_FLEET_EQUITY_COLOR,
        data: buildEquityCurveData(restValues),
      },
    ];
  }

  const { focus: focusPnl, rest: restPnl } = buildFocusRestPnlFromTrades(
    trades,
    taskAgentMap,
    focusAgentId,
  );

  const focusEquity = pnlDataToEquityCurve(focusPnl, focusBaseline);
  const restEquity = pnlDataToEquityCurve(restPnl, restBaseline);

  if (focusEquity.length === 0 && restEquity.length === 0) {
    return [
      {
        id: focusAgentId,
        label: getAgentLabel(focusAgentId),
        color: FOCUS_EQUITY_COLOR,
        data: [{ time: toUtcTimestamp(Date.now()), value: focusBaseline }],
      },
      {
        id: "rest",
        label: "Rest of fleet",
        color: REST_FLEET_EQUITY_COLOR,
        data: [{ time: toUtcTimestamp(Date.now()), value: restBaseline }],
      },
    ];
  }

  return [
    {
      id: focusAgentId,
      label: getAgentLabel(focusAgentId),
      color: FOCUS_EQUITY_COLOR,
      data: focusEquity,
    },
    {
      id: "rest",
      label: "Rest of fleet",
      color: REST_FLEET_EQUITY_COLOR,
      data: restEquity,
    },
  ];
}

export function buildFocusVolume14d(
  trades: TradeHistoryRow[],
  taskAgentMap: Map<string, string>,
  focusAgentId: string,
  cutoffMs: number,
): { focus: number; otherAgents: number } {
  let focus = 0;
  let otherAgents = 0;

  for (const trade of trades) {
    if (trade.time < cutoffMs) continue;
    if (!trade.agentTaskId) continue;

    const agentId = taskAgentMap.get(trade.agentTaskId);
    if (!agentId) continue;

    const notional = trade.size * trade.price;
    if (agentId === focusAgentId) {
      focus += notional;
    } else {
      otherAgents += notional;
    }
  }

  return { focus, otherAgents };
}

export interface AgentBucketCollection {
  bucketId: string;
  totalEquity: number;
  marginType?: string;
  marginMode?: string;
}

export interface EquityBreakdownSegmentInput {
  id: string;
  label: string;
  value: number;
  color: string;
}

function marginTypeKey(marginType?: string, marginMode?: string): "cross" | "isolated" {
  const normalized = `${marginType ?? ""} ${marginMode ?? ""}`.toLowerCase();
  if (normalized.includes("isolated")) return "isolated";
  return "cross";
}

export function buildFocusEquityBreakdown(
  focusAgentId: string,
  agentBucketIds: Set<string>,
  collections: AgentBucketCollection[],
  spotWalletBalance: number,
): EquityBreakdownSegmentInput[] {
  const segments: EquityBreakdownSegmentInput[] = [];

  if (spotWalletBalance > 0) {
    segments.push({
      id: "spot",
      label: "Spot wallet (shared)",
      value: spotWalletBalance,
      color: "#64748b",
    });
  }

  let crossTotal = 0;
  let isolatedTotal = 0;

  for (const bucket of collections) {
    if (!agentBucketIds.has(String(bucket.bucketId))) continue;
    const key = marginTypeKey(bucket.marginType, bucket.marginMode);
    if (key === "isolated") {
      isolatedTotal += bucket.totalEquity;
    } else {
      crossTotal += bucket.totalEquity;
    }
  }

  if (crossTotal > 0) {
    segments.push({
      id: "cross",
      label: "Cross",
      value: crossTotal,
      color: "#38bdf8",
    });
  }

  if (isolatedTotal > 0) {
    segments.push({
      id: "isolated",
      label: "Isolated",
      value: isolatedTotal,
      color: "#a78bfa",
    });
  }

  return segments.filter((s) => s.value > 0);
}

export function buildFocusVsFleetEquity(
  focusAgentId: string,
  agentLabel: string,
  agentBucketEquity: number,
  accountEquity: number,
  focusColor = FOCUS_EQUITY_COLOR,
): EquityBreakdownSegmentInput[] {
  const restEquity = Math.max(accountEquity - agentBucketEquity, 0);
  const segments: EquityBreakdownSegmentInput[] = [];

  if (agentBucketEquity > 0) {
    segments.push({
      id: focusAgentId,
      label: agentLabel,
      value: agentBucketEquity,
      color: focusColor,
    });
  }

  if (restEquity > 0) {
    segments.push({
      id: "rest",
      label: "Other agents",
      value: restEquity,
      color: REST_FLEET_EQUITY_COLOR,
    });
  }

  return segments;
}

export function scaleDailyPnlSummary(
  summary: DailyPnlSummary,
  scale: number,
  fleetSummary: DailyPnlSummary,
): DailyPnlSummary {
  const scaledTotal = summary.totalPnl * scale;
  const fleetTotal = fleetSummary.totalPnl;
  return {
    realizedPnl7d: summary.realizedPnl7d * scale,
    realizedPnl7dPct: summary.realizedPnl7dPct * scale,
    winRatePct: summary.winRatePct,
    totalPnl: scaledTotal,
    totalPnlPct: summary.totalPnlPct * scale,
    unrealizedProfits: summary.unrealizedProfits * scale,
    fleetTotalPnl: fleetTotal,
    agentPctOfFleetTotal:
      fleetTotal !== 0 ? (scaledTotal / fleetTotal) * 100 : 0,
  };
}

export function scaleDailyPnlByDay(
  days: DailyPnlDay[],
  scale: number,
): DailyPnlDay[] {
  return days.map((day) =>
    day.pnl === null
      ? day
      : { ...day, pnl: day.pnl * scale },
  );
}

const SEVEN_DAYS_MS = 7 * DAY_MS;

export function computeDailyPnlSummary(
  trades: TradeHistoryRow[],
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
  accountEquity: number,
  unrealizedProfits: number,
): DailyPnlSummary {
  const now = Date.now();
  const cutoff7d = now - SEVEN_DAYS_MS;

  let realized7d = 0;
  let totalPnl = 0;
  let wins = 0;
  let closedCount = 0;

  for (const trade of trades) {
    const pnl = trade.closedPnl;
    if (pnl == null) continue;

    const agentId = trade.agentTaskId
      ? taskAgentMap.get(trade.agentTaskId)
      : undefined;

    if (
      filterAgentIds.length > 0 &&
      agentId &&
      !filterAgentIds.includes(agentId)
    ) {
      continue;
    }
    if (!agentId && filterAgentIds.length > 0) continue;

    totalPnl += pnl;
    closedCount += 1;
    if (pnl > 0) wins += 1;

    if (trade.time >= cutoff7d) {
      realized7d += pnl;
    }
  }

  const baseline = Math.max(accountEquity - totalPnl, 1);
  const baseline7d = Math.max(accountEquity - realized7d, 1);

  return {
    realizedPnl7d: realized7d,
    realizedPnl7dPct: (realized7d / baseline7d) * 100,
    winRatePct: closedCount > 0 ? (wins / closedCount) * 100 : 0,
    totalPnl,
    totalPnlPct: (totalPnl / baseline) * 100,
    unrealizedProfits,
  };
}
