import { useEffect, useMemo } from "react";

import type {
  CopyRelation,
  CopySettings,
} from "../../offline/mock_data/fleetCopyRelations";
import { useFleetCopyStore } from "../store/fleetCopyStore";

export function useFleetCopyRelations(walletAddress?: string | null): {
  relations: CopyRelation[];
  hydrated: boolean;
  hasActiveCopy: (targetCatalogAgentId: string) => boolean;
  getRelationForAgent: (targetCatalogAgentId: string) => CopyRelation | undefined;
  addCopyRelation: (
    targetCatalogAgentId: string,
    copySettings: Omit<CopySettings, "startedAt"> & { startedAt?: string },
  ) => CopyRelation | null;
  removeCopyRelation: (relationId: string) => void;
} {
  const copierWallet = walletAddress?.trim().toLowerCase() ?? null;
  const hydrated = useFleetCopyStore((state) => state.hydrated);
  const relations = useFleetCopyStore((state) => state.relations);
  const hydrate = useFleetCopyStore((state) => state.hydrate);
  const addCopyRelationStore = useFleetCopyStore((state) => state.addCopyRelation);
  const removeCopyRelationStore = useFleetCopyStore(
    (state) => state.removeCopyRelation,
  );
  const hasActiveCopyStore = useFleetCopyStore((state) => state.hasActiveCopy);
  const getRelationForAgentStore = useFleetCopyStore(
    (state) => state.getRelationForAgent,
  );

  useEffect(() => {
    hydrate(copierWallet);
  }, [copierWallet, hydrate]);

  return useMemo(
    () => ({
      relations,
      hydrated,
      hasActiveCopy: hasActiveCopyStore,
      getRelationForAgent: getRelationForAgentStore,
      addCopyRelation: (targetCatalogAgentId, copySettings) => {
        if (!copierWallet) return null;
        return addCopyRelationStore(
          copierWallet,
          targetCatalogAgentId,
          copySettings,
        );
      },
      removeCopyRelation: removeCopyRelationStore,
    }),
    [
      relations,
      hydrated,
      copierWallet,
      addCopyRelationStore,
      removeCopyRelationStore,
      hasActiveCopyStore,
      getRelationForAgentStore,
    ],
  );
}
