import type { CopyAutonomyPreset } from "../../../offline/mock_data/fleetCopyRelations";
import type { Bucket } from "../../sdk";

export const COPY_AGENT_MIN_MARGIN = 10;
export const COPY_AGENT_MIN_SIZE_PCT = 5;
export const COPY_AGENT_MAX_SIZE_PCT = 100;
export const COPY_AGENT_DEFAULT_SIZE_PCT = 25;
export const COPY_AGENT_DEFAULT_STARTING_MARGIN = 100;

export type CopyBucketDestination =
  | { mode: "new"; startingMargin: number }
  | { mode: "existing"; bucketId: string };

export type CopyAgentConfirmParams = {
  targetCatalogAgentId: string;
  profileName: string;
  perpBaseAsset: string;
  destination: CopyBucketDestination;
  copySizePct: number;
  autonomyPreset: CopyAutonomyPreset;
};

export type CopyAgentFormState = {
  walletConnected: boolean;
  destinationMode: "new" | "existing";
  startingMargin: number;
  existingBucketId: string;
  copySizePct: number;
  spotWalletBalance: number;
  autonomyPreset: CopyAutonomyPreset;
  highAgencyConfirmed: boolean;
  existingBucketShareAcknowledged: boolean;
  riskAcknowledged: boolean;
  selectedBucketEquity: number;
};

export function needsExistingBucketShareConfirm(
  destinationMode: "new" | "existing",
  selectedBucketEquity: number,
): boolean {
  return destinationMode === "existing" && selectedBucketEquity > 0;
}

export function isCopyAgentFormBasicsValid(state: CopyAgentFormState): boolean {
  if (!state.walletConnected) return false;
  if (
    state.copySizePct < COPY_AGENT_MIN_SIZE_PCT ||
    state.copySizePct > COPY_AGENT_MAX_SIZE_PCT
  ) {
    return false;
  }
  if (state.destinationMode === "new") {
    return (
      state.startingMargin >= COPY_AGENT_MIN_MARGIN &&
      state.startingMargin <= state.spotWalletBalance
    );
  }
  return state.existingBucketId.trim().length > 0;
}

export function isCopyAgentConfirmValid(state: CopyAgentFormState): boolean {
  if (!isCopyAgentFormBasicsValid(state)) return false;
  if (!state.riskAcknowledged) return false;
  if (
    state.autonomyPreset === "highAgency" &&
    !state.highAgencyConfirmed
  ) {
    return false;
  }
  if (
    needsExistingBucketShareConfirm(
      state.destinationMode,
      state.selectedBucketEquity,
    ) &&
    !state.existingBucketShareAcknowledged
  ) {
    return false;
  }
  return true;
}

export function buildCopyAgentFormState(
  params: {
    walletConnected: boolean;
    destinationMode: "new" | "existing";
    startingMargin: number;
    existingBucketId: string;
    copySizePct: number;
    spotWalletBalance: number;
    autonomyPreset: CopyAutonomyPreset;
    highAgencyConfirmed: boolean;
    existingBucketShareAcknowledged: boolean;
    riskAcknowledged: boolean;
    selectedBucket: Bucket | null | undefined;
  },
): CopyAgentFormState {
  return {
    walletConnected: params.walletConnected,
    destinationMode: params.destinationMode,
    startingMargin: params.startingMargin,
    existingBucketId: params.existingBucketId,
    copySizePct: params.copySizePct,
    spotWalletBalance: params.spotWalletBalance,
    autonomyPreset: params.autonomyPreset,
    highAgencyConfirmed: params.highAgencyConfirmed,
    existingBucketShareAcknowledged: params.existingBucketShareAcknowledged,
    riskAcknowledged: params.riskAcknowledged,
    selectedBucketEquity: Number(params.selectedBucket?.totalEquity ?? 0),
  };
}

export function buildCopyAgentConfirmParams(
  targetCatalogAgentId: string,
  profileName: string,
  perpBaseAsset: string,
  state: CopyAgentFormState,
  autonomyPreset: CopyAutonomyPreset,
): CopyAgentConfirmParams {
  const destination: CopyBucketDestination =
    state.destinationMode === "new"
      ? { mode: "new", startingMargin: state.startingMargin }
      : { mode: "existing", bucketId: state.existingBucketId };

  return {
    targetCatalogAgentId,
    profileName,
    perpBaseAsset,
    destination,
    copySizePct: state.copySizePct,
    autonomyPreset,
  };
}
