import type {
  DeepPartial,
  ChartOptions,
  AreaSeriesOptions,
} from "lightweight-charts";
import { CrosshairMode, LineStyle, LineType } from "lightweight-charts";

import { TERMINAL_COLORS } from "../../constants/terminalColors";

export const COMPACT_CHART_WIDTH = 72;
export const COMPACT_CHART_HEIGHT = 24;
export const COMPACT_CHART_POSITIVE = TERMINAL_COLORS.long;
export const COMPACT_CHART_NEGATIVE = TERMINAL_COLORS.short;

export function createCompactSparklineChartOptions(): DeepPartial<ChartOptions> {
  return {
    autoSize: true,
    layout: {
      background: { color: "transparent" },
      textColor: "transparent",
      attributionLogo: false,
    },
    grid: {
      vertLines: { visible: false },
      horzLines: { visible: false },
    },
    crosshair: {
      mode: CrosshairMode.Magnet,
      vertLine: {
        visible: true,
        color: TERMINAL_COLORS.muted,
        width: 1,
        style: LineStyle.Dashed,
        labelVisible: false,
      },
      horzLine: {
        visible: false,
        labelVisible: false,
      },
    },
    handleScroll: false,
    handleScale: false,
    rightPriceScale: {
      visible: false,
      autoScale: true,
      scaleMargins: { top: 0.15, bottom: 0.15 },
    },
    leftPriceScale: {
      visible: false,
      autoScale: true,
      scaleMargins: { top: 0.15, bottom: 0.15 },
    },
    timeScale: { visible: false },
  };
}

function areaFillFromLineColor(lineColor: string): {
  topColor: string;
  bottomColor: string;
} {
  if (lineColor === COMPACT_CHART_POSITIVE) {
    return {
      topColor: "rgba(0, 255, 136, 0.18)",
      bottomColor: "rgba(0, 255, 136, 0)",
    };
  }
  if (lineColor === COMPACT_CHART_NEGATIVE) {
    return {
      topColor: "rgba(255, 71, 87, 0.18)",
      bottomColor: "rgba(255, 71, 87, 0)",
    };
  }
  return {
    topColor: `${lineColor}2e`,
    bottomColor: `${lineColor}00`,
  };
}

export function createCompactSparklineAreaOptions(
  lineColor: string,
): DeepPartial<AreaSeriesOptions> {
  const { topColor, bottomColor } = areaFillFromLineColor(lineColor);

  return {
    lineColor,
    topColor,
    bottomColor,
    relativeGradient: false,
    lineWidth: 2,
    lineType: LineType.Curved,
    priceLineVisible: false,
    lastValueVisible: false,
    crosshairMarkerVisible: true,
    crosshairMarkerRadius: 3,
    crosshairMarkerBorderColor: lineColor,
    crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
  };
}

export function createCompactSparklineLineOptions(
  color: string,
): DeepPartial<AreaSeriesOptions> {
  return createCompactSparklineAreaOptions(color);
}
