import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { AgentTask, AgentTaskStatus } from "../../store/types";
import { AGENT_TASK_STATUS_CONFIG, DEFAULT_BASE_URL } from "../../constants";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import { useMarkets } from "../../hooks/useMarkets";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import { Typewriter } from "../ui/Typewriter";
import SafetyAuditLogMetricCell from "./SafetyAuditLogMetricCell";
import SafetyAuditLogRowActions from "./SafetyAuditLogRowActions";
import SafetyLogReviewMiniChart from "./SafetyLogReviewMiniChart";
import { getRiskZone } from "./RiskScoreMetric";
import { getGuardrailMeta, riskImpactLabel } from "./guardrailMeta";
import { resolveReviewChartMarket } from "./resolveReviewChartMarket";
import "../tables/agentTasks.css";

export interface SafetyLogReviewSheetProps {
  isOpen: boolean;
  task: AgentTask | null;
  agentLabel: string;
  sizePct: number;
  baseURL?: string;
  /** Spotlight T4 uses incident copy; default intent review title. */
  reviewKind?: "intent" | "incident";
  /** Hide approve/reject when incident is audit-only (post-hoc T4). */
  showActions?: boolean;
  onSizePctChange: (value: number) => void;
  onApprove: () => void;
  onReject: () => void;
  onClose: () => void;
}

function statusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

const REVIEW_SHEET_ANIMATION_MS = OVERLAY_TIMING.tradeSheetMs;

type ReviewSheetLatch = {
  task: AgentTask;
  agentLabel: string;
  sizePct: number;
};

type PendingReviewAction =
  | { type: "close" }
  | { type: "approve" }
  | { type: "reject" };

function SafetyLogReviewSheet({
  isOpen,
  task,
  agentLabel,
  sizePct,
  baseURL = DEFAULT_BASE_URL,
  reviewKind = "intent",
  showActions = true,
  onSizePctChange,
  onApprove,
  onReject,
  onClose,
}: SafetyLogReviewSheetProps): JSX.Element | null {
  const [latched, setLatched] = useState<ReviewSheetLatch | null>(null);
  const pendingActionRef = useRef<PendingReviewAction | null>(null);

  const handleAfterUnmount = useCallback(() => {
    const pending = pendingActionRef.current;
    pendingActionRef.current = null;
    setLatched(null);

    if (pending?.type === "approve") onApprove();
    else if (pending?.type === "reject") onReject();
  }, [onApprove, onReject]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: REVIEW_SHEET_ANIMATION_MS,
    backdropFadeMs: REVIEW_SHEET_ANIMATION_MS,
    staggerBackdrop: false,
    onAfterUnmount: handleAfterUnmount,
  });

  const requestClose = useCallback(
    (action: PendingReviewAction = { type: "close" }) => {
      if (!isOpen) return;
      pendingActionRef.current = action;
      onClose();
    },
    [isOpen, onClose],
  );

  useOverlayEscapeKey(isOpen, () => requestClose({ type: "close" }));
  useOverlayScrollLock(isOpen && mounted);

  const { markets, fetchMarkets } = useMarkets({ baseURL, autoFetchMarkets: false });

  useEffect(() => {
    if (!isOpen || markets.length > 0) return;
    fetchMarkets().catch(console.error);
  }, [isOpen, markets.length, fetchMarkets]);

  useEffect(() => {
    if (isOpen && task) {
      setLatched({ task, agentLabel, sizePct });
    }
  }, [isOpen, task, agentLabel, sizePct]);

  const display = latched;
  const displayTask = display?.task ?? null;

  const chartMarket = useMemo(
    () => (displayTask ? resolveReviewChartMarket(displayTask, markets) : null),
    [displayTask, markets],
  );

  const [animateIntent, setAnimateIntent] = useState(false);
  const intentTaskId = displayTask?.id ?? null;

  useEffect(() => {
    if (panelOpen && intentTaskId) {
      setAnimateIntent(true);
      return;
    }
    setAnimateIntent(false);
  }, [panelOpen, intentTaskId]);

  if (!mounted || !displayTask || !display) return null;

  const meta = getGuardrailMeta(displayTask);
  const headline = displayTask.trigger || displayTask.description;
  const hasDetail = Boolean(displayTask.trigger && displayTask.description);
  const confidenceZone = getRiskZone(100 - meta.confidencePct);
  const isClosing = !isOpen;
  const taskStatus = statusConfig(displayTask.status);

  const modalContent = (
    <StaggeredOverlayRoot className="safety-log-review-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={() => requestClose({ type: "close" })}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={[
          "safety-log-review-panel",
          isClosing ? "safety-log-review-panel--closing" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        aria-label="Review intent"
      >
        <header className="safety-log-review-header">
          <div className="safety-log-review-header-copy">
            <p className="safety-log-review-eyebrow">{display.agentLabel}</p>
            <h2 className="safety-log-review-title">
              {reviewKind === "incident" ? "Review incident" : "Review intent"}
            </h2>
          </div>
          <button
            type="button"
            className="safety-log-review-close"
            onClick={() => requestClose({ type: "close" })}
            aria-label="Close review"
            disabled={isClosing}
          >
            ×
          </button>
        </header>

        <div className="safety-log-review-body">
          <section className="safety-log-review-section safety-log-review-section--intent">
            <h3 className="terminal-label safety-log-review-section-label">Intent</h3>
            <div className="safety-log-review-intent-copy">
              {animateIntent ? (
                <>
                  <Typewriter
                    text={headline}
                    className="safety-log-review-intent-headline"
                    multiline={hasDetail ? false : "auto"}
                    active={panelOpen}
                  />
                  {hasDetail ? (
                    <Typewriter
                      text={displayTask.description}
                      className="safety-log-review-intent-detail"
                      multiline="auto"
                      active={panelOpen}
                    />
                  ) : null}
                </>
              ) : (
                <>
                  <p className="safety-log-review-intent-headline">{headline}</p>
                  {hasDetail ? (
                    <p className="safety-log-review-intent-detail">{displayTask.description}</p>
                  ) : null}
                </>
              )}
            </div>
          </section>

          {chartMarket ? (
            <section className="safety-log-review-section">
              <h3 className="terminal-label safety-log-review-section-label">Market context</h3>
              <SafetyLogReviewMiniChart
                market={chartMarket}
                taskId={displayTask.id}
              />
            </section>
          ) : null}

          <section className="safety-log-review-section safety-log-review-section--status">
            <h3 className="terminal-label safety-log-review-section-label">Status</h3>
            <div className="safety-log-review-status-card">
              <div className="safety-log-review-status-primary">
                <span
                  className={`agent-task-status-pill agent-task-status-pill--${taskStatus.tone}`}
                >
                  {taskStatus.label}
                </span>
              </div>
              <div className="safety-log-review-status-meta">
                <span className="terminal-label safety-log-review-status-meta-label">
                  Last updated
                </span>
                <time
                  className="terminal-value safety-log-review-status-time"
                  dateTime={new Date(displayTask.updatedAt).toISOString()}
                >
                  {formatRelativeTime(displayTask.updatedAt)}
                </time>
              </div>
            </div>
          </section>

          <section className="safety-log-review-section">
            <h3 className="terminal-label safety-log-review-section-label">Guardrail assessment</h3>
            <div className="safety-log-review-metrics-row">
              <div className="safety-log-review-metric-card">
                <span className="terminal-label safety-log-review-metric-label">Risk impact</span>
                <span
                  className={`guardrail-risk-pill guardrail-risk-pill--${meta.riskImpact}`}
                >
                  {riskImpactLabel(meta.riskImpact)}
                </span>
              </div>
              <div className="safety-log-review-metric-card">
                <span className="terminal-label safety-log-review-metric-label">Confidence</span>
                <SafetyAuditLogMetricCell
                  riskImpact={meta.riskImpact}
                  confidencePct={meta.confidencePct}
                  variant="confidenceOnly"
                />
              </div>
              <div className="safety-log-review-metric-card">
                <span className="terminal-label safety-log-review-metric-label">Est. fill impact</span>
                <span className="terminal-value safety-log-review-metric-value">
                  +{meta.expectedFillImpactBps.toFixed(1)} bps
                </span>
              </div>
            </div>
            <div
              className={[
                "safety-log-review-simulation",
                `safety-log-review-simulation--${confidenceZone}`,
              ].join(" ")}
            >
              <span className="safety-log-review-simulation-label">Simulation note</span>
              <p className="safety-log-review-simulation-text">{meta.simulationNote}</p>
            </div>
          </section>
        </div>

        {showActions ? (
          <footer className="safety-log-review-footer">
            <p className="terminal-label safety-log-review-footer-label">Human action</p>
            <SafetyAuditLogRowActions
              taskId={displayTask.id}
              sizePct={display.sizePct}
              onSizePctChange={onSizePctChange}
              onApprove={() => requestClose({ type: "approve" })}
              onReject={() => requestClose({ type: "reject" })}
              showSizeExplanation
            />
          </footer>
        ) : (
          <footer className="safety-log-review-footer safety-log-review-footer--readonly">
            <button
              type="button"
              className="trade-agent-deck-btn"
              onClick={() => requestClose({ type: "close" })}
            >
              Close
            </button>
          </footer>
        )}
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(SafetyLogReviewSheet);
