import { getCopyMirrorBucketRealizedDelta } from "../../../offline/mock_data/copyMirrorState";
import type { CopyTourGateKind } from "./constants";

export function isCopyTourGateSatisfied(
  gateKind: CopyTourGateKind | undefined,
  state: {
    confirmComplete: boolean;
    stripVisible: boolean;
    mirrorProfit: boolean;
    pnlVisible: boolean;
  },
): boolean {
  switch (gateKind) {
    case undefined:
    case "none":
      return true;
    case "confirmComplete":
      return state.confirmComplete;
    case "stripVisible":
      return state.stripVisible;
    case "mirrorProfit":
      return state.mirrorProfit;
    case "pnlVisible":
      return state.pnlVisible;
    default:
      return true;
  }
}

export function resolveMirrorProfitForTour(
  wallet: string | null | undefined,
  bucketId: string | null | undefined,
): boolean {
  if (!wallet?.trim() || !bucketId?.trim()) return false;
  return getCopyMirrorBucketRealizedDelta(wallet, bucketId) > 0;
}

export function inferTourBreakpointFromWidth(width: number): string {
  if (width >= 1200) return "lg";
  if (width >= 992) return "md";
  if (width >= 768) return "sm";
  return "xs";
}
