import React from "react";
import { formatCurrency } from "../../../sdk/utils/display";
import { getChainsForAsset } from "../../../constants/crossChain";
import {
  SECURITY_STAGES,
  type CrossChainTransferRecord,
  type SecurityStage,
} from "../../../types/crossChainFlow";
import { CrossChainSecurityStepper } from "./CrossChainSecurityStepper";
import "./cross-chain.css";

export interface CrossChainTrackingPanelProps {
  record: CrossChainTransferRecord;
  validatorCount: number;
  onDemoLinkClick?: () => void;
}

function shortHash(hash?: string): string {
  if (!hash) return "—";
  return `${hash.slice(0, 8)}…${hash.slice(-4)}`;
}

function stageIdx(stage: SecurityStage): number {
  return SECURITY_STAGES.indexOf(stage);
}

export function CrossChainTrackingPanel({
  record,
  validatorCount,
  onDemoLinkClick,
}: CrossChainTrackingPanelProps): JSX.Element {
  const chainName =
    getChainsForAsset(record.assetId).find((c) => c.value === record.chain)
      ?.label ?? record.chain;
  const activeStage: SecurityStage =
    record.currentStage === "complete" ? "delivered" : record.currentStage;
  const activeIdx = stageIdx(activeStage);
  const validators = validatorCount || record.validatorCount || 0;

  const rows: Array<{
    key: SecurityStage;
    label: string;
    meta?: string;
    link?: boolean;
  }> = [
    { key: "authorize", label: "Authorized", meta: record.originTxHash ? shortHash(record.originTxHash) : undefined, link: true },
    { key: "submit", label: "Submitted", meta: record.originTxHash ? shortHash(record.originTxHash) : undefined, link: true },
    {
      key: "locked",
      label: `Locked on ${record.mode === "deposit" ? chainName : "Morpheum"}`,
      meta: activeStage === "locked" ? "confirming (3/12)" : undefined,
    },
    {
      key: "attested",
      label: "Validators attesting",
      meta: `${validators} / 9 signatures`,
    },
    {
      key: "delivered",
      label: `Delivering to ${record.mode === "deposit" ? "Morpheum" : chainName}`,
    },
  ];

  return (
    <div data-tour="deposit-tour-tracking">
      <p className="terminal-value cross-chain-tracking-amount">
        {formatCurrency(record.amount)} {record.assetId}
      </p>
      <CrossChainSecurityStepper activeStage={activeStage} />
      <div className="cross-chain-tracking-list">
        {rows.map((row) => {
          const idx = stageIdx(row.key);
          const isDone = idx < activeIdx;
          const isActive = idx === activeIdx;
          return (
            <div key={row.key} className="cross-chain-tracking-row">
              <span className="cross-chain-tracking-row-icon">
                {isDone ? "✓" : isActive ? "●" : "○"}
              </span>
              <div className="cross-chain-tracking-row-body">
                <div className="cross-chain-tracking-row-title">{row.label}</div>
                {row.meta && (
                  <div className="cross-chain-tracking-row-meta">
                    {row.meta}
                    {row.link ? (
                      <>
                        {" "}
                        <button
                          type="button"
                          className="cross-chain-explorer-link"
                          onClick={onDemoLinkClick}
                        >
                          ↗
                        </button>
                      </>
                    ) : null}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
      <p className="cross-chain-close-safe-hint">
        ⓘ Safe to close — track anytime via the history pill.
      </p>
    </div>
  );
}
