import React, { useCallback, useMemo, useState } from "react";
import type { AgentTask } from "../../store/types";
import type { TooltipGroupId } from "../preference/settingsRegistry";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import { getRiskZone } from "./RiskScoreMetric";
import { getGuardrailMeta, riskImpactLabel } from "./guardrailMeta";

export interface GuardrailIntentCardExtrasProps {
  task: AgentTask;
  baseAssetLabel?: string;
  onApprove: (taskId: string, sizePct: number) => void;
  onReject: (taskId: string) => void;
  dimmed?: boolean;
  hideGateActions?: boolean;
  onSizePctChange?: (sizePct: number) => void;
  tooltipGroup: TooltipGroupId;
}

function GuardrailIntentCardExtras({
  task,
  baseAssetLabel = "market",
  onApprove,
  onReject,
  dimmed = false,
  hideGateActions = false,
  onSizePctChange,
  tooltipGroup,
}: GuardrailIntentCardExtrasProps): JSX.Element {
  const meta = useMemo(() => getGuardrailMeta(task), [task]);
  const [sizePct, setSizePct] = useState(100);
  const [tweakOpen, setTweakOpen] = useState(false);

  const handleSizePctChange = useCallback(
    (next: number) => {
      setSizePct(next);
      onSizePctChange?.(next);
    },
    [onSizePctChange],
  );

  const confidenceZone = getRiskZone(100 - meta.confidencePct);

  const handleApprove = useCallback(() => {
    onApprove(task.id, sizePct);
  }, [onApprove, task.id, sizePct]);

  return (
    <div
      className={[
        "guardrail-intent-extras",
        dimmed ? "guardrail-intent-extras--dimmed" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <div className="guardrail-intent-extras-metrics">
        <BubbleTip id={BUBBLE_TIP_IDS.gateIntentConfidence} group={tooltipGroup}>
          <span
            className={`guardrail-confidence-badge guardrail-confidence-badge--${confidenceZone}`}
          >
            {meta.confidencePct}% conf
          </span>
        </BubbleTip>
        <BubbleTip id={BUBBLE_TIP_IDS.gateIntentRiskImpact} group={tooltipGroup}>
          <span
            className={`guardrail-risk-pill guardrail-risk-pill--${meta.riskImpact}`}
          >
            {riskImpactLabel(meta.riskImpact)} risk
          </span>
        </BubbleTip>
      </div>
      <BubbleTip id={BUBBLE_TIP_IDS.gateIntentSlippage} group={tooltipGroup}>
        <p className="guardrail-intent-fill-impact">
          Est. +{meta.expectedFillImpactBps.toFixed(1)} bps slippage on{" "}
          {baseAssetLabel}
        </p>
      </BubbleTip>
      <BubbleTip id={BUBBLE_TIP_IDS.gateIntentSizeTweak} group={tooltipGroup}>
        <button
          type="button"
          className="guardrail-intent-tweak-toggle"
          aria-expanded={tweakOpen}
          onClick={() => setTweakOpen((v) => !v)}
        >
          {tweakOpen ? "Hide tweak" : "Approve with tweak"}
        </button>
      </BubbleTip>
      {tweakOpen ? (
        <div className="guardrail-intent-tweak-row">
          <label className="guardrail-intent-tweak-label" htmlFor={`tweak-${task.id}`}>
            Size {sizePct}%
          </label>
          <FilledRangeSlider
            id={`tweak-${task.id}`}
            variant="brand"
            size="sm"
            min={10}
            max={100}
            step={5}
            value={sizePct}
            onChange={handleSizePctChange}
          />
        </div>
      ) : null}
      {!hideGateActions ? (
        <div className="trade-agent-deck-card-actions">
          <BubbleTip id={BUBBLE_TIP_IDS.gateIntentApprove} group={tooltipGroup}>
            <button
              type="button"
              className="trade-agent-deck-btn trade-agent-deck-btn--primary"
              onClick={handleApprove}
            >
              {sizePct === 100 ? "Approve" : `Approve ${sizePct}%`}
            </button>
          </BubbleTip>
          <BubbleTip id={BUBBLE_TIP_IDS.gateIntentReject} group={tooltipGroup}>
            <button
              type="button"
              className="trade-agent-deck-btn trade-agent-deck-btn--danger"
              onClick={() => onReject(task.id)}
            >
              Reject
            </button>
          </BubbleTip>
        </div>
      ) : null}
    </div>
  );
}

export default React.memo(GuardrailIntentCardExtras);
