import React, { useState } from "react";

import type { AgentSettingsState, McpServer } from "./agentSettingsTypes";
import { AddMcpServerModal } from "./agentSettingsModals";

export interface AgentMcpServersTabProps {
  settings: AgentSettingsState;
  onAddMcpServer: (input: Omit<McpServer, "id" | "createdAt">) => boolean;
  onRemoveMcpServer: (serverId: string) => void;
}

function AgentMcpServersTab({
  settings,
  onAddMcpServer,
  onRemoveMcpServer,
}: AgentMcpServersTabProps): JSX.Element {
  const [addOpen, setAddOpen] = useState(false);

  return (
    <>
      <div className="agent-settings-section-header">
        <div>
          <h4 className="agent-settings-section-title">MCP Servers</h4>
          <p className="agent-settings-section-desc">
            Connect any MCP-compliant server. Tools become callable via the agent.
          </p>
        </div>
        <button
          type="button"
          className="agent-secondary-btn"
          onClick={() => setAddOpen(true)}
        >
          + Add
        </button>
      </div>

      {settings.mcpServers.length === 0 ? (
        <div className="agent-settings-empty">
          <p className="agent-settings-empty-title">No MCP servers yet</p>
          <p className="agent-settings-empty-desc">
            Add an MCP server to give your agent access to external tools.
          </p>
        </div>
      ) : (
        <div className="agent-settings-mcp-list">
          {settings.mcpServers.map((server) => (
            <div key={server.id} className="agent-settings-mcp-card">
              <div className="agent-settings-mcp-card-header">
                <p className="agent-settings-mcp-name">{server.name}</p>
                <button
                  type="button"
                  className="agent-secondary-btn"
                  onClick={() => onRemoveMcpServer(server.id)}
                >
                  Remove
                </button>
              </div>
              <p className="agent-settings-mcp-meta">{server.url}</p>
              <p className="agent-settings-mcp-meta">
                Transport:{" "}
                {server.transport === "streamableHttp" ? "Streamable HTTP" : "SSE (legacy)"}
                {server.headers.length > 0
                  ? ` · ${server.headers.length} header(s)`
                  : ""}
              </p>
            </div>
          ))}
        </div>
      )}

      <AddMcpServerModal
        open={addOpen}
        onClose={() => setAddOpen(false)}
        onAdd={(input) => {
          const ok = onAddMcpServer(input);
          if (ok) setAddOpen(false);
          return ok;
        }}
      />
    </>
  );
}

export default AgentMcpServersTab;
