/** 5m OHLC candle for agent token price history JSON files. */
export type AgentTokenPriceCandle = {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
};

/** Per-agent price history file served from packages/mock-system-data/agent-token-prices/. */
export type AgentTokenPriceHistoryFile = {
  catalogAgentId: string;
  ticker: string;
  tokenAddress: string;
  interval: "5m";
  startTime: string;
  endTime: string;
  candleCount: number;
  candles: AgentTokenPriceCandle[];
};

/** Manifest index for all issued agent token price history files. */
export type AgentTokenPriceHistoryManifestAgent = {
  catalogAgentId: string;
  name: string;
  ticker: string;
  tokenAddress: string;
  currentPrice: number;
  change24h: number;
  file: string;
};

export type AgentTokenPriceHistoryManifest = {
  version: 1;
  generatedAt: string;
  interval: "5m";
  intervalMs: number;
  historyDays: number;
  candleCount: number;
  basePath: string;
  agents: AgentTokenPriceHistoryManifestAgent[];
};

export const AGENT_TOKEN_PRICE_HISTORY_INTERVAL = "5m" as const;
export const AGENT_TOKEN_PRICE_HISTORY_INTERVAL_MS = 5 * 60 * 1000;
export const AGENT_TOKEN_PRICE_HISTORY_DAYS = 30;
export const AGENT_TOKEN_PRICE_HISTORY_CANDLE_COUNT =
  AGENT_TOKEN_PRICE_HISTORY_DAYS * 24 * 12;
export const AGENT_TOKEN_PRICE_HISTORY_BASE_PATH = "agent-token-prices";
