import { useMemo, type JSX } from "react";
import {
  CURRENCY_MIN_FRACTION_DIGITS,
  CURRENCY_MAX_FRACTION_DIGITS,
} from "../../constants";
import type { Bucket } from "../../sdk/types/data";
import { shortenId } from "../../sdk/utils/display";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

export interface TradeOperationInfoPanelProps {
  spotWalletBalance: number;
  collections: Bucket[];
  selectedBucketId?: string | null;
  selectedBucket: Bucket | null;
  onOpenBucketRules?: (bucketId: string) => void;
  onRequestFundAccount?: () => void;
  onRequestDepositTour?: () => void;
  availableTradeBalance?: number;
}

export function TradeOperationInfoPanel({
  spotWalletBalance,
  collections,
  selectedBucketId,
  selectedBucket,
  onOpenBucketRules,
  onRequestFundAccount,
  onRequestDepositTour,
  availableTradeBalance = 0,
}: TradeOperationInfoPanelProps): JSX.Element {
  const currencyFormatOptions = useMemo(
    () => ({
      minimumFractionDigits: CURRENCY_MIN_FRACTION_DIGITS,
      maximumFractionDigits: CURRENCY_MAX_FRACTION_DIGITS,
    }),
    [],
  );

  const accountEquity = useMemo(() => {
    const totalBucketsEquity = collections.reduce(
      (sum, collection) => sum + collection.totalEquity,
      0,
    );
    return spotWalletBalance + totalBucketsEquity;
  }, [collections, spotWalletBalance]);

  const accountEquityDisplay = useMemo(
    () => accountEquity.toLocaleString("en-US", currencyFormatOptions),
    [accountEquity, currencyFormatOptions],
  );

  const spotBalanceDisplay = useMemo(
    () => spotWalletBalance.toLocaleString("en-US", currencyFormatOptions),
    [spotWalletBalance, currencyFormatOptions],
  );

  const selectedBucketBalanceDisplay = useMemo(
    () =>
      selectedBucket
        ? selectedBucket.totalEquity.toLocaleString(
            "en-US",
            currencyFormatOptions,
          )
        : "--",
    [selectedBucket, currencyFormatOptions],
  );

  const bucketBalanceDisplay = useMemo(
    () =>
      selectedBucket
        ? selectedBucket.totalEquity.toLocaleString(
            "en-US",
            currencyFormatOptions,
          )
        : "--",
    [selectedBucket, currencyFormatOptions],
  );

  const unrealizedPnLDisplay = useMemo(
    () =>
      selectedBucket
        ? selectedBucket.unrealizedPnL.toLocaleString(
            "en-US",
            currencyFormatOptions,
          )
        : "--",
    [selectedBucket, currencyFormatOptions],
  );

  const crossMarginRatioDisplay = useMemo(
    () =>
      selectedBucket
        ? (selectedBucket.marginRatio * 100).toFixed(
            CURRENCY_MIN_FRACTION_DIGITS,
          ) + "%"
        : "--",
    [selectedBucket],
  );

  const maintenanceMarginDisplay = useMemo(
    () =>
      selectedBucket
        ? selectedBucket.usedMargin.toLocaleString(
            "en-US",
            currencyFormatOptions,
          )
        : "--",
    [selectedBucket, currencyFormatOptions],
  );

  const crossAccountLeverageDisplay = useMemo(
    () =>
      selectedBucket
        ? `${selectedBucket.leverage.toFixed(CURRENCY_MIN_FRACTION_DIGITS)}x`
        : "--",
    [selectedBucket],
  );

  const shortenedBucketId = useMemo(
    () => shortenId(selectedBucketId || null),
    [selectedBucketId],
  );

  return (
    <div className="trade-op-info-panel">
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.accountEquity}>
          <span className="trade-op-info-label">Account Equity:</span>
        </BubbleTip>
        <span className="trade-op-info-value">{accountEquityDisplay} USDC</span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.spot}>
          <span className="trade-op-info-label">Spot:</span>
        </BubbleTip>
        <span className="trade-op-info-value">{spotBalanceDisplay} USDC</span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.balance}>
          <span className="trade-op-info-label">
            {selectedBucketId || "Bucket"}:
          </span>
        </BubbleTip>
        <span className="trade-op-info-value">
          {selectedBucketBalanceDisplay} USDC
        </span>
      </div>
      <div className="trade-op-info-row trade-op-info-row--bucket-rules">
        <BubbleTip id={BUBBLE_TIP_IDS.bucketOverview}>
          <span className="trade-op-info-label">
            Bucket Overview: {shortenedBucketId}
          </span>
        </BubbleTip>
        {selectedBucketId &&
        selectedBucketId !== "--" &&
        onOpenBucketRules ? (
          <button
            type="button"
            className="trade-op-bucket-rules-link"
            onClick={() => onOpenBucketRules(selectedBucketId)}
          >
            Edit rules
          </button>
        ) : null}
      </div>

      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.balance}>
          <span className="trade-op-info-label">Balance:</span>
        </BubbleTip>
        <span className="trade-op-info-value">{bucketBalanceDisplay} USDC</span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.unrealizedPnl}>
          <span className="trade-op-info-label">Unrealized PNL:</span>
        </BubbleTip>
        <span className="trade-op-info-value">{unrealizedPnLDisplay} USDC</span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.crossMarginRatio}>
          <span className="trade-op-info-label">Cross Margin Ratio:</span>
        </BubbleTip>
        <span className="trade-op-info-value">{crossMarginRatioDisplay}</span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.maintenanceMargin}>
          <span className="trade-op-info-label">Maintenance Margin:</span>
        </BubbleTip>
        <span className="trade-op-info-value">
          {maintenanceMarginDisplay} USDC
        </span>
      </div>
      <div className="trade-op-info-row">
        <BubbleTip id={BUBBLE_TIP_IDS.crossAccountLeverage}>
          <span className="trade-op-info-label">Cross Account Leverage:</span>
        </BubbleTip>
        <span className="trade-op-info-value">
          {crossAccountLeverageDisplay}
        </span>
      </div>
      {onRequestFundAccount &&
      spotWalletBalance <= 0 &&
      availableTradeBalance <= 0 ? (
        <div
          className="trade-op-info-row"
          style={{ flexDirection: "column", alignItems: "stretch", gap: "0.5rem" }}
        >
          <span className="terminal-label" style={{ fontSize: "0.8rem" }}>
            Not enough balance to open this order.
          </span>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "0.5rem" }}>
            <button
              type="button"
              className="btn btn-primary btn-sm"
              onClick={onRequestFundAccount}
            >
              Fund account →
            </button>
            {onRequestDepositTour ? (
              <button
                type="button"
                className="btn btn-secondary btn-sm"
                onClick={onRequestDepositTour}
              >
                Guided deposit
              </button>
            ) : null}
          </div>
        </div>
      ) : null}
    </div>
  );
}
