interface AgentTasksProps {
  baseURL?: string;
  authToken?: string;
  height?: string;
  selectedBucketId?: string | null;
  hide_header?: boolean;
  isMobile?: boolean;
  layoutBreakpoint?: string;
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  onRequestViewOnChart?: (marketId: string) => void;
  onRequestEditAgentTask?: (taskId: string, description: string) => void;
  showAgentConsoleTrigger?: boolean;
  agentConsoleOpen?: boolean;
  onRequestExpandAgentConsole?: () => void;
  filterAgentIds?: string[];
  walletAddress?: string;
  tradingMode?: TradingMode;
}

type SortDirection = typeof SORT_DIRECTION_ASC | typeof SORT_DIRECTION_DESC;

const MOBILE_SORT_OPTIONS: { field: AgentTaskSortField; label: string }[] = [
  { field: AGENT_TASK_SORT_FIELD_UPDATED, label: "Updated" },
  { field: AGENT_TASK_SORT_FIELD_STATUS, label: "Status" },
  { field: AGENT_TASK_SORT_FIELD_TASK, label: "Intent" },
  { field: AGENT_TASK_SORT_FIELD_MARKET, label: "Market" },
];

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function getStatusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

function isTerminalTaskStatus(status: AgentTaskStatus): boolean {
  return status === "completed" || status === "rejected";
}

function canRejectTaskStatus(status: AgentTaskStatus): boolean {
  return status === "pending" || status === "watching";
}

function canForceExecuteTaskStatus(status: AgentTaskStatus): boolean {
  return !isTerminalTaskStatus(status) && status !== "executing";
}

function canPauseResumeTaskStatus(status: AgentTaskStatus): boolean {
  return !isTerminalTaskStatus(status);
}

function getTaskActionFlags(status: AgentTaskStatus) {
  return {
    isPaused: status === "paused",
    isTerminal: isTerminalTaskStatus(status),
    canPauseResume: canPauseResumeTaskStatus(status),
    canForceExecute: canForceExecuteTaskStatus(status),
    canReject: canRejectTaskStatus(status),
  };
}

function memoryPreviewForAgent(agent: TradingAgent | undefined): string {
  if (!agent || agent.memory.length === 0) return "";
  return agent.memory[agent.memory.length - 1]?.text ?? "";
}

function AgentTasks({
  baseURL = DEFAULT_BASE_URL,
  authToken,
  height = DEFAULT_HEIGHT_PENDING_ORDERS,
  selectedBucketId = null,
  hide_header = false,
  isMobile = false,
  layoutBreakpoint = "lg",
  onRequestHeaderActions,
  onRequestViewOnChart,
  onRequestEditAgentTask,
  showAgentConsoleTrigger = false,
  agentConsoleOpen = false,
  onRequestExpandAgentConsole,
  filterAgentIds = [],
  walletAddress = "",
  tradingMode = "proTerminal",
}: AgentTasksProps): JSX.Element {
  const {
    tasks,
    loading,
    pauseTask,
    resumeTask,
    forceExecute,
    rejectTask,
  } = useAgentTasks();
  const {
    agents,
    agentCount,
    supervisors,
    getAgentById,
    getAgentsBySupervisor,
    setSelectedAgentId,
  } = useTradingAgents();
  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });

  const relationalRootRef = useRef<HTMLDivElement>(null);
  const memorySectionRef = useRef<HTMLDivElement>(null);

  const settingsContext = useOptionalSettings();
  const showMarketBucket =
    settingsContext?.settings.agentTasks.showMarketBucket ??
    DEFAULT_AGENT_TASKS_PREFS.showMarketBucket;

  const setShowMarketBucket = useCallback(
    (next: boolean) => {
      settingsContext?.setSettings((prev) => ({
        ...prev,
        agentTasks: {
          ...prev.agentTasks,
          showMarketBucket: next,
        },
      }));
    },
    [settingsContext],
  );

  const agentConsoleShortcutLabel = useMemo(() => {
    const binding =
      settingsContext?.settings.keyboardShortcuts.toggleAgentConsole ??
      getDefaultBindingForAction("toggleAgentConsole");
    return `${formatKeyboardBindingLabel(binding)} toggle`;
  }, [settingsContext?.settings.keyboardShortcuts.toggleAgentConsole]);

  const [filterMode, setFilterMode] = useState<AgentTaskFilterMode>(
    AGENT_TASK_FILTER_ALL,
  );
  const [searchQuery, setSearchQuery] = useState("");
  const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);
  const [executionTraceTaskId, setExecutionTraceTaskId] = useState<
    string | null
  >(null);
  const [hoveredTaskId, setHoveredTaskId] = useState<string | null>(null);
  const [agentColumnFilterId, setAgentColumnFilterId] = useState<string | null>(
    null,
  );
  const [highlightedTaskId, setHighlightedTaskId] = useState<string | null>(
    null,
  );
  const [panelOpen, setPanelOpen] = useState(false);
  const [panelView, setPanelView] =
    useState<AgentMemoryPanelView>("supervisorList");
  const [panelSupervisorId, setPanelSupervisorId] = useState<string | null>(
    null,
  );
  const [panelFleetId, setPanelFleetId] = useState<string | null>(null);
  const [panelAgentId, setPanelAgentId] = useState<string | null>(null);
  const [filterObjectiveId, setFilterObjectiveId] = useState<string | null>(
    null,
  );
  const [expandedObjectiveId, setExpandedObjectiveId] = useState<string | null>(
    null,
  );
  const [panelEntrySource, setPanelEntrySource] =
    useState<AgentPanelEntrySource>("row");
  const [sortField, setSortField] = useState<AgentTaskSortField | null>(
    AGENT_TASK_SORT_FIELD_UPDATED,
  );
  const [sortDirection, setSortDirection] = useState<SortDirection>(
    SORT_DIRECTION_DESC,
  );

  const tableLayout = getAgentTasksTableLayout(
    isMobile ? "xs" : layoutBreakpoint,
  );
  const columns = useMemo(
    () =>
      applyAgentTasksColumnPrefs(tableLayout, {
        showMarketBucket,
      }),
    [tableLayout, showMarketBucket],
  );
  const isCardLayout = isAgentTasksCardLayout(tableLayout);
  const showMarketBucketToggle = supportsAgentTasksMarketBucketColumn(tableLayout);
  const gridColumns = columns.gridColumns;

  const bucketPolicies = useBucketPolicyStore((s) => s.policies);
  const resolvePolicyForTask = useMemo(
    () => createTaskPolicyResolver(tradingMode),
    [tradingMode, bucketPolicies],
  );

  const isHil = tradingMode === "humanInLoop";

  const highlightedAgentId = useMemo(() => {
    if (panelOpen && panelAgentId) return panelAgentId;
    if (hoveredTaskId) {
      return tasks.find((t) => t.id === hoveredTaskId)?.agentId ?? null;
    }
    return null;
  }, [panelOpen, panelAgentId, hoveredTaskId, tasks]);

  const openAgentDetail = useCallback(
    (
      agentId: string,
      taskId?: string,
      entrySource: AgentPanelEntrySource = "row",
      objectiveId?: string | null,
    ) => {
      setPanelEntrySource(entrySource);
      setPanelAgentId(agentId);
      setPanelView("detail");
      setPanelOpen(true);
      setSelectedAgentId(agentId);
      setFilterObjectiveId(objectiveId ?? null);
      if (taskId) {
        setHighlightedTaskId(taskId);
        setHoveredTaskId(taskId);
      }
    },
    [setSelectedAgentId],
  );

  const openObjectiveDetail = useCallback(
    (objectiveId: string, leadIntent: AgentTask) => {
      setExpandedObjectiveId(objectiveId);
      openAgentDetail(
        leadIntent.agentId,
        leadIntent.id,
        "row",
        objectiveId,
      );
    },
    [openAgentDetail],
  );

  const handleAgentNameClick = useCallback(
    (agentId: string, taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      setAgentColumnFilterId(agentId);
      setExpandedTaskId(taskId);
      setHoveredTaskId(taskId);
      if (task?.objectiveId) {
        setExpandedObjectiveId(task.objectiveId);
      }
      openAgentDetail(
        agentId,
        taskId,
        "row",
        task?.objectiveId ?? null,
      );
    },
    [openAgentDetail, tasks],
  );

  const handleMemoryLinkClick = useCallback(
    (agentId: string, taskId: string) => {
      setAgentColumnFilterId(agentId);
      setExpandedTaskId(taskId);
      setHoveredTaskId(taskId);
      openAgentDetail(agentId, taskId, "memoryLink");
    },
    [openAgentDetail],
  );

  const openAgentsList = useCallback(() => {
    setPanelEntrySource("agentList");
    setPanelView("supervisorList");
    setPanelSupervisorId(null);
    setPanelFleetId(null);
    setPanelAgentId(null);
    setFilterObjectiveId(null);
    setPanelOpen(true);
  }, []);

  const handleSelectSupervisor = useCallback((supervisorId: string) => {
    setPanelSupervisorId(supervisorId);
    const supervisorAgents = getAgentsBySupervisor(supervisorId);
    setPanelFleetId(supervisorAgents[0]?.fleetId ?? null);
    setPanelView("agentList");
    setPanelAgentId(null);
    setFilterObjectiveId(null);
    setHighlightedTaskId(null);
  }, [getAgentsBySupervisor]);

  const handleBackToSupervisorList = useCallback(() => {
    setPanelView("supervisorList");
    setPanelSupervisorId(null);
    setPanelFleetId(null);
    setPanelAgentId(null);
    setFilterObjectiveId(null);
    setHighlightedTaskId(null);
  }, []);

  const handleBackToAgentList = useCallback(() => {
    setPanelView("agentList");
    setPanelAgentId(null);
    setFilterObjectiveId(null);
    setHighlightedTaskId(null);
  }, []);

  const closePanel = useCallback(() => {
    setPanelOpen(false);
    setHighlightedTaskId(null);
    setFilterObjectiveId(null);
  }, []);

  const panelListAgents = useMemo(() => {
    if (panelSupervisorId) {
      return getAgentsBySupervisor(panelSupervisorId);
    }
    return agents;
  }, [panelSupervisorId, getAgentsBySupervisor, agents]);

  const clearAgentColumnFilter = useCallback(() => {
    setAgentColumnFilterId(null);
  }, []);

  const handleSelectAgentFromList = useCallback(
    (agentId: string) => {
      const entry = getAgentById(agentId);
      if (entry && !panelSupervisorId) {
        setPanelSupervisorId(entry.supervisorId);
        setPanelFleetId(entry.fleetId);
      }
      setAgentColumnFilterId(agentId);
      openAgentDetail(agentId, undefined, "agentList");
    },
    [openAgentDetail, getAgentById, panelSupervisorId],
  );

  const handleSelectTaskFromPanel = useCallback(
    (taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task) return;
      setAgentColumnFilterId(task.agentId);
      setHighlightedTaskId(taskId);
      setExpandedTaskId(taskId);
      setHoveredTaskId(taskId);
      const row = relationalRootRef.current?.querySelector(
        `[data-task-row-id="${taskId}"]`,
      );
      row?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    },
    [tasks],
  );

  const filteredTasks = useMemo(() => {
    let result = [...tasks];

    if (filterAgentIds.length > 0) {
      const fleet = new Set(filterAgentIds);
      result = result.filter((t) => fleet.has(t.agentId));
    }

    if (agentColumnFilterId) {
      result = result.filter((t) => t.agentId === agentColumnFilterId);
    }

    if (filterMode === AGENT_TASK_FILTER_PENDING) {
      result = result.filter((t) => t.status === "pending");
    } else if (filterMode === AGENT_TASK_FILTER_ACTIVE) {
      result = result.filter((t) =>
        ["watching", "executing"].includes(t.status),
      );
    } else if (
      filterMode === AGENT_TASK_FILTER_BY_BUCKET &&
      selectedBucketId
    ) {
      result = result.filter(
        (t) => t.bucketId?.toString() === selectedBucketId.toString(),
      );
    }

    const q = searchQuery.trim().toLowerCase();
    if (q) {
      result = result.filter((t) => {
        const agent = getAgentById(t.agentId);
        const memoryMatch = agent?.memory.some((m) =>
          m.text.toLowerCase().includes(q),
        );
        return (
          t.description.toLowerCase().includes(q) ||
          t.trigger.toLowerCase().includes(q) ||
          (agent?.displayName.toLowerCase().includes(q) ?? false) ||
          memoryMatch
        );
      });
    }

    return result;
  }, [
    tasks,
    filterAgentIds,
    agentColumnFilterId,
    filterMode,
    selectedBucketId,
    searchQuery,
    getAgentById,
  ]);

  const sortedTasks = useMemo(() => {
    if (!sortField) return filteredTasks;

    return [...filteredTasks].sort((a, b) => {
      let aValue: string | number = "";
      let bValue: string | number = "";

      switch (sortField) {
        case AGENT_TASK_SORT_FIELD_TASK:
          aValue = a.description;
          bValue = b.description;
          break;
        case AGENT_TASK_SORT_FIELD_TASK_ID:
          aValue = a.id;
          bValue = b.id;
          break;
        case AGENT_TASK_SORT_FIELD_STATUS:
          aValue = a.status;
          bValue = b.status;
          break;
        case AGENT_TASK_SORT_FIELD_MARKET:
          aValue =
            getSymbolByMarketId(a.marketId ?? "") || a.marketId || "";
          bValue =
            getSymbolByMarketId(b.marketId ?? "") || b.marketId || "";
          break;
        case AGENT_TASK_SORT_FIELD_AGENT:
          aValue = getAgentById(a.agentId)?.displayName ?? a.agentId;
          bValue = getAgentById(b.agentId)?.displayName ?? b.agentId;
          break;
        case AGENT_TASK_SORT_FIELD_UPDATED:
          aValue = new Date(a.updatedAt).getTime();
          bValue = new Date(b.updatedAt).getTime();
          break;
      }

      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === SORT_DIRECTION_ASC
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }
      return sortDirection === SORT_DIRECTION_ASC
        ? Number(aValue) - Number(bValue)
        : Number(bValue) - Number(aValue);
    });
  }, [filteredTasks, sortField, sortDirection, getSymbolByMarketId, getAgentById]);

  const sortedTableRows = useMemo(
    () => groupAgentTasksByObjective(sortedTasks),
    [sortedTasks],
  );

  const toggleObjectiveExpand = useCallback((objectiveId: string) => {
    setExpandedObjectiveId((prev) =>
      prev === objectiveId ? null : objectiveId,
    );
  }, []);

  const handleSort = (field: AgentTaskSortField) => {
    if (sortField === field) {
      setSortDirection(
        sortDirection === SORT_DIRECTION_ASC
          ? SORT_DIRECTION_DESC
          : SORT_DIRECTION_ASC,
      );
    } else {
      setSortField(field);
      setSortDirection(SORT_DIRECTION_DESC);
    }
  };

  const toggleExpand = useCallback(
    (taskId: string) => {
      if (expandedTaskId === taskId) {
        setExpandedTaskId(null);
        setHoveredTaskId(null);
        setAgentColumnFilterId(null);
        setHighlightedTaskId(null);
        setPanelOpen(false);
        setPanelAgentId(null);
        return;
      }
      setExpandedTaskId(taskId);
      setHoveredTaskId(taskId);
      if (panelOpen && panelAgentId) {
        setHighlightedTaskId(taskId);
      }
    },
    [expandedTaskId, panelOpen, panelAgentId],
  );

  const handleEdit = useCallback(
    (task: AgentTask) => {
      if (!onRequestEditAgentTask) {
        toast.error("Edit is unavailable in this view");
        return;
      }
      onRequestEditAgentTask(task.id, task.description);
    },
    [onRequestEditAgentTask],
  );

  const handlePauseResume = useCallback(
    (task: AgentTask) => {
      if (task.status === "paused") {
        resumeTask(task.id);
        toast.success("Task resumed");
      } else if (!isTerminalTaskStatus(task.status)) {
        pauseTask(task.id);
        toast.success("Task paused");
      }
    },
    [pauseTask, resumeTask],
  );

  const handleForceExecute = useCallback(
    (task: AgentTask) => {
      if (!canForceExecuteTaskStatus(task.status)) return;
      forceExecute(task.id);
      toast.success("Task executing", {
        description: "Agent is executing this task now.",
      });
    },
    [forceExecute],
  );

  const handlePauseForPanel = useCallback(
    (task: AgentTask) => {
      if (!canPauseResumeTaskStatus(task.status) || task.status === "paused") {
        return;
      }
      pauseTask(task.id);
      toast.success("Intent held");
    },
    [pauseTask],
  );

  const handleReject = useCallback(
    (task: AgentTask) => {
      if (!canRejectTaskStatus(task.status)) return;
      rejectTask(task.id);
      toast.success("Intent rejected");
    },
    [rejectTask],
  );

  const handleViewOnChart = useCallback(
    (task: AgentTask) => {
      if (!task.marketId) {
        toast.error("No market linked to this task");
        return;
      }
      if (!onRequestViewOnChart) {
        toast.error("Chart navigation is unavailable");
        return;
      }
      onRequestViewOnChart(task.marketId);
      toast.success("Chart updated", {
        description: `Switched to ${getSymbolByMarketId(task.marketId) || task.marketId}`,
      });
    },
    [onRequestViewOnChart, getSymbolByMarketId],
  );

  const handleRefresh = useCallback(() => {
    toast.message("Refresh queued", {
      description: "Agent tasks will sync when API is available.",
    });
  }, []);

  const headerActions = useMemo(
    () => (
      <>
        <button
          type="button"
          className="btn-tab agent-my-agents-btn"
          onClick={openAgentsList}
        >
          My Agents ({agentCount})
        </button>
        <div
          className={`btn-tab ${filterMode === AGENT_TASK_FILTER_ALL ? "active" : ""}`}
          onClick={() => setFilterMode(AGENT_TASK_FILTER_ALL)}
        >
          {AGENT_TASK_FILTER_LABEL_ALL}
        </div>
        <div
          className={`btn-tab ${filterMode === AGENT_TASK_FILTER_PENDING ? "active" : ""}`}
          onClick={() => setFilterMode(AGENT_TASK_FILTER_PENDING)}
        >
          {AGENT_TASK_FILTER_LABEL_PENDING}
        </div>
        <div
          className={`btn-tab ${filterMode === AGENT_TASK_FILTER_ACTIVE ? "active" : ""}`}
          onClick={() => setFilterMode(AGENT_TASK_FILTER_ACTIVE)}
        >
          {AGENT_TASK_FILTER_LABEL_ACTIVE}
        </div>
        {selectedBucketId ? (
          <div
            className={`btn-tab ${filterMode === AGENT_TASK_FILTER_BY_BUCKET ? "active" : ""}`}
            onClick={() => setFilterMode(AGENT_TASK_FILTER_BY_BUCKET)}
          >
            {AGENT_TASK_FILTER_LABEL_BY_BUCKET}
          </div>
        ) : null}
        <div className="agent-task-header-search">
          <input
            type="search"
            className="form-input agent-task-header-search-input"
            placeholder="Search..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="Search agent tasks"
          />
        </div>
        <div className="btn-tab" onClick={handleRefresh}>
          Refresh
        </div>
        {showMarketBucketToggle ? (
          <>
            <div className="agent-task-header-columns-label">Columns</div>
            <div
              className={`btn-tab${showMarketBucket ? " active" : ""}`}
              onClick={() => setShowMarketBucket(!showMarketBucket)}
              role="menuitemcheckbox"
              aria-checked={showMarketBucket}
            >
              Market + Bucket
            </div>
          </>
        ) : null}
        {isCardLayout ? (
          <>
            <div className="agent-task-header-sort-label">Sort by</div>
            {MOBILE_SORT_OPTIONS.map(({ field, label }) => {
              const isActive = sortField === field;
              const arrow =
                isActive && sortDirection === SORT_DIRECTION_ASC ? " ↑" : " ↓";
              return (
                <div
                  key={field}
                  className={`btn-tab${isActive ? " active" : ""}`}
                  onClick={() => handleSort(field)}
                >
                  {label}
                  {isActive ? arrow : ""}
                </div>
              );
            })}
          </>
        ) : null}
      </>
    ),
    [
      agentCount,
      filterMode,
      selectedBucketId,
      searchQuery,
      handleRefresh,
      openAgentsList,
      isCardLayout,
      showMarketBucketToggle,
      showMarketBucket,
      setShowMarketBucket,
      sortField,
      sortDirection,
    ],
  );

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, headerActions]);

  useEffect(() => {
    if (!panelOpen || !highlightedTaskId) return;
    const panelTask = relationalRootRef.current?.querySelector(
      `[data-task-id="${highlightedTaskId}"]`,
    );
    panelTask?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [panelOpen, highlightedTaskId]);

  const overlayAnchorTaskId = highlightedTaskId ?? hoveredTaskId;
  const overlayFromSelector =
    panelOpen && panelView === "detail" && overlayAnchorTaskId
      ? `[data-task-row-id="${overlayAnchorTaskId}"] [data-agent-pill-id]`
      : null;

  const overlayToSelector =
    panelOpen && panelView === "detail" && (overlayAnchorTaskId ?? panelAgentId)
      ? `[data-panel-relational-anchor="${overlayAnchorTaskId ?? panelAgentId}"]`
      : null;

  if (loading) {
    return <MorpheumInlineLoading message={AGENT_TASK_LOADING_MESSAGE} />;
  }

  const renderInlineActions = (
    task: AgentTask,
    actionFlags: ReturnType<typeof getTaskActionFlags>,
  ) => {
    const gatedHil =
      isHil && isNeedsYouTaskResolved(task, resolvePolicyForTask);

    return (
      <>
        <button
          type="button"
          className="btn"
          onClick={() => handleEdit(task)}
        >
          Edit
        </button>
        {actionFlags.canPauseResume ? (
          <button
            type="button"
            className="btn"
            onClick={() => handlePauseResume(task)}
          >
            {actionFlags.isPaused
              ? "Resume"
              : gatedHil
                ? "Hold"
                : "Pause"}
          </button>
        ) : null}
        {actionFlags.canForceExecute ? (
          <button
            type="button"
            className="btn btn-success"
            onClick={() => handleForceExecute(task)}
          >
            {gatedHil ? "Approve" : "Execute"}
          </button>
        ) : null}
        {actionFlags.canReject ? (
          <button
            type="button"
            className="btn btn-danger"
            onClick={() => handleReject(task)}
          >
            Reject
          </button>
        ) : null}
        {task.marketId ? (
          <button
            type="button"
            className="btn"
            onClick={() => handleViewOnChart(task)}
          >
            Chart
          </button>
        ) : null}
      </>
    );
  };

  const renderAgentName = (
    task: AgentTask,
    agent: TradingAgent | undefined,
  ) =>
    agent ? (
      <button
        type="button"
        className="agent-task-agent-name"
        data-agent-pill-id={agent.id}
        title={agent.displayName}
        onClick={(e) => {
          e.stopPropagation();
          handleAgentNameClick(agent.id, task.id);
        }}
      >
        {agent.displayName}
      </button>
    ) : (
      "—"
    );

  const renderTaskIdCell = (task: AgentTask) => (
    <div
      className="table-cell agent-task-id-cell"
      onClick={(e) => e.stopPropagation()}
    >
      <span title={task.id}>{shortHashId(task.id)}</span>
    </div>
  );

  const renderStatusCell = (task: AgentTask) => (
    <div className="table-cell agent-task-status-cell">
      <span>{getIntentGateDisplayLabel(task, resolvePolicyForTask)}</span>
    </div>
  );

  const renderMarketBucketCell = (task: AgentTask, symbol: string) => (
    <div className="table-cell">
      <div className="agent-task-market-bucket">
        <span>{symbol}</span>
        <span className="agent-task-bucket">
          {task.bucketId ? shortHashId(task.bucketId) : "—"}
        </span>
      </div>
    </div>
  );

  const renderIntentCell = (task: AgentTask) => (
    <div className="table-cell primary agent-task-intent-cell">
      {task.isNew ? <span className="agent-task-new-dot" aria-hidden /> : null}
      <span title={task.description}>{task.description}</span>
    </div>
  );

  const renderParentAgentCell = (
    task: AgentTask,
    agent: TradingAgent | undefined,
  ) => (
    <div
      className="table-cell agent-task-agent-cell"
      onClick={(e) => e.stopPropagation()}
    >
      {renderAgentName(task, agent)}
    </div>
  );

  const renderMemoryCell = (preview: string) => (
    <div className="table-cell">
      <div className="agent-memory-preview" title={preview}>
        <span className="agent-memory-preview-icon" aria-hidden>
          🧠
        </span>
        <span className="agent-memory-preview-text">{preview || "—"}</span>
      </div>
    </div>
  );

  const renderMergedMetaCell = (
    task: AgentTask,
    symbol: string,
    agent: TradingAgent | undefined,
  ) => (
    <div
      className="table-cell agent-task-meta-cell"
      onClick={(e) => e.stopPropagation()}
    >
      <div className="agent-task-market-bucket">
        <span>{symbol}</span>
        <span className="agent-task-bucket">
          {task.bucketId ? shortHashId(task.bucketId) : "—"}
        </span>
      </div>
      <div className="agent-task-meta-agent">{renderAgentName(task, agent)}</div>
    </div>
  );

  const renderActionsCell = (
    task: AgentTask,
    actionFlags: ReturnType<typeof getTaskActionFlags>,
  ) => (
    <div
      className={`table-row-actions agent-task-actions${columns.actionsMode === "menu" ? " agent-task-actions--compact" : ""}`}
      onClick={(e) => e.stopPropagation()}
    >
      {columns.actionsMode === "menu" ? (
        <AgentTaskRowActionsMenu
          task={task}
          actionFlags={actionFlags}
          isMobile={false}
          onEdit={handleEdit}
          onPauseResume={handlePauseResume}
          onForceExecute={handleForceExecute}
          onReject={handleReject}
          onViewOnChart={handleViewOnChart}
        />
      ) : (
        renderInlineActions(task, actionFlags)
      )}
    </div>
  );

  const renderTableRowCells = (
    task: AgentTask,
    statusCfg: ReturnType<typeof getStatusConfig>,
    symbol: string,
    agent: TradingAgent | undefined,
    preview: string,
    actionFlags: ReturnType<typeof getTaskActionFlags>,
  ) => {
    if (columns.mergeMarketAgent) {
      return (
        <>
          {renderStatusCell(task)}
          {renderIntentCell(task)}
          {renderMergedMetaCell(task, symbol, agent)}
          {renderActionsCell(task, actionFlags)}
        </>
      );
    }

    return (
      <>
        {columns.showTaskId ? renderTaskIdCell(task) : null}
        {renderStatusCell(task)}
        {columns.showMarketBucket
          ? renderMarketBucketCell(task, symbol)
          : null}
        {renderIntentCell(task)}
        {columns.showParentAgent
          ? renderParentAgentCell(task, agent)
          : null}
        {columns.showMemory ? renderMemoryCell(preview) : null}
        {renderActionsCell(task, actionFlags)}
      </>
    );
  };

  const renderTableHeader = () => {
    if (columns.mergeMarketAgent) {
      return (
        <>
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_STATUS}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Status / Gate
          </TableHeaderCell>
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_TASK}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.nlIntent} />
          </TableHeaderCell>
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_MARKET}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.marketAgent} />
          </TableHeaderCell>
          <TableHeaderCellStatic right>Actions</TableHeaderCellStatic>
        </>
      );
    }

    return (
      <>
        {columns.showTaskId ? (
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_TASK_ID}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.taskId} />
          </TableHeaderCell>
        ) : null}
        <TableHeaderCell
          field={AGENT_TASK_SORT_FIELD_STATUS}
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          left
        >
          Status / Gate
        </TableHeaderCell>
        {columns.showMarketBucket ? (
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_MARKET}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.marketBucket} />
          </TableHeaderCell>
        ) : null}
        <TableHeaderCell
          field={AGENT_TASK_SORT_FIELD_TASK}
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          left
        >
          <TableHeaderLabel {...TABLE_HEADER_LABELS.nlIntent} />
        </TableHeaderCell>
        {columns.showParentAgent ? (
          <TableHeaderCell
            field={AGENT_TASK_SORT_FIELD_AGENT}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.parentAgent} />
          </TableHeaderCell>
        ) : null}
        {columns.showMemory ? (
          <TableHeaderCellStatic left>Memory</TableHeaderCellStatic>
        ) : null}
        <TableHeaderCellStatic right>Actions</TableHeaderCellStatic>
      </>
    );
  };

  const renderTaskExpandedContent = (
    task: AgentTask,
    agent: TradingAgent | undefined,
    actionFlags: ReturnType<typeof getTaskActionFlags>,
    showActionsInExpand: boolean,
  ) => (
    <div className="agent-task-expanded-row">
      <div className="agent-task-expanded-section">
        <div className="agent-task-expanded-label">Intent ID</div>
        <span title={task.id}>{shortHashId(task.id)}</span>
      </div>
      <div className="agent-task-expanded-section">
        <div className="agent-task-expanded-label">Objective</div>
        <div>{task.description}</div>
        <div className="terminal-text-muted" style={{ marginTop: "0.25rem" }}>
          Status / Gate: {getIntentGateDisplayLabel(task, resolvePolicyForTask)}
        </div>
      </div>
      <div className="agent-task-expanded-section">
        <div className="agent-task-expanded-label">Agent memory</div>
        {agent && agent.memory.length > 0 ? (
          <ul className="agent-memory-side-panel-memory-list">
            {agent.memory.slice(-3).map((item) => (
              <li key={item.id} className="agent-memory-side-panel-memory-item">
                {item.text}
              </li>
            ))}
          </ul>
        ) : (
          <div>No memory recorded yet.</div>
        )}
        {agent ? (
          <button
            type="button"
            className="agent-expanded-memory-link"
            onClick={() => handleMemoryLinkClick(agent.id, task.id)}
          >
            View full agent memory
          </button>
        ) : null}
        <button
          type="button"
          className="agent-expanded-memory-link"
          onClick={(e) => {
            e.stopPropagation();
            setExecutionTraceTaskId(task.id);
          }}
        >
          View Execution Trace
        </button>
      </div>
      <div className="agent-task-expanded-section">
        <div className="agent-task-expanded-label">Timestamps</div>
        <div>
          Created {formatDateTime(task.createdAt)} · Updated{" "}
          {formatDateTime(task.updatedAt)}
        </div>
      </div>
      {showActionsInExpand ? (
        <div className="agent-task-expanded-section">
          <div className="agent-task-expanded-label">Actions</div>
          <div
            className="agent-task-actions agent-task-expanded-actions"
            onClick={(e) => e.stopPropagation()}
          >
            {renderInlineActions(task, actionFlags)}
          </div>
        </div>
      ) : null}
    </div>
  );

  const renderTaskCard = (task: AgentTask, index: number) => {
    const statusCfg = getStatusConfig(task.status);
    const symbol = task.marketId
      ? getSymbolByMarketId(task.marketId) || `m-${task.marketId}`
      : "—";
    const agent = getAgentById(task.agentId);
    const isExpanded = expandedTaskId === task.id;
    const actionFlags = getTaskActionFlags(task.status);
    const isLinked =
      hoveredTaskId === task.id ||
      highlightedTaskId === task.id ||
      (agentColumnFilterId == null &&
        highlightedAgentId === task.agentId);
    const bucketLabel = task.bucketId ? shortHashId(task.bucketId) : "—";

    return (
      <div
        key={task.id}
        className={`agent-task-table-group agent-task-card-group${tableLayout === "cardsTight" ? " agent-task-card-group--tight" : ""}${isExpanded ? " is-expanded" : ""}`}
        data-task-row-id={task.id}
      >
        <div
          className={`agent-task-card${index % 2 === 0 ? " even" : ""}${isLinked ? " agent-task-row--linked" : ""}${isExpanded ? " is-expanded" : ""}`}
          onClick={() => toggleExpand(task.id)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggleExpand(task.id);
            }
          }}
        >
          <div className="agent-task-card-header">
            <span>{getIntentGateDisplayLabel(task, resolvePolicyForTask)}</span>
            <div onClick={(e) => e.stopPropagation()}>
              <AgentTaskRowActionsMenu
              task={task}
              actionFlags={actionFlags}
              isMobile={isCardLayout}
              onEdit={handleEdit}
              onPauseResume={handlePauseResume}
              onForceExecute={handleForceExecute}
              onReject={handleReject}
              onViewOnChart={handleViewOnChart}
              />
            </div>
          </div>
          <div className="agent-task-card-intent">
            {task.isNew ? <span className="agent-task-new-dot" aria-hidden /> : null}
            <span title={task.description}>{task.description}</span>
          </div>
          <div
            className="agent-task-card-meta"
            onClick={(e) => e.stopPropagation()}
          >
            <span className="agent-task-card-meta-symbol">{symbol}</span>
            <span className="agent-task-card-meta-sep" aria-hidden>
              ·
            </span>
            <span className="agent-task-card-meta-bucket">{bucketLabel}</span>
            <span className="agent-task-card-meta-sep" aria-hidden>
              ·
            </span>
            {agent ? (
              <button
                type="button"
                className="agent-task-agent-name"
                data-agent-pill-id={agent.id}
                onClick={(e) => {
                  e.stopPropagation();
                  handleAgentNameClick(agent.id, task.id);
                }}
              >
                {agent.displayName}
              </button>
            ) : (
              <span>—</span>
            )}
          </div>
          <div className="agent-task-card-footer">
            Updated {formatDateTime(task.updatedAt)}
          </div>
        </div>
        {isExpanded
          ? renderTaskExpandedContent(
              task,
              agent,
              actionFlags,
              true,
            )
          : null}
      </div>
    );
  };

  const renderObjectiveRow = (
    row: Extract<AgentTaskTableRow, { kind: "objective" }>,
    index: number,
  ) => {
    const { objectiveId, objectiveSummary, intents, leadIntent } = row;
    const isExpanded = expandedObjectiveId === objectiveId;
    const agent = getAgentById(leadIntent.agentId);
    const preview = memoryPreviewForAgent(agent);
    const actionFlags = getTaskActionFlags(leadIntent.status);
    const symbol = leadIntent.marketId
      ? getSymbolByMarketId(leadIntent.marketId) ||
        `m-${leadIntent.marketId}`
      : "—";
    const gateLabel = rollUpObjectiveGateLabel(intents, resolvePolicyForTask);
    const isLinked =
      filterObjectiveId === objectiveId ||
      intents.some(
        (intent) =>
          hoveredTaskId === intent.id ||
          highlightedTaskId === intent.id ||
          (agentColumnFilterId == null &&
            highlightedAgentId === intent.agentId),
      );

    const handleIntentsChipClick = (e: React.MouseEvent) => {
      e.stopPropagation();
      openObjectiveDetail(objectiveId, leadIntent);
    };

    return (
      <div
        key={objectiveId}
        className={`agent-task-table-group agent-task-objective-group${isExpanded ? " is-expanded" : ""}`}
        data-objective-id={objectiveId}
        data-task-row-id={leadIntent.id}
      >
        <div
          className={`table-row agent-task-row-toggle agent-task-objective-row ${index % 2 === 0 ? "even" : ""}${isLinked ? " agent-task-row--linked" : ""}`}
          style={{ gridTemplateColumns: gridColumns }}
          onClick={() => toggleObjectiveExpand(objectiveId)}
          onMouseEnter={() => setHoveredTaskId(leadIntent.id)}
          onMouseLeave={() => {
            if (panelOpen && agentColumnFilterId) return;
            setHoveredTaskId((prev) =>
              prev === leadIntent.id ? null : prev,
            );
          }}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggleObjectiveExpand(objectiveId);
            }
          }}
        >
          {columns.mergeMarketAgent ? (
            <>
              <div className="table-cell agent-task-status-cell">
                <span>{gateLabel}</span>
              </div>
              <div className="table-cell primary agent-task-intent-cell">
                <span title={objectiveSummary}>{objectiveSummary}</span>
                <button
                  type="button"
                  className="agent-task-intents-chip"
                  data-intents-chip={objectiveId}
                  onClick={handleIntentsChipClick}
                >
                  Intents ({intents.length})
                </button>
              </div>
              <div
                className="table-cell agent-task-meta-cell"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="agent-task-market-bucket">
                  <span>{symbol}</span>
                  <span className="agent-task-bucket">
                    {leadIntent.bucketId
                      ? shortHashId(leadIntent.bucketId)
                      : "—"}
                  </span>
                </div>
                <div className="agent-task-meta-agent">
                  {renderAgentName(leadIntent, agent)}
                </div>
              </div>
              {renderActionsCell(leadIntent, actionFlags)}
            </>
          ) : (
            <>
              {columns.showTaskId ? (
                <div className="table-cell agent-task-id-cell">
                  <span title={objectiveId}>{shortHashId(objectiveId)}</span>
                </div>
              ) : null}
              <div className="table-cell agent-task-status-cell">
                <span>{gateLabel}</span>
              </div>
              <div className="table-cell primary agent-task-intent-cell">
                <span title={objectiveSummary}>{objectiveSummary}</span>
                <button
                  type="button"
                  className="agent-task-intents-chip"
                  data-intents-chip={objectiveId}
                  onClick={handleIntentsChipClick}
                >
                  Intents ({intents.length})
                </button>
              </div>
              {columns.showMarketBucket
                ? renderMarketBucketCell(leadIntent, symbol)
                : null}
              {renderParentAgentCell(leadIntent, agent)}
              {renderMemoryCell(preview)}
              {renderActionsCell(leadIntent, actionFlags)}
            </>
          )}
        </div>
        {isExpanded
          ? intents.map((task, childIndex) =>
              renderTaskRow(task, childIndex, { isObjectiveChild: true }),
            )
          : null}
      </div>
    );
  };

  const renderTableRow = (row: AgentTaskTableRow, index: number) => {
    if (row.kind === "objective") {
      return renderObjectiveRow(row, index);
    }
    return renderTaskRow(row.intent, index);
  };

  const renderTaskRow = (
    task: AgentTask,
    index: number,
    options?: { isObjectiveChild?: boolean },
  ) => {
    const statusCfg = getStatusConfig(task.status);
    const symbol = task.marketId
      ? getSymbolByMarketId(task.marketId) || `m-${task.marketId}`
      : "—";
    const agent = getAgentById(task.agentId);
    const preview = memoryPreviewForAgent(agent);
    const isExpanded = expandedTaskId === task.id;
    const actionFlags = getTaskActionFlags(task.status);
    const isLinked =
      hoveredTaskId === task.id ||
      highlightedTaskId === task.id ||
      (agentColumnFilterId == null &&
        highlightedAgentId === task.agentId);

    return (
      <div
        key={task.id}
        className={`agent-task-table-group${isExpanded ? " is-expanded" : ""}${options?.isObjectiveChild ? " agent-task-objective-child-group" : ""}`}
        data-task-row-id={task.id}
        {...(options?.isObjectiveChild
          ? { "data-objective-intent-id": task.id }
          : {})}
      >
        <div
          className={`table-row agent-task-row-toggle ${index % 2 === 0 ? "even" : ""}${isLinked ? " agent-task-row--linked" : ""}${options?.isObjectiveChild ? " agent-task-objective-child" : ""}`}
          style={{ gridTemplateColumns: gridColumns }}
          onClick={() => toggleExpand(task.id)}
          onMouseEnter={() => setHoveredTaskId(task.id)}
          onMouseLeave={() => {
            if (panelOpen && agentColumnFilterId) return;
            setHoveredTaskId((prev) => (prev === task.id ? null : prev));
          }}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggleExpand(task.id);
            }
          }}
        >
          {renderTableRowCells(
            task,
            statusCfg,
            symbol,
            agent,
            preview,
            actionFlags,
          )}
        </div>
        {isExpanded
          ? renderTaskExpandedContent(
              task,
              agent,
              actionFlags,
              columns.actionsMode === "menu",
            )
          : null}
      </div>
    );
  };

  const filteredAgentLabel = agentColumnFilterId
    ? getAgentById(agentColumnFilterId)?.displayName ??
      shortHashId(agentColumnFilterId)
    : null;

  return (
    <div
      className="layout-container"
      style={{
        height,
        display: "flex",
        flexDirection: "column",
        minHeight: 0,
        ...(hide_header ? { borderRadius: 0, background: "transparent" } : {}),
      }}
    >
      {!hide_header && (
        <LayoutHeader title="AGENT TASKS">{headerActions}</LayoutHeader>
      )}
      <div
        ref={relationalRootRef}
        className={`agent-task-relational-root${panelOpen ? " is-panel-open" : ""}${isMobile ? " agent-task-relational-root--mobile" : ""}`}
      >
        <div className="agent-task-relational-main">
          <div
            className={`table-container shrinkable agent-task-table agent-task-table--layout-${tableLayout}${panelOpen && tableLayout === "sm" ? " agent-task-table--panel-open" : ""}`}
          >
            {!panelOpen && agentColumnFilterId && filteredAgentLabel ? (
              <div className="agent-agent-filter-chip-row">
                <span className="agent-agent-filter-chip">
                  Showing: {filteredAgentLabel}
                  <button
                    type="button"
                    className="agent-agent-filter-chip-dismiss"
                    onClick={clearAgentColumnFilter}
                    aria-label={`Clear filter for ${filteredAgentLabel}`}
                  >
                    ×
                  </button>
                </span>
              </div>
            ) : null}

            {!isCardLayout ? (
            <div
              className="table-header"
              style={{ gridTemplateColumns: gridColumns }}
            >
              {renderTableHeader()}
            </div>
            ) : null}

            {sortedTableRows.length === 0 ? (
              <EmptyMessage message={AGENT_TASK_EMPTY_MESSAGE} />
            ) : isCardLayout ? (
              sortedTasks.map((task, index) => renderTaskCard(task, index))
            ) : (
              sortedTableRows.map((row, index) => renderTableRow(row, index))
            )}

            {sortedTableRows.length > 0 ? (
              <div className="agent-tasks-end-marker" aria-hidden>
                <span className="agent-tasks-end-marker-line" />
                <span className="agent-tasks-end-marker-text">
                  End of agent tasks
                </span>
              </div>
            ) : null}

            {showAgentConsoleTrigger && onRequestExpandAgentConsole ? (
              <div className="agent-tasks-expand-console">
                <button
                  type="button"
                  className="agent-tasks-expand-console-btn"
                  onClick={onRequestExpandAgentConsole}
                  aria-expanded={agentConsoleOpen}
                >
                  <ExpandCollapseIcon
                    expanded={false}
                    direction="up"
                    className="agent-tasks-expand-console-chevron"
                    size={14}
                  />
                  Expand Agent Console
                  <span className="agent-tasks-expand-console-keys">
                    {agentConsoleShortcutLabel}
                  </span>
                </button>
              </div>
            ) : null}
          </div>
        </div>

        <AgentRelationalOverlay
          key={`${panelAgentId ?? "none"}-${overlayAnchorTaskId ?? "none"}-${filterObjectiveId ?? "none"}`}
          active={
            !isCardLayout &&
            panelView === "detail" &&
            Boolean(overlayFromSelector && overlayToSelector)
          }
          containerRef={relationalRootRef}
          fromSelector={overlayFromSelector}
          toSelector={overlayToSelector}
        />

        <AgentMemorySidePanel
          isOpen={panelOpen}
          isMobile={isMobile}
          view={panelView}
          supervisorId={panelSupervisorId}
          agentId={panelAgentId}
          supervisors={supervisors}
          agents={agents}
          listAgents={panelListAgents}
          tasks={tasks}
          highlightedTaskId={highlightedTaskId}
          filterObjectiveId={filterObjectiveId}
          memorySectionRef={memorySectionRef}
          tradingMode={tradingMode}
          panelEntrySource={panelEntrySource}
          resolvePolicyForTask={resolvePolicyForTask}
          onClose={closePanel}
          onBackToSupervisorList={handleBackToSupervisorList}
          onBackToAgentList={handleBackToAgentList}
          onSelectSupervisor={handleSelectSupervisor}
          onSelectAgent={handleSelectAgentFromList}
          onSelectTask={handleSelectTaskFromPanel}
          onForceExecute={handleForceExecute}
          onReject={handleReject}
          onPause={handlePauseForPanel}
        />
        <ExplainActionModal
          isOpen={executionTraceTaskId != null}
          agentTaskId={executionTraceTaskId}
          baseURL={baseURL}
          walletAddress={walletAddress}
          onClose={() => setExecutionTraceTaskId(null)}
        />
      </div>
    </div>
  );
}

export default React.memo(AgentTasks);
