import React from "react";
import type { CrossChainTransferRecord } from "../../../types/crossChainFlow";
import { formatCurrency } from "../../../sdk/utils/display";
import "./cross-chain.css";

export interface CrossChainHistoryPillProps {
  record: CrossChainTransferRecord;
  validatorCount?: number;
  onClick: () => void;
}

export function CrossChainHistoryPill({
  record,
  validatorCount = 0,
  onClick,
}: CrossChainHistoryPillProps): JSX.Element {
  const modeLabel = record.mode === "deposit" ? "Deposit" : "Withdraw";
  let status = "In progress";
  if (record.completedAt) status = "Complete";
  else if (record.failedStage) status = "Needs attention";
  else if (record.currentStage === "attested") {
    status = `Attesting ${validatorCount || record.validatorCount || 0}/9`;
  } else if (record.currentStage) {
    status = record.currentStage.charAt(0).toUpperCase() + record.currentStage.slice(1);
  }

  return (
    <div className="cross-chain-history-pill-host">
      <button
        type="button"
        className="cross-chain-history-pill"
        onClick={onClick}
        aria-label={`${modeLabel} ${record.assetId} transfer — ${status}`}
      >
        <span>🌉</span>
        <span>
          {modeLabel} {formatCurrency(record.amount)} {record.assetId} · {status}
        </span>
      </button>
    </div>
  );
}
