import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";

import { mockAgentProfiles } from "../../../offline/mock_data";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import { APP_ROUTES } from "../../routes";
import { runAfterPreNavigateCleanup } from "../../utils/preNavigateCleanup";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import {
  buildComparePath,
  MAX_AGENT_COMPARE,
  toggleCompareId,
} from "../../utils/agentCompareIds";
import "./agent.css";

const OVERFLOW_THRESHOLD_PX = 4;
const MARQUEE_SPEED_PX_PER_SEC = 45;

type AgentDiscoveryRailBaseProps = {
  height?: string;
};

type AgentDiscoveryRailDiscoverProps = AgentDiscoveryRailBaseProps & {
  variant?: "discover";
  activeAgentId: string;
  compareIds?: never;
  onCompareIdsChange?: never;
};

type AgentDiscoveryRailCompareProps = AgentDiscoveryRailBaseProps & {
  variant: "compare";
  compareIds: string[];
  onCompareIdsChange: (ids: string[]) => void;
  activeAgentId?: never;
};

export type AgentDiscoveryRailProps =
  | AgentDiscoveryRailDiscoverProps
  | AgentDiscoveryRailCompareProps;

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function AgentDiscoveryCard({
  entry,
  isActive,
  isSelected,
  onSelect,
}: {
  entry: PropertyProfile;
  isActive: boolean;
  isSelected: boolean;
  onSelect: (id: string) => void;
}): JSX.Element {
  const changeTone = entry.change24h >= 0 ? "positive" : "negative";
  const changeLabel = `${entry.change24h >= 0 ? "+" : ""}${entry.change24h.toFixed(1)}%`;
  const avatarSrc = resolveAgentAvatarSvgUrl(entry.id);
  const className = [
    "agent-discovery-card",
    isActive ? "agent-discovery-card--active" : "",
    isSelected ? "agent-discovery-card--selected" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <button
      type="button"
      role="listitem"
      className={className}
      aria-current={isActive ? "true" : undefined}
      aria-pressed={isSelected ? "true" : undefined}
      onClick={() => onSelect(entry.id)}
    >
      <span className="agent-discovery-card-avatar" aria-hidden>
        <span
          className="agent-discovery-card-avatar-image"
          style={{
            maskImage: `url(${avatarSrc})`,
            WebkitMaskImage: `url(${avatarSrc})`,
          }}
        />
      </span>
      <span className="agent-discovery-card-body">
        <strong className="agent-discovery-card-name">{entry.name}</strong>
        <span className="agent-discovery-card-meta">
          <span className="agent-discovery-card-ticker">{entry.ticker}</span>
          <span className={`agent-discovery-card-change ${changeTone}`}>
            {changeLabel}
          </span>
        </span>
      </span>
    </button>
  );
}

function AgentDiscoveryRail(props: AgentDiscoveryRailProps): JSX.Element {
  const {
    height = "100%",
    variant = "discover",
  } = props;

  const navigate = useNavigate();
  const viewportRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const [shouldAnimate, setShouldAnimate] = useState(false);

  const isCompare = variant === "compare";
  const activeAgentId = !isCompare ? props.activeAgentId : "";
  const compareIds = isCompare ? props.compareIds : [];
  const marqueeKey = isCompare ? compareIds.join(",") : activeAgentId;

  useEffect(() => {
    const container = viewportRef.current;
    const track = trackRef.current;
    if (!container || !track) {
      setShouldAnimate(false);
      return;
    }

    const updateMarquee = () => {
      const containerWidth = container.clientWidth;
      const trackWidth = track.scrollWidth;

      if (!shouldAnimate) {
        if (
          !prefersReducedMotion() &&
          trackWidth > containerWidth + OVERFLOW_THRESHOLD_PX
        ) {
          setShouldAnimate(true);
        }
        return;
      }

      const halfWidth = trackWidth / 2;
      if (halfWidth <= containerWidth + OVERFLOW_THRESHOLD_PX) {
        setShouldAnimate(false);
        return;
      }

      track.style.setProperty(
        "--agent-discovery-scroll-duration",
        `${halfWidth / MARQUEE_SPEED_PX_PER_SEC}s`,
      );
    };

    updateMarquee();

    const observer = new ResizeObserver(updateMarquee);
    observer.observe(container);
    observer.observe(track);

    return () => observer.disconnect();
  }, [shouldAnimate, marqueeKey]);

  const handleSelect = (id: string) => {
    if (isCompare) {
      props.onCompareIdsChange(toggleCompareId(compareIds, id));
      return;
    }
    if (id === activeAgentId) return;
    runAfterPreNavigateCleanup(() => navigate(`/agents/${id}`));
  };

  const handleCompareNavigate = () => {
    if (isCompare || !activeAgentId) return;
    runAfterPreNavigateCleanup(() => navigate(buildComparePath([activeAgentId])));
  };

  return (
    <div
      className="agent-slot agent-discovery-rail"
      style={{ height }}
      aria-label={isCompare ? "Agent compare picker" : "Agent discovery"}
    >
      <div className="agent-discovery-rail-inner">
        <div className="agent-discovery-actions">
          <button
            type="button"
            className="agent-secondary-btn"
            onClick={() =>
              runAfterPreNavigateCleanup(() => navigate(APP_ROUTES.markets))
            }
          >
            Back to Markets
          </button>
          {!isCompare ? (
            <button
              type="button"
              className="agent-secondary-btn"
              onClick={handleCompareNavigate}
            >
              Compare
            </button>
          ) : (
            <span className="agent-discovery-compare-count" aria-live="polite">
              {compareIds.length}/{MAX_AGENT_COMPARE} selected
            </span>
          )}
        </div>
        <div
          ref={viewportRef}
          className={`agent-discovery-carousel-viewport${shouldAnimate ? " agent-discovery-carousel-viewport--animated" : ""}`}
          aria-label="Demo agents"
        >
          <div
            ref={trackRef}
            className="agent-discovery-carousel-track"
            role="list"
          >
            {mockAgentProfiles.map((entry) => (
              <AgentDiscoveryCard
                key={`a-${entry.id}`}
                entry={entry}
                isActive={!isCompare && entry.id === activeAgentId}
                isSelected={isCompare && compareIds.includes(entry.id)}
                onSelect={handleSelect}
              />
            ))}
            {shouldAnimate
              ? mockAgentProfiles.map((entry) => (
                  <AgentDiscoveryCard
                    key={`b-${entry.id}`}
                    entry={entry}
                    isActive={!isCompare && entry.id === activeAgentId}
                    isSelected={isCompare && compareIds.includes(entry.id)}
                    onSelect={handleSelect}
                  />
                ))
              : null}
          </div>
          {shouldAnimate ? (
            <>
              <div
                className="agent-discovery-carousel-fade agent-discovery-carousel-fade--left is-visible"
                aria-hidden
              />
              <div
                className="agent-discovery-carousel-fade agent-discovery-carousel-fade--right is-visible"
                aria-hidden
              />
            </>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default AgentDiscoveryRail;
