import React from "react";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { formatPortfolioFeeRate } from "./portfolioFormat";
import "./portfolio.css";

export interface PortfolioFeesPanelProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  refreshInterval?: number;
}

function PortfolioFeesPanel({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  refreshInterval,
}: PortfolioFeesPanelProps): JSX.Element {
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    refreshInterval,
  });

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section className="portfolio-fees-panel" aria-label="Perps fee tier rates">
        <span className="portfolio-volume-fees-label">Fees (Taker / Maker)</span>
        <div className="portfolio-volume-fees-row">
          <span>{formatPortfolioFeeRate(analytics.feeTier.takerRatePct)}</span>
          <span>/</span>
          <span>{formatPortfolioFeeRate(analytics.feeTier.makerRatePct)}</span>
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioFeesPanel);
