import { useCallback, useEffect, useState } from "react";
import {
  OVERLAY_TIMING,
  useOverlayScrollLock,
  useStaggeredOverlay,
  type UseStaggeredOverlayResult,
} from "../ui/overlay";

const MOBILE_BREAKPOINT_PX = 768;
export const BUCKET_SHEET_MS = OVERLAY_TIMING.tradeSheetMs;

export function useIsMobileViewport(
  breakpointPx = MOBILE_BREAKPOINT_PX,
): boolean {
  const [isMobile, setIsMobile] = useState(
    () =>
      typeof window !== "undefined" &&
      window.matchMedia(`(max-width: ${breakpointPx}px)`).matches,
  );

  useEffect(() => {
    const mediaQuery = window.matchMedia(`(max-width: ${breakpointPx}px)`);
    const syncMobile = () => setIsMobile(mediaQuery.matches);
    syncMobile();
    mediaQuery.addEventListener("change", syncMobile);
    return () => mediaQuery.removeEventListener("change", syncMobile);
  }, [breakpointPx]);

  return isMobile;
}

export type UseBucketModalOverlayResult = UseStaggeredOverlayResult & {
  isMobile: boolean;
  isClosing: boolean;
};

export function useBucketModalOverlay(
  isOpen: boolean,
  options?: { onAfterUnmount?: () => void },
): UseBucketModalOverlayResult {
  return useResponsiveModalOverlay(isOpen, {
    ...options,
    unmountOnCloseImmediately: true,
  });
}

/** Copy-agent modals: full staggered dismiss (passThrough on shell prevents nav traps). */
export function useCopyAgentModalOverlay(
  isOpen: boolean,
  options?: { onAfterUnmount?: () => void },
): UseBucketModalOverlayResult {
  return useResponsiveModalOverlay(isOpen, {
    ...options,
    unmountOnCloseImmediately: false,
  });
}

function useResponsiveModalOverlay(
  isOpen: boolean,
  options: {
    onAfterUnmount?: () => void;
    unmountOnCloseImmediately: boolean;
  },
): UseBucketModalOverlayResult {
  const isMobile = useIsMobileViewport();

  const overlay = useStaggeredOverlay({
    isOpen,
    panelDurationMs: isMobile
      ? BUCKET_SHEET_MS
      : OVERLAY_TIMING.desktopScaleMs,
    backdropFadeMs: isMobile ? BUCKET_SHEET_MS : OVERLAY_TIMING.backdropFadeMs,
    staggerBackdrop: !isMobile,
    unmountOnCloseImmediately: options.unmountOnCloseImmediately,
    onAfterUnmount: options.onAfterUnmount,
  });

  useOverlayScrollLock(isOpen && overlay.mounted && isMobile);

  return {
    ...overlay,
    isMobile,
    isClosing: !isOpen,
  };
}

/** Keeps overlay content visible through the close animation. */
export function useOverlayContentLatch<T>(
  isOpen: boolean,
  value: T | null,
): { latched: T | null; clearLatch: () => void } {
  const [latched, setLatched] = useState<T | null>(null);

  useEffect(() => {
    if (isOpen && value != null) {
      setLatched(value);
    }
  }, [isOpen, value]);

  const clearLatch = useCallback(() => setLatched(null), []);

  return { latched, clearLatch };
}
