import type { JSX } from "react";
import type { IntentBreakdown } from "../intentBreakdown";

export interface IntentRelationalBodyProps {
  breakdown: IntentBreakdown;
}

export function IntentRelationalBody({
  breakdown,
}: IntentRelationalBodyProps): JSX.Element {
  const legs = breakdown.execution.legs ?? [];
  const legA = legs[0];
  const legB = legs[1];

  return (
    <div className="intent-relational-body">
      <div className="intent-relational-legs">
        <div className="intent-relational-leg">
          <span className="terminal-label">LEG A</span>
          <span className="intent-leg-value">
            {legA ? `${legA.direction} $${legA.baseAsset}` : "—"}
          </span>
        </div>
        <span className="intent-linked-badge" aria-label="Linked legs">
          🔗 linked
        </span>
        <div className="intent-relational-leg">
          <span className="terminal-label">LEG B</span>
          <span className="intent-leg-value">
            {legB ? `${legB.direction} $${legB.baseAsset}` : "—"}
          </span>
        </div>
      </div>
      <div className="intent-relational-meta">
        <span>Notional 1,000 USDC</span>
        <span>Ratio 1 : 1</span>
        <span>Neutrality β-weighted</span>
      </div>
    </div>
  );
}
