import type { DeepPartial, ChartOptions } from "lightweight-charts";
import { CrosshairMode, LineType } from "lightweight-charts";
import { TERMINAL_COLORS } from "../../constants/terminalColors";

const sharedChartLayout = {
  autoSize: true,
  layout: {
    background: { color: TERMINAL_COLORS.panel },
    textColor: TERMINAL_COLORS.textSecondary,
    fontFamily:
      'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  grid: {
    vertLines: { visible: false },
    horzLines: { color: TERMINAL_COLORS.gridMajor },
  },
  crosshair: {
    mode: CrosshairMode.Normal,
    vertLine: {
      color: TERMINAL_COLORS.muted,
      width: 1,
      style: 3,
    },
    horzLine: {
      color: TERMINAL_COLORS.muted,
      width: 1,
      style: 3,
    },
  },
  timeScale: {
    visible: true,
    borderVisible: true,
    borderColor: TERMINAL_COLORS.panelStrong,
    timeVisible: true,
    secondsVisible: false,
    ticksVisible: true,
    minimumHeight: 22,
  },
} satisfies DeepPartial<ChartOptions>;

/** Flat portfolio hero chart options aligned with terminal.css tokens. */
export function createPortfolioChartOptions(): DeepPartial<ChartOptions> {
  return {
    ...sharedChartLayout,
    rightPriceScale: {
      borderColor: TERMINAL_COLORS.panelStrong,
      visible: true,
      scaleMargins: { top: 0.08, bottom: 0.08 },
    },
    leftPriceScale: {
      visible: false,
    },
  };
}

/** PnL chart with Y-axis on the left (supports negative values). */
export function createPortfolioPnlChartOptions(): DeepPartial<ChartOptions> {
  return {
    ...sharedChartLayout,
    defaultVisiblePriceScaleId: "left",
    rightPriceScale: {
      visible: false,
    },
    leftPriceScale: {
      borderColor: TERMINAL_COLORS.panelStrong,
      visible: true,
      autoScale: true,
      scaleMargins: { top: 0.08, bottom: 0.08 },
    },
  };
}

const portfolioAreaSeriesBase = {
  lineColor: TERMINAL_COLORS.brand,
  topColor: TERMINAL_COLORS.brandSoft,
  bottomColor: TERMINAL_COLORS.brandFillBottom,
  lineWidth: 2 as const,
  crosshairMarkerVisible: true,
  crosshairMarkerRadius: 5,
  crosshairMarkerBorderColor: TERMINAL_COLORS.brand,
  crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
};

export function portfolioAreaSeriesOptions() {
  return {
    ...portfolioAreaSeriesBase,
    priceScaleId: "right" as const,
  };
}

export function portfolioLeftAxisAreaSeriesOptions() {
  return {
    ...portfolioAreaSeriesBase,
    priceScaleId: "left" as const,
  };
}

export function portfolioLineSeriesOptions(
  color: string,
  lineType: LineType = LineType.Simple,
) {
  return {
    color,
    lineWidth: 2 as const,
    lineType,
    crosshairMarkerVisible: true,
    crosshairMarkerRadius: 5,
    crosshairMarkerBorderColor: TERMINAL_COLORS.brand,
    crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
    priceScaleId: "right" as const,
  };
}

export function portfolioPnlLineSeriesOptions(color: string) {
  return {
    ...portfolioLineSeriesOptions(color, LineType.WithSteps),
    priceScaleId: "left" as const,
  };
}
