import type { JSX, ReactNode } from "react";
import { BUBBLE_TIP_IDS, type BubbleTipId } from "./bubbleTipIds";
import { getBubbleTipContent } from "./bubbleTipContent";

function IntentCard({ title, summary }: { title: string; summary: string }): JSX.Element {
  return (
    <div className="bubble-tip-guide__intent-card">
      <div className="bubble-tip-guide__intent-card-title">{title}</div>
      <div className="bubble-tip-guide__intent-card-summary">{summary}</div>
    </div>
  );
}

function InfoRow({ label, value, valueClassName }: { label: string; value: string; valueClassName?: string }): JSX.Element {
  return (
    <div className="bubble-tip-guide__info-row">
      <span className="terminal-label">{label}</span>
      <span className={`terminal-value ${valueClassName ?? ""}`.trim()}>{value}</span>
    </div>
  );
}

function OrderbookRow({
  price,
  size,
  total,
  side,
}: {
  price: string;
  size: string;
  total: string;
  side: "bid" | "ask" | "header";
}): JSX.Element {
  const sideClass = side === "ask" ? "terminal-short" : side === "bid" ? "terminal-long" : "";
  return (
    <div className={`bubble-tip-guide__orderbook-row ${sideClass}`.trim()}>
      <span>{price}</span>
      <span>{size}</span>
      <span>{total}</span>
    </div>
  );
}

function FutureTrigger({ label }: { label: string }): JSX.Element {
  return (
    <>
      {label}
      <span className="bubble-tip-guide__future-badge">Soon</span>
    </>
  );
}

