/** Whether the demo card needs a context label above the mock trigger. */
export function guideTriggerNeedsLabel(tipId: BubbleTipId): boolean {
  switch (tipId) {
    case BUBBLE_TIP_IDS.orderbookClickPrice:
    case BUBBLE_TIP_IDS.recentTradesTape:
      return true;
    default:
      return false;
  }
}
