import React, { useState } from "react";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import {
  AGENT_RANK_ACTION_LABELS,
  type AgentRankActionHint,
  type AgentRankRow,
  type AgentRankSummary,
} from "../../utils/portfolioAgentRankMetrics";
import PortfolioAgentRankQuadrantChart from "./PortfolioAgentRankQuadrantChart";
import "./portfolio.css";

export interface PortfolioAgentRankChartProps {
  summary: AgentRankSummary;
  focusAgentId?: string | null;
}

type AgentRankViewMode = "chart" | "data";

const ACTION_HINT_COLORS: Record<AgentRankActionHint, string> = {
  scale: "#00ff88",
  keep: "#c8f5a8",
  monitor: "rgba(255, 255, 255, 0.55)",
  tweak: "#fbbf24",
  pause: "#ff4757",
};

function formatScore(value: number): string {
  return value.toFixed(0);
}

function formatPct(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`;
}

function formatSharpe(value: number): string {
  return value.toFixed(2);
}

function formatProfitFactor(value: number): string {
  return `${value.toFixed(1)}×`;
}

function formatCalmar(value: number): string {
  return value.toFixed(1);
}

function buildAgentTipTitle(agent: AgentRankRow): string {
  return `${agent.icon ? `${agent.icon} ` : ""}${agent.label}`;
}

function buildAgentTipContent(agent: AgentRankRow): string {
  return [
    `Composite ${formatScore(agent.compositeScore)} · ${AGENT_RANK_ACTION_LABELS[agent.actionHint]}.`,
    `CAGR ${formatPct(agent.cagrPct)} · Sharpe ${formatSharpe(agent.sharpe)} · MDD -${agent.maxDrawdownPct.toFixed(1)}% · PF ${formatProfitFactor(agent.profitFactor)}.`,
    `Calmar tie-breaker ${formatCalmar(agent.calmarRatio)} (CAGR ÷ MDD).`,
  ].join(" ");
}

function PortfolioAgentRankChart({
  summary,
  focusAgentId = null,
}: PortfolioAgentRankChartProps): JSX.Element {
  const [viewMode, setViewMode] = useState<AgentRankViewMode>("chart");
  const hasAgents = summary.agents.length > 0;

  return (
    <div className="portfolio-agent-rank-chart">
      <div className="portfolio-agent-rank-kpis">
        <div className="portfolio-agent-rank-kpi">
          <span className="portfolio-agent-rank-kpi-label">Top composite</span>
          <span className="portfolio-agent-rank-kpi-value">
            {summary.topAgent
              ? `${summary.topAgent.icon ? `${summary.topAgent.icon} ` : ""}${summary.topAgent.label} · ${formatScore(summary.topAgent.compositeScore)}`
              : "—"}
          </span>
        </div>
        <div className="portfolio-agent-rank-kpi">
          <span className="portfolio-agent-rank-kpi-label">Fleet median</span>
          <span className="portfolio-agent-rank-kpi-value">
            {formatScore(summary.fleetMedianComposite)}
          </span>
        </div>
        <div className="portfolio-agent-rank-kpi">
          <span className="portfolio-agent-rank-kpi-label">Above median</span>
          <span className="portfolio-agent-rank-kpi-value">
            {summary.aboveMedianPct.toFixed(0)}%
          </span>
        </div>
      </div>

      <div className="portfolio-agent-rank-body">
        {viewMode === "chart" ? (
          <PortfolioAgentRankQuadrantChart
            summary={summary}
            focusAgentId={focusAgentId}
          />
        ) : hasAgents ? (
          <div
            className="portfolio-agent-rank-list"
            role="list"
            aria-label="Agent composite rank"
          >
            {summary.agents.map((agent) => (
              <BubbleTip
                key={agent.id}
                id={BUBBLE_TIP_IDS.agentRankAgent}
                title={buildAgentTipTitle(agent)}
                content={buildAgentTipContent(agent)}
                side="top"
              >
                <div className="portfolio-agent-rank-row" role="listitem">
                  <span className="portfolio-agent-rank-position">
                    #{agent.rank}
                  </span>
                  <span className="portfolio-agent-rank-name">
                    {agent.icon ? `${agent.icon} ` : ""}
                    {agent.label}
                  </span>
                  <div className="portfolio-agent-rank-bar-track">
                    <div
                      className="portfolio-agent-rank-bar-fill"
                      style={{
                        width: `${Math.max(agent.compositeScore, 2)}%`,
                        background: agent.color,
                      }}
                    />
                  </div>
                  <span className="portfolio-agent-rank-score">
                    {formatScore(agent.compositeScore)}
                  </span>
                  <span
                    className="portfolio-agent-rank-action"
                    style={{
                      borderColor: ACTION_HINT_COLORS[agent.actionHint],
                    }}
                  >
                    {AGENT_RANK_ACTION_LABELS[agent.actionHint]}
                  </span>
                </div>
              </BubbleTip>
            ))}
          </div>
        ) : (
          <p className="terminal-text-muted portfolio-agent-rank-empty">
            No agent rank data.
          </p>
        )}

        <div className="portfolio-agent-rank-footer">
          <div
            className="portfolio-agent-rank-view-toggle"
            role="group"
            aria-label="Toggle composite rank view"
          >
            <button
              type="button"
              className={`portfolio-agent-rank-view-toggle-btn${
                viewMode === "chart" ? " is-active" : ""
              }`}
              aria-pressed={viewMode === "chart"}
              onClick={() => setViewMode("chart")}
            >
              Chart
            </button>
            <button
              type="button"
              className={`portfolio-agent-rank-view-toggle-btn${
                viewMode === "data" ? " is-active" : ""
              }`}
              aria-pressed={viewMode === "data"}
              onClick={() => setViewMode("data")}
            >
              Data
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default React.memo(PortfolioAgentRankChart);
