import React, {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type JSX,
  type KeyboardEvent,
  type TouchEvent,
  type TransitionEvent,
} from "react";
import {
  WELCOME_RAIL_DESKTOP_MIN_PX,
  WELCOME_RAIL_MOBILE_MAX_PX,
  WELCOME_STORY_RAIL_INTERVAL_MS,
  WELCOME_STORY_RAIL_TRANSITION_MS,
} from "./constants";
import type { WelcomeSlide } from "./content";
import { WelcomeSlideAnimatedContent } from "./WelcomeSlideAnimatedContent";

const SWIPE_THRESHOLD_PX = 40;

interface ExtendedSlideEntry {
  slide: WelcomeSlide;
  key: string;
  logicalIndex: number;
  isClone: boolean;
}

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function useViewportWidth(): number {
  const [width, setWidth] = useState(() =>
    typeof window !== "undefined" ? window.innerWidth : WELCOME_RAIL_DESKTOP_MIN_PX,
  );

  useEffect(() => {
    const handleResize = () => setWidth(window.innerWidth);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return width;
}

function reenableTransition(setTransitionEnabled: (enabled: boolean) => void): void {
  requestAnimationFrame(() => {
    requestAnimationFrame(() => setTransitionEnabled(true));
  });
}

export interface WelcomeStoryRailHandle {
  goToPrev: () => void;
  goToNext: () => void;
}

export interface WelcomeStoryRailProps {
  slides: WelcomeSlide[];
}

export const WelcomeStoryRail = forwardRef<WelcomeStoryRailHandle, WelcomeStoryRailProps>(
  function WelcomeStoryRail({ slides }, ref): JSX.Element {
    const slideCount = slides.length;
    const useCloneTrack = slideCount > 1;
    const [activeIndex, setActiveIndex] = useState(0);
    const [trackIndex, setTrackIndex] = useState(1);
    const [transitionEnabled, setTransitionEnabled] = useState(true);
    const [isPaused, setIsPaused] = useState(false);
    const [isManualNav, setIsManualNav] = useState(false);
    const [isTypingComplete, setIsTypingComplete] = useState(false);
    const [reducedMotion, setReducedMotion] = useState(prefersReducedMotion);
    const touchStartXRef = useRef<number | null>(null);
    const autoplayTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const autoplayRemainingRef = useRef(WELCOME_STORY_RAIL_INTERVAL_MS);
    const autoplayStartedAtRef = useRef<number | null>(null);
    const manualNavTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const trackIndexRef = useRef(trackIndex);
    const snapFallbackTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    trackIndexRef.current = trackIndex;
    const viewportWidth = useViewportWidth();
    const isDesktop = viewportWidth >= WELCOME_RAIL_DESKTOP_MIN_PX;
    const isMobile = viewportWidth <= WELCOME_RAIL_MOBILE_MAX_PX;
    const autoplayEnabled = !reducedMotion && !isMobile;

    const extendedSlides = useMemo((): ExtendedSlideEntry[] => {
      if (!useCloneTrack) {
        return slides.map((slide, index) => ({
          slide,
          key: slide.id,
          logicalIndex: index,
          isClone: false,
        }));
      }

      const last = slides[slideCount - 1];
      const first = slides[0];
      return [
        {
          slide: last,
          key: `${last.id}-clone-start`,
          logicalIndex: slideCount - 1,
          isClone: true,
        },
        ...slides.map((slide, index) => ({
          slide,
          key: slide.id,
          logicalIndex: index,
          isClone: false,
        })),
        {
          slide: first,
          key: `${first.id}-clone-end`,
          logicalIndex: 0,
          isClone: true,
        },
      ];
    }, [slideCount, slides, useCloneTrack]);

    useEffect(() => {
      const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
      const handleChange = () => setReducedMotion(mediaQuery.matches);
      handleChange();
      mediaQuery.addEventListener("change", handleChange);
      return () => mediaQuery.removeEventListener("change", handleChange);
    }, []);

    const clearAutoplayTimer = useCallback(() => {
      if (autoplayTimerRef.current) {
        clearTimeout(autoplayTimerRef.current);
        autoplayTimerRef.current = null;
      }
    }, []);

    const clearSnapFallbackTimer = useCallback(() => {
      if (snapFallbackTimerRef.current) {
        clearTimeout(snapFallbackTimerRef.current);
        snapFallbackTimerRef.current = null;
      }
    }, []);

    const snapToRealTrackIndex = useCallback((realTrackIndex: number) => {
      setTransitionEnabled(false);
      setTrackIndex(realTrackIndex);
      reenableTransition(setTransitionEnabled);
    }, []);

    const markManualNav = useCallback(() => {
      setIsManualNav(true);
      if (manualNavTimerRef.current) clearTimeout(manualNavTimerRef.current);
      manualNavTimerRef.current = setTimeout(() => setIsManualNav(false), 1000);
    }, []);

    const jumpToIndex = useCallback(
      (nextIndex: number) => {
        setTransitionEnabled(false);
        setActiveIndex(nextIndex);
        if (useCloneTrack) {
          setTrackIndex(nextIndex + 1);
        }
        reenableTransition(setTransitionEnabled);
      },
      [useCloneTrack],
    );

    const goToAdjacent = useCallback(
      (direction: 1 | -1, manual = false) => {
        const nextActive = (activeIndex + direction + slideCount) % slideCount;

        if (!useCloneTrack || reducedMotion) {
          jumpToIndex(nextActive);
        } else {
          setTransitionEnabled(true);
          setActiveIndex(nextActive);
          setTrackIndex((current) => current + direction);
        }

        if (manual) markManualNav();
      },
      [activeIndex, jumpToIndex, markManualNav, reducedMotion, slideCount, useCloneTrack],
    );

    const goToIndex = useCallback(
      (index: number, manual = false) => {
        const nextIndex = ((index % slideCount) + slideCount) % slideCount;
        if (nextIndex === activeIndex) return;

        const isAdjacent = Math.abs(nextIndex - activeIndex) === 1;

        if (!useCloneTrack || reducedMotion || !isAdjacent) {
          jumpToIndex(nextIndex);
        } else {
          const direction = nextIndex > activeIndex ? 1 : -1;
          goToAdjacent(direction, false);
        }

        if (manual) markManualNav();
      },
      [
        activeIndex,
        goToAdjacent,
        jumpToIndex,
        markManualNav,
        reducedMotion,
        slideCount,
        useCloneTrack,
      ],
    );

    const goToPrev = useCallback(() => {
      goToAdjacent(-1, true);
    }, [goToAdjacent]);

    const goToNext = useCallback(
      (manual = true) => {
        goToAdjacent(1, manual);
      },
      [goToAdjacent],
    );

    const handleTransitionEnd = useCallback(
      (event: TransitionEvent<HTMLDivElement>) => {
        if (!useCloneTrack || reducedMotion) return;
        if (event.propertyName !== "transform") return;
        if (event.target !== event.currentTarget) return;

        const currentTrackIndex = trackIndexRef.current;
        clearSnapFallbackTimer();

        if (currentTrackIndex === slideCount + 1) {
          snapToRealTrackIndex(1);
        } else if (currentTrackIndex === 0) {
          snapToRealTrackIndex(slideCount);
        }
      },
      [
        clearSnapFallbackTimer,
        reducedMotion,
        slideCount,
        snapToRealTrackIndex,
        useCloneTrack,
      ],
    );

    useEffect(() => {
      if (!useCloneTrack || reducedMotion) return;

      clearSnapFallbackTimer();

      if (trackIndex === slideCount + 1) {
        snapFallbackTimerRef.current = setTimeout(() => {
          if (trackIndexRef.current === slideCount + 1) {
            snapToRealTrackIndex(1);
          }
        }, WELCOME_STORY_RAIL_TRANSITION_MS + 50);
      } else if (trackIndex === 0) {
        snapFallbackTimerRef.current = setTimeout(() => {
          if (trackIndexRef.current === 0) {
            snapToRealTrackIndex(slideCount);
          }
        }, WELCOME_STORY_RAIL_TRANSITION_MS + 50);
      }

      return clearSnapFallbackTimer;
    }, [
      clearSnapFallbackTimer,
      reducedMotion,
      slideCount,
      snapToRealTrackIndex,
      trackIndex,
      useCloneTrack,
    ]);

    useLayoutEffect(() => {
      setIsTypingComplete(false);
      autoplayRemainingRef.current = WELCOME_STORY_RAIL_INTERVAL_MS;
      autoplayStartedAtRef.current = null;
    }, [activeIndex]);

    const handleSequenceComplete = useCallback(() => {
      setIsTypingComplete(true);
    }, []);

    useImperativeHandle(
      ref,
      () => ({
        goToPrev,
        goToNext: () => goToNext(true),
      }),
      [goToNext, goToPrev],
    );

    useEffect(() => {
      clearAutoplayTimer();

      if (!autoplayEnabled || !isTypingComplete) {
        if (!isTypingComplete) {
          autoplayRemainingRef.current = WELCOME_STORY_RAIL_INTERVAL_MS;
          autoplayStartedAtRef.current = null;
        }
        return;
      }

      if (isPaused) {
        if (autoplayStartedAtRef.current != null) {
          const elapsed = Date.now() - autoplayStartedAtRef.current;
          autoplayRemainingRef.current = Math.max(
            0,
            autoplayRemainingRef.current - elapsed,
          );
          autoplayStartedAtRef.current = null;
        }
        return;
      }

      autoplayStartedAtRef.current = Date.now();
      autoplayTimerRef.current = setTimeout(() => {
        autoplayRemainingRef.current = WELCOME_STORY_RAIL_INTERVAL_MS;
        autoplayStartedAtRef.current = null;
        goToAdjacent(1, false);
      }, autoplayRemainingRef.current);

      return clearAutoplayTimer;
    }, [
      activeIndex,
      autoplayEnabled,
      clearAutoplayTimer,
      goToAdjacent,
      isPaused,
      isTypingComplete,
    ]);

    useEffect(
      () => () => {
        clearAutoplayTimer();
        clearSnapFallbackTimer();
        if (manualNavTimerRef.current) clearTimeout(manualNavTimerRef.current);
      },
      [clearAutoplayTimer, clearSnapFallbackTimer],
    );

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        goToPrev();
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        goToNext(true);
      }
    };

    const handleTouchStart = (event: TouchEvent<HTMLDivElement>) => {
      touchStartXRef.current = event.changedTouches[0]?.clientX ?? null;
    };

    const handleTouchEnd = (event: TouchEvent<HTMLDivElement>) => {
      const startX = touchStartXRef.current;
      const endX = event.changedTouches[0]?.clientX;
      touchStartXRef.current = null;
      if (startX == null || endX == null) return;

      const delta = endX - startX;
      if (Math.abs(delta) < SWIPE_THRESHOLD_PX) return;
      if (delta > 0) {
        goToPrev();
      } else {
        goToNext(true);
      }
    };

    const isTrackSettled =
      !useCloneTrack || reducedMotion || trackIndex === activeIndex + 1;

    const renderSlide = (entry: ExtendedSlideEntry) => {
      const slideIsActive =
        !entry.isClone && entry.logicalIndex === activeIndex && isTrackSettled;

      return (
        <article
          key={entry.key}
          className="welcome-story-rail-slide"
          role="group"
          aria-roledescription="slide"
          aria-label={`${entry.logicalIndex + 1} of ${slideCount}`}
          aria-hidden={entry.isClone || entry.logicalIndex !== activeIndex}
        >
          <WelcomeSlideAnimatedContent
            slide={entry.slide}
            isActive={slideIsActive}
            onSequenceComplete={slideIsActive ? handleSequenceComplete : undefined}
          />
        </article>
      );
    };

    const trackOffset = useCloneTrack ? trackIndex : activeIndex;
    const trackTransitionMs =
      reducedMotion || !transitionEnabled ? 0 : WELCOME_STORY_RAIL_TRANSITION_MS;

    const progressFillClassName = [
      "welcome-story-rail-progress-fill",
      isTypingComplete && (isPaused || !autoplayEnabled) ? "is-paused" : "",
      !isTypingComplete ? "is-waiting" : "",
      reducedMotion ? "is-reduced" : "",
    ]
      .filter(Boolean)
      .join(" ");

    const progressControl = (
      <div className="welcome-story-rail-progress" aria-hidden>
        <div
          key={`progress-${activeIndex}-${isTypingComplete ? "ready" : "waiting"}`}
          className={progressFillClassName}
        />
      </div>
    );

    const dotsControl = (
      <div className="welcome-story-rail-dots" role="tablist" aria-label="Story slides">
        {slides.map((slide, index) => (
          <button
            key={slide.id}
            type="button"
            role="tab"
            className={`welcome-story-rail-dot${index === activeIndex ? " is-active" : ""}`}
            aria-label={`Go to slide ${index + 1}: ${slide.headline}`}
            aria-selected={index === activeIndex}
            onClick={() => goToIndex(index, true)}
          />
        ))}
      </div>
    );

    return (
      <section
        className={`welcome-story-rail${isDesktop ? " welcome-story-rail--desktop" : ""}${isMobile ? " welcome-story-rail--mobile" : ""}`}
        aria-label="Welcome overview"
        aria-live={isManualNav ? "polite" : "off"}
        onMouseEnter={() => setIsPaused(true)}
        onMouseLeave={() => setIsPaused(false)}
        onFocusCapture={() => setIsPaused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
            setIsPaused(false);
          }
        }}
        onKeyDown={handleKeyDown}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        tabIndex={-1}
      >
        <div className="welcome-story-rail-row">
          {isDesktop ? (
            <button
              type="button"
              className="welcome-story-rail-nav welcome-story-rail-nav--prev"
              aria-label="Previous slide"
              onClick={goToPrev}
            >
              ‹
            </button>
          ) : null}

          <div className="welcome-story-rail-viewport">
            <div
              className={`welcome-story-rail-track${reducedMotion ? " is-reduced" : ""}`}
              style={{
                transform: `translateX(-${trackOffset * 100}%)`,
                transitionDuration: `${trackTransitionMs}ms`,
              }}
              onTransitionEnd={handleTransitionEnd}
            >
              {extendedSlides.map((entry) => renderSlide(entry))}
            </div>
          </div>

          {isDesktop ? (
            <button
              type="button"
              className="welcome-story-rail-nav welcome-story-rail-nav--next"
              aria-label="Next slide"
              onClick={() => goToNext(true)}
            >
              ›
            </button>
          ) : null}
        </div>

        {isDesktop ? (
          <>
            {progressControl}
            {dotsControl}
          </>
        ) : null}

        {!isDesktop ? (
          <>
            {!isMobile ? progressControl : null}
            <div className="welcome-story-rail-bottom-nav">
              {!isMobile ? (
                <button
                  type="button"
                  className="welcome-story-rail-nav welcome-story-rail-nav--prev"
                  aria-label="Previous slide"
                  onClick={goToPrev}
                >
                  ‹
                </button>
              ) : null}
              <div className="welcome-story-rail-bottom-nav-center">{dotsControl}</div>
              {!isMobile ? (
                <button
                  type="button"
                  className="welcome-story-rail-nav welcome-story-rail-nav--next"
                  aria-label="Next slide"
                  onClick={() => goToNext(true)}
                >
                  ›
                </button>
              ) : null}
            </div>
          </>
        ) : null}

        {isMobile ? (
          <p className="welcome-story-rail-swipe-hint">Swipe left or right to move</p>
        ) : null}
      </section>
    );
  },
);
