import type { JSX } from "react";
import type { IntentBreakdown } from "../intentBreakdown";

export interface IntentPortfolioBodyProps {
  breakdown: IntentBreakdown;
}

export function IntentPortfolioBody({
  breakdown,
}: IntentPortfolioBodyProps): JSX.Element {
  const assets = breakdown.slots.assets.value ?? ["BTC", "ETH", "SOL", "USDC"];
  const weights = ["40%", "30%", "20%", "10%"];

  return (
    <div className="intent-portfolio-body">
      <div className="intent-portfolio-scope" role="group" aria-label="Scope">
        <button type="button" className="intent-scope-chip is-active">
          Whole book
        </button>
        <button type="button" className="intent-scope-chip">
          Majors
        </button>
        <button type="button" className="intent-scope-chip">
          Custom set
        </button>
      </div>
      <div className="intent-portfolio-weights">
        <span className="terminal-label">Weights</span>
        {assets.slice(0, 4).map((asset, i) => (
          <span key={asset} className="intent-weight-chip">
            {asset} {weights[i] ?? "—"}
          </span>
        ))}
      </div>
      <div className="intent-portfolio-band">
        <span className="terminal-label">Rebalance band</span>
        <span>±5%</span>
      </div>
    </div>
  );
}
