import React from "react";

import type { CompareMatrixSection } from "../../utils/agentCompareMatrix";
import AgentCompareMatrixDailyPnlCell from "./AgentCompareMatrixDailyPnlCell";
import "./agent.css";

export interface AgentCompareMatrixTableProps {
  section: CompareMatrixSection;
  columnCount: number;
  showAddSlot: boolean;
  highlightBest?: boolean;
}

function AgentCompareMatrixAddSpacer(): JSX.Element {
  return (
    <th scope="col" className="agent-compare-matrix-add-spacer" aria-hidden />
  );
}

function AgentCompareMatrixAddSpacerCell(): JSX.Element {
  return <td className="agent-compare-matrix-add-spacer" aria-hidden />;
}

function AgentCompareMatrixListCell({ items }: { items: string[] }): JSX.Element {
  return (
    <ul className="agent-compare-matrix-list">
      {items.map((item) => (
        <li key={item}>{item}</li>
      ))}
    </ul>
  );
}

function AgentCompareMatrixTable({
  section,
  columnCount,
  showAddSlot,
  highlightBest = true,
}: AgentCompareMatrixTableProps): JSX.Element {
  return (
    <div className="agent-compare-matrix-scroll">
      <table className="agent-compare-matrix-table">
        <caption className="agent-compare-matrix-section-label">
          <span className="agent-compare-matrix-section-name">{section.label}</span>
          <span className="agent-compare-matrix-section-hint">{section.hint}</span>
        </caption>
        <colgroup>
          <col className="agent-compare-matrix-col-label" />
          {showAddSlot ? <col className="agent-compare-matrix-col-add" /> : null}
          {Array.from({ length: columnCount }, (_, index) => (
            <col key={`col-${index}`} className="agent-compare-matrix-col-agent" />
          ))}
        </colgroup>
        <thead>
          <tr className="agent-compare-matrix-row agent-compare-matrix-row--header">
            <th scope="col" className="agent-compare-matrix-label-cell">
              Metric
            </th>
            {showAddSlot ? <AgentCompareMatrixAddSpacer /> : null}
            {Array.from({ length: columnCount }, (_, index) => (
              <th
                key={`header-col-${index}`}
                scope="col"
                className="agent-compare-matrix-value-cell"
              >
                Agent {index + 1}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {section.rows.map((row, rowIndex) => {
            const isCalendarRow = row.kind === "dailyPnlCalendar";
            const isListRow = row.kind === "list";
            return (
              <tr
                key={row.label}
                className={`agent-compare-matrix-row${
                  isCalendarRow ? " agent-compare-matrix-row--calendar" : ""
                }${isListRow ? " agent-compare-matrix-row--list" : ""}${
                  !isCalendarRow && !isListRow && rowIndex % 2 === 1
                    ? " agent-compare-matrix-row--alt"
                    : ""
                }`}
              >
                <th scope="row" className="agent-compare-matrix-label-cell">
                  {row.label}
                </th>
                {showAddSlot ? <AgentCompareMatrixAddSpacerCell /> : null}
                {isCalendarRow
                  ? (row.calendarCells ?? []).map((calendarDays, cellIndex) => (
                      <td
                        key={`${row.label}-calendar-${cellIndex}`}
                        className={`agent-compare-matrix-value-cell agent-compare-matrix-value-cell--calendar${
                          calendarDays ? "" : " agent-compare-matrix-cell--placeholder"
                        }`}
                      >
                        {calendarDays ? (
                          <AgentCompareMatrixDailyPnlCell days={calendarDays} />
                        ) : (
                          <span className="agent-compare-matrix-empty">—</span>
                        )}
                      </td>
                    ))
                  : row.cells.map((cell, cellIndex) => (
                      <td
                        key={`${row.label}-${cellIndex}`}
                        className={`agent-compare-matrix-value-cell${
                          isListRow ? " agent-compare-matrix-value-cell--list" : ""
                        }${cell ? "" : " agent-compare-matrix-cell--placeholder"}`}
                      >
                        {cell ? (
                          isListRow && cell.listItems && cell.listItems.length > 0 ? (
                            <AgentCompareMatrixListCell items={cell.listItems} />
                          ) : (
                            <span
                              className={[
                                "agent-compare-kpi-value",
                                cell.tone ?? "",
                                highlightBest && cell.isBest
                                  ? "agent-compare-kpi-value--best"
                                  : "",
                              ]
                                .filter(Boolean)
                                .join(" ")}
                            >
                              {cell.value}
                            </span>
                          )
                        ) : (
                          <span className="agent-compare-matrix-empty">—</span>
                        )}
                      </td>
                    ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default AgentCompareMatrixTable;
