import type { KeyboardBinding } from "./types";
import { normalizeKey } from "./normalizeKey";

export function matchesKeyboardBinding(
  event: KeyboardEvent,
  binding: KeyboardBinding,
): boolean {
  const eventKey = normalizeKey(event.key);
  const bindingKey = normalizeKey(binding.key);

  if (eventKey !== bindingKey) return false;
  if (event.metaKey !== binding.meta) return false;
  if (event.ctrlKey !== binding.ctrl) return false;
  if (event.altKey !== binding.alt) return false;

  if (binding.excludeShift) {
    if (event.shiftKey) return false;
  } else if (event.shiftKey !== binding.shift) {
    return false;
  }

  return true;
}

export function bindingsAreEqual(a: KeyboardBinding, b: KeyboardBinding): boolean {
  return (
    normalizeKey(a.key) === normalizeKey(b.key) &&
    a.meta === b.meta &&
    a.ctrl === b.ctrl &&
    a.alt === b.alt &&
    a.shift === b.shift &&
    Boolean(a.excludeShift) === Boolean(b.excludeShift)
  );
}
