import React, { useState } from "react";
import {
  calculateRiskRatio,
  getDisplayMarginType,
  type Bucket,
} from "../../sdk";
import { formatCurrency, formatPercentage } from "../../sdk/utils/display";
import { AnimatedCollapse } from "../ui/AnimatedCollapse";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { getBucketCapitalSummary } from "./bucketCapital";
import "./bucketCollection.css";

export interface BucketOverviewPanelProps {
  bucket: Bucket;
}

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function truncateAddress(address: string): string {
  if (address.length <= 12) return address;
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

function CollapsibleSection({
  title,
  headline,
  defaultOpen = false,
  children,
}: {
  title: string;
  headline?: React.ReactNode;
  defaultOpen?: boolean;
  children: React.ReactNode;
}): JSX.Element {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <section className="bucket-overview-section">
      <button
        type="button"
        className="bucket-overview-section-toggle"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <span className="bucket-overview-section-title">{title}</span>
        {headline ? (
          <span className="bucket-overview-section-headline">{headline}</span>
        ) : null}
        <ExpandCollapseIcon
          expanded={open}
          className="bucket-overview-chevron"
          size={14}
        />
      </button>
      <AnimatedCollapse
        open={open}
        timing="deck"
        innerClassName="bucket-overview-section-body"
      >
        {children}
      </AnimatedCollapse>
    </section>
  );
}

function DetailRow({ label, value, title }: { label: string; value: React.ReactNode; title?: string }) {
  return (
    <div className="bucket-overview-row">
      <dt className="terminal-label">{label}</dt>
      <dd className="terminal-value" title={title}>
        {value}
      </dd>
    </div>
  );
}

function BucketOverviewPanel({ bucket }: BucketOverviewPanelProps): JSX.Element {
  const capital = getBucketCapitalSummary(bucket);
  const riskRatio = calculateRiskRatio(bucket);
  const marginType = getDisplayMarginType(bucket);
  const riskLabel =
    riskRatio < 0.25 ? "low" : riskRatio < 0.5 ? "moderate" : "elevated";

  return (
    <div className="bucket-overview-panel">
      <section className="bucket-overview-section bucket-overview-section--capital">
        <h4 className="bucket-overview-section-title">Capital</h4>
        <dl className="bucket-overview-grid">
          <DetailRow label="Total equity" value={formatCurrency(capital.totalEquity)} />
          <DetailRow
            label="Withdrawable now"
            value={
              <span className="bucket-overview-withdrawable">
                {formatCurrency(capital.withdrawable)}
              </span>
            }
          />
        </dl>
        <div className="bucket-overview-locked-breakdown">
          <p className="terminal-label bucket-overview-locked-title">Locked breakdown</p>
          <dl className="bucket-overview-grid bucket-overview-grid--nested">
            <DetailRow
              label="In open positions (margin)"
              value={formatCurrency(capital.lockedInPositions)}
            />
            <DetailRow
              label="Reserved by open orders"
              value={formatCurrency(capital.reservedByOrders)}
            />
            {capital.pendingSettlement > 0 ? (
              <DetailRow
                label="Pending settlement"
                value={formatCurrency(capital.pendingSettlement)}
              />
            ) : null}
          </dl>
        </div>
      </section>

      <CollapsibleSection
        title="Risk"
        headline={
          <>
            Risk ratio {formatPercentage(riskRatio)}{" "}
            <span className="bucket-overview-risk-label">({riskLabel})</span>
          </>
        }
      >
        <dl className="bucket-overview-grid">
          <DetailRow label="Margin ratio" value={formatPercentage(bucket.marginRatio || 0)} />
          <DetailRow
            label="IMR"
            value={bucket.imr != null ? `${bucket.imr}%` : "—"}
          />
          <DetailRow
            label="Max leverage"
            value={bucket.maxLeverage != null ? `${bucket.maxLeverage}x` : "—"}
          />
          <DetailRow label="Risk level" value={bucket.riskLevel || "—"} />
          <DetailRow
            label="Total notional"
            value={formatCurrency(bucket.totalNotionalValue || 0)}
          />
        </dl>
      </CollapsibleSection>

      <CollapsibleSection
        title="Performance"
        headline={
          <>
            Unrealized PnL{" "}
            <span
              className={
                (bucket.unrealizedPnL || 0) >= 0
                  ? "bucket-overview-pnl-positive"
                  : "bucket-overview-pnl-negative"
              }
            >
              {formatCurrency(bucket.unrealizedPnL || 0)}
            </span>
          </>
        }
      >
        <dl className="bucket-overview-grid">
          <DetailRow
            label="Unrealized profit"
            value={formatCurrency(bucket.unrealizedProfit || 0)}
          />
          <DetailRow
            label="Unrealized loss"
            value={formatCurrency(bucket.unrealizedLoss || 0)}
          />
          <DetailRow
            label="Realized profit"
            value={formatCurrency(bucket.realizedProfit || 0)}
          />
          <DetailRow
            label="Realized loss"
            value={formatCurrency(bucket.realizedLoss || 0)}
          />
        </dl>
      </CollapsibleSection>

      <CollapsibleSection title="Details">
        <dl className="bucket-overview-grid">
          <DetailRow label="Bucket ID" value={bucket.bucketId} title={bucket.bucketId} />
          <DetailRow
            label="Address"
            value={truncateAddress(bucket.address || "—")}
            title={bucket.address || undefined}
          />
          <DetailRow label="Margin type" value={marginType.toUpperCase()} />
          <DetailRow label="Collateral" value={bucket.collateralAsset || "—"} />
          <DetailRow label="Status" value={bucket.status || "—"} />
          <DetailRow label="Created" value={formatDateTime(bucket.createdAt)} />
          <DetailRow label="Updated" value={formatDateTime(bucket.updatedAt)} />
        </dl>
      </CollapsibleSection>
    </div>
  );
}

export default React.memo(BucketOverviewPanel);
