import type { KeyboardBinding } from "./types";
import { normalizeKey } from "./normalizeKey";

const MODIFIER_KEYS = new Set([
  "control",
  "ctrl",
  "shift",
  "alt",
  "meta",
  "os",
]);

export function isModifierOnlyKey(key: string): boolean {
  return MODIFIER_KEYS.has(normalizeKey(key));
}

export function captureKeyboardBinding(event: KeyboardEvent): KeyboardBinding | null {
  const key = normalizeKey(event.key);
  if (!key || isModifierOnlyKey(key)) return null;

  const hasModifier = event.metaKey || event.ctrlKey || event.altKey || event.shiftKey;
  if (!hasModifier) return null;

  return {
    key,
    meta: event.metaKey,
    ctrl: event.ctrlKey,
    alt: event.altKey,
    shift: event.shiftKey,
  };
}

export function isValidKeyboardBinding(binding: KeyboardBinding | null): binding is KeyboardBinding {
  if (!binding) return false;
  if (!binding.key) return false;
  if (isModifierOnlyKey(binding.key)) return false;
  return binding.meta || binding.ctrl || binding.alt || binding.shift;
}
