import type { IndexPerformanceMetrics } from "../../offline/mock_data/types";
import type { CompactMetricDefinition } from "../components/metrics/types";
import { formatPercent } from "../components/index/indexFormat";
import { buildSignedPercentLineData, HOUR_MS } from "./compactMetricChartData";

type MetricKey = keyof IndexPerformanceMetrics;

interface PerformanceMetricConfig {
  label: string;
  key: MetricKey;
  pointCount: number;
  stepMs: number;
}

const PERFORMANCE_METRIC_CONFIGS: PerformanceMetricConfig[] = [
  { label: "24H Change", key: "change24h", pointCount: 24, stepMs: HOUR_MS },
  { label: "7D ROI", key: "roi7d", pointCount: 7, stepMs: 24 * HOUR_MS },
  { label: "1M ROI", key: "roi1m", pointCount: 30, stepMs: HOUR_MS },
  { label: "3M ROI", key: "roi3m", pointCount: 12, stepMs: 7 * 24 * HOUR_MS },
  { label: "1Y ROI", key: "roi1y", pointCount: 12, stepMs: 30 * 24 * HOUR_MS },
  { label: "YTD", key: "roiYtd", pointCount: 12, stepMs: 30 * 24 * HOUR_MS },
  {
    label: "1Y ROI vs. BTC",
    key: "roi1yVsBtc",
    pointCount: 12,
    stepMs: 30 * 24 * HOUR_MS,
  },
];

export function buildIndexPerformanceMetricDefinitions(
  metrics: IndexPerformanceMetrics,
  sparkline: number[],
): CompactMetricDefinition[] {
  return PERFORMANCE_METRIC_CONFIGS.map(({ label, key, pointCount, stepMs }) => {
    const value = metrics[key];

    return {
      id: key,
      label,
      value: formatPercent(value),
      valueTone: "signed" as const,
      chart: {
        kind: "line" as const,
        data: buildSignedPercentLineData(
          sparkline,
          value,
          pointCount,
          stepMs,
        ),
      },
    };
  });
}

export { PERFORMANCE_METRIC_CONFIGS };
