import type { CrossChainTransferRecord } from "../types/crossChainFlow";

const STORAGE_KEY = "morpheum_cross_chain_transfers";

function readStore(): CrossChainTransferRecord[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as CrossChainTransferRecord[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeStore(records: CrossChainTransferRecord[]): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records.slice(0, 10)));
  } catch {
    // ignore storage errors
  }
}

export function getActiveCrossChainTransfer(): CrossChainTransferRecord | null {
  const records = readStore();
  return (
    records.find(
      (r) => r.currentStage !== "complete" && !r.completedAt,
    ) ?? null
  );
}

export function getCrossChainTransfers(): CrossChainTransferRecord[] {
  return readStore();
}

export function upsertCrossChainTransfer(
  record: CrossChainTransferRecord,
): void {
  const records = readStore().filter((r) => r.id !== record.id);
  writeStore([record, ...records]);
}

export function clearCrossChainTransfer(id: string): void {
  writeStore(readStore().filter((r) => r.id !== id));
}

export function generateTransferId(): string {
  return `xchain_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

export function generateDemoTxHash(prefix: string): string {
  const hex = Date.now().toString(16).padStart(8, "0");
  return `0x${prefix}${hex}${"a".repeat(24)}`.slice(0, 42);
}
