import React, { useState } from "react";
import Orderbook002 from "./Orderbook02";
import TradePrice from "../TradePrice";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import type { EnhancementConfig } from "../../utils/orderbookEnhancement";
import type { TradingMode } from "../../configs/tradeLayoutMode";
import { SubscriptionClient } from "../../sdk";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import {
  DEFAULT_HEIGHT_ORDERBOOK,
  DEFAULT_LIMIT,
  DEFAULT_MAX_DEPTH,
} from "../../constants";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./orderbookTradesPanel.css";

export type OrderbookTradesPanelTabId = "orderbook" | "trades";

export interface OrderbookTradesPanelProps {
  baseURL: string;
  /** Optional: when inside SubscriptionProvider, children use context. */
  subscriptionClient?: SubscriptionClient;
  marketId: string;
  maxDepth?: number;
  limit?: number;
  height?: string;
  onPriceClick?: (price: number) => void;
  enhancementConfig?: EnhancementConfig;
  /** When false, suppresses flash highlight on size changes. Defaults to true. */
  animationEnabled?: boolean;
  /** Optional controlled active tab; use with onTabChange for controlled mode. */
  activeTab?: OrderbookTradesPanelTabId;
  onTabChange?: (tabId: OrderbookTradesPanelTabId) => void;
  /** Agent layout mode — enables attribution styling when not proTerminal */
  tradingMode?: TradingMode;
}

const TABS = [
  { id: "orderbook", label: "Order Book" },
  { id: "trades", label: "Trades" },
] as const;

function layoutModeChipLabel(mode: TradingMode): string | null {
  if (mode === "highAgency") return "High-Agency";
  if (mode === "humanInLoop") return "Guarded";
  return null;
}

function layoutModeChipClass(mode: TradingMode): string {
  if (mode === "humanInLoop") {
    return "orderbook-trades-panel-mode-chip orderbook-trades-panel-mode-chip--risk";
  }
  return "orderbook-trades-panel-mode-chip orderbook-trades-panel-mode-chip--agent";
}

function OrderbookTradesPanel({
  baseURL,
  subscriptionClient,
  marketId,
  maxDepth = DEFAULT_MAX_DEPTH,
  limit = DEFAULT_LIMIT,
  height = DEFAULT_HEIGHT_ORDERBOOK,
  onPriceClick,
  enhancementConfig,
  animationEnabled = true,
  activeTab: controlledTab,
  onTabChange,
  tradingMode = "proTerminal",
}: OrderbookTradesPanelProps): JSX.Element {
  const [internalTab, setInternalTab] =
    useState<OrderbookTradesPanelTabId>("orderbook");
  const isControlled = controlledTab != null && onTabChange != null;
  const activeTab = isControlled ? controlledTab : internalTab;
  const setActiveTab = isControlled ? onTabChange : setInternalTab;
  const agentAugmented = tradingMode !== "proTerminal";
  const riskOverlay = tradingMode === "humanInLoop";
  const modeChipLabel = layoutModeChipLabel(tradingMode);

  return (
    <div
      className={`layout-container tab-section-root orderbook-trades-panel${agentAugmented ? " orderbook-trades-panel--agent" : ""}${riskOverlay ? " orderbook-trades-panel--risk" : ""}`}
      style={{ height, minHeight: 0 }}
      data-tour="welcome-orderbook"
    >
      <TabLayoutHeaderToolBar
        tabs={[...TABS]}
        activeTabId={activeTab}
        onTabChange={(id) => setActiveTab(id as OrderbookTradesPanelTabId)}
      >
        {modeChipLabel ? (
          <BubbleTip id={BUBBLE_TIP_IDS.orderbookLayoutMode}>
            <span className={layoutModeChipClass(tradingMode)}>
              {modeChipLabel}
            </span>
          </BubbleTip>
        ) : null}
      </TabLayoutHeaderToolBar>
      <div className="tab-section-content orderbook-trades-panel-content">
        {activeTab === "orderbook" ? (
          <Orderbook002
            key={`orderbook-${marketId}`}
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            marketId={marketId}
            maxDepth={maxDepth}
            height="100%"
            onPriceClick={onPriceClick}
            enhancementConfig={enhancementConfig}
            animationEnabled={animationEnabled}
          />
        ) : (
          <TradePrice
            key={`trades-${marketId}`}
            baseURL={baseURL}
            marketId={marketId}
            limit={limit}
            height="100%"
          />
        )}
      </div>
    </div>
  );
}

export default React.memo(OrderbookTradesPanel);
