import React from "react";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";

export interface RiskEnvelopeGaugeProps {
  deployedPct: number;
  dayPnlUsd: number;
  riskScore: number;
  riskCap?: number;
}

function formatDayPnl(usd: number): string {
  const sign = usd >= 0 ? "+" : "";
  return `${sign}$${Math.abs(usd).toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
}

function RiskEnvelopeGauge({
  deployedPct,
  dayPnlUsd,
  riskScore,
  riskCap = 1,
}: RiskEnvelopeGaugeProps): JSX.Element {
  const barPct = Math.min(100, Math.max(0, deployedPct));
  const pnlPositive = dayPnlUsd >= 0;

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.highARiskEnvelope}>
      <div className="high-a-risk-envelope">
        <span className="high-a-risk-deployed">
          Deployed {deployedPct}%
          <span
            className="high-a-risk-bar"
            role="progressbar"
            aria-valuenow={barPct}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label={`Deployed ${deployedPct}%`}
          >
            <span
              className="high-a-risk-bar-fill"
              style={{ width: `${barPct}%` }}
            />
          </span>
        </span>
        <span className="high-a-risk-sep" aria-hidden>
          ·
        </span>
        <span
          className={`high-a-risk-pnl${pnlPositive ? " positive" : " negative"}`}
        >
          Day {formatDayPnl(dayPnlUsd)}
        </span>
        <span className="high-a-risk-sep" aria-hidden>
          ·
        </span>
        <span className="high-a-risk-score">
          Risk {riskScore.toFixed(2)}/{riskCap.toFixed(1)}
        </span>
      </div>
    </BubbleTip>
  );
}

export default React.memo(RiskEnvelopeGauge);
