import React from "react";
import type { ReportTier } from "../../../store/types";
import { BubbleTip, BUBBLE_TIP_IDS, type BubbleTipId } from "../../../tutorials/bubble-tip";
import NeedsYouBadge from "./NeedsYouBadge";
import PauseAllButton from "./PauseAllButton";
import FeedHealthDot from "./FeedHealthDot";

export interface HighAControlRowProps {
  silentCount: number;
  watchingCount: number;
  needsYouCount: number;
  escalated: boolean;
  onFocusSpotlight?: () => void;
  onOpenTierAudit?: (tier: ReportTier) => void;
}

function TierCounter({
  label,
  count,
  tier,
  tipId,
  onOpenTierAudit,
}: {
  label: string;
  count: number;
  tier: ReportTier;
  tipId: BubbleTipId;
  onOpenTierAudit?: (tier: ReportTier) => void;
}) {
  const clickable = Boolean(onOpenTierAudit);
  const className = [
    "high-a-tier-counter",
    clickable ? "high-a-tier-counter--clickable" : "",
  ]
    .filter(Boolean)
    .join(" ");

  if (clickable) {
    return (
      <BubbleTip id={tipId}>
        <button
          type="button"
          className={className}
          onClick={() => onOpenTierAudit?.(tier)}
          aria-label={`${label} ${count}, open audit filtered by tier`}
        >
          {label} {count}
        </button>
      </BubbleTip>
    );
  }

  return (
    <BubbleTip id={tipId}>
      <span className={className}>
        {label} {count}
      </span>
    </BubbleTip>
  );
}

function HighAControlRow({
  silentCount,
  watchingCount,
  needsYouCount,
  escalated,
  onFocusSpotlight,
  onOpenTierAudit,
}: HighAControlRowProps): JSX.Element {
  return (
    <div className="high-a-control-row">
      <div className="high-a-tier-counters">
        <TierCounter
          label="Silent"
          count={silentCount}
          tier="T0"
          tipId={BUBBLE_TIP_IDS.highATierSilent}
          onOpenTierAudit={onOpenTierAudit}
        />
        <span className="high-a-tier-sep" aria-hidden>
          ·
        </span>
        <TierCounter
          label="Watching"
          count={watchingCount}
          tier="T1"
          tipId={BUBBLE_TIP_IDS.highATierWatching}
          onOpenTierAudit={onOpenTierAudit}
        />
        <span className="high-a-tier-sep" aria-hidden>
          ·
        </span>
        <NeedsYouBadge
          count={needsYouCount}
          escalated={escalated}
          onFocus={onFocusSpotlight}
        />
      </div>
      <div className="high-a-control-actions">
        <PauseAllButton />
        <FeedHealthDot />
      </div>
    </div>
  );
}

export default React.memo(HighAControlRow);
