export function catalogEntryToSkill(entry: CatalogSkillEntry): AgentSkill {
  return {
    id: `catalog:${entry.catalogId}`,
    catalogId: entry.catalogId,
    name: entry.name,
    description: entry.description,
    files: entry.files.map((file) => ({ ...file })),
    installedAt: new Date().toISOString(),
    source: "catalog",
  };
}

export function findCatalogSkill(catalogId: string): CatalogSkillEntry | undefined {
  return CATALOG_SKILLS.find((entry) => entry.catalogId === catalogId);
}
