/**
 * Top navigation menu bar for DEX layout.
 * Layout: logo (left) | 6 menu buttons (center, collapsible on mobile) | config + connect (right).
 * Height: 58px. Responsive: menu items collapse into hamburger layout on mobile (≤768px).
 */
import React, { useCallback, useState } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { BubbleTip, BUBBLE_TIP_IDS } from "../tutorials/bubble-tip";
import {
  dispatchPreNavigateCleanup,
  runAfterPreNavigateCleanup,
} from "../utils/preNavigateCleanup";
import { useKeyboardShortcut } from "../utils/keyboardShortcuts";
import "./MenuBar.css";
import WalletModal from "./wallet-modal";

export type MenuBarItemId = "trade" | "markets" | "portfolio" | "index" | "quorum" | "networkHealth";

export interface MenuBarProps {
  /** Brand name shown next to logo */
  brandName?: string;
  /** Menu items (label, optional href, optional hasDropdown, optional id) */
  menuItems?: Array<{ label: string; href?: string; hasDropdown?: boolean; id?: MenuBarItemId }>;
  /** Called when a menu item is selected (legacy — prefer deferMenuNavigation + onPreNavigateCleanup) */
  onMenuItemClick?: (item: { label: string; href?: string; hasDropdown?: boolean; id?: MenuBarItemId }) => void;
  /** When true, menu clicks defer navigation for chart teardown (trade / agent routes). */
  deferMenuNavigation?: boolean;
  /** Runs before route change (modal cleanup, etc.). */
  onPreNavigateCleanup?: () => void;
  /** Wallet address when connected; empty shows "Connect Wallet" */
  walletAddress?: string;
  /** Called when Connect/Connect Wallet button is clicked (when not connected) */
  onConnectClick?: () => void;
  /** Display name for the connected RPC network chain (e.g. "Morpheum Mainnet") */
  networkChainName?: string;
  /** Called when Bucket Transfer is clicked in the wallet modal */
  onBucketTransfer?: () => void;
  /** Called when Coin Transfer is clicked in the wallet modal */
  onCoinTransfer?: () => void;
  /** Called when Deposit is clicked in the wallet modal */
  onDeposit?: () => void;
  /** Called when Withdraw is clicked in the wallet modal */
  onWithdraw?: () => void;
  /** Called when Disconnect is clicked in the wallet modal */
  onDisconnect?: () => void;
  /** Called when settings gear is clicked */
  onSettingsClick?: () => void;
  /** JELLY-MODE active — show in-session exit controls */
  jellyModeActive?: boolean;
  jellyReplayActive?: boolean;
  /** Exit JELLY mode (only shown while jelly is active) */
  onJellyModeToggle?: () => void;
  /** Reopen JELLY intro slides while mode is active */
  onJellyIntroClick?: () => void;
  /** Open demo welcome hub */
  onWelcomeTourClick?: () => void;
  /** Show demo guide ? button */
  showWelcomeTourHelp?: boolean;
  /** Optional block/status indicator text (e.g. "Block 176475481") */
  statusText?: string;
  /** Optional network/language dropdown click */
  onNetworkClick?: () => void;
  /** Custom logo element; defaults to Morpheum-style placeholder */
  logo?: React.ReactNode;
}

const DEFAULT_LOGO_SRC = "/morhpeum-2.svg";

const DEFAULT_MENU_ITEMS: Array<{ label: string; href?: string; hasDropdown?: boolean; id?: MenuBarItemId }> = [
  { label: "Markets", href: "/markets", id: "markets" },
  { label: "Trade", href: "/trade", id: "trade" },
  { label: "Index", href: "/cindex", id: "index" },
  { label: "Portfolio", href: "/portfolio", id: "portfolio" },
 /**
  { label: "Quorum Proof", href: "/explainations/quorum-intersection", id: "quorum" },
  { label: "Network Health", href: "/explainations/networkhealth", id: "networkHealth" },
   **/
];

function truncateAddress(addr: string, chars = 6): string {
  if (addr.length <= chars * 2) return addr;
  return `${addr.slice(0, chars)}...${addr.slice(-chars)}`;
}

function isEditableTarget(target: EventTarget | null): boolean {
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement ||
    (target instanceof HTMLElement && target.isContentEditable)
  );
}

function MenuBar({
  brandName = "Morpheum",
  menuItems = DEFAULT_MENU_ITEMS,
  walletAddress = "",
  onConnectClick,
  networkChainName = "Morpheum Network",
  onBucketTransfer,
  onCoinTransfer,
  onDeposit,
  onWithdraw,
  onDisconnect,
  onSettingsClick,
  onMenuItemClick,
  deferMenuNavigation = false,
  onPreNavigateCleanup = dispatchPreNavigateCleanup,
  jellyModeActive = false,
  jellyReplayActive = false,
  onJellyModeToggle,
  onJellyIntroClick,
  onWelcomeTourClick,
  showWelcomeTourHelp = false,
  statusText,
  onNetworkClick,
  logo,
}: MenuBarProps): React.JSX.Element {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [walletModalOpen, setWalletModalOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const isConnected = Boolean(walletAddress?.trim());
  const showDemoGuide = showWelcomeTourHelp && Boolean(onWelcomeTourClick);

  const handleWalletShortcut = useCallback(() => {
    if (isConnected) {
      setWalletModalOpen((open) => !open);
    } else {
      onConnectClick?.();
    }
  }, [isConnected, onConnectClick]);

  useKeyboardShortcut("openWalletMenu", handleWalletShortcut, {
    suppressWhen: (event) => isEditableTarget(event.target),
  });

  return (
    <header className="menubar" role="banner" data-tour="welcome-header">
      <div className="menubar-inner">
        {/* Left: Hamburger (mobile) + Logo + Brand */}
        <div className="menubar-left">
          <button
            type="button"
            className="menubar-hamburger"
            aria-expanded={mobileMenuOpen}
            aria-controls="menubar-menu"
            aria-label="Open menu"
            onClick={() => setMobileMenuOpen((o) => !o)}
          >
            <span />
            <span />
            <span />
          </button>
          <button
            type="button"
            className="menubar-logo-link"
            aria-label={`${brandName} home`}
            onClick={() => navigate("/")}
          >
            {logo ?? (
              <img
                src={DEFAULT_LOGO_SRC}
                alt=""
                className="menubar-logo-img"
                aria-hidden
              />
            )}
            <span className="menubar-brand">{brandName}</span>
          </button>
        </div>

        {/* Center: Menu buttons (desktop) */}
        <nav className="menubar-nav" aria-label="Main navigation">
          <ul
            id="menubar-menu"
            className={`menubar-menu ${mobileMenuOpen ? "menubar-menu-open" : ""}`}
          >
            {menuItems.map((item) => (
              <li key={item.label}>
                <Link
                  to={item.href ?? "#"}
                  className={`menubar-menu-item terminal-nav-link${
                    item.href && location.pathname.startsWith(item.href)
                      ? " menubar-menu-item--active terminal-nav-link-active"
                      : ""
                  }`}
                  onClick={(e) => {
                    setMobileMenuOpen(false);

                    if (onMenuItemClick) {
                      e.preventDefault();
                      onPreNavigateCleanup();
                      onMenuItemClick(item);
                      return;
                    }

                    if (deferMenuNavigation && item.href && item.href !== "#") {
                      e.preventDefault();
                      onPreNavigateCleanup();
                      runAfterPreNavigateCleanup(() => navigate(item.href!));
                      return;
                    }

                    // Lightweight routes: native Link navigation. History patch notifies shell.
                  }}
                >
                  {item.label}
                  {item.hasDropdown && (
                    <svg className="menubar-chevron" width="10" height="6" viewBox="0 0 10 6" fill="none" aria-hidden>
                      <path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                  )}
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        {/* Right: Status, network, settings, connect */}
        <div className="menubar-right">
          {statusText && (
            <BubbleTip id={BUBBLE_TIP_IDS.networkStatus}>
              <div className="menubar-status">
                <span className="menubar-status-dot" />
                <span className="menubar-status-text">{statusText}</span>
              </div>
            </BubbleTip>
          )}
          {onNetworkClick && (
            <button
              type="button"
              className="menubar-icon-btn"
              onClick={onNetworkClick}
              aria-label="Network or language"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="10" />
                <path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
              </svg>
              <svg className="menubar-chevron" width="10" height="6" viewBox="0 0 10 6" fill="none">
                <path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          )}
          {showDemoGuide ? (
            <BubbleTip id={BUBBLE_TIP_IDS.productTourHelp}>
              <button
                type="button"
                className="menubar-welcome-help-btn"
                onClick={onWelcomeTourClick}
                aria-label="Open demo guide"
                title="Demo welcome and guided tour"
              >
                ?
              </button>
            </BubbleTip>
          ) : null}
          {jellyModeActive && onJellyModeToggle ? (
            <>
              <button
                type="button"
                className={`menubar-jelly-btn active${jellyReplayActive ? " menubar-jelly-btn--replaying" : ""}`}
                onClick={onJellyModeToggle}
                aria-label="Exit JELLY mode"
                aria-pressed
                title="Exit JELLY incident replay"
              >
                JELLY MODE
              </button>
              {onJellyIntroClick ? (
                <button
                  type="button"
                  className="menubar-jelly-help-btn"
                  onClick={onJellyIntroClick}
                  aria-label="JELLY intro"
                  title="JELLY incident intro"
                >
                  ?
                </button>
              ) : null}
            </>
          ) : null}
          <button
            type="button"
            className="menubar-icon-btn"
            onClick={onSettingsClick}
            aria-label="Settings"
          >
            <svg className="menubar-settings-icon" fill="currentColor" viewBox="0 0 1920 1920" xmlns="http://www.w3.org/2000/svg" aria-hidden>
              <path d="m1739.34 1293.414-105.827 180.818-240.225-80.188-24.509 22.25c-69.91 63.586-150.211 109.666-238.644 136.771l-32.076 9.94-49.468 244.065H835.584l-49.468-244.179-32.076-9.939c-88.432-27.105-168.734-73.185-238.644-136.771l-24.508-22.25-240.226 80.189-105.826-180.82 189.74-164.442-7.453-32.978c-10.39-45.742-15.586-91.483-15.586-135.869 0-44.386 5.195-90.127 15.586-135.868l7.454-32.979-189.741-164.442 105.826-180.819 240.226 80.075 24.508-22.25c69.91-63.585 150.212-109.665 238.644-136.884l32.076-9.826 49.468-244.066h213.007l49.468 244.18 32.076 9.825c88.433 27.219 168.734 73.186 238.644 136.885l24.509 22.25 240.225-80.189 105.826 180.819-189.74 164.442 7.453 32.98c10.39 45.74 15.586 91.481 15.586 135.867 0 44.386-5.195 90.127-15.586 135.869l-7.454 32.978 189.741 164.556Zm-53.76-333.403c0-41.788-3.84-84.48-11.634-127.284l210.184-182.062-199.454-340.856-265.186 88.433c-66.974-55.567-143.322-99.388-223.85-128.414L1140.977.01H743.198l-54.663 269.704c-81.431 29.139-156.424 72.282-223.963 128.414L199.5 309.809.045 650.665l210.07 182.062c-7.68 42.804-11.52 85.496-11.52 127.284 0 41.789 3.84 84.48 11.52 127.172L.046 1269.357 199.5 1610.214l265.186-88.546c66.974 55.68 143.323 99.388 223.85 128.527l54.663 269.816h397.779l54.663-269.703c81.318-29.252 156.424-72.283 223.85-128.527l265.186 88.546 199.454-340.857-210.184-182.174c7.793-42.805 11.633-85.496 11.633-127.285ZM942.075 564.706C724.1 564.706 546.782 742.024 546.782 960c0 217.976 177.318 395.294 395.294 395.294 217.977 0 395.294-177.318 395.294-395.294 0-217.976-177.317-395.294-395.294-395.294m0 677.647c-155.633 0-282.353-126.72-282.353-282.353s126.72-282.353 282.353-282.353S1224.43 804.367 1224.43 960s-126.72 282.353-282.353 282.353" fillRule="evenodd" />
            </svg>
          </button>
          <button
            type="button"
            className="menubar-connect-btn"
            onClick={handleWalletShortcut}
            {...(isConnected ? { "data-tour": "deposit-tour-wallet-btn" } : {})}
          >
            {isConnected ? truncateAddress(walletAddress) : "Connect Wallet"}
          </button>
        </div>
      </div>
      <WalletModal
        isOpen={walletModalOpen}
        onClose={() => setWalletModalOpen(false)}
        networkChainName={networkChainName}
        walletAddress={walletAddress}
        onBucketTransfer={() => {
          setWalletModalOpen(false);
          onBucketTransfer?.();
        }}
        onCoinTransfer={() => {
          setWalletModalOpen(false);
          onCoinTransfer?.();
        }}
        onDeposit={() => {
          setWalletModalOpen(false);
          onDeposit?.();
        }}
        onWithdraw={() => {
          setWalletModalOpen(false);
          onWithdraw?.();
        }}
        onDisconnect={onDisconnect}
      />
    </header>
  );
}

export default MenuBar;
