import React from "react";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { formatPortfolioCurrency } from "./portfolioFormat";
import "./portfolio.css";

export interface PortfolioVolumePanelProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  focusAgentId?: string | null;
  refreshInterval?: number;
}

function PortfolioVolumePanel({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  focusAgentId = null,
  refreshInterval,
}: PortfolioVolumePanelProps): JSX.Element {
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    focusAgentId,
    refreshInterval,
  });

  const isFocused = focusAgentId != null && analytics.focusVolume14d != null;
  const focusVol = analytics.focusVolume14d;

  const volTotal = isFocused
    ? focusVol!.focus + focusVol!.otherAgents
    : analytics.volume14d.agent + analytics.volume14d.manual;

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section
        className={`portfolio-volume-panel${isFocused ? " portfolio-volume-panel--focused" : ""}`}
        aria-label="14 day volume"
      >
        <span className="portfolio-volume-fees-label">
          {isFocused ? "14 Day Volume · Agent vs Fleet" : "14 Day Volume"}
        </span>
        <strong className="portfolio-volume-fees-value">
          {formatPortfolioCurrency(volTotal)}
        </strong>
        <div className="portfolio-vol-bars portfolio-volume-fees-bars">
          {isFocused ? (
            <>
              <div className="portfolio-vol-bar-row">
                <span>This agent</span>
                <div className="portfolio-vol-bar-track">
                  <div
                    className="portfolio-vol-bar-fill portfolio-vol-bar-fill--agent"
                    style={{
                      width: `${volTotal > 0 ? (focusVol!.focus / volTotal) * 100 : 0}%`,
                    }}
                  />
                </div>
                <span>{formatPortfolioCurrency(focusVol!.focus)}</span>
              </div>
              <div className="portfolio-vol-bar-row">
                <span>Other agents</span>
                <div className="portfolio-vol-bar-track">
                  <div
                    className="portfolio-vol-bar-fill portfolio-vol-bar-fill--manual"
                    style={{
                      width: `${volTotal > 0 ? (focusVol!.otherAgents / volTotal) * 100 : 0}%`,
                    }}
                  />
                </div>
                <span>{formatPortfolioCurrency(focusVol!.otherAgents)}</span>
              </div>
            </>
          ) : (
            <>
              <div className="portfolio-vol-bar-row">
                <span>Agents</span>
                <div className="portfolio-vol-bar-track">
                  <div
                    className="portfolio-vol-bar-fill portfolio-vol-bar-fill--agent"
                    style={{
                      width: `${volTotal > 0 ? (analytics.volume14d.agent / volTotal) * 100 : 0}%`,
                    }}
                  />
                </div>
                <span>{formatPortfolioCurrency(analytics.volume14d.agent)}</span>
              </div>
              <div className="portfolio-vol-bar-row">
                <span>Manual</span>
                <div className="portfolio-vol-bar-track">
                  <div
                    className="portfolio-vol-bar-fill portfolio-vol-bar-fill--manual"
                    style={{
                      width: `${volTotal > 0 ? (analytics.volume14d.manual / volTotal) * 100 : 0}%`,
                    }}
                  />
                </div>
                <span>{formatPortfolioCurrency(analytics.volume14d.manual)}</span>
              </div>
            </>
          )}
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioVolumePanel);
