import { useCallback, useEffect, useState } from "react";

import {
  catalogEntryToSkill,
  findCatalogSkill,
} from "../components/agent/agentSettingsCatalog";
import {
  isCatalogSkillInstalled,
  loadAgentSettings,
  saveAgentSettings,
} from "../components/agent/agentSettingsStorage";
import type {
  AgentEnvVar,
  AgentSettingsState,
  AgentSkill,
  EnvVarScope,
  McpServer,
  SkillFile,
} from "../components/agent/agentSettingsTypes";
import { buildCustomSkillFromFiles } from "../components/agent/agentSettingsValidation";

function createId(prefix: string): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return `${prefix}:${crypto.randomUUID()}`;
  }
  return `${prefix}:${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export interface UseAgentSettingsResult {
  settings: AgentSettingsState;
  installCatalogSkill: (catalogId: string) => boolean;
  createCustomSkill: (files: SkillFile[]) => boolean;
  removeSkill: (skillId: string) => void;
  upsertEnvVar: (
    scope: EnvVarScope,
    key: string,
    value: string,
    existingId?: string,
  ) => boolean;
  removeEnvVar: (envVarId: string) => void;
  addMcpServer: (
    input: Omit<McpServer, "id" | "createdAt">,
  ) => boolean;
  removeMcpServer: (serverId: string) => void;
}

export function useAgentSettings(catalogAgentId: string): UseAgentSettingsResult {
  const [settings, setSettings] = useState<AgentSettingsState>(() =>
    loadAgentSettings(catalogAgentId),
  );

  useEffect(() => {
    setSettings(loadAgentSettings(catalogAgentId));
  }, [catalogAgentId]);

  const persist = useCallback(
    (next: AgentSettingsState) => {
      setSettings(next);
      saveAgentSettings(catalogAgentId, next);
    },
    [catalogAgentId],
  );

  const installCatalogSkill = useCallback(
    (catalogId: string): boolean => {
      const entry = findCatalogSkill(catalogId);
      if (!entry) return false;
      if (isCatalogSkillInstalled(settings, catalogId)) return false;
      const next: AgentSettingsState = {
        ...settings,
        skills: [...settings.skills, catalogEntryToSkill(entry)],
      };
      persist(next);
      return true;
    },
    [persist, settings],
  );

  const createCustomSkill = useCallback(
    (files: SkillFile[]): boolean => {
      const draft = buildCustomSkillFromFiles(files);
      if (!draft) return false;
      const skill: AgentSkill = {
        ...draft,
        id: createId("skill"),
        installedAt: new Date().toISOString(),
      };
      persist({
        ...settings,
        skills: [...settings.skills, skill],
      });
      return true;
    },
    [persist, settings],
  );

  const removeSkill = useCallback(
    (skillId: string) => {
      persist({
        ...settings,
        skills: settings.skills.filter((skill) => skill.id !== skillId),
      });
    },
    [persist, settings],
  );

  const upsertEnvVar = useCallback(
    (
      scope: EnvVarScope,
      key: string,
      value: string,
      existingId?: string,
    ): boolean => {
      const trimmedKey = key.trim();
      if (!trimmedKey) return false;

      const duplicate = settings.envVars.find(
        (envVar) =>
          envVar.scope === scope &&
          envVar.key.toLowerCase() === trimmedKey.toLowerCase() &&
          envVar.id !== existingId,
      );
      if (duplicate) return false;

      if (existingId) {
        persist({
          ...settings,
          envVars: settings.envVars.map((envVar) =>
            envVar.id === existingId
              ? { ...envVar, key: trimmedKey, value, scope }
              : envVar,
          ),
        });
        return true;
      }

      const envVar: AgentEnvVar = {
        id: createId("env"),
        key: trimmedKey,
        value,
        scope,
      };
      persist({
        ...settings,
        envVars: [...settings.envVars, envVar],
      });
      return true;
    },
    [persist, settings],
  );

  const removeEnvVar = useCallback(
    (envVarId: string) => {
      persist({
        ...settings,
        envVars: settings.envVars.filter((envVar) => envVar.id !== envVarId),
      });
    },
    [persist, settings],
  );

  const addMcpServer = useCallback(
    (input: Omit<McpServer, "id" | "createdAt">): boolean => {
      const name = input.name.trim();
      const url = input.url.trim();
      if (!name || !url) return false;
      const server: McpServer = {
        ...input,
        id: createId("mcp"),
        name,
        url,
        headers: input.headers.filter((header) => header.name.trim()),
        createdAt: new Date().toISOString(),
      };
      persist({
        ...settings,
        mcpServers: [...settings.mcpServers, server],
      });
      return true;
    },
    [persist, settings],
  );

  const removeMcpServer = useCallback(
    (serverId: string) => {
      persist({
        ...settings,
        mcpServers: settings.mcpServers.filter((server) => server.id !== serverId),
      });
    },
    [persist, settings],
  );

  return {
    settings,
    installCatalogSkill,
    createCustomSkill,
    removeSkill,
    upsertEnvVar,
    removeEnvVar,
    addMcpServer,
    removeMcpServer,
  };
}
