import type { IChartApi, ISeriesApi } from "lightweight-charts";
import {
  EXECUTION_MARKER_FILL_SIZE,
  type ChartExecutionMarker,
} from "./chartMarkers";
import { clampMarkerBarSpacing, executionMarkerShapeMargin } from "./executionMarkerSizing";
import { resolveBarAtMarkerTime } from "./resolveBarAtMarkerTime";

export interface MarkerAnchorPoint {
  x: number;
  y: number;
}

export function isResolvedMarkerAnchor(
  point: { x?: number; y?: number } | null | undefined,
): point is MarkerAnchorPoint {
  return (
    point != null &&
    typeof point.x === "number" &&
    typeof point.y === "number" &&
    Number.isFinite(point.x) &&
    Number.isFinite(point.y)
  );
}

function ceiledEven(value: number): number {
  const rounded = Math.round(value);
  return rounded % 2 !== 0 ? rounded + 1 : rounded;
}

/** Matches lightweight-charts marker shape height for bar-positioned markers. */
export function calculateMarkerShapeHeight(barSpacing: number, markerSize = 1): number {
  return ceiledEven(clampMarkerBarSpacing(barSpacing)) * markerSize;
}

export function findExecutionMarker(
  markers: ChartExecutionMarker[],
  tradeId: string,
): ChartExecutionMarker | undefined {
  return markers.find((marker) => marker.tradeId === tradeId);
}

/** @deprecated Use findExecutionMarker */
export const findSeriesMarker = findExecutionMarker;

/**
 * Resolve the canvas center of an execution marker (matches library aboveBar/belowBar placement).
 */
export function resolveMarkerAnchorPoint(
  chart: IChartApi,
  series: ISeriesApi<"Candlestick">,
  marker: ChartExecutionMarker,
  barSpacing: number,
): MarkerAnchorPoint | null {
  const timeScale = chart.timeScale();
  const bar = resolveBarAtMarkerTime(chart, series, marker.time);
  if (!bar) return null;

  const x =
    timeScale.timeToCoordinate(bar.time) ?? timeScale.timeToCoordinate(marker.time);
  if (x === null) return null;

  const invertScale = series.priceScale().options().invertScale;
  const position = marker.position;
  let price: number;

  if (position === "aboveBar") {
    price = invertScale ? bar.low : bar.high;
  } else if (position === "belowBar") {
    price = invertScale ? bar.high : bar.low;
  } else {
    return null;
  }

  let y = series.priceToCoordinate(price);
  if (y === null) return null;

  const shapeHeight = calculateMarkerShapeHeight(barSpacing, EXECUTION_MARKER_FILL_SIZE);
  const halfSize = shapeHeight / 2;
  const margin = executionMarkerShapeMargin(barSpacing);

  if (position === "aboveBar") {
    y -= halfSize + margin;
  } else if (position === "belowBar") {
    y += halfSize + margin;
  }

  return { x, y };
}
