export type AddressFormat = "evm" | "solana" | "bitcoin" | "unknown";

const EVM_CHAINS = new Set(["ethereum", "arbitrum", "base", "bsc"]);

export function getAddressFormatForChain(chain: string): AddressFormat {
  const normalized = chain.trim().toLowerCase();
  if (EVM_CHAINS.has(normalized)) return "evm";
  if (normalized === "solana") return "solana";
  if (normalized === "bitcoin") return "bitcoin";
  return "unknown";
}

function isValidEvmAddress(addr: string): boolean {
  const trimmed = addr.trim();
  return trimmed.length === 42 && /^0x[a-fA-F0-9]{40}$/.test(trimmed);
}

function isValidSolanaAddress(addr: string): boolean {
  const trimmed = addr.trim();
  if (trimmed.length < 32 || trimmed.length > 44) return false;
  return /^[1-9A-HJ-NP-Za-km-z]+$/.test(trimmed);
}

function isValidBitcoinAddress(addr: string): boolean {
  const trimmed = addr.trim();
  if (/^bc1[a-z0-9]{25,87}$/i.test(trimmed)) return true;
  if (/^[13][a-km-zA-HJ-NP-Z1-9]{25,34}$/.test(trimmed)) return true;
  return false;
}

export function validateWithdrawAddress(
  chain: string,
  addr: string,
): { valid: boolean; format: AddressFormat; hint?: string } {
  const format = getAddressFormatForChain(chain);
  const trimmed = addr?.trim() ?? "";

  if (!trimmed) {
    return { valid: false, format, hint: "Address is required" };
  }

  switch (format) {
    case "evm":
      return isValidEvmAddress(trimmed)
        ? { valid: true, format }
        : {
            valid: false,
            format,
            hint: "Enter a valid 0x address (42 characters)",
          };
    case "solana":
      return isValidSolanaAddress(trimmed)
        ? { valid: true, format }
        : {
            valid: false,
            format,
            hint: "Enter a valid Solana base58 address",
          };
    case "bitcoin":
      return isValidBitcoinAddress(trimmed)
        ? { valid: true, format }
        : {
            valid: false,
            format,
            hint: "Enter a valid Bitcoin address (bech32 or legacy)",
          };
    default:
      return { valid: false, format, hint: "Unsupported chain for validation" };
  }
}

export function getAddressPlaceholder(chain: string): string {
  const format = getAddressFormatForChain(chain);
  switch (format) {
    case "evm":
      return "0x...";
    case "solana":
      return "Solana address...";
    case "bitcoin":
      return "bc1... or 1/3...";
    default:
      return "Address...";
  }
}

const SEEN_ADDRESSES_KEY = "morpheum_cross_chain_seen_addresses";

export function isKnownWithdrawAddress(chain: string, addr: string): boolean {
  if (typeof localStorage === "undefined") return false;
  try {
    const raw = localStorage.getItem(SEEN_ADDRESSES_KEY);
    if (!raw) return false;
    const map = JSON.parse(raw) as Record<string, string[]>;
    const key = chain.trim().toLowerCase();
    const normalized = addr.trim().toLowerCase();
    return (map[key] ?? []).some((a) => a.toLowerCase() === normalized);
  } catch {
    return false;
  }
}

export function markWithdrawAddressSeen(chain: string, addr: string): void {
  if (typeof localStorage === "undefined") return;
  try {
    const raw = localStorage.getItem(SEEN_ADDRESSES_KEY);
    const map: Record<string, string[]> = raw ? JSON.parse(raw) : {};
    const key = chain.trim().toLowerCase();
    const normalized = addr.trim();
    const list = map[key] ?? [];
    if (!list.some((a) => a.toLowerCase() === normalized.toLowerCase())) {
      map[key] = [...list, normalized];
      localStorage.setItem(SEEN_ADDRESSES_KEY, JSON.stringify(map));
    }
  } catch {
    // ignore storage errors
  }
}
