import React, { useMemo } from "react";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import type { TierCounts } from "./reportTier";

export interface SwarmPulseProps {
  height?: string;
  silentCount: number;
  watchingCount: number;
  liveExecutingCount: number;
  tierCounts: TierCounts;
  activeAgentCount: number;
}

function SwarmPulse({
  height,
  silentCount,
  watchingCount,
  liveExecutingCount,
  tierCounts,
  activeAgentCount,
}: SwarmPulseProps): JSX.Element {
  const { agents } = useTradingAgents();

  const topPerformer = useMemo(() => {
    if (agents.length === 0) return null;
    return [...agents].sort(
      (a, b) => (b.revenue30d ?? 0) - (a.revenue30d ?? 0),
    )[0];
  }, [agents]);

  const ambient = tierCounts.T1;

  return (
    <div
      className="swarm-pulse trade-agent-deck"
      style={{ height, minHeight: 0 }}
      data-tour="welcome-agent-deck"
    >
      <div className="trade-agent-deck-head">
        <h2 className="trade-agent-deck-title">Swarm Pulse</h2>
        <p className="trade-agent-deck-sub">
          {activeAgentCount} active agent{activeAgentCount === 1 ? "" : "s"} · calm
        </p>
      </div>
      <div className="swarm-pulse-body trade-agent-deck-body">
        <div className="swarm-pulse-heartbeat" aria-hidden>
          <span className="swarm-pulse-heartbeat-line" />
          <span className="swarm-pulse-heartbeat-dot" />
        </div>
        <div className="swarm-pulse-metrics">
          <div className="swarm-pulse-metric">
            <span className="swarm-pulse-metric-label">Silent</span>
            <span className="swarm-pulse-metric-value">{silentCount}</span>
          </div>
          <div className="swarm-pulse-metric">
            <span className="swarm-pulse-metric-label">Watching</span>
            <span className="swarm-pulse-metric-value">{watchingCount}</span>
          </div>
          <div className="swarm-pulse-metric">
            <span className="swarm-pulse-metric-label">Live</span>
            <span className="swarm-pulse-metric-value">{liveExecutingCount}</span>
          </div>
          <div className="swarm-pulse-metric">
            <span className="swarm-pulse-metric-label">Ambient</span>
            <span className="swarm-pulse-metric-value">{ambient}</span>
          </div>
        </div>
        {topPerformer ? (
          <p className="swarm-pulse-note">
            Top performer: <strong>{topPerformer.displayName}</strong>
            {topPerformer.revenue30d != null
              ? ` · ${Math.round(topPerformer.revenue30d / 1000)}k / 30d`
              : ""}
          </p>
        ) : null}
        <p className="swarm-pulse-calm trade-agent-reasoning-item">
          Swarm running within policy. Exceptions surface automatically.
        </p>
      </div>
    </div>
  );
}

export default React.memo(SwarmPulse);
