import React, { useEffect, useMemo, useState } from "react";
import { usePendingOrders } from "../../hooks/usePendingOrders";
import { SubscriptionClient } from "../../sdk";
import { useSubscription } from "../../context/SubscriptionContext";
import { PendingOrder as PendingOrderData } from "../../sdk/types/data";
import { useMarkets } from "../../hooks/useMarkets";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_PENDING_ORDERS,
  DEFAULT_REFRESH_INTERVAL,
} from "../../constants";
import { shortHashId } from "../../utils/hashId";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import {
  buildTaskAgentMap,
  rowMatchesFleetFilter,
} from "../../utils/agentFilter";
import "../smartlayout/layout.css";
import "./agentTasks.css";

type SortField = "time" | "token" | "side" | "positionSize" | "payout" | "rate";
type SortDirection = "asc" | "desc";

interface FundingHistoryProps {
  baseURL: string;
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress: string;
  height?: string;
  refreshInterval?: number;
  hide_header?: boolean;
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  filterAgentIds?: string[];
}

const GRID_TEMPLATE_COLUMNS = "1.2fr 5rem 0.9fr 0.8fr 1fr 1fr 5rem";

function formatDateTime(value?: string | number | Date | null): string {
  if (value == null || value === "") return "—";
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, { dateStyle: "short", timeStyle: "short" }).format(date);
}

function formatNumber(value: number | string | undefined | null): string {
  const n = Number(value);
  if (value == null || Number.isNaN(n)) return "—";
  return new Intl.NumberFormat(undefined, { maximumFractionDigits: 8 }).format(n);
}

function getFundingField(order: PendingOrderData, keys: string[]): unknown {
  const raw = order.raw as Record<string, unknown> | undefined;
  for (const key of keys) {
    const value = raw?.[key];
    if (value != null && value !== "") return value;
  }
  return undefined;
}

function getFundingTime(order: PendingOrderData): string | number | Date | null | undefined {
  const raw = order.raw as Record<string, unknown> | undefined;
  return (
    (raw?.time as string | number | Date | undefined) ??
    (raw?.timestamp as string | number | Date | undefined) ??
    (raw?.createdAt as string | number | Date | undefined) ??
    (order as PendingOrderData & { createdAt?: string | number | Date }).createdAt ??
    (order as PendingOrderData & { timestamp?: string | number | Date }).timestamp
  );
}

function getSortValue(order: PendingOrderData, field: SortField): string | number {
  const symbol = String(getFundingField(order, ["symbol", "token", "marketSymbol"]) ?? `m-${order.marketId}`);
  const side = String(getFundingField(order, ["side"]) ?? order.side ?? "");
  const positionSize = Number(getFundingField(order, ["positionSize", "size", "quantity"]) ?? order.quantity ?? 0);
  const payout = Number(getFundingField(order, ["payout", "fundingPayment", "fundingFee"]) ?? 0);
  const rate = Number(getFundingField(order, ["rate", "fundingRate"]) ?? 0);
  const time = new Date(getFundingTime(order) ?? 0).getTime();

  switch (field) {
    case "time":
      return Number.isNaN(time) ? 0 : time;
    case "token":
      return symbol;
    case "side":
      return side;
    case "positionSize":
      return positionSize;
    case "payout":
      return payout;
    case "rate":
      return rate;
  }
}

function FundingHistory({
  baseURL = DEFAULT_BASE_URL,
  subscriptionClient: subscriptionClientProp,
  authToken,
  walletAddress,
  height = DEFAULT_HEIGHT_PENDING_ORDERS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  hide_header = false,
  onRequestHeaderActions,
  filterAgentIds = [],
}: FundingHistoryProps): JSX.Element {
  const { client: contextClient } = useSubscription();
  const subscriptionClient = subscriptionClientProp ?? contextClient;
  const { orders, loading, error } = usePendingOrders({
    ...(subscriptionClient != null && { subscriptionClient }),
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });
  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });
  const { tasks } = useAgentTasks();
  const taskAgentMap = useMemo(() => buildTaskAgentMap(tasks), [tasks]);

  const [sortField, setSortField] = useState<SortField | null>("time");
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");

  const fundingHistory = useMemo(() => {
    return orders
      .filter((order) => {
        const raw = order.raw as Record<string, unknown> | undefined;
        return Boolean(
          raw?.payout != null ||
            raw?.fundingPayment != null ||
            raw?.fundingFee != null ||
            raw?.fundingRate != null ||
            raw?.rate != null,
        );
      })
      .filter((order) =>
        rowMatchesFleetFilter(order.agentTaskId, filterAgentIds, taskAgentMap),
      );
  }, [orders, filterAgentIds, taskAgentMap]);

  const sortedHistory = useMemo(() => {
    if (!sortField) return fundingHistory;
    return [...fundingHistory].sort((a, b) => {
      const aValue = getSortValue(a, sortField);
      const bValue = getSortValue(b, sortField);

      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === "asc" ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
      }

      return sortDirection === "asc" ? Number(aValue) - Number(bValue) : Number(bValue) - Number(aValue);
    });
  }, [fundingHistory, sortField, sortDirection]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("desc");
    }
  };

  const headerActions = useMemo(() => null, []);

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, error, headerActions]);

  if (loading) return <MorpheumInlineLoading message="Loading funding history..." />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <div className="layout-container" style={{ height, ...(hide_header ? { borderRadius: 0, background: "transparent" } : {}) }}>
      {!hide_header && <LayoutHeader title="FUNDING HISTORY">{headerActions}</LayoutHeader>}
      <div className="table-container shrinkable">
        <div className="table-header" style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}>
          <TableHeaderCell field="time" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} left>Time</TableHeaderCell>
          <TableHeaderCellStatic center>Agent</TableHeaderCellStatic>
          <TableHeaderCell field="token" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} left>Token</TableHeaderCell>
          <TableHeaderCell field="side" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} left>Side</TableHeaderCell>
          <TableHeaderCell field="positionSize" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} left>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.positionSize} />
          </TableHeaderCell>
          <TableHeaderCell field="payout" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} left>Payout</TableHeaderCell>
          <TableHeaderCell field="rate" currentSortField={sortField} sortDirection={sortDirection} onSort={handleSort} right>Rate</TableHeaderCell>
        </div>

        {sortedHistory.length === 0 ? (
          <EmptyMessage message="No funding history found" />
        ) : (
          sortedHistory.map((order, index) => {
            const symbol = String(getFundingField(order, ["symbol", "token", "marketSymbol"]) ?? getSymbolByMarketId(order.marketId) ?? `m-${order.marketId}`);
            const side = String(getFundingField(order, ["side"]) ?? order.side ?? "—");
            const positionSize = Number(getFundingField(order, ["positionSize", "size", "quantity"]) ?? order.quantity ?? 0);
            const payout = Number(getFundingField(order, ["payout", "fundingPayment", "fundingFee"]) ?? 0);
            const rate = Number(getFundingField(order, ["rate", "fundingRate"]) ?? 0);

            return (
              <div key={`funding-${order.orderId}-${index}`} className={`table-row ${index % 2 === 0 ? "even" : ""}`} style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}>
                <div className="table-cell primary">{formatDateTime(getFundingTime(order))}</div>
                <div
                  className="table-cell center"
                  title={order.agentTaskId ?? undefined}
                >
                  {order.agentTaskId ? (
                    <span className="task-id-chip">
                      {shortHashId(order.agentTaskId)}
                    </span>
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell">{symbol}</div>
                <div className="table-cell">{side}</div>
                <div className="table-cell">{formatNumber(positionSize)}</div>
                <div className="table-cell">{formatNumber(payout)}</div>
                <div className="table-cell right">{formatNumber(rate)}</div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

export default React.memo(FundingHistory);
