import type React from "react";
import "./layout.css";

export interface CancelButtonProps {
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
  disabled?: boolean;
}

export interface CloseButtonProps {
  onClick: () => void;
}

export interface ActionButtonProps {
  onClick: () => void;
  variant?: "danger" | "success";
  children: React.ReactNode;
}

/**
 * Cancel button fragment
 */
export function CancelButton({
  onClick,
  disabled,
}: CancelButtonProps): JSX.Element {
  return (
    <button
      onClick={(e) => {
        if (!disabled && onClick) {
          onClick(e);
        }
      }}
      className="btn btn-danger"
      disabled={disabled}
      style={{
        pointerEvents: disabled ? "none" : "auto",
        cursor: disabled ? "not-allowed" : "pointer",
      }}
    >
      Cancel
    </button>
  );
}

/**
 * Close button fragment
 */
export function CloseButton({ onClick }: CloseButtonProps): JSX.Element {
  return (
    <button onClick={onClick} className="btn btn-success">
      Close
    </button>
  );
}

/**
 * Action button fragment with customizable variant
 */
export function ActionButton({
  onClick,
  variant = "danger",
  children,
}: ActionButtonProps): JSX.Element {
  return (
    <button onClick={onClick} className={`btn btn-${variant}`}>
      {children}
    </button>
  );
}
