import type { UTCTimestamp } from "lightweight-charts";
import { toBinanceInterval } from "../../sdk/api/binance/klineUtil";
import type { TradeHistoryRow } from "../../sdk/types/data";
import type { AgentTask } from "../../store/types";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { shortHashId } from "../../utils/hashId";

export type ExecutionMarkerKind = "agent" | "manual";

export interface ChartExecutionMarkerMeta {
  tradeId: string;
  kind: ExecutionMarkerKind;
  agentTaskId?: string;
  task?: AgentTask;
  side: "Buy" | "Sell";
  price: number;
  size: number;
  direction: string;
  time: number;
  closedPnl: number | null;
  coin: string;
}

export interface ChartExecutionMarker {
  tradeId: string;
  time: UTCTimestamp;
  position: "aboveBar" | "belowBar";
  shape: "circle" | "square";
  color: string;
  label: string;
  /** Public SVG/PNG URL; when set, render avatar image instead of shape + label. */
  imageUrl?: string;
  /** Higher values win when stack cap drops markers on the same bar anchor. */
  stackRank?: number;
}

export interface ChartTradeFocusRequest {
  marketId: string;
  tradeId: string;
  /** Fill timestamp in milliseconds (TradeHistoryRow.time). */
  time: number;
  /** Bumps on repeat focus so the same trade can re-scroll. */
  requestId: number;
}

/** Constant brand border ring thickness in CSS pixels (2px per side). */
export const EXECUTION_MARKER_BORDER_WIDTH_PX = 2;
export const EXECUTION_MARKER_FILL_SIZE = 2;
/** Opacity for white background halo behind avatar/shape markers. */
export const EXECUTION_MARKER_BACKGROUND_OPACITY = 0.5;

export function isShortDirection(direction: string): boolean {
  return /short/i.test(direction);
}

export function markerBarPosition(direction: string): "aboveBar" | "belowBar" {
  return isShortDirection(direction) ? "aboveBar" : "belowBar";
}

export function resolveMarkerKind(agentTaskId?: string | null): ExecutionMarkerKind {
  return agentTaskId ? "agent" : "manual";
}

export function resolveMarkerLabel(
  kind: ExecutionMarkerKind,
  agentTaskId?: string | null,
): string {
  return kind === "agent" && agentTaskId ? shortHashId(agentTaskId) : "M";
}

export function resolveChartSide(
  orderSide: string,
): "Buy" | "Sell" {
  const upper = orderSide.toUpperCase();
  if (upper.includes("BUY") || upper.includes("LONG")) return "Buy";
  return "Sell";
}

export function resolveSideColor(side: "Buy" | "Sell"): string {
  return side === "Buy" ? TERMINAL_COLORS.long : TERMINAL_COLORS.short;
}

export interface TradesToExecutionMarkersResult {
  markers: ChartExecutionMarker[];
  metaByTradeId: Map<string, ChartExecutionMarkerMeta>;
}

/** Binance-style interval string → bucket size in seconds. */
export function intervalToSeconds(interval: string): number {
  const binanceInterval = toBinanceInterval(interval);
  const match = binanceInterval.match(/^(\d+)([smhdwMy])$/);
  if (!match) return 300;

  const value = parseInt(match[1]!, 10);
  const unit = match[2]!;

  switch (unit) {
    case "s":
      return value;
    case "m":
      return value * 60;
    case "h":
      return value * 3600;
    case "d":
      return value * 86400;
    case "w":
      return value * 604800;
    case "M":
      return value * 2592000;
    case "y":
      return value * 31536000;
    default:
      return 300;
  }
}

/** Floor fill timestamp (ms) to candle bucket open (unix seconds). */
export function snapTimeToCandleInterval(timeMs: number, interval: string): UTCTimestamp {
  const bucketSec = intervalToSeconds(interval);
  const timeSec = Math.floor(timeMs / 1000);
  const snapped = Math.floor(timeSec / bucketSec) * bucketSec;
  return snapped as UTCTimestamp;
}

/** Map a target unix time to the nearest open time in sorted bar series. Clamps to range. */
export function resolveTimeToNearestBar(
  targetSec: number,
  barTimes: readonly number[] | undefined,
): UTCTimestamp | null {
  if (!barTimes || barTimes.length === 0) return null;

  const first = barTimes[0]!;
  const last = barTimes[barTimes.length - 1]!;
  const clamped = Math.min(last, Math.max(first, targetSec));

  if (barTimes.length === 1) {
    return first as UTCTimestamp;
  }

  let lo = 0;
  let hi = barTimes.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (barTimes[mid]! < clamped) lo = mid + 1;
    else hi = mid;
  }

  const candidate = barTimes[lo]!;
  if (lo === 0) return candidate as UTCTimestamp;

  const prev = barTimes[lo - 1]!;
  return (
    Math.abs(prev - clamped) <= Math.abs(candidate - clamped) ? prev : candidate
  ) as UTCTimestamp;
}

export function normalizeTradeBaseAsset(coin: string): string {
  const trimmed = coin.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("m-")) {
    return trimmed.slice(2).toUpperCase();
  }
  const withoutQuote = trimmed.split(/[-/]/)[0] ?? trimmed;
  return withoutQuote.toUpperCase();
}

export function filterTradesForMarket(
  trades: TradeHistoryRow[],
  marketId: string,
  baseAsset?: string,
): TradeHistoryRow[] {
  const normalizedBase = baseAsset ? baseAsset.toUpperCase() : "";
  if (!marketId && !normalizedBase) return [];

  return trades.filter((row) => {
    if (normalizedBase) {
      return normalizeTradeBaseAsset(row.coin) === normalizedBase;
    }
    if (marketId) {
      return row.marketId === marketId;
    }
    return false;
  });
}

function buildTaskMap(tasks: AgentTask[]): Map<string, AgentTask> {
  return new Map(tasks.map((task) => [task.id, task]));
}

export function tradesToSeriesMarkers(
  trades: TradeHistoryRow[],
  tasks: AgentTask[],
  interval: string,
): TradesToExecutionMarkersResult {
  const taskMap = buildTaskMap(tasks);
  const markers: ChartExecutionMarker[] = [];
  const metaByTradeId = new Map<string, ChartExecutionMarkerMeta>();

  for (const row of trades) {
    const kind = resolveMarkerKind(row.agentTaskId);
    const isAgent = kind === "agent";
    const side = row.side;
    const task = row.agentTaskId ? taskMap.get(row.agentTaskId) : undefined;

    const meta: ChartExecutionMarkerMeta = {
      tradeId: row.tradeId,
      kind,
      agentTaskId: row.agentTaskId ?? undefined,
      task,
      side,
      price: row.price,
      size: row.size,
      direction: row.direction,
      time: row.time,
      closedPnl: row.closedPnl,
      coin: row.coin,
    };

    markers.push({
      tradeId: row.tradeId,
      time: snapTimeToCandleInterval(row.time, interval),
      position: markerBarPosition(row.direction),
      shape: isAgent ? "circle" : "square",
      color: resolveSideColor(side),
      label: resolveMarkerLabel(kind, row.agentTaskId),
    });
    metaByTradeId.set(row.tradeId, meta);
  }

  return { markers, metaByTradeId };
}
