import React, { type JSX } from "react";

import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import AgentTokenTakerKlineChart from "../agent/AgentTokenTakerKlineChart";
import AgentTokenKlineChartWidgetInner from "./AgentTokenKlineChartWidgetInner";

export interface AgentTokenKlineChartWidgetProps {
  catalogAgentId: string;
  interval?: string;
  height?: string;
  className?: string;
  baseUrl?: string;
  limit?: number;
  /** When set with tokenTakerEvents, render taker avatar markers on the token chart. */
  showTokenTakerMarkers?: boolean;
  tokenTakerEvents?: AgentTokenTakerTradeEvent[];
  tokenTakerEventsLoading?: boolean;
  focusEventId?: string | null;
  focusTimeMs?: number;
}

function AgentTokenKlineChartWidget({
  showTokenTakerMarkers = false,
  tokenTakerEvents = [],
  tokenTakerEventsLoading = false,
  focusEventId = null,
  focusTimeMs = 0,
  ...rest
}: AgentTokenKlineChartWidgetProps): JSX.Element {
  if (showTokenTakerMarkers) {
    return (
      <AgentTokenTakerKlineChart
        catalogAgentId={rest.catalogAgentId}
        events={tokenTakerEvents}
        eventsLoading={tokenTakerEventsLoading}
        focusEventId={focusEventId}
        focusTimeMs={focusTimeMs}
        height={rest.height}
        className={rest.className}
        baseUrl={rest.baseUrl}
        limit={rest.limit}
      />
    );
  }

  return <AgentTokenKlineChartWidgetInner {...rest} />;
}

export default AgentTokenKlineChartWidget;
