import type { LineData, UTCTimestamp } from "lightweight-charts";

export type CompactMetricChart =
  | { kind: "sparkline"; values: number[]; tone?: "signed" | "neutral" }
  | {
      kind: "line";
      data: LineData<UTCTimestamp>[];
      color?: string;
      formatValue?: (value: number) => string;
    }
  | { kind: "none" };

export interface CompactMetricDefinition {
  id: string;
  label: string;
  value: string;
  changePercent?: number;
  valueTone?: "neutral" | "signed";
  chart?: CompactMetricChart;
}

export type CompactMetricTone = "positive" | "negative" | "neutral";

export function metricToneFromValue(value: number): CompactMetricTone {
  if (value > 0) return "positive";
  if (value < 0) return "negative";
  return "neutral";
}

export function metricToneClassName(tone: CompactMetricTone): string {
  if (tone === "positive") return "positive";
  if (tone === "negative") return "negative";
  return "";
}
