import type { LineData, UTCTimestamp } from "lightweight-charts";

import { sanitizeLineDataForChart } from "./portfolioChartData";

const DAY_MS = 24 * 60 * 60 * 1000;
/** Minimum mock history span — one month of daily points. */
export const INDEX_CHART_HISTORY_DAYS = 30;

function toUtcTimestamp(ms: number): UTCTimestamp {
  return Math.floor(ms / 1000) as UTCTimestamp;
}

export interface IndexNavPriceChartSeries {
  priceData: LineData<UTCTimestamp>[];
  navData: LineData<UTCTimestamp>[];
}

function interpolateSeries(values: number[], pointCount: number): number[] {
  if (values.length === 0) return [];
  if (pointCount <= 1) return [values[values.length - 1] ?? 0];
  if (values.length === 1) return Array.from({ length: pointCount }, () => values[0]!);

  return Array.from({ length: pointCount }, (_, index) => {
    const t = (index / (pointCount - 1)) * (values.length - 1);
    const lo = Math.floor(t);
    const hi = Math.min(Math.ceil(t), values.length - 1);
    const frac = t - lo;
    return values[lo]! * (1 - frac) + values[hi]! * frac;
  });
}

/**
 * Build mocked NAV vs market price time series from profile chartSeries.
 * Resamples authored anchors across at least 30 days of daily points ending today.
 * Scales the last point to current price; NAV tracks price × (nav / price).
 */
export function buildIndexNavPriceChartSeries(
  chartSeries: number[],
  nav: number,
  price: number,
): IndexNavPriceChartSeries {
  const anchors = chartSeries.length > 1 ? chartSeries : [nav, price];
  const pointCount = INDEX_CHART_HISTORY_DAYS + 1;
  const resampled = interpolateSeries(anchors, pointCount);

  const lastResampled = resampled[resampled.length - 1] ?? price;
  const scale = lastResampled !== 0 ? price / lastResampled : 1;
  const navRatio = price !== 0 ? nav / price : 1;

  const now = Date.now();
  const priceData: LineData<UTCTimestamp>[] = resampled.map((value, index) => ({
    time: toUtcTimestamp(now - (pointCount - 1 - index) * DAY_MS),
    value: Number((value * scale).toFixed(4)),
  }));

  const navData: LineData<UTCTimestamp>[] = priceData.map((point) => ({
    time: point.time,
    value: Number((point.value * navRatio).toFixed(4)),
  }));

  return {
    priceData: sanitizeLineDataForChart(priceData),
    navData: sanitizeLineDataForChart(navData),
  };
}
