import type { CopyRelation } from "../../offline/mock_data/fleetCopyRelations";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import type { AgentTask, AgentTaskGuardrailMeta } from "../store/types";

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function isEntryAction(action: FleetTradeEvent["action"]): boolean {
  return action === "BUY" || action === "SNIPE";
}

function deriveMirrorGuardrail(
  event: FleetTradeEvent,
  copySizePct: number,
): AgentTaskGuardrailMeta {
  const mirrorNotional = round2(event.amountUsd * (copySizePct / 100));
  const isEntry = isEntryAction(event.action);

  if (isEntry) {
    return {
      confidencePct: mirrorNotional > 500 ? 78 : 88,
      riskImpact: mirrorNotional > 800 ? "moderate" : "low",
      expectedFillImpactBps: 2.5,
      simulationNote: `Mirror ${event.action} · ~$${mirrorNotional.toFixed(0)} notional at ${copySizePct}%.`,
    };
  }

  return {
    confidencePct: event.closedPnl != null && event.closedPnl >= 0 ? 86 : 74,
    riskImpact: "moderate",
    expectedFillImpactBps: 3.1,
    simulationNote: `Mirror exit · leader closed $${(event.closedPnl ?? 0).toFixed(2)} · ~$${mirrorNotional.toFixed(0)} notional.`,
  };
}

export type MirrorTaskInput = Omit<
  AgentTask,
  "id" | "createdAt" | "updatedAt" | "isNew" | "agentId"
> &
  Partial<Pick<AgentTask, "id" | "createdAt" | "updatedAt" | "isNew" | "agentId">>;

export function buildMirrorTaskFromFleetEvent(params: {
  event: FleetTradeEvent;
  relation: CopyRelation;
  agentId: string;
  profileName: string;
}): MirrorTaskInput {
  const { event, relation, agentId, profileName } = params;
  const copySizePct = relation.copySettings.copySizePct;
  const actionLabel = event.action;
  const description = `Mirror ${actionLabel} ${copySizePct}% · ${profileName} · ${event.coin}`;

  return {
    agentId,
    description,
    status: "pending",
    marketId: event.marketId,
    bucketId: relation.copySettings.bucketId,
    trigger: `Leader fill · ${actionLabel} · ${event.coin} · ${profileName}`,
    eta: null,
    leaderTradeId: event.id,
    copyRelationId: relation.id,
    guardrail: deriveMirrorGuardrail(event, copySizePct),
    statusHistory: [
      {
        status: "pending",
        at: new Date().toISOString(),
        note: "Leader fill detected; mirror intent queued.",
      },
    ],
  };
}
