export type WelcomeSlideWelcome = {
  id: string;
  icon: string;
  kicker: string;
  headline: string;
  body: string;
  chips: { icon: string; label: string }[];
};

export type WelcomeSlideBullets = {
  id: string;
  icon: string;
  kicker: string;
  headline: string;
  bullets: [string, string, string];
};

export type WelcomeSlide = WelcomeSlideWelcome | WelcomeSlideBullets;

export function isWelcomeSlideWelcome(slide: WelcomeSlide): slide is WelcomeSlideWelcome {
  return "body" in slide;
}

