import type { TradeHistoryRow } from "../sdk/types/data";
import type { PortfolioTimeRange } from "./portfolioChartData";
import { filterPerformanceTrades } from "./portfolioPerformanceMetrics";

export type AgentRankActionHint = "scale" | "keep" | "monitor" | "tweak" | "pause";

export interface AgentRankRow {
  id: string;
  label: string;
  icon?: string;
  color: string;
  rank: number;
  cagrPct: number;
  sharpe: number;
  maxDrawdownPct: number;
  profitFactor: number;
  calmarRatio: number;
  compositeScore: number;
  actionHint: AgentRankActionHint;
}

export interface AgentRankSummary {
  fleetMedianComposite: number;
  aboveMedianPct: number;
  topAgent: AgentRankRow | null;
  agents: AgentRankRow[];
}

export const AGENT_RANK_ACTION_LABELS: Record<AgentRankActionHint, string> = {
  scale: "Scale up",
  keep: "Keep / add",
  monitor: "Monitor",
  tweak: "Tweak",
  pause: "Pause",
};

const TRADING_DAYS_PER_YEAR = 252;
const MIN_STD = 1e-6;
const DAY_MS = 24 * 60 * 60 * 1000;

const COMPOSITE_WEIGHTS = {
  cagr: 0.3,
  sharpe: 0.3,
  inverseMdd: 0.2,
  profitFactor: 0.2,
} as const;

function dateKey(ms: number): string {
  const date = new Date(ms);
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${date.getUTCFullYear()}-${month}-${day}`;
}

function computeSharpeFromDailyPnl(
  dailyPnls: number[],
  equityBaseline: number,
): number | null {
  if (dailyPnls.length < 2 || equityBaseline <= 0) return null;

  const returns = dailyPnls.map((pnl) => pnl / equityBaseline);
  const mean = returns.reduce((sum, value) => sum + value, 0) / returns.length;
  const variance =
    returns.reduce((sum, value) => sum + (value - mean) ** 2, 0) /
    (returns.length - 1);
  const std = Math.sqrt(variance);

  if (std < MIN_STD) {
    if (mean > 0) return 2;
    if (mean < 0) return -1;
    return 0;
  }

  return (mean / std) * Math.sqrt(TRADING_DAYS_PER_YEAR);
}

function fallbackSharpeFromRevenue(
  revenue30d: number,
  revenues: number[],
): number {
  if (revenues.length === 0) return 1;

  const sorted = [...revenues].sort((a, b) => a - b);
  const min = sorted[0]!;
  const max = sorted[sorted.length - 1]!;
  const range = max - min;
  if (range <= 0) return 1.2;

  const normalized = (revenue30d - min) / range;
  if (revenue30d < 0) {
    return -0.5 + normalized * 0.8;
  }
  return 0.8 + normalized * 1.6;
}

function computeAgentMaxDrawdownPct(
  trades: TradeHistoryRow[],
  equityBaseline: number,
): number {
  const sorted = [...trades]
    .filter((trade) => trade.closedPnl != null)
    .sort((a, b) => a.time - b.time);

  if (sorted.length === 0) return 0;

  const totalPnl = sorted.reduce((sum, trade) => sum + (trade.closedPnl ?? 0), 0);
  let equity = Math.max(equityBaseline - totalPnl, 1);
  let peak = equity;
  let maxDrawdown = 0;

  for (const trade of sorted) {
    equity += trade.closedPnl ?? 0;
    if (equity > peak) peak = equity;
    if (peak > 0) {
      const drawdown = ((peak - equity) / peak) * 100;
      if (drawdown > maxDrawdown) maxDrawdown = drawdown;
    }
  }

  return maxDrawdown;
}

function computeProfitFactor(trades: TradeHistoryRow[]): number {
  let grossProfit = 0;
  let grossLoss = 0;

  for (const trade of trades) {
    const pnl = trade.closedPnl;
    if (pnl == null) continue;
    if (pnl > 0) grossProfit += pnl;
    else if (pnl < 0) grossLoss += Math.abs(pnl);
  }

  if (grossLoss <= 0) {
    return grossProfit > 0 ? 3.5 : 1;
  }
  return grossProfit / grossLoss;
}

function computeCagrPct(
  realizedPnl: number,
  equityPerAgent: number,
  trackRecordDays: number,
): number {
  if (equityPerAgent <= 0) return 0;

  const roiPct = (realizedPnl / equityPerAgent) * 100;
  if (trackRecordDays <= 0 || trackRecordDays >= 365) {
    return roiPct;
  }

  const roiDecimal = realizedPnl / equityPerAgent;
  const annualized =
    (Math.pow(1 + roiDecimal, 365 / trackRecordDays) - 1) * 100;
  return Number.isFinite(annualized) ? annualized : roiPct;
}

function normalizeMetric(values: number[], value: number): number {
  if (values.length === 0) return 50;
  const min = Math.min(...values);
  const max = Math.max(...values);
  if (max === min) return 50;
  return ((value - min) / (max - min)) * 100;
}

function assignActionHint(compositeScore: number): AgentRankActionHint {
  if (compositeScore >= 72) return compositeScore >= 90 ? "scale" : "keep";
  if (compositeScore >= 45) return "monitor";
  if (compositeScore >= 22) return "tweak";
  return "pause";
}

function computeTrackRecordDays(
  trades: TradeHistoryRow[],
  timeRange: PortfolioTimeRange,
): number {
  const closed = trades.filter((trade) => trade.closedPnl != null);
  if (closed.length === 0) {
    if (timeRange === "30d") return 30;
    if (timeRange === "7d") return 7;
    if (timeRange === "24h") return 1;
    return 365;
  }

  const times = closed.map((trade) => trade.time);
  const spanMs = Math.max(Math.max(...times) - Math.min(...times), DAY_MS);
  return Math.max(spanMs / DAY_MS, 1);
}

export interface BuildAgentRankInput {
  agents: Array<{
    id: string;
    displayName: string;
    icon?: string;
    revenue30d?: number;
  }>;
  trades: TradeHistoryRow[];
  taskAgentMap: Map<string, string>;
  filterAgentIds: string[];
  timeRange: PortfolioTimeRange;
  accountEquity: number;
  agentColor: (index: number) => string;
}

export function buildAgentRankMetrics(input: BuildAgentRankInput): AgentRankSummary {
  const filteredTrades = filterPerformanceTrades(
    input.trades,
    "perps",
    input.timeRange,
    input.filterAgentIds,
    input.taskAgentMap,
  );

  const revenues = input.agents.map((agent) => agent.revenue30d ?? 0);
  const equityPerAgent = Math.max(
    input.accountEquity / Math.max(input.agents.length, 1),
    1,
  );

  const tradesByAgent = new Map<string, TradeHistoryRow[]>();
  const dailyByAgent = new Map<string, Map<string, number>>();

  for (const trade of filteredTrades) {
    if (trade.closedPnl == null) continue;

    const agentId = trade.agentTaskId
      ? input.taskAgentMap.get(trade.agentTaskId)
      : undefined;
    if (!agentId) continue;

    const agentTrades = tradesByAgent.get(agentId) ?? [];
    agentTrades.push(trade);
    tradesByAgent.set(agentId, agentTrades);

    const day = dateKey(trade.time);
    const days = dailyByAgent.get(agentId) ?? new Map<string, number>();
    days.set(day, (days.get(day) ?? 0) + trade.closedPnl);
    dailyByAgent.set(agentId, days);
  }

  const trackRecordDays = computeTrackRecordDays(filteredTrades, input.timeRange);

  const rawRows = input.agents.map((agent, index) => {
    const agentTrades = tradesByAgent.get(agent.id) ?? [];
    const dailyMap = dailyByAgent.get(agent.id);
    const dailyPnls = dailyMap ? [...dailyMap.values()] : [];
    const realizedPnl = agentTrades.reduce(
      (sum, trade) => sum + (trade.closedPnl ?? 0),
      0,
    );

    const sharpe =
      computeSharpeFromDailyPnl(dailyPnls, equityPerAgent) ??
      fallbackSharpeFromRevenue(agent.revenue30d ?? 0, revenues);
    const maxDrawdownPct = computeAgentMaxDrawdownPct(
      agentTrades,
      equityPerAgent,
    );
    const profitFactor = computeProfitFactor(agentTrades);
    const cagrPct = computeCagrPct(
      realizedPnl,
      equityPerAgent,
      trackRecordDays,
    );
    const calmarRatio =
      maxDrawdownPct > 0 ? cagrPct / maxDrawdownPct : cagrPct > 0 ? cagrPct : 0;

    return {
      agent,
      index,
      cagrPct,
      sharpe,
      maxDrawdownPct,
      profitFactor,
      calmarRatio,
    };
  });

  const cagrValues = rawRows.map((row) => row.cagrPct);
  const sharpeValues = rawRows.map((row) => row.sharpe);
  const inverseMddValues = rawRows.map((row) => -row.maxDrawdownPct);
  const profitFactorValues = rawRows.map((row) => row.profitFactor);

  const compositeScores = rawRows.map((row) => {
    const cagrNorm = normalizeMetric(cagrValues, row.cagrPct);
    const sharpeNorm = normalizeMetric(sharpeValues, row.sharpe);
    const inverseMddNorm = normalizeMetric(inverseMddValues, -row.maxDrawdownPct);
    const profitFactorNorm = normalizeMetric(profitFactorValues, row.profitFactor);

    return (
      COMPOSITE_WEIGHTS.cagr * cagrNorm +
      COMPOSITE_WEIGHTS.sharpe * sharpeNorm +
      COMPOSITE_WEIGHTS.inverseMdd * inverseMddNorm +
      COMPOSITE_WEIGHTS.profitFactor * profitFactorNorm
    );
  });

  const agents: AgentRankRow[] = rawRows
    .map((row, rowIndex) => ({
      id: row.agent.id,
      label: row.agent.displayName,
      icon: row.agent.icon,
      color: input.agentColor(row.index),
      rank: 0,
      cagrPct: row.cagrPct,
      sharpe: row.sharpe,
      maxDrawdownPct: row.maxDrawdownPct,
      profitFactor: row.profitFactor,
      calmarRatio: row.calmarRatio,
      compositeScore: compositeScores[rowIndex]!,
      actionHint: assignActionHint(compositeScores[rowIndex]!),
    }))
    .sort((a, b) => b.compositeScore - a.compositeScore)
    .map((agent, index) => ({ ...agent, rank: index + 1 }));

  const sortedComposites = agents.map((agent) => agent.compositeScore);
  const mid = Math.floor(sortedComposites.length / 2);
  const fleetMedianComposite =
    sortedComposites.length === 0
      ? 0
      : sortedComposites.length % 2 === 0
        ? (sortedComposites[mid - 1]! + sortedComposites[mid]!) / 2
        : sortedComposites[mid]!;

  const aboveMedian = agents.filter(
    (agent) => agent.compositeScore >= fleetMedianComposite,
  ).length;
  const aboveMedianPct =
    agents.length > 0 ? (aboveMedian / agents.length) * 100 : 0;

  return {
    fleetMedianComposite,
    aboveMedianPct,
    topAgent: agents[0] ?? null,
    agents,
  };
}

export const QUADRANT_CAGR_THRESHOLD = 40;
export const QUADRANT_MDD_THRESHOLD = 25;

export type AgentRankQuadrant =
  | "stars"
  | "volatileWinners"
  | "steady"
  | "pauseRework";

export const AGENT_RANK_QUADRANT_LABELS: Record<AgentRankQuadrant, string> = {
  stars: "Stars — scale up",
  volatileWinners: "Volatile Winners — size carefully",
  steady: "Steady — hold & optimize",
  pauseRework: "Pause / Rework",
};

export interface AgentRankQuadrantPoint {
  agent: AgentRankRow;
  quadrant: AgentRankQuadrant;
  x: number;
  y: number;
}

export interface AgentRankQuadrantLayout {
  points: AgentRankQuadrantPoint[];
  xMin: number;
  xMax: number;
  yMin: number;
  yMax: number;
  cagrThreshold: number;
  mddThreshold: number;
}

export function classifyAgentQuadrant(
  cagrPct: number,
  maxDrawdownPct: number,
  cagrThreshold = QUADRANT_CAGR_THRESHOLD,
  mddThreshold = QUADRANT_MDD_THRESHOLD,
): AgentRankQuadrant {
  const highReturn = cagrPct >= cagrThreshold;
  const highRisk = maxDrawdownPct >= mddThreshold;

  if (highReturn && !highRisk) return "stars";
  if (highReturn && highRisk) return "volatileWinners";
  if (!highReturn && !highRisk) return "steady";
  return "pauseRework";
}

function padDomain(
  min: number,
  max: number,
  threshold: number,
  floor: number,
  paddingRatio = 0.12,
): [number, number] {
  let domainMin = Math.min(min, threshold, floor);
  let domainMax = Math.max(max, threshold);

  if (domainMin === domainMax) {
    domainMin -= 1;
    domainMax += 1;
  }

  const span = domainMax - domainMin;
  return [domainMin - span * paddingRatio, domainMax + span * paddingRatio];
}

export function buildAgentRankQuadrantLayout(
  agents: AgentRankRow[],
  cagrThreshold = QUADRANT_CAGR_THRESHOLD,
  mddThreshold = QUADRANT_MDD_THRESHOLD,
): AgentRankQuadrantLayout {
  if (agents.length === 0) {
    return {
      points: [],
      xMin: 0,
      xMax: mddThreshold * 1.5,
      yMin: 0,
      yMax: cagrThreshold * 1.5,
      cagrThreshold,
      mddThreshold,
    };
  }

  const points: AgentRankQuadrantPoint[] = agents.map((agent) => ({
    agent,
    quadrant: classifyAgentQuadrant(
      agent.cagrPct,
      agent.maxDrawdownPct,
      cagrThreshold,
      mddThreshold,
    ),
    x: agent.maxDrawdownPct,
    y: agent.cagrPct,
  }));

  const xValues = points.map((point) => point.x);
  const yValues = points.map((point) => point.y);
  const [xMin, xMax] = padDomain(
    Math.min(...xValues),
    Math.max(...xValues),
    mddThreshold,
    0,
  );
  const [yMin, yMax] = padDomain(
    Math.min(...yValues, 0),
    Math.max(...yValues),
    cagrThreshold,
    0,
  );

  return {
    points,
    xMin,
    xMax,
    yMin,
    yMax,
    cagrThreshold,
    mddThreshold,
  };
}
