import React from "react";

import { useOptionalSettingsHost } from "../../context/SettingsHostContext";
import type { SubmenuKey } from "./settingsRegistry";
import "./TerminalSettingsButton.css";

function SettingsWrenchIcon(): JSX.Element {
  return (
    <svg
      className="terminal-settings-button-icon"
      fill="currentColor"
      viewBox="0 0 256 256"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden
    >
      <path d="M48,244.8l126-126c0.7-0.7,1.4-1.5,2.1-2.3c20.3,6.8,43.6,2.1,59.8-14.1c17.5-17.5,21.6-43.3,12.2-64.7l-38.5,38.5-30.2-30.2l38.5-38.5c-21.4-9.3-47.2-5.2-64.7,12.2c-16.2,16.2-20.9,39.5-14.1,59.8c-0.8,0.6-1.6,1.3-2.3,2.1l-126,126c-10.2,10.2-10.2,27,0,37.2C21,255,37.7,255,48,244.8z" />
    </svg>
  );
}

export interface TerminalCompactSettingsButtonProps {
  focusSection?: SubmenuKey;
  className?: string;
  ariaLabel?: string;
}

function TerminalCompactSettingsButton({
  focusSection,
  className = "",
  ariaLabel = "Page settings",
}: TerminalCompactSettingsButtonProps): JSX.Element | null {
  const settingsHost = useOptionalSettingsHost();
  if (!settingsHost) return null;

  return (
    <button
      type="button"
      className={`terminal-settings-button terminal-settings-button--compact${className ? ` ${className}` : ""}`}
      onClick={() => settingsHost.openSettings({ focusSection })}
      aria-label={ariaLabel}
    >
      <SettingsWrenchIcon />
    </button>
  );
}

export default TerminalCompactSettingsButton;
