import React from "react";

import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import { humanizeBehaviorProfile } from "./agentHeroFocus";
import "./agent.css";

export interface AgentPlaybookTabProps {
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
}

function AgentPlaybookTab({
  profile,
  fleet,
}: AgentPlaybookTabProps): JSX.Element {
  const behaviorLabel = humanizeBehaviorProfile(fleet.behaviorProfile);
  const contextLine = `${profile.sector} · ${profile.product} · ${profile.perpBaseAsset}`;

  return (
    <div className="agent-playbook-tab">
      <div className="agent-playbook-field">
        <span className="agent-playbook-label">Strategy</span>
        <strong className="agent-playbook-value">{profile.strategy}</strong>
      </div>

      <div className="agent-playbook-field">
        <span className="agent-playbook-label">Behavior</span>
        <strong className="agent-playbook-value">{behaviorLabel}</strong>
      </div>

      <div className="agent-playbook-field">
        <span className="agent-playbook-label">Risk</span>
        <strong className="agent-playbook-value">{profile.riskScore}</strong>
      </div>

      <div className="agent-playbook-field">
        <span className="agent-playbook-label">Context</span>
        <span className="agent-playbook-value agent-playbook-value--muted">
          {contextLine}
        </span>
      </div>

      {profile.leverage != null || profile.annFunding != null ? (
        <div className="agent-playbook-params">
          {profile.leverage != null ? (
            <span>Leverage {profile.leverage}x</span>
          ) : null}
          {profile.annFunding != null ? (
            <span>Ann. funding {profile.annFunding.toFixed(1)}%</span>
          ) : null}
        </div>
      ) : null}

      {profile.riskInputs.length > 0 ? (
        <div className="agent-playbook-field">
          <span className="agent-playbook-label">Policy</span>
          <ul className="agent-playbook-policy-list">
            {profile.riskInputs.map((input) => (
              <li key={input}>{input}</li>
            ))}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

export default AgentPlaybookTab;
