import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { useLocation } from "react-router-dom";
import SettingsModal from "../components/preference/SettingsModal";
import type { SubmenuKey } from "../components/preference/settingsRegistry";
import {
  buildMenuGroups,
  resolveSettingsPageContext,
  type SettingsPageContext,
} from "../components/preference/settingsRegistry";
import { useSettings } from "./SettingsContext";

export interface OpenSettingsOptions {
  focusSection?: SubmenuKey;
}

interface TradeSettingsCallbacks {
  onLayoutEdit?: () => void;
}

interface SettingsHostContextType {
  openSettings: (options?: OpenSettingsOptions) => void;
  closeSettings: () => void;
  isOpen: boolean;
  pageContext: SettingsPageContext;
  registerTradeCallbacks: (callbacks: TradeSettingsCallbacks) => void;
}

const SettingsHostContext = createContext<SettingsHostContextType | undefined>(
  undefined,
);

export function SettingsHost({
  children,
  onOpenKeyboardShortcuts,
}: {
  children: ReactNode;
  onOpenKeyboardShortcuts?: () => void;
}): JSX.Element {
  const location = useLocation();
  const { settings, setSettings } = useSettings();
  const [isOpen, setIsOpen] = useState(false);
  const [focusSection, setFocusSection] = useState<SubmenuKey | null>(null);
  const [tradeCallbacks, setTradeCallbacks] = useState<TradeSettingsCallbacks>({});

  const pageContext = useMemo(
    () => resolveSettingsPageContext(location.pathname),
    [location.pathname],
  );

  const menuGroups = useMemo(
    () => buildMenuGroups(pageContext),
    [pageContext],
  );

  const openSettings = useCallback((options?: OpenSettingsOptions) => {
    setFocusSection(options?.focusSection ?? null);
    setIsOpen(true);
  }, []);

  const closeSettings = useCallback(() => {
    setIsOpen(false);
    setFocusSection(null);
  }, []);

  const registerTradeCallbacks = useCallback((callbacks: TradeSettingsCallbacks) => {
    setTradeCallbacks(callbacks);
  }, []);

  useEffect(() => {
    const state = location.state as { openSettings?: boolean } | null;
    if (state?.openSettings) {
      openSettings();
      window.history.replaceState({}, "", location.pathname + location.search);
    }
  }, [location.pathname, location.search, location.state, openSettings]);

  const value = useMemo(
    () => ({
      openSettings,
      closeSettings,
      isOpen,
      pageContext,
      registerTradeCallbacks,
    }),
    [openSettings, closeSettings, isOpen, pageContext, registerTradeCallbacks],
  );

  return (
    <SettingsHostContext.Provider value={value}>
      {children}
      <SettingsModal
        isOpen={isOpen}
        onClose={closeSettings}
        state={settings}
        onStateChange={setSettings}
        pageContext={pageContext}
        menuGroups={menuGroups}
        initialSubmenu={focusSection}
        onLayoutEdit={tradeCallbacks.onLayoutEdit}
        onOpenKeyboardShortcuts={onOpenKeyboardShortcuts}
      />
    </SettingsHostContext.Provider>
  );
}

export function useSettingsHost(): SettingsHostContextType {
  const context = useContext(SettingsHostContext);
  if (!context) {
    throw new Error("useSettingsHost must be used within SettingsHost");
  }
  return context;
}

export function useOptionalSettingsHost(): SettingsHostContextType | undefined {
  return useContext(SettingsHostContext);
}
