import React, { useLayoutEffect, useMemo, useRef, useState } from "react";

export type RiskZone = "low" | "moderate" | "high";

export interface RiskScoreMetricProps {
  label: string;
  score: number;
  variant?: "default" | "compact";
}

function clampScore(score: number): number {
  return Math.min(100, Math.max(0, Math.round(score)));
}

export function getRiskZone(score: number): RiskZone {
  const clamped = clampScore(score);
  if (clamped <= 33) return "low";
  if (clamped <= 66) return "moderate";
  return "high";
}

function zoneLabel(zone: RiskZone): string {
  switch (zone) {
    case "low":
      return "Low";
    case "moderate":
      return "Moderate";
    case "high":
      return "High";
  }
}

function zoneAriaLabel(zone: RiskZone): string {
  switch (zone) {
    case "low":
      return "low risk";
    case "moderate":
      return "moderate risk";
    case "high":
      return "high risk";
  }
}

function RiskScoreBadge({ zone }: { zone: RiskZone }): JSX.Element {
  return (
    <span className={`risk-score-badge risk-score-badge--${zone}`}>
      {zoneLabel(zone)}
    </span>
  );
}

function RiskScoreValue({
  score,
  zone,
}: {
  score: number;
  zone: RiskZone;
}): JSX.Element {
  return (
    <span
      className={`trade-safety-header-value trade-safety-header-value--zone-${zone}`}
    >
      {score}/100
    </span>
  );
}

function RiskScoreZoneBar({
  score,
  zone,
  width,
}: {
  score: number;
  zone: RiskZone;
  width?: number;
}): JSX.Element {
  return (
    <div
      className={`risk-score-zone-bar risk-score-zone-bar--${zone}`}
      style={
        {
          "--risk-score": score / 100,
          ...(width != null ? { width } : null),
        } as React.CSSProperties
      }
    >
      <div className="risk-score-zone-track">
        <div className="risk-score-zone-segment risk-score-zone-segment--low" />
        <div className="risk-score-zone-segment risk-score-zone-segment--moderate" />
        <div className="risk-score-zone-segment risk-score-zone-segment--high" />
      </div>
      <div className="risk-score-zone-marker" aria-hidden="true" />
    </div>
  );
}

function RiskScoreMetric({
  label,
  score,
  variant = "default",
}: RiskScoreMetricProps): JSX.Element {
  const labelRef = useRef<HTMLSpanElement>(null);
  const headlineRef = useRef<HTMLDivElement>(null);
  const [barWidth, setBarWidth] = useState<number | undefined>();

  const clamped = useMemo(() => clampScore(score), [score]);
  const zone = useMemo(() => getRiskZone(clamped), [clamped]);
  const isCompact = variant === "compact";

  useLayoutEffect(() => {
    const widthSource = isCompact ? headlineRef.current : labelRef.current;
    if (!widthSource) return undefined;

    const updateWidth = () => {
      setBarWidth(widthSource.offsetWidth);
    };

    updateWidth();

    const observer = new ResizeObserver(updateWidth);
    observer.observe(widthSource);
    return () => observer.disconnect();
  }, [isCompact, label]);

  const metricClassName = [
    "trade-safety-header-metric",
    "risk-score-metric",
    isCompact ? "risk-score-metric--compact" : "",
  ]
    .filter(Boolean)
    .join(" ");

  if (isCompact) {
    return (
      <div
        className={metricClassName}
        role="img"
        aria-label={`${label}: ${clamped} out of 100, ${zoneAriaLabel(zone)}`}
      >
        <span className="trade-safety-header-label">{label}</span>
        <div ref={headlineRef} className="risk-score-metric-headline">
          <RiskScoreBadge zone={zone} />
          <RiskScoreValue score={clamped} zone={zone} />
        </div>
        <RiskScoreZoneBar score={clamped} zone={zone} width={barWidth} />
      </div>
    );
  }

  return (
    <div
      className={metricClassName}
      role="img"
      aria-label={`${label}: ${clamped} out of 100, ${zoneAriaLabel(zone)}`}
    >
      <span ref={labelRef} className="trade-safety-header-label">
        {label}
      </span>
      <RiskScoreBadge zone={zone} />
      <RiskScoreValue score={clamped} zone={zone} />
      <RiskScoreZoneBar score={clamped} zone={zone} width={barWidth} />
    </div>
  );
}

export default React.memo(RiskScoreMetric);
