import React, { useState } from "react";
import { ExpandCollapseIcon } from "../../../mormv1/components/ui/ExpandCollapseIcon";
import Sparkline from "./Sparkline";
import QueryState from "./QueryState";
import { resolveColorToken } from "./colorTokens";
import { fmtNum } from "./format";
import { useTelemetryPanels } from "./useTelemetryPanels";

export default function DeepTelemetrySection(): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const { data, isPending, isError, error } = useTelemetryPanels();

  return (
    <div className="nh-telemetry">
      <button
        type="button"
        className="nh-telemetry-toggle"
        aria-expanded={open}
        onClick={() => setOpen((prev) => !prev)}
      >
        <ExpandCollapseIcon expanded={open} className="nh-telemetry-chevron" size={16} />
        Deep telemetry (Grafana)
      </button>

      {open ? (
        <div className="nh-telemetry-content">
          <p className="nh-section-note text-small">
            These are live validator panels. Rate-based charts (throughput,
            finalisation, per-stage latency) read flat or blank while the network
            is idle and fill in once traffic flows. Recovery charts (Frosty
            fallbacks, finality dip) move only during an injected fault. Slider
            settings above rescale the simulated series.
          </p>
          <QueryState
            isLoading={isPending}
            isError={isError}
            error={error}
            label="telemetry panels"
          >
            <div className="nh-telemetry-grid">
              {data?.map((panel) => {
                const latest = panel.series[panel.series.length - 1];
                return (
                  <article key={panel.id} className="nh-telemetry-panel">
                    <header className="nh-telemetry-panel-header">
                      <h4>{panel.title}</h4>
                      <span className="nh-telemetry-latest terminal-value">
                        {fmtNum(latest, panel.unit === "nodes" ? 1 : 2)}
                        {panel.unit ? ` ${panel.unit}` : ""}
                      </span>
                    </header>
                    <Sparkline
                      values={panel.series}
                      className="nh-telemetry-chart"
                      width={320}
                      height={160}
                      stroke={
                        panel.colorToken
                          ? resolveColorToken(panel.colorToken)
                          : "var(--terminal-accent)"
                      }
                    />
                  </article>
                );
              })}
            </div>
          </QueryState>
        </div>
      ) : null}
    </div>
  );
}
