import type { Market, TradingAgent } from "../../store/types";
import { extractAgentMentions, extractTickerMentions } from "./intentMentions";
import type {
  CompositeLeg,
  DirectionClass,
  IntentArchetype,
  ObjectiveClass,
  ResolvedFacet,
  RiskConstraints,
  StructureClass,
  TriggerClass,
} from "./intentBreakdown";
import {
  COUPLED_SEPARATORS,
  DIRECTION_LONG,
  DIRECTION_NEUTRAL,
  DIRECTION_SHORT,
  OBJECTIVE_CLOSE,
  OBJECTIVE_HEDGE,
  OBJECTIVE_OPEN,
  OBJECTIVE_REBALANCE,
  OBJECTIVE_RELATIVE,
  PORTFOLIO_SCOPE,
  POSITION_REF,
  RISK_TIGHT_STOPS,
  TRIGGER_EVENT,
  TRIGGER_PRICE,
  TRIGGER_SCHEDULED,
} from "./intentLexicon";
import { isUnsupportedObjective } from "./intentQualify";

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function wordBoundaryMatch(text: string, term: string): boolean {
  const pattern = new RegExp(
    `(?:^|[\\s,.;:!?'"([{])${escapeRegExp(term.toLowerCase())}(?:$|[\\s,.;:!?'")\\]}])`,
    "i",
  );
  return pattern.test(text.toLowerCase());
}

function hasAnyTerm(text: string, terms: readonly string[]): boolean {
  const normalized = text.toLowerCase();
  return terms.some(
    (term) =>
      wordBoundaryMatch(normalized, term) || normalized.includes(term.toLowerCase()),
  );
}

function firstMatchingTerm(text: string, terms: readonly string[]): string | null {
  for (const term of terms) {
    if (wordBoundaryMatch(text, term) || text.toLowerCase().includes(term.toLowerCase())) {
      return term;
    }
  }
  return null;
}

export function extractObjective(text: string): ResolvedFacet<ObjectiveClass> {
  if (isUnsupportedObjective(text)) {
    return {
      confidence: "resolved",
      value: "unsupported",
      label: "Liquidity / yield / options",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, OBJECTIVE_RELATIVE)) {
    const term = firstMatchingTerm(text, OBJECTIVE_RELATIVE);
    return {
      confidence: "resolved",
      value: "relative-value",
      label: term ?? "relative value",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, OBJECTIVE_HEDGE)) {
    return {
      confidence: "resolved",
      value: "hedge",
      label: "hedge",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, OBJECTIVE_REBALANCE)) {
    return {
      confidence: "resolved",
      value: "rebalance-allocate",
      label: "rebalance / allocate",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, OBJECTIVE_CLOSE) || hasAnyTerm(text, POSITION_REF)) {
    return {
      confidence: "resolved",
      value: "close-reduce",
      label: "close / reduce",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, OBJECTIVE_OPEN)) {
    const term = firstMatchingTerm(text, OBJECTIVE_OPEN);
    return {
      confidence: "resolved",
      value: "open",
      label: term ?? "open",
      source: "nl",
    };
  }
  return {
    confidence: "missing",
    value: null,
    label: "—",
    source: "nl",
  };
}

const ASSET_NL_ALIASES: Record<string, string[]> = {
  BTC: ["bitcoin"],
  ETH: ["ethereum", "ether"],
  SOL: ["solana"],
};

export function extractNlAssets(text: string): string[] {
  const found: string[] = [];
  const normalized = text.toLowerCase();
  for (const [base, aliases] of Object.entries(ASSET_NL_ALIASES)) {
    if (
      wordBoundaryMatch(normalized, base.toLowerCase()) ||
      aliases.some((a) => wordBoundaryMatch(normalized, a))
    ) {
      found.push(base);
    }
  }
  return found;
}

function hasNlAsset(text: string): boolean {
  return extractNlAssets(text).length > 0;
}

export function extractStructure(text: string): ResolvedFacet<StructureClass> {
  const tickers = extractTickerMentions(text);
  const nlAssets = extractNlAssets(text);
  const allAssets = [...new Set([...tickers.map((t) => t.toUpperCase()), ...nlAssets])];
  const hasPortfolioScope = hasAnyTerm(text, PORTFOLIO_SCOPE);
  const isCoupled = COUPLED_SEPARATORS.some((re) => re.test(text));

  if (hasPortfolioScope) {
    return {
      confidence: "resolved",
      value: "portfolio-scope",
      label: "portfolio scope",
      source: "nl",
    };
  }

  if (isCoupled && allAssets.length >= 2) {
    return {
      confidence: "resolved",
      value: "coupled-pair",
      label: "coupled pair",
      source: "nl",
    };
  }

  if (allAssets.length > 1) {
    return {
      confidence: "multiple",
      value: "basket",
      label: `${allAssets.length} assets`,
      source: tickers.length ? "mention" : "nl",
      candidates: allAssets,
    };
  }

  if (/\band\b/i.test(text)) {
    const parts = text.split(/\band\b/i);
    const partAssets = parts.flatMap((p) => [
      ...extractTickerMentions(p).map((t) => t.toUpperCase()),
      ...extractNlAssets(p),
    ]);
    const unique = [...new Set(partAssets)];
    if (unique.length >= 2) {
      return {
        confidence: "multiple",
        value: "basket",
        label: "multi-independent",
        source: "nl",
        candidates: unique,
      };
    }
  }

  if (allAssets.length === 1) {
    return {
      confidence: "resolved",
      value: "single",
      label: "single",
      source: tickers.length ? "mention" : "nl",
    };
  }

  return {
    confidence: "missing",
    value: null,
    label: "—",
    source: "nl",
  };
}

export function extractAssets(text: string): ResolvedFacet<string[]> {
  const tickers = extractTickerMentions(text).map((t) => t.toUpperCase());
  const nlAssets = extractNlAssets(text);
  const merged = [...new Set([...tickers, ...nlAssets])];

  if (merged.length > 1) {
    return {
      confidence: "multiple",
      value: merged,
      label: merged.join(", "),
      source: tickers.length ? "mention" : "nl",
      candidates: merged,
    };
  }
  if (merged.length === 1) {
    return {
      confidence: "resolved",
      value: merged,
      label: merged[0]!,
      source: tickers.length ? "mention" : "nl",
    };
  }

  if (hasAnyTerm(text, PORTFOLIO_SCOPE)) {
    return {
      confidence: "resolved",
      value: ["portfolio"],
      label: "portfolio",
      source: "nl",
    };
  }

  if (hasAnyTerm(text, POSITION_REF)) {
    return {
      confidence: "defaulted",
      value: [],
      label: "existing positions",
      source: "inferred",
    };
  }

  return {
    confidence: "missing",
    value: null,
    label: "—",
    source: "nl",
  };
}

export function extractDirection(
  text: string,
  objective: ObjectiveClass | null,
): ResolvedFacet<DirectionClass> {
  if (hasAnyTerm(text, DIRECTION_LONG)) {
    return {
      confidence: "resolved",
      value: "long",
      label: "long",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, DIRECTION_SHORT)) {
    return {
      confidence: "resolved",
      value: "short",
      label: "short",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, DIRECTION_NEUTRAL)) {
    return {
      confidence: "resolved",
      value: "market-neutral",
      label: "market-neutral",
      source: "nl",
    };
  }

  if (objective === "hedge") {
    return {
      confidence: "defaulted",
      value: "market-neutral",
      label: "market-neutral",
      source: "inferred",
    };
  }
  if (objective === "open") {
    return {
      confidence: "defaulted",
      value: "long",
      label: "long (default)",
      source: "inferred",
    };
  }
  if (objective === "close-reduce") {
    return {
      confidence: "defaulted",
      value: null,
      label: "agent discretion",
      source: "inferred",
    };
  }

  return {
    confidence: "missing",
    value: null,
    label: "—",
    source: "nl",
  };
}

export function extractTrigger(text: string): ResolvedFacet<TriggerClass> {
  if (hasAnyTerm(text, TRIGGER_SCHEDULED)) {
    return {
      confidence: "resolved",
      value: "scheduled",
      label: "scheduled (DCA/TWAP)",
      source: "nl",
    };
  }
  if (hasAnyTerm(text, TRIGGER_EVENT)) {
    const hasEventDetail = TRIGGER_EVENT.some((e) =>
      wordBoundaryMatch(text, e),
    );
    return {
      confidence: hasEventDetail ? "resolved" : "ambiguous",
      value: "event-conditional",
      label: "event-conditional",
      source: "nl",
    };
  }
  const priceSignals = TRIGGER_PRICE.filter((t) => wordBoundaryMatch(text, t));
  const hasPriceValue =
    /\d+(?:\.\d+)?%/.test(text) ||
    /\$[\d,]+/.test(text) ||
    /\bat\s+\d+/i.test(text);
  if (priceSignals.length > 0 || hasPriceValue) {
    return {
      confidence: hasPriceValue ? "resolved" : "ambiguous",
      value: "price-conditional",
      label: "price-conditional",
      source: "nl",
    };
  }
  return {
    confidence: "resolved",
    value: "immediate",
    label: "immediate (market)",
    source: "nl",
  };
}

export function extractRisk(text: string): ResolvedFacet<RiskConstraints> {
  const risk: RiskConstraints = {};
  let hasExplicit = false;

  const levMatch = text.match(/\b(\d{1,2})x\b/i);
  if (levMatch) {
    risk.leverage = parseInt(levMatch[1]!, 10);
    hasExplicit = true;
  }

  const sizePctMatch = text.match(/\b(\d{1,3})%\b/);
  if (sizePctMatch) {
    risk.sizePct = parseInt(sizePctMatch[1]!, 10);
    hasExplicit = true;
  }

  const slMatch = text.match(/\bstop(?:\s*loss)?\s*(?:at\s*)?(\d+(?:\.\d+)?)/i);
  if (slMatch) {
    risk.stopLoss = parseFloat(slMatch[1]!);
    hasExplicit = true;
  }

  const tpMatch = text.match(/\btake[\s-]?profit\s*(?:at\s*)?(\d+(?:\.\d+)?)/i);
  if (tpMatch) {
    risk.takeProfit = parseFloat(tpMatch[1]!);
    hasExplicit = true;
  }

  if (hasAnyTerm(text, RISK_TIGHT_STOPS)) {
    risk.stopLoss = null;
    hasExplicit = true;
  }

  if (/\breduce[\s-]?only\b/i.test(text)) {
    risk.reduceOnly = true;
    hasExplicit = true;
  }

  if (!hasExplicit) {
    return {
      confidence: "defaulted",
      value: { leverage: null, sizePct: null, stopLoss: null },
      label: "defaults apply",
      source: "inferred",
    };
  }

  return {
    confidence: "resolved",
    value: risk,
    label: "explicit constraints",
    source: "nl",
  };
}

export function extractAgentsFromText(
  text: string,
  agents: TradingAgent[],
): ResolvedFacet<string[]> {
  const mentions = extractAgentMentions(text);
  if (mentions.length > 1) {
    return {
      confidence: "multiple",
      value: mentions,
      label: mentions.join(", "),
      source: "mention",
      candidates: mentions,
    };
  }
  if (mentions.length === 1) {
    return {
      confidence: "resolved",
      value: mentions,
      label: mentions[0]!,
      source: "mention",
    };
  }
  return {
    confidence: "missing",
    value: null,
    label: "—",
    source: "nl",
  };
}

export function extractScope(
  text: string,
  bucketLabel?: string,
): ResolvedFacet<string> {
  if (hasAnyTerm(text, PORTFOLIO_SCOPE)) {
    const term = firstMatchingTerm(text, PORTFOLIO_SCOPE);
    return {
      confidence: "resolved",
      value: term ?? "portfolio",
      label: term ?? "portfolio",
      source: "nl",
    };
  }
  if (bucketLabel) {
    return {
      confidence: "defaulted",
      value: bucketLabel,
      label: bucketLabel,
      source: "context",
    };
  }
  return {
    confidence: "defaulted",
    value: "default",
    label: "active bucket",
    source: "context",
  };
}

export function deriveArchetype(
  objective: ObjectiveClass | null,
  structure: StructureClass | null,
  trigger: TriggerClass | null,
  sticky?: IntentArchetype,
): IntentArchetype {
  if (sticky && sticky !== "unsupported") return sticky;
  if (objective === "unsupported") return "unsupported";
  if (trigger === "event-conditional") return "conditional";
  if (structure === "portfolio-scope") return "portfolio";
  if (structure === "coupled-pair" || objective === "relative-value") {
    return "relational";
  }
  if (structure === "basket") return "portfolio";
  if (objective === "rebalance-allocate") return "portfolio";
  if (objective === "hedge" && structure === "coupled-pair") return "relational";
  return "directional";
}

export function deriveCompositeLegs(
  text: string,
  tickers: string[],
): CompositeLeg[] | undefined {
  if (tickers.length < 2) return undefined;
  const legs: CompositeLeg[] = [];
  const lower = text.toLowerCase();

  for (const ticker of tickers) {
    const idx = lower.indexOf(ticker.toLowerCase());
    const before = lower.slice(Math.max(0, idx - 20), idx);
    let direction: DirectionClass = "long";
    if (/\bshort\b/.test(before)) direction = "short";
    else if (/\blong\b/.test(before)) direction = "long";
    legs.push({ direction, baseAsset: ticker.toUpperCase() });
  }
  return legs;
}

export function classifyFacets(
  text: string,
  agents: TradingAgent[],
  bucketLabel?: string,
): import("./intentBreakdown").IntentFacetSlots {
  const objective = extractObjective(text);
  const structure = extractStructure(text);
  const direction = extractDirection(text, objective.value);
  const trigger = extractTrigger(text);
  const risk = extractRisk(text);
  const agentFacet = extractAgentsFromText(text, agents);
  const assets = extractAssets(text);
  const scope = extractScope(text, bucketLabel);

  return {
    objective,
    structure,
    direction,
    trigger,
    risk,
    agents: agentFacet,
    assets,
    scope,
  };
}
