import { mockAgentProfiles } from "../../offline/mock_data";
import type { PropertyProfile } from "../../offline/mock_data/types";
import type { ResolvedIndexConstituent } from "./indexConstituents";

export type ConstituentTableRow = {
  agentId: string;
  icon: string;
  ticker: string;
  name: string;
  price: number;
  marketCap: string;
  marketCapSort: number;
  weight: number;
  change24h: number;
  roi1m: number | null;
  roi1y: number | null;
};

export type ConstituentSortField =
  | "price"
  | "marketCap"
  | "weight"
  | "change24h"
  | "roi1m"
  | "roi1y";

function parseMarketCapSort(value: string): number {
  const normalized = value.replace(/[$,]/g, "").trim();
  const match = normalized.match(/^([\d.]+)\s*([KMB])?$/i);
  if (!match) return 0;
  const amount = Number(match[1]);
  if (!Number.isFinite(amount)) return 0;
  const suffix = (match[2] ?? "").toUpperCase();
  if (suffix === "K") return amount * 1_000;
  if (suffix === "M") return amount * 1_000_000;
  if (suffix === "B") return amount * 1_000_000_000;
  return amount;
}

function sparklineRoi(
  values: number[],
  startIndex: number,
  endIndex: number,
): number | null {
  if (values.length < 2) return null;
  const start = values[startIndex];
  const end = values[endIndex];
  if (start == null || end == null || start === 0) return null;
  return ((end - start) / start) * 100;
}

function deriveRoiFromSparkline(sparkline: number[]): {
  roi1m: number | null;
  roi1y: number | null;
} {
  const clean = sparkline.filter((value) => Number.isFinite(value));
  if (clean.length < 2) {
    return { roi1m: null, roi1y: null };
  }
  const last = clean.length - 1;
  const mid = Math.floor(clean.length / 2);
  return {
    roi1m: sparklineRoi(clean, mid, last),
    roi1y: sparklineRoi(clean, 0, last),
  };
}

function lookupAgent(
  agentId: string,
  agentProfiles: PropertyProfile[],
): PropertyProfile | undefined {
  return agentProfiles.find((agent) => agent.id === agentId);
}

export function buildConstituentTableRows(
  constituents: ResolvedIndexConstituent[],
  agentProfiles: PropertyProfile[] = mockAgentProfiles,
): ConstituentTableRow[] {
  return constituents.map((item) => {
    const agent = lookupAgent(item.agentId, agentProfiles);
    const marketCap = agent?.marketCap ?? "—";
    const { roi1m, roi1y } = deriveRoiFromSparkline(agent?.sparkline ?? []);

    return {
      agentId: item.agentId,
      icon: item.icon,
      ticker: item.ticker,
      name: item.name,
      price: agent?.price ?? 0,
      marketCap,
      marketCapSort: parseMarketCapSort(marketCap),
      weight: item.weight,
      change24h: agent?.change24h ?? 0,
      roi1m,
      roi1y,
    };
  });
}

export function getConstituentSortValue(
  row: ConstituentTableRow,
  field: ConstituentSortField,
): number {
  switch (field) {
    case "price":
      return row.price;
    case "marketCap":
      return row.marketCapSort;
    case "weight":
      return row.weight;
    case "change24h":
      return row.change24h;
    case "roi1m":
      return row.roi1m ?? Number.NEGATIVE_INFINITY;
    case "roi1y":
      return row.roi1y ?? Number.NEGATIVE_INFINITY;
  }
}

export function sortConstituentTableRows(
  rows: ConstituentTableRow[],
  field: ConstituentSortField,
  direction: "asc" | "desc",
): ConstituentTableRow[] {
  return [...rows].sort((a, b) => {
    const aValue = getConstituentSortValue(a, field);
    const bValue = getConstituentSortValue(b, field);
    return direction === "asc" ? aValue - bValue : bValue - aValue;
  });
}
