import React, { useCallback, useMemo, useState } from "react";
import type { Bucket } from "../../sdk";
import { formatCurrency } from "../../sdk/utils/display";
import { getBucketCapitalSummary } from "./bucketCapital";
import { useBucketWithdraw } from "./useBucketWithdraw";
import { useBucketClose } from "./useBucketClose";
import BucketCloseConfirmModal from "./BucketCloseConfirmModal";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import "./bucketCollection.css";

export interface BucketManagePanelProps {
  bucket: Bucket;
  bucketId: string;
  baseURL: string;
  walletAddress?: string;
  mnemonic?: string;
  canManage?: boolean;
  editing?: boolean;
  onSaved?: (bucketId: string) => void;
  onCloseModal?: () => void;
  onRequestViewPositions?: (bucketId: string, totalEquity: number) => void;
}

function BucketManagePanel({
  bucket,
  bucketId,
  baseURL,
  walletAddress,
  mnemonic,
  canManage = true,
  editing = true,
  onSaved,
  onCloseModal,
  onRequestViewPositions,
}: BucketManagePanelProps): JSX.Element {
  const capital = getBucketCapitalSummary(bucket);
  const { tasks } = useAgentTasks();
  const { withdrawToSpot, isWithdrawing } = useBucketWithdraw({
    baseURL,
    walletAddress,
    mnemonic,
  });
  const { closeBucket, step, error, isClosing } = useBucketClose({
    baseURL,
    walletAddress,
    mnemonic,
    bucketId,
    withdrawable: capital.withdrawable,
    onComplete: (id) => {
      onSaved?.(id);
      onCloseModal?.();
    },
  });

  const [amount, setAmount] = useState("");
  const [reviewOpen, setReviewOpen] = useState(false);
  const [closeConfirmOpen, setCloseConfirmOpen] = useState(false);

  const bucketTasks = useMemo(
    () =>
      tasks.filter((t) => t.bucketId?.toString() === bucketId.toString()),
    [tasks, bucketId],
  );

  const activeTaskCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "executing" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  const pendingTaskCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "pending" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  const parsedAmount = useMemo(() => {
    const n = Number.parseFloat(amount.replace(/,/g, ""));
    return Number.isFinite(n) ? n : 0;
  }, [amount]);

  const amountValid =
    parsedAmount > 0 && parsedAmount <= capital.withdrawable + 0.001;

  const hasOpenExposure =
    (bucket.usedMargin || 0) > 0 || capital.reservedByOrders > 0;
  const isOffline = isOfflineMode(baseURL);
  const closeBlockedLive = !isOffline && hasOpenExposure;

  const handleMax = useCallback(() => {
    setAmount(capital.withdrawable.toFixed(2));
  }, [capital.withdrawable]);

  const handleReviewWithdraw = useCallback(() => {
    if (!amountValid) return;
    setReviewOpen(true);
  }, [amountValid]);

  const handleConfirmWithdraw = useCallback(async () => {
    if (!amountValid) return;
    await withdrawToSpot(bucketId, parsedAmount);
    setReviewOpen(false);
    setAmount("");
    onSaved?.(bucketId);
  }, [amountValid, withdrawToSpot, bucketId, parsedAmount, onSaved]);

  const handleStartClose = useCallback(() => {
    if (closeBlockedLive) return;
    setCloseConfirmOpen(true);
  }, [closeBlockedLive]);

  const handleConfirmClose = useCallback(async () => {
    setCloseConfirmOpen(false);
    await closeBucket();
  }, [closeBucket]);

  if (!canManage) {
    return (
      <p className="bucket-agents-modal-empty">
        You don&apos;t have permission to manage this bucket.
      </p>
    );
  }

  return (
    <div className="bucket-manage-panel">
      <section className="bucket-manage-section">
        <h4 className="bucket-rules-section-title">Withdraw to spot</h4>
        <dl className="bucket-overview-grid">
          <div className="bucket-overview-row">
            <dt className="terminal-label">Withdrawable now</dt>
            <dd className="terminal-value">{formatCurrency(capital.withdrawable)}</dd>
          </div>
        </dl>
        <label className="bucket-manage-field">
          <span className="terminal-label">Amount</span>
          <div className="bucket-manage-amount-row">
            <input
              type="number"
              className="bucket-manage-input"
              value={amount}
              min={0}
              max={capital.withdrawable}
              step="0.01"
              onChange={(e) => setAmount(e.target.value)}
              disabled={!editing || isWithdrawing}
            />
            <span className="bucket-manage-asset">USDC</span>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleMax}
              disabled={!editing || capital.withdrawable <= 0}
            >
              Max
            </button>
          </div>
        </label>
        <p className="bucket-manage-destination bucket-rules-meta-text">
          Destination: Your spot account (USDC) — fixed
        </p>
        {!reviewOpen ? (
          <button
            type="button"
            className="btn btn-primary"
            onClick={handleReviewWithdraw}
            disabled={!editing || !amountValid || isWithdrawing}
          >
            Review withdrawal
          </button>
        ) : (
          <div className="bucket-manage-review">
            <p className="bucket-rules-meta-text">
              Send {formatCurrency(parsedAmount)} from this bucket to your spot
              account?
            </p>
            <div className="bucket-manage-review-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setReviewOpen(false)}
                disabled={isWithdrawing}
              >
                Back
              </button>
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleConfirmWithdraw}
                disabled={isWithdrawing}
              >
                Confirm withdrawal
              </button>
            </div>
          </div>
        )}
        <p className="bucket-rules-hint bucket-rules-meta-text">
          Locked {formatCurrency(capital.lockedTotal)} stays until positions and
          orders close.
        </p>
      </section>

      <section className="bucket-manage-section">
        <h4 className="bucket-rules-section-title">Close bucket (withdraw everything)</h4>
        <p className="bucket-rules-meta-text">
          This cancels pending intents, disables agents, and returns all free
          capital to spot.
          {!isOffline
            ? " Open positions must be closed first (live mode)."
            : null}
        </p>
        {closeBlockedLive ? (
          <div className="bucket-manage-blocked">
            <p className="bucket-rules-error">
              Close positions and cancel orders before closing this bucket in live
              mode.
            </p>
            {onRequestViewPositions ? (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() =>
                  onRequestViewPositions(bucketId, bucket.totalEquity ?? 0)
                }
              >
                View positions
              </button>
            ) : null}
          </div>
        ) : (
          <>
            {isClosing ? (
              <p className="bucket-manage-progress" role="status" aria-live="polite">
                {step === "locking" && "Locking bucket…"}
                {step === "stopping-agents" && "Stopping agents in this bucket…"}
                {step === "withdrawing" && "Withdrawing free balance…"}
                {step === "clearing" && "Clearing policy and marking dormant…"}
                {step === "done" && "Done."}
                {step === "error" && error}
              </p>
            ) : null}
            <button
              type="button"
              className="btn btn-secondary bucket-close-start-btn"
              onClick={handleStartClose}
              disabled={!editing || isClosing || capital.withdrawable <= 0 && !isOffline}
            >
              Start close
            </button>
          </>
        )}
      </section>

      <BucketCloseConfirmModal
        isOpen={closeConfirmOpen}
        bucket={bucket}
        withdrawable={capital.withdrawable}
        activeTaskCount={activeTaskCount}
        pendingTaskCount={pendingTaskCount}
        onCancel={() => setCloseConfirmOpen(false)}
        onConfirm={handleConfirmClose}
        disabled={isClosing}
      />
    </div>
  );
}

export default React.memo(BucketManagePanel);
