import { useMemo } from "react";
import { useTradeHistory } from "./useTradeHistory";
import { useAgentTasks } from "./useAgentTasks";
import {
  filterTradesForMarket,
  tradesToSeriesMarkers,
  type ChartExecutionMarkerMeta,
} from "../components/finchartview/chartMarkers";
import type { ChartExecutionMarker } from "../components/finchartview/chartMarkers";

export interface UseChartExecutionMarkersConfig {
  baseURL: string;
  walletAddress?: string;
  authToken?: string;
  marketId: string;
  baseAsset?: string;
  interval?: string;
  enabled?: boolean;
  refreshInterval?: number;
}

export interface UseChartExecutionMarkersResult {
  markers: ChartExecutionMarker[];
  metaByTradeId: Map<string, ChartExecutionMarkerMeta>;
  loading: boolean;
}

export function useChartExecutionMarkers(
  config: UseChartExecutionMarkersConfig,
): UseChartExecutionMarkersResult {
  const {
    baseURL,
    walletAddress,
    authToken,
    marketId,
    baseAsset,
    interval = "5m",
    enabled = true,
    refreshInterval,
  } = config;

  const { trades, loading: tradesLoading } = useTradeHistory({
    baseURL,
    walletAddress,
    authToken,
    refreshInterval,
  });

  const { tasks } = useAgentTasks();

  const { markers, metaByTradeId } = useMemo(() => {
    if (!enabled || !marketId) {
      return {
        markers: [] as ChartExecutionMarker[],
        metaByTradeId: new Map<string, ChartExecutionMarkerMeta>(),
      };
    }

    const marketTrades = filterTradesForMarket(trades, marketId, baseAsset);
    return tradesToSeriesMarkers(marketTrades, tasks, interval);
  }, [enabled, marketId, baseAsset, trades, tasks, interval]);

  return {
    markers,
    metaByTradeId,
    loading: enabled && tradesLoading,
  };
}
