import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type JSX,
  type KeyboardEvent,
} from "react";
import type { Market, TradingAgent } from "../../store/types";
import { highlightQueryMatch } from "./highlightQueryMatch";
import { getMentionTrigger, replaceMentionAtCaret } from "./intentMentions";

export { highlightQueryMatch } from "./highlightQueryMatch";

export interface IntentMentionAutocompleteProps {
  text: string;
  caret: number;
  agents: TradingAgent[];
  markets: Market[];
  textareaRef: React.RefObject<HTMLTextAreaElement | null>;
  onTextChange: (value: string, nextCaret: number) => void;
}

function filterAgents(agents: TradingAgent[], query: string): TradingAgent[] {
  const q = query.trim().toLowerCase();
  if (!q) return agents.slice(0, 8);
  return agents
    .filter((a) => {
      const haystack = `${a.displayName} ${a.id} ${a.riskScore ?? ""} ${a.status}`.toLowerCase();
      return haystack.includes(q);
    })
    .slice(0, 8);
}

function filterMarkets(markets: Market[], query: string): Market[] {
  const q = query.trim().toUpperCase();
  if (!q) return markets.slice(0, 8);
  return markets
    .filter((m) => {
      const base = m.baseAsset?.toUpperCase() ?? "";
      const sym = m.symbol?.toUpperCase() ?? "";
      const mon = m.moniker?.toUpperCase() ?? "";
      return base.includes(q) || sym.includes(q) || mon.includes(q);
    })
    .slice(0, 8);
}

export function IntentMentionAutocomplete({
  text,
  caret,
  agents,
  markets,
  textareaRef,
  onTextChange,
}: IntentMentionAutocompleteProps): JSX.Element | null {
  const [activeIndex, setActiveIndex] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);

  const trigger = useMemo(
    () => getMentionTrigger(text, caret),
    [text, caret],
  );

  const options = useMemo(() => {
    if (!trigger) return [];
    if (trigger.kind === "agent") {
      return filterAgents(agents, trigger.query).map((agent) => ({
        id: agent.id,
        label: agent.displayName,
        meta: [agent.riskScore, agent.status].filter(Boolean).join(" · "),
        insertText: `@${agent.displayName}`,
      }));
    }
    return filterMarkets(markets, trigger.query).map((market) => ({
      id: market.index ?? market.marketIndex ?? market.symbol,
      label: market.baseAsset?.toUpperCase() ?? market.symbol,
      meta: market.symbol ?? market.moniker ?? "",
      insertText: `$${market.baseAsset?.toUpperCase() ?? market.symbol}`,
    }));
  }, [trigger, agents, markets]);

  useEffect(() => {
    setActiveIndex(0);
  }, [trigger?.kind, trigger?.query, options.length]);

  const selectOption = useCallback(
    (insertText: string) => {
      const el = textareaRef.current;
      const caretPos = el?.selectionStart ?? caret;
      const { nextText, nextCaret } = replaceMentionAtCaret(
        text,
        caretPos,
        insertText,
      );
      onTextChange(nextText, nextCaret);
      requestAnimationFrame(() => {
        el?.focus();
        el?.setSelectionRange(nextCaret, nextCaret);
      });
    },
    [caret, onTextChange, text, textareaRef],
  );

  if (!trigger || options.length === 0) return null;

  return (
    <div
      ref={listRef}
      className="intent-mention-autocomplete"
      role="listbox"
      aria-label={trigger.kind === "agent" ? "Agent suggestions" : "Market suggestions"}
      aria-live="polite"
    >
      {options.map((option, index) => (
        <button
          key={option.id}
          type="button"
          role="option"
          aria-selected={index === activeIndex}
          id={`intent-mention-option-${option.id}`}
          className={`intent-mention-option${index === activeIndex ? " is-active" : ""}`}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => selectOption(option.insertText)}
          onMouseEnter={() => setActiveIndex(index)}
        >
          <span className="intent-mention-option-label">
            {highlightQueryMatch(option.label, trigger.query)}
          </span>
          {option.meta ? (
            <span className="intent-mention-option-meta">
              {highlightQueryMatch(option.meta, trigger.query)}
            </span>
          ) : null}
        </button>
      ))}
    </div>
  );
}

export function useIntentMentionKeyDown(
  text: string,
  caret: number,
  agents: TradingAgent[],
  markets: Market[],
  textareaRef: React.RefObject<HTMLTextAreaElement | null>,
  onTextChange: (value: string, nextCaret: number) => void,
): (event: KeyboardEvent<HTMLTextAreaElement>) => boolean {
  const trigger = useMemo(
    () => getMentionTrigger(text, caret),
    [text, caret],
  );

  const options = useMemo(() => {
    if (!trigger) return [];
    if (trigger.kind === "agent") {
      return filterAgents(agents, trigger.query);
    }
    return filterMarkets(markets, trigger.query);
  }, [trigger, agents, markets]);

  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    setActiveIndex(0);
  }, [trigger?.kind, trigger?.query]);

  return useCallback(
    (event: KeyboardEvent<HTMLTextAreaElement>) => {
      if (!trigger || options.length === 0) return false;

      if (event.key === "ArrowDown") {
        event.preventDefault();
        setActiveIndex((prev) => Math.min(prev + 1, options.length - 1));
        return true;
      }
      if (event.key === "ArrowUp") {
        event.preventDefault();
        setActiveIndex((prev) => Math.max(prev - 1, 0));
        return true;
      }
      if (event.key === "Enter" || event.key === "Tab") {
        event.preventDefault();
        const el = textareaRef.current;
        const caretPos = el?.selectionStart ?? caret;
        const pick = options[activeIndex];
        if (!pick) return true;
        const insertText =
          trigger.kind === "agent"
            ? `@${(pick as TradingAgent).displayName}`
            : `$${((pick as Market).baseAsset ?? "").toUpperCase()}`;
        const { nextText, nextCaret } = replaceMentionAtCaret(
          text,
          caretPos,
          insertText,
        );
        onTextChange(nextText, nextCaret);
        requestAnimationFrame(() => {
          el?.focus();
          el?.setSelectionRange(nextCaret, nextCaret);
        });
        return true;
      }
      return false;
    },
    [
      activeIndex,
      caret,
      onTextChange,
      options,
      text,
      textareaRef,
      trigger,
    ],
  );
}
