import type { MockBucket } from "./bucketdata";
import { getCopyMirrorBucketRealizedDelta } from "./copyMirrorState";
import { mockWalletState } from "./demoData";
import { mockHashId } from "./mockHashId";

const SATOSHI = 100_000_000;
const STORAGE_PREFIX = "offline_demo_buckets:v1:";
const MAX_SETTLED_TRANSFER_IDS = 20;

type DemoBucketShard = {
  buckets: MockBucket[];
  spotDebit: number;
  spotDelta: Record<string, number>;
  bucketEquityDelta: Record<string, number>;
  bucketStatusOverride: Record<string, string>;
  createBucketSeq: number;
  settledTransferIds: string[];
};

const bucketListeners = new Set<() => void>();

function emptyShard(): DemoBucketShard {
  return {
    buckets: [],
    spotDebit: 0,
    spotDelta: {},
    bucketEquityDelta: {},
    bucketStatusOverride: {},
    createBucketSeq: 0,
    settledTransferIds: [],
  };
}

function normalizeWallet(wallet: string): string {
  return wallet.trim().toLowerCase();
}

function normalizeAsset(asset: string): string {
  return asset.trim().toUpperCase();
}

function normalizeMarginType(marginType: string): "cross" | "isolated" {
  return marginType.trim().toLowerCase() === "isolated" ? "isolated" : "cross";
}

function collateralAssetToIndex(asset: string): string {
  const normalized = normalizeAsset(asset);
  if (normalized === "USDT") return "2";
  return "1";
}

function storageKey(wallet: string): string {
  return `${STORAGE_PREFIX}${normalizeWallet(wallet)}`;
}

function notifyBucketListeners(): void {
  bucketListeners.forEach((listener) => listener());
}

function parseRecordOfNumbers(
  value: unknown,
): Record<string, number> {
  if (!value || typeof value !== "object") return {};
  return Object.fromEntries(
    Object.entries(value).filter(([, entry]) => typeof entry === "number"),
  );
}

function parseRecordOfStrings(
  value: unknown,
): Record<string, string> {
  if (!value || typeof value !== "object") return {};
  return Object.fromEntries(
    Object.entries(value).filter(
      ([, entry]) => typeof entry === "string" && entry.trim() !== "",
    ),
  );
}

function loadShard(wallet: string): DemoBucketShard {
  if (typeof localStorage === "undefined") {
    return emptyShard();
  }
  try {
    const raw = localStorage.getItem(storageKey(wallet));
    if (!raw) return emptyShard();
    const parsed = JSON.parse(raw) as Partial<DemoBucketShard>;
    return {
      buckets: Array.isArray(parsed.buckets) ? parsed.buckets : [],
      spotDebit: typeof parsed.spotDebit === "number" ? parsed.spotDebit : 0,
      spotDelta: parseRecordOfNumbers(parsed.spotDelta),
      bucketEquityDelta: parseRecordOfNumbers(parsed.bucketEquityDelta),
      bucketStatusOverride: parseRecordOfStrings(parsed.bucketStatusOverride),
      createBucketSeq:
        typeof parsed.createBucketSeq === "number" ? parsed.createBucketSeq : 0,
      settledTransferIds: Array.isArray(parsed.settledTransferIds)
        ? parsed.settledTransferIds.filter((id) => typeof id === "string")
        : [],
    };
  } catch {
    return emptyShard();
  }
}

function saveShard(wallet: string, shard: DemoBucketShard): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(storageKey(wallet), JSON.stringify(shard));
}

function toSatoshiStr(value: number): string {
  return String(Math.round(value * SATOSHI));
}

function fromSatoshiStr(value: string): number {
  return Number(value) / SATOSHI;
}

function seedBalance(asset: string): number {
  return mockWalletState.balances[normalizeAsset(asset)] ?? 0;
}

function generateDemoTxHash(prefix: string): string {
  const hex = Date.now().toString(16).padStart(8, "0");
  return `0x${prefix}${hex}${"a".repeat(24)}`.slice(0, 42);
}

export function buildDemoCopyBucketId(
  wallet: string,
  catalogAgentId: string,
): string {
  return mockHashId(
    `offline:copy-bucket:${normalizeWallet(wallet)}:${catalogAgentId.trim().toLowerCase()}`,
  );
}

export function buildDemoCreatedBucketId(
  wallet: string,
  marginType: "cross" | "isolated",
  collateralAssetIndex: string,
  seq: number,
): string {
  return mockHashId(
    `offline:created-bucket:${normalizeWallet(wallet)}:${marginType}:${collateralAssetIndex}:${seq}`,
  );
}

export type AddDemoCopyBucketParams = {
  bucketId: string;
  startingMargin: number;
  catalogAgentId: string;
};

export type AddDemoCreatedBucketParams = {
  marginType: "cross" | "isolated";
  collateralAsset: string;
  amount: number;
  fundFrom: "spot-wallet" | string;
  reuseBucketId?: string;
  /** Portfolio/runtime base equity for fundFrom when not spot-wallet. */
  sourceBucketBaseEquity?: number;
};

export type DemoCreateBucketResult = {
  bucketId: string;
  marginType: "cross" | "isolated";
  collateralAsset: string;
  amount: number;
  fundFrom: "spot-wallet" | string;
  bucketMode: "new" | "reused";
  txHash: string;
  fundTxHash?: string;
};

export type DemoCrossChainSettlementParams = {
  transferId: string;
  mode: "deposit" | "withdraw";
  assetId: string;
  amount: number;
};

function getEffectiveBucketEquity(
  wallet: string,
  bucketId: string,
  baseEquity: number,
): number {
  const shard = loadShard(normalizeWallet(wallet));
  const delta = shard.bucketEquityDelta[bucketId] ?? 0;
  return Math.max(0, baseEquity + delta);
}

function resolveRuntimeBucketEquity(
  shard: DemoBucketShard,
  bucketId: string,
): number {
  const runtime = shard.buckets.find((entry) => entry.bucketId === bucketId);
  if (!runtime) return 0;
  const base = fromSatoshiStr(runtime.totalEquity);
  const delta = shard.bucketEquityDelta[bucketId] ?? 0;
  return Math.max(0, base + delta);
}

function applyFundFromBucket(
  shard: DemoBucketShard,
  wallet: string,
  fundFrom: string,
  amount: number,
  sourceBucketBaseEquity?: number,
): void {
  if (amount <= 0) return;

  const runtimeEquity = resolveRuntimeBucketEquity(shard, fundFrom);
  const baseEquity =
    runtimeEquity > 0 ? runtimeEquity : (sourceBucketBaseEquity ?? 0);
  const available = getEffectiveBucketEquity(wallet, fundFrom, baseEquity);
  if (available < amount) {
    throw new Error("Insufficient funds in source bucket");
  }

  shard.bucketEquityDelta = {
    ...shard.bucketEquityDelta,
    [fundFrom]: (shard.bucketEquityDelta[fundFrom] ?? 0) - amount,
  };
}

function applyFundFromSpot(shard: DemoBucketShard, amount: number): void {
  if (amount <= 0) return;
  shard.spotDebit += amount;
}

/** Persist a user-created margin bucket (transfer modal) and apply demo funding. */
export function addDemoCreatedBucket(
  wallet: string,
  params: AddDemoCreatedBucketParams,
): DemoCreateBucketResult {
  if (!wallet?.trim()) {
    throw new Error("Wallet address is required");
  }

  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  const marginType = normalizeMarginType(params.marginType);
  const collateralAsset = normalizeAsset(params.collateralAsset);
  const collateralAssetIndex = collateralAssetToIndex(collateralAsset);
  const amount = Number.isFinite(params.amount) ? Math.max(0, params.amount) : 0;
  const fundFrom = params.fundFrom?.trim() || "spot-wallet";

  if (amount > 0 && fundFrom === "spot-wallet") {
    const available = getEffectiveMockBalance(normalizedWallet, collateralAsset);
    if (available < amount) {
      throw new Error("Insufficient spot wallet balance");
    }
  }

  if (amount > 0 && fundFrom !== "spot-wallet") {
    applyFundFromBucket(
      shard,
      normalizedWallet,
      fundFrom,
      amount,
      params.sourceBucketBaseEquity,
    );
  }

  const txHash = generateDemoTxHash("cb");
  let fundTxHash: string | undefined;
  let bucketId: string;
  let bucketMode: "new" | "reused";

  if (params.reuseBucketId?.trim()) {
    bucketId = params.reuseBucketId.trim();
    bucketMode = "reused";
    shard.bucketStatusOverride = {
      ...shard.bucketStatusOverride,
      [bucketId]: "active",
    };
    if (amount > 0) {
      shard.bucketEquityDelta = {
        ...shard.bucketEquityDelta,
        [bucketId]: (shard.bucketEquityDelta[bucketId] ?? 0) + amount,
      };
    }
  } else {
    const seq = shard.createBucketSeq + 1;
    shard.createBucketSeq = seq;
    bucketId = buildDemoCreatedBucketId(
      normalizedWallet,
      marginType,
      collateralAssetIndex,
      seq,
    );
    bucketMode = "new";

    const bucket: MockBucket = {
      bucketId,
      totalEquity: toSatoshiStr(amount),
      marginType,
      collateralAssetIndex,
      status: "active",
    };

    const withoutDup = shard.buckets.filter(
      (entry) => entry.bucketId !== bucketId,
    );
    shard.buckets = [...withoutDup, bucket];
  }

  if (amount > 0 && fundFrom === "spot-wallet") {
    applyFundFromSpot(shard, amount);
    fundTxHash = generateDemoTxHash("fd");
  } else if (amount > 0 && fundFrom !== "spot-wallet") {
    fundTxHash = generateDemoTxHash("bt");
  }

  saveShard(normalizedWallet, shard);
  notifyBucketListeners();

  return {
    bucketId,
    marginType,
    collateralAsset,
    amount,
    fundFrom,
    bucketMode,
    txHash,
    ...(fundTxHash ? { fundTxHash } : {}),
  };
}

/** Persist a cross-margin copy bucket and debit spot for demo funding. */
export function addDemoCopyBucket(
  wallet: string,
  params: AddDemoCopyBucketParams,
): MockBucket {
  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  const bucket: MockBucket = {
    bucketId: params.bucketId,
    totalEquity: toSatoshiStr(params.startingMargin),
    marginType: "cross",
    collateralAssetIndex: "1",
    status: "active",
  };

  const withoutDup = shard.buckets.filter(
    (entry) => entry.bucketId !== params.bucketId,
  );
  const previous = shard.buckets.find(
    (entry) => entry.bucketId === params.bucketId,
  );
  const previousEquity = previous
    ? Number(previous.totalEquity) / SATOSHI
    : 0;

  shard.buckets = [...withoutDup, bucket];
  shard.spotDebit =
    shard.spotDebit - previousEquity + params.startingMargin;
  saveShard(normalizedWallet, shard);
  notifyBucketListeners();
  return bucket;
}

/** Apply demo ledger deltas/overrides when reading portfolio buckets. */
export function applyDemoBucketAdjustments(
  wallet: string | null | undefined,
  bucket: MockBucket,
): MockBucket {
  if (!wallet?.trim()) return bucket;
  const shard = loadShard(normalizeWallet(wallet));
  const equityDelta = shard.bucketEquityDelta[bucket.bucketId] ?? 0;
  const copyRealized = getCopyMirrorBucketRealizedDelta(wallet, bucket.bucketId);
  const statusOverride = shard.bucketStatusOverride[bucket.bucketId];
  const baseEquity = fromSatoshiStr(bucket.totalEquity);
  const adjustedEquity = Math.max(0, baseEquity + equityDelta + copyRealized);

  return {
    ...bucket,
    totalEquity: toSatoshiStr(adjustedEquity),
    ...(statusOverride ? { status: statusOverride } : {}),
  };
}

/** Per-bucket equity delta from demo transfers/create flows. */
export function getDemoBucketEquityDelta(
  wallet: string | null | undefined,
  bucketId: string,
): number {
  if (!wallet?.trim()) return 0;
  return loadShard(normalizeWallet(wallet)).bucketEquityDelta[bucketId] ?? 0;
}

/** Demo copy buckets appended at runtime (persisted per wallet). */
export function getDemoBucketOverrides(wallet?: string | null): MockBucket[] {
  if (!wallet?.trim()) return [];
  const shard = loadShard(normalizeWallet(wallet));
  return shard.buckets.map((bucket) => ({ ...bucket }));
}

/** Total spot USDC debited for demo copy bucket funding. */
export function getDemoSpotDebit(wallet?: string | null): number {
  if (!wallet?.trim()) return 0;
  return loadShard(normalizeWallet(wallet)).spotDebit;
}

/** Per-asset spot delta from demo cross-chain settlements. */
export function getDemoSpotDelta(
  wallet: string | null | undefined,
  asset: string,
): number {
  if (!wallet?.trim()) return 0;
  const key = normalizeAsset(asset);
  return loadShard(normalizeWallet(wallet)).spotDelta[key] ?? 0;
}

/** Effective spot balance: seed + cross-chain delta - copy-bucket USDC debit. */
export function getEffectiveMockBalance(
  wallet: string | null | undefined,
  asset: string,
): number {
  if (!wallet?.trim()) return seedBalance(asset);
  const normalizedAsset = normalizeAsset(asset);
  const shard = loadShard(normalizeWallet(wallet));
  const delta = shard.spotDelta[normalizedAsset] ?? 0;
  const debit = normalizedAsset === "USDC" ? shard.spotDebit : 0;
  return Math.max(0, seedBalance(normalizedAsset) + delta - debit);
}

/** Apply demo cross-chain deposit credit or withdraw debit to the wallet ledger. */
export function applyDemoCrossChainSettlement(
  wallet: string,
  params: DemoCrossChainSettlementParams,
): boolean {
  if (!wallet?.trim() || !params.transferId?.trim()) return false;
  if (!Number.isFinite(params.amount) || params.amount <= 0) return false;

  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  if (shard.settledTransferIds.includes(params.transferId)) {
    return false;
  }

  const asset = normalizeAsset(params.assetId);
  const current = getEffectiveMockBalance(normalizedWallet, asset);
  const signedDelta = params.mode === "deposit" ? params.amount : -params.amount;

  if (params.mode === "withdraw") {
    const next = current + signedDelta;
    if (next < 0) return false;
  }

  const previousDelta = shard.spotDelta[asset] ?? 0;
  shard.spotDelta = {
    ...shard.spotDelta,
    [asset]: previousDelta + signedDelta,
  };
  shard.settledTransferIds = [
    params.transferId,
    ...shard.settledTransferIds,
  ].slice(0, MAX_SETTLED_TRANSFER_IDS);
  saveShard(normalizedWallet, shard);
  notifyBucketListeners();
  return true;
}

export function subscribeDemoBuckets(listener: () => void): () => void {
  bucketListeners.add(listener);
  return () => bucketListeners.delete(listener);
}

/** Test helper: reset demo bucket state for a wallet. */
export function resetDemoBucketState(wallet?: string | null): void {
  if (wallet?.trim()) {
    if (typeof localStorage !== "undefined") {
      localStorage.removeItem(storageKey(normalizeWallet(wallet)));
    }
  }
  notifyBucketListeners();
}

export function isBucketClosing(
  wallet: string | null | undefined,
  bucketId: string,
): boolean {
  if (!wallet?.trim()) return false;
  const override =
    loadShard(normalizeWallet(wallet)).bucketStatusOverride[bucketId];
  return override === "closing" || override === "draining";
}

export type DemoWithdrawFromBucketParams = {
  bucketId: string;
  amount: number;
  transferId: string;
};

export type DemoWithdrawFromBucketResult = {
  amount: number;
  txHash: string;
};

/** Demo bucket → spot withdraw; idempotent via transferId. */
export function applyDemoWithdrawFromBucket(
  wallet: string,
  params: DemoWithdrawFromBucketParams,
): DemoWithdrawFromBucketResult {
  if (!wallet?.trim()) {
    throw new Error("Wallet address is required");
  }
  if (!params.transferId?.trim()) {
    throw new Error("Transfer id is required");
  }
  const amount = Number.isFinite(params.amount) ? Math.max(0, params.amount) : 0;
  if (amount <= 0) {
    throw new Error("Withdraw amount must be greater than zero");
  }

  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  if (shard.settledTransferIds.includes(params.transferId)) {
    return { amount, txHash: generateDemoTxHash("wd") };
  }

  const available = resolveRuntimeBucketEquity(shard, params.bucketId);
  if (available < amount) {
    throw new Error("Insufficient withdrawable balance in bucket");
  }

  shard.bucketEquityDelta = {
    ...shard.bucketEquityDelta,
    [params.bucketId]:
      (shard.bucketEquityDelta[params.bucketId] ?? 0) - amount,
  };
  shard.spotDebit = Math.max(0, shard.spotDebit - amount);
  shard.settledTransferIds = [
    params.transferId,
    ...shard.settledTransferIds,
  ].slice(0, MAX_SETTLED_TRANSFER_IDS);

  saveShard(normalizedWallet, shard);
  notifyBucketListeners();
  return { amount, txHash: generateDemoTxHash("wd") };
}

export function setDemoBucketClosing(
  wallet: string,
  bucketId: string,
): void {
  if (!wallet?.trim()) return;
  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  shard.bucketStatusOverride = {
    ...shard.bucketStatusOverride,
    [bucketId]: "closing",
  };
  saveShard(normalizedWallet, shard);
  notifyBucketListeners();
}

/** Mark bucket dormant and zero equity after close wizard completes. */
export function applyDemoCloseBucket(
  wallet: string,
  bucketId: string,
): void {
  if (!wallet?.trim()) return;
  const normalizedWallet = normalizeWallet(wallet);
  const shard = loadShard(normalizedWallet);
  const runtime = shard.buckets.find((entry) => entry.bucketId === bucketId);
  const baseEquity = runtime ? fromSatoshiStr(runtime.totalEquity) : 0;
  const delta = shard.bucketEquityDelta[bucketId] ?? 0;
  const effective = Math.max(0, baseEquity + delta);

  if (effective > 0) {
    shard.bucketEquityDelta = {
      ...shard.bucketEquityDelta,
      [bucketId]: delta - effective,
    };
    shard.spotDebit = Math.max(0, shard.spotDebit - effective);
  }

  shard.bucketStatusOverride = {
    ...shard.bucketStatusOverride,
    [bucketId]: "dormant",
  };
  saveShard(normalizedWallet, shard);
  notifyBucketListeners();
}
