import { getAgentProfileById, getAgentProfileByPerpBaseAsset } from "../../../../offline/mock_data/agentProfile";
import type {
  AgentTokenPriceHistoryFile,
  AgentTokenPriceHistoryManifest,
  AgentTokenPriceHistoryManifestAgent,
} from "../../../../offline/mock_data/agentTokenPriceHistory.types";

export const AGENT_TOKEN_MARKET_PREFIX = "agent-token:";

export const AGENT_TOKEN_PRICE_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_AGENT_TOKEN_PRICE_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/agent-token-prices";

export type ResolveCatalogAgentIdInput = {
  catalogAgentId?: string;
  baseAsset?: string;
  ticker?: string;
  marketId?: string;
};

let manifestCache: AgentTokenPriceHistoryManifest | null = null;
let manifestPromise: Promise<AgentTokenPriceHistoryManifest> | null = null;
const historyCache = new Map<string, AgentTokenPriceHistoryFile>();
const historyPromises = new Map<string, Promise<AgentTokenPriceHistoryFile>>();

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function normalizeAgentTicker(ticker: string): string {
  const trimmed = ticker.trim().toUpperCase();
  return trimmed.startsWith("$") ? trimmed : `$${trimmed}`;
}

export function stripAgentTicker(ticker: string): string {
  return normalizeAgentTicker(ticker).slice(1);
}

export function isAgentTokenMarketId(marketId: string): boolean {
  return marketId.trim().toLowerCase().startsWith(AGENT_TOKEN_MARKET_PREFIX);
}

export function catalogAgentIdFromMarketId(marketId: string): string | null {
  const normalized = marketId.trim().toLowerCase();
  if (!normalized.startsWith(AGENT_TOKEN_MARKET_PREFIX)) return null;
  const id = marketId.slice(AGENT_TOKEN_MARKET_PREFIX.length).trim();
  return id || null;
}

export function agentTokenMarketId(catalogAgentId: string): string {
  return `${AGENT_TOKEN_MARKET_PREFIX}${catalogAgentId}`;
}

export function clearAgentTokenPriceCache(): void {
  manifestCache = null;
  manifestPromise = null;
  historyCache.clear();
  historyPromises.clear();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export async function fetchAgentTokenManifest(
  baseUrl: string = AGENT_TOKEN_PRICE_DATA_BASE_URL,
): Promise<AgentTokenPriceHistoryManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<AgentTokenPriceHistoryManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  ).then((manifest) => {
    manifestCache = manifest;
    return manifest;
  }).finally(() => {
    manifestPromise = null;
  });

  return manifestPromise;
}

export function getCachedAgentTokenManifest(): AgentTokenPriceHistoryManifest | null {
  return manifestCache;
}

export function getManifestAgentByCatalogId(
  manifest: AgentTokenPriceHistoryManifest,
  catalogAgentId: string,
): AgentTokenPriceHistoryManifestAgent | undefined {
  const normalized = catalogAgentId.trim().toLowerCase();
  return manifest.agents.find(
    (agent) => agent.catalogAgentId.toLowerCase() === normalized,
  );
}

export function getManifestAgentByTicker(
  manifest: AgentTokenPriceHistoryManifest,
  ticker: string,
): AgentTokenPriceHistoryManifestAgent | undefined {
  const normalized = normalizeAgentTicker(ticker);
  return manifest.agents.find(
    (agent) => normalizeAgentTicker(agent.ticker) === normalized,
  );
}

export function getManifestAgentByBaseAsset(
  manifest: AgentTokenPriceHistoryManifest,
  baseAsset: string,
): AgentTokenPriceHistoryManifestAgent | undefined {
  const normalized = baseAsset.trim().toUpperCase();
  if (!normalized) return undefined;

  const profile = getAgentProfileByPerpBaseAsset(normalized);
  if (profile) {
    const byProfile = getManifestAgentByCatalogId(manifest, profile.id);
    if (byProfile) return byProfile;
  }

  return manifest.agents.find(
    (agent) => stripAgentTicker(agent.ticker) === normalized,
  );
}

export function resolveCatalogAgentId(
  manifest: AgentTokenPriceHistoryManifest | null | undefined,
  input: ResolveCatalogAgentIdInput,
): string | null {
  if (input.catalogAgentId?.trim()) {
    return input.catalogAgentId.trim();
  }

  const fromMarket = input.marketId ? catalogAgentIdFromMarketId(input.marketId) : null;
  if (fromMarket) return fromMarket;

  if (input.baseAsset?.trim()) {
    const profile = getAgentProfileByPerpBaseAsset(input.baseAsset);
    if (profile) return profile.id;
    if (manifest) {
      const byBase = getManifestAgentByBaseAsset(manifest, input.baseAsset);
      if (byBase) return byBase.catalogAgentId;
    }
  }

  if (input.ticker?.trim() && manifest) {
    const byTicker = getManifestAgentByTicker(manifest, input.ticker);
    if (byTicker) return byTicker.catalogAgentId;
  }

  return null;
}

export async function fetchAgentTokenHistory(
  catalogAgentId: string,
  baseUrl: string = AGENT_TOKEN_PRICE_DATA_BASE_URL,
): Promise<AgentTokenPriceHistoryFile> {
  const normalizedId = catalogAgentId.trim();
  const cached = historyCache.get(normalizedId);
  if (cached) return cached;

  const inflight = historyPromises.get(normalizedId);
  if (inflight) return inflight;

  const promise = (async () => {
    const manifest = await fetchAgentTokenManifest(baseUrl);
    const agent = getManifestAgentByCatalogId(manifest, normalizedId);
    if (!agent) {
      throw new Error(`Unknown agent token catalog id: ${normalizedId}`);
    }

    const payload = await fetchJson<AgentTokenPriceHistoryFile>(
      joinBaseUrl(baseUrl, agent.file),
    );
    historyCache.set(normalizedId, payload);
    return payload;
  })().finally(() => {
    historyPromises.delete(normalizedId);
  });

  historyPromises.set(normalizedId, promise);
  return promise;
}

export function isCatalogAgentProfileId(catalogAgentId: string): boolean {
  return Boolean(getAgentProfileById(catalogAgentId));
}
