import React, { useCallback, useEffect, useMemo, useState } from "react";
import type { Bucket } from "../../sdk";
import { ModalTabBar } from "../smartlayout/modal-tab-bar";
import BucketModalShell from "./BucketModalShell";
import BucketAgentsPanel from "./BucketAgentsPanel";
import BucketOverviewPanel from "./BucketOverviewPanel";
import BucketRulesPanel from "./BucketRulesPanel";
import BucketManagePanel from "./BucketManagePanel";
import BucketSafetyRail from "./BucketSafetyRail";
import BucketAutonomyConfirmModal from "./BucketAutonomyConfirmModal";
import {
  BUCKET_DETAIL_TABS,
  type BucketDetailTabId,
} from "./bucketDetailTypes";
import {
  useCopyAgentModalOverlay,
  useOverlayContentLatch,
} from "./useBucketModalOverlay";
import { useBucketRulesEditor } from "./useBucketRulesEditor";
import { useBucketPolicyStore } from "../../store/bucketPolicyStore";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { getBucketCapitalSummary } from "./bucketCapital";
import "../smartlayout/layout.css";
import "./bucketCollection.css";

export interface BucketDetailModalProps {
  isOpen: boolean;
  bucketId: string | null;
  bucket: Bucket | null;
  initialTab?: BucketDetailTabId;
  baseURL: string;
  authToken?: string;
  walletAddress?: string;
  mnemonic?: string;
  canManage?: boolean;
  onClose: () => void;
  onSaved?: (bucketId: string) => void;
  onRequestViewPositions?: (bucketId: string, totalEquity: number) => void;
}

type DetailModalLatch = {
  bucketId: string;
  bucket: Bucket | null;
};

function shortBucketId(bucketId: string): string {
  return bucketId.length > 8 ? `${bucketId.slice(0, 6)}…` : bucketId;
}

function BucketDetailModal({
  isOpen,
  bucketId,
  bucket,
  initialTab = "overview",
  baseURL,
  authToken,
  walletAddress,
  mnemonic,
  canManage = true,
  onClose,
  onSaved,
  onRequestViewPositions,
}: BucketDetailModalProps): JSX.Element | null {
  const [activeTab, setActiveTab] = useState<BucketDetailTabId>("overview");
  const [autonomyConfirmOpen, setAutonomyConfirmOpen] = useState(false);
  const [pauseAllConfirming, setPauseAllConfirming] = useState(false);

  const latchValue: DetailModalLatch | null =
    isOpen && bucketId ? { bucketId, bucket } : null;

  const { latched, clearLatch } = useOverlayContentLatch(isOpen, latchValue);

  const handleAfterUnmount = useCallback(() => {
    clearLatch();
    setActiveTab("overview");
    setAutonomyConfirmOpen(false);
    setPauseAllConfirming(false);
  }, [clearLatch]);

  const overlayOpen = isOpen && Boolean(bucketId);
  const overlay = useCopyAgentModalOverlay(overlayOpen, {
    onAfterUnmount: handleAfterUnmount,
  });

  const displayBucketId = latched?.bucketId ?? bucketId;
  const displayBucket = latched?.bucket ?? bucket;

  useEffect(() => {
    if (isOpen) {
      setActiveTab(initialTab);
    }
  }, [isOpen, initialTab, bucketId]);

  const getPolicy = useBucketPolicyStore((s) => s.getPolicy);
  const bucketPolicy = useMemo(() => {
    if (!displayBucketId) return getPolicy("");
    return (
      useBucketPolicyStore.getState().policies[displayBucketId] ??
      getPolicy(displayBucketId)
    );
  }, [displayBucketId, getPolicy]);

  const rulesEditor = useBucketRulesEditor({
    isActive: isOpen && activeTab === "rules",
    bucketId: displayBucketId,
    bucket: displayBucket,
    onSaved,
  });

  const {
    draft,
    setDraft,
    advancedOpen,
    setAdvancedOpen,
    error,
    saveSuccessMessage,
    bucketTasks,
    impactRows,
    needsYouPreview,
    autoExecutePreview,
    handlePresetSelect,
    handleSave,
    commitSaveAfterConfirm,
    handleReset,
    resetEditor,
  } = rulesEditor;

  const { pauseActiveTasksForBucket, rejectAllPendingForBucket } =
    useAgentTasks();

  const activeTaskCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "executing" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  const pendingInBucketCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "pending" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  const handleClose = useCallback(() => {
    resetEditor();
    setAutonomyConfirmOpen(false);
    setPauseAllConfirming(false);
    onClose();
  }, [onClose, resetEditor]);

  const handleViewPositions = useCallback(
    (id: string, totalEquity: number) => {
      onRequestViewPositions?.(id, totalEquity);
      handleClose();
    },
    [onRequestViewPositions, handleClose],
  );

  const handlePauseBucket = useCallback(() => {
    if (!displayBucketId) return;
    pauseActiveTasksForBucket(displayBucketId);
  }, [displayBucketId, pauseActiveTasksForBucket]);

  const handlePauseAllInBucket = useCallback(() => {
    if (!displayBucketId || activeTaskCount === 0) return;
    if (!pauseAllConfirming) {
      setPauseAllConfirming(true);
      return;
    }
    pauseActiveTasksForBucket(displayBucketId);
    setPauseAllConfirming(false);
  }, [
    displayBucketId,
    activeTaskCount,
    pauseAllConfirming,
    pauseActiveTasksForBucket,
  ]);

  const handleRejectAllPending = useCallback(() => {
    if (!displayBucketId) return;
    if (
      !window.confirm(
        `Reject all ${pendingInBucketCount} pending intent${pendingInBucketCount === 1 ? "" : "s"} in this bucket?`,
      )
    ) {
      return;
    }
    rejectAllPendingForBucket(displayBucketId);
  }, [displayBucketId, pendingInBucketCount, rejectAllPendingForBucket]);

  const handleSaveRules = useCallback(() => {
    const result = handleSave();
    if (result === "needs_confirm") {
      setAutonomyConfirmOpen(true);
    }
  }, [handleSave]);

  const handleConfirmAutonomy = useCallback(() => {
    commitSaveAfterConfirm();
    setAutonomyConfirmOpen(false);
  }, [commitSaveAfterConfirm]);

  const panelClassName = useMemo(() => {
    const preset = draft?.preset ?? bucketPolicy.preset ?? "manual";
    return `bucket-detail-modal-content bucket-rules-modal-content--${preset}`;
  }, [draft?.preset, bucketPolicy.preset]);

  const withdrawable = displayBucket
    ? getBucketCapitalSummary(displayBucket).withdrawable
    : 0;

  if (!overlay.mounted || !displayBucketId) return null;

  const editing = isOpen && !overlay.isClosing && canManage;
  const shortId = shortBucketId(displayBucketId);

  return (
    <BucketModalShell
      overlayOpen={overlayOpen}
      onClose={handleClose}
      overlay={overlay}
      ariaLabel={`Bucket ${shortId}`}
      panelClassName={panelClassName}
    >
      <div className="modal-header bucket-modal-header">
        <h3 className="terminal-panel-title">Bucket {shortId}</h3>
        {overlay.isMobile ? (
          <button
            type="button"
            className="bucket-modal-close"
            onClick={handleClose}
            disabled={overlay.isClosing}
            aria-label="Close"
          >
            ×
          </button>
        ) : null}
      </div>

      <BucketSafetyRail
        policy={draft ?? bucketPolicy}
        activeTaskCount={activeTaskCount}
        canManage={canManage}
        disabled={overlay.isClosing}
        onPauseBucket={handlePauseBucket}
        onGoToManage={() => setActiveTab("manage")}
      />

      <ModalTabBar
        tabs={BUCKET_DETAIL_TABS}
        activeTabId={activeTab}
        onTabChange={setActiveTab}
        disabled={overlay.isClosing}
        aria-label="Bucket detail sections"
      />

      <div className="modal-body bucket-detail-modal-body">
        {activeTab === "overview" && displayBucket ? (
          <BucketOverviewPanel bucket={displayBucket} />
        ) : null}

        {activeTab === "overview" && !displayBucket ? (
          <p className="bucket-agents-modal-empty">
            Bucket details are unavailable.
          </p>
        ) : null}

        {activeTab === "agents" ? (
          <div className="bucket-agents-modal-body">
            <BucketAgentsPanel
              bucketId={displayBucketId}
              baseURL={baseURL}
              authToken={authToken}
              isMobile={overlay.isMobile}
              canManage={canManage}
              editing={editing}
            />
          </div>
        ) : null}

        {activeTab === "rules" && draft ? (
          <BucketRulesPanel
            bucket={displayBucket}
            draft={draft}
            setDraft={setDraft}
            advancedOpen={advancedOpen}
            setAdvancedOpen={setAdvancedOpen}
            error={error}
            saveSuccessMessage={saveSuccessMessage}
            editing={editing}
            onPresetSelect={handlePresetSelect}
            impactRows={impactRows}
            needsYouPreview={needsYouPreview}
            bucketTasks={bucketTasks}
          />
        ) : null}

        {activeTab === "manage" && displayBucket ? (
          <BucketManagePanel
            bucket={displayBucket}
            bucketId={displayBucketId}
            baseURL={baseURL}
            walletAddress={walletAddress}
            mnemonic={mnemonic}
            canManage={canManage}
            editing={editing}
            onSaved={onSaved}
            onCloseModal={handleClose}
            onRequestViewPositions={onRequestViewPositions}
          />
        ) : null}
      </div>

      {activeTab === "rules" ? (
        <div className="modal-footer bucket-rules-modal-footer bucket-modal-footer">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={handleReset}
            disabled={!editing}
          >
            Reset to preset
          </button>
          <div className="bucket-rules-footer-actions">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleClose}
              disabled={overlay.isClosing}
            >
              Cancel
            </button>
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleSaveRules}
              disabled={!editing}
            >
              Save rules
            </button>
          </div>
        </div>
      ) : activeTab === "agents" ? (
        <div className="modal-footer bucket-rules-modal-footer bucket-modal-footer">
          <button
            type="button"
            onClick={handleClose}
            className="btn btn-secondary"
            disabled={overlay.isClosing}
          >
            Close
          </button>
          <div className="bucket-rules-footer-actions">
            {canManage && activeTaskCount > 0 ? (
              <button
                type="button"
                className={`btn btn-secondary bucket-agents-pause-all${
                  pauseAllConfirming ? " bucket-agents-pause-all--confirm" : ""
                }`}
                onClick={handlePauseAllInBucket}
                onBlur={() => setPauseAllConfirming(false)}
                disabled={!editing}
              >
                {pauseAllConfirming
                  ? "Confirm pause all in bucket"
                  : "Pause all in bucket"}
              </button>
            ) : null}
            {canManage && pendingInBucketCount > 0 ? (
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleRejectAllPending}
                disabled={!editing}
              >
                Reject all pending in bucket
              </button>
            ) : null}
          </div>
        </div>
      ) : activeTab === "overview" &&
        onRequestViewPositions &&
        displayBucket ? (
        <div className="modal-footer bucket-modal-footer">
          <button
            type="button"
            onClick={handleClose}
            className="btn btn-secondary"
            disabled={overlay.isClosing}
          >
            Close
          </button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() =>
              handleViewPositions(
                displayBucket.bucketId,
                displayBucket.totalEquity ?? 0,
              )
            }
            disabled={overlay.isClosing}
          >
            View positions
          </button>
        </div>
      ) : (
        <div className="modal-footer bucket-modal-footer">
          <button
            type="button"
            onClick={handleClose}
            className="btn btn-secondary"
            disabled={overlay.isClosing}
          >
            Close
          </button>
        </div>
      )}

      {draft ? (
        <BucketAutonomyConfirmModal
          isOpen={autonomyConfirmOpen}
          draft={draft}
          withdrawable={withdrawable}
          autoExecuteCount={autoExecutePreview}
          totalIntentCount={bucketTasks.length}
          onCancel={() => setAutonomyConfirmOpen(false)}
          onConfirm={handleConfirmAutonomy}
          disabled={overlay.isClosing}
        />
      ) : null}
    </BucketModalShell>
  );
}

export default React.memo(BucketDetailModal);
