import React, { useEffect, useMemo, useState } from "react";
import QRCode from "qrcode";

import MorpheumLogo from "../../ui/MorpheumLogo";
import { formatPercent } from "../indexFormat";
import IndexShareConstituents from "./IndexShareConstituents";
import IndexSharePerformanceChart from "./IndexSharePerformanceChart";
import {
  buildShareChartSeries,
  buildShareUrl,
  formatShareTimestamp,
  getTopShareConstituents,
  type IndexSharePayload,
  SHARE_CARD_WIDTH_PX,
} from "./indexShareData";

export interface IndexShareCardProps {
  payload: IndexSharePayload;
}

function IndexShareCard({
  payload,
}: IndexShareCardProps): JSX.Element {
  const { profile, modeLabel, constituents, performanceMetrics } = payload;
  const [qrDataUrl, setQrDataUrl] = useState("");

  const shareUrl = useMemo(() => buildShareUrl(profile.ticker), [profile.ticker]);
  const chartPoints = useMemo(
    () =>
      buildShareChartSeries(
        profile.chartSeries,
        performanceMetrics.roi1yVsBtc,
      ),
    [profile.chartSeries, performanceMetrics.roi1yVsBtc],
  );
  const topConstituents = useMemo(
    () => getTopShareConstituents(constituents),
    [constituents],
  );
  const btcRoi1y = performanceMetrics.roi1y - performanceMetrics.roi1yVsBtc;
  const timestamp = useMemo(() => formatShareTimestamp(), []);

  useEffect(() => {
    let cancelled = false;
    QRCode.toDataURL(shareUrl, {
      margin: 1,
      width: 96,
      color: {
        dark: "#c8f5a8",
        light: "#05070d",
      },
    })
      .then((url) => {
        if (!cancelled) setQrDataUrl(url);
      })
      .catch(() => {
        if (!cancelled) setQrDataUrl("");
      });
    return () => {
      cancelled = true;
    };
  }, [shareUrl]);

  return (
    <article
      className="index-share-card"
      style={{ width: SHARE_CARD_WIDTH_PX }}
      aria-label={`Share card for ${profile.name}`}
    >
      <div className="index-share-card-frame" aria-hidden />
      <header className="index-share-card-brand">
        <MorpheumLogo width={48} height={29} fill="#C8F5A8" />
        <p className="index-share-card-tagline">
          Agent-optimized trading for the onchain economy
        </p>
      </header>

      <div className="index-share-card-title-block">
        <h2 className="index-share-card-title">
          {profile.name}
          <span className="index-share-card-ticker"> | {profile.ticker}</span>
        </h2>
        <p className="index-share-card-subtitle">{profile.subtitle}</p>
        {modeLabel ? (
          <span className="index-share-card-mode">{modeLabel} mode</span>
        ) : null}
      </div>

      <div className="index-share-metrics">
        <div className="index-share-metric">
          <span className="index-share-metric-label">24H Change</span>
          <span
            className={`index-share-metric-value ${
              performanceMetrics.change24h >= 0 ? "positive" : "negative"
            }`}
          >
            {formatPercent(performanceMetrics.change24h)}
          </span>
        </div>
        <div className="index-share-metric">
          <span className="index-share-metric-label">1Y ROI</span>
          <span
            className={`index-share-metric-value ${
              performanceMetrics.roi1y >= 0 ? "positive" : "negative"
            }`}
          >
            {formatPercent(performanceMetrics.roi1y)}
          </span>
        </div>
        <div className="index-share-metric">
          <span className="index-share-metric-label">1Y ROI vs. BTC</span>
          <span
            className={`index-share-metric-value ${
              performanceMetrics.roi1yVsBtc >= 0 ? "positive" : "negative"
            }`}
          >
            {formatPercent(performanceMetrics.roi1yVsBtc)}
          </span>
        </div>
      </div>

      <hr className="index-share-divider" />

      <IndexSharePerformanceChart
        points={chartPoints}
        indexLabel={profile.ticker}
        indexRoi1y={performanceMetrics.roi1y}
        btcRoi1y={btcRoi1y}
      />

      <hr className="index-share-divider" />

      <IndexShareConstituents slices={topConstituents} />

      <footer className="index-share-card-footer">
        <div className="index-share-card-footer-copy">
          <p className="index-share-footer-cta">
            Explore MAEX indices on Morpheum — trade agent baskets in one NAV
            token.
          </p>
          <p className="index-share-footer-url">{shareUrl}</p>
          <p className="index-share-footer-time">{timestamp}</p>
        </div>
        {qrDataUrl ? (
          <img
            className="index-share-qr"
            src={qrDataUrl}
            alt={`QR code for ${profile.name}`}
            width={96}
            height={96}
          />
        ) : null}
      </footer>
    </article>
  );
}

export default IndexShareCard;
