import { toast, type ExternalToast } from "sonner";

export type ToastId = string | number;

/** Start a loading toast; optional stableId for predictable updates across retries. */
export function toastLoading(
  message: string,
  opts?: ExternalToast & { stableId?: string },
): ToastId {
  const { stableId, ...toastOpts } = opts ?? {};
  if (stableId) {
    return toast.loading(message, { ...toastOpts, id: stableId });
  }
  return toast.loading(message, toastOpts);
}

/** Replace a loading toast with success (same list slot, spinner removed). */
export function toastCompleteSuccess(
  id: ToastId,
  message: string,
  opts?: ExternalToast,
): void {
  toast.success(message, { ...opts, id });
}

/** Replace a loading toast with error (same list slot, spinner removed). */
export function toastCompleteError(
  id: ToastId,
  message: string,
  opts?: ExternalToast,
): void {
  toast.error(message, { ...opts, id });
}

export function toastDismiss(id: ToastId): void {
  toast.dismiss(id);
}

/** Update an in-flight loading toast in place (same notification slot). */
export function toastUpdateLoading(
  id: ToastId,
  message: string,
  opts?: ExternalToast,
): void {
  toast.loading(message, { ...opts, id });
}

/** Track sequential step toasts for multi-phase pipelines (e.g. portfolio build). */
export function createToastStepTracker() {
  const ids = new Map<string, ToastId>();

  return {
    start(stepKey: string, message: string, stableId?: string): ToastId {
      const id = toastLoading(
        message,
        stableId ? { stableId } : undefined,
      );
      ids.set(stepKey, id);
      return id;
    },

    succeed(stepKey: string, message: string, opts?: ExternalToast): void {
      const id = ids.get(stepKey);
      if (id != null) {
        toastCompleteSuccess(id, message, opts);
        ids.delete(stepKey);
      } else {
        toast.success(message, opts);
      }
    },

    fail(stepKey: string, message: string, opts?: ExternalToast): void {
      const id = ids.get(stepKey);
      if (id != null) {
        toastCompleteError(id, message, opts);
        ids.delete(stepKey);
      } else {
        toast.error(message, opts);
      }
    },

    dismissAll(): void {
      for (const id of ids.values()) {
        toastDismiss(id);
      }
      ids.clear();
    },

    clear(): void {
      ids.clear();
    },
  };
}
