import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";
import {
  AGENT_DISCOVERY_ROWS,
  AGENT_LAYOUT_MARGIN,
  AGENT_ROW_HEIGHT,
} from "./agentLayoutConfig";

export const AGENT_COMPARE_SLOT_INDICES = {
  body: 0,
  focusHero: 3,
  discovery: 6,
} as const;

export const AGENT_COMPARE_COLLAPSED_SLOTS = [1, 2, 4, 5, 7, 8] as const;

export const AGENT_COMPARE_FOCUS_ROWS = 1;
export const AGENT_COMPARE_BODY_ROWS = 25;
export const AGENT_COMPARE_BODY_START_ROW = AGENT_COMPARE_FOCUS_ROWS;
export const AGENT_COMPARE_DISCOVERY_START_ROW =
  AGENT_COMPARE_BODY_START_ROW + AGENT_COMPARE_BODY_ROWS;

export { AGENT_ROW_HEIGHT, AGENT_LAYOUT_MARGIN, AGENT_DISCOVERY_ROWS };

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];

function focusHeroSlot(cols: number): LayoutDefinition {
  return [0, 0, cols, AGENT_COMPARE_FOCUS_ROWS];
}

function compareBodySlot(cols: number): LayoutDefinition {
  return [0, AGENT_COMPARE_BODY_START_ROW, cols, AGENT_COMPARE_BODY_ROWS];
}

function discoverySlot(cols: number): LayoutDefinition {
  return [0, AGENT_COMPARE_DISCOVERY_START_ROW, cols, AGENT_DISCOVERY_ROWS];
}

function buildCompareLayout(cols: number): LayoutConfigLest {
  return [
    compareBodySlot(cols),
    COLLAPSED,
    COLLAPSED,
    focusHeroSlot(cols),
    COLLAPSED,
    COLLAPSED,
    discoverySlot(cols),
    COLLAPSED,
    COLLAPSED,
  ];
}

export function buildAgentCompareResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseInactive = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, AGENT_COMPARE_COLLAPSED_SLOTS);

  return {
    lg: collapseInactive(buildCompareLayout(12)),
    md: collapseInactive(buildCompareLayout(10)),
    sm: collapseInactive(buildCompareLayout(6)),
    xs: collapseInactive(buildCompareLayout(4)),
    xxs: collapseInactive(buildCompareLayout(2)),
  };
}

export function generateAgentCompareResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

export function assertAgentCompareLayoutValid(config: ResponsiveLayoutConfig): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `agent-compare ${bp}`);
  }
}

export function compareBodyPixelHeight(): number {
  return (
    AGENT_COMPARE_BODY_ROWS * AGENT_ROW_HEIGHT +
    (AGENT_COMPARE_BODY_ROWS - 1) * AGENT_LAYOUT_MARGIN
  );
}
