import { useEffect, useMemo, useState } from "react";
import type { CandlestickData } from "lightweight-charts";

import {
  aggregateAgentTokenCandles,
  agentTokenCandlesToChart,
  agentTokenVolumeByTime,
  sliceAgentTokenCandles,
} from "../sdk/api/agentTokenPrice/agentTokenCandleUtil";
import {
  AGENT_TOKEN_PRICE_DATA_BASE_URL,
  fetchAgentTokenHistory,
} from "../sdk/api/agentTokenPrice/agentTokenPriceClient";
import { toBinanceInterval } from "../sdk/api/binance/klineUtil";
import { resolveAgentTokenChartLimit } from "../components/finchartview/chartHistoryUtil";

export interface AgentTokenPriceHistoryConfig {
  catalogAgentId: string;
  interval?: string;
  baseUrl?: string;
  limit?: number;
}

export {
  AGENT_TOKEN_FULL_HISTORY_LIMIT,
} from "../components/finchartview/chartHistoryUtil";

export function useAgentTokenPriceHistory(config: AgentTokenPriceHistoryConfig) {
  const catalogAgentId = config.catalogAgentId.trim();
  const interval = toBinanceInterval(config.interval ?? "5m");
  const baseUrl = config.baseUrl ?? AGENT_TOKEN_PRICE_DATA_BASE_URL;
  const limit = resolveAgentTokenChartLimit(interval, config.limit);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sourceCandles, setSourceCandles] = useState<
    ReturnType<typeof sliceAgentTokenCandles>
  >([]);

  useEffect(() => {
    if (!catalogAgentId) {
      setSourceCandles([]);
      setLoading(false);
      setError("Missing agent token catalog id");
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchAgentTokenHistory(catalogAgentId, baseUrl)
      .then((file) => {
        if (cancelled) return;
        setSourceCandles(file.candles);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load agent token price history",
        );
        setSourceCandles([]);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [catalogAgentId, baseUrl]);

  const aggregated = useMemo(
    () => aggregateAgentTokenCandles(sourceCandles, interval),
    [sourceCandles, interval],
  );

  const sliced = useMemo(
    () => sliceAgentTokenCandles(aggregated, limit),
    [aggregated, limit],
  );

  const candles = useMemo(
    (): CandlestickData[] => agentTokenCandlesToChart(sliced),
    [sliced],
  );

  const volumeByTime = useMemo(
    () => agentTokenVolumeByTime(sliced),
    [sliced],
  );

  return {
    candles,
    volumeByTime,
    loading,
    error,
    isConnected: false,
    catalogAgentId,
    interval,
  };
}
