import type { CandlestickData, UTCTimestamp } from "lightweight-charts";
import type { RawKline } from "../../sdk/types/api";
import type { KlineData } from "../../sdk/types/data";
import {
  binanceRestKlineToCandle,
  binanceWsKlineToCandle,
  binanceWsKlineToUpdate,
  mergeBinanceCandles,
  toBinanceInterval,
  toBinanceSymbol,
} from "../../sdk/api/binance/klineUtil";
import { toNumberFromSatoshi } from "../../sdk/utils/math";
import type { KlineUpdate } from "./KlineChart";

export {
  binanceRestKlineToCandle,
  binanceWsKlineToCandle,
  binanceWsKlineToUpdate,
  mergeBinanceCandles,
  toBinanceInterval,
  toBinanceSymbol,
};

function parsePrice(value: string | number): number {
  if (typeof value === "number") return value;
  return toNumberFromSatoshi(value);
}

function toChartTime(openTime: number): UTCTimestamp {
  const ms = openTime < 1e12 ? openTime * 1000 : openTime;
  return Math.floor(ms / 1000) as UTCTimestamp;
}

export function rawKlineToCandle(kline: RawKline): CandlestickData | null {
  const [openTime, open, high, low, close] = kline;
  if (openTime == null || open == null || high == null || low == null || close == null) {
    return null;
  }

  return {
    time: toChartTime(openTime),
    open: parsePrice(open),
    high: parsePrice(high),
    low: parsePrice(low),
    close: parsePrice(close),
  };
}

export function klineDataToCandle(kline: KlineData): CandlestickData {
  return {
    time: toChartTime(kline.openTime),
    open: kline.open,
    high: kline.high,
    low: kline.low,
    close: kline.close,
  };
}

export function klineDataToUpdate(kline: KlineData): KlineUpdate {
  return {
    openTime: kline.openTime,
    closeTime: kline.closeTime,
    open: kline.open,
    high: kline.high,
    low: kline.low,
    close: kline.close,
    volume: kline.volume,
  };
}

export function mergeCandles(
  historical: CandlestickData[],
  live: KlineData[],
): CandlestickData[] {
  const byTime = new Map<number, CandlestickData>();

  for (const candle of historical) {
    byTime.set(candle.time as number, candle);
  }

  for (const kline of live) {
    const candle = klineDataToCandle(kline);
    byTime.set(candle.time as number, candle);
  }

  return Array.from(byTime.values()).sort((a, b) => (a.time as number) - (b.time as number));
}

export function parseHeightPx(height?: string): number {
  if (!height) return 500;
  const parsed = parseFloat(height);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 500;
}
