import React, { useMemo } from "react";
import type { EquityBreakdownSegment } from "../../hooks/usePortfolioAnalytics";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import "./portfolio.css";

export interface PortfolioEquitySummaryProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  focusAgentId?: string | null;
  refreshInterval?: number;
}

function formatCurrency(value: number): string {
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(2)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(1)}k`;
  return `$${value.toFixed(2)}`;
}

function formatPct(value: number): string {
  return `${value.toFixed(1)}%`;
}

function buildDonutStyle(segments: EquityBreakdownSegment[]): React.CSSProperties {
  const total = segments.reduce((s, seg) => s + seg.value, 0);
  if (total <= 0) return {};
  let cursor = 0;
  const stops = segments.map((seg) => {
    const pct = (seg.value / total) * 100;
    const start = cursor;
    cursor += pct;
    return `${seg.color} ${start}% ${cursor}%`;
  });
  return { background: `conic-gradient(${stops.join(", ")})` };
}

interface EquityDonutProps {
  segments: EquityBreakdownSegment[];
  centerLabel: string;
  groupLabel: string;
}

function EquityDonut({
  segments,
  centerLabel,
  groupLabel,
}: EquityDonutProps): JSX.Element {
  const donutStyle = useMemo(() => buildDonutStyle(segments), [segments]);

  return (
    <div className="portfolio-equity-donut-group">
      <span className="portfolio-equity-donut-group-label">{groupLabel}</span>
      <div className="portfolio-equity-donut-wrap portfolio-equity-donut-wrap--compact">
        <div
          className="portfolio-equity-donut"
          style={donutStyle}
          aria-hidden
        />
        <div className="portfolio-equity-donut-center">{centerLabel}</div>
      </div>
      <div className="portfolio-equity-comparison-legend">
        {segments.slice(0, 4).map((seg) => (
          <div key={seg.id} className="portfolio-attribution-row">
            <span
              className="portfolio-attribution-dot"
              style={{ background: seg.color }}
              aria-hidden
            />
            <span>{seg.label}</span>
            <strong>{formatCurrency(seg.value)}</strong>
          </div>
        ))}
      </div>
    </div>
  );
}

function PortfolioEquitySummary({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  focusAgentId = null,
  refreshInterval,
}: PortfolioEquitySummaryProps): JSX.Element {
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    focusAgentId,
    refreshInterval,
  });

  const isFocused =
    focusAgentId != null &&
    analytics.focusEquityBreakdown != null &&
    analytics.focusVsFleetEquity != null;

  const equityDonutStyle = useMemo(
    () => buildDonutStyle(analytics.equityBreakdown),
    [analytics.equityBreakdown],
  );

  const allocationTotal = useMemo(() => {
    if (!analytics.focusEquityBreakdown) return 0;
    return analytics.focusEquityBreakdown.reduce((s, seg) => s + seg.value, 0);
  }, [analytics.focusEquityBreakdown]);

  const fleetSharePct = useMemo(() => {
    if (analytics.accountEquity <= 0) return 0;
    return (analytics.focusAgentBucketEquity / analytics.accountEquity) * 100;
  }, [analytics.focusAgentBucketEquity, analytics.accountEquity]);

  if (isFocused) {
    return (
      <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
        <section
          className="portfolio-equity-summary portfolio-equity-summary--focused"
          aria-label="Equity breakdown"
        >
          <span className="portfolio-mini-chart-label">Equity breakdown</span>
          <div className="portfolio-equity-donuts-row">
            <EquityDonut
              segments={analytics.focusEquityBreakdown!}
              centerLabel={formatCurrency(allocationTotal)}
              groupLabel="Allocation"
            />
            <EquityDonut
              segments={analytics.focusVsFleetEquity!}
              centerLabel={formatPct(fleetSharePct)}
              groupLabel="vs Fleet"
            />
          </div>
        </section>
      </div>
    );
  }

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section className="portfolio-equity-summary" aria-label="Equity breakdown">
        <span className="portfolio-mini-chart-label">Equity breakdown</span>
        <div className="portfolio-equity-donut-wrap">
          <div
            className="portfolio-equity-donut"
            style={equityDonutStyle}
            aria-hidden
          />
          <div className="portfolio-equity-donut-center">
            {formatCurrency(analytics.accountEquity)}
          </div>
        </div>
        <div className="portfolio-attribution-legend">
          {analytics.equityBreakdown.slice(0, 4).map((seg) => (
            <div key={seg.id} className="portfolio-attribution-row">
              <span
                className="portfolio-attribution-dot"
                style={{ background: seg.color }}
                aria-hidden
              />
              <span>{seg.label}</span>
              <strong>{formatCurrency(seg.value)}</strong>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioEquitySummary);
