import type { JSX } from "react";

export type ControlDepth = "simple" | "precise";

export interface IntentControlDepthToggleProps {
  depth: ControlDepth;
  onChange: (depth: ControlDepth) => void;
}

export function IntentControlDepthToggle({
  depth,
  onChange,
}: IntentControlDepthToggleProps): JSX.Element {
  return (
    <div className="intent-control-depth" role="group" aria-label="Control depth">
      <span className="terminal-label">Depth:</span>
      <button
        type="button"
        className={`intent-depth-chip${depth === "simple" ? " is-active" : ""}`}
        onClick={() => onChange("simple")}
      >
        Simple
      </button>
      <button
        type="button"
        className={`intent-depth-chip${depth === "precise" ? " is-active" : ""}`}
        onClick={() => onChange("precise")}
      >
        Precise
      </button>
    </div>
  );
}
