import type { Step } from "react-joyride";
import { COPY_TOUR_STEPS_CONTENT } from "./content";
import { COPY_TOUR_TARGETS, type CopyTourGateKind } from "./constants";

function tourTarget(value: string): string {
  return `[data-tour="${value}"]`;
}

const STEP_TARGETS: Record<string, string> = {
  "agent-intro": COPY_TOUR_TARGETS.actionTab,
  "copy-cta": COPY_TOUR_TARGETS.copyCta,
  "modal-capital": COPY_TOUR_TARGETS.modalCapital,
  "modal-risk-rail": COPY_TOUR_TARGETS.modalRiskRail,
  "modal-autonomy": COPY_TOUR_TARGETS.modalAutonomy,
  "modal-confirm": COPY_TOUR_TARGETS.modalConfirm,
  "portfolio-strip": COPY_TOUR_TARGETS.mirroredStrip,
  "mirror-wait": COPY_TOUR_TARGETS.mirroredStrip,
  "status-pnl": COPY_TOUR_TARGETS.bucketPnl,
  closing: "body",
};

type CopyTourStepContent = (typeof COPY_TOUR_STEPS_CONTENT)[number];

export interface CopyTourStepMeta {
  stepId: string;
  stepNumber: number;
  targetSelector: string;
  requiresClick: boolean;
  gateKind: CopyTourGateKind;
  gateMaxMs?: number;
}

export function buildCopyTourSteps(): Step[] {
  return COPY_TOUR_STEPS_CONTENT.map((step, index) => {
    const targetKey = STEP_TARGETS[step.id] ?? step.id;
    const targetSelector =
      step.placement === "center" || step.id === "closing"
        ? "body"
        : tourTarget(targetKey);
    const requiresClick = Boolean(step.requiresClick);
    const isCenter = step.placement === "center" || step.id === "closing";

    return {
      target: targetSelector,
      title: step.title,
      content: step.content,
      placement: (step.placement ?? "auto") as Step["placement"],
      skipBeacon: true,
      isFixed: !isCenter,
      spotlightClicks: requiresClick,
      disableOverlay: requiresClick,
      disableOverlayClose: true,
      hideBackButton: requiresClick,
      hideCloseButton: true,
      showSkipButton: true,
      buttons: requiresClick
        ? (["skip"] as ("back" | "skip" | "primary")[])
        : (["skip", "primary"] as ("back" | "skip" | "primary")[]),
      blockTargetInteraction: false,
      skipScroll: true,
      data: {
        stepId: step.id,
        stepNumber: index + 1,
        targetSelector,
        requiresClick,
        gateKind: step.gateKind ?? "none",
        gateMaxMs: step.gateMaxMs,
      } satisfies CopyTourStepMeta,
    };
  });
}

export function getCopyTourStepCount(): number {
  return COPY_TOUR_STEPS_CONTENT.length;
}

export function findCopyTourStepIndex(stepId: string, steps: Step[]): number {
  return steps.findIndex(
    (step) => (step.data as CopyTourStepMeta | undefined)?.stepId === stepId,
  );
}
