import React, { type JSX } from "react";
import { createPortal } from "react-dom";
import { useOptionalSettings } from "../../context/SettingsContext";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
  useOverlayScrollLock,
} from "../../components/ui/overlay";
import {
  detectPlatform,
  formatKeyboardBinding,
  getDefaultKeyboardShortcuts,
  getPrimaryModLabel,
  type KeyboardBinding,
  type KeyboardShortcutPrefs,
} from "../../utils/keyboardShortcuts";
import {
  KEYBOARD_SHORTCUT_NOTES,
  KEYBOARD_SHORTCUT_SECTIONS,
  KEYBOARD_SHORTCUTS_FOOTER,
  type KeyboardShortcutRow,
  type ShortcutKeyToken,
} from "./keyboardShortcutsContent";
import "../../components/smartlayout/layout.css";
import "./KeyboardShortcutsModal.css";

export interface KeyboardShortcutsModalProps {
  isOpen: boolean;
  onClose: () => void;
  bindings?: KeyboardShortcutPrefs;
}

function resolveKeyLabel(token: ShortcutKeyToken, modKey: string): string {
  if (token === "Mod") return modKey;
  return token;
}

function BindingKeys({ binding }: { binding: KeyboardBinding }): JSX.Element {
  const platform = detectPlatform();
  const tokens = formatKeyboardBinding(binding, platform);

  return (
    <span className="keyboard-shortcuts-keys">
      {tokens.map((token, index) => (
        <React.Fragment key={`${token}-${index}`}>
          {index > 0 ? (
            <span className="keyboard-shortcuts-key-sep" aria-hidden>
              +
            </span>
          ) : null}
          <kbd className="keyboard-shortcuts-kbd">{token}</kbd>
        </React.Fragment>
      ))}
    </span>
  );
}

function ShortcutKeys({
  keys,
  modKey,
}: {
  keys: ShortcutKeyToken[];
  modKey: string;
}): JSX.Element {
  return (
    <span className="keyboard-shortcuts-keys">
      {keys.map((key, index) => (
        <React.Fragment key={`${key}-${index}`}>
          {index > 0 ? (
            <span className="keyboard-shortcuts-key-sep" aria-hidden>
              +
            </span>
          ) : null}
          <kbd className="keyboard-shortcuts-kbd">{resolveKeyLabel(key, modKey)}</kbd>
        </React.Fragment>
      ))}
    </span>
  );
}

function ShortcutRow({
  row,
  modKey,
  bindings,
}: {
  row: KeyboardShortcutRow;
  modKey: string;
  bindings: KeyboardShortcutPrefs;
}): JSX.Element {
  const liveBinding = row.customizableActionId
    ? bindings[row.customizableActionId]
    : null;

  return (
    <div className="keyboard-shortcuts-row">
      <div className="keyboard-shortcuts-row-keys">
        {liveBinding ? (
          <BindingKeys binding={liveBinding} />
        ) : (
          <ShortcutKeys keys={row.keys} modKey={modKey} />
        )}
      </div>
      <div className="keyboard-shortcuts-row-action">
        <span>{row.action}</span>
        {row.note ? (
          <span className="keyboard-shortcuts-row-note">{row.note}</span>
        ) : null}
      </div>
    </div>
  );
}

export function KeyboardShortcutsModal({
  isOpen,
  onClose,
  bindings: bindingsOverride,
}: KeyboardShortcutsModalProps): JSX.Element | null {
  const settingsContext = useOptionalSettings();
  const modKey = getPrimaryModLabel();
  const bindings =
    bindingsOverride ??
    settingsContext?.settings.keyboardShortcuts ??
    getDefaultKeyboardShortcuts();

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onClose);
  useOverlayScrollLock(isOpen && mounted);

  if (!mounted) return null;

  const modal = (
    <StaggeredOverlayRoot className="keyboard-shortcuts-overlay modal-overlay--stacked">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="keyboard-shortcuts-panel terminal-overlay-panel-shell staggered-overlay-panel--scale"
        aria-label="Keyboard shortcuts"
      >
        <header className="keyboard-shortcuts-header">
          <div>
            <h2 id="keyboard-shortcuts-title" className="terminal-panel-title">
              Keyboard shortcuts
            </h2>
            <p className="keyboard-shortcuts-header-hint">Esc to close</p>
          </div>
          <button
            type="button"
            className="keyboard-shortcuts-close"
            onClick={onClose}
            aria-label="Close keyboard shortcuts"
          >
            ×
          </button>
        </header>

        <div className="keyboard-shortcuts-body">
          {KEYBOARD_SHORTCUT_SECTIONS.map((section) => (
            <section key={section.id} className="keyboard-shortcuts-section">
              <h3 className="keyboard-shortcuts-section-title terminal-label">
                {section.title}
              </h3>
              {section.intro ? (
                <p className="keyboard-shortcuts-section-intro">{section.intro}</p>
              ) : null}
              <div className="keyboard-shortcuts-rows">
                {section.rows.map((row, index) => (
                  <ShortcutRow
                    key={`${section.id}-${index}`}
                    row={row}
                    modKey={modKey}
                    bindings={bindings}
                  />
                ))}
              </div>
            </section>
          ))}

          {KEYBOARD_SHORTCUT_NOTES.map((noteSection) => (
            <section key={noteSection.id} className="keyboard-shortcuts-notes">
              <h3 className="keyboard-shortcuts-section-title terminal-label">
                {noteSection.title}
              </h3>
              <ul className="keyboard-shortcuts-note-list">
                {noteSection.bullets.map((bullet) => (
                  <li key={bullet}>{bullet}</li>
                ))}
              </ul>
            </section>
          ))}
        </div>

        <footer className="keyboard-shortcuts-footer">
          <p>{KEYBOARD_SHORTCUTS_FOOTER}</p>
          <p className="keyboard-shortcuts-mod-footnote">
            Default Mod = {modKey} on this device. Custom bindings appear above.
          </p>
        </footer>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modal, document.body)
    : null;
}
