import React, { useMemo, useState } from "react";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import type { AgentTask, AgentTaskStatus } from "../../store/types";
import MemoryAuditPanel from "../portfolio/MemoryAuditPanel";
import { sortGuardrailIntents } from "./deckIntents";
import { compareGuardrailRisk, getGuardrailMeta } from "./guardrailMeta";
import SafetyAuditLogViewToggle from "./SafetyAuditLogViewToggle";
import SafetyAuditLogMetricCell from "./SafetyAuditLogMetricCell";
import SafetyAuditLogRowActions from "./SafetyAuditLogRowActions";
import SafetyAuditLogIntentCard from "./SafetyAuditLogIntentCard";
import SafetyLogReviewSheet from "./SafetyLogReviewSheet";
import {
  getSafetyLogLayout,
  SAFETY_LOG_CARD_PREVIEW_COUNT,
} from "./safetyAuditLogLayout";

export interface SafetyAuditLogPanelProps {
  height?: string;
  filterAgentIds?: string[];
  isMobile?: boolean;
  layoutBreakpoint?: string;
  baseURL?: string;
  onRequestViewOnChart?: (marketId: string) => void;
}

function statusLabel(status: AgentTaskStatus): string {
  return AGENT_TASK_STATUS_CONFIG[status]?.label ?? status;
}

function abbreviateAgent(label: string, compact: boolean): string {
  if (!compact) return label;
  const first = label.split(/\s+/)[0] ?? label;
  return first.length > 10 ? `${first.slice(0, 9)}…` : first;
}

function SafetyAuditLogPanel({
  height = "100%",
  filterAgentIds = [],
  layoutBreakpoint = "lg",
  baseURL,
  onRequestViewOnChart,
}: SafetyAuditLogPanelProps): JSX.Element {
  const { getAgentById } = useTradingAgents();
  const { tasks, forceExecute, rejectTask } = useAgentTasks();
  const [viewMode, setViewMode] = useState<"intents" | "memory">("intents");
  const [tweakByTask, setTweakByTask] = useState<Record<string, number>>({});
  const [cardsExpanded, setCardsExpanded] = useState(false);
  const [reviewTaskId, setReviewTaskId] = useState<string | null>(null);

  const layout = useMemo(
    () => getSafetyLogLayout(layoutBreakpoint),
    [layoutBreakpoint],
  );

  const pendingIntents = useMemo(() => {
    const queue = sortGuardrailIntents(tasks);
    if (filterAgentIds.length === 0) {
      return [...queue].sort(compareGuardrailRisk);
    }
    const allowed = new Set(filterAgentIds);
    return queue
      .filter((t) => allowed.has(t.agentId))
      .sort(compareGuardrailRisk);
  }, [tasks, filterAgentIds]);

  const visibleCards = useMemo(() => {
    if (layout !== "cards" && layout !== "cardsReview") return pendingIntents;
    if (cardsExpanded) return pendingIntents;
    return pendingIntents.slice(0, SAFETY_LOG_CARD_PREVIEW_COUNT);
  }, [pendingIntents, layout, cardsExpanded]);

  const overflowCount = Math.max(
    0,
    pendingIntents.length - visibleCards.length,
  );

  const reviewTask = useMemo(
    () => pendingIntents.find((t) => t.id === reviewTaskId) ?? null,
    [pendingIntents, reviewTaskId],
  );

  const rootClass = [
    "safety-audit-log",
    layout === "tableCompact" ? "safety-audit-log--compact-table" : "",
    layout === "cards" || layout === "cardsReview"
      ? "safety-audit-log--cards"
      : "",
    layout === "cardsReview" ? "safety-audit-log--cards-review" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const getSizePct = (taskId: string) => tweakByTask[taskId] ?? 100;

  const renderTable = () => {
    const compactTable = layout === "tableCompact";

    return (
      <table className="safety-audit-log-table">
        <thead>
          <tr>
            <th className="safety-audit-log-col-agent">Agent</th>
            <th className="safety-audit-log-col-intent">Intent Summary</th>
            {compactTable ? (
              <th className="safety-audit-log-col-risk-conf">Risk · Conf</th>
            ) : (
              <>
                <th className="safety-audit-log-col-risk">Risk Impact</th>
                <th className="safety-audit-log-col-confidence">Confidence</th>
              </>
            )}
            <th className="safety-audit-log-col-actions">Human Action</th>
          </tr>
        </thead>
        <tbody>
          {pendingIntents.map((task) => {
            const meta = getGuardrailMeta(task);
            const agentLabel =
              getAgentById(task.agentId)?.displayName ??
              task.agentId.slice(0, 8);
            const summary = task.trigger || task.description;
            const sizePct = getSizePct(task.id);

            return (
              <tr
                key={task.id}
                className={[
                  "safety-audit-log-row",
                  task.status === "pending"
                    ? "safety-audit-log-row--pending"
                    : "",
                  task.status === "watching"
                    ? "safety-audit-log-row--watching"
                    : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
              >
                <td className="safety-audit-log-col-agent">
                  <div className="safety-audit-log-agent-cell">
                    {task.status === "pending" ? (
                      <span className="safety-audit-log-pending-badge">
                        Pending
                      </span>
                    ) : null}
                    <span className="safety-audit-log-agent-name">
                      {abbreviateAgent(agentLabel, compactTable)}
                    </span>
                  </div>
                </td>
                <td className="safety-audit-log-col-intent">
                  <button
                    type="button"
                    className="safety-audit-log-intent-link"
                    title={summary}
                    onClick={() => {
                      if (task.marketId && onRequestViewOnChart) {
                        onRequestViewOnChart(task.marketId);
                      }
                    }}
                  >
                    {summary}
                  </button>
                  <div className="terminal-text-muted safety-audit-log-intent-meta">
                    {statusLabel(task.status)} ·{" "}
                    {formatRelativeTime(task.updatedAt)}
                  </div>
                </td>
                {compactTable ? (
                  <td className="safety-audit-log-col-risk-conf">
                    <SafetyAuditLogMetricCell
                      riskImpact={meta.riskImpact}
                      confidencePct={meta.confidencePct}
                      variant="combined"
                    />
                  </td>
                ) : (
                  <>
                    <td className="safety-audit-log-col-risk">
                      <SafetyAuditLogMetricCell
                        riskImpact={meta.riskImpact}
                        confidencePct={meta.confidencePct}
                        variant="riskOnly"
                      />
                    </td>
                    <td className="safety-audit-log-col-confidence">
                      <SafetyAuditLogMetricCell
                        riskImpact={meta.riskImpact}
                        confidencePct={meta.confidencePct}
                        variant="confidenceOnly"
                      />
                    </td>
                  </>
                )}
                <td className="safety-audit-log-col-actions">
                  <SafetyAuditLogRowActions
                    taskId={task.id}
                    sizePct={sizePct}
                    abbreviated={compactTable}
                    onSizePctChange={(value) =>
                      setTweakByTask((prev) => ({
                        ...prev,
                        [task.id]: value,
                      }))
                    }
                    onApprove={() => forceExecute(task.id, { sizePct })}
                    onReject={() => rejectTask(task.id)}
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    );
  };

  return (
    <div className={rootClass} style={{ height }}>
      <SafetyAuditLogViewToggle value={viewMode} onChange={setViewMode} />
      {viewMode === "memory" ? (
        <MemoryAuditPanel height="100%" filterAgentIds={filterAgentIds} />
      ) : (
        <div className="safety-audit-log-body">
          {pendingIntents.length === 0 ? (
            <p className="terminal-text-muted safety-audit-log-empty">
              No intents awaiting approval.
            </p>
          ) : layout === "cards" || layout === "cardsReview" ? (
            <div className="safety-audit-log-card-list">
              {visibleCards.map((task) => {
                const agentLabel =
                  getAgentById(task.agentId)?.displayName ??
                  task.agentId.slice(0, 8);
                const sizePct = getSizePct(task.id);
                return (
                  <SafetyAuditLogIntentCard
                    key={task.id}
                    task={task}
                    agentLabel={agentLabel}
                    layout={layout}
                    sizePct={sizePct}
                    onSizePctChange={(value) =>
                      setTweakByTask((prev) => ({
                        ...prev,
                        [task.id]: value,
                      }))
                    }
                    onApprove={() => forceExecute(task.id, { sizePct })}
                    onReject={() => rejectTask(task.id)}
                    onReview={() => setReviewTaskId(task.id)}
                    onRequestViewOnChart={() => {
                      if (task.marketId && onRequestViewOnChart) {
                        onRequestViewOnChart(task.marketId);
                      }
                    }}
                  />
                );
              })}
              {overflowCount > 0 ? (
                <button
                  type="button"
                  className="safety-audit-log-show-all"
                  onClick={() => setCardsExpanded(true)}
                >
                  Show all {pendingIntents.length}
                </button>
              ) : null}
            </div>
          ) : (
            <div className="safety-audit-log-table-wrap">{renderTable()}</div>
          )}
        </div>
      )}
      <SafetyLogReviewSheet
        isOpen={reviewTaskId != null}
        task={reviewTask}
        agentLabel={
          reviewTask
            ? getAgentById(reviewTask.agentId)?.displayName ??
              reviewTask.agentId.slice(0, 8)
            : ""
        }
        sizePct={reviewTask ? getSizePct(reviewTask.id) : 100}
        baseURL={baseURL}
        onSizePctChange={(value) => {
          if (!reviewTask) return;
          setTweakByTask((prev) => ({ ...prev, [reviewTask.id]: value }));
        }}
        onApprove={() => {
          if (!reviewTask) return;
          forceExecute(reviewTask.id, { sizePct: getSizePct(reviewTask.id) });
        }}
        onReject={() => {
          if (!reviewTask) return;
          rejectTask(reviewTask.id);
        }}
        onClose={() => setReviewTaskId(null)}
      />
    </div>
  );
}

export default React.memo(SafetyAuditLogPanel);
