import React, { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { useTradeHistory } from "../../hooks/useTradeHistory";
import { TradeHistoryRow } from "../../sdk/types/data";
import { useMarkets } from "../../hooks/useMarkets";
import type { ChartTradeFocusRequest } from "../finchartview/chartMarkers";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_PENDING_ORDERS,
  DEFAULT_REFRESH_INTERVAL,
  SORT_DIRECTION_ASC,
  SORT_DIRECTION_DESC,
  TRADE_HISTORY_EMPTY_MESSAGE,
  TRADE_HISTORY_GRID_TEMPLATE_COLUMNS,
  TRADE_HISTORY_LOADING_MESSAGE,
  TRADE_HISTORY_TITLE,
  ORDER_SIDE_COLOR_BUY_LONG,
  ORDER_SIDE_COLOR_SELL_SHORT,
} from "../../constants";
import { shortHashId } from "../../utils/hashId";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import {
  buildTaskAgentMap,
  rowMatchesFleetFilter,
} from "../../utils/agentFilter";
import ExplainActionModal from "./ExplainActionModal";

interface TradeHistoryProps {
  baseURL: string;
  authToken?: string;
  walletAddress: string;
  height?: string;
  refreshInterval?: number;
  hide_header?: boolean;
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  onRequestViewTradeOnChart?: (req: Omit<ChartTradeFocusRequest, "requestId">) => void;
  filterAgentIds?: string[];
}

type SortField =
  | "time"
  | "coin"
  | "direction"
  | "side"
  | "size"
  | "price"
  | "fee"
  | "closedPnl";

type SortDirection = typeof SORT_DIRECTION_ASC | typeof SORT_DIRECTION_DESC;

function formatDateTime(value?: number | null): string {
  if (value == null) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function formatNumber(value: number | null | undefined): string {
  if (value == null || Number.isNaN(value)) return "—";
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function getSortValue(row: TradeHistoryRow, field: SortField): string | number {
  switch (field) {
    case "time":
      return row.time;
    case "coin":
      return row.coin;
    case "direction":
      return row.direction;
    case "side":
      return row.side;
    case "size":
      return row.size;
    case "price":
      return row.price;
    case "fee":
      return row.fee;
    case "closedPnl":
      return row.closedPnl ?? 0;
  }
}

function TradeHistory({
  baseURL = DEFAULT_BASE_URL,
  authToken,
  walletAddress,
  height = DEFAULT_HEIGHT_PENDING_ORDERS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  hide_header = false,
  onRequestHeaderActions,
  onRequestViewTradeOnChart,
  filterAgentIds = [],
}: TradeHistoryProps): JSX.Element {
  const { trades, loading, error } = useTradeHistory({
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });

  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });
  const { tasks } = useAgentTasks();

  const taskAgentMap = useMemo(() => buildTaskAgentMap(tasks), [tasks]);

  const displayTrades = useMemo(
    () =>
      trades
        .filter((row) =>
          rowMatchesFleetFilter(row.agentTaskId, filterAgentIds, taskAgentMap),
        )
        .map((row) =>
        row.coin.startsWith("m-")
          ? {
              ...row,
              coin: getSymbolByMarketId(row.marketId) || row.coin,
            }
          : row,
      ),
    [trades, getSymbolByMarketId, filterAgentIds, taskAgentMap],
  );

  const [sortField, setSortField] = useState<SortField | null>("time");
  const [sortDirection, setSortDirection] = useState<SortDirection>(
    SORT_DIRECTION_DESC,
  );
  const [explainTaskId, setExplainTaskId] = useState<string | null>(null);

  const sortedTrades = useMemo(() => {
    if (!sortField) return displayTrades;
    return [...displayTrades].sort((a, b) => {
      const aValue = getSortValue(a, sortField);
      const bValue = getSortValue(b, sortField);
      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === SORT_DIRECTION_ASC
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }
      return sortDirection === SORT_DIRECTION_ASC
        ? Number(aValue) - Number(bValue)
        : Number(bValue) - Number(aValue);
    });
  }, [displayTrades, sortField, sortDirection]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(
        sortDirection === SORT_DIRECTION_ASC
          ? SORT_DIRECTION_DESC
          : SORT_DIRECTION_ASC,
      );
    } else {
      setSortField(field);
      setSortDirection(SORT_DIRECTION_DESC);
    }
  };

  const handleViewTradeOnChart = useCallback(
    (row: TradeHistoryRow) => {
      if (!row.marketId) {
        toast.error("No market linked to this fill");
        return;
      }
      onRequestViewTradeOnChart?.({
        marketId: row.marketId,
        tradeId: row.tradeId,
        time: row.time,
      });
      toast.success("Chart updated", {
        description: `Switched to ${row.coin}`,
      });
    },
    [onRequestViewTradeOnChart],
  );

  const headerActions = useMemo(() => null, []);

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, error, headerActions]);

  if (loading) {
    return <MorpheumInlineLoading message={TRADE_HISTORY_LOADING_MESSAGE} />;
  }
  if (error) return <ErrorMessage error={error} />;

  return (
    <div
      className="layout-container"
      style={{
        height,
        ...(hide_header ? { borderRadius: 0, background: "transparent" } : {}),
      }}
    >
      {!hide_header && (
        <LayoutHeader title={TRADE_HISTORY_TITLE}>{headerActions}</LayoutHeader>
      )}
      <div className="table-container shrinkable">
        <div
          className="table-header"
          style={{ gridTemplateColumns: TRADE_HISTORY_GRID_TEMPLATE_COLUMNS }}
        >
          <TableHeaderCell
            field="time"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Time
          </TableHeaderCell>
          <TableHeaderCellStatic center>Agent</TableHeaderCellStatic>
          <TableHeaderCell
            field="coin"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Coin
          </TableHeaderCell>
          <TableHeaderCell
            field="direction"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Direction
          </TableHeaderCell>
          <TableHeaderCell
            field="side"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            center
          >
            Side
          </TableHeaderCell>
          <TableHeaderCell
            field="size"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Size
          </TableHeaderCell>
          <TableHeaderCell
            field="price"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Price
          </TableHeaderCell>
          <TableHeaderCell
            field="fee"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Fee
          </TableHeaderCell>
          <TableHeaderCell
            field="closedPnl"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.closedPnl} />
          </TableHeaderCell>
        </div>

        {sortedTrades.length === 0 ? (
          <EmptyMessage message={TRADE_HISTORY_EMPTY_MESSAGE} />
        ) : (
          sortedTrades.map((row, index) => {
            const sideColor =
              row.side === "Buy"
                ? ORDER_SIDE_COLOR_BUY_LONG
                : ORDER_SIDE_COLOR_SELL_SHORT;
            const pnlColor =
              row.closedPnl == null
                ? undefined
                : row.closedPnl > 0
                  ? ORDER_SIDE_COLOR_BUY_LONG
                  : row.closedPnl < 0
                    ? ORDER_SIDE_COLOR_SELL_SHORT
                    : undefined;

            return (
              <div
                key={`trade-${row.tradeId}-${index}`}
                className={`table-row ${index % 2 === 0 ? "even" : ""}`}
                style={{
                  gridTemplateColumns: TRADE_HISTORY_GRID_TEMPLATE_COLUMNS,
                }}
              >
                <div className="table-cell primary">
                  {formatDateTime(row.time)}
                </div>
                <div
                  className="table-cell center"
                  title={row.agentTaskId ?? undefined}
                >
                  {row.agentTaskId ? (
                      <span className="task-id-chip"
                         onClick={() => setExplainTaskId(row.agentTaskId ?? null)}
                      >{shortHashId(row.agentTaskId)}</span>
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell">
                  {onRequestViewTradeOnChart ? (
                    <button
                      type="button"
                      className="trade-history-coin-link"
                      onClick={() => handleViewTradeOnChart(row)}
                    >
                      {row.coin}
                    </button>
                  ) : (
                    row.coin
                  )}
                </div>
                <div className="table-cell">{row.direction}</div>
                <div
                  className="table-cell center"
                  style={{ color: sideColor, fontWeight: 500 }}
                >
                  {row.side}
                </div>
                <div className="table-cell right">
                  {formatNumber(row.size)}
                </div>
                <div className="table-cell right">
                  {formatNumber(row.price)}
                </div>
                <div className="table-cell right">
                  {formatNumber(row.fee)}
                </div>
                <div
                  className="table-cell right"
                  style={{ color: pnlColor, fontWeight: pnlColor ? 500 : 400 }}
                >
                  {row.closedPnl == null ? "—" : formatNumber(row.closedPnl)}
                </div>
              </div>
            );
          })
        )}

        {sortedTrades.length > 0 ? (
          <div className="trade-history-end-marker" aria-hidden>
            <span className="trade-history-end-marker-line" />
            <span className="trade-history-end-marker-text">End of activity log</span>
          </div>
        ) : null}
      </div>
      <ExplainActionModal
        isOpen={explainTaskId != null}
        agentTaskId={explainTaskId}
        baseURL={baseURL}
        walletAddress={walletAddress}
        onClose={() => setExplainTaskId(null)}
      />
    </div>
  );
}

export default React.memo(TradeHistory);
