import type { ShortcutActionId } from "./types";

export interface ShortcutActionDefinition {
  id: ShortcutActionId;
  label: string;
  description: string;
}

export const SHORTCUT_ACTION_CATALOG: ShortcutActionDefinition[] = [
  {
    id: "toggleTickerSelection",
    label: "Toggle ticker selection",
    description: "Open or close the market picker overlay",
  },
  {
    id: "toggleAgentConsole",
    label: "Toggle Agent Console",
    description: "Open or close the bottom Agent Console panel",
  },
  {
    id: "openIntentComposer",
    label: "Open intent composer",
    description: "Switch to Agent mode and open the intent modal (desktop only)",
  },
  {
    id: "switchLayoutClassic",
    label: "Switch to Classic layout",
    description: "Apply the Classic trade page layout (Settings → Layout)",
  },
  {
    id: "switchLayoutCompact",
    label: "Switch to Compact layout",
    description: "Apply the Compact trade page layout (Settings → Layout)",
  },
  {
    id: "switchLayoutHighAgency",
    label: "Switch to High-Agency layout",
    description: "Apply the High-Agency trade page layout (Settings → Layout)",
  },
  {
    id: "switchLayoutHumanInLoop",
    label: "Switch to Human-in-Loop layout",
    description: "Apply the Human-in-Loop trade page layout (Settings → Layout)",
  },
  {
    id: "intentSubmitValidate",
    label: "Validate or deploy intent",
    description: "Parse & validate, or deploy when already validated (intent modal)",
  },
  {
    id: "openWalletMenu",
    label: "Open wallet menu",
    description: "Toggle wallet panel when connected, or open connect modal when not",
  },
];

export function findShortcutAction(id: ShortcutActionId): ShortcutActionDefinition {
  const action = SHORTCUT_ACTION_CATALOG.find((entry) => entry.id === id);
  if (!action) {
    throw new Error(`Unknown shortcut action: ${id}`);
  }
  return action;
}
