import React, { useMemo } from "react";
import { AxisBottom, AxisLeft } from "@visx/axis";
import { GridColumns, GridRows } from "@visx/grid";
import { Group } from "@visx/group";
import { ParentSize } from "@visx/responsive";
import { scaleLinear } from "@visx/scale";
import { Circle } from "@visx/shape";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import {
  AGENT_RANK_ACTION_LABELS,
  AGENT_RANK_QUADRANT_LABELS,
  buildAgentRankQuadrantLayout,
  type AgentRankRow,
  type AgentRankSummary,
} from "../../utils/portfolioAgentRankMetrics";
import "./portfolio.css";

export interface PortfolioAgentRankQuadrantChartProps {
  summary: AgentRankSummary;
  focusAgentId?: string | null;
}

const MARGIN = { top: 28, right: 12, bottom: 40, left: 44 };
const AXIS_COLOR = TERMINAL_COLORS.textSecondary;
const GRID_COLOR = TERMINAL_COLORS.gridMajor;
const DIVIDER_COLOR = "rgba(255, 255, 255, 0.28)";
const QUADRANT_FILL = "rgba(255, 255, 255, 0.025)";
const MARKER_RADIUS = 6;

const QUADRANT_CORNER_LABELS: {
  quadrant: keyof typeof AGENT_RANK_QUADRANT_LABELS;
  x: "left" | "right";
  y: "top" | "bottom";
}[] = [
  { quadrant: "stars", x: "left", y: "top" },
  { quadrant: "volatileWinners", x: "right", y: "top" },
  { quadrant: "steady", x: "left", y: "bottom" },
  { quadrant: "pauseRework", x: "right", y: "bottom" },
];

function formatPct(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`;
}

function formatSharpe(value: number): string {
  return value.toFixed(2);
}

function formatProfitFactor(value: number): string {
  return `${value.toFixed(1)}×`;
}

function buildAgentTipTitle(agent: AgentRankRow): string {
  return `${agent.icon ? `${agent.icon} ` : ""}${agent.label}`;
}

function buildAgentTipContent(
  agent: AgentRankRow,
  quadrantLabel: string,
): string {
  return [
    `${quadrantLabel}.`,
    `CAGR ${formatPct(agent.cagrPct)} · MDD -${agent.maxDrawdownPct.toFixed(1)}%.`,
    `Sharpe ${formatSharpe(agent.sharpe)} · PF ${formatProfitFactor(agent.profitFactor)} · Composite ${agent.compositeScore.toFixed(0)} · ${AGENT_RANK_ACTION_LABELS[agent.actionHint]}.`,
  ].join(" ");
}

interface MarkerLayout {
  agent: AgentRankRow;
  quadrantLabel: string;
  leftPct: number;
  topPct: number;
}

function QuadrantChartInner({
  width,
  height,
  summary,
  focusAgentId = null,
}: {
  width: number;
  height: number;
  summary: AgentRankSummary;
  focusAgentId?: string | null;
}): JSX.Element {
  const layout = useMemo(
    () => buildAgentRankQuadrantLayout(summary.agents),
    [summary.agents],
  );

  const innerWidth = Math.max(width - MARGIN.left - MARGIN.right, 1);
  const innerHeight = Math.max(height - MARGIN.top - MARGIN.bottom, 1);

  const xScale = useMemo(
    () =>
      scaleLinear<number>({
        domain: [layout.xMin, layout.xMax],
        range: [0, innerWidth],
        clamp: true,
      }),
    [layout.xMin, layout.xMax, innerWidth],
  );

  const yScale = useMemo(
    () =>
      scaleLinear<number>({
        domain: [layout.yMin, layout.yMax],
        range: [innerHeight, 0],
        clamp: true,
      }),
    [layout.yMin, layout.yMax, innerHeight],
  );

  const dividerX = xScale(layout.mddThreshold);
  const dividerY = yScale(layout.cagrThreshold);

  const markers: MarkerLayout[] = useMemo(
    () =>
      layout.points.map((point) => ({
        agent: point.agent,
        quadrantLabel: AGENT_RANK_QUADRANT_LABELS[point.quadrant],
        leftPct:
          ((MARGIN.left + xScale(point.x)) / Math.max(width, 1)) * 100,
        topPct:
          ((MARGIN.top + yScale(point.y)) / Math.max(height, 1)) * 100,
      })),
    [layout.points, xScale, yScale, width, height],
  );

  return (
    <div className="portfolio-agent-rank-quadrant-wrap">
      <svg width={width} height={height} className="portfolio-agent-rank-quadrant-svg">
        <rect
          width={width}
          height={height}
          fill={TERMINAL_COLORS.panel}
          rx={4}
        />
        <Group left={MARGIN.left} top={MARGIN.top}>
          <rect
            x={0}
            y={0}
            width={dividerX}
            height={dividerY}
            fill={QUADRANT_FILL}
          />
          <rect
            x={dividerX}
            y={0}
            width={innerWidth - dividerX}
            height={dividerY}
            fill={QUADRANT_FILL}
          />
          <rect
            x={0}
            y={dividerY}
            width={dividerX}
            height={innerHeight - dividerY}
            fill={QUADRANT_FILL}
          />
          <rect
            x={dividerX}
            y={dividerY}
            width={innerWidth - dividerX}
            height={innerHeight - dividerY}
            fill={QUADRANT_FILL}
          />

          <GridRows
            scale={yScale}
            width={innerWidth}
            stroke={GRID_COLOR}
            strokeDasharray="2 4"
          />
          <GridColumns
            scale={xScale}
            height={innerHeight}
            stroke={GRID_COLOR}
            strokeDasharray="2 4"
          />

          <line
            x1={dividerX}
            x2={dividerX}
            y1={0}
            y2={innerHeight}
            stroke={DIVIDER_COLOR}
            strokeDasharray="4 4"
          />
          <line
            x1={0}
            x2={innerWidth}
            y1={dividerY}
            y2={dividerY}
            stroke={DIVIDER_COLOR}
            strokeDasharray="4 4"
          />

          {layout.points.map((point) => {
            const isFocused = focusAgentId === point.agent.id;
            const isDimmed = focusAgentId != null && !isFocused;
            const radius = isFocused ? 10 : MARKER_RADIUS;
            const label =
              point.agent.icon ??
              point.agent.label.slice(0, isFocused ? 3 : 2);
            return (
              <g
                key={point.agent.id}
                className={`portfolio-agent-rank-quadrant-marker${isFocused ? " is-focused" : ""}${isDimmed ? " is-dimmed" : ""}`}
                opacity={isDimmed ? 0.45 : 1}
              >
                <Circle
                  cx={xScale(point.x)}
                  cy={yScale(point.y)}
                  r={radius}
                  fill={point.agent.color}
                  stroke={
                    isFocused
                      ? TERMINAL_COLORS.brand
                      : "rgba(10, 14, 23, 0.9)"
                  }
                  strokeWidth={isFocused ? 2.5 : 1.5}
                />
                <text
                  x={xScale(point.x)}
                  y={yScale(point.y) + 16}
                  textAnchor="middle"
                  className="portfolio-agent-rank-quadrant-marker-label"
                >
                  {label}
                </text>
              </g>
            );
          })}

          {QUADRANT_CORNER_LABELS.map(({ quadrant, x, y }) => (
            <text
              key={quadrant}
              x={x === "left" ? 4 : innerWidth - 4}
              y={y === "top" ? 12 : innerHeight - 6}
              textAnchor={x === "left" ? "start" : "end"}
              className="portfolio-agent-rank-quadrant-corner-label"
            >
              {AGENT_RANK_QUADRANT_LABELS[quadrant]}
            </text>
          ))}

          <AxisLeft
            scale={yScale}
            stroke={AXIS_COLOR}
            tickStroke={AXIS_COLOR}
            tickLabelProps={{
              fill: AXIS_COLOR,
              fontSize: 10,
              textAnchor: "end",
              dx: -4,
            }}
            numTicks={4}
            label="Return (CAGR %)"
            labelProps={{
              fill: AXIS_COLOR,
              fontSize: 10,
              textAnchor: "middle",
            }}
          />
          <AxisBottom
            top={innerHeight}
            scale={xScale}
            stroke={AXIS_COLOR}
            tickStroke={AXIS_COLOR}
            tickLabelProps={{
              fill: AXIS_COLOR,
              fontSize: 10,
              textAnchor: "middle",
              dy: 4,
            }}
            numTicks={4}
            label="Risk (Max DD %)"
            labelProps={{
              fill: AXIS_COLOR,
              fontSize: 10,
              textAnchor: "middle",
            }}
          />
        </Group>
      </svg>

      <div className="portfolio-agent-rank-quadrant-marker-layer">
        {markers.map(({ agent, quadrantLabel, leftPct, topPct }) => {
          if (focusAgentId != null && focusAgentId !== agent.id) {
            return null;
          }
          return (
            <BubbleTip
              key={agent.id}
              id={BUBBLE_TIP_IDS.agentRankAgent}
              title={buildAgentTipTitle(agent)}
              content={buildAgentTipContent(agent, quadrantLabel)}
              side="top"
            >
              <button
                type="button"
                className="portfolio-agent-rank-quadrant-marker-hit"
                style={{
                  left: `${leftPct}%`,
                  top: `${topPct}%`,
                }}
                aria-label={`${agent.label} quadrant details`}
              />
            </BubbleTip>
          );
        })}
      </div>
    </div>
  );
}

function PortfolioAgentRankQuadrantChart({
  summary,
  focusAgentId = null,
}: PortfolioAgentRankQuadrantChartProps): JSX.Element {
  if (summary.agents.length === 0) {
    return (
      <p className="terminal-text-muted portfolio-agent-rank-empty">
        No agent rank data.
      </p>
    );
  }

  return (
    <div className="portfolio-agent-rank-quadrant-parent">
      <ParentSize>
        {({ width, height }) =>
          width > 0 && height > 0 ? (
            <QuadrantChartInner
              width={width}
              height={height}
              summary={summary}
              focusAgentId={focusAgentId}
            />
          ) : null
        }
      </ParentSize>
    </div>
  );
}

export default React.memo(PortfolioAgentRankQuadrantChart);
