/**
 * Portfolio terminal page — multi-slot grid layout.
 */
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { ResponsiveLayouts, Layout } from "react-grid-layout";
import { GridViewerLayout, GRID_COLS, type TabSectionTabId } from "../components";
import {
  PortfolioEquitySummary,
  PortfolioFeesPanel,
  PortfolioHeroCharts,
  PortfolioHeroTitle,
  PortfolioLeaderboardPanel,
  PortfolioPerformanceAccountsPanel,
  PortfolioPerformanceMetricsPanel,
  PortfolioTabSection,
  PortfolioVolumePanel,
  CopiedAgentsStrip,
} from "../components/portfolio";
import type { HeroChartMode } from "../components/portfolio/PortfolioHeroCharts";
import type { PortfolioHeroView } from "../components/portfolio/portfolioHeroView";
import {
  applyPortfolioLayoutSizing,
  buildPortfolioResponsiveLayoutConfig,
  generatePortfolioResponsiveLayouts,
  patchPortfolioHeroView,
  patchPortfolioCopiedAgentsStrip,
  PORTFOLIO_LAYOUT_MARGIN,
  PORTFOLIO_MOBILE_HIDDEN_SLOTS,
  PORTFOLIO_ROW_HEIGHT,
} from "../configs/portfolioLayoutConfig";
import { MOBILE_BREAKPOINTS } from "../configs/terminalLayoutConfig";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import { useTransferModals } from "../context/TransferModalsContext";
import { useSubscription } from "../context/SubscriptionContext";
import { useOnboard } from "../hooks/useOnboard";
import { useFleetCopyRelations } from "../hooks/useFleetCopyRelations";
import { usePortfolioFleetFilter } from "../hooks/usePortfolioFleetFilter";
import { useTradingAgents } from "../hooks/useTradingAgents";
import { useAgentTasks } from "../hooks/useAgentTasks";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { useOptionalWelcomeTour } from "../tutorials/welcome-tour";
import { useOptionalDepositTour } from "../tutorials/deposit-tour";
import { useJellyMode } from "../context/JellyModeContext";
import { toast } from "sonner";
import { useSettings } from "../context/SettingsContext";
import { heroViewToChartMode } from "../components/portfolio/portfolioHeroView";
import { WalletConnectedGate } from "../components/wallet";
import "./PortfolioPage.css";

const INITIAL_CONFIG = {
  baseURL: "offline://local",
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [PORTFOLIO_LAYOUT_MARGIN, PORTFOLIO_LAYOUT_MARGIN] as const,
  refreshInterval: 5000,
} as const;

const ROW_HEIGHT = PORTFOLIO_ROW_HEIGHT;

function buildLayouts(
  viewportHeight?: number,
  heroView: PortfolioHeroView = "overview",
  showCopiedAgentsStrip = false,
) {
  let base = buildPortfolioResponsiveLayoutConfig();
  base = patchPortfolioHeroView(base, heroView);
  if (showCopiedAgentsStrip) {
    base = patchPortfolioCopiedAgentsStrip(base, true);
  }
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyPortfolioLayoutSizing(base, height);
  return generatePortfolioResponsiveLayouts(sized, 0);
}

export interface PortfolioPageProps {
  shellManagesOnboard?: boolean;
  shellWalletAddress?: string;
  shellMnemonic?: string;
  shellAuthToken?: string;
}

function PortfolioPageContent({
  shellManagesOnboard = false,
  shellWalletAddress,
  shellMnemonic,
  shellAuthToken,
}: PortfolioPageProps) {
  const { settings } = useSettings();
  const portfolioPrefs = settings.portfolio;

  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() =>
    buildLayouts(undefined, portfolioPrefs.defaultHeroView),
  );
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const [selectedBucketId, setSelectedBucketId] = useState<string>("--");
  const [tabSectionActiveTab, setTabSectionActiveTab] = useState<TabSectionTabId>(
    portfolioPrefs.defaultTab,
  );
  const [heroView, setHeroView] = useState<PortfolioHeroView>(
    portfolioPrefs.defaultHeroView,
  );
  const [heroChartMode, setHeroChartMode] = useState<HeroChartMode>(() =>
    heroViewToChartMode(portfolioPrefs.defaultHeroView),
  );
  const [chartTimeRange, setChartTimeRange] = useState(portfolioPrefs.defaultTimeRange);
  const [isLayoutMounted, setIsLayoutMounted] = useState(false);
  const hasTriggeredToggleRef = useRef(false);
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);
  const currentBreakpointRef = useRef(currentBreakpoint);
  currentBreakpointRef.current = currentBreakpoint;

  const { selectedAgentIds } = usePortfolioFleetFilter();
  const { selectedAgentId: focusAgentId } = useTradingAgents();
  const { navigateToAgentTasks, setNavigateToAgentTasks } = useAgentTasks();
  const welcomeTour = useOptionalWelcomeTour();
  const depositTour = useOptionalDepositTour();
  const { isJellyMode } = useJellyMode();

  useEffect(() => {
    setHeroView(portfolioPrefs.defaultHeroView);
    setHeroChartMode(heroViewToChartMode(portfolioPrefs.defaultHeroView));
    setChartTimeRange(portfolioPrefs.defaultTimeRange);
    setTabSectionActiveTab(portfolioPrefs.defaultTab);
  }, [
    portfolioPrefs.defaultHeroView,
    portfolioPrefs.defaultTimeRange,
    portfolioPrefs.defaultTab,
  ]);

  useEffect(() => {
    if (navigateToAgentTasks) {
      setTabSectionActiveTab("agentTasks");
      setNavigateToAgentTasks(false);
    }
  }, [navigateToAgentTasks, setNavigateToAgentTasks]);

  const [sessionToken, setSessionToken] = useState(
    () => localStorage.getItem("authToken") || "",
  );

  const {
    mnemonic,
    walletAddress,
    authToken: onboardAuthToken,
  } = useOnboard(INITIAL_CONFIG.baseURL);

  const effectiveWalletAddress =
    shellManagesOnboard && shellWalletAddress !== undefined
      ? shellWalletAddress
      : (walletAddress ?? "");
  const { relations: copiedAgentRelations } = useFleetCopyRelations(
    effectiveWalletAddress,
  );
  const showCopiedAgentsStrip =
    Boolean(effectiveWalletAddress?.trim()) && copiedAgentRelations.length > 0;

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(
        window.innerHeight,
        heroView,
        showCopiedAgentsStrip,
      );
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };

    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, [heroView, showCopiedAgentsStrip]);

  const effectiveMnemonic =
    shellManagesOnboard && shellMnemonic !== undefined
      ? shellMnemonic
      : (mnemonic ?? "");

  useEffect(() => {
    if (!shellManagesOnboard || shellAuthToken === undefined) return;
    setSessionToken(shellAuthToken);
    if (shellAuthToken) localStorage.setItem("authToken", shellAuthToken);
    else localStorage.removeItem("authToken");
  }, [shellManagesOnboard, shellAuthToken]);

  useEffect(() => {
    if (shellManagesOnboard) return;
    setSessionToken(onboardAuthToken ?? "");
    if (onboardAuthToken) localStorage.setItem("authToken", onboardAuthToken);
    else localStorage.removeItem("authToken");
  }, [shellManagesOnboard, onboardAuthToken]);

  const isOfflineModeActive = isOfflineMode(INITIAL_CONFIG.baseURL);
  const { setAuthToken, setWalletAddress, toggleEnabled } = useSubscription();

  useEffect(() => {
    if (!isOfflineModeActive) setAuthToken(sessionToken || undefined);
  }, [isOfflineModeActive, sessionToken, setAuthToken]);

  useEffect(() => {
    if (!isOfflineModeActive) {
      setWalletAddress(effectiveWalletAddress || undefined);
    }
  }, [isOfflineModeActive, effectiveWalletAddress, setWalletAddress]);

  const { openBucketTransfer, openCoinTransfer, openCrossChainFlow } = useTransferModals();

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const isMobile = (MOBILE_BREAKPOINTS as readonly string[]).includes(
    currentBreakpoint,
  );

  const handleLayoutMount = useCallback(() => setIsLayoutMounted(true), []);

  useEffect(() => {
    if (!isLayoutMounted || hasTriggeredToggleRef.current) return;
    if (effectiveWalletAddress?.trim()) {
      hasTriggeredToggleRef.current = true;
      if (!isOfflineModeActive) setTimeout(() => toggleEnabled(), 100);
    }
  }, [
    isLayoutMounted,
    effectiveWalletAddress,
    toggleEnabled,
    isOfflineModeActive,
  ]);

  useEffect(() => {
    if (!welcomeTour?.registerTabController) return;
    return welcomeTour.registerTabController((tabId) => {
      setTabSectionActiveTab(tabId);
    });
  }, [welcomeTour?.registerTabController]);

  useEffect(() => {
    if (!welcomeTour?.registerBreakpoint) return;
    return welcomeTour.registerBreakpoint(() => currentBreakpointRef.current);
  }, [welcomeTour?.registerBreakpoint]);

  useEffect(() => {
    if (!depositTour?.registerBreakpoint) return;
    return depositTour.registerBreakpoint(() => currentBreakpointRef.current);
  }, [depositTour?.registerBreakpoint]);

  const handleRequestDepositTour = useCallback(() => {
    if (isJellyMode) {
      toast.info("Exit JELLY mode to run the deposit tour.");
      return;
    }
    depositTour?.startDepositTour({ entry: "deposit-form" });
  }, [depositTour, isJellyMode]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const analyticsProps = useMemo(
    () => ({
      baseURL: INITIAL_CONFIG.baseURL,
      walletAddress: effectiveWalletAddress,
      filterAgentIds: [] as string[],
      focusAgentId,
      refreshInterval: INITIAL_CONFIG.refreshInterval,
    }),
    [effectiveWalletAddress, focusAgentId],
  );

  const isPerformanceView = heroView === "performance";
  const isAgentRanksView = heroView === "agentRanks";

  const handleHeroViewChange = useCallback((view: PortfolioHeroView) => {
    setHeroView(view);
    if (view === "overview") {
      setHeroChartMode("equity");
    } else if (view === "agentRanks") {
      setHeroChartMode("agentRank");
    } else if (view === "performance") {
      setHeroChartMode("dailyPnl");
    }
  }, []);

  const handleHeroChartModeChange = useCallback((mode: HeroChartMode) => {
    setHeroChartMode(mode);
  }, []);

  const tabSectionProps = useMemo(
    () => ({
      baseURL: INITIAL_CONFIG.baseURL,
      authToken: sessionToken,
      walletAddress: effectiveWalletAddress,
      mnemonic: effectiveMnemonic,
      refreshInterval: INITIAL_CONFIG.refreshInterval,
      activeTab: tabSectionActiveTab,
      onTabChange: setTabSectionActiveTab,
      isMobile,
      layoutBreakpoint: currentBreakpoint,
      selectedBucketId,
      filterAgentIds: selectedAgentIds,
      onBucketSelect: (bucketId: string) => setSelectedBucketId(bucketId),
      onRequestOpenTransferModal: openBucketTransfer,
      onRequestOpenWalletTransferModal: openCoinTransfer,
      onRequestFundAccount: () => openCrossChainFlow("deposit"),
      onRequestDepositTour: handleRequestDepositTour,
      height: slotDimensions[4]?.height ?? "100%",
    }),
    [
      sessionToken,
      effectiveWalletAddress,
      effectiveMnemonic,
      tabSectionActiveTab,
      isMobile,
      currentBreakpoint,
      selectedBucketId,
      selectedAgentIds,
      openBucketTransfer,
      openCoinTransfer,
      openCrossChainFlow,
      handleRequestDepositTour,
      slotDimensions,
    ],
  );

  const slotContent = useMemo(
    () => [
      <PortfolioHeroTitle
        key="title"
        height={slotDimensions[0]?.height}
        walletAddress={effectiveWalletAddress}
        activeView={heroView}
        onViewChange={handleHeroViewChange}
      />,
      isPerformanceView ? (
        <WalletConnectedGate
          key="perf-metrics"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[1]?.height ?? "100%"}
        >
          <PortfolioPerformanceMetricsPanel
            height={slotDimensions[1]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ) : isAgentRanksView ? null : (
        <WalletConnectedGate
          key="volume"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[1]?.height ?? "100%"}
        >
          <PortfolioVolumePanel
            height={slotDimensions[1]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ),
      isPerformanceView ? (
        <WalletConnectedGate
          key="perf-accounts"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[2]?.height ?? "100%"}
        >
          <PortfolioPerformanceAccountsPanel
            height={slotDimensions[2]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ) : isAgentRanksView ? (
        <WalletConnectedGate
          key="leaderboard"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[2]?.height ?? "100%"}
        >
          <PortfolioLeaderboardPanel
            height={slotDimensions[2]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ) : (
        <WalletConnectedGate
          key="equity"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[2]?.height ?? "100%"}
        >
          <PortfolioEquitySummary
            height={slotDimensions[2]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ),
      <WalletConnectedGate
        key="charts"
        walletAddress={effectiveWalletAddress}
        variant="portfolio"
        height={slotDimensions[3]?.height ?? "100%"}
      >
        <PortfolioHeroCharts
          height={slotDimensions[3]?.height}
          chartMode={heroChartMode}
          onChartModeChange={handleHeroChartModeChange}
          timeRange={chartTimeRange}
          onTimeRangeChange={setChartTimeRange}
          heroView={heroView}
          layoutBreakpoint={currentBreakpoint}
          {...analyticsProps}
        />
      </WalletConnectedGate>,
      <PortfolioTabSection key="tabs" {...tabSectionProps} />,
      isPerformanceView || isAgentRanksView ? null : (
        <WalletConnectedGate
          key="fees"
          walletAddress={effectiveWalletAddress}
          variant="portfolio"
          height={slotDimensions[5]?.height ?? "100%"}
        >
          <PortfolioFeesPanel
            height={slotDimensions[5]?.height}
            {...analyticsProps}
          />
        </WalletConnectedGate>
      ),
      showCopiedAgentsStrip ? (
        <CopiedAgentsStrip
          key="copied-agents"
          height={slotDimensions[6]?.height}
          relations={copiedAgentRelations}
          walletAddress={effectiveWalletAddress}
        />
      ) : null,
      null,
      null,
    ],
    [
      slotDimensions,
      effectiveWalletAddress,
      heroView,
      isPerformanceView,
      isAgentRanksView,
      heroChartMode,
      handleHeroChartModeChange,
      chartTimeRange,
      handleHeroViewChange,
      analyticsProps,
      tabSectionProps,
      currentBreakpoint,
      showCopiedAgentsStrip,
      copiedAgentRelations,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--portfolio">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={PORTFOLIO_MOBILE_HIDDEN_SLOTS}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
        onMount={handleLayoutMount}
      />
    </div>
  );
}

export default function PortfolioPage(props: PortfolioPageProps) {
  return <PortfolioPageContent {...props} />;
}
