import React from "react";
import { formatCurrency } from "../../../sdk/utils/display";
import { DEMO_WARP_ROUTE } from "../../../types/crossChainFlow";
import type { CrossChainMode } from "../cross-chain-modal";
import type { WalletTransferAssetId } from "../wallet-transfer-modal";
import { CrossChainSecurityStepper } from "./CrossChainSecurityStepper";
import "./cross-chain.css";

export interface CrossChainSubmitPanelProps {
  mode: CrossChainMode;
  assetId: WalletTransferAssetId;
  amount: number;
  chain: string;
  isWaiting: boolean;
  onSimulateSignature: () => void;
}

export function CrossChainSubmitPanel({
  mode,
  assetId,
  amount,
  chain,
  isWaiting,
  onSimulateSignature,
}: CrossChainSubmitPanelProps): JSX.Element {
  const chainName = chain.charAt(0).toUpperCase() + chain.slice(1);
  const lockPhrase =
    mode === "deposit"
      ? `This signature WILL lock ${formatCurrency(amount)} ${assetId} on ${chainName}.`
      : `This signature WILL lock ${formatCurrency(amount)} ${assetId} on Morpheum.`;

  return (
    <>
      <p className="terminal-label cross-chain-status-label">
        {isWaiting ? "◑ waiting for signature" : "◑ ready to sign"}
      </p>
      <CrossChainSecurityStepper
        activeStage="submit"
        completedStages={assetId !== "BTC" ? ["authorize"] : []}
      />
      <p className="cross-chain-body-copy cross-chain-body-copy--spaced">{lockPhrase}</p>
      <p className="cross-chain-body-copy">Verify before signing:</p>
      <dl className="cross-chain-signature-verify">
        <dt>to</dt>
        <dd className="cross-chain-amount-value terminal-value">
          {DEMO_WARP_ROUTE.slice(0, 6)}…{DEMO_WARP_ROUTE.slice(-4)} (warp route)
        </dd>
        <dt>amount</dt>
        <dd className="cross-chain-amount-value terminal-value">
          {formatCurrency(amount)} {assetId}
        </dd>
      </dl>
      <button
        type="button"
        className="btn btn-primary cross-chain-btn-full"
        disabled={isWaiting}
        onClick={onSimulateSignature}
        data-tour="deposit-tour-submit-btn"
      >
        {isWaiting ? "Waiting…" : "Simulate signature"}
      </button>
    </>
  );
}
