import { N, Q } from "./constants";
import type { Membership, QuorumStats, Validator, ValidatorGroups, VerdictKind } from "./types";

export function cluster(idx: number, count: number): { dx: number; dy: number } {
  const perRow = 3;
  const row = Math.floor(idx / perRow);
  const col = idx % perRow;
  const rows = Math.ceil(count / perRow);
  const dx = (col - (Math.min(count, perRow) - 1) / 2) * 9;
  const dy = (row - (rows - 1) / 2) * 9;
  return { dx, dy };
}

export function groupValidators(validators: Validator[]): ValidatorGroups {
  const groups: ValidatorGroups = { a: [], both: [], b: [], none: [] };
  validators.forEach((v) => groups[v.m].push(v));
  return groups;
}

export function computeStats(validators: Validator[], groups: ValidatorGroups): QuorumStats {
  const sizeA = groups.a.length + groups.both.length;
  const sizeB = groups.b.length + groups.both.length;
  const inter = groups.both;
  const honestInter = inter.filter((v) => !v.byz);
  const byzCount = validators.filter((v) => v.byz).length;

  return {
    sizeA,
    sizeB,
    interCount: inter.length,
    honestInterCount: honestInter.length,
    byzCount,
    faultOk: 3 * byzCount < N,
    aValid: sizeA >= Q,
    bValid: sizeB >= Q,
  };
}

export function getVerdictKind(stats: QuorumStats): VerdictKind {
  if (!stats.aValid || !stats.bValid) return "warn";
  if (!stats.faultOk) return "bad";
  return "ok";
}

export function isSharedHonest(
  region: Membership,
  validator: Validator,
  stats: QuorumStats,
): boolean {
  return region === "both" && !validator.byz && stats.faultOk && stats.aValid && stats.bValid;
}
