import { useCallback, useMemo, useState } from "react";

import {
  addSavedCompareList,
  isCompareSetSaved,
  loadSavedCompareLists,
  persistSavedCompareLists,
  removeSavedCompareList,
  sortSavedCompareListsNewestFirst,
  type SavedCompareList,
} from "../utils/agentCompareSavedLists";

export function useAgentCompareSavedLists(currentCompareIds: string[]) {
  const [savedLists, setSavedLists] = useState<SavedCompareList[]>(loadSavedCompareLists);

  const sortedSavedLists = useMemo(
    () => sortSavedCompareListsNewestFirst(savedLists),
    [savedLists],
  );

  const isCurrentSaved = useMemo(
    () => isCompareSetSaved(savedLists, currentCompareIds),
    [savedLists, currentCompareIds],
  );

  const addCurrentList = useCallback((agentIds: string[]) => {
    setSavedLists((prev) => {
      const next = addSavedCompareList(prev, agentIds);
      if (next.length === prev.length) return prev;
      persistSavedCompareLists(next);
      return next;
    });
  }, []);

  const removeList = useCallback((id: string) => {
    setSavedLists((prev) => {
      const next = removeSavedCompareList(prev, id);
      if (next.length === prev.length) return prev;
      persistSavedCompareLists(next);
      return next;
    });
  }, []);

  return {
    savedLists: sortedSavedLists,
    isCurrentSaved,
    addCurrentList,
    removeList,
  };
}
