import type { MarketRow } from "../hooks/useMarketsPageData";
import type { CompactMetricDefinition } from "../components/metrics/types";
import { formatPercent } from "../components/index/indexFormat";
import {
  buildSignedPercentLineData,
  buildSparklineLineData,
  HOUR_MS,
} from "./compactMetricChartData";

const COPY_TREND_POINTS = 7;
const COPY_TREND_STEP_MS = 24 * HOUR_MS;
const INDEX_TREND_POINTS = 24;

function formatCopyCount(value: number): string {
  return Math.round(value).toLocaleString();
}

export function buildAgentCopyingMetric(
  row: MarketRow,
  showChart: boolean,
): CompactMetricDefinition | null {
  if (row.copyCount == null) return null;

  const value = row.isPopular
    ? `${row.copyCount.toLocaleString()} · popular`
    : row.copyCount.toLocaleString();

  const metric: CompactMetricDefinition = {
    id: "copying",
    label: "Copying",
    value,
    valueTone: "neutral",
  };

  if (showChart) {
    metric.chart = {
      kind: "line",
      data: buildSparklineLineData(
        row.sparkline,
        row.copyCount,
        COPY_TREND_POINTS,
        COPY_TREND_STEP_MS,
      ),
      formatValue: formatCopyCount,
    };
  }

  return metric;
}

export function buildIndexTrendMetric(
  row: MarketRow,
  showChart: boolean,
): CompactMetricDefinition {
  const metric: CompactMetricDefinition = {
    id: "trend",
    label: "Trend",
    value: formatPercent(row.change24h),
    valueTone: "signed",
  };

  if (showChart) {
    metric.chart = {
      kind: "line",
      data: buildSignedPercentLineData(
        row.sparkline,
        row.change24h,
        INDEX_TREND_POINTS,
        HOUR_MS,
      ),
    };
  }

  return metric;
}

export function buildMarketsTableMetric(
  row: MarketRow,
  showChart: boolean,
): CompactMetricDefinition | null {
  if (row.kind === "agent") {
    return buildAgentCopyingMetric(row, showChart);
  }
  return buildIndexTrendMetric(row, showChart);
}
