import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the agent detail page layout */
export const AGENT_SLOT_INDICES = {
  hero: 0,
  chart: 1,
  action: 3,
  tabs: 4,
  metrics: 5,
  discovery: 6,
} as const;

export const AGENT_TAB_SLOT_INDEX = AGENT_SLOT_INDICES.tabs;
export const AGENT_DISCOVERY_SLOT_INDEX = AGENT_SLOT_INDICES.discovery;

/** Slots collapsed on all breakpoints */
export const AGENT_COLLAPSED_SLOTS = [2, 7, 8] as const;

export const AGENT_ROW_HEIGHT = 30;
export const AGENT_MENUBAR_HEIGHT = 54;
export const AGENT_LAYOUT_MARGIN = 10;
export const AGENT_VIEWPORT_FUDGE_PX = 4;

export const AGENT_TITLE_ROWS = 2;
export const AGENT_METRICS_ROWS = 2;
export const AGENT_CHART_ROWS = 10;
export const AGENT_ACTION_ROWS = 10;
/** lg desktop right rail — taller than stacked action band */
export const AGENT_ACTION_ROWS_LG = 22;
export const AGENT_BASE_TAB_ROWS = 6;
export const AGENT_SCROLL_TAB_ROWS = 12;
export const AGENT_DISCOVERY_ROWS = 3;

export const AGENT_TITLE_COLS_LG = 4;
export const AGENT_METRICS_COLS_LG = 8;
export const AGENT_LEFT_COLS_LG = 8;
export const AGENT_RIGHT_COLS_LG = 4;

export const AGENT_HERO_START_ROW = AGENT_TITLE_ROWS;
export const AGENT_TAB_START_ROW = AGENT_HERO_START_ROW + AGENT_CHART_ROWS;

export const AGENT_STACKED_METRICS_START_ROW = AGENT_TITLE_ROWS;
export const AGENT_STACKED_ACTION_START_ROW =
  AGENT_HERO_START_ROW + AGENT_CHART_ROWS;
export const AGENT_STACKED_TAB_START_ROW =
  AGENT_STACKED_ACTION_START_ROW + AGENT_ACTION_ROWS;

export const AGENT_NAV_START_ROW_LG =
  AGENT_TAB_START_ROW + AGENT_SCROLL_TAB_ROWS;
export const AGENT_NAV_START_ROW_STACKED =
  AGENT_STACKED_TAB_START_ROW + AGENT_SCROLL_TAB_ROWS;
export const AGENT_MOBILE_TAB_START_ROW =
  AGENT_STACKED_METRICS_START_ROW +
  AGENT_METRICS_ROWS +
  AGENT_CHART_ROWS +
  AGENT_ACTION_ROWS;
export const AGENT_NAV_START_ROW_MOBILE =
  AGENT_MOBILE_TAB_START_ROW + AGENT_SCROLL_TAB_ROWS;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];

function discoveryTail(cols: number, yDiscovery: number): LayoutConfigLest {
  return [
    [0, yDiscovery, cols, AGENT_DISCOVERY_ROWS],
    COLLAPSED,
    COLLAPSED,
  ];
}

function splitTitleMetricsCols(cols: number): {
  titleW: number;
  metricsW: number;
  metricsX: number;
} {
  const titleW = Math.round(cols / 3);
  const metricsW = cols - titleW;
  return { titleW, metricsW, metricsX: titleW };
}

function titleMetricsSlot5(
  cols: number,
  stacked: boolean,
): [LayoutDefinition, LayoutDefinition] {
  if (stacked) {
    return [
      [0, 0, cols, AGENT_TITLE_ROWS],
      [0, AGENT_STACKED_METRICS_START_ROW, cols, AGENT_METRICS_ROWS],
    ];
  }

  if (cols === 12) {
    return [
      [0, 0, AGENT_TITLE_COLS_LG, AGENT_TITLE_ROWS],
      [AGENT_TITLE_COLS_LG, 0, AGENT_METRICS_COLS_LG, AGENT_METRICS_ROWS],
    ];
  }

  const { titleW, metricsW, metricsX } = splitTitleMetricsCols(cols);
  return [
    [0, 0, titleW, AGENT_TITLE_ROWS],
    [metricsX, 0, metricsW, AGENT_METRICS_ROWS],
  ];
}

function desktopAgentLayout(cols: number): LayoutConfigLest {
  const left = cols === 12 ? AGENT_LEFT_COLS_LG : Math.floor(cols * 0.67);
  const right = cols - left;
  const actionRows = cols === 12 ? AGENT_ACTION_ROWS_LG : AGENT_ACTION_ROWS;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, AGENT_HERO_START_ROW, left, AGENT_CHART_ROWS],
    COLLAPSED,
    [left, AGENT_HERO_START_ROW, right, actionRows],
    [0, AGENT_TAB_START_ROW, left, AGENT_BASE_TAB_ROWS],
    metricsSlot,
    ...discoveryTail(cols, AGENT_NAV_START_ROW_LG),
  ];
}

function stackedAgentLayout(cols: number): LayoutConfigLest {
  const yChart = AGENT_HERO_START_ROW;
  const yAction = AGENT_STACKED_ACTION_START_ROW;
  const yTabs = AGENT_STACKED_TAB_START_ROW;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, yChart, cols, AGENT_CHART_ROWS],
    COLLAPSED,
    [0, yAction, cols, AGENT_ACTION_ROWS],
    [0, yTabs, cols, AGENT_BASE_TAB_ROWS],
    metricsSlot,
    ...discoveryTail(cols, AGENT_NAV_START_ROW_STACKED),
  ];
}

function mobileAgentLayout(cols: number): LayoutConfigLest {
  const yChart = AGENT_STACKED_METRICS_START_ROW + AGENT_METRICS_ROWS;
  const yAction = yChart + AGENT_CHART_ROWS;
  const yTabs = yAction + AGENT_ACTION_ROWS;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, true);
  return [
    titleSlot,
    [0, yChart, cols, AGENT_CHART_ROWS],
    COLLAPSED,
    [0, yAction, cols, AGENT_ACTION_ROWS],
    [0, yTabs, cols, AGENT_BASE_TAB_ROWS],
    metricsSlot,
    ...discoveryTail(cols, AGENT_NAV_START_ROW_MOBILE),
  ];
}

export const agentLayoutLg: LayoutConfigLest = desktopAgentLayout(12);
export const agentLayoutMd: LayoutConfigLest = stackedAgentLayout(10);
export const agentLayoutSm: LayoutConfigLest = stackedAgentLayout(6);
export const agentLayoutXs: LayoutConfigLest = mobileAgentLayout(4);
export const agentLayoutXxs: LayoutConfigLest = mobileAgentLayout(2);

export function buildAgentResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, AGENT_COLLAPSED_SLOTS);

  return {
    lg: collapseAll(agentLayoutLg),
    md: collapseAll(agentLayoutMd),
    sm: collapseAll(agentLayoutSm),
    xs: collapseAll(agentLayoutXs),
    xxs: collapseAll(agentLayoutXxs),
  };
}

export function generateAgentResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

function patchTabSlotHeight(
  layout: LayoutConfigLest,
  tabRows: number,
): LayoutConfigLest {
  const tabSlot = layout[AGENT_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const next: LayoutDefinition = [tabSlot[0], tabSlot[1], tabSlot[2], tabRows];

  return layout.map((item, index) =>
    index === AGENT_TAB_SLOT_INDEX ? next : item,
  );
}

export function patchAgentScrollTabHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTabSlotHeight(layout, AGENT_SCROLL_TAB_ROWS);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/** Fixed tab rows on all breakpoints; page scrolls vertically. */
export function applyAgentLayoutSizing(
  config: ResponsiveLayoutConfig,
  _viewportHeight?: number,
): ResponsiveLayoutConfig {
  return patchAgentScrollTabHeights(config);
}

export function assertAgentLayoutValid(config: ResponsiveLayoutConfig): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `agent ${bp}`);
  }
}
