import { getAgentKpiSummaryByCatalogId } from "../../../offline/mock_data/agentKpiManifestSnapshot";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { Bucket } from "../../sdk";
import { formatCurrency } from "../../sdk/utils/display";
import type { CopyAutonomyPreset } from "../../../offline/mock_data/fleetCopyRelations";
import {
  autonomyBadgeCopy,
  autonomyPolicyForPreset,
  type AutonomyPreset,
} from "../tradeagent/autonomyPolicy";

export type CopyAgentLeaderChip = {
  label: string;
  value: string;
  tone?: "positive" | "negative" | "neutral";
};

export type CopyAgentCostDisclosure = {
  performanceFeePct: number;
  estSpreadPct: number;
  fundingLabel: string;
};

export type CopyAgentRiskPreview = {
  capitalAtRisk: number;
  estPerTrade: number;
  maxLoss: number;
  estLiquidationMovePct: number;
  costs: CopyAgentCostDisclosure;
};

export type CopyAgentRiskPreviewInput = {
  destinationMode: "new" | "existing";
  startingMargin: number;
  existingBucket: Bucket | null | undefined;
  copySizePct: number;
  autonomyPreset: CopyAutonomyPreset;
  profileLeverage?: number;
};

const DEMO_PERFORMANCE_FEE_PCT = 10;
const DEMO_EST_SPREAD_PCT = 0.05;

function monthsSince(isoDate: string): number {
  const deployed = Date.parse(isoDate);
  if (Number.isNaN(deployed)) return 0;
  const months = (Date.now() - deployed) / (30 * 24 * 60 * 60 * 1000);
  return Math.max(1, Math.round(months));
}

function formatTrackLength(months: number): string {
  if (months < 12) return `${months}mo`;
  const years = Math.floor(months / 12);
  const rem = months % 12;
  return rem > 0 ? `${years}y ${rem}mo` : `${years}y`;
}

export function buildCopyAgentLeaderChips(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): CopyAgentLeaderChip[] {
  const kpi = getAgentKpiSummaryByCatalogId(profile.id);
  const pnl30d = profile.stats.find((stat) => stat.label === "30d PnL");
  const sharpe = profile.stats.find((stat) => stat.label === "Sharpe");
  const maxDd = profile.stats.find((stat) => stat.label === "Max DD");
  const tradeCount = kpi
    ? Math.round(kpi.timeLivePct * 2.4)
    : Math.round(fleet.winRatePct * 3.2);
  const trackMonths = monthsSince(fleet.agentDeployedAt);

  return [
    {
      label: "30d PnL",
      value: pnl30d?.value ?? "—",
      tone: pnl30d?.tone,
    },
    {
      label: "Win",
      value: `${fleet.winRatePct}%`,
      tone: "neutral",
    },
    {
      label: "MDD",
      value: maxDd?.value ?? (kpi ? `-${kpi.maxDdPct}%` : "—"),
      tone: "negative",
    },
    {
      label: "Sharpe",
      value: sharpe?.value ?? (kpi ? kpi.sharpe30d.toFixed(1) : "—"),
      tone: "positive",
    },
    {
      label: "Trades",
      value: `${tradeCount}`,
      tone: "neutral",
    },
    {
      label: "Track",
      value: formatTrackLength(trackMonths),
      tone: "neutral",
    },
  ];
}

export function resolveCapitalAtRisk(input: CopyAgentRiskPreviewInput): number {
  if (input.destinationMode === "new") {
    return input.startingMargin;
  }
  return Number(input.existingBucket?.totalEquity ?? 0);
}

export function buildCopyAgentRiskPreview(
  input: CopyAgentRiskPreviewInput,
  profile: PropertyProfile,
): CopyAgentRiskPreview {
  const capitalAtRisk = resolveCapitalAtRisk(input);
  const estPerTrade = capitalAtRisk * (input.copySizePct / 100);
  const maxLoss = -capitalAtRisk;
  const leverage = input.profileLeverage ?? profile.leverage ?? 20;
  const marginRatio = Number(input.existingBucket?.marginRatio ?? 0);
  const maintenancePct =
    marginRatio > 0 ? marginRatio : Math.max(5, 100 / Math.max(leverage, 1));
  const estLiquidationMovePct = Math.round(
    Math.min(95, (capitalAtRisk > 0 ? 100 / leverage : 50) + maintenancePct * 0.4),
  );

  const fundingPct = profile.annFunding ?? 0;

  return {
    capitalAtRisk,
    estPerTrade,
    maxLoss,
    estLiquidationMovePct,
    costs: {
      performanceFeePct: DEMO_PERFORMANCE_FEE_PCT,
      estSpreadPct: DEMO_EST_SPREAD_PCT,
      fundingLabel:
        fundingPct > 0 ? `${fundingPct.toFixed(1)}% ann.` : "variable",
    },
  };
}

export function formatCopyAgentAutonomySummary(
  autonomyPreset: CopyAutonomyPreset,
): { label: string; description: string; toneClass: string } {
  const badge = autonomyBadgeCopy(
    autonomyPolicyForPreset(autonomyPreset as AutonomyPreset),
  );
  return {
    label: badge.headline,
    description: badge.subline,
    toneClass: `agent-copy-autonomy-tone--${badge.tone}`,
  };
}

export function formatSignedCurrency(value: number): string {
  const formatted = formatCurrency(Math.abs(value));
  if (value > 0) return `+${formatted}`;
  if (value < 0) return `-${formatted}`;
  return formatted;
}

export function deriveCopierBucketPnl(bucket: Bucket | null | undefined): {
  value: number;
  formatted: string;
  tone: "positive" | "negative" | "neutral";
} {
  if (!bucket) {
    return { value: 0, formatted: formatCurrency(0), tone: "neutral" };
  }
  const unrealized = bucket.unrealizedPnL ?? 0;
  const realized =
    (bucket.realizedProfit ?? 0) - (bucket.realizedLoss ?? 0);
  const value = unrealized + realized;
  return {
    value,
    formatted: formatSignedCurrency(value),
    tone: value > 0 ? "positive" : value < 0 ? "negative" : "neutral",
  };
}
