import type {
  AgentKpiHistoryFile,
  AgentKpiHistoryManifest,
} from "../../../../offline/mock_data/agentKpiHistory.types";

export const AGENT_KPI_HISTORY_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_AGENT_KPI_HISTORY_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/agent-kpi-history";

let manifestCache: AgentKpiHistoryManifest | null = null;
let manifestPromise: Promise<AgentKpiHistoryManifest> | null = null;
const historyCache = new Map<string, AgentKpiHistoryFile>();
const historyPromises = new Map<string, Promise<AgentKpiHistoryFile>>();

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearAgentKpiHistoryCache(): void {
  manifestCache = null;
  manifestPromise = null;
  historyCache.clear();
  historyPromises.clear();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export async function fetchAgentKpiManifest(
  baseUrl: string = AGENT_KPI_HISTORY_DATA_BASE_URL,
): Promise<AgentKpiHistoryManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<AgentKpiHistoryManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  ).then((manifest) => {
    manifestCache = manifest;
    return manifest;
  }).finally(() => {
    manifestPromise = null;
  });

  return manifestPromise;
}

export function getCachedAgentKpiManifest(): AgentKpiHistoryManifest | null {
  return manifestCache;
}

export function getManifestKpiAgentByCatalogId(
  manifest: AgentKpiHistoryManifest,
  catalogAgentId: string,
): AgentKpiHistoryManifest["agents"][number] | undefined {
  const normalized = catalogAgentId.trim().toLowerCase();
  return manifest.agents.find(
    (agent) => agent.catalogAgentId.toLowerCase() === normalized,
  );
}

export async function fetchAgentKpiByCatalogId(
  catalogAgentId: string,
  baseUrl: string = AGENT_KPI_HISTORY_DATA_BASE_URL,
): Promise<AgentKpiHistoryFile> {
  const normalizedId = catalogAgentId.trim().toLowerCase();
  const cached = historyCache.get(normalizedId);
  if (cached) return cached;

  const inflight = historyPromises.get(normalizedId);
  if (inflight) return inflight;

  const promise = (async () => {
    const manifest = await fetchAgentKpiManifest(baseUrl);
    const agent = getManifestKpiAgentByCatalogId(manifest, catalogAgentId);
    if (!agent) {
      throw new Error(`Unknown catalog agent id: ${catalogAgentId}`);
    }

    const payload = await fetchJson<AgentKpiHistoryFile>(
      joinBaseUrl(baseUrl, agent.file),
    );
    historyCache.set(normalizedId, payload);
    return payload;
  })().finally(() => {
    historyPromises.delete(normalizedId);
  });

  historyPromises.set(normalizedId, promise);
  return promise;
}

export async function fetchAgentKpiForAgents(
  catalogAgentIds: readonly string[],
  baseUrl: string = AGENT_KPI_HISTORY_DATA_BASE_URL,
): Promise<Map<string, AgentKpiHistoryFile>> {
  const uniqueIds = [...new Set(catalogAgentIds.map((id) => id.trim()).filter(Boolean))];
  const entries = await Promise.all(
    uniqueIds.map(async (id) => [id, await fetchAgentKpiByCatalogId(id, baseUrl)] as const),
  );
  return new Map(entries);
}

export function getCachedAgentKpiByCatalogId(
  catalogAgentId: string,
): AgentKpiHistoryFile | null {
  return historyCache.get(catalogAgentId.trim().toLowerCase()) ?? null;
}
