import React from "react";
import "./tradePageStatusFooter.css";

export interface TradePageStatusFooterProps {
  visible?: boolean;
  layoutEditMode?: boolean;
  onOpenNetworkHealth?: () => void;
}

function TradePageStatusFooter({
  visible = true,
  layoutEditMode = false,
  onOpenNetworkHealth,
}: TradePageStatusFooterProps): JSX.Element | null {
  if (!visible) return null;

  return (
    <footer
      className="trade-page-status-footer"
      aria-hidden={layoutEditMode}
      data-tour="welcome-status-footer"
    >
      <div className="trade-page-status-footer-gradient" />
      {layoutEditMode ? (
        <span className="trade-page-status-footer-ghost">
          Drop widget here to claim space
        </span>
      ) : onOpenNetworkHealth ? (
        <button
          type="button"
          className="trade-page-status-footer-link"
          onClick={onOpenNetworkHealth}
        >
          Network metrics →
        </button>
      ) : (
        <span className="trade-page-status-footer-badge">Layout optimized ✓</span>
      )}
    </footer>
  );
}

export default React.memo(TradePageStatusFooter);
