import type { CandlestickData, UTCTimestamp } from "lightweight-charts";

import type { AgentTokenPriceCandle } from "../../../../offline/mock_data/agentTokenPriceHistory.types";
import { binanceIntervalToMs, toBinanceInterval } from "../binance/klineUtil";

export const AGENT_TOKEN_SOURCE_INTERVAL = "5m" as const;
export const AGENT_TOKEN_SOURCE_INTERVAL_MS = 5 * 60 * 1000;

function toChartTime(isoTime: string): UTCTimestamp {
  return Math.floor(Date.parse(isoTime) / 1000) as UTCTimestamp;
}

export function agentTokenCandleToChart(
  candle: AgentTokenPriceCandle,
): CandlestickData {
  return {
    time: toChartTime(candle.time),
    open: candle.open,
    high: candle.high,
    low: candle.low,
    close: candle.close,
  };
}

export function agentTokenCandlesToChart(
  candles: AgentTokenPriceCandle[],
): CandlestickData[] {
  return candles.map(agentTokenCandleToChart);
}

export function agentTokenVolumeByTime(
  candles: AgentTokenPriceCandle[],
): Map<number, number> {
  const volumes = new Map<number, number>();
  for (const candle of candles) {
    const time = toChartTime(candle.time) as number;
    volumes.set(time, candle.volume);
  }
  return volumes;
}

function floorToBucketMs(isoTime: string, bucketMs: number): number {
  const ms = Date.parse(isoTime);
  return Math.floor(ms / bucketMs) * bucketMs;
}

export function aggregateAgentTokenCandles(
  candles: AgentTokenPriceCandle[],
  interval: string,
): AgentTokenPriceCandle[] {
  const normalized = toBinanceInterval(interval);
  const bucketMs = binanceIntervalToMs(normalized);
  if (bucketMs <= AGENT_TOKEN_SOURCE_INTERVAL_MS) {
    return candles;
  }

  const buckets = new Map<number, AgentTokenPriceCandle>();
  for (const candle of candles) {
    const bucketStart = floorToBucketMs(candle.time, bucketMs);
    const existing = buckets.get(bucketStart);
    if (!existing) {
      buckets.set(bucketStart, { ...candle, time: new Date(bucketStart).toISOString() });
      continue;
    }
    existing.high = Math.max(existing.high, candle.high);
    existing.low = Math.min(existing.low, candle.low);
    existing.close = candle.close;
    existing.volume += candle.volume;
  }

  return [...buckets.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, candle]) => candle);
}

export function sliceAgentTokenCandles(
  candles: AgentTokenPriceCandle[],
  limit?: number,
): AgentTokenPriceCandle[] {
  if (limit == null || limit <= 0 || candles.length <= limit) {
    return candles;
  }
  return candles.slice(candles.length - limit);
}
