import { useMemo } from "react";
import type { Market, TickerData } from "../../store/types";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import { useAgentTokenManifest } from "../../context/AgentTokenManifestContext";
import {
  CRYPTO_PICKER_MAJORS,
  getAgentProfileById,
  getAgentProfileByPerpBaseAsset,
  getIndexPickerCatalog,
  getMockMarketPrice,
  getTickerPickerMeta,
} from "../../../offline/mock_data";
import {
  catalogAgentIdFromMarketId,
  isAgentTokenMarketId,
} from "../../sdk/api/agentTokenPrice/agentTokenPriceClient";
import type {
  TickerCategory,
  TickerSelectionRow,
  TickerSortField,
  SortDirection,
} from "./types";

function toNumber(value: unknown): number {
  if (value == null) return 0;
  const n = typeof value === "number" ? value : parseFloat(String(value));
  return Number.isFinite(n) ? n : 0;
}

function titleCaseCatalogId(catalogAgentId: string): string {
  return catalogAgentId
    .replace(/^ext-/, "")
    .split("-")
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function buildTradableRow({
  market,
  tickers,
  favorites,
  baseURL,
  manifestAgent,
}: {
  market: Market;
  tickers: Map<string, TickerData>;
  favorites: Set<string>;
  baseURL: string;
  manifestAgent?: {
    catalogAgentId: string;
    ticker: string;
    currentPrice: number;
    change24h: number;
    name?: string;
  };
}): TickerSelectionRow | null {
  const marketId = market.marketIndex || market.index;
  const baseAsset = market.baseAsset || market.symbol?.split("-")[0] || "";
  const meta = getTickerPickerMeta(baseAsset);

  if (meta.showInPicker === false && !isAgentTokenMarketId(marketId) && !manifestAgent) {
    return null;
  }

  const offline = isOfflineMode(baseURL);
  const ticker = tickers.get(marketId);
  const agentProfile = getAgentProfileByPerpBaseAsset(baseAsset);
  const catalogAgentId =
    manifestAgent?.catalogAgentId
    ?? (isAgentTokenMarketId(marketId) ? catalogAgentIdFromMarketId(marketId) : agentProfile?.id);
  const price = offline
    ? manifestAgent?.currentPrice ?? getMockMarketPrice(marketId)
    : toNumber(ticker?.lastPrice) || manifestAgent?.currentPrice || getMockMarketPrice(marketId);
  const change24h = offline
    ? manifestAgent?.change24h ?? meta.change24h
    : toNumber(ticker?.priceChangePercent24h) || manifestAgent?.change24h || meta.change24h;
  const volume24h = offline
    ? meta.volume24h
    : toNumber(ticker?.volume) || meta.volume24h;

  const displayName =
    manifestAgent?.name
    ?? meta.displayName
    ?? agentProfile?.name
    ?? (catalogAgentId ? titleCaseCatalogId(catalogAgentId) : baseAsset);
  const tickerLabel =
    manifestAgent?.ticker ?? meta.tickerLabel ?? agentProfile?.ticker ?? baseAsset;
  const rowCategory =
    isAgentTokenMarketId(marketId) || manifestAgent || agentProfile
      ? "agent"
      : meta.category;

  return {
    marketId,
    symbol: baseAsset,
    baseAsset,
    displayName,
    tickerLabel,
    price,
    change24h,
    annFunding: meta.annFunding,
    volume24h,
    openInterest: meta.openInterest,
    leverage: meta.leverage ?? 20,
    isBeta: meta.isBeta ?? false,
    category: rowCategory,
    deployer: meta.deployer,
    isSelectable: meta.isSelectable ?? true,
    comingSoon: meta.comingSoon,
    comingSoonGroup: meta.comingSoonGroup,
    navRoute: meta.navRoute,
    agentRoute:
      catalogAgentId && getAgentProfileById(catalogAgentId)
        ? `/agents/${catalogAgentId}`
        : meta.agentRoute ?? (agentProfile ? `/agents/${agentProfile.id}` : undefined),
    isFavorite: favorites.has(marketId),
  };
}

function buildComingSoonRow(
  entry: ReturnType<typeof getIndexPickerCatalog>[number],
): TickerSelectionRow {
  return {
    marketId: `soon-${entry.baseAsset}`,
    symbol: entry.baseAsset,
    baseAsset: entry.baseAsset,
    displayName: entry.displayName,
    tickerLabel: entry.tickerLabel,
    price: entry.price,
    change24h: entry.change24h,
    annFunding: entry.annFunding,
    volume24h: entry.volume24h,
    openInterest: entry.openInterest,
    leverage: entry.leverage,
    isBeta: false,
    category: "index",
    deployer: entry.deployer,
    isSelectable: false,
    comingSoon: true,
    comingSoonGroup: entry.comingSoonGroup,
    navRoute: entry.navRoute,
    isFavorite: false,
  };
}

function matchesCategory(row: TickerSelectionRow, category: TickerCategory): boolean {
  switch (category) {
    case "all":
      return true;
    case "agent":
      return row.category === "agent";
    case "index":
      return row.category === "index";
    case "crypto":
      return (
        row.category === "crypto" &&
        (CRYPTO_PICKER_MAJORS as readonly string[]).includes(row.baseAsset)
      );
    case "tradfi":
      return row.category === "tradfi";
    default:
      return true;
  }
}

function matchesAllMarkets(row: TickerSelectionRow): boolean {
  if (row.category === "agent" || row.category === "index") {
    return true;
  }
  if (
    row.category === "crypto" &&
    (CRYPTO_PICKER_MAJORS as readonly string[]).includes(row.baseAsset)
  ) {
    return true;
  }
  if (row.category === "tradfi" || row.category === "legacy") {
    return true;
  }
  return false;
}

function matchesSearch(row: TickerSelectionRow, query: string): boolean {
  if (!query) return true;
  const haystack = [
    row.displayName,
    row.tickerLabel,
    row.symbol,
    row.baseAsset,
  ]
    .join(" ")
    .toLowerCase();
  return haystack.includes(query);
}

function sortRows(
  rows: TickerSelectionRow[],
  sortField: TickerSortField,
  sortDirection: SortDirection,
): TickerSelectionRow[] {
  const liveRows = rows.filter((row) => !row.comingSoon);
  const soonRows = rows.filter((row) => row.comingSoon);
  const dir = sortDirection === "asc" ? 1 : -1;

  liveRows.sort((a, b) => {
    switch (sortField) {
      case "symbol":
        return a.displayName.localeCompare(b.displayName) * dir;
      case "price":
        return (a.price - b.price) * dir;
      case "change24h":
        return (a.change24h - b.change24h) * dir;
      case "funding":
        return (a.annFunding - b.annFunding) * dir;
      case "volume":
        return (a.volume24h - b.volume24h) * dir;
      case "openInterest":
        return (a.openInterest - b.openInterest) * dir;
      default:
        return 0;
    }
  });

  return [...liveRows, ...soonRows];
}

export function useTickerSelectionRows({
  markets,
  tickers,
  favorites,
  category,
  search,
  sortField,
  sortDirection,
  baseURL,
}: {
  markets: Market[];
  tickers: Map<string, TickerData>;
  favorites: Set<string>;
  category: TickerCategory;
  search: string;
  sortField: TickerSortField;
  sortDirection: SortDirection;
  baseURL: string;
}): TickerSelectionRow[] {
  const { agents, getAgentByCatalogId, getAgentByBaseAsset } = useAgentTokenManifest();

  return useMemo(() => {
    const query = search.trim().toLowerCase();

    const tradableRows = markets
      .map((market) => {
        const catalogId = isAgentTokenMarketId(market.marketIndex)
          ? catalogAgentIdFromMarketId(market.marketIndex)
          : getAgentProfileByPerpBaseAsset(market.baseAsset ?? "")?.id;
        const manifestAgent =
          (catalogId ? getAgentByCatalogId(catalogId) : undefined)
          ?? getAgentByBaseAsset(market.baseAsset ?? "");
        return buildTradableRow({
          market,
          tickers,
          favorites,
          baseURL,
          manifestAgent,
        });
      })
      .filter((row): row is TickerSelectionRow => row != null);

    const comingSoonRows =
      category === "index" || category === "all"
        ? getIndexPickerCatalog()
            .filter((entry) => entry.comingSoon)
            .map(buildComingSoonRow)
        : [];

    let rows = [...tradableRows, ...comingSoonRows];

    rows = rows.filter((row) => {
      if (category === "all") {
        return matchesAllMarkets(row);
      }
      return matchesCategory(row, category);
    });

    if (query) {
      rows = rows.filter((row) => matchesSearch(row, query));
    }

    return sortRows(rows, sortField, sortDirection);
  }, [
    markets,
    tickers,
    favorites,
    category,
    search,
    sortField,
    sortDirection,
    baseURL,
    agents,
    getAgentByCatalogId,
    getAgentByBaseAsset,
  ]);
}
