import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import { useCopyAgentConfirm } from "../../hooks/useCopyAgentConfirm";
import { useFleetCopyRelations } from "../../hooks/useFleetCopyRelations";
import { useStopCopyMirror } from "../../hooks/useStopCopyMirror";
import { APP_ROUTES } from "../../routes";
import {
  COPY_TOUR_AGENT_ID,
  COPY_TOUR_TARGETS,
} from "../../tutorials/copy-tour/constants";
import { useOptionalCopyTour } from "../../tutorials/copy-tour";
import BucketDetailModal from "../tables/BucketDetailModal";
import type { BucketDetailTabId } from "../tables/bucketDetailTypes";
import CopiedAgentStatusModal from "../portfolio/CopiedAgentStatusModal";
import StopCopyWizardModal from "../portfolio/StopCopyWizardModal";
import CopyAgentModal, { type CopyAgentConfirmParams } from "./CopyAgentModal";
import "./agent.css";

const OFFLINE_BASE_URL = "offline://local";

export interface AgentActionTabProps {
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  walletAddress?: string;
}

function AgentActionTab({
  profile,
  fleet,
  walletAddress = "",
}: AgentActionTabProps): JSX.Element {
  const navigate = useNavigate();
  const [copyModalOpen, setCopyModalOpen] = useState(false);
  const [statusModalOpen, setStatusModalOpen] = useState(false);
  const [stopModalOpen, setStopModalOpen] = useState(false);
  const [bucketDetail, setBucketDetail] = useState<{
    bucketId: string;
    initialTab: BucketDetailTabId;
  } | null>(null);

  const { hasActiveCopy, getRelationForAgent } = useFleetCopyRelations(walletAddress);
  const {
    crossBuckets,
    spotWalletBalance,
    isPending: copyPending,
    confirmCopy,
  } = useCopyAgentConfirm(OFFLINE_BASE_URL);
  const { stopMirror, isPending: stopPending } = useStopCopyMirror();
  const copyTour = useOptionalCopyTour();
  const isCopyTourAgent =
    profile.id.trim().toLowerCase() === COPY_TOUR_AGENT_ID;

  const isCopying = hasActiveCopy(profile.id);
  const activeRelation = useMemo(
    () => getRelationForAgent(profile.id),
    [getRelationForAgent, profile.id],
  );
  const activeBucket = useMemo(
    () =>
      activeRelation
        ? crossBuckets.find(
            (bucket) => bucket.bucketId === activeRelation.copySettings.bucketId,
          ) ?? null
        : null,
    [activeRelation, crossBuckets],
  );
  const bucketDetailBucket = useMemo(
    () =>
      bucketDetail
        ? crossBuckets.find((bucket) => bucket.bucketId === bucketDetail.bucketId) ??
          null
        : null,
    [bucketDetail, crossBuckets],
  );

  const walletConnected = Boolean(walletAddress?.trim());

  const socialHook = fleet.isPopular
    ? `Popular · ${fleet.copyCount.toLocaleString()} copying`
    : `${fleet.copyCount.toLocaleString()} users copying (demo)`;

  const handleTrade = useCallback(() => {
    navigate(`${APP_ROUTES.trade}?ticker=${profile.perpBaseAsset}`);
  }, [navigate, profile.perpBaseAsset]);

  const handleCopyConfirm = useCallback(
    async (params: CopyAgentConfirmParams) => {
      if (!walletConnected) return;
      const relation = await confirmCopy(params);
      if (relation) {
        setCopyModalOpen(false);
        navigate(APP_ROUTES.portfolio);
      }
    },
    [confirmCopy, navigate, walletConnected],
  );

  const handleCopyClick = () => {
    if (isCopying && !copyTour?.runTour) {
      setStatusModalOpen(true);
      return;
    }
    setCopyModalOpen(true);
  };

  useEffect(() => {
    if (!copyTour?.runTour || !isCopyTourAgent) return;
    if (copyTour.openStatusModal && activeRelation) {
      setStatusModalOpen(true);
    }
  }, [activeRelation, copyTour?.openStatusModal, copyTour?.runTour, isCopyTourAgent]);

  const handleStopConfirm = useCallback(async () => {
    if (!activeRelation) return;
    const ok = await stopMirror(activeRelation, profile.name);
    if (ok) {
      setStopModalOpen(false);
      setStatusModalOpen(false);
    }
  }, [activeRelation, profile.name, stopMirror]);

  return (
    <>
      <div className="agent-action-body agent-action-tab-body" data-tour={COPY_TOUR_TARGETS.actionTab}>
        <div className="agent-action-identity" data-tour={COPY_TOUR_TARGETS.leaderContext}>
          <span className="terminal-market-title">{profile.ticker}</span>
          <p className="agent-action-summary">{profile.strategySummary}</p>
          <p className="agent-action-copy-count">{socialHook}</p>
        </div>

        <div className="agent-action-buttons">
          <button
            type="button"
            className="agent-secondary-btn agent-secondary-btn--primary agent-secondary-btn--block"
            data-tour={COPY_TOUR_TARGETS.copyCta}
            onClick={handleCopyClick}
          >
            {isCopying ? "Copying agent" : "Copy agent"}
          </button>
          <button
            type="button"
            className="agent-secondary-btn agent-secondary-btn--block"
            onClick={handleTrade}
          >
            Trade {profile.ticker} perp
          </button>
        </div>
      </div>

      <CopyAgentModal
        open={copyModalOpen}
        profile={profile}
        fleet={fleet}
        walletConnected={walletConnected}
        isCopying={copyPending}
        crossBuckets={crossBuckets}
        spotWalletBalance={spotWalletBalance}
        onClose={() => setCopyModalOpen(false)}
        onConfirm={handleCopyConfirm}
      />

      <CopiedAgentStatusModal
        open={statusModalOpen && activeRelation != null}
        relation={activeRelation ?? null}
        profile={profile}
        fleet={fleet}
        bucket={activeBucket}
        onClose={() => setStatusModalOpen(false)}
        onViewAgent={() => {
          setStatusModalOpen(false);
          navigate(`/agents/${profile.id}`);
        }}
        onManageBucket={(bucketId) => {
          setStatusModalOpen(false);
          setBucketDetail({ bucketId, initialTab: "manage" });
        }}
        onAdjustSettings={(bucketId) => {
          setStatusModalOpen(false);
          setBucketDetail({ bucketId, initialTab: "rules" });
        }}
        onStopCopy={() => {
          setStatusModalOpen(false);
          setStopModalOpen(true);
        }}
      />

      <StopCopyWizardModal
        open={stopModalOpen}
        relation={activeRelation}
        profile={profile}
        isPending={stopPending}
        onClose={() => setStopModalOpen(false)}
        onConfirm={handleStopConfirm}
      />

      <BucketDetailModal
        isOpen={bucketDetail != null}
        bucketId={bucketDetail?.bucketId ?? null}
        bucket={bucketDetailBucket}
        initialTab={bucketDetail?.initialTab ?? "overview"}
        baseURL={OFFLINE_BASE_URL}
        walletAddress={walletAddress}
        onClose={() => setBucketDetail(null)}
      />
    </>
  );
}

export default AgentActionTab;
