import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type JSX,
} from "react";

import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import { useAgentTokenPriceHistory } from "../../hooks/useAgentTokenPriceHistory";
import { useAgentTokenManifest } from "../../context/AgentTokenManifestContext";
import { toBinanceInterval } from "../../sdk/api/binance/klineUtil";
import KlineChart, {
  type ChartOverlayLayout,
  type KlineChartRef,
  type MarkerInteractionPoint,
} from "../finchartview/KlineChart";
import type { LogicalRange } from "lightweight-charts";
import KlineChartLoadingOverlay from "../finchartview/KlineChartLoadingOverlay";
import { isResolvedMarkerAnchor } from "../finchartview/markerAnchor";
import TokenTakerMarkerBubble from "../finchartview/TokenTakerMarkerBubble";
import {
  canStepChartInterval,
  isChartIntervalAtLeast,
  stepChartInterval,
  TOKEN_TAKER_MARKER_MIN_INTERVAL,
  TOKEN_TAKER_MARKER_SEED_VISIBLE_BARS,
} from "../finchartview/chartIntervalScale";
import { AGENT_TOKEN_INITIAL_VISIBLE_BARS } from "../finchartview/chartHistoryUtil";
import {
  intervalToSeconds,
  snapTimeToCandleInterval,
} from "../finchartview/chartMarkers";
import {
  DEFAULT_TOKEN_TAKER_MARKER_STRATEGY,
  TOKEN_TAKER_MARKER_STRATEGY_LABELS,
  TOKEN_TAKER_TOP_TRADER_COUNT,
  tokenTakerEventsToSeriesMarkers,
  tokenTakerMarkersToChartMarkers,
  visibleTimeBoundsFromCandleTimes,
  type TokenTakerChartMarkerMeta,
  type TokenTakerMarkerStrategy,
} from "../finchartview/tokenTakerChartMarkers";
import "../finchartview/finchart.css";
import "./agent.css";

export interface AgentTokenTakerKlineChartProps {
  catalogAgentId: string;
  events: AgentTokenTakerTradeEvent[];
  focusEventId?: string | null;
  focusTimeMs?: number;
  height?: string;
  className?: string;
  baseUrl?: string;
  limit?: number;
  eventsLoading?: boolean;
  /**
   * Top-N takers by aggregate fill volume (default {@link TOKEN_TAKER_TOP_TRADER_COUNT}).
   * Interval / viewport gates are bypassed.
   */
  maxTopTraders?: number;
  /** How top-N markers are painted (default {@link DEFAULT_TOKEN_TAKER_MARKER_STRATEGY}). */
  markerStrategy?: TokenTakerMarkerStrategy;
  onChartIntervalChange?: (interval: string) => void;
  onViewportLogicalRangeChange?: (range: LogicalRange | null) => void;
}

interface ActiveMarker {
  eventId: string;
  x?: number;
  y?: number;
}

function AgentTokenTakerKlineChart({
  catalogAgentId,
  events,
  focusEventId = null,
  focusTimeMs = 0,
  height,
  className = "",
  baseUrl,
  limit,
  eventsLoading = false,
  maxTopTraders = TOKEN_TAKER_TOP_TRADER_COUNT,
  markerStrategy = DEFAULT_TOKEN_TAKER_MARKER_STRATEGY,
  onChartIntervalChange,
  onViewportLogicalRangeChange,
}: AgentTokenTakerKlineChartProps): JSX.Element {
  const overlayHostRef = useRef<HTMLDivElement>(null);
  const layoutRootRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<KlineChartRef>(null);
  const mountedRef = useRef(true);
  const [chartInterval, setChartInterval] = useState(() =>
    toBinanceInterval(TOKEN_TAKER_MARKER_MIN_INTERVAL),
  );
  const [chartReady, setChartReady] = useState(false);
  const [intervalTransitionPending, setIntervalTransitionPending] = useState(false);
  const [hoveredMarker, setHoveredMarker] = useState<ActiveMarker | null>(null);
  const [pinnedMarker, setPinnedMarker] = useState<ActiveMarker | null>(null);
  const [overlayLayout, setOverlayLayout] = useState<ChartOverlayLayout | null>(null);
  const [visibleLogicalRange, setVisibleLogicalRange] = useState<LogicalRange | null>(null);
  const manifest = useAgentTokenManifest();
  const resolvedBaseUrl = baseUrl ?? manifest.baseUrl;

  const { candles, volumeByTime, loading, error, interval: activeInterval } =
    useAgentTokenPriceHistory({
      catalogAgentId,
      interval: chartInterval,
      baseUrl: resolvedBaseUrl,
      limit,
    });

  const manifestAgent = manifest.getAgentByCatalogId(catalogAgentId);
  const displaySymbol = manifestAgent?.ticker ?? catalogAgentId.toUpperCase();

  const visibleTimeBounds = useMemo(
    () =>
      visibleTimeBoundsFromCandleTimes(
        candles.map((bar) => bar.time as number),
        visibleLogicalRange,
        TOKEN_TAKER_MARKER_SEED_VISIBLE_BARS,
      ),
    [candles, visibleLogicalRange],
  );

  const markerTransformOptions = useMemo(
    () => ({
      focusEventId,
      maxTopTraders,
      markerStrategy,
      visibleTimeFromSec: visibleTimeBounds?.fromSec ?? null,
      visibleTimeToSec: visibleTimeBounds?.toSec ?? null,
    }),
    [focusEventId, maxTopTraders, markerStrategy, visibleTimeBounds],
  );

  const { markers, metaByEventId } = useMemo(
    () => tokenTakerEventsToSeriesMarkers(events, chartInterval, markerTransformOptions),
    [events, chartInterval, markerTransformOptions],
  );

  const chartMarkers = useMemo(
    () => tokenTakerMarkersToChartMarkers(markers),
    [markers],
  );

  const markersEnabled = useMemo(
    () => isChartIntervalAtLeast(chartInterval, TOKEN_TAKER_MARKER_MIN_INTERVAL),
    [chartInterval],
  );

  const strategyLabel = TOKEN_TAKER_MARKER_STRATEGY_LABELS[markerStrategy];

  const markersForChart = useMemo(() => chartMarkers, [chartMarkers]);

  const handleVisibleLogicalRangeChange = useCallback(
    (range: LogicalRange | null) => {
      setVisibleLogicalRange(range);
      onViewportLogicalRangeChange?.(range);
    },
    [onViewportLogicalRangeChange],
  );

  useEffect(() => {
    onChartIntervalChange?.(chartInterval);
  }, [chartInterval, onChartIntervalChange]);

  const canCoarserInterval = useMemo(
    () => canStepChartInterval(chartInterval, 1),
    [chartInterval],
  );
  const canFinerInterval = useMemo(
    () => canStepChartInterval(chartInterval, -1),
    [chartInterval],
  );

  const handleCoarserInterval = useCallback(() => {
    const next = stepChartInterval(chartInterval, 1);
    if (next) setChartInterval(next);
  }, [chartInterval]);

  const handleFinerInterval = useCallback(() => {
    const next = stepChartInterval(chartInterval, -1);
    if (next) setChartInterval(next);
  }, [chartInterval]);

  const handleChartReady = useCallback(() => {
    setChartReady(true);
    requestAnimationFrame(() => {
      chartRef.current?.repushOverlays?.();
      setIntervalTransitionPending(false);
    });
  }, []);

  const handleMarkerHover = useCallback(
    (nextEventId: string | null, point: MarkerInteractionPoint | null) => {
      if (!nextEventId || !point) {
        setHoveredMarker(null);
        return;
      }
      setHoveredMarker({ eventId: nextEventId, x: point.x, y: point.y });
    },
    [],
  );

  const handleMarkerClick = useCallback(
    (nextEventId: string | null, point: MarkerInteractionPoint | null) => {
      if (!nextEventId || !point) {
        setPinnedMarker(null);
        return;
      }
      setPinnedMarker((current) =>
        current?.eventId === nextEventId
          ? null
          : { eventId: nextEventId, x: point.x, y: point.y },
      );
    },
    [],
  );

  const handleOverlayLayout = useCallback((layout: ChartOverlayLayout) => {
    setOverlayLayout((current) => {
      if (
        current &&
        current.canvasOffsetLeft === layout.canvasOffsetLeft &&
        current.canvasOffsetTop === layout.canvasOffsetTop &&
        current.widgetWidth === layout.widgetWidth &&
        current.widgetHeight === layout.widgetHeight
      ) {
        return current;
      }
      return layout;
    });
  }, []);

  const handleActiveAnchorMove = useCallback(
    (nextEventId: string, point: MarkerInteractionPoint) => {
      setHoveredMarker((current) =>
        current?.eventId === nextEventId
          ? { eventId: nextEventId, x: point.x, y: point.y }
          : current,
      );
      setPinnedMarker((current) =>
        current?.eventId === nextEventId
          ? { eventId: nextEventId, x: point.x, y: point.y }
          : current,
      );
    },
    [],
  );

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    setChartReady(false);
    setIntervalTransitionPending(true);
    setHoveredMarker(null);
    setPinnedMarker(null);
    setOverlayLayout(null);
    setVisibleLogicalRange(null);
  }, [catalogAgentId, chartInterval]);

  useEffect(() => {
    if (!focusEventId) {
      setPinnedMarker(null);
      return;
    }
    setHoveredMarker(null);
    setPinnedMarker({ eventId: focusEventId });
  }, [focusEventId]);

  useEffect(() => {
    if (loading || candles.length === 0 || !chartRef.current || !chartReady) {
      return;
    }
    if (!focusEventId || focusTimeMs <= 0) return;

    const snappedTime = snapTimeToCandleInterval(focusTimeMs, chartInterval);
    const halfWindowSec = 30 * intervalToSeconds(chartInterval);
    let outerFrameId = 0;
    let innerFrameId = 0;
    let thirdFrameId = 0;

    const applyFocus = () => {
      if (!mountedRef.current) return;
      chartRef.current?.scrollToTime(snappedTime, halfWindowSec);
    };

    const afterScroll = () => {
      if (!mountedRef.current) return;
      chartRef.current?.repushOverlays?.();
    };

    outerFrameId = requestAnimationFrame(() => {
      applyFocus();
      innerFrameId = requestAnimationFrame(() => {
        afterScroll();
        thirdFrameId = requestAnimationFrame(afterScroll);
      });
    });

    return () => {
      cancelAnimationFrame(outerFrameId);
      cancelAnimationFrame(innerFrameId);
      cancelAnimationFrame(thirdFrameId);
    };
  }, [loading, candles.length, chartInterval, focusTimeMs, focusEventId, chartReady]);

  useEffect(() => {
    if (!chartReady || markersForChart.length === 0) return;
    const applyMarkerOverlays = () => {
      if (!mountedRef.current) return;
      chartRef.current?.repushOverlays?.();
    };
    applyMarkerOverlays();
    let outerFrameId = 0;
    let innerFrameId = 0;
    outerFrameId = requestAnimationFrame(() => {
      innerFrameId = requestAnimationFrame(applyMarkerOverlays);
    });
    return () => {
      cancelAnimationFrame(outerFrameId);
      cancelAnimationFrame(innerFrameId);
    };
  }, [chartReady, markersForChart.length, chartInterval, visibleLogicalRange]);

  const activeMarker = pinnedMarker ?? hoveredMarker;
  const bubbleMarker =
    activeMarker && isResolvedMarkerAnchor(activeMarker) ? activeMarker : null;
  const activeMeta: TokenTakerChartMarkerMeta | undefined = bubbleMarker
    ? metaByEventId.get(bubbleMarker.eventId)
    : undefined;
  const chartActiveTradeId =
    activeMarker?.eventId ?? focusEventId ?? null;

  const chartOverlay = useMemo(() => {
    if (!overlayLayout || overlayLayout.widgetWidth === 0 || !bubbleMarker || !activeMeta) {
      return null;
    }

    const { canvasOffsetLeft, canvasOffsetTop, widgetWidth, widgetHeight } = overlayLayout;

    return (
      <TokenTakerMarkerBubble
        meta={activeMeta}
        x={bubbleMarker.x + canvasOffsetLeft}
        y={bubbleMarker.y + canvasOffsetTop}
        containerWidth={widgetWidth}
        containerHeight={widgetHeight}
      />
    );
  }, [bubbleMarker, activeMeta, overlayLayout]);

  const blockChartMount = (loading && candles.length === 0) || eventsLoading;
  const showLoadingOverlay = blockChartMount || intervalTransitionPending;
  const chartMountReady = !error && !blockChartMount;

  return (
    <div
      className={`kline-chart-widget agent-token-taker-kline ${className}`.trim()}
      style={{ width: "100%", height: height ?? "100%" }}
    >
      <div ref={overlayHostRef} className="kline-chart-widget-overlay">
        {showLoadingOverlay ? <KlineChartLoadingOverlay /> : null}
      </div>
      <div ref={layoutRootRef} className="kline-chart-widget-body">
        {chartMountReady ? (
          <KlineChart
            ref={chartRef}
            initialData={candles}
            volumeByTime={volumeByTime}
            symbol={displaySymbol}
            interval={activeInterval}
            showVolume
            seedScrollMode="live"
            autoScrollHalfWindowSec={
              AGENT_TOKEN_INITIAL_VISIBLE_BARS * 5 * 60
            }
            seedMaxVisibleLogicalBars={TOKEN_TAKER_MARKER_SEED_VISIBLE_BARS}
            resetScrollKey={`${catalogAgentId}-${chartInterval}`}
            markers={markersForChart}
            anchorMarkers={chartMarkers}
            onCoarserInterval={handleCoarserInterval}
            onFinerInterval={handleFinerInterval}
            canCoarserInterval={canCoarserInterval}
            canFinerInterval={canFinerInterval}
            onMarkerHover={handleMarkerHover}
            onMarkerClick={handleMarkerClick}
            overlayHostRef={overlayHostRef}
            layoutRootRef={layoutRootRef}
            onOverlayLayout={handleOverlayLayout}
            activeTradeId={chartActiveTradeId}
            onActiveAnchorMove={handleActiveAnchorMove}
            onReady={handleChartReady}
            onVisibleLogicalRangeChange={handleVisibleLogicalRangeChange}
            overlay={chartOverlay}
          />
        ) : null}
      </div>
      {!error ? (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--compact">
          {loading || eventsLoading ? (
            <>Loading · {activeInterval}</>
          ) : candles.length === 0 ? (
            <>No token price data available</>
          ) : (
            <>
              Token takers · {displaySymbol} · {activeInterval} · {markers.length} visible · top{" "}
              {maxTopTraders} · {strategyLabel} · {events.length} fills
              {!markersEnabled ? " · Markers at 4h+" : ""}
            </>
          )}
        </div>
      ) : (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--error">
          {error}
        </div>
      )}
    </div>
  );
}

export default AgentTokenTakerKlineChart;
