import React, { useMemo } from "react";
import { LineType } from "lightweight-charts";
import type { TradeHistoryRow } from "../../sdk/types/data";
import {
  filterPnlSeriesByRange,
  getSeriesFinalPnl,
  selectPnlChartSeries,
  type PnlChartViewMode,
  type PortfolioPnlSeries,
  type PortfolioTimeRange,
} from "../../utils/portfolioChartData";
import PortfolioTimeSeriesChart from "./PortfolioTimeSeriesChart";
import "./portfolio.css";

export interface PortfolioAgentPnlChartProps {
  allSeries: PortfolioPnlSeries[];
  viewMode: PnlChartViewMode;
  timeRange: PortfolioTimeRange;
  trades: TradeHistoryRow[];
  taskAgentMap: Map<string, string>;
  filterAgentIds: string[];
  focusAgentId?: string | null;
}

function formatCurrency(value: number): string {
  const sign = value < 0 ? "-" : "";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000) return `${sign}$${(abs / 1_000).toFixed(1)}k`;
  return `${sign}$${abs.toFixed(2)}`;
}

function PortfolioAgentPnlChart({
  allSeries,
  viewMode,
  timeRange,
  trades,
  taskAgentMap,
  filterAgentIds,
  focusAgentId = null,
}: PortfolioAgentPnlChartProps): JSX.Element {
  const chartSeries = useMemo(() => {
    const selected = focusAgentId
      ? allSeries.filter((entry) => entry.id === focusAgentId)
      : selectPnlChartSeries(
          allSeries,
          viewMode,
          trades,
          taskAgentMap,
          filterAgentIds,
        );
    const ranged = filterPnlSeriesByRange(selected, timeRange);
    return ranged.map((entry) => ({
      id: entry.id,
      color: entry.color,
      lineType: LineType.WithSteps,
      data: entry.data,
    }));
  }, [
    allSeries,
    viewMode,
    trades,
    taskAgentMap,
    filterAgentIds,
    focusAgentId,
    timeRange,
  ]);

  const legendSeries = useMemo(() => {
    const selected = focusAgentId
      ? allSeries.filter((entry) => entry.id === focusAgentId)
      : selectPnlChartSeries(
          allSeries,
          viewMode,
          trades,
          taskAgentMap,
          filterAgentIds,
        );
    return filterPnlSeriesByRange(selected, timeRange);
  }, [
    allSeries,
    viewMode,
    trades,
    taskAgentMap,
    filterAgentIds,
    focusAgentId,
    timeRange,
  ]);

  const hasData = chartSeries.some((entry) => entry.data.length > 0);

  return (
    <div className="portfolio-agent-pnl-chart">
      <PortfolioTimeSeriesChart
        variant="line"
        priceScale="left"
        series={chartSeries}
        emptyMessage="No PnL attribution data"
        className="portfolio-agent-pnl-chart-canvas"
      />
      {hasData ? (
        <div className="portfolio-attribution-legend portfolio-hero-pnl-legend">
          {legendSeries.map((entry) => (
            <div key={entry.id} className="portfolio-attribution-row">
              <span
                className="portfolio-attribution-dot"
                style={{ background: entry.color }}
                aria-hidden
              />
              <span>{entry.label}</span>
              <strong
                className={
                  getSeriesFinalPnl(entry) >= 0 ? "positive" : "negative"
                }
              >
                {formatCurrency(getSeriesFinalPnl(entry))}
              </strong>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export default React.memo(PortfolioAgentPnlChart);
