import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type JSX,
} from "react";

import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { CopyRelation } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import { useBinanceKline } from "../../hooks/useBinanceKline";
import { toBinanceInterval } from "../../sdk/api/binance/klineUtil";
import { resolveBinanceKlineSymbol } from "../tradingview/symbols";
import KlineChart, {
  type ChartOverlayLayout,
  type KlineChartRef,
  type MarkerInteractionPoint,
} from "../finchartview/KlineChart";
import KlineChartLoadingOverlay from "../finchartview/KlineChartLoadingOverlay";
import { isResolvedMarkerAnchor } from "../finchartview/markerAnchor";
import FleetMarkerBubble from "../finchartview/FleetMarkerBubble";
import { canStepChartInterval, stepChartInterval } from "../finchartview/chartIntervalScale";
import {
  intervalToSeconds,
  snapTimeToCandleInterval,
} from "../finchartview/chartMarkers";
import {
  filterFleetTradesForMarket,
  filterFleetTradesSinceCopyStart,
  fleetMarkersToChartMarkers,
  fleetTradesToSeriesMarkers,
  type FleetChartMarkerMeta,
} from "../finchartview/fleetChartMarkers";
import "../finchartview/finchart.css";
import "../agent/agent.css";

const KLINE_FETCH_LIMIT = 500;
export const FLEET_ASSET_CHART_BASE_INTERVAL = "4h";
const DEFAULT_INTERVAL = FLEET_ASSET_CHART_BASE_INTERVAL;

export interface FleetAssetKlineChartProps {
  coin: string;
  tradeTimeMs: number;
  tradeId: string;
  fleetTrades: FleetTradeEvent[];
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  copyRelation?: CopyRelation | null;
  className?: string;
}

interface ActiveMarker {
  tradeId: string;
  x?: number;
  y?: number;
}

interface FleetAssetKlineChartInnerProps extends FleetAssetKlineChartProps {
  symbol: string;
}

function FleetAssetKlineChartInner({
  symbol,
  coin,
  tradeTimeMs,
  tradeId,
  fleetTrades,
  profile,
  fleet,
  copyRelation = null,
  className = "",
}: FleetAssetKlineChartInnerProps): JSX.Element {
  const overlayHostRef = useRef<HTMLDivElement>(null);
  const layoutRootRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<KlineChartRef>(null);
  const mountedRef = useRef(true);
  const [chartInterval, setChartInterval] = useState(() =>
    toBinanceInterval(DEFAULT_INTERVAL),
  );
  const [chartReady, setChartReady] = useState(false);
  const [hoveredMarker, setHoveredMarker] = useState<ActiveMarker | null>(null);
  const [pinnedMarker, setPinnedMarker] = useState<ActiveMarker | null>(null);
  const [overlayLayout, setOverlayLayout] = useState<ChartOverlayLayout | null>(null);

  const { candles, volumeByTime, loading, error, interval: activeInterval } =
    useBinanceKline({
      symbol,
      interval: chartInterval,
      limit: KLINE_FETCH_LIMIT,
      enableLiveWs: false,
    });

  const { markers, metaByTradeId } = useMemo(() => {
    const byCoin = filterFleetTradesForMarket(fleetTrades, undefined, coin);
    const scoped = copyRelation
      ? filterFleetTradesSinceCopyStart(byCoin, copyRelation.copySettings.startedAt)
      : byCoin;
    return fleetTradesToSeriesMarkers(
      scoped,
      profile,
      fleet,
      chartInterval,
      Boolean(copyRelation),
      copyRelation?.copySettings.copySizePct,
    );
  }, [fleetTrades, coin, profile, fleet, chartInterval, copyRelation]);

  const chartMarkers = useMemo(
    () => fleetMarkersToChartMarkers(markers),
    [markers],
  );

  const canCoarserInterval = useMemo(
    () => canStepChartInterval(chartInterval, 1),
    [chartInterval],
  );
  const canFinerInterval = useMemo(
    () => canStepChartInterval(chartInterval, -1),
    [chartInterval],
  );

  const handleCoarserInterval = useCallback(() => {
    setChartInterval((prev) => stepChartInterval(prev, 1) ?? prev);
  }, []);

  const handleFinerInterval = useCallback(() => {
    setChartInterval((prev) => stepChartInterval(prev, -1) ?? prev);
  }, []);

  const handleChartReady = useCallback(() => {
    setChartReady(true);
  }, []);

  const handleMarkerHover = useCallback(
    (nextTradeId: string | null, point: MarkerInteractionPoint | null) => {
      if (!nextTradeId || !point) {
        setHoveredMarker(null);
        return;
      }
      setHoveredMarker({ tradeId: nextTradeId, x: point.x, y: point.y });
    },
    [],
  );

  const handleMarkerClick = useCallback(
    (nextTradeId: string | null, point: MarkerInteractionPoint | null) => {
      if (!nextTradeId || !point) {
        setPinnedMarker(null);
        return;
      }
      setPinnedMarker((current) =>
        current?.tradeId === nextTradeId ? null : { tradeId: nextTradeId, x: point.x, y: point.y },
      );
    },
    [],
  );

  const handleOverlayLayout = useCallback((layout: ChartOverlayLayout) => {
    setOverlayLayout((current) => {
      if (
        current &&
        current.canvasOffsetLeft === layout.canvasOffsetLeft &&
        current.canvasOffsetTop === layout.canvasOffsetTop &&
        current.widgetWidth === layout.widgetWidth &&
        current.widgetHeight === layout.widgetHeight
      ) {
        return current;
      }
      return layout;
    });
  }, []);

  const handleActiveAnchorMove = useCallback(
    (nextTradeId: string, point: MarkerInteractionPoint) => {
      setHoveredMarker((current) =>
        current?.tradeId === nextTradeId ? { tradeId: nextTradeId, x: point.x, y: point.y } : current,
      );
      setPinnedMarker((current) =>
        current?.tradeId === nextTradeId ? { tradeId: nextTradeId, x: point.x, y: point.y } : current,
      );
    },
    [],
  );

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    setChartInterval(toBinanceInterval(DEFAULT_INTERVAL));
  }, [coin, tradeId]);

  useEffect(() => {
    setChartReady(false);
    setHoveredMarker(null);
    setPinnedMarker(null);
    setOverlayLayout(null);
  }, [symbol, chartInterval]);

  useEffect(() => {
    if (!tradeId) {
      setPinnedMarker(null);
      return;
    }
    setHoveredMarker(null);
    setPinnedMarker({ tradeId });
  }, [tradeId]);

  useEffect(() => {
    if (loading || candles.length === 0 || !chartRef.current || !chartReady) {
      return;
    }

    const snappedTime = snapTimeToCandleInterval(tradeTimeMs, chartInterval);
    const halfWindowSec = 30 * intervalToSeconds(chartInterval);
    let outerFrameId = 0;
    let innerFrameId = 0;
    let thirdFrameId = 0;

    const applyFocus = () => {
      if (!mountedRef.current) return;
      chartRef.current?.scrollToTime(snappedTime, halfWindowSec);
    };

    const afterScroll = () => {
      if (!mountedRef.current) return;
      chartRef.current?.repushOverlays?.();
    };

    outerFrameId = requestAnimationFrame(() => {
      applyFocus();
      innerFrameId = requestAnimationFrame(() => {
        afterScroll();
        thirdFrameId = requestAnimationFrame(afterScroll);
      });
    });

    return () => {
      cancelAnimationFrame(outerFrameId);
      cancelAnimationFrame(innerFrameId);
      cancelAnimationFrame(thirdFrameId);
    };
  }, [loading, candles.length, chartInterval, tradeTimeMs, tradeId, chartReady]);

  useEffect(() => {
    if (!chartReady || chartMarkers.length === 0) return;
    const applyMarkerOverlays = () => {
      if (!mountedRef.current) return;
      chartRef.current?.repushOverlays?.();
    };
    applyMarkerOverlays();
    let outerFrameId = 0;
    let innerFrameId = 0;
    outerFrameId = requestAnimationFrame(() => {
      innerFrameId = requestAnimationFrame(applyMarkerOverlays);
    });
    return () => {
      cancelAnimationFrame(outerFrameId);
      cancelAnimationFrame(innerFrameId);
    };
  }, [chartReady, chartMarkers.length, chartInterval]);

  const activeMarker = pinnedMarker ?? hoveredMarker;
  const bubbleMarker =
    activeMarker && isResolvedMarkerAnchor(activeMarker) ? activeMarker : null;
  const activeMeta: FleetChartMarkerMeta | undefined = bubbleMarker
    ? metaByTradeId.get(bubbleMarker.tradeId)
    : undefined;
  const chartActiveTradeId = activeMarker?.tradeId ?? tradeId ?? null;

  const chartOverlay = useMemo(() => {
    if (!overlayLayout || overlayLayout.widgetWidth === 0 || !bubbleMarker || !activeMeta) {
      return null;
    }

    const { canvasOffsetLeft, canvasOffsetTop, widgetWidth, widgetHeight } = overlayLayout;

    return (
      <FleetMarkerBubble
        meta={activeMeta}
        x={bubbleMarker.x + canvasOffsetLeft}
        y={bubbleMarker.y + canvasOffsetTop}
        containerWidth={widgetWidth}
        containerHeight={widgetHeight}
      />
    );
  }, [bubbleMarker, activeMeta, overlayLayout]);

  const showLoadingOverlay = loading && candles.length === 0;
  const chartMountReady = !showLoadingOverlay && !error;

  return (
    <div
      className={`kline-chart-widget agent-fleet-asset-kline ${className}`.trim()}
      style={{ width: "100%", height: "100%" }}
    >
      <div ref={overlayHostRef} className="kline-chart-widget-overlay">
        {showLoadingOverlay ? <KlineChartLoadingOverlay /> : null}
      </div>
      <div ref={layoutRootRef} className="kline-chart-widget-body">
        {chartMountReady ? (
          <KlineChart
            ref={chartRef}
            initialData={candles}
            volumeByTime={volumeByTime}
            symbol={symbol}
            interval={activeInterval}
            showVolume
            markers={chartMarkers}
            anchorMarkers={chartMarkers}
            resetScrollKey={`${symbol}-${chartInterval}`}
            onCoarserInterval={handleCoarserInterval}
            onFinerInterval={handleFinerInterval}
            canCoarserInterval={canCoarserInterval}
            canFinerInterval={canFinerInterval}
            onMarkerHover={handleMarkerHover}
            onMarkerClick={handleMarkerClick}
            overlayHostRef={overlayHostRef}
            layoutRootRef={layoutRootRef}
            onOverlayLayout={handleOverlayLayout}
            activeTradeId={chartActiveTradeId}
            onActiveAnchorMove={handleActiveAnchorMove}
            onReady={handleChartReady}
            overlay={chartOverlay}
          />
        ) : null}
      </div>
      {!error ? (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--compact">
          {loading ? (
            <>Loading · {activeInterval}</>
          ) : candles.length === 0 ? (
            <>No kline data available</>
          ) : (
            <>
              Leader fills · read-only mirror
              {copyRelation
                ? ` · copying · ${copyRelation.copySettings.copySizePct}%`
                : ""}
              {" · "}
              {coin} · {activeInterval} · {markers.length} fills
            </>
          )}
        </div>
      ) : (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--error">
          {error}
        </div>
      )}
    </div>
  );
}

function FleetAssetKlineChart(props: FleetAssetKlineChartProps): JSX.Element {
  const { coin, className = "" } = props;
  const symbol = useMemo(() => resolveBinanceKlineSymbol(coin), [coin]);

  if (!symbol) {
    return (
      <div className={`agent-fleet-asset-kline agent-fleet-asset-kline--unsupported ${className}`.trim()}>
        <p className="agent-fleet-asset-kline-error">
          Kline not available for {coin}
        </p>
      </div>
    );
  }

  return <FleetAssetKlineChartInner {...props} symbol={symbol} />;
}

export default FleetAssetKlineChart;
