import { BINANCE_TRADE_SNAPSHOT } from "./binanceTradeSnapshot";
import type { CopyRelation } from "./fleetCopyRelations";
import {
  getFleetAgentByCatalogId,
  toSatoshiStr,
  type FleetAgentRecord,
} from "./fleetCatalog";
import type {
  FleetTradeAction,
  FleetTradeEvent,
} from "./fleetTradeHistory.types";
import { mockHashId } from "./mockHashId";

export const COPY_MIRROR_DEMO_AGENT_ID = "alphabot";
export const COPY_MIRROR_REPLAY_INTERVAL_MS = 10_000;

type ReplayStepTemplate = {
  action: FleetTradeAction;
  /** Index into tail BTC candles (from end of snapshot). */
  candleTailIndex: number;
  qty: number;
};

const BTC_TAIL = BINANCE_TRADE_SNAPSHOT.candles.BTCUSDT.slice(-12);

const COPY_MIRROR_REPLAY_STEPS: ReplayStepTemplate[] = [
  { action: "BUY", candleTailIndex: 8, qty: 0.12 },
  { action: "SNIPE", candleTailIndex: 6, qty: 0.06 },
  { action: "SELL", candleTailIndex: 4, qty: 0.09 },
  { action: "SELL", candleTailIndex: 2, qty: 0.09 },
];

const replayLeaderEventsByAgent = new Map<string, FleetTradeEvent[]>();
const activeReplayRelationIds = new Set<string>();
const replayListeners = new Set<() => void>();

function notifyCopyMirrorReplayListeners(): void {
  replayListeners.forEach((listener) => listener());
}

/** Subscribe to replay leader-event / session changes (fleet trade list refresh). */
export function subscribeCopyMirrorReplayListeners(
  listener: () => void,
): () => void {
  replayListeners.add(listener);
  return () => replayListeners.delete(listener);
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

export function getReplayStepCount(): number {
  return COPY_MIRROR_REPLAY_STEPS.length;
}

export function getCopyReplayLeaderEvents(
  catalogAgentId: string,
): FleetTradeEvent[] {
  return [...(replayLeaderEventsByAgent.get(catalogAgentId.trim().toLowerCase()) ?? [])];
}

export function isCopyMirrorReplayActive(relationId: string): boolean {
  return activeReplayRelationIds.has(relationId);
}

export function recordReplayLeaderEvent(event: FleetTradeEvent): void {
  const key = event.catalogAgentId.trim().toLowerCase();
  const existing = replayLeaderEventsByAgent.get(key) ?? [];
  replayLeaderEventsByAgent.set(key, [event, ...existing]);
  notifyCopyMirrorReplayListeners();
}

export function clearReplayLeaderEventsForAgent(catalogAgentId: string): void {
  replayLeaderEventsByAgent.delete(catalogAgentId.trim().toLowerCase());
}

export function resetCopyMirrorReplayState(): void {
  replayLeaderEventsByAgent.clear();
  activeReplayRelationIds.clear();
  notifyCopyMirrorReplayListeners();
}

export function startCopyMirrorReplay(relation: CopyRelation): void {
  activeReplayRelationIds.add(relation.id);
  notifyCopyMirrorReplayListeners();
}

export function stopCopyMirrorReplay(relationId: string): void {
  activeReplayRelationIds.delete(relationId);
  notifyCopyMirrorReplayListeners();
}

function resolveFleetAgent(catalogAgentId: string): FleetAgentRecord {
  const fleet =
    getFleetAgentByCatalogId(catalogAgentId) ??
    getFleetAgentByCatalogId(COPY_MIRROR_DEMO_AGENT_ID);
  if (!fleet) {
    throw new Error(`Missing fleet agent record for ${catalogAgentId}`);
  }
  return fleet;
}

function candleForStep(stepIndex: number): (typeof BTC_TAIL)[number] {
  const template = COPY_MIRROR_REPLAY_STEPS[stepIndex];
  if (!template) {
    throw new RangeError(`Invalid replay step index ${stepIndex}`);
  }
  const candle = BTC_TAIL[template.candleTailIndex];
  if (!candle) {
    throw new Error(`Missing BTC candle for replay step ${stepIndex}`);
  }
  return candle;
}

function estimateClosedPnl(
  stepIndex: number,
  price: number,
  qty: number,
): number | null {
  const action = COPY_MIRROR_REPLAY_STEPS[stepIndex]?.action;
  if (action !== "SELL" && action !== "LIQUIDATE") return null;

  const entrySteps = COPY_MIRROR_REPLAY_STEPS.slice(0, stepIndex).filter(
    (step) => step.action === "BUY" || step.action === "SNIPE",
  );
  if (entrySteps.length === 0) return null;

  let avgEntry = 0;
  let totalQty = 0;
  for (const entry of entrySteps) {
    const entryCandle = BTC_TAIL[entry.candleTailIndex]!;
    const w = entry.qty;
    avgEntry = totalQty === 0 ? entryCandle.close : (avgEntry * totalQty + entryCandle.close * w) / (totalQty + w);
    totalQty += w;
  }
  return round2((price - avgEntry) * Math.min(qty, totalQty));
}

export function buildReplayLeaderEvent(
  relation: CopyRelation,
  stepIndex: number,
  baseTimeMs: number = Date.now(),
): FleetTradeEvent {
  const template = COPY_MIRROR_REPLAY_STEPS[stepIndex];
  if (!template) {
    throw new RangeError(`Invalid replay step index ${stepIndex}`);
  }

  const catalogAgentId = relation.targetCatalogAgentId.trim().toLowerCase();
  const fleet = resolveFleetAgent(catalogAgentId);
  const candle = candleForStep(stepIndex);
  const price = candle.close;
  const qty = template.qty;
  const amountUsd = round2(price * qty);
  const timestamp = new Date(
    baseTimeMs + stepIndex * COPY_MIRROR_REPLAY_INTERVAL_MS,
  ).toISOString();
  const eventId = mockHashId(`copy-replay:${relation.id}:${stepIndex}`);
  const closedPnl = estimateClosedPnl(stepIndex, price, qty);

  return {
    id: eventId,
    catalogAgentId,
    agentWallet: fleet.agentWallet,
    masterWallet: fleet.masterWallet,
    masterInvolved: false,
    timestamp,
    action: template.action,
    marketId: "1",
    coin: "BTC",
    price: toSatoshiStr(price),
    quantity: toSatoshiStr(qty),
    amountUsd,
    txSimHash: `mock:copy-replay:${relation.id}:${stepIndex}`,
    frequencyPattern: fleet.behaviorProfile,
    closedPnl,
  };
}

/** In-memory store linking emitted events to relations for execution bridge. */
const leaderEventById = new Map<string, FleetTradeEvent>();
const relationIdByLeaderEventId = new Map<string, string>();

export function storeReplayLeaderEvent(
  relationId: string,
  event: FleetTradeEvent,
): void {
  leaderEventById.set(event.id, event);
  relationIdByLeaderEventId.set(event.id, relationId);
  recordReplayLeaderEvent(event);
}

export function getStoredReplayLeaderEvent(
  leaderTradeId: string,
): FleetTradeEvent | undefined {
  return leaderEventById.get(leaderTradeId);
}

export function getStoredReplayRelationId(leaderTradeId: string): string | undefined {
  return relationIdByLeaderEventId.get(leaderTradeId);
}

export function clearStoredReplayLeaderEventsForRelation(
  relationId: string,
): void {
  for (const [eventId, relId] of relationIdByLeaderEventId.entries()) {
    if (relId !== relationId) continue;
    relationIdByLeaderEventId.delete(eventId);
    leaderEventById.delete(eventId);
  }
}
