/**
 * Markets terminal page — multi-slot grid layout.
 */
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { useNavigate } from "react-router-dom";

import { indexDetailPath, rowIdToSlug } from "../../offline/mock_data";
import { GridViewerLayout, GRID_COLS } from "../components";
import {
  MarketsDataTable,
  MarketsFiltersSidebar,
  MarketsHeroHeader,
  MarketsSearchToolbar,
  MarketsSummaryMetrics,
} from "../components/markets";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  applyMarketsLayoutSizing,
  buildMarketsResponsiveLayoutConfig,
  generateMarketsResponsiveLayouts,
  MARKETS_LAYOUT_MARGIN,
  MARKETS_ROW_HEIGHT,
} from "../configs/marketsLayoutConfig";
import {
  type MarketRow,
  useMarketsPageData,
} from "../hooks/useMarketsPageData";
import { useSettings } from "../context/SettingsContext";
import MorpheumLoadingOverlay from "../components/ui/MorpheumLoadingOverlay";
import "./MarketsPage.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [MARKETS_LAYOUT_MARGIN, MARKETS_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = MARKETS_ROW_HEIGHT;

function buildLayouts(viewportHeight?: number) {
  const base = buildMarketsResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyMarketsLayoutSizing(base, height);
  return generateMarketsResponsiveLayouts(sized, 0);
}

export default function MarketsPage(): JSX.Element {
  const navigate = useNavigate();
  const { settings } = useSettings();
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const [isLayoutMounted, setIsLayoutMounted] = useState(false);
  const [layoutsHydrated, setLayoutsHydrated] = useState(false);
  const [isPageReady, setIsPageReady] = useState(false);
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);

  const handleLayoutMount = useCallback(() => setIsLayoutMounted(true), []);

  const {
    activeTab,
    setActiveTab,
    query,
    setQuery,
    sector,
    setSector,
    risk,
    setRisk,
    revenue,
    setRevenue,
    sortKey,
    sortDir,
    filteredRows,
    handleSort,
    resetFilters,
    totalTradableRows,
  } = useMarketsPageData();

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(window.innerHeight);
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };

    applyViewportLayouts();
    setLayoutsHydrated(true);
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, []);

  useEffect(() => {
    if (!isLayoutMounted || !layoutsHydrated) return;
    const id = requestAnimationFrame(() => setIsPageReady(true));
    return () => cancelAnimationFrame(id);
  }, [isLayoutMounted, layoutsHydrated]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const handleRowNavigate = useCallback(
    (row: MarketRow) => {
      if (row.kind === "agent") {
        navigate(`/agents/${row.id}`);
        return;
      }
      const slug = rowIdToSlug(row.id);
      navigate(slug ? indexDetailPath(slug) : "/cindex");
    },
    [navigate],
  );

  const slotContent = useMemo(
    () => [
      <MarketsHeroHeader
        key="hero"
        height={slotDimensions[0]?.height}
      />,
      <MarketsSearchToolbar
        key="toolbar"
        height={slotDimensions[1]?.height}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        query={query}
        sector={sector}
        risk={risk}
        revenue={revenue}
        onQueryChange={setQuery}
        onSectorChange={setSector}
        onRiskChange={setRisk}
        onRevenueChange={setRevenue}
      />,
      <MarketsFiltersSidebar
        key="filters"
        height={slotDimensions[2]?.height}
        sector={sector}
        risk={risk}
        revenue={revenue}
        onSectorChange={setSector}
        onRiskChange={setRisk}
        onRevenueChange={setRevenue}
        onReset={resetFilters}
      />,
      <MarketsDataTable
        key="table"
        height={slotDimensions[3]?.height ?? "100%"}
        activeTab={activeTab}
        rows={filteredRows}
        sortKey={sortKey}
        sortDir={sortDir}
        showSparklines={settings.markets.showSparklines}
        onSort={handleSort}
        onRowNavigate={handleRowNavigate}
      />,
      null,
      <MarketsSummaryMetrics
        key="metrics"
        height={slotDimensions[5]?.height}
        totalRows={totalTradableRows}
        activeTab={activeTab}
      />,
      null,
      null,
      null,
    ],
    [
      slotDimensions,
      activeTab,
      setActiveTab,
      query,
      sector,
      risk,
      revenue,
      setQuery,
      setSector,
      setRisk,
      setRevenue,
      resetFilters,
      filteredRows,
      sortKey,
      sortDir,
      handleRowNavigate,
      totalTradableRows,
      settings.markets.showSparklines,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--markets">
      {!isPageReady ? (
        <MorpheumLoadingOverlay
          layout="absolute"
          label="Loading markets..."
          matrixText
        />
      ) : null}
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
        onMount={handleLayoutMount}
      />
    </div>
  );
}
