  /**
   * Process deposit
   * POST /bank/v1/deposit
   */
  async deposit(params: {
    to: string;
    amount: number;
    assetId: string;
    source_chain?: string;
    source_txhash?: string;
  }): Promise<{
    txhash: string;
    to: string;
    amount: string;
    collateralAssetIndex: { ticker: string };
    status: string;
    timestamp: { seconds: number; nanos: number };
  }> {
    if (!this.mnemonic) {
      throw new Error("Mnemonic is required for deposit");
    }

    if (!this.walletAddress) {
      await this.initialize();
    }

    const timestamp = toRFC3339Nano();
    const deadline = (Math.floor(Date.now() / 1000) + 300).toString();
    const nonce = await this.getNextNonce();

    const payload = {
      to: params.to,
      amount: toSatoshi(params.amount),
      asset: params.assetId,
      source_chain: params.source_chain,
      source_txhash: params.source_txhash,
    };

    const signatureBuilder = this.getSignatureBuilder();
    const completeMessage = await signatureBuilder.buildCompleteMessage(
      payload,
      this.getNonceProvider(),
    );
    const signature = await signatureBuilder.signPayload(completeMessage);

    const requestBody = {
      to: params.to,
      amount: toSatoshi(params.amount),
      collateralAssetIndex: { ticker: params.assetId },
      source_chain: params.source_chain,
      source_txhash: params.source_txhash,
      timestamp,
      signature,
      nonce,
      deadline,
    };

    const response = await this.httpClient.post(
      "/bank/v1/deposit",
      requestBody,
      this.getHeaders(),
    );
    return response.body;
  }

