  /**
   * Create new pool
   * POST /clamm/v1/pools
   */
  async createCLAMMPool(params: {
    token0: string;
    token1: string;
    feeTier: string;
    tickSpacing: string;
  }): Promise<{
    success: boolean;
    pool_id: string;
    message?: string;
  }> {
    if (!this.mnemonic) {
      throw new Error("Mnemonic is required for createCLAMMPool");
    }

    if (!this.walletAddress) {
      await this.initialize();
    }

    const timestamp = toRFC3339Nano();
    const deadline = (Math.floor(Date.now() / 1000) + 300).toString();
    const nonce = await this.getNextNonce();

    const payload = {
      token0: params.token0,
      token1: params.token1,
      feeTier: params.feeTier,
      tickSpacing: params.tickSpacing,
    };

    const signatureBuilder = this.getSignatureBuilder();
    const completeMessage = await signatureBuilder.buildCompleteMessage(
      payload,
      this.getNonceProvider(),
    );
    const signature = await signatureBuilder.signPayload(completeMessage);

    const requestBody = {
      address: this.getWalletAddress(),
      token0: params.token0,
      token1: params.token1,
      fee_tier: params.feeTier,
      tick_spacing: params.tickSpacing,
      timestamp,
      signature,
      nonce,
      deadline,
      chain_id: this.chainID.toString(),
    };

    const response = await this.httpClient.post(
      "/clamm/v1/pools",
      requestBody,
      this.getHeaders(),
    );
    return response.body;
  }

