import React, { useCallback, useState } from "react";

import { shortWalletAddress } from "./agentHeroFocus";
import "./agent.css";

export interface AgentAddressFieldProps {
  label: string;
  address: string;
  layout?: "about" | "token";
  copyAriaLabel?: string;
}

export function formatAgentMetadataDate(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function AgentAddressField({
  label,
  address,
  layout = "about",
  copyAriaLabel,
}: AgentAddressFieldProps): JSX.Element {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      setCopied(false);
    }
  }, [address]);

  const addressRow = (
    <span className="agent-token-contract-row">
      <span>{shortWalletAddress(address)}</span>
      <button
        type="button"
        className="agent-token-copy-btn"
        onClick={handleCopy}
        aria-label={copyAriaLabel ?? `Copy ${label}`}
      >
        {copied ? "Copied" : "Copy"}
      </button>
    </span>
  );

  if (layout === "token") {
    return (
      <div className="agent-token-kv-row">
        <span className="agent-token-kv-label">{label}</span>
        <span className="agent-token-kv-value agent-token-kv-value--mono">
          {addressRow}
        </span>
      </div>
    );
  }

  return (
    <div className="agent-about-field">
      <span className="agent-about-label">{label}</span>
      <span
        className="agent-about-value agent-about-value--mono"
        title={address}
      >
        {addressRow}
      </span>
    </div>
  );
}

export default AgentAddressField;
