import React from "react";

import type { MarketKind } from "../../hooks/useMarketsPageData";
import "./markets.css";

export interface MarketsSummaryMetricsProps {
  height?: string;
  totalRows: number;
  activeTab: MarketKind;
}

export default function MarketsSummaryMetrics({
  height = "100%",
  totalRows,
  activeTab,
}: MarketsSummaryMetricsProps): JSX.Element {
  const modeLabel =
    activeTab === "agent" ? "Individual agents" : "The basket";

  return (
    <div
      className="markets-slot markets-header-band markets-header-band--metrics markets-summary-metrics"
      style={{ height }}
      aria-label="Markets summary"
    >
      <div className="markets-summary-metrics-inner">
        <div className="markets-summary-metric">
          <span className="markets-summary-metric-label">Market breadth</span>
          <strong className="markets-summary-metric-value">
            {totalRows} tradable rows
          </strong>
        </div>
        <div className="markets-summary-metric">
          <span className="markets-summary-metric-label">Mode</span>
          <strong className="markets-summary-metric-value">{modeLabel}</strong>
        </div>
      </div>
    </div>
  );
}
