/**
 * Wallet modal: anchored panel below the connect-wallet button (Settings-style overlay).
 * Displays: network chain, full address, total account value, Copy Address, transfers,
 * deposit/withdraw, Disconnect.
 */
import React, { useMemo } from "react";
import { createPortal } from "react-dom";
import { toast } from "sonner";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useStaggeredOverlay,
} from "./ui/overlay";
import { useBucketCollections } from "../hooks/useBucketCollections";
import { formatCurrency } from "../sdk/utils/display";
import { useOptionalSettings } from "../context/SettingsContext";
import "./smartlayout/layout.css";
import "./wallet-modal.css";

const OFFLINE_BASE_URL = "offline://local";

/** Mask formatted currency digits while preserving separators (e.g. $**,***.**). */
function maskCurrencyDisplay(formattedAmount: string): string {
  const [integerPart = "", decimalPart = ""] = formattedAmount.split(".");
  const maskedInteger = integerPart.replace(/\d/g, "*");
  const maskedDecimal = (decimalPart || "00").replace(/\d/g, "*");
  return `$${maskedInteger}.${maskedDecimal}`;
}

export interface WalletModalProps {
  isOpen: boolean;
  onClose: () => void;
  /** Display name for the connected RPC network chain */
  networkChainName: string;
  /** Full wallet address */
  walletAddress: string;
  /** Called when Copy Address is clicked */
  onCopyAddress?: () => void;
  /** Called when Bucket Transfer is clicked */
  onBucketTransfer?: () => void;
  /** Called when Coin Transfer is clicked (opens wallet-to-address transfer modal) */
  onCoinTransfer?: () => void;
  /** Called when Deposit is clicked (opens cross-chain deposit modal) */
  onDeposit?: () => void;
  /** Called when Withdraw is clicked (opens cross-chain withdraw modal) */
  onWithdraw?: () => void;
  /** Called when Disconnect is clicked */
  onDisconnect?: () => void;
  /** Optional ref for the anchor button; used to position the modal below it */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

function WalletModal({
  isOpen,
  onClose,
  networkChainName,
  walletAddress,
  onCopyAddress,
  onBucketTransfer,
  onCoinTransfer,
  onDeposit,
  onWithdraw,
  onDisconnect,
}: WalletModalProps): JSX.Element | null {
  const settingsContext = useOptionalSettings();
  const showWalletAccountValue =
    settingsContext?.settings.showWalletAccountValue ?? true;

  const { collections, spotWalletBalance } = useBucketCollections({
    baseURL: OFFLINE_BASE_URL,
    walletAddress,
    refreshInterval: 5000,
  });

  const totalAccountValueUsd = useMemo(() => {
    const bucketEquity = collections.reduce(
      (sum, collection) => sum + collection.totalEquity,
      0,
    );
    return spotWalletBalance + bucketEquity;
  }, [collections, spotWalletBalance]);

  const accountValueDisplay = useMemo(() => {
    const formatted = formatCurrency(totalAccountValueUsd);
    return showWalletAccountValue
      ? `$${formatted}`
      : maskCurrencyDisplay(formatted);
  }, [showWalletAccountValue, totalAccountValueUsd]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: OVERLAY_TIMING.desktopScaleMs,
  });

  useOverlayEscapeKey(isOpen, onClose);

  const handleCopyAddress = () => {
    if (walletAddress) {
      navigator.clipboard.writeText(walletAddress).then(
        () => toast.success("Address copied to clipboard"),
        () => toast.error("Failed to copy address"),
      );
    }
    onCopyAddress?.();
  };

  const handleBucketTransfer = () => {
    onClose();
    onBucketTransfer?.();
  };

  const handleCoinTransfer = () => {
    onClose();
    onCoinTransfer?.();
  };

  const handleDeposit = () => {
    onClose();
    onDeposit?.();
  };

  const handleWithdraw = () => {
    onClose();
    onWithdraw?.();
  };

  const handleDisconnect = () => {
    onClose();
    onDisconnect?.();
  };

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot
      passThrough={!isOpen}
      className="wallet-modal-overlay"
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={`wallet-modal-panel terminal-overlay-panel-shell staggered-overlay-panel--scale${!isOpen ? " bucket-modal-panel--closing" : ""}`}
        aria-label="Wallet"
        role="dialog"
      >
        <div className="wallet-modal-header">
          <h3>Wallet</h3>
        </div>

        <div className="wallet-modal-body">
          <div className="wallet-modal-account-value">
            <span className="terminal-label">Total account value</span>
            <span
              className={`wallet-modal-account-value-amount${showWalletAccountValue ? "" : " wallet-modal-account-value-amount--masked"}`}
              aria-label={
                showWalletAccountValue
                  ? `Total account value $${formatCurrency(totalAccountValueUsd)}`
                  : "Total account value hidden"
              }
            >
              {accountValueDisplay}
            </span>
          </div>

          <div className="wallet-modal-row">
            <span className="terminal-label">Network</span>
            <span className="wallet-modal-value">{networkChainName}</span>
          </div>

          <div className="wallet-modal-row">
            <span className="terminal-label">Address</span>
            <span className="terminal-value wallet-modal-address" title={walletAddress}>
              {walletAddress}
            </span>
          </div>

          <div className="wallet-modal-actions">
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn"
              onClick={handleCopyAddress}
            >
              Copy Address
            </button>
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn"
              onClick={handleBucketTransfer}
            >
              Bucket Transfer
            </button>
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn"
              onClick={handleCoinTransfer}
            >
              Coin Transfer
            </button>
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn"
              onClick={handleDeposit}
              data-tour="deposit-tour-wallet-deposit"
            >
              Deposit
            </button>
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn"
              onClick={handleWithdraw}
            >
              Withdraw
            </button>
            <button
              type="button"
              className="btn btn-danger onboard-option-btn"
              onClick={handleDisconnect}
            >
              Disconnect
            </button>
          </div>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default WalletModal;
