import React, { useMemo, useState } from "react";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import {
  filterLineDataByRange,
  PNL_CHART_VIEW_OPTIONS,
  type PnlChartViewMode,
  type PortfolioTimeRange,
} from "../../utils/portfolioChartData";
import PortfolioAgentPnlChart from "./PortfolioAgentPnlChart";
import PortfolioAgentRankChart from "./PortfolioAgentRankChart";
import PortfolioDailyPnlCard from "./PortfolioDailyPnlCard";
import PortfolioFleetEdgeChart from "./PortfolioFleetEdgeChart";
import PortfolioLeftAxisTimeSeriesChart from "./PortfolioLeftAxisTimeSeriesChart";
import {
  getVisibleHeroChartModes,
  type PortfolioHeroView,
} from "./portfolioHeroView";
import "../tables/TabSection.css";
import "./portfolio.css";

export type HeroChartMode =
  | "equity"
  | "pnl"
  | "dailyPnl"
  | "fleetEdge"
  | "agentRank";

export interface PortfolioHeroChartsProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  focusAgentId?: string | null;
  refreshInterval?: number;
  chartMode?: HeroChartMode;
  onChartModeChange?: (mode: HeroChartMode) => void;
  timeRange?: PortfolioTimeRange;
  onTimeRangeChange?: (range: PortfolioTimeRange) => void;
  heroView?: PortfolioHeroView;
  layoutBreakpoint?: string;
}

const CHART_TABS = [
  { id: "equity", label: "Equity" },
  { id: "pnl", label: "PnL Attribution" },
  { id: "dailyPnl", label: "Daily PnL" },
  { id: "fleetEdge", label: "Fleet Edge" },
  { id: "agentRank", label: "Composite Rank" },
] as const;

const TIME_RANGE_OPTIONS: { value: PortfolioTimeRange; label: string }[] = [
  { value: "all", label: "All-time" },
  { value: "30d", label: "30D" },
  { value: "7d", label: "7D" },
  { value: "24h", label: "24H" },
];

function formatCurrency(value: number): string {
  const sign = value < 0 ? "-" : "";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000) return `${sign}$${(abs / 1_000).toFixed(1)}k`;
  return `${sign}$${abs.toFixed(2)}`;
}

function PortfolioHeroCharts({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  focusAgentId: focusAgentIdProp = null,
  refreshInterval,
  chartMode: chartModeProp,
  onChartModeChange,
  timeRange: timeRangeProp,
  onTimeRangeChange,
  heroView = "overview",
  layoutBreakpoint,
}: PortfolioHeroChartsProps): JSX.Element {
  const { selectedAgentId: focusAgentIdFromStore } = useTradingAgents();
  const focusAgentId = focusAgentIdProp ?? focusAgentIdFromStore;
  const [internalChartMode, setInternalChartMode] =
    useState<HeroChartMode>("equity");
  const visibleChartModes = useMemo(
    () => getVisibleHeroChartModes(heroView),
    [heroView],
  );
  const chartTabs = useMemo(
    () => CHART_TABS.filter((tab) => visibleChartModes.includes(tab.id)),
    [visibleChartModes],
  );
  const requestedChartMode = chartModeProp ?? internalChartMode;
  const chartMode = visibleChartModes.includes(requestedChartMode)
    ? requestedChartMode
    : visibleChartModes[0];
  const setChartMode = onChartModeChange ?? setInternalChartMode;
  const [internalTimeRange, setInternalTimeRange] =
    useState<PortfolioTimeRange>("all");
  const timeRange = timeRangeProp ?? internalTimeRange;
  const setTimeRange = onTimeRangeChange ?? setInternalTimeRange;
  const [pnlViewMode, setPnlViewMode] = useState<PnlChartViewMode>("topAgents");
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    focusAgentId,
    refreshInterval,
  });

  const equitySeries = useMemo(() => {
    if (focusAgentId && analytics.focusEquityCurveSeries) {
      return analytics.focusEquityCurveSeries.map((entry) => ({
        id: entry.id,
        color: entry.color,
        data: filterLineDataByRange(entry.data, timeRange),
      }));
    }
    return [
      {
        id: "equity",
        color: TERMINAL_COLORS.brand,
        data: filterLineDataByRange(analytics.equityCurveData, timeRange),
      },
    ];
  }, [
    focusAgentId,
    analytics.focusEquityCurveSeries,
    analytics.equityCurveData,
    timeRange,
  ]);

  const showTimeRange =
    chartMode === "equity" ||
    chartMode === "pnl" ||
    chartMode === "fleetEdge" ||
    chartMode === "agentRank";

  const fleetEdgeSummary = analytics.fleetEdgeByRange[timeRange];
  const agentRankSummary = analytics.agentRankByRange[timeRange];

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section className="portfolio-hero-charts">
      <TabLayoutHeaderToolBar
        tabs={[...chartTabs]}
        activeTabId={chartMode}
        onTabChange={(id) => setChartMode(id as HeroChartMode)}
      >
        <div className="portfolio-hero-chart-controls">
          {showTimeRange ? (
            <select
              className="portfolio-hero-time-range"
              value={timeRange}
              onChange={(event) =>
                setTimeRange(event.target.value as PortfolioTimeRange)
              }
              aria-label="Chart time range"
            >
              {TIME_RANGE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          ) : null}
          {chartMode === "pnl" && !focusAgentId ? (
            <select
              className="portfolio-hero-time-range"
              value={pnlViewMode}
              onChange={(event) =>
                setPnlViewMode(event.target.value as PnlChartViewMode)
              }
              aria-label="PnL chart view"
            >
              {PNL_CHART_VIEW_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          ) : null}
        </div>
      </TabLayoutHeaderToolBar>
      <div className="portfolio-hero-charts-body">
        {chartMode === "dailyPnl" ? (
          <PortfolioDailyPnlCard
            summary={
              focusAgentId && analytics.focusDailyPnlSummary
                ? analytics.focusDailyPnlSummary
                : analytics.dailyPnlSummary
            }
            days={
              focusAgentId && analytics.focusDailyPnlByDay
                ? analytics.focusDailyPnlByDay
                : analytics.dailyPnlByDay
            }
            layoutBreakpoint={layoutBreakpoint}
            focusAgentId={focusAgentId}
          />
        ) : chartMode === "fleetEdge" ? (
          <PortfolioFleetEdgeChart
            summary={fleetEdgeSummary}
            focusAgentId={focusAgentId}
          />
        ) : chartMode === "agentRank" ? (
          <PortfolioAgentRankChart
            summary={agentRankSummary}
            focusAgentId={focusAgentId}
          />
        ) : chartMode === "equity" ? (
          <>
            <PortfolioLeftAxisTimeSeriesChart
              variant="area"
              series={equitySeries}
              emptyMessage="No equity data"
              className="portfolio-equity-chart-canvas"
            />
            {focusAgentId && analytics.focusEquityCurveSeries ? (
              <div className="portfolio-equity-chart-legend">
                {analytics.focusEquityCurveSeries.map((entry) => (
                  <div key={entry.id} className="portfolio-attribution-row">
                    <span
                      className="portfolio-attribution-dot"
                      style={{ background: entry.color }}
                      aria-hidden
                    />
                    <span>{entry.label}</span>
                  </div>
                ))}
              </div>
            ) : null}
          </>
        ) : (
          <PortfolioAgentPnlChart
            allSeries={analytics.cumulativePnlSeries}
            viewMode={pnlViewMode}
            timeRange={timeRange}
            trades={analytics.trades}
            taskAgentMap={analytics.taskAgentMap}
            filterAgentIds={filterAgentIds}
            focusAgentId={focusAgentId}
          />
        )}
       
      </div>
    </section>
    </div>
  );
}

export default React.memo(PortfolioHeroCharts);
