import React from "react";
import { createPortal } from "react-dom";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import { LEVERAGE_MIN, LEVERAGE_MAX } from "../../constants";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../../terminal.css";
import "./layout.css";

/**
 * Leverage Selection Modal
 */
export function LeverageModal({
  isOpen,
  currentLeverage: _currentLeverage,
  tempLeverage,
  maxRatio,
  onLeverageChange,
  onConfirm,
  onCancel,
  onOverlayClick = () => {},
}: {
  isOpen: boolean;
  currentLeverage: number;
  tempLeverage: number;
  maxRatio: string;
  onLeverageChange: (leverage: number) => void;
  onConfirm: () => void;
  onCancel: () => void;
  /** Called when the modal overlay (backdrop) is clicked. Default: no-op. */
  onOverlayClick?: () => void;
}): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onCancel);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onOverlayClick}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content staggered-overlay-panel--scale"
        aria-label="Select Leverage"
      >
        <div className="modal-header">
          <h3 className="terminal-panel-title">Select Leverage</h3>
        </div>
        <div className="modal-body">
          <div className="leverage-max-ratio">
            <div className="terminal-label leverage-max-ratio-label">
              Maximum Ratio
            </div>
            <div className="terminal-price leverage-max-ratio-value">
              {maxRatio}x
            </div>
          </div>

          <div className="leverage-slider-container">
            <FilledRangeSlider
              variant="brand"
              min={LEVERAGE_MIN}
              max={LEVERAGE_MAX}
              value={tempLeverage}
              onChange={onLeverageChange}
            />
            <div className="leverage-slider-labels">
              <span className="terminal-value">1x</span>
              <span className="terminal-value leverage-current-value">
                {tempLeverage}x
              </span>
              <span className="terminal-value">100x</span>
            </div>
          </div>
        </div>
        <div className="modal-footer">
          <button onClick={onCancel} className="btn btn-secondary">
            Cancel
          </button>
          <button onClick={onConfirm} className="btn btn-primary">
            Confirm
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
