import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  CandlestickSeries,
  CrosshairMode,
  createChart,
  type CandlestickData,
  type DeepPartial,
  type ChartOptions,
  type IChartApi,
  type ISeriesApi,
} from "lightweight-charts";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { useBinanceKline } from "../../hooks/useBinanceKline";
import KlineChartLoadingOverlay from "../finchartview/KlineChartLoadingOverlay";
import type { ReviewChartMarket } from "./resolveReviewChartMarket";

export type ReviewChartRange = "1h" | "4h" | "1d" | "1w";

const REVIEW_CHART_RANGES: Record<
  ReviewChartRange,
  { interval: string; limit: number; label: string; caption: string }
> = {
  "1h": { interval: "1m", limit: 60, label: "1H", caption: "last 1 hour" },
  "4h": { interval: "5m", limit: 48, label: "4H", caption: "last 4 hours" },
  "1d": { interval: "15m", limit: 96, label: "1D", caption: "last 24 hours" },
  "1w": { interval: "1h", limit: 168, label: "1W", caption: "last 7 days" },
};

const RANGE_OPTIONS: ReviewChartRange[] = ["1h", "4h", "1d", "1w"];

function createMiniCandleChartOptions(): DeepPartial<ChartOptions> {
  return {
    autoSize: false,
    layout: {
      background: { color: "transparent" },
      textColor: TERMINAL_COLORS.muted,
      attributionLogo: false,
    },
    grid: {
      vertLines: { color: TERMINAL_COLORS.gridMajor },
      horzLines: { color: TERMINAL_COLORS.gridMajor },
    },
    crosshair: { mode: CrosshairMode.Hidden },
    handleScroll: false,
    handleScale: false,
    rightPriceScale: {
      visible: true,
      borderVisible: false,
      scaleMargins: { top: 0.1, bottom: 0.1 },
    },
    timeScale: {
      visible: false,
      borderVisible: false,
    },
  };
}

interface SafetyLogReviewMiniChartCanvasProps {
  symbol: string;
  interval: string;
  limit: number;
}

function SafetyLogReviewMiniChartCanvas({
  symbol,
  interval,
  limit,
}: SafetyLogReviewMiniChartCanvasProps): JSX.Element {
  const containerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);

  const { candles, loading, error } = useBinanceKline({
    symbol,
    interval,
    limit,
  });

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const chart = createChart(container, createMiniCandleChartOptions());
    const series = chart.addSeries(CandlestickSeries, {
      upColor: TERMINAL_COLORS.long,
      downColor: TERMINAL_COLORS.short,
      borderVisible: false,
      wickUpColor: TERMINAL_COLORS.long,
      wickDownColor: TERMINAL_COLORS.short,
    });

    chartRef.current = chart;
    seriesRef.current = series;

    const resize = () => {
      const { clientWidth, clientHeight } = container;
      if (clientWidth > 0 && clientHeight > 0) {
        chart.resize(clientWidth, clientHeight);
      }
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(container);

    return () => {
      observer.disconnect();
      chart.remove();
      chartRef.current = null;
      seriesRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!seriesRef.current || !chartRef.current) return;
    const data = candles as CandlestickData[];
    seriesRef.current.setData(data);
    if (data.length > 0) {
      chartRef.current.timeScale().fitContent();
    }
  }, [candles]);

  const stateClass = error
    ? "safety-log-review-mini-chart--error"
    : !loading && candles.length === 0
      ? "safety-log-review-mini-chart--empty"
      : "";

  return (
    <div
      className={["safety-log-review-mini-chart", stateClass].filter(Boolean).join(" ")}
    >
      <div ref={containerRef} className="safety-log-review-mini-chart-canvas" />
      {loading ? <KlineChartLoadingOverlay /> : null}
      {error ? (
        <p className="safety-log-review-mini-chart-status safety-log-review-mini-chart-status--error">
          {error}
        </p>
      ) : null}
      {!loading && !error && candles.length === 0 ? (
        <p className="safety-log-review-mini-chart-status">No candle data</p>
      ) : null}
    </div>
  );
}

export interface SafetyLogReviewMiniChartProps {
  market: ReviewChartMarket;
  taskId: string;
}

function SafetyLogReviewMiniChart({
  market,
  taskId,
}: SafetyLogReviewMiniChartProps): JSX.Element {
  const [range, setRange] = useState<ReviewChartRange>("1h");
  const rangeConfig = REVIEW_CHART_RANGES[range];
  const chartEnabled = Boolean(market.binanceSymbol);

  useEffect(() => {
    setRange("1h");
  }, [taskId, market.marketId]);

  return (
    <div className="safety-log-review-mini-chart-wrap">
      <div
        className="safety-log-review-range-bar"
        role="group"
        aria-label="Chart time range"
      >
        {RANGE_OPTIONS.map((option) => {
          const { label } = REVIEW_CHART_RANGES[option];
          return (
            <button
              key={option}
              type="button"
              className={[
                "safety-log-review-range-btn",
                range === option ? "is-active" : "",
              ]
                .filter(Boolean)
                .join(" ")}
              disabled={!chartEnabled}
              aria-pressed={range === option}
              onClick={() => setRange(option)}
            >
              {label}
            </button>
          );
        })}
      </div>

      {chartEnabled && market.binanceSymbol ? (
        <SafetyLogReviewMiniChartCanvas
          key={`${market.binanceSymbol}-${range}-${taskId}`}
          symbol={market.binanceSymbol}
          interval={rangeConfig.interval}
          limit={rangeConfig.limit}
        />
      ) : (
        <div className="safety-log-review-mini-chart safety-log-review-mini-chart--placeholder">
          <p className="safety-log-review-mini-chart-status">
            Chart preview unavailable for {market.displayLabel}
          </p>
        </div>
      )}

      <p className="safety-log-review-chart-caption">
        {market.baseAsset} · {rangeConfig.caption}
      </p>
    </div>
  );
}

export default React.memo(SafetyLogReviewMiniChart);
