import { useEffect, useState } from "react";

import {
  getCopyReplayLeaderEvents,
  subscribeCopyMirrorReplayListeners,
} from "../../offline/mock_data/copyMirrorReplay";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import {
  FLEET_TRADE_HISTORY_DATA_BASE_URL,
  fetchFleetTradesByCatalogId,
} from "../sdk/api/fleetTradeHistory/fleetTradeHistoryClient";

export interface UseFleetAgentTradesResult {
  trades: FleetTradeEvent[];
  loading: boolean;
  error: string | null;
}

function mergeFleetTrades(
  staticEvents: FleetTradeEvent[],
  replayEvents: FleetTradeEvent[],
): FleetTradeEvent[] {
  const seen = new Set<string>();
  const merged: FleetTradeEvent[] = [];
  for (const event of [...replayEvents, ...staticEvents]) {
    if (seen.has(event.id)) continue;
    seen.add(event.id);
    merged.push(event);
  }
  return merged.sort(
    (a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp),
  );
}

export function useFleetAgentTrades(
  catalogAgentId: string,
  baseUrl: string = FLEET_TRADE_HISTORY_DATA_BASE_URL,
): UseFleetAgentTradesResult {
  const [staticTrades, setStaticTrades] = useState<FleetTradeEvent[]>([]);
  const [, setReplayRevision] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const normalizedId = catalogAgentId.trim();

  useEffect(() => {
    if (!normalizedId) {
      setStaticTrades([]);
      setLoading(false);
      setError("Missing fleet catalog agent id");
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchFleetTradesByCatalogId(normalizedId, baseUrl)
      .then((events) => {
        if (cancelled) return;
        setStaticTrades(events);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load fleet trade history",
        );
        setStaticTrades([]);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [normalizedId, baseUrl]);

  useEffect(() => {
    return subscribeCopyMirrorReplayListeners(() => {
      setReplayRevision((value) => value + 1);
    });
  }, []);

  const trades = mergeFleetTrades(
    staticTrades,
    normalizedId ? getCopyReplayLeaderEvents(normalizedId) : [],
  );

  return { trades, loading, error };
}
