import { useEffect, useMemo } from "react";
import { useOptionalSettings } from "../../context/SettingsContext";
import { getDefaultBindingForAction } from "./defaults";
import { matchesKeyboardBinding } from "./matchKeyboardBinding";
import type { KeyboardBinding, ShortcutActionId } from "./types";

export interface UseKeyboardShortcutOptions {
  enabled?: boolean;
  suppressWhen?: (event: KeyboardEvent) => boolean;
  binding?: KeyboardBinding;
}

export function useKeyboardShortcut(
  actionId: ShortcutActionId,
  handler: (event: KeyboardEvent) => void,
  {
    enabled = true,
    suppressWhen,
    binding: bindingOverride,
  }: UseKeyboardShortcutOptions = {},
): void {
  const settingsContext = useOptionalSettings();
  const settingsBinding = settingsContext?.settings.keyboardShortcuts[actionId];
  const binding = useMemo(
    () =>
      bindingOverride ??
      settingsBinding ??
      getDefaultBindingForAction(actionId),
    [actionId, bindingOverride, settingsBinding],
  );

  useEffect(() => {
    if (!enabled) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (suppressWhen?.(event)) return;
      if (!matchesKeyboardBinding(event, binding)) return;
      event.preventDefault();
      handler(event);
    };

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [actionId, binding, enabled, handler, suppressWhen]);
}
