import type { Market } from "../../store/types";

export type IntentGenContext = {
  symbol: string;
  peer: string;
  params: Record<string, number | string>;
};

export type IntentExampleTemplate = {
  templateId: string;
  actorType: string;
  buildIntent: (ctx: IntentGenContext) => string;
  buildSummary: (ctx: IntentGenContext) => string;
};

export type GeneratedIntent = {
  instanceId: string;
  templateId: string;
  actorType: string;
  summary: string;
  intentText: string;
  createdAt: number;
};

const PEER_MAP: Record<string, string> = {
  NVDA: "AMD",
  TSLA: "AMD",
  BTC: "ETH",
  ETH: "BTC",
  SOL: "AVAX",
  AAPL: "MSFT",
  PLTR: "COIN",
  AMD: "NVDA",
  META: "GOOGL",
  AMZN: "GOOGL",
};

const NL_SYMBOL_ALIASES: Record<string, string> = {
  XAU: "gold",
  XAG: "silver",
  TSLA: "Tesla",
};

function randomInRange(min: number, max: number, decimals = 1): number {
  const value = min + Math.random() * (max - min);
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function pickOne<T>(items: readonly T[]): T {
  return items[Math.floor(Math.random() * items.length)]!;
}

export function resolveBaseAsset(
  selectedMarket: Pick<Market, "baseAsset" | "moniker" | "symbol"> | null | undefined,
  selectedMarketSymbol: string | null | undefined,
): string {
  if (selectedMarket?.baseAsset) return selectedMarket.baseAsset;
  const fromSymbol = selectedMarketSymbol?.split(/[-/]/)[0]?.trim();
  return fromSymbol || "";
}

export function resolveDisplaySymbol(baseAsset: string): string {
  const upper = baseAsset.toUpperCase();
  return NL_SYMBOL_ALIASES[upper] ?? upper;
}

export function resolvePeerSymbol(baseAsset: string): string {
  const upper = baseAsset.toUpperCase();
  return PEER_MAP[upper] ?? "sector peer";
}

