export function randomizeParams(templateId: string): Record<string, number | string> {
  switch (templateId) {
    case "momentum-risk-guard":
      return {
        drawdown: randomInRange(1, 3),
        alertThreshold: randomInRange(2, 5),
        rebalance: pickOne(["weekly", "bi-weekly"] as const),
      };
    case "mean-reversion": {
      const pair = pickOne([
        { slow: 200, fast: 50 },
        { slow: 100, fast: 20 },
      ] as const);
      return {
        emaSlow: pair.slow,
        emaFast: pair.fast,
        positionSize: randomInRange(0.5, 2),
      };
    }
    case "news-event":
      return {
        trigger: pickOne([
          "earnings",
          "key announcements, and macro updates",
          "earnings, executive updates, and FSD news",
        ] as const),
        riskCap: randomInRange(3, 7),
      };
    case "scalping":
      return {
        stopLoss: randomInRange(0.3, 0.8),
        takeProfit: randomInRange(1, 2),
      };
    case "stat-arb":
      return {
        spreadThreshold: randomInRange(1.5, 3),
        maxHoldHours: Math.round(randomInRange(24, 72, 0)),
      };
    case "sentiment-macro":
      return {
        allocation: randomInRange(2, 5),
      };
    case "portfolio-allocation":
      return {
        weight: Math.round(randomInRange(30, 50, 0)),
        rebalance: pickOne(["monthly", "quarterly"] as const),
        volTarget: Math.round(randomInRange(12, 18, 0)),
      };
    case "polymarket-event":
      return {
        marketCap: Math.round(randomInRange(300, 700, 0)),
      };
    default:
      return {};
  }
}

export function pickRandomTemplate(): IntentExampleTemplate {
  return pickOne(INTENT_TEMPLATES);
}

function createInstanceId(): string {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return `intent-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function generateIntent(baseAsset: string): GeneratedIntent {
  const template = pickRandomTemplate();
  const symbol = resolveDisplaySymbol(baseAsset);
  const peer = resolvePeerSymbol(baseAsset);
  const params = randomizeParams(template.templateId);
  const ctx: IntentGenContext = { symbol, peer, params };

  return {
    instanceId: createInstanceId(),
    templateId: template.templateId,
    actorType: template.actorType,
    summary: template.buildSummary(ctx),
    intentText: template.buildIntent(ctx),
    createdAt: Date.now(),
  };
}

