import React, { type JSX } from "react";
import type { ChartExecutionMarkerMeta } from "./chartMarkers";
import ChartOrderBubble from "./ChartOrderBubble";
import { formatNumber } from "../../sdk/utils/display";
import { TERMINAL_COLORS } from "../../constants/terminalColors";

export interface ExecutionMarkerBubbleProps {
  meta: ChartExecutionMarkerMeta;
  x: number;
  y: number;
  containerWidth: number;
  containerHeight: number;
  onViewTask?: () => void;
}

function ExecutionMarkerBubble({
  meta,
  x,
  y,
  containerWidth,
  containerHeight,
  onViewTask,
}: ExecutionMarkerBubbleProps): JSX.Element {
  const pnlColor =
    meta.closedPnl == null
      ? undefined
      : meta.closedPnl > 0
        ? TERMINAL_COLORS.long
        : meta.closedPnl < 0
          ? TERMINAL_COLORS.short
          : undefined;

  return (
    <ChartOrderBubble
      kind={meta.kind}
      title={meta.direction}
      side={meta.side}
      size={meta.size}
      price={meta.price}
      footer={
        meta.closedPnl != null
          ? `Closed PnL ${formatNumber(meta.closedPnl)}`
          : undefined
      }
      footerColor={pnlColor}
      x={x}
      y={y}
      containerWidth={containerWidth}
      containerHeight={containerHeight}
      onViewTask={onViewTask}
    />
  );
}

export default ExecutionMarkerBubble;
