import type { JSX, ReactNode } from "react";
import type { IntentArchetype, IntentBreakdown } from "../intentBreakdown";
import type { ContractOverrides } from "../executionContract";
import { IntentArchetypeOverride } from "./IntentArchetypeOverride";
import { IntentConditionalBody } from "./IntentConditionalBody";
import type { ControlDepth } from "./IntentControlDepthToggle";
import { IntentDirectionalBody } from "./IntentDirectionalBody";
import { IntentParkedBanner } from "./IntentParkedBanner";
import { IntentPortfolioBody } from "./IntentPortfolioBody";
import { IntentRelationalBody } from "./IntentRelationalBody";

export interface IntentAdaptiveRegionProps {
  breakdown: IntentBreakdown | null;
  displayedArchetype: IntentArchetype | null;
  depth: ControlDepth;
  contractOverrides: ContractOverrides;
  onArchetypeOverride: (archetype: IntentArchetype) => void;
  onContractOverride: (patch: ContractOverrides) => void;
  onOpenManual?: () => void;
  compactSummary?: ReactNode;
}

export function IntentAdaptiveRegion({
  breakdown,
  displayedArchetype,
  depth,
  contractOverrides,
  onArchetypeOverride,
  onContractOverride,
  onOpenManual,
  compactSummary,
}: IntentAdaptiveRegionProps): JSX.Element | null {
  if (!breakdown) return null;

  if (breakdown.isParked) {
    return (
      <IntentParkedBanner reason={breakdown.parkedReason} onOpenManual={onOpenManual} />
    );
  }

  const archetype = displayedArchetype ?? breakdown.wireframe;

  return (
    <div className="intent-adaptive-region">
      <div className="intent-adaptive-header">
        <span className="intent-adaptive-label">‹ {archetype} ›</span>
        <IntentArchetypeOverride active={archetype} onSelect={onArchetypeOverride} />
      </div>

      {compactSummary ? (
        <div className="intent-adaptive-summary">{compactSummary}</div>
      ) : null}

      {archetype === "directional" ? (
        <IntentDirectionalBody
          direction={
            contractOverrides.direction ??
            breakdown.slots.direction.value ??
            "long"
          }
          sizePct={
            contractOverrides.sizePct ??
            breakdown.slots.risk.value?.sizePct ??
            20
          }
          leverage={
            contractOverrides.leverage ??
            breakdown.slots.risk.value?.leverage ??
            5
          }
          depth={depth}
          stopLoss={
            contractOverrides.stopLoss ?? breakdown.slots.risk.value?.stopLoss
          }
          takeProfit={
            contractOverrides.takeProfit ?? breakdown.slots.risk.value?.takeProfit
          }
          reduceOnly={breakdown.slots.risk.value?.reduceOnly}
          onChange={onContractOverride}
        />
      ) : null}

      {archetype === "relational" ? (
        <IntentRelationalBody breakdown={breakdown} />
      ) : null}

      {archetype === "portfolio" ? (
        <IntentPortfolioBody breakdown={breakdown} />
      ) : null}

      {archetype === "conditional" ? (
        <IntentConditionalBody breakdown={breakdown} />
      ) : null}
    </div>
  );
}
