import React, { useLayoutEffect, useRef, type JSX } from "react";
import { Typewriter } from "../ui/Typewriter";
import {
  resolveDisplaySymbol,
  type FeedEnterState,
  type GeneratedIntent,
} from "./intentExamples";
import { useFlipListInsert } from "./useFlipListInsert";
import { BubbleTip, resolveIntentBubbleId, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

export interface AgentIntentExampleCardsProps {
  baseAsset: string;
  intents: GeneratedIntent[];
  enterState: FeedEnterState | null;
  exitingId: string | null;
  onSelect: (intent: GeneratedIntent) => void;
  onExitAnimationEnd: (instanceId: string) => void;
  selectedInstanceId?: string | null;
}

export function AgentIntentExampleCards({
  baseAsset,
  intents,
  enterState,
  exitingId,
  onSelect,
  onExitAnimationEnd,
  selectedInstanceId,
}: AgentIntentExampleCardsProps): JSX.Element | null {
  const scrollRef = useRef<HTMLDivElement>(null);
  const prevCountRef = useRef(0);

  const itemIds = intents.map((intent) => intent.instanceId);
  const enteringId =
    enterState?.phase === "push" ? enterState.instanceId : null;

  const setFlipRef = useFlipListInsert({ itemIds, enteringId });

  const displaySymbol = resolveDisplaySymbol(baseAsset);

  useLayoutEffect(() => {
    if (intents.length > prevCountRef.current && scrollRef.current) {
      scrollRef.current.scrollTop = 0;
    }
    prevCountRef.current = intents.length;
  }, [intents.length]);

  if (!baseAsset) return null;

  return (
    <div className="agent-intent-examples">
      <BubbleTip id={BUBBLE_TIP_IDS.liveIntents}>
        <div className="agent-intent-status agent-intent-examples-header">
          Live intents for {displaySymbol}
        </div>
      </BubbleTip>
      <div
        ref={scrollRef}
        className="agent-intent-examples-scroll"
        aria-live="polite"
        aria-label={`Live intent suggestions for ${displaySymbol}`}
      >
        {intents.map((intent) => {
          const isPushing =
            enterState?.instanceId === intent.instanceId &&
            enterState.phase === "push";
          const isRevealing =
            enterState?.instanceId === intent.instanceId &&
            enterState.phase === "reveal";
          const isExiting = exitingId === intent.instanceId;
          const isActive = selectedInstanceId === intent.instanceId;
          const typewriterActive = !isPushing;

          return (
            <BubbleTip
              key={intent.instanceId}
              id={resolveIntentBubbleId(intent.templateId)}
            >
              <div
                ref={setFlipRef(intent.instanceId)}
                className="feed-card-flip-shell"
              >
                <button
                  type="button"
                  className={[
                    "agent-intent-example-card",
                    isPushing ? "is-push" : "",
                    isRevealing ? "is-reveal" : "",
                    isExiting ? "is-exiting" : "",
                    isActive ? "is-active" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                  onClick={() => onSelect(intent)}
                  onAnimationEnd={(event) => {
                    if (
                      isExiting &&
                      event.animationName === "agentIntentCardExit"
                    ) {
                      onExitAnimationEnd(intent.instanceId);
                    }
                  }}
                >
                  <>
                    <Typewriter
                      text={intent.actorType}
                      className="agent-intent-example-card-title"
                      active={typewriterActive}
                    />
                    <Typewriter
                      text={intent.summary}
                      className="agent-intent-example-card-summary"
                      multiline="auto"
                      active={typewriterActive}
                    />
                  </>
                </button>
              </div>
            </BubbleTip>
          );
        })}
      </div>
    </div>
  );
}
