import {
  useCallback,
  useLayoutEffect,
  useRef,
  type RefObject,
} from "react";
import { FEED_INSERT_DURATION_MS } from "../tradeops/feedAnimation";
import {
  computeDeckVisibleCapacity,
  DECK_DEFAULT_VISIBLE_INTENTS,
  DECK_ESTIMATED_CARD_HEIGHT_PX,
  DECK_MIN_VISIBLE_INTENTS,
  type DeckCapacityOptions,
} from "./deckCapacity";

export interface UseDeckCardCapacityParams {
  cardsViewportRef: RefObject<HTMLDivElement>;
  /** Stable queue ids used for measurement (exclude exiting animation ghosts). */
  measureCardIds: string[];
  setFlipRef: (id: string) => (el: HTMLElement | null) => void;
  onCapacityChange: (capacity: number) => void;
  options?: DeckCapacityOptions;
}

export function useDeckCardCapacity({
  cardsViewportRef,
  measureCardIds,
  setFlipRef,
  onCapacityChange,
  options = {},
}: UseDeckCardCapacityParams): (taskId: string) => (node: HTMLElement | null) => void {
  const cardRefs = useRef<Map<string, HTMLElement>>(new Map());
  const measureCardIdsRef = useRef(measureCardIds);
  const onCapacityChangeRef = useRef(onCapacityChange);
  const lastReportedRef = useRef<number | null>(null);
  const measureRef = useRef<(() => void) | null>(null);

  measureCardIdsRef.current = measureCardIds;
  onCapacityChangeRef.current = onCapacityChange;

  const min = options.min ?? DECK_MIN_VISIBLE_INTENTS;
  const max = options.max;
  const fallback = options.fallback ?? DECK_DEFAULT_VISIBLE_INTENTS;
  const estimatedCardHeightPx =
    options.estimatedCardHeightPx ?? DECK_ESTIMATED_CARD_HEIGHT_PX;

  const setCardRef = useCallback(
    (taskId: string) => (node: HTMLElement | null) => {
      setFlipRef(taskId)(node);
      if (node) {
        cardRefs.current.set(taskId, node);
      } else {
        cardRefs.current.delete(taskId);
      }
    },
    [setFlipRef],
  );

  const measureOptions: DeckCapacityOptions = {
    min,
    max,
    fallback,
    estimatedCardHeightPx,
  };

  const reportCapacity = useCallback((next: number) => {
    if (lastReportedRef.current === next) return;
    lastReportedRef.current = next;
    onCapacityChangeRef.current(next);
  }, []);

  useLayoutEffect(() => {
    const container = cardsViewportRef.current;
    if (!container) return;

    const measure = () => {
      const heights = measureCardIdsRef.current
        .map((id) => cardRefs.current.get(id)?.offsetHeight)
        .filter((height): height is number => height != null && height > 0);

      const next = computeDeckVisibleCapacity(
        container.clientHeight,
        heights,
        measureOptions,
      );
      reportCapacity(next);
    };

    measureRef.current = measure;
    measure();

    const observer = new ResizeObserver(measure);
    observer.observe(container);

    const remeasureTimeout = setTimeout(
      measure,
      FEED_INSERT_DURATION_MS + 100,
    );

    return () => {
      observer.disconnect();
      clearTimeout(remeasureTimeout);
      measureRef.current = null;
    };
  }, [
    cardsViewportRef,
    min,
    max,
    fallback,
    estimatedCardHeightPx,
    reportCapacity,
  ]);

  const measureCardIdsKey = measureCardIds.join("\0");
  useLayoutEffect(() => {
    measureRef.current?.();
  }, [measureCardIdsKey]);

  return setCardRef;
}
