import type { DeepPartial, ChartOptions } from "lightweight-charts";
import { CrosshairMode, LineType } from "lightweight-charts";

import { TERMINAL_COLORS } from "../../constants/terminalColors";

const sharedChartLayout = {
  autoSize: true,
  layout: {
    background: { color: "transparent" },
    textColor: TERMINAL_COLORS.textSecondary,
    fontFamily:
      'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  grid: {
    vertLines: { visible: false },
    horzLines: { color: TERMINAL_COLORS.gridMajor },
  },
  crosshair: {
    mode: CrosshairMode.Normal,
    vertLine: {
      color: TERMINAL_COLORS.muted,
      width: 1,
      style: 3,
    },
    horzLine: {
      color: TERMINAL_COLORS.muted,
      width: 1,
      style: 3,
    },
  },
  timeScale: {
    visible: true,
    borderVisible: true,
    borderColor: TERMINAL_COLORS.panelStrong,
    timeVisible: true,
    secondsVisible: false,
    ticksVisible: true,
    minimumHeight: 18,
  },
} satisfies DeepPartial<ChartOptions>;

export function createAgentCompareMainChartOptions(): DeepPartial<ChartOptions> {
  return {
    ...sharedChartLayout,
    rightPriceScale: {
      borderColor: TERMINAL_COLORS.panelStrong,
      visible: true,
      scaleMargins: { top: 0.08, bottom: 0.28 },
    },
    leftPriceScale: { visible: false },
    handleScroll: {
      mouseWheel: true,
      pressedMouseMove: true,
      horzTouchDrag: true,
      vertTouchDrag: false,
    },
    handleScale: {
      axisPressedMouseMove: true,
      mouseWheel: true,
      pinch: true,
    },
  };
}

export function createAgentCompareBrushChartOptions(): DeepPartial<ChartOptions> {
  return {
    ...sharedChartLayout,
    rightPriceScale: { visible: false },
    leftPriceScale: { visible: false },
    timeScale: {
      ...sharedChartLayout.timeScale,
      visible: false,
      minimumHeight: 0,
    },
    crosshair: { mode: CrosshairMode.Hidden },
    handleScroll: false,
    handleScale: false,
  };
}

export function agentCompareLineSeriesOptions(color: string, faded = false) {
  return {
    color: faded ? `${color}59` : color,
    lineWidth: faded ? 1 : 2,
    lineType: LineType.Simple,
    crosshairMarkerVisible: !faded,
    crosshairMarkerRadius: 4,
    crosshairMarkerBorderColor: color,
    crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
    priceScaleId: "right" as const,
  };
}
