import React from "react";
import {
  PORTFOLIO_HERO_VIEWS,
  type PortfolioHeroView,
} from "./portfolioHeroView";
import "./portfolio.css";

export interface PortfolioHeroViewNavProps {
  activeView: PortfolioHeroView;
  onViewChange: (view: PortfolioHeroView) => void;
}

function PortfolioHeroViewNav({
  activeView,
  onViewChange,
}: PortfolioHeroViewNavProps): JSX.Element {
  return (
    <nav
      className="portfolio-hero-view-nav markets-tabs"
      aria-label="Portfolio view"
      role="tablist"
    >
      {PORTFOLIO_HERO_VIEWS.map((view) => (
        <button
          key={view.id}
          type="button"
          role="tab"
          aria-selected={activeView === view.id}
          className={activeView === view.id ? "active" : ""}
          onClick={() => onViewChange(view.id)}
        >
          {view.label}
        </button>
      ))}
    </nav>
  );
}

export default React.memo(PortfolioHeroViewNav);
