import React from "react";
import { formatCurrency } from "../../sdk/utils/display";
import { autonomyBadgeCopy, type AutonomyPolicy } from "../tradeagent/autonomyPolicy";
import { NestedConfirmDialog } from "../ui/NestedConfirmDialog";

export interface BucketAutonomyConfirmModalProps {
  isOpen: boolean;
  draft: AutonomyPolicy;
  withdrawable: number;
  autoExecuteCount: number;
  totalIntentCount: number;
  onCancel: () => void;
  onConfirm: () => void;
  disabled?: boolean;
}

function BucketAutonomyConfirmModal({
  isOpen,
  draft,
  withdrawable,
  autoExecuteCount,
  totalIntentCount,
  onCancel,
  onConfirm,
  disabled = false,
}: BucketAutonomyConfirmModalProps): JSX.Element | null {
  const badge = autonomyBadgeCopy(draft);
  const presetUpper = draft.preset === "highAgency" ? "HIGH-AGENCY" : draft.preset.toUpperCase();

  return (
    <NestedConfirmDialog
      isOpen={isOpen}
      title="Confirm: let agents trade more on their own?"
      titleId="bucket-autonomy-confirm-title"
      confirmLabel="Yes, enable"
      onCancel={onCancel}
      onConfirm={onConfirm}
      disabled={disabled}
    >
      <p className="nested-confirm-body">
        You&apos;re switching this bucket to <strong>{presetUpper}</strong>.
        {draft.preset === "highAgency"
          ? " Agents will be able to open and close positions without asking you,"
          : " Agents will have more freedom to act on their own,"}{" "}
        using up to {formatCurrency(withdrawable)} withdrawable + margin in this
        bucket.
      </p>
      <p className="nested-confirm-body">
        {badge.headline}. Right now, {autoExecuteCount} of {totalIntentCount}{" "}
        intents would auto-execute under these rules.
      </p>
    </NestedConfirmDialog>
  );
}

export default React.memo(BucketAutonomyConfirmModal);
