import React from "react";
import type { TickerCategory } from "./types";

interface TickerSelectionToolbarProps {
  category: TickerCategory;
  onCategoryChange: (category: TickerCategory) => void;
  search: string;
  onSearchChange: (value: string) => void;
  isMobile?: boolean;
  searchInputRef?: React.RefObject<HTMLInputElement | null>;
}

const TABS: { id: TickerCategory; label: string; showBeta?: boolean }[] = [
  { id: "all", label: "All Markets" },
  { id: "agent", label: "Agents (AI)" },
  { id: "index", label: "Indices" },
  { id: "crypto", label: "Crypto" },
  { id: "tradfi", label: "TradFi", showBeta: true },
];

export function TickerSelectionToolbar({
  category,
  onCategoryChange,
  search,
  onSearchChange,
  isMobile = false,
  searchInputRef,
}: TickerSelectionToolbarProps): JSX.Element {
  return (
    <div
      className={`ticker-selection-toolbar ${isMobile ? "ticker-selection-toolbar--mobile" : ""}`}
    >
      <div className="ticker-selection-tabs">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            type="button"
            className={`ticker-selection-tab ${category === tab.id ? "active" : ""}`}
            onClick={() => onCategoryChange(tab.id)}
          >
            {tab.label}
            {tab.showBeta ? (
              <span className="ticker-selection-beta-pill">Beta</span>
            ) : null}
          </button>
        ))}
      </div>
      <div className="terminal-search-field ticker-selection-search">
        <span className="ticker-selection-search-icon" aria-hidden>
          ⌕
        </span>
        <input
          ref={searchInputRef}
          type="search"
          className="terminal-search-input"
          placeholder="Search"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
          aria-label="Search assets"
        />
      </div>
    </div>
  );
}
