import React, { useMemo } from "react";
import { useNavigate } from "react-router-dom";

import type {
  PropertyIndexMode,
  PropertyIndexProfile,
} from "../../../offline/mock_data/types";
import { APP_ROUTES } from "../../routes";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./index.css";

export interface IndexModeTabSectionProps {
  height?: string;
  profile: PropertyIndexProfile;
  activeMode: PropertyIndexMode["id"];
  onModeChange: (mode: PropertyIndexMode["id"]) => void;
}

function IndexModeTabSection({
  height = "100%",
  profile,
  activeMode,
  onModeChange,
}: IndexModeTabSectionProps): JSX.Element {
  const navigate = useNavigate();

  const tabs = useMemo(
    () =>
      profile.modes.map((mode) => ({
        id: mode.id,
        label: mode.label,
      })),
    [profile.modes],
  );

  const activeModeMeta = useMemo(
    () => profile.modes.find((mode) => mode.id === activeMode),
    [profile.modes, activeMode],
  );

  return (
    <div
      id="index-modes"
      className="index-slot index-mode-tab-section"
      style={{ height }}
      aria-label={`${profile.name} index modes`}
    >
      <div className="layout-container tab-section-root index-mode-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={activeMode}
          onTabChange={(id) => onModeChange(id as PropertyIndexMode["id"])}
        />
        <div className="tab-section-content">
          {activeModeMeta ? (
            <div className="index-mode-tab-body">
              <p className="index-mode-tab-description">
                {activeModeMeta.description}
              </p>

              <dl className="index-mode-tab-kv">
                <div className="index-mode-tab-kv-row">
                  <dt className="terminal-label">Constituents</dt>
                  <dd className="terminal-value">
                    {activeModeMeta.constituentIds.length}
                  </dd>
                </div>
                <div className="index-mode-tab-kv-row">
                  <dt className="terminal-label">Weighting</dt>
                  <dd className="terminal-value">
                    {activeModeMeta.weightingMethod}
                  </dd>
                </div>
                <div className="index-mode-tab-kv-row">
                  <dt className="terminal-label">Rebalance</dt>
                  <dd className="terminal-value">
                    {activeModeMeta.rebalanceFrequency}
                  </dd>
                </div>
                <div className="index-mode-tab-kv-row">
                  <dt className="terminal-label">Cap structure</dt>
                  <dd className="terminal-value">
                    {activeModeMeta.capStructure}
                  </dd>
                </div>
              </dl>

              <div className="index-mode-tab-schedule">
                <span className="terminal-label">Rebalance schedule</span>
                <strong>{profile.schedule.rebalanceWindow}</strong>
                <small>{profile.schedule.proofOfReserves}</small>
              </div>

              <div className="index-mode-tab-actions">
                <button
                  type="button"
                  className="index-secondary-btn"
                  onClick={() => navigate(APP_ROUTES.trade)}
                >
                  Trade index perp
                </button>
                {profile.docsUrl ? (
                  <a
                    href={profile.docsUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="index-overview-link"
                  >
                    Methodology docs
                  </a>
                ) : (
                  <span className="index-overview-link index-overview-link--muted">
                    Methodology docs
                  </span>
                )}
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default IndexModeTabSection;
