import React from "react";
import { createPortal } from "react-dom";
import { useMarkets } from "../../hooks/useMarkets";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { shortHashId } from "../../utils/hashId";
import type { AgentTask, AgentTaskStatus } from "../../store/types";
import AgentTaskTimeline from "./AgentTaskTimeline";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./agentTasks.css";
import "./bucketCollection.css";

interface AgentTaskDetailModalProps {
  isOpen: boolean;
  task: AgentTask | null;
  baseURL: string;
  authToken?: string;
  onClose: () => void;
}

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function getStatusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

function statusPillClassName(tone: string): string {
  return `agent-task-status-pill agent-task-status-pill--${tone}`;
}

function AgentTaskDetailModal({
  isOpen,
  task,
  baseURL,
  authToken,
  onClose,
}: AgentTaskDetailModalProps): JSX.Element | null {
  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });

  const overlayOpen = isOpen && Boolean(task);
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(overlayOpen);

  useOverlayEscapeKey(overlayOpen, onClose);

  if (!mounted || !task) return null;

  const statusCfg = getStatusConfig(task.status);
  const symbol = task.marketId
    ? getSymbolByMarketId(task.marketId) || `m-${task.marketId}`
    : "—";
  const history = task.statusHistory ?? [];

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content bucket-agents-modal-content agent-task-detail-modal-content staggered-overlay-panel--scale terminal-overlay-panel-shell"
        aria-label="Agent task detail"
      >
        <div className="modal-header">
          <div className="agent-task-detail-modal-header">
            <h3 className="terminal-panel-title">Agent task</h3>
            <span
              className="task-id-chip"
              title={task.id}
              aria-label={`Task ${shortHashId(task.id)}`}
            >
              {shortHashId(task.id)}
            </span>
            <span className={statusPillClassName(statusCfg.tone)}>
              {statusCfg.label}
            </span>
          </div>
        </div>
        <div className="modal-body bucket-agents-modal-body">
          <div className="agent-task-detail-modal-description">
            {task.description}
          </div>
          <div className="agent-task-detail-modal-meta">
            <div className="agent-task-detail-modal-meta-row">
              <span className="terminal-label">Market</span>
              <span className="terminal-value">{symbol}</span>
            </div>
            <div className="agent-task-detail-modal-meta-row">
              <span className="terminal-label">Bucket</span>
              <span className="terminal-value">
                {task.bucketId ? shortHashId(task.bucketId) : "—"}
              </span>
            </div>
            <div className="agent-task-detail-modal-meta-row">
              <span className="terminal-label">Trigger</span>
              <span className="terminal-value">{task.trigger || "—"}</span>
            </div>
            <div className="agent-task-detail-modal-meta-row">
              <span className="terminal-label">Updated</span>
              <span className="terminal-value">
                {formatDateTime(task.updatedAt)}
              </span>
            </div>
          </div>
          <div className="agent-task-expanded-label">Status timeline</div>
          <AgentTaskTimeline history={history} />
        </div>
        <div className="modal-footer">
          <button type="button" onClick={onClose} className="btn btn-secondary">
            Close
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(AgentTaskDetailModal);
