import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { DEFAULT_BASE_URL } from "../../constants";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import type { AgentTask } from "../../store/types";
import { shortHashId } from "../../utils/hashId";
import { Typewriter } from "../ui/Typewriter";
import { useFeedEnter } from "../tradeops/useFeedEnter";
import { DECK_EXIT_ANIMATION_MS } from "./useDeckTaskListAnimation";
import GuardrailIntentCardExtras from "./GuardrailIntentCardExtras";
import { getTaskReportingMeta } from "./reportTier";
import { riskImpactLabel } from "./guardrailMeta";
import type { AutonomyPolicy } from "./autonomyPolicy";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import SafetyLogReviewSheet from "./SafetyLogReviewSheet";
import "./tradeAgentDeck.css";

export interface ExceptionSpotlightProps {
  task: AgentTask;
  policy: AutonomyPolicy;
  height?: string;
  baseURL?: string;
  queueCount?: number;
  onResolved?: () => void;
  onOpenBucketRules?: (bucketId: string) => void;
}

function formatCountdown(approveBy: string | undefined): string | null {
  if (!approveBy) return null;
  const ms = new Date(approveBy).getTime() - Date.now();
  if (ms <= 0) return "0:00";
  const totalSec = Math.ceil(ms / 1000);
  const min = Math.floor(totalSec / 60);
  const sec = totalSec % 60;
  return `${min}:${sec.toString().padStart(2, "0")}`;
}

function isGateableTask(task: AgentTask): boolean {
  return task.status === "pending" || task.status === "watching";
}

function ExceptionSpotlight({
  task,
  policy,
  height,
  baseURL = DEFAULT_BASE_URL,
  queueCount = 0,
  onResolved,
  onOpenBucketRules,
}: ExceptionSpotlightProps): JSX.Element {
  const { forceExecute, rejectTask } = useAgentTasks();
  const { getAgentById } = useTradingAgents();
  const { enterState, markEntering } = useFeedEnter();
  const [reviewOpen, setReviewOpen] = useState(false);
  const [sizePct, setSizePct] = useState(100);
  const [isExiting, setIsExiting] = useState(false);
  const pendingResolveRef = useRef<
    { kind: "approve"; taskId: string; sizePct: number } | { kind: "reject"; taskId: string } | null
  >(null);

  const meta = useMemo(
    () => getTaskReportingMeta(task, policy),
    [task, policy],
  );
  const agent = getAgentById(task.agentId);
  const agentLabel = agent?.displayName ?? shortHashId(task.agentId);
  const isT4 = meta.reportTier === "T4";
  const gateable = isGateableTask(task);
  const countdown = formatCountdown(meta.approveBy);
  const intentText = task.trigger || task.description;
  const hasQueue = queueCount > 0;

  const isPushing =
    enterState?.instanceId === task.id && enterState.phase === "push";
  const isRevealing =
    enterState?.instanceId === task.id && enterState.phase === "reveal";

  useLayoutEffect(() => {
    markEntering(task.id);
  }, [task.id, markEntering]);

  const resolveWithExit = useCallback(
    (taskId: string, approvedSizePct?: number) => {
      pendingResolveRef.current =
        approvedSizePct != null
          ? { kind: "approve", taskId, sizePct: approvedSizePct }
          : { kind: "reject", taskId };
      setIsExiting(true);
    },
    [],
  );

  const handleApprove = useCallback(
    (taskId: string, approvedSizePct: number) => {
      resolveWithExit(taskId, approvedSizePct);
    },
    [resolveWithExit],
  );

  const handleReject = useCallback(
    (taskId: string) => {
      resolveWithExit(taskId);
    },
    [resolveWithExit],
  );

  const flushPendingResolve = useCallback(() => {
    const pending = pendingResolveRef.current;
    if (!pending) return;
    pendingResolveRef.current = null;
    if (pending.kind === "approve") {
      forceExecute(pending.taskId, { sizePct: pending.sizePct });
    } else {
      rejectTask(pending.taskId);
    }
    onResolved?.();
  }, [forceExecute, rejectTask, onResolved]);

  const handleExitAnimationEnd = useCallback(
    (event: React.AnimationEvent<HTMLDivElement>) => {
      if (event.animationName !== "agentIntentCardExit") return;
      flushPendingResolve();
    },
    [flushPendingResolve],
  );

  useEffect(() => {
    if (!isExiting) return;
    const timer = setTimeout(flushPendingResolve, DECK_EXIT_ANIMATION_MS + 50);
    return () => clearTimeout(timer);
  }, [isExiting, flushPendingResolve]);

  const openReview = useCallback(() => setReviewOpen(true), []);
  const closeReview = useCallback(() => setReviewOpen(false), []);

  return (
    <>
      <div
        className={[
          "exception-spotlight",
          isT4 ? "exception-spotlight--incident" : "",
          hasQueue ? "exception-spotlight--has-queue" : "",
          isPushing ? "is-push" : "",
          isRevealing ? "is-reveal" : "",
          isExiting ? "is-exiting" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        style={{ height, minHeight: 0 }}
        data-report-tier={meta.reportTier}
        onAnimationEnd={isExiting ? handleExitAnimationEnd : undefined}
      >
        <div className="exception-spotlight-inner">
          <div className="exception-spotlight-head">
            <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightTier}>
              <span className="exception-spotlight-tier">
                {isT4 ? "⛔ Incident" : "🔶 Needs approval"}
              </span>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightAgent}>
              <span className="exception-spotlight-agent">{agentLabel}</span>
            </BubbleTip>
            {hasQueue ? (
              <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightQueue}>
                <span className="exception-spotlight-queue-count">
                  +{queueCount} more in queue
                </span>
              </BubbleTip>
            ) : null}
            {countdown ? (
              <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightTimer}>
                <span
                  className="exception-spotlight-timer"
                  aria-label="Approval deadline"
                >
                  {countdown} ⏱
                </span>
              </BubbleTip>
            ) : null}
          </div>
          <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightIntent}>
            <span className="exception-spotlight-intent-wrap">
              <Typewriter
                text={intentText}
                className="exception-spotlight-intent"
                multiline="auto"
                active={!isPushing && !isExiting}
              />
            </span>
          </BubbleTip>
          <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightReason}>
            <span className="exception-spotlight-reason-wrap">
              <Typewriter
                text={meta.tierReason}
                className="exception-spotlight-reason"
                multiline="auto"
                active={!isPushing && !isExiting}
              />
            </span>
          </BubbleTip>
          <div className="exception-spotlight-meta">
            <BubbleTip id={BUBBLE_TIP_IDS.gateIntentRiskImpact} group="ExceptionSpotlight">
              <span>{riskImpactLabel(meta.riskImpact)} risk</span>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.gateIntentConfidence} group="ExceptionSpotlight">
              <span>{meta.confidencePct}% conf</span>
            </BubbleTip>
            <BubbleTip id={BUBBLE_TIP_IDS.gateIntentSlippage} group="ExceptionSpotlight">
              <span>+{meta.expectedFillImpactBps.toFixed(1)} bps est.</span>
            </BubbleTip>
          </div>
          {gateable ? (
            <>
              <GuardrailIntentCardExtras
                task={task}
                onApprove={handleApprove}
                onReject={handleReject}
                tooltipGroup="ExceptionSpotlight"
              />
              <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightReview}>
                <button
                  type="button"
                  className="exception-spotlight-review-link"
                  onClick={openReview}
                >
                  Full review…
                </button>
              </BubbleTip>
              {task.bucketId && onOpenBucketRules ? (
                <button
                  type="button"
                  className="exception-spotlight-review-link"
                  onClick={() => onOpenBucketRules(task.bucketId!)}
                >
                  Bucket rules
                </button>
              ) : null}
            </>
          ) : (
            <div className="exception-spotlight-actions">
              <BubbleTip id={BUBBLE_TIP_IDS.exceptionSpotlightReview}>
                <button
                  type="button"
                  className="trade-agent-deck-btn"
                  onClick={openReview}
                >
                  View incident
                </button>
              </BubbleTip>
            </div>
          )}
        </div>
      </div>
      <SafetyLogReviewSheet
        isOpen={reviewOpen}
        task={task}
        agentLabel={agentLabel}
        sizePct={sizePct}
        baseURL={baseURL}
        reviewKind={isT4 ? "incident" : "intent"}
        showActions={gateable}
        onSizePctChange={setSizePct}
        onApprove={() => {
          handleApprove(task.id, sizePct);
          closeReview();
        }}
        onReject={() => {
          handleReject(task.id);
          closeReview();
        }}
        onClose={closeReview}
      />
    </>
  );
}

export default React.memo(ExceptionSpotlight);
