import { appendCopyMirrorFill } from "../../offline/mock_data/copyMirrorState";
import {
  getStoredReplayLeaderEvent,
  getStoredReplayRelationId,
} from "../../offline/mock_data/copyMirrorReplay";
import { useAgentTaskStore } from "../store/agentTaskStore";
import { useFleetCopyStore } from "../store/fleetCopyStore";
import { useTradingAgentStore } from "../store/tradingAgentStore";

function nowIso(): string {
  return new Date().toISOString();
}

export function executeCopyMirrorFill(taskId: string): boolean {
  const task = useAgentTaskStore.getState().tasks.find((entry) => entry.id === taskId);
  if (!task?.leaderTradeId || !task.copyRelationId || !task.bucketId) {
    return false;
  }

  const leaderEvent = getStoredReplayLeaderEvent(task.leaderTradeId);
  if (!leaderEvent) {
    return false;
  }

  const relation = useFleetCopyStore
    .getState()
    .relations.find((entry) => entry.id === task.copyRelationId);
  const relationIdFromStore = getStoredReplayRelationId(task.leaderTradeId);
  if (!relation || relationIdFromStore !== relation.id) {
    return false;
  }

  const fill = appendCopyMirrorFill({
    wallet: relation.copierWallet,
    bucketId: task.bucketId,
    copyRelationId: relation.id,
    copySizePct: relation.copySettings.copySizePct,
    leaderEvent,
    taskId: task.id,
  });

  if (!fill) {
    return false;
  }

  useTradingAgentStore
    .getState()
    .appendMemoryNote(
      task.agentId,
      `Mirror fill recorded · ${fill.dir} · ${fill.coin} · PnL ${fill.closedPnl >= 0 ? "+" : ""}${fill.closedPnl.toFixed(2)}.`,
    );

  useAgentTaskStore.getState().updateTask(task.id, {
    status: "completed",
    statusHistory: [
      ...task.statusHistory,
      {
        status: "completed",
        at: nowIso(),
        note: "Mirror fill recorded.",
      },
    ],
  });

  return true;
}
