import { toBinanceInterval } from "../../sdk/api/binance/klineUtil";
import { intervalToSeconds } from "./chartMarkers";

export const CHART_INTERVAL_SCALE = [
  "5m",
  "15m",
  "30m",
  "1h",
  "2h",
  "4h",
  "6h",
  "8h",
  "12h",
  "1d",
  "3d",
  "1w",
] as const;

export type ChartIntervalScaleValue = (typeof CHART_INTERVAL_SCALE)[number];

/** Minimum candle interval for token taker avatar markers on the chart. */
export const TOKEN_TAKER_MARKER_MIN_INTERVAL = "4h" as const;

/**
 * Hide canvas markers when the visible logical span exceeds this bar count.
 * Cuts layout k on heavy zoom-out (e.g. full month @ 4h ≈ 180 bars) without
 * affecting table rows or pinned/hover bubbles.
 */
export const TOKEN_TAKER_MARKER_MAX_VISIBLE_BARS = 120;

/** Live-edge seed zoom so default viewport stays inside the marker budget. */
export const TOKEN_TAKER_MARKER_SEED_VISIBLE_BARS = 100;

export function visibleLogicalBarSpan(range: { from: number; to: number }): number {
  return Math.max(0, Math.ceil(range.to) - Math.floor(range.from));
}

export function isWithinTokenTakerMarkerVisibleBarBudget(
  range: { from: number; to: number } | null,
  maxBars: number = TOKEN_TAKER_MARKER_MAX_VISIBLE_BARS,
): boolean {
  if (range == null) return true;
  return visibleLogicalBarSpan(range) <= maxBars;
}

function resolveScaleIndex(interval: string): number {
  const normalized = toBinanceInterval(interval);
  const exactIndex = CHART_INTERVAL_SCALE.indexOf(normalized as ChartIntervalScaleValue);
  if (exactIndex >= 0) return exactIndex;

  const targetSec = intervalToSeconds(normalized);
  let nearestIndex = 0;
  let nearestDelta = Number.POSITIVE_INFINITY;
  for (let i = 0; i < CHART_INTERVAL_SCALE.length; i += 1) {
    const delta = Math.abs(intervalToSeconds(CHART_INTERVAL_SCALE[i]!) - targetSec);
    if (delta < nearestDelta) {
      nearestDelta = delta;
      nearestIndex = i;
    }
  }
  return nearestIndex;
}

/** direction 1 = coarser (longer candles), -1 = finer (shorter candles) */
export function stepChartInterval(interval: string, direction: 1 | -1): string | null {
  const index = resolveScaleIndex(interval);
  const nextIndex = index + direction;
  if (nextIndex < 0 || nextIndex >= CHART_INTERVAL_SCALE.length) return null;
  return CHART_INTERVAL_SCALE[nextIndex]!;
}

export function canStepChartInterval(interval: string, direction: 1 | -1): boolean {
  return stepChartInterval(interval, direction) != null;
}

export function isChartIntervalAtLeast(
  interval: string,
  minInterval: ChartIntervalScaleValue,
): boolean {
  return resolveScaleIndex(interval) >= resolveScaleIndex(minInterval);
}
