import React, { useState, useRef, useEffect } from "react";
import "./layout.css";

export interface SliderConfirmBarProps {
  onConfirm: () => void;
  label?: string;
  confirmThreshold?: number; // Percentage (0-100) to trigger confirmation, default 90
  disabled?: boolean;
  icon?: React.ReactNode; // Icon to render on the thumb button
}

/**
 * Slider confirm bar - drag to the right end to confirm
 */
export function SliderConfirmBar({
  onConfirm,
  label = "Slide to confirm",
  confirmThreshold = 90,
  disabled = false,
  icon,
}: SliderConfirmBarProps): JSX.Element {
  const [dragProgress, setDragProgress] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (disabled) return;
    e.preventDefault();
    setIsDragging(true);
  };

  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (!sliderRef.current || disabled) return;

      const rect = sliderRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const maxX = rect.width;
      const progress = Math.max(0, Math.min(100, (x / maxX) * 100));

      setDragProgress(progress);
    };

    const handleMouseUp = () => {
      if (disabled) return;

      if (dragProgress >= confirmThreshold) {
        onConfirm();
        // Reset after a brief delay to show completion
        setTimeout(() => {
          setDragProgress(0);
        }, 200);
      } else {
        // Reset if not confirmed
        setDragProgress(0);
      }
      setIsDragging(false);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDragging, dragProgress, confirmThreshold, onConfirm, disabled]);

  const isConfirmed = dragProgress >= confirmThreshold;

  return (
    <div
      ref={sliderRef}
      className={`slider-confirm-bar ${disabled ? "disabled" : ""} ${isDragging ? "dragging" : ""}`}
    >
      {/* Progress fill */}
      <div
        className={`slider-confirm-bar-progress ${isConfirmed ? "confirmed" : "default"} ${isDragging ? "no-transition" : ""}`}
        style={{
          width: `${dragProgress}%`,
        }}
      />
      {/* Label */}
      <div className="slider-confirm-bar-label">
        {isConfirmed ? "Release to confirm" : label}
      </div>
      {/* Draggable thumb */}
      <div
        ref={thumbRef}
        onMouseDown={handleMouseDown}
        className={`slider-confirm-bar-thumb ${disabled ? "disabled" : ""} ${isDragging ? "dragging" : ""} ${isConfirmed ? "confirmed" : ""}`}
        style={{
          left: `${dragProgress}%`,
        }}
      >
        {icon ? (
          <span className={`slider-confirm-bar-thumb-icon ${isConfirmed ? "confirmed" : ""}`}>
            {icon}
          </span>
        ) : (
          <span className={`slider-confirm-bar-thumb-arrow ${isConfirmed ? "confirmed" : ""}`}>
            →
          </span>
        )}
      </div>
    </div>
  );
}
