import { useEffect, useState } from "react";

import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import {
  FLEET_TRADE_HISTORY_DATA_BASE_URL,
  fetchFleetTradesForAgents,
} from "../sdk/api/fleetTradeHistory/fleetTradeHistoryClient";

export interface UseFleetTradesForAgentsResult {
  tradesByAgentId: Map<string, FleetTradeEvent[]>;
  loading: boolean;
  error: string | null;
}

export function useFleetTradesForAgents(
  catalogAgentIds: readonly string[],
  baseUrl: string = FLEET_TRADE_HISTORY_DATA_BASE_URL,
): UseFleetTradesForAgentsResult {
  const [tradesByAgentId, setTradesByAgentId] = useState<Map<string, FleetTradeEvent[]>>(
    () => new Map(),
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const idsKey = catalogAgentIds.join(",");

  useEffect(() => {
    const ids = catalogAgentIds.map((id) => id.trim()).filter(Boolean);
    if (ids.length === 0) {
      setTradesByAgentId(new Map());
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchFleetTradesForAgents(ids, baseUrl)
      .then((map) => {
        if (cancelled) return;
        setTradesByAgentId(map);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load fleet trade history",
        );
        setTradesByAgentId(new Map());
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [idsKey, baseUrl]);

  return { tradesByAgentId, loading, error };
}
