import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";

import { DEFAULT_SKILL_MD_TEMPLATE } from "./agentSettingsCatalog";
import type { SkillFile, SkillFileKind } from "./agentSettingsTypes";
import { isValidCreateSkillDraft } from "./agentSettingsValidation";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./agent.css";
import "./agentSettings.css";

export interface CreateSkillModalProps {
  open: boolean;
  onClose: () => void;
  onCreate: (files: SkillFile[]) => boolean;
}

type EditorMode = "edit" | "preview";
type SidebarAddKind = "reference" | "resource" | null;

function CloseIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M18 6L6 18M6 6l12 12" />
    </svg>
  );
}

function initialFiles(): SkillFile[] {
  return [
    {
      path: "SKILL.md",
      kind: "skill",
      content: DEFAULT_SKILL_MD_TEMPLATE,
    },
  ];
}

function fileKindFromPath(path: string): SkillFileKind {
  if (path === "SKILL.md") return "skill";
  if (path.startsWith("references/")) return "reference";
  return "resource";
}

function CreateSkillModal({
  open,
  onClose,
  onCreate,
}: CreateSkillModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(open);

  useOverlayEscapeKey(open, onClose);

  const [files, setFiles] = useState<SkillFile[]>(initialFiles);
  const [selectedPath, setSelectedPath] = useState("SKILL.md");
  const [editorMode, setEditorMode] = useState<EditorMode>("edit");
  const [sidebarAddKind, setSidebarAddKind] = useState<SidebarAddKind>(null);
  const [sidebarAddPath, setSidebarAddPath] = useState("");

  useEffect(() => {
    if (!open) return;
    setFiles(initialFiles());
    setSelectedPath("SKILL.md");
    setEditorMode("edit");
    setSidebarAddKind(null);
    setSidebarAddPath("");
  }, [open]);

  const selectedFile = useMemo(
    () => files.find((file) => file.path === selectedPath) ?? files[0],
    [files, selectedPath],
  );

  const referenceCount = files.filter((file) => file.kind === "reference").length;

  const canCreate = isValidCreateSkillDraft(files);

  const updateSelectedContent = useCallback(
    (content: string) => {
      setFiles((prev) =>
        prev.map((file) =>
          file.path === selectedPath ? { ...file, content } : file,
        ),
      );
    },
    [selectedPath],
  );

  const handleAddFile = useCallback(() => {
    if (!sidebarAddKind) return;
    const trimmed = sidebarAddPath.trim();
    if (!trimmed) return;
    const prefix = sidebarAddKind === "reference" ? "references/" : "resources/";
    const path = trimmed.includes("/") ? trimmed : `${prefix}${trimmed}`;
    if (files.some((file) => file.path === path)) return;
    setFiles((prev) => [
      ...prev,
      {
        path,
        kind: fileKindFromPath(path),
        content:
          sidebarAddKind === "reference"
            ? `# ${trimmed.replace(/\.md$/, "")}\n\nReference content for the agent.\n`
            : "",
      },
    ]);
    setSelectedPath(path);
    setSidebarAddKind(null);
    setSidebarAddPath("");
    setEditorMode("edit");
  }, [files, sidebarAddKind, sidebarAddPath]);

  const handleCreate = useCallback(() => {
    if (!canCreate) return;
    onCreate(files.map((file) => ({ ...file })));
  }, [canCreate, files, onCreate]);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="agent-settings-nested-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content agent-settings-create-skill-content staggered-overlay-panel--scale"
        aria-label="Create Skill"
      >
        <div className="modal-header agent-settings-modal-header">
          <div>
            <h3 className="terminal-panel-title">Create Skill</h3>
            <p className="agent-settings-section-desc">
              SKILL.md, references, and resource files
            </p>
          </div>
          <button
            type="button"
            className="agent-settings-modal-close"
            onClick={onClose}
            aria-label="Close"
          >
            <CloseIcon />
          </button>
        </div>

        <div className="agent-settings-create-skill-layout">
          <aside className="agent-settings-create-skill-sidebar">
            <p className="agent-settings-create-skill-sidebar-label">Files</p>
            <ul className="agent-settings-file-list">
              {files.map((file) => (
                <li key={file.path}>
                  <button
                    type="button"
                    className={`agent-settings-file-btn${
                      selectedPath === file.path ? " is-active" : ""
                    }`}
                    onClick={() => {
                      setSelectedPath(file.path);
                      setEditorMode("edit");
                    }}
                  >
                    {file.path}
                  </button>
                </li>
              ))}
            </ul>

            <div className="agent-settings-sidebar-add">
              <p className="agent-settings-create-skill-sidebar-label">References/</p>
              {sidebarAddKind === "reference" ? (
                <div className="agent-settings-sidebar-add-form">
                  <input
                    type="text"
                    className="form-input transfer-select transfer-input"
                    placeholder="filename.md"
                    value={sidebarAddPath}
                    onChange={(e) => setSidebarAddPath(e.target.value)}
                  />
                  <div className="agent-settings-sidebar-add-actions">
                    <button
                      type="button"
                      className="agent-secondary-btn agent-secondary-btn--primary"
                      onClick={handleAddFile}
                    >
                      Add
                    </button>
                    <button
                      type="button"
                      className="agent-secondary-btn"
                      onClick={() => {
                        setSidebarAddKind(null);
                        setSidebarAddPath("");
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  className="agent-settings-sidebar-link"
                  onClick={() => {
                    setSidebarAddKind("reference");
                    setSidebarAddPath("");
                  }}
                >
                  + Add reference
                </button>
              )}
            </div>

            <div className="agent-settings-sidebar-add">
              <p className="agent-settings-create-skill-sidebar-label">Resources/</p>
              {sidebarAddKind === "resource" ? (
                <div className="agent-settings-sidebar-add-form">
                  <input
                    type="text"
                    className="form-input transfer-select transfer-input"
                    placeholder="scripts/helper.sh"
                    value={sidebarAddPath}
                    onChange={(e) => setSidebarAddPath(e.target.value)}
                  />
                  <div className="agent-settings-sidebar-add-actions">
                    <button
                      type="button"
                      className="agent-secondary-btn agent-secondary-btn--primary"
                      onClick={handleAddFile}
                    >
                      Add
                    </button>
                    <button
                      type="button"
                      className="agent-secondary-btn"
                      onClick={() => {
                        setSidebarAddKind(null);
                        setSidebarAddPath("");
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  className="agent-settings-sidebar-link"
                  onClick={() => {
                    setSidebarAddKind("resource");
                    setSidebarAddPath("");
                  }}
                >
                  + Add resource
                </button>
              )}
            </div>
          </aside>

          <div className="agent-settings-create-skill-editor">
            <div className="agent-settings-editor-toolbar">
              <span className="agent-settings-editor-filename">
                {selectedFile?.path ?? "SKILL.md"}
              </span>
              {selectedFile?.kind === "skill" ? (
                <div className="agent-settings-editor-mode-toggle">
                  <button
                    type="button"
                    className={`agent-settings-editor-mode-btn${
                      editorMode === "edit" ? " is-active" : ""
                    }`}
                    onClick={() => setEditorMode("edit")}
                  >
                    Edit
                  </button>
                  <button
                    type="button"
                    className={`agent-settings-editor-mode-btn${
                      editorMode === "preview" ? " is-active" : ""
                    }`}
                    onClick={() => setEditorMode("preview")}
                  >
                    Preview
                  </button>
                </div>
              ) : null}
            </div>
            {editorMode === "edit" || selectedFile?.kind !== "skill" ? (
              <textarea
                className="agent-settings-editor-textarea"
                value={selectedFile?.content ?? ""}
                onChange={(e) => updateSelectedContent(e.target.value)}
                spellCheck={false}
              />
            ) : (
              <div className="agent-settings-editor-preview">
                <pre>{selectedFile?.content ?? ""}</pre>
              </div>
            )}
          </div>
        </div>

        <div className="agent-settings-create-skill-footer">
          <span className="agent-settings-create-skill-footer-meta">
            {referenceCount} reference{referenceCount === 1 ? "" : "s"}
          </span>
          <div className="modal-footer" style={{ border: "none", padding: 0 }}>
            <button type="button" className="agent-secondary-btn" onClick={onClose}>
              Cancel
            </button>
            <button
              type="button"
              className="agent-secondary-btn agent-secondary-btn--primary"
              disabled={!canCreate}
              onClick={handleCreate}
            >
              Create
            </button>
          </div>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default CreateSkillModal;
