import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  getLayoutBottomRow,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the multi-slot portfolio layout */
export const PORTFOLIO_SLOT_INDICES = {
  title: 0,
  volume: 1,
  equity: 2,
  charts: 3,
  tabs: 4,
  fees: 5,
} as const;

/** Grid slot index stretched to viewport height */
export const PORTFOLIO_TAB_SLOT_INDEX = PORTFOLIO_SLOT_INDICES.tabs;

/** @deprecated Use PORTFOLIO_SLOT_INDICES.volume */
export const PORTFOLIO_HERO_SLOT_INDEX = PORTFOLIO_SLOT_INDICES.volume;

/** Grid slot for copied-agents strip (above tabs when active) */
export const PORTFOLIO_COPIED_AGENTS_SLOT_INDEX = 6;

/** Row height for copied-agents strip band (~70px at ROW_HEIGHT=30) */
export const PORTFOLIO_COPIED_AGENTS_ROWS = 2;

/** Slots collapsed on all breakpoints (slot 6 opens via patchPortfolioCopiedAgentsStrip) */
export const PORTFOLIO_COLLAPSED_SLOTS = [6, 7, 8] as const;

/** @deprecated Use PORTFOLIO_COLLAPSED_SLOTS */
export const PORTFOLIO_PLACEHOLDER_SLOTS = PORTFOLIO_COLLAPSED_SLOTS;

/** @deprecated Single-slot layout — no mobile-only side panels */
export const PORTFOLIO_MOBILE_HIDDEN_SLOTS = [] as const;

/** Grid row height — must match PortfolioPage ROW_HEIGHT */
export const PORTFOLIO_ROW_HEIGHT = 30;

/** MenuBar height — must match MenuBar.css */
export const PORTFOLIO_MENUBAR_HEIGHT = 54;

/** Horizontal and vertical margin between grid slots (px) */
export const PORTFOLIO_LAYOUT_MARGIN = 10;

/** Small fudge for grid chrome / sub-pixel rounding */
export const PORTFOLIO_VIEWPORT_FUDGE_PX = 4;

/** Title row height */
export const PORTFOLIO_TITLE_ROWS = 2;

/** Hero panel row height (equity / charts band; volume + fees stack to this) */
export const PORTFOLIO_HERO_ROWS = 8;

/** Volume panel rows within the left column (desktop) */
export const PORTFOLIO_VOLUME_ROWS = 5;

/** Fees panel rows within the left column (desktop) */
export const PORTFOLIO_FEES_ROWS = 3;

/** First row of the hero panel band */
export const PORTFOLIO_HERO_START_ROW = PORTFOLIO_TITLE_ROWS;

/** First row of the tab section */
export const PORTFOLIO_TAB_START_ROW =
  PORTFOLIO_HERO_START_ROW + PORTFOLIO_HERO_ROWS;

/** Tab start row when md/sm performance uses metrics|accounts pair + full-width charts */
export const PORTFOLIO_MD_PERFORMANCE_TAB_START_ROW =
  PORTFOLIO_HERO_START_ROW + PORTFOLIO_HERO_ROWS + PORTFOLIO_HERO_ROWS;

/** Tab start row when md/sm overview uses vol|fees + charts band then full-width equity */
export const PORTFOLIO_OVERVIEW_PAIRED_TAB_START_ROW =
  PORTFOLIO_MD_PERFORMANCE_TAB_START_ROW;

/** Base tab section height before viewport stretch */
export const PORTFOLIO_BASE_TAB_ROWS = 3;

/** Fixed tab section height on md/sm/xs/xxs — page scrolls instead of viewport squeeze */
export const PORTFOLIO_SCROLL_TAB_ROWS = 26;

/** Default bottom row when viewport fit is not applied */
export const PORTFOLIO_DEFAULT_BOTTOM_ROW =
  PORTFOLIO_TAB_START_ROW + PORTFOLIO_BASE_TAB_ROWS;

/** Max bottom row (~1080p minus MenuBar) */
export const PORTFOLIO_MAX_BOTTOM_ROW = 33;

/** Min bottom row before the tab section would become unusably small */
export const PORTFOLIO_MIN_BOTTOM_ROW = PORTFOLIO_DEFAULT_BOTTOM_ROW;

/** @deprecated Use PORTFOLIO_HERO_ROWS */
export const PORTFOLIO_BASE_HERO_ROWS = PORTFOLIO_HERO_ROWS;

/** @deprecated Use PORTFOLIO_DEFAULT_BOTTOM_ROW */
export const PORTFOLIO_LG_TARGET_BOTTOM_ROW = PORTFOLIO_DEFAULT_BOTTOM_ROW;

/** @deprecated Multi-slot header — single hero slot only */
export const PORTFOLIO_DESKTOP_HEADER_ROWS = 0;

/** @deprecated Multi-slot mobile header — single hero slot only */
export const PORTFOLIO_MOBILE_HEADER_ROWS = 0;

/** Stacked volume panel height on xs/xxs */
export const PORTFOLIO_STACKED_VOLUME_ROWS = 4;

/** Stacked fees panel height on sm/xs/xxs */
export const PORTFOLIO_STACKED_FEES_ROWS = 2;

/** Stacked hero panel height on sm/xs/xxs (equity / metrics / accounts) */
export const PORTFOLIO_STACKED_PANEL_ROWS = 6;

/** Stacked charts slot height on sm/xs/xxs — fits full Daily PnL card */
export const PORTFOLIO_STACKED_CHARTS_ROWS = 12;

/** Performance accounts slot (slot 2) on xs/xxs — Accounts + Perpetuals Overview ledger rows */
export const PORTFOLIO_PERFORMANCE_ACCOUNTS_ROWS = 10;

/** Tab start row when xs/xxs performance stacks metrics, accounts, then charts */
export const PORTFOLIO_STACKED_PERFORMANCE_TAB_START_ROW =
  PORTFOLIO_HERO_START_ROW +
  PORTFOLIO_STACKED_PANEL_ROWS +
  PORTFOLIO_PERFORMANCE_ACCOUNTS_ROWS +
  PORTFOLIO_STACKED_CHARTS_ROWS;

/** Tab start row when xs/xxs agent ranks stacks leaderboard then charts */
export const PORTFOLIO_AGENT_RANKS_STACKED_TAB_START_ROW =
  PORTFOLIO_HERO_START_ROW +
  PORTFOLIO_STACKED_PANEL_ROWS +
  PORTFOLIO_STACKED_CHARTS_ROWS;

/** Tab start row when hero panels are stacked vertically */
export const PORTFOLIO_STACKED_TAB_START_ROW =
  PORTFOLIO_HERO_START_ROW +
  PORTFOLIO_STACKED_VOLUME_ROWS +
  PORTFOLIO_STACKED_FEES_ROWS +
  PORTFOLIO_STACKED_PANEL_ROWS +
  PORTFOLIO_STACKED_CHARTS_ROWS;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];

const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function desktopHeroLayout(cols: number, w1: number, w2: number, w3: number): LayoutConfigLest {
  const x2 = w1;
  const x3 = w1 + w2;
  const feesY = PORTFOLIO_HERO_START_ROW + PORTFOLIO_VOLUME_ROWS;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, PORTFOLIO_HERO_START_ROW, w1, PORTFOLIO_VOLUME_ROWS],
    [x2, PORTFOLIO_HERO_START_ROW, w2, PORTFOLIO_HERO_ROWS],
    [x3, PORTFOLIO_HERO_START_ROW, w3, PORTFOLIO_HERO_ROWS],
    [0, PORTFOLIO_TAB_START_ROW, cols, PORTFOLIO_BASE_TAB_ROWS],
    [0, feesY, w1, PORTFOLIO_FEES_ROWS],
    ...COLLAPSED_TAIL,
  ];
}

function stackedHeroLayout(cols: number): LayoutConfigLest {
  const yVolume = PORTFOLIO_HERO_START_ROW;
  const yFees = yVolume + PORTFOLIO_STACKED_VOLUME_ROWS;
  const yEquity = yFees + PORTFOLIO_STACKED_FEES_ROWS;
  const yCharts = yEquity + PORTFOLIO_STACKED_PANEL_ROWS;
  const yTabs = yCharts + PORTFOLIO_STACKED_CHARTS_ROWS;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, yVolume, cols, PORTFOLIO_STACKED_VOLUME_ROWS],
    [0, yEquity, cols, PORTFOLIO_STACKED_PANEL_ROWS],
    [0, yCharts, cols, PORTFOLIO_STACKED_CHARTS_ROWS],
    [0, yTabs, cols, PORTFOLIO_BASE_TAB_ROWS],
    [0, yFees, cols, PORTFOLIO_STACKED_FEES_ROWS],
    ...COLLAPSED_TAIL,
  ];
}

function pairedOverviewLayout(cols: number, wLeft: number): LayoutConfigLest {
  const wCharts = cols - wLeft;
  const yHero = PORTFOLIO_HERO_START_ROW;
  const yFees = yHero + PORTFOLIO_VOLUME_ROWS;
  const yEquity = yHero + PORTFOLIO_HERO_ROWS;
  const yTabs = yEquity + PORTFOLIO_HERO_ROWS;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, yHero, wLeft, PORTFOLIO_VOLUME_ROWS],
    [0, yEquity, cols, PORTFOLIO_HERO_ROWS],
    [wLeft, yHero, wCharts, PORTFOLIO_HERO_ROWS],
    [0, yTabs, cols, PORTFOLIO_BASE_TAB_ROWS],
    [0, yFees, wLeft, PORTFOLIO_FEES_ROWS],
    ...COLLAPSED_TAIL,
  ];
}

/** lg: 4 + 2 + 6 columns (volume : equity : charts) */
export const portfolioLayoutLg: LayoutConfigLest = desktopHeroLayout(12, 4, 2, 6);

/** md: vol+fees left (3) | charts right (7); equity full width above tabs */
export const portfolioLayoutMd: LayoutConfigLest = pairedOverviewLayout(10, 3);

/** sm: vol+fees left (2) | charts right (4); equity full width above tabs */
export const portfolioLayoutSm: LayoutConfigLest = pairedOverviewLayout(6, 2);
export const portfolioLayoutXs: LayoutConfigLest = stackedHeroLayout(4);
export const portfolioLayoutXxs: LayoutConfigLest = stackedHeroLayout(2);

export type PortfolioLayoutHeroView =
  | "overview"
  | "performance"
  | "agentRanks";

/** performance lg: 3 + 3 + 6 one row | md/sm: pairedPerformanceLayout */
function desktopPerformanceLayout(cols: number): LayoutConfigLest {
  const w1 = cols === 12 ? 3 : 2;
  const w2 = cols === 12 ? 3 : 2;
  const w3 = cols - w1 - w2;
  const x2 = w1;
  const x3 = w1 + w2;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, PORTFOLIO_HERO_START_ROW, w1, PORTFOLIO_HERO_ROWS],
    [x2, PORTFOLIO_HERO_START_ROW, w2, PORTFOLIO_HERO_ROWS],
    [x3, PORTFOLIO_HERO_START_ROW, w3, PORTFOLIO_HERO_ROWS],
    [0, PORTFOLIO_TAB_START_ROW, cols, PORTFOLIO_BASE_TAB_ROWS],
    COLLAPSED,
    ...COLLAPSED_TAIL,
  ];
}

function pairedPerformanceLayout(
  cols: number,
  accountsRows = PORTFOLIO_HERO_ROWS,
): LayoutConfigLest {
  const half = cols / 2;
  const yPair = PORTFOLIO_HERO_START_ROW;
  const pairBandRows = Math.max(PORTFOLIO_HERO_ROWS, accountsRows);
  const yCharts = yPair + pairBandRows;
  const yTabs = yCharts + PORTFOLIO_HERO_ROWS;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, yPair, half, PORTFOLIO_HERO_ROWS],
    [half, yPair, half, accountsRows],
    [0, yCharts, cols, PORTFOLIO_HERO_ROWS],
    [0, yTabs, cols, PORTFOLIO_BASE_TAB_ROWS],
    COLLAPSED,
    ...COLLAPSED_TAIL,
  ];
}

function stackedPerformanceLayout(cols: number): LayoutConfigLest {
  const yMetrics = PORTFOLIO_HERO_START_ROW;
  const yAccounts = yMetrics + PORTFOLIO_STACKED_PANEL_ROWS;
  const yCharts = yAccounts + PORTFOLIO_PERFORMANCE_ACCOUNTS_ROWS;
  const yTabs = yCharts + PORTFOLIO_STACKED_CHARTS_ROWS;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    [0, yMetrics, cols, PORTFOLIO_STACKED_PANEL_ROWS],
    [0, yAccounts, cols, PORTFOLIO_PERFORMANCE_ACCOUNTS_ROWS],
    [0, yCharts, cols, PORTFOLIO_STACKED_CHARTS_ROWS],
    [0, yTabs, cols, PORTFOLIO_BASE_TAB_ROWS],
    COLLAPSED,
    ...COLLAPSED_TAIL,
  ];
}

function buildPerformanceResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseInactive = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, PORTFOLIO_COLLAPSED_SLOTS);

  return {
    lg: collapseInactive(desktopPerformanceLayout(12)),
    md: collapseInactive(pairedPerformanceLayout(10)),
    sm: collapseInactive(pairedPerformanceLayout(6)),
    xs: collapseInactive(stackedPerformanceLayout(4)),
    xxs: collapseInactive(stackedPerformanceLayout(2)),
  };
}

/** agent ranks lg/md: leaderboard | charts 50/50; volume and fees collapsed */
function desktopAgentRanksLayout(cols: number): LayoutConfigLest {
  const half = cols / 2;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    COLLAPSED,
    [0, PORTFOLIO_HERO_START_ROW, half, PORTFOLIO_HERO_ROWS],
    [half, PORTFOLIO_HERO_START_ROW, half, PORTFOLIO_HERO_ROWS],
    [0, PORTFOLIO_TAB_START_ROW, cols, PORTFOLIO_BASE_TAB_ROWS],
    COLLAPSED,
    ...COLLAPSED_TAIL,
  ];
}

function stackedAgentRanksLayout(
  cols: number,
  panelRows: number,
): LayoutConfigLest {
  const yPanel = PORTFOLIO_HERO_START_ROW;
  const chartsRows =
    panelRows === PORTFOLIO_HERO_ROWS
      ? PORTFOLIO_HERO_ROWS
      : PORTFOLIO_STACKED_CHARTS_ROWS;
  const yCharts = yPanel + panelRows;
  const yTabs =
    panelRows === PORTFOLIO_HERO_ROWS
      ? PORTFOLIO_OVERVIEW_PAIRED_TAB_START_ROW
      : PORTFOLIO_AGENT_RANKS_STACKED_TAB_START_ROW;
  return [
    [0, 0, cols, PORTFOLIO_TITLE_ROWS],
    COLLAPSED,
    [0, yPanel, cols, panelRows],
    [0, yCharts, cols, chartsRows],
    [0, yTabs, cols, PORTFOLIO_BASE_TAB_ROWS],
    COLLAPSED,
    ...COLLAPSED_TAIL,
  ];
}

function buildAgentRanksResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseInactive = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, PORTFOLIO_COLLAPSED_SLOTS);

  return {
    lg: collapseInactive(desktopAgentRanksLayout(12)),
    md: collapseInactive(desktopAgentRanksLayout(10)),
    sm: collapseInactive(
      stackedAgentRanksLayout(6, PORTFOLIO_HERO_ROWS),
    ),
    xs: collapseInactive(
      stackedAgentRanksLayout(4, PORTFOLIO_STACKED_PANEL_ROWS),
    ),
    xxs: collapseInactive(
      stackedAgentRanksLayout(2, PORTFOLIO_STACKED_PANEL_ROWS),
    ),
  };
}

/**
 * Swap hero-band geometry for overview vs performance vs agent ranks view.
 */
export function patchPortfolioHeroView(
  config: ResponsiveLayoutConfig,
  heroView: PortfolioLayoutHeroView,
): ResponsiveLayoutConfig {
  if (heroView === "performance") return buildPerformanceResponsiveLayoutConfig();
  if (heroView === "agentRanks") return buildAgentRanksResponsiveLayoutConfig();
  return config;
}

/**
 * Mount copied-agents strip in slot 6 full width directly above the tab section.
 * When hidden, slot 6 stays collapsed and tab geometry is unchanged.
 */
export function patchPortfolioCopiedAgentsStripLayout(
  layout: LayoutConfigLest,
  show: boolean,
): LayoutConfigLest {
  const tabSlot = layout[PORTFOLIO_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) {
    return layout.map((item, index) =>
      index === PORTFOLIO_COPIED_AGENTS_SLOT_INDEX ? COLLAPSED : item,
    );
  }

  if (!show) {
    return layout.map((item, index) =>
      index === PORTFOLIO_COPIED_AGENTS_SLOT_INDEX ? COLLAPSED : item,
    );
  }

  const [tabX, tabY, tabW, tabH] = tabSlot;
  return layout.map((item, index) => {
    if (index === PORTFOLIO_COPIED_AGENTS_SLOT_INDEX) {
      return [0, tabY, tabW, PORTFOLIO_COPIED_AGENTS_ROWS];
    }
    if (index === PORTFOLIO_TAB_SLOT_INDEX) {
      return [tabX, tabY + PORTFOLIO_COPIED_AGENTS_ROWS, tabW, tabH];
    }
    return item;
  });
}

export function patchPortfolioCopiedAgentsStrip(
  config: ResponsiveLayoutConfig,
  show: boolean,
): ResponsiveLayoutConfig {
  const result = {} as ResponsiveLayoutConfig;
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = patchPortfolioCopiedAgentsStripLayout(config[bp], show);
  }
  return result;
}

export function buildPortfolioResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseInactive = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, PORTFOLIO_COLLAPSED_SLOTS);

  return {
    lg: collapseInactive(portfolioLayoutLg),
    md: collapseInactive(portfolioLayoutMd),
    sm: collapseInactive(portfolioLayoutSm),
    xs: collapseInactive(portfolioLayoutXs),
    xxs: collapseInactive(portfolioLayoutXxs),
  };
}

/** Portfolio layouts — keeps all hero slots visible on xs/xxs (no trade MOBILE_HIDDEN_SLOTS). */
export function generatePortfolioResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(configs[bp], totalItems) as ResponsiveLayouts[string];
  }
  return result;
}

/**
 * Compute max grid bottom row that fits in the viewport without page scroll.
 */
export function computePortfolioTargetBottomRow(
  viewportHeight: number,
  menubarHeight = PORTFOLIO_MENUBAR_HEIGHT,
): number {
  const available =
    viewportHeight - menubarHeight - PORTFOLIO_VIEWPORT_FUDGE_PX;
  const rowUnit = PORTFOLIO_ROW_HEIGHT + PORTFOLIO_LAYOUT_MARGIN;
  const rows = Math.floor((available + PORTFOLIO_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    PORTFOLIO_MIN_BOTTOM_ROW,
    Math.min(PORTFOLIO_MAX_BOTTOM_ROW, rows),
  );
}

function patchTabSlotHeight(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const tabSlot = layout[PORTFOLIO_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const tabStart = tabSlot[1];
  const tabHeight = Math.max(PORTFOLIO_BASE_TAB_ROWS, targetBottomRow - tabStart);
  const next: LayoutDefinition = [tabSlot[0], tabStart, tabSlot[2], tabHeight];

  return layout.map((item, index) =>
    index === PORTFOLIO_TAB_SLOT_INDEX ? next : item,
  );
}

function patchTabSlotFixedHeight(
  layout: LayoutConfigLest,
  tabRows: number,
): LayoutConfigLest {
  const tabSlot = layout[PORTFOLIO_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const next: LayoutDefinition = [tabSlot[0], tabSlot[1], tabSlot[2], tabRows];

  return layout.map((item, index) =>
    index === PORTFOLIO_TAB_SLOT_INDEX ? next : item,
  );
}

/** Fixed tab heights for md/sm/xs/xxs scroll mode (lg unchanged). */
export function patchPortfolioScrollTabHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTabSlotFixedHeight(layout, PORTFOLIO_SCROLL_TAB_ROWS);

  return {
    lg: config.lg,
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/**
 * lg: stretch tabs to viewport. md–xxs: fixed tab rows; page scrolls.
 */
export function applyPortfolioLayoutSizing(
  config: ResponsiveLayoutConfig,
  viewportHeight: number,
): ResponsiveLayoutConfig {
  const targetBottomRow = computePortfolioTargetBottomRow(viewportHeight);
  const scrollSized = patchPortfolioScrollTabHeights(config);

  return {
    lg: patchTabSlotHeight(config.lg, targetBottomRow),
    md: scrollSized.md,
    sm: scrollSized.sm,
    xs: scrollSized.xs,
    xxs: scrollSized.xxs,
  };
}

/**
 * Stretch the tab slot so the grid bottom row matches the viewport.
 */
export function patchPortfolioViewportFit(
  config: ResponsiveLayoutConfig,
  targetBottomRow: number,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTabSlotHeight(layout, targetBottomRow);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/**
 * Multi-slot sidebar geometry (deferred — kept for future slot 6 reintroduction).
 */
export function patchPortfolioSidebarLayout(
  layout: LayoutConfigLest,
  showSidebar: boolean,
  targetBottomRow: number,
  heroEndRow = PORTFOLIO_TAB_START_ROW,
): LayoutConfigLest {
  const tabSlot = layout[4];
  const heroSlot = layout[2];
  const sidebarSlot = layout[6];
  if (!tabSlot || !heroSlot || !sidebarSlot) return layout;

  const tabHeight = Math.max(PORTFOLIO_BASE_TAB_ROWS, targetBottomRow - heroEndRow);
  if (!showSidebar) {
    return layout.map((item, index) => {
      if (index === 2 && heroSlot[2] > 0) {
        return [heroSlot[0], heroSlot[1], heroSlot[2] + (sidebarSlot[2] || 0), heroSlot[3]];
      }
      if (index === 4 && tabSlot[2] > 0) {
        return [tabSlot[0], heroEndRow, tabSlot[2] + (sidebarSlot[2] || 0), tabHeight];
      }
      if (index === 6) return COLLAPSED;
      return item;
    });
  }

  const sidebarHeight = heroEndRow - (sidebarSlot[1] || 0) + tabHeight;
  return layout.map((item, index) => {
    if (index === 2 && heroSlot[2] > 0) {
      return [heroSlot[0], heroSlot[1], heroSlot[2], heroSlot[3]];
    }
    if (index === 4 && tabSlot[2] > 0) {
      return [tabSlot[0], heroEndRow, tabSlot[2], tabHeight];
    }
    if (index === 6) {
      return [9, sidebarSlot[1] || 4, 3, sidebarHeight];
    }
    return item;
  });
}

/**
 * Applies viewport fit for the multi-slot layout, or sidebar patches when enabled.
 */
export function patchPortfolioDesktopLayout(
  config: ResponsiveLayoutConfig,
  targetBottomRow: number,
  showSidebar = false,
): ResponsiveLayoutConfig {
  const scrollSized = patchPortfolioScrollTabHeights(config);
  const fitted: ResponsiveLayoutConfig = {
    lg: patchTabSlotHeight(config.lg, targetBottomRow),
    md: scrollSized.md,
    sm: scrollSized.sm,
    xs: scrollSized.xs,
    xxs: scrollSized.xxs,
  };
  if (!showSidebar) return fitted;

  return {
    lg: patchPortfolioSidebarLayout(fitted.lg, true, targetBottomRow),
    md: fitted.md,
    sm: fitted.sm,
    xs: fitted.xs,
    xxs: fitted.xxs,
  };
}

export function assertPortfolioLgViewportFit(): void {
  const bottom = getLayoutBottomRow(
    buildPortfolioResponsiveLayoutConfig().lg,
  );
  if (bottom !== PORTFOLIO_DEFAULT_BOTTOM_ROW) {
    throw new Error(
      `portfolio lg layout bottom row ${bottom} !== ${PORTFOLIO_DEFAULT_BOTTOM_ROW}`,
    );
  }
}

export function assertPortfolioLayoutValid(
  config: ResponsiveLayoutConfig,
): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `portfolio ${bp}`);
  }
}
