import { useCallback, useState, type JSX } from "react";
import type {
  ContractFieldKey,
  ContractOverrides,
  ExecutionContract,
} from "./executionContract";

export interface IntentExecutionContractProps {
  contract: ExecutionContract | null;
  compact?: boolean;
  overrides?: ContractOverrides;
  onOverrideChange?: (patch: ContractOverrides) => void;
}

function sourceLabel(source: ExecutionContract["lines"][0]["source"], warning?: boolean): string {
  switch (source) {
    case "you":
      return "you:";
    case "default":
      return warning ? "default ⚠" : "default";
    case "bucket":
      return "bucket";
    case "agent-bounded":
      return "agent-bounded";
    case "inferred":
      return "inferred";
    default:
      return "";
  }
}

export function IntentExecutionContract({
  contract,
  compact = false,
  overrides = {},
  onOverrideChange,
}: IntentExecutionContractProps): JSX.Element | null {
  const [editingField, setEditingField] = useState<ContractFieldKey | null>(null);
  const [editValue, setEditValue] = useState("");

  const startEdit = useCallback(
    (field: ContractFieldKey, currentValue: string) => {
      if (!onOverrideChange) return;
      setEditingField(field);
      const numeric = currentValue.replace(/[^\d.]/g, "");
      setEditValue(numeric);
    },
    [onOverrideChange],
  );

  const commitEdit = useCallback(
    (field: ContractFieldKey) => {
      if (!onOverrideChange) return;
      const num = parseFloat(editValue);
      if (Number.isNaN(num)) {
        setEditingField(null);
        return;
      }
      const patch: ContractOverrides = { ...overrides };
      if (field === "size") patch.sizePct = num;
      if (field === "leverage") patch.leverage = num;
      if (field === "stop") patch.stopLoss = num;
      if (field === "takeProfit") patch.takeProfit = num;
      if (field === "entry") patch.entryPrice = num;
      onOverrideChange(patch);
      setEditingField(null);
    },
    [editValue, onOverrideChange, overrides],
  );

  if (!contract) return null;

  if (compact) {
    return (
      <div className="intent-contract intent-contract--compact" aria-label="Intent preview">
        <span className="intent-contract-summary">{contract.summaryOneLine}</span>
        {contract.hasDefaultedRisk ? (
          <span className="intent-contract-warn">⚠ size &amp; lev = default</span>
        ) : null}
      </div>
    );
  }

  return (
    <div className="intent-contract" aria-label="Intent preview">
      <div className="intent-contract-header">Intent preview</div>
      <p className="intent-contract-you-said">
        You said: &ldquo;{contract.youSaid}&rdquo;
      </p>
      <div className="intent-contract-table">
        <div className="intent-contract-table-head">I will:</div>
        {contract.lines.map((line) => (
          <div key={line.field} className="intent-contract-row">
            <span className="intent-contract-key">{line.key}</span>
            <span className="intent-contract-value">
              {editingField === line.field ? (
                <input
                  type="text"
                  className="intent-contract-edit-input"
                  value={editValue}
                  autoFocus
                  onChange={(e) => setEditValue(e.target.value)}
                  onBlur={() => commitEdit(line.field)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit(line.field);
                    if (e.key === "Escape") setEditingField(null);
                  }}
                />
              ) : (
                line.value
              )}
            </span>
            <span
              className={`intent-contract-source${line.warning ? " is-warning" : ""}`}
            >
              {sourceLabel(line.source, line.warning)}
            </span>
            {line.editable && onOverrideChange ? (
              <button
                type="button"
                className="intent-contract-edit-btn"
                onClick={() => startEdit(line.field, line.value)}
              >
                edit
              </button>
            ) : null}
          </div>
        ))}
      </div>
    </div>
  );
}
