/**
 * Onboard modal: choose connection method for owner wallet.
 * 1) Wallet extension: detect installed wallet; greyed out when no wallet detected
 * 2) Demo mnemonic: generate or enter phrase, derive ETH address at index 0 via mormSigner
 * Uses detectSupportedWallet and connect patterns from AgentDelegation.
 */
import { useState, useCallback, useEffect } from "react";
import { createPortal } from "react-dom";
import { isAddress } from "viem";
import {
  detectSupportedWallet,
  type SupportedWallet,
} from "../hooks/useAgentDelegation";
import mormSigner from "../sdk/signing/mormSigner";
import { toast } from "sonner";
import { isOfflineBaseURL } from "../sdk/utils/onboardMock";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "./ui/overlay";
import "./smartlayout/layout.css";

const WALLET_DISPLAY_NAMES: Record<string, string> = {
  phantom: "Phantom",
  metamask: "MetaMask",
  onekey: "OneKey",
};

export interface OnboardModalProps {
  isOpen: boolean;
  /** Called when mnemonic is valid; should return a Promise that resolves on success, rejects on failure. Modal stays open until resolved. */
  onMnemonicConnect: (mnemonic: string, address: string) => void | Promise<void>;
  onWalletExtensionConnect: (address: string) => void;
  onClose?: () => void;
  baseURL?: string;
}

interface EthRequestProvider {
  request(args: { method: "eth_requestAccounts" }): Promise<string[]>;
}

export function OnboardModal({
  isOpen,
  onMnemonicConnect,
  onWalletExtensionConnect,
  onClose,
  baseURL,
}: OnboardModalProps): JSX.Element | null {
  const [mnemonic, setMnemonic] = useState("");
  const [mnemonicError, setMnemonicError] = useState<string | null>(null);
  const [walletError, setWalletError] = useState<string | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [supportedWallet, setSupportedWallet] = useState<SupportedWallet | null>(
    null,
  );

  useEffect(() => {
    if (!isOpen) {
      setMnemonic("");
      setMnemonicError(null);
      setWalletError(null);
      return;
    }

    setSupportedWallet(detectSupportedWallet());
  }, [isOpen]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  const handleEscapeClose = useCallback(() => {
    onClose?.();
  }, [onClose]);

  useOverlayEscapeKey(isOpen, handleEscapeClose);

  const isWalletDetected = !!supportedWallet;
  const walletDisplayName = supportedWallet
    ? WALLET_DISPLAY_NAMES[supportedWallet] ?? "Browser Wallet"
    : "";

  const deriveAddressFromMnemonic = useCallback(
    async (phrase: string): Promise<string | null> => {
      const trimmed = phrase.trim();
      if (!trimmed) return null;
      try {
        if (!mormSigner.isReady()) {
          await mormSigner.initialize();
        }
        const result = await mormSigner.generateAddress(trimmed, 0);
        return result.success && result.address ? result.address : null;
      } catch {
        return null;
      }
    },
    [],
  );

  const handleGenerateMnemonic = useCallback(async () => {
    try {
      setMnemonicError(null);
      if (!mormSigner.isReady()) {
        await mormSigner.initialize();
      }
      const result = await mormSigner.generateMnemonic(12);
      if (!result.success || !result.mnemonic) {
        setMnemonicError(result.error ?? "Failed to generate mnemonic");
        return;
      }
      setMnemonic(result.mnemonic);
      toast.success("Demo mnemonic generated");
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Failed to generate mnemonic";
      setMnemonicError(msg);
      toast.error(msg);
    }
  }, []);

  const handleMnemonicConnect = useCallback(async () => {
    setIsConnecting(true);
    setMnemonicError(null);
    const trimmed = mnemonic.trim();
    if (!trimmed) {
      setMnemonicError("Please enter a mnemonic phrase");
      setIsConnecting(false);
      return;
    }
    try {
      const address = await deriveAddressFromMnemonic(trimmed);
      if (!address) {
        setMnemonicError("Invalid mnemonic phrase");
        return;
      }
      await Promise.resolve(onMnemonicConnect(trimmed, address));
    } catch (err) {
      const msg =
        err instanceof Error ? err.message : "Connection failed";
      setMnemonicError(msg);
    } finally {
      setIsConnecting(false);
    }
  }, [mnemonic, deriveAddressFromMnemonic, onMnemonicConnect]);

  const handleWalletExtensionConnect = useCallback(async () => {
    if (!supportedWallet) return;
    const w = typeof window !== "undefined" ? window : null;
    if (!w) return;

    setIsConnecting(true);
    setWalletError(null);
    const ethereum = w.ethereum;
    let provider: EthRequestProvider | null = ethereum as EthRequestProvider | null;
    if (supportedWallet === "phantom") {
      const phantomEth = w.phantom?.ethereum;
      const phantomSelf =
        w.phantom && "request" in w.phantom && typeof (w.phantom as EthRequestProvider).request === "function"
          ? (w.phantom as EthRequestProvider)
          : null;
      provider =
        (phantomEth as EthRequestProvider) ??
        phantomSelf ??
        (ethereum?.isPhantom ? (ethereum as EthRequestProvider) : null);
    } else if (supportedWallet === "onekey") {
      provider = (w.$onekey?.ethereum ?? ethereum) as EthRequestProvider | null;
    }

    if (!provider || typeof provider.request !== "function") {
      setIsConnecting(false);
      return;
    }

    try {
      if (baseURL && isOfflineBaseURL(baseURL)) {
        const mockAddress = "0x000000000000000000000000000000000000dEaD";
        onWalletExtensionConnect(mockAddress);
        setIsConnecting(false);
        return;
      }

      const accounts = await provider.request({ method: "eth_requestAccounts" });
      if (!accounts?.length || !accounts[0]) {
        setWalletError(
          "No accounts returned. Please approve the connection in your wallet.",
        );
        return;
      }
      const address = accounts[0];
      if (!isAddress(address)) {
        setWalletError("Invalid address returned from wallet");
        return;
      }
      await new Promise((resolve) => setTimeout(resolve, 300));
      onWalletExtensionConnect(address);
    } catch (err) {
      const msg =
        err instanceof Error ? err.message : "Failed to connect wallet";
      setWalletError(msg);
      console.error("Wallet connect error:", err);
    } finally {
      setIsConnecting(false);
    }
  }, [baseURL, supportedWallet, onWalletExtensionConnect]);

  const handleBackdropClose = useCallback(() => {
    onClose?.();
  }, [onClose]);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={handleBackdropClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--onboard"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content onboard-modal-content staggered-overlay-panel--scale"
        aria-label="Connect Wallet"
      >
        <div className="modal-header onboard-modal-header">
          <div className="onboard-modal-header-text">
            <h3 id="onboard-modal-title" className="terminal-market-title">
              Connect Wallet
            </h3>
            <p className="onboard-modal-subtitle">
              Choose how to connect as the owner
            </p>
          </div>
          {onClose && (
            <button
              type="button"
              className="onboard-modal-close terminal-interactive"
              onClick={onClose}
              aria-label="Close"
            >
              ×
            </button>
          )}
        </div>

        <div className="onboard-modal-body">
          {/* Option 1: Wallet extension */}
          <div
            className={`onboard-option terminal-interactive ${!isWalletDetected ? "onboard-option-greyed" : ""}`}
          >
            <h4 className="terminal-panel-title onboard-option-heading">
              1. Wallet extension
            </h4>
            <p className="onboard-option-desc">
              {isWalletDetected
                ? `${walletDisplayName} detected`
                : "No wallet extension detected"}
            </p>
            {walletError && (
              <div className="onboard-error">{walletError}</div>
            )}
            <button
              type="button"
              className="btn btn-primary onboard-option-btn terminal-interactive"
              onClick={handleWalletExtensionConnect}
              disabled={!isWalletDetected || isConnecting}
            >
              {isConnecting
                ? "Connecting..."
                : isWalletDetected
                  ? `Connect with ${walletDisplayName}`
                  : "No wallet available"}
            </button>
          </div>

          {/* Option 2: Demo mnemonic */}
          <div className="onboard-option terminal-interactive">
            <h4 className="terminal-panel-title onboard-option-heading">
              2. Demo mnemonic
            </h4>
            <p className="onboard-option-desc">
              For demo and development only. Address derived at index 0 (ETH, no
              password).
            </p>
            <div className="risk-notice onboard-demo-notice">
              Demo only — do not use a generated phrase for real funds or
              production wallets.
            </div>
            <div className="form-row onboard-mnemonic-row">
              <div className="onboard-mnemonic-label-row">
                <label htmlFor="onboard-mnemonic-input" className="terminal-label">
                  Mnemonic phrase
                </label>
                <button
                  type="button"
                  className="onboard-generate-link terminal-interactive"
                  onClick={handleGenerateMnemonic}
                  disabled={isConnecting}
                  aria-label="Generate demo mnemonic phrase"
                >
                  Generate demo phrase
                </button>
              </div>
              <textarea
                id="onboard-mnemonic-input"
                className="form-input form-input--textarea onboard-mnemonic-input"
                value={mnemonic}
                onChange={(e) => {
                  setMnemonic(e.target.value);
                  setMnemonicError(null);
                }}
                placeholder="Enter or generate a 12-word demo phrase..."
                rows={3}
                disabled={isConnecting}
                autoComplete="off"
              />
            </div>
            {mnemonicError && (
              <div className="onboard-error">{mnemonicError}</div>
            )}
            <button
              type="button"
              className="btn btn-secondary onboard-option-btn terminal-interactive"
              onClick={handleMnemonicConnect}
              disabled={isConnecting || !mnemonic.trim()}
            >
              {isConnecting ? "Connecting..." : "Connect with Mnemonic"}
            </button>
          </div>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
