import {
  ORDER_PENDING_STATUSES,
} from "../../constants";
import type { PendingOrder } from "../types/data";

/** Whether a normalized or prefixed order status is pending/open. */
export function isPendingOrderStatus(status: string): boolean {
  const upper = status.toUpperCase();
  return ORDER_PENDING_STATUSES.some((s) => upper.includes(s.replace("ORDER_STATUS_", "")));
}

function normalizeOrderType(type: unknown): string {
  return String(type ?? "").toUpperCase();
}

/** Whether the order type is a scale parent order. */
export function isScaleOrderType(type: unknown): boolean {
  const normalized = normalizeOrderType(type);
  return normalized.includes("SCALE");
}

/** Whether the order type is stop-limit (resting stop price + limit). */
export function isStopLimitOrderType(type: unknown): boolean {
  const normalized = normalizeOrderType(type);
  return normalized.includes("STOP") && normalized.includes("LIMIT");
}

export type PendingOrderLineCategory = "limit" | "stop_limit" | "scale";

/** Classify a pending order type for chart line filtering. */
export function classifyChartOrderCategory(orderType: unknown): PendingOrderLineCategory {
  const normalized = normalizeOrderType(orderType);
  if (isScaleOrderType(normalized)) return "scale";
  if (isStopLimitOrderType(normalized)) return "stop_limit";
  return "limit";
}

function getOrderType(order: PendingOrder): string {
  const raw = order.raw as Record<string, unknown> | undefined;
  return normalizeOrderType(raw?.orderType ?? order.type);
}

function isLimitLikeOrderType(type: string): boolean {
  return (
    type.includes("LIMIT") &&
    !type.includes("MARKET") &&
    !type.includes("SCALE")
  );
}

/**
 * Pending orders eligible for chart price lines: limit, stop_limit, and scale
 * parents (expanded to legs elsewhere). Excludes market orders.
 */
export function isChartEligibleOrder(order: PendingOrder): boolean {
  if (!isPendingOrderStatus(String(order.status ?? ""))) {
    return false;
  }
  const orderType = getOrderType(order);
  if (orderType.includes("MARKET") && !orderType.includes("STOP")) {
    return false;
  }
  return isLimitLikeOrderType(orderType) || isScaleOrderType(orderType) || orderType.includes("STOP_LIMIT");
}

export function getPendingOrderType(order: PendingOrder): string {
  return getOrderType(order);
}
