import type { BinanceClientConfig, BinanceKlineRow } from "./types";
import { BINANCE_SPOT_REST_DEFAULT } from "./types";
import { binanceIntervalToMs } from "./klineUtil";

function defaultRestBaseUrl(): string {
  if (typeof window !== "undefined") {
    return "/api/binance";
  }
  return BINANCE_SPOT_REST_DEFAULT;
}

export class BinanceClient {
  private readonly restBaseUrl: string;

  constructor(config: BinanceClientConfig = {}) {
    this.restBaseUrl = (config.restBaseUrl ?? defaultRestBaseUrl()).replace(/\/$/, "");
  }

  /**
   * Fetch historical klines from Binance Spot REST API.
   * GET /api/v3/klines
   */
  async getKlines(
    symbol: string,
    interval: string,
    limit = 500,
    startTime?: number,
    endTime?: number,
  ): Promise<BinanceKlineRow[]> {
    const params = new URLSearchParams({
      symbol: symbol.toUpperCase(),
      interval,
      limit: String(Math.min(Math.max(limit, 1), 1000)),
    });
    if (startTime != null && startTime > 0) {
      params.set("startTime", String(startTime));
    }
    if (endTime != null && endTime > 0) {
      params.set("endTime", String(endTime));
    }

    const url = `${this.restBaseUrl}/api/v3/klines?${params.toString()}`;
    const response = await fetch(url);
    if (!response.ok) {
      const body = await response.text().catch(() => "");
      throw new Error(
        `Binance klines request failed (${response.status}): ${body || response.statusText}`,
      );
    }

    const data = (await response.json()) as unknown;
    if (!Array.isArray(data)) {
      throw new Error("Binance klines response is not an array");
    }
    return data as BinanceKlineRow[];
  }

  /**
   * Fetch all klines in [startTime, endTime] with paginated requests (max 1000 per call).
   */
  async getKlinesRange(
    symbol: string,
    interval: string,
    startTime: number,
    endTime: number = Date.now(),
  ): Promise<BinanceKlineRow[]> {
    const pageLimit = 1000;
    const intervalMs = binanceIntervalToMs(interval);
    const all: BinanceKlineRow[] = [];
    let cursor = startTime;

    while (cursor < endTime) {
      const rows = await this.getKlines(symbol, interval, pageLimit, cursor, endTime);
      if (rows.length === 0) break;

      for (const row of rows) {
        const openMs = Number(row[0]);
        if (openMs >= startTime && openMs <= endTime) {
          all.push(row);
        }
      }

      const lastOpenMs = Number(rows[rows.length - 1]![0]);
      const next = lastOpenMs + intervalMs;
      if (next <= cursor) break;
      cursor = next;

      if (rows.length < pageLimit) break;
    }

    const deduped = new Map<number, BinanceKlineRow>();
    for (const row of all) {
      deduped.set(Number(row[0]), row);
    }
    return [...deduped.values()].sort((a, b) => Number(a[0]) - Number(b[0]));
  }
}

export default BinanceClient;
