import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import {
  AGENT_KPI_MANIFEST_SNAPSHOT,
  getAgentKpiSummaryByCatalogId,
} from "../../offline/mock_data/agentKpiManifestSnapshot";
import type {
  AgentKpiHistoryManifest,
  AgentKpiSummary,
} from "../../offline/mock_data/agentKpiHistory.types";
import {
  AGENT_KPI_HISTORY_DATA_BASE_URL,
  fetchAgentKpiManifest,
  getCachedAgentKpiManifest,
  getManifestKpiAgentByCatalogId,
} from "../sdk/api/agentKpiHistory/agentKpiHistoryClient";

type AgentKpiManifestContextValue = {
  manifest: AgentKpiHistoryManifest | null;
  agents: AgentKpiHistoryManifest["agents"];
  loading: boolean;
  error: string | null;
  baseUrl: string;
  refresh: () => Promise<void>;
  getSummaryByCatalogId: (catalogAgentId: string) => AgentKpiSummary;
  getAgentByCatalogId: (
    catalogAgentId: string,
  ) => AgentKpiHistoryManifest["agents"][number] | undefined;
};

const AgentKpiManifestContext = createContext<AgentKpiManifestContextValue | null>(
  null,
);

export function AgentKpiManifestProvider({
  children,
  enabled = true,
  baseUrl = AGENT_KPI_HISTORY_DATA_BASE_URL,
}: {
  children: ReactNode;
  enabled?: boolean;
  baseUrl?: string;
}): JSX.Element {
  const [manifest, setManifest] = useState<AgentKpiHistoryManifest | null>(
    () => getCachedAgentKpiManifest() ?? AGENT_KPI_MANIFEST_SNAPSHOT,
  );
  const [loading, setLoading] = useState(enabled && !getCachedAgentKpiManifest());
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!enabled) {
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const next = await fetchAgentKpiManifest(baseUrl);
      setManifest(next);
    } catch (err: unknown) {
      setError(
        err instanceof Error ? err.message : "Failed to load agent KPI manifest",
      );
      setManifest(AGENT_KPI_MANIFEST_SNAPSHOT);
    } finally {
      setLoading(false);
    }
  }, [baseUrl, enabled]);

  useEffect(() => {
    void load();
  }, [load]);

  const value = useMemo<AgentKpiManifestContextValue>(() => ({
    manifest,
    agents: manifest?.agents ?? AGENT_KPI_MANIFEST_SNAPSHOT.agents,
    loading,
    error,
    baseUrl,
    refresh: load,
    getSummaryByCatalogId: (catalogAgentId) => {
      const fromManifest = manifest
        ? getManifestKpiAgentByCatalogId(manifest, catalogAgentId)?.summary
        : undefined;
      return fromManifest ?? getAgentKpiSummaryByCatalogId(catalogAgentId);
    },
    getAgentByCatalogId: (catalogAgentId) =>
      manifest ? getManifestKpiAgentByCatalogId(manifest, catalogAgentId) : undefined,
  }), [manifest, loading, error, baseUrl, load]);

  return (
    <AgentKpiManifestContext.Provider value={value}>
      {children}
    </AgentKpiManifestContext.Provider>
  );
}

export function useAgentKpiManifest(): AgentKpiManifestContextValue {
  const context = useContext(AgentKpiManifestContext);
  if (!context) {
    return {
      manifest: AGENT_KPI_MANIFEST_SNAPSHOT,
      agents: AGENT_KPI_MANIFEST_SNAPSHOT.agents,
      loading: false,
      error: null,
      baseUrl: AGENT_KPI_HISTORY_DATA_BASE_URL,
      refresh: async () => {},
      getSummaryByCatalogId: getAgentKpiSummaryByCatalogId,
      getAgentByCatalogId: (catalogAgentId) =>
        getManifestKpiAgentByCatalogId(AGENT_KPI_MANIFEST_SNAPSHOT, catalogAgentId),
    };
  }
  return context;
}
