import React, { useMemo } from "react";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useMarkets } from "../../hooks/useMarkets";
import { DEFAULT_BASE_URL } from "../../constants";
import { sortGuardrailIntents } from "./deckIntents";

export interface PendingMarketPillsProps {
  baseURL?: string;
  selectedMarketId?: string;
  onMarketSelect?: (marketId: string) => void;
}

function PendingMarketPills({
  baseURL = DEFAULT_BASE_URL,
  selectedMarketId = "",
  onMarketSelect,
}: PendingMarketPillsProps): JSX.Element | null {
  const { tasks } = useAgentTasks();
  const { markets } = useMarkets({ baseURL, autoFetchMarkets: false });

  const groups = useMemo(() => {
    const pending = sortGuardrailIntents(tasks).filter((t) => t.marketId);
    const byMarket = new Map<string, number>();
    for (const task of pending) {
      const id = task.marketId!;
      byMarket.set(id, (byMarket.get(id) ?? 0) + 1);
    }
    return [...byMarket.entries()]
      .map(([marketId, count]) => {
        const market = markets.find(
          (m) => m.index === marketId || m.marketIndex === marketId,
        );
        const label =
          market?.baseAsset ||
          market?.moniker?.split("/")[0]?.split("-")[0] ||
          marketId;
        return { marketId, count, label: label.toUpperCase() };
      })
      .sort((a, b) => b.count - a.count);
  }, [tasks, markets]);

  if (groups.length <= 1) return null;

  return (
    <div className="trade-safety-header-pills" role="list">
      {groups.map(({ marketId, count, label }) => {
        const isActive =
          selectedMarketId === marketId ||
          markets.some(
            (m) =>
              (m.index === selectedMarketId ||
                m.marketIndex === selectedMarketId) &&
              (m.index === marketId || m.marketIndex === marketId),
          );
        return (
          <button
            key={marketId}
            type="button"
            role="listitem"
            className={`trade-safety-header-pill${isActive ? " is-active" : ""}`}
            onClick={() => onMarketSelect?.(marketId)}
          >
            {label} ({count})
          </button>
        );
      })}
    </div>
  );
}

export default React.memo(PendingMarketPills);
