import type { DemoContext, LiveMetrics, NetworkKpis, TelemetryPanel, ThroughputTier } from "./types";
import { bftQuorumFor, dvtOperatorsFor } from "./types";

let blockCounter = 12_847;
let confirmedCounter = 12_842;
let tick = 0;

interface ThroughputProfile {
  submitMin: number;
  submitMax: number;
  confirmedRatio: number;
  p50Min: number;
  p50Max: number;
  p99Min: number;
  p99Max: number;
  throughputChartMin: number;
  throughputChartMax: number;
  finalityChartMin: number;
  finalityChartMax: number;
  pipelineChartMin: number;
  pipelineChartMax: number;
  blockIncrementChance: number;
}

const THROUGHPUT_PROFILES: Record<ThroughputTier, ThroughputProfile> = {
  0: {
    submitMin: 2,
    submitMax: 4,
    confirmedRatio: 0.95,
    p50Min: 180,
    p50Max: 260,
    p99Min: 420,
    p99Max: 680,
    throughputChartMin: 1.5,
    throughputChartMax: 4.5,
    finalityChartMin: 160,
    finalityChartMax: 720,
    pipelineChartMin: 12,
    pipelineChartMax: 48,
    blockIncrementChance: 0.45,
  },
  1: {
    submitMin: 100,
    submitMax: 1000,
    confirmedRatio: 0.95,
    p50Min: 50,
    p50Max: 120,
    p99Min: 150,
    p99Max: 400,
    throughputChartMin: 80,
    throughputChartMax: 1050,
    finalityChartMin: 45,
    finalityChartMax: 420,
    pipelineChartMin: 8,
    pipelineChartMax: 32,
    blockIncrementChance: 0.72,
  },
  2: {
    submitMin: 8000,
    submitMax: 50000,
    confirmedRatio: 0.98,
    p50Min: 5,
    p50Max: 25,
    p99Min: 20,
    p99Max: 80,
    throughputChartMin: 7500,
    throughputChartMax: 52000,
    finalityChartMin: 5,
    finalityChartMax: 85,
    pipelineChartMin: 2,
    pipelineChartMax: 12,
    blockIncrementChance: 0.92,
  },
};

function wave(min: number, max: number, phase = 0): number {
  const span = max - min;
  const t = tick + phase;
  return min + span * (0.5 + 0.5 * Math.sin(t * 0.35));
}

function latencyMultiplier(validatorCount: number): number {
  return 1 + (validatorCount - 4) * 0.008;
}

function buildSeries(
  length: number,
  min: number,
  max: number,
  phase = 0,
): number[] {
  const values: number[] = [];
  for (let i = 0; i < length; i += 1) {
    const t = tick - (length - i) + phase;
    const span = max - min;
    values.push(min + span * (0.5 + 0.5 * Math.sin(t * 0.35)));
  }
  return values;
}

export const TELEMETRY_PANELS: readonly Omit<TelemetryPanel, "series">[] = [
  { id: "throughput", title: "Live Throughput (submit vs confirmed TPS)", unit: "tx/s", colorToken: "accent" },
  { id: "finality", title: "Finality Latency (ingress → finality)", unit: "ms", colorToken: "secondary" },
  { id: "pipeline", title: "Per-Stage Avg Pipeline Latency", unit: "ms", colorToken: "long" },
  { id: "availability", title: "Validator / DVT Availability", unit: "nodes", colorToken: "premium" },
  { id: "chaos", title: "Finality During Chaos (rounds/s)", unit: "r/s", colorToken: "short" },
  { id: "frosty", title: "Frosty Fallbacks Rate", unit: "/s", colorToken: "info" },
];

export function generateNetworkKpis(ctx: DemoContext): NetworkKpis {
  const profile = THROUGHPUT_PROFILES[ctx.throughputTier];
  blockCounter += Math.random() > 1 - profile.blockIncrementChance ? 1 : 0;
  confirmedCounter += Math.random() > 1 - profile.blockIncrementChance * 0.85 ? 1 : 0;

  const submitTps = wave(profile.submitMin, profile.submitMax, 0);

  return {
    activeValidators: ctx.validatorCount,
    totalValidators: ctx.validatorCount,
    totalBlocks: blockCounter,
    confirmedBlocks: confirmedCounter,
    averageTps: Number(submitTps.toFixed(1)),
    finalityRate: Math.min(100, Math.round((confirmedCounter / blockCounter) * 100)),
    roundsFinalised: 4201 + tick * ctx.validatorCount,
    roundsFailed: ctx.throughputTier === 0 ? 0 : 0,
    frostyFallbacks: ctx.throughputTier === 0 ? 0 : Math.floor(tick * 0.01),
    latestTips: Math.max(1, Math.round(3 + ctx.validatorCount / 16)),
    timestampMs: Date.now(),
  };
}

export function generateLiveMetrics(ctx: DemoContext): LiveMetrics {
  tick += 1;

  const profile = THROUGHPUT_PROFILES[ctx.throughputTier];
  const latencyMul = latencyMultiplier(ctx.validatorCount);
  const submitTps = wave(profile.submitMin, profile.submitMax, 0);
  const confirmedTps = submitTps * (profile.confirmedRatio + 0.04 * Math.sin(tick * 0.2));

  return {
    submitTps: Number(submitTps.toFixed(ctx.throughputTier === 2 ? 0 : 1)),
    confirmedTps: Number(confirmedTps.toFixed(ctx.throughputTier === 2 ? 0 : 1)),
    finalityP50Ms: Number((wave(profile.p50Min, profile.p50Max, 1) * latencyMul).toFixed(0)),
    finalityP99Ms: Number((wave(profile.p99Min, profile.p99Max, 2) * latencyMul).toFixed(0)),
    committeeSize: ctx.validatorCount,
    bftQuorum: bftQuorumFor(ctx.validatorCount),
    validatorsUp: ctx.validatorCount,
    dvtOperatorsUp: dvtOperatorsFor(ctx.validatorCount),
  };
}

export function generateTelemetryPanels(ctx: DemoContext): TelemetryPanel[] {
  const profile = THROUGHPUT_PROFILES[ctx.throughputTier];
  const n = ctx.validatorCount;
  const dvt = dvtOperatorsFor(n);
  const availabilityMin = n * 0.95;
  const chaosMax = ctx.throughputTier === 0 ? 2.4 : ctx.throughputTier === 1 ? 8 : 24;
  const frostyMax = ctx.throughputTier === 0 ? 0.08 : ctx.throughputTier === 1 ? 0.4 : 1.2;

  return [
    {
      ...TELEMETRY_PANELS[0],
      series: buildSeries(40, profile.throughputChartMin, profile.throughputChartMax, 0),
    },
    {
      ...TELEMETRY_PANELS[1],
      series: buildSeries(
        40,
        profile.finalityChartMin * latencyMultiplier(n),
        profile.finalityChartMax * latencyMultiplier(n),
        1,
      ),
    },
    {
      ...TELEMETRY_PANELS[2],
      series: buildSeries(40, profile.pipelineChartMin, profile.pipelineChartMax, 2),
    },
    {
      ...TELEMETRY_PANELS[3],
      series: buildSeries(40, availabilityMin, n + dvt * 0.02, 3),
    },
    {
      ...TELEMETRY_PANELS[4],
      series: buildSeries(40, 0.2, chaosMax, 4),
    },
    {
      ...TELEMETRY_PANELS[5],
      series: buildSeries(40, 0, frostyMax, 5),
    },
  ];
}
