import { useEffect, useState } from "react";

import type { AgentKpiHistoryFile } from "../../offline/mock_data/agentKpiHistory.types";
import {
  AGENT_KPI_HISTORY_DATA_BASE_URL,
  fetchAgentKpiForAgents,
} from "../sdk/api/agentKpiHistory/agentKpiHistoryClient";

export interface UseAgentKpiHistoryForAgentsResult {
  kpiByAgentId: Map<string, AgentKpiHistoryFile>;
  loading: boolean;
  error: string | null;
}

export function useAgentKpiHistoryForAgents(
  catalogAgentIds: readonly string[],
  baseUrl: string = AGENT_KPI_HISTORY_DATA_BASE_URL,
): UseAgentKpiHistoryForAgentsResult {
  const [kpiByAgentId, setKpiByAgentId] = useState<Map<string, AgentKpiHistoryFile>>(
    () => new Map(),
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const ids = [...new Set(catalogAgentIds.map((id) => id.trim()).filter(Boolean))];
    if (ids.length === 0) {
      setKpiByAgentId(new Map());
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchAgentKpiForAgents(ids, baseUrl)
      .then((map) => {
        if (cancelled) return;
        setKpiByAgentId(map);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error ? err.message : "Failed to load agent KPI history",
        );
        setKpiByAgentId(new Map());
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [catalogAgentIds, baseUrl]);

  return { kpiByAgentId, loading, error };
}
