import type { JSX } from "react";
import type { ContractOverrides } from "../executionContract";
import type { DirectionClass } from "../intentBreakdown";
import type { ControlDepth } from "./IntentControlDepthToggle";

export interface IntentDirectionalBodyProps {
  direction: DirectionClass;
  sizePct: number;
  leverage: number;
  depth: ControlDepth;
  stopLoss?: number | null;
  takeProfit?: number | null;
  reduceOnly?: boolean;
  onChange: (patch: ContractOverrides) => void;
}

export function IntentDirectionalBody({
  direction,
  sizePct,
  leverage,
  depth,
  stopLoss,
  takeProfit,
  reduceOnly,
  onChange,
}: IntentDirectionalBodyProps): JSX.Element {
  return (
    <div className="intent-directional-body">
      <div className="intent-directional-side" role="group" aria-label="Side">
        <button
          type="button"
          className={`intent-side-btn${direction === "long" ? " is-active" : ""}`}
          onClick={() => onChange({ direction: "long" })}
        >
          LONG
        </button>
        <button
          type="button"
          className={`intent-side-btn${direction === "short" ? " is-active" : ""}`}
          onClick={() => onChange({ direction: "short" })}
        >
          SHORT
        </button>
      </div>

      {depth === "simple" ? (
        <div className="intent-directional-inline-params">
          <label className="intent-param-field">
            <span className="terminal-label">Size</span>
            <input
              type="range"
              min={5}
              max={100}
              step={5}
              value={sizePct}
              onChange={(e) =>
                onChange({ sizePct: parseInt(e.target.value, 10) })
              }
            />
            <span className="intent-param-value">{sizePct}%</span>
          </label>
          <label className="intent-param-field">
            <span className="terminal-label">Lev</span>
            <select
              value={leverage}
              onChange={(e) =>
                onChange({ leverage: parseInt(e.target.value, 10) })
              }
            >
              {[1, 2, 3, 5, 10, 20].map((l) => (
                <option key={l} value={l}>
                  {l}x
                </option>
              ))}
            </select>
          </label>
        </div>
      ) : (
        <div className="intent-directional-precise-params">
          <label className="intent-param-field">
            <span className="terminal-label">Size %</span>
            <input
              type="number"
              min={1}
              max={100}
              value={sizePct}
              onChange={(e) =>
                onChange({ sizePct: parseInt(e.target.value, 10) || sizePct })
              }
            />
          </label>
          <label className="intent-param-field">
            <span className="terminal-label">Leverage</span>
            <input
              type="number"
              min={1}
              max={50}
              value={leverage}
              onChange={(e) =>
                onChange({ leverage: parseInt(e.target.value, 10) || leverage })
              }
            />
          </label>
          <label className="intent-param-field">
            <span className="terminal-label">Stop</span>
            <input
              type="number"
              placeholder="—"
              value={stopLoss ?? ""}
              onChange={(e) =>
                onChange({
                  stopLoss: e.target.value ? parseFloat(e.target.value) : null,
                })
              }
            />
          </label>
          <label className="intent-param-field">
            <span className="terminal-label">TP</span>
            <input
              type="number"
              placeholder="—"
              value={takeProfit ?? ""}
              onChange={(e) =>
                onChange({
                  takeProfit: e.target.value ? parseFloat(e.target.value) : null,
                })
              }
            />
          </label>
          <label className="intent-param-field intent-param-check">
            <input
              type="checkbox"
              checked={reduceOnly ?? false}
              onChange={(e) => onChange({ reduceOnly: e.target.checked })}
            />
            <span className="terminal-label">Reduce-only</span>
          </label>
        </div>
      )}
    </div>
  );
}
