import React, { useMemo } from "react";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { usePositions } from "../../hooks/usePositions";
import {
  buildPerformanceAccountsRows,
  buildPerpetualsOverviewRows,
} from "../../utils/portfolioPerformanceMetrics";
import PortfolioLedgerRow from "./PortfolioLedgerRow";
import PortfolioLedgerSection from "./PortfolioLedgerSection";
import "./portfolio.css";

export interface PortfolioPerformanceAccountsPanelProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  refreshInterval?: number;
}

function PortfolioPerformanceAccountsPanel({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  refreshInterval,
}: PortfolioPerformanceAccountsPanelProps): JSX.Element {
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    refreshInterval,
  });
  const { collections, spotWalletBalance } = useBucketCollections({
    baseURL,
    walletAddress,
  });
  const { positions } = usePositions({ baseURL, walletAddress });

  const accountRows = useMemo(
    () =>
      buildPerformanceAccountsRows({
        accountEquity: analytics.accountEquity,
        spotWalletBalance,
        collections,
        positions,
      }),
    [analytics.accountEquity, spotWalletBalance, collections, positions],
  );

  const perpetualsRows = useMemo(
    () => buildPerpetualsOverviewRows(collections, positions),
    [collections, positions],
  );

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section className="portfolio-ledger-panel" aria-label="Accounts">
        <div className="portfolio-ledger-panel-body portfolio-ledger-panel-body--sections">
          <PortfolioLedgerSection title="Accounts">
            {accountRows.map((row) => (
              <PortfolioLedgerRow
                key={row.label}
                label={row.label}
                value={row.value}
                valueClassName={row.valueClassName}
              />
            ))}
          </PortfolioLedgerSection>
          <PortfolioLedgerSection title="Perpetuals Overview">
            {perpetualsRows.map((row) => (
              <PortfolioLedgerRow
                key={row.label}
                label={row.label}
                value={row.value}
                valueClassName={row.valueClassName}
              />
            ))}
          </PortfolioLedgerSection>
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioPerformanceAccountsPanel);
