import React from "react";
import { createPortal } from "react-dom";

import { getAgentProfileById } from "../../../offline/mock_data";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { compareSetsEqual } from "../../utils/agentCompareSavedLists";
import type { SavedCompareList } from "../../utils/agentCompareSavedLists";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./agent.css";

export interface AgentCompareSavedListsModalProps {
  isOpen: boolean;
  onClose: () => void;
  savedLists: SavedCompareList[];
  currentCompareIds: string[];
  onRemove: (id: string) => void;
  onView: (agentIds: string[]) => void;
}

function SavedCompareListRow({
  entry,
  isCurrent,
  onRemove,
  onView,
}: {
  entry: SavedCompareList;
  isCurrent: boolean;
  onRemove: (id: string) => void;
  onView: (agentIds: string[]) => void;
}): JSX.Element {
  const profiles = entry.agentIds
    .map((id) => getAgentProfileById(id))
    .filter((profile): profile is NonNullable<typeof profile> => profile !== undefined);

  return (
    <div
      className={[
        "agent-compare-saved-list-row",
        isCurrent ? "agent-compare-saved-list-row--current" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <button
        type="button"
        className="agent-compare-saved-list-row-main"
        onClick={() => onView(entry.agentIds)}
        aria-current={isCurrent ? "true" : undefined}
      >
        <span className="agent-compare-saved-list-agents" aria-hidden>
          {profiles.map((profile) => {
            const avatarSrc = resolveAgentAvatarSvgUrl(profile.id);
            return (
              <span
                key={profile.id}
                className="agent-compare-saved-list-agent"
                title={profile.name}
              >
                <span
                  className="agent-compare-saved-list-agent-avatar"
                  style={{
                    maskImage: `url(${avatarSrc})`,
                    WebkitMaskImage: `url(${avatarSrc})`,
                  }}
                />
                <span className="agent-compare-saved-list-agent-name">{profile.name}</span>
              </span>
            );
          })}
        </span>
        <span className="agent-compare-saved-list-meta terminal-label">
          {entry.agentIds.length} agent{entry.agentIds.length === 1 ? "" : "s"}
          {isCurrent ? " · Current" : ""}
        </span>
      </button>
      <div className="agent-compare-saved-list-actions">
        <button
          type="button"
          className="agent-secondary-btn agent-compare-saved-list-view-btn"
          onClick={() => onView(entry.agentIds)}
        >
          View
        </button>
        <button
          type="button"
          className="agent-secondary-btn agent-compare-saved-list-remove-btn"
          onClick={() => onRemove(entry.id)}
          aria-label="Remove saved compare list"
        >
          Remove
        </button>
      </div>
    </div>
  );
}

function AgentCompareSavedListsModal({
  isOpen,
  onClose,
  savedLists,
  currentCompareIds,
  onRemove,
  onView,
}: AgentCompareSavedListsModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onClose);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="agent-compare-saved-lists-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="agent-compare-saved-lists-panel staggered-overlay-panel--scale"
        aria-label="Saved compare lists"
      >
        <header className="agent-compare-saved-lists-header">
          <h2 className="agent-compare-saved-lists-title">Saved compare lists</h2>
          <button
            type="button"
            className="agent-compare-saved-lists-close"
            onClick={onClose}
            aria-label="Close saved compare lists"
          >
            ×
          </button>
        </header>

        <div className="agent-compare-saved-lists-body">
          {savedLists.length === 0 ? (
            <p className="agent-compare-saved-list-empty">
              No saved compare lists yet. Use Add to my list on a comparison to save one.
            </p>
          ) : (
            savedLists.map((entry) => (
              <SavedCompareListRow
                key={entry.id}
                entry={entry}
                isCurrent={compareSetsEqual(entry.agentIds, currentCompareIds)}
                onRemove={onRemove}
                onView={onView}
              />
            ))
          )}
        </div>

        <div className="agent-compare-saved-lists-footer">
          <button type="button" className="agent-secondary-btn" onClick={onClose}>
            Close
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : modalContent;
}

export default AgentCompareSavedListsModal;
