import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type JSX,
} from "react";
import { Typewriter } from "../ui/Typewriter";
import {
  computeVisibleNewsCapacity,
  formatRelativeTime,
  MIN_X_NEWS_SEED_COUNT,
  type FeedEnterState,
  type GeneratedXNews,
} from "./xNewsExamples";
import { resolveDisplaySymbol } from "./intentExamples";
import { SEED_STAGGER_MS } from "./useXNewsStream";
import { useFlipListInsert } from "./useFlipListInsert";
import { FEED_INSERT_DURATION_MS } from "./feedAnimation";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

export interface TickerXNewsCardsProps {
  baseAsset: string;
  items: GeneratedXNews[];
  enterState: FeedEnterState | null;
  onVisibleCapacityChange: (capacity: number) => void;
  /** Overrides default `X pulse · {symbol}` header copy. */
  pulseLabel?: string;
  /** Resets typewriter state when the feed source changes (defaults to baseAsset). */
  streamKey?: string;
}

const SENTIMENT_LABEL: Record<GeneratedXNews["sentiment"], string> = {
  bull: "Bull",
  bear: "Bear",
  neutral: "Neutral",
};

/** Items newer than this get a subtle "fresh" time accent. */
const RECENT_NEWS_MS = 3 * 60 * 1000;

function isRecentNews(createdAt: number, now = Date.now()): boolean {
  return now - createdAt < RECENT_NEWS_MS;
}

export function TickerXNewsCards({
  baseAsset,
  items,
  enterState,
  onVisibleCapacityChange,
  pulseLabel,
  streamKey,
}: TickerXNewsCardsProps): JSX.Element | null {
  const listRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<Map<string, HTMLElement>>(new Map());
  const typedHeadlineIdsRef = useRef(new Set<string>());
  const [, bumpTypedState] = useState(0);

  const itemIds = items.map((item) => item.instanceId);
  const enteringId =
    enterState?.phase === "push" ? enterState.instanceId : null;

  const setFlipRef = useFlipListInsert({ itemIds, enteringId });

  const displaySymbol = resolveDisplaySymbol(baseAsset);
  const headerLabel = pulseLabel ?? `X pulse · ${displaySymbol}`;
  const resetKey = streamKey ?? baseAsset;

  useEffect(() => {
    typedHeadlineIdsRef.current.clear();
    bumpTypedState((n) => n + 1);
  }, [resetKey]);

  const setCardRef = useCallback(
    (instanceId: string) => (node: HTMLElement | null) => {
      if (node) {
        cardRefs.current.set(instanceId, node);
      } else {
        cardRefs.current.delete(instanceId);
      }
    },
    [],
  );

  const shouldTypewrite = useCallback((instanceId: string) => {
    return !typedHeadlineIdsRef.current.has(instanceId);
  }, []);

  const handleHeadlineComplete = useCallback((instanceId: string) => {
    if (typedHeadlineIdsRef.current.has(instanceId)) return;
    typedHeadlineIdsRef.current.add(instanceId);
    bumpTypedState((n) => n + 1);
  }, []);

  useLayoutEffect(() => {
    const container = listRef.current;
    if (!container) return;

    const measure = () => {
      const heights = items
        .map((item) => cardRefs.current.get(item.instanceId)?.offsetHeight)
        .filter((height): height is number => height != null && height > 0);

      const capacity = computeVisibleNewsCapacity(
        container.clientHeight,
        heights,
      );
      onVisibleCapacityChange(capacity);
    };

    measure();

    const observer = new ResizeObserver(measure);
    observer.observe(container);

    const remeasureTimeout = setTimeout(
      measure,
      MIN_X_NEWS_SEED_COUNT * SEED_STAGGER_MS + FEED_INSERT_DURATION_MS + 100,
    );

    return () => {
      observer.disconnect();
      clearTimeout(remeasureTimeout);
    };
  }, [items, enterState, onVisibleCapacityChange]);

  if (!baseAsset && !pulseLabel) return null;

  return (
    <section
      className="ticker-x-news"
      aria-label={pulseLabel ?? `X market pulse for ${displaySymbol}`}
    >
      <BubbleTip id={BUBBLE_TIP_IDS.xPulseFeed}>
        <div className="ticker-x-news-header">
          <span className="ticker-x-news-live-dot" aria-hidden="true" />
          {headerLabel}
        </div>
      </BubbleTip>
      <div
        ref={listRef}
        className="ticker-x-news-viewport"
        aria-live="polite"
      >
        {items.map((item) => {
          const isPushing =
            enterState?.instanceId === item.instanceId &&
            enterState.phase === "push";
          const isRevealing =
            enterState?.instanceId === item.instanceId &&
            enterState.phase === "reveal";
          const isRecent = isRecentNews(item.createdAt);
          const showTypewriter = shouldTypewrite(item.instanceId);
          const typewriterActive = !isPushing;

          return (
            <BubbleTip
              key={item.instanceId}
              id={BUBBLE_TIP_IDS.individualNewsItem}
            >
              <div
                ref={setFlipRef(item.instanceId)}
                className="feed-card-flip-shell"
              >
                <article
                  ref={setCardRef(item.instanceId)}
                  className={[
                    "ticker-x-news-card",
                    isPushing ? "is-push" : "",
                    isRevealing ? "is-reveal" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                >
                  <div className="ticker-x-news-card-meta">
                    <span className="ticker-x-news-handle">@{item.handle}</span>
                    <time
                      className={[
                        "terminal-value",
                        "ticker-x-news-time",
                        isRecent ? "is-recent" : "",
                      ]
                        .filter(Boolean)
                        .join(" ")}
                      dateTime={new Date(item.createdAt).toISOString()}
                    >
                      {formatRelativeTime(item.createdAt)}
                    </time>
                  </div>
                  {showTypewriter ? (
                    <Typewriter
                      text={item.headline}
                      className="ticker-x-news-headline"
                      multiline="auto"
                      active={typewriterActive}
                      onComplete={() => handleHeadlineComplete(item.instanceId)}
                    />
                  ) : (
                    <p className="ticker-x-news-headline">{item.headline}</p>
                  )}
                  <span
                    className={[
                      "ticker-x-news-sentiment",
                      `ticker-x-news-sentiment--${item.sentiment}`,
                    ].join(" ")}
                  >
                    {SENTIMENT_LABEL[item.sentiment]}
                  </span>
                </article>
              </div>
            </BubbleTip>
          );
        })}
      </div>
    </section>
  );
}
