import { getAgentTokenProfile } from "../../../offline/mock_data";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { AgentCompareFocus } from "./agentCompareFocus";
import {
  buildAgentMetricsForFocus,
  buildChange24hMetric,
  type AgentFocusMetric,
} from "./agentFocusMetrics";
import {
  formatManagedAum,
  hasAgentToken,
  humanizeBehaviorProfile,
} from "./agentHeroFocus";

export type AgentCompareMetricEntry =
  | {
      kind: "metric";
      label: string;
      value: string;
      tone?: "positive" | "negative" | "neutral";
    }
  | {
      kind: "list";
      label: string;
      items: string[];
    };

function toMetric(entry: AgentFocusMetric): AgentCompareMetricEntry {
  return {
    kind: "metric",
    label: entry.label,
    value: entry.value,
    tone: entry.tone,
  };
}

function compactEntries(
  entries: Array<AgentCompareMetricEntry | null>,
): AgentCompareMetricEntry[] {
  return entries.filter((entry): entry is AgentCompareMetricEntry => entry !== null);
}

function findStatValue(profile: PropertyProfile, label: string): string | null {
  return profile.stats.find((entry) => entry.label === label)?.value ?? null;
}

function parseDrawdownCap(profile: PropertyProfile): AgentCompareMetricEntry | null {
  const input = profile.riskInputs.find((entry) =>
    entry.toLowerCase().startsWith("drawdown:"),
  );
  if (!input) return null;
  const match = input.match(/-(\d+(?:\.\d+)?)\s*%/);
  if (!match) return null;
  return {
    kind: "metric",
    label: "Drawdown cap",
    value: `-${match[1]}%`,
    tone: "negative",
  };
}

function parseRevenueStability(profile: PropertyProfile): AgentCompareMetricEntry | null {
  const input = profile.riskInputs.find((entry) =>
    entry.toLowerCase().startsWith("revenue stability:"),
  );
  if (!input) return null;
  const match = input.match(/(\d+(?:\.\d+)?)/);
  if (!match) return null;
  return {
    kind: "metric",
    label: "Revenue stability",
    value: match[1]!,
    tone: "neutral",
  };
}

function parseMandateCap(profile: PropertyProfile): AgentCompareMetricEntry | null {
  const input = profile.riskInputs.find((entry) =>
    entry.toLowerCase().startsWith("mandate caps:"),
  );
  if (!input) return null;
  const value = input.split(":").slice(1).join(":").trim();
  if (!value) return null;
  return {
    kind: "metric",
    label: "Mandate cap",
    value,
    tone: "neutral",
  };
}

function buildLeverageMetric(profile: PropertyProfile): AgentCompareMetricEntry | null {
  if (profile.leverage == null) return null;
  return {
    kind: "metric",
    label: "Leverage",
    value: `${profile.leverage}x`,
    tone: "neutral",
  };
}

function buildAnnFundingMetric(profile: PropertyProfile): AgentCompareMetricEntry | null {
  if (profile.annFunding == null) return null;
  return {
    kind: "metric",
    label: "Ann. funding",
    value: `${profile.annFunding.toFixed(1)}%`,
    tone: "neutral",
  };
}

function buildOpenInterestMetric(profile: PropertyProfile): AgentCompareMetricEntry | null {
  if (profile.openInterest == null) return null;
  return {
    kind: "metric",
    label: "Open interest",
    value: `$${(profile.openInterest / 1_000_000).toFixed(1)}M`,
    tone: "neutral",
  };
}

function buildManagedAumMetric(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentCompareMetricEntry {
  return {
    kind: "metric",
    label: "Managed AUM",
    value: formatManagedAum(profile, fleet),
    tone: "neutral",
  };
}

function buildNetExposureMetric(profile: PropertyProfile): AgentCompareMetricEntry | null {
  const value = findStatValue(profile, "Net exposure");
  if (!value) return null;
  return {
    kind: "metric",
    label: "Net exposure",
    value,
    tone: "neutral",
  };
}

function buildWinRateMetric(fleet: FleetAgentRecord): AgentCompareMetricEntry {
  return {
    kind: "metric",
    label: "Win rate",
    value: `${fleet.winRatePct}%`,
    tone: "neutral",
  };
}

function buildMaxDdMetric(profile: PropertyProfile): AgentCompareMetricEntry | null {
  const stat = profile.stats.find((entry) => entry.label === "Max DD");
  if (!stat) return null;
  return {
    kind: "metric",
    label: "Max DD",
    value: stat.value,
    tone: stat.tone,
  };
}

function buildTokenMetrics(
  catalogAgentId: string,
  fleet: FleetAgentRecord,
): AgentCompareMetricEntry[] {
  if (!hasAgentToken(fleet)) return [];
  const tokenProfile = getAgentTokenProfile(catalogAgentId);
  if (!tokenProfile) return [];
  return compactEntries([
    {
      kind: "metric",
      label: "FDV",
      value: tokenProfile.fullyDilutedValuation,
      tone: "neutral",
    },
    tokenProfile.rank != null
      ? {
          kind: "metric",
          label: "Token rank",
          value: `#${tokenProfile.rank}`,
          tone: "neutral",
        }
      : null,
  ]);
}

export function buildComparePlaybookMetrics(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentCompareMetricEntry[] {
  const base = buildAgentMetricsForFocus("playbook", profile, fleet).map(toMetric);
  return compactEntries([
    ...base,
    {
      kind: "metric",
      label: "Behavior",
      value: humanizeBehaviorProfile(fleet.behaviorProfile),
      tone: "neutral",
    },
    {
      kind: "metric",
      label: "Risk tier",
      value: profile.riskScore,
      tone: "neutral",
    },
    {
      kind: "metric",
      label: "Context",
      value: `${profile.sector} · ${profile.product} · ${profile.perpBaseAsset}`,
      tone: "neutral",
    },
    buildLeverageMetric(profile),
    buildAnnFundingMetric(profile),
    profile.riskInputs.length > 0
      ? { kind: "list", label: "Policy", items: profile.riskInputs }
      : null,
    parseDrawdownCap(profile),
    parseRevenueStability(profile),
    parseMandateCap(profile),
  ]);
}

export function buildComparePerformanceMetrics(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentCompareMetricEntry[] {
  const statMetrics = buildAgentMetricsForFocus("playbook", profile, fleet)
    .filter((metric) =>
      ["30d PnL", "Sharpe", "All-time PnL"].includes(metric.label),
    )
    .map(toMetric);

  return compactEntries([
    ...statMetrics,
    buildMaxDdMetric(profile),
    buildWinRateMetric(fleet),
    buildNetExposureMetric(profile),
  ]);
}

export function buildCompareRiskMetrics(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentCompareMetricEntry[] {
  const base = buildAgentMetricsForFocus("trust", profile, fleet).map(toMetric);
  return compactEntries([
    ...base,
    buildManagedAumMetric(profile, fleet),
    profile.badges.length > 0
      ? { kind: "list", label: "Badges", items: profile.badges }
      : null,
    profile.receipts.length > 0
      ? { kind: "list", label: "Compliance", items: profile.receipts }
      : null,
  ]);
}

export function buildCompareScaleMetrics(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
  catalogAgentId: string,
): AgentCompareMetricEntry[] {
  const base = buildAgentMetricsForFocus("scale", profile, fleet).map(toMetric);
  return compactEntries([
    ...base,
    toMetric(buildChange24hMetric(profile)),
    {
      kind: "metric",
      label: "Volume 24H",
      value: profile.volume24h,
      tone: "neutral",
    },
    buildOpenInterestMetric(profile),
    buildAnnFundingMetric(profile),
    buildManagedAumMetric(profile, fleet),
    ...buildTokenMetrics(catalogAgentId, fleet),
  ]);
}

export function buildCompareFocusMetrics(
  focus: AgentCompareFocus,
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
  catalogAgentId: string,
): AgentCompareMetricEntry[] {
  switch (focus) {
    case "playbook":
      return buildComparePlaybookMetrics(profile, fleet);
    case "performance":
      return buildComparePerformanceMetrics(profile, fleet);
    case "risk":
      return buildCompareRiskMetrics(profile, fleet);
    case "scale":
      return buildCompareScaleMetrics(profile, fleet, catalogAgentId);
    default:
      return buildComparePerformanceMetrics(profile, fleet);
  }
}
