export type AgentCompareFocus = "playbook" | "performance" | "risk" | "scale";

export const AGENT_COMPARE_FOCUS_OPTIONS = [
  { value: "playbook", label: "Playbook", hint: "How does it trade?" },
  { value: "performance", label: "Performance", hint: "How well does it perform?" },
  { value: "risk", label: "Risk", hint: "How safe is it?" },
  { value: "scale", label: "Scale", hint: "Is it proven at size?" },
] as const satisfies ReadonlyArray<{
  value: AgentCompareFocus;
  label: string;
  hint: string;
}>;

export const DEFAULT_AGENT_COMPARE_FOCUS: AgentCompareFocus = "performance";

export const VALID_AGENT_COMPARE_FOCUSES: readonly AgentCompareFocus[] =
  AGENT_COMPARE_FOCUS_OPTIONS.map((option) => option.value);

export function isAgentCompareFocus(value: string): value is AgentCompareFocus {
  return (VALID_AGENT_COMPARE_FOCUSES as readonly string[]).includes(value);
}

export function getCompareFocusHint(focus: AgentCompareFocus): string {
  return (
    AGENT_COMPARE_FOCUS_OPTIONS.find((option) => option.value === focus)?.hint ??
    AGENT_COMPARE_FOCUS_OPTIONS[0].hint
  );
}

export function resolveCompareChartVisible(focus: AgentCompareFocus): boolean {
  return focus === "performance" || focus === "scale";
}

