export function getCompareFocusMeta(focus: AgentCompareFocus): {
  label: string;
  hint: string;
} {
  const option =
    AGENT_COMPARE_FOCUS_OPTIONS.find((entry) => entry.value === focus) ??
    AGENT_COMPARE_FOCUS_OPTIONS[0]!;
  return { label: option.label, hint: option.hint };
}

export function getCompareFocusLoadingRows(focus: AgentCompareFocus): CompareLoadingRow[] {
  switch (focus) {
    case "performance":
      return PERFORMANCE_LOADING_ROWS;
    case "scale":
      return SCALE_LOADING_ROWS;
    case "playbook":
      return PLAYBOOK_LOADING_ROWS;
    case "risk":
      return RISK_LOADING_ROWS;
    default:
      return PERFORMANCE_LOADING_ROWS;
  }
}
