import React, { useCallback, useMemo } from "react";
import { DEFAULT_BASE_URL } from "../../constants";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import MarketContextChip from "./MarketContextChip";
import RiskScoreMetric from "./RiskScoreMetric";
import GuardedModeHero from "./GuardedModeHero";
import PendingMarketPills from "./PendingMarketPills";
import { sortGuardrailIntents } from "./deckIntents";
import { compareGuardrailRisk, getGuardrailMeta } from "./guardrailMeta";
import { shouldGuardedHeroCollapse, getSafetyHeaderLayoutMode } from "./safetyAuditLogLayout";
import "./tradeAgentDeck.css";

export interface SafetyHeaderProps {
  height?: string;
  baseURL?: string;
  selectedMarketId?: string;
  onOpenTickerSelection?: () => void;
  tickerSelectionOpen?: boolean;
  selectionAnchorRef?: React.RefObject<HTMLDivElement | null>;
  containerRef?: React.RefObject<HTMLElement | null>;
  isMobile?: boolean;
  onApproveAll?: () => void;
  onRejectAll?: () => void;
  onStopActive?: () => void;
  onMarketSelect?: (marketId: string) => void;
  onSimulateAll?: () => void;
  hilPolishActive?: boolean;
  riskThreshold?: number;
  onRiskThresholdChange?: (value: number) => void;
  layoutBreakpoint?: string;
  guardedHeroExpanded?: boolean;
  onGuardedHeroExpandedChange?: (expanded: boolean) => void;
  /** @deprecated Use onStopActive */
  onKillAll?: () => void;
}

function SafetyHeader({
  height,
  baseURL = DEFAULT_BASE_URL,
  selectedMarketId = "",
  onOpenTickerSelection,
  tickerSelectionOpen = false,
  selectionAnchorRef,
  containerRef,
  isMobile = false,
  onApproveAll,
  onRejectAll,
  onStopActive,
  onMarketSelect,
  onSimulateAll,
  hilPolishActive = true,
  riskThreshold = 100,
  onRiskThresholdChange,
  onKillAll,
  layoutBreakpoint = "lg",
  guardedHeroExpanded = false,
  onGuardedHeroExpandedChange,
}: SafetyHeaderProps): JSX.Element {
  const {
    tasks,
    activeCount,
    forceExecuteAllPending,
    rejectAllPending,
    pauseActiveTasks,
    pauseTasksForAgent,
  } = useAgentTasks();

  const pendingCount = useMemo(
    () => tasks.filter((t) => t.status === "pending").length,
    [tasks],
  );

  const awaitingApprovalCount = useMemo(
    () =>
      tasks.filter((t) => t.status === "pending" || t.status === "watching")
        .length,
    [tasks],
  );

  const riskScore = Math.min(100, pendingCount * 18 + activeCount * 8);

  const simulateSummary = useMemo(() => {
    const queue = sortGuardrailIntents(tasks);
    if (queue.length === 0) return "No pending intents to simulate.";
    const sorted = [...queue].sort(compareGuardrailRisk);
    const top = getGuardrailMeta(sorted[0]!);
    return `Simulate ${queue.length} intent${queue.length === 1 ? "" : "s"}: highest risk ${top.riskImpact}, max fill ${top.expectedFillImpactBps.toFixed(1)} bps.`;
  }, [tasks]);

  const handleApproveAll = () => {
    if (onApproveAll) {
      onApproveAll();
      return;
    }
    forceExecuteAllPending("humanInLoop");
  };

  const handleRejectAll = () => {
    if (awaitingApprovalCount === 0) return;
    const confirmed = window.confirm(
      `Dismiss ${awaitingApprovalCount} intent${awaitingApprovalCount === 1 ? "" : "s"} awaiting approval?`,
    );
    if (!confirmed) return;
    if (onRejectAll) {
      onRejectAll();
      return;
    }
    rejectAllPending();
  };

  const handleStopActive = () => {
    if (onStopActive) {
      onStopActive();
      return;
    }
    if (onKillAll) {
      onKillAll();
      return;
    }
    pauseActiveTasks();
  };

  const handleSimulateAll = useCallback(() => {
    if (onSimulateAll) {
      onSimulateAll();
      return;
    }
    window.alert(simulateSummary);
  }, [onSimulateAll, simulateSummary]);

  const handleLowerRiskThreshold = useCallback(() => {
    const next = Math.max(40, riskThreshold - 10);
    onRiskThresholdChange?.(next);
  }, [riskThreshold, onRiskThresholdChange]);

  const handleKillRiskiestAgent = useCallback(() => {
    const queue = sortGuardrailIntents(tasks);
    if (queue.length === 0) return;
    const sorted = [...queue].sort(compareGuardrailRisk);
    const riskiestAgentId = sorted[0]?.agentId;
    if (!riskiestAgentId) return;
    pauseTasksForAgent(riskiestAgentId);
  }, [tasks, pauseTasksForAgent]);

  const heroCollapsible = hilPolishActive && shouldGuardedHeroCollapse(layoutBreakpoint);

  const layoutMode = useMemo(
    () => getSafetyHeaderLayoutMode(layoutBreakpoint, guardedHeroExpanded, hilPolishActive),
    [layoutBreakpoint, guardedHeroExpanded, hilPolishActive],
  );

  const isCompactActions = layoutMode !== "lg";
  const hideStatsUntilExpand = layoutMode === "collapsed";
  const ghostInCommand = layoutMode === "lg";
  const hidePendingMetric = heroCollapsible && layoutMode === "collapsed";

  const primaryActions = (
    <>
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--approve"
        onClick={handleApproveAll}
        disabled={awaitingApprovalCount === 0}
        aria-label="Approve all intents awaiting approval"
      >
        {isCompactActions ? "Approve" : "Approve All"}
      </button>
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--reject"
        onClick={handleRejectAll}
        disabled={awaitingApprovalCount === 0}
        aria-label="Reject all intents awaiting approval"
      >
        {isCompactActions ? "Reject" : "Reject All"}
      </button>
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--kill"
        onClick={handleStopActive}
        aria-label="Stop all active agents"
      >
        {isCompactActions ? "Stop" : "Stop Active"}
      </button>
    </>
  );

  const ghostActions = (
    <div className="trade-safety-header-quick-actions">
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--ghost"
        onClick={handleSimulateAll}
        disabled={awaitingApprovalCount === 0}
      >
        {isCompactActions ? "Sim" : "Simulate All"}
      </button>
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--ghost"
        onClick={handleLowerRiskThreshold}
        title={`Risk threshold ${riskThreshold}%`}
      >
        {isCompactActions ? "−Risk" : "Lower Risk Threshold"}
      </button>
      <button
        type="button"
        className="trade-safety-header-btn trade-safety-header-btn--ghost"
        onClick={handleKillRiskiestAgent}
        disabled={awaitingApprovalCount === 0}
      >
        {isCompactActions ? "Kill" : "Kill Riskiest Agent"}
      </button>
    </div>
  );

  const statsBlock = !hideStatsUntilExpand ? (
    <div className="trade-safety-header-stats">
      <RiskScoreMetric
        label="Risk score"
        score={riskScore}
        variant="compact"
      />
      {!hidePendingMetric ? (
        <div className="trade-safety-header-metric">
          <span className="trade-safety-header-label">Pending intents</span>
          <span className="trade-safety-header-value">{pendingCount}</span>
        </div>
      ) : null}
      <div className="trade-safety-header-metric">
        <span className="trade-safety-header-label">Active agents</span>
        <span className="trade-safety-header-value">{activeCount}</span>
      </div>
    </div>
  ) : null;

  return (
    <header
      ref={containerRef}
      className={[
        "trade-safety-header",
        isMobile ? "trade-safety-header--mobile" : "",
        hilPolishActive ? "trade-safety-header--hil-polish" : "",
        hilPolishActive ? `trade-safety-header--bp-${layoutBreakpoint}` : "",
      ]
        .filter(Boolean)
        .join(" ")}
      data-safety-layout={hilPolishActive ? layoutMode : undefined}
      style={{ height }}
      data-tour="welcome-safety-header"
    >
      <div className="trade-safety-header-row trade-safety-header-row--context">
        <div className="trade-safety-header-context">
          {selectedMarketId ? (
            <MarketContextChip
              baseURL={baseURL}
              selectedMarketId={selectedMarketId}
              onOpenTickerSelection={onOpenTickerSelection}
              tickerSelectionOpen={tickerSelectionOpen}
              selectionAnchorRef={selectionAnchorRef}
            />
          ) : null}
        </div>
        {hilPolishActive && onMarketSelect ? (
          <div className="trade-safety-header-pills-row">
            <PendingMarketPills
              baseURL={baseURL}
              selectedMarketId={selectedMarketId}
              onMarketSelect={onMarketSelect}
            />
          </div>
        ) : null}
      </div>

      <div className="trade-safety-header-row trade-safety-header-row--command">
        {hilPolishActive ? (
          <div className="trade-safety-header-posture">
            <GuardedModeHero
              layoutBreakpoint={layoutBreakpoint}
              expanded={guardedHeroExpanded}
              onExpandedChange={onGuardedHeroExpandedChange}
              isMobile={isMobile}
            />
          </div>
        ) : null}
        {statsBlock}
        {ghostInCommand ? (
          <div className="trade-safety-header-tools">{ghostActions}</div>
        ) : null}
        <div className="trade-safety-header-actions trade-safety-header-actions--primary">
          {primaryActions}
        </div>
      </div>

      {hilPolishActive && layoutMode === "expanded" ? (
        <div className="trade-safety-header-row trade-safety-header-row--interventions">
          {ghostActions}
        </div>
      ) : null}
    </header>
  );
}

export default React.memo(SafetyHeader);
