import {
  EXECUTION_MARKER_BORDER_WIDTH_PX,
  EXECUTION_MARKER_FILL_SIZE,
  type ChartExecutionMarker,
} from "./chartMarkers";

const CIRCLE_SHAPE_COEFF = 0.8;
const SQUARE_SHAPE_COEFF = 0.7;
/** Total diameter gap between fill and outer brand border (2px per side). */
export const EXECUTION_MARKER_BORDER_DIAMETER_GAP =
  2 * EXECUTION_MARKER_BORDER_WIDTH_PX;

/**
 * Marker size scales only while chart barSpacing is in [MIN, MAX]; outside that band
 * size plateaus (gmgn-style — avatars stop growing past max zoom-in).
 */
export const EXECUTION_MARKER_BAR_SPACING_MIN = 6;
export const EXECUTION_MARKER_BAR_SPACING_MAX = 12;

function ceiledOdd(value: number): number {
  const rounded = Math.ceil(value);
  return rounded % 2 === 0 ? rounded + 1 : rounded;
}

export function clampMarkerBarSpacing(barSpacing: number): number {
  return Math.min(
    Math.max(barSpacing, EXECUTION_MARKER_BAR_SPACING_MIN),
    EXECUTION_MARKER_BAR_SPACING_MAX,
  );
}

function scaledSize(barSpacing: number, coeff: number): number {
  return ceiledOdd(clampMarkerBarSpacing(barSpacing) * coeff);
}

function shapeCoeff(shape: ChartExecutionMarker["shape"]): number {
  return shape === "circle" ? CIRCLE_SHAPE_COEFF : SQUARE_SHAPE_COEFF;
}

/** Pixel diameter for marker fill, derived from chart bar spacing only. */
export function calculateExecutionMarkerPixelDiameter(
  barSpacing: number,
  shape: ChartExecutionMarker["shape"],
  sizeMultiplier: number,
): number {
  return scaledSize(barSpacing, sizeMultiplier * shapeCoeff(shape));
}

export function calculateExecutionMarkerDrawSizes(
  barSpacing: number,
  shape: ChartExecutionMarker["shape"],
): { borderDiameter: number; fillDiameter: number } {
  const fillDiameter = calculateExecutionMarkerPixelDiameter(
    barSpacing,
    shape,
    EXECUTION_MARKER_FILL_SIZE,
  );
  const borderDiameter = fillDiameter + EXECUTION_MARKER_BORDER_DIAMETER_GAP;
  return { borderDiameter, fillDiameter };
}

export function executionMarkerShapeMargin(barSpacing: number): number {
  return Math.max(scaledSize(barSpacing, 0.1), 3);
}
