import type {
  IntentBlockingSlot,
  IntentDeployState,
  IntentResolution,
  ResolutionSource,
  SlotConfidence,
} from "./intentResolution";

export type IntentQualification =
  | "qualified"
  | "underspecified"
  | "non-intent"
  | "reject";

export type IntentArchetype =
  | "directional"
  | "relational"
  | "portfolio"
  | "conditional"
  | "unsupported";

export type IntentWireframe = IntentArchetype;

export type IntentExecutionKind = "single" | "fanout" | "composite";

export type FacetConfidence = SlotConfidence | "multiple";

export type ObjectiveClass =
  | "open"
  | "close-reduce"
  | "hedge"
  | "rebalance-allocate"
  | "relative-value"
  | "manage-yield"
  | "unsupported";

export type StructureClass =
  | "single"
  | "basket"
  | "coupled-pair"
  | "portfolio-scope";

export type DirectionClass = "long" | "short" | "neutral" | "market-neutral";

export type TriggerClass =
  | "immediate"
  | "price-conditional"
  | "event-conditional"
  | "scheduled";

export type IntentBlockingFacet =
  | "objective"
  | "structure"
  | "subject"
  | "agent"
  | "asset"
  | "trigger"
  | null;

export interface ResolvedFacet<T> {
  confidence: FacetConfidence;
  value: T | null;
  label: string;
  source: ResolutionSource | "inferred";
  candidates?: T[];
}

export interface RiskConstraints {
  leverage?: number | null;
  sizePct?: number | null;
  stopLoss?: number | null;
  takeProfit?: number | null;
  maxDrawdown?: number | null;
  slippagePct?: number | null;
  reduceOnly?: boolean;
}

export interface CompositeLeg {
  direction: DirectionClass;
  baseAsset: string;
  marketId?: string;
}

export interface IntentFacetSlots {
  objective: ResolvedFacet<ObjectiveClass>;
  structure: ResolvedFacet<StructureClass>;
  direction: ResolvedFacet<DirectionClass>;
  trigger: ResolvedFacet<TriggerClass>;
  risk: ResolvedFacet<RiskConstraints>;
  agents: ResolvedFacet<string[]>;
  assets: ResolvedFacet<string[]>;
  scope: ResolvedFacet<string>;
}

export interface IntentExecutionModel {
  kind: IntentExecutionKind;
  groupId?: string;
  legs?: CompositeLeg[];
}

export interface IntentFacetConfidence {
  objective: FacetConfidence;
  structure: FacetConfidence;
  direction: FacetConfidence;
  trigger: FacetConfidence;
  risk: FacetConfidence;
  agents: FacetConfidence;
  assets: FacetConfidence;
  scope: FacetConfidence;
}

export interface IntentBreakdown {
  qualification: IntentQualification;
  archetype: IntentArchetype;
  wireframe: IntentWireframe;
  slots: IntentFacetSlots;
  confidence: IntentFacetConfidence;
  deployState: IntentDeployState;
  blockingFacet: IntentBlockingFacet;
  /** Legacy blocking slot for chip/ambiguity UI compatibility */
  blockingSlot: IntentBlockingSlot;
  execution: IntentExecutionModel;
  resolution: IntentResolution;
  stickyArchetype?: IntentArchetype;
  rawText: string;
  clarifyPrompt?: string;
  parkedReason?: string;
  /** True when archetype is unsupported — deploy blocked, manual path suggested */
  isParked: boolean;
}

export interface QualifyResult {
  qualification: IntentQualification;
  hasObjective: boolean;
  hasSubject: boolean;
  clarifyPrompt?: string;
  rejectReason?: string;
}

export function facetConfidenceFrom<T>(
  facet: ResolvedFacet<T>,
): FacetConfidence {
  return facet.confidence;
}

export function buildFacetConfidence(
  slots: IntentFacetSlots,
): IntentFacetConfidence {
  return {
    objective: slots.objective.confidence,
    structure: slots.structure.confidence,
    direction: slots.direction.confidence,
    trigger: slots.trigger.confidence,
    risk: slots.risk.confidence,
    agents: slots.agents.confidence,
    assets: slots.assets.confidence,
    scope: slots.scope.confidence,
  };
}
