import React, {
  type JSX,
  useCallback,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
} from "react";
import { createPortal } from "react-dom";
import { useSettings } from "../../context/SettingsContext";
import { matchesKeyboardBinding } from "../../utils/keyboardShortcuts";
import type { Market, TradingAgent } from "../../store/types";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import { replaceTokenAtCaret } from "./intentKeywords";
import { useIntentHints } from "./useIntentHints";
import type { IntentTemplateSuggestion } from "./intentKeywords";
import {
  IntentMentionAutocomplete,
  useIntentMentionKeyDown,
} from "./IntentMentionAutocomplete";
import { IntentResolutionChips } from "./IntentResolutionChips";
import { IntentExecutionContract } from "./IntentExecutionContract";
import {
  IntentAdaptiveRegion,
  IntentClarifyPrompt,
  IntentControlDepthToggle,
  useIntentMorph,
  type ControlDepth,
} from "./adaptive";
import type { IntentBreakdown } from "./intentBreakdown";
import type {
  ContractOverrides,
  ExecutionContract,
} from "./executionContract";
import { canDeployBreakdown } from "./resolveIntentBreakdown";
import type {
  IntentResolution,
  ResolvedAgent,
  ResolvedAsset,
} from "./intentResolution";
import "../../terminal.css";
import "./intentWindow.css";

const INTENT_PLACEHOLDER =
  "Describe your intent — use @ for an agent, $ for a market";

export interface IntentWindowModalProps {
  isOpen: boolean;
  onClose: () => void;
  text: string;
  onTextChange: (value: string) => void;
  validated: boolean;
  onValidate: () => void;
  onDeploy: () => void;
  baseAsset: string;
  marketSymbol?: string;
  bucketLabel?: string;
  marginMode?: string;
  agents: TradingAgent[];
  markets: Market[];
  intentResolution: IntentResolution | null;
  intentBreakdown: IntentBreakdown | null;
  executionContract: ExecutionContract | null;
  contractOverrides: ContractOverrides;
  controlDepth: ControlDepth;
  stickyArchetype?: IntentBreakdown["stickyArchetype"];
  onArchetypeOverride: (archetype: IntentBreakdown["archetype"]) => void;
  onContractOverride: (patch: ContractOverrides) => void;
  onControlDepthChange: (depth: ControlDepth) => void;
  onOpenManual?: () => void;
  deployButtonLabel: string;
  deployDisabled: boolean;
  onResolveAgent: (agent: ResolvedAgent) => void;
  onResolveAsset: (asset: ResolvedAsset) => void;
}

function insertAtCaret(
  textarea: HTMLTextAreaElement,
  insertText: string,
  replaceToken: boolean,
): { nextText: string; nextCaret: number } {
  const caret = textarea.selectionStart ?? textarea.value.length;
  if (replaceToken) {
    return replaceTokenAtCaret(textarea.value, caret, insertText);
  }
  const before = textarea.value.slice(0, caret);
  const after = textarea.value.slice(caret);
  const prefix = before.length > 0 && !/\s$/.test(before) ? " " : "";
  const nextText = `${before}${prefix}${insertText}${after}`;
  const nextCaret = before.length + prefix.length + insertText.length;
  return { nextText, nextCaret };
}

export function IntentWindowModal({
  isOpen,
  onClose,
  text,
  onTextChange,
  validated,
  onValidate,
  onDeploy,
  baseAsset,
  marketSymbol,
  bucketLabel,
  marginMode,
  agents,
  markets,
  intentResolution,
  intentBreakdown,
  executionContract,
  contractOverrides,
  controlDepth,
  stickyArchetype,
  onArchetypeOverride,
  onContractOverride,
  onControlDepthChange,
  onOpenManual,
  deployButtonLabel,
  deployDisabled,
  onResolveAgent,
  onResolveAsset,
}: IntentWindowModalProps): JSX.Element | null {
  const { settings } = useSettings();
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [caret, setCaret] = useState(0);
  const [activeSuggestion, setActiveSuggestion] = useState(0);

  const { displayedArchetype } = useIntentMorph({
    wireframe: intentBreakdown?.wireframe ?? null,
    validated,
    stickyArchetype,
  });

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onClose);

  const { detectedKeywords, chipKeywords, suggestions } = useIntentHints(
    text,
    baseAsset,
    caret,
    isOpen,
  );

  useEffect(() => {
    if (!panelOpen) return;
    const frame = requestAnimationFrame(() => {
      const el = textareaRef.current;
      if (!el) return;
      el.focus();
      const end = el.value.length;
      el.setSelectionRange(end, end);
      setCaret(end);
    });
    return () => cancelAnimationFrame(frame);
  }, [panelOpen]);

  useEffect(() => {
    setActiveSuggestion(0);
  }, [text, caret, suggestions.length]);

  const applyTextUpdate = useCallback(
    (nextText: string, nextCaret: number) => {
      onTextChange(nextText);
      requestAnimationFrame(() => {
        const el = textareaRef.current;
        if (!el) return;
        el.focus();
        el.setSelectionRange(nextCaret, nextCaret);
        setCaret(nextCaret);
      });
    },
    [onTextChange],
  );

  const handleMentionKeyDown = useIntentMentionKeyDown(
    text,
    caret,
    agents,
    markets,
    textareaRef,
    applyTextUpdate,
  );

  const handleChipClick = useCallback(
    (keyword: string) => {
      const el = textareaRef.current;
      if (!el) {
        onTextChange(text ? `${text} ${keyword}` : keyword);
        return;
      }
      const { nextText, nextCaret } = insertAtCaret(el, keyword, true);
      applyTextUpdate(nextText, nextCaret);
    },
    [applyTextUpdate, onTextChange, text],
  );

  const handleMentionTrigger = useCallback(
    (trigger: "@" | "$") => {
      const el = textareaRef.current;
      const caretPos = el?.selectionStart ?? text.length;
      if (el) {
        const { nextText, nextCaret } = insertAtCaret(el, trigger, false);
        applyTextUpdate(nextText, nextCaret);
        return;
      }
      const nextText =
        text.slice(0, caretPos) +
        (caretPos > 0 && !/\s$/.test(text.slice(0, caretPos)) ? " " : "") +
        trigger +
        text.slice(caretPos);
      applyTextUpdate(nextText, nextText.length);
    },
    [applyTextUpdate, text],
  );

  const handleSelectSuggestion = useCallback(
    (suggestion: IntentTemplateSuggestion) => {
      onTextChange(suggestion.intentText);
      requestAnimationFrame(() => {
        const el = textareaRef.current;
        if (!el) return;
        const end = suggestion.intentText.length;
        el.focus();
        el.setSelectionRange(end, end);
        setCaret(end);
      });
    },
    [onTextChange],
  );

  const handleTextareaKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (handleMentionKeyDown(e)) return;

      if (
        matchesKeyboardBinding(
          e.nativeEvent,
          settings.keyboardShortcuts.intentSubmitValidate,
        )
      ) {
        e.preventDefault();
        if (
          validated &&
          intentBreakdown &&
          canDeployBreakdown(intentBreakdown)
        ) {
          onDeploy();
          onClose();
        } else {
          void onValidate();
        }
        return;
      }

      if (e.key === "Tab" && suggestions.length > 0) {
        e.preventDefault();
        const pick = suggestions[activeSuggestion];
        if (pick) handleSelectSuggestion(pick);
        return;
      }

      if (e.key === "ArrowDown" && suggestions.length > 0) {
        e.preventDefault();
        setActiveSuggestion((prev) =>
          Math.min(prev + 1, suggestions.length - 1),
        );
        return;
      }

      if (e.key === "ArrowUp" && suggestions.length > 0) {
        e.preventDefault();
        setActiveSuggestion((prev) => Math.max(prev - 1, 0));
      }
    },
    [
      activeSuggestion,
      handleMentionKeyDown,
      handleSelectSuggestion,
      intentBreakdown,
      onClose,
      onDeploy,
      onValidate,
      settings.keyboardShortcuts.intentSubmitValidate,
      suggestions,
      validated,
    ],
  );

  if (!mounted) return null;

  const showDeploy =
    validated &&
    intentBreakdown != null &&
    canDeployBreakdown(intentBreakdown);

  const modal = (
    <StaggeredOverlayRoot className="intent-window-overlay" data-intent-window-root>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="intent-window-panel terminal-overlay-panel-shell staggered-overlay-panel--scale"
        aria-label="Agent intent composer"
      >
        <div className="intent-window-header">
          <div className="terminal-panel-title">Agent intent</div>
          <span className="intent-window-header-hint">ESC to close</span>
        </div>

        <div className="intent-window-context agent-intent-row">
          <div className="intent-window-context-item">
            <span className="terminal-label">Market</span>
            <span className="agent-intent-value">
              {marketSymbol || baseAsset || "—"}
            </span>
          </div>
          <div className="intent-window-context-item">
            <span className="terminal-label">Margin</span>
            <span className="agent-intent-value">{marginMode || "—"}</span>
          </div>
          <div className="intent-window-context-item">
            <span className="terminal-label">Bucket</span>
            <span className="agent-intent-value">{bucketLabel || "—"}</span>
          </div>
          <IntentControlDepthToggle
            depth={controlDepth}
            onChange={onControlDepthChange}
          />
        </div>

        <div className="intent-window-chip-rail" role="list">
          <button
            type="button"
            role="listitem"
            className="intent-window-chip intent-window-chip--mention"
            onClick={() => handleMentionTrigger("@")}
          >
            @ agent
          </button>
          <button
            type="button"
            role="listitem"
            className="intent-window-chip intent-window-chip--mention"
            onClick={() => handleMentionTrigger("$")}
          >
            $ market
          </button>
          {chipKeywords.map((keyword) => {
            const isMatch = detectedKeywords.some(
              (k) => k.toLowerCase() === keyword.toLowerCase(),
            );
            return (
              <button
                key={keyword}
                type="button"
                role="listitem"
                className={`intent-window-chip${isMatch ? " is-match" : ""}`}
                onClick={() => handleChipClick(keyword)}
              >
                {keyword}
              </button>
            );
          })}
        </div>

        <div className="intent-composer-field intent-composer-spine">
          <textarea
            ref={textareaRef}
            className="form-input form-input--textarea intent-window-input"
            value={text}
            onChange={(e) => {
              onTextChange(e.target.value);
              setCaret(e.target.selectionStart ?? e.target.value.length);
            }}
            onBlur={() => {
              if (text.trim()) void onValidate();
            }}
            onSelect={(e) =>
              setCaret(e.currentTarget.selectionStart ?? text.length)
            }
            onKeyUp={(e) =>
              setCaret(e.currentTarget.selectionStart ?? text.length)
            }
            onKeyDown={handleTextareaKeyDown}
            placeholder={INTENT_PLACEHOLDER}
            rows={4}
          />
          <IntentMentionAutocomplete
            text={text}
            caret={caret}
            agents={agents}
            markets={markets}
            textareaRef={textareaRef}
            onTextChange={applyTextUpdate}
          />
        </div>

        {suggestions.length > 0 ? (
          <div
            className="intent-window-suggestions"
            aria-label="Intent suggestions"
          >
            <div className="intent-window-suggestions-label">Suggestions</div>
            {suggestions.map((suggestion, index) => (
              <button
                key={suggestion.id}
                type="button"
                className={`intent-window-suggestion${index === activeSuggestion ? " is-active" : ""}`}
                onClick={() => handleSelectSuggestion(suggestion)}
              >
                <span className="intent-window-suggestion-title">
                  {suggestion.label}
                </span>
                <span className="intent-window-suggestion-summary">
                  {suggestion.summary}
                </span>
              </button>
            ))}
          </div>
        ) : null}

        {intentResolution && validated ? (
          <IntentResolutionChips resolution={intentResolution} />
        ) : null}

        {validated && intentBreakdown ? (
          <IntentAdaptiveRegion
            breakdown={intentBreakdown}
            displayedArchetype={displayedArchetype}
            depth={controlDepth}
            contractOverrides={contractOverrides}
            onArchetypeOverride={onArchetypeOverride}
            onContractOverride={onContractOverride}
            onOpenManual={onOpenManual}
          />
        ) : null}

        {validated && executionContract ? (
          <IntentExecutionContract
            contract={executionContract}
            overrides={contractOverrides}
            onOverrideChange={onContractOverride}
          />
        ) : null}

        {intentBreakdown ? (
          <IntentClarifyPrompt
            breakdown={intentBreakdown}
            onSelectAgent={onResolveAgent}
            onSelectAsset={onResolveAsset}
          />
        ) : null}

        <div className="intent-window-footer">
          <button
            type="button"
            className="intent-window-btn intent-window-btn--parse"
            disabled={!text.trim()}
            onClick={() => void onValidate()}
          >
            Re-parse
          </button>
          {showDeploy ? (
            <button
              type="button"
              className="intent-window-btn intent-window-btn--deploy"
              disabled={deployDisabled}
              onClick={() => {
                onDeploy();
                onClose();
              }}
            >
              {deployButtonLabel} ▸
            </button>
          ) : null}
          <span className="intent-window-footer-hint">Cmd+Enter</span>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return createPortal(modal, document.body);
}
