import React, { useEffect, useState } from "react";
import "./agentTasks.css";

/** Matches margin-right / transform transitions on table inset + panel slide. */
const LAYOUT_TRANSITION_MS = 400;

interface AgentRelationalOverlayProps {
  active: boolean;
  containerRef: React.RefObject<HTMLElement>;
  fromSelector: string | null;
  toSelector: string | null;
}

function AgentRelationalOverlay({
  active,
  containerRef,
  fromSelector,
  toSelector,
}: AgentRelationalOverlayProps): JSX.Element | null {
  const [pathD, setPathD] = useState<string>("");

  useEffect(() => {
    if (!active || !fromSelector || !toSelector) {
      setPathD("");
      return;
    }

    const update = () => {
      const container = containerRef.current;
      if (!container) return;

      const fromEl = container.querySelector(fromSelector);
      const toEl = container.querySelector(toSelector);
      if (!fromEl || !toEl) {
        setPathD("");
        return;
      }

      const containerRect = container.getBoundingClientRect();
      const fromRect = fromEl.getBoundingClientRect();
      const toRect = toEl.getBoundingClientRect();

      const x1 = fromRect.right - containerRect.left;
      const y1 = fromRect.top + fromRect.height / 2 - containerRect.top;
      const x2 = toRect.left - containerRect.left;
      const y2 = toRect.top + toRect.height / 2 - containerRect.top;
      const midX = (x1 + x2) / 2;

      setPathD(`M ${x1} ${y1} C ${midX} ${y1}, ${midX} ${y2}, ${x2} ${y2}`);
    };

    const container = containerRef.current;
    const observed = new Set<Element>();
    const resizeObserver = new ResizeObserver(() => update());

    const observeEl = (el: Element | null | undefined) => {
      if (el && !observed.has(el)) {
        resizeObserver.observe(el);
        observed.add(el);
      }
    };

    const bindResizeTargets = () => {
      if (!container) return;
      observeEl(container);
      observeEl(container.querySelector(".agent-task-relational-main"));
      observeEl(container.querySelector(".agent-memory-side-panel"));
      observeEl(container.querySelector(fromSelector));
      observeEl(container.querySelector(toSelector));
    };

    update();
    bindResizeTargets();

    const onTransitionEnd = (event: Event) => {
      const transitionEvent = event as TransitionEvent;
      if (
        transitionEvent.propertyName === "margin-right" ||
        transitionEvent.propertyName === "transform"
      ) {
        update();
        bindResizeTargets();
      }
    };

    const mainEl = container?.querySelector(".agent-task-relational-main");
    const panelEl = container?.querySelector(".agent-memory-side-panel");
    mainEl?.addEventListener("transitionend", onTransitionEnd);
    panelEl?.addEventListener("transitionend", onTransitionEnd);

    const onWindowResize = () => update();
    window.addEventListener("resize", onWindowResize);
    container?.addEventListener("scroll", onWindowResize, true);

    // Transform-based panel slide does not always trigger ResizeObserver.
    let rafId = 0;
    const transitionDeadline = performance.now() + LAYOUT_TRANSITION_MS;
    const tickDuringTransition = () => {
      update();
      if (performance.now() < transitionDeadline) {
        rafId = requestAnimationFrame(tickDuringTransition);
      }
    };
    rafId = requestAnimationFrame(tickDuringTransition);

    return () => {
      cancelAnimationFrame(rafId);
      resizeObserver.disconnect();
      window.removeEventListener("resize", onWindowResize);
      container?.removeEventListener("scroll", onWindowResize, true);
      mainEl?.removeEventListener("transitionend", onTransitionEnd);
      panelEl?.removeEventListener("transitionend", onTransitionEnd);
    };
  }, [active, containerRef, fromSelector, toSelector]);

  if (!active || !pathD) return null;

  return (
    <svg className="agent-relational-overlay" aria-hidden>
      <path d={pathD} />
    </svg>
  );
}

export default React.memo(AgentRelationalOverlay);
