import type { CopyAutonomyPreset } from "../../offline/mock_data/fleetCopyRelations";
import {
  addDemoCopyBucket,
  buildDemoCopyBucketId,
  MOCK_TRADING_TICKERS,
  getMockMarketIndex,
  type MockTradingTicker,
} from "../../offline/mock_data";
import type { CopyBucketDestination } from "../components/agent/copyAgentModalValidation";

export const OFFLINE_COPY_SETUP_DELAY_MS = 900;

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineCopySetupParams = {
  wallet: string;
  destination: CopyBucketDestination;
  targetCatalogAgentId: string;
  profileName: string;
  perpBaseAsset: string;
  copySizePct: number;
  autonomyPreset: CopyAutonomyPreset;
};

export type ExecuteOfflineCopySetupResult = {
  bucketId: string;
  bucketMode: "new" | "existing";
  startingMargin?: number;
};

export async function executeOfflineCopySetup(
  params: ExecuteOfflineCopySetupParams,
  options?: { setupDelayMs?: number },
): Promise<ExecuteOfflineCopySetupResult> {
  await delay(options?.setupDelayMs ?? OFFLINE_COPY_SETUP_DELAY_MS);

  const normalizedWallet = params.wallet.trim();
  const normalizedAgent = params.targetCatalogAgentId.trim().toLowerCase();
  let bucketId: string;
  let bucketMode: "new" | "existing";
  let startingMargin: number | undefined;

  if (params.destination.mode === "existing") {
    bucketId = params.destination.bucketId;
    bucketMode = "existing";
  } else {
    startingMargin = params.destination.startingMargin;
    bucketId = buildDemoCopyBucketId(normalizedWallet, normalizedAgent);
    addDemoCopyBucket(normalizedWallet, {
      bucketId,
      startingMargin,
      catalogAgentId: normalizedAgent,
    });
    bucketMode = "new";
  }

  return {
    bucketId,
    bucketMode,
    startingMargin,
  };
}
