import React, { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { usePendingOrders } from "../../hooks/usePendingOrders";
import { useFiClient } from "../../hooks/useFiClient";
import { SubscriptionClient } from "../../sdk";
import { useSubscription } from "../../context/SubscriptionContext";
import { PendingOrder as PendingOrderData } from "../../sdk/types/data";
import { useMarketStore } from "../../store";
import { useAgentTaskStore } from "../../store/agentTaskStore";
import { createErrorCopyAction } from "../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
} from "../ui/toastTask";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_PENDING_ORDERS,
  DEFAULT_MNEMONIC,
  DEFAULT_REFRESH_INTERVAL,
  SORT_DIRECTION_ASC,
  SORT_DIRECTION_DESC,
} from "../../constants";
import { isPendingOrderStatus, isScaleOrderType } from "../../sdk/utils/orderFilters";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import { cancelMockOrder } from "../../../offline/mock_data";
import {
  formatSize,
  formatPrice,
  formatCurrency,
} from "../../sdk/utils/display";
import "../smartlayout/layout.css";
import "./agentTasks.css";
import "./tradeHistory.css";
import AgentTaskDetailModal from "./AgentTaskDetailModal";
import {
  buildTaskAgentMap,
  rowMatchesFleetFilter,
} from "../../utils/agentFilter";

interface OpenOrdersProps {
  baseURL: string;
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress: string;
  mnemonic?: string;
  height?: string;
  refreshInterval?: number;
  hide_header?: boolean;
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  onRequestViewOnChart?: (marketId: string) => void;
  filterAgentIds?: string[];
}

type OpenOrderTabId = "openOrders" | "scaleOrders";
type OpenOrderSortField =
  | "time"
  | "orderType"
  | "token"
  | "side"
  | "originalSize"
  | "filledSize"
  | "price"
  | "orderValue";

type ScaleOrderSortField = OpenOrderSortField | "orders" | "avgPrice";

type SortDirection = typeof SORT_DIRECTION_ASC | typeof SORT_DIRECTION_DESC;

const OPEN_GRID =
  "1fr 0.9fr 0.8fr 0.7fr 0.9fr 0.9fr 0.8fr 0.9fr 12rem";
const SCALE_GRID =
  "1fr 0.9fr 0.8fr 0.7fr 0.7fr 0.9fr 0.9fr 0.8fr 0.8fr 0.9fr 12rem";

function formatDateTime(value?: string | number | Date | null): string {
  if (value == null || value === "") return "—";
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function getOrderTypeLabel(type: unknown): string {
  return typeof type === "string" && type ? type.replace("ORDER_TYPE_", "") : "—";
}

function OpenOrders({
  baseURL = DEFAULT_BASE_URL,
  subscriptionClient: subscriptionClientProp,
  authToken,
  walletAddress,
  mnemonic,
  height = DEFAULT_HEIGHT_PENDING_ORDERS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  hide_header = false,
  onRequestHeaderActions,
  onRequestViewOnChart,
  filterAgentIds = [],
}: OpenOrdersProps): JSX.Element {
  const signingMnemonic = mnemonic?.trim() || DEFAULT_MNEMONIC;
  const { client: contextClient } = useSubscription();
  const subscriptionClient = subscriptionClientProp ?? contextClient;
  const { orders, loading, error, refresh } = usePendingOrders({
    ...(subscriptionClient != null && { subscriptionClient }),
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });
  const { client: exchangeClient, isReady: exchangeReady } = useFiClient({
    baseURL,
    mnemonic: signingMnemonic,
  });
  const [cancelingOrderId, setCancelingOrderId] = useState<string | null>(null);
  const markets = useMarketStore((s) => s.markets);
  const selectedMarketId = useMarketStore((s) => s.selectedMarketId);
  const agentTasks = useAgentTaskStore((s) => s.tasks);
  const taskAgentMap = useMemo(() => buildTaskAgentMap(agentTasks), [agentTasks]);

  const getSymbolByMarketId = useCallback(
    (marketId: string): string | null => {
      const market = markets.find(
        (m) => m.index === marketId || m.marketIndex === marketId,
      );
      if (!market) return null;
      if (market.moniker) return market.moniker;
      if (market.symbol) return market.symbol;
      if (market.baseAsset && market.quoteAsset) {
        return `${market.baseAsset}/${market.quoteAsset}`;
      }
      return null;
    },
    [markets],
  );

  const selectedMarketSymbol = useMemo(() => {
    if (!selectedMarketId) return null;
    const market = markets.find(
      (m) => m.index === selectedMarketId || m.marketIndex === selectedMarketId,
    );
    if (!market) return null;
    if (market.moniker) return market.moniker;
    if (market.symbol) return market.symbol;
    if (market.baseAsset && market.quoteAsset) {
      return `${market.baseAsset}-${market.quoteAsset}`;
    }
    return null;
  }, [markets, selectedMarketId]);
  const [selectedAgentTaskId, setSelectedAgentTaskId] = useState<string | null>(
    null,
  );

  const selectedAgentTask = useMemo(
    () =>
      selectedAgentTaskId
        ? agentTasks.find((t) => t.id === selectedAgentTaskId) ?? null
        : null,
    [agentTasks, selectedAgentTaskId],
  );

  const [tab, setTab] = useState<OpenOrderTabId>("openOrders");
  const [marketFilterActive, setMarketFilterActive] = useState(false);
  const [sortField, setSortField] = useState<
    OpenOrderSortField | ScaleOrderSortField | null
  >("time");
  const [sortDirection, setSortDirection] = useState<SortDirection>(
    SORT_DIRECTION_DESC,
  );

  const pendingOrders = useMemo(() => {
    return orders.filter((order) => isPendingOrderStatus(String(order.status ?? "")));
  }, [orders]);

  const openOrders = useMemo(
    () =>
      pendingOrders.filter((o) => {
        const raw = o.raw as Record<string, unknown> | undefined;
        return !isScaleOrderType(raw?.orderType ?? o.type);
      }),
    [pendingOrders],
  );
  const scaleOrders = useMemo(
    () =>
      pendingOrders.filter((o) => {
        const raw = o.raw as Record<string, unknown> | undefined;
        return isScaleOrderType(raw?.orderType ?? o.type);
      }),
    [pendingOrders],
  );

  const activeOrders = tab === "openOrders" ? openOrders : scaleOrders;

  const marketFilteredOrders = useMemo(() => {
    let result = activeOrders;
    if (marketFilterActive && selectedMarketId) {
      result = result.filter(
        (order) => String(order.marketId) === String(selectedMarketId),
      );
    }
    if (filterAgentIds.length > 0) {
      result = result.filter((order) =>
        rowMatchesFleetFilter(order.agentTaskId, filterAgentIds, taskAgentMap),
      );
    }
    return result;
  }, [activeOrders, marketFilterActive, selectedMarketId, filterAgentIds, taskAgentMap]);

  const sortedOrders = useMemo(() => {
    if (!sortField) return marketFilteredOrders;
    return [...marketFilteredOrders].sort((a, b) => {
      const rawA = a.raw as Record<string, unknown> | undefined;
      const rawB = b.raw as Record<string, unknown> | undefined;
      let aValue: number | string = 0;
      let bValue: number | string = 0;
      switch (sortField) {
        case "time":
          aValue = Number(
            (a as PendingOrderData & { createdAt?: number }).createdAt ??
              rawA?.time ??
              0,
          );
          bValue = Number(
            (b as PendingOrderData & { createdAt?: number }).createdAt ??
              rawB?.time ??
              0,
          );
          break;
        case "orderType":
          aValue = getOrderTypeLabel(rawA?.orderType ?? a.type);
          bValue = getOrderTypeLabel(rawB?.orderType ?? b.type);
          break;
        case "token":
          aValue = getSymbolByMarketId(a.marketId) || `m-${a.marketId}`;
          bValue = getSymbolByMarketId(b.marketId) || `m-${b.marketId}`;
          break;
        case "side":
          aValue = a.side;
          bValue = b.side;
          break;
        case "orders":
          aValue = Number(rawA?.orders ?? rawA?.legs ?? 0);
          bValue = Number(rawB?.orders ?? rawB?.legs ?? 0);
          break;
        case "originalSize":
          aValue = Number(a.quantity ?? 0);
          bValue = Number(b.quantity ?? 0);
          break;
        case "filledSize":
          aValue = Number(a.filledQuantity ?? 0);
          bValue = Number(b.filledQuantity ?? 0);
          break;
        case "price":
          aValue = Number(a.price ?? 0);
          bValue = Number(b.price ?? 0);
          break;
        case "avgPrice":
          aValue = Number(rawA?.avgPrice ?? a.price ?? 0);
          bValue = Number(rawB?.avgPrice ?? b.price ?? 0);
          break;
        case "orderValue":
          aValue = Number(a.quantity ?? 0) * Number(a.price ?? 0);
          bValue = Number(b.quantity ?? 0) * Number(b.price ?? 0);
          break;
      }
      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === SORT_DIRECTION_ASC
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }
      return sortDirection === SORT_DIRECTION_ASC
        ? Number(aValue) - Number(bValue)
        : Number(bValue) - Number(aValue);
    });
  }, [marketFilteredOrders, sortField, sortDirection, getSymbolByMarketId]);

  const handleViewOnChart = useCallback(
    (order: PendingOrderData) => {
      if (!order.marketId) {
        toast.error("No market linked to this order");
        return;
      }
      const symbol =
        getSymbolByMarketId(order.marketId) || `m-${order.marketId}`;
      onRequestViewOnChart?.(order.marketId);
      toast.success("Chart updated", {
        description: `Switched to ${symbol}`,
      });
    },
    [onRequestViewOnChart, getSymbolByMarketId],
  );

  const handleSort = (field: OpenOrderSortField | ScaleOrderSortField) => {
    if (sortField === field) {
      setSortDirection(
        sortDirection === SORT_DIRECTION_ASC
          ? SORT_DIRECTION_DESC
          : SORT_DIRECTION_ASC,
      );
    } else {
      setSortField(field);
      setSortDirection(SORT_DIRECTION_DESC);
    }
  };

  const handleCancelOrder = async (order: PendingOrderData) => {
    const orderId = order.orderId;
    const marketId = order.marketId;

    if (!orderId) {
      const errorMsg = "Cannot cancel order without a valid order ID.";
      toast.error("Order ID is missing", {
        description: errorMsg,
        action: createErrorCopyAction(errorMsg),
      });
      return;
    }

    if (!marketId) {
      const errorMsg = "Cannot cancel order without a valid market ID.";
      toast.error("Market ID is missing", {
        description: errorMsg,
        action: createErrorCopyAction(errorMsg),
      });
      return;
    }

    if (cancelingOrderId) {
      toast.info("Cancellation in progress", {
        description: "Please wait for the current cancellation to complete.",
      });
      return;
    }

    setCancelingOrderId(orderId);

    const loadingId = toastLoading("Canceling order...", {
      description: `Canceling order ${orderId}`,
    });

    try {
      if (isOfflineMode(baseURL)) {
        const cancelled = cancelMockOrder(orderId, walletAddress);
        if (cancelled) {
          toastCompleteSuccess(loadingId, "Order canceled successfully", {
            description: `Order ${orderId} has been canceled. TX: mock-cancel-${orderId.slice(0, 8)}`,
          });
        } else {
          const errorMsg = `Order ${orderId} was not found or already canceled.`;
          toastCompleteError(loadingId, "Failed to cancel order", {
            description: errorMsg,
            action: createErrorCopyAction(errorMsg),
          });
        }
        return;
      }

      if (!exchangeClient || !exchangeReady) {
        toastCompleteError(loadingId, "Exchange client not ready", {
          description: "Please wait for the exchange client to initialize.",
          action: createErrorCopyAction("Exchange client not ready"),
        });
        return;
      }

      const response = await exchangeClient.cancelOrder({
        orderId,
        marketId,
      });

      const isSuccess =
        response.success === true ||
        response.result.success === true ||
        (response && !response.error && !response.message);

      const tx = response.txhash;
      if (isSuccess) {
        toastCompleteSuccess(loadingId, "Order canceled successfully", {
          description: `Order ${orderId} has been canceled. TX: ${tx}`,
        });
        if (refresh) {
          await refresh();
        }
      } else {
        const errorMsg =
          response?.error ||
          response?.message ||
          response?.response?.error ||
          "Failed to cancel order";
        throw new Error(errorMsg);
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error occurred";
      const fullErrorMessage = `${errorMessage}. Order ID: ${orderId}`;
      toastCompleteError(loadingId, "Failed to cancel order", {
        description: fullErrorMessage,
        duration: 6000,
        action: createErrorCopyAction(fullErrorMessage),
      });
    } finally {
      setCancelingOrderId(null);
    }
  };

  const headerActions = useMemo(
    () => (
      <>
        <div
          className={`btn-tab ${tab === "openOrders" ? "active" : ""}`}
          onClick={() => setTab("openOrders")}
        >
          Open Orders
        </div>
        <div
          className={`btn-tab ${tab === "scaleOrders" ? "active" : ""}`}
          onClick={() => setTab("scaleOrders")}
        >
          Scale Orders
        </div>
        <div
          className={`btn-tab ${marketFilterActive ? "active" : ""}${!selectedMarketId ? " is-disabled" : ""}`}
          onClick={() => {
            if (!selectedMarketId) return;
            setMarketFilterActive((prev) => !prev);
          }}
          title={
            selectedMarketId
              ? `Show ${selectedMarketSymbol ?? "selected ticker"} only`
              : "Select a ticker to filter"
          }
        >
          {selectedMarketSymbol ? `Active (${selectedMarketSymbol})` : "Active"}
        </div>
      </>
    ),
    [tab, marketFilterActive, selectedMarketId, selectedMarketSymbol],
  );

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, error, headerActions]);

  useEffect(() => {
    if (
      tab === "openOrders" &&
      (sortField === "avgPrice" || sortField === "orders")
    ) {
      setSortField("time");
    }
  }, [tab, sortField]);

  if (loading) return <MorpheumInlineLoading message="Loading open orders..." />;
  if (error) return <ErrorMessage error={error} />;

  const gridColumns = tab === "openOrders" ? OPEN_GRID : SCALE_GRID;

  const tableHeaders = (
    <>
      <TableHeaderCell
        field="time"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        left
      >
        Time
      </TableHeaderCell>
      <TableHeaderCell
        field="orderType"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        center
      >
        <TableHeaderLabel {...TABLE_HEADER_LABELS.orderType} />
      </TableHeaderCell>
      <TableHeaderCell
        field="token"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        left
      >
        Token
      </TableHeaderCell>
      <TableHeaderCell
        field="side"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        center
      >
        Side
      </TableHeaderCell>
      {tab === "scaleOrders" ? (
        <TableHeaderCell
          field="orders"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          right
        >
          Orders
        </TableHeaderCell>
      ) : null}
      <TableHeaderCell
        field="originalSize"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        right
      >
        <TableHeaderLabel {...TABLE_HEADER_LABELS.originalSize} />
      </TableHeaderCell>
      <TableHeaderCell
        field="filledSize"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        right
      >
        <TableHeaderLabel {...TABLE_HEADER_LABELS.filledSize} />
      </TableHeaderCell>
      <TableHeaderCell
        field="price"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        right
      >
        Price
      </TableHeaderCell>
      {tab === "scaleOrders" ? (
        <TableHeaderCell
          field="avgPrice"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          right
        >
          <TableHeaderLabel {...TABLE_HEADER_LABELS.avgPrice} />
        </TableHeaderCell>
      ) : null}
      <TableHeaderCell
        field="orderValue"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        right
      >
        <TableHeaderLabel {...TABLE_HEADER_LABELS.orderValue} />
      </TableHeaderCell>
      <TableHeaderCellStatic right>Actions</TableHeaderCellStatic>
    </>
  );

  return (
    <>
      <div
        className="layout-container"
        style={{
          height,
          ...(hide_header ? { borderRadius: 0, background: "transparent" } : {}),
        }}
      >
        {!hide_header && (
          <LayoutHeader title="OPEN ORDERS">{headerActions}</LayoutHeader>
        )}
        <div className="table-container shrinkable">
          <div
            className="table-header"
            style={{ gridTemplateColumns: gridColumns }}
          >
            {tableHeaders}
          </div>

          {sortedOrders.length === 0 ? (
            <EmptyMessage
              message={
                marketFilterActive && selectedMarketSymbol
                  ? tab === "openOrders"
                    ? `No open orders for ${selectedMarketSymbol}`
                    : `No scale orders for ${selectedMarketSymbol}`
                  : tab === "openOrders"
                    ? "No open orders"
                    : "No scale orders"
              }
            />
          ) : (
            sortedOrders.map((order, index) => {
              const raw = order.raw as Record<string, unknown> | undefined;
              const side = order.side || "—";
              const symbol = getSymbolByMarketId(order.marketId) || `m-${order.marketId}`;
              const ordersCount =
                tab === "scaleOrders" ? (raw?.orders ?? raw?.legs ?? 1) : null;
              const avgPrice =
                tab === "scaleOrders" ? (raw?.avgPrice ?? order.price) : null;
              const orderValue =
                Number(order.quantity || 0) * Number(order.price || 0);
              return (
                <div
                  key={`open-${order.orderId}-${index}`}
                  className={`table-row ${index % 2 === 0 ? "even" : ""}`}
                  style={{ gridTemplateColumns: gridColumns }}
                >
                  <div className="table-cell primary">
                    {formatDateTime(
                      (order as PendingOrderData & { createdAt?: number })
                        .createdAt ??
                        raw?.time ??
                        raw?.createdAt,
                    )}
                  </div>
                  <div className="table-cell center">
                    {getOrderTypeLabel(raw?.orderType ?? order.type)}
                  </div>
                  <div className="table-cell">
                    {onRequestViewOnChart && order.marketId ? (
                      <button
                        type="button"
                        className="trade-history-coin-link"
                        onClick={() => handleViewOnChart(order)}
                      >
                        {symbol}
                      </button>
                    ) : (
                      symbol
                    )}
                  </div>
                  <div className="table-cell center">{side}</div>
                  {tab === "scaleOrders" ? (
                    <div className="table-cell right">{ordersCount}</div>
                  ) : null}
                  <div className="table-cell right">
                    {formatSize(order.quantity)}
                  </div>
                  <div className="table-cell right">
                    {formatSize(order.filledQuantity)}
                  </div>
                  <div className="table-cell right">
                    {formatPrice(order.price)}
                  </div>
                  {tab === "scaleOrders" ? (
                    <div className="table-cell right">
                      {formatPrice(Number(avgPrice) || order.price)}
                    </div>
                  ) : null}
                  <div className="table-cell right">
                    {formatCurrency(orderValue)}
                  </div>
                  <div
                    className="table-row-actions agent-task-actions position-row-actions"
                    style={{ gap: "0.5rem" }}
                  >
                    {order.agentTaskId ? (
                      <button
                        type="button"
                        className="btn"
                        onClick={() =>
                          setSelectedAgentTaskId(order.agentTaskId ?? null)
                        }
                      >
                        Agent
                      </button>
                    ) : null}
                    <button
                      type="button"
                      className="btn"
                      onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        if (
                          cancelingOrderId !== order.orderId &&
                          !cancelingOrderId
                        ) {
                          handleCancelOrder(order);
                        }
                      }}
                      disabled={
                        cancelingOrderId === order.orderId ||
                        !!cancelingOrderId
                      }
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
      <AgentTaskDetailModal
        isOpen={selectedAgentTaskId != null}
        task={selectedAgentTask}
        baseURL={baseURL}
        authToken={authToken}
        onClose={() => setSelectedAgentTaskId(null)}
      />
    </>
  );
}

export default React.memo(OpenOrders);
