import React, { useState, useMemo, useEffect, useCallback } from "react";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { buildFleetBucketIds } from "../../utils/agentFilter";
import { SubscriptionClient } from "../../sdk";
import { formatCurrency, formatPercentage } from "../../sdk/utils/display";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_BUCKET_COLLECTIONS,
  DEFAULT_REFRESH_INTERVAL,
} from "../../constants";
import "../smartlayout/layout.css";
import "./bucketCollection.css";
import BucketDetailModal from "./BucketDetailModal";
import type { BucketDetailTabId } from "./bucketDetailTypes";
import { autonomyPolicyLabel } from "../tradeagent/autonomyPolicy";
import { useBucketPolicyStore } from "../../store/bucketPolicyStore";
import { Bucket, calculateRiskRatio, getDisplayMarginType, isDisplayableBucket, getBucketCollectionEmptyMessage } from "../../sdk";
import { PRE_NAVIGATE_CLEANUP_EVENT } from "../../utils/preNavigateCleanup";
import { isBucketExtractEnabled } from "../../configs/terminalLayoutConfig";
import BucketPositionsSidePanel from "./BucketPositionsSidePanel";

interface BucketCollectionsProps {
  baseURL: string;
  /** Optional: when inside SubscriptionProvider, hook uses context; pass for backward compat or when outside provider. */
  subscriptionClient?: SubscriptionClient;
  walletAddress: string;
  mnemonic: string; // Required for transfer operations
  authToken?: string;
  height?: string;
  refreshInterval?: number;
  onBucketSelect?: (bucketId: string, totalEquity: number) => void;
  /** When true, do not render LayoutHeader (e.g. when used inside TabSection). */
  hide_header?: boolean;
  /** When hide_header is true, call with the header actions node so parent can show them in a shared toolbar. */
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  /** Called when Transfer button is clicked; opens transfer modal at page level when provided. */
  onRequestOpenTransferModal?: (anchor?: HTMLElement) => void;
  /** Called when Send to Address button is clicked; opens wallet transfer modal when provided. */
  onRequestOpenWalletTransferModal?: () => void;
  /** Called when view is clicked; navigates to Positions tab filtered by bucket. */
  onRequestViewPositions?: (bucketId: string, totalEquity: number) => void;
  /** Opens cross-chain deposit when spot balance is empty. */
  onRequestFundAccount?: () => void;
  /** Starts guided deposit tour from empty spot balance state. */
  onRequestDepositTour?: () => void;
  /** When set, show only buckets linked to this agent's tasks. */
  filterAgentIds?: string[];
  /** When true, disable bucket extract side panel (phone layout). */
  isMobile?: boolean;
  /** Grid breakpoint from GridViewerLayout — extract enabled on lg/md only. */
  layoutBreakpoint?: string;
}

const BUCKET_ID_COLUMN_WIDTH = "5rem";
const BUCKET_AUTONOMY_COLUMN_WIDTH = "7rem";
const BUCKET_GRID_COLUMNS = `${BUCKET_ID_COLUMN_WIDTH} ${BUCKET_AUTONOMY_COLUMN_WIDTH} 1fr 1fr 1fr 1fr`;
const BUCKET_GRID_COLUMNS_WITH_ACTIONS = `${BUCKET_ID_COLUMN_WIDTH} ${BUCKET_AUTONOMY_COLUMN_WIDTH} 1fr 1fr 1fr 1fr 5rem`;

type SortField =
  | "marginType"
  | "usedMargin"
  | "totalEquity"
  | "riskRatio"
  | "bucketId";
type SortDirection = "asc" | "desc";

function BucketCollections({
  baseURL = DEFAULT_BASE_URL,
  subscriptionClient,
  authToken,
  walletAddress,
  mnemonic,
  height = DEFAULT_HEIGHT_BUCKET_COLLECTIONS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  onBucketSelect,
  hide_header = false,
  onRequestHeaderActions,
  onRequestOpenTransferModal,
  onRequestOpenWalletTransferModal,
  onRequestViewPositions,
  onRequestFundAccount,
  onRequestDepositTour,
  filterAgentIds = [],
  isMobile = false,
  layoutBreakpoint,
}: BucketCollectionsProps): JSX.Element {
  const extractEnabled =
    layoutBreakpoint != null
      ? isBucketExtractEnabled(isMobile, layoutBreakpoint)
      : false;
  const gridColumns = onRequestViewPositions
    ? BUCKET_GRID_COLUMNS_WITH_ACTIONS
    : BUCKET_GRID_COLUMNS;
  const {
    collections,
    loading,
    error,
    isConnected,
    refreshBucketBalance,
    spotWalletBalance,
  } = useBucketCollections({
    ...(subscriptionClient != null && { subscriptionClient }),
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });
  const { tasks } = useAgentTasks();

  const fleetBucketIds = useMemo(() => {
    if (filterAgentIds.length === 0) return null;
    return buildFleetBucketIds(tasks, filterAgentIds);
  }, [tasks, filterAgentIds]);

  // Removed debug logging for better performance

  const [sortField, setSortField] = useState<SortField | null>(null);
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");
  const [selectedBucketId, setSelectedBucketId] = useState<string>("");
  const [filterMode, setFilterMode] = useState<
    "all" | "non-zero" | "dormant" | "active"
  >("all");
  const [detailModal, setDetailModal] = useState<{
    bucketId: string;
    initialTab?: BucketDetailTabId;
  } | null>(null);
  const [extractedBucketId, setExtractedBucketId] = useState<string | null>(
    null,
  );
  const bucketPolicies = useBucketPolicyStore((s) => s.policies);
  const getBucketPolicy = useBucketPolicyStore((s) => s.getPolicy);

  const openBucketDetail = useCallback(
    (bucketId: string, initialTab: BucketDetailTabId = "overview") => {
      setExtractedBucketId(null);
      setDetailModal({ bucketId, initialTab });
    },
    [],
  );

  const closeExtractPanel = useCallback(() => {
    setExtractedBucketId(null);
  }, []);

  useEffect(() => {
    const onPreNavigate = () => {
      setDetailModal((current) => (current !== null ? null : current));
      setExtractedBucketId((current) => (current !== null ? null : current));
    };
    window.addEventListener(PRE_NAVIGATE_CLEANUP_EVENT, onPreNavigate);
    return () => {
      window.removeEventListener(PRE_NAVIGATE_CLEANUP_EVENT, onPreNavigate);
    };
  }, []);

  useEffect(() => {
    if (!extractEnabled && extractedBucketId != null) {
      setExtractedBucketId(null);
    }
  }, [extractEnabled, extractedBucketId]);

  const detailModalBucket = useMemo(() => {
    const id = detailModal?.bucketId;
    if (!id) return null;
    return collections.find((c) => c.bucketId === id) ?? null;
  }, [detailModal?.bucketId, collections]);
  // Sort and filter collections
  const sortedCollections = useMemo(() => {
    // Collections are validated in the hook; keep displayable rows only
    let validCollections = collections.filter(isDisplayableBucket);

    if (fleetBucketIds) {
      validCollections = validCollections.filter((c) =>
        fleetBucketIds.has(String(c.bucketId)),
      );
    }

    // Apply filters based on filterMode
    if (filterMode === "non-zero") {
      validCollections = validCollections.filter(
        (c) => (c.totalEquity || 0) > 0,
      );
    } else if (filterMode === "dormant") {
      validCollections = validCollections.filter(
        (c) => c.status?.toLowerCase() === "dormant",
      );
    } else if (filterMode === "active") {
      validCollections = validCollections.filter(
        (c) => c.status?.toLowerCase() === "active",
      );
    }
    // "all" mode shows all valid collections without additional filtering

    if (!sortField) {
      return validCollections;
    }

    return [...validCollections].sort((a, b) => {
      let aValue: number | string = 0;
      let bValue: number | string = 0;

      switch (sortField) {
        case "marginType":
          aValue = getDisplayMarginType(a) || "";
          bValue = getDisplayMarginType(b) || "";
          break;
        case "usedMargin":
          aValue = a.usedMargin || 0;
          bValue = b.usedMargin || 0;
          break;
        case "totalEquity":
          aValue = a.totalEquity || 0;
          bValue = b.totalEquity || 0;
          break;
        case "riskRatio":
          aValue = calculateRiskRatio(a);
          bValue = calculateRiskRatio(b);
          break;
        case "bucketId":
          aValue = a.bucketId || "";
          bValue = b.bucketId || "";
          break;
      }

      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === "asc"
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      const numA = Number(aValue);
      const numB = Number(bValue);

      return sortDirection === "asc" ? numA - numB : numB - numA;
    });
  }, [collections, sortField, sortDirection, filterMode, fleetBucketIds]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("desc");
    }
  };

  const handleRowClick = (bucketId: string, available_margin: number) => {
    if (extractEnabled && extractedBucketId === bucketId) {
      setExtractedBucketId(null);
      return;
    }
    if (
      extractEnabled &&
      extractedBucketId != null &&
      extractedBucketId !== bucketId
    ) {
      setExtractedBucketId(null);
    }
    if (onBucketSelect) {
      onBucketSelect(bucketId, available_margin);
    }
    setSelectedBucketId(bucketId);
  };

  const handleRowDoubleClick = (bucketId: string, totalEquity: number) => {
    if (!extractEnabled) return;
    setDetailModal(null);
    setExtractedBucketId(bucketId);
    onBucketSelect?.(bucketId, totalEquity);
    setSelectedBucketId(bucketId);
  };

  const handleFilterToggle = () => {
    setFilterMode((prev) => {
      // Cycle through: non-zero -> active -> dormant -> all -> non-zero
      switch (prev) {
        case "non-zero":
          return "active";
        case "active":
          return "dormant";
        case "dormant":
          return "all";
        case "all":
          return "non-zero";
        default:
          return "non-zero";
      }
    });
  };

  const headerActions = useMemo(
    () => (
      <>
        <div
          onClick={handleFilterToggle}
          className="btn-tab"
          title={
            filterMode === "non-zero"
              ? "Click to show active buckets"
              : filterMode === "active"
                ? "Click to show dormant buckets"
                : filterMode === "dormant"
                  ? "Click to show all buckets"
                  : "Click to show non-zero balance buckets"
          }
        >
          <span>
            {filterMode === "all"
              ? "All"
              : filterMode === "non-zero"
                ? "Non-Zero"
                : filterMode === "dormant"
                  ? "Dormant"
                  : "Active"}
          </span>
        </div>
        <div
          onClick={(e) => onRequestOpenTransferModal?.(e.currentTarget)}
          className="btn-tab"
          style={{ cursor: onRequestOpenTransferModal ? "pointer" : undefined }}
        >
          <span>Transfer</span>
        </div>
        {onRequestOpenWalletTransferModal && (
          <div
            onClick={() => onRequestOpenWalletTransferModal()}
            className="btn-tab"
            style={{ cursor: "pointer" }}
          >
            <span>Send to Address</span>
          </div>
        )}
        {!isConnected && (
          <div
            onClick={async () => {
              if (refreshBucketBalance) {
                await refreshBucketBalance();
              }
            }}
            className="btn-tab"
            style={{
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
            title="WebSocket disconnected - Click to refresh bucket collections"
          >
            <img
              src="/caution-icy.svg"
              alt="Warning"
              style={{ width: "1rem", height: "1rem" }}
            />
            <span>Refresh</span>
          </div>
        )}
      </>
    ),
    [
      filterMode,
      handleFilterToggle,
      onRequestOpenTransferModal,
      onRequestOpenWalletTransferModal,
      isConnected,
      refreshBucketBalance,
    ],
  );

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, error, headerActions]);

  // Only show loading message on initial load when there's no data yet
  if (loading && collections.length === 0) {
    return <MorpheumInlineLoading message="Loading bucket collections..." />;
  }

  if (error) {
    return <ErrorMessage error={error} />;
  }

  return (
    <div
      className="layout-container"
      style={{
        height,
        ...(hide_header
          ? { borderRadius: 0, background: "transparent" }
          : {}),
      }}
    >
      {!hide_header && (
        <LayoutHeader title="BUCKET COLLECTIONS">{headerActions}</LayoutHeader>
      )}

      <div
        className={`bucket-collection-relational-root${extractedBucketId ? " is-panel-open" : ""}`}
        style={
          {
            "--bucket-table-col1-width": BUCKET_ID_COLUMN_WIDTH,
            "--bucket-table-col2-width": BUCKET_AUTONOMY_COLUMN_WIDTH,
          } as React.CSSProperties
        }
      >
        <div className="bucket-collection-relational-main">
      {/* Table */}
      <div className="table-container shrinkable bucket-collection-table">
        {/* Table Header */}
        <div
          className="table-header"
          style={{ gridTemplateColumns: gridColumns }}
        >
          <TableHeaderCell
            field="bucketId"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.bucketId} />
          </TableHeaderCell>
          <TableHeaderCellStatic center>Autonomy</TableHeaderCellStatic>
          <TableHeaderCell
            field="marginType"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.marginType} />
          </TableHeaderCell>
          <TableHeaderCell
            field="usedMargin"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.usedMargin} />
          </TableHeaderCell>
          <TableHeaderCell
            field="totalEquity"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.totalEquity} />
          </TableHeaderCell>
          <TableHeaderCell
            field="riskRatio"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.riskRatio} />
          </TableHeaderCell>
          {onRequestViewPositions && (
            <TableHeaderCellStatic center>Actions</TableHeaderCellStatic>
          )}
        </div>
        {/* Table Body */}
        {spotWalletBalance <= 0 && onRequestFundAccount ? (
          <div className="message empty" style={{ padding: "1.5rem", textAlign: "center" }}>
            <p>Your spot balance is 0.</p>
            <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "0.5rem", marginTop: "0.75rem" }}>
              <button
                type="button"
                className="btn btn-primary"
                onClick={onRequestFundAccount}
              >
                Fund account →
              </button>
              {onRequestDepositTour ? (
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={onRequestDepositTour}
                >
                  Guided deposit
                </button>
              ) : null}
            </div>
          </div>
        ) : sortedCollections.length === 0 ? (
          <EmptyMessage
            message={getBucketCollectionEmptyMessage(
              collections,
              sortedCollections.length,
              filterMode,
            )}
          />
        ) : (
          sortedCollections.map((collection: Bucket, index: number) => {
            const riskRatio = calculateRiskRatio(collection);
            const displayMarginType = getDisplayMarginType(collection);
            const policy =
              bucketPolicies[collection.bucketId] ??
              getBucketPolicy(collection.bucketId);
            const autonomyLabel = autonomyPolicyLabel(policy);
            const autonomyTone = policy.preset === "highAgency" ? "high" : policy.preset === "manual" ? "manual" : autonomyLabel.toLowerCase();
            const handsOff = policy.preset === "highAgency";
            const isRowSelected =
              selectedBucketId === collection.bucketId ||
              extractedBucketId === collection.bucketId;
            return (
              <div
                key={`collection-${collection.bucketId}-${index}`}
                onClick={() =>
                  handleRowClick(
                    collection.bucketId,
                    collection.availableMargin,
                  )
                }
                {...(extractEnabled
                  ? {
                      onDoubleClick: () =>
                        handleRowDoubleClick(
                          collection.bucketId,
                          collection.totalEquity ?? 0,
                        ),
                    }
                  : {})}
                className={`table-row clickable ${index % 2 === 0 ? "even" : ""} ${isRowSelected ? "selected" : ""}${extractedBucketId === collection.bucketId ? " bucket-row--extracted" : ""}`}
                style={{ gridTemplateColumns: gridColumns }}
                title={
                  extractEnabled
                    ? "Double-click to view positions for this bucket"
                    : undefined
                }
              >
                <div
                  className="table-cell primary bucket-collection-id-cell"
                  title={collection.bucketId || undefined}
                >
                  {collection.bucketId
                    ? collection.bucketId.slice(0, 6)
                    : "---"}
                </div>
                <div className="table-cell center bucket-collection-autonomy-cell">
                  <button
                    type="button"
                    className={`bucket-autonomy-pill bucket-autonomy-pill--${autonomyTone}`}
                    title={`${autonomyLabel} autonomy — open bucket rules`}
                    onClick={(e) => {
                      e.stopPropagation();
                      openBucketDetail(collection.bucketId, "rules");
                    }}
                  >
                    {handsOff ? (
                      <span className="bucket-autonomy-pill-warn" aria-hidden>
                        ⚡
                      </span>
                    ) : null}
                    {autonomyLabel}
                  </button>
                </div>
                <div className="table-cell">
                  {displayMarginType.toUpperCase()}
                </div>
                <div className="table-cell right">
                  {formatCurrency(collection.usedMargin || 0)}
                </div>
                <div className="table-cell right">
                  {formatCurrency(collection.totalEquity || 0)}
                </div>
                <div
                  className={`table-cell right ${riskRatio > 0.5 ? "terminal-short" : "terminal-long"}`}
                  style={{ fontWeight: 500 }}
                >
                  {formatPercentage(riskRatio)}
                </div>
                {onRequestViewPositions && (
                  <div className="table-row-actions bucket-collection-actions">
                    <button
                      type="button"
                      className="btn"
                      onClick={(e) => {
                        e.stopPropagation();
                        openBucketDetail(collection.bucketId, "overview");
                      }}
                    >
                      detail
                    </button>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
        </div>

        <BucketPositionsSidePanel
          isOpen={extractedBucketId != null}
          bucketId={extractedBucketId}
          baseURL={baseURL}
          subscriptionClient={subscriptionClient}
          authToken={authToken}
          walletAddress={walletAddress}
          mnemonic={mnemonic}
          refreshInterval={refreshInterval}
          filterAgentIds={filterAgentIds}
          onClose={closeExtractPanel}
        />
      </div>

      <BucketDetailModal
        isOpen={detailModal != null}
        bucketId={detailModal?.bucketId ?? null}
        bucket={detailModalBucket}
        initialTab={detailModal?.initialTab}
        baseURL={baseURL}
        authToken={authToken}
        walletAddress={walletAddress}
        mnemonic={mnemonic}
        onClose={() => setDetailModal(null)}
        onSaved={() => refreshBucketBalance()}
        onRequestViewPositions={onRequestViewPositions}
      />
    </div>
  );
}

export default React.memo(BucketCollections);
