import React, { useMemo } from "react";

import type { IndexShareConstituentSlice } from "./indexShareData";

export interface IndexShareConstituentsProps {
  slices: IndexShareConstituentSlice[];
}

function buildDonutStyle(
  slices: IndexShareConstituentSlice[],
): React.CSSProperties {
  const total = slices.reduce((sum, slice) => sum + slice.weight, 0);
  if (total <= 0) return {};
  let cursor = 0;
  const stops = slices.map((slice) => {
    const pct = (slice.weight / total) * 100;
    const start = cursor;
    cursor += pct;
    return `${slice.color} ${start}% ${cursor}%`;
  });
  return { background: `conic-gradient(${stops.join(", ")})` };
}

function IndexShareConstituents({
  slices,
}: IndexShareConstituentsProps): JSX.Element {
  const donutStyle = useMemo(() => buildDonutStyle(slices), [slices]);

  return (
    <div className="index-share-constituents">
      <h3 className="index-share-section-title">Constituent Weights</h3>
      <div className="index-share-constituents-body">
        <ul className="index-share-constituent-list">
          {slices.map((slice) => (
            <li key={slice.ticker} className="index-share-constituent-row">
              <span
                className="index-share-constituent-bar"
                style={{ background: slice.color }}
                aria-hidden
              />
              <span className="index-share-constituent-icon">{slice.icon}</span>
              <span className="index-share-constituent-name">{slice.name}</span>
              <span className="index-share-constituent-weight">
                {slice.weight.toFixed(1)}%
              </span>
            </li>
          ))}
        </ul>
        <div className="index-share-donut-wrap">
          <div
            className="index-share-donut"
            style={donutStyle}
            aria-hidden
          />
          <div className="index-share-donut-center">MAEX</div>
        </div>
      </div>
    </div>
  );
}

export default IndexShareConstituents;
