import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { toast } from "sonner";
import { createToastStepTracker } from "../../mormv1/components/ui/toastTask";
import { isOfflineMode } from "../../mormv1/sdk/utils/onboardMock";
import {
  generateOfflinePortfolioProgressive,
  hydrateOfflinePortfolioFromStorage,
  hasOfflinePortfolioInStorage,
  normalizeOfflineWallet,
  resolvePortfolioWallet,
  resetOfflinePortfolio,
} from "../mock_data/offlinePortfolio";
import {
  getOfflinePortfolioManifestCounts,
  loadPortfolioManifest,
} from "../mock_data/offlinePortfolioStorage";
import { isJellyOverrideActive } from "../mock_data/jellyevent";

const ONBOARD_WALLET_KEY = "onboard_wallet_address";

export type OfflinePortfolioStatus = "idle" | "loading" | "ready" | "error";

export type OfflinePortfolioContextValue = {
  status: OfflinePortfolioStatus;
  portfolioReady: boolean;
  version: number;
  activeWallet: string | null;
  initializeForMnemonicConnect: (address: string) => Promise<void>;
  resetPortfolio: (wallet?: string | null) => void;
};

const OfflinePortfolioContext = createContext<OfflinePortfolioContextValue | null>(
  null,
);

function readPersistedWalletAddress(): string {
  if (typeof localStorage === "undefined") return "";
  return localStorage.getItem(ONBOARD_WALLET_KEY)?.trim() ?? "";
}

function formatRecoveryDescription(
  counts: NonNullable<ReturnType<typeof getOfflinePortfolioManifestCounts>>,
): string {
  return [
    `${counts.bucketIds} buckets`,
    `${counts.positions} positions`,
    `${counts.openOrders} open orders`,
    `${counts.orderHistory} history`,
    `${counts.fundingHistory} funding`,
    `${counts.agentTasks} agent tasks`,
  ].join(" · ");
}

function showRecoveryToast(wallet: string): void {
  const counts = getOfflinePortfolioManifestCounts(wallet);
  if (!counts) {
    toast.success("Demo portfolio restored from local storage");
    return;
  }
  const manifest = loadPortfolioManifest(normalizeOfflineWallet(wallet));
  const sizeKb =
    manifest?.totalBytes != null
      ? ` (~${Math.round(manifest.totalBytes / 1024)} KB)`
      : "";
  toast.success(`Demo portfolio restored${sizeKb}`, {
    description: formatRecoveryDescription(counts),
  });
}

export type OfflinePortfolioProviderProps = {
  children: ReactNode;
  /** Connected wallet from useOnboard when available. */
  walletAddress?: string | null;
};

export function OfflinePortfolioProvider({
  children,
  walletAddress,
}: OfflinePortfolioProviderProps): JSX.Element {
  const [status, setStatus] = useState<OfflinePortfolioStatus>("idle");
  const [version, setVersion] = useState(0);
  const [activeWallet, setActiveWallet] = useState<string | null>(null);
  const initInFlightRef = useRef(false);
  const recoveredWalletRef = useRef<string | null>(null);

  const bumpReady = useCallback((wallet: string) => {
    setActiveWallet(normalizeOfflineWallet(wallet));
    setStatus("ready");
    setVersion((v) => v + 1);
  }, []);

  const tryRecoverWallet = useCallback(
    (address: string, showToast: boolean): boolean => {
      const normalized = resolvePortfolioWallet(address);
      if (!normalized) return false;
      if (!hasOfflinePortfolioInStorage(normalized)) return false;
      const portfolio = hydrateOfflinePortfolioFromStorage(normalized);
      if (!portfolio) return false;
      bumpReady(normalized);
      if (showToast) showRecoveryToast(normalized);
      return true;
    },
    [bumpReady],
  );

  useEffect(() => {
    const effectiveWallet =
      walletAddress?.trim() || readPersistedWalletAddress();
    if (!effectiveWallet) {
      if (!initInFlightRef.current) {
        setStatus("idle");
        setActiveWallet(null);
        recoveredWalletRef.current = null;
      }
      return;
    }

    const normalized = resolvePortfolioWallet(effectiveWallet);
    if (!normalized) return;
    if (initInFlightRef.current || recoveredWalletRef.current === normalized) {
      return;
    }

    if (tryRecoverWallet(normalized, true)) {
      recoveredWalletRef.current = normalized;
    }
  }, [walletAddress, tryRecoverWallet]);

  const initializeForMnemonicConnect = useCallback(
    async (address: string) => {
      if (initInFlightRef.current) return;
      initInFlightRef.current = true;
      const normalized = normalizeOfflineWallet(address);

      let stepTracker = createToastStepTracker();

      try {
        if (hasOfflinePortfolioInStorage(normalized)) {
          const portfolio = hydrateOfflinePortfolioFromStorage(normalized);
          if (portfolio) {
            recoveredWalletRef.current = normalized;
            showRecoveryToast(normalized);
            bumpReady(normalized);
            return;
          }
        }

        setStatus("loading");
        setActiveWallet(normalized);
        stepTracker = createToastStepTracker();

        await generateOfflinePortfolioProgressive(normalized, {
          onStepStart: (step) => {
            stepTracker.start(
              step.id,
              step.loadingMessage,
              `offline-pf:${step.id}`,
            );
          },
          onStepComplete: (step, count) => {
            stepTracker.succeed(step.id, step.successMessage(count));
          },
        });

        stepTracker.dismissAll();

        const manifest = loadPortfolioManifest(normalized);
        const sizeLabel =
          manifest?.totalBytes != null
            ? ` (~${Math.round(manifest.totalBytes / 1024)} KB stored)`
            : "";
        toast.success(`Demo portfolio saved locally${sizeLabel}`);

        recoveredWalletRef.current = normalized;
        bumpReady(normalized);
      } catch (error) {
        stepTracker.dismissAll();
        resetOfflinePortfolio(normalized);
        setStatus("error");
        setActiveWallet(null);
        const message =
          error instanceof Error ? error.message : "Portfolio generation failed";
        toast.error("Failed to build demo portfolio", { description: message });
        throw error;
      } finally {
        initInFlightRef.current = false;
      }
    },
    [bumpReady],
  );

  const resetPortfolio = useCallback(
    (wallet?: string | null) => {
      const target = wallet?.trim()
        ? resolvePortfolioWallet(wallet)
        : activeWallet;
      if (target) {
        resetOfflinePortfolio(target);
      } else {
        resetOfflinePortfolio();
      }
      recoveredWalletRef.current = null;
      setStatus("idle");
      setActiveWallet(null);
      setVersion((v) => v + 1);
    },
    [activeWallet],
  );

  const value = useMemo<OfflinePortfolioContextValue>(
    () => ({
      status,
      portfolioReady: status === "ready" && activeWallet != null,
      version,
      activeWallet,
      initializeForMnemonicConnect,
      resetPortfolio,
    }),
    [status, version, activeWallet, initializeForMnemonicConnect, resetPortfolio],
  );

  return (
    <OfflinePortfolioContext.Provider value={value}>
      {children}
    </OfflinePortfolioContext.Provider>
  );
}

export function useOfflinePortfolio(): OfflinePortfolioContextValue {
  const ctx = useContext(OfflinePortfolioContext);
  if (!ctx) {
    throw new Error(
      "useOfflinePortfolio must be used within OfflinePortfolioProvider",
    );
  }
  return ctx;
}

export function useOptionalOfflinePortfolio(): OfflinePortfolioContextValue | null {
  return useContext(OfflinePortfolioContext);
}

/** Gate standard offline mock data until mnemonic portfolio is ready. */
export function useStandardOfflinePortfolioReady(
  baseURL: string,
  isJellyMode: boolean,
  configWallet?: string | null,
): { ready: boolean; version: number; activeWallet: string | null } {
  const ctx = useOptionalOfflinePortfolio();

  if (!isOfflineMode(baseURL) || isJellyOverrideActive(baseURL, isJellyMode)) {
    return { ready: true, version: 0, activeWallet: null };
  }

  const activeWallet = ctx?.activeWallet ?? null;
  const configNormalized = resolvePortfolioWallet(configWallet);
  const ready =
    ctx?.portfolioReady === true &&
    activeWallet != null &&
    (configNormalized == null || configNormalized === activeWallet);

  return {
    ready,
    version: ctx?.version ?? 0,
    activeWallet,
  };
}
