import React, { useMemo } from "react";

import type { IndexPerformanceMetrics } from "../../../offline/mock_data/types";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import { buildIndexPerformanceMetricDefinitions } from "../../utils/indexPerformanceMetrics";
import CompactMetricCell from "../metrics/CompactMetricCell";
import "./index.css";

export interface IndexPerformanceMetricsBarProps {
  height?: string;
  metrics: IndexPerformanceMetrics;
  sparkline: number[];
}

type MetricKey = keyof IndexPerformanceMetrics;

interface MetricCellConfig {
  label: string;
  key: MetricKey;
  tipId?: (typeof BUBBLE_TIP_IDS)[keyof typeof BUBBLE_TIP_IDS];
}

const METRIC_CELLS: MetricCellConfig[] = [
  { label: "24H Change", key: "change24h", tipId: BUBBLE_TIP_IDS.change24h },
  { label: "7D ROI", key: "roi7d" },
  { label: "1M ROI", key: "roi1m" },
  { label: "3M ROI", key: "roi3m" },
  { label: "1Y ROI", key: "roi1y", tipId: BUBBLE_TIP_IDS.indexRoi1y },
  { label: "YTD", key: "roiYtd", tipId: BUBBLE_TIP_IDS.indexRoiYtd },
  {
    label: "1Y ROI vs. BTC",
    key: "roi1yVsBtc",
    tipId: BUBBLE_TIP_IDS.indexRoi1yVsBtc,
  },
];

function MetricLabel({
  label,
  tipId,
}: {
  label: string;
  tipId?: (typeof BUBBLE_TIP_IDS)[keyof typeof BUBBLE_TIP_IDS];
}): JSX.Element {
  const labelClassName = tipId
    ? "index-performance-metric-label index-performance-metric-label--tip"
    : "index-performance-metric-label";

  if (tipId) {
    return (
      <BubbleTip id={tipId}>
        <span className={labelClassName}>{label}</span>
      </BubbleTip>
    );
  }

  return <span className={labelClassName}>{label}</span>;
}

function IndexPerformanceMetricsBar({
  height = "100%",
  metrics,
  sparkline,
}: IndexPerformanceMetricsBarProps): JSX.Element {
  const definitionsById = useMemo(() => {
    const definitions = buildIndexPerformanceMetricDefinitions(
      metrics,
      sparkline,
    );
    return Object.fromEntries(definitions.map((definition) => [definition.id, definition]));
  }, [metrics, sparkline]);

  return (
    <div
      className="index-slot index-header-band index-header-band--metrics index-performance-metrics-bar"
      style={{ height }}
      aria-label="Index performance metrics"
    >
      <div className="index-performance-metrics-bar-inner">
        {METRIC_CELLS.map(({ label, key, tipId }) => (
          <div key={key} className="index-performance-metric">
            <CompactMetricCell
              layout="background"
              metric={definitionsById[key]!}
              labelNode={<MetricLabel label={label} tipId={tipId} />}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default IndexPerformanceMetricsBar;
