import type { Market, TradingAgent } from "../../store/types";
import {
  buildFacetConfidence,
  type IntentArchetype,
  type IntentBlockingFacet,
  type IntentBreakdown,
  type IntentExecutionModel,
} from "./intentBreakdown";
import {
  classifyFacets,
  deriveArchetype,
  deriveCompositeLegs,
  extractNlAssets,
} from "./intentClassify";
import { qualifyIntent, isUnsupportedObjective } from "./intentQualify";
import {
  applyAgentToResolution,
  applyAssetToResolution,
  computeDeployState,
  resolveIntent,
  type IntentDeployState,
  type IntentResolution,
  type IntentResolutionContext,
  type ResolveIntentInput,
} from "./intentResolution";

export interface ResolveIntentBreakdownInput extends ResolveIntentInput {
  stickyArchetype?: IntentArchetype;
  bucketLabel?: string;
}

function blockingSlotFromFacet(
  facet: IntentBlockingFacet,
): import("./intentResolution").IntentBlockingSlot {
  if (facet === "agent") return "agent";
  if (facet === "asset" || facet === "subject") return "asset";
  return null;
}

function computeDeployStateV2(
  breakdown: Pick<
    IntentBreakdown,
    "qualification" | "archetype" | "slots" | "resolution" | "isParked"
  >,
): {
  deployState: IntentDeployState;
  blockingFacet: IntentBlockingFacet;
} {
  const { qualification, archetype, slots, resolution, isParked } = breakdown;

  if (qualification === "reject" || qualification === "non-intent") {
    return { deployState: "resolve", blockingFacet: "objective" };
  }

  if (qualification === "underspecified") {
    if (!slots.objective.value) {
      return { deployState: "resolve", blockingFacet: "objective" };
    }
    return { deployState: "resolve", blockingFacet: "subject" };
  }

  if (isParked || archetype === "unsupported") {
    return { deployState: "resolve", blockingFacet: null };
  }

  if (slots.objective.confidence === "missing") {
    return { deployState: "resolve", blockingFacet: "objective" };
  }

  if (
    slots.assets.confidence === "missing" ||
    slots.assets.confidence === "ambiguous"
  ) {
    return { deployState: "resolve", blockingFacet: "subject" };
  }

  if (slots.assets.confidence === "multiple") {
    return { deployState: "resolve", blockingFacet: "subject" };
  }

  if (
    slots.trigger.confidence === "ambiguous" &&
    slots.trigger.value !== "immediate"
  ) {
    return { deployState: "resolve", blockingFacet: "trigger" };
  }

  const agentBlocks =
    resolution.agent.confidence === "ambiguous" ||
    resolution.agent.confidence === "missing";
  if (agentBlocks) {
    return { deployState: "resolve", blockingFacet: "agent" };
  }

  const assetBlocks =
    resolution.asset.confidence === "ambiguous" ||
    resolution.asset.confidence === "missing";
  if (assetBlocks) {
    return { deployState: "resolve", blockingFacet: "asset" };
  }

  const riskDefaulted =
    slots.risk.confidence === "defaulted" ||
    (slots.risk.value?.leverage == null && slots.risk.value?.sizePct == null);
  const slotDefaulted =
    resolution.agent.confidence === "defaulted" ||
    resolution.asset.confidence === "defaulted";

  if (riskDefaulted || slotDefaulted) {
    return { deployState: "review", blockingFacet: null };
  }

  const legacy = computeDeployState(resolution.agent, resolution.asset);
  if (legacy.deployState === "review") {
    return { deployState: "review", blockingFacet: null };
  }

  return { deployState: "deploy", blockingFacet: null };
}

function deriveExecution(
  slots: IntentBreakdown["slots"],
  text: string,
): IntentExecutionModel {
  const tickers = slots.assets.value ?? extractNlAssets(text);

  if (slots.structure.value === "coupled-pair" && tickers.length >= 2) {
    return {
      kind: "composite",
      legs: deriveCompositeLegs(text, tickers),
    };
  }

  if (
    slots.structure.value === "basket" ||
    (slots.assets.confidence === "multiple" && tickers.length > 1)
  ) {
    return {
      kind: "fanout",
      groupId: crypto.randomUUID(),
    };
  }

  if (slots.structure.value === "portfolio-scope") {
    return {
      kind: "fanout",
      groupId: crypto.randomUUID(),
    };
  }

  return { kind: "single" };
}

function emptyBreakdown(
  text: string,
  qualification: IntentBreakdown["qualification"],
  clarifyPrompt?: string,
  rejectReason?: string,
): IntentBreakdown {
  const resolution = resolveIntent({
    text,
    agents: [],
    markets: [],
    context: {
      defaultAgentId: null,
      defaultMarketId: null,
      chartMarketId: null,
    },
  });

  const emptySlots = classifyFacets(text, [], undefined);

  return {
    qualification,
    archetype: "directional",
    wireframe: "directional",
    slots: emptySlots,
    confidence: buildFacetConfidence(emptySlots),
    deployState: "resolve",
    blockingFacet: qualification === "reject" ? "objective" : "subject",
    blockingSlot: "asset",
    execution: { kind: "single" },
    resolution,
    rawText: text,
    clarifyPrompt,
    parkedReason: rejectReason,
    isParked: false,
  };
}

export function resolveIntentBreakdown(
  input: ResolveIntentBreakdownInput,
): IntentBreakdown {
  const { text, agents, markets, context, stickyArchetype, bucketLabel } =
    input;
  const trimmed = text.trim();

  const qualify = qualifyIntent(trimmed);

  if (qualify.qualification === "reject") {
    return {
      ...emptyBreakdown(trimmed, "reject", undefined, qualify.rejectReason),
      parkedReason: qualify.rejectReason,
    };
  }

  if (qualify.qualification === "non-intent") {
    return emptyBreakdown(trimmed, "non-intent");
  }

  const slots = classifyFacets(trimmed, agents, bucketLabel);
  const resolution = resolveIntent({ text: trimmed, agents, markets, context });

  const archetype = deriveArchetype(
    slots.objective.value,
    slots.structure.value,
    slots.trigger.value,
    stickyArchetype,
  );

  const isParked =
    archetype === "unsupported" || isUnsupportedObjective(trimmed);

  const parkedReason = isParked
    ? "Liquidity provision, yield, and options strategies are not supported via intent deploy. Use the Manual order form."
    : undefined;

  const wireframe = isParked ? "unsupported" : archetype;

  const execution = deriveExecution(slots, trimmed);

  const partial: IntentBreakdown = {
    qualification: qualify.qualification,
    archetype,
    wireframe,
    slots,
    confidence: buildFacetConfidence(slots),
    deployState: "resolve",
    blockingFacet: null,
    blockingSlot: null,
    execution,
    resolution,
    stickyArchetype,
    rawText: trimmed,
    clarifyPrompt: qualify.clarifyPrompt,
    parkedReason,
    isParked,
  };

  const { deployState, blockingFacet } = computeDeployStateV2(partial);

  return {
    ...partial,
    deployState,
    blockingFacet,
    blockingSlot: blockingSlotFromFacet(blockingFacet),
  };
}

export function applyAgentToBreakdown(
  breakdown: IntentBreakdown,
  agent: import("./intentResolution").ResolvedAgent,
  chartMarketId: string | null,
): IntentBreakdown {
  const resolution = applyAgentToResolution(breakdown.resolution, agent);
  const next = { ...breakdown, resolution };
  const { deployState, blockingFacet } = computeDeployStateV2(next);
  return {
    ...next,
    deployState,
    blockingFacet,
    blockingSlot: blockingSlotFromFacet(blockingFacet),
  };
}

export function applyAssetToBreakdown(
  breakdown: IntentBreakdown,
  asset: import("./intentResolution").ResolvedAsset,
  chartMarketId: string | null,
): IntentBreakdown {
  const resolution = applyAssetToResolution(
    breakdown.resolution,
    asset,
    chartMarketId,
  );
  const next = { ...breakdown, resolution };
  const { deployState, blockingFacet } = computeDeployStateV2(next);
  return {
    ...next,
    deployState,
    blockingFacet,
    blockingSlot: blockingSlotFromFacet(blockingFacet),
  };
}

export function applyStickyArchetype(
  breakdown: IntentBreakdown,
  archetype: IntentArchetype,
): IntentBreakdown {
  if (archetype === "unsupported") return breakdown;
  const wireframe = archetype;
  const next = {
    ...breakdown,
    stickyArchetype: archetype,
    archetype,
    wireframe,
  };
  const { deployState, blockingFacet } = computeDeployStateV2(next);
  return {
    ...next,
    deployState,
    blockingFacet,
    blockingSlot: blockingSlotFromFacet(blockingFacet),
  };
}

export function canDeployBreakdown(
  breakdown: IntentBreakdown | null,
): boolean {
  if (!breakdown) return false;
  if (breakdown.isParked) return false;
  if (breakdown.qualification === "non-intent") return false;
  if (breakdown.qualification === "reject") return false;
  return breakdown.deployState !== "resolve";
}

export function projectResolution(breakdown: IntentBreakdown): IntentResolution {
  return breakdown.resolution;
}
