import { useMemo } from "react";
import {
  useAgentTaskStore,
  selectActiveAgentTaskCount,
  selectHasUnreadAgentTasks,
} from "../store/agentTaskStore";
import type { AgentTask, AgentTaskPendingEdit, ForceExecuteOptions } from "../store/types";

export interface UseAgentTasksResult {
  tasks: AgentTask[];
  loading: boolean;
  error: string | null;
  activeCount: number;
  hasUnreadUpdates: boolean;
  pendingEdit: AgentTaskPendingEdit | null;
  navigateToAgentTasks: boolean;
  addTask: ReturnType<typeof useAgentTaskStore.getState>["addTask"];
  updateTask: ReturnType<typeof useAgentTaskStore.getState>["updateTask"];
  pauseTask: ReturnType<typeof useAgentTaskStore.getState>["pauseTask"];
  resumeTask: ReturnType<typeof useAgentTaskStore.getState>["resumeTask"];
  forceExecute: (id: string, options?: ForceExecuteOptions) => void;
  forceExecuteAllPending: ReturnType<
    typeof useAgentTaskStore.getState
  >["forceExecuteAllPending"];
  pauseActiveTasks: ReturnType<
    typeof useAgentTaskStore.getState
  >["pauseActiveTasks"];
  pauseTasksForAgent: ReturnType<
    typeof useAgentTaskStore.getState
  >["pauseTasksForAgent"];
  rejectTask: ReturnType<typeof useAgentTaskStore.getState>["rejectTask"];
  rejectAllPending: ReturnType<
    typeof useAgentTaskStore.getState
  >["rejectAllPending"];
  pauseActiveTasksForBucket: ReturnType<
    typeof useAgentTaskStore.getState
  >["pauseActiveTasksForBucket"];
  rejectAllPendingForBucket: ReturnType<
    typeof useAgentTaskStore.getState
  >["rejectAllPendingForBucket"];
  markAllSeen: ReturnType<typeof useAgentTaskStore.getState>["markAllSeen"];
  setPendingEdit: ReturnType<typeof useAgentTaskStore.getState>["setPendingEdit"];
  setNavigateToAgentTasks: ReturnType<
    typeof useAgentTaskStore.getState
  >["setNavigateToAgentTasks"];
}

export function useAgentTasks(): UseAgentTasksResult {
  const tasks = useAgentTaskStore((s) => s.tasks);
  const pendingEdit = useAgentTaskStore((s) => s.pendingEdit);
  const navigateToAgentTasks = useAgentTaskStore((s) => s.navigateToAgentTasks);
  const addTask = useAgentTaskStore((s) => s.addTask);
  const updateTask = useAgentTaskStore((s) => s.updateTask);
  const pauseTask = useAgentTaskStore((s) => s.pauseTask);
  const resumeTask = useAgentTaskStore((s) => s.resumeTask);
  const forceExecute = useAgentTaskStore((s) => s.forceExecute);
  const forceExecuteAllPending = useAgentTaskStore((s) => s.forceExecuteAllPending);
  const pauseActiveTasks = useAgentTaskStore((s) => s.pauseActiveTasks);
  const pauseTasksForAgent = useAgentTaskStore((s) => s.pauseTasksForAgent);
  const rejectTask = useAgentTaskStore((s) => s.rejectTask);
  const rejectAllPending = useAgentTaskStore((s) => s.rejectAllPending);
  const pauseActiveTasksForBucket = useAgentTaskStore(
    (s) => s.pauseActiveTasksForBucket,
  );
  const rejectAllPendingForBucket = useAgentTaskStore(
    (s) => s.rejectAllPendingForBucket,
  );
  const markAllSeen = useAgentTaskStore((s) => s.markAllSeen);
  const setPendingEdit = useAgentTaskStore((s) => s.setPendingEdit);
  const setNavigateToAgentTasks = useAgentTaskStore(
    (s) => s.setNavigateToAgentTasks,
  );

  const activeCount = useMemo(
    () => selectActiveAgentTaskCount(tasks),
    [tasks],
  );
  const hasUnreadUpdates = useMemo(
    () => selectHasUnreadAgentTasks(tasks),
    [tasks],
  );

  return {
    tasks,
    loading: false,
    error: null,
    activeCount,
    hasUnreadUpdates,
    pendingEdit,
    navigateToAgentTasks,
    addTask,
    updateTask,
    pauseTask,
    resumeTask,
    forceExecute,
    forceExecuteAllPending,
    pauseActiveTasks,
    pauseTasksForAgent,
    rejectTask,
    rejectAllPending,
    pauseActiveTasksForBucket,
    rejectAllPendingForBucket,
    markAllSeen,
    setPendingEdit,
    setNavigateToAgentTasks,
  };
}
