import React, { useState, useMemo, useEffect } from "react";
import { toast } from "sonner";
import { createErrorCopyAction } from "../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
} from "../ui/toastTask";
import { usePositions } from "../../hooks/usePositions";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useFiClient } from "../../hooks/useFiClient";
import { useMarkets } from "../../hooks/useMarkets";
import { useSubscription } from "../../context/SubscriptionContext";
import { Position, SubscriptionClient } from "../../sdk";
import {
  formatPrice,
  formatSize,
  formatMargin,
  formatPnL,
} from "../../sdk/utils/display";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
  CloseButton,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_BUCKET_POSITIONS,
  DEFAULT_REFRESH_INTERVAL,
  SORT_DIRECTION_ASC,
  SORT_DIRECTION_DESC,
  ORDER_SIDE_LONG,
  ORDER_SIDE_SHORT,
  MARGIN_MODE_CROSS,
  MARGIN_MODE_ISOLATED,
  POSITION_SORT_FIELD_SYMBOL,
  POSITION_SORT_FIELD_LEVERAGE,
  POSITION_SORT_FIELD_SIZE,
  POSITION_SORT_FIELD_LIQUIDATION_PRICE,
  POSITION_SORT_FIELD_UNREALIZED_PNL,
  POSITION_SORT_FIELD_ENTRY_PRICE,
  POSITION_SORT_FIELD_MARGIN,
  POSITION_VIEW_MODE_ALL,
  POSITION_VIEW_MODE_BY_BUCKET,
  POSITION_GRID_TEMPLATE_COLUMNS,
  POSITION_GRID_TEMPLATE_COLUMNS_EMBED,
  POSITION_PNL_COLOR_POSITIVE,
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_LOADING_MESSAGE,
  POSITION_EMPTY_MESSAGE,
  POSITION_TITLE_PREFIX,
  POSITION_TAB_LABEL_ALL,
  POSITION_TAB_LABEL_BY_BUCKET,
  POSITION_LEVERAGE_FALLBACK,
  PositionSortField,
  PositionSortDirection,
  PositionViewMode,
} from "../../constants";
import "../smartlayout/layout.css";
import "./position.css";
import "./agentTasks.css";
import AgentTaskDetailModal from "./AgentTaskDetailModal";
import ExplainActionModal from "./ExplainActionModal";
import { shortHashId } from "../../utils/hashId";
import {
  buildTaskAgentMap,
  rowMatchesFleetFilter,
} from "../../utils/agentFilter";

interface BucketPositionsProps {
  baseURL?: string;
  /** Optional: when inside SubscriptionProvider, hook uses context. */
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress?: string;
  mnemonic?: string; // Required for closing positions
  height?: string;
  refreshInterval?: number;
  selectedBucketId?: string | null;
  /** Optional controlled view mode; use with onViewModeChange (e.g. from TabSection). */
  viewMode?: PositionViewMode;
  /** Called when All / By Bucket view mode changes. */
  onViewModeChange?: (mode: PositionViewMode) => void;
  /** When true, do not render LayoutHeader (e.g. when used inside TabSection). */
  hide_header?: boolean;
  /** When hide_header is true, call with the header actions node so parent can show them in a shared toolbar. */
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  filterAgentIds?: string[];
  /** Scoped embed in bucket extract side panel — hides view tabs and bucket column */
  embedMode?: boolean;
}

function BucketPositions({
  baseURL = DEFAULT_BASE_URL,
  subscriptionClient: subscriptionClientProp,
  authToken,
  walletAddress,
  mnemonic,
  height = DEFAULT_HEIGHT_BUCKET_POSITIONS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  selectedBucketId = null,
  viewMode: viewModeProp,
  onViewModeChange,
  hide_header = false,
  onRequestHeaderActions,
  filterAgentIds = [],
  embedMode = false,
}: BucketPositionsProps): JSX.Element {
  const { client: contextClient } = useSubscription();
  const subscriptionClient = subscriptionClientProp ?? contextClient;

  const {
    positions,
    loading,
    error,
    isConnected,
    refresh: refreshPositions,
  } = usePositions({
    ...(subscriptionClient != null && { subscriptionClient }),
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });
  const { getSymbolByMarketId, selectedMarketId, selectedMarketSymbol } =
    useMarkets({
      baseURL,
      sessionToken: authToken ?? "",
      autoFetchMarkets: true,
    });
  const { client: exchangeClient, isReady: exchangeReady, error: exchangeError } = useFiClient({
    baseURL,
    mnemonic: mnemonic ?? "",
  });
  const { tasks: agentTasks } = useAgentTasks();
  const taskAgentMap = useMemo(() => buildTaskAgentMap(agentTasks), [agentTasks]);
  const [selectedAgentTaskId, setSelectedAgentTaskId] = useState<string | null>(
    null,
  );
  const [explainTaskId, setExplainTaskId] = useState<string | null>(null);

  const selectedAgentTask = useMemo(
    () =>
      selectedAgentTaskId
        ? agentTasks.find((t) => t.id === selectedAgentTaskId) ?? null
        : null,
    [agentTasks, selectedAgentTaskId],
  );

  useEffect(() => {
    if (exchangeError) {
      const msg = exchangeError.message;
      console.error("Failed to initialize FiClient:", exchangeError);
      toast.error("Exchange client initialization failed", {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    }
  }, [exchangeError]);

  const [internalViewMode, setInternalViewMode] = useState<PositionViewMode>(
    POSITION_VIEW_MODE_ALL,
  );
  const isViewModeControlled =
    !embedMode && viewModeProp != null && onViewModeChange != null;
  const viewMode = embedMode
    ? POSITION_VIEW_MODE_BY_BUCKET
    : isViewModeControlled
      ? viewModeProp
      : internalViewMode;
  const setViewMode = isViewModeControlled
    ? onViewModeChange
    : setInternalViewMode;
  const [sortField, setSortField] = useState<PositionSortField | null>(null);
  const [sortDirection, setSortDirection] =
    useState<PositionSortDirection>(SORT_DIRECTION_DESC);
  const [marketFilterActive, setMarketFilterActive] = useState(false);

  // Filter and sort positions
  const processedPositions = useMemo(() => {
    let filtered = [...positions];

    // Filter by selected bucket only when view mode is BY_BUCKET
    if (viewMode === POSITION_VIEW_MODE_BY_BUCKET && selectedBucketId) {
      filtered = filtered.filter((pos) => {
        // Convert both to string for comparison to handle number/string mismatches
        const posBucketId = pos.bucketId.toString();
        const selectedId = selectedBucketId.toString();
        return posBucketId === selectedId;
      });
    }

    if (marketFilterActive && selectedMarketId) {
      filtered = filtered.filter(
        (pos) => String(pos.marketId) === String(selectedMarketId),
      );
    }

    if (filterAgentIds.length > 0) {
      filtered = filtered.filter((pos) =>
        rowMatchesFleetFilter(pos.agentTaskId, filterAgentIds, taskAgentMap),
      );
    }

    // Apply sorting only if a column header was clicked (sortField is set)
    if (!sortField) {
      return filtered; // Return filtered positions without sorting
    }

    // Sort by the selected field
    return filtered.sort((a, b) => {
      let aValue: number | string = 0;
      let bValue: number | string = 0;

      switch (sortField) {
        case POSITION_SORT_FIELD_SYMBOL:
          aValue = getSymbolByMarketId(a.marketId) ?? a.symbol ?? "";
          bValue = getSymbolByMarketId(b.marketId) ?? b.symbol ?? "";
          break;
        case POSITION_SORT_FIELD_LEVERAGE:
          aValue = a.leverage ?? 0;
          bValue = b.leverage ?? 0;
          break;
        case POSITION_SORT_FIELD_SIZE:
          aValue = a.size || 0;
          bValue = b.size || 0;
          break;
        case POSITION_SORT_FIELD_LIQUIDATION_PRICE:
          aValue = a.liquidationPrice || 0;
          bValue = b.liquidationPrice || 0;
          break;
        case POSITION_SORT_FIELD_UNREALIZED_PNL:
          aValue = a.unrealizedPnL || 0;
          bValue = b.unrealizedPnL || 0;
          break;
        case POSITION_SORT_FIELD_ENTRY_PRICE:
          aValue = a.entryPrice || 0;
          bValue = b.entryPrice || 0;
          break;
        case POSITION_SORT_FIELD_MARGIN:
          aValue = a.margin || 0;
          bValue = b.margin || 0;
          break;
      }

      if (typeof aValue === "string" && typeof bValue === "string") {
        return sortDirection === SORT_DIRECTION_ASC
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      const numA = Number(aValue);
      const numB = Number(bValue);

      return sortDirection === SORT_DIRECTION_ASC ? numA - numB : numB - numA;
    });
  }, [positions, sortField, sortDirection, selectedBucketId, viewMode, marketFilterActive, selectedMarketId, getSymbolByMarketId, filterAgentIds, taskAgentMap]);

  const handleSort = (field: PositionSortField) => {
    if (sortField === field) {
      setSortDirection(
        sortDirection === SORT_DIRECTION_ASC
          ? SORT_DIRECTION_DESC
          : SORT_DIRECTION_ASC,
      );
    } else {
      setSortField(field);
      setSortDirection(SORT_DIRECTION_DESC);
    }
  };

  const handleClosePosition = async (position: Position) => {
    // Check if mnemonic is available
    if (!mnemonic) {
      const mnemonicErrorMsg =
        "Please provide the 'mnemonic' prop to enable position closing.";
      toast.error("Mnemonic required", {
        description: mnemonicErrorMsg,
        action: createErrorCopyAction(mnemonicErrorMsg),
      });
      return;
    }

    // Check if FiClient is initialized
    if (!exchangeClient || !exchangeReady) {
      const clientNotReadyMsg =
        "Please wait for the exchange client to initialize.";
      toast.error("Exchange client not ready", {
        description: clientNotReadyMsg,
        action: createErrorCopyAction(clientNotReadyMsg),
      });
      return;
    }

    // Show entry toast (when closing starts)
    const displaySymbol = getSymbolByMarketId(position.marketId) ?? position.symbol;
    const loadingId = toastLoading("Closing position...", {
      description: `Closing ${position.side} position for ${displaySymbol} (Size: ${formatSize(position.size)})`,
    });

    try {
      // Close the position using FiClient
      const response = await exchangeClient.closePosition({
        positionId: position.positionId,
        marketId: position.marketId,
        marketPrice: position.markPrice, // Required: current mark price for the position
        quantity: position.size, // Optional: pass to close partial position, omit to close entire position
        bucketId: position.bucketId, // Shard hint for multi-node routing (E2E alignment)
      });

      toastCompleteSuccess(loadingId, "Position closed successfully", {
        description: `${position.side} position for ${displaySymbol} has been closed. tx: ${response.txhash}`,
        duration: 5000,
      });

      // Refresh positions to reflect the change
      if (refreshPositions) {
        await refreshPositions();
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error occurred";
      toastCompleteError(loadingId, "Failed to close position", {
        description: errorMessage,
        duration: 6000,
        action: createErrorCopyAction(errorMessage),
      });
      console.error("Failed to close position:", error);
    }
  };

  const gridTemplateColumns = embedMode
    ? POSITION_GRID_TEMPLATE_COLUMNS_EMBED
    : POSITION_GRID_TEMPLATE_COLUMNS;

  const headerActions = useMemo(
    () => (
      <>
        {!embedMode ? (
          <>
            <div
              onClick={() => {
                setViewMode(POSITION_VIEW_MODE_ALL);
                setSortField(null);
              }}
              className={`btn-tab ${viewMode === POSITION_VIEW_MODE_ALL ? "active" : ""}`}
            >
              {POSITION_TAB_LABEL_ALL}
            </div>
            <div
              onClick={() => {
                setViewMode(POSITION_VIEW_MODE_BY_BUCKET);
                setSortField(null);
              }}
              className={`btn-tab ${viewMode === POSITION_VIEW_MODE_BY_BUCKET ? "active" : ""}`}
            >
              <span>{POSITION_TAB_LABEL_BY_BUCKET}</span>
            </div>
          </>
        ) : null}
        <div
          className={`btn-tab ${marketFilterActive ? "active" : ""}${!selectedMarketId ? " is-disabled" : ""}`}
          onClick={() => {
            if (!selectedMarketId) return;
            setMarketFilterActive((prev) => !prev);
          }}
          title={
            selectedMarketId
              ? `Show ${selectedMarketSymbol ?? "selected ticker"} only`
              : "Select a ticker to filter"
          }
        >
          {selectedMarketSymbol ? `Active (${selectedMarketSymbol})` : "Active"}
        </div>
        {!isConnected && (
          <div
            onClick={async () => {
              if (refreshPositions) {
                await refreshPositions();
              }
            }}
            className="btn-tab"
            style={{
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
            title="WebSocket disconnected - Click to refresh positions"
          >
            <img
              src="/caution-icy.svg"
              alt="Warning"
              style={{ width: "1rem", height: "1rem" }}
            />
            <span>Refresh</span>
          </div>
        )}
      </>
    ),
    [viewMode, marketFilterActive, selectedMarketId, selectedMarketSymbol, isConnected, refreshPositions, setViewMode, embedMode],
  );

  useEffect(() => {
    if (embedMode || !onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [embedMode, hide_header, onRequestHeaderActions, loading, error, headerActions]);

  if (loading) {
    return <MorpheumInlineLoading message={POSITION_LOADING_MESSAGE} />;
  }

  if (error) {
    return <ErrorMessage error={error} />;
  }

  return (
    <>
      <div
        className="layout-container"
        style={{
          height,
          ...(hide_header
            ? { borderRadius: 0, background: "transparent" }
            : {}),
        }}
      >
      {!hide_header && (
        <LayoutHeader
          title={`${POSITION_TITLE_PREFIX} ${viewMode === POSITION_VIEW_MODE_BY_BUCKET && selectedBucketId ? `(Bucket ${selectedBucketId})` : ""}`}
        >
          {headerActions}
        </LayoutHeader>
      )}

      {/* Table */}
      <div className="table-container shrinkable position-table">
        {/* Table Header */}
        <div
          className="table-header"
          style={{
            gridTemplateColumns,
          }}
        >
          <TableHeaderCell
            field={POSITION_SORT_FIELD_SYMBOL}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Symbol
          </TableHeaderCell>
          {!embedMode ? (
            <TableHeaderCellStatic left>Bucket</TableHeaderCellStatic>
          ) : null}
          <TableHeaderCell
            field={POSITION_SORT_FIELD_LEVERAGE}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            left
          >
            Leverage
          </TableHeaderCell>
          <TableHeaderCell
            field={POSITION_SORT_FIELD_SIZE}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Size
          </TableHeaderCell>
          <TableHeaderCell
            field={POSITION_SORT_FIELD_LIQUIDATION_PRICE}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.liqPrice} />
          </TableHeaderCell>
          <TableHeaderCell
            field={POSITION_SORT_FIELD_UNREALIZED_PNL}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            P/L
          </TableHeaderCell>
          <TableHeaderCell
            field={POSITION_SORT_FIELD_ENTRY_PRICE}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            <TableHeaderLabel {...TABLE_HEADER_LABELS.entryPrice} />
          </TableHeaderCell>
          <TableHeaderCell
            field={POSITION_SORT_FIELD_MARGIN}
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Margin
          </TableHeaderCell>
          <TableHeaderCellStatic center>Actions</TableHeaderCellStatic>
        </div>

        {/* Table Body */}
        {processedPositions.length === 0 ? (
          <EmptyMessage
            message={
              marketFilterActive && selectedMarketSymbol
                ? `No positions for ${selectedMarketSymbol}`
                : POSITION_EMPTY_MESSAGE
            }
          />
        ) : (
          processedPositions.map((position: Position, index: number) => {
            const isLong = position.side === ORDER_SIDE_LONG;
            const pnlColor =
              (position.unrealizedPnL || 0) >= 0
                ? POSITION_PNL_COLOR_POSITIVE
                : POSITION_PNL_COLOR_NEGATIVE;
            const isIsolated =
              (position.marginMode || MARGIN_MODE_CROSS).toUpperCase() ===
              MARGIN_MODE_ISOLATED;
            const marginIndicator = isIsolated ? "(ISO)" : "(X)";
            const leverageText =
              position.leverage > 0
                ? `${position.leverage}x`
                : POSITION_LEVERAGE_FALLBACK;

            const isNearLiquidation =
              position.symbol.includes("JELLY") &&
              position.liquidationPrice > 0 &&
              position.markPrice > 0 &&
              position.markPrice <= position.liquidationPrice * 1.02;

            return (
              <div
                key={`position-${position.marketId}-${index}`}
                className={`table-row ${index % 2 === 0 ? "even" : ""}${isNearLiquidation ? " position-row--liquidation-warning" : ""}`}
                style={{
                  gridTemplateColumns,
                }}
              >
                {/* Symbol */}
                <div
                  className="table-cell primary"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "0.5rem",
                  }}
                >
                  <span>{getSymbolByMarketId(position.marketId) ?? position.symbol}</span>
                </div>

                {!embedMode ? (
                  <div
                    className="table-cell position-bucket-cell"
                    title={position.bucketId || undefined}
                  >
                    <span className="terminal-value">
                      {position.bucketId ? shortHashId(position.bucketId) : "—"}
                    </span>
                    {marginIndicator}
                  </div>
                ) : null}

                {/* Leverage */}
                <div className={isLong ? "terminal-long" : "terminal-short"}>
              {leverageText}     {isLong?"LONG":"SHORT"} 
                </div>

                {/* Size */}
                <div className="table-cell right">
                  {formatSize(position.size)}
                </div>

                {/* Liq. Price */}
                <div className="table-cell right">
                  {formatPrice(position.liquidationPrice)}
                </div>

                {/* P/L */}
                <div
                  className="table-cell right"
                  style={{ color: pnlColor}}
                >
                  {formatPnL(position.unrealizedPnL)}
                </div>

                {/* Entry Price */}
                <div className="table-cell right">
                  {formatPrice(position.entryPrice)}
                </div>

                {/* Margin */}
                <div className="table-cell right">
                  {formatMargin(position.margin)}
                </div>

                {/* Actions */}
                <div className="table-row-actions agent-task-actions position-row-actions">
                  {position.agentTaskId ? (
                    <>
                      <button
                        type="button"
                        className="btn"
                        onClick={() =>
                          setSelectedAgentTaskId(position.agentTaskId ?? null)
                        }
                      >
                        Agent
                      </button>
                      <button
                        type="button"
                        className="btn explain-action-btn"
                        onClick={() =>
                          setExplainTaskId(position.agentTaskId ?? null)
                        }
                      >
                        Why?
                      </button>
                    </>
                  ) : null}
                  <CloseButton onClick={() => handleClosePosition(position)} />
                </div>
              </div>
            );
          })
        )}
      </div>
      </div>
      <AgentTaskDetailModal
        isOpen={selectedAgentTaskId != null}
        task={selectedAgentTask}
        baseURL={baseURL}
        authToken={authToken}
        onClose={() => setSelectedAgentTaskId(null)}
      />
      <ExplainActionModal
        isOpen={explainTaskId != null}
        agentTaskId={explainTaskId}
        baseURL={baseURL}
        walletAddress={walletAddress}
        onClose={() => setExplainTaskId(null)}
      />
    </>
  );
}

export default React.memo(BucketPositions);
