import { useQuery } from "@tanstack/react-query";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import { generateLiveMetrics } from "./mockData";

/** Simulated live metrics, polled on a gentle interval. */
export function useLiveMetrics() {
  const { throughputTier, validatorCount } = useNetworkHealthDemo();

  return useQuery({
    queryKey: ["network-health", "metrics", throughputTier, validatorCount],
    queryFn: async () =>
      generateLiveMetrics({ throughputTier, validatorCount }),
    refetchInterval: 5_000,
  });
}
