import React, { useMemo } from "react";

import { TERMINAL_COLORS } from "../../../constants/terminalColors";
import type { IndexShareChartPoint } from "./indexShareData";

const CHART_WIDTH = 432;
const CHART_HEIGHT = 140;
const PADDING = { top: 8, right: 8, bottom: 24, left: 36 };

export interface IndexSharePerformanceChartProps {
  points: IndexShareChartPoint[];
  indexLabel: string;
  indexRoi1y: number;
  btcRoi1y: number;
}

function buildPolyline(
  values: number[],
  min: number,
  max: number,
  width: number,
  height: number,
): string {
  if (values.length === 0) return "";
  const innerWidth = width - PADDING.left - PADDING.right;
  const innerHeight = height - PADDING.top - PADDING.bottom;

  return values
    .map((value, index) => {
      const x =
        values.length === 1
          ? PADDING.left + innerWidth / 2
          : PADDING.left + (index / (values.length - 1)) * innerWidth;
      const normalized = max === min ? 0.5 : (value - min) / (max - min);
      const y = PADDING.top + innerHeight - normalized * innerHeight;
      return `${x},${y}`;
    })
    .join(" ");
}

function buildAreaPath(
  values: number[],
  min: number,
  max: number,
  width: number,
  height: number,
): string {
  const line = buildPolyline(values, min, max, width, height);
  if (!line) return "";
  const innerWidth = width - PADDING.left - PADDING.right;
  const baseline = height - PADDING.bottom;
  const firstX = PADDING.left;
  const lastX = PADDING.left + innerWidth;
  return `M ${firstX} ${baseline} L ${line} L ${lastX} ${baseline} Z`;
}

function IndexSharePerformanceChart({
  points,
  indexLabel,
  indexRoi1y,
  btcRoi1y,
}: IndexSharePerformanceChartProps): JSX.Element {
  const { indexValues, btcValues, min, max, yTicks } = useMemo(() => {
    const indexValues = points.map((point) => point.indexPct);
    const btcValues = points.map((point) => point.btcPct);
    const allValues = [...indexValues, ...btcValues];
    const min = Math.min(...allValues, 0);
    const max = Math.max(...allValues, 0);
    const span = max - min || 1;
    const yTicks = [min, min + span * 0.5, max].map((value) =>
      Math.round(value),
    );
    return { indexValues, btcValues, min, max, yTicks };
  }, [points]);

  const indexLine = buildPolyline(
    indexValues,
    min,
    max,
    CHART_WIDTH,
    CHART_HEIGHT,
  );
  const btcLine = buildPolyline(btcValues, min, max, CHART_WIDTH, CHART_HEIGHT);
  const indexArea = buildAreaPath(
    indexValues,
    min,
    max,
    CHART_WIDTH,
    CHART_HEIGHT,
  );

  return (
    <div className="index-share-chart">
      <div className="index-share-chart-head">
        <h3 className="index-share-section-title">Performance in the past year</h3>
        <div className="index-share-chart-legend">
          <span className="index-share-legend-item">
            <span
              className="index-share-legend-swatch"
              style={{ background: TERMINAL_COLORS.long }}
            />
            {indexLabel} {indexRoi1y >= 0 ? "+" : ""}
            {indexRoi1y.toFixed(2)}%
          </span>
          <span className="index-share-legend-item">
            <span
              className="index-share-legend-swatch"
              style={{ background: TERMINAL_COLORS.warning }}
            />
            BTC {btcRoi1y >= 0 ? "+" : ""}
            {btcRoi1y.toFixed(2)}%
          </span>
        </div>
      </div>
      <svg
        viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
        className="index-share-chart-svg"
        role="img"
        aria-label="Index performance versus BTC over the past year"
      >
        {yTicks.map((tick) => {
          const innerHeight =
            CHART_HEIGHT - PADDING.top - PADDING.bottom;
          const normalized = max === min ? 0.5 : (tick - min) / (max - min);
          const y = PADDING.top + innerHeight - normalized * innerHeight;
          return (
            <g key={tick}>
              <line
                x1={PADDING.left}
                y1={y}
                x2={CHART_WIDTH - PADDING.right}
                y2={y}
                stroke="rgba(255,255,255,0.08)"
              />
              <text
                x={PADDING.left - 6}
                y={y + 4}
                textAnchor="end"
                fill="rgba(255,255,255,0.45)"
                fontSize="10"
              >
                {tick}%
              </text>
            </g>
          );
        })}
        <path d={indexArea} fill={TERMINAL_COLORS.longSoft} />
        <polyline
          points={indexLine}
          fill="none"
          stroke={TERMINAL_COLORS.long}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <polyline
          points={btcLine}
          fill="none"
          stroke={TERMINAL_COLORS.warning}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
}

export default IndexSharePerformanceChart;
