/** Perps fee tier row (Hyperliquid-style schedule). */
export interface PerpsFeeTier {
  tier: number;
  /** Exclusive lower bound; tier applies when volume14d > minVolume (tier 0 is fallback). */
  minVolume: number;
  /** Decimal rate, e.g. 0.00045 for 0.0450%. */
  takerRate: number;
  makerRate: number;
}

/** Perps tiers ordered highest threshold first for lookup. */
const PERPS_FEE_TIERS_DESC: PerpsFeeTier[] = [
  { tier: 6, minVolume: 7_000_000_000, takerRate: 0.00024, makerRate: 0 },
  { tier: 5, minVolume: 2_000_000_000, takerRate: 0.00026, makerRate: 0 },
  { tier: 4, minVolume: 500_000_000, takerRate: 0.00028, makerRate: 0 },
  { tier: 3, minVolume: 100_000_000, takerRate: 0.0003, makerRate: 0.00004 },
  { tier: 2, minVolume: 25_000_000, takerRate: 0.00035, makerRate: 0.00008 },
  { tier: 1, minVolume: 5_000_000, takerRate: 0.0004, makerRate: 0.00012 },
];

const PERPS_FEE_TIER_0: PerpsFeeTier = {
  tier: 0,
  minVolume: 0,
  takerRate: 0.00045,
  makerRate: 0.00015,
};

/** Resolve perps fee tier from rolling 14-day volume (USD notional). */
export function resolvePerpsFeeTier(volume14d: number): PerpsFeeTier {
  for (const tier of PERPS_FEE_TIERS_DESC) {
    if (volume14d > tier.minVolume) {
      return tier;
    }
  }
  return PERPS_FEE_TIER_0;
}

/** Display percentage points for a decimal rate (0.00045 → 0.045). */
export function perpsRateToDisplayPct(rate: number): number {
  return rate * 100;
}
