import {
  AGENT_TOKEN_PRICE_HISTORY_CANDLE_COUNT,
  AGENT_TOKEN_PRICE_HISTORY_DAYS,
  AGENT_TOKEN_PRICE_HISTORY_INTERVAL_MS,
} from "../../../offline/mock_data/agentTokenPriceHistory.types";
import { binanceIntervalToMs, toBinanceInterval } from "../../sdk/api/binance/klineUtil";

export const CHART_HISTORY_DAYS = AGENT_TOKEN_PRICE_HISTORY_DAYS;

export const AGENT_TOKEN_FULL_HISTORY_LIMIT = AGENT_TOKEN_PRICE_HISTORY_CANDLE_COUNT;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Max bar count for N days at the given chart interval (Binance-style). */
export function chartBarLimitForDays(interval: string, days: number = CHART_HISTORY_DAYS): number {
  const normalized = toBinanceInterval(interval);
  const intervalMs = binanceIntervalToMs(normalized);
  const windowMs = days * MS_PER_DAY;
  return Math.max(1, Math.ceil(windowMs / intervalMs));
}

/** Cap for agent-token source files (5m) aggregated to coarser intervals. */
export function agentTokenChartBarLimit(interval: string, days: number = CHART_HISTORY_DAYS): number {
  const normalized = toBinanceInterval(interval);
  const intervalMs = binanceIntervalToMs(normalized);
  if (intervalMs <= AGENT_TOKEN_PRICE_HISTORY_INTERVAL_MS) {
    return AGENT_TOKEN_PRICE_HISTORY_CANDLE_COUNT;
  }
  return chartBarLimitForDays(normalized, days);
}

/** Resolve hook/widget limit: undefined means full history; explicit limits are capped to the window. */
export function resolveAgentTokenChartLimit(
  interval: string,
  limit: number | undefined,
  days: number = CHART_HISTORY_DAYS,
): number | undefined {
  const maxBars = agentTokenChartBarLimit(interval, days);
  if (limit == null || limit <= 0) return undefined;
  return Math.min(limit, maxBars);
}

/** Default visible bar window when seeding chart at the live edge (readable zoom). */
export const AGENT_TOKEN_INITIAL_VISIBLE_BARS = 400;
