import type { LineData, UTCTimestamp } from "lightweight-charts";

export const HOUR_MS = 60 * 60 * 1000;

export function interpolateSeries(values: number[], pointCount: number): number[] {
  if (values.length === 0) return [];
  if (pointCount <= 1) return [values[values.length - 1] ?? 0];
  if (values.length === 1) {
    return Array.from({ length: pointCount }, () => values[0]!);
  }

  return Array.from({ length: pointCount }, (_, index) => {
    const t = (index / (pointCount - 1)) * (values.length - 1);
    const lo = Math.floor(t);
    const hi = Math.min(Math.ceil(t), values.length - 1);
    const frac = t - lo;
    return values[lo]! * (1 - frac) + values[hi]! * frac;
  });
}

export function toUtcTimestamp(ms: number): UTCTimestamp {
  return Math.floor(ms / 1000) as UTCTimestamp;
}

export function scaleSparklineSeries(
  sparkline: number[],
  targetEnd: number,
  pointCount = 24,
): number[] {
  const resampled = interpolateSeries(sparkline, pointCount);
  const last = resampled[resampled.length - 1] ?? 1;
  const scale = last !== 0 ? targetEnd / last : 1;
  return resampled.map((value) => Number((value * scale).toFixed(4)));
}

export function buildSparklineLineData(
  sparkline: number[],
  targetEnd: number,
  pointCount = 24,
  stepMs = HOUR_MS,
): LineData<UTCTimestamp>[] {
  const anchors = sparkline.length > 1 ? sparkline : [0, targetEnd];
  const scaled = scaleSparklineSeries(anchors, targetEnd, pointCount);
  const now = Date.now();

  return scaled.map((value, index) => ({
    time: toUtcTimestamp(now - (pointCount - 1 - index) * stepMs),
    value,
  }));
}

export function buildSignedPercentLineData(
  sparkline: number[],
  targetEnd: number,
  pointCount = 24,
  stepMs = HOUR_MS,
): LineData<UTCTimestamp>[] {
  return buildSparklineLineData(sparkline, targetEnd, pointCount, stepMs);
}
