import React, { useEffect, useRef, type JSX, type RefObject } from "react";
import type { IChartApi, UTCTimestamp } from "lightweight-charts";

const MIN_LABEL_PX = 80;
const LABEL_POOL_SIZE = 16;
const DAY_SEC = 86400;
const WEEK_SEC = 7 * DAY_SEC;

export interface KlineChartTimeAxisOverlayProps {
  chart: IChartApi | null;
  canvasWrapperRef: RefObject<HTMLDivElement | null>;
  barTimes: readonly UTCTimestamp[];
  interval?: string;
  intervalSec?: number;
  isPanningRef?: RefObject<boolean>;
}

interface AxisSlotElements {
  root: HTMLDivElement | null;
  tick: HTMLSpanElement | null;
  label: HTMLSpanElement | null;
}

type FormatMode = "time" | "datetime" | "date";

interface LockedAxisState {
  tickTimes: UTCTimestamp[];
  formatMode: FormatMode;
  stepSec: number;
}

function createRafCoalescer(fn: () => void): () => void {
  let id = 0;
  return () => {
    if (id) return;
    id = requestAnimationFrame(() => {
      id = 0;
      fn();
    });
  };
}

function pickTickStepSec(visibleSpanSec: number, intervalSec: number, widthPx: number): number {
  const targetCount = Math.max(2, Math.floor(widthPx / MIN_LABEL_PX));
  const minStep = visibleSpanSec / targetCount;
  const multipliers = [1, 2, 3, 4, 6, 8, 12, 24, 48, 72, 168, 336, 720];
  for (const multiplier of multipliers) {
    const step = multiplier * intervalSec;
    if (step >= minStep) return step;
  }
  return multipliers[multipliers.length - 1]! * intervalSec;
}

function resolveFormatMode(
  intervalSec: number,
  barSpacing: number,
  visibleSpanSec: number,
): FormatMode {
  if (intervalSec >= DAY_SEC) return "date";
  if (visibleSpanSec >= WEEK_SEC || barSpacing <= 3) return "date";
  if (visibleSpanSec >= DAY_SEC || barSpacing <= 4) return "datetime";
  return "time";
}

function formatLabel(time: UTCTimestamp, mode: FormatMode): string {
  const d = new Date(time * 1000);
  const datePart = d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const timePart = d.toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });

  switch (mode) {
    case "date":
      return datePart;
    case "datetime":
      return `${datePart}, ${timePart}`;
    case "time":
      return timePart;
  }
}

function KlineChartTimeAxisOverlay({
  chart,
  canvasWrapperRef,
  barTimes,
  intervalSec = 300,
  isPanningRef,
}: KlineChartTimeAxisOverlayProps): JSX.Element {
  const slotRefs = useRef<AxisSlotElements[]>([]);
  const barTimesRef = useRef(barTimes);
  barTimesRef.current = barTimes;
  const isPanningRefProp = isPanningRef;

  useEffect(() => {
    if (!chart) return;

    const lockedState: LockedAxisState = {
      tickTimes: [],
      formatMode: "time",
      stepSec: intervalSec,
    };
    let wasPanning = false;

    const hideSlot = (slot: AxisSlotElements) => {
      if (slot.root) slot.root.style.display = "none";
    };

    const getVisibleTimes = (): { fromTime: number; toTime: number } | null => {
      const visibleRange = chart.timeScale().getVisibleRange();
      if (visibleRange) {
        return {
          fromTime: visibleRange.from as number,
          toTime: visibleRange.to as number,
        };
      }
      const times = barTimesRef.current;
      if (times.length === 0) return null;
      return {
        fromTime: times[0] as number,
        toTime: times[times.length - 1] as number,
      };
    };

    const applyPositions = () => {
      const slots = slotRefs.current;
      const timeScale = chart.timeScale();
      let slot = 0;

      for (const time of lockedState.tickTimes) {
        if (slot >= LABEL_POOL_SIZE) break;
        const entry = slots[slot];
        if (!entry?.root) {
          slot++;
          continue;
        }

        const x = timeScale.timeToCoordinate(time);
        if (x === null) {
          hideSlot(entry);
          slot++;
          continue;
        }

        entry.root.style.display = "";
        entry.root.style.transform = `translate3d(${x}px, 0, 0) translate3d(-50%, 0, 0)`;
        if (entry.tick) entry.tick.style.display = "";
        slot++;
      }

      for (let i = slot; i < LABEL_POOL_SIZE; i++) {
        hideSlot(slots[i] ?? { root: null, tick: null, label: null });
      }
    };

    const rebuildTicks = () => {
      const slots = slotRefs.current;
      const times = barTimesRef.current;
      const timeScale = chart.timeScale();
      const wrapper = canvasWrapperRef.current;
      const width = timeScale.width() || wrapper?.clientWidth || 0;

      if (width <= 0 || times.length === 0) {
        lockedState.tickTimes = [];
        for (let i = 0; i < LABEL_POOL_SIZE; i++) {
          hideSlot(slots[i] ?? { root: null, tick: null, label: null });
        }
        return;
      }

      const visible = getVisibleTimes();
      if (!visible) return;

      const { fromTime, toTime } = visible;
      const visibleSpanSec = Math.max(intervalSec, toTime - fromTime);
      const barSpacing = timeScale.options().barSpacing ?? 6;
      const stepSec = pickTickStepSec(visibleSpanSec, intervalSec, width);
      const formatMode = resolveFormatMode(intervalSec, barSpacing, visibleSpanSec);

      lockedState.stepSec = stepSec;
      lockedState.formatMode = formatMode;
      lockedState.tickTimes = [];

      const bufferSec = visibleSpanSec;
      const rangeStart = fromTime - bufferSec;
      const rangeEnd = toTime + bufferSec;
      const startTick = Math.ceil(rangeStart / stepSec) * stepSec;

      for (let t = startTick; t <= rangeEnd && lockedState.tickTimes.length < LABEL_POOL_SIZE; t += stepSec) {
        lockedState.tickTimes.push(t as UTCTimestamp);
      }

      let slot = 0;
      for (const time of lockedState.tickTimes) {
        if (slot >= LABEL_POOL_SIZE) break;
        const entry = slots[slot];
        if (!entry?.root || !entry.label) {
          slot++;
          continue;
        }

        const x = timeScale.timeToCoordinate(time);
        if (x === null) {
          hideSlot(entry);
          slot++;
          continue;
        }

        entry.root.style.display = "";
        entry.root.style.transform = `translate3d(${x}px, 0, 0) translate3d(-50%, 0, 0)`;
        if (entry.tick) entry.tick.style.display = "";
        entry.label.textContent = formatLabel(time, formatMode);
        slot++;
      }

      for (let i = slot; i < LABEL_POOL_SIZE; i++) {
        hideSlot(slots[i] ?? { root: null, tick: null, label: null });
      }
    };

    const scheduleIdleRebuild = createRafCoalescer(rebuildTicks);

    const onRangeChange = () => {
      const panning = isPanningRefProp?.current ?? false;

      if (panning) {
        if (!wasPanning) {
          wasPanning = true;
          rebuildTicks();
        } else {
          applyPositions();
        }
        return;
      }

      if (wasPanning) {
        wasPanning = false;
        rebuildTicks();
        return;
      }

      scheduleIdleRebuild();
    };
    const timeScale = chart.timeScale();

    rebuildTicks();
    timeScale.subscribeVisibleLogicalRangeChange(onRangeChange);

    const wrapper = canvasWrapperRef.current;
    const observer =
      wrapper != null ? new ResizeObserver(() => scheduleIdleRebuild()) : null;
    if (wrapper && observer) observer.observe(wrapper);

    return () => {
      timeScale.unsubscribeVisibleLogicalRangeChange(onRangeChange);
      observer?.disconnect();
    };
  }, [barTimes.length, canvasWrapperRef, chart, intervalSec, isPanningRefProp]);

  return (
    <div className="kline-chart-time-axis-overlay" aria-hidden>
      <div className="kline-chart-time-axis-baseline" />
      {Array.from({ length: LABEL_POOL_SIZE }, (_, i) => (
        <div
          key={i}
          ref={(el) => {
            if (!slotRefs.current[i]) {
              slotRefs.current[i] = { root: null, tick: null, label: null };
            }
            slotRefs.current[i]!.root = el;
          }}
          className="kline-chart-time-axis-slot"
          style={{ display: "none" }}
        >
          <span
            ref={(el) => {
              if (slotRefs.current[i]) slotRefs.current[i]!.tick = el;
            }}
            className="kline-chart-time-axis-tick"
          />
          <span
            ref={(el) => {
              if (slotRefs.current[i]) slotRefs.current[i]!.label = el;
            }}
            className="kline-chart-time-axis-label"
          />
        </div>
      ))}
    </div>
  );
}

export default KlineChartTimeAxisOverlay;
