/* HIL Mode — Human-in-Loop Cockpit
 * Primary job: fast, confident approve/reject with full context.
 * Designed to feel like a professional risk desk, not a chat window.
 */
import React, {
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useMarkets } from "../../hooks/useMarkets";
import { DEFAULT_BASE_URL } from "../../constants";
import type { AgentTask } from "../../store/types";
import { useFlipListInsert } from "../tradeops/useFlipListInsert";
import {
  DECK_DEFAULT_VISIBLE_INTENTS,
  DECK_GUARDRAIL_ESTIMATED_CARD_HEIGHT_PX,
} from "./deckCapacity";
import { isSameMarketId, sortGuardrailIntents } from "./deckIntents";
import { ManualTradeAccordion } from "./AgentCommandDeck";
import { TradeAgentIntentCard } from "./TradeAgentIntentCard";
import { useDeckBottomFade } from "./useDeckBottomFade";
import { useDeckCardCapacity } from "./useDeckCardCapacity";
import { useDeckTaskListAnimation } from "./useDeckTaskListAnimation";
import GuardrailSimulationPreview from "./GuardrailSimulationPreview";
import GuardrailIntentCardExtras from "./GuardrailIntentCardExtras";
import { getGuardrailMeta } from "./guardrailMeta";
import "./tradeAgentDeck.css";

export interface GuardrailCockpitProps {
  height?: string;
  manualTrade: React.ReactNode;
  onRequestExpandConsole?: () => void;
  selectedMarketId?: string;
  baseURL?: string;
  onTaskContextSelect?: (task: AgentTask) => void;
  hilPolishActive?: boolean;
  riskThreshold?: number;
}

function mergeRenderTasks(
  visibleTasks: AgentTask[],
  allTasks: AgentTask[],
  exitingId: string | null,
): AgentTask[] {
  if (!exitingId || visibleTasks.some((t) => t.id === exitingId)) {
    return visibleTasks;
  }
  const exitingTask = allTasks.find((t) => t.id === exitingId);
  if (!exitingTask) return visibleTasks;
  return [...visibleTasks, exitingTask];
}

function GuardrailCockpit({
  height,
  manualTrade,
  onRequestExpandConsole,
  selectedMarketId,
  baseURL = DEFAULT_BASE_URL,
  onTaskContextSelect,
  hilPolishActive = true,
  riskThreshold = 100,
}: GuardrailCockpitProps): JSX.Element {
  const { tasks, forceExecute, rejectTask } = useAgentTasks();
  const { markets, getSymbolByMarketId } = useMarkets({
    baseURL,
    autoFetchMarkets: false,
  });
  const prevCardCountRef = useRef(0);
  const cardsViewportRef = useRef<HTMLDivElement>(null);
  const [visibleCapacity, setVisibleCapacity] = useState(
    DECK_DEFAULT_VISIBLE_INTENTS,
  );

  const handleCapacityChange = useCallback((next: number) => {
    setVisibleCapacity((prev) => (prev === next ? prev : next));
  }, []);

  const pendingIntents = useMemo(
    () => sortGuardrailIntents(tasks),
    [tasks],
  );

  const pendingQueue = useMemo(
    () => pendingIntents.slice(0, visibleCapacity),
    [pendingIntents, visibleCapacity],
  );

  const overflowCount = Math.max(0, pendingIntents.length - pendingQueue.length);

  const measureCardIds = useMemo(
    () => pendingQueue.map((task) => task.id),
    [pendingQueue],
  );

  const { enterState, exitingId, onExitAnimationEnd } =
    useDeckTaskListAnimation(measureCardIds);

  const renderTasks = useMemo(
    () => mergeRenderTasks(pendingQueue, tasks, exitingId),
    [pendingQueue, tasks, exitingId],
  );

  const renderTaskIds = useMemo(
    () => renderTasks.map((task) => task.id),
    [renderTasks],
  );

  const enteringId =
    enterState?.phase === "push" ? enterState.instanceId : null;

  const setFlipRef = useFlipListInsert({
    itemIds: renderTaskIds,
    enteringId,
  });

  const setCardRef = useDeckCardCapacity({
    cardsViewportRef,
    measureCardIds,
    setFlipRef,
    onCapacityChange: handleCapacityChange,
    options: {
      estimatedCardHeightPx: hilPolishActive
        ? DECK_GUARDRAIL_ESTIMATED_CARD_HEIGHT_PX
        : 120,
    },
  });

  const showBottomFade = useDeckBottomFade(
    cardsViewportRef,
    overflowCount,
    renderTaskIds.join("\0"),
  );

  const watchingCount = useMemo(
    () => tasks.filter((t) => t.status === "watching").length,
    [tasks],
  );

  const executingCount = useMemo(
    () => tasks.filter((t) => t.status === "executing").length,
    [tasks],
  );

  const pausedCount = useMemo(
    () => tasks.filter((t) => t.status === "paused").length,
    [tasks],
  );

  const handleApprove = useCallback(
    (taskId: string, sizePct: number) => {
      forceExecute(taskId, { sizePct });
    },
    [forceExecute],
  );

  const isBelowThreshold = useCallback(
    (task: AgentTask) => getGuardrailMeta(task).confidencePct < riskThreshold,
    [riskThreshold],
  );

  useLayoutEffect(() => {
    if (renderTasks.length > prevCardCountRef.current && cardsViewportRef.current) {
      cardsViewportRef.current.scrollTop = 0;
    }
    prevCardCountRef.current = renderTasks.length;
  }, [renderTasks.length, cardsViewportRef]);

  return (
    <div
      className={[
        "trade-agent-deck",
        hilPolishActive ? "trade-agent-deck--hil-polish" : "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{ height, minHeight: 0 }}
      data-tour="welcome-guardrail-deck"
    >
      <div className="trade-agent-deck-head">
        <h2 className="trade-agent-deck-title">Guardrail Cockpit</h2>
        <div className="trade-agent-deck-metrics">
          <div className="trade-safety-header-metric">
            <span className="trade-safety-header-label">Watching</span>
            <span className="trade-safety-header-value">{watchingCount}</span>
          </div>
          <div className="trade-safety-header-metric">
            <span className="trade-safety-header-label">Executing</span>
            <span className="trade-safety-header-value">{executingCount}</span>
          </div>
          <div className="trade-safety-header-metric">
            <span className="trade-safety-header-label">Paused</span>
            <span className="trade-safety-header-value">{pausedCount}</span>
          </div>
        </div>
      </div>
      <div className="trade-agent-deck-body">
        {hilPolishActive ? <GuardrailSimulationPreview tasks={tasks} /> : null}
        <div className="trade-agent-deck-cards-shell">
          <div ref={cardsViewportRef} className="trade-agent-deck-cards">
            {renderTasks.map((task) => {
              const symbol =
                getSymbolByMarketId(task.marketId ?? "")?.split("/")[0] ?? "market";
              return (
                <TradeAgentIntentCard
                  key={task.id}
                  task={task}
                  enterState={enterState}
                  exitingId={exitingId}
                  setFlipRef={setCardRef}
                  onExitAnimationEnd={onExitAnimationEnd}
                  onContextSelect={
                    task.marketId && onTaskContextSelect
                      ? () => onTaskContextSelect(task)
                      : undefined
                  }
                  isContextActive={isSameMarketId(
                    markets,
                    task.marketId,
                    selectedMarketId,
                  )}
                >
                  {hilPolishActive ? (
                    <GuardrailIntentCardExtras
                      task={task}
                      baseAssetLabel={symbol}
                      onApprove={handleApprove}
                      onReject={rejectTask}
                      dimmed={isBelowThreshold(task)}
                      tooltipGroup="GuardrailCockpit"
                    />
                  ) : (
                    <div className="trade-agent-deck-card-actions">
                      <button
                        type="button"
                        className="trade-agent-deck-btn trade-agent-deck-btn--primary"
                        onClick={() => forceExecute(task.id)}
                      >
                        Approve
                      </button>
                      <button
                        type="button"
                        className="trade-agent-deck-btn trade-agent-deck-btn--danger"
                        onClick={() => rejectTask(task.id)}
                      >
                        Reject
                      </button>
                    </div>
                  )}
                </TradeAgentIntentCard>
              );
            })}
          </div>
          <div
            className={[
              "trade-agent-deck-cards-fade",
              showBottomFade ? "is-visible" : "",
            ]
              .filter(Boolean)
              .join(" ")}
            aria-hidden
          />
        </div>
        {pendingQueue.length === 0 && !exitingId ? (
          <p className="trade-agent-reasoning-item">No intents awaiting approval.</p>
        ) : null}
        {onRequestExpandConsole ? (
          <button
            type="button"
            className={[
              "trade-agent-deck-overflow-btn",
              overflowCount > 0 ? "" : "trade-agent-deck-overflow-btn--placeholder",
            ]
              .filter(Boolean)
              .join(" ")}
            onClick={overflowCount > 0 ? onRequestExpandConsole : undefined}
            disabled={overflowCount === 0}
            aria-hidden={overflowCount === 0}
            tabIndex={overflowCount === 0 ? -1 : undefined}
          >
            {overflowCount > 0
              ? `+${overflowCount} more in queue`
              : "\u00a0"}
          </button>
        ) : null}
        {!hilPolishActive ? (
          <p className="trade-agent-reasoning-item">
            Simulation preview: approving queue may increase exposure on active
            markets.
          </p>
        ) : null}
      </div>
      <ManualTradeAccordion>{manualTrade}</ManualTradeAccordion>
    </div>
  );
}

export default React.memo(GuardrailCockpit);
