import React from "react";

import {
  REVENUE_OPTIONS,
  RISK_OPTIONS,
  SECTOR_OPTIONS,
} from "../../hooks/useMarketsPageData";
import "./markets.css";

export interface MarketsFiltersSidebarProps {
  height?: string;
  sector: string;
  risk: string;
  revenue: string;
  onSectorChange: (value: string) => void;
  onRiskChange: (value: string) => void;
  onRevenueChange: (value: string) => void;
  onReset: () => void;
}

export default function MarketsFiltersSidebar({
  height = "100%",
  sector,
  risk,
  revenue,
  onSectorChange,
  onRiskChange,
  onRevenueChange,
  onReset,
}: MarketsFiltersSidebarProps): JSX.Element {
  return (
    <aside className="markets-slot markets-filters-sidebar" style={{ height }}>
      <h2>Filters</h2>
      <div className="markets-filter-group">
        <label>Sector</label>
        <div className="markets-chips">
          {SECTOR_OPTIONS.filter((item) => item !== "All").map((item) => (
            <button
              type="button"
              key={item}
              className={`markets-pill-btn${sector === item ? " active" : ""}`}
              onClick={() => onSectorChange(item)}
            >
              {item}
            </button>
          ))}
        </div>
      </div>
      <div className="markets-filter-group">
        <label>Risk</label>
        <div className="markets-chips">
          {RISK_OPTIONS.filter((item) => item !== "All").map((item) => (
            <button
              type="button"
              key={item}
              className={`markets-pill-btn${risk === item ? " active" : ""}`}
              onClick={() => onRiskChange(item)}
            >
              {item}
            </button>
          ))}
        </div>
      </div>
      <div className="markets-filter-group">
        <label>Revenue</label>
        <div className="markets-chips">
          {REVENUE_OPTIONS.filter((item) => item !== "All").map((item) => (
            <button
              type="button"
              key={item}
              className={`markets-pill-btn${revenue === item ? " active" : ""}`}
              onClick={() => onRevenueChange(item)}
            >
              {item}
            </button>
          ))}
        </div>
      </div>
      <button type="button" className="markets-pill-btn" onClick={onReset}>
        Reset filters
      </button>
    </aside>
  );
}
