export function getMormSignerWasmCandidates(): string[] {
  const baseUrl = import.meta.env?.BASE_URL ?? "/";

  return [
    `${baseUrl}morm_signer.wasm`,
    "/morm_signer.wasm",
    "/packages/offline/public/morm_signer.wasm",
  ];
}

export function getMormSignerWasmDebugLabel(path: string): string {
  if (path.startsWith("/packages/offline/public/")) {
    return "offline public asset";
  }

  if (path === "/morm_signer.wasm") {
    return "root public asset";
  }

  return "app base asset";
}
