import React, { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useStaggeredOverlay,
} from "../ui/overlay";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import AgentCommandCenterTab from "./tabs/AgentCommandCenterTab";
import AgentExecutionTraceTab from "./tabs/AgentExecutionTraceTab";
import AgentRiskAttributionTab from "./tabs/AgentRiskAttributionTab";
import { WalletConnectedGate } from "../wallet";
import "../tables/TabSection.css";
import "./agentConsole.css";

const MIN_HEIGHT_VH = 20;
const MAX_HEIGHT_VH = 60;
const DEFAULT_HEIGHT_VH = 30;

const STORAGE_OPEN_KEY = "agentConsoleOpen";
const STORAGE_HEIGHT_KEY = "agentConsoleHeight";

export type AgentConsoleTabId = "commandCenter" | "executionTrace" | "riskAttribution";

const TAB_LABELS: Record<AgentConsoleTabId, string> = {
  commandCenter: "Command Center",
  executionTrace: "Execution Trace",
  riskAttribution: "Risk Attribution",
};

export interface AgentConsolePanelProps {
  isOpen: boolean;
  onClose: () => void;
  baseURL: string;
  authToken?: string;
  walletAddress: string;
  heightVh?: number;
  onHeightChange?: (vh: number) => void;
}

function loadStoredHeight(): number {
  if (typeof window === "undefined") return DEFAULT_HEIGHT_VH;
  try {
    const raw = localStorage.getItem(STORAGE_HEIGHT_KEY);
    const parsed = raw ? parseFloat(raw) : NaN;
    if (!Number.isNaN(parsed) && parsed >= MIN_HEIGHT_VH && parsed <= MAX_HEIGHT_VH) {
      return parsed;
    }
  } catch {
    // ignore
  }
  return DEFAULT_HEIGHT_VH;
}

function AgentConsolePanel({
  isOpen,
  onClose,
  baseURL,
  authToken,
  walletAddress,
  heightVh: heightVhProp,
  onHeightChange,
}: AgentConsolePanelProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: OVERLAY_TIMING.tradeSheetMs,
  });

  useOverlayEscapeKey(isOpen, onClose);

  const [activeTab, setActiveTab] = useState<AgentConsoleTabId>("commandCenter");
  const { agents, selectedAgentId, setSelectedAgentId, getAgentById } =
    useTradingAgents();
  const [internalHeightVh, setInternalHeightVh] = useState(loadStoredHeight);
  const resizeRef = useRef<{ startY: number; startHeight: number } | null>(null);

  const heightVh = heightVhProp ?? internalHeightVh;

  const setHeightVh = useCallback(
    (vh: number) => {
      const clamped = Math.min(MAX_HEIGHT_VH, Math.max(MIN_HEIGHT_VH, vh));
      setInternalHeightVh(clamped);
      onHeightChange?.(clamped);
      try {
        localStorage.setItem(STORAGE_HEIGHT_KEY, String(clamped));
      } catch {
        // ignore
      }
    },
    [onHeightChange],
  );

  useEffect(() => {
    if (!isOpen || agents.length === 0) return;
    if (selectedAgentId && getAgentById(selectedAgentId)) return;
    const active = agents.find((a) => a.status === "active");
    setSelectedAgentId(active?.id ?? agents[0]!.id);
  }, [isOpen, agents, selectedAgentId, getAgentById, setSelectedAgentId]);

  const handleResizePointerDown = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      e.preventDefault();
      resizeRef.current = { startY: e.clientY, startHeight: heightVh };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    },
    [heightVh],
  );

  const handleResizePointerMove = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (!resizeRef.current) return;
      const deltaY = resizeRef.current.startY - e.clientY;
      const deltaVh = (deltaY / window.innerHeight) * 100;
      setHeightVh(resizeRef.current.startHeight + deltaVh);
    },
    [setHeightVh],
  );

  const handleResizePointerUp = useCallback(() => {
    resizeRef.current = null;
  }, []);

  const tabs = (Object.keys(TAB_LABELS) as AgentConsoleTabId[]).map((id) => ({
    id,
    label: TAB_LABELS[id],
  }));

  if (!mounted) return null;

  const panelContent = (
    <StaggeredOverlayRoot className="agent-console-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="agent-console-panel"
        style={{ height: `${heightVh}vh` }}
        aria-label="Agent Console"
      >
        <div
          className="agent-console-resize-handle"
          onPointerDown={handleResizePointerDown}
          onPointerMove={handleResizePointerMove}
          onPointerUp={handleResizePointerUp}
          onPointerCancel={handleResizePointerUp}
          aria-label="Resize agent console"
          role="separator"
          aria-orientation="horizontal"
        />
        <div className="agent-console-header">
          <span className="agent-console-title">Agent Console</span>
          <button
            type="button"
            className="agent-console-close"
            onClick={onClose}
            aria-label="Collapse agent console"
          >
            <ExpandCollapseIcon expanded direction="up" size={16} />
          </button>
        </div>
        <div className="agent-console-tabs-wrap tab-section-root">
          <TabLayoutHeaderToolBar
            tabs={tabs}
            activeTabId={activeTab}
            onTabChange={(id) => setActiveTab(id as AgentConsoleTabId)}
          />
          <div
            className={[
              "agent-console-tab-body",
              "tab-section-content",
              activeTab === "commandCenter" ? "agent-console-tab-body--command" : "",
            ]
              .filter(Boolean)
              .join(" ")}
          >
            {activeTab === "commandCenter" ? <AgentCommandCenterTab /> : null}
            {activeTab === "executionTrace" ? (
              <AgentExecutionTraceTab highlightAgentId={selectedAgentId} />
            ) : null}
            {activeTab === "riskAttribution" ? (
              <WalletConnectedGate
                walletAddress={walletAddress}
                variant="risk"
              >
                <AgentRiskAttributionTab
                  baseURL={baseURL}
                  authToken={authToken}
                  walletAddress={walletAddress}
                  highlightAgentId={selectedAgentId}
                />
              </WalletConnectedGate>
            ) : null}
          </div>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(panelContent, document.body)
    : null;
}

export { STORAGE_OPEN_KEY, STORAGE_HEIGHT_KEY, DEFAULT_HEIGHT_VH };

export default React.memo(AgentConsolePanel);
