import React, { useCallback, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import {
  SORT_DIRECTION_ASC,
  SORT_DIRECTION_DESC,
} from "../../constants";
import { useTickerFavorites } from "../../hooks/useTickerFavorites";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import type { PropertyIndexMode } from "../../../offline/mock_data/types";
import { TableHeaderCell, TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import type { ResolvedIndexConstituent } from "../../utils/indexConstituents";
import {
  buildConstituentTableRows,
  sortConstituentTableRows,
  type ConstituentSortField,
} from "../../utils/indexConstituentTableRows";
import { formatCurrency, formatPercent } from "./indexFormat";
import "./index.css";

export interface IndexConstituentsPanelProps {
  height?: string;
  constituents: ResolvedIndexConstituent[];
  activeMode: PropertyIndexMode["id"];
  modeLabel?: string;
}

const GRID_TEMPLATE_COLUMNS =
  "minmax(3.75rem,0.9fr) minmax(4.5rem,1.15fr) minmax(3.25rem,0.75fr) minmax(3.5rem,0.85fr) minmax(3.75rem,0.9fr) minmax(3.25rem,0.8fr) minmax(3rem,0.75fr) minmax(3rem,0.75fr) 1.25rem";

type SortDirection = typeof SORT_DIRECTION_ASC | typeof SORT_DIRECTION_DESC;

function formatSignedPercent(value: number | null): string {
  if (value == null || Number.isNaN(value)) return "—";
  return formatPercent(value);
}

function signedPercentClass(value: number | null): string {
  if (value == null || Number.isNaN(value)) return "";
  return value >= 0 ? "positive" : "negative";
}

function IndexConstituentsPanel({
  height = "100%",
  constituents,
  activeMode,
  modeLabel,
}: IndexConstituentsPanelProps): JSX.Element {
  const navigate = useNavigate();
  const { favorites, toggleFavorite } = useTickerFavorites();
  const [sortField, setSortField] = useState<ConstituentSortField>("marketCap");
  const [sortDirection, setSortDirection] = useState<SortDirection>(
    SORT_DIRECTION_DESC,
  );

  const tableRows = useMemo(
    () => buildConstituentTableRows(constituents),
    [constituents],
  );

  const sortedRows = useMemo(
    () => sortConstituentTableRows(tableRows, sortField, sortDirection),
    [tableRows, sortField, sortDirection],
  );

  const handleSort = useCallback(
    (field: ConstituentSortField) => {
      if (sortField === field) {
        setSortDirection((prev) =>
          prev === SORT_DIRECTION_ASC
            ? SORT_DIRECTION_DESC
            : SORT_DIRECTION_ASC,
        );
        return;
      }
      setSortField(field);
      setSortDirection(SORT_DIRECTION_DESC);
    },
    [sortField],
  );

  return (
    <div className="index-slot" style={{ height }}>
      <div className="index-slot-body index-slot-body--constituents">
        <div className="index-section-head index-section-head--compact">
          <div>
            <span className="eyebrow-text">Constituents</span>
            <h2>
              {modeLabel ? `${modeLabel} basket` : "Revenue-weighted basket"}
            </h2>
          </div>
        </div>

        <div
          className="index-constituents-table-wrap"
          data-active-mode={activeMode}
        >
          <div className="table-container shrinkable index-constituents-table">
            <div
              className="table-header"
              style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
            >
              <TableHeaderCellStatic left>Coin</TableHeaderCellStatic>
              <TableHeaderCellStatic left>Name</TableHeaderCellStatic>
              <TableHeaderCell
                field="price"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                Price
              </TableHeaderCell>
              <TableHeaderCell
                field="marketCap"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                MarketCap
              </TableHeaderCell>
              <TableHeaderCell
                field="weight"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                <TableHeaderLabel {...TABLE_HEADER_LABELS.positionRatio} />
              </TableHeaderCell>
              <TableHeaderCell
                field="change24h"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                <TableHeaderLabel {...TABLE_HEADER_LABELS.change24h} />
              </TableHeaderCell>
              <TableHeaderCell
                field="roi1m"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                <TableHeaderLabel {...TABLE_HEADER_LABELS.roi1m} />
              </TableHeaderCell>
              <TableHeaderCell
                field="roi1y"
                currentSortField={sortField}
                sortDirection={sortDirection}
                onSort={handleSort}
                left
              >
                <TableHeaderLabel {...TABLE_HEADER_LABELS.roi1y} />
              </TableHeaderCell>
              <TableHeaderCellStatic left aria-label="Favorite">
                {" "}
              </TableHeaderCellStatic>
            </div>

            {sortedRows.map((row, index) => {
              const isFavorite = favorites.includes(row.agentId);
              const agentAvatarSrc = resolveAgentAvatarSvgUrl(row.agentId);

              return (
                <div
                  key={row.agentId}
                  className={`table-row clickable ${index % 2 === 0 ? "even" : ""}`}
                  style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
                  role="button"
                  tabIndex={0}
                  onClick={() => navigate(`/agents/${row.agentId}`)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      navigate(`/agents/${row.agentId}`);
                    }
                  }}
                >
                  <div className="table-cell primary index-constituent-coin-cell">
                    <span className="index-constituent-icon" aria-hidden>
                      <span
                        className="index-constituent-icon-image"
                        style={{
                          maskImage: `url(${agentAvatarSrc})`,
                          WebkitMaskImage: `url(${agentAvatarSrc})`,
                        }}
                      />
                    </span>
                    <strong>{row.ticker}</strong>
                  </div>
                  <div className="table-cell index-constituent-name-cell">
                    {row.name}
                  </div>
                  <div className="table-cell primary">
                    {formatCurrency(row.price)}
                  </div>
                  <div className="table-cell">{row.marketCap}</div>
                  <div className="table-cell">{row.weight.toFixed(2)}%</div>
                  <div
                    className={`table-cell ${signedPercentClass(row.change24h)}`}
                  >
                    {formatSignedPercent(row.change24h)}
                  </div>
                  <div
                    className={`table-cell ${signedPercentClass(row.roi1m)}`}
                  >
                    {formatSignedPercent(row.roi1m)}
                  </div>
                  <div
                    className={`table-cell ${signedPercentClass(row.roi1y)}`}
                  >
                    {formatSignedPercent(row.roi1y)}
                  </div>
                  <div className="table-cell">
                    <button
                      type="button"
                      className={`index-constituent-star ${isFavorite ? "active" : ""}`}
                      aria-label={
                        isFavorite ? "Remove favorite" : "Add favorite"
                      }
                      onClick={(event) => {
                        event.stopPropagation();
                        toggleFavorite(row.agentId);
                      }}
                    >
                      ★
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export default IndexConstituentsPanel;
