import React, { useCallback, useMemo, useState } from "react";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { formatDateTime } from "../../utils/formatDateTime";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import { groupEventsByDay } from "../../utils/groupEventsByDay";
import { shortHashId } from "../../utils/hashId";
import type { AgentTaskStatus } from "../../store/types";
import "../tables/agentTasks.css";
import "./portfolio.css";

export interface MemoryAuditPanelProps {
  height?: string;
  filterAgentIds?: string[];
}

type AuditEvent = {
  id: string;
  at: string;
  kind: "memory" | "status";
  agentLabel: string;
  text: string;
  taskId?: string;
  status?: AgentTaskStatus;
};

type KindFilter = "all" | "memory" | "status";

function getStatusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

function statusPillClass(tone: string): string {
  return `agent-task-status-pill agent-task-status-pill--${tone}`;
}

function emptyMessage(kindFilter: KindFilter): string {
  if (kindFilter === "memory") return "No memory notes yet.";
  if (kindFilter === "status") return "No status transitions yet.";
  return "Memory notes and task status changes will appear here.";
}

function MemoryAuditPanel({
  height = "100%",
  filterAgentIds = [],
}: MemoryAuditPanelProps): JSX.Element {
  const { agents, getAgentById } = useTradingAgents();
  const { tasks } = useAgentTasks();
  const [kindFilter, setKindFilter] = useState<KindFilter>("all");
  const [expandedIds, setExpandedIds] = useState<Set<string>>(() => new Set());

  const events = useMemo(() => {
    const scopedAgents =
      filterAgentIds.length === 0
        ? agents
        : agents.filter((a) => filterAgentIds.includes(a.id));
    const agentIds = new Set(scopedAgents.map((a) => a.id));
    const scopedTasks =
      filterAgentIds.length === 0
        ? tasks
        : tasks.filter((t) => agentIds.has(t.agentId));

    const rows: AuditEvent[] = [];

    for (const agent of scopedAgents) {
      for (const item of agent.memory) {
        rows.push({
          id: `mem-${item.id}`,
          at: item.at,
          kind: "memory",
          agentLabel: agent.displayName,
          text: item.text,
        });
      }
    }

    for (const task of scopedTasks) {
      for (const event of task.statusHistory ?? []) {
        rows.push({
          id: `status-${task.id}-${event.at}-${event.status}`,
          at: event.at,
          kind: "status",
          agentLabel:
            getAgentById(task.agentId)?.displayName ?? task.agentId.slice(0, 8),
          text: event.note ?? "",
          taskId: task.id,
          status: event.status,
        });
      }
    }

    return rows.sort(
      (a, b) => new Date(b.at).getTime() - new Date(a.at).getTime(),
    );
  }, [agents, tasks, filterAgentIds, getAgentById]);

  const filtered = useMemo(() => {
    if (kindFilter === "all") return events;
    return events.filter((e) => e.kind === kindFilter);
  }, [events, kindFilter]);

  const grouped = useMemo(
    () => groupEventsByDay(filtered),
    [filtered],
  );

  const toggleExpanded = useCallback((id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const renderEventBody = (event: AuditEvent) => {
    if (!event.text) return null;

    const isExpanded = expandedIds.has(event.id);
    const bodyClass = [
      "portfolio-memory-audit-body",
      event.kind === "memory"
        ? "portfolio-memory-audit-body--memory"
        : "portfolio-memory-audit-body--status",
      isExpanded ? "is-expanded" : "",
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <button
        type="button"
        className={bodyClass}
        aria-expanded={isExpanded}
        onClick={() => toggleExpanded(event.id)}
      >
        {event.text}
      </button>
    );
  };

  const renderEventRow = (event: AuditEvent) => {
    const statusCfg =
      event.kind === "status" && event.status
        ? getStatusConfig(event.status)
        : null;
    const itemClass = [
      "portfolio-memory-audit-item",
      event.kind === "memory" ? "is-memory" : "is-status",
      statusCfg ? `is-tone-${statusCfg.tone}` : "",
    ]
      .filter(Boolean)
      .join(" ");

    const pillClass =
      event.kind === "memory"
        ? statusPillClass("muted")
        : statusPillClass(statusCfg?.tone ?? "muted");
    const pillLabel =
      event.kind === "memory" ? "Memory" : (statusCfg?.label ?? "Status");

    return (
      <li key={event.id} className={itemClass}>
        <div className="portfolio-memory-audit-meta">
          <span className={pillClass}>{pillLabel}</span>
          <span
            className="portfolio-memory-audit-agent"
            title={event.agentLabel}
          >
            {event.agentLabel}
          </span>
          {event.taskId ? (
            <span className="task-id-chip" title={event.taskId}>
              {shortHashId(event.taskId)}
            </span>
          ) : (
            <span className="portfolio-memory-audit-task-slot" aria-hidden />
          )}
          <time
            className="terminal-text-muted portfolio-memory-audit-time"
            dateTime={event.at}
            title={formatDateTime(event.at)}
          >
            {formatRelativeTime(event.at)}
          </time>
        </div>
        {renderEventBody(event)}
      </li>
    );
  };

  return (
    <div className="portfolio-memory-audit" style={{ height }}>
      <div className="portfolio-memory-audit-toolbar">
        {(["all", "memory", "status"] as const).map((kind) => (
          <button
            key={kind}
            type="button"
            className={`portfolio-fleet-chip${kindFilter === kind ? " is-selected" : ""}`}
            aria-pressed={kindFilter === kind}
            onClick={() => setKindFilter(kind)}
          >
            {kind === "all" ? "All" : kind === "memory" ? "Memory" : "Status"}
          </button>
        ))}
      </div>
      <ol
        className="portfolio-memory-audit-list"
        aria-label="Agent memory and task status audit log"
      >
        {filtered.length === 0 ? (
          <li className="portfolio-memory-audit-empty terminal-text-muted">
            {emptyMessage(kindFilter)}
          </li>
        ) : (
          grouped.map((group) => (
            <React.Fragment key={group.day}>
              <li
                className="portfolio-memory-audit-daydivider"
                aria-hidden="true"
              >
                {group.label}
              </li>
              {group.events.map(renderEventRow)}
            </React.Fragment>
          ))
        )}
      </ol>
    </div>
  );
}

export default React.memo(MemoryAuditPanel);
