const DEFAULT_BAR_SPACING = 6;
const MIN_BAR_SPACING = 2;
const MAX_BAR_SPACING = 50;
const LIVE_SCROLL_THRESHOLD = 0.5;
const DRAG_THRESHOLD_PX = 4;
const PENDING_VIEW_RIGHT_PADDING_PX = 100;
const SCROLL_TO_POSITION_ANIMATION_MS = 700;
const LIVE_RIGHT_OFFSET_BARS = 5;

interface PinnedViewport {
  time: UTCTimestamp;
  halfWindowSec: number;
}

function barTimesFromCandles(data: CandlestickData[] | undefined): number[] {
  if (!data?.length) return [];
  return data.map((bar) => bar.time as number);
}

function clampLiveVisibleLogicalRange(
  chart: IChartApi,
  maxVisibleLogicalBars: number,
): void {
  if (maxVisibleLogicalBars <= 0) return;
  const timeScale = chart.timeScale();
  const range = timeScale.getVisibleLogicalRange();
  if (!range) return;
  const span = Math.max(0, Math.ceil(range.to) - Math.floor(range.from));
  if (span <= maxVisibleLogicalBars) return;
  timeScale.setVisibleLogicalRange({
    from: range.to - maxVisibleLogicalBars,
    to: range.to,
  });
}

function applyPinnedViewport(
  chart: IChartApi,
  pin: PinnedViewport,
  intervalSec: number,
  barTimes: readonly number[] | undefined,
): boolean {
  if (!barTimes?.length) return false;
  const resolved = resolveTimeToNearestBar(pin.time as number, barTimes);
  if (resolved == null) return false;

  pin.time = resolved;

  chart.applyOptions({ timeScale: { shiftVisibleRangeOnNewBar: false } });
  const timeScale = chart.timeScale();
  const halfWindow = Math.max(pin.halfWindowSec, 60);
  const logical = timeScale.timeToIndex(resolved, true);
  if (logical === null) return false;

  const spanBars = Math.max(30, Math.ceil((halfWindow * 2) / intervalSec));
  timeScale.setVisibleLogicalRange({
    from: logical - spanBars / 2,
    to: logical + spanBars / 2,
  });
  return true;
}

function viewportContainsPin(chart: IChartApi, pin: PinnedViewport): boolean {
  return chart.timeScale().timeToCoordinate(pin.time) !== null;
}

function createRafCoalescer(fn: () => void): () => void {
  let id = 0;
  return () => {
    if (id) return;
    id = requestAnimationFrame(() => {
      id = 0;
      fn();
    });
  };
}

function scrollRealtimeBarToRightPadding(
  chart: IChartApi,
  paddingPx: number,
  barSpacing: number,
): void {
  const targetOffset = paddingPx / barSpacing;
  chart.applyOptions({ timeScale: { shiftVisibleRangeOnNewBar: false } });
  chart.timeScale().scrollToPosition(targetOffset, true);
}

function buildVolumeHistogramData(
  candles: CandlestickData[],
  volumeByTime: ReadonlyMap<number, number> | undefined,
): HistogramData[] {
  if (!volumeByTime || volumeByTime.size === 0) return [];
  const bars: HistogramData[] = [];
  for (const bar of candles) {
    const volume = volumeByTime.get(bar.time as number);
    if (volume == null || volume <= 0) continue;
    const isUp = bar.close >= bar.open;
    bars.push({
      time: bar.time,
      value: volume,
      color: isUp ? TERMINAL_COLORS.longSoft : TERMINAL_COLORS.shortSoft,
    });
  }
  return bars;
}

function seedChartSeriesData(
  chart: IChartApi,
  candlestickSeries: ISeriesApi<"Candlestick">,
  volumeSeries: ISeriesApi<"Histogram"> | null,
  data: CandlestickData[],
  volumeByTime: ReadonlyMap<number, number> | undefined,
  showVolume: boolean,
  scrollMode: "live" | "fit",
  pinnedViewport?: PinnedViewport | null,
  intervalSec = 300,
  seedMaxVisibleLogicalBars?: number,
): boolean {
  if (data.length === 0) return false;
  candlestickSeries.setData(data);
  if (showVolume && volumeSeries) {
    const volumeData = buildVolumeHistogramData(data, volumeByTime);
    if (volumeData.length > 0) {
      volumeSeries.setData(volumeData);
    }
  }
  if (pinnedViewport) {
    const barTimes = barTimesFromCandles(data);
    if (applyPinnedViewport(chart, pinnedViewport, intervalSec, barTimes)) {
      return true;
    }
  }
  const timeScale = chart.timeScale();
  if (scrollMode === "live") {
    timeScale.scrollToRealTime();
    if (seedMaxVisibleLogicalBars != null) {
      clampLiveVisibleLogicalRange(chart, seedMaxVisibleLogicalBars);
    }
  } else {
    timeScale.fitContent();
  }
  return false;
}

export type MarkerInteractionPoint = { x: number; y: number };

export type MarkerInteractionHandler = (
  tradeId: string | null,
  point: MarkerInteractionPoint | null,
) => void;

function getMarkerTradeId(param: MouseEventParams<Time>): string | undefined {
  if (param.hoveredInfo?.objectKind !== "series-marker") return undefined;
  const id = param.hoveredInfo.objectId;
  return id != null ? String(id) : undefined;
}

function getOrderLineId(
  param: MouseEventParams<Time>,
  orderLineIds: Set<string>,
): string | undefined {
  if (param.hoveredInfo?.objectKind !== "primitive") return undefined;
  const id = param.hoveredInfo.objectId;
  if (id == null) return undefined;
  const lineId = String(id);
  return orderLineIds.has(lineId) ? lineId : undefined;
}

function resolveMarkerInteractionPoint(
  chart: IChartApi,
  series: ISeriesApi<"Candlestick">,
  tradeId: string,
  markers: ChartExecutionMarker[],
  barSpacing: number,
): MarkerInteractionPoint | null {
  const barSpacingFromChart = chart.timeScale().options().barSpacing ?? barSpacing;
  return resolveLaidOutMarkerAnchorPoint(
    chart,
    series,
    tradeId,
    markers,
    barSpacingFromChart,
  );
}

export type OrderLineInteractionHandler = (
  lineId: string | null,
  point: MarkerInteractionPoint | null,
) => void;

export interface ChartOverlayLayout {
  widgetWidth: number;
  widgetHeight: number;
  canvasOffsetLeft: number;
  canvasOffsetTop: number;
  canvasWidth: number;
  canvasHeight: number;
  paneWidth: number;
  priceScaleWidth: number;
}

export interface KlineChartProps {
  initialData?: CandlestickData[]; // Optional historical data
  volumeByTime?: ReadonlyMap<number, number>;
  symbol?: string; // e.g., "BTC/USDC"
  interval?: string; // e.g., "5m" — used for time-axis label formatting
  height?: number; // Chart height in pixels
  showVolume?: boolean; // Whether to show volume histogram
  /** How to position the viewport after a full data seed. Live charts use "live". */
  seedScrollMode?: "live" | "fit";
  /** When set, chart seeds and re-seeds scroll to this time instead of live edge. */
  autoScrollToTime?: UTCTimestamp | null;
  autoScrollHalfWindowSec?: number;
  /** After live-edge seed, clamp visible logical span to this bar count. */
  seedMaxVisibleLogicalBars?: number;
  markers?: ChartExecutionMarker[];
  /** Full marker list for active-trade anchor lookup; defaults to `markers`. */
  anchorMarkers?: ChartExecutionMarker[];
  orderLines?: ChartPendingOrderLine[];
  orderLinePriceOverrides?: ReadonlyMap<string, number>;
  onMarkerHover?: MarkerInteractionHandler;
  onMarkerClick?: MarkerInteractionHandler;
  onOrderLineHover?: OrderLineInteractionHandler;
  onOrderLineClick?: OrderLineInteractionHandler;
  overlay?: ReactNode;
  overlayHostRef?: RefObject<HTMLElement | null>;
  layoutRootRef?: RefObject<HTMLElement | null>;
  onOverlayLayout?: (layout: ChartOverlayLayout) => void;
  resetScrollKey?: string;
  activeTradeId?: string | null;
  activeOrderLineId?: string | null;
  onActiveAnchorMove?: (tradeId: string, point: MarkerInteractionPoint) => void;
  onActiveOrderLineAnchorMove?: (lineId: string, point: MarkerInteractionPoint) => void;
  onCoarserInterval?: () => void;
  onFinerInterval?: () => void;
  canCoarserInterval?: boolean;
  canFinerInterval?: boolean;
  showPendingViewButton?: boolean;
  onReady?: () => void;
  /** Fires when the chart visible logical range changes (pan/zoom). */
  onVisibleLogicalRangeChange?: (range: LogicalRange | null) => void;
}

const DEFAULT_SCROLL_TO_TIME_HALF_WINDOW_SEC = 30 * 300;

export interface KlineChartRef {
  updateChart: (kline: KlineUpdate) => void;
  scrollToLatest: () => void;
  scrollToTime: (time: UTCTimestamp, halfWindowSec?: number) => void;
  scrollByBars: (direction: number) => void;
  zoomBy: (factor: number) => void;
  /** Re-push execution markers and order lines after viewport or candle data changes. */
  repushOverlays: () => void;
  coordinateToPrice: (clientY: number) => number | null;
  priceToCoordinate: (price: number) => number | null;
}

export interface KlineUpdate {
  openTime?: number; // Unix timestamp in milliseconds
  closeTime?: number; // Unix timestamp in milliseconds
  open: string | number;
  high: string | number;
  low: string | number;
  close: string | number;
  volume?: string | number;
}

const KlineChart = forwardRef<KlineChartRef, KlineChartProps>(
  ({
    initialData = [] as CandlestickData[],
    volumeByTime,
    symbol = "BTC/USDC",
    interval = "5m",
    height = 500,
    showVolume = true,
    seedScrollMode = "live",
    autoScrollToTime = null,
    autoScrollHalfWindowSec = DEFAULT_SCROLL_TO_TIME_HALF_WINDOW_SEC,
    seedMaxVisibleLogicalBars,
    markers = [],
    anchorMarkers,
    orderLines = [] as ChartPendingOrderLine[],
    orderLinePriceOverrides,
    onMarkerHover,
    onMarkerClick,
    onOrderLineHover,
    onOrderLineClick,
    overlay,
    overlayHostRef,
    layoutRootRef,
    onOverlayLayout,
    resetScrollKey,
    activeTradeId,
    activeOrderLineId,
    onActiveAnchorMove,
    onActiveOrderLineAnchorMove,
    onCoarserInterval,
    onFinerInterval,
    canCoarserInterval = false,
    canFinerInterval = false,
    showPendingViewButton = false,
    onReady,
    onVisibleLogicalRangeChange,
  }, ref) => {
    const chartContainerRef = useRef<HTMLDivElement>(null);
    const canvasWrapperRef = useRef<HTMLDivElement>(null);
    const mountedRef = useRef(true);
    const scheduledRafIdsRef = useRef<number[]>([]);
    const chartRef = useRef<IChartApi | null>(null);
    const candlestickSeriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);
    const volumeSeriesRef = useRef<ISeriesApi<"Histogram"> | null>(null);
    const executionMarkersRef = useRef<ExecutionMarkersPrimitive | null>(null);
    const pendingOrderLinesRef = useRef<PendingOrderLinesPrimitive | null>(null);
    const followLiveRef = useRef(true);
    const pinnedViewportRef = useRef<PinnedViewport | null>(null);
    const autoScrollToTimeRef = useRef<UTCTimestamp | null>(autoScrollToTime);
    autoScrollToTimeRef.current = autoScrollToTime;
    const autoScrollHalfWindowSecRef = useRef(autoScrollHalfWindowSec);
    autoScrollHalfWindowSecRef.current = autoScrollHalfWindowSec;
    const seedMaxVisibleLogicalBarsRef = useRef(seedMaxVisibleLogicalBars);
    seedMaxVisibleLogicalBarsRef.current = seedMaxVisibleLogicalBars;

    const resolveSeedPinnedViewport = useCallback((): PinnedViewport | null => {
      if (pinnedViewportRef.current) return pinnedViewportRef.current;
      const time = autoScrollToTimeRef.current;
      if (time == null) return null;
      const pin: PinnedViewport = {
        time,
        halfWindowSec: Math.max(autoScrollHalfWindowSecRef.current, 60),
      };
      pinnedViewportRef.current = pin;
      return pin;
    }, []);
    const resolveSeedPinnedViewportRef = useRef(resolveSeedPinnedViewport);
    resolveSeedPinnedViewportRef.current = resolveSeedPinnedViewport;
    const isPanningRef = useRef(false);
    const pendingBarRef = useRef<KlineUpdate | null>(null);
    const pendingPriceRef = useRef<number | null>(null);
    const barSpacingRef = useRef(DEFAULT_BAR_SPACING);
    const onMarkerHoverRef = useRef(onMarkerHover);
    const onMarkerClickRef = useRef(onMarkerClick);
    const onOrderLineHoverRef = useRef(onOrderLineHover);
    const onOrderLineClickRef = useRef(onOrderLineClick);
    const onOverlayLayoutRef = useRef(onOverlayLayout);
    const overlayHostRefProp = overlayHostRef;
    const layoutRootRefProp = layoutRootRef;
    const activeTradeIdRef = useRef(activeTradeId);
    const activeOrderLineIdRef = useRef(activeOrderLineId);
    const onActiveAnchorMoveRef = useRef(onActiveAnchorMove);
    const onActiveOrderLineAnchorMoveRef = useRef(onActiveOrderLineAnchorMove);
    const onReadyRef = useRef(onReady);
    const onVisibleLogicalRangeChangeRef = useRef(onVisibleLogicalRangeChange);
    const readyNotifiedRef = useRef(false);
    const initialDataRef = useRef(initialData);
    const volumeByTimeRef = useRef(volumeByTime);
    const seedScrollModeRef = useRef(seedScrollMode);
    const markersListRef = useRef(markers);
    const markerAnchorListRef = useRef(anchorMarkers ?? markers);
    const orderLinesListRef = useRef(orderLines);
    const orderLineIdsRef = useRef(new Set<string>());
    const orderLinePriceOverridesRef = useRef<ReadonlyMap<string, number>>(
      orderLinePriceOverrides ?? new Map(),
    );
    onMarkerHoverRef.current = onMarkerHover;
    onMarkerClickRef.current = onMarkerClick;
    onOrderLineHoverRef.current = onOrderLineHover;
    onOrderLineClickRef.current = onOrderLineClick;
    onOverlayLayoutRef.current = onOverlayLayout;
    activeTradeIdRef.current = activeTradeId;
    activeOrderLineIdRef.current = activeOrderLineId;
    onActiveAnchorMoveRef.current = onActiveAnchorMove;
    onActiveOrderLineAnchorMoveRef.current = onActiveOrderLineAnchorMove;
    onReadyRef.current = onReady;
    onVisibleLogicalRangeChangeRef.current = onVisibleLogicalRangeChange;
    initialDataRef.current = initialData;
    volumeByTimeRef.current = volumeByTime;
    seedScrollModeRef.current = seedScrollMode;
    markersListRef.current = markers;
    markerAnchorListRef.current = anchorMarkers ?? markers;
    orderLinesListRef.current = orderLines;
    orderLineIdsRef.current = new Set(orderLines.map((line) => line.lineId));
    orderLinePriceOverridesRef.current = orderLinePriceOverrides ?? new Map();

    const cancelScheduledRafs = useCallback(() => {
      for (const id of scheduledRafIdsRef.current) {
        cancelAnimationFrame(id);
      }
      scheduledRafIdsRef.current = [];
    }, []);

    const scheduleRaf = useCallback((fn: () => void) => {
      const outerId = requestAnimationFrame(() => {
        const innerId = requestAnimationFrame(() => {
          if (!mountedRef.current) return;
          fn();
        });
        scheduledRafIdsRef.current.push(innerId);
      });
      scheduledRafIdsRef.current.push(outerId);
    }, []);

    const repushChartOverlays = useCallback(() => {
      try {
        executionMarkersRef.current?.setMarkers(markersListRef.current);
        pendingOrderLinesRef.current?.setLines(orderLinesListRef.current);
        pendingOrderLinesRef.current?.setPriceOverrides(orderLinePriceOverridesRef.current);
      } catch (error) {
        console.error("[KlineChart] Error repushing chart overlays:", error);
      }
    }, []);

    const repushChartOverlaysRef = useRef(repushChartOverlays);
    repushChartOverlaysRef.current = repushChartOverlays;

    const scheduleRepushChartOverlays = useCallback(() => {
      scheduleRaf(() => {
        repushChartOverlaysRef.current();
      });
    }, [scheduleRaf]);

    const repushOverlays = useCallback(() => {
      repushChartOverlays();
      scheduleRepushChartOverlays();
    }, [repushChartOverlays, scheduleRepushChartOverlays]);

    const notifyReadyIfEligible = useCallback(() => {
      if (readyNotifiedRef.current) return;
      if (!chartRef.current || !candlestickSeriesRef.current) return;
      if (initialDataRef.current.length === 0) return;
      readyNotifiedRef.current = true;
      onReadyRef.current?.();
    }, []);

    const notifyReadyIfEligibleRef = useRef(notifyReadyIfEligible);
    notifyReadyIfEligibleRef.current = notifyReadyIfEligible;

    const scheduleReadyAfterPaintRef = useRef(() => {
      scheduleRaf(() => {
        notifyReadyIfEligibleRef.current();
      });
    });
    const [overlayPortalHost, setOverlayPortalHost] = useState<HTMLElement | null>(null);
    const [currentPrice, setCurrentPrice] = useState<number | null>(null);
    const [showNavToolbar, setShowNavToolbar] = useState(false);
    const [chartInstance, setChartInstance] = useState<IChartApi | null>(null);
    const showVolumeRef = useRef(showVolume);
    showVolumeRef.current = showVolume;
    const setCurrentPriceSafe = useCallback((price: number) => {
      if (mountedRef.current) setCurrentPrice(price);
    }, []);
    const setShowNavToolbarSafe = useCallback((show: boolean) => {
      if (mountedRef.current) setShowNavToolbar(show);
    }, []);
    const setCurrentPriceRef = useRef(setCurrentPriceSafe);
    setCurrentPriceRef.current = setCurrentPriceSafe;
    const flushPendingBarUpdateRef = useRef<() => void>(() => {});
    const scheduleBarUpdateRef = useRef(createRafCoalescer(() => flushPendingBarUpdateRef.current()));
    const pendingViewScrollTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const clearPendingViewScrollTimeout = useCallback(() => {
      if (pendingViewScrollTimeoutRef.current != null) {
        window.clearTimeout(pendingViewScrollTimeoutRef.current);
        pendingViewScrollTimeoutRef.current = null;
      }
    }, []);

    const disableFollowLive = useCallback(() => {
      if (!followLiveRef.current) return;
      followLiveRef.current = false;
      setShowNavToolbarSafe(true);
    }, [setShowNavToolbarSafe]);

    const markOffLive = useCallback(() => {
      followLiveRef.current = false;
    }, []);

    const enableFollowLive = useCallback(() => {
      clearPendingViewScrollTimeout();
      pinnedViewportRef.current = null;
      followLiveRef.current = true;
      setShowNavToolbarSafe(false);
      chartRef.current?.applyOptions({
        timeScale: {
          rightOffsetPixels: undefined,
          rightOffset: LIVE_RIGHT_OFFSET_BARS,
          shiftVisibleRangeOnNewBar: true,
        },
      });
      chartRef.current?.timeScale().scrollToRealTime();
      candlestickSeriesRef.current?.priceScale().setAutoScale(true);
    }, [clearPendingViewScrollTimeout, setShowNavToolbarSafe]);

    const scrollToLatest = useCallback(() => {
      enableFollowLive();
    }, [enableFollowLive]);

    const fitToPendingOrderLines = useCallback(() => {
      const chart = chartRef.current;
      const series = candlestickSeriesRef.current;
      if (!chart || !series) return;
      const range = pendingOrderLinePriceRange(orderLinesListRef.current);
      if (!range) return;

      series.priceScale().setAutoScale(false);
      series.priceScale().setVisibleRange(range);
      disableFollowLive();

      clearPendingViewScrollTimeout();
      const barSpacing = chart.timeScale().options().barSpacing ?? barSpacingRef.current;
      scrollRealtimeBarToRightPadding(chart, PENDING_VIEW_RIGHT_PADDING_PX, barSpacing);
      pendingViewScrollTimeoutRef.current = window.setTimeout(() => {
        pendingViewScrollTimeoutRef.current = null;
        chartRef.current?.applyOptions({
          timeScale: { rightOffsetPixels: PENDING_VIEW_RIGHT_PADDING_PX },
        });
      }, SCROLL_TO_POSITION_ANIMATION_MS);

      repushChartOverlaysRef.current();
      scheduleRaf(() => {
        repushChartOverlaysRef.current();
      });
    }, [clearPendingViewScrollTimeout, disableFollowLive, scheduleRaf]);

    const intervalSec = useMemo(() => intervalToSeconds(interval), [interval]);
    const intervalSecRef = useRef(intervalSec);
    intervalSecRef.current = intervalSec;

    const applyPinnedScrollAndRepush = useCallback(
      (time: UTCTimestamp, halfWindowSec: number) => {
        const chart = chartRef.current;
        if (!chart || isPanningRef.current) return;

        const barTimes = barTimesFromCandles(initialDataRef.current);
        const halfWindow = Math.max(halfWindowSec, 60);
        pinnedViewportRef.current = { time, halfWindowSec: halfWindow };

        const applied = applyPinnedViewport(
          chart,
          pinnedViewportRef.current,
          intervalSecRef.current,
          barTimes,
        );
        if (!applied) {
          pinnedViewportRef.current = null;
          chart.timeScale().scrollToRealTime();
          return;
        }

        followLiveRef.current = false;
        setShowNavToolbarSafe(true);

        const repushIfPinVisible = () => {
          const currentChart = chartRef.current;
          const pin = pinnedViewportRef.current;
          if (!currentChart || !pin || !viewportContainsPin(currentChart, pin)) return;
          repushChartOverlaysRef.current();
        };

        repushIfPinVisible();
        scheduleRaf(() => {
          const currentChart = chartRef.current;
          const pin = pinnedViewportRef.current;
          if (!currentChart || !pin || isPanningRef.current) return;
          const freshBarTimes = barTimesFromCandles(initialDataRef.current);
          applyPinnedViewport(currentChart, pin, intervalSecRef.current, freshBarTimes);
          repushIfPinVisible();
          scheduleRaf(repushIfPinVisible);
        });
      },
      [scheduleRaf, setShowNavToolbarSafe],
    );

    const applyPinnedScrollAndRepushRef = useRef(applyPinnedScrollAndRepush);
    applyPinnedScrollAndRepushRef.current = applyPinnedScrollAndRepush;

    const scrollToTime = useCallback(
      (time: UTCTimestamp, halfWindowSec = DEFAULT_SCROLL_TO_TIME_HALF_WINDOW_SEC) => {
        applyPinnedScrollAndRepushRef.current(time, halfWindowSec);
      },
      [],
    );

    const scrollByBars = useCallback((direction: number) => {
      const chart = chartRef.current;
      if (!chart || direction === 0) return;

      pinnedViewportRef.current = null;
      const timeScale = chart.timeScale();
      const range = timeScale.getVisibleLogicalRange();
      if (!range) return;

      const span = range.to - range.from;
      const shift = span * 0.25 * (direction > 0 ? 1 : -1);
      timeScale.setVisibleLogicalRange({
        from: range.from + shift,
        to: range.to + shift,
      });
      disableFollowLive();
    }, [disableFollowLive]);

    const zoomBy = useCallback((factor: number) => {
      const chart = chartRef.current;
      if (!chart || factor <= 0) return;

      const nextSpacing = Math.min(
        MAX_BAR_SPACING,
        Math.max(MIN_BAR_SPACING, barSpacingRef.current * factor),
      );
      barSpacingRef.current = nextSpacing;
      chart.applyOptions({ timeScale: { barSpacing: nextSpacing } });
    }, []);

    const disableFollowLiveRef = useRef(disableFollowLive);
    disableFollowLiveRef.current = disableFollowLive;
    const markOffLiveRef = useRef(markOffLive);
    markOffLiveRef.current = markOffLive;
    const isPanningRefForPointer = isPanningRef;
    const setShowNavToolbarRef = useRef(setShowNavToolbarSafe);
    setShowNavToolbarRef.current = setShowNavToolbarSafe;

    const updateActiveMarkerAnchor = useCallback((chart: IChartApi, series: ISeriesApi<"Candlestick">) => {
      const tradeId = activeTradeIdRef.current;
      const handler = onActiveAnchorMoveRef.current;
      if (tradeId && handler) {
        const point = resolveMarkerInteractionPoint(
          chart,
          series,
          tradeId,
          markerAnchorListRef.current,
          barSpacingRef.current,
        );
        if (point) {
          handler(tradeId, point);
        }
      }

      const lineId = activeOrderLineIdRef.current;
      const lineHandler = onActiveOrderLineAnchorMoveRef.current;
      if (lineId && lineHandler) {
        const point = resolveOrderLineAnchorPoint(
          chart,
          series,
          lineId,
          orderLinesListRef.current,
          orderLinePriceOverridesRef.current,
        );
        if (point) {
          lineHandler(lineId, point);
        }
      }
    }, []);
    const updateActiveMarkerAnchorRef = useRef(updateActiveMarkerAnchor);
    updateActiveMarkerAnchorRef.current = updateActiveMarkerAnchor;

    const notifyOverlayLayout = useCallback(() => {
      const wrapper = canvasWrapperRef.current;
      const host = overlayHostRefProp?.current;
      const callback = onOverlayLayoutRef.current;
      if (!wrapper || !host || !callback) return;

      const hostRect = host.getBoundingClientRect();
      const canvasRect = wrapper.getBoundingClientRect();
      const chart = chartRef.current;
      const series = candlestickSeriesRef.current;
      let paneWidth = canvasRect.width;
      let priceScaleWidth = 0;
      if (chart && series) {
        const pane = chart.paneSize(series.getPane().paneIndex());
        paneWidth = pane.width;
        priceScaleWidth = series.priceScale().width();
      }
      callback({
        widgetWidth: hostRect.width,
        widgetHeight: hostRect.height,
        canvasOffsetLeft: canvasRect.left - hostRect.left,
        canvasOffsetTop: canvasRect.top - hostRect.top,
        canvasWidth: canvasRect.width,
        canvasHeight: canvasRect.height,
        paneWidth,
        priceScaleWidth,
      });
    }, [overlayHostRefProp]);

    const notifyOverlayLayoutRef = useRef(notifyOverlayLayout);
    notifyOverlayLayoutRef.current = notifyOverlayLayout;

    useLayoutEffect(() => {
      const host = overlayHostRefProp?.current ?? null;
      setOverlayPortalHost((prev) => (prev === host ? prev : host));
    });

    // Convert satoshi string to decimal number
    const parsePrice = (price: string | number | undefined | null): number => {
      // Handle undefined/null
      if (price === undefined || price === null) {
        console.warn("[KlineChart] Invalid price: undefined or null");
        return 0;
      }
      
      if (typeof price === "number") {
        if (isNaN(price) || !isFinite(price) || price < 0) {
          console.warn("[KlineChart] Invalid price number:", price);
          return 0;
        }
        return price;
      }
      
      if (typeof price === "string") {
        if (price.trim() === "") {
          console.warn("[KlineChart] Invalid price: empty string");
          return 0;
        }
        const asDecimal = parseFloat(price);
        if (Number.isFinite(asDecimal) && asDecimal > 0) {
          return asDecimal;
        }
        try {
          const parsed = fromSatoshi(price);
          if (isNaN(parsed) || !isFinite(parsed) || parsed < 0) {
            console.warn("[KlineChart] Invalid price after conversion:", price, "->", parsed);
            return 0;
          }
          return parsed;
        } catch (error) {
          console.error("[KlineChart] Error parsing price:", price, error);
          return 0;
        }
      }
      
      // Fallback for any other type
      console.warn("[KlineChart] Invalid price type:", typeof price, price);
      return 0;
    };

    // Convert kline update to chart data format
    const convertKlineToBar = (kline: KlineUpdate): CandlestickData | null => {
      // Validate required fields
      if (
        kline.open === undefined || kline.open === null ||
        kline.high === undefined || kline.high === null ||
        kline.low === undefined || kline.low === null ||
        kline.close === undefined || kline.close === null
      ) {
        console.warn("[KlineChart] Missing required OHLC fields:", kline);
        return null;
      }
      
      const time = Math.floor((kline.openTime ?? kline.closeTime ?? Date.now()) / 1000) as UTCTimestamp;
      const open = parsePrice(kline.open);
      const high = parsePrice(kline.high);
      const low = parsePrice(kline.low);
      const close = parsePrice(kline.close);
      
      // Validate parsed prices are valid
      if (open <= 0 || high <= 0 || low <= 0 || close <= 0) {
        console.warn("[KlineChart] Invalid kline data - non-positive prices detected:", {
          original: kline,
          parsed: { open, high, low, close },
        });
        return null;
      }
      
      // Validate and correct data integrity (OHLC requirements)
      // High must be >= max(open, high, low, close)
      // Low must be <= min(open, high, low, close)
      const actualHigh = Math.max(open, high, low, close);
      const actualLow = Math.min(open, high, low, close);
      
      if (high !== actualHigh || low !== actualLow) {
        console.warn("[KlineChart] Kline data corrected - high/low were not extremes:", {
          original: { high, low },
          corrected: { high: actualHigh, low: actualLow },
        });
      }
      
      return {
        time,
        open,
        high: actualHigh,
        low: actualLow,
        close,
      };
    };

    // Convert kline update to volume data format
    const convertKlineToVolume = (kline: KlineUpdate): HistogramData | null => {
      if (!kline.volume) return null;
      
      const time = Math.floor((kline.openTime ?? kline.closeTime ?? Date.now()) / 1000) as UTCTimestamp;
      
      let volume: number;
      if (typeof kline.volume === "number") {
        if (isNaN(kline.volume) || !isFinite(kline.volume) || kline.volume < 0) {
          console.warn("[KlineChart] Invalid volume number:", kline.volume);
          return null;
        }
        volume = kline.volume;
      } else if (typeof kline.volume === "string" && kline.volume.trim() !== "") {
        try {
          volume = fromSatoshi(kline.volume);
          if (isNaN(volume) || !isFinite(volume) || volume < 0) {
            console.warn("[KlineChart] Invalid volume after conversion:", kline.volume, "->", volume);
            return null;
          }
        } catch (error) {
          console.error("[KlineChart] Error converting volume from satoshi:", kline.volume, error);
          return null;
        }
      } else {
        console.warn("[KlineChart] Invalid volume type:", typeof kline.volume, kline.volume);
        return null;
      }
      
      const close = parsePrice(kline.close);
      const open = parsePrice(kline.open);
      
      // Validate prices are valid before determining color
      if (close <= 0 || open <= 0) {
        console.warn("[KlineChart] Invalid prices for volume color calculation:", { open, close });
        return null;
      }
      
      const isUp = close >= open;

      return {
        time,
        value: volume,
        color: isUp ? TERMINAL_COLORS.longSoft : TERMINAL_COLORS.shortSoft,
      };
    };

    // Function to update with new Kline bar (exposed via ref)
    flushPendingBarUpdateRef.current = () => {
      const kline = pendingBarRef.current;
      if (!kline || !candlestickSeriesRef.current) return;

      pendingBarRef.current = null;

      try {
        const bar = convertKlineToBar(kline);
        if (!bar) return;

        const volumeBar = showVolumeRef.current ? convertKlineToVolume(kline) : null;

        candlestickSeriesRef.current.update(bar);

        if (showVolumeRef.current && volumeSeriesRef.current && volumeBar) {
          volumeSeriesRef.current.update(volumeBar);
        }

        if (isPanningRef.current) {
          pendingPriceRef.current = bar.close;
        } else {
          setCurrentPriceRef.current(bar.close);
        }
      } catch (error) {
        console.error("[KlineChart] Error updating chart:", error);
      }
    };

    const updateChart = (kline: KlineUpdate) => {
      if (!candlestickSeriesRef.current) {
        console.warn("[KlineChart] updateChart called before chart is initialized");
        return;
      }

      if (!kline || typeof kline !== "object") {
        console.warn("[KlineChart] Invalid kline update data:", kline);
        return;
      }

      pendingBarRef.current = kline;
      scheduleBarUpdateRef.current();
    };

    // Expose chart controls via ref
    useImperativeHandle(ref, () => ({
      updateChart,
      scrollToLatest,
      scrollToTime,
      scrollByBars,
      zoomBy,
      repushOverlays,
      coordinateToPrice: (clientY: number) => {
        const wrapper = canvasWrapperRef.current;
        const series = candlestickSeriesRef.current;
        if (!wrapper || !series) return null;
        const rect = wrapper.getBoundingClientRect();
        const y = clientY - rect.top;
        const price = series.coordinateToPrice(y);
        return price ?? null;
      },
      priceToCoordinate: (price: number) => {
        const series = candlestickSeriesRef.current;
        if (!series) return null;
        const y = series.priceToCoordinate(price);
        return y ?? null;
      },
    }));

    useEffect(() => {
      mountedRef.current = true;
      return () => {
        mountedRef.current = false;
        cancelScheduledRafs();
      };
    }, [cancelScheduledRafs]);

    useEffect(() => {
      return () => {
        clearPendingViewScrollTimeout();
      };
    }, [clearPendingViewScrollTimeout]);

    useEffect(() => {
      if (resetScrollKey === undefined) return;

      let outerFrameId = 0;
      let innerFrameId = 0;

      const applyResetScroll = () => {
        if (!mountedRef.current) return;
        const hasAutoScroll = autoScrollToTimeRef.current != null;
        if (!hasAutoScroll) {
          pinnedViewportRef.current = null;
          followLiveRef.current = true;
          setShowNavToolbarSafe(false);
        }
        barSpacingRef.current = DEFAULT_BAR_SPACING;

        const chart = chartRef.current;
        const series = candlestickSeriesRef.current;
        const volSeries = volumeSeriesRef.current;
        const data = initialDataRef.current;
        if (!chart || !series || data.length === 0) return;

        if (!hasAutoScroll) {
          chart.applyOptions({ timeScale: { shiftVisibleRangeOnNewBar: true } });
        }

        chart.applyOptions({ timeScale: { barSpacing: DEFAULT_BAR_SPACING } });
        const pinnedApplied = seedChartSeriesData(
          chart,
          series,
          volSeries,
          data,
          volumeByTimeRef.current,
          showVolume,
          seedScrollModeRef.current,
          resolveSeedPinnedViewportRef.current(),
          intervalSecRef.current,
          seedMaxVisibleLogicalBarsRef.current,
        );
        if (pinnedApplied) {
          followLiveRef.current = false;
          setShowNavToolbarSafe(true);
        }
        setCurrentPriceSafe(data[data.length - 1]!.close);
        scheduleRepushChartOverlays();
        scheduleReadyAfterPaintRef.current();
        if (mountedRef.current) {
          notifyOverlayLayoutRef.current?.();
        }
      };

      outerFrameId = requestAnimationFrame(() => {
        innerFrameId = requestAnimationFrame(applyResetScroll);
      });

      return () => {
        cancelAnimationFrame(outerFrameId);
        cancelAnimationFrame(innerFrameId);
      };
    }, [resetScrollKey, showVolume, scheduleRepushChartOverlays]);

    useEffect(() => {
      readyNotifiedRef.current = false;
    }, [resetScrollKey]);

    useEffect(() => {
      if (!chartContainerRef.current) return;

      // Clean up existing chart if it exists
      if (chartRef.current) {
        try {
          chartRef.current.remove();
        } catch (error) {
          console.warn("[KlineChart] Error removing existing chart:", error);
        }
        chartRef.current = null;
        candlestickSeriesRef.current = null;
        volumeSeriesRef.current = null;
        executionMarkersRef.current = null;
        pendingOrderLinesRef.current = null;
      }

      let chart: IChartApi | null = null;
      let animationFrameId: number | null = null;
      let initAttempts = 0;
      const maxInitAttempts = 120;
      let onVisibleRangeChange: (() => void) | null = null;
      let pointerStartX: number | null = null;
      let pointerStartY: number | null = null;

      const onPointerDown = (event: PointerEvent) => {
        pointerStartX = event.clientX;
        pointerStartY = event.clientY;
      };

      const onPointerMove = (event: PointerEvent) => {
        if (pointerStartX === null || pointerStartY === null || event.buttons === 0) return;
        const dx = Math.abs(event.clientX - pointerStartX);
        const dy = Math.abs(event.clientY - pointerStartY);
        if (dx > DRAG_THRESHOLD_PX || dy > DRAG_THRESHOLD_PX) {
          pinnedViewportRef.current = null;
          markOffLiveRef.current();
          isPanningRefForPointer.current = true;
        }
      };

      const onPointerUp = () => {
        isPanningRefForPointer.current = false;
        if (pendingPriceRef.current != null) {
          setCurrentPriceRef.current(pendingPriceRef.current);
          pendingPriceRef.current = null;
        }
        if (!followLiveRef.current) {
          setShowNavToolbarRef.current(true);
        }
        const chartOnRelease = chartRef.current;
        const seriesOnRelease = candlestickSeriesRef.current;
        if (
          chartOnRelease &&
          seriesOnRelease &&
          (activeTradeIdRef.current || activeOrderLineIdRef.current)
        ) {
          updateActiveMarkerAnchorRef.current(chartOnRelease, seriesOnRelease);
        }
        executionMarkersRef.current?.flushPanInvalidation();
        pendingOrderLinesRef.current?.flushPanInvalidation();
        pointerStartX = null;
        pointerStartY = null;
      };

      const applyChartData = (
        candlestickSeries: ISeriesApi<"Candlestick">,
        volumeSeries: ISeriesApi<"Histogram"> | null,
        data: CandlestickData[],
      ) => {
        if (!chart || data.length === 0) return;
        seedChartSeriesData(
          chart,
          candlestickSeries,
          volumeSeries,
          data,
          volumeByTimeRef.current,
          showVolume,
          seedScrollModeRef.current,
          resolveSeedPinnedViewportRef.current(),
          intervalSecRef.current,
          seedMaxVisibleLogicalBarsRef.current,
        );
        if (resolveSeedPinnedViewportRef.current()) {
          followLiveRef.current = false;
          setShowNavToolbarRef.current(true);
        }
        setCurrentPriceRef.current(data[data.length - 1]!.close);
        scheduleReadyAfterPaintRef.current();
      };

      const initializeChart = () => {
        if (!chartContainerRef.current) return;

        const container = chartContainerRef.current;
        const containerWidth = container.clientWidth || container.offsetWidth;
        const containerHeight = container.clientHeight || container.offsetHeight;

        if (
          (!containerWidth || containerWidth < 50 || !containerHeight || containerHeight < 80) &&
          initAttempts < maxInitAttempts
        ) {
          initAttempts += 1;
          animationFrameId = requestAnimationFrame(initializeChart);
          return;
        }

        let candlestickSeriesInstance: ISeriesApi<"Candlestick">;
        let volumeSeries: ISeriesApi<"Histogram"> | null = null;

        try {
          chart = createChart(container, {
            autoSize: true,
            layout: {
              background: { color: TERMINAL_COLORS.bgDeep },
              textColor: TERMINAL_COLORS.textSecondary,
            },
            grid: {
              vertLines: { color: TERMINAL_COLORS.gridMajor },
              horzLines: { color: TERMINAL_COLORS.gridMajor },
            },
            crosshair: {
              mode: 1,
            },
            rightPriceScale: {
              borderColor: TERMINAL_COLORS.panelStrong,
            },
            timeScale: {
              visible: false,
              borderVisible: false,
              timeVisible: true,
              secondsVisible: false,
              rightBarStaysOnScroll: true,
              shiftVisibleRangeOnNewBar: true,
              minBarSpacing: MIN_BAR_SPACING,
              barSpacing: DEFAULT_BAR_SPACING,
              lockVisibleTimeRangeOnResize: true,
              rightOffset: LIVE_RIGHT_OFFSET_BARS,
              enableConflation: false,
            },
          });

          candlestickSeriesInstance = chart.addSeries(CandlestickSeries, {
            upColor: TERMINAL_COLORS.long,
            downColor: TERMINAL_COLORS.short,
            borderVisible: false,
            wickUpColor: TERMINAL_COLORS.long,
            wickDownColor: TERMINAL_COLORS.short,
          });

          if (showVolume) {
            volumeSeries = chart.addSeries(HistogramSeries, {
              color: TERMINAL_COLORS.longSoft,
              priceFormat: { type: "volume" },
              priceScaleId: "volume",
            });
            chart.priceScale("volume").applyOptions({
              scaleMargins: { top: 0.8, bottom: 0.05 },
            });
            candlestickSeriesInstance.priceScale().applyOptions({
              scaleMargins: { top: 0.1, bottom: 0.2 },
            });
          } else {
            candlestickSeriesInstance.priceScale().applyOptions({
              scaleMargins: { top: 0.1, bottom: 0.08 },
            });
          }
        } catch (error) {
          console.error("[KlineChart] Error creating chart or series:", error);
          return;
        }

        applyChartData(candlestickSeriesInstance, volumeSeries, initialDataRef.current);

        const executionMarkers = new ExecutionMarkersPrimitive(isPanningRefForPointer);
        candlestickSeriesInstance.attachPrimitive(executionMarkers);
        executionMarkers.setMarkers(markersListRef.current);
        executionMarkersRef.current = executionMarkers;

        const pendingOrderLines = new PendingOrderLinesPrimitive(isPanningRefForPointer);
        candlestickSeriesInstance.attachPrimitive(pendingOrderLines);
        pendingOrderLines.setLines(orderLinesListRef.current);
        pendingOrderLinesRef.current = pendingOrderLines;

        chart.subscribeCrosshairMove((param) => {
          const markerHandler = onMarkerHoverRef.current;
          const lineHandler = onOrderLineHoverRef.current;
          if (!chart) return;

          const tradeId = getMarkerTradeId(param);
          if (tradeId && markerHandler) {
            const point = resolveMarkerInteractionPoint(
              chart,
              candlestickSeriesInstance,
              tradeId,
              markerAnchorListRef.current,
              barSpacingRef.current,
            );
            if (point) {
              markerHandler(tradeId, point);
            }
            if (lineHandler) lineHandler(null, null);
            return;
          }

          const lineId = getOrderLineId(param, orderLineIdsRef.current);
          if (lineId && lineHandler) {
            const point =
              resolveOrderLineAnchorPoint(
                chart,
                candlestickSeriesInstance,
                lineId,
                orderLinesListRef.current,
                orderLinePriceOverridesRef.current,
              ) ?? (param.point ? { x: param.point.x, y: param.point.y } : null);
            lineHandler(lineId, point);
            if (markerHandler) markerHandler(null, null);
            return;
          }

          if (
            isPanningRefForPointer.current &&
            (activeTradeIdRef.current || activeOrderLineIdRef.current)
          ) {
            return;
          }
          markerHandler?.(null, null);
          lineHandler?.(null, null);
        });

        chart.subscribeClick((param) => {
          const markerHandler = onMarkerClickRef.current;
          const lineHandler = onOrderLineClickRef.current;
          if (!chart) return;

          const tradeId = getMarkerTradeId(param);
          if (tradeId && markerHandler) {
            const point = resolveMarkerInteractionPoint(
              chart,
              candlestickSeriesInstance,
              tradeId,
              markerAnchorListRef.current,
              barSpacingRef.current,
            );
            if (point) {
              markerHandler(tradeId, point);
            }
            return;
          }

          const lineId = getOrderLineId(param, orderLineIdsRef.current);
          if (lineId && lineHandler) {
            const point =
              resolveOrderLineAnchorPoint(
                chart,
                candlestickSeriesInstance,
                lineId,
                orderLinesListRef.current,
                orderLinePriceOverridesRef.current,
              ) ?? (param.point ? { x: param.point.x, y: param.point.y } : null);
            lineHandler(lineId, point);
            return;
          }

          markerHandler?.(null, null);
          lineHandler?.(null, null);
        });

        let pinWasVisible = false;

        const scheduleRepushOnRangeChange = createRafCoalescer(() => {
          if (isPanningRefForPointer.current) return;
          const chartInstance = chartRef.current;
          const pin = pinnedViewportRef.current;
          if (!chartInstance || !pin) {
            pinWasVisible = false;
            return;
          }
          const pinVisible = viewportContainsPin(chartInstance, pin);
          if (pinVisible && !pinWasVisible) {
            repushChartOverlaysRef.current();
          }
          pinWasVisible = pinVisible;
        });

        const schedulePinnedViewportEnforce = createRafCoalescer(() => {
          if (isPanningRefForPointer.current) return;
          const chartInstance = chartRef.current;
          const pin = pinnedViewportRef.current;
          if (!chartInstance || !pin || viewportContainsPin(chartInstance, pin)) return;
          const barTimes = barTimesFromCandles(initialDataRef.current);
          const applied = applyPinnedViewport(
            chartInstance,
            pin,
            intervalSecRef.current,
            barTimes,
          );
          if (!applied) {
            pinnedViewportRef.current = null;
            return;
          }
          followLiveRef.current = false;
          setShowNavToolbarRef.current(true);
          repushChartOverlaysRef.current();
        });

        onVisibleRangeChange = () => {
          if (!chart) return;
          barSpacingRef.current = chart.timeScale().options().barSpacing ?? barSpacingRef.current;
          onVisibleLogicalRangeChangeRef.current?.(chart.timeScale().getVisibleLogicalRange());
          if (chart.timeScale().scrollPosition() > LIVE_SCROLL_THRESHOLD) {
            markOffLiveRef.current();
          }
          schedulePinnedViewportEnforce();
          scheduleRepushOnRangeChange();
          if (activeTradeIdRef.current || activeOrderLineIdRef.current) {
            updateActiveMarkerAnchorRef.current(chart, candlestickSeriesInstance);
          }
        };
        chart.timeScale().subscribeVisibleLogicalRangeChange(onVisibleRangeChange);

        container.addEventListener("pointerdown", onPointerDown);
        container.addEventListener("pointermove", onPointerMove);
        container.addEventListener("pointerup", onPointerUp);
        container.addEventListener("pointercancel", onPointerUp);

        chartRef.current = chart;
        candlestickSeriesRef.current = candlestickSeriesInstance;
        volumeSeriesRef.current = volumeSeries;
        if (mountedRef.current) {
          setChartInstance(chart);
        }

        if (mountedRef.current) {
          notifyOverlayLayoutRef.current?.();
        }
        scheduleRepushChartOverlays();
        onVisibleLogicalRangeChangeRef.current?.(chart.timeScale().getVisibleLogicalRange());
      };

      // Start initialization
      initializeChart();

      // Cleanup function
      return () => {
        cancelScheduledRafs();
        if (animationFrameId !== null) {
          cancelAnimationFrame(animationFrameId);
        }
        if (chart && onVisibleRangeChange) {
          chart.timeScale().unsubscribeVisibleLogicalRangeChange(onVisibleRangeChange);
        }
        if (chartContainerRef.current) {
          const container = chartContainerRef.current;
          container.removeEventListener("pointerdown", onPointerDown);
          container.removeEventListener("pointermove", onPointerMove);
          container.removeEventListener("pointerup", onPointerUp);
          container.removeEventListener("pointercancel", onPointerUp);
        }
        if (chart) {
          try {
            chart.remove();
          } catch (error) {
            console.error("[KlineChart] Error removing chart:", error);
          }
        }
        chartRef.current = null;
        candlestickSeriesRef.current = null;
        volumeSeriesRef.current = null;
        executionMarkersRef.current = null;
        pendingOrderLinesRef.current = null;
      };
    }, [height, showVolume, cancelScheduledRafs]);

    useEffect(() => {
      if (!candlestickSeriesRef.current || initialData.length === 0) return;
      scheduleRepushChartOverlays();
      notifyOverlayLayoutRef.current();
    }, [initialData.length, scheduleRepushChartOverlays]);

    useEffect(() => {
      if (!executionMarkersRef.current) return;
      try {
        executionMarkersRef.current.setMarkers(markers);
        scheduleRepushChartOverlays();
      } catch (error) {
        console.error("[KlineChart] Error setting markers:", error);
      }
    }, [markers, initialData.length, chartInstance, scheduleRepushChartOverlays]);

    useEffect(() => {
      if (!pendingOrderLinesRef.current) return;
      try {
        pendingOrderLinesRef.current.setLines(orderLines);
        scheduleRepushChartOverlays();
      } catch (error) {
        console.error("[KlineChart] Error setting order lines:", error);
      }
    }, [orderLines, initialData.length, chartInstance, scheduleRepushChartOverlays]);

    useEffect(() => {
      if (!pendingOrderLinesRef.current) return;
      try {
        pendingOrderLinesRef.current.setPriceOverrides(orderLinePriceOverrides ?? new Map());
        scheduleRepushChartOverlays();
      } catch (error) {
        console.error("[KlineChart] Error setting order line price overrides:", error);
      }
    }, [orderLinePriceOverrides, initialData.length, chartInstance, scheduleRepushChartOverlays]);

    useEffect(() => {
      const chart = chartRef.current;
      const series = candlestickSeriesRef.current;
      if (!chart || !series) return;
      if (activeTradeId || activeOrderLineId) {
        updateActiveMarkerAnchor(chart, series);
      }
    }, [activeTradeId, activeOrderLineId, markers, orderLines, orderLinePriceOverrides, updateActiveMarkerAnchor]);

    useEffect(() => {
      const wrapper = canvasWrapperRef.current;
      const container = chartContainerRef.current;
      const host = overlayHostRefProp?.current;
      const layoutRoot = layoutRootRefProp?.current;
      if (!wrapper) return;

      const scheduleLayout = createRafCoalescer(() => {
        if (!mountedRef.current) return;
        notifyOverlayLayoutRef.current?.();
        if (
          activeTradeIdRef.current || activeOrderLineIdRef.current
        ) {
          const chart = chartRef.current;
          const series = candlestickSeriesRef.current;
          if (chart && series) {
            updateActiveMarkerAnchorRef.current(chart, series);
          }
        }
      });

      scheduleLayout();
      const observer = new ResizeObserver(scheduleLayout);
      observer.observe(wrapper);
      if (container) {
        observer.observe(container);
      }
      if (host) {
        observer.observe(host);
      }
      if (layoutRoot) {
        observer.observe(layoutRoot);
      }
      return () => observer.disconnect();
    }, [overlayHostRefProp, layoutRootRefProp]);

    const overlayPortal =
      overlay && overlayPortalHost ? createPortal(overlay, overlayPortalHost) : null;

    const barTimes = useMemo(
      () => initialData.map((bar) => bar.time as UTCTimestamp),
      [initialData.length],
    );

    return (
      <div className="kline-chart-container chart-panel">
        <div className="kline-chart-header">
          <span className="terminal-market-title">{symbol}</span>
          {currentPrice !== null ? (
            <span className="chart-current-price">${currentPrice.toFixed(2)}</span>
          ) : null}
        </div>
        <div ref={canvasWrapperRef} className="kline-chart-canvas">
          <div ref={chartContainerRef} className="kline-chart-canvas-inner" />
          <KlineChartTimeAxisOverlay
            chart={chartInstance}
            canvasWrapperRef={canvasWrapperRef}
            barTimes={barTimes}
            interval={interval}
            intervalSec={intervalSec}
            isPanningRef={isPanningRef}
          />
          {showNavToolbar ? (
            <KlineChartNavToolbar
              onCoarserInterval={onCoarserInterval ?? (() => {})}
              onFinerInterval={onFinerInterval ?? (() => {})}
              coarserDisabled={!canCoarserInterval}
              finerDisabled={!canFinerInterval}
              onScrollOlder={() => scrollByBars(-1)}
              onScrollNewer={() => scrollByBars(1)}
              showPendingViewButton={showPendingViewButton}
              pendingViewDisabled={orderLines.length === 0}
              onViewPendings={fitToPendingOrderLines}
              onReset={scrollToLatest}
            />
          ) : null}
        </div>
        {overlayPortal}
      </div>
    );
  }
);

KlineChart.displayName = "KlineChart";

export default KlineChart;
