import React from "react";

import { TabLayoutHeaderToolBar } from "../smartlayout";
import {
  AGENT_COMPARE_FOCUS_OPTIONS,
  type AgentCompareFocus,
} from "./agentCompareFocus";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./agent.css";

export interface AgentCompareFocusBarProps {
  height?: string;
  focus: AgentCompareFocus;
  onFocusChange: (focus: AgentCompareFocus) => void;
  onShareClick: () => void;
  shareDisabled?: boolean;
  listAddDisabled?: boolean;
  isCurrentSaved: boolean;
  onListClick: () => void;
  highlightBest: boolean;
  onHighlightBestChange: (enabled: boolean) => void;
}

const FOCUS_TABS = AGENT_COMPARE_FOCUS_OPTIONS.map((option) => ({
  id: option.value,
  label: option.label,
}));

function ShareIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8" />
      <polyline points="16 6 12 2 8 6" />
      <line x1="12" y1="2" x2="12" y2="15" />
    </svg>
  );
}

function ListIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <line x1="8" y1="6" x2="21" y2="6" />
      <line x1="8" y1="12" x2="21" y2="12" />
      <line x1="8" y1="18" x2="21" y2="18" />
      <line x1="3" y1="6" x2="3.01" y2="6" />
      <line x1="3" y1="12" x2="3.01" y2="12" />
      <line x1="3" y1="18" x2="3.01" y2="18" />
    </svg>
  );
}

function AgentCompareFocusBar({
  height = "100%",
  focus,
  onFocusChange,
  onShareClick,
  shareDisabled = false,
  listAddDisabled = false,
  isCurrentSaved,
  onListClick,
  highlightBest,
  onHighlightBestChange,
}: AgentCompareFocusBarProps): JSX.Element {
  const listButtonDisabled = listAddDisabled && !isCurrentSaved;

  return (
    <div
      className="agent-slot agent-compare-focus-bar"
      style={{ height }}
      aria-label="Compare focus"
    >
      <TabLayoutHeaderToolBar
        tabs={FOCUS_TABS}
        activeTabId={focus}
        onTabChange={(id) => onFocusChange(id as AgentCompareFocus)}
        scrollActiveTabIntoView
      >
        <div className="agent-compare-focus-actions">
          <button
            type="button"
            className="agent-compare-share-btn"
            onClick={onShareClick}
            disabled={shareDisabled}
            aria-label="Share compare"
            aria-disabled={shareDisabled}
          >
            <ShareIcon />
            <span>Share</span>
          </button>
          <button
            type="button"
            className="agent-compare-list-btn"
            onClick={onListClick}
            disabled={listButtonDisabled}
            aria-disabled={listButtonDisabled}
            aria-label={
              isCurrentSaved ? "Edit saved compare lists" : "Add compare to my list"
            }
          >
            <ListIcon />
            <span className="agent-compare-list-btn-label agent-compare-list-btn-label--full">
              {isCurrentSaved ? "Edit" : "Add to my list"}
            </span>
            <span className="agent-compare-list-btn-label agent-compare-list-btn-label--short">
              {isCurrentSaved ? "Edit" : "Add"}
            </span>
          </button>
          <button
            type="button"
            className={`agent-compare-highlight-btn${
              highlightBest ? " agent-compare-highlight-btn--active" : ""
            }`}
            aria-pressed={highlightBest}
            aria-label="Highlight the best"
            onClick={() => onHighlightBestChange(!highlightBest)}
          >
            <span className="agent-compare-highlight-btn-label agent-compare-highlight-btn-label--full">
              Highlight the best
            </span>
            <span className="agent-compare-highlight-btn-label agent-compare-highlight-btn-label--short">
              Best
            </span>
          </button>
        </div>
      </TabLayoutHeaderToolBar>
    </div>
  );
}

export default AgentCompareFocusBar;
