import type { TabSectionTabId } from "../tables/TabSection";
import {
  buildHighAgencyTabOrder,
  DEFAULT_HIGH_AGENCY_OPTIONAL_TABS,
} from "./highAgencyTabs";

/** Default High-Agency Agent-segment tab order (pinned + default optional tabs). */
export const HIGH_AGENCY_TAB_ORDER: TabSectionTabId[] = buildHighAgencyTabOrder(
  DEFAULT_HIGH_AGENCY_OPTIONAL_TABS,
);

export const HUMAN_IN_LOOP_TAB_ORDER: TabSectionTabId[] = [
  "memoryAudit",
  "agentTasks",
  "positions",
  "openOrders",
  "tradeHistory",
  "history",
  "fundingHistory",
  "buckets",
];

/** Classic pro tables shown when "Raw Pro Data" is toggled on in agent modes */
export const RAW_PRO_DATA_TAB_ORDER: TabSectionTabId[] = [
  "openOrders",
  "history",
  "fundingHistory",
  "tradeHistory",
  "positions",
  "buckets",
];

export function defaultTabForTradingMode(
  mode: "proTerminal" | "highAgency" | "humanInLoop",
): TabSectionTabId {
  if (mode === "highAgency") return "agentTasks";
  if (mode === "humanInLoop") return "memoryAudit";
  return "tradeHistory";
}
