import React, { useMemo, useState } from "react";

import { TickerXNewsCards } from "../tradeops/TickerXNewsCards";
import { DEFAULT_X_NEWS_CAPACITY } from "../tradeops/useXNewsStream";
import type { ResolvedIndexConstituent } from "../../utils/indexConstituents";
import { useConstituentXNewsStream } from "./useConstituentXNewsStream";
import "./index.css";

export interface IndexConstituentXNewsPanelProps {
  height?: string;
  constituents: ResolvedIndexConstituent[];
  /** Stable header label; not tied to active index mode tab. */
  pulseLabel?: string;
  enabled?: boolean;
}

function IndexConstituentXNewsPanel({
  height = "100%",
  constituents,
  pulseLabel: pulseLabelProp,
  enabled = true,
}: IndexConstituentXNewsPanelProps): JSX.Element {
  const [xNewsCapacity, setXNewsCapacity] = useState(DEFAULT_X_NEWS_CAPACITY);

  const tickers = useMemo(
    () => constituents.map((item) => item.ticker).filter(Boolean),
    [constituents],
  );

  const tickerKey = useMemo(() => [...tickers].sort().join("|"), [tickers]);

  const pulseLabel =
    pulseLabelProp ?? `Basket pulse · ${tickers.length} names`;

  const { items, enterState } = useConstituentXNewsStream(
    tickers,
    enabled && tickers.length > 0,
    xNewsCapacity,
  );

  if (tickers.length === 0) {
    return (
      <div className="index-slot index-slot--x-news" style={{ height }}>
        <div className="index-slot-body index-slot-body--x-news">
          <div className="index-x-news-empty">
            <span className="eyebrow-text">X pulse</span>
            <p>No constituents for pulse feed</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="index-slot index-slot--x-news" style={{ height }}>
      <div className="index-slot-body index-slot-body--x-news">
        <TickerXNewsCards
          baseAsset={tickers[0] ?? ""}
          items={items}
          enterState={enterState}
          onVisibleCapacityChange={setXNewsCapacity}
          pulseLabel={pulseLabel}
          streamKey={tickerKey}
        />
      </div>
    </div>
  );
}

export default IndexConstituentXNewsPanel;
