import { useCallback, useEffect, useRef } from "react";
import { isMockSeedTaskId, MOCK_AGENT_IDS } from "../../../offline/mock_data";
import { useAgentTaskStore } from "../../store/agentTaskStore";
import { deriveGuardrailMeta } from "./guardrailMeta";
import { generateIntent } from "../tradeops/intentExamples";

export const MIN_INTERVAL_MS = 5_000;
export const MAX_INTERVAL_MS = 15_000;
export const MAX_STREAM_PENDING = 8;
export const SHIPPER_AGENT_ID = MOCK_AGENT_IDS.alphaArb;

export function randomIntervalMs(): number {
  return MIN_INTERVAL_MS + Math.random() * (MAX_INTERVAL_MS - MIN_INTERVAL_MS);
}

export interface UseAgentPendingIntentStreamOptions {
  baseAsset: string;
  marketId: string;
  enabled: boolean;
}

function pruneStreamPendingIfNeeded(): void {
  const { tasks, updateTask } = useAgentTaskStore.getState();
  const streamPending = tasks.filter(
    (task) =>
      !isMockSeedTaskId(task.id) &&
      task.agentId === SHIPPER_AGENT_ID &&
      task.status === "pending",
  );
  if (streamPending.length < MAX_STREAM_PENDING) return;

  const oldest = streamPending[streamPending.length - 1];
  if (!oldest) return;

  const at = new Date().toISOString();
  updateTask(oldest.id, {
    status: "completed",
    isNew: false,
    statusHistory: [
      ...oldest.statusHistory,
      {
        status: "completed",
        at,
        note: "Auto-completed to make room for newer intents.",
      },
    ],
  });
}

function shipPendingIntent(baseAsset: string, marketId: string): void {
  if (!baseAsset) return;

  pruneStreamPendingIfNeeded();

  const intent = generateIntent(baseAsset);
  const at = new Date().toISOString();
  const taskId =
    typeof crypto !== "undefined" && crypto.randomUUID
      ? crypto.randomUUID().replace(/-/g, "").slice(0, 16)
      : `${Date.now().toString(16)}${Math.random().toString(16).slice(2, 10)}`.slice(
          0,
          16,
        );
  const guardrail = deriveGuardrailMeta({ id: taskId, agentId: SHIPPER_AGENT_ID });

  useAgentTaskStore.getState().addTask(
    {
      id: taskId,
      agentId: SHIPPER_AGENT_ID,
      description: intent.intentText,
      status: "pending",
      marketId: marketId || null,
      bucketId: null,
      trigger: intent.summary,
      eta: null,
      guardrail,
      statusHistory: [
        {
          status: "pending",
          at,
          note: "Intent surfaced for human review.",
        },
      ],
    },
    { navigate: false, appendMemory: false },
  );
}

export function useAgentPendingIntentStream({
  baseAsset,
  marketId,
  enabled,
}: UseAgentPendingIntentStreamOptions): void {
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const baseAssetRef = useRef(baseAsset);
  const marketIdRef = useRef(marketId);

  const clearTimer = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);

  const scheduleNext = useCallback(
    (asset: string, market: string) => {
      if (!asset || !enabled) return;
      timeoutRef.current = setTimeout(() => {
        if (baseAssetRef.current !== asset || marketIdRef.current !== market) {
          return;
        }
        shipPendingIntent(asset, market);
        scheduleNext(asset, market);
      }, randomIntervalMs());
    },
    [enabled],
  );

  useEffect(() => {
    baseAssetRef.current = baseAsset;
    marketIdRef.current = marketId;
    clearTimer();

    if (!baseAsset || !enabled) {
      return clearTimer;
    }

    scheduleNext(baseAsset, marketId);
    return clearTimer;
  }, [baseAsset, marketId, enabled, clearTimer, scheduleNext]);
}
