import React, { useCallback, useEffect, useState } from "react";
import { createPortal } from "react-dom";

import type { McpServer, McpTransport } from "./agentSettingsTypes";
import { isValidMcpServerDraft } from "./agentSettingsValidation";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./agent.css";
import "./agentSettings.css";

export interface AddMcpServerModalProps {
  open: boolean;
  onClose: () => void;
  onAdd: (input: Omit<McpServer, "id" | "createdAt">) => boolean;
}

interface HeaderDraft {
  name: string;
  value: string;
}

function CloseIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M18 6L6 18M6 6l12 12" />
    </svg>
  );
}

function AddMcpServerModal({
  open,
  onClose,
  onAdd,
}: AddMcpServerModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(open);

  useOverlayEscapeKey(open, onClose);

  const [name, setName] = useState("Linear");
  const [url, setUrl] = useState("https://mcp.example.com/mcp");
  const [transport, setTransport] = useState<McpTransport>("streamableHttp");
  const [headers, setHeaders] = useState<HeaderDraft[]>([
    { name: "", value: "Bearer {{LINEAR_API_KEY}}" },
  ]);

  useEffect(() => {
    if (!open) return;
    setName("Linear");
    setUrl("https://mcp.example.com/mcp");
    setTransport("streamableHttp");
    setHeaders([{ name: "", value: "Bearer {{LINEAR_API_KEY}}" }]);
  }, [open]);

  const canSubmit = isValidMcpServerDraft({ name, url });

  const handleSubmit = useCallback(() => {
    if (!canSubmit) return;
    onAdd({
      name: name.trim(),
      url: url.trim(),
      transport,
      headers: headers
        .filter((header) => header.name.trim())
        .map((header) => ({
          name: header.name.trim(),
          value: header.value,
        })),
    });
  }, [canSubmit, headers, name, onAdd, transport, url]);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="agent-settings-nested-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content agent-settings-mcp-modal-content staggered-overlay-panel--scale"
        aria-label="Add MCP Server"
      >
        <div className="modal-header agent-settings-modal-header">
          <div>
            <h3 className="terminal-panel-title">Add MCP Server</h3>
            <p className="agent-settings-section-desc">
              Connect an MCP-compliant endpoint. Tool discovery runs automatically after
              save (demo — local only).
            </p>
          </div>
          <button
            type="button"
            className="agent-settings-modal-close"
            onClick={onClose}
            aria-label="Close"
          >
            <CloseIcon />
          </button>
        </div>

        <div className="modal-body">
          <div className="transfer-field-group">
            <label className="terminal-label transfer-field-label">Name</label>
            <input
              type="text"
              className="form-input transfer-select transfer-input"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>

          <div className="transfer-field-group">
            <label className="terminal-label transfer-field-label">URL</label>
            <input
              type="url"
              className="form-input transfer-select transfer-input"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
            />
          </div>

          <fieldset className="transfer-field-group">
            <legend className="terminal-label transfer-field-label">Transport</legend>
            <div className="agent-settings-transport-row">
              <label
                className={`agent-settings-transport-option${
                  transport === "streamableHttp" ? " is-active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="mcp-transport"
                  checked={transport === "streamableHttp"}
                  onChange={() => setTransport("streamableHttp")}
                />
                Streamable HTTP
              </label>
              <label
                className={`agent-settings-transport-option${
                  transport === "sse" ? " is-active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="mcp-transport"
                  checked={transport === "sse"}
                  onChange={() => setTransport("sse")}
                />
                SSE (legacy)
              </label>
            </div>
          </fieldset>

          <div className="transfer-field-group">
            <span className="terminal-label transfer-field-label">Headers</span>
            <p className="transfer-field-hint">
              Use <code>{`{{ENV_VAR}}`}</code> to reference env vars
            </p>
            {headers.map((header, index) => (
              <div key={index} className="agent-settings-header-row">
                <input
                  type="text"
                  className="form-input transfer-select transfer-input"
                  placeholder="Header-Name"
                  value={header.name}
                  onChange={(e) => {
                    const next = [...headers];
                    next[index] = { ...next[index]!, name: e.target.value };
                    setHeaders(next);
                  }}
                />
                <input
                  type="text"
                  className="form-input transfer-select transfer-input"
                  placeholder="Bearer {{LINEAR_API_KEY}}"
                  value={header.value}
                  onChange={(e) => {
                    const next = [...headers];
                    next[index] = { ...next[index]!, value: e.target.value };
                    setHeaders(next);
                  }}
                />
                <button
                  type="button"
                  className="agent-settings-header-remove"
                  aria-label="Remove header"
                  onClick={() => setHeaders(headers.filter((_, i) => i !== index))}
                  disabled={headers.length <= 1}
                >
                  ×
                </button>
              </div>
            ))}
            <button
              type="button"
              className="agent-settings-add-header-link"
              onClick={() => setHeaders([...headers, { name: "", value: "" }])}
            >
              + Add header
            </button>
          </div>
        </div>

        <div className="modal-footer">
          <button type="button" className="agent-secondary-btn" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            className="agent-secondary-btn agent-secondary-btn--primary"
            disabled={!canSubmit}
            onClick={handleSubmit}
          >
            Add server
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default AddMcpServerModal;
