import React from "react";
import { createPortal } from "react-dom";

import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
} from "../ui/overlay";
import {
  useCopyAgentModalOverlay,
  type UseBucketModalOverlayResult,
} from "../tables/useBucketModalOverlay";
import { useCopyAgentModalLayout, type CopyAgentModalLayout } from "./useCopyAgentModalLayout";
import "../smartlayout/layout.css";
import "./agent.css";

export interface CopyAgentModalShellProps {
  open: boolean;
  onClose: () => void;
  ariaLabel: string;
  variant?: "setup" | "status";
  onAfterUnmount?: () => void;
  children: React.ReactNode;
}

function layoutPanelClass(
  layout: CopyAgentModalLayout,
  variant: "setup" | "status",
): string {
  const classes = [
    "modal-content",
    "agent-copy-modal-content",
    "terminal-overlay-panel-shell",
    variant === "status" ? "copied-agent-status-modal" : "",
  ];
  if (layout === "sheet") {
    classes.push("agent-copy-modal-content--sheet", "bucket-modal-panel--sheet");
  } else if (layout === "lg") {
    classes.push(
      "agent-copy-modal-content--lg",
      "agent-copy-modal-content--desktop",
      "staggered-overlay-panel--scale",
    );
  } else {
    classes.push("agent-copy-modal-content--md", "staggered-overlay-panel--scale");
  }
  return classes.filter(Boolean).join(" ");
}

export type CopyAgentModalShellContext = {
  layout: CopyAgentModalLayout;
  isSheet: boolean;
  overlay: UseBucketModalOverlayResult;
};

export const CopyAgentModalShellContext =
  React.createContext<CopyAgentModalShellContext | null>(null);

export function useCopyAgentModalShell(): CopyAgentModalShellContext {
  const ctx = React.useContext(CopyAgentModalShellContext);
  if (!ctx) {
    throw new Error("useCopyAgentModalShell must be used within CopyAgentModalShell");
  }
  return ctx;
}

function CopyAgentModalShell({
  open,
  onClose,
  ariaLabel,
  variant = "setup",
  onAfterUnmount,
  children,
}: CopyAgentModalShellProps): JSX.Element | null {
  const layout = useCopyAgentModalLayout();
  const isSheet = layout === "sheet";
  const overlay = useCopyAgentModalOverlay(open, { onAfterUnmount });

  useOverlayEscapeKey(open, onClose);

  if (!overlay.mounted) return null;

  const panelClassName = [
    layoutPanelClass(layout, variant),
    overlay.isClosing ? "bucket-modal-panel--closing" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const modalContent = (
    <CopyAgentModalShellContext.Provider
      value={{ layout, isSheet, overlay }}
    >
      <StaggeredOverlayRoot
        passThrough={!open}
        className={
          isSheet
            ? "bucket-modal-overlay bucket-modal-overlay--sheet agent-copy-sheet-overlay"
            : undefined
        }
      >
        <StaggeredOverlayBackdrop
          visible={overlay.backdropVisible && open}
          onClose={onClose}
          style={overlay.backdropStyle}
          className="staggered-overlay-backdrop--deep"
        />
        <StaggeredOverlayPanel
          open={overlay.panelOpen}
          className={panelClassName}
          aria-label={ariaLabel}
          role="dialog"
          aria-modal={true}
        >
          {isSheet ? (
            <div className="agent-copy-sheet__handle" aria-hidden>
              <span />
            </div>
          ) : null}
          {children}
        </StaggeredOverlayPanel>
      </StaggeredOverlayRoot>
    </CopyAgentModalShellContext.Provider>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(CopyAgentModalShell);
