import React from "react";

import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory";
import {
  FLEET_ACTIVITY_GRID_TEMPLATE_COLUMNS,
  ORDER_SIDE_COLOR_BUY_LONG,
  ORDER_SIDE_COLOR_SELL_SHORT,
} from "../../constants";
import { isBinanceKlineSupported } from "../tradingview/symbols";
import { TableHeaderCellStatic } from "../smartlayout";
import "../smartlayout/layout.css";
import "./agent.css";

function shortWallet(address: string): string {
  if (!address || address.length < 12) return address;
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

function formatTime(iso: string): string {
  const date = new Date(iso);
  return date.toISOString().replace("T", " ").slice(0, 16);
}

export interface FleetActivityTabProps {
  catalogAgentId: string;
  trades: FleetTradeEvent[];
  onViewAssetOnChart?: (event: FleetTradeEvent) => void;
  activeAssetCoin?: string | null;
}

export default function FleetActivityTab({
  catalogAgentId,
  trades,
  onViewAssetOnChart,
  activeAssetCoin = null,
}: FleetActivityTabProps): JSX.Element {
  const sorted = [...trades].sort((a, b) =>
    b.timestamp.localeCompare(a.timestamp),
  );

  if (sorted.length === 0) {
    return (
      <div className="agent-fleet-activity agent-fleet-activity--empty">
        <p>No simulated on-chain activity for {catalogAgentId}.</p>
      </div>
    );
  }

  return (
    <div
      className="layout-container agent-fleet-activity-table"
      style={{ height: "100%", borderRadius: 0, background: "transparent" }}
    >
      <div className="table-container shrinkable">
        <div
          className="table-header"
          style={{ gridTemplateColumns: FLEET_ACTIVITY_GRID_TEMPLATE_COLUMNS }}
        >
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Action</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Asset</TableHeaderCellStatic>
          <TableHeaderCellStatic right>USD</TableHeaderCellStatic>
          <TableHeaderCellStatic right>PnL</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Tx</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Signer</TableHeaderCellStatic>
        </div>
        {sorted.map((event, index) => {
          const pnlColor =
            event.closedPnl == null
              ? undefined
              : event.closedPnl > 0
                ? ORDER_SIDE_COLOR_BUY_LONG
                : event.closedPnl < 0
                  ? ORDER_SIDE_COLOR_SELL_SHORT
                  : undefined;

          const klineSupported = isBinanceKlineSupported(event.coin);
          const isActiveAsset =
            activeAssetCoin != null &&
            event.coin.toUpperCase() === activeAssetCoin.toUpperCase();

          return (
            <div
              key={event.id}
              className={`table-row ${index % 2 === 0 ? "even" : ""}${
                isActiveAsset ? " agent-fleet-activity-row--active" : ""
              }`}
              style={{ gridTemplateColumns: FLEET_ACTIVITY_GRID_TEMPLATE_COLUMNS }}
            >
              <div className="table-cell primary">
                {formatTime(event.timestamp)}
              </div>
              <div className="table-cell">
                <span
                  className={`agent-fleet-action agent-fleet-action--${event.action.toLowerCase()}`}
                >
                  {event.action}
                </span>
              </div>
              <div className="table-cell">
                {onViewAssetOnChart && klineSupported ? (
                  <button
                    type="button"
                    className={`agent-fleet-asset-link${
                      isActiveAsset ? " agent-fleet-asset-link--active" : ""
                    }`}
                    onClick={() => onViewAssetOnChart(event)}
                  >
                    {event.coin}
                  </button>
                ) : (
                  <span
                    className={
                      klineSupported ? undefined : "agent-fleet-asset-link--disabled"
                    }
                    title={
                      klineSupported
                        ? undefined
                        : "Kline not available for this asset"
                    }
                  >
                    {event.coin}
                  </span>
                )}
              </div>
              <div className="table-cell right">
                ${event.amountUsd.toFixed(0)}
              </div>
              <div
                className="table-cell right"
                style={{ color: pnlColor, fontWeight: pnlColor ? 500 : 400 }}
              >
                {event.closedPnl != null
                  ? `${event.closedPnl >= 0 ? "+" : ""}$${event.closedPnl.toFixed(2)}`
                  : "—"}
              </div>
              <div className="table-cell" title={event.txSimHash}>
                {shortWallet(event.txSimHash)}
              </div>
              <div className="table-cell" title={event.agentWallet}>
                {shortWallet(event.agentWallet)}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
