import type { AgentTask } from "../store/types";

export type ObjectiveGroupRow = {
  kind: "objective";
  objectiveId: string;
  objectiveSummary: string;
  intents: AgentTask[];
  leadIntent: AgentTask;
};

export type StandaloneIntentRow = {
  kind: "intent";
  intent: AgentTask;
};

export type AgentTaskTableRow = ObjectiveGroupRow | StandaloneIntentRow;

export function groupAgentTasksByObjective(tasks: AgentTask[]): AgentTaskTableRow[] {
  const grouped = new Map<string, AgentTask[]>();

  for (const task of tasks) {
    if (task.objectiveId) {
      const bucket = grouped.get(task.objectiveId) ?? [];
      bucket.push(task);
      grouped.set(task.objectiveId, bucket);
    }
  }

  const seenObjectives = new Set<string>();
  const rows: AgentTaskTableRow[] = [];

  for (const task of tasks) {
    if (task.objectiveId) {
      if (seenObjectives.has(task.objectiveId)) continue;
      seenObjectives.add(task.objectiveId);
      const intents = grouped.get(task.objectiveId) ?? [];
      const sorted = [...intents].sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
      );
      const leadIntent = sorted[0]!;
      rows.push({
        kind: "objective",
        objectiveId: task.objectiveId,
        objectiveSummary:
          leadIntent.objectiveSummary ?? leadIntent.description,
        intents: sorted,
        leadIntent,
      });
    } else {
      rows.push({ kind: "intent", intent: task });
    }
  }

  return rows;
}

export function flattenAgentTaskTableRows(rows: AgentTaskTableRow[]): AgentTask[] {
  const result: AgentTask[] = [];
  for (const row of rows) {
    if (row.kind === "objective") {
      result.push(...row.intents);
    } else {
      result.push(row.intent);
    }
  }
  return result;
}
