import { useCallback, useState } from "react";
import { toast } from "sonner";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useBucketPolicyStore } from "../../store/bucketPolicyStore";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import {
  applyDemoCloseBucket,
  setDemoBucketClosing,
} from "../../../offline/mock_data";
import { useBucketWithdraw } from "./useBucketWithdraw";

export type BucketCloseStep =
  | "idle"
  | "locking"
  | "stopping-agents"
  | "withdrawing"
  | "clearing"
  | "done"
  | "error";

export interface UseBucketCloseOptions {
  baseURL: string;
  walletAddress?: string;
  mnemonic?: string;
  bucketId: string;
  withdrawable: number;
  onComplete?: (bucketId: string) => void;
}

export function useBucketClose({
  baseURL,
  walletAddress,
  mnemonic,
  bucketId,
  withdrawable,
  onComplete,
}: UseBucketCloseOptions) {
  const { pauseActiveTasksForBucket, rejectAllPendingForBucket } =
    useAgentTasks();
  const clearPolicy = useBucketPolicyStore((s) => s.clearPolicy);
  const { withdrawToSpot } = useBucketWithdraw({
    baseURL,
    walletAddress,
    mnemonic,
  });
  const [step, setStep] = useState<BucketCloseStep>("idle");
  const [error, setError] = useState<string | null>(null);
  const isOffline = isOfflineMode(baseURL);

  const closeBucket = useCallback(async () => {
    setError(null);
    try {
      setStep("locking");
      if (isOffline && walletAddress?.trim()) {
        setDemoBucketClosing(walletAddress, bucketId);
      }

      setStep("stopping-agents");
      pauseActiveTasksForBucket(bucketId);
      rejectAllPendingForBucket(bucketId);

      setStep("withdrawing");
      if (withdrawable > 0) {
        await withdrawToSpot(bucketId, withdrawable);
      }

      setStep("clearing");
      clearPolicy(bucketId);
      if (isOffline && walletAddress?.trim()) {
        applyDemoCloseBucket(walletAddress, bucketId);
      }

      setStep("done");
      toast.success("Bucket closed", {
        description: "Capital returned to spot and agents disabled for this bucket",
      });
      onComplete?.(bucketId);
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Failed to close bucket";
      setError(message);
      setStep("error");
      toast.error("Close bucket failed", { description: message });
    }
  }, [
    isOffline,
    walletAddress,
    bucketId,
    withdrawable,
    pauseActiveTasksForBucket,
    rejectAllPendingForBucket,
    withdrawToSpot,
    clearPolicy,
    onComplete,
  ]);

  const resetClose = useCallback(() => {
    setStep("idle");
    setError(null);
  }, []);

  return { closeBucket, step, error, resetClose, isClosing: step !== "idle" && step !== "done" && step !== "error" };
}
