import React, { useMemo } from "react";

import type { DailyPnlDay } from "../../utils/portfolioChartData";
import {
  formatCompactCurrency,
  formatDayLabel,
  formatMonthLabel,
} from "../../utils/dailyPnlFormat";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import "./portfolio.css";

export interface DailyPnlCalendarProps {
  days: DailyPnlDay[];
  className?: string;
}

function DailyPnlCalendar({
  days,
  className = "",
}: DailyPnlCalendarProps): JSX.Element {
  const monthLabel = useMemo(() => formatMonthLabel(days), [days]);

  return (
    <div className={`portfolio-daily-pnl-calendar${className ? ` ${className}` : ""}`}>
      <div className="portfolio-daily-pnl-calendar-header">
        <svg
          className="portfolio-daily-pnl-calendar-icon"
          width="14"
          height="14"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          aria-hidden
        >
          <rect x="3" y="4" width="18" height="18" rx="2" />
          <line x1="16" y1="2" x2="16" y2="6" />
          <line x1="8" y1="2" x2="8" y2="6" />
          <line x1="3" y1="10" x2="21" y2="10" />
        </svg>
        <span>{monthLabel}</span>
      </div>
      <div className="portfolio-daily-pnl-grid">
        {days.map((day) => {
          if (day.isEmpty || day.pnl === null) {
            return (
              <div
                key={day.dateKey}
                className="portfolio-daily-pnl-day portfolio-daily-pnl-day--empty"
                aria-hidden
              />
            );
          }

          const isPositive = day.pnl >= 0;
          return (
            <BubbleTip
              key={day.dateKey}
              id={BUBBLE_TIP_IDS.dailyPnlDay}
              title={formatDayLabel(day.dateKey)}
              content={formatCompactCurrency(day.pnl)}
            >
              <div
                className={`portfolio-daily-pnl-day ${
                  isPositive
                    ? "portfolio-daily-pnl-day--positive"
                    : "portfolio-daily-pnl-day--negative"
                }`}
              >
                {formatCompactCurrency(day.pnl)}
              </div>
            </BubbleTip>
          );
        })}
      </div>
    </div>
  );
}

export default React.memo(DailyPnlCalendar);
