import React, { useMemo } from "react";
import { useMarkets } from "../../hooks/useMarkets";
import { useTradePrice } from "../../hooks/useTradePrice";
import { formatPriceFlexible, formatPercentage } from "../../sdk/utils/display";
import { DEFAULT_BASE_URL } from "../../constants";
import {
  getMockMarketPriceByTicker,
  getTickerPickerMeta,
} from "../../../offline/mock_data";
import { isOfflineMode } from "../../sdk/utils/onboardMock";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

export interface MarketContextChipProps {
  baseURL?: string;
  selectedMarketId: string;
  onOpenTickerSelection?: () => void;
  tickerSelectionOpen?: boolean;
  selectionAnchorRef?: React.RefObject<HTMLDivElement | null>;
}

function parseOptionalNumber(value: string | number | null | undefined): number | null {
  if (value == null) return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const parsed = parseFloat(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function MarketContextChip({
  baseURL = DEFAULT_BASE_URL,
  selectedMarketId,
  onOpenTickerSelection,
  tickerSelectionOpen = false,
  selectionAnchorRef,
}: MarketContextChipProps): JSX.Element {
  const { markets, tickers } = useMarkets({
    baseURL,
    autoFetchMarkets: true,
  });

  const { displayPrice: tradeDisplayPrice } = useTradePrice({
    baseURL,
    marketId: selectedMarketId,
  });

  const selectedMarket = useMemo(
    () =>
      markets.find(
        (m) =>
          m.index === selectedMarketId || m.marketIndex === selectedMarketId,
      ),
    [markets, selectedMarketId],
  );

  const selectedTicker = useMemo(
    () => tickers.get(selectedMarketId),
    [tickers, selectedMarketId],
  );

  const baseAsset = useMemo(
    () =>
      selectedMarket?.baseAsset ||
      selectedMarket?.moniker?.split("/")[0]?.split("-")[0] ||
      selectedMarket?.symbol?.split("/")[0]?.split("-")[0] ||
      "",
    [selectedMarket],
  );

  const pickerMeta = useMemo(
    () => getTickerPickerMeta(baseAsset),
    [baseAsset],
  );

  const symbolLabel = useMemo(() => {
    if (!baseAsset) return "—";
    return pickerMeta.tickerLabel ?? baseAsset.toUpperCase();
  }, [baseAsset, pickerMeta]);

  const offline = isOfflineMode(baseURL);
  const mockBasePrice = getMockMarketPriceByTicker(baseAsset);

  const tickerLastPrice = useMemo(
    () => parseOptionalNumber(selectedTicker?.lastPrice),
    [selectedTicker],
  );

  const liveChangePercent = useMemo(
    () => parseOptionalNumber(selectedTicker?.priceChangePercent24h),
    [selectedTicker],
  );

  const displayPrice = useMemo(() => {
    if (tradeDisplayPrice != null) return tradeDisplayPrice;
    if (tickerLastPrice != null) return tickerLastPrice;
    if (offline && baseAsset) return mockBasePrice;
    return null;
  }, [tradeDisplayPrice, tickerLastPrice, offline, baseAsset, mockBasePrice]);

  const priceChangePercent = useMemo(() => {
    if (liveChangePercent != null) return liveChangePercent;
    if (offline && baseAsset) return pickerMeta.change24h;
    return null;
  }, [liveChangePercent, offline, baseAsset, pickerMeta.change24h]);

  const handleOpen = (e: React.MouseEvent | React.KeyboardEvent) => {
    if (!onOpenTickerSelection) return;
    e.stopPropagation();
    onOpenTickerSelection();
  };

  const isClickable = Boolean(onOpenTickerSelection);

  const chipClassName = [
    "market-context-chip",
    isClickable ? "market-context-chip--clickable" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.marketContextChip}>
      <div
        ref={selectionAnchorRef}
        className={chipClassName}
        data-tour="welcome-market-selector"
        role={isClickable ? "button" : undefined}
        tabIndex={isClickable ? 0 : undefined}
        aria-expanded={isClickable ? tickerSelectionOpen : undefined}
        aria-label={
          isClickable ? `Validation market ${symbolLabel}, open picker` : undefined
        }
        onClick={isClickable ? handleOpen : undefined}
        onKeyDown={
          isClickable
            ? (e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleOpen(e);
                }
              }
            : undefined
        }
      >
        <span className="market-context-chip-symbol-group">
          <span className="market-context-chip-symbol">{symbolLabel}</span>
          {isClickable ? (
            <ExpandCollapseIcon
              expanded={tickerSelectionOpen}
              className="market-context-chip-chevron"
              size={12}
            />
          ) : null}
        </span>
        <span className="market-context-chip-price">
          {displayPrice !== null ? formatPriceFlexible(displayPrice) : "—"}
        </span>
        {priceChangePercent !== null ? (
          <span
            className={`market-context-chip-change ${
              priceChangePercent >= 0 ? "positive" : "negative"
            }`}
          >
            {priceChangePercent >= 0 ? "+" : ""}
            {formatPercentage(priceChangePercent / 100)}
          </span>
        ) : null}
      </div>
    </BubbleTip>
  );
}

export default React.memo(MarketContextChip);
