import type { IntentBreakdown } from "../components/intentwindow/intentBreakdown";

const ENRICH_TIMEOUT_MS = 300;
const ENRICH_ENDPOINT = "/api/intent/enrich";

export interface IntentEnrichOptions {
  baseURL?: string;
  authToken?: string;
  timeoutMs?: number;
}

function mergeBreakdowns(
  client: IntentBreakdown,
  server: Partial<IntentBreakdown>,
): IntentBreakdown {
  if (!server.slots) return client;

  const merged = { ...client, slots: { ...client.slots } };

  for (const key of Object.keys(server.slots) as (keyof typeof merged.slots)[]) {
    const clientFacet = merged.slots[key];
    const serverFacet = server.slots[key];
    if (!serverFacet) continue;

    const clientWeak =
      clientFacet.confidence === "missing" ||
      clientFacet.confidence === "ambiguous";
    const serverStrong =
      serverFacet.confidence === "resolved" ||
      serverFacet.confidence === "defaulted";

    if (clientWeak && serverStrong) {
      merged.slots[key] = serverFacet as (typeof merged.slots)[typeof key];
    }
  }

  return merged;
}

export async function enrichIntentBreakdown(
  breakdown: IntentBreakdown,
  options: IntentEnrichOptions = {},
  signal?: AbortSignal,
): Promise<IntentBreakdown> {
  const timeoutMs = options.timeoutMs ?? ENRICH_TIMEOUT_MS;
  const baseURL = options.baseURL ?? "";

  if (!baseURL || typeof fetch === "undefined") {
    return breakdown;
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const url = `${baseURL.replace(/\/$/, "")}${ENRICH_ENDPOINT}`;
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(options.authToken ? { Authorization: `Bearer ${options.authToken}` } : {}),
      },
      body: JSON.stringify({
        text: breakdown.rawText,
        clientBreakdown: breakdown,
      }),
      signal: signal ?? controller.signal,
    });

    if (!res.ok) return breakdown;

    const server = (await res.json()) as Partial<IntentBreakdown>;
    return mergeBreakdowns(breakdown, server);
  } catch {
    return breakdown;
  } finally {
    clearTimeout(timeout);
  }
}
