import { useCallback } from "react";
import { useKeyboardShortcut } from "../../utils/keyboardShortcuts";

export interface UseIntentWindowShortcutOptions {
  enabled: boolean;
  onOpen: () => void;
  /** When true, shortcut is suppressed (e.g. modal already open) */
  isOpen?: boolean;
}

function isForeignEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  if (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  ) {
    return !target.closest("[data-intent-window-root]");
  }
  return false;
}

export function useIntentWindowShortcut({
  enabled,
  onOpen,
  isOpen = false,
}: UseIntentWindowShortcutOptions): void {
  const handler = useCallback(
    (event: KeyboardEvent) => {
      void event;
      onOpen();
    },
    [onOpen],
  );

  useKeyboardShortcut("openIntentComposer", handler, {
    enabled: enabled && !isOpen,
    suppressWhen: (event) => isForeignEditableTarget(event.target),
  });
}
