import React, { useEffect, useMemo, useRef, type JSX } from "react";
import {
  AreaSeries,
  LineSeries,
  LineType,
  createChart,
  type IChartApi,
  type ISeriesApi,
  type LineData,
  type UTCTimestamp,
} from "lightweight-charts";
import { sanitizeLineDataForChart } from "../../utils/portfolioChartData";
import {
  createPortfolioChartOptions,
  createPortfolioPnlChartOptions,
  portfolioAreaSeriesOptions,
  portfolioLeftAxisAreaSeriesOptions,
  portfolioLineSeriesOptions,
  portfolioPnlLineSeriesOptions,
} from "./portfolioChartTheme";

export interface PortfolioChartSeries {
  id: string;
  data: LineData<UTCTimestamp>[];
  color: string;
  lineType?: LineType;
}

export interface PortfolioTimeSeriesChartProps {
  series: PortfolioChartSeries[];
  variant: "area" | "line";
  emptyMessage?: string;
  className?: string;
  priceScale?: "left" | "right";
}

function PortfolioTimeSeriesChart({
  series,
  variant,
  emptyMessage = "No data",
  className = "",
  priceScale = "right",
}: PortfolioTimeSeriesChartProps): JSX.Element {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRefs = useRef<
    Map<string, ISeriesApi<"Line"> | ISeriesApi<"Area">>
  >(new Map());

  const hasData = series.some((entry) => entry.data.length > 0);

  const seriesKey = useMemo(
    () =>
      `${variant}|${priceScale}|${series
        .map(
          (entry) =>
            `${entry.id}:${entry.color}:${entry.lineType ?? LineType.Simple}:${entry.data.length}`,
        )
        .join("|")}`,
    [series, variant, priceScale],
  );

  useEffect(() => {
    if (!chartContainerRef.current || !hasData) return;

    if (chartRef.current) {
      try {
        chartRef.current.remove();
      } catch {
        // ignore
      }
      chartRef.current = null;
      seriesRefs.current.clear();
    }

    let chart: IChartApi | null = null;
    let animationFrameId: number | null = null;
    let initAttempts = 0;
    const maxInitAttempts = 120;

    const initializeChart = () => {
      if (!chartContainerRef.current) return;

      const container = chartContainerRef.current;
      const containerWidth = container.clientWidth || container.offsetWidth;
      const containerHeight = container.clientHeight || container.offsetHeight;

      if (
        (!containerWidth ||
          containerWidth < 50 ||
          !containerHeight ||
          containerHeight < 60) &&
        initAttempts < maxInitAttempts
      ) {
        initAttempts += 1;
        animationFrameId = requestAnimationFrame(initializeChart);
        return;
      }

      try {
        const chartOptions =
          priceScale === "left"
            ? createPortfolioPnlChartOptions()
            : createPortfolioChartOptions();
        chart = createChart(container, chartOptions);
        const refs = new Map<string, ISeriesApi<"Line"> | ISeriesApi<"Area">>();

        if (variant === "area") {
          const primary = series[0];
          if (primary && primary.data.length > 0) {
            const areaOptions =
              priceScale === "left"
                ? portfolioLeftAxisAreaSeriesOptions()
                : portfolioAreaSeriesOptions();
            const areaSeries = chart.addSeries(AreaSeries, areaOptions);
            areaSeries.setData(sanitizeLineDataForChart(primary.data));
            refs.set(primary.id, areaSeries);
          }
        } else {
          for (const config of series) {
            if (config.data.length === 0) continue;
            const lineOptions =
              priceScale === "left"
                ? portfolioPnlLineSeriesOptions(config.color)
                : portfolioLineSeriesOptions(
                    config.color,
                    config.lineType ?? LineType.WithSteps,
                  );
            const lineSeries = chart.addSeries(LineSeries, lineOptions);
            lineSeries.setData(sanitizeLineDataForChart(config.data));
            refs.set(config.id, lineSeries);
          }
        }

        if (priceScale === "left") {
          chart.priceScale("left").applyOptions({ autoScale: true });
        }

        chart.timeScale().fitContent();
        chartRef.current = chart;
        seriesRefs.current = refs;
      } catch (error) {
        console.error("[PortfolioTimeSeriesChart] Error creating chart:", error);
      }
    };

    initializeChart();

    return () => {
      if (animationFrameId !== null) {
        cancelAnimationFrame(animationFrameId);
      }
      if (chart) {
        try {
          chart.remove();
        } catch {
          // ignore
        }
      }
      chartRef.current = null;
      seriesRefs.current.clear();
    };
  }, [hasData, seriesKey, variant, priceScale, series]);

  useEffect(() => {
    if (seriesRefs.current.size === 0 || !hasData) return;

    for (const config of series) {
      const chartSeries = seriesRefs.current.get(config.id);
      if (!chartSeries || config.data.length === 0) continue;
      try {
        chartSeries.setData(sanitizeLineDataForChart(config.data));
      } catch (error) {
        console.error(
          "[PortfolioTimeSeriesChart] Error updating series:",
          config.id,
          error,
        );
      }
    }

    chartRef.current?.timeScale().fitContent();
  }, [series, hasData]);

  if (!hasData) {
    return (
      <div className={`portfolio-hero-chart-empty terminal-text-muted ${className}`}>
        {emptyMessage}
      </div>
    );
  }

  return (
    <div
      ref={chartContainerRef}
      className={`portfolio-hero-chart-canvas ${className}`}
      role="img"
      aria-label="Portfolio time series chart"
    />
  );
}

export default React.memo(PortfolioTimeSeriesChart);
