import React, { useState } from "react";

import {
  CATALOG_SKILLS,
  SKILLS_BANKR_URL,
} from "./agentSettingsCatalog";
import { isCatalogSkillInstalled } from "./agentSettingsStorage";
import type { AgentSettingsState, SkillFile } from "./agentSettingsTypes";
import { CreateSkillModal } from "./agentSettingsModals";

export interface AgentSkillsTabProps {
  settings: AgentSettingsState;
  onInstallCatalog: (catalogId: string) => boolean;
  onCreateCustom: (files: SkillFile[]) => boolean;
  onRemoveSkill: (skillId: string) => void;
}

function AgentSkillsTab({
  settings,
  onInstallCatalog,
  onCreateCustom,
  onRemoveSkill,
}: AgentSkillsTabProps): JSX.Element {
  const [createOpen, setCreateOpen] = useState(false);
  const hasInstalled = settings.skills.length > 0;

  return (
    <>
      <div className="agent-settings-section-header">
        <div>
          <h4 className="agent-settings-section-title">Your Skills</h4>
          <p className="agent-settings-section-desc">
            SKILL.md + references/ that teach your agent new capabilities
          </p>
        </div>
        <button
          type="button"
          className="agent-secondary-btn"
          onClick={() => setCreateOpen(true)}
        >
          + Add
        </button>
      </div>

      {hasInstalled ? (
        <div className="agent-settings-installed-list">
          {settings.skills.map((skill) => (
            <div key={skill.id} className="agent-settings-installed-card">
              <div className="agent-settings-catalog-card-body">
                <p className="agent-settings-catalog-card-title">{skill.name}</p>
                <p className="agent-settings-catalog-card-desc">{skill.description}</p>
              </div>
              <button
                type="button"
                className="agent-secondary-btn"
                onClick={() => onRemoveSkill(skill.id)}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      ) : (
        <div className="agent-settings-empty">
          <p className="agent-settings-empty-title">Get started</p>
          <p className="agent-settings-empty-desc">
            Install an example skill to see what your agent can do.
          </p>
          <div className="agent-settings-catalog-list">
            {CATALOG_SKILLS.map((entry) => {
              const installed = isCatalogSkillInstalled(settings, entry.catalogId);
              return (
                <div key={entry.catalogId} className="agent-settings-catalog-card">
                  <div className="agent-settings-catalog-card-body">
                    <p className="agent-settings-catalog-card-title">{entry.name}</p>
                    <p className="agent-settings-catalog-card-desc">{entry.description}</p>
                  </div>
                  <button
                    type="button"
                    className="agent-secondary-btn agent-secondary-btn--primary"
                    disabled={installed}
                    onClick={() => onInstallCatalog(entry.catalogId)}
                  >
                    {installed ? "Installed" : "Install"}
                  </button>
                </div>
              );
            })}
          </div>
          <p className="agent-settings-external-link">
            Browse more at{" "}
            <a href={SKILLS_BANKR_URL} target="_blank" rel="noopener noreferrer">
              skills.bankr.bot
            </a>
          </p>
        </div>
      )}

      <CreateSkillModal
        open={createOpen}
        onClose={() => setCreateOpen(false)}
        onCreate={(files: SkillFile[]) => {
          const ok = onCreateCustom(files);
          if (ok) setCreateOpen(false);
          return ok;
        }}
      />
    </>
  );
}

export default AgentSkillsTab;
