import React from "react";
import { createPortal } from "react-dom";

import MorpheumInlineLoading from "../../ui/MorpheumInlineLoading";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
  useOverlayScrollLock,
} from "../../ui/overlay";
import AgentCompareShareCard from "./AgentCompareShareCard";
import type { AgentCompareSharePayload } from "./agentCompareShareData";
import { useAgentCompareShareActions } from "./useAgentCompareShareActions";
import "../../index/share/indexShare.css";

export interface AgentCompareShareModalProps {
  isOpen: boolean;
  onClose: () => void;
  payload: AgentCompareSharePayload;
}

function ShareRailIcon({
  children,
}: {
  children: React.ReactNode;
}): JSX.Element {
  return (
    <span className="index-share-rail-icon" aria-hidden>
      {children}
    </span>
  );
}

function CloseIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M18 6L6 18M6 6l12 12" />
    </svg>
  );
}

function AgentCompareShareModal({
  isOpen,
  onClose,
  payload,
}: AgentCompareShareModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onClose);
  useOverlayScrollLock(isOpen && mounted);

  const {
    cardRef,
    isCardReady,
    onCopyImage,
    onDownloadImage,
    onCopyLink,
    onShareX,
    onShareTelegram,
  } = useAgentCompareShareActions(isOpen, payload);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="index-share-overlay-root">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        className="staggered-overlay-backdrop--deep"
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="index-share-panel staggered-overlay-panel--scale"
        aria-label="Share agent compare"
      >
        <div className="index-share-layout">
          <aside className="index-share-rail" aria-label="Share actions">
            <button
              type="button"
              className="index-share-rail-btn"
              onClick={onShareX}
            >
              <ShareRailIcon>
                <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                  <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z" />
                </svg>
              </ShareRailIcon>
              <span>X</span>
            </button>
            <button
              type="button"
              className="index-share-rail-btn"
              onClick={onShareTelegram}
            >
              <ShareRailIcon>
                <svg
                  viewBox="0 0 24 24"
                  width="18"
                  height="18"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M22 2 11 13" />
                  <path d="M22 2 15 22l-4-9-9-4z" />
                </svg>
              </ShareRailIcon>
              <span>Telegram</span>
            </button>
            <button
              type="button"
              className="index-share-rail-btn"
              onClick={() => void onCopyImage()}
              disabled={!isCardReady}
            >
              <ShareRailIcon>
                <svg
                  viewBox="0 0 24 24"
                  width="18"
                  height="18"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <rect x="3" y="3" width="18" height="18" rx="2" />
                  <circle cx="8.5" cy="8.5" r="1.5" />
                  <path d="m21 15-5-5L5 21" />
                </svg>
              </ShareRailIcon>
              <span>Copy Image</span>
            </button>
            <button
              type="button"
              className="index-share-rail-btn"
              onClick={() => void onDownloadImage()}
              disabled={!isCardReady}
            >
              <ShareRailIcon>
                <svg
                  viewBox="0 0 24 24"
                  width="18"
                  height="18"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M12 3v12" />
                  <path d="m7 10 5 5 5-5" />
                  <path d="M5 21h14" />
                </svg>
              </ShareRailIcon>
              <span>Download Image</span>
            </button>
            <hr className="index-share-rail-divider" />
            <button
              type="button"
              className="index-share-rail-btn"
              onClick={() => void onCopyLink()}
            >
              <ShareRailIcon>
                <svg
                  viewBox="0 0 24 24"
                  width="18"
                  height="18"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" />
                  <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" />
                </svg>
              </ShareRailIcon>
              <span>Copy link</span>
            </button>
          </aside>

          <div className="index-share-preview-wrap">
            <button
              type="button"
              className="index-share-close"
              onClick={onClose}
              aria-label="Close share modal"
            >
              <CloseIcon />
            </button>
            <div className="index-share-preview">
              {!isCardReady ? (
                <MorpheumInlineLoading message="Preparing share card..." />
              ) : null}
              <div
                ref={cardRef}
                className={`index-share-card-mount${
                  isCardReady ? " is-ready" : ""
                }`}
              >
                <AgentCompareShareCard payload={payload} />
              </div>
            </div>
          </div>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default AgentCompareShareModal;
