import React, { useEffect, useMemo, type JSX } from "react";

import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory.types";
import type { PropertyCharts, PropertyProfile } from "../../../offline/mock_data/types";
import { AGENT_DETAIL_TAB_BUBBLE_MAP } from "../../tutorials/bubble-tip";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import "../agentconsole/agentConsole.css";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import FleetActivityTab from "./FleetActivityTab";
import TokenTakerActivityTab from "./TokenTakerActivityTab";
import "./agent.css";

export type AgentDetailTabId = "activity" | "tokenTakers" | "execution" | "receipts";

const TAB_LABELS: Record<AgentDetailTabId, string> = {
  activity: "Fleet activity",
  tokenTakers: "Token takers",
  execution: "Execution feed",
  receipts: "Receipts",
};

const DETAIL_TAB_ORDER: AgentDetailTabId[] = [
  "activity",
  "tokenTakers",
  "execution",
  "receipts",
];

export interface AgentDetailTabSectionProps {
  height?: string;
  profile: PropertyProfile;
  charts: PropertyCharts;
  fleetTrades: FleetTradeEvent[];
  hasAgentToken?: boolean;
  onViewAssetOnChart?: (event: FleetTradeEvent) => void;
  activeAssetCoin?: string | null;
  activeTab?: AgentDetailTabId;
  onTabChange?: (tabId: AgentDetailTabId) => void;
  onViewTakerOnChart?: (event: AgentTokenTakerTradeEvent) => void;
  activeTakerEventId?: string | null;
}

function AgentDetailTabSection({
  height = "100%",
  profile,
  charts,
  fleetTrades,
  hasAgentToken = false,
  onViewAssetOnChart,
  activeAssetCoin = null,
  activeTab: controlledTab,
  onTabChange,
  onViewTakerOnChart,
  activeTakerEventId = null,
}: AgentDetailTabSectionProps): JSX.Element {
  const [internalTab, setInternalTab] = React.useState<AgentDetailTabId>("activity");
  const isControlled = controlledTab != null && onTabChange != null;
  const activeTab = isControlled ? controlledTab : internalTab;
  const setActiveTab = isControlled ? onTabChange : setInternalTab;

  const tabIds = useMemo(
    () =>
      DETAIL_TAB_ORDER.filter(
        (id) => id !== "tokenTakers" || hasAgentToken,
      ),
    [hasAgentToken],
  );

  useEffect(() => {
    if (activeTab === "tokenTakers" && !hasAgentToken) {
      setActiveTab("activity");
    }
  }, [activeTab, hasAgentToken, setActiveTab]);

  const tabs = useMemo(
    () =>
      tabIds.map((id) => ({
        id,
        label: TAB_LABELS[id],
        bubbleTipId: AGENT_DETAIL_TAB_BUBBLE_MAP[id],
      })),
    [tabIds],
  );

  return (
    <div
      className="agent-slot agent-detail-tab-section"
      style={{ height }}
      aria-label={`${profile.name} detail tabs`}
    >
      <div className="layout-container tab-section-root agent-detail-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={activeTab}
          onTabChange={(id) => setActiveTab(id as AgentDetailTabId)}
        />
        <div className="tab-section-content">
          {activeTab === "activity" ? (
            <FleetActivityTab
              catalogAgentId={profile.id}
              trades={fleetTrades}
              onViewAssetOnChart={onViewAssetOnChart}
              activeAssetCoin={activeAssetCoin}
            />
          ) : null}

          {activeTab === "tokenTakers" && hasAgentToken ? (
            <TokenTakerActivityTab
              marketCatalogAgentId={profile.id}
              emptyMessage="No taker activity for this token yet."
              onViewEventOnChart={onViewTakerOnChart}
              activeEventId={activeTakerEventId}
            />
          ) : null}

          {activeTab === "execution" ? (
            <ul className="agent-execution-feed">
              {charts.executionFeed.map((entry) => (
                <li key={`${entry.time}-${entry.event}`} className="agent-execution-feed-item">
                  <span className="agent-execution-feed-time">{entry.time}</span>
                  <span className="agent-execution-feed-event">{entry.event}</span>
                  <span className="agent-execution-feed-result">{entry.result}</span>
                </li>
              ))}
            </ul>
          ) : null}

          {activeTab === "receipts" ? (
            <ul className="agent-receipts-list">
              {charts.receiptsFeed.map((entry) => (
                <li key={entry.title} className="agent-receipt-item">
                  <strong>{entry.title}</strong>
                  <span>{entry.description}</span>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default AgentDetailTabSection;
