import React from "react";

import type { MarketKind } from "../../hooks/useMarketsPageData";
import {
  REVENUE_OPTIONS,
  RISK_OPTIONS,
  SECTOR_OPTIONS,
} from "../../hooks/useMarketsPageData";
import "./markets.css";

export interface MarketsSearchToolbarProps {
  height?: string;
  activeTab: MarketKind;
  onTabChange: (tab: MarketKind) => void;
  query: string;
  sector: string;
  risk: string;
  revenue: string;
  onQueryChange: (value: string) => void;
  onSectorChange: (value: string) => void;
  onRiskChange: (value: string) => void;
  onRevenueChange: (value: string) => void;
}

export default function MarketsSearchToolbar({
  height = "100%",
  activeTab,
  onTabChange,
  query,
  sector,
  risk,
  revenue,
  onQueryChange,
  onSectorChange,
  onRiskChange,
  onRevenueChange,
}: MarketsSearchToolbarProps): JSX.Element {
  return (
    <div className="markets-slot markets-toolbar-panel" style={{ height }}>
      <nav
        className="markets-tabs markets-toolbar-tabs"
        role="tablist"
        aria-label="Markets tabs"
      >
        <button
          type="button"
          role="tab"
          aria-selected={activeTab === "agent"}
          className={`markets-pill-btn${activeTab === "agent" ? " active" : ""}`}
          onClick={() => onTabChange("agent")}
        >
          Agents
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={activeTab === "index"}
          className={`markets-pill-btn${activeTab === "index" ? " active" : ""}`}
          onClick={() => onTabChange("index")}
        >
          Indices (MAEX)
        </button>
      </nav>
      <div className="markets-search-row">
        <div className="terminal-search-field markets-search-field">
          <input
            className="terminal-search-input"
            value={query}
            onChange={(e) => onQueryChange(e.target.value)}
            placeholder="Search markets"
            aria-label="Search markets"
          />
        </div>
        <select
          className="form-input markets-filter-select"
          value={sector}
          onChange={(e) => onSectorChange(e.target.value)}
          aria-label="Filter by sector"
        >
          {SECTOR_OPTIONS.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
        <select
          className="form-input markets-filter-select"
          value={risk}
          onChange={(e) => onRiskChange(e.target.value)}
          aria-label="Filter by risk"
        >
          {RISK_OPTIONS.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
        <select
          className="form-input markets-filter-select"
          value={revenue}
          onChange={(e) => onRevenueChange(e.target.value)}
          aria-label="Filter by revenue"
        >
          {REVENUE_OPTIONS.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}
