import { useCallback, useEffect, useRef, useState, type PointerEvent, type RefObject } from "react";
import { useFiClient } from "./useFiClient";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { modifyMockOrderPrice } from "../../offline/mock_data";
import {
  createErrorCopyAction,
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
} from "../components/ui/Toaster";
import type { KlineChartRef } from "../components/finchartview/KlineChart";
import type { ChartPendingOrderLineMeta } from "../components/finchartview/chartOrderLines";

export interface UsePendingOrderPriceDragConfig {
  chartRef: RefObject<KlineChartRef | null>;
  baseURL: string;
  mnemonic?: string;
  walletAddress?: string;
  marketId: string;
}

export interface UsePendingOrderPriceDragResult {
  draggingLineId: string | null;
  draftPrices: ReadonlyMap<string, number>;
  startDrag: (
    lineId: string,
    meta: ChartPendingOrderLineMeta,
    event: PointerEvent<HTMLButtonElement>,
  ) => void;
}

export function usePendingOrderPriceDrag(
  config: UsePendingOrderPriceDragConfig,
): UsePendingOrderPriceDragResult {
  const { chartRef, baseURL, mnemonic, walletAddress, marketId } = config;
  const [draggingLineId, setDraggingLineId] = useState<string | null>(null);
  const [draftPrices, setDraftPrices] = useState<ReadonlyMap<string, number>>(new Map());
  const dragMetaRef = useRef<ChartPendingOrderLineMeta | null>(null);
  const { client: exchangeClient, isReady: exchangeReady } = useFiClient({
    baseURL,
    mnemonic,
  });

  const commitPrice = useCallback(
    async (meta: ChartPendingOrderLineMeta, newPrice: number) => {
      const orderId = meta.orderId;
      const loadingId = toastLoading("Updating order price...", {
        description: `Setting price to ${newPrice}`,
      });

      try {
        if (isOfflineMode(baseURL)) {
          const updated = modifyMockOrderPrice(orderId, newPrice, walletAddress);
          if (updated) {
            toastCompleteSuccess(loadingId, "Order price updated", {
              description: `Order ${orderId} price set to ${newPrice}`,
            });
          } else {
            throw new Error(`Order ${orderId} was not found.`);
          }
          return;
        }

        if (!exchangeClient || !exchangeReady) {
          throw new Error("Exchange client not ready");
        }

        const response = await exchangeClient.modifyOrder({
          orderId,
          marketId,
          newPrice,
          newQuantity: meta.remainingQuantity,
        });

        const isSuccess =
          response?.success === true ||
          response?.result?.success === true ||
          (response && !response.error && !response.message);

        if (!isSuccess) {
          const errorMsg =
            response?.error ||
            response?.message ||
            response?.response?.error ||
            "Failed to update order price";
          throw new Error(errorMsg);
        }

        toastCompleteSuccess(loadingId, "Order price updated", {
          description: `Order ${orderId} price set to ${newPrice}`,
        });
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : "Unknown error occurred";
        toastCompleteError(loadingId, "Failed to update order price", {
          description: errorMessage,
          duration: 6000,
          action: createErrorCopyAction(errorMessage),
        });
      }
    },
    [baseURL, exchangeClient, exchangeReady, marketId, walletAddress],
  );

  const startDrag = useCallback(
    (
      lineId: string,
      meta: ChartPendingOrderLineMeta,
      event: PointerEvent<HTMLButtonElement>,
    ) => {
      event.preventDefault();
      event.stopPropagation();
      dragMetaRef.current = meta;
      setDraggingLineId(lineId);
      setDraftPrices(new Map([[lineId, meta.price]]));
      event.currentTarget.setPointerCapture(event.pointerId);
    },
    [],
  );

  useEffect(() => {
    if (!draggingLineId) return;

    const handlePointerMove = (event: PointerEvent) => {
      const chart = chartRef.current;
      const meta = dragMetaRef.current;
      if (!chart || !meta) return;
      const price = chart.coordinateToPrice(event.clientY);
      if (price == null || !Number.isFinite(price) || price <= 0) return;
      setDraftPrices(new Map([[draggingLineId, price]]));
    };

    const handlePointerUp = async (event: PointerEvent) => {
      const chart = chartRef.current;
      const meta = dragMetaRef.current;
      const lineId = draggingLineId;
      if (!chart || !meta || !lineId) {
        setDraggingLineId(null);
        setDraftPrices(new Map());
        dragMetaRef.current = null;
        return;
      }

      const price = chart.coordinateToPrice(event.clientY) ?? meta.price;
      setDraggingLineId(null);
      setDraftPrices(new Map());
      dragMetaRef.current = null;

      if (!Number.isFinite(price) || price <= 0 || price === meta.price) {
        return;
      }

      await commitPrice(meta, price);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerUp);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
    };
  }, [chartRef, commitPrice, draggingLineId]);

  return { draggingLineId, draftPrices, startDrag };
}
