import { type CSSProperties, type JSX } from "react";
import type { ExecutionMarkerKind } from "./chartMarkers";
import { MARKER_BUBBLE_BODY_GAP_PX, MARKER_BUBBLE_TIP_GAP_PX } from "./markerBubbleLayout";
import { useMarkerBubbleLayout } from "./useMarkerBubbleLayout";
import { formatNumber, formatPrice } from "../../sdk/utils/display";

export interface ChartOrderBubbleProps {
  kind: ExecutionMarkerKind;
  title: string;
  side: string;
  size: number;
  price: number;
  badge?: "Pending" | "Agent" | "Manual";
  footer?: string;
  footerColor?: string;
  x: number;
  y: number;
  containerWidth: number;
  containerHeight: number;
  onViewTask?: () => void;
}

function ChartOrderBubble({
  kind,
  title,
  side,
  size,
  price,
  badge,
  footer,
  footerColor,
  x,
  y,
  containerWidth,
  containerHeight,
  onViewTask,
}: ChartOrderBubbleProps): JSX.Element {
  const resolvedBadge =
    badge ?? (kind === "agent" ? "Agent" : "Manual");

  const { bubbleRef, layout } = useMarkerBubbleLayout(
    x,
    y,
    containerWidth,
    containerHeight,
    [title, price, footer, kind],
  );

  return (
    <div
      ref={bubbleRef}
      className={`execution-marker-bubble execution-marker-bubble--${layout.side}`}
      style={
        {
          left: layout.left,
          top: layout.top,
          "--marker-bubble-body-gap": `${MARKER_BUBBLE_BODY_GAP_PX}px`,
          "--marker-bubble-tip-gap": `${MARKER_BUBBLE_TIP_GAP_PX}px`,
          "--marker-bubble-arrow-offset-y": `${layout.arrowOffsetY}px`,
        } as CSSProperties
      }
      role="tooltip"
    >
      <div className="execution-marker-bubble__header">
        <span className="execution-marker-bubble__direction">{title}</span>
        <span
          className={`execution-marker-bubble__badge execution-marker-bubble__badge--${kind}`}
        >
          {resolvedBadge}
        </span>
      </div>
      <div className="execution-marker-bubble__body">
        <span className="execution-marker-bubble__side">{side}</span>
        {" "}
        {formatNumber(size)}
        {" @ "}
        {formatPrice(price)}
      </div>
      {footer ? (
        <div className="execution-marker-bubble__footer" style={{ color: footerColor }}>
          {footer}
        </div>
      ) : null}
      {kind === "agent" && onViewTask ? (
        <button type="button" className="execution-marker-bubble__link" onClick={onViewTask}>
          View task
        </button>
      ) : null}
      <span className="execution-marker-bubble__arrow" aria-hidden />
    </div>
  );
}

export default ChartOrderBubble;
