import type { SecurityStage } from "../types/crossChainFlow";
import type { CrossChainMode } from "../components/smartlayout/cross-chain-modal";
import type { WalletTransferAssetId } from "../components/smartlayout/wallet-transfer-modal";

export interface FailureScenario {
  title: string;
  whatHappened: string;
  fundState: string;
  primaryAction: string;
  secondaryAction: string;
}

export function getFailureScenario(
  stage: SecurityStage,
  mode: CrossChainMode,
  assetId: WalletTransferAssetId,
  amount: number,
  chain: string,
): FailureScenario {
  const amountLabel = `${amount} ${assetId}`;
  const chainLabel = chain.charAt(0).toUpperCase() + chain.slice(1);

  switch (stage) {
    case "authorize":
      return {
        title: "Approval was not completed",
        whatHappened:
          "Your wallet rejected the token approval or there was not enough gas to submit it. Your funds have not moved.",
        fundState: "Untouched — no tokens were approved or locked.",
        primaryAction: "Retry approval",
        secondaryAction: "Switch network",
      };
    case "submit":
      return {
        title: "Transfer signature was not completed",
        whatHappened:
          `The transfer signature was rejected or submitted on the wrong network. Your ${amountLabel} has not been locked.`,
        fundState: "Untouched — the bridge transfer was not submitted.",
        primaryAction: "Switch network & retry",
        secondaryAction: "Back to review",
      };
    case "locked":
      return {
        title: "Origin transaction did not confirm",
        whatHappened:
          `The transaction on ${chainLabel} was dropped or failed to confirm. Your ${amountLabel} is not locked on the origin chain.`,
        fundState: "Not locked yet — funds remain in your origin wallet.",
        primaryAction: "Resubmit transfer",
        secondaryAction: "Back to review",
      };
    case "attested":
      return {
        title: "Validators confirming — slower than expected",
        whatHappened:
          mode === "deposit"
            ? `Validators confirming (4/9) — slower than expected. Your ${amountLabel} is LOCKED on ${chainLabel} and NOT yet delivered to Morpheum. It is not lost, but stays pending until validators clear, or support resolves it via the message ID.`
            : `Validators confirming (4/9) — slower than expected. Your ${amountLabel} is LOCKED on Morpheum and NOT yet released on ${chainLabel}. It is not lost, but stays pending until validators clear.`,
        fundState: `Locked on ${mode === "deposit" ? chainLabel : "Morpheum"}, not yet delivered.`,
        primaryAction: "Keep polling",
        secondaryAction: "Get help (msg id)",
      };
    case "delivered":
      return {
        title: "Delivery delayed on destination",
        whatHappened:
          `Attestation completed but release on ${mode === "deposit" ? "Morpheum" : chainLabel} is taking longer than usual. Your transfer is attested and should complete automatically.`,
        fundState: "Locked and attested — awaiting final delivery.",
        primaryAction: "Keep polling",
        secondaryAction: "Get help (msg id)",
      };
    default:
      return {
        title: "Transfer needs attention",
        whatHappened: "Something unexpected interrupted this transfer.",
        fundState: "Check your wallet and transaction history.",
        primaryAction: "Retry",
        secondaryAction: "Get help",
      };
  }
}
