import type { CompareMatrixCell } from "./agentCompareMatrix";

export type CompareRankDirection = "higher" | "lower" | "none";

export const RANK_DIRECTION_BY_LABEL: Record<string, CompareRankDirection> = {
  "30d PnL": "higher",
  "All-time PnL": "higher",
  Sharpe: "higher",
  "Win rate": "higher",
  "Live %": "higher",
  Copying: "higher",
  "Market cap": "higher",
  "30d revenue": "higher",
  Price: "higher",
  "24H": "higher",
  "Volume 24H": "higher",
  "Open interest": "higher",
  "Managed AUM": "higher",
  FDV: "higher",
  "Mandate cap": "higher",
  "Revenue stability": "higher",
  Risk: "higher",
  "Risk tier": "higher",
  "Max DD": "lower",
  "Drawdown cap": "lower",
  "Token rank": "lower",
  Behavior: "none",
  Context: "none",
  Leverage: "none",
  "Ann. funding": "none",
  "Net exposure": "none",
  Policy: "none",
  Badges: "none",
  Compliance: "none",
};

const RISK_GRADE_SCORES: Record<string, number> = {
  "A+": 12,
  A: 11,
  "A-": 10,
  "B+": 9,
  B: 8,
  "B-": 7,
  "C+": 6,
  C: 5,
  "C-": 4,
  "D+": 3,
  D: 2,
  "D-": 1,
  F: 0,
};

function parseMoneyValue(raw: string): number | null {
  const normalized = raw.replace(/,/g, "").trim();
  const match = normalized.match(/([+-]?)\$?([\d.]+)\s*([kKmMbB])?/);
  if (!match) return null;
  const sign = match[1] === "-" ? -1 : 1;
  const amount = Number.parseFloat(match[2]!);
  if (!Number.isFinite(amount)) return null;
  const suffix = match[3]?.toUpperCase();
  const multiplier =
    suffix === "K" ? 1_000 : suffix === "M" ? 1_000_000 : suffix === "B" ? 1_000_000_000 : 1;
  return sign * amount * multiplier;
}

function parsePercentValue(raw: string): number | null {
  const normalized = raw.replace(/,/g, "").trim();
  const match = normalized.match(/([+-]?[\d.]+)\s*%/);
  if (!match) return null;
  const value = Number.parseFloat(match[1]!);
  return Number.isFinite(value) ? value : null;
}

function parseRiskGrade(raw: string): number | null {
  const gradeMatch = raw.trim().match(/\b(A\+|A-|B\+|B-|C\+|C-|D\+|D-|A|B|C|D|F)\b/);
  if (!gradeMatch) return null;
  return RISK_GRADE_SCORES[gradeMatch[1]!] ?? null;
}

function parseTokenRank(raw: string): number | null {
  const match = raw.trim().match(/#([\d,]+)/);
  if (!match) return null;
  const value = Number.parseInt(match[1]!.replace(/,/g, ""), 10);
  return Number.isFinite(value) ? value : null;
}

function parseScalarValue(raw: string): number | null {
  const normalized = raw.replace(/,/g, "").trim();
  const value = Number.parseFloat(normalized);
  return Number.isFinite(value) ? value : null;
}

export function resolveRankDirection(label: string): CompareRankDirection {
  return RANK_DIRECTION_BY_LABEL[label] ?? "none";
}

export function parseCompareMetricNumeric(
  label: string,
  value: string | null | undefined,
): number | null {
  if (value == null || value.trim() === "") return null;
  if (label === "Risk" || label === "Risk tier") {
    return parseRiskGrade(value);
  }
  if (label === "Token rank") {
    return parseTokenRank(value);
  }
  if (label === "Revenue stability") {
    return parseScalarValue(value);
  }
  if (label === "Sharpe" || label === "Copying") {
    return parseScalarValue(value);
  }
  if (label === "Max DD" || label === "Drawdown cap") {
    const percent = parsePercentValue(value);
    return percent == null ? null : Math.abs(percent);
  }
  if (value.includes("%")) {
    return parsePercentValue(value);
  }
  if (value.includes("$") || value.includes("k") || value.includes("K") || value.includes("M")) {
    return parseMoneyValue(value);
  }
  return parseScalarValue(value);
}

export function markBestCompareCells(
  label: string,
  cells: Array<CompareMatrixCell | null>,
): Array<CompareMatrixCell | null> {
  const direction = resolveRankDirection(label);
  if (direction === "none") return cells;

  const comparable: Array<{ index: number; value: number }> = [];
  for (let index = 0; index < cells.length; index += 1) {
    const cell = cells[index];
    if (!cell) continue;
    const numeric = parseCompareMetricNumeric(label, cell.value);
    if (numeric == null) continue;
    comparable.push({ index, value: numeric });
  }

  if (comparable.length < 2) return cells;

  const target =
    direction === "higher"
      ? Math.max(...comparable.map((entry) => entry.value))
      : Math.min(...comparable.map((entry) => entry.value));

  const winnerIndexes = new Set(
    comparable.filter((entry) => entry.value === target).map((entry) => entry.index),
  );

  return cells.map((cell, index) => {
    if (!cell || !winnerIndexes.has(index)) return cell;
    return { ...cell, isBest: true };
  });
}
