import { useCallback, useLayoutEffect, useState } from "react";

export const ANCHORED_OVERLAY_GAP_PX = 6;

export interface AnchoredOverlayPosition {
  top: number;
  right: number;
}

export interface UseAnchoredOverlayPositionOptions {
  isActive: boolean;
  anchorEl: HTMLElement | null | undefined;
  gapPx?: number;
}

export function useAnchoredOverlayPosition({
  isActive,
  anchorEl,
  gapPx = ANCHORED_OVERLAY_GAP_PX,
}: UseAnchoredOverlayPositionOptions): AnchoredOverlayPosition | null {
  const [position, setPosition] = useState<AnchoredOverlayPosition | null>(null);

  const updatePosition = useCallback(() => {
    if (!anchorEl) {
      setPosition(null);
      return;
    }

    const rect = anchorEl.getBoundingClientRect();
    setPosition({
      top: rect.bottom + gapPx,
      right: window.innerWidth - rect.right,
    });
  }, [anchorEl, gapPx]);

  useLayoutEffect(() => {
    if (!isActive || !anchorEl) {
      setPosition(null);
      return;
    }

    updatePosition();

    const onReposition = () => updatePosition();
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);

    return () => {
      window.removeEventListener("resize", onReposition);
      window.removeEventListener("scroll", onReposition, true);
    };
  }, [isActive, anchorEl, updatePosition]);

  return position;
}
