export const WELCOME_TOUR_STORAGE_KEY = "offline_welcome_seen";

export const WELCOME_MODAL_Z_INDEX = 10050;
/** Must stay above WELCOME_JOYRIDE_Z_INDEX so step-prep loading is not dimmed by Joyride overlay */
export const WELCOME_TOUR_LOADING_Z_INDEX = 10150;
export const WELCOME_JOYRIDE_Z_INDEX = 10100;

/** Breakpoints where the guided tour spotlight targets are visible */
export const DESKTOP_TOUR_BREAKPOINTS = ["lg", "md", "sm"] as const;

export function isDesktopTourBreakpoint(breakpoint: string): boolean {
  return (DESKTOP_TOUR_BREAKPOINTS as readonly string[]).includes(breakpoint);
}

export const WELCOME_STORY_RAIL_INTERVAL_MS = 8000;
export const WELCOME_STORY_RAIL_TRANSITION_MS = 400;

export const WELCOME_RAIL_DESKTOP_MIN_PX = 900;
export const WELCOME_RAIL_MOBILE_MAX_PX = 639;

export function isWelcomeRailDesktop(widthPx: number): boolean {
  return widthPx >= WELCOME_RAIL_DESKTOP_MIN_PX;
}

export function isWelcomeRailMobile(widthPx: number): boolean {
  return widthPx <= WELCOME_RAIL_MOBILE_MAX_PX;
}

