import React from "react";

interface QueryStateProps {
  isLoading: boolean;
  isError: boolean;
  error?: Error | null;
  label?: string;
  children: React.ReactNode;
}

export default function QueryState({
  isLoading,
  isError,
  error,
  label = "data",
  children,
}: QueryStateProps): React.JSX.Element {
  if (isLoading) {
    return <p className="nh-query-state">Loading {label}…</p>;
  }
  if (isError) {
    return (
      <p role="alert" className="nh-query-state nh-query-error">
        Couldn&apos;t load {label}: {error?.message ?? "unknown error"}
      </p>
    );
  }
  return <>{children}</>;
}
