import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  Joyride,
  type CallBackProps,
  type Step,
  type TooltipRenderProps,
  EVENTS,
  STATUS,
} from "react-joyride";
import { toast } from "sonner";

import { isDesktopTourBreakpoint } from "../welcome-tour/constants";
import { welcomeTourLocale, welcomeTourStyles } from "../welcome-tour/welcomeTourStyles";
import { useCopyTour } from "./CopyTourContext";
import { prepareCopyTourTarget } from "./copyTourDom";
import { isCopyTourGateSatisfied } from "./copyTourFlowSync";
import {
  buildCopyTourSteps,
  type CopyTourStepMeta,
} from "./copyTourSteps";
import { copyTourDefaultOptions } from "./copyTourStyles";
import "../welcome-tour/WelcomeModal.css";

interface CopyTourTooltipActions {
  advanceFromTooltip: (index: number, isLastStep: boolean) => void;
  isNextDisabled: (meta: CopyTourStepMeta | undefined) => boolean;
  waitHint: (meta: CopyTourStepMeta | undefined) => string | null;
}

const CopyTourTooltipActionsContext =
  createContext<CopyTourTooltipActions | null>(null);

const GATE_HINTS: Record<string, string> = {
  confirmComplete: "Wait for copy setup to finish…",
  stripVisible: "Opening portfolio…",
  mirrorProfit: "Waiting for mirror profit…",
  pnlVisible: "Opening your mirror status…",
};

function CopyTourTooltip({
  continuous,
  index,
  isLastStep,
  skipProps,
  step,
  tooltipProps,
  size,
}: TooltipRenderProps): JSX.Element {
  const actions = useContext(CopyTourTooltipActionsContext);
  const meta = step.data as CopyTourStepMeta | undefined;
  const stepNumber = meta?.stepNumber ?? index + 1;
  const requiresClick = meta?.requiresClick ?? false;
  const nextDisabled = actions?.isNextDisabled(meta) ?? false;
  const waitHint = actions?.waitHint(meta);

  return (
    <div {...tooltipProps} className="welcome-tour-tooltip">
      <div className="welcome-tour-tooltip-header">
        <span className="welcome-tour-step-badge">
          {stepNumber} / {size}
        </span>
        {step.title ? (
          <h4 className="welcome-tour-tooltip-title">{step.title}</h4>
        ) : null}
      </div>
      <div className="welcome-tour-tooltip-body">{step.content}</div>
      <div className="welcome-tour-tooltip-footer">
        <button type="button" className="welcome-tour-skip" {...skipProps}>
          {skipProps.title}
        </button>
        {!requiresClick && continuous ? (
          <div className="welcome-tour-tooltip-nav">
            {nextDisabled && waitHint ? (
              <p
                className="welcome-tour-wait-hint"
                style={{
                  margin: 0,
                  fontSize: "0.75rem",
                  color: "var(--terminal-text-muted)",
                }}
              >
                {waitHint}
              </p>
            ) : null}
            <button
              type="button"
              className="welcome-tour-next"
              disabled={nextDisabled}
              aria-disabled={nextDisabled}
              onClick={() => actions?.advanceFromTooltip(index, isLastStep)}
            >
              {isLastStep ? "Finish" : "Next"}
            </button>
          </div>
        ) : requiresClick ? (
          <p
            className="welcome-tour-click-hint"
            style={{
              margin: 0,
              fontSize: "0.75rem",
              color: "var(--terminal-text-muted)",
            }}
          >
            Click the highlighted control to continue
          </p>
        ) : null}
      </div>
    </div>
  );
}

export function CopyTourJoyride(): JSX.Element {
  const {
    runTour,
    stepIndex,
    setStepIndex,
    currentBreakpoint,
    gateState,
    stopTour,
    onTourComplete,
  } = useCopyTour();

  const isDesktop = isDesktopTourBreakpoint(currentBreakpoint);
  const shouldRun = runTour && isDesktop;
  const [tourSession, setTourSession] = useState(0);
  const [gateForced, setGateForced] = useState<Record<string, boolean>>({});
  const prevRunRef = useRef(false);
  const stepIndexRef = useRef(stepIndex);
  const setStepIndexRef = useRef(setStepIndex);
  const onTourCompleteRef = useRef(onTourComplete);
  stepIndexRef.current = stepIndex;
  setStepIndexRef.current = setStepIndex;
  onTourCompleteRef.current = onTourComplete;

  const steps = useMemo(() => buildCopyTourSteps(), []);
  const stepCount = steps.length;

  const scheduleStepIndex = useCallback((index: number) => {
    window.setTimeout(() => {
      setStepIndexRef.current(index);
      stepIndexRef.current = index;
    }, 120);
  }, []);

  const isNextDisabled = useCallback(
    (meta: CopyTourStepMeta | undefined) => {
      if (!meta?.gateKind || meta.gateKind === "none") return false;
      if (gateForced[meta.stepId]) return false;
      return !isCopyTourGateSatisfied(meta.gateKind, gateState);
    },
    [gateForced, gateState],
  );

  const waitHint = useCallback(
    (meta: CopyTourStepMeta | undefined) => {
      if (!meta?.gateKind || meta.gateKind === "none") return null;
      return GATE_HINTS[meta.gateKind] ?? "Please wait…";
    },
    [],
  );

  const advanceFromTooltip = useCallback(
    (index: number, isLastStep: boolean) => {
      const meta = steps[index]?.data as CopyTourStepMeta | undefined;
      if (isNextDisabled(meta)) return;
      if (isLastStep) {
        onTourCompleteRef.current();
        return;
      }
      scheduleStepIndex(index + 1);
    },
    [isNextDisabled, scheduleStepIndex, steps],
  );

  const tooltipActions = useMemo(
    (): CopyTourTooltipActions => ({
      advanceFromTooltip,
      isNextDisabled,
      waitHint,
    }),
    [advanceFromTooltip, isNextDisabled, waitHint],
  );

  useEffect(() => {
    if (shouldRun && !prevRunRef.current) {
      setTourSession((value) => value + 1);
      setGateForced({});
    }
    prevRunRef.current = shouldRun;
  }, [shouldRun]);

  useEffect(() => {
    if (shouldRun) {
      document.body.setAttribute("data-copy-tour-active", "true");
    } else {
      document.body.removeAttribute("data-copy-tour-active");
    }
    return () => {
      document.body.removeAttribute("data-copy-tour-active");
    };
  }, [shouldRun]);

  useEffect(() => {
    if (runTour && !isDesktop) {
      stopTour();
      toast.info(
        "Copy tour is available on desktop and tablet view. Widen your window to explore step-by-step.",
      );
    }
  }, [runTour, isDesktop, stopTour]);

  useEffect(() => {
    if (!shouldRun) return;
    const meta = steps[stepIndex]?.data as CopyTourStepMeta | undefined;
    if (!meta?.gateKind || meta.gateKind === "none" || !meta.gateMaxMs) return;
    if (gateForced[meta.stepId]) return;
    if (isCopyTourGateSatisfied(meta.gateKind, gateState)) return;

    const timer = window.setTimeout(() => {
      setGateForced((prev) => ({ ...prev, [meta.stepId]: true }));
    }, meta.gateMaxMs);

    return () => window.clearTimeout(timer);
  }, [shouldRun, stepIndex, gateState, gateForced, steps]);

  const stepsWithBefore = useMemo((): Step[] => {
    return steps.map((step) => {
      const meta = step.data as CopyTourStepMeta | undefined;
      const targetSelector = meta?.targetSelector;
      if (!targetSelector || targetSelector === "body") return step;

      return {
        ...step,
        before: async () => {
          await prepareCopyTourTarget(targetSelector, 800);
        },
      };
    });
  }, [steps]);

  useEffect(() => {
    if (!shouldRun || steps.length === 0) return;
    const meta = steps[stepIndex]?.data as CopyTourStepMeta | undefined;
    if (!meta?.requiresClick || !meta.targetSelector) return;
    if (meta.targetSelector === "body") return;

    const el = document.querySelector(meta.targetSelector);
    if (!el) return;

    const capturedIndex = stepIndex;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const onClick = () => {
      timer = window.setTimeout(() => {
        if (stepIndexRef.current !== capturedIndex) return;
        if (capturedIndex >= stepCount - 1) return;
        scheduleStepIndex(capturedIndex + 1);
      }, 120);
    };

    el.addEventListener("click", onClick, true);
    return () => {
      el.removeEventListener("click", onClick, true);
      if (timer !== undefined) {
        window.clearTimeout(timer);
      }
    };
  }, [shouldRun, stepIndex, steps, stepCount, scheduleStepIndex]);

  const handleCallback = useCallback(
    (data: CallBackProps) => {
      const { status, type, index } = data;

      if (status === STATUS.SKIPPED) {
        stopTour();
        onTourComplete();
        return;
      }

      if (type === EVENTS.TARGET_NOT_FOUND) {
        toast.error("Copy tour step target not found", {
          description: "Navigate to the agent or portfolio view, or skip the tour.",
        });
        if (index > 0) {
          scheduleStepIndex(index - 1);
        } else {
          stopTour();
        }
        return;
      }

      if (type === EVENTS.TOUR_END && status === STATUS.FINISHED) {
        onTourComplete();
      }
    },
    [stopTour, onTourComplete, scheduleStepIndex],
  );

  return (
    <CopyTourTooltipActionsContext.Provider value={tooltipActions}>
      <Joyride
        key={tourSession}
        steps={stepsWithBefore}
        run={shouldRun}
        stepIndex={stepIndex}
        continuous
        scrollToFirstStep={false}
        disableScrolling
        disableOverlayClose
        callback={handleCallback}
        locale={welcomeTourLocale}
        options={copyTourDefaultOptions}
        styles={welcomeTourStyles}
        loaderComponent={null}
        tooltipComponent={(props) => (
          <CopyTourTooltip {...props} size={stepCount} />
        )}
      />
    </CopyTourTooltipActionsContext.Provider>
  );
}
