import React, { useMemo } from "react";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { sortGuardrailIntents } from "./deckIntents";
import {
  getGuardedHeroVariant,
  shouldGuardedHeroCollapse,
} from "./safetyAuditLogLayout";

export interface GuardedModeHeroProps {
  layoutBreakpoint?: string;
  expanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** @deprecated Use layoutBreakpoint */
  isMobile?: boolean;
}

function GuardedModeHero({
  layoutBreakpoint = "lg",
  expanded = false,
  onExpandedChange,
}: GuardedModeHeroProps): JSX.Element {
  const { tasks } = useAgentTasks();

  const variant = useMemo(
    () => getGuardedHeroVariant(layoutBreakpoint),
    [layoutBreakpoint],
  );

  const collapsible = useMemo(
    () => shouldGuardedHeroCollapse(layoutBreakpoint),
    [layoutBreakpoint],
  );

  const { humanPct, autoPct, awaitingCount } = useMemo(() => {
    const pending = sortGuardrailIntents(tasks);
    const awaiting = pending.length;
    const reviewed = tasks.filter(
      (t) =>
        t.status === "executing" ||
        t.status === "completed" ||
        t.status === "rejected",
    ).length;
    const total = reviewed + awaiting;
    if (total === 0) {
      return { humanPct: 51, autoPct: 49, awaitingCount: awaiting };
    }
    const human = Math.round((reviewed / total) * 100);
    return { humanPct: human, autoPct: 100 - human, awaitingCount: awaiting };
  }, [tasks]);

  const showExpanded = !collapsible || expanded;

  const combinedLabel =
    variant === "md" ? `${humanPct}% reviewed` : null;

  const pendingLabel = `${awaitingCount} pending`;

  const rootClass = [
    "trade-safety-header-guarded-hero",
    `trade-safety-header-guarded-hero--${variant}`,
    collapsible ? "trade-safety-header-guarded-hero--collapsible" : "",
    showExpanded ? "trade-safety-header-guarded-hero--expanded" : "",
    collapsible && !showExpanded
      ? "trade-safety-header-guarded-hero--collapsed"
      : "",
  ]
    .filter(Boolean)
    .join(" ");

  if (collapsible && !showExpanded) {
    return (
      <button
        type="button"
        className={`${rootClass} trade-safety-header-guarded-hero-toggle`}
        aria-expanded={false}
        aria-label={`Guarded mode, ${pendingLabel}. Tap to expand review ratio.`}
        onClick={() => onExpandedChange?.(true)}
      >
        <span className="trade-safety-header-guarded-badge">Guarded</span>
        <span className="trade-safety-header-guarded-pending-count">
          · {pendingLabel}
        </span>
        <ExpandCollapseIcon
          expanded={false}
          className="trade-safety-header-guarded-chevron"
          size={12}
        />
      </button>
    );
  }

  return (
    <div className={rootClass}>
      {collapsible ? (
        <button
          type="button"
          className="trade-safety-header-guarded-hero-toggle trade-safety-header-guarded-hero-toggle--expanded"
          aria-expanded={true}
          aria-label={`Guarded mode, ${pendingLabel}. Tap to collapse.`}
          onClick={() => onExpandedChange?.(false)}
        >
          <span className="trade-safety-header-guarded-badge">Guarded</span>
          <span className="trade-safety-header-guarded-pending-count">
            · {pendingLabel}
          </span>
          <ExpandCollapseIcon
            expanded
            className="trade-safety-header-guarded-chevron"
            size={12}
          />
        </button>
      ) : null}
      <div className="trade-safety-header-guarded-hero-main">
        {!collapsible ? (
          <span className="trade-safety-header-guarded-badge">Guarded</span>
        ) : null}
        {variant === "sm" ? (
          <div
            className="trade-safety-header-guarded-bar trade-safety-header-guarded-bar--inline"
            role="img"
            aria-label={`Human reviewed ${humanPct}%, awaiting ${autoPct}%`}
          >
            <div
              className="trade-safety-header-guarded-bar-segment trade-safety-header-guarded-bar-segment--human"
              style={{ width: `${humanPct}%` }}
            />
            <div
              className="trade-safety-header-guarded-bar-segment trade-safety-header-guarded-bar-segment--auto"
              style={{ width: `${autoPct}%` }}
            />
          </div>
        ) : null}
      </div>
      {variant !== "sm" ? (
        <div
          className="trade-safety-header-guarded-bar"
          role="img"
          aria-label={`Human reviewed ${humanPct}%, awaiting ${autoPct}%`}
        >
          <div
            className="trade-safety-header-guarded-bar-segment trade-safety-header-guarded-bar-segment--human"
            style={{ width: `${humanPct}%` }}
          />
          <div
            className="trade-safety-header-guarded-bar-segment trade-safety-header-guarded-bar-segment--auto"
            style={{ width: `${autoPct}%` }}
          />
        </div>
      ) : null}
      {variant === "lg" ? (
        <div className="trade-safety-header-guarded-labels">
          <span>Human {humanPct}%</span>
          <span>Awaiting {autoPct}%</span>
        </div>
      ) : null}
      {combinedLabel ? (
        <div className="trade-safety-header-guarded-labels trade-safety-header-guarded-labels--single">
          <span>{combinedLabel}</span>
        </div>
      ) : null}
      {collapsible && variant !== "lg" && variant !== "md" ? (
        <div className="trade-safety-header-guarded-labels trade-safety-header-guarded-labels--single">
          <span>
            Human {humanPct}% · Awaiting {autoPct}%
          </span>
        </div>
      ) : null}
    </div>
  );
}

export default React.memo(GuardedModeHero);
