import { useMemo } from "react";

import {
  buildFleetCharts,
  getAgentProfileById,
  getAgentTokenProfile,
  getFleetAgentByCatalogId,
} from "../../offline/mock_data";
import type { AgentKpiHistoryFile } from "../../offline/mock_data/agentKpiHistory.types";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import type { AgentTokenProfile } from "../../offline/mock_data/agentTokenProfile";
import type { PropertyCharts } from "../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../offline/mock_data/fleetCatalog";
import { buildAgentMetricsForFocus } from "../components/agent/agentFocusMetrics";
import {
  DEFAULT_AGENT_HERO_FOCUS,
  hasAgentToken,
  VALID_AGENT_HERO_FOCUSES,
  type AgentHeroFocus,
} from "../components/agent/agentHeroFocus";

export interface AgentPageMetric {
  label: string;
  value: string;
  tone?: "positive" | "negative" | "neutral";
}

export type AgentMetricsByFocus = Record<AgentHeroFocus, AgentPageMetric[]>;

export interface UseAgentPageDataResult {
  profile: NonNullable<ReturnType<typeof getAgentProfileById>>;
  fleet: FleetAgentRecord;
  charts: PropertyCharts;
  metrics: AgentPageMetric[];
  metricsByFocus: AgentMetricsByFocus;
  fleetTradeCount: number;
  hasAgentToken: boolean;
  tokenProfile: AgentTokenProfile | undefined;
}

function buildMetricsByFocus(
  profile: NonNullable<ReturnType<typeof getAgentProfileById>>,
  fleet: FleetAgentRecord,
): AgentMetricsByFocus {
  const metricsByFocus = {} as AgentMetricsByFocus;
  for (const focus of VALID_AGENT_HERO_FOCUSES) {
    metricsByFocus[focus] = buildAgentMetricsForFocus(focus, profile, fleet);
  }
  return metricsByFocus;
}

export function useAgentPageData(
  agentId: string,
  trades: FleetTradeEvent[],
  heroFocus: AgentHeroFocus = DEFAULT_AGENT_HERO_FOCUS,
  kpiHistory?: AgentKpiHistoryFile | null,
): UseAgentPageDataResult | null {
  return useMemo(() => {
    const profile = getAgentProfileById(agentId);
    const fleet = getFleetAgentByCatalogId(agentId);
    if (!profile || !fleet) return null;

    const charts = buildFleetCharts(trades, agentId, kpiHistory);
    const metricsByFocus = buildMetricsByFocus(profile, fleet);
    const agentHasToken = hasAgentToken(fleet);
    const tokenProfile = agentHasToken
      ? getAgentTokenProfile(agentId)
      : undefined;

    return {
      profile,
      fleet,
      charts,
      metrics: metricsByFocus[heroFocus],
      metricsByFocus,
      fleetTradeCount: trades.length,
      hasAgentToken: agentHasToken,
      tokenProfile,
    };
  }, [agentId, heroFocus, trades, kpiHistory]);
}
