import type { IChartApiBase, ISeriesApi, Time } from "lightweight-charts";
import type { RefObject } from "react";

export interface SeriesPrimitiveInvalidationHandle {
  unsubscribe: () => void;
  flush: () => void;
}

export function subscribeSeriesPrimitiveInvalidation(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  invalidate: () => void,
  requestUpdate: () => void,
  isPanningRef?: RefObject<boolean>,
): SeriesPrimitiveInvalidationHandle {
  let dirtyWhilePanning = false;

  const runUpdate = () => {
    invalidate();
    requestUpdate();
  };

  const notify = () => {
    if (isPanningRef?.current) {
      dirtyWhilePanning = true;
      return;
    }
    runUpdate();
  };

  const flush = () => {
    if (!dirtyWhilePanning) return;
    dirtyWhilePanning = false;
    runUpdate();
  };

  const onDataChanged = () => notify();
  series.subscribeDataChanged(onDataChanged);

  const onVisibleRangeChange = () => notify();
  chart.timeScale().subscribeVisibleLogicalRangeChange(onVisibleRangeChange);

  const onTimeScaleSizeChange = () => notify();
  chart.timeScale().subscribeSizeChange(onTimeScaleSizeChange);

  return {
    unsubscribe: () => {
      series.unsubscribeDataChanged(onDataChanged);
      chart.timeScale().unsubscribeVisibleLogicalRangeChange(onVisibleRangeChange);
      chart.timeScale().unsubscribeSizeChange(onTimeScaleSizeChange);
    },
    flush,
  };
}
