import React, { useMemo } from "react";

import {
  useCompareAgentsData,
  type CompareAgentsData,
} from "../../hooks/useCompareAgentsData";
import { resolveActiveSection } from "../../utils/agentCompareMatrix";
import {
  resolveCompareChartVisible,
  type AgentCompareFocus,
} from "./agentCompareFocus";
import AgentCompareMatrixActions from "./AgentCompareMatrixActions";
import AgentCompareMatrixChart from "./AgentCompareMatrixChart";
import AgentCompareMatrixHeader from "./AgentCompareMatrixHeader";
import AgentCompareMatrixTable from "./AgentCompareMatrixTable";
import AgentCompareMatrixTableLoading from "./AgentCompareMatrixTableLoading";
import "./agent.css";

export interface AgentCompareBodyProps {
  compareIds: string[];
  compareFocus: AgentCompareFocus;
  height?: string;
  showAddSlot: boolean;
  highlightBest?: boolean;
  compareData?: CompareAgentsData;
  onRequestAddAgent: () => void;
  onRemoveAgent: (agentId: string) => void;
  matrixHeaderRef?: React.RefObject<HTMLDivElement | null>;
}

function AgentCompareBody({
  compareIds,
  compareFocus,
  height = "100%",
  showAddSlot,
  highlightBest = true,
  compareData: preloadedCompareData,
  onRequestAddAgent,
  onRemoveAgent,
  matrixHeaderRef,
}: AgentCompareBodyProps): JSX.Element {
  const fetchedCompareData = useCompareAgentsData(compareIds);
  const compareData = preloadedCompareData ?? fetchedCompareData;
  const { agents, columnCount, sections, tradesByAgentId, kpiByAgentId, loading, error } =
    compareData;
  const activeSection = useMemo(
    () => resolveActiveSection(sections, compareFocus),
    [sections, compareFocus],
  );
  const showChart = resolveCompareChartVisible(compareFocus);

  if (!loading && agents.length === 0) {
    return (
      <div className="agent-slot agent-compare-body" style={{ height }}>
        <p className="agent-compare-empty">No agents to compare.</p>
      </div>
    );
  }

  const bodyClassName = [
    "agent-slot",
    "agent-compare-body",
    showAddSlot ? "agent-compare-body--with-add-slot" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const chartTradeProps = preloadedCompareData
    ? { tradesByAgentId, kpiByAgentId, loading, error }
    : { loading, error, tradesByAgentId, kpiByAgentId };

  return (
    <div className={bodyClassName} style={{ height }}>
      <div className="agent-compare-matrix-sync-scroll">
        <AgentCompareMatrixHeader
          ref={matrixHeaderRef}
          agents={agents}
          columnCount={columnCount}
          showAddSlot={showAddSlot}
          onRequestAddAgent={onRequestAddAgent}
          onRemoveAgent={onRemoveAgent}
        />

        {showChart ? (
          <AgentCompareMatrixChart
            compareIds={compareIds}
            compareFocus={compareFocus}
            {...chartTradeProps}
          />
        ) : null}

        {loading ? (
          <AgentCompareMatrixTableLoading
            compareFocus={compareFocus}
            columnCount={columnCount}
            showAddSlot={showAddSlot}
          />
        ) : activeSection ? (
          <AgentCompareMatrixTable
            section={activeSection}
            columnCount={columnCount}
            showAddSlot={showAddSlot}
            highlightBest={highlightBest}
          />
        ) : null}

        {!loading ? (
          <AgentCompareMatrixActions
            agents={agents}
            columnCount={columnCount}
            compareFocus={compareFocus}
            showAddSlot={showAddSlot}
          />
        ) : null}
      </div>
    </div>
  );
}

export default AgentCompareBody;
