function startOfDayMs(ms: number): number {
  const d = new Date(ms);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

export function buildMockDailyPnlByDay(
  year: number,
  month: number,
  referenceDate = new Date(),
): DailyPnlDay[] {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const todayStart = startOfDayMs(referenceDate.getTime());
  const result: DailyPnlDay[] = [];

  for (let day = 1; day <= daysInMonth; day++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const dayStart = startOfDayMs(new Date(year, month, day).getTime());
    const mockPnl = MOCK_DAILY_PNL_BY_DAY[day];

    if (dayStart > todayStart || mockPnl === undefined) {
      result.push({ dateKey, dayOfMonth: day, pnl: null, isEmpty: true });
    } else {
      result.push({ dateKey, dayOfMonth: day, pnl: mockPnl, isEmpty: false });
    }
  }

  return result;
}

export function getMockDailyPnlData(referenceDate = new Date()) {
  const year = referenceDate.getFullYear();
  const month = referenceDate.getMonth();
  return {
    summary: MOCK_DAILY_PNL_SUMMARY,
    days: buildMockDailyPnlByDay(year, month, referenceDate),
  };
}
