import { type CSSProperties, type JSX } from "react";

import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { formatNumber, formatPrice } from "../../sdk/utils/display";
import { MARKER_BUBBLE_BODY_GAP_PX, MARKER_BUBBLE_TIP_GAP_PX } from "./markerBubbleLayout";
import type { TokenTakerChartMarkerMeta } from "./tokenTakerChartMarkers";
import { useMarkerBubbleLayout } from "./useMarkerBubbleLayout";

export interface TokenTakerMarkerBubbleProps {
  meta: TokenTakerChartMarkerMeta;
  x: number;
  y: number;
  containerWidth: number;
  containerHeight: number;
}

function TokenTakerMarkerBubble({
  meta,
  x,
  y,
  containerWidth,
  containerHeight,
}: TokenTakerMarkerBubbleProps): JSX.Element {
  const pnlColor =
    meta.closedPnl == null
      ? undefined
      : meta.closedPnl > 0
        ? TERMINAL_COLORS.long
        : meta.closedPnl < 0
          ? TERMINAL_COLORS.short
          : undefined;

  const { bubbleRef, layout } = useMarkerBubbleLayout(
    x,
    y,
    containerWidth,
    containerHeight,
    [meta.action, meta.amountUsd, meta.closedPnl],
  );

  return (
    <div
      ref={bubbleRef}
      className={`execution-marker-bubble fleet-marker-bubble execution-marker-bubble--${layout.side}`}
      style={
        {
          left: layout.left,
          top: layout.top,
          "--marker-bubble-body-gap": `${MARKER_BUBBLE_BODY_GAP_PX}px`,
          "--marker-bubble-tip-gap": `${MARKER_BUBBLE_TIP_GAP_PX}px`,
          "--marker-bubble-arrow-offset-y": `${layout.arrowOffsetY}px`,
        } as CSSProperties
      }
      role="tooltip"
    >
      <div className="fleet-marker-bubble__header">
        <span
          className="agent-hero-avatar fleet-marker-bubble__avatar"
          aria-hidden
        >
          <span
            className="agent-hero-avatar-image fleet-marker-bubble__avatar-image"
            style={{
              WebkitMaskImage: `url(${meta.avatarSvgUrl})`,
              maskImage: `url(${meta.avatarSvgUrl})`,
            }}
          />
        </span>
        <div className="fleet-marker-bubble__title-block">
          <span className="execution-marker-bubble__direction">{meta.takerAgentName}</span>
          <span className="fleet-marker-bubble__action">{meta.action}</span>
        </div>
        <span className="execution-marker-bubble__badge execution-marker-bubble__badge--agent">
          Taker
        </span>
      </div>
      <div className="execution-marker-bubble__body">
        {meta.coin} · ${meta.amountUsd.toFixed(0)} · {formatPrice(meta.price)}
      </div>
      {meta.closedPnl != null ? (
        <div className="execution-marker-bubble__footer" style={{ color: pnlColor }}>
          Closed PnL {formatNumber(meta.closedPnl)}
        </div>
      ) : null}
      <span className="execution-marker-bubble__arrow" aria-hidden />
    </div>
  );
}

export default TokenTakerMarkerBubble;
