import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import {
  DEFAULT_AGENT_HERO_FOCUS,
  extractRiskLabel,
  type AgentHeroFocus,
} from "./agentHeroFocus";

export interface AgentFocusMetric {
  label: string;
  value: string;
  tone?: "positive" | "negative" | "neutral";
}

function findStat(
  profile: PropertyProfile,
  label: string,
): AgentFocusMetric | null {
  const stat = profile.stats.find((entry) => entry.label === label);
  if (!stat) return null;
  return {
    label: stat.label,
    value: stat.value,
    tone: stat.tone,
  };
}

function findQuickStat(
  profile: PropertyProfile,
  label: string,
): AgentFocusMetric | null {
  const stat = profile.quickStats.find((entry) => entry.label === label);
  if (!stat) return null;
  return {
    label: stat.label,
    value: stat.value,
    tone: "neutral",
  };
}

export function extractTimeLivePct(profile: PropertyProfile): string | null {
  const input = profile.riskInputs.find((entry) =>
    entry.toLowerCase().startsWith("time-live:"),
  );
  if (!input) return null;
  const match = input.match(/(\d+(?:\.\d+)?)\s*%/);
  return match ? `${match[1]}%` : null;
}

export function buildPriceMetric(profile: PropertyProfile): AgentFocusMetric {
  return {
    label: "Price",
    value: `$${profile.price.toFixed(2)}`,
  };
}

export function buildChange24hMetric(profile: PropertyProfile): AgentFocusMetric {
  return {
    label: "24H",
    value: `${profile.change24h >= 0 ? "+" : ""}${profile.change24h.toFixed(1)}%`,
    tone: profile.change24h >= 0 ? "positive" : "negative",
  };
}

function buildWinRateMetric(fleet: FleetAgentRecord): AgentFocusMetric {
  return {
    label: "Win rate",
    value: `${fleet.winRatePct}%`,
    tone: "neutral",
  };
}

function buildCopyingMetric(fleet: FleetAgentRecord): AgentFocusMetric {
  return {
    label: "Copying",
    value: fleet.copyCount.toLocaleString(),
    tone: "neutral",
  };
}

function buildRiskMetric(profile: PropertyProfile): AgentFocusMetric {
  const quickRisk = findQuickStat(profile, "Risk");
  if (quickRisk) return { ...quickRisk, label: "Risk" };
  return {
    label: "Risk",
    value: extractRiskLabel(profile.riskScore),
    tone: "neutral",
  };
}

function buildLivePctMetric(profile: PropertyProfile): AgentFocusMetric | null {
  const livePct = extractTimeLivePct(profile);
  if (!livePct) return null;
  return {
    label: "Live %",
    value: livePct,
    tone: "neutral",
  };
}

function buildVolume24hMetric(profile: PropertyProfile): AgentFocusMetric {
  return {
    label: "Volume 24H",
    value: profile.volume24h,
    tone: "neutral",
  };
}

function compactMetrics(metrics: Array<AgentFocusMetric | null>): AgentFocusMetric[] {
  return metrics.filter((metric): metric is AgentFocusMetric => metric !== null);
}

export function buildAgentMetricsForFocus(
  focus: AgentHeroFocus,
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentFocusMetric[] {
  switch (focus) {
    case "copy":
      return compactMetrics([
        buildPriceMetric(profile),
        buildChange24hMetric(profile),
        findStat(profile, "30d PnL"),
        findStat(profile, "Sharpe"),
        findStat(profile, "Max DD"),
        findStat(profile, "All-time PnL"),
      ]);
    case "trust":
      return compactMetrics([
        buildRiskMetric(profile),
        findStat(profile, "Max DD"),
        findStat(profile, "Sharpe"),
        findStat(profile, "30d PnL"),
        buildWinRateMetric(fleet),
        buildLivePctMetric(profile),
      ]);
    case "scale":
      return compactMetrics([
        buildPriceMetric(profile),
        findQuickStat(profile, "Market cap"),
        findQuickStat(profile, "30d revenue"),
        findStat(profile, "30d PnL"),
        findStat(profile, "Net exposure"),
        buildCopyingMetric(fleet),
      ]);
    case "brand":
      return compactMetrics([
        buildPriceMetric(profile),
        buildChange24hMetric(profile),
        findQuickStat(profile, "Market cap"),
        buildVolume24hMetric(profile),
        findStat(profile, "30d PnL"),
      ]);
    case "playbook":
      return compactMetrics([
        findStat(profile, "30d PnL"),
        findStat(profile, "Sharpe"),
        findStat(profile, "Max DD"),
        buildWinRateMetric(fleet),
        findStat(profile, "Net exposure"),
        findStat(profile, "All-time PnL"),
      ]);
    default:
      return buildAgentMetricsForFocus(
        DEFAULT_AGENT_HERO_FOCUS,
        profile,
        fleet,
      );
  }
}

/** Four KPI rows for agent compare columns (ranking-oriented). */
export function buildCompareKpiMetrics(
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
): AgentFocusMetric[] {
  return compactMetrics([
    findStat(profile, "30d PnL"),
    findStat(profile, "Sharpe"),
    findStat(profile, "Max DD"),
    buildWinRateMetric(fleet),
  ]);
}

/** Return KPIs shown below the equity chart in compare Performance focus. */
export function buildComparePerformanceMetrics(
  profile: PropertyProfile,
): AgentFocusMetric[] {
  return compactMetrics([
    findStat(profile, "30d PnL"),
    findStat(profile, "Sharpe"),
    findStat(profile, "All-time PnL"),
  ]);
}
