import { getIndexListMetricsBySlug } from "../../offline/mock_data/indexListMetrics";
import type { IndexCatalogEntry } from "../../offline/mock_data/maexIndexCatalog";
import type { PropertyIndexRow } from "../../offline/mock_data/types";
import type { CompactMetricDefinition } from "../components/metrics/types";
import { formatPercent } from "../components/index/indexFormat";
import { formatLargeNumber } from "../sdk/utils/display";
import {
  buildSignedPercentLineData,
  buildSparklineLineData,
} from "./compactMetricChartData";

const CHANGE24H_POINTS = 24;

function hashSlug(slug: string): number {
  let hash = 0;
  for (let index = 0; index < slug.length; index += 1) {
    hash = (hash * 31 + slug.charCodeAt(index)) >>> 0;
  }
  return hash;
}

function buildFallbackMetrics(
  entry: IndexCatalogEntry,
): {
  marketCap: number;
  marketCapChange24h: number;
  turnover: number;
  turnoverChange24h: number;
  totalMentions: number;
  totalMentionsChange24h: number;
} {
  const seed = hashSlug(entry.baseAsset);
  const marketCap = entry.openInterest * (1.05 + (seed % 17) / 100);
  const turnover = entry.volume24h;
  const totalMentions = 120 + (seed % 140);

  return {
    marketCap,
    marketCapChange24h: Number((((seed % 200) - 100) / 100).toFixed(2)),
    turnover,
    turnoverChange24h: Number((((seed % 400) - 200) / 10).toFixed(2)),
    totalMentions,
    totalMentionsChange24h: Number((((seed % 300) - 150) / 3).toFixed(2)),
  };
}

function formatUsdCompact(value: number): string {
  if (value >= 1_000_000_000) {
    return `$${(value / 1_000_000_000).toFixed(2)}B`;
  }
  if (value >= 1_000_000) {
    return `$${formatLargeNumber(value)}`;
  }
  if (value >= 1_000) {
    return `$${formatLargeNumber(value)}`;
  }
  return `$${value.toFixed(2)}`;
}

export function buildIndexListMetricDefinitions(
  entry: IndexCatalogEntry,
  row?: PropertyIndexRow,
): CompactMetricDefinition[] {
  const snapshot =
    getIndexListMetricsBySlug(entry.baseAsset) ?? buildFallbackMetrics(entry);
  const sparkline = row?.sparkline ?? [0, entry.change24h];

  const marketCapLineData = buildSparklineLineData(
    sparkline,
    snapshot.marketCap,
  );
  const turnoverLineData = buildSparklineLineData(
    sparkline,
    snapshot.turnover,
  );
  const change24hSeries = buildSignedPercentLineData(
    sparkline,
    entry.change24h,
    CHANGE24H_POINTS,
  );

  return [
    {
      id: "marketCap",
      label: "Market cap",
      value: formatUsdCompact(snapshot.marketCap),
      changePercent: snapshot.marketCapChange24h,
      chart: {
        kind: "line",
        data: marketCapLineData,
        formatValue: formatUsdCompact,
      },
    },
    {
      id: "turnover",
      label: "Turnover",
      value: formatUsdCompact(snapshot.turnover),
      changePercent: snapshot.turnoverChange24h,
      chart: {
        kind: "line",
        data: turnoverLineData,
        formatValue: formatUsdCompact,
      },
    },
    {
      id: "change24h",
      label: "24h change",
      value: formatPercent(entry.change24h),
      valueTone: "signed",
      chart: {
        kind: "line",
        data: change24hSeries,
      },
    },
    {
      id: "totalMentions",
      label: "Total mentions",
      value: String(snapshot.totalMentions),
      changePercent: snapshot.totalMentionsChange24h,
      chart: { kind: "none" },
    },
  ];
}
