import React, { useEffect, useState, type ReactNode } from "react";
import type { AgentTask } from "../../store/types";
import { shortHashId } from "../../utils/hashId";
import { Typewriter } from "../ui/Typewriter";
import type { FeedEnterState } from "../tradeops/feedAnimation";

export interface TradeAgentIntentCardProps {
  task: AgentTask;
  enterState: FeedEnterState | null;
  exitingId: string | null;
  setFlipRef: (id: string) => (el: HTMLElement | null) => void;
  onExitAnimationEnd: (taskId: string) => void;
  onContextSelect?: () => void;
  isContextActive?: boolean;
  headerLeading?: ReactNode;
  isGateTimeoutComplete?: boolean;
  children?: ReactNode;
}

export function TradeAgentIntentCard({
  task,
  enterState,
  exitingId,
  setFlipRef,
  onExitAnimationEnd,
  onContextSelect,
  isContextActive = false,
  headerLeading,
  isGateTimeoutComplete = false,
  children,
}: TradeAgentIntentCardProps): JSX.Element {
  const isPushing =
    enterState?.instanceId === task.id && enterState.phase === "push";
  const isRevealing =
    enterState?.instanceId === task.id && enterState.phase === "reveal";
  const isEntering = enterState?.instanceId === task.id;
  const isExiting = exitingId === task.id;

  const [animateText, setAnimateText] = useState(false);

  useEffect(() => {
    if (isEntering) {
      setAnimateText(true);
    }
  }, [isEntering]);

  const handleContextKeyDown = (e: React.KeyboardEvent) => {
    if (!onContextSelect) return;
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      onContextSelect();
    }
  };

  return (
    <div ref={setFlipRef(task.id)} className="feed-card-flip-shell">
      <div
        className={[
          "trade-agent-intent-card",
          isPushing ? "is-push" : "",
          isRevealing ? "is-reveal" : "",
          isExiting ? "is-exiting" : "",
          isGateTimeoutComplete ? "is-gate-timeout-complete" : "",
          isContextActive ? "is-context-active" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        onAnimationEnd={(event) => {
          if (
            isExiting &&
            (event.animationName === "agentIntentCardExit" ||
              event.animationName === "agentIntentCardExitAfterGate")
          ) {
            onExitAnimationEnd(task.id);
          }
        }}
      >
        <div
          className={[
            "trade-agent-intent-card-context",
            onContextSelect ? "trade-agent-intent-card-context--selectable" : "",
          ]
            .filter(Boolean)
            .join(" ")}
          role={onContextSelect ? "button" : undefined}
          tabIndex={onContextSelect ? 0 : undefined}
          aria-label={
            onContextSelect
              ? `Show ${task.trigger || task.description} on chart`
              : undefined
          }
          onClick={onContextSelect}
          onKeyDown={onContextSelect ? handleContextKeyDown : undefined}
        >
          <div className="trade-agent-intent-card-top">
            <div className="trade-agent-intent-card-top-leading">
              <span className="task-id-chip" title={task.id}>
                {shortHashId(task.id)}
              </span>
              {headerLeading}
            </div>
            <span
              className="trade-agent-intent-status"
              data-status={task.status}
            >
              {task.status}
            </span>
          </div>
          {task.trigger ? (
            animateText ? (
              <span
                className="trade-agent-intent-card-title-wrap"
                title={task.trigger}
              >
                <Typewriter
                  text={task.trigger}
                  className="trade-agent-intent-card-title"
                  active={!isPushing}
                />
              </span>
            ) : (
              <p className="trade-agent-intent-card-title" title={task.trigger}>
                {task.trigger}
              </p>
            )
          ) : null}
          {animateText ? (
            <span
              className="trade-agent-intent-desc-wrap"
              title={task.description}
            >
              <Typewriter
                text={task.description}
                className="trade-agent-intent-desc"
                multiline="auto"
                active={!isPushing}
              />
            </span>
          ) : (
            <p className="trade-agent-intent-desc" title={task.description}>
              {task.description}
            </p>
          )}
        </div>
        {children}
      </div>
    </div>
  );
}
