import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";

import { useAgentSettings } from "../../hooks/useAgentSettings";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import { ModalTabBar } from "../smartlayout/modal-tab-bar";
import AgentEnvVarsTab from "./AgentEnvVarsTab";
import AgentMcpServersTab from "./AgentMcpServersTab";
import AgentSkillsTab from "./AgentSkillsTab";
import type { AgentSettingsTabId } from "./agentSettingsTypes";
import "../smartlayout/layout.css";
import "./agent.css";
import "./agentSettings.css";

export interface AgentSettingsModalProps {
  open: boolean;
  onClose: () => void;
  catalogAgentId: string;
  agentName?: string;
}

const TAB_LABELS: Record<AgentSettingsTabId, string> = {
  skills: "Skills",
  envVars: "Env Vars",
  mcpServers: "MCP Servers",
};

function CloseIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M18 6L6 18M6 6l12 12" />
    </svg>
  );
}

function AgentSettingsModal({
  open,
  onClose,
  catalogAgentId,
  agentName,
}: AgentSettingsModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(open);

  useOverlayEscapeKey(open, onClose);

  const [activeTab, setActiveTab] = useState<AgentSettingsTabId>("skills");

  const {
    settings,
    installCatalogSkill,
    createCustomSkill,
    removeSkill,
    upsertEnvVar,
    removeEnvVar,
    addMcpServer,
    removeMcpServer,
  } = useAgentSettings(catalogAgentId);

  useEffect(() => {
    if (!open) {
      setActiveTab("skills");
    }
  }, [open]);

  const tabs = (Object.keys(TAB_LABELS) as AgentSettingsTabId[]).map((id) => ({
    id,
    label: TAB_LABELS[id],
  }));

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content agent-settings-modal-content staggered-overlay-panel--scale"
        aria-label={agentName ? `Agent settings for ${agentName}` : "Agent settings"}
      >
        <div className="modal-header agent-settings-modal-header">
          <h3 className="terminal-panel-title">Agent Settings</h3>
          <button
            type="button"
            className="agent-settings-modal-close"
            onClick={onClose}
            aria-label="Close agent settings"
          >
            <CloseIcon />
          </button>
        </div>

        <ModalTabBar tabs={tabs} activeTabId={activeTab} onTabChange={setActiveTab} />

        <div className="modal-body">
          {activeTab === "skills" ? (
            <AgentSkillsTab
              settings={settings}
              onInstallCatalog={installCatalogSkill}
              onCreateCustom={createCustomSkill}
              onRemoveSkill={removeSkill}
            />
          ) : null}
          {activeTab === "envVars" ? (
            <AgentEnvVarsTab
              settings={settings}
              onUpsertEnvVar={upsertEnvVar}
              onRemoveEnvVar={removeEnvVar}
            />
          ) : null}
          {activeTab === "mcpServers" ? (
            <AgentMcpServersTab
              settings={settings}
              onAddMcpServer={addMcpServer}
              onRemoveMcpServer={removeMcpServer}
            />
          ) : null}
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default AgentSettingsModal;
