import type { UTCTimestamp } from "lightweight-charts";

import type {
  FleetTradeAction,
  FleetTradeEvent,
} from "../../../offline/mock_data/fleetTradeHistory";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { type ChartExecutionMarker, snapTimeToCandleInterval } from "./chartMarkers";

export type FleetChartMarkerMeta = {
  tradeId: string;
  catalogAgentId: string;
  agentName: string;
  avatar: string;
  avatarSvgUrl: string;
  agentWallet: string;
  masterWallet: string;
  action: FleetTradeAction;
  amountUsd: number;
  copyCount: number;
  copyEnabled: boolean;
  /** Set when the viewer has an active copy relation for this agent. */
  copySizePct?: number;
  coin: string;
  price: number;
  quantity: number;
  time: number;
  closedPnl: number | null;
};

export type FleetChartMarker = {
  tradeId: string;
  time: UTCTimestamp;
  position: "aboveBar" | "belowBar";
  shape: "circle" | "square" | "arrowDown";
  color: string;
  label: string;
  imageUrl?: string;
  stackRank?: number;
};

export type FleetTradesToMarkersResult = {
  markers: FleetChartMarker[];
  metaByTradeId: Map<string, FleetChartMarkerMeta>;
};

const SATOSHI = 100_000_000;

function fromSatoshi(value: string): number {
  const intStr = value.includes(".") ? value.split(".")[0]! : value;
  return Number(BigInt(intStr)) / SATOSHI;
}

function isBuyAction(action: FleetTradeAction): boolean {
  return action === "BUY" || action === "SNIPE";
}

function markerLabel(profile: PropertyProfile | undefined): string {
  if (!profile) return "A";
  const ticker = profile.ticker.replace(/^\$/, "").slice(0, 3);
  return ticker.toUpperCase();
}

export function filterFleetTradesForMarket(
  trades: FleetTradeEvent[],
  marketId?: string,
  baseAsset?: string,
): FleetTradeEvent[] {
  const normalizedBase = baseAsset?.trim().toUpperCase() ?? "";
  if (!marketId && !normalizedBase) return trades;

  return trades.filter((event) => {
    if (normalizedBase) return event.coin.toUpperCase() === normalizedBase;
    if (marketId) return event.marketId === marketId;
    return true;
  });
}

/** Keep leader fills on or after the copier's copy start time. */
export function filterFleetTradesSinceCopyStart(
  trades: FleetTradeEvent[],
  startedAt?: string,
): FleetTradeEvent[] {
  if (!startedAt) return trades;
  const sinceMs = Date.parse(startedAt);
  if (Number.isNaN(sinceMs)) return trades;
  return trades.filter((event) => Date.parse(event.timestamp) >= sinceMs);
}

export function fleetMarkersToChartMarkers(
  markers: FleetChartMarker[],
): ChartExecutionMarker[] {
  return markers.map((marker) => ({
    tradeId: marker.tradeId,
    time: marker.time,
    position: marker.position,
    shape: marker.imageUrl ? "circle" : marker.shape === "square" ? "square" : "circle",
    color: marker.color,
    label: marker.imageUrl ? "" : marker.label,
    imageUrl: marker.imageUrl,
    stackRank: marker.stackRank,
  }));
}

export function fleetTradesToSeriesMarkers(
  trades: FleetTradeEvent[],
  profile: PropertyProfile | undefined,
  fleet: FleetAgentRecord | undefined,
  interval: string,
  copyEnabled = false,
  copySizePct?: number,
): FleetTradesToMarkersResult {
  const markers: FleetChartMarker[] = [];
  const metaByTradeId = new Map<string, FleetChartMarkerMeta>();
  const label = markerLabel(profile);
  const copyCount = fleet?.copyCount ?? 0;

  for (const event of trades) {
    const buy = isBuyAction(event.action);
    const timeMs = Date.parse(event.timestamp);
    const price = fromSatoshi(event.price);
    const quantity = fromSatoshi(event.quantity);
    const avatarSvgUrl = resolveAgentAvatarSvgUrl(event.catalogAgentId);

    const meta: FleetChartMarkerMeta = {
      tradeId: event.id,
      catalogAgentId: event.catalogAgentId,
      agentName: profile?.name ?? event.catalogAgentId,
      avatar: profile?.avatar ?? "🤖",
      avatarSvgUrl,
      agentWallet: event.agentWallet,
      masterWallet: event.masterWallet,
      action: event.action,
      amountUsd: event.amountUsd,
      copyCount,
      copyEnabled,
      copySizePct: copyEnabled ? copySizePct : undefined,
      coin: event.coin,
      price,
      quantity,
      time: timeMs,
      closedPnl: event.closedPnl,
    };

    markers.push({
      tradeId: event.id,
      time: snapTimeToCandleInterval(timeMs, interval),
      position: buy ? "belowBar" : "aboveBar",
      shape: "circle",
      color: buy ? TERMINAL_COLORS.long : TERMINAL_COLORS.short,
      label,
      imageUrl: avatarSvgUrl,
    });
    metaByTradeId.set(event.id, meta);
  }

  return { markers, metaByTradeId };
}
