import { useEffect, useMemo, useState } from "react";

import { useSettings } from "../context/SettingsContext";
import { mockAgentProfiles, mockIndexRows, getFleetAgentByCatalogId } from "../../offline/mock_data";

export type MarketKind = "agent" | "index";
export type SortKey =
  | "name"
  | "price"
  | "change24h"
  | "revenue30d"
  | "risk"
  | "copyCount";
export type RiskBand = "A" | "B" | "C" | "D" | "E";

export type MarketRow = {
  id: string;
  name: string;
  kind: MarketKind;
  sector: string;
  icon: string;
  price: number;
  change24h: number;
  revenue30d: number | "basket";
  risk: RiskBand;
  product: string;
  sparkline: number[];
  agentWallet?: string;
  copyCount?: number;
  isPopular?: boolean;
};

export const AGENT_ROWS: MarketRow[] = mockAgentProfiles.map((agent) => {
  const fleet = getFleetAgentByCatalogId(agent.id);
  return {
    id: agent.id,
    name: agent.name,
    kind: "agent" as const,
    sector: agent.sector,
    icon: agent.avatar ?? "🤖",
    price: agent.price,
    change24h: agent.change24h,
    revenue30d:
      Number(
        agent.quickStats
          .find((item) => item.label === "30d revenue")
          ?.value.replace(/[^\d.]/g, "") ?? 0,
      ) * 1000,
    risk: agent.riskScore.startsWith("A")
      ? "A"
      : agent.riskScore.startsWith("B")
        ? "B"
        : "C",
    product: agent.product,
    sparkline: agent.sparkline,
    agentWallet: fleet?.agentWallet,
    copyCount: fleet?.copyCount,
    isPopular: fleet?.isPopular,
  };
});

export const INDEX_ROWS: MarketRow[] = mockIndexRows as MarketRow[];

export const SECTOR_OPTIONS = ["All", "Trading", "Yield", "Arbitrage", "Basket"];
export const RISK_OPTIONS = ["All", "A", "B", "C", "D", "E"];
export const REVENUE_OPTIONS = ["All", "High", "Medium", "Low"];

export function formatCurrency(value: number): string {
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(1)}k`;
  return `$${value.toFixed(2)}`;
}

export function useMarketsPageData() {
  const { settings } = useSettings();
  const marketsPrefs = settings.markets;

  const [activeTab, setActiveTab] = useState<MarketKind>(marketsPrefs.defaultTab);
  const [query, setQuery] = useState("");
  const [sector, setSector] = useState("All");
  const [risk, setRisk] = useState("All");
  const [revenue, setRevenue] = useState("All");
  const [sortKey, setSortKey] = useState<SortKey>(marketsPrefs.defaultSortKey);
  const [sortDir, setSortDir] = useState<"asc" | "desc">(marketsPrefs.defaultSortDir);

  useEffect(() => {
    setActiveTab(marketsPrefs.defaultTab);
    setSortKey(marketsPrefs.defaultSortKey);
    setSortDir(marketsPrefs.defaultSortDir);
  }, [
    marketsPrefs.defaultTab,
    marketsPrefs.defaultSortKey,
    marketsPrefs.defaultSortDir,
  ]);

  const rows = activeTab === "agent" ? AGENT_ROWS : INDEX_ROWS;
  const totalTradableRows = AGENT_ROWS.length + INDEX_ROWS.length;

  const filteredRows = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    const revenueFilter = revenue;

    const nextRows = rows.filter((row) => {
      const matchesQuery =
        !normalizedQuery ||
        row.name.toLowerCase().includes(normalizedQuery) ||
        row.sector.toLowerCase().includes(normalizedQuery) ||
        row.product.toLowerCase().includes(normalizedQuery);
      const matchesSector = sector === "All" || row.sector === sector;
      const matchesRisk = risk === "All" || row.risk === risk;
      const rowRevenue = typeof row.revenue30d === "number" ? row.revenue30d : 0;
      const matchesRevenue =
        revenueFilter === "All" ||
        (revenueFilter === "High" && rowRevenue >= 40000) ||
        (revenueFilter === "Medium" &&
          rowRevenue >= 20000 &&
          rowRevenue < 40000) ||
        (revenueFilter === "Low" && rowRevenue < 20000);

      return matchesQuery && matchesSector && matchesRisk && matchesRevenue;
    });

    return nextRows.sort((a, b) => {
      const direction = sortDir === "asc" ? 1 : -1;
      if (sortKey === "name") return a.name.localeCompare(b.name) * direction;
      if (sortKey === "copyCount") {
        return ((a.copyCount ?? 0) - (b.copyCount ?? 0)) * direction;
      }
      const aValue = a[sortKey];
      const bValue = b[sortKey];
      const aNum = typeof aValue === "number" ? aValue : 0;
      const bNum = typeof bValue === "number" ? bValue : 0;
      return (aNum - bNum) * direction;
    });
  }, [rows, query, sector, risk, revenue, sortKey, sortDir]);

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir((current) => (current === "asc" ? "desc" : "asc"));
      return;
    }
    setSortKey(key);
    setSortDir(key === "name" ? "asc" : "desc");
  };

  const resetFilters = () => {
    setQuery("");
    setSector("All");
    setRisk("All");
    setRevenue("All");
    setSortKey("revenue30d");
    setSortDir("desc");
  };

  return {
    activeTab,
    setActiveTab,
    query,
    setQuery,
    sector,
    setSector,
    risk,
    setRisk,
    revenue,
    setRevenue,
    sortKey,
    sortDir,
    filteredRows,
    handleSort,
    resetFilters,
    totalTradableRows,
  };
}
