import type {
  AgentTokenTakerHistoryFile,
  AgentTokenTakerHistoryManifest,
  AgentTokenTakerTradeEvent,
} from "../../../../offline/mock_data/agentTokenTakerHistory.types";

export const AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_AGENT_TOKEN_TAKER_HISTORY_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/agent-token-taker-history";

let manifestCache: AgentTokenTakerHistoryManifest | null = null;
let manifestPromise: Promise<AgentTokenTakerHistoryManifest> | null = null;
const eventsCache = new Map<string, AgentTokenTakerTradeEvent[]>();
const eventsPromises = new Map<string, Promise<AgentTokenTakerTradeEvent[]>>();

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearAgentTokenTakerHistoryCache(): void {
  manifestCache = null;
  manifestPromise = null;
  eventsCache.clear();
  eventsPromises.clear();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export async function fetchAgentTokenTakerManifest(
  baseUrl: string = AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL,
): Promise<AgentTokenTakerHistoryManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<AgentTokenTakerHistoryManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  ).then((manifest) => {
    manifestCache = manifest;
    return manifest;
  }).finally(() => {
    manifestPromise = null;
  });

  return manifestPromise;
}

export function getCachedAgentTokenTakerManifest(): AgentTokenTakerHistoryManifest | null {
  return manifestCache;
}

export function getManifestMarketByCatalogId(
  manifest: AgentTokenTakerHistoryManifest,
  marketCatalogAgentId: string,
): AgentTokenTakerHistoryManifest["markets"][number] | undefined {
  const normalized = marketCatalogAgentId.trim().toLowerCase();
  return manifest.markets.find(
    (market) => market.marketCatalogAgentId.toLowerCase() === normalized,
  );
}

export async function fetchAgentTokenTakerEventsByMarketId(
  marketCatalogAgentId: string,
  baseUrl: string = AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL,
): Promise<AgentTokenTakerTradeEvent[]> {
  const normalizedId = marketCatalogAgentId.trim().toLowerCase();
  const cached = eventsCache.get(normalizedId);
  if (cached) return cached;

  const inflight = eventsPromises.get(normalizedId);
  if (inflight) return inflight;

  const promise = (async () => {
    const manifest = await fetchAgentTokenTakerManifest(baseUrl);
    const market = getManifestMarketByCatalogId(manifest, normalizedId);
    if (!market) {
      return [];
    }

    const payload = await fetchJson<AgentTokenTakerHistoryFile>(
      joinBaseUrl(baseUrl, market.file),
    );
    eventsCache.set(normalizedId, payload.events);
    return payload.events;
  })().finally(() => {
    eventsPromises.delete(normalizedId);
  });

  eventsPromises.set(normalizedId, promise);
  return promise;
}

export async function hasAgentTokenTakerMarket(
  marketCatalogAgentId: string,
  baseUrl: string = AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL,
): Promise<boolean> {
  const manifest = await fetchAgentTokenTakerManifest(baseUrl);
  return getManifestMarketByCatalogId(manifest, marketCatalogAgentId) != null;
}

export function getCachedAgentTokenTakerEventsByMarketId(
  marketCatalogAgentId: string,
): AgentTokenTakerTradeEvent[] | null {
  return eventsCache.get(marketCatalogAgentId.trim().toLowerCase()) ?? null;
}
