import {
  isElementVisible,
  waitAnimationFrames,
  waitForTourTarget,
} from "../welcome-tour/welcomeTourDom";

export { isElementVisible, waitAnimationFrames, waitForTourTarget };

/** Scroll target into view inside modals without scrolling the page behind. */
export function scrollTourTargetIntoView(selector: string): void {
  const el = document.querySelector(selector);
  if (!el || !isElementVisible(el)) return;
  el.scrollIntoView({ block: "nearest", inline: "nearest" });
}

/**
 * Wait for a tour anchor, scroll it into view, and report whether it is visible.
 * Used in step `before` hooks — no React state loops.
 */
export async function prepareDepositTourTarget(
  selector: string,
  maxMs = 4000,
): Promise<boolean> {
  await waitAnimationFrames(2);
  await waitForTourTarget(selector, maxMs);
  let el = document.querySelector(selector);
  if (!el || !isElementVisible(el)) {
    await waitAnimationFrames(3);
    el = document.querySelector(selector);
  }
  if (!el || !isElementVisible(el)) return false;
  scrollTourTargetIntoView(selector);
  await waitAnimationFrames(2);
  return true;
}
