import type { CrossChainFlowStep } from "../../types/crossChainFlow";

export interface DepositTourFlowStateSnapshot {
  flowStep: CrossChainFlowStep;
  mode: "deposit" | "withdraw";
  isCrossChainModalOpen: boolean;
}

/** Shallow compare — pollers must use this before setFlowState to avoid context churn loops. */
export function flowStateEqual(
  a: DepositTourFlowStateSnapshot | null,
  b: DepositTourFlowStateSnapshot | null,
): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return (
    a.flowStep === b.flowStep &&
    a.mode === b.mode &&
    a.isCrossChainModalOpen === b.isCrossChainModalOpen
  );
}

export function nextFlowState(
  prev: DepositTourFlowStateSnapshot | null,
  next: DepositTourFlowStateSnapshot | null,
): DepositTourFlowStateSnapshot | null {
  return flowStateEqual(prev, next) ? prev : next;
}
