import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  SHORTCUT_ACTION_CATALOG,
  captureKeyboardBinding,
  detectPlatform,
  findBindingConflicts,
  findShortcutAction,
  formatKeyboardBinding,
  getDefaultBindingForAction,
  getDefaultKeyboardShortcuts,
  getPlatformHint,
  isValidKeyboardBinding,
  type KeyboardBinding,
  type KeyboardShortcutPrefs,
  type ShortcutActionId,
} from "../../utils/keyboardShortcuts";

interface KeyboardShortcutsSettingsPanelProps {
  shortcuts: KeyboardShortcutPrefs;
  onChange: (shortcuts: KeyboardShortcutPrefs) => void;
}

function BindingChips({ binding }: { binding: KeyboardBinding }): JSX.Element {
  const platform = detectPlatform();
  const tokens = formatKeyboardBinding(binding, platform);

  return (
    <span className="settings-shortcut-chips">
      {tokens.map((token, index) => (
        <React.Fragment key={`${token}-${index}`}>
          {index > 0 ? (
            <span className="settings-shortcut-chip-sep" aria-hidden>
              +
            </span>
          ) : null}
          <kbd className="settings-shortcut-kbd">{token}</kbd>
        </React.Fragment>
      ))}
    </span>
  );
}

export function KeyboardShortcutsSettingsPanel({
  shortcuts,
  onChange,
}: KeyboardShortcutsSettingsPanelProps): JSX.Element {
  const platform = detectPlatform();
  const [recordingActionId, setRecordingActionId] = useState<ShortcutActionId | null>(null);
  const [draftBinding, setDraftBinding] = useState<KeyboardBinding | null>(null);
  const [recordError, setRecordError] = useState<string | null>(null);

  const conflictActionIds = useMemo(() => {
    if (!draftBinding || !recordingActionId) return [];
    return findBindingConflicts(shortcuts, draftBinding, recordingActionId);
  }, [draftBinding, recordingActionId, shortcuts]);

  const startRecording = useCallback((actionId: ShortcutActionId) => {
    setRecordingActionId(actionId);
    setDraftBinding(null);
    setRecordError(null);
  }, []);

  const cancelRecording = useCallback(() => {
    setRecordingActionId(null);
    setDraftBinding(null);
    setRecordError(null);
  }, []);

  const saveRecording = useCallback(() => {
    if (!recordingActionId || !draftBinding) return;
    if (conflictActionIds.length > 0) return;

    const nextBinding: KeyboardBinding = {
      ...draftBinding,
      ...(recordingActionId === "toggleAgentConsole" && !draftBinding.shift
        ? { excludeShift: true }
        : {}),
    };

    if (recordingActionId !== "toggleAgentConsole" || draftBinding.shift) {
      delete nextBinding.excludeShift;
    }

    onChange({
      ...shortcuts,
      [recordingActionId]: nextBinding,
    });
    cancelRecording();
  }, [cancelRecording, conflictActionIds.length, draftBinding, onChange, recordingActionId, shortcuts]);

  const resetAction = useCallback(
    (actionId: ShortcutActionId) => {
      onChange({
        ...shortcuts,
        [actionId]: getDefaultBindingForAction(actionId, platform),
      });
      if (recordingActionId === actionId) cancelRecording();
    },
    [cancelRecording, onChange, platform, recordingActionId, shortcuts],
  );

  const resetAll = useCallback(() => {
    onChange(getDefaultKeyboardShortcuts(platform));
    cancelRecording();
  }, [cancelRecording, onChange, platform]);

  useEffect(() => {
    if (!recordingActionId) return;

    const onKeyDown = (event: KeyboardEvent) => {
      event.preventDefault();
      event.stopPropagation();

      if (event.key === "Escape") {
        cancelRecording();
        return;
      }

      const captured = captureKeyboardBinding(event);
      if (!isValidKeyboardBinding(captured)) {
        setRecordError("Press a modifier plus a key (for example Ctrl+K).");
        setDraftBinding(null);
        return;
      }

      setRecordError(null);
      setDraftBinding(captured);
    };

    document.addEventListener("keydown", onKeyDown, true);
    return () => document.removeEventListener("keydown", onKeyDown, true);
  }, [cancelRecording, recordingActionId]);

  return (
    <div className="settings-shortcuts-panel">
      <p className="settings-chart-overlay-hint settings-shortcuts-hint">{getPlatformHint(platform)}</p>

      <div className="settings-shortcuts-rows">
        {SHORTCUT_ACTION_CATALOG.map((action) => {
          const binding = shortcuts[action.id];
          const isRecording = recordingActionId === action.id;

          return (
            <div key={action.id} className="settings-shortcut-row">
              <div className="settings-shortcut-row-main">
                <div className="settings-shortcut-row-copy">
                  <span className="settings-shortcut-label">{action.label}</span>
                  <span className="settings-shortcut-description">{action.description}</span>
                </div>
                <div className="settings-shortcut-row-binding">
                  {isRecording && draftBinding ? (
                    <BindingChips binding={draftBinding} />
                  ) : (
                    <BindingChips binding={binding} />
                  )}
                </div>
              </div>

              <div className="settings-shortcut-row-actions">
                {isRecording ? (
                  <>
                    <button
                      type="button"
                      className="settings-shortcut-action settings-shortcut-action--primary"
                      onClick={saveRecording}
                      disabled={!draftBinding || conflictActionIds.length > 0}
                    >
                      Save
                    </button>
                    <button
                      type="button"
                      className="settings-shortcut-action"
                      onClick={cancelRecording}
                    >
                      Cancel
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      type="button"
                      className="settings-shortcut-action"
                      onClick={() => startRecording(action.id)}
                      disabled={recordingActionId !== null}
                    >
                      Change
                    </button>
                    <button
                      type="button"
                      className="settings-shortcut-action"
                      onClick={() => resetAction(action.id)}
                      disabled={recordingActionId !== null}
                    >
                      Reset
                    </button>
                  </>
                )}
              </div>

              {isRecording ? (
                <p className="settings-shortcut-record-hint">
                  {draftBinding
                    ? `Preview: ${formatKeyboardBinding(draftBinding, platform).join(" + ")}`
                    : "Press the new shortcut combination…"}
                </p>
              ) : null}

              {isRecording && recordError ? (
                <p className="settings-shortcut-error">{recordError}</p>
              ) : null}

              {isRecording && conflictActionIds.length > 0 ? (
                <p className="settings-shortcut-error">
                  Conflicts with {conflictActionIds.map((id) => findShortcutAction(id).label).join(", ")}.
                </p>
              ) : null}
            </div>
          );
        })}
      </div>

      <div className="settings-shortcuts-footer-actions">
        <button
          type="button"
          className="settings-shortcut-action"
          onClick={resetAll}
          disabled={recordingActionId !== null}
        >
          Reset all to defaults
        </button>
      </div>
    </div>
  );
}
