import React, { useEffect, useMemo, useRef } from "react";
import {
  AreaSeries,
  createChart,
  createSeriesMarkers,
  type IChartApi,
  type ISeriesApi,
  type SeriesMarker,
  type UTCTimestamp,
} from "lightweight-charts";

import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { buildIndexNavPriceChartSeries } from "../../utils/indexChartData";
import { snapTimeToCandleInterval } from "../finchartview/chartMarkers";
import "./agent.css";

const EQUITY_COLOR = "#34d399";

export interface AgentEquityChartProps {
  height?: string;
  series: number[];
  currentValue: number;
  fleetTrades?: FleetTradeEvent[];
  agentTicker?: string;
  hideHead?: boolean;
  hideOuterShell?: boolean;
}

function AgentEquityChart({
  height = "100%",
  series,
  currentValue,
  fleetTrades = [],
  agentTicker = "",
  hideHead = false,
  hideOuterShell = false,
}: AgentEquityChartProps): JSX.Element {
  const chartWrapRef = useRef<HTMLDivElement>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const equitySeriesRef = useRef<ISeriesApi<"Area"> | null>(null);
  const markersRef = useRef<ReturnType<typeof createSeriesMarkers> | null>(null);

  const { priceData } = useMemo(
    () => buildIndexNavPriceChartSeries(series, currentValue, currentValue),
    [series, currentValue],
  );

  const seriesKey = useMemo(
    () => `${priceData.length}:${priceData.at(-1)?.value ?? 0}:${fleetTrades.length}`,
    [priceData, fleetTrades.length],
  );

  const fleetMarkers = useMemo((): SeriesMarker<UTCTimestamp>[] => {
    const label = agentTicker.replace(/^\$/, "").slice(0, 3).toUpperCase() || "A";
    return fleetTrades.slice(0, 24).map((event) => {
      const isBuy = event.action === "BUY" || event.action === "SNIPE";
      const timeMs = Date.parse(event.timestamp);
      return {
        time: snapTimeToCandleInterval(timeMs, "1d"),
        position: isBuy ? "belowBar" : "aboveBar",
        shape: isBuy ? "circle" : "arrowDown",
        color: isBuy ? TERMINAL_COLORS.long : TERMINAL_COLORS.short,
        text: label,
      } satisfies SeriesMarker<UTCTimestamp>;
    });
  }, [agentTicker, fleetTrades]);

  const hasData = priceData.length > 0;

  useEffect(() => {
    if (!chartContainerRef.current || !hasData) return;

    if (chartRef.current) {
      try {
        chartRef.current.remove();
      } catch {
        // ignore
      }
      chartRef.current = null;
      equitySeriesRef.current = null;
      markersRef.current = null;
    }

    let chart: IChartApi | null = null;
    let animationFrameId: number | null = null;
    let initAttempts = 0;
    const maxInitAttempts = 120;

    const initializeChart = () => {
      if (!chartContainerRef.current) return;

      const container = chartContainerRef.current;
      const containerWidth = container.clientWidth || container.offsetWidth;
      const containerHeight = container.clientHeight || container.offsetHeight;

      if (
        (!containerWidth ||
          containerWidth < 50 ||
          !containerHeight ||
          containerHeight < 60) &&
        initAttempts < maxInitAttempts
      ) {
        initAttempts += 1;
        animationFrameId = requestAnimationFrame(initializeChart);
        return;
      }

      try {
        chart = createChart(container, {
          autoSize: true,
          layout: {
            background: { color: "transparent" },
            textColor: TERMINAL_COLORS.textSecondary,
          },
          grid: {
            vertLines: { visible: false },
            horzLines: { color: TERMINAL_COLORS.gridMajor },
          },
          crosshair: { mode: 1 },
          handleScroll: {
            mouseWheel: true,
            pressedMouseMove: true,
            horzTouchDrag: true,
            vertTouchDrag: false,
          },
          handleScale: {
            axisPressedMouseMove: true,
            mouseWheel: true,
            pinch: true,
          },
          rightPriceScale: {
            borderColor: TERMINAL_COLORS.panelStrong,
            visible: true,
            scaleMargins: { top: 0.08, bottom: 0.08 },
          },
          leftPriceScale: { visible: false },
          timeScale: {
            visible: true,
            borderVisible: true,
            borderColor: TERMINAL_COLORS.panelStrong,
            timeVisible: true,
            secondsVisible: false,
            ticksVisible: true,
            minimumHeight: 22,
          },
        });

        const equitySeries = chart.addSeries(AreaSeries, {
          lineColor: EQUITY_COLOR,
          topColor: "rgba(52, 211, 153, 0.22)",
          bottomColor: "rgba(52, 211, 153, 0.02)",
          lineWidth: 2,
          priceScaleId: "right",
          crosshairMarkerVisible: true,
          crosshairMarkerRadius: 4,
          crosshairMarkerBorderColor: EQUITY_COLOR,
          crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
        });

        equitySeries.setData(priceData);
        chart.timeScale().fitContent();

        chartRef.current = chart;
        equitySeriesRef.current = equitySeries;
        markersRef.current = createSeriesMarkers(equitySeries, fleetMarkers);
      } catch {
        // ignore chart init failures in constrained layouts
      }
    };

    initializeChart();

    return () => {
      if (animationFrameId != null) {
        cancelAnimationFrame(animationFrameId);
      }
      if (chart) {
        try {
          chart.remove();
        } catch {
          // ignore
        }
      }
      chartRef.current = null;
      equitySeriesRef.current = null;
      markersRef.current = null;
    };
  }, [hasData, seriesKey, priceData, fleetMarkers]);

  useEffect(() => {
    if (!equitySeriesRef.current || !hasData) return;
    equitySeriesRef.current.setData(priceData);
    markersRef.current?.setMarkers(fleetMarkers);
    chartRef.current?.timeScale().fitContent();
  }, [hasData, priceData, fleetMarkers]);

  const chartContainer = (
    <div
      className="agent-chart-container"
      ref={chartContainerRef}
      style={hideOuterShell ? { height: "100%" } : undefined}
    />
  );

  if (hideOuterShell) {
    return chartContainer;
  }

  return (
    <div
      className="agent-slot agent-slot--chart agent-chart-wrap"
      style={{ height }}
      ref={chartWrapRef}
    >
      {!hideHead ? (
        <div className="agent-chart-head">
          <span className="agent-chart-label">
            PnL / equity curve · {fleetTrades.length} simulated fills
          </span>
        </div>
      ) : null}
      {chartContainer}
    </div>
  );
}

export default AgentEquityChart;
