import React, { useState, useMemo, useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { formatCurrency } from "../../sdk/utils/display";
import { SliderConfirmBar } from "./slider-confirm-bar";
import { NumberPad } from "./number-pad";
import { ModalTabBar, type ModalTab } from "./modal-tab-bar";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useAnchoredOverlayPosition,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../../terminal.css";
import "./layout.css";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import MorpheumLogo from "../ui/MorpheumLogo";
import { CreateBucketSuccessPanel } from "./transfer/CreateBucketSuccessPanel";
import type { DemoCreateBucketResult } from "../../../offline/mock_data";

export type CreateBucketFlowStep = "form" | "processing" | "success";

const SLIDER_CONFIRM_ICON_SRC = "/morhpeum-2.svg";

const TRANSFER_MODAL_TABS = [
  { id: "transfer", label: "Transfer" },
  { id: "create", label: "Create Bucket" },
] as const satisfies readonly ModalTab<"transfer" | "create">[];

/**
 * Transfer flow parameters
 */
export interface TransferFlowParams {
  type: "transfer";
  from: string;
  to: string;
  amount: number;
  // marginType is not needed - when from is "spot-wallet", to must be a bucket
  // and the bucket's marginType can be determined from the bucket data
}

/**
 * Create bucket flow parameters.
 * collateralAsset: symbol for collateral (e.g. USDC, USDT). Proto uses collateralAssetIndex.
 */
export interface CreateBucketFlowParams {
  type: "create";
  from: string;
  collateralAsset: string;
  marginType: "cross" | "isolated";
  amount: number;
}

/**
 * Union type for transfer modal confirm parameters
 */
export type TransferModalConfirmParams =
  | TransferFlowParams
  | CreateBucketFlowParams;

/**
 * Transfer Modal Props
 */
export interface TransferModalProps {
  isOpen: boolean;
  /** Anchor element for desktop dropdown positioning (e.g. Transfer btn-tab). */
  anchorEl?: HTMLElement | null;
  /** When true, ignore anchor and use viewport-centered layout (mobile). */
  preferCentered?: boolean;
  fromValue: string;
  toValue: string;
  options: Array<{ value: string; label: string }>;
  bucketsData: Array<{ bucketId: string; totalEquity: number }>;
  transferAmount: number;
  createBucketAmount: number;
  createBucketAsset: string;
  createMarginType: "cross" | "isolated";
  transferMarginType?: "cross" | "isolated";
  onFromChange: (value: string) => void;
  onToChange: (value: string) => void;
  onTransferAmountChange: (amount: number) => void;
  onCreateBucketAmountChange: (amount: number) => void;
  onCreateBucketAssetChange: (value: string) => void;
  onCreateMarginTypeChange: (value: "cross" | "isolated") => void;
  onTransferMarginTypeChange?: (value: "cross" | "isolated") => void;
  onConfirm: (params: TransferModalConfirmParams) => void;
  onCancel: () => void;
  spotWalletBalance?: number;
  activeTab?: "transfer" | "create";
  onActiveTabChange?: (tab: "transfer" | "create") => void;
  isTransferring?: boolean;
  onOpen?: () => void;
  collections?: Array<{ bucketId: string; marginType?: string }>;
  /** Called when the modal overlay (backdrop) is clicked. Default: no-op. */
  onOverlayClick?: () => void;
  createBucketFlowStep?: CreateBucketFlowStep;
  createBucketResult?: DemoCreateBucketResult | null;
  postCreateSpotBalance?: number | null;
  onCreateBucketDone?: () => void;
  onCreateAnotherBucket?: () => void;
}

/**
 * Transfer Modal
 */
export function TransferModal({
  isOpen,
  anchorEl = null,
  preferCentered = false,
  fromValue,
  toValue,
  options,
  bucketsData,
  transferAmount,
  createBucketAmount,
  createBucketAsset,
  createMarginType,
  transferMarginType,
  onFromChange,
  onToChange,
  onTransferAmountChange,
  onCreateBucketAmountChange,
  onCreateBucketAssetChange,
  onCreateMarginTypeChange,
  onTransferMarginTypeChange,
  onConfirm,
  onCancel,
  spotWalletBalance = 0,
  activeTab,
  onActiveTabChange,
  isTransferring = false,
  onOpen,
  collections,
  onOverlayClick = () => {},
  createBucketFlowStep = "form",
  createBucketResult = null,
  postCreateSpotBalance = null,
  onCreateBucketDone,
  onCreateAnotherBucket,
}: TransferModalProps): JSX.Element | null {
  // Use internal state if not provided from parent (for backward compatibility)
  const [internalActiveTab, setInternalActiveTab] = useState<
    "transfer" | "create"
  >("transfer");
  const currentActiveTab = activeTab ?? internalActiveTab;
  const handleActiveTabChange = onActiveTabChange ?? setInternalActiveTab;

  // Track previous isOpen state to detect when modal opens
  const prevIsOpenRef = useRef<boolean>(false);

  // Number pad state
  const [isNumberPadOpen, setIsNumberPadOpen] = useState<boolean>(false);
  const [numberPadType, setNumberPadType] = useState<"transfer" | "create">(
    "transfer",
  );

  // Slider confirm state
  const [isSliderConfirmed, setIsSliderConfirmed] = useState<boolean>(false);

  // Refresh spot wallet balance when modal opens
  useEffect(() => {
    if (isOpen && !prevIsOpenRef.current && onOpen) {
      // Modal just opened - refresh the data
      onOpen();
    }
    prevIsOpenRef.current = isOpen;
    // Reset slider confirmation when modal opens/closes or tab changes
    if (!isOpen) {
      setIsSliderConfirmed(false);
    }
  }, [isOpen, onOpen, currentActiveTab]);

  // Get transferable funds for selected bucket or spot wallet
  const selectedBucket = useMemo(() => {
    if (fromValue === "spot-wallet") {
      return null; // Spot wallet is not in bucketsData
    }
    return bucketsData.find((b) => b.bucketId === fromValue);
  }, [bucketsData, fromValue]);

  // Get the selected bucket's margin type from collections
  const selectedBucketMarginType = useMemo(() => {
    if (fromValue === "spot-wallet" || !collections) {
      return null;
    }
    const bucket = collections.find((b) => b.bucketId === fromValue);
    return bucket?.marginType?.toLowerCase() || null;
  }, [collections, fromValue]);

  // Calculate max transferable - use spot wallet balance if selected
  const maxTransferable = useMemo(() => {
    if (fromValue === "spot-wallet") {
      return spotWalletBalance;
    }
    return selectedBucket?.totalEquity || 0;
  }, [fromValue, spotWalletBalance, selectedBucket]);
  const minAmount = 10;
  const maxAmount = Math.max(minAmount, maxTransferable);

  // Reset amounts when bucket changes
  React.useEffect(() => {
    if (fromValue && maxAmount > 0) {
      const currentAmount =
        currentActiveTab === "transfer" ? transferAmount : createBucketAmount;
      if (currentAmount > maxAmount) {
        if (currentActiveTab === "transfer") {
          onTransferAmountChange(maxAmount);
        } else {
          onCreateBucketAmountChange(maxAmount);
        }
      } else if (currentAmount < minAmount && maxAmount >= minAmount) {
        if (currentActiveTab === "transfer") {
          onTransferAmountChange(minAmount);
        } else {
          onCreateBucketAmountChange(minAmount);
        }
      }
    }
  }, [
    fromValue,
    maxAmount,
    currentActiveTab,
    transferAmount,
    createBucketAmount,
    onTransferAmountChange,
    onCreateBucketAmountChange,
  ]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  const useAnchoredLayout = Boolean(isOpen && anchorEl && !preferCentered);
  const panelPosition = useAnchoredOverlayPosition({
    isActive: useAnchoredLayout,
    anchorEl: useAnchoredLayout ? anchorEl : null,
  });

  useOverlayEscapeKey(isOpen, onCancel);

  const isTransferValid =
    fromValue &&
    toValue &&
    transferAmount >= minAmount &&
    transferAmount <= maxAmount;
  const isCreateValid =
    fromValue &&
    createBucketAmount >= minAmount &&
    createBucketAmount <= maxAmount &&
    createBucketAsset &&
    createMarginType;

  const isCreateFlowActive =
    currentActiveTab === "create" && createBucketFlowStep !== "form";
  const modalTitle =
    currentActiveTab === "create" && createBucketFlowStep === "success"
      ? "Bucket created"
      : currentActiveTab === "create" && createBucketFlowStep === "processing"
        ? "Creating bucket"
        : "Transfer Funds";

  const modalContent = (
    <StaggeredOverlayRoot
      className={useAnchoredLayout ? "transfer-modal-overlay--anchored" : undefined}
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onOverlayClick}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content transfer-modal-content staggered-overlay-panel--scale"
        style={
          panelPosition
            ? ({
                top: panelPosition.top,
                right: panelPosition.right,
                position: "fixed",
                "--transfer-modal-anchor-top": `${panelPosition.top}px`,
              } as React.CSSProperties)
            : undefined
        }
        aria-label="Transfer Funds"
      >
        <div className="modal-header">
          <h3 className="terminal-panel-title">{modalTitle}</h3>
        </div>

        {!isCreateFlowActive ? (
          <ModalTabBar
            tabs={TRANSFER_MODAL_TABS}
            activeTabId={currentActiveTab}
            onTabChange={handleActiveTabChange}
            disabled={isTransferring}
          />
        ) : null}

        <div className="modal-body">
          {currentActiveTab === "create" &&
          createBucketFlowStep === "processing" ? (
            <div className="transfer-create-processing">
              <p className="terminal-label">Creating bucket…</p>
              <p className="terminal-value">
                On-chain progress is shown in the notification.
              </p>
            </div>
          ) : currentActiveTab === "create" &&
            createBucketFlowStep === "success" &&
            createBucketResult ? (
            <CreateBucketSuccessPanel
              result={createBucketResult}
              postCreateSpotBalance={postCreateSpotBalance}
              onDone={onCreateBucketDone ?? onCancel}
              onCreateAnother={onCreateAnotherBucket ?? onCancel}
            />
          ) : currentActiveTab === "transfer" ? (
            <>
              {/* From Selection Field */}
              <div className="transfer-field-group">
                <label className="terminal-label transfer-field-label">From</label>
                <select
                  value={fromValue}
                  onChange={(e) => onFromChange(e.target.value)}
                  className="form-input transfer-select"
                >
                  <option value="">Select source bucket</option>
                  {options.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* To Selection Field - Show when from is selected */}
              {fromValue && (
                <div className="transfer-field-group">
                  <label className="terminal-label transfer-field-label">To</label>
                  <select
                    value={toValue}
                    onChange={(e) => onToChange(e.target.value)}
                    className="form-input transfer-select"
                    disabled={!fromValue}
                  >
                    <option value="">Select destination bucket</option>
                    {options
                      .filter((option) => option.value !== fromValue)
                      .map((option) => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))}
                  </select>
                </div>
              )}

              {/* Amount Range Input */}
              {fromValue && maxAmount >= minAmount ? (
                <div className="transfer-field-group">
                  <div className="transfer-amount-header">
                    <label className="terminal-label transfer-field-label">Amount</label>
                    <div className="transfer-available-balance">
                      <span className="terminal-label">Available</span>
                      <span className="terminal-value">
                        {formatCurrency(maxTransferable)}
                      </span>
                    </div>
                  </div>
                  <div
                    className="transfer-amount-display transfer-amount-display--interactive"
                    onClick={() => {
                      setNumberPadType("transfer");
                      setIsNumberPadOpen(true);
                    }}
                  >
                    <span className="terminal-price transfer-amount-value">
                      {formatCurrency(transferAmount)}
                    </span>
                  </div>
                  <div className="transfer-amount-container">
                    <FilledRangeSlider
                      variant="info"
                      min={minAmount}
                      max={maxAmount}
                      step={0.01}
                      value={transferAmount}
                      onChange={onTransferAmountChange}
                    />
                    <div className="transfer-amount-labels">
                      <span className="terminal-value">
                        {formatCurrency(minAmount)}
                      </span>
                      <span className="terminal-value">
                        {formatCurrency(maxAmount)}
                      </span>
                    </div>
                  </div>
                </div>
              ) : fromValue ? (
                <div className="transfer-field-group">
                  <div className="transfer-insufficient-funds">
                    Insufficient funds. Minimum required:{" "}
                    {formatCurrency(minAmount)}
                  </div>
                </div>
              ) : null}
            </>
          ) : (
            <>
              {/* From Selection Field for Create Bucket */}
              <div className="transfer-field-group">
                <label className="terminal-label transfer-field-label">From</label>
                <select
                  value={fromValue}
                  onChange={(e) => onFromChange(e.target.value)}
                  className="form-input transfer-select"
                >
                  <option value="">Select source bucket</option>
                  {options.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {/* Collateral Asset Selection for Create Bucket */}
              <div className="transfer-field-group">
                <label className="terminal-label transfer-field-label">Collateral Asset</label>
                <select
                  value={createBucketAsset}
                  onChange={(e) => onCreateBucketAssetChange(e.target.value)}
                  className="form-input transfer-select"
                >
                  <option value="">Select collateral asset</option>
                  <option value="USDC">USDC</option>
                </select>
              </div>

              {/* Margin Type Selection Field for Create Bucket */}
              <div className="transfer-field-group">
                <label className="terminal-label transfer-field-label">Margin Type</label>
                <select
                  value={createMarginType}
                  onChange={(e) =>
                    onCreateMarginTypeChange(
                      e.target.value as "cross" | "isolated",
                    )
                  }
                  className="form-input transfer-select"
                >
                  <option value="">Select margin type</option>
                  <option value="cross">Cross Margin</option>
                  <option value="isolated">Isolated Margin</option>
                </select>
              </div>

              {/* Amount Range Input for Create Bucket */}
              {fromValue && maxAmount >= minAmount ? (
                <div className="transfer-field-group">
                  <div className="transfer-amount-header">
                    <label className="terminal-label transfer-field-label">Amount</label>
                    <div className="transfer-available-balance">
                      <span className="terminal-label">Available</span>
                      <span className="terminal-value">
                        {formatCurrency(maxTransferable)}
                      </span>
                    </div>
                  </div>
                  <div
                    className="transfer-amount-display transfer-amount-display--interactive"
                    onClick={() => {
                      setNumberPadType("create");
                      setIsNumberPadOpen(true);
                    }}
                  >
                    <span className="terminal-price transfer-amount-value">
                      {formatCurrency(createBucketAmount)}
                    </span>
                  </div>
                  <div className="transfer-amount-container">
                    <FilledRangeSlider
                      variant="info"
                      min={minAmount}
                      max={maxAmount}
                      step={0.01}
                      value={createBucketAmount}
                      onChange={onCreateBucketAmountChange}
                    />
                    <div className="transfer-amount-labels">
                      <span className="terminal-value">
                        {formatCurrency(minAmount)}
                      </span>
                      <span className="terminal-value">
                        {formatCurrency(maxAmount)}
                      </span>
                    </div>
                  </div>
                </div>
              ) : fromValue ? (
                <div className="transfer-field-group">
                  <div className="transfer-insufficient-funds">
                    Insufficient funds. Minimum required:{" "}
                    {formatCurrency(minAmount)}
                  </div>
                </div>
              ) : null}
            </>
          )}
        </div>

        {!isCreateFlowActive ? (
          <div className="modal-footer">
            <button
              onClick={onCancel}
              className="btn btn-secondary"
              disabled={isTransferring}
            >
              Cancel
            </button>
            <div className="transfer-footer-confirm">
              <div
                className={`transfer-footer-slider${isSliderConfirmed ? " is-hidden" : ""}`}
              >
                <SliderConfirmBar
                  onConfirm={() => {
                    setIsSliderConfirmed(true);
                  }}
                  label="Slide to confirm"
                  disabled={
                    isTransferring ||
                    (currentActiveTab === "transfer"
                      ? !isTransferValid
                      : !isCreateValid)
                  }
                  icon={
                   <MorpheumLogo fill="var(--terminal-bg-deep)"/>
                  }
                />
              </div>
              <button
                onClick={() => {
                  if (currentActiveTab === "transfer") {
                    onConfirm({
                      type: "transfer",
                      from: fromValue,
                      to: toValue,
                      amount: transferAmount,
                    });
                  } else {
                    onConfirm({
                      type: "create",
                      from: fromValue,
                      collateralAsset: createBucketAsset,
                      marginType: createMarginType,
                      amount: createBucketAmount,
                    });
                  }
                }}
                className={`btn btn-primary transfer-footer-confirm-btn${isSliderConfirmed ? " is-visible" : ""}`}
                disabled={
                  isTransferring ||
                  (currentActiveTab === "transfer"
                    ? !isTransferValid
                    : !isCreateValid)
                }
              >
                {isTransferring ? "Processing..." : "Confirm"}
              </button>
            </div>
          </div>
        ) : null}
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  // Get current amount based on number pad type
  const currentAmount =
    numberPadType === "transfer" ? transferAmount : createBucketAmount;
  const handleNumberPadConfirm = (value: number) => {
    if (numberPadType === "transfer") {
      onTransferAmountChange(value);
    } else {
      onCreateBucketAmountChange(value);
    }
    setIsNumberPadOpen(false);
  };

  return (
    <>
      {mounted && typeof document !== "undefined"
        ? createPortal(modalContent, document.body)
        : null}
      <NumberPad
        isOpen={isNumberPadOpen}
        value={currentAmount}
        min={minAmount}
        max={maxAmount}
        onConfirm={handleNumberPadConfirm}
        onCancel={() => setIsNumberPadOpen(false)}
      />
    </>
  );
}
