import type { Step } from "react-joyride";
import { TOUR_STEPS } from "./content";
import { WELCOME_TOUR_TARGETS } from "./constants";

function tourTarget(value: string): string {
  return `[data-tour="${value}"]`;
}

const STEP_TARGETS: Record<string, string> = {
  header: WELCOME_TOUR_TARGETS.header,
  "market-selector": WELCOME_TOUR_TARGETS.marketSelector,
  chart: WELCOME_TOUR_TARGETS.chart,
  orderbook: WELCOME_TOUR_TARGETS.orderbook,
  "order-panel": WELCOME_TOUR_TARGETS.orderPanel,
  "risk-controls": WELCOME_TOUR_TARGETS.riskControls,
  positions: WELCOME_TOUR_TARGETS.portfolioTabs,
  "open-orders": WELCOME_TOUR_TARGETS.portfolioTabs,
  "agent-layer": WELCOME_TOUR_TARGETS.portfolioTabs,
  architecture: WELCOME_TOUR_TARGETS.statusFooter,
};

/** Grid / panel targets sit inside transformed layout slots — use fixed spotlight. */
const FIXED_TARGET_STEP_IDS = new Set([
  "market-selector",
  "chart",
  "orderbook",
  "order-panel",
  "risk-controls",
  "positions",
  "open-orders",
  "agent-layer",
  "architecture",
]);

export type WelcomeTourTabId = "positions" | "openOrders" | "agentTasks";

export interface WelcomeTourStepMeta {
  tabId?: WelcomeTourTabId;
  targetSelector?: string;
  placement?: "center" | "auto";
  stepNumber: number;
  stepId: string;
}

export const WELCOME_TOUR_STEPS: Step[] = TOUR_STEPS.map((step, index) => {
  const isCenter = "placement" in step && step.placement === "center";
  const tabId = "tabId" in step ? step.tabId : undefined;
  const targetSelector = isCenter
    ? "body"
    : tourTarget(STEP_TARGETS[step.id] ?? WELCOME_TOUR_TARGETS.portfolioTabs);

  return {
    target: targetSelector,
    title: step.title,
    content: step.content,
    placement: isCenter ? "center" : "auto",
    skipBeacon: true,
    isFixed: !isCenter && FIXED_TARGET_STEP_IDS.has(step.id),
    buttons: ["back", "skip", "primary"],
    blockTargetInteraction: false,
    skipScroll: false,
    data: {
      tabId,
      targetSelector: isCenter ? undefined : targetSelector,
      placement: isCenter ? "center" : "auto",
      stepNumber: index + 1,
      stepId: step.id,
    } satisfies WelcomeTourStepMeta,
  };
});

export const WELCOME_TOUR_STEP_COUNT = WELCOME_TOUR_STEPS.length;
