import React, { useEffect, useRef, type JSX } from "react";
import { toast } from "sonner";
import { useJellyMode } from "../../context/JellyModeContext";
import {
  JELLY_ANCHOR_INDEX,
  TIMELINE_OFFSETS,
  getTimelineFrameOffset,
} from "../../../offline/mock_data/jellyevent";
import { useDemoGuideActions } from "../../tutorials/demo-guide/DemoGuideActionsContext";

const CHAPTER_MESSAGES: Record<number, string> = {
  [TIMELINE_OFFSETS.HEALTH_CHECK]:
    "Health transfer: SAFE → MEME. Watch bucket tabs.",
  [TIMELINE_OFFSETS.LIQUIDATION]:
    "Scoped liquidation: OP-MEME only. Check the liquidation comparison chart.",
  [TIMELINE_OFFSETS.WIND_DOWN]:
    "Hedge profit + wind-down. Other buckets stay protected.",
};

/** Timeline chapter toasts during JELLY replay. */
export function JellyReplayGuide(): null {
  const { isJellyMode, frameIndex, replayPhase } = useJellyMode();
  const demoGuide = useDemoGuideActions();
  const shownChaptersRef = useRef<Set<number>>(new Set());
  const finishedToastRef = useRef(false);

  useEffect(() => {
    if (!isJellyMode) {
      shownChaptersRef.current.clear();
      finishedToastRef.current = false;
    }
  }, [isJellyMode]);

  useEffect(() => {
    if (!isJellyMode || replayPhase !== "replaying") return;

    const offset = getTimelineFrameOffset(frameIndex, JELLY_ANCHOR_INDEX);
    for (const chapterOffset of Object.keys(CHAPTER_MESSAGES).map(Number)) {
      if (offset < chapterOffset) continue;
      if (shownChaptersRef.current.has(chapterOffset)) continue;
      shownChaptersRef.current.add(chapterOffset);
      toast.info(CHAPTER_MESSAGES[chapterOffset]);
    }
  }, [isJellyMode, replayPhase, frameIndex]);

  useEffect(() => {
    if (!isJellyMode || replayPhase !== "finished" || finishedToastRef.current) {
      return;
    }
    finishedToastRef.current = true;
    toast.info("Replay complete — loss contained without ADL.", {
      description: "Explore Network Health for throughput metrics.",
      action: demoGuide?.openNetworkHealth
        ? {
            label: "Network Health",
            onClick: demoGuide.openNetworkHealth,
          }
        : undefined,
      duration: 8000,
    });
  }, [isJellyMode, replayPhase, demoGuide]);

  return null;
}

export default JellyReplayGuide;
