import React, { useCallback, useState } from "react";
import {
  autonomyBadgeCopy,
  type AutonomyPolicy,
} from "../tradeagent/autonomyPolicy";
import "./bucketCollection.css";

export interface BucketSafetyRailProps {
  policy: AutonomyPolicy;
  activeTaskCount: number;
  canManage: boolean;
  disabled?: boolean;
  onPauseBucket: () => void;
  onGoToManage: () => void;
}

function BucketSafetyRail({
  policy,
  activeTaskCount,
  canManage,
  disabled = false,
  onPauseBucket,
  onGoToManage,
}: BucketSafetyRailProps): JSX.Element {
  const badge = autonomyBadgeCopy(policy);
  const [pauseConfirming, setPauseConfirming] = useState(false);

  const handlePauseClick = useCallback(() => {
    if (activeTaskCount === 0) return;
    if (!pauseConfirming) {
      setPauseConfirming(true);
      return;
    }
    onPauseBucket();
    setPauseConfirming(false);
  }, [activeTaskCount, pauseConfirming, onPauseBucket]);

  const handlePauseBlur = useCallback(() => {
    setPauseConfirming(false);
  }, []);

  return (
    <div
      className={`bucket-safety-rail bucket-safety-rail--${badge.tone}`}
      role="region"
      aria-label="Bucket safety controls"
    >
      <div className="bucket-safety-rail-leading">
        <span className="bucket-safety-rail-icon" aria-hidden>
          {badge.icon}
        </span>
        <div className="bucket-safety-rail-copy">
          <span className="bucket-safety-rail-headline">{badge.headline}</span>
          <span className="bucket-safety-rail-subline bucket-rules-meta-text">
            {badge.subline}
            {activeTaskCount > 0
              ? ` · ${activeTaskCount} active task${activeTaskCount === 1 ? "" : "s"}`
              : null}
          </span>
        </div>
      </div>
      {canManage ? (
        <div className="bucket-safety-rail-actions">
          <button
            type="button"
            className={`btn btn-secondary bucket-safety-rail-btn${
              pauseConfirming ? " bucket-safety-rail-btn--confirm" : ""
            }`}
            onClick={handlePauseClick}
            onBlur={handlePauseBlur}
            disabled={disabled || activeTaskCount === 0}
          >
            {pauseConfirming ? "Confirm pause" : "Pause agents in bucket"}
          </button>
          <button
            type="button"
            className="btn btn-secondary bucket-safety-rail-btn"
            onClick={onGoToManage}
            disabled={disabled}
          >
            Withdraw
          </button>
        </div>
      ) : null}
    </div>
  );
}

export default React.memo(BucketSafetyRail);
