import { useMemo } from "react";
import {
  buildTemplateSuggestions,
  detectIntentKeywords,
  getContextualKeywords,
  getTokenAtCaret,
  type IntentTemplateSuggestion,
} from "./intentKeywords";

export interface UseIntentHintsResult {
  detectedKeywords: string[];
  chipKeywords: string[];
  activeToken: string;
  suggestions: IntentTemplateSuggestion[];
}

export function useIntentHints(
  text: string,
  baseAsset: string,
  caret: number,
  enabled = true,
): UseIntentHintsResult {
  return useMemo(() => {
    if (!enabled) {
      return {
        detectedKeywords: [],
        chipKeywords: [],
        activeToken: "",
        suggestions: [],
      };
    }

    const detectedKeywords = detectIntentKeywords(text, baseAsset);
    const chipKeywords = getContextualKeywords(baseAsset);
    const activeToken = getTokenAtCaret(text, caret);
    const query = activeToken || text.trim();
    const suggestions = buildTemplateSuggestions(baseAsset, query, 4);

    return {
      detectedKeywords,
      chipKeywords,
      activeToken,
      suggestions,
    };
  }, [text, baseAsset, caret, enabled]);
}
