import type { LayoutStyle } from "../components/preference/SettingsModal";

export type TradingMode = "proTerminal" | "highAgency" | "humanInLoop";

export function getTradingModeFromLayout(layout: LayoutStyle): TradingMode {
  if (layout === "layout3") return "highAgency";
  if (layout === "layout4") return "humanInLoop";
  return "proTerminal";
}

export function isAgentTradingMode(mode: TradingMode): boolean {
  return mode === "highAgency" || mode === "humanInLoop";
}
