import type { FleetTradeAction, FleetTradeEvent } from "./fleetTradeHistory.types";
import { mockHashId } from "./mockHashId";
import type { MockPosition } from "./positions";
import type { MockTradeFill } from "./tradeHistory";

const SATOSHI = 100_000_000;
const COUNTERPARTY = "0xdeadbeef00000000000000000000000000000001";

export type CopyMirrorFill = MockTradeFill & {
  leaderTradeId: string;
  copyRelationId: string;
  bucketId: string;
};

type PositionLedger = {
  qty: number;
  avgEntry: number;
  side: "long";
};

export type AppendCopyMirrorFillParams = {
  wallet: string;
  bucketId: string;
  copyRelationId: string;
  copySizePct: number;
  leaderEvent: FleetTradeEvent;
  taskId: string;
};

const fillsByWallet = new Map<string, CopyMirrorFill[]>();
const ledgerByKey = new Map<string, PositionLedger>();
const processedLeaderIds = new Set<string>();
const bucketRealizedDelta = new Map<string, number>();
const listeners = new Set<() => void>();

function normalizeWallet(wallet: string): string {
  return wallet.trim().toLowerCase();
}

function ledgerKey(wallet: string, bucketId: string, coin: string): string {
  return `${normalizeWallet(wallet)}:${bucketId}:${coin.toUpperCase()}`;
}

function bucketKey(wallet: string, bucketId: string): string {
  return `${normalizeWallet(wallet)}:${bucketId}`;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function roundQty(n: number): number {
  return Math.round(n * 10000) / 10000;
}

function toSatoshiStr(value: number): string {
  return String(Math.round(value * SATOSHI));
}

function fromSatoshi(value: string): number {
  if (value.includes(".")) return Number.parseFloat(value);
  return Number.parseInt(value, 10) / SATOSHI;
}

function notifyListeners(): void {
  listeners.forEach((listener) => listener());
}

function isEntryAction(action: FleetTradeAction): boolean {
  return action === "BUY" || action === "SNIPE";
}

function resolveDir(
  action: FleetTradeAction,
  ledger: PositionLedger | undefined,
  isFullClose: boolean,
): string {
  if (isEntryAction(action)) {
    return ledger && ledger.qty > 0.0001 ? "Add Long" : "Open Long";
  }
  return isFullClose ? "Close Long" : "Reduce Long";
}

export function subscribeCopyMirrorListeners(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function resetCopyMirrorState(): void {
  fillsByWallet.clear();
  ledgerByKey.clear();
  processedLeaderIds.clear();
  bucketRealizedDelta.clear();
  notifyListeners();
}

export function clearCopyMirrorForRelation(relationId: string): void {
  for (const [wallet, fills] of fillsByWallet.entries()) {
    const next = fills.filter((fill) => fill.copyRelationId !== relationId);
    if (next.length === 0) {
      fillsByWallet.delete(wallet);
    } else {
      fillsByWallet.set(wallet, next);
    }
  }

  for (const leaderId of [...processedLeaderIds]) {
    if (leaderId.includes(`:${relationId}:`)) {
      processedLeaderIds.delete(leaderId);
    }
  }

  notifyListeners();
}

export function getCopyMirrorFills(wallet?: string | null): CopyMirrorFill[] {
  if (!wallet?.trim()) {
    return [...fillsByWallet.values()].flat();
  }
  return [...(fillsByWallet.get(normalizeWallet(wallet)) ?? [])];
}

export function getCopyMirrorBucketRealizedDelta(
  wallet: string,
  bucketId: string,
): number {
  return bucketRealizedDelta.get(bucketKey(wallet, bucketId)) ?? 0;
}

export function hasProcessedLeaderTrade(
  copyRelationId: string,
  leaderTradeId: string,
): boolean {
  return processedLeaderIds.has(`${copyRelationId}:${leaderTradeId}`);
}

export function appendCopyMirrorFill(
  params: AppendCopyMirrorFillParams,
): CopyMirrorFill | null {
  const wallet = normalizeWallet(params.wallet);
  const dedupKey = `${params.copyRelationId}:${params.leaderEvent.id}`;
  if (processedLeaderIds.has(dedupKey)) {
    return null;
  }

  const leaderQty = fromSatoshi(params.leaderEvent.quantity);
  const leaderPrice = fromSatoshi(params.leaderEvent.price);
  const mirrorQty = roundQty(leaderQty * (params.copySizePct / 100));
  if (mirrorQty <= 0) return null;

  const coin = params.leaderEvent.coin.toUpperCase();
  const key = ledgerKey(wallet, params.bucketId, coin);
  const ledger = ledgerByKey.get(key) ?? { qty: 0, avgEntry: 0, side: "long" as const };

  let closedPnl = 0;
  let userIsBuyer = true;
  let dir: string;

  if (isEntryAction(params.leaderEvent.action)) {
    dir = resolveDir(
      params.leaderEvent.action,
      ledger.qty > 0.0001 ? ledger : undefined,
      false,
    );
    const newTotal = ledger.qty + mirrorQty;
    ledger.avgEntry =
      ledger.qty <= 0.0001
        ? leaderPrice
        : (ledger.avgEntry * ledger.qty + leaderPrice * mirrorQty) / newTotal;
    ledger.qty = roundQty(newTotal);
    userIsBuyer = true;
  } else {
    const closeQty = Math.min(mirrorQty, ledger.qty);
    if (closeQty <= 0) return null;
    closedPnl = round2((leaderPrice - ledger.avgEntry) * closeQty);
    ledger.qty = roundQty(Math.max(0, ledger.qty - closeQty));
    const isFullClose = ledger.qty <= 0.0001;
    dir = resolveDir(params.leaderEvent.action, ledger, isFullClose);
    userIsBuyer = false;

    const bKey = bucketKey(wallet, params.bucketId);
    bucketRealizedDelta.set(
      bKey,
      round2((bucketRealizedDelta.get(bKey) ?? 0) + closedPnl),
    );
  }

  ledgerByKey.set(key, ledger);

  const seed = `copy-mirror:${params.copyRelationId}:${params.leaderEvent.id}`;
  const tradeId = mockHashId(seed);
  const buyOrderId = mockHashId(`${seed}:buy`);
  const sellOrderId = mockHashId(`${seed}:sell`);
  const fee = round2(params.leaderEvent.amountUsd * (params.copySizePct / 100) * 0.0005);

  const fill: CopyMirrorFill = {
    tradeId,
    buyOrderId,
    sellOrderId,
    price: toSatoshiStr(leaderPrice),
    quantity: toSatoshiStr(mirrorQty),
    timestamp: params.leaderEvent.timestamp,
    marketIndex: params.leaderEvent.marketId,
    makerFee: toSatoshiStr(fee * 0.4),
    takerFee: toSatoshiStr(fee),
    dualWriteId: "",
    sequenceId: "1",
    tradeType: "INITIAL",
    buyAddress: userIsBuyer ? wallet : COUNTERPARTY,
    sellAddress: userIsBuyer ? COUNTERPARTY : wallet,
    dir,
    closedPnl,
    fee,
    coin,
    symbol: `${coin}-USDT`,
    orderId: buyOrderId,
    agentTaskId: params.taskId,
    leaderTradeId: params.leaderEvent.id,
    copyRelationId: params.copyRelationId,
    bucketId: params.bucketId,
  };

  const existing = fillsByWallet.get(wallet) ?? [];
  fillsByWallet.set(wallet, [fill, ...existing]);
  processedLeaderIds.add(dedupKey);
  notifyListeners();
  return fill;
}

export function getCopyMirrorPositions(wallet?: string | null): MockPosition[] {
  const positions: MockPosition[] = [];
  const normalized = wallet?.trim() ? normalizeWallet(wallet) : null;

  for (const [key, ledger] of ledgerByKey.entries()) {
    if (ledger.qty <= 0.0001) continue;
    const [w, bucketId, coin] = key.split(":");
    if (normalized && w !== normalized) continue;

    const markPrice = ledger.avgEntry;
    positions.push({
      positionId: mockHashId(`copy-mirror:pos:${key}`),
      bucketId: bucketId!,
      marketIndex: resolveMarketIndexForCoin(coin!),
      address: w!,
      symbol: `${coin}-USDT`,
      size: toSatoshiStr(ledger.qty),
      side: "SIDE_BUY",
      averageEntryPrice: toSatoshiStr(ledger.avgEntry),
      markPrice: toSatoshiStr(markPrice),
      leverage: toSatoshiStr(3),
      unrealizedProfit: "0",
      unrealizedLoss: "0",
      mmr: toSatoshiStr(ledger.qty * markPrice * 0.01),
      marginBalance: toSatoshiStr(ledger.qty * markPrice / 3),
      status: "OPEN",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      marginMode: "cross",
      marginType: "cross",
    });
  }

  return positions;
}

function resolveMarketIndexForCoin(coin: string): string {
  switch (coin.toUpperCase()) {
    case "BTC":
      return "1";
    case "ETH":
      return "2";
    case "SOL":
      return "3";
    case "AVAX":
      return "6";
    case "LINK":
      return "7";
    default:
      return "1";
  }
}
