import { useEffect, useState } from "react";

import type { AgentKpiHistoryFile } from "../../offline/mock_data/agentKpiHistory.types";
import {
  AGENT_KPI_HISTORY_DATA_BASE_URL,
  fetchAgentKpiByCatalogId,
} from "../sdk/api/agentKpiHistory/agentKpiHistoryClient";

export interface UseAgentKpiHistoryResult {
  kpi: AgentKpiHistoryFile | null;
  loading: boolean;
  error: string | null;
}

export function useAgentKpiHistory(
  catalogAgentId: string,
  baseUrl: string = AGENT_KPI_HISTORY_DATA_BASE_URL,
): UseAgentKpiHistoryResult {
  const [kpi, setKpi] = useState<AgentKpiHistoryFile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const normalizedId = catalogAgentId.trim();
    if (!normalizedId) {
      setKpi(null);
      setLoading(false);
      setError("Missing fleet catalog agent id");
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchAgentKpiByCatalogId(normalizedId, baseUrl)
      .then((file) => {
        if (cancelled) return;
        setKpi(file);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error ? err.message : "Failed to load agent KPI history",
        );
        setKpi(null);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [catalogAgentId, baseUrl]);

  return { kpi, loading, error };
}
