import type { HeroChartMode } from "./PortfolioHeroCharts";

export const PORTFOLIO_HERO_VIEWS = [
  { id: "overview", label: "Overview" },
  { id: "performance", label: "Performance" },
  { id: "agentRanks", label: "Agent Ranks" },
] as const;

export type PortfolioHeroView = (typeof PORTFOLIO_HERO_VIEWS)[number]["id"];

const ALL_HERO_CHART_MODES: HeroChartMode[] = [
  "equity",
  "pnl",
  "dailyPnl",
  "fleetEdge",
  "agentRank",
];

export function getVisibleHeroChartModes(
  view: PortfolioHeroView,
): HeroChartMode[] {
  switch (view) {
    case "overview":
      return ALL_HERO_CHART_MODES.filter(
        (mode) => mode !== "fleetEdge" && mode !== "agentRank",
      );
    case "performance":
      return ["dailyPnl", "pnl", "fleetEdge"];
    case "agentRanks":
      return ["agentRank", "pnl", "fleetEdge"];
    default:
      return ALL_HERO_CHART_MODES.filter((mode) => mode !== "agentRank");
  }
}

export function heroViewToChartMode(view: PortfolioHeroView): HeroChartMode {
  switch (view) {
    case "overview":
      return "equity";
    case "performance":
      return "dailyPnl";
    case "agentRanks":
      return "agentRank";
  }
}
