/**
 * App-shell transfer modals: bucket transfer, coin transfer, and cross-chain deposit/withdraw.
 * Mounted outside route tree so MenuBar wallet actions work on any page.
 */
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { toast } from "sonner";
import {
  TransferModal,
  type TransferModalConfirmParams,
  WalletTransferModal,
  type WalletTransferConfirmParams,
  type WalletTransferAssetId,
  CrossChainModal,
  type CrossChainMode,
  type CrossChainConfirmParams,
} from "../components";
import { useOnboard } from "../hooks/useOnboard";
import { useBucketCollections } from "../hooks/useBucketCollections";
import { useFiClient } from "../hooks/useFiClient";
import { useEcoClient } from "../hooks/useEcoClient";
import { useSubscription } from "./SubscriptionContext";
import { createErrorCopyAction } from "../components/ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
  type ToastId,
} from "../components/ui/toastTask";
import { formatCurrency } from "../sdk/utils/display";
import { Bucket, getDisplayMarginType } from "../sdk";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import {
  getEffectiveMockBalance,
  applyDemoCrossChainSettlement,
  isBucketClosing,
  OFFLINE_CREATE_BUCKET_STABLE_TOAST_ID,
  type DemoCreateBucketResult,
} from "../../offline/mock_data";
import {
  assetSymbolToCollateralIndex,
  executeBucketCreateAndFund,
} from "../utils/executeBucketCreateAndFund";
import { executeOfflineBucketCreate } from "../utils/executeOfflineBucketCreate";
import type { CreateBucketFlowStep } from "../components/smartlayout/transfer-modal";
import {
  getChainsForAsset,
  getDefaultChainForAsset,
  isAllowedAssetChainPair,
  normalizeAssetChainSelection,
  type CrossChainOption,
} from "../constants/crossChain";
import { useCrossChainDemoOrchestrator } from "../hooks/useCrossChainDemoOrchestrator";
import {
  getActiveCrossChainTransfer,
} from "../stores/crossChainTransferStore";
import type { CrossChainTransferRecord } from "../types/crossChainFlow";
import { CrossChainHistoryPill } from "../components/smartlayout/cross-chain/CrossChainHistoryPill";
import { useOptionalDepositTour } from "../tutorials/deposit-tour";
import {
  DEPOSIT_TOUR_DEFAULT_ASSET,
  DEPOSIT_TOUR_DEFAULT_CHAIN,
  DEPOSIT_TOUR_DEFAULT_AMOUNT,
} from "../tutorials/deposit-tour/constants";
import { useOptionalCopyTour } from "../tutorials/copy-tour";

export interface TransferModalsContextValue {
  openBucketTransfer: (anchor?: HTMLElement) => void;
  openCoinTransfer: () => void;
  openCrossChainFlow: (mode: CrossChainMode) => void;
}

const TransferModalsContext = createContext<TransferModalsContextValue | undefined>(
  undefined,
);

export interface TransferModalsProviderProps {
  children: ReactNode;
  baseURL: string;
  refreshInterval?: number;
}

export function TransferModalsProvider({
  children,
  baseURL,
  refreshInterval = 5000,
}: TransferModalsProviderProps): JSX.Element {
  const depositTour = useOptionalDepositTour();
  const copyTour = useOptionalCopyTour();
  const { mnemonic, walletAddress, authToken: onboardAuthToken } = useOnboard(baseURL);
  const [sessionToken, setSessionToken] = useState(
    () => localStorage.getItem("authToken") || "",
  );

  useEffect(() => {
    setSessionToken(onboardAuthToken ?? "");
    if (onboardAuthToken) localStorage.setItem("authToken", onboardAuthToken);
    else localStorage.removeItem("authToken");
  }, [onboardAuthToken]);

  const isOfflineModeActive = isOfflineMode(baseURL);
  const { setAuthToken, setWalletAddress, client: subscriptionClient } =
    useSubscription();

  useEffect(() => {
    if (!isOfflineModeActive) setAuthToken(sessionToken || undefined);
  }, [isOfflineModeActive, sessionToken, setAuthToken]);

  useEffect(() => {
    if (!isOfflineModeActive) setWalletAddress(walletAddress || undefined);
  }, [isOfflineModeActive, walletAddress, setWalletAddress]);

  const { collections, spotWalletBalance, refreshBucketBalance, refreshSpotWalletBalance } =
    useBucketCollections({
      subscriptionClient: subscriptionClient ?? undefined,
      baseURL,
      authToken: sessionToken,
      walletAddress: walletAddress ?? "",
      refreshInterval,
    });

  const { client: exchangeClient, isReady: exchangeReady, error: exchangeError } =
    useFiClient({
      baseURL,
      mnemonic: mnemonic ?? "",
    });

  const { client: ecoClient, isReady: ecoReady, error: ecoError } = useEcoClient({
    baseURL,
    mnemonic: mnemonic ?? "",
  });

  const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
  const [transferAnchorEl, setTransferAnchorEl] = useState<HTMLElement | null>(
    null,
  );
  const [isMobileViewport, setIsMobileViewport] = useState(false);
  const [transferFrom, setTransferFrom] = useState<string>("");
  const [transferTo, setTransferTo] = useState<string>("");
  const [transferAmount, setTransferAmount] = useState<number>(10);
  const [createBucketAmount, setCreateBucketAmount] = useState<number>(10);
  const [createBucketAsset, setCreateBucketAsset] = useState<string>("");
  const [createMarginType, setCreateMarginType] = useState<"cross" | "isolated">(
    "cross",
  );
  const [transferMarginType, setTransferMarginType] = useState<
    "cross" | "isolated"
  >("cross");
  const [transferActiveTab, setTransferActiveTab] = useState<
    "transfer" | "create"
  >("transfer");
  const [isTransferring, setIsTransferring] = useState<boolean>(false);
  const [createBucketFlowStep, setCreateBucketFlowStep] =
    useState<CreateBucketFlowStep>("form");
  const [createBucketResult, setCreateBucketResult] =
    useState<DemoCreateBucketResult | null>(null);
  const [postCreateSpotBalance, setPostCreateSpotBalance] = useState<
    number | null
  >(null);
  const loadingToastIdRef = useRef<ToastId | null>(null);
  const [isWalletTransferModalOpen, setIsWalletTransferModalOpen] =
    useState(false);
  const [walletTransferTo, setWalletTransferTo] = useState("");
  const [walletTransferAsset, setWalletTransferAsset] =
    useState<WalletTransferAssetId>("USDC");
  const [walletTransferAmount, setWalletTransferAmount] = useState(10);
  const [walletTransferMemo, setWalletTransferMemo] = useState("");
  const [walletTransferBalance, setWalletTransferBalance] = useState(0);

  const [isCrossChainModalOpen, setIsCrossChainModalOpen] = useState(false);
  const [crossChainMode, setCrossChainMode] = useState<CrossChainMode>("deposit");
  const [crossChainAsset, setCrossChainAsset] =
    useState<WalletTransferAssetId>("USDC");
  const [crossChainAmount, setCrossChainAmount] = useState(10);
  const [crossChainChain, setCrossChainChain] = useState("");
  const [crossChainToAddress, setCrossChainToAddress] = useState("");
  const [crossChainBalance, setCrossChainBalance] = useState(0);
  const [historyPillRecord, setHistoryPillRecord] =
    useState<CrossChainTransferRecord | null>(() => getActiveCrossChainTransfer());
  const [chainOptions, setChainOptions] =
    useState<CrossChainOption[]>(getChainsForAsset("USDC"));
  const [isCrossChainSubmitting, setIsCrossChainSubmitting] = useState(false);
  const [crossChainSuccessBalance, setCrossChainSuccessBalance] = useState<
    number | null
  >(null);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 768px)");
    const syncMobile = () => setIsMobileViewport(mediaQuery.matches);
    syncMobile();
    mediaQuery.addEventListener("change", syncMobile);
    return () => mediaQuery.removeEventListener("change", syncMobile);
  }, []);

  useEffect(() => {
    if (exchangeError) {
      const msg = exchangeError.message;
      toast.error("Exchange client initialization failed", {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    }
  }, [exchangeError]);

  useEffect(() => {
    if (ecoError) {
      const msg = ecoError.message;
      toast.error("Eco client initialization failed", {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    }
  }, [ecoError]);

  const fetchWalletTransferBalance = useCallback(async () => {
    if (!walletAddress?.trim()) return;
    const available = isOfflineModeActive
      ? getEffectiveMockBalance(walletAddress, walletTransferAsset)
      : 0;
    setWalletTransferBalance(available);
  }, [walletAddress, walletTransferAsset, isOfflineModeActive]);

  useEffect(() => {
    if (isWalletTransferModalOpen && walletAddress?.trim()) {
      fetchWalletTransferBalance();
    }
  }, [
    isWalletTransferModalOpen,
    walletAddress,
    walletTransferAsset,
    fetchWalletTransferBalance,
  ]);

  const findDormantOrEmptyBucket = useCallback(
    (marginType: "cross" | "isolated", collateralAsset: string): Bucket | null => {
      const normalizedMarginType = marginType.toLowerCase();
      const normalizedAsset = collateralAsset.toUpperCase();
      const expectedIndex =
        normalizedAsset && String(assetSymbolToCollateralIndex(normalizedAsset));
      return (
        collections.find((bucket) => {
          const bucketMarginType = getDisplayMarginType(bucket)?.toLowerCase();
          const isDormant = bucket.status?.toLowerCase() === "dormant";
          const isEmpty = Number(bucket.totalEquity || 0) <= 0;
          const isClosing =
            isOfflineModeActive &&
            walletAddress?.trim() &&
            isBucketClosing(walletAddress, bucket.bucketId);
          const matchesMarginType = bucketMarginType === normalizedMarginType;
          const matchesCollateralAsset = expectedIndex
            ? bucket.collateralAssetIndex === expectedIndex
            : true;
          return (
            (isDormant || isEmpty) &&
            !isClosing &&
            matchesMarginType &&
            matchesCollateralAsset
          );
        }) || null
      );
    },
    [collections, isOfflineModeActive, walletAddress],
  );

  const resetCreateBucketFlow = useCallback(() => {
    setCreateBucketFlowStep("form");
    setCreateBucketResult(null);
    setPostCreateSpotBalance(null);
  }, []);

  const resetTransferForm = useCallback(() => {
    setTransferFrom("");
    setTransferTo("");
    setTransferAmount(10);
    setCreateBucketAmount(10);
    setCreateBucketAsset("");
    setCreateMarginType("cross");
    setTransferMarginType("cross");
    setTransferActiveTab("transfer");
    resetCreateBucketFlow();
  }, [resetCreateBucketFlow]);

  const resetWalletTransferForm = useCallback(() => {
    setWalletTransferTo("");
    setWalletTransferAsset("USDC");
    setWalletTransferAmount(10);
    setWalletTransferMemo("");
  }, []);

  const crossChainDemo = useCrossChainDemoOrchestrator((record) => {
    if (walletAddress?.trim()) {
      applyDemoCrossChainSettlement(walletAddress, {
        transferId: record.id,
        mode: record.mode,
        assetId: record.assetId,
        amount: record.amount,
      });
      setCrossChainSuccessBalance(
        getEffectiveMockBalance(walletAddress, record.assetId),
      );
    }
    void refreshSpotWalletBalance();
    refreshBucketBalance();
    setHistoryPillRecord(record);
  });

  const crossChainFlowStepRef = useRef(crossChainDemo.flowStep);
  crossChainFlowStepRef.current = crossChainDemo.flowStep;
  const crossChainModeRef = useRef(crossChainMode);
  crossChainModeRef.current = crossChainMode;
  const isCrossChainModalOpenRef = useRef(isCrossChainModalOpen);
  isCrossChainModalOpenRef.current = isCrossChainModalOpen;

  const resetCrossChainForm = useCallback((mode: CrossChainMode) => {
    const defaultAsset: WalletTransferAssetId = "USDC";
    setCrossChainMode(mode);
    setCrossChainAsset(defaultAsset);
    setCrossChainAmount(10);
    setCrossChainChain(getDefaultChainForAsset(defaultAsset));
    setChainOptions(getChainsForAsset(defaultAsset));
    setCrossChainToAddress("");
    setCrossChainSuccessBalance(null);
    crossChainDemo.resetFlow();
  }, [crossChainDemo]);

  const resetCrossChainModeFields = useCallback((mode: CrossChainMode) => {
    setCrossChainMode(mode);
    setCrossChainToAddress("");
    crossChainDemo.resetFlow();
  }, [crossChainDemo]);

  const requireWallet = useCallback((): boolean => {
    if (walletAddress?.trim()) return true;
    toast.error("Connect wallet first", {
      description: "Connect your wallet before transferring funds.",
    });
    return false;
  }, [walletAddress]);

  const openBucketTransfer = useCallback(
    (anchor?: HTMLElement) => {
      if (!requireWallet()) return;
      setTransferAnchorEl(anchor ?? null);
      setIsTransferModalOpen(true);
      resetTransferForm();
    },
    [requireWallet, resetTransferForm],
  );

  const openCoinTransfer = useCallback(() => {
    if (!requireWallet()) return;
    setIsWalletTransferModalOpen(true);
    resetWalletTransferForm();
  }, [requireWallet, resetWalletTransferForm]);

  const openCrossChainFlow = useCallback(
    (mode: CrossChainMode) => {
      if (!requireWallet()) return;
      resetCrossChainForm(mode);
      setIsCrossChainModalOpen(true);
    },
    [requireWallet, resetCrossChainForm],
  );

  const openDepositForTour = useCallback(() => {
    if (!requireWallet()) return;
    resetCrossChainForm("deposit");
    setCrossChainAsset(DEPOSIT_TOUR_DEFAULT_ASSET);
    setCrossChainAmount(DEPOSIT_TOUR_DEFAULT_AMOUNT);
    setCrossChainChain(DEPOSIT_TOUR_DEFAULT_CHAIN);
    setChainOptions(getChainsForAsset(DEPOSIT_TOUR_DEFAULT_ASSET));
    crossChainDemo.resetFlow();
    setIsCrossChainModalOpen(true);
  }, [requireWallet, resetCrossChainForm, crossChainDemo]);

  const openDepositForCopyTour = useCallback(
    (amount: number) => {
      if (!requireWallet()) return;
      resetCrossChainForm("deposit");
      setCrossChainAsset(DEPOSIT_TOUR_DEFAULT_ASSET);
      setCrossChainAmount(Math.max(1, Math.round(amount)));
      setCrossChainChain(DEPOSIT_TOUR_DEFAULT_CHAIN);
      setChainOptions(getChainsForAsset(DEPOSIT_TOUR_DEFAULT_ASSET));
      crossChainDemo.resetFlow();
      setIsCrossChainModalOpen(true);
    },
    [requireWallet, resetCrossChainForm, crossChainDemo],
  );

  useEffect(() => {
    if (!depositTour?.registerOpenDepositForTour) return;
    return depositTour.registerOpenDepositForTour(openDepositForTour);
  }, [depositTour?.registerOpenDepositForTour, openDepositForTour]);

  useEffect(() => {
    if (!copyTour?.registerOpenDepositForCopyTour) return;
    return copyTour.registerOpenDepositForCopyTour(openDepositForCopyTour);
  }, [copyTour?.registerOpenDepositForCopyTour, openDepositForCopyTour]);

  useEffect(() => {
    if (crossChainDemo.flowStep !== "success" || crossChainMode !== "deposit") {
      return;
    }
    copyTour?.onDepositCompleteForCopyTour();
  }, [copyTour, crossChainDemo.flowStep, crossChainMode]);

  useEffect(() => {
    if (!depositTour?.registerFlowState) return;
    return depositTour.registerFlowState(() => ({
      flowStep: isOfflineModeActive ? crossChainFlowStepRef.current : "form",
      mode: crossChainModeRef.current,
      isCrossChainModalOpen: isCrossChainModalOpenRef.current,
    }));
  }, [depositTour?.registerFlowState, isOfflineModeActive]);

  const fetchCrossChainBalance = useCallback(async () => {
    if (!walletAddress?.trim()) return;
    const available = isOfflineModeActive
      ? getEffectiveMockBalance(walletAddress, crossChainAsset)
      : 0;
    setCrossChainBalance(available);
  }, [walletAddress, crossChainAsset, isOfflineModeActive]);

  const handleCrossChainOpen = useCallback(async () => {
    refreshBucketBalance();
    setChainOptions(getChainsForAsset(crossChainAsset));
    setCrossChainChain((current) =>
      normalizeAssetChainSelection(crossChainAsset, current),
    );
    await fetchCrossChainBalance();
  }, [refreshBucketBalance, crossChainAsset, fetchCrossChainBalance]);

  const handleCrossChainAssetChange = useCallback((asset: WalletTransferAssetId) => {
    setCrossChainAsset(asset);
    setChainOptions(getChainsForAsset(asset));
    setCrossChainChain((current) => normalizeAssetChainSelection(asset, current));
  }, []);

  useEffect(() => {
    if (isCrossChainModalOpen && walletAddress?.trim()) {
      fetchCrossChainBalance();
    }
  }, [
    isCrossChainModalOpen,
    walletAddress,
    crossChainAsset,
    fetchCrossChainBalance,
  ]);

  const handleTransferCancel = useCallback(() => {
    setIsTransferModalOpen(false);
    setTransferAnchorEl(null);
    resetTransferForm();
  }, [resetTransferForm]);

  const handleCreateBucketDone = useCallback(() => {
    setIsTransferModalOpen(false);
    setTransferAnchorEl(null);
    resetTransferForm();
  }, [resetTransferForm]);

  const handleCreateAnotherBucket = useCallback(() => {
    resetCreateBucketFlow();
    setCreateBucketAmount(10);
    setCreateBucketAsset("");
    setCreateMarginType("cross");
    setTransferActiveTab("create");
  }, [resetCreateBucketFlow]);

  const handleWalletTransferCancel = useCallback(() => {
    setIsWalletTransferModalOpen(false);
    resetWalletTransferForm();
  }, [resetWalletTransferForm]);

  const handleCrossChainCancel = useCallback(() => {
    if (
      crossChainDemo.flowStep === "tracking" &&
      crossChainDemo.transferRecord
    ) {
      setHistoryPillRecord(crossChainDemo.transferRecord);
      setIsCrossChainModalOpen(false);
      return;
    }
    if (depositTour?.runTour) {
      depositTour.stopTour();
    }
    copyTour?.cancelDepositHandoff();
    setIsCrossChainModalOpen(false);
    resetCrossChainForm(crossChainMode);
  }, [crossChainDemo, resetCrossChainForm, crossChainMode, depositTour, copyTour]);

  const handleCrossChainModeChange = useCallback(
    (mode: CrossChainMode) => {
      if (depositTour?.runTour && mode !== "deposit") {
        depositTour.stopTour();
        toast.info("Deposit tour ended — stay on Deposit to finish the guided flow.");
      }
      resetCrossChainModeFields(mode);
    },
    [depositTour, resetCrossChainModeFields],
  );

  const handleCrossChainFundBucket = useCallback(() => {
    setIsCrossChainModalOpen(false);
    crossChainDemo.resetFlow();
    void refreshSpotWalletBalance();
    if (depositTour?.runTour) {
      depositTour.onTourComplete();
    }
    openBucketTransfer();
  }, [crossChainDemo, openBucketTransfer, refreshSpotWalletBalance, depositTour]);

  const handleCrossChainNewTransfer = useCallback(() => {
    crossChainDemo.resetFlow();
    setHistoryPillRecord(null);
    setCrossChainSuccessBalance(null);
  }, [crossChainDemo]);

  const handleHistoryPillClick = useCallback(() => {
    if (!historyPillRecord) return;
    if (
      walletAddress?.trim() &&
      (historyPillRecord.completedAt ||
        historyPillRecord.currentStage === "complete")
    ) {
      setCrossChainSuccessBalance(
        getEffectiveMockBalance(walletAddress, historyPillRecord.assetId),
      );
    }
    crossChainDemo.reopenTracking(historyPillRecord);
    setIsCrossChainModalOpen(true);
  }, [historyPillRecord, crossChainDemo, walletAddress]);

  useEffect(() => {
    if (crossChainDemo.transferRecord && crossChainDemo.flowStep === "tracking") {
      setHistoryPillRecord(crossChainDemo.transferRecord);
    }
  }, [crossChainDemo.transferRecord, crossChainDemo.flowStep]);

  const handleWalletTransferConfirm = useCallback(
    async (params: WalletTransferConfirmParams) => {
      if (!mnemonic) {
        toast.error("Mnemonic required", {
          description: "Mnemonic is required to perform transfers.",
          action: createErrorCopyAction("Mnemonic required"),
        });
        return;
      }
      if (!exchangeClient || !exchangeReady) {
        toast.error("Exchange client not ready", {
          description: "Please wait for the exchange client to initialize.",
          action: createErrorCopyAction("Exchange client not ready"),
        });
        return;
      }
      setIsTransferring(true);
      const loadingId = toastLoading("Processing transfer...", {
        description: "Sending tokens to address",
      });
      loadingToastIdRef.current = loadingId;
      try {
        const result = await exchangeClient.bankTransfer({
          to: params.to,
          assetId: params.assetId,
          amount: params.amount,
          memo: params.memo,
        });
        loadingToastIdRef.current = null;
        if (result.success) {
          toastCompleteSuccess(loadingId, "Transfer completed", {
            description: `Successfully sent ${formatCurrency(params.amount)} ${params.assetId} to ${params.to.slice(0, 10)}...${result.txhash ? `\ntxhash: ${result.txhash}` : ""}`,
          });
          setIsWalletTransferModalOpen(false);
          resetWalletTransferForm();
          refreshBucketBalance();
        } else {
          toastCompleteError(loadingId, "Transfer failed", {
            description: result.errorMessage ?? "Unknown error",
            action: createErrorCopyAction(result.errorMessage ?? ""),
          });
        }
      } catch (err) {
        loadingToastIdRef.current = null;
        const msg = err instanceof Error ? err.message : "Transfer failed";
        toastCompleteError(loadingId, "Transfer failed", {
          description: msg,
          action: createErrorCopyAction(msg),
        });
      } finally {
        setIsTransferring(false);
      }
    },
    [
      mnemonic,
      exchangeClient,
      exchangeReady,
      refreshBucketBalance,
      resetWalletTransferForm,
    ],
  );

  const handleCrossChainConfirm = useCallback(
    async (params: CrossChainConfirmParams) => {
      if (!walletAddress?.trim()) return;

      const actionLabel = params.mode === "deposit" ? "Deposit" : "Withdraw";
      setIsCrossChainSubmitting(true);
      const loadingId = toastLoading(`Processing ${actionLabel.toLowerCase()}...`, {
        description: "Please wait while the operation is being processed",
      });
      loadingToastIdRef.current = loadingId;

      try {
        if (!isAllowedAssetChainPair(params.assetId, params.chain)) {
          loadingToastIdRef.current = null;
          toastCompleteError(loadingId, `${actionLabel} failed`, {
            description: "Selected chain is not supported for this asset.",
            action: createErrorCopyAction("Unsupported asset-chain pair"),
          });
          return;
        }

        if (isOfflineModeActive) {
          crossChainDemo.confirmReview(params);
          loadingToastIdRef.current = null;
          return;
        }

        if (!mnemonic) {
          loadingToastIdRef.current = null;
          toastCompleteError(loadingId, `${actionLabel} failed`, {
            description: "Mnemonic is required to perform this operation.",
            action: createErrorCopyAction("Mnemonic required"),
          });
          return;
        }
        if (!ecoClient || !ecoReady) {
          loadingToastIdRef.current = null;
          toastCompleteError(loadingId, `${actionLabel} failed`, {
            description: "Please wait for the eco client to initialize.",
            action: createErrorCopyAction("Eco client not ready"),
          });
          return;
        }

        if (params.mode === "deposit") {
          const result = await ecoClient.deposit({
            to: walletAddress,
            amount: params.amount,
            assetId: params.assetId,
            source_chain: params.chain,
          });
          toastCompleteSuccess(loadingId, "Deposit completed", {
            description: `Successfully deposited ${formatCurrency(params.amount)} ${params.assetId} from ${params.chain}${result.txhash ? `\ntxhash: ${result.txhash}` : ""}`,
          });
        } else {
          const result = await ecoClient.withdraw({
            from: walletAddress,
            to: params.toAddress,
            amount: params.amount,
            assetId: params.assetId,
            destination_chain: params.chain,
          });
          toastCompleteSuccess(loadingId, "Withdraw completed", {
            description: `Successfully withdrew ${formatCurrency(params.amount)} ${params.assetId} to ${params.chain}${result.txhash ? `\ntxhash: ${result.txhash}` : ""}`,
          });
        }

        loadingToastIdRef.current = null;
        setIsCrossChainModalOpen(false);
        resetCrossChainForm(params.mode);
        refreshBucketBalance();
      } catch (err) {
        loadingToastIdRef.current = null;
        const msg = err instanceof Error ? err.message : `${actionLabel} failed`;
        toastCompleteError(loadingId, `${actionLabel} failed`, {
          description: msg,
          action: createErrorCopyAction(msg),
        });
      } finally {
        setIsCrossChainSubmitting(false);
      }
    },
    [
      walletAddress,
      isOfflineModeActive,
      mnemonic,
      ecoClient,
      ecoReady,
      refreshBucketBalance,
      resetCrossChainForm,
      crossChainDemo,
    ],
  );

  const handleTransferConfirm = useCallback(
    async (params: TransferModalConfirmParams) => {
      if (params.type === "create" && isOfflineModeActive) {
        if (!walletAddress?.trim()) return;
        setIsTransferring(true);
        setCreateBucketFlowStep("processing");
        const toastId = toastLoading("Creating bucket…", {
          stableId: OFFLINE_CREATE_BUCKET_STABLE_TOAST_ID,
          description: "Signing transaction…",
        });
        loadingToastIdRef.current = toastId;

        try {
          const { from, collateralAsset, marginType, amount } = params;
          const sourceBucket =
            from !== "spot-wallet"
              ? collections.find((bucket) => bucket.bucketId === from)
              : null;

          const result = await executeOfflineBucketCreate(
            {
              wallet: walletAddress,
              marginType,
              collateralAsset,
              amount,
              fundFrom: from,
              sourceBucketBaseEquity: sourceBucket
                ? Number(sourceBucket.totalEquity || 0)
                : undefined,
              reuseEmptyBucket: findDormantOrEmptyBucket,
            },
            {
              onStepStart: (step) => {
                toastUpdateLoading(toastId, step.loadingMessage, {
                  description: step.loadingDescription,
                });
              },
            },
          );

          toastCompleteSuccess(toastId, "Bucket created", {
            description: `${result.bucketMode === "reused" ? "Reused" : "Created"} ${result.marginType} bucket · ${result.bucketId.slice(0, 10)}…`,
          });
          loadingToastIdRef.current = null;
          setCreateBucketResult(result);
          setPostCreateSpotBalance(
            getEffectiveMockBalance(walletAddress, collateralAsset),
          );
          refreshBucketBalance();
          setCreateBucketFlowStep("success");
        } catch (err) {
          loadingToastIdRef.current = null;
          const errorMessage =
            err instanceof Error ? err.message : "Failed to create bucket";
          toastCompleteError(toastId, "Create bucket failed", {
            description: errorMessage,
            action: createErrorCopyAction(errorMessage),
          });
          setCreateBucketFlowStep("form");
        } finally {
          setIsTransferring(false);
        }
        return;
      }

      if (!mnemonic) return;
      if (!exchangeClient || !exchangeReady) return;
      setIsTransferring(true);
      const loadingId = toastLoading("Processing transfer...", {
        description: "Please wait while the transfer is being processed",
      });
      loadingToastIdRef.current = loadingId;
      try {
        const assetId = "USDC";
        let result;
        let successMessage = "";
        if (params.type === "transfer") {
          const { from, to, amount } = params;
          if (from === "spot-wallet" && to === "spot-wallet") {
            throw new Error("Cannot transfer from spot wallet to spot wallet");
          }
          if (from === "spot-wallet") {
            if (!to || to === "spot-wallet") {
              throw new Error("Please select a destination bucket");
            }
            result = await exchangeClient.extractToBucket({
              bucketId: to,
              assetId,
              amount,
            });
            if (!result.success) return;
            successMessage = `Successfully transferred ${formatCurrency(amount)} from Spot Wallet to ${to}`;
          } else if (to === "spot-wallet") {
            result = await exchangeClient.withdrawFromBucket({
              bucketId: from,
              assetId,
              amount,
            });
            if (!result.success) return;
            successMessage = `Successfully transferred ${formatCurrency(amount)} from ${from} to Spot Wallet`;
          } else {
            if (!to) throw new Error("Please select a destination bucket");
            result = await exchangeClient.bucketTransfer({
              fromBucketId: from,
              toBucketId: to,
              assetId,
              amount,
            });
            if (!result.success) return;
            successMessage = `Successfully transferred ${formatCurrency(amount)} from ${from} to ${to}`;
          }
        } else {
          const { from, collateralAsset, marginType, amount } = params;
          const targetBucketId = await executeBucketCreateAndFund({
            exchangeClient,
            marginType,
            collateralAsset,
            amount,
            fundFrom: from,
            reuseEmptyBucket: findDormantOrEmptyBucket,
          });
          successMessage = `Successfully created bucket ${targetBucketId}${
            amount > 0 ? ` with ${formatCurrency(amount)} ${collateralAsset}` : ""
          }`;
        }
        loadingToastIdRef.current = null;
        toastCompleteSuccess(loadingId, "Transfer completed", {
          description: successMessage,
        });
        setIsTransferModalOpen(false);
        setTransferAnchorEl(null);
        await new Promise((resolve) => setTimeout(resolve, 1000));
        refreshBucketBalance();
      } catch (err) {
        loadingToastIdRef.current = null;
        const errorMessage =
          err instanceof Error ? err.message : "Transfer failed";
        toastCompleteError(loadingId, "Transfer failed", {
          description: errorMessage,
          action: createErrorCopyAction(errorMessage),
        });
      } finally {
        setIsTransferring(false);
      }
    },
    [
      walletAddress,
      isOfflineModeActive,
      collections,
      findDormantOrEmptyBucket,
      mnemonic,
      exchangeClient,
      exchangeReady,
      refreshBucketBalance,
    ],
  );

  const transferOptions = useMemo(() => {
    const bucketOptions = collections
      .filter((c) => c?.bucketId && c.bucketId.trim() !== "")
      .map((collection) => ({
        value: collection.bucketId,
        label: `${collection.bucketId} (${formatCurrency(collection.totalEquity)})`,
      }));
    return [
      {
        value: "spot-wallet",
        label: `Spot Wallet (${formatCurrency(spotWalletBalance)})`,
      },
      ...bucketOptions,
    ];
  }, [collections, spotWalletBalance]);

  const bucketsData = useMemo(
    () =>
      collections
        .filter((c) => c?.bucketId && c.bucketId.trim() !== "")
        .map((collection) => ({
          bucketId: collection.bucketId,
          totalEquity: collection.totalEquity,
        })),
    [collections],
  );

  const contextValue = useMemo(
    () => ({ openBucketTransfer, openCoinTransfer, openCrossChainFlow }),
    [openBucketTransfer, openCoinTransfer, openCrossChainFlow],
  );

  return (
    <TransferModalsContext.Provider value={contextValue}>
      {children}
      <TransferModal
        isOpen={isTransferModalOpen}
        anchorEl={transferAnchorEl}
        preferCentered={isMobileViewport}
        fromValue={transferFrom}
        toValue={transferTo}
        options={transferOptions}
        bucketsData={bucketsData}
        transferAmount={transferAmount}
        createBucketAmount={createBucketAmount}
        createBucketAsset={createBucketAsset}
        createMarginType={createMarginType}
        transferMarginType={transferMarginType}
        onFromChange={setTransferFrom}
        onToChange={setTransferTo}
        onTransferAmountChange={setTransferAmount}
        onCreateBucketAmountChange={setCreateBucketAmount}
        onCreateBucketAssetChange={setCreateBucketAsset}
        onCreateMarginTypeChange={setCreateMarginType}
        onTransferMarginTypeChange={setTransferMarginType}
        onConfirm={handleTransferConfirm}
        onCancel={handleTransferCancel}
        spotWalletBalance={spotWalletBalance}
        activeTab={transferActiveTab}
        onActiveTabChange={setTransferActiveTab}
        isTransferring={isTransferring}
        onOpen={refreshBucketBalance}
        collections={collections.map((c) => ({
          bucketId: c.bucketId,
          marginType: c.marginType,
        }))}
        createBucketFlowStep={createBucketFlowStep}
        createBucketResult={createBucketResult}
        postCreateSpotBalance={postCreateSpotBalance}
        onCreateBucketDone={handleCreateBucketDone}
        onCreateAnotherBucket={handleCreateAnotherBucket}
      />
      <WalletTransferModal
        isOpen={isWalletTransferModalOpen}
        toAddress={walletTransferTo}
        assetId={walletTransferAsset}
        amount={walletTransferAmount}
        availableBalance={walletTransferBalance}
        onToAddressChange={setWalletTransferTo}
        onAssetChange={setWalletTransferAsset}
        onAmountChange={setWalletTransferAmount}
        onConfirm={handleWalletTransferConfirm}
        onCancel={handleWalletTransferCancel}
        isTransferring={isTransferring}
        onOpen={fetchWalletTransferBalance}
        memo={walletTransferMemo}
        onMemoChange={setWalletTransferMemo}
      />
      <CrossChainModal
        isOpen={isCrossChainModalOpen}
        mode={crossChainMode}
        flowStep={isOfflineModeActive ? crossChainDemo.flowStep : "form"}
        walletAddress={walletAddress ?? ""}
        assetId={crossChainAsset}
        amount={crossChainAmount}
        chain={crossChainChain}
        toAddress={crossChainToAddress}
        availableBalance={crossChainBalance}
        chainOptions={chainOptions}
        transferRecord={crossChainDemo.transferRecord}
        isSimulatingSignature={crossChainDemo.isSimulatingSignature}
        validatorCount={crossChainDemo.validatorCount}
        showDemoHelper={isOfflineModeActive}
        newBalance={crossChainSuccessBalance}
        onModeChange={handleCrossChainModeChange}
        onAssetChange={handleCrossChainAssetChange}
        onAmountChange={setCrossChainAmount}
        onChainChange={setCrossChainChain}
        onToAddressChange={setCrossChainToAddress}
        onGoToReview={crossChainDemo.goToReview}
        onBackToForm={crossChainDemo.goBackToForm}
        onConfirmReview={
          isOfflineModeActive
            ? crossChainDemo.confirmReview
            : handleCrossChainConfirm
        }
        onSimulateAuthorize={crossChainDemo.simulateAuthorize}
        onSimulateSubmit={crossChainDemo.simulateSubmit}
        onRetryFromFailure={crossChainDemo.retryFromFailure}
        onKeepPollingFromFailure={crossChainDemo.keepPollingFromFailure}
        onNewTransfer={handleCrossChainNewTransfer}
        onFundBucket={handleCrossChainFundBucket}
        onPreviewFailure={crossChainDemo.previewFailure}
        onFailOnNextConfirm={crossChainDemo.setFailOnNextConfirm}
        onCancel={handleCrossChainCancel}
        onOpen={handleCrossChainOpen}
      />
      {isOfflineModeActive &&
        historyPillRecord &&
        !isCrossChainModalOpen && (
          <CrossChainHistoryPill
            record={historyPillRecord}
            validatorCount={crossChainDemo.validatorCount}
            onClick={handleHistoryPillClick}
          />
        )}
    </TransferModalsContext.Provider>
  );
}

export function useTransferModals(): TransferModalsContextValue {
  const ctx = useContext(TransferModalsContext);
  if (!ctx) {
    throw new Error("useTransferModals must be used within TransferModalsProvider");
  }
  return ctx;
}
