import React, { useEffect, useMemo, useState } from "react";
import QRCode from "qrcode";

import MorpheumLogo from "../../ui/MorpheumLogo";
import {
  buildCompareShareUrl,
  SHARE_CARD_WIDTH_PX,
  type AgentCompareSharePayload,
} from "./agentCompareShareData";
import "../../index/share/indexShare.css";
import "./agentCompareShare.css";

export interface AgentCompareShareCardProps {
  payload: AgentCompareSharePayload;
}

function AgentCompareShareCard({
  payload,
}: AgentCompareShareCardProps): JSX.Element {
  const { agents, focusLabel, focusHint, metricRows, timestamp } = payload;
  const [qrDataUrl, setQrDataUrl] = useState("");

  const shareUrl = useMemo(
    () => buildCompareShareUrl(payload.compareIds),
    [payload.compareIds],
  );

  useEffect(() => {
    let cancelled = false;
    QRCode.toDataURL(shareUrl, {
      margin: 1,
      width: 96,
      color: {
        dark: "#c8f5a8",
        light: "#05070d",
      },
    })
      .then((url) => {
        if (!cancelled) setQrDataUrl(url);
      })
      .catch(() => {
        if (!cancelled) setQrDataUrl("");
      });
    return () => {
      cancelled = true;
    };
  }, [shareUrl]);

  return (
    <article
      className="index-share-card agent-compare-share-card"
      style={{ width: SHARE_CARD_WIDTH_PX }}
      aria-label="Agent compare share card"
    >
      <div className="index-share-card-frame" aria-hidden />

      <header className="index-share-card-brand">
        <MorpheumLogo width={48} height={29} fill="#C8F5A8" />
        <p className="index-share-card-tagline">
          Agent-optimized trading for the onchain economy
        </p>
      </header>

      <div className="index-share-card-title-block">
        <h2 className="index-share-card-title">Agent Compare</h2>
        <span className="index-share-card-mode">
          {focusLabel} · {focusHint}
        </span>
      </div>

      <div
        className="agent-compare-share-agents"
        style={{
          gridTemplateColumns: `repeat(${Math.max(agents.length, 1)}, minmax(0, 1fr))`,
        }}
      >
        {agents.map((agent) => (
          <div key={agent.id} className="agent-compare-share-agent">
            <span className="agent-compare-share-agent-avatar" aria-hidden>
              <span
                className="agent-compare-share-agent-avatar-image"
                style={{
                  maskImage: `url(${agent.avatarSrc})`,
                  WebkitMaskImage: `url(${agent.avatarSrc})`,
                }}
              />
            </span>
            <strong className="agent-compare-share-agent-name">{agent.name}</strong>
            <span className="agent-compare-share-agent-meta">
              {agent.ticker} · {agent.strategy}
            </span>
          </div>
        ))}
      </div>

      {metricRows.length > 0 ? (
        <>
          <hr className="index-share-divider" />
          <table className="agent-compare-share-metrics">
            <thead>
              <tr>
                <th scope="col">Metric</th>
                {agents.map((agent) => (
                  <th key={agent.id} scope="col">
                    {agent.ticker}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {metricRows.map((row) => (
                <tr key={row.label}>
                  <th scope="row">{row.label}</th>
                  {row.cells.slice(0, agents.length).map((cell, index) => (
                    <td key={`${row.label}-${index}`}>
                      {cell ? (
                        cell.listItems && cell.listItems.length > 0 ? (
                          <ul className="agent-compare-share-metric-list">
                            {cell.listItems.map((item) => (
                              <li key={item}>{item}</li>
                            ))}
                          </ul>
                        ) : (
                          <span
                            className={[
                              "agent-compare-share-metric-value",
                              cell.tone ?? "",
                              cell.isBest ? "agent-compare-share-metric-value--best" : "",
                            ]
                              .filter(Boolean)
                              .join(" ")}
                          >
                            {cell.value}
                          </span>
                        )
                      ) : (
                        <span className="agent-compare-share-metric-empty">—</span>
                      )}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </>
      ) : null}

      <footer className="index-share-card-footer">
        <div className="index-share-card-footer-copy">
          <p className="index-share-footer-cta">
            Compare trading agents side-by-side on Morpheum — pick your lens and
            decide.
          </p>
          <p className="index-share-footer-url">{shareUrl}</p>
          <p className="index-share-footer-time">{timestamp}</p>
        </div>
        {qrDataUrl ? (
          <img
            className="index-share-qr"
            src={qrDataUrl}
            alt="QR code for agent compare link"
            width={96}
            height={96}
          />
        ) : null}
      </footer>
    </article>
  );
}

export default AgentCompareShareCard;
