import {
  DEFAULT_AGENT_SETTINGS,
  type AgentEnvVar,
  type AgentSettingsState,
  type AgentSkill,
  type McpServer,
} from "./agentSettingsTypes";

const STORAGE_PREFIX = "morpheum:agentSettings:";

export function agentSettingsStorageKey(catalogAgentId: string): string {
  return `${STORAGE_PREFIX}${catalogAgentId.trim().toLowerCase()}`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function normalizeSkillFile(raw: unknown): AgentSkill["files"][number] | null {
  if (!isRecord(raw)) return null;
  const path = typeof raw.path === "string" ? raw.path.trim() : "";
  const content = typeof raw.content === "string" ? raw.content : "";
  const kind = raw.kind;
  if (!path) return null;
  if (kind !== "skill" && kind !== "reference" && kind !== "resource") return null;
  return { path, kind, content };
}

function normalizeSkill(raw: unknown): AgentSkill | null {
  if (!isRecord(raw)) return null;
  const id = typeof raw.id === "string" ? raw.id.trim() : "";
  const name = typeof raw.name === "string" ? raw.name.trim() : "";
  const description = typeof raw.description === "string" ? raw.description : "";
  const installedAt = typeof raw.installedAt === "string" ? raw.installedAt : "";
  const source = raw.source === "catalog" || raw.source === "custom" ? raw.source : null;
  const filesRaw = Array.isArray(raw.files) ? raw.files : [];
  const files = filesRaw
    .map(normalizeSkillFile)
    .filter((file): file is AgentSkill["files"][number] => file !== null);
  if (!id || !name || !installedAt || !source || files.length === 0) return null;
  const catalogId =
    typeof raw.catalogId === "string" && raw.catalogId.trim()
      ? raw.catalogId.trim()
      : undefined;
  return { id, catalogId, name, description, files, installedAt, source };
}

function normalizeEnvVar(raw: unknown): AgentEnvVar | null {
  if (!isRecord(raw)) return null;
  const id = typeof raw.id === "string" ? raw.id.trim() : "";
  const key = typeof raw.key === "string" ? raw.key.trim() : "";
  const value = typeof raw.value === "string" ? raw.value : "";
  const scope =
    raw.scope === "agentTools" || raw.scope === "x402Endpoints" ? raw.scope : null;
  if (!id || !key || !scope) return null;
  return { id, key, value, scope };
}

function normalizeMcpHeader(raw: unknown): McpServer["headers"][number] | null {
  if (!isRecord(raw)) return null;
  const name = typeof raw.name === "string" ? raw.name.trim() : "";
  const value = typeof raw.value === "string" ? raw.value : "";
  if (!name) return null;
  return { name, value };
}

function normalizeMcpServer(raw: unknown): McpServer | null {
  if (!isRecord(raw)) return null;
  const id = typeof raw.id === "string" ? raw.id.trim() : "";
  const name = typeof raw.name === "string" ? raw.name.trim() : "";
  const url = typeof raw.url === "string" ? raw.url.trim() : "";
  const transport =
    raw.transport === "streamableHttp" || raw.transport === "sse"
      ? raw.transport
      : null;
  const createdAt = typeof raw.createdAt === "string" ? raw.createdAt : "";
  const headersRaw = Array.isArray(raw.headers) ? raw.headers : [];
  const headers = headersRaw
    .map(normalizeMcpHeader)
    .filter((header): header is McpServer["headers"][number] => header !== null);
  if (!id || !name || !url || !transport || !createdAt) return null;
  return { id, name, url, transport, headers, createdAt };
}

export function normalizeAgentSettings(raw: unknown): AgentSettingsState {
  if (!isRecord(raw)) return { ...DEFAULT_AGENT_SETTINGS };

  const skills = (Array.isArray(raw.skills) ? raw.skills : [])
    .map(normalizeSkill)
    .filter((skill): skill is AgentSkill => skill !== null);
  const envVars = (Array.isArray(raw.envVars) ? raw.envVars : [])
    .map(normalizeEnvVar)
    .filter((envVar): envVar is AgentEnvVar => envVar !== null);
  const mcpServers = (Array.isArray(raw.mcpServers) ? raw.mcpServers : [])
    .map(normalizeMcpServer)
    .filter((server): server is McpServer => server !== null);

  return { skills, envVars, mcpServers };
}

export function loadAgentSettings(catalogAgentId: string): AgentSettingsState {
  if (typeof window === "undefined") return { ...DEFAULT_AGENT_SETTINGS };
  try {
    const raw = localStorage.getItem(agentSettingsStorageKey(catalogAgentId));
    if (!raw) return { ...DEFAULT_AGENT_SETTINGS };
    return normalizeAgentSettings(JSON.parse(raw));
  } catch {
    return { ...DEFAULT_AGENT_SETTINGS };
  }
}

export function saveAgentSettings(
  catalogAgentId: string,
  state: AgentSettingsState,
): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(
      agentSettingsStorageKey(catalogAgentId),
      JSON.stringify(state),
    );
  } catch {
    // ignore quota / private mode
  }
}

export function isCatalogSkillInstalled(
  state: AgentSettingsState,
  catalogId: string,
): boolean {
  return state.skills.some((skill) => skill.catalogId === catalogId);
}
