import { useEffect, useMemo, useState } from "react";

import {
  getIndexProfileBySlug,
  getIndexRowBySlug,
} from "../../offline/mock_data";
import type { PropertyIndexMode } from "../../offline/mock_data/types";
import { useSettings } from "../context/SettingsContext";
import {
  resolveConstituentsForMode,
  resolveConstituentsUnion,
} from "../utils/indexConstituents";

export function useIndexPageData(baseAsset: string) {
  const { settings } = useSettings();
  const profile = getIndexProfileBySlug(baseAsset)!;
  const row = getIndexRowBySlug(baseAsset)!;
  const [activeMode, setActiveMode] = useState<PropertyIndexMode["id"]>(
    settings.index.defaultMode,
  );

  useEffect(() => {
    setActiveMode(settings.index.defaultMode);
  }, [settings.index.defaultMode]);

  const nav = profile.pricing.nav;
  const price = profile.pricing.price;

  const constituents = useMemo(
    () => resolveConstituentsForMode(profile, activeMode),
    [profile, activeMode],
  );

  const xPulseConstituents = useMemo(
    () => resolveConstituentsUnion(profile),
    [profile],
  );

  const activeModeMeta = useMemo(
    () => profile.modes.find((mode) => mode.id === activeMode),
    [profile.modes, activeMode],
  );

  return {
    profile,
    row,
    activeMode,
    setActiveMode,
    activeModeMeta,
    constituents,
    xPulseConstituents,
    nav,
    price,
    chartSeries: profile.chartSeries,
    tabCopy: profile.tabCopy,
    performanceMetrics: profile.performanceMetrics,
  };
}

export type IndexPageData = ReturnType<typeof useIndexPageData>;
