import React from "react";
import InfoTip from "./InfoTip";
import Sparkline from "./Sparkline";
import StatusDot, { type Status } from "./StatusDot";
import { resolveSeriesColor, type SeriesColorToken } from "./colorTokens";

export interface KpiCardProps {
  label: string;
  value: React.ReactNode;
  unit?: string;
  hint?: string;
  info?: React.ReactNode;
  status?: Status;
  series?: number[];
  seriesColor?: SeriesColorToken;
}

export default function KpiCard({
  label,
  value,
  unit,
  hint,
  info,
  status,
  series,
  seriesColor,
}: KpiCardProps): React.JSX.Element {
  return (
    <article className="nh-kpi-card">
      <div className="nh-kpi-card-header">
        <span className="nh-kpi-label terminal-label">
          {label}
          {info ? <InfoTip label={label}>{info}</InfoTip> : null}
        </span>
        {status ? <StatusDot status={status} /> : null}
      </div>
      <div className="nh-kpi-value-row">
        <span className="nh-kpi-value terminal-value">{value}</span>
        {unit ? <span className="nh-kpi-unit">{unit}</span> : null}
      </div>
      {series && series.length > 1 ? (
        <Sparkline
          values={series}
          className="nh-kpi-sparkline"
          height={28}
          stroke={seriesColor ? resolveSeriesColor(seriesColor) : undefined}
        />
      ) : null}
      {hint ? <span className="nh-kpi-hint">{hint}</span> : null}
    </article>
  );
}
