import { useEffect, useRef, useState } from "react";
import type { IntentArchetype } from "../intentBreakdown";

export interface UseIntentMorphOptions {
  wireframe: IntentArchetype | null;
  validated: boolean;
  stickyArchetype?: IntentArchetype;
}

export interface UseIntentMorphResult {
  displayedArchetype: IntentArchetype | null;
  morphKey: string;
}

const STICKY_THRESHOLD = 0.6;

export function useIntentMorph({
  wireframe,
  validated,
  stickyArchetype,
}: UseIntentMorphOptions): UseIntentMorphResult {
  const [displayed, setDisplayed] = useState<IntentArchetype | null>(null);
  const lastValidatedRef = useRef(false);

  useEffect(() => {
    if (!validated) {
      lastValidatedRef.current = false;
      return;
    }

    const archetype = stickyArchetype ?? wireframe;
    if (!archetype || archetype === "unsupported") return;

    if (!lastValidatedRef.current) {
      setDisplayed(archetype);
      lastValidatedRef.current = true;
      return;
    }

    if (stickyArchetype) {
      setDisplayed(stickyArchetype);
    } else if (wireframe && wireframe !== displayed) {
      setDisplayed(wireframe);
    }
  }, [validated, wireframe, stickyArchetype, displayed]);

  return {
    displayedArchetype: stickyArchetype ?? displayed ?? wireframe,
    morphKey: `${stickyArchetype ?? displayed ?? wireframe ?? "none"}`,
  };
}

export { STICKY_THRESHOLD };
