import type {
  IChartApiBase,
  ISeriesApi,
  Time,
} from "lightweight-charts";
import type {
  ChartPendingOrderLine,
  ChartPendingOrderLineMeta,
} from "./chartOrderLines";

export function resolveLinePrice(
  line: ChartPendingOrderLine,
  priceOverrides?: ReadonlyMap<string, number>,
): number {
  return priceOverrides?.get(line.lineId) ?? line.price;
}

/** Canvas-space Y for a pending order line at its price (or override). */
export function resolveOrderLinePriceAxisAnchor(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  lineId: string,
  lines: readonly ChartPendingOrderLine[],
  priceOverrides?: ReadonlyMap<string, number>,
): { y: number } | null {
  const line = lines.find((entry) => entry.lineId === lineId);
  if (!line) return null;
  const price = resolveLinePrice(line, priceOverrides);
  const y = series.priceToCoordinate(price);
  if (y === null) return null;
  return { y };
}

export function isDraggablePendingLine(meta: ChartPendingOrderLineMeta): boolean {
  return meta.kind === "manual" && (meta.memberLineIds?.length ?? 1) === 1;
}

export function resolveCancelOrderTargets(
  meta: ChartPendingOrderLineMeta,
  metaByLineId: ReadonlyMap<string, ChartPendingOrderLineMeta>,
  marketId: string,
): Array<{ orderId: string; marketId: string }> {
  const members = meta.memberLineIds;
  if (members && members.length > 1) {
    return members.map((lineId) => {
      const memberMeta = metaByLineId.get(lineId);
      return {
        orderId: memberMeta?.orderId ?? lineId,
        marketId,
      };
    });
  }
  return [{ orderId: meta.orderId, marketId }];
}
