import { clearCopyMirrorForRelation } from "../../../offline/mock_data/copyMirrorState";
import { resetCopyMirrorReplayState } from "../../../offline/mock_data/copyMirrorReplay";
import { stopCopyMirrorReplaySession } from "../../services/copyMirrorOrchestrator";
import { useFleetCopyStore } from "../../store/fleetCopyStore";
import { COPY_TOUR_AGENT_ID } from "./constants";

/** Clear stale copy relation + mirror session so the tour always starts from setup. */
export function resetCopyTourAgentState(
  wallet: string,
  catalogAgentId: string = COPY_TOUR_AGENT_ID,
): void {
  const normalizedAgent = catalogAgentId.trim().toLowerCase();
  const store = useFleetCopyStore.getState();
  store.hydrate(wallet);
  const relation = store.getRelationForAgent(normalizedAgent);
  if (relation) {
    stopCopyMirrorReplaySession(relation.id);
    clearCopyMirrorForRelation(relation.id);
    store.removeCopyRelation(relation.id);
  }
  resetCopyMirrorReplayState();
}
