export type OfflinePortfolio = {
  walletAddress: string;
  bucketIds: string[];
  buckets: MockBucket[];
  positions: MockPosition[];
  openOrders: MockOrder[];
  orderHistory: MockOrder[];
  fundingHistory: MockFundingHistory[];
  agentTasks: MockAgentTask[];
  allOrders: MockOrder[];
};

const portfolioCache = new Map<string, OfflinePortfolio>();

function toSatoshiStr(value: number): string {
  return String(Math.round(value * SATOSHI));
}

function fromSatoshiNum(value: string): number {
  const intStr = value.includes(".") ? value.split(".")[0]! : value;
  return Number(BigInt(intStr)) / SATOSHI;
}

/** Lowercase wallet address; falls back to demo wallet when empty. */
export function normalizeOfflineWallet(address?: string | null): string {
  const trimmed = address?.trim();
  if (!trimmed) return mockWalletState.address.toLowerCase();
  return trimmed.toLowerCase();
}

/** Resolve wallet for portfolio reads — no demo fallback when empty. */
export function resolvePortfolioWallet(address?: string | null): string | null {
  const trimmed = address?.trim();
  if (!trimmed) return null;
  return trimmed.toLowerCase();
}

/** Deterministic bucket ids for a wallet (default 10). */
export function buildOfflineBucketIds(
  address: string,
  count = OFFLINE_BUCKET_COUNT,
): string[] {
  const normalized = normalizeOfflineWallet(address);
  return Array.from({ length: count }, (_, index) =>
    mockHashId(`offline:bucket:${normalized}:${index}`),
  );
}

/** Aggregate bucket equity from open positions (jelly-style). */
export function aggregateBucketFromPositions(
  bucketId: string,
  marginType: MockBucket["marginType"],
  baseEquity: number,
  status: string,
  positions: MockPosition[],
): MockBucket {
  const bucketPositions = positions.filter((p) => p.bucketId === bucketId);
  let unrealizedProfit = 0;
  let unrealizedLoss = 0;

  for (const pos of bucketPositions) {
    unrealizedProfit += fromSatoshiNum(pos.unrealizedProfit);
    unrealizedLoss += fromSatoshiNum(pos.unrealizedLoss);
  }

  const netUpnl = unrealizedProfit - unrealizedLoss;
  const totalEquity = Math.max(0, baseEquity + netUpnl);

  return {
    bucketId,
    marginType,
    collateralAssetIndex: "1",
    status,
    totalEquity: toSatoshiStr(totalEquity),
  };
}

function buildLegacyBucketIdMap(walletBucketIds: string[]): Map<string, string> {
  const map = new Map<string, string>();
  for (let i = 0; i < mockBuckets.length; i++) {
    const targetIndex = i % walletBucketIds.length;
    map.set(mockBuckets[i]!.bucketId, walletBucketIds[targetIndex]!);
  }
  return map;
}

function remapBucketId(
  legacyBucketId: string,
  legacyMap: Map<string, string>,
  walletBucketIds: string[],
): string {
  const mapped = legacyMap.get(legacyBucketId);
  if (mapped) return mapped;
  return walletBucketIds[0] ?? legacyBucketId;
}

function remapBucketEntity<T extends { bucketId: string; address: string }>(
  entity: T,
  legacyMap: Map<string, string>,
  walletAddress: string,
  walletBucketIds: string[],
): T {
  return {
    ...entity,
    bucketId: remapBucketId(entity.bucketId, legacyMap, walletBucketIds),
    address: walletAddress,
  };
}

function buildExtraPositionTemplates(): MockPosition[] {
  const now = BINANCE_SNAPSHOT_FETCHED_AT;
  const specs = [
    { id: "doge", ticker: "DOGE" as const, size: 5000, entryOffset: -0.02, side: "SIDE_BUY" as const },
    { id: "xrp", ticker: "XRP" as const, size: 800, entryOffset: 0.01, side: "SIDE_BUY" as const },
    { id: "bnb", ticker: "BNB" as const, size: 3, entryOffset: 0.015, side: "SIDE_SELL" as const },
    { id: "hype", ticker: "HYPE" as const, size: 150, entryOffset: -0.03, side: "SIDE_BUY" as const },
  ];

  return specs.map(({ id, ticker, size, entryOffset, side }) => {
    const marketIndex = getMockMarketIndex(ticker);
    const mark = mockMarketPrices[marketIndex] ?? 1;
    const entry = mark * (1 + entryOffset);
    const notional = entry * size;
    const leverage = 10;
    const marginBalance = notional / leverage;
    const isLong = side === "SIDE_BUY";
    const profit =
      isLong && mark > entry
        ? (mark - entry) * size
        : !isLong && mark < entry
          ? (entry - mark) * size
          : 0;
    const loss =
      isLong && mark < entry
        ? (entry - mark) * size
        : !isLong && mark > entry
          ? (mark - entry) * size
          : 0;

    return {
      positionId: `pos-${id}-offline`,
      bucketId: "",
      marketIndex,
      address: "",
      symbol: `${ticker}-USDT`,
      size: toSatoshiStr(size),
      side,
      averageEntryPrice: toSatoshiStr(entry),
      markPrice: toSatoshiStr(mark),
      leverage: toSatoshiStr(leverage),
      unrealizedProfit: toSatoshiStr(profit),
      unrealizedLoss: toSatoshiStr(loss),
      liquidationPrice: toSatoshiStr(isLong ? entry * 0.85 : entry * 1.15),
      marginBalance: toSatoshiStr(marginBalance),
      mmr: toSatoshiStr(marginBalance / 20),
      status: "active",
      marginMode: id === "bnb" ? "ISOLATED" : "CROSS",
      createdAt: now,
      updatedAt: now,
    };
  });
}

function buildWalletPositions(
  walletAddress: string,
  bucketIds: string[],
): MockPosition[] {
  const templates = [
    ...mockPositions.map((position) => ({ ...position })),
    ...buildExtraPositionTemplates(),
  ];

  return templates.slice(0, bucketIds.length).map((position, index) => ({
    ...position,
    bucketId: bucketIds[index]!,
    address: walletAddress,
  }));
}

function buildWalletBuckets(
  bucketIds: string[],
  positions: MockPosition[],
): MockBucket[] {
  return bucketIds.map((bucketId, index) => {
    const preset = OFFLINE_BUCKET_PRESETS[index] ?? OFFLINE_BUCKET_PRESETS[0]!;
    return aggregateBucketFromPositions(
      bucketId,
      preset.marginType,
      preset.baseEquity,
      preset.status,
      positions,
    );
  });
}

function remapOrders<T extends MockOrder>(
  orders: T[],
  legacyMap: Map<string, string>,
  walletAddress: string,
  walletBucketIds: string[],
): T[] {
  return orders.map((order) =>
    remapBucketEntity(order, legacyMap, walletAddress, walletBucketIds),
  );
}

function buildOfflinePortfolio(address?: string | null): OfflinePortfolio {
  const walletAddress = normalizeOfflineWallet(address);
  const bucketIds = buildOfflineBucketIds(walletAddress);
  const legacyMap = buildLegacyBucketIdMap(bucketIds);
  const positions = buildWalletPositions(walletAddress, bucketIds);
  const buckets = buildWalletBuckets(bucketIds, positions);
  const openOrders = remapOrders(
    mockOrders.map((order) => ({ ...order })),
    legacyMap,
    walletAddress,
    bucketIds,
  );
  const orderHistory = remapOrders(
    mockOrderHistory.map((order) => ({ ...order })),
    legacyMap,
    walletAddress,
    bucketIds,
  );
  const fundingHistory = remapOrders(
    mockFundingHistory.map((entry) => ({ ...entry })),
    legacyMap,
    walletAddress,
    bucketIds,
  ) as MockFundingHistory[];
  const agentTasks = linkMockAgentTasksToBucketIds(
    cloneMockAgentTasks(),
    bucketIds,
  ).map((task) => ({
    ...task,
    statusHistory: task.statusHistory.map((event) => ({ ...event })),
  }));

  return {
    walletAddress,
    bucketIds,
    buckets,
    positions,
    openOrders,
    orderHistory,
    fundingHistory,
    agentTasks,
    allOrders: [...openOrders, ...orderHistory, ...fundingHistory],
  };
}

/** Build a full portfolio in memory (used by progressive generator and tests). */
export function buildOfflinePortfolioForWallet(
  address?: string | null,
): OfflinePortfolio {
  return buildOfflinePortfolio(address);
}

export function setOfflinePortfolioInCache(portfolio: OfflinePortfolio): void {
  const wallet = resolvePortfolioWallet(portfolio.walletAddress);
  if (!wallet) return;
  portfolioCache.set(wallet, portfolio);
}

export function getCachedOfflinePortfolio(
  address?: string | null,
): OfflinePortfolio | null {
  const walletAddress = resolvePortfolioWallet(address);
  if (!walletAddress) return null;
  return portfolioCache.get(walletAddress) ?? null;
}

/**
 * Progressive generate: build step-by-step, persist each shard, then manifest.
 */
export async function generateOfflinePortfolioProgressive(
  address: string,
  callbacks: OfflinePortfolioProgressCallbacks = {},
): Promise<OfflinePortfolio> {
  const walletAddress = normalizeOfflineWallet(address);
  clearOfflinePortfolioStorage(walletAddress);

  const bucketIds = buildOfflineBucketIds(walletAddress);
  const legacyMap = buildLegacyBucketIdMap(bucketIds);

  const runStep = async (
    step: OfflinePortfolioStep,
    shard: PortfolioShard,
    data: unknown,
    count: number,
  ) => {
    callbacks.onStepStart?.(step);
    savePortfolioShard(walletAddress, shard, data);
    callbacks.onStepComplete?.(step, count);
    await Promise.resolve();
  };

  await runStep(
    OFFLINE_PORTFOLIO_STEPS[0]!,
    "meta",
    { bucketIds },
    bucketIds.length,
  );

  const positions = buildWalletPositions(walletAddress, bucketIds);
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[1]!,
    "positions",
    positions,
    positions.length,
  );

  const buckets = buildWalletBuckets(bucketIds, positions);
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[2]!,
    "buckets",
    buckets,
    buckets.length,
  );

  const openOrders = remapOrders(
    mockOrders.map((order) => ({ ...order })),
    legacyMap,
    walletAddress,
    bucketIds,
  );
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[3]!,
    "openOrders",
    openOrders,
    openOrders.length,
  );

  const orderHistory = remapOrders(
    mockOrderHistory.map((order) => ({ ...order })),
    legacyMap,
    walletAddress,
    bucketIds,
  );
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[4]!,
    "orderHistory",
    orderHistory,
    orderHistory.length,
  );

  const fundingHistory = remapOrders(
    mockFundingHistory.map((entry) => ({ ...entry })),
    legacyMap,
    walletAddress,
    bucketIds,
  ) as MockFundingHistory[];
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[5]!,
    "fundingHistory",
    fundingHistory,
    fundingHistory.length,
  );

  const agentTasks = linkMockAgentTasksToBucketIds(
    cloneMockAgentTasks(),
    bucketIds,
  ).map((task) => ({
    ...task,
    statusHistory: task.statusHistory.map((event) => ({ ...event })),
  }));
  await runStep(
    OFFLINE_PORTFOLIO_STEPS[6]!,
    "agentTasks",
    agentTasks,
    agentTasks.length,
  );

  const portfolio: OfflinePortfolio = {
    walletAddress,
    bucketIds,
    buckets,
    positions,
    openOrders,
    orderHistory,
    fundingHistory,
    agentTasks,
    allOrders: [...openOrders, ...orderHistory, ...fundingHistory],
  };

  saveOfflinePortfolioToStorage(portfolio);
  setOfflinePortfolioInCache(portfolio);
  return portfolio;
}

/** Hydrate cache from localStorage without regenerating. */
export function hydrateOfflinePortfolioFromStorage(
  address?: string | null,
): OfflinePortfolio | null {
  return tryGetOfflinePortfolio(address);
}

/** Read portfolio from memory cache, then localStorage. Does not build implicitly. */
export function tryGetOfflinePortfolio(
  address?: string | null,
): OfflinePortfolio | null {
  const walletAddress = resolvePortfolioWallet(address);
  if (!walletAddress) return null;
  const cached = portfolioCache.get(walletAddress);
  if (cached) return cached;
  const loaded = loadOfflinePortfolioFromStorage(walletAddress);
  if (!loaded) return null;
  portfolioCache.set(walletAddress, loaded);
  return loaded;
}

export function getOfflinePortfolio(
  address?: string | null,
): OfflinePortfolio | null {
  return tryGetOfflinePortfolio(address);
}

export function clearOfflinePortfolioCache(): void {
  portfolioCache.clear();
}

export function resetOfflinePortfolio(wallet?: string | null): void {
  const normalized = resolvePortfolioWallet(wallet);
  if (normalized) {
    portfolioCache.delete(normalized);
    clearOfflinePortfolioStorage(normalized);
  } else {
    clearOfflinePortfolioCache();
  }
}

export { hasOfflinePortfolioInStorage };

export function cloneOfflineBuckets(address?: string | null): MockBucket[] {
  const portfolio = tryGetOfflinePortfolio(address);
  if (!portfolio) return [];
  return portfolio.buckets.map((bucket) => ({ ...bucket }));
}

export function cloneOfflinePositions(address?: string | null): MockPosition[] {
  const portfolio = tryGetOfflinePortfolio(address);
  if (!portfolio) return [];
  return portfolio.positions.map((position) => ({
    ...position,
  }));
}

export function cloneOfflineAgentTasks(address?: string | null): MockAgentTask[] {
  const portfolio = tryGetOfflinePortfolio(address);
  if (!portfolio) return [];
  return portfolio.agentTasks.map((task) => ({
    ...task,
    statusHistory: task.statusHistory.map((event) => ({ ...event })),
  }));
}

export function cloneOfflineOrders(address?: string | null): MockOrder[] {
  const portfolio = tryGetOfflinePortfolio(address);
  if (!portfolio) return [];
  return portfolio.allOrders.map((order) => ({ ...order }));
}

/** Legacy slot index from static mockBuckets → wallet bucket id. */
export function remapLegacyBucketSlot(
  slot: number,
  address?: string | null,
): string {
  const portfolio = tryGetOfflinePortfolio(address);
  if (!portfolio || portfolio.bucketIds.length === 0) {
    throw new Error(
      "Offline portfolio is not ready. Connect with a demo mnemonic first.",
    );
  }
  const bucketIds = portfolio.bucketIds;
  const index = Math.max(0, Math.min(slot, bucketIds.length - 1));
  return bucketIds[index]!;
}
