import {
  INTENT_TEMPLATES,
  resolveDisplaySymbol,
  resolvePeerSymbol,
  randomizeParams,
  type IntentGenContext,
} from "../tradeops/intentExamples";

/** Static trading / strategy keywords extracted from intent templates */
export const INTENT_KEYWORD_LEXICON = [
  "long",
  "short",
  "momentum",
  "mean reversion",
  "stop loss",
  "take profit",
  "rebalance",
  "scalp",
  "scalping",
  "spread",
  "sentiment",
  "portfolio",
  "drawdown",
  "arbitrage",
  "pairs trading",
  "volatility",
  "allocation",
  "news",
  "event",
  "dip",
  "perps",
] as const;

export type IntentKeyword = (typeof INTENT_KEYWORD_LEXICON)[number] | string;

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function buildLexicon(baseAsset?: string): string[] {
  const terms = new Set<string>(INTENT_KEYWORD_LEXICON);
  if (baseAsset) {
    const upper = baseAsset.toUpperCase();
    terms.add(upper.toLowerCase());
    terms.add(resolveDisplaySymbol(baseAsset).toLowerCase());
    terms.add(resolvePeerSymbol(baseAsset).toLowerCase());
  }
  for (const template of INTENT_TEMPLATES) {
    terms.add(template.actorType.toLowerCase());
    terms.add(template.templateId.replace(/-/g, " "));
  }
  return [...terms].sort((a, b) => b.length - a.length);
}

/** Word-boundary aware keyword detection in free text */
export function detectIntentKeywords(
  text: string,
  baseAsset?: string,
): string[] {
  const normalized = text.toLowerCase().trim();
  if (!normalized) return [];

  const lexicon = buildLexicon(baseAsset);
  const found: string[] = [];

  for (const term of lexicon) {
    const pattern = new RegExp(
      `(?:^|[\\s,.;:!?'"([{])${escapeRegExp(term.toLowerCase())}(?:$|[\\s,.;:!?'")\\]}])`,
      "i",
    );
    if (pattern.test(normalized) || normalized.includes(term.toLowerCase())) {
      found.push(term);
    }
  }

  return [...new Set(found)];
}

export function getContextualKeywords(baseAsset?: string): string[] {
  const lexicon = buildLexicon(baseAsset);
  return lexicon.slice(0, 12);
}

export type IntentTemplateSuggestion = {
  id: string;
  label: string;
  summary: string;
  intentText: string;
  score: number;
};

export function buildTemplateSuggestions(
  baseAsset: string,
  query: string,
  limit = 4,
): IntentTemplateSuggestion[] {
  if (!baseAsset) return [];

  const symbol = resolveDisplaySymbol(baseAsset);
  const peer = resolvePeerSymbol(baseAsset);
  const q = query.toLowerCase().trim();

  const scored = INTENT_TEMPLATES.map((template) => {
    const params = randomizeParams(template.templateId);
    const ctx: IntentGenContext = { symbol, peer, params };
    const summary = template.buildSummary(ctx);
    const intentText = template.buildIntent(ctx);
    const haystack = [
      template.actorType,
      template.templateId,
      summary,
      intentText,
    ]
      .join(" ")
      .toLowerCase();

    let score = 0;
    if (!q) {
      score = 1;
    } else {
      const tokens = q.split(/\s+/).filter(Boolean);
      for (const token of tokens) {
        if (haystack.includes(token)) score += 2;
      }
      if (haystack.includes(q)) score += 4;
      if (template.actorType.toLowerCase().includes(q)) score += 3;
    }

    return {
      id: template.templateId,
      label: template.actorType,
      summary,
      intentText,
      score,
    };
  })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);

  return scored;
}

export function getTokenAtCaret(text: string, caret: number): string {
  const before = text.slice(0, caret);
  const match = before.match(/([a-zA-Z0-9_-]+)$/);
  return match?.[1] ?? "";
}

export function replaceTokenAtCaret(
  text: string,
  caret: number,
  replacement: string,
): { nextText: string; nextCaret: number } {
  const token = getTokenAtCaret(text, caret);
  const start = caret - token.length;
  const needsSpace =
    replacement.length > 0 &&
    caret < text.length &&
    !/\s/.test(text[caret] ?? "");
  const suffix = needsSpace ? " " : "";
  const nextText =
    text.slice(0, start) + replacement + suffix + text.slice(caret);
  const nextCaret = start + replacement.length + suffix.length;
  return { nextText, nextCaret };
}
