import React, { useMemo } from "react";

import type { PropertyIndexProfile } from "../../../offline/mock_data/types";
import TerminalCompactSettingsButton from "../preference/TerminalCompactSettingsButton";
import { Typewriter } from "../ui/Typewriter";
import "./index.css";

export interface IndexHeroHeaderProps {
  height?: string;
  profile: PropertyIndexProfile;
}

function IndexHeroHeader({
  height = "100%",
  profile,
}: IndexHeroHeaderProps): JSX.Element {
  const eyebrow = useMemo(
    () => `${profile.narrativeBeat} · ${profile.priority}`,
    [profile.narrativeBeat, profile.priority],
  );

  return (
    <div
      className="index-slot index-header-band index-header-band--title index-hero-header"
      style={{ height }}
    >
      <div className="terminal-header-band-actions">
        <TerminalCompactSettingsButton
          focusSection="indexDefaultMode"
          ariaLabel="Index settings"
        />
      </div>
      <div className="index-hero-header-content">
        <p className="eyebrow-text-wrap" title={eyebrow}>
          <Typewriter
            text={eyebrow}
            className="eyebrow-text"
            multiline={false}
          />
        </p>
        <div className="index-hero-title-row">
          <h1 className="index-hero-title">{profile.name}</h1>
        </div>
      </div>
    </div>
  );
}

export default IndexHeroHeader;
