import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
  type JSX,
  type ReactNode,
} from "react";
import { Typewriter } from "../../components/ui/Typewriter";
import { isWelcomeSlideWelcome, type WelcomeSlide } from "./content";

type SlideStep =
  | { kind: "kicker"; text: string }
  | { kind: "headline"; text: string }
  | { kind: "body"; text: string }
  | { kind: "bullet"; text: string; index: number };

export interface WelcomeSlideAnimatedContentProps {
  slide: WelcomeSlide;
  isActive: boolean;
  onSequenceComplete?: () => void;
}

interface WelcomeSlideContentLayoutProps {
  slide: WelcomeSlide;
  kicker: ReactNode | null;
  headline: ReactNode | null;
  body: ReactNode | null;
  bullets: ReactNode | null;
  showChips: boolean;
}

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function buildSlideSteps(slide: WelcomeSlide): SlideStep[] {
  const steps: SlideStep[] = [
    { kind: "kicker", text: slide.kicker },
    { kind: "headline", text: slide.headline },
  ];

  if (isWelcomeSlideWelcome(slide)) {
    steps.push({ kind: "body", text: slide.body });
    return steps;
  }

  slide.bullets.forEach((bullet, index) => {
    steps.push({ kind: "bullet", text: bullet, index });
  });

  return steps;
}

function WelcomeSlideContentLayout({
  slide,
  kicker,
  headline,
  body,
  bullets,
  showChips,
}: WelcomeSlideContentLayoutProps): JSX.Element {
  return (
    <div className="welcome-story-rail-slide-content">
      {kicker !== null ? (
        <div className="welcome-story-rail-slide-meta">
          <span className="welcome-story-rail-slide-icon" aria-hidden>
            {slide.icon}
          </span>
          <div className="terminal-label welcome-story-rail-kicker">{kicker}</div>
        </div>
      ) : null}

      {headline !== null ? (
        <h3 className="welcome-story-rail-headline">{headline}</h3>
      ) : null}

      {body !== null ? <p className="welcome-story-rail-body">{body}</p> : null}

      {bullets}

      {isWelcomeSlideWelcome(slide) && showChips ? (
        <div className="welcome-story-rail-chips welcome-story-rail-chips--visible">
          {slide.chips.map((chip) => (
            <span key={chip.label} className="welcome-story-rail-chip">
              <span className="welcome-story-rail-chip-icon" aria-hidden>
                {chip.icon}
              </span>
              {chip.label}
            </span>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function WelcomeSlideAnimatedContent({
  slide,
  isActive,
  onSequenceComplete,
}: WelcomeSlideAnimatedContentProps): JSX.Element {
  const [stepIndex, setStepIndex] = useState(0);
  const reducedMotion = prefersReducedMotion();
  const shouldAnimate = isActive && !reducedMotion;
  const steps = useMemo(() => buildSlideSteps(slide), [slide]);
  const currentStep = steps[stepIndex] ?? null;
  const isSequenceDone = stepIndex >= steps.length;

  useLayoutEffect(() => {
    if (!isActive) return;
    setStepIndex(0);
  }, [isActive, slide.id]);

  useLayoutEffect(() => {
    if (!isActive || !reducedMotion) return;
    onSequenceComplete?.();
  }, [isActive, reducedMotion, slide.id, onSequenceComplete]);

  useEffect(() => {
    if (!isActive || reducedMotion) return;
    if (stepIndex < steps.length) return;
    onSequenceComplete?.();
  }, [isActive, onSequenceComplete, reducedMotion, stepIndex, steps.length]);

  if (!isActive || reducedMotion) {
    return (
      <WelcomeSlideContentLayout
        slide={slide}
        kicker={slide.kicker}
        headline={slide.headline}
        body={isWelcomeSlideWelcome(slide) ? slide.body : null}
        bullets={
          isWelcomeSlideWelcome(slide) ? null : (
            <ul className="welcome-story-rail-bullets">
              {slide.bullets.map((bullet) => (
                <li key={bullet}>{bullet}</li>
              ))}
            </ul>
          )
        }
        showChips={isWelcomeSlideWelcome(slide)}
      />
    );
  }

  const advanceStep = () => setStepIndex((index) => index + 1);
  const kickerDone = stepIndex > 0;
  const headlineDone = stepIndex > 1;
  const bodyDone = isWelcomeSlideWelcome(slide) && stepIndex > 2;
  const completedBulletCount =
    !isWelcomeSlideWelcome(slide) && stepIndex > 2 ? stepIndex - 2 : 0;

  const renderKicker = (): ReactNode | null => {
    if (stepIndex === 0 && currentStep?.kind === "kicker") {
      return (
        <Typewriter
          key={`${slide.id}-kicker`}
          text={currentStep.text}
          className="welcome-story-rail-kicker-typewriter"
          multiline={false}
          active={shouldAnimate}
          onComplete={advanceStep}
        />
      );
    }
    if (kickerDone) return slide.kicker;
    return null;
  };

  const renderHeadline = (): ReactNode | null => {
    if (stepIndex === 1 && currentStep?.kind === "headline") {
      return (
        <Typewriter
          key={`${slide.id}-headline`}
          text={currentStep.text}
          className="welcome-story-rail-headline-typewriter"
          multiline="auto"
          active={shouldAnimate}
          onComplete={advanceStep}
        />
      );
    }
    if (headlineDone) return slide.headline;
    return null;
  };

  const renderBody = (): ReactNode | null => {
    if (!isWelcomeSlideWelcome(slide)) return null;

    if (stepIndex === 2 && currentStep?.kind === "body") {
      return (
        <Typewriter
          key={`${slide.id}-body`}
          text={currentStep.text}
          className="welcome-story-rail-body-typewriter"
          multiline="auto"
          active={shouldAnimate}
          onComplete={advanceStep}
        />
      );
    }
    if (bodyDone) return slide.body;
    return null;
  };

  const renderBullets = (): ReactNode | null => {
    if (isWelcomeSlideWelcome(slide) || stepIndex < 2) return null;

    const isTypingBullet = currentStep?.kind === "bullet";
    const activeBulletIndex = isTypingBullet ? currentStep.index : -1;

    return (
      <ul className="welcome-story-rail-bullets">
        {slide.bullets.map((bullet, index) => {
          if (index < completedBulletCount) {
            return <li key={bullet}>{bullet}</li>;
          }

          if (index === activeBulletIndex && isTypingBullet) {
            return (
              <li key={bullet}>
                <Typewriter
                  key={`${slide.id}-bullet-${index}`}
                  text={bullet}
                  className="welcome-story-rail-bullet-typewriter"
                  multiline="auto"
                  active={shouldAnimate}
                  onComplete={advanceStep}
                />
              </li>
            );
          }

          return null;
        })}
      </ul>
    );
  };

  const showKicker = (stepIndex === 0 && currentStep?.kind === "kicker") || kickerDone;
  const showHeadline = (stepIndex === 1 && currentStep?.kind === "headline") || headlineDone;
  const showBody =
    isWelcomeSlideWelcome(slide) &&
    ((stepIndex === 2 && currentStep?.kind === "body") || bodyDone);

  return (
    <WelcomeSlideContentLayout
      slide={slide}
      kicker={showKicker ? renderKicker() : null}
      headline={showHeadline ? renderHeadline() : null}
      body={showBody ? renderBody() : null}
      bullets={renderBullets()}
      showChips={isWelcomeSlideWelcome(slide) && isSequenceDone}
    />
  );
}
