import { useMemo } from "react";
import { usePendingOrders } from "./usePendingOrders";
import { useAgentTasks } from "./useAgentTasks";
import {
  pendingOrdersToChartLines,
  type ChartPendingOrderLine,
  type ChartPendingOrderLineMeta,
  type PendingOrderLineFilters,
} from "../components/finchartview/chartOrderLines";

export interface UseChartPendingOrderLinesConfig {
  baseURL: string;
  walletAddress?: string;
  authToken?: string;
  marketId: string;
  currentPrice?: number | null;
  enabled?: boolean;
  refreshInterval?: number;
  filters?: PendingOrderLineFilters;
}

export interface UseChartPendingOrderLinesResult {
  lines: ChartPendingOrderLine[];
  metaByLineId: Map<string, ChartPendingOrderLineMeta>;
  overflowCount: number;
  loading: boolean;
}

export function useChartPendingOrderLines(
  config: UseChartPendingOrderLinesConfig,
): UseChartPendingOrderLinesResult {
  const {
    baseURL,
    walletAddress,
    authToken,
    marketId,
    currentPrice,
    enabled = true,
    refreshInterval,
    filters,
  } = config;

  const { orders, loading: ordersLoading } = usePendingOrders({
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });

  const { tasks } = useAgentTasks();

  const { lines, metaByLineId, overflowCount } = useMemo(() => {
    if (!enabled || !marketId) {
      return {
        lines: [] as ChartPendingOrderLine[],
        metaByLineId: new Map<string, ChartPendingOrderLineMeta>(),
        overflowCount: 0,
      };
    }

    return pendingOrdersToChartLines(orders, tasks, marketId, { currentPrice, filters });
  }, [enabled, marketId, orders, tasks, currentPrice, filters]);

  return {
    lines,
    metaByLineId,
    overflowCount,
    loading: enabled && ordersLoading,
  };
}
