import { useCallback, useLayoutEffect, useRef, useState } from "react";
import type { FeedEnterState } from "../tradeops/feedAnimation";
import { useFeedEnter } from "../tradeops/useFeedEnter";

export const DECK_EXIT_ANIMATION_MS = 220;

export interface UseDeckTaskListAnimationResult {
  enterState: FeedEnterState | null;
  exitingId: string | null;
  onExitAnimationEnd: (taskId: string) => void;
}

export function useDeckTaskListAnimation(
  visibleTaskIds: string[],
): UseDeckTaskListAnimationResult {
  const { enterState, markEntering, clearEnter } = useFeedEnter();
  const [exitingId, setExitingId] = useState<string | null>(null);

  const hasHydratedRef = useRef(false);
  const seenInDeckRef = useRef<Set<string>>(new Set());
  const prevVisibleIdsRef = useRef<string[]>([]);
  const exitingIdRef = useRef<string | null>(null);
  const exitFallbackRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const finishExit = useCallback((taskId: string) => {
    if (exitingIdRef.current !== taskId) return;
    exitingIdRef.current = null;
    setExitingId(null);
    if (exitFallbackRef.current) {
      clearTimeout(exitFallbackRef.current);
      exitFallbackRef.current = null;
    }
  }, []);

  const cancelExit = useCallback(() => {
    if (exitFallbackRef.current) {
      clearTimeout(exitFallbackRef.current);
      exitFallbackRef.current = null;
    }
    exitingIdRef.current = null;
    setExitingId(null);
  }, []);

  const startExit = useCallback(
    (taskId: string) => {
      if (exitingIdRef.current === taskId) return;
      exitingIdRef.current = taskId;
      setExitingId(taskId);
      if (exitFallbackRef.current) {
        clearTimeout(exitFallbackRef.current);
      }
      exitFallbackRef.current = setTimeout(() => {
        finishExit(taskId);
      }, DECK_EXIT_ANIMATION_MS);
    },
    [finishExit],
  );

  const onExitAnimationEnd = useCallback(
    (taskId: string) => {
      finishExit(taskId);
    },
    [finishExit],
  );

  useLayoutEffect(() => {
    if (!hasHydratedRef.current) {
      hasHydratedRef.current = true;
      visibleTaskIds.forEach((id) => seenInDeckRef.current.add(id));
      prevVisibleIdsRef.current = visibleTaskIds;
      return;
    }

    const prevIds = prevVisibleIdsRef.current;
    const currentSet = new Set(visibleTaskIds);
    const newIds = visibleTaskIds.filter((id) => !seenInDeckRef.current.has(id));

    if (newIds.length > 0) {
      const headId = visibleTaskIds[0];
      if (headId && newIds.includes(headId)) {
        markEntering(headId);
      }
      newIds.forEach((id) => seenInDeckRef.current.add(id));
    }

    const removedIds = prevIds.filter((id) => !currentSet.has(id));

    if (visibleTaskIds.length === 0) {
      cancelExit();
      clearEnter();
      seenInDeckRef.current.clear();
    } else if (removedIds.length > 1) {
      // Bulk approve / kill — skip exit animation to avoid stale ghosts + measure churn.
      cancelExit();
      removedIds.forEach((id) => seenInDeckRef.current.delete(id));
    } else if (removedIds.length === 1 && !exitingIdRef.current) {
      startExit(removedIds[0]!);
    }

    prevVisibleIdsRef.current = visibleTaskIds;
  }, [visibleTaskIds, markEntering, startExit, cancelExit, clearEnter]);

  return {
    enterState,
    exitingId,
    onExitAnimationEnd,
  };
}
