import { useMemo } from "react";
import { useAgentTasks } from "../../../hooks/useAgentTasks";
import { useTradingAgents } from "../../../hooks/useTradingAgents";
import type { TierCounts } from "../reportTier";

export interface HighATickerMetrics {
  deployedPct: number;
  dayPnlUsd: number;
  riskScore: number;
  riskCap: number;
  lastActionMs: number | null;
  activeTaskCount: number;
}

const DEMO_DAY_PNL_USD = 1840;

export function useHighATickerMetrics(
  tierCounts: TierCounts,
  watchingCount: number,
  liveExecutingCount: number,
): HighATickerMetrics {
  const { tasks } = useAgentTasks();
  const { agents } = useTradingAgents();

  return useMemo(() => {
    const activeAgentCount = Math.max(
      agents.filter((a) => a.status === "active").length,
      1,
    );
    const activeTaskCount = watchingCount + liveExecutingCount;
    const capacity = Math.max(activeAgentCount * 2, 1);
    const deployedPct = Math.min(
      100,
      Math.round((activeTaskCount / capacity) * 100),
    );

    const pendingCount = tasks.filter((t) => t.status === "pending").length;
    const riskScore = Math.min(
      1,
      pendingCount * 0.1 + tierCounts.T3 * 0.15 + tierCounts.T4 * 0.25,
    );

    const nonTerminal = tasks.filter(
      (t) => t.status !== "completed" && t.status !== "rejected",
    );
    const lastActionMs =
      nonTerminal.length > 0
        ? Math.max(
            ...nonTerminal.map((t) => new Date(t.updatedAt).getTime()),
          )
        : null;

    return {
      deployedPct,
      dayPnlUsd: DEMO_DAY_PNL_USD,
      riskScore,
      riskCap: 1,
      lastActionMs,
      activeTaskCount,
    };
  }, [
    tierCounts,
    watchingCount,
    liveExecutingCount,
    tasks,
    agents,
  ]);
}

export function formatRelativeSeconds(ms: number | null): string {
  if (ms == null) return "—";
  const sec = Math.max(0, Math.floor((Date.now() - ms) / 1000));
  if (sec < 60) return `${sec}s ago`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min}m ago`;
  return `${Math.floor(min / 60)}h ago`;
}
