import React from "react";
import type { AgentTaskGuardrailRiskImpact } from "../../store/types";
import { getRiskZone } from "./RiskScoreMetric";
import { riskImpactLabel } from "./guardrailMeta";

export type SafetyAuditLogMetricVariant =
  | "riskOnly"
  | "confidenceOnly"
  | "combined"
  | "card";

export interface SafetyAuditLogMetricCellProps {
  riskImpact: AgentTaskGuardrailRiskImpact;
  confidencePct: number;
  variant?: SafetyAuditLogMetricVariant;
}

function SafetyAuditLogMetricCell({
  riskImpact,
  confidencePct,
  variant = "combined",
}: SafetyAuditLogMetricCellProps): JSX.Element {
  const confidenceZone = getRiskZone(100 - confidencePct);

  if (variant === "riskOnly") {
    return (
      <div className="safety-audit-log-metric-cell safety-audit-log-metric-cell--risk-only">
        <span className={`guardrail-risk-pill guardrail-risk-pill--${riskImpact}`}>
          {riskImpactLabel(riskImpact)}
        </span>
      </div>
    );
  }

  if (variant === "confidenceOnly") {
    return (
      <div className="safety-audit-log-metric-cell safety-audit-log-metric-cell--confidence-only">
        <span
          className={`safety-audit-log-confidence-badge safety-audit-log-confidence-badge--${confidenceZone}`}
        >
          {confidencePct}%
        </span>
        <div
          className={`safety-audit-log-confidence-bar safety-audit-log-confidence-bar--${confidenceZone}`}
          style={{ "--risk-score": confidencePct / 100 } as React.CSSProperties}
          aria-hidden
        >
          <div className="safety-audit-log-confidence-bar-fill" />
        </div>
      </div>
    );
  }

  if (variant === "card") {
    return (
      <div className="safety-audit-log-metric-cell safety-audit-log-metric-cell--card">
        <div className="safety-audit-log-card-metrics-row">
          <span
            className={`guardrail-confidence-badge guardrail-confidence-badge--${confidenceZone}`}
          >
            <span className="terminal-value">{confidencePct}%</span> conf
          </span>
          <span className={`guardrail-risk-pill guardrail-risk-pill--${riskImpact}`}>
            {riskImpactLabel(riskImpact)} risk
          </span>
        </div>
        <div
          className={`safety-audit-log-confidence-bar safety-audit-log-confidence-bar--${confidenceZone}`}
          style={{ "--risk-score": confidencePct / 100 } as React.CSSProperties}
          aria-hidden
        >
          <div className="safety-audit-log-confidence-bar-fill" />
        </div>
      </div>
    );
  }

  return (
    <div className="safety-audit-log-metric-cell safety-audit-log-metric-cell--combined">
      <span className={`guardrail-risk-pill guardrail-risk-pill--${riskImpact}`}>
        {riskImpactLabel(riskImpact)} · {confidencePct}%
      </span>
      <div
        className={`safety-audit-log-confidence-bar safety-audit-log-confidence-bar--${confidenceZone}`}
        style={{ "--risk-score": confidencePct / 100 } as React.CSSProperties}
        aria-hidden
      >
        <div className="safety-audit-log-confidence-bar-fill" />
      </div>
    </div>
  );
}

export default React.memo(SafetyAuditLogMetricCell);
