import React from "react";
import { formatCurrency } from "../../../sdk/utils/display";
import { DEMO_WARP_ROUTE } from "../../../types/crossChainFlow";
import type { WalletTransferAssetId } from "../wallet-transfer-modal";
import { CrossChainSecurityStepper } from "./CrossChainSecurityStepper";
import "./cross-chain.css";

export interface CrossChainAuthorizePanelProps {
  assetId: WalletTransferAssetId;
  amount: number;
  isWaiting: boolean;
  onSimulateSignature: () => void;
}

export function CrossChainAuthorizePanel({
  assetId,
  amount,
  isWaiting,
  onSimulateSignature,
}: CrossChainAuthorizePanelProps): JSX.Element {
  return (
    <>
      <p className="terminal-label cross-chain-status-label">
        {isWaiting ? "◔ waiting for signature" : "◔ ready to sign"}
      </p>
      <CrossChainSecurityStepper activeStage="authorize" />
      <p className="cross-chain-body-copy cross-chain-body-copy--spaced">
        Approving EXACTLY {formatCurrency(amount)} {assetId} (not unlimited).
        Verify before signing:
      </p>
      <dl className="cross-chain-signature-verify">
        <dt>spender</dt>
        <dd className="cross-chain-amount-value terminal-value">
          {DEMO_WARP_ROUTE.slice(0, 6)}…{DEMO_WARP_ROUTE.slice(-4)} (warp route)
        </dd>
        <dt>amount</dt>
        <dd className="cross-chain-amount-value terminal-value">
          {formatCurrency(amount)} {assetId}
        </dd>
      </dl>
      <button
        type="button"
        className="btn btn-primary cross-chain-btn-full"
        disabled={isWaiting}
        onClick={onSimulateSignature}
        data-tour="deposit-tour-authorize-btn"
      >
        {isWaiting ? "Waiting…" : "Simulate signature"}
      </button>
    </>
  );
}
