export type BinanceTradeSnapshotSymbol = keyof typeof BINANCE_TRADE_SNAPSHOT.candles;

/** Pick candle by index from the end (0 = most recent). */
export function pickSnapshotCandle(
  symbol: BinanceTradeSnapshotSymbol,
  fromEnd: number,
): BinanceSnapshotCandle {
  const list = BINANCE_TRADE_SNAPSHOT.candles[symbol];
  const idx = list.length - 1 - fromEnd;
  if (idx < 0 || idx >= list.length) {
    throw new Error(`pickSnapshotCandle: index ${fromEnd} out of range for ${symbol}`);
  }
  return list[idx]!;
}
