import React from "react";
import { createPortal } from "react-dom";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useStaggeredOverlay,
} from "../ui/overlay";
import "./mobileTradeSheet.css";

export interface MobileTradeSheetProps {
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
}

export function MobileTradeSheet({
  isOpen,
  onClose,
  children,
}: MobileTradeSheetProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: OVERLAY_TIMING.tradeSheetMs,
  });

  useOverlayEscapeKey(isOpen, onClose);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="mobile-trade-overlay">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content mobile-trade-panel"
        aria-label="Trade"
      >
        <header className="mobile-trade-panel-header">
          <h2 className="mobile-trade-panel-title">Trade</h2>
          <button
            type="button"
            className="mobile-trade-panel-close"
            onClick={onClose}
            aria-label="Close trade panel"
          >
            ×
          </button>
        </header>
        <div className="mobile-trade-panel-body">{children}</div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
