import type { FiClient } from "../sdk";
import type { Bucket } from "../sdk/types/data";

export function assetSymbolToCollateralIndex(symbol: string): number {
  return ({ USDC: 1, USDT: 2 }[symbol?.toUpperCase()] ?? 1);
}

export type ExecuteBucketCreateAndFundParams = {
  exchangeClient: FiClient;
  marginType: "cross" | "isolated";
  collateralAsset: string;
  amount: number;
  /** Spot wallet or an existing bucket id to fund from. */
  fundFrom: "spot-wallet" | string;
  /** When set, reuse a dormant/empty bucket instead of creating a new one. */
  reuseEmptyBucket?: (
    marginType: "cross" | "isolated",
    collateralAsset: string,
  ) => Bucket | null;
};

/**
 * Creates a margin bucket (or reuses an empty/dormant match) and optionally funds it.
 * Shared by TransferModalsContext create-bucket tab and copy-agent confirm flow.
 */
export async function executeBucketCreateAndFund({
  exchangeClient,
  marginType,
  collateralAsset,
  amount,
  fundFrom,
  reuseEmptyBucket,
}: ExecuteBucketCreateAndFundParams): Promise<string> {
  const existingBucket = reuseEmptyBucket?.(marginType, collateralAsset) ?? null;
  let targetBucketId: string;

  if (existingBucket) {
    targetBucketId = existingBucket.bucketId;
  } else {
    const createResult = await exchangeClient.createBucket({
      collateralAssetIndex: assetSymbolToCollateralIndex(collateralAsset),
      marginType,
      initialMargin: "0",
    });
    if (!createResult.success) {
      throw new Error(createResult.message || "Failed to create bucket");
    }
    targetBucketId = createResult.bucketId ?? "";
    if (!targetBucketId) {
      throw new Error("Failed to create bucket — no bucket id returned");
    }
  }

  if (amount > 0 && fundFrom === "spot-wallet") {
    const fundResult = await exchangeClient.extractToBucket({
      bucketId: targetBucketId,
      assetId: collateralAsset,
      amount,
    });
    if (!fundResult.success) {
      throw new Error(fundResult.errorMessage ?? "Failed to fund bucket from spot");
    }
  } else if (amount > 0 && fundFrom !== "spot-wallet") {
    const transferResult = await exchangeClient.bucketTransfer({
      fromBucketId: fundFrom,
      toBucketId: targetBucketId,
      assetId: collateralAsset,
      amount,
    });
    if (!transferResult.success) {
      throw new Error(transferResult.errorMessage ?? "Failed to fund bucket");
    }
  }

  return targetBucketId;
}
