import type { TelemetryColorToken } from "./types";

/** Resolve design-system colour tokens for SVG strokes and inline use. */
export function resolveColorToken(token: TelemetryColorToken): string {
  const map: Record<TelemetryColorToken, string> = {
    accent: "var(--terminal-accent)",
    secondary: "var(--terminal-secondary)",
    long: "var(--terminal-long)",
    premium: "var(--terminal-warning)",
    short: "var(--terminal-short)",
    info: "var(--terminal-info)",
  };
  return map[token];
}

export type SeriesColorToken = "accent" | "long";

export function resolveSeriesColor(token: SeriesColorToken): string {
  return token === "long" ? "var(--terminal-long)" : "var(--terminal-accent)";
}
