import React, { useEffect, useMemo, useState } from "react";

import type { AgentTokenProfile } from "../../../offline/mock_data/agentTokenProfile";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import { AGENT_ACTION_TAB_BUBBLE_MAP } from "../../tutorials/bubble-tip";
import { TabLayoutHeaderToolBar } from "../smartlayout";
import "../agentconsole/agentConsole.css";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import AgentAboutTab from "./AgentAboutTab";
import AgentActionTab from "./AgentActionTab";
import AgentPlaybookTab from "./AgentPlaybookTab";
import AgentTokenTab from "./AgentTokenTab";
import {
  AGENT_ACTION_TAB_LABELS,
  buildActionTabs,
  defaultActionTabForFocus,
  type AgentActionTabId,
  type AgentHeroFocus,
} from "./agentHeroFocus";
import "./agent.css";

export interface AgentActionTabSectionProps {
  height?: string;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  walletAddress?: string;
  heroFocus?: AgentHeroFocus;
  hasAgentToken?: boolean;
  tokenProfile?: AgentTokenProfile;
  initialActionTab?: AgentActionTabId;
}

function resolveInitialActionTab(
  initialActionTab: AgentActionTabId | undefined,
  heroFocus: AgentHeroFocus,
  hasAgentToken: boolean,
): AgentActionTabId {
  const tabIds = buildActionTabs(hasAgentToken);
  if (initialActionTab && tabIds.includes(initialActionTab)) {
    return initialActionTab;
  }
  return defaultActionTabForFocus(heroFocus, hasAgentToken);
}

function AgentActionTabSection({
  height = "100%",
  profile,
  fleet,
  walletAddress = "",
  heroFocus = "copy",
  hasAgentToken = false,
  tokenProfile,
  initialActionTab,
}: AgentActionTabSectionProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<AgentActionTabId>(() =>
    resolveInitialActionTab(initialActionTab, heroFocus, hasAgentToken),
  );

  useEffect(() => {
    if (activeTab === "token" && !hasAgentToken) {
      setActiveTab("action");
    }
  }, [activeTab, hasAgentToken]);

  useEffect(() => {
    if (!initialActionTab) return;
    const tabIds = buildActionTabs(hasAgentToken);
    if (tabIds.includes(initialActionTab)) {
      setActiveTab(initialActionTab);
    }
  }, [initialActionTab, hasAgentToken]);

  const tabIds = useMemo(
    () => buildActionTabs(hasAgentToken),
    [hasAgentToken],
  );

  const tabs = useMemo(
    () =>
      tabIds.map((id) => ({
        id,
        label: AGENT_ACTION_TAB_LABELS[id],
        bubbleTipId: AGENT_ACTION_TAB_BUBBLE_MAP[id],
      })),
    [tabIds],
  );

  return (
    <div
      className="agent-slot agent-action-tab-section"
      style={{ height }}
      aria-label={`${profile.name} action tabs`}
    >
      <div className="layout-container tab-section-root agent-action-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={activeTab}
          onTabChange={(id) => setActiveTab(id as AgentActionTabId)}
          scrollActiveTabIntoView
        />
        <div className="tab-section-content">
          {activeTab === "action" ? (
            <AgentActionTab
              profile={profile}
              fleet={fleet}
              walletAddress={walletAddress}
            />
          ) : null}

          {activeTab === "token" && hasAgentToken && tokenProfile ? (
            <AgentTokenTab
              profile={profile}
              fleet={fleet}
              tokenProfile={tokenProfile}
            />
          ) : null}

          {activeTab === "playbook" ? (
            <AgentPlaybookTab profile={profile} fleet={fleet} />
          ) : null}

          {activeTab === "about" ? (
            <AgentAboutTab
              profile={profile}
              fleet={fleet}
              hasAgentToken={hasAgentToken}
            />
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default AgentActionTabSection;
