import React, { useEffect, useMemo, useState } from "react";

import type { AgentKpiHistoryFile } from "../../../offline/mock_data/agentKpiHistory.types";
import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory.types";
import {
  buildAgentCompareChartPayload,
  resolveDefaultChartMode,
  type AgentCompareChartMode,
  type AgentCompareTimeRange,
} from "../../utils/agentCompareChartData";
import { useAgentKpiHistoryForAgents } from "../../hooks/useAgentKpiHistoryForAgents";
import { useFleetTradesForAgents } from "../../hooks/useFleetTradesForAgents";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import type { AgentCompareFocus } from "./agentCompareFocus";
import AgentCompareChart from "./AgentCompareChart";
import "./agent.css";

const COMPARE_LOADING_MESSAGE = "Loading compare data…";

const TIME_RANGE_OPTIONS: { value: AgentCompareTimeRange; label: string }[] = [
  { value: "24h", label: "24H" },
  { value: "7d", label: "7D" },
  { value: "30d", label: "30D" },
  { value: "all", label: "Max" },
];

export interface AgentCompareMatrixChartProps {
  compareIds: string[];
  compareFocus: AgentCompareFocus;
  tradesByAgentId?: Map<string, FleetTradeEvent[]>;
  kpiByAgentId?: Map<string, AgentKpiHistoryFile>;
  loading?: boolean;
  error?: string | null;
}

function AgentCompareMatrixChart({
  compareIds,
  compareFocus,
  tradesByAgentId: preloadedTradesByAgentId,
  kpiByAgentId: preloadedKpiByAgentId,
  loading: preloadedLoading,
  error: preloadedError,
}: AgentCompareMatrixChartProps): JSX.Element {
  const [chartMode, setChartMode] = useState<AgentCompareChartMode>(() =>
    resolveDefaultChartMode(compareFocus),
  );
  const [timeRange, setTimeRange] = useState<AgentCompareTimeRange>("7d");
  const fetched = useFleetTradesForAgents(compareIds);
  const fetchedKpi = useAgentKpiHistoryForAgents(compareIds);
  const hasPreloadedTrades = preloadedTradesByAgentId !== undefined;
  const tradesByAgentId = hasPreloadedTrades
    ? preloadedTradesByAgentId
    : fetched.tradesByAgentId;
  const kpiByAgentId = preloadedKpiByAgentId ?? fetchedKpi.kpiByAgentId;
  const loading = hasPreloadedTrades
    ? (preloadedLoading ?? false)
    : fetched.loading || fetchedKpi.loading;
  const error = hasPreloadedTrades ? preloadedError : fetched.error ?? fetchedKpi.error;

  useEffect(() => {
    setChartMode(resolveDefaultChartMode(compareFocus));
  }, [compareFocus]);

  const payload = useMemo(() => {
    if (loading) return null;
    return buildAgentCompareChartPayload(
      compareIds,
      chartMode,
      timeRange,
      tradesByAgentId,
      kpiByAgentId,
    );
  }, [compareIds, chartMode, timeRange, tradesByAgentId, kpiByAgentId, loading]);

  if (loading) {
    return (
      <div className="agent-compare-matrix-chart">
        <div className="agent-compare-chart-plot agent-compare-chart-plot--loading">
          <MorpheumInlineLoading message={COMPARE_LOADING_MESSAGE} />
        </div>
      </div>
    );
  }

  return (
    <div className="agent-compare-matrix-chart">
      <div className="agent-compare-chart-toolbar">
        <div className="agent-compare-chart-mode-toggle" role="group" aria-label="Chart mode">
          <button
            type="button"
            className={`agent-compare-chart-mode-btn${chartMode === "price" ? " agent-compare-chart-mode-btn--active" : ""}`}
            onClick={() => setChartMode("price")}
          >
            Price
          </button>
          <button
            type="button"
            className={`agent-compare-chart-mode-btn${chartMode === "performance" ? " agent-compare-chart-mode-btn--active" : ""}`}
            onClick={() => setChartMode("performance")}
          >
            Performance %
          </button>
        </div>

        <div className="agent-compare-chart-range-group" role="group" aria-label="Time range">
          {TIME_RANGE_OPTIONS.map((option) => (
            <button
              key={option.value}
              type="button"
              className={`agent-compare-chart-range-btn${timeRange === option.value ? " agent-compare-chart-range-btn--active" : ""}`}
              onClick={() => setTimeRange(option.value)}
            >
              {option.label}
            </button>
          ))}
        </div>
      </div>

      {error ? (
        <p className="agent-compare-chart-error">{error}</p>
      ) : payload ? (
        <>
          <AgentCompareChart
            series={payload.series}
            volume={payload.volume}
            mode={chartMode}
          />

          <div className="agent-compare-chart-legend" aria-label="Compared agents">
            {payload.series.map((entry) => (
              <span key={entry.id} className="agent-compare-chart-legend-item">
                <span
                  className="agent-compare-chart-legend-dot"
                  style={{ backgroundColor: entry.color }}
                />
                {entry.ticker}
              </span>
            ))}
          </div>
        </>
      ) : null}
    </div>
  );
}

export default AgentCompareMatrixChart;
