import { useEffect, useState } from "react";

/**
 * Accumulate a bounded, in-memory history of a polled scalar so a sparkline can
 * show its recent trend.
 */
export function useRollingSeries(
  value: number | null | undefined,
  max = 30,
  resetKey?: string | number,
): number[] {
  const [series, setSeries] = useState<number[]>([]);
  const [last, setLast] = useState<number | null>(null);

  useEffect(() => {
    setSeries([]);
    setLast(null);
  }, [resetKey]);

  if (value != null && !Number.isNaN(value) && value !== last) {
    setLast(value);
    setSeries((prev) => [...prev, value].slice(-max));
  }

  return series;
}
