import React, { type JSX } from "react";

import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { CopyRelation } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { AgentAssetChartFocus } from "./agentAssetChartFocus";
import AgentEquityChart from "./AgentEquityChart";
import AgentTokenTakerKlineChart from "./AgentTokenTakerKlineChart";
import {
  AGENT_PAGE_TOKEN_TAKER_MARKER_STRATEGY,
  AGENT_PAGE_TOKEN_TAKER_MAX_TOP_TRADERS,
  type TokenTakerMarkerStrategy,
} from "../finchartview/tokenTakerChartMarkers";
import FleetAssetKlineChart from "./FleetAssetKlineChart";
import "./agent.css";

export type TokenTakerChartFocus = {
  eventId: string;
  timeMs: number;
};

export interface AgentChartSectionProps {
  height?: string;
  series: number[];
  currentValue: number;
  fleetTrades: FleetTradeEvent[];
  agentTicker: string;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  assetFocus: AgentAssetChartFocus | null;
  onClearAssetFocus: () => void;
  copyRelation?: CopyRelation | null;
  tokenTakersActive?: boolean;
  marketCatalogAgentId?: string;
  takerEvents?: AgentTokenTakerTradeEvent[];
  takerEventsLoading?: boolean;
  tokenTakerFocus?: TokenTakerChartFocus | null;
  onClearTokenTakerFocus?: () => void;
  tokenTicker?: string;
  tokenTakerMaxTopTraders?: number;
  tokenTakerMarkerStrategy?: TokenTakerMarkerStrategy;
}

function AgentChartSection({
  height = "100%",
  series,
  currentValue,
  fleetTrades,
  agentTicker,
  profile,
  fleet,
  assetFocus,
  onClearAssetFocus,
  copyRelation = null,
  tokenTakersActive = false,
  marketCatalogAgentId,
  takerEvents = [],
  takerEventsLoading = false,
  tokenTakerFocus = null,
  onClearTokenTakerFocus,
  tokenTicker,
  tokenTakerMaxTopTraders = AGENT_PAGE_TOKEN_TAKER_MAX_TOP_TRADERS,
  tokenTakerMarkerStrategy = AGENT_PAGE_TOKEN_TAKER_MARKER_STRATEGY,
}: AgentChartSectionProps): JSX.Element {
  const showTokenChart = tokenTakersActive && Boolean(marketCatalogAgentId);
  const showAssetChart = !showTokenChart && assetFocus != null;

  const handleEquityClick = () => {
    onClearAssetFocus();
    onClearTokenTakerFocus?.();
  };

  return (
    <div
      className="agent-slot agent-slot--chart agent-chart-wrap"
      style={{ height }}
    >
      <div className="agent-chart-head">
        <div className="agent-chart-nav">
          <div
            className="agent-compare-chart-mode-toggle"
            role="group"
            aria-label="Chart mode"
          >
            <button
              type="button"
              className={`agent-compare-chart-mode-btn${
                !showAssetChart && !showTokenChart
                  ? " agent-compare-chart-mode-btn--active"
                  : ""
              }`}
              onClick={handleEquityClick}
            >
              Equity
            </button>
            {showTokenChart && tokenTicker ? (
              <button
                type="button"
                className="agent-compare-chart-mode-btn agent-compare-chart-mode-btn--active"
                aria-current="true"
              >
                {tokenTicker}
              </button>
            ) : assetFocus ? (
              <button
                type="button"
                className={`agent-compare-chart-mode-btn${
                  showAssetChart ? " agent-compare-chart-mode-btn--active" : ""
                }`}
                aria-current={showAssetChart ? "true" : undefined}
              >
                {assetFocus.coin}
              </button>
            ) : null}
          </div>
          {showTokenChart ? (
            <span className="agent-chart-label">
              Token takers · {takerEvents.length} loaded fills
            </span>
          ) : !showAssetChart ? (
            <span className="agent-chart-label">
              PnL / equity curve · {fleetTrades.length} simulated fills
            </span>
          ) : (
            <span className="agent-chart-label">
              Leader fill · read-only mirror
              {copyRelation
                ? ` · copying · ${copyRelation.copySettings.copySizePct}%`
                : ""}
            </span>
          )}
        </div>
      </div>
      <div className="agent-chart-container">
        {showTokenChart && marketCatalogAgentId ? (
          <AgentTokenTakerKlineChart
            catalogAgentId={marketCatalogAgentId}
            events={takerEvents}
            eventsLoading={takerEventsLoading}
            focusEventId={tokenTakerFocus?.eventId ?? null}
            focusTimeMs={tokenTakerFocus?.timeMs ?? 0}
            height="100%"
            maxTopTraders={tokenTakerMaxTopTraders}
            markerStrategy={tokenTakerMarkerStrategy}
          />
        ) : showAssetChart && assetFocus ? (
          <FleetAssetKlineChart
            coin={assetFocus.coin}
            tradeTimeMs={assetFocus.tradeTimeMs}
            tradeId={assetFocus.tradeId}
            fleetTrades={fleetTrades}
            profile={profile}
            fleet={fleet}
            copyRelation={copyRelation}
          />
        ) : (
          <AgentEquityChart
            series={series}
            currentValue={currentValue}
            fleetTrades={fleetTrades}
            agentTicker={agentTicker}
            hideHead
            hideOuterShell
          />
        )}
      </div>
    </div>
  );
}

export default AgentChartSection;
