import { useCallback, useEffect, useMemo, useState } from "react";

import type { AgentTokenTakerTradeEvent } from "../../offline/mock_data/agentTokenTakerHistory.types";
import {
  AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL,
  fetchAgentTokenTakerEventsByMarketId,
  hasAgentTokenTakerMarket,
} from "../sdk/api/agentTokenTakerHistory/agentTokenTakerHistoryClient";

const INITIAL_VISIBLE_COUNT = 100;
const LOAD_MORE_INCREMENT = 100;

export interface UseAgentTokenTakerHistoryResult {
  events: AgentTokenTakerTradeEvent[];
  visibleEvents: AgentTokenTakerTradeEvent[];
  loading: boolean;
  error: string | null;
  hasMarket: boolean;
  visibleCount: number;
  hasMore: boolean;
  loadMore: () => void;
}

export function useAgentTokenTakerHistory(
  marketCatalogAgentId: string,
  baseUrl: string = AGENT_TOKEN_TAKER_HISTORY_DATA_BASE_URL,
): UseAgentTokenTakerHistoryResult {
  const [events, setEvents] = useState<AgentTokenTakerTradeEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [hasMarket, setHasMarket] = useState(false);
  const [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE_COUNT);

  useEffect(() => {
    const normalizedId = marketCatalogAgentId.trim();
    if (!normalizedId) {
      setEvents([]);
      setLoading(false);
      setError(null);
      setHasMarket(false);
      setVisibleCount(INITIAL_VISIBLE_COUNT);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);
    setVisibleCount(INITIAL_VISIBLE_COUNT);

    (async () => {
      try {
        const marketExists = await hasAgentTokenTakerMarket(normalizedId, baseUrl);
        if (cancelled) return;

        if (!marketExists) {
          setHasMarket(false);
          setEvents([]);
          return;
        }

        setHasMarket(true);
        const loaded = await fetchAgentTokenTakerEventsByMarketId(
          normalizedId,
          baseUrl,
        );
        if (cancelled) return;
        setEvents(loaded);
      } catch (err: unknown) {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load agent token taker history",
        );
        setEvents([]);
        setHasMarket(false);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [marketCatalogAgentId, baseUrl]);

  const hasMore = visibleCount < events.length;

  const loadMore = useCallback(() => {
    setVisibleCount((prev) =>
      Math.min(prev + LOAD_MORE_INCREMENT, events.length),
    );
  }, [events.length]);

  const visibleEvents = useMemo(
    () => events.slice(0, visibleCount),
    [events, visibleCount],
  );

  return {
    events,
    visibleEvents,
    loading,
    error,
    hasMarket,
    visibleCount,
    hasMore,
    loadMore,
  };
}
