import React, { useEffect, useMemo, useRef } from "react";
import {
  AreaSeries,
  LineSeries,
  createChart,
  type IChartApi,
  type ISeriesApi,
  type UTCTimestamp,
} from "lightweight-charts";

import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { buildIndexNavPriceChartSeries } from "../../utils/indexChartData";
import { sanitizeLineDataForChart } from "../../utils/portfolioChartData";
import { formatCurrency } from "./indexFormat";
import "./index.css";

const NAV_COLOR = "#34d399";
const PRICE_COLOR = "#60a5fa";
const DEFAULT_VISIBLE_DAYS = 7;
const DAY_SEC = 24 * 60 * 60;

function applyDefaultVisibleRange(
  chart: IChartApi,
  priceData: { time: UTCTimestamp }[],
): void {
  if (priceData.length === 0) return;

  const lastTime = priceData[priceData.length - 1]!.time as number;
  const visibleSpanSec = Math.min(
    DEFAULT_VISIBLE_DAYS * DAY_SEC,
    lastTime - (priceData[0]!.time as number),
  );

  chart.timeScale().setVisibleRange({
    from: (lastTime - visibleSpanSec) as UTCTimestamp,
    to: lastTime as UTCTimestamp,
  });
}

export interface IndexNavPriceChartProps {
  height?: string;
  price: number;
  nav: number;
  series: number[];
}

function IndexNavPriceChart({
  height = "100%",
  price,
  nav,
  series,
}: IndexNavPriceChartProps): JSX.Element {
  const chartWrapRef = useRef<HTMLDivElement>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const priceSeriesRef = useRef<ISeriesApi<"Area"> | null>(null);
  const navSeriesRef = useRef<ISeriesApi<"Line"> | null>(null);

  const { priceData, navData } = useMemo(
    () => buildIndexNavPriceChartSeries(series, nav, price),
    [series, nav, price],
  );

  const seriesKey = useMemo(
    () =>
      `${priceData.length}:${navData.length}:${priceData.at(-1)?.value}:${navData.at(-1)?.value}`,
    [priceData, navData],
  );

  const hasData = priceData.length > 0;

  useEffect(() => {
    if (!chartContainerRef.current || !hasData) return;

    if (chartRef.current) {
      try {
        chartRef.current.remove();
      } catch {
        // ignore
      }
      chartRef.current = null;
      priceSeriesRef.current = null;
      navSeriesRef.current = null;
    }

    let chart: IChartApi | null = null;
    let animationFrameId: number | null = null;
    let initAttempts = 0;
    const maxInitAttempts = 120;

    const initializeChart = () => {
      if (!chartContainerRef.current) return;

      const container = chartContainerRef.current;
      const containerWidth = container.clientWidth || container.offsetWidth;
      const containerHeight = container.clientHeight || container.offsetHeight;

      if (
        (!containerWidth ||
          containerWidth < 50 ||
          !containerHeight ||
          containerHeight < 60) &&
        initAttempts < maxInitAttempts
      ) {
        initAttempts += 1;
        animationFrameId = requestAnimationFrame(initializeChart);
        return;
      }

      try {
        chart = createChart(container, {
          autoSize: true,
          layout: {
            background: { color: "transparent" },
            textColor: TERMINAL_COLORS.textSecondary,
          },
          grid: {
            vertLines: { visible: false },
            horzLines: { color: TERMINAL_COLORS.gridMajor },
          },
          crosshair: { mode: 1 },
          handleScroll: {
            mouseWheel: true,
            pressedMouseMove: true,
            horzTouchDrag: true,
            vertTouchDrag: false,
          },
          handleScale: {
            axisPressedMouseMove: true,
            mouseWheel: true,
            pinch: true,
          },
          rightPriceScale: {
            borderColor: TERMINAL_COLORS.panelStrong,
            visible: true,
            scaleMargins: { top: 0.08, bottom: 0.08 },
          },
          leftPriceScale: { visible: false },
          timeScale: {
            visible: true,
            borderVisible: true,
            borderColor: TERMINAL_COLORS.panelStrong,
            timeVisible: true,
            secondsVisible: false,
            ticksVisible: true,
            minimumHeight: 22,
          },
        });

        const priceSeries = chart.addSeries(AreaSeries, {
          lineColor: PRICE_COLOR,
          topColor: "rgba(96, 165, 250, 0.22)",
          bottomColor: "rgba(96, 165, 250, 0.02)",
          lineWidth: 2,
          priceScaleId: "right",
          crosshairMarkerVisible: true,
          crosshairMarkerRadius: 4,
          crosshairMarkerBorderColor: PRICE_COLOR,
          crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
        });
        priceSeries.setData(sanitizeLineDataForChart(priceData));

        const navSeries = chart.addSeries(LineSeries, {
          color: NAV_COLOR,
          lineWidth: 2,
          lineStyle: 2,
          priceScaleId: "right",
          crosshairMarkerVisible: true,
          crosshairMarkerRadius: 4,
          crosshairMarkerBorderColor: NAV_COLOR,
          crosshairMarkerBackgroundColor: TERMINAL_COLORS.panel,
        });
        navSeries.setData(sanitizeLineDataForChart(navData));

        applyDefaultVisibleRange(chart, priceData);
        chartRef.current = chart;
        priceSeriesRef.current = priceSeries;
        navSeriesRef.current = navSeries;
        chart.resize(containerWidth, containerHeight);
      } catch (error) {
        console.error("[IndexNavPriceChart] Error creating chart:", error);
      }
    };

    initializeChart();

    return () => {
      if (animationFrameId !== null) {
        cancelAnimationFrame(animationFrameId);
      }
      if (chart) {
        try {
          chart.remove();
        } catch {
          // ignore
        }
      }
      chartRef.current = null;
      priceSeriesRef.current = null;
      navSeriesRef.current = null;
    };
  }, [hasData, seriesKey, priceData, navData]);

  useEffect(() => {
    if (!priceSeriesRef.current || !navSeriesRef.current || !hasData) return;

    try {
      priceSeriesRef.current.setData(sanitizeLineDataForChart(priceData));
      navSeriesRef.current.setData(sanitizeLineDataForChart(navData));
    } catch (error) {
      console.error("[IndexNavPriceChart] Error updating series:", error);
    }
  }, [priceData, navData, hasData]);

  useEffect(() => {
    const wrap = chartWrapRef.current;
    if (!wrap || !hasData) return;

    const scheduleResize = () => {
      requestAnimationFrame(() => {
        const chart = chartRef.current;
        const container = chartContainerRef.current;
        if (!chart || !container) return;

        const width = container.clientWidth || container.offsetWidth;
        const height = container.clientHeight || container.offsetHeight;
        if (width <= 0 || height <= 0) return;

        try {
          chart.resize(width, height);
        } catch {
          // ignore
        }
      });
    };

    const observer = new ResizeObserver(scheduleResize);
    observer.observe(wrap);
    scheduleResize();

    return () => observer.disconnect();
  }, [hasData, seriesKey]);

  return (
    <div className="index-slot index-slot--chart" style={{ height, width: "100%" }}>
      <div className="index-slot-body index-slot-body--chart">
        <div className="index-section-head  overlay-head">
          <div>
            <span className="eyebrow-text">NAV vs market price</span>
            <h2>Premium band and live tracking</h2>
          </div>
        </div>
        <div ref={chartWrapRef} className="index-chart-canvas-wrap">
          <div
            ref={chartContainerRef}
            className="index-chart-canvas"
            role="img"
            aria-label="NAV versus market price chart"
          />
        </div>
        <div className="index-chart-legend  overlay-footer">
          <span>
            <i className="nav" /> NAV {formatCurrency(nav)}
          </span>
          <span>
            <i className="price" /> Market {formatCurrency(price)}
          </span>
        </div>
      </div>
    </div>
  );
}

export default IndexNavPriceChart;
