import React, { useMemo } from "react";
import { formatCurrency, formatPercentage } from "../../sdk/utils/display";
import { calculateRiskRatio, getDisplayMarginType, type Bucket } from "../../sdk";
import {
  clampAutonomyThreshold,
  isCustomAutonomyPolicy,
  AUTONOMY_PRESET_TONE,
  type AutonomyPolicy,
  type AutonomyPreset,
} from "../tradeagent/autonomyPolicy";
import { reportTierLabel } from "../tradeagent/reportTier";
import { AnimatedCollapse } from "../ui/AnimatedCollapse";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { PresetCardGrid } from "../ui/PresetCardGrid";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import type { PresetCardOption } from "../ui/PresetCardGrid";
import type { useBucketRulesEditor } from "./useBucketRulesEditor";
import "./bucketCollection.css";

function formatBucketStatus(status?: string | null): string {
  return (status || "active").toLowerCase();
}

function BucketContextStrip({ bucket }: { bucket: Bucket }): JSX.Element {
  const riskRatio = calculateRiskRatio(bucket);
  const marginType = getDisplayMarginType(bucket);

  const items = [
    marginType.toUpperCase(),
    `${formatCurrency(bucket.totalEquity || 0)} equity`,
    `${formatPercentage(riskRatio)} risk`,
    formatBucketStatus(bucket.status),
  ];

  return (
    <div className="bucket-rules-context-strip">
      {items.map((item, index) => (
        <span key={`${item}-${index}`} className="bucket-rules-meta-text">
          {item}
        </span>
      ))}
    </div>
  );
}

const PRESET_OPTIONS: PresetCardOption<AutonomyPreset>[] = [
  {
    value: "manual",
    label: "Manual",
    description: "Agents off — intents are logged for you, nothing auto-executes.",
    tone: AUTONOMY_PRESET_TONE.manual,
  },
  {
    value: "guarded",
    label: "Guarded",
    description: "Ask first — more intents surface for your approval.",
    tone: AUTONOMY_PRESET_TONE.guarded,
  },
  {
    value: "highAgency",
    label: "High-Agency",
    description: "Hands-off — agents can trade without asking (risky).",
    tone: AUTONOMY_PRESET_TONE.highAgency,
  },
];

const PRESET_ACTIVE_DESCRIPTION: Record<AutonomyPreset, string> = {
  manual: "Manual: agents never execute; intents are logged for you.",
  guarded: "Guarded: agents propose; risky moves wait for your approval.",
  highAgency: "High-Agency: silent execution when confidence and risk stay in band.",
};

const APPROVE_BY_OPTIONS = [1, 3, 5, 10];

const SILENT_BAND_MIN = 50;
const SILENT_BAND_MAX = 95;
const GATE_BAND_MIN = 40;
const GATE_BAND_MAX = 90;

function tierBadgeClass(tier: string): string {
  return `bucket-rules-tier-badge bucket-rules-tier-badge--${tier.toLowerCase()}`;
}

function impactOutcomeHint(tier: string): string {
  if (tier === "T0" || tier === "T1") return "→ would auto";
  if (tier === "T3" || tier === "T4") return "→ asks you";
  return "→ FYI only";
}

export interface BucketRulesPanelProps {
  bucket: Bucket | null;
  draft: AutonomyPolicy;
  setDraft: React.Dispatch<React.SetStateAction<AutonomyPolicy | null>>;
  advancedOpen: boolean;
  setAdvancedOpen: React.Dispatch<React.SetStateAction<boolean>>;
  error: string | null;
  saveSuccessMessage?: string | null;
  editing: boolean;
  onPresetSelect: (preset: AutonomyPreset) => void;
  impactRows: ReturnType<typeof useBucketRulesEditor>["impactRows"];
  needsYouPreview: number;
  bucketTasks: ReturnType<typeof useBucketRulesEditor>["bucketTasks"];
}

function BucketRulesPanel({
  bucket,
  draft,
  setDraft,
  advancedOpen,
  setAdvancedOpen,
  error,
  saveSuccessMessage,
  editing,
  onPresetSelect,
  impactRows,
  needsYouPreview,
  bucketTasks,
}: BucketRulesPanelProps): JSX.Element {
  const isCustom = isCustomAutonomyPolicy(draft);
  const isManual = draft.preset === "manual";

  const activeDescription = useMemo(() => {
    if (isCustom && !isManual) {
      return "Custom thresholds — reset to restore preset defaults.";
    }
    return PRESET_ACTIVE_DESCRIPTION[draft.preset];
  }, [draft.preset, isCustom, isManual]);

  return (
    <div className="bucket-rules-modal-body bucket-detail-rules-panel">
      {bucket ? <BucketContextStrip bucket={bucket} /> : null}

      <section className="bucket-rules-section">
        <h4 className="bucket-rules-section-title">How much can agents do?</h4>
        <PresetCardGrid
          options={PRESET_OPTIONS}
          selected={draft.preset}
          onSelect={onPresetSelect}
          isActive={(option) => draft.preset === option.value && !isCustom}
          disabled={!editing}
          columns={3}
          hint={activeDescription}
          hintClassName="preset-card-hint bucket-rules-meta-text"
          aria-label="Autonomy preset"
        />
      </section>

      {!isManual ? (
        <section className="bucket-rules-section">
          <button
            type="button"
            className="bucket-rules-advanced-toggle"
            onClick={() => setAdvancedOpen((open) => !open)}
            aria-expanded={advancedOpen}
            disabled={!editing}
          >
            Advanced thresholds
            <ExpandCollapseIcon
              expanded={advancedOpen}
              className="bucket-rules-advanced-chevron"
              size={14}
            />
          </button>
          <AnimatedCollapse open={advancedOpen} timing="deck">
            <div className="bucket-rules-advanced-panel">
              <label className="bucket-rules-field">
                <span className="terminal-label bucket-rules-field-label">
                  Silent band (confidence %)
                </span>
                <FilledRangeSlider
                  variant="brand"
                  min={SILENT_BAND_MIN}
                  max={SILENT_BAND_MAX}
                  value={draft.silentMinConfidence}
                  onChange={(value) =>
                    setDraft((prev) =>
                      prev
                        ? {
                            ...prev,
                            silentMinConfidence: clampAutonomyThreshold(value),
                          }
                        : prev,
                    )
                  }
                  disabled={!editing}
                />
                <span className="bucket-rules-field-value bucket-rules-meta-text">
                  {draft.silentMinConfidence}%
                </span>
              </label>
              <p className="bucket-rules-hint bucket-rules-meta-text">
                At or above + low risk → T0 silent auto-execute.
              </p>

              <label className="bucket-rules-field">
                <span className="terminal-label bucket-rules-field-label">
                  Gate below (confidence %)
                </span>
                <FilledRangeSlider
                  variant="brand"
                  min={GATE_BAND_MIN}
                  max={GATE_BAND_MAX}
                  value={draft.gateMinConfidence}
                  onChange={(value) =>
                    setDraft((prev) =>
                      prev
                        ? {
                            ...prev,
                            gateMinConfidence: clampAutonomyThreshold(
                              value,
                              GATE_BAND_MIN,
                              GATE_BAND_MAX,
                            ),
                          }
                        : prev,
                    )
                  }
                  disabled={!editing}
                />
                <span className="bucket-rules-field-value bucket-rules-meta-text">
                  {draft.gateMinConfidence}%
                </span>
              </label>
              <p className="bucket-rules-hint bucket-rules-meta-text">
                Below this on a gateable intent → T3 approval gate.
              </p>

              <div className="bucket-rules-field">
                <span className="terminal-label bucket-rules-field-label">
                  T3 approve-by window
                </span>
                <div className="bucket-rules-approve-options">
                  {APPROVE_BY_OPTIONS.map((minutes) => (
                    <button
                      key={minutes}
                      type="button"
                      className={`bucket-rules-approve-option${
                        draft.t3ApproveByMinutes === minutes ? " is-active" : ""
                      }`}
                      onClick={() =>
                        setDraft((prev) =>
                          prev ? { ...prev, t3ApproveByMinutes: minutes } : prev,
                        )
                      }
                      disabled={!editing}
                    >
                      {minutes}m
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </AnimatedCollapse>
        </section>
      ) : null}

      <section className="bucket-rules-section">
        <h4 className="bucket-rules-section-title">Live impact</h4>
        {impactRows.length === 0 ? (
          <p className="bucket-rules-hint bucket-rules-meta-text">
            No active intents in this bucket — rules apply when agents deploy
            here.
          </p>
        ) : (
          <>
            <p className="bucket-rules-impact-summary bucket-rules-meta-text">
              Under these rules:{" "}
              <span className="bucket-rules-impact-emphasis">
                {needsYouPreview} need you
              </span>
              {bucketTasks.length > impactRows.length
                ? ` · showing ${impactRows.length} of ${bucketTasks.length}`
                : null}
            </p>
            <ul className="bucket-rules-impact-list">
              {impactRows.map(({ task, meta }) => (
                <li key={task.id} className="bucket-rules-impact-item">
                  <span className={tierBadgeClass(meta.reportTier)}>
                    {reportTierLabel(meta.reportTier)}
                  </span>
                  <span className="bucket-rules-impact-desc">
                    {task.description}
                  </span>
                  <span className="bucket-rules-impact-meta bucket-rules-meta-text">
                    {meta.confidencePct}% · {meta.riskImpact} risk{" "}
                    {impactOutcomeHint(meta.reportTier)}
                  </span>
                </li>
              ))}
            </ul>
          </>
        )}
      </section>

      {saveSuccessMessage ? (
        <p className="bucket-rules-success" role="status">
          {saveSuccessMessage}
        </p>
      ) : null}
      {error ? <p className="bucket-rules-error">{error}</p> : null}
    </div>
  );
}

export default React.memo(BucketRulesPanel);
