import type { CompareAgentColumn } from "../../utils/agentCompareMatrix";
import type { AgentCompareFocus } from "./agentCompareFocus";
import { hasAgentToken, type AgentActionTabId } from "./agentHeroFocus";

export type CompareFocusCta =
  | { kind: "navigate"; label: string; path: string }
  | { kind: "copy"; label: string };

export function buildAgentCompareTerminalPath(
  id: string,
  tab: AgentActionTabId,
): string {
  return `/agents/${encodeURIComponent(id)}?tab=${tab}`;
}

function copyAgentLabel(isCopying: boolean): string {
  return isCopying ? "Copying agent" : "Copy agent";
}

export function resolveCompareFocusCta(
  focus: AgentCompareFocus,
  agent: CompareAgentColumn,
  isCopying: boolean,
): CompareFocusCta {
  switch (focus) {
    case "playbook":
      return {
        kind: "navigate",
        label: "View playbook",
        path: buildAgentCompareTerminalPath(agent.id, "playbook"),
      };
    case "performance":
      return {
        kind: "copy",
        label: copyAgentLabel(isCopying),
      };
    case "risk":
      return {
        kind: "navigate",
        label: "View risk profile",
        path: buildAgentCompareTerminalPath(agent.id, "about"),
      };
    case "scale":
      if (hasAgentToken(agent.fleet)) {
        return {
          kind: "navigate",
          label: "View token",
          path: buildAgentCompareTerminalPath(agent.id, "token"),
        };
      }
      return {
        kind: "navigate",
        label: "View profile",
        path: buildAgentCompareTerminalPath(agent.id, "about"),
      };
    default:
      return {
        kind: "navigate",
        label: "View profile",
        path: buildAgentCompareTerminalPath(agent.id, "about"),
      };
  }
}
