import React, { useMemo } from "react";
import { useTradingAgents } from "../../../hooks/useTradingAgents";
import { useAgentTasks } from "../../../hooks/useAgentTasks";
import { useTradeHistory } from "../../../hooks/useTradeHistory";
import { shortHashId } from "../../../utils/hashId";

export interface AgentRiskAttributionTabProps {
  baseURL: string;
  authToken?: string;
  walletAddress: string;
  highlightAgentId?: string | null;
}

/** Deterministic mock PnL when no linked trades exist for an agent. */
function mockAttributedPnl(agentId: string): number {
  let hash = 0;
  for (let i = 0; i < agentId.length; i++) {
    hash = (hash * 31 + agentId.charCodeAt(i)) | 0;
  }
  return ((hash % 2000) - 800) / 100;
}

function formatPnl(value: number): string {
  const sign = value >= 0 ? "+" : "";
  return `${sign}$${value.toFixed(2)}`;
}

function AgentRiskAttributionTab({
  baseURL,
  authToken,
  walletAddress,
  highlightAgentId,
}: AgentRiskAttributionTabProps): JSX.Element {
  const { agents } = useTradingAgents();
  const { tasks } = useAgentTasks();
  const { trades } = useTradeHistory({
    baseURL,
    authToken,
    walletAddress,
    refreshInterval: 5000,
  });

  const taskAgentMap = useMemo(() => {
    const map = new Map<string, string>();
    for (const task of tasks) {
      if (task.agentId) map.set(task.id, task.agentId);
    }
    return map;
  }, [tasks]);

  const pnlByAgentId = useMemo(() => {
    const map = new Map<string, number>();
    for (const row of trades) {
      if (!row.agentTaskId || row.closedPnl == null) continue;
      const agentId = taskAgentMap.get(row.agentTaskId);
      if (!agentId) continue;
      map.set(agentId, (map.get(agentId) ?? 0) + row.closedPnl);
    }
    return map;
  }, [trades, taskAgentMap]);

  const rows = useMemo(() => {
    let list = agents;
    if (highlightAgentId) {
      list = list.filter((a) => a.id === highlightAgentId);
    }
    return list.map((agent) => {
      const linkedPnl = pnlByAgentId.get(agent.id);
      const attributedPnl =
        linkedPnl != null && linkedPnl !== 0
          ? linkedPnl
          : mockAttributedPnl(agent.id);
      const isMock = linkedPnl == null || linkedPnl === 0;

      return { agent, attributedPnl, isMock };
    });
  }, [agents, highlightAgentId, pnlByAgentId]);

  if (rows.length === 0) {
    return (
      <p className="agent-console-empty terminal-text-muted">
        No agents to attribute risk against.
      </p>
    );
  }

  return (
    <div className="agent-console-risk-table">
      <div className="agent-console-risk-header">
        <span>Agent</span>
        <span>Risk</span>
        <span>Attributed PnL</span>
        <span>Source</span>
      </div>
      {rows.map(({ agent, attributedPnl, isMock }) => {
        const pnlColor =
          attributedPnl > 0
            ? "var(--terminal-long)"
            : attributedPnl < 0
              ? "var(--terminal-short)"
              : undefined;

        return (
          <div key={agent.id} className="agent-console-risk-row">
            <span className="agent-console-risk-agent">
              {agent.icon ? `${agent.icon} ` : ""}
              {agent.displayName}
              <span className="task-id-chip" title={agent.id}>
                {shortHashId(agent.id)}
              </span>
            </span>
            <span className="agent-console-risk-score">
              {agent.riskScore ?? "—"}
            </span>
            <span style={{ color: pnlColor, fontWeight: 500 }}>
              {formatPnl(attributedPnl)}
            </span>
            <span className="terminal-text-muted" style={{ fontSize: "0.65rem" }}>
              {isMock ? "estimated" : "trades"}
            </span>
          </div>
        );
      })}
    </div>
  );
}

export default React.memo(AgentRiskAttributionTab);
