import type { AgentTask, Market } from "../../store/types";

function byUpdatedAtDesc(a: AgentTask, b: AgentTask): number {
  return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
}

/** Resolve whether two market id strings refer to the same catalog market. */
export function isSameMarketId(
  markets: Pick<Market, "index" | "marketIndex">[],
  a: string | null | undefined,
  b: string | null | undefined,
): boolean {
  if (!a || !b) return false;
  if (a === b) return true;

  const resolve = (id: string) =>
    markets.find((m) => m.index === id || m.marketIndex === id);

  const marketA = resolve(a);
  const marketB = resolve(b);
  if (!marketA || !marketB) return false;

  const idA = marketA.marketIndex ?? marketA.index;
  const idB = marketB.marketIndex ?? marketB.index;
  return idA === idB;
}

/** Guardrail deck: intents awaiting human approval (pending + watching). */
export function sortGuardrailIntents(tasks: AgentTask[]): AgentTask[] {
  return [...tasks]
    .filter((t) => t.status === "pending" || t.status === "watching")
    .sort(byUpdatedAtDesc);
}

/** Command deck: all non-terminal live intents, newest first. */
export function sortLiveIntents(tasks: AgentTask[]): AgentTask[] {
  return [...tasks]
    .filter((t) => t.status !== "completed" && t.status !== "rejected")
    .sort(byUpdatedAtDesc);
}
