import { useCallback, useState } from "react";

export const TICKER_FAVORITES_KEY = "ticker_favorites";

function loadFavoritesFromStorage(): string[] {
  try {
    const raw = localStorage.getItem(TICKER_FAVORITES_KEY);
    return raw ? (JSON.parse(raw) as string[]) : [];
  } catch {
    return [];
  }
}

export function useTickerFavorites() {
  const [favorites, setFavorites] = useState<string[]>(loadFavoritesFromStorage);

  const toggleFavorite = useCallback((marketId: string) => {
    setFavorites((prev) => {
      const next = prev.includes(marketId)
        ? prev.filter((id) => id !== marketId)
        : [...prev, marketId];
      localStorage.setItem(TICKER_FAVORITES_KEY, JSON.stringify(next));
      return next;
    });
  }, []);

  return { favorites, toggleFavorite };
}
