import React, { useEffect, useMemo, useState } from "react";
import { usePendingOrders } from "../../hooks/usePendingOrders";
import { SubscriptionClient } from "../../sdk";
import { useSubscription } from "../../context/SubscriptionContext";
import { PendingOrder as PendingOrderData } from "../../sdk/types/data";
import { useMarkets } from "../../hooks/useMarkets";
import {
  ErrorMessage,
  EmptyMessage,
  LayoutHeader,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  DEFAULT_BASE_URL,
  DEFAULT_HEIGHT_PENDING_ORDERS,
  DEFAULT_REFRESH_INTERVAL,
  ORDER_EMPTY_MESSAGE_HISTORY,
  ORDER_TITLE_HISTORY,
} from "../../constants";
import { shortHashId } from "../../utils/hashId";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import {
  buildTaskAgentMap,
  rowMatchesFleetFilter,
} from "../../utils/agentFilter";
import ExplainActionModal from "./ExplainActionModal";
import "./agentTasks.css";

interface OrderHistoryProps {
  baseURL: string;
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress: string;
  height?: string;
  refreshInterval?: number;
  hide_header?: boolean;
  onRequestHeaderActions?: (node: React.ReactNode) => void;
  filterAgentIds?: string[];
}

const GRID_TEMPLATE_COLUMNS =
  "1.1fr 5rem 0.8fr 0.7fr 0.9fr 0.9fr 0.9fr 0.9fr 1fr 0.95fr 0.9fr 0.75fr 5rem";

function formatDateTime(value?: string | number | Date | null): string {
  if (value == null || value === "") return "—";
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function formatNumber(value: number | undefined | null): string {
  if (value == null || Number.isNaN(value)) return "—";
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function formatMoney(value: number | undefined | null): string {
  if (value == null || Number.isNaN(value)) return "—";
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function getTriggerCondition(order: PendingOrderData): string {
  const raw = order.raw as Record<string, unknown> | undefined;
  const triggerValue =
    raw?.triggerCondition ??
    raw?.triggerPrice ??
    raw?.stopPrice ??
    raw?.takeProfit ??
    raw?.stopLoss;

  if (triggerValue == null || triggerValue === "") {
    return "—";
  }

  return String(triggerValue);
}

function getOrderTypeLabel(type: unknown): string {
  if (typeof type !== "string" || type.trim() === "") {
    return "—";
  }

  return type.replace("ORDER_TYPE_", "");
}

function OrderHistory({
  baseURL = DEFAULT_BASE_URL,
  subscriptionClient: subscriptionClientProp,
  authToken,
  walletAddress,
  height = DEFAULT_HEIGHT_PENDING_ORDERS,
  refreshInterval = DEFAULT_REFRESH_INTERVAL,
  hide_header = false,
  onRequestHeaderActions,
  filterAgentIds = [],
}: OrderHistoryProps): JSX.Element {
  const { client: contextClient } = useSubscription();
  const subscriptionClient = subscriptionClientProp ?? contextClient;

  const { orders, loading, error } = usePendingOrders({
    ...(subscriptionClient != null && { subscriptionClient }),
    baseURL,
    authToken,
    walletAddress,
    refreshInterval,
  });

  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });
  const { tasks } = useAgentTasks();
  const taskAgentMap = useMemo(() => buildTaskAgentMap(tasks), [tasks]);
  const [explainTaskId, setExplainTaskId] = useState<string | null>(null);

  const historyOrders = useMemo(
    () =>
      orders
        .filter((order) => {
          const status = String(order.status ?? "").toUpperCase();
          return ![
            "PENDING",
            "OPEN",
            "ACTIVE",
            "PARTIAL",
            "NEW",
            "PARTIALLY_FILLED",
          ].some((pending) => status.includes(pending));
        })
        .filter((order) =>
          rowMatchesFleetFilter(order.agentTaskId, filterAgentIds, taskAgentMap),
        ),
    [orders, filterAgentIds, taskAgentMap],
  );

  const headerActions = useMemo(() => null, []);

  useEffect(() => {
    if (!onRequestHeaderActions) return;
    if (hide_header && !loading && !error) {
      onRequestHeaderActions(headerActions);
      return () => onRequestHeaderActions(null);
    }
    onRequestHeaderActions(null);
  }, [hide_header, onRequestHeaderActions, loading, error, headerActions]);

  if (loading) return <MorpheumInlineLoading message="Loading order history..." />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <div
      className="layout-container"
      style={{
        height,
        ...(hide_header ? { borderRadius: 0, background: "transparent" } : {}),
      }}
    >
      {!hide_header && (
        <LayoutHeader title={ORDER_TITLE_HISTORY}>{headerActions}</LayoutHeader>
      )}

      <div className="table-container shrinkable">
        <div
          className="table-header"
          style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
        >
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic center>Agent</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Token</TableHeaderCellStatic>
          <TableHeaderCellStatic center>Side</TableHeaderCellStatic>
          <TableHeaderCellStatic center>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.orderType} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.originalSize} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.filledSize} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.initialPrice} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic center>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.triggerCondition} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.avgFilledPrice} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.orderValue} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic center>Status</TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.orderId} />
          </TableHeaderCellStatic>
        </div>

        {historyOrders.length === 0 ? (
          <EmptyMessage message={ORDER_EMPTY_MESSAGE_HISTORY} />
        ) : (
          historyOrders.map((order: PendingOrderData, index: number) => {
            const symbol =
              getSymbolByMarketId(order.marketId) || `m-${order.marketId}`;
            const originalSize = order.quantity;
            const filledSize = order.filledQuantity;
            const avgFilledPrice = order.price;
            const orderValue = (order.quantity || 0) * (order.price || 0);

            return (
              <div
                key={`history-${order.orderId}-${index}`}
                className={`table-row ${index % 2 === 0 ? "even" : ""}`}
                style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
              >
                <div className="table-cell primary">
                  {formatDateTime(
                    (order as PendingOrderData & {
                      createdAt?: string | number | Date;
                    }).createdAt ??
                      (order as PendingOrderData & {
                        timestamp?: string | number | Date;
                      }).timestamp,
                  )}
                </div>
                <div
                  className="table-cell center"
                  title={order.agentTaskId ?? undefined}
                >
                  {order.agentTaskId ? (
                      <span className="task-id-chip"  onClick={() => setExplainTaskId(order.agentTaskId ?? null)}>
                        {shortHashId(order.agentTaskId)}
                      </span>     
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell">{symbol}</div>
                <div className="table-cell center">{order.side || "—"}</div>
                <div className="table-cell center">
                  {getOrderTypeLabel(order.type)}
                </div>
                <div className="table-cell right">
                  {formatNumber(originalSize)}
                </div>
                <div className="table-cell right">
                  {formatNumber(filledSize)}
                </div>
                <div className="table-cell right">
                  {formatMoney(order.price)}
                </div>
                <div className="table-cell center">{getTriggerCondition(order)}</div>
                <div className="table-cell right">
                  {formatMoney(avgFilledPrice)}
                </div>
                <div className="table-cell right">
                  {formatMoney(orderValue)}
                </div>
                <div className="table-cell center">{order.status || "—"}</div>
                <div
                  className="table-cell right"
                  title={order.orderId || undefined}
                >
                  {order.orderId ? order.orderId.slice(0, 6) : "—"}
                </div>
              </div>
            );
          })
        )}
      </div>
      <ExplainActionModal
        isOpen={explainTaskId != null}
        agentTaskId={explainTaskId}
        baseURL={baseURL}
        walletAddress={walletAddress}
        onClose={() => setExplainTaskId(null)}
      />
    </div>
  );
}

export default React.memo(OrderHistory);
