import React, {
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { toast } from "sonner";
import { copyToClipboard } from "../ui/Toaster";
import { capitalize } from "./util";
import type { CompactType, LayoutItem } from "./type";
import "./layout.css";
import "./grid-editor.css";

export const GRID_COLS: Record<string, number> = {
  lg: 12,
  md: 10,
  sm: 6,
  xs: 4,
  xxs: 2,
};

export interface GridEditorProps {
  layout: LayoutItem[];
  currentBreakpoint?: string;
  compactType?: CompactType | string;
  cols?: Record<string, number>;
  className?: string;
  /** Called when the user exits layout edit mode. */
  onExitEditMode?: () => void;
}

function compareSlotIds(a: string, b: string): number {
  const aNum = Number.parseInt(a, 10);
  const bNum = Number.parseInt(b, 10);
  const aIsNum = !Number.isNaN(aNum) && String(aNum) === a;
  const bIsNum = !Number.isNaN(bNum) && String(bNum) === b;
  if (aIsNum && bIsNum) return aNum - bNum;
  if (aIsNum) return -1;
  if (bIsNum) return 1;
  return a.localeCompare(b);
}

function sortLayoutBySlotIndex(layout: LayoutItem[]): LayoutItem[] {
  return layout.slice().sort((a, b) => compareSlotIds(a.i, b.i));
}

function chunkItems<T>(items: T[], colCount: number): T[][] {
  if (colCount <= 1) return [items];
  const size = Math.ceil(items.length / colCount);
  return Array.from({ length: colCount }, (_, i) =>
    items.slice(i * size, (i + 1) * size),
  ).filter((col) => col.length > 0);
}

function estimateColumnCount(
  itemCount: number,
  budget: number,
  rowHeight: number,
  gap: number,
): number {
  if (itemCount === 0 || budget <= 0 || rowHeight <= 0) return 1;

  let cols = 1;
  while (cols < itemCount) {
    const rows = Math.ceil(itemCount / cols);
    const estimated = rows * rowHeight + Math.max(0, rows - 1) * gap;
    if (estimated <= budget) break;
    cols++;
  }
  return cols;
}

function renderLayoutItem(item: LayoutItem) {
  return (
    <div className="layoutItem" key={item.i}>
      <b>{item.i}</b>: [{item.x}, {item.y}, {item.w}, {item.h}]
    </div>
  );
}

export default function GridEditor({
  layout,
  currentBreakpoint,
  compactType,
  cols = GRID_COLS,
  className,
  onExitEditMode,
}: GridEditorProps) {
  const [isCopying, setIsCopying] = useState(false);
  const [matrixColCount, setMatrixColCount] = useState(1);
  const helpersRef = useRef<HTMLElement>(null);
  const matrixRef = useRef<HTMLDivElement>(null);
  const rowProbeRef = useRef<HTMLDivElement>(null);
  const layoutFingerprintRef = useRef("");

  const sortedLayout = useMemo(
    () => sortLayoutBySlotIndex(layout),
    [layout],
  );

  const layoutFingerprint = useMemo(
    () =>
      `${layout.length}:${sortedLayout.map((item) => item.i).join(",")}:${currentBreakpoint ?? ""}:${compactType ?? ""}`,
    [layout.length, sortedLayout, currentBreakpoint, compactType],
  );

  const matrixColumns = useMemo(
    () => chunkItems(sortedLayout, matrixColCount),
    [sortedLayout, matrixColCount],
  );

  const probeItem = sortedLayout[0];

  const recomputeMatrixColumns = useCallback(() => {
    const helpers = helpersRef.current;
    const probe = rowProbeRef.current;
    const matrix = matrixRef.current;

    if (!helpers || layout.length === 0) {
      setMatrixColCount(1);
      return;
    }

    const budget = helpers.offsetHeight;
    if (budget <= 0) return;

    const rowEl = probe?.querySelector(".layoutItem");
    const rowHeight =
      rowEl instanceof HTMLElement ? rowEl.offsetHeight : probe?.offsetHeight ?? 0;

    const colEl = matrix?.querySelector(".grid-editor__matrix-col");
    const gap = colEl
      ? parseFloat(getComputedStyle(colEl).rowGap) ||
        parseFloat(getComputedStyle(colEl).gap) ||
        0
      : 0;

    const layoutChanged = layoutFingerprintRef.current !== layoutFingerprint;
    layoutFingerprintRef.current = layoutFingerprint;

    setMatrixColCount((prev) => {
      if (layoutChanged) {
        return estimateColumnCount(layout.length, budget, rowHeight, gap);
      }

      if (matrix && matrix.offsetHeight > budget && prev < layout.length) {
        return prev + 1;
      }

      return prev;
    });
  }, [layout.length, layoutFingerprint]);

  useLayoutEffect(() => {
    recomputeMatrixColumns();
  }, [recomputeMatrixColumns, matrixColCount]);

  useLayoutEffect(() => {
    const helpers = helpersRef.current;
    if (!helpers) return;

    const observer = new ResizeObserver(() => {
      recomputeMatrixColumns();
    });
    observer.observe(helpers);
    return () => observer.disconnect();
  }, [recomputeMatrixColumns]);

  const handleCopyLayoutMatrix = useCallback(async () => {
    if (layout.length === 0 || isCopying) return;

    setIsCopying(true);
    try {
      const layoutMatrix = sortedLayout
        .map((item) => `  [${item.x}, ${item.y}, ${item.w}, ${item.h}]`)
        .join(",\n");
      const breakpointComment = currentBreakpoint
        ? `// ${currentBreakpoint}\n`
        : "";
      const text = `${breakpointComment}[\n${layoutMatrix},\n]`;
      const copied = await copyToClipboard(text);
      if (copied) {
        toast.success("Layout matrix copied", {
          description: currentBreakpoint
            ? `Breakpoint: ${currentBreakpoint}`
            : undefined,
        });
      } else {
        toast.error("Failed to copy layout matrix", {
          description: "Clipboard access may be blocked in this browser.",
        });
      }
    } catch (err) {
      console.error("Failed to copy layout matrix:", err);
      toast.error("Failed to copy layout matrix", {
        description: "Clipboard access may be blocked in this browser.",
      });
    } finally {
      setIsCopying(false);
    }
  }, [layout.length, sortedLayout, currentBreakpoint, isCopying]);

  const rootClassName = ["overview-layout", "layoutJSON", "grid-editor", className]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={rootClassName}>
      <div className="grid-editor__layout">
        <aside ref={helpersRef} className="grid-editor__helpers">
          {currentBreakpoint ? (
            <div className="terminal-label">
              Current Breakpoint (from GridViewerLayout): {currentBreakpoint} (
              {cols[currentBreakpoint] ?? "—"} columns)
            </div>
          ) : null}
          {compactType !== undefined ? (
            <div className="terminal-label">
              Compaction type:{" "}
              {capitalize(compactType ?? "") || "No Compaction"}
            </div>
          ) : null}
          <span className="grid-editor__helper">
            Displayed as <code>[x, y, w, h]</code>
          </span>
        </aside>
        <div ref={matrixRef} className="grid-editor__matrix">
          {sortedLayout.length > 0 ? (
            matrixColumns.map((colItems, colIdx) => (
              <div key={colIdx} className="grid-editor__matrix-col">
                {colItems.map((item) => renderLayoutItem(item))}
              </div>
            ))
          ) : (
            <span className="grid-editor__empty">No layout items</span>
          )}
        </div>
        <div className="grid-editor__controls">
          <button
            type="button"
            className="btn btn-secondary terminal-interactive"
            onClick={handleCopyLayoutMatrix}
            disabled={layout.length === 0 || isCopying}
          >
            Copy
          </button>
          {onExitEditMode ? (
            <button
              type="button"
              className="btn btn-secondary terminal-interactive"
              onClick={onExitEditMode}
            >
              Exit Edit
            </button>
          ) : null}
        </div>
      </div>
      {probeItem ? (
        <div
          ref={rowProbeRef}
          className="grid-editor__row-probe"
          aria-hidden="true"
        >
          {renderLayoutItem(probeItem)}
        </div>
      ) : null}
    </div>
  );
}
