import React from "react";
import { DEFAULT_BASE_URL } from "../../../constants";
import MarketContextChip from "../MarketContextChip";
import { useReportTierTasks } from "../../../hooks/useReportTierTasks";
import { useSubscription } from "../../../context/SubscriptionContext";
import { getTaskReportingMeta } from "../reportTier";
import type { ReportTier } from "../../../store/types";
import FleetHeartbeat from "./FleetHeartbeat";
import RiskEnvelopeGauge from "./RiskEnvelopeGauge";
import RegimeVolChip from "./RegimeVolChip";
import HighAControlRow from "./HighAControlRow";
import { useHighATickerMetrics } from "./useHighATickerMetrics";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";
import "./highATickerBar.css";

export interface HighATickerBarProps {
  height?: string;
  baseURL?: string;
  selectedMarketId: string;
  onOpenTickerSelection?: () => void;
  tickerSelectionOpen?: boolean;
  selectionAnchorRef?: React.RefObject<HTMLDivElement | null>;
  containerRef?: React.RefObject<HTMLElement | null>;
  onMarketSelect?: (marketId: string) => void;
  layoutBreakpoint?: string;
  isMobile?: boolean;
  onFocusSpotlight?: () => void;
  onOpenTierAudit?: (tier: ReportTier) => void;
  /** T4 incident banner grows slot 0 when true */
  incidentExpanded?: boolean;
}

function HighATickerBar({
  height,
  baseURL = DEFAULT_BASE_URL,
  selectedMarketId,
  onOpenTickerSelection,
  tickerSelectionOpen = false,
  selectionAnchorRef,
  containerRef,
  onFocusSpotlight,
  onOpenTierAudit,
  incidentExpanded = false,
}: HighATickerBarProps): JSX.Element {
  const {
    tierCounts,
    needsYouCount,
    escalated,
    silentCount,
    watchingCount,
    liveExecutingCount,
    spotlight,
    policy,
  } = useReportTierTasks("highAgency");

  const { isConnected } = useSubscription();
  const metrics = useHighATickerMetrics(
    tierCounts,
    watchingCount,
    liveExecutingCount,
  );

  const spotlightTier = spotlight
    ? getTaskReportingMeta(spotlight, policy).reportTier
    : null;
  const showIncidentBanner =
    incidentExpanded && spotlightTier === "T4";

  const rootClass = [
    "high-a-ticker-bar",
    escalated ? "high-a-ticker-bar--escalated" : "high-a-ticker-bar--calm",
    showIncidentBanner ? "high-a-ticker-bar--incident" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <header
      ref={containerRef as React.RefObject<HTMLElement>}
      className={rootClass}
      style={height ? { minHeight: height } : undefined}
      data-high-a-ticker
      data-calm={!escalated ? "true" : undefined}
      data-escalated={escalated ? "true" : undefined}
    >
      {showIncidentBanner ? (
        <BubbleTip id={BUBBLE_TIP_IDS.highAIncidentBanner}>
          <div className="high-a-incident-banner" role="alert">
            <span className="high-a-incident-label">T4 Incident</span>
            <span className="high-a-incident-detail">
              {spotlight?.description ?? "Hard-stop exception requires supervisor action"}
            </span>
          </div>
        </BubbleTip>
      ) : null}

      <div className="high-a-row high-a-row--status">
        <div className="high-a-zone high-a-zone--left">
          <MarketContextChip
            baseURL={baseURL}
            selectedMarketId={selectedMarketId}
            onOpenTickerSelection={onOpenTickerSelection}
            tickerSelectionOpen={tickerSelectionOpen}
            selectionAnchorRef={selectionAnchorRef}
          />
          <RegimeVolChip
            baseURL={baseURL}
            selectedMarketId={selectedMarketId}
          />
        </div>

        <div className="high-a-zone high-a-zone--center">
          <FleetHeartbeat
            lastActionMs={metrics.lastActionMs}
            isConnected={isConnected}
          />
          <RiskEnvelopeGauge
            deployedPct={metrics.deployedPct}
            dayPnlUsd={metrics.dayPnlUsd}
            riskScore={metrics.riskScore}
            riskCap={metrics.riskCap}
          />
        </div>
      </div>

      <HighAControlRow
        silentCount={silentCount}
        watchingCount={watchingCount}
        needsYouCount={needsYouCount}
        escalated={escalated}
        onFocusSpotlight={onFocusSpotlight}
        onOpenTierAudit={onOpenTierAudit}
      />
    </header>
  );
}

export default React.memo(HighATickerBar);
