import React, { Fragment } from "react";
import { useNavigate } from "react-router-dom";
import { TableHeaderCell } from "../smartlayout";
import { TickerSelectionRow } from "./TickerSelectionRow";
import { TickerSelectionRowMobile } from "./TickerSelectionRowMobile";
import { TickerSelectionTableFooter } from "./TickerSelectionTableFooter";
import type {
  TickerCategory,
  TickerSelectionRow as RowData,
  TickerSortField,
  SortDirection,
} from "./types";

const DESKTOP_GRID =
  "minmax(220px, 2fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(90px, 1fr)";

const MOBILE_GRID = "1.4fr 1fr 0.8fr 0.8fr";

interface TickerSelectionTableProps {
  rows: RowData[];
  category: TickerCategory;
  selectedMarketId: string;
  sortField: TickerSortField;
  sortDirection: SortDirection;
  onSort: (field: TickerSortField) => void;
  onSelect: (marketId: string) => void;
  onFavoriteToggle: (marketId: string) => void;
  isMobile?: boolean;
}

function renderRowsWithSections(
  rows: RowData[],
  renderRow: (row: RowData) => React.ReactNode,
): React.ReactNode {
  let lastGroup: string | undefined;
  let soonHeaderShown = false;

  return rows.map((row) => {
    const nodes: React.ReactNode[] = [];

    if (row.comingSoon) {
      if (!soonHeaderShown) {
        soonHeaderShown = true;
        nodes.push(
          <div key="coming-soon-header" className="ticker-selection-section-header">
            COMING SOON
          </div>,
        );
      }
      if (row.comingSoonGroup && row.comingSoonGroup !== lastGroup) {
        lastGroup = row.comingSoonGroup;
        nodes.push(
          <div
            key={`group-${row.comingSoonGroup}`}
            className="ticker-selection-section-subheader"
          >
            {row.comingSoonGroup}
          </div>,
        );
      }
    }

    nodes.push(<Fragment key={row.marketId}>{renderRow(row)}</Fragment>);
    return nodes;
  });
}

export function TickerSelectionTable({
  rows,
  category,
  selectedMarketId,
  sortField,
  sortDirection,
  onSort,
  onSelect,
  onFavoriteToggle,
  isMobile = false,
}: TickerSelectionTableProps): JSX.Element {
  const navigate = useNavigate();
  const handleBuySpotAtNav = () => {
    const selectedRow = rows.find((row) => row.marketId === selectedMarketId);
    if (category === "index" && selectedRow?.navRoute) {
      navigate(selectedRow.navRoute);
      return;
    }
    navigate("/cindex");
  };

  const rowNodes = renderRowsWithSections(rows, (row) =>
    isMobile ? (
      <TickerSelectionRowMobile
        row={row}
        isSelected={row.marketId === selectedMarketId}
        onSelect={onSelect}
        onFavoriteToggle={onFavoriteToggle}
      />
    ) : (
      <TickerSelectionRow
        row={row}
        isSelected={row.marketId === selectedMarketId}
        onSelect={onSelect}
        onFavoriteToggle={onFavoriteToggle}
      />
    ),
  );

  if (isMobile) {
    return (
      <div className="ticker-selection-table-wrap">
        <div
          className="ticker-selection-table-header ticker-selection-table-header--mobile"
          style={{ gridTemplateColumns: MOBILE_GRID }}
        >
          <TableHeaderCell
            field="symbol"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={onSort}
            left
          >
            Market
          </TableHeaderCell>
          <TableHeaderCell
            field="price"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={onSort}
            left
          >
            Last Price / 24h
          </TableHeaderCell>
          <TableHeaderCell
            field="volume"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={onSort}
            left
          >
            Volume
          </TableHeaderCell>
          <TableHeaderCell
            field="openInterest"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={onSort}
            left
          >
            OI
          </TableHeaderCell>
        </div>
        <div className="ticker-selection-table-body">
          {rows.length === 0 ? (
            <div className="ticker-selection-empty">No assets match your filters.</div>
          ) : (
            rowNodes
          )}
        </div>
        <TickerSelectionTableFooter
          category={category}
          onBuySpotAtNav={handleBuySpotAtNav}
        />
      </div>
    );
  }

  return (
    <div className="ticker-selection-table-wrap">
      <div
        className="ticker-selection-table-header"
        style={{ gridTemplateColumns: DESKTOP_GRID }}
      >
        <TableHeaderCell
          field="symbol"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={onSort}
          center
        >
          {category === "index" ? "Symbol" : "Asset"}
        </TableHeaderCell>
        <TableHeaderCell
          field="price"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={onSort}
          left
        >
          {category === "index" ? "Last Price" : "Price"}
        </TableHeaderCell>
        <TableHeaderCell
          field="change24h"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={onSort}
          left
        >
          24h Change
        </TableHeaderCell>
        <TableHeaderCell
          field="funding"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={onSort}
          left
        >
          {category === "index" ? "Funding" : "Ann. Funding"}
        </TableHeaderCell>
        <TableHeaderCell
          field="volume"
          currentSortField={sortField}
          sortDirection={sortDirection}
          onSort={onSort}
        >
          24h Volume
        </TableHeaderCell>
      </div>
      <div className="ticker-selection-table-body">
        {rows.length === 0 ? (
          <div className="ticker-selection-empty">No assets match your filters.</div>
        ) : (
          rowNodes
        )}
      </div>
      <TickerSelectionTableFooter
        category={category}
        onBuySpotAtNav={handleBuySpotAtNav}
      />
    </div>
  );
}
