import { useEffect, useRef } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useWelcomeTour } from "../../mormv1/tutorials/welcome-tour";
import { hasSeenWelcome } from "./welcomeTourStorage";

export interface UseWelcomeTourOrchestrationOptions {
  portfolioReady: boolean;
  walletAddress: string;
  isJellyMode: boolean;
}

export function useWelcomeTourOrchestration({
  portfolioReady,
  walletAddress,
  isJellyMode,
}: UseWelcomeTourOrchestrationOptions): void {
  const location = useLocation();
  const navigate = useNavigate();
  const { openWelcomeModal, isTradeUiReady } = useWelcomeTour();
  /** One-time redirect to /trade after first connect; must not re-fire when user browses elsewhere. */
  const sentToTradeRef = useRef(false);
  /** Welcome hub opened once per connect session. */
  const welcomeOpenedRef = useRef(false);

  useEffect(() => {
    if (!walletAddress?.trim()) {
      sentToTradeRef.current = false;
      welcomeOpenedRef.current = false;
    }
  }, [walletAddress]);

  useEffect(() => {
    if (welcomeOpenedRef.current || hasSeenWelcome()) return;
    if (!portfolioReady || !walletAddress?.trim() || isJellyMode) return;

    if (location.pathname !== "/trade") {
      if (!sentToTradeRef.current) {
        sentToTradeRef.current = true;
        navigate("/trade");
      }
      return;
    }

    if (!isTradeUiReady) return;

    welcomeOpenedRef.current = true;
    openWelcomeModal();
  }, [
    portfolioReady,
    walletAddress,
    isJellyMode,
    isTradeUiReady,
    location.pathname,
    navigate,
    openWelcomeModal,
  ]);
}
