import type { ShortcutActionId } from "../../utils/keyboardShortcuts";

export type ShortcutKeyToken =
  | "Mod"
  | "Shift"
  | "Enter"
  | "Esc"
  | "Tab"
  | "Space"
  | "↑"
  | "↓"
  | "A"
  | "E"
  | "K"
  | "S"
  | "J"
  | "1"
  | "2"
  | "3"
  | "4";

export interface KeyboardShortcutRow {
  keys: ShortcutKeyToken[];
  action: string;
  note?: string;
  customizableActionId?: ShortcutActionId;
}

export interface KeyboardShortcutSection {
  id: string;
  title: string;
  intro?: string;
  rows: KeyboardShortcutRow[];
}

export interface KeyboardShortcutNoteSection {
  id: string;
  title: string;
  bullets: string[];
}

