import React from "react";
import { createPortal } from "react-dom";

import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../../components/ui/overlay";
import { formatCurrency } from "../../sdk/utils/display";
import { COPY_TOUR_MIN_SPOT_USDC } from "./constants";
import { useCopyTour } from "./CopyTourContext";
import { WELCOME_MODAL_Z_INDEX } from "../welcome-tour/constants";
import "../welcome-tour/WelcomeModal.css";

export function CopyTourPreflightModal(): JSX.Element | null {
  const {
    showPreflightModal,
    preflightSpotBalance,
    preflightDepositAmount,
    dismissPreflight,
    startPreflightDeposit,
  } = useCopyTour();

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(showPreflightModal);

  useOverlayEscapeKey(showPreflightModal, dismissPreflight);

  if (!mounted) return null;

  return createPortal(
    <StaggeredOverlayRoot
      passThrough={!showPreflightModal}
      className="welcome-modal-overlay"
      style={{ zIndex: WELCOME_MODAL_Z_INDEX }}
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={dismissPreflight}
        style={backdropStyle}
        className="staggered-overlay-backdrop--onboard"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="welcome-modal copy-tour-preflight-modal staggered-overlay-panel--scale"
        aria-label="Fund your account first"
      >
        <div className="welcome-modal-header">
          <h2 id="copy-tour-preflight-title" className="welcome-modal-title">
            Fund your account first
          </h2>
          <p className="welcome-modal-subtitle">
            Copy trading moves USDC from spot into a cross-margin bucket. This guided demo
            requires at least {formatCurrency(COPY_TOUR_MIN_SPOT_USDC)} USDC in spot before
            mirroring an agent.
          </p>
        </div>
        <div className="welcome-modal-body">
          <p className="copy-tour-preflight-copy">
            Current spot balance:{" "}
            <strong>{formatCurrency(preflightSpotBalance)}</strong>
          </p>
          <p className="copy-tour-preflight-copy">
            Demo deposit needed:{" "}
            <strong>{formatCurrency(preflightDepositAmount)}</strong> USDC via the Morpheum
            Bridge.
          </p>
        </div>
        <div className="welcome-modal-footer">
          <button type="button" className="btn btn-secondary" onClick={dismissPreflight}>
            Not now
          </button>
          <button type="button" className="btn btn-primary" onClick={startPreflightDeposit}>
            Start demo deposit
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>,
    document.body,
  );
}
