import { useCallback, useLayoutEffect, useRef } from "react";
import {
  FEED_INSERT_DURATION_MS,
  FEED_INSERT_EASING,
} from "./feedAnimation";

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export interface UseFlipListInsertOptions {
  itemIds: string[];
  enteringId: string | null;
  enabled?: boolean;
}

function cancelShellAnimation(el: HTMLElement): void {
  el.style.transition = "none";
  el.style.transform = "";
  el.classList.remove("is-flipping");
}

function playFlip(
  el: HTMLElement,
  deltaY: number,
  durationMs: number,
  easing: string,
): void {
  cancelShellAnimation(el);

  el.classList.add("is-flipping");
  el.style.transform = `translateY(${deltaY}px)`;
  el.style.transition = "none";

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      el.style.transition = `transform ${durationMs}ms ${easing}`;
      el.style.transform = "translateY(0)";
    });
  });

  const onTransitionEnd = (event: TransitionEvent) => {
    if (event.propertyName !== "transform") return;
    el.removeEventListener("transitionend", onTransitionEnd);
    el.style.transition = "";
    el.style.transform = "";
    el.classList.remove("is-flipping");
  };
  el.addEventListener("transitionend", onTransitionEnd);
}

export function useFlipListInsert({
  itemIds,
  enteringId,
  enabled = true,
}: UseFlipListInsertOptions): (id: string) => (el: HTMLElement | null) => void {
  const refsRef = useRef<Map<string, HTMLElement>>(new Map());
  const prevTopsRef = useRef<Map<string, number>>(new Map());
  const prevIdsRef = useRef<string[]>([]);

  const setFlipRef = useCallback(
    (id: string) => (el: HTMLElement | null) => {
      if (el) {
        refsRef.current.set(id, el);
      } else {
        refsRef.current.delete(id);
      }
    },
    [],
  );

  useLayoutEffect(() => {
    const prevIds = prevIdsRef.current;
    const prevTops = prevTopsRef.current;
    const flipEnabled = enabled && !prefersReducedMotion();

    // Detect prepend when head changes — covers growing lists and capacity-stable
    // inserts (X news trim drops the tail while prepending at index 0).
    const isPrepend =
      itemIds.length > 0 &&
      prevIds.length > 0 &&
      itemIds[0] !== prevIds[0];

    if (itemIds.length === 0) {
      refsRef.current.forEach(cancelShellAnimation);
      prevTopsRef.current = new Map();
      prevIdsRef.current = [];
      return;
    }

    const currentTops = new Map<string, number>();
    for (const id of itemIds) {
      const el = refsRef.current.get(id);
      if (el) {
        currentTops.set(id, el.getBoundingClientRect().top);
      }
    }

    if (flipEnabled && isPrepend) {
      refsRef.current.forEach(cancelShellAnimation);

      for (const id of itemIds) {
        if (id === enteringId) continue;
        if (!prevTops.has(id)) continue;

        const el = refsRef.current.get(id);
        const prevTop = prevTops.get(id);
        const newTop = currentTops.get(id);
        if (!el || prevTop == null || newTop == null) continue;

        const deltaY = prevTop - newTop;
        if (Math.abs(deltaY) < 0.5) continue;

        playFlip(el, deltaY, FEED_INSERT_DURATION_MS, FEED_INSERT_EASING);
      }
    }

    prevTopsRef.current = currentTops;
    prevIdsRef.current = itemIds;
  }, [itemIds, enteringId, enabled]);

  return setFlipRef;
}
