import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { CandlestickData } from "lightweight-charts";
import { BinanceClient } from "../sdk/api/binance/BinanceClient";
import {
  BINANCE_KLINE_DEFAULT_START_MS,
  binanceRestKlineToCandle,
  binanceRestKlineVolume,
  binanceWsKlineToCandle,
  binanceWsKlineToUpdate,
  mergeBinanceCandles,
  mergeVolumeByTime,
  toBinanceInterval,
  toBinanceSymbol,
} from "../sdk/api/binance/klineUtil";
import { BINANCE_SPOT_WS_BASE } from "../sdk/api/binance/types";
import type { BinanceWsKlinePayload } from "../sdk/api/binance/types";

export interface BinanceKlineConfig {
  symbol: string;
  interval?: string;
  /** When set, fetches the latest N candles only (no historical pagination). */
  limit?: number;
  /** Inclusive start of historical range (ms). Defaults to May 20, 2026 when limit is unset. */
  startTime?: number;
  /** Exclusive end of historical range (ms). Defaults to now. */
  endTime?: number;
  restBaseUrl?: string;
  /** When false, skips Binance WebSocket live updates (REST history only). */
  enableLiveWs?: boolean;
}

const WS_RECONNECT_BASE_MS = 1000;
const WS_RECONNECT_MAX_MS = 30000;

function buildWsUrl(symbol: string, interval: string): string {
  const pair = toBinanceSymbol(symbol).toLowerCase();
  const binanceInterval = toBinanceInterval(interval);
  return `${BINANCE_SPOT_WS_BASE}/${pair}@kline_${binanceInterval}`;
}

export function useBinanceKline(config: BinanceKlineConfig) {
  const useLatestOnly = config.limit != null;
  const historicalStartTime = config.startTime ?? BINANCE_KLINE_DEFAULT_START_MS;
  const historicalEndTime = config.endTime;
  const latestLimit = config.limit ?? 500;
  const enableLiveWs = config.enableLiveWs !== false;

  const binanceSymbol = useMemo(() => toBinanceSymbol(config.symbol), [config.symbol]);
  const binanceInterval = useMemo(
    () => toBinanceInterval(config.interval ?? "5m"),
    [config.interval],
  );

  const [historicalCandles, setHistoricalCandles] = useState<CandlestickData[]>([]);
  const [historicalVolumeByTime, setHistoricalVolumeByTime] = useState<Map<number, number>>(
    () => new Map(),
  );
  const [liveCandles, setLiveCandles] = useState<CandlestickData[]>([]);
  const [liveVolumeByTime, setLiveVolumeByTime] = useState<Map<number, number>>(() => new Map());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isConnected, setIsConnected] = useState(false);

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectAttemptRef = useRef(0);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const mountedRef = useRef(false);

  const clearReconnectTimer = useCallback(() => {
    if (reconnectTimerRef.current != null) {
      clearTimeout(reconnectTimerRef.current);
      reconnectTimerRef.current = null;
    }
  }, []);

  const disconnectWs = useCallback(() => {
    clearReconnectTimer();
    const ws = wsRef.current;
    if (!ws) return;

    ws.onopen = null;
    ws.onmessage = null;
    ws.onerror = null;
    ws.onclose = null;
    if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
      ws.close();
    }
    wsRef.current = null;
  }, [clearReconnectTimer]);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      disconnectWs();
    };
  }, [disconnectWs]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    setHistoricalCandles([]);
    setHistoricalVolumeByTime(new Map());
    setLiveCandles([]);
    setLiveVolumeByTime(new Map());

    const client = new BinanceClient(
      config.restBaseUrl ? { restBaseUrl: config.restBaseUrl } : {},
    );

    const endTime = historicalEndTime ?? Date.now();

    const loadHistory = useLatestOnly
      ? client.getKlines(binanceSymbol, binanceInterval, latestLimit)
      : client.getKlinesRange(
          binanceSymbol,
          binanceInterval,
          historicalStartTime,
          endTime,
        );

    loadHistory
      .then((rows) => {
        if (cancelled || !mountedRef.current) return;
        const candles = rows
          .map(binanceRestKlineToCandle)
          .filter((candle): candle is CandlestickData => candle !== null);
        const volumes = new Map<number, number>();
        for (const row of rows) {
          const entry = binanceRestKlineVolume(row);
          if (entry) volumes.set(entry.time as number, entry.volume);
        }
        setHistoricalCandles(candles);
        setHistoricalVolumeByTime(volumes);
      })
      .catch((err: unknown) => {
        if (cancelled || !mountedRef.current) return;
        setError(err instanceof Error ? err.message : "Failed to load Binance kline history");
        setHistoricalCandles([]);
        setHistoricalVolumeByTime(new Map());
      })
      .finally(() => {
        if (!cancelled && mountedRef.current) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [
    binanceSymbol,
    binanceInterval,
    config.restBaseUrl,
    historicalEndTime,
    historicalStartTime,
    latestLimit,
    useLatestOnly,
  ]);

  const handleWsMessage = useCallback((event: MessageEvent) => {
    if (!mountedRef.current) return;

    try {
      const payload = JSON.parse(String(event.data)) as BinanceWsKlinePayload;
      if (payload.e !== "kline" || !payload.k) return;

      const candle = binanceWsKlineToCandle(payload.k);
      const update = binanceWsKlineToUpdate(payload.k);
      const chartTime = candle.time as number;
      setLiveCandles((prev) => {
        const next = [...prev];
        const idx = next.findIndex((c) => (c.time as number) === chartTime);
        if (idx >= 0) {
          next[idx] = candle;
        } else {
          next.push(candle);
        }
        return mergeBinanceCandles(next);
      });
      if (update.volume != null && update.volume > 0) {
        setLiveVolumeByTime((prev) => {
          const next = new Map(prev);
          next.set(chartTime, update.volume as number);
          return next;
        });
      }
    } catch (err) {
      console.warn("[useBinanceKline] Failed to parse WS message:", err);
    }
  }, []);

  const connectWs = useCallback(() => {
    if (!mountedRef.current) return;

    disconnectWs();

    const wsUrl = buildWsUrl(config.symbol, config.interval ?? "5m");
    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      if (!mountedRef.current) return;
      reconnectAttemptRef.current = 0;
      setIsConnected(true);
      setError(null);
    };

    ws.onmessage = handleWsMessage;

    ws.onerror = () => {
      if (!mountedRef.current) return;
      setError("Binance WebSocket connection error");
    };

    ws.onclose = () => {
      if (!mountedRef.current) return;
      setIsConnected(false);
      wsRef.current = null;

      const delay = Math.min(
        WS_RECONNECT_BASE_MS * 2 ** reconnectAttemptRef.current,
        WS_RECONNECT_MAX_MS,
      );
      reconnectAttemptRef.current += 1;
      reconnectTimerRef.current = setTimeout(() => {
        if (mountedRef.current) connectWs();
      }, delay);
    };
  }, [clearReconnectTimer, config.symbol, config.interval, disconnectWs, handleWsMessage]);

  useEffect(() => {
    if (!enableLiveWs) {
      return;
    }

    reconnectAttemptRef.current = 0;
    setLiveCandles([]);
    setLiveVolumeByTime(new Map());
    connectWs();

    return () => {
      disconnectWs();
    };
  }, [binanceSymbol, binanceInterval, connectWs, disconnectWs, enableLiveWs]);

  const candles = useMemo(() => {
    if (loading) return [];
    return mergeBinanceCandles([...historicalCandles, ...liveCandles]);
  }, [loading, historicalCandles, liveCandles]);

  const volumeByTime = useMemo(() => {
    if (loading) return new Map<number, number>();
    return mergeVolumeByTime(historicalVolumeByTime, liveVolumeByTime);
  }, [loading, historicalVolumeByTime, liveVolumeByTime]);

  return {
    candles,
    volumeByTime,
    loading,
    historyLoaded: !loading,
    error,
    isConnected,
    symbol: binanceSymbol,
    interval: binanceInterval,
  };
}
