import { useQuery } from "@tanstack/react-query";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import { generateTelemetryPanels } from "./mockData";

/** Simulated deep-telemetry panel series, polled on a gentle interval. */
export function useTelemetryPanels() {
  const { throughputTier, validatorCount } = useNetworkHealthDemo();

  return useQuery({
    queryKey: ["network-health", "telemetry", throughputTier, validatorCount],
    queryFn: async () =>
      generateTelemetryPanels({ throughputTier, validatorCount }),
    refetchInterval: 5_000,
  });
}
