import React from "react";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import { shortHashId } from "../../utils/hashId";
import PortfolioHeroViewNav from "./PortfolioHeroViewNav";
import type { PortfolioHeroView } from "./portfolioHeroView";
import "../tables/agentTasks.css";
import "./portfolio.css";

export interface PortfolioHeroTitleProps {
  height?: string;
  walletAddress?: string;
  activeView?: PortfolioHeroView;
  onViewChange?: (view: PortfolioHeroView) => void;
}

function noopViewChange(): void {}

function PortfolioHeroTitle({
  height = "100%",
  walletAddress = "",
  activeView = "overview",
  onViewChange = noopViewChange,
}: PortfolioHeroTitleProps): JSX.Element {
  const { selectedAgentId, setSelectedAgentId, getAgentById } =
    useTradingAgents();
  const focusedAgent = selectedAgentId
    ? getAgentById(selectedAgentId)
    : undefined;

  const trimmed = walletAddress.trim();
  const displayAddress =
    trimmed.length > 10
      ? `${trimmed.slice(0, 6)}…${trimmed.slice(-4)}`
      : trimmed;

  const showWallet = trimmed.length > 0;
  const showFocus = focusedAgent != null;

  return (
    <div
      className="portfolio-slot portfolio-slot--flush portfolio-hero-title-slot"
      style={{ height }}
    >
      <div className="portfolio-hero-title-primary">
        <h1 className="portfolio-hero-title-heading">Portfolio</h1>
        {showWallet ? (
          <span className="portfolio-hero-title-wallet" title={trimmed}>
            Master: {displayAddress || shortHashId(trimmed)}
          </span>
        ) : null}
      </div>

      {showFocus ? (
        <div className="portfolio-hero-title-focus-col">
          <span
            className="portfolio-hero-title-focus"
            aria-label={`Focused on ${focusedAgent.displayName}`}
          >
            <span className="portfolio-hero-title-focus-label">Focused</span>
            {focusedAgent.icon ? (
              <span aria-hidden>{focusedAgent.icon}</span>
            ) : null}
            <span className="portfolio-hero-title-focus-name">
              {focusedAgent.displayName}
            </span>
            <span className="task-id-chip" title={focusedAgent.id}>
              {shortHashId(focusedAgent.id)}
            </span>
            <button
              type="button"
              className="portfolio-hero-title-focus-clear"
              onClick={() => setSelectedAgentId(null)}
              aria-label="Clear agent focus"
            >
              ×
            </button>
          </span>
        </div>
      ) : null}

      <PortfolioHeroViewNav
        activeView={activeView}
        onViewChange={onViewChange}
      />
    </div>
  );
}

export default React.memo(PortfolioHeroTitle);
