import { COPY_TOUR_STORAGE_KEY } from "../../mormv1/tutorials/copy-tour/constants";

export function hasSeenCopyTour(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(COPY_TOUR_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markCopyTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(COPY_TOUR_STORAGE_KEY, "1");
  } catch {
    // ignore
  }
}

export function clearCopyTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(COPY_TOUR_STORAGE_KEY);
  } catch {
    // ignore
  }
}
