import { useCallback, useState } from "react";
import { toast } from "sonner";
import { useFiClient } from "./useFiClient";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { cancelMockOrder } from "../../offline/mock_data";
import {
  createErrorCopyAction,
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
} from "../components/ui/Toaster";
import type { ChartPendingOrderLineMeta } from "../components/finchartview/chartOrderLines";
import { resolveCancelOrderTargets } from "../components/finchartview/pendingOrderLineAnchor";

export interface UsePendingOrderCancelConfig {
  baseURL: string;
  mnemonic?: string;
  walletAddress?: string;
  marketId: string;
  metaByLineId: Map<string, ChartPendingOrderLineMeta>;
}

export interface UsePendingOrderCancelResult {
  cancelingLineId: string | null;
  cancelLine: (lineId: string, meta: ChartPendingOrderLineMeta) => Promise<void>;
}

export function usePendingOrderCancel(
  config: UsePendingOrderCancelConfig,
): UsePendingOrderCancelResult {
  const { baseURL, mnemonic, walletAddress, marketId, metaByLineId } = config;
  const [cancelingLineId, setCancelingLineId] = useState<string | null>(null);
  const { client: exchangeClient, isReady: exchangeReady } = useFiClient({
    baseURL,
    mnemonic,
  });

  const cancelLine = useCallback(
    async (lineId: string, meta: ChartPendingOrderLineMeta) => {
      if (cancelingLineId) {
        toast.info("Cancellation in progress", {
          description: "Please wait for the current cancellation to complete.",
        });
        return;
      }

      const targets = resolveCancelOrderTargets(meta, metaByLineId, marketId);
      if (targets.length === 0) {
        toast.error("Cannot cancel order", {
          description: "No valid order targets for this line.",
        });
        return;
      }

      setCancelingLineId(lineId);
      const loadingMessage =
        targets.length > 1 ? "Canceling orders..." : "Canceling order...";
      const loadingDescription =
        targets.length > 1
          ? `Canceling ${targets.length} orders at this price`
          : `Canceling order ${targets[0]!.orderId}`;
      const loadingId = toastLoading(loadingMessage, {
        description: loadingDescription,
      });

      try {
        if (isOfflineMode(baseURL)) {
          let cancelledCount = 0;
          for (const target of targets) {
            if (cancelMockOrder(target.orderId, walletAddress)) {
              cancelledCount += 1;
            }
          }
          if (cancelledCount > 0) {
            toastCompleteSuccess(
              loadingId,
              cancelledCount > 1
                ? "Orders canceled successfully"
                : "Order canceled successfully",
              {
                description:
                  cancelledCount > 1
                    ? `${cancelledCount} orders canceled.`
                    : `Order ${targets[0]!.orderId} has been canceled.`,
              },
            );
          } else {
            const errorMsg = "Orders were not found or already canceled.";
            toastCompleteError(loadingId, "Failed to cancel order", {
              description: errorMsg,
              action: createErrorCopyAction(errorMsg),
            });
          }
          return;
        }

        if (!exchangeClient || !exchangeReady) {
          toastCompleteError(loadingId, "Exchange client not ready", {
            description: "Please wait for the exchange client to initialize.",
            action: createErrorCopyAction("Exchange client not ready"),
          });
          return;
        }

        for (const target of targets) {
          const response = await exchangeClient.cancelOrder({
            orderId: target.orderId,
            marketId: target.marketId,
          });
          const isSuccess =
            response.success === true ||
            response.result?.success === true ||
            (response && !response.error && !response.message);
          if (!isSuccess) {
            const errorMsg =
              response?.error ||
              response?.message ||
              response?.response?.error ||
              `Failed to cancel order ${target.orderId}`;
            throw new Error(errorMsg);
          }
        }

        toastCompleteSuccess(
          loadingId,
          targets.length > 1
            ? "Orders canceled successfully"
            : "Order canceled successfully",
          {
            description:
              targets.length > 1
                ? `${targets.length} orders canceled.`
                : `Order ${targets[0]!.orderId} has been canceled.`,
          },
        );
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : "Unknown error occurred";
        toastCompleteError(loadingId, "Failed to cancel order", {
          description: errorMessage,
          duration: 6000,
          action: createErrorCopyAction(errorMessage),
        });
      } finally {
        setCancelingLineId(null);
      }
    },
    [baseURL, cancelingLineId, exchangeClient, exchangeReady, marketId, metaByLineId, walletAddress],
  );

  return { cancelingLineId, cancelLine };
}
