import React, { useMemo } from "react";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useMarkets } from "../../hooks/useMarkets";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { shortHashId } from "../../utils/hashId";
import type { AgentTask, AgentTaskStatus } from "../../store/types";
import {
  getTaskReportingMetaResolved,
  isGatedTier,
} from "../tradeagent/reportTier";
import { createTaskPolicyResolver } from "../../store/bucketPolicyStore";
import GuardrailIntentCardExtras from "../tradeagent/GuardrailIntentCardExtras";
import "./bucketCollection.css";

export interface BucketAgentsPanelProps {
  bucketId: string;
  baseURL: string;
  authToken?: string;
  isMobile?: boolean;
  canManage?: boolean;
  editing?: boolean;
}

function formatDateTime(value?: string | null): string {
  if (value == null || value === "") return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function getStatusConfig(status: AgentTaskStatus) {
  return (
    AGENT_TASK_STATUS_CONFIG[status] ?? {
      label: status,
      tone: "muted" as const,
    }
  );
}

function BucketAgentsPanel({
  bucketId,
  baseURL,
  authToken,
  isMobile = false,
  canManage = true,
  editing = true,
}: BucketAgentsPanelProps): JSX.Element {
  const {
    tasks,
    pauseTask,
    resumeTask,
    forceExecute,
    rejectTask,
  } = useAgentTasks();
  const { getSymbolByMarketId } = useMarkets({
    baseURL,
    sessionToken: authToken ?? "",
    autoFetchMarkets: false,
  });

  const policyResolver = useMemo(
    () => createTaskPolicyResolver("highAgency"),
    [],
  );

  const bucketTasks = useMemo(() => {
    return tasks.filter(
      (task) => task.bucketId?.toString() === bucketId.toString(),
    );
  }, [tasks, bucketId]);

  const activeCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "executing" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  const pendingCount = useMemo(
    () =>
      bucketTasks.filter(
        (t) => t.status === "pending" || t.status === "watching",
      ).length,
    [bucketTasks],
  );

  if (bucketTasks.length === 0) {
    return (
      <p className="bucket-agents-modal-empty">
        No agent tasks are linked to this bucket.
      </p>
    );
  }

  return (
    <div className="bucket-agents-panel">
      <p className="bucket-agents-panel-summary bucket-rules-meta-text">
        {activeCount} active · {pendingCount} pending
      </p>

      <ul className="bucket-agents-modal-list">
        {bucketTasks.map((task: AgentTask, index) => {
          const statusCfg = getStatusConfig(task.status);
          const symbol = task.marketId
            ? getSymbolByMarketId(task.marketId) || `m-${task.marketId}`
            : "—";
          const meta = getTaskReportingMetaResolved(task, policyResolver);
          const isGated =
            (task.status === "pending" || task.status === "watching") &&
            isGatedTier(meta.reportTier);
          const isPausable =
            task.status === "executing" || task.status === "watching";

          return (
            <li
              key={task.id}
              className="bucket-agents-modal-item"
              style={
                isMobile
                  ? ({ "--item-index": index } as React.CSSProperties)
                  : undefined
              }
            >
              <div className="bucket-agents-modal-item-header">
                <div className="bucket-agents-modal-item-leading">
                  <span
                    className="bucket-agents-task-id"
                    title={task.id}
                    aria-label={`Task ${shortHashId(task.id)}`}
                  >
                    {shortHashId(task.id)}
                  </span>
                  <span className="bucket-agents-status bucket-rules-meta-text">
                    {statusCfg.label}
                  </span>
                </div>
                <span className="terminal-value bucket-agents-modal-market">
                  {symbol}
                </span>
              </div>
              <div className="bucket-agents-modal-description">
                {task.description}
              </div>
              <div className="bucket-agents-modal-meta">
                <div className="bucket-agents-modal-meta-row">
                  <span className="terminal-label">Trigger</span>
                  <span className="terminal-value">{task.trigger || "—"}</span>
                </div>
                <div className="bucket-agents-modal-meta-row">
                  <span className="terminal-label">Updated</span>
                  <span className="terminal-value">
                    {formatDateTime(task.updatedAt)}
                  </span>
                </div>
              </div>
              {canManage && editing ? (
                <div className="bucket-agents-modal-actions">
                  {isGated ? (
                    <div className="bucket-agents-guardrail">
                      <GuardrailIntentCardExtras
                        task={task}
                        tooltipGroup="GuardrailCockpit"
                        onApprove={(taskId) => forceExecute(taskId)}
                        onReject={(taskId) => rejectTask(taskId)}
                        hideGateActions={false}
                      />
                    </div>
                  ) : isPausable ? (
                    <button
                      type="button"
                      className="btn btn-secondary"
                      onClick={() =>
                        task.status === "paused"
                          ? resumeTask(task.id)
                          : pauseTask(task.id)
                      }
                    >
                      {task.status === "paused" ? "Resume" : "Pause"}
                    </button>
                  ) : null}
                </div>
              ) : null}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export default React.memo(BucketAgentsPanel);
