import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  getLayoutBottomRow,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the index page layout */
export const INDEX_SLOT_INDICES = {
  title: 0,
  chart: 1,
  constituents: 2,
  overview: 3,
  tabs: 4,
  metrics: 5,
  xNews: 6,
} as const;

export const INDEX_TAB_SLOT_INDEX = INDEX_SLOT_INDICES.tabs;

/** Slots collapsed on sm/xs/xxs */
export const INDEX_COLLAPSED_SLOTS = [6, 7, 8] as const;
/** Slots collapsed on lg (slot 6 X pulse is active) */
export const INDEX_COLLAPSED_SLOTS_LG = [7, 8] as const;
/** Slots collapsed on md (slot 6 X pulse is active beside overview) */
export const INDEX_COLLAPSED_SLOTS_MD = [7, 8] as const;

export const INDEX_ROW_HEIGHT = 30;
export const INDEX_MENUBAR_HEIGHT = 54;
export const INDEX_LAYOUT_MARGIN = 10;
export const INDEX_VIEWPORT_FUDGE_PX = 4;

export const INDEX_TITLE_ROWS = 4;
export const INDEX_METRICS_ROWS = 4;
export const INDEX_CHART_ROWS = 8;
export const INDEX_CONSTITUENTS_ROWS = 10;
/** md/sm stacked: full-width overview between chart and constituents */
export const INDEX_OVERVIEW_ROWS_STACKED = 15;
/** @deprecated Use INDEX_OVERVIEW_ROWS_STACKED */
export const INDEX_TICKET_ROWS_STACKED = INDEX_OVERVIEW_ROWS_STACKED;
export const INDEX_BASE_TAB_ROWS = 6;
export const INDEX_SCROLL_TAB_ROWS = 12;

export const INDEX_TITLE_COLS_LG = 4;
export const INDEX_METRICS_COLS_LG = 8;

export const INDEX_HERO_START_ROW = INDEX_TITLE_ROWS;
export const INDEX_CONSTITUENTS_START_ROW =
  INDEX_HERO_START_ROW + INDEX_CHART_ROWS;
export const INDEX_TAB_START_ROW =
  INDEX_CONSTITUENTS_START_ROW + INDEX_CONSTITUENTS_ROWS;

/** lg: overview rail — taller than chart band for key parameters */
export const INDEX_OVERVIEW_ROWS_LG = 15;
/** @deprecated Use INDEX_OVERVIEW_ROWS_LG */
export const INDEX_TICKET_ROWS_LG = INDEX_OVERVIEW_ROWS_LG;
export const INDEX_X_NEWS_START_ROW =
  INDEX_HERO_START_ROW + INDEX_OVERVIEW_ROWS_LG;
export const INDEX_X_NEWS_ROWS_LG =
  INDEX_TAB_START_ROW + INDEX_SCROLL_TAB_ROWS - INDEX_X_NEWS_START_ROW;

export const INDEX_DEFAULT_BOTTOM_ROW =
  INDEX_TAB_START_ROW + INDEX_BASE_TAB_ROWS;
/** lg content bottom — X pulse rail and scroll tabs share row 34 */
export const INDEX_LG_CONTENT_BOTTOM_ROW =
  INDEX_X_NEWS_START_ROW + INDEX_X_NEWS_ROWS_LG;
export const INDEX_MIN_BOTTOM_ROW = INDEX_DEFAULT_BOTTOM_ROW;
export const INDEX_MAX_BOTTOM_ROW = 40;

export const INDEX_LEFT_COLS_LG = 8;
export const INDEX_RIGHT_COLS_LG = 4;
/** md: overview + X pulse side-by-side on the overview row */
export const INDEX_OVERVIEW_COLS_MD = 5;
export const INDEX_X_NEWS_COLS_MD = 5;

/** xs/xxs: overview before chart */
export const INDEX_STACKED_METRICS_START_ROW = INDEX_TITLE_ROWS;
export const INDEX_STACKED_TICKET_START_ROW =
  INDEX_TITLE_ROWS + INDEX_METRICS_ROWS;
export const INDEX_OVERVIEW_ROWS_MOBILE = 15;
/** @deprecated Use INDEX_OVERVIEW_ROWS_MOBILE */
export const INDEX_STACKED_TICKET_ROWS = INDEX_OVERVIEW_ROWS_MOBILE;
export const INDEX_STACKED_CHART_ROWS = 8;
export const INDEX_STACKED_CONSTITUENTS_ROWS = 10;
export const INDEX_STACKED_TAB_START_ROW =
  INDEX_STACKED_TICKET_START_ROW +
  INDEX_STACKED_TICKET_ROWS +
  INDEX_STACKED_CHART_ROWS +
  INDEX_STACKED_CONSTITUENTS_ROWS;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function splitTitleMetricsCols(cols: number): {
  titleW: number;
  metricsW: number;
  metricsX: number;
} {
  const titleW = Math.round(cols / 3);
  const metricsW = cols - titleW;
  return { titleW, metricsW, metricsX: titleW };
}

function titleMetricsSlot5(
  cols: number,
  stacked: boolean,
): [LayoutDefinition, LayoutDefinition] {
  if (stacked) {
    return [
      [0, 0, cols, INDEX_TITLE_ROWS],
      [0, INDEX_STACKED_METRICS_START_ROW, cols, INDEX_METRICS_ROWS],
    ];
  }

  if (cols === 12) {
    return [
      [0, 0, INDEX_TITLE_COLS_LG, INDEX_TITLE_ROWS],
      [INDEX_TITLE_COLS_LG, 0, INDEX_METRICS_COLS_LG, INDEX_METRICS_ROWS],
    ];
  }

  const { titleW, metricsW, metricsX } = splitTitleMetricsCols(cols);
  return [
    [0, 0, titleW, INDEX_TITLE_ROWS],
    [metricsX, 0, metricsW, INDEX_METRICS_ROWS],
  ];
}

function desktopIndexLayout(cols: number): LayoutConfigLest {
  const left = cols === 12 ? INDEX_LEFT_COLS_LG : Math.floor(cols * 0.67);
  const right = cols - left;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, INDEX_HERO_START_ROW, left, INDEX_CHART_ROWS],
    [0, INDEX_CONSTITUENTS_START_ROW, left, INDEX_CONSTITUENTS_ROWS],
    [left, INDEX_HERO_START_ROW, right, INDEX_OVERVIEW_ROWS_LG],
    [0, INDEX_TAB_START_ROW, left, INDEX_BASE_TAB_ROWS],
    metricsSlot,
    [left, INDEX_X_NEWS_START_ROW, right, INDEX_X_NEWS_ROWS_LG],
    COLLAPSED,
    COLLAPSED,
  ];
}

function stackedIndexLayout(cols: number): LayoutConfigLest {
  const yChart = INDEX_HERO_START_ROW;
  const yTicket = yChart + INDEX_CHART_ROWS;
  const yConstituents = yTicket + INDEX_OVERVIEW_ROWS_STACKED;
  const yTabs = yConstituents + INDEX_CONSTITUENTS_ROWS;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, yChart, cols, INDEX_CHART_ROWS],
    [0, yConstituents, cols, INDEX_CONSTITUENTS_ROWS],
    [0, yTicket, cols, INDEX_OVERVIEW_ROWS_STACKED],
    [0, yTabs, cols, INDEX_BASE_TAB_ROWS],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

function mdStackedIndexLayout(): LayoutConfigLest {
  const cols = 10;
  const yChart = INDEX_HERO_START_ROW;
  const yTicket = yChart + INDEX_CHART_ROWS;
  const yConstituents = yTicket + INDEX_OVERVIEW_ROWS_STACKED;
  const yTabs = yConstituents + INDEX_CONSTITUENTS_ROWS;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, yChart, cols, INDEX_CHART_ROWS],
    [0, yConstituents, cols, INDEX_CONSTITUENTS_ROWS],
    [0, yTicket, INDEX_OVERVIEW_COLS_MD, INDEX_OVERVIEW_ROWS_STACKED],
    [0, yTabs, cols, INDEX_BASE_TAB_ROWS],
    metricsSlot,
    [
      INDEX_OVERVIEW_COLS_MD,
      yTicket,
      INDEX_X_NEWS_COLS_MD,
      INDEX_OVERVIEW_ROWS_STACKED,
    ],
    COLLAPSED,
    COLLAPSED,
  ];
}

function mobileIndexLayout(cols: number): LayoutConfigLest {
  const yTicket = INDEX_STACKED_TICKET_START_ROW;
  const yChart = yTicket + INDEX_OVERVIEW_ROWS_MOBILE;
  const yConstituents = yChart + INDEX_STACKED_CHART_ROWS;
  const yTabs = INDEX_STACKED_TAB_START_ROW;
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, true);
  return [
    titleSlot,
    [0, yChart, cols, INDEX_STACKED_CHART_ROWS],
    [0, yConstituents, cols, INDEX_STACKED_CONSTITUENTS_ROWS],
    [0, yTicket, cols, INDEX_OVERVIEW_ROWS_MOBILE],
    [0, yTabs, cols, INDEX_BASE_TAB_ROWS],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

export const indexLayoutLg: LayoutConfigLest = desktopIndexLayout(12);
export const indexLayoutMd: LayoutConfigLest = mdStackedIndexLayout();
export const indexLayoutSm: LayoutConfigLest = stackedIndexLayout(6);
export const indexLayoutXs: LayoutConfigLest = mobileIndexLayout(4);
export const indexLayoutXxs: LayoutConfigLest = mobileIndexLayout(2);

export function buildIndexResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseNonLg = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, INDEX_COLLAPSED_SLOTS);

  return {
    lg: patchCollapseSlots(indexLayoutLg, INDEX_COLLAPSED_SLOTS_LG),
    md: patchCollapseSlots(indexLayoutMd, INDEX_COLLAPSED_SLOTS_MD),
    sm: collapseNonLg(indexLayoutSm),
    xs: collapseNonLg(indexLayoutXs),
    xxs: collapseNonLg(indexLayoutXxs),
  };
}

export function generateIndexResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(configs[bp], totalItems) as ResponsiveLayouts[string];
  }
  return result;
}

export function computeIndexTargetBottomRow(
  viewportHeight: number,
  menubarHeight = INDEX_MENUBAR_HEIGHT,
): number {
  const available =
    viewportHeight - menubarHeight - INDEX_VIEWPORT_FUDGE_PX;
  const rowUnit = INDEX_ROW_HEIGHT + INDEX_LAYOUT_MARGIN;
  const rows = Math.floor((available + INDEX_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    INDEX_MIN_BOTTOM_ROW,
    Math.min(INDEX_MAX_BOTTOM_ROW, rows),
  );
}

function patchTabSlotHeight(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const tabSlot = layout[INDEX_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const tabStart = tabSlot[1];
  const tabHeight = Math.max(INDEX_BASE_TAB_ROWS, targetBottomRow - tabStart);
  const next: LayoutDefinition = [tabSlot[0], tabStart, tabSlot[2], tabHeight];

  return layout.map((item, index) =>
    index === INDEX_TAB_SLOT_INDEX ? next : item,
  );
}

function patchTabSlotFixedHeight(
  layout: LayoutConfigLest,
  tabRows: number,
): LayoutConfigLest {
  const tabSlot = layout[INDEX_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const next: LayoutDefinition = [tabSlot[0], tabSlot[1], tabSlot[2], tabRows];

  return layout.map((item, index) =>
    index === INDEX_TAB_SLOT_INDEX ? next : item,
  );
}

export function patchIndexScrollTabHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTabSlotFixedHeight(layout, INDEX_SCROLL_TAB_ROWS);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/** Fixed tab rows on all breakpoints; page scrolls vertically. */
export function applyIndexLayoutSizing(
  config: ResponsiveLayoutConfig,
  _viewportHeight?: number,
): ResponsiveLayoutConfig {
  return patchIndexScrollTabHeights(config);
}

export function assertIndexLgViewportFit(): void {
  const bottom = getLayoutBottomRow(buildIndexResponsiveLayoutConfig().lg);
  if (bottom !== INDEX_LG_CONTENT_BOTTOM_ROW) {
    throw new Error(
      `index lg layout bottom row ${bottom} !== ${INDEX_LG_CONTENT_BOTTOM_ROW}`,
    );
  }
}

export function assertIndexLayoutValid(config: ResponsiveLayoutConfig): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `index ${bp}`);
  }
}
