import React, { type JSX, useEffect } from "react";
import { useTradePriceContext } from "../../context/SubscriptionContext";
import { useJellyMode } from "../../context/JellyModeContext";
import { JELLY_MARKET_INDEX } from "../../../offline/mock_data";

/** Keeps JELLY trade price slice in sync during replay frames. */
export function JellyReplaySync(): null {
  const { isJellyMode, frameIndex, replayPhase } = useJellyMode();
  const { refreshTradePrice, tradePriceMarketId } = useTradePriceContext();

  useEffect(() => {
    if (!isJellyMode || replayPhase === "intro") return;
    if (tradePriceMarketId !== JELLY_MARKET_INDEX) return;
    void refreshTradePrice();
  }, [isJellyMode, frameIndex, replayPhase, tradePriceMarketId, refreshTradePrice]);

  return null;
}
