import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  Joyride,
  type EventData,
  type Step,
  type TooltipRenderProps,
  EVENTS,
} from "react-joyride";
import { toast } from "sonner";
import MorpheumLoadingOverlay from "../../components/ui/MorpheumLoadingOverlay";
import { isDesktopTourBreakpoint } from "./constants";
import { WelcomeModal } from "./WelcomeModal";
import { useWelcomeTour } from "./WelcomeTourContext";
import {
  WELCOME_TOUR_STEPS,
  type WelcomeTourStepMeta,
  type WelcomeTourTabId,
} from "./welcomeTourSteps";
import {
  waitAnimationFrames,
  waitForTourTarget,
} from "./welcomeTourDom";
import {
  welcomeTourDefaultOptions,
  welcomeTourLocale,
  welcomeTourStyles,
} from "./welcomeTourStyles";
import "./WelcomeModal.css";

export interface WelcomeTourGuideActions {
  onStartJellyIncident?: () => void;
  onOpenNetworkHealth?: () => void;
}

const WelcomeTourGuideActionsContext =
  React.createContext<WelcomeTourGuideActions>({});

function useWelcomeTourGuideActions(): WelcomeTourGuideActions {
  return React.useContext(WelcomeTourGuideActionsContext);
}

function WelcomeTourTooltip({
  backProps,
  closeProps,
  continuous,
  index,
  isLastStep,
  primaryProps,
  skipProps,
  step,
  tooltipProps,
}: TooltipRenderProps): JSX.Element {
  const meta = step.data as WelcomeTourStepMeta | undefined;
  const stepNumber = meta?.stepNumber ?? index + 1;
  const { onStartJellyIncident, onOpenNetworkHealth } = useWelcomeTourGuideActions();

  return (
    <div {...tooltipProps} className="welcome-tour-tooltip">
      <div className="welcome-tour-tooltip-header">
        <span className="welcome-tour-step-badge">
          {stepNumber} / {WELCOME_TOUR_STEPS.length}
        </span>
        {step.title ? (
          <h4 className="welcome-tour-tooltip-title">{step.title}</h4>
        ) : null}
      </div>
      <div className="welcome-tour-tooltip-body">{step.content}</div>
      <div className="welcome-tour-tooltip-footer">
        {!isLastStep && (
          <button type="button" className="welcome-tour-skip" {...skipProps}>
            {skipProps.title}
          </button>
        )}
        <div className="welcome-tour-tooltip-nav">
          {index > 0 && (
            <button type="button" className="welcome-tour-back" {...backProps}>
              {backProps.title}
            </button>
          )}
          {continuous && (
            <button type="button" className="welcome-tour-next" {...primaryProps}>
              {isLastStep ? "Finish" : primaryProps.title}
            </button>
          )}
          {!continuous && (
            <button type="button" className="welcome-tour-next" {...closeProps}>
              {closeProps.title}
            </button>
          )}
        </div>
      </div>
      {isLastStep && (onStartJellyIncident || onOpenNetworkHealth) ? (
        <div className="welcome-tour-tooltip-deep-links">
          {onStartJellyIncident ? (
            <button
              type="button"
              className="welcome-tour-tooltip-deep-link"
              onClick={onStartJellyIncident}
            >
              Try $JELLY replay
            </button>
          ) : null}
          {onOpenNetworkHealth ? (
            <button
              type="button"
              className="welcome-tour-tooltip-deep-link"
              onClick={onOpenNetworkHealth}
            >
              Network metrics
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

function getNextStepTabId(index: number): WelcomeTourTabId | undefined {
  const next = WELCOME_TOUR_STEPS[index + 1]?.data as WelcomeTourStepMeta | undefined;
  return next?.tabId;
}

export function WelcomeTourJoyride(): JSX.Element {
  const {
    runTour,
    currentBreakpoint,
    stopTour,
    onTourComplete,
    switchTourTab,
  } = useWelcomeTour();

  const isDesktop = isDesktopTourBreakpoint(currentBreakpoint);
  const shouldRun = runTour && isDesktop;
  const prevRunRef = useRef(false);
  const [tourSession, setTourSession] = useState(0);
  const [preparingStep, setPreparingStep] = useState(false);
  const setPreparingStepRef = useRef(setPreparingStep);
  setPreparingStepRef.current = setPreparingStep;
  const switchTourTabRef = useRef(switchTourTab);
  switchTourTabRef.current = switchTourTab;

  useEffect(() => {
    if (shouldRun && !prevRunRef.current) {
      setTourSession((session) => session + 1);
    }
    prevRunRef.current = shouldRun;
  }, [shouldRun]);

  useEffect(() => {
    if (shouldRun) {
      document.body.setAttribute("data-welcome-tour-active", "true");
    } else {
      document.body.removeAttribute("data-welcome-tour-active");
    }
    return () => {
      document.body.removeAttribute("data-welcome-tour-active");
    };
  }, [shouldRun]);

  useEffect(() => {
    if (runTour && !isDesktop) {
      stopTour();
      toast.info(
        "Guided tour is available on desktop and tablet view. Widen your window to explore step-by-step.",
      );
    }
  }, [runTour, isDesktop, stopTour]);

  const steps = useMemo((): Step[] => {
    return WELCOME_TOUR_STEPS.map((step) => {
      const meta = step.data as WelcomeTourStepMeta | undefined;
      const tabId = meta?.tabId;
      const targetSelector = meta?.targetSelector;

      if (!tabId && !targetSelector) {
        return step;
      }

      return {
        ...step,
        before: async () => {
          setPreparingStepRef.current(true);
          try {
            if (tabId) {
              switchTourTabRef.current(tabId);
              await waitAnimationFrames(3);
            }
            if (targetSelector && targetSelector !== "body") {
              await waitForTourTarget(targetSelector);
            }
          } finally {
            setPreparingStepRef.current(false);
          }
        },
      };
    });
  }, []);

  const handleEvent = useCallback(
    (data: EventData) => {
      const { type, index } = data;

      if (type === EVENTS.STEP_AFTER) {
        const nextTabId = getNextStepTabId(index);
        if (nextTabId) {
          switchTourTab(nextTabId);
        }
      }

      if (type === EVENTS.TOUR_END) {
        onTourComplete();
      }
    },
    [onTourComplete, switchTourTab],
  );

  return (
    <>
      {preparingStep
        ? createPortal(
            <MorpheumLoadingOverlay
              layout="fixed"
              className="welcome-tour-loading-overlay"
              label="Loading tour step..."
              matrixText={true}
            />,
            document.body,
          )
        : null}
      <Joyride
        key={tourSession}
        steps={steps}
        run={shouldRun}
        continuous
        scrollToFirstStep
        onEvent={handleEvent}
        locale={welcomeTourLocale}
        options={welcomeTourDefaultOptions}
        styles={welcomeTourStyles}
        loaderComponent={null}
        tooltipComponent={WelcomeTourTooltip}
      />
    </>
  );
}

export function WelcomeTourShell({
  onOpenKeyboardShortcuts,
  onStartJellyIncident,
  onOpenNetworkHealth,
  onStartDepositTour,
  onStartCopyTour,
  showBootstrapLoading = false,
}: {
  onOpenKeyboardShortcuts?: () => void;
  onStartJellyIncident?: () => void;
  onOpenNetworkHealth?: () => void;
  onStartDepositTour?: () => void;
  onStartCopyTour?: () => void;
  showBootstrapLoading?: boolean;
}): JSX.Element {
  const {
    showWelcomeModal,
    startGuidedTour,
    dismissWelcome,
    closeWelcomeModal,
    welcomeHubMode,
    highlightDeepDive,
    stopTour,
  } = useWelcomeTour();

  const startJellyFromTour = useCallback(() => {
    stopTour();
    onStartJellyIncident?.();
  }, [stopTour, onStartJellyIncident]);

  const openNetworkFromTour = useCallback(() => {
    stopTour();
    onOpenNetworkHealth?.();
  }, [stopTour, onOpenNetworkHealth]);

  const guideActions = useMemo<WelcomeTourGuideActions>(
    () => ({
      onStartJellyIncident: startJellyFromTour,
      onOpenNetworkHealth: openNetworkFromTour,
    }),
    [openNetworkFromTour, startJellyFromTour],
  );

  return (
    <WelcomeTourGuideActionsContext.Provider value={guideActions}>
      {showBootstrapLoading
        ? createPortal(
            <MorpheumLoadingOverlay
              layout="fixed"
              className="welcome-tour-loading-overlay"
              label="Preparing demo workspace..."
            />,
            document.body,
          )
        : null}
      <WelcomeModal
        isOpen={showWelcomeModal}
        onStartTour={startGuidedTour}
        onExploreOwn={dismissWelcome}
        onClose={closeWelcomeModal}
        onOpenKeyboardShortcuts={onOpenKeyboardShortcuts}
        onStartJellyIncident={onStartJellyIncident}
        onOpenNetworkHealth={onOpenNetworkHealth}
        onStartDepositTour={onStartDepositTour}
        onStartCopyTour={onStartCopyTour}
        welcomeHubMode={welcomeHubMode}
        highlightDeepDive={highlightDeepDive}
      />
      <WelcomeTourJoyride />
    </WelcomeTourGuideActionsContext.Provider>
  );
}
