import type { UTCTimestamp } from "lightweight-charts";

import { getAgentProfileById } from "../../../offline/mock_data";
import type {
  AgentTokenTakerAction,
  AgentTokenTakerTradeEvent,
} from "../../../offline/mock_data/agentTokenTakerHistory.types";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { type ChartExecutionMarker, snapTimeToCandleInterval } from "./chartMarkers";
import { fleetMarkersToChartMarkers, type FleetChartMarker } from "./fleetChartMarkers";

export type TokenTakerChartMarkerMeta = {
  eventId: string;
  takerCatalogAgentId: string;
  takerAgentName: string;
  avatar: string;
  avatarSvgUrl: string;
  takerAgentWallet: string;
  action: AgentTokenTakerAction;
  amountUsd: number;
  coin: string;
  price: number;
  quantity: number;
  time: number;
  closedPnl: number | null;
};

export type TokenTakerEventsToMarkersResult = {
  markers: FleetChartMarker[];
  metaByEventId: Map<string, TokenTakerChartMarkerMeta>;
};

export type TokenTakerEventsToMarkersOptions = {
  /** Top-N takers by aggregate notional (default {@link TOKEN_TAKER_TOP_TRADER_COUNT}). */
  maxTopTraders?: number;
  /** How top-N taker fills become chart markers (default {@link DEFAULT_TOKEN_TAKER_MARKER_STRATEGY}). */
  markerStrategy?: TokenTakerMarkerStrategy;
  /** Always include this event as a marker candidate (table scroll-to-fill). */
  focusEventId?: string | null;
  /** Inclusive UTC seconds for visible window (snapped bar times). */
  visibleTimeFromSec?: number | null;
  visibleTimeToSec?: number | null;
};

/** Global chart marker budget: only top-N takers by total amountUsd get avatar markers. */
export const TOKEN_TAKER_TOP_TRADER_COUNT = 15;

/**
 * How top-N taker markers are painted on the chart.
 *
 * - viewportSpotlight — at most one avatar per top taker in the visible window (their largest fill).
 * - perCandleSide — at most one long + one short avatar per top taker per visible candle.
 */
export const TOKEN_TAKER_MARKER_STRATEGIES = {
  viewportSpotlight: "viewportSpotlight",
  perCandleSide: "perCandleSide",
} as const;

export type TokenTakerMarkerStrategy =
  (typeof TOKEN_TAKER_MARKER_STRATEGIES)[keyof typeof TOKEN_TAKER_MARKER_STRATEGIES];

export const DEFAULT_TOKEN_TAKER_MARKER_STRATEGY: TokenTakerMarkerStrategy =
  TOKEN_TAKER_MARKER_STRATEGIES.perCandleSide;

/** Agent page token taker chart: viewport spotlight with top 25 traders by notional. */
export const AGENT_PAGE_TOKEN_TAKER_MAX_TOP_TRADERS = 25;
export const AGENT_PAGE_TOKEN_TAKER_MARKER_STRATEGY: TokenTakerMarkerStrategy =
  TOKEN_TAKER_MARKER_STRATEGIES.viewportSpotlight;

export const TOKEN_TAKER_MARKER_STRATEGY_LABELS: Record<TokenTakerMarkerStrategy, string> = {
  [TOKEN_TAKER_MARKER_STRATEGIES.viewportSpotlight]: "Viewport spotlight",
  [TOKEN_TAKER_MARKER_STRATEGIES.perCandleSide]: "Per candle (long + short)",
};

/** Default live-edge bar window when chart viewport range is not yet known. */
export const TOKEN_TAKER_VISIBLE_WINDOW_FALLBACK_BARS = 100;

const SATOSHI = 100_000_000;

function fromSatoshi(value: string): number {
  const intStr = value.includes(".") ? value.split(".")[0]! : value;
  return Number(BigInt(intStr)) / SATOSHI;
}

function isBuyAction(action: AgentTokenTakerAction): boolean {
  return action === "BUY" || action === "SNIPE";
}

function takerMarkerLabel(takerCatalogAgentId: string): string {
  const profile = getAgentProfileById(takerCatalogAgentId);
  if (!profile) return "A";
  const ticker = profile.ticker.replace(/^\$/, "").slice(0, 3);
  return ticker.toUpperCase();
}

/** Rank for stack cap: buys by notional, sells/liquidations by |closedPnl| with amountUsd fallback. */
export function takerEventStackRank(event: AgentTokenTakerTradeEvent): number {
  if (isBuyAction(event.action)) return event.amountUsd;
  if (event.closedPnl != null) return Math.abs(event.closedPnl);
  return event.amountUsd;
}

/** Sum amountUsd per taker across full history. */
export function rankTakersByTotalNotional(
  events: AgentTokenTakerTradeEvent[],
): Map<string, number> {
  const totals = new Map<string, number>();
  for (const event of events) {
    const id = event.takerCatalogAgentId;
    totals.set(id, (totals.get(id) ?? 0) + event.amountUsd);
  }
  return totals;
}

/** Top takers by aggregate notional; ties broken by catalog id for stability. */
export function selectTopTakerIds(
  events: AgentTokenTakerTradeEvent[],
  maxCount: number,
): Set<string> {
  if (maxCount <= 0 || events.length === 0) return new Set();

  const totals = rankTakersByTotalNotional(events);
  const ranked = [...totals.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return a[0].localeCompare(b[0]);
  });

  return new Set(ranked.slice(0, maxCount).map(([id]) => id));
}

function resolveTopTraderCount(
  events: AgentTokenTakerTradeEvent[],
  maxTopTraders: number | undefined,
): number {
  const uniqueTakerCount = new Set(events.map((event) => event.takerCatalogAgentId)).size;
  const requested = maxTopTraders ?? TOKEN_TAKER_TOP_TRADER_COUNT;
  return Math.min(Math.max(0, requested), uniqueTakerCount);
}

function resolveMarkerStrategy(
  strategy: TokenTakerMarkerStrategy | undefined,
): TokenTakerMarkerStrategy {
  return strategy ?? DEFAULT_TOKEN_TAKER_MARKER_STRATEGY;
}

function considerBetterFill(
  event: AgentTokenTakerTradeEvent,
  current: AgentTokenTakerTradeEvent | undefined,
): boolean {
  if (!current) return true;
  const rank = takerEventStackRank(event);
  const currentRank = takerEventStackRank(current);
  return rank > currentRank || (rank === currentRank && event.id.localeCompare(current.id) < 0);
}

function eventBarSec(event: AgentTokenTakerTradeEvent, interval: string): number {
  return snapTimeToCandleInterval(Date.parse(event.timestamp), interval);
}

function isBarInVisibleWindow(
  barSec: number,
  fromSec: number | null | undefined,
  toSec: number | null | undefined,
): boolean {
  if (fromSec == null || toSec == null) return false;
  return barSec >= fromSec && barSec <= toSec;
}

/** Map chart logical range + candle times to inclusive snapped-bar UTC seconds. */
export function visibleTimeBoundsFromCandleTimes(
  candleTimes: readonly number[],
  range: { from: number; to: number } | null,
  fallbackBarCount: number = TOKEN_TAKER_VISIBLE_WINDOW_FALLBACK_BARS,
): { fromSec: number; toSec: number } | null {
  if (candleTimes.length === 0) return null;

  if (range) {
    const fromIdx = Math.max(0, Math.floor(range.from));
    const toIdx = Math.min(candleTimes.length - 1, Math.ceil(range.to) - 1);
    if (fromIdx <= toIdx) {
      return { fromSec: candleTimes[fromIdx]!, toSec: candleTimes[toIdx]! };
    }
  }

  const tailCount = Math.min(fallbackBarCount, candleTimes.length);
  const fromIdx = candleTimes.length - tailCount;
  return {
    fromSec: candleTimes[fromIdx]!,
    toSec: candleTimes[candleTimes.length - 1]!,
  };
}

/** One fill per top taker in the visible window (viewport spotlight). */
export function selectOneFillPerTopTakerInWindow(
  events: AgentTokenTakerTradeEvent[],
  topTakerIds: Set<string>,
  interval: string,
  fromSec: number | null | undefined,
  toSec: number | null | undefined,
  focusEventId: string | null = null,
): AgentTokenTakerTradeEvent[] {
  const bestByTaker = new Map<string, AgentTokenTakerTradeEvent>();

  const consider = (event: AgentTokenTakerTradeEvent) => {
    if (!isBarInVisibleWindow(eventBarSec(event, interval), fromSec, toSec)) return;

    const takerId = event.takerCatalogAgentId;
    const current = bestByTaker.get(takerId);
    if (considerBetterFill(event, current)) {
      bestByTaker.set(takerId, event);
    }
  };

  for (const event of events) {
    if (topTakerIds.has(event.takerCatalogAgentId)) {
      consider(event);
    }
  }

  if (focusEventId) {
    const focusEvent = events.find((event) => event.id === focusEventId);
    if (focusEvent && isBarInVisibleWindow(eventBarSec(focusEvent, interval), fromSec, toSec)) {
      bestByTaker.set(focusEvent.takerCatalogAgentId, focusEvent);
    }
  }

  return [...bestByTaker.values()].sort(
    (a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp),
  );
}

function barTakerSideKey(
  event: AgentTokenTakerTradeEvent,
  interval: string,
): string {
  const barSec = eventBarSec(event, interval);
  const side = isBuyAction(event.action) ? "belowBar" : "aboveBar";
  return `${barSec}:${event.takerCatalogAgentId}:${side}`;
}

/** One fill per top taker per candle side (long below, short above) in the visible window. */
export function selectOneFillPerTopTakerPerCandleSide(
  events: AgentTokenTakerTradeEvent[],
  topTakerIds: Set<string>,
  interval: string,
  fromSec: number | null | undefined,
  toSec: number | null | undefined,
  focusEventId: string | null = null,
): AgentTokenTakerTradeEvent[] {
  const bestByBarTakerSide = new Map<string, AgentTokenTakerTradeEvent>();

  const consider = (event: AgentTokenTakerTradeEvent) => {
    if (!isBarInVisibleWindow(eventBarSec(event, interval), fromSec, toSec)) return;
    const key = barTakerSideKey(event, interval);
    const current = bestByBarTakerSide.get(key);
    if (considerBetterFill(event, current)) {
      bestByBarTakerSide.set(key, event);
    }
  };

  for (const event of events) {
    if (topTakerIds.has(event.takerCatalogAgentId)) {
      consider(event);
    }
  }

  if (focusEventId) {
    const focusEvent = events.find((event) => event.id === focusEventId);
    if (focusEvent && isBarInVisibleWindow(eventBarSec(focusEvent, interval), fromSec, toSec)) {
      bestByBarTakerSide.set(barTakerSideKey(focusEvent, interval), focusEvent);
    }
  }

  return [...bestByBarTakerSide.values()].sort(
    (a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp),
  );
}

function buildMarkerMeta(event: AgentTokenTakerTradeEvent): TokenTakerChartMarkerMeta {
  const takerProfile = getAgentProfileById(event.takerCatalogAgentId);
  const price = fromSatoshi(event.price);
  return {
    eventId: event.id,
    takerCatalogAgentId: event.takerCatalogAgentId,
    takerAgentName: takerProfile?.name ?? event.takerCatalogAgentId,
    avatar: takerProfile?.avatar ?? "🤖",
    avatarSvgUrl: resolveAgentAvatarSvgUrl(event.takerCatalogAgentId),
    takerAgentWallet: event.takerAgentWallet,
    action: event.action,
    amountUsd: event.amountUsd,
    coin: event.coin,
    price,
    quantity: event.quantity,
    time: Date.parse(event.timestamp),
    closedPnl: event.closedPnl,
  };
}

function fleetMarkerFromEvent(
  event: AgentTokenTakerTradeEvent,
  interval: string,
): FleetChartMarker {
  const buy = isBuyAction(event.action);
  const barTime = snapTimeToCandleInterval(Date.parse(event.timestamp), interval) as UTCTimestamp;
  return {
    tradeId: event.id,
    time: barTime,
    position: buy ? "belowBar" : "aboveBar",
    shape: "circle",
    color: buy ? TERMINAL_COLORS.long : TERMINAL_COLORS.short,
    label: takerMarkerLabel(event.takerCatalogAgentId),
    imageUrl: resolveAgentAvatarSvgUrl(event.takerCatalogAgentId),
    stackRank: takerEventStackRank(event),
  };
}

export function tokenTakerMarkersToChartMarkers(
  markers: FleetChartMarker[],
): ChartExecutionMarker[] {
  return fleetMarkersToChartMarkers(
    markers.map((marker) => ({
      ...marker,
      tradeId: marker.tradeId,
    })),
  );
}

export function tokenTakerEventsToSeriesMarkers(
  events: AgentTokenTakerTradeEvent[],
  interval: string,
  options?: TokenTakerEventsToMarkersOptions,
): TokenTakerEventsToMarkersResult {
  const metaByEventId = new Map<string, TokenTakerChartMarkerMeta>();
  const focusEventId = options?.focusEventId ?? null;
  const markerStrategy = resolveMarkerStrategy(options?.markerStrategy);
  const topTraderCount = resolveTopTraderCount(events, options?.maxTopTraders);
  const allowedTakers = selectTopTakerIds(events, topTraderCount);
  const windowFrom = options?.visibleTimeFromSec ?? null;
  const windowTo = options?.visibleTimeToSec ?? null;

  for (const event of events) {
    metaByEventId.set(event.id, buildMarkerMeta(event));
  }

  const selectedEvents =
    markerStrategy === TOKEN_TAKER_MARKER_STRATEGIES.viewportSpotlight
      ? selectOneFillPerTopTakerInWindow(
          events,
          allowedTakers,
          interval,
          windowFrom,
          windowTo,
          focusEventId,
        )
      : selectOneFillPerTopTakerPerCandleSide(
          events,
          allowedTakers,
          interval,
          windowFrom,
          windowTo,
          focusEventId,
        );

  const markers = selectedEvents.map((event) => fleetMarkerFromEvent(event, interval));
  return { markers, metaByEventId };
}
