import React, { useCallback } from "react";
import { useNavigate } from "react-router-dom";

import {
  getIndexRowBySlug,
  indexDetailPath,
} from "../../../offline/mock_data";
import { LIVE_MAEX_INDEX_PERPS } from "../../../offline/mock_data/maexIndexCatalog";
import type { IndexCatalogEntry } from "../../../offline/mock_data/maexIndexCatalog";
import CompactMetricCell from "../metrics/CompactMetricCell";
import type { CompactMetricDefinition } from "../metrics/types";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import { formatCurrency } from "./indexFormat";
import { buildIndexListMetricDefinitions } from "../../utils/indexListMetrics";
import "./index.css";

export interface IndexSymbolListProps {
  height?: string;
  entries?: IndexCatalogEntry[];
}

const GRID_TEMPLATE_COLUMNS =
  "minmax(9rem, 1.15fr) minmax(4.5rem, 0.55fr) minmax(9rem, 1fr) minmax(9rem, 1fr) minmax(8rem, 0.9fr) minmax(7.5rem, 0.85fr) minmax(3rem, 0.35fr)";

function metricsById(
  entry: IndexCatalogEntry,
  row: ReturnType<typeof getIndexRowBySlug>,
): Record<string, CompactMetricDefinition> {
  return Object.fromEntries(
    buildIndexListMetricDefinitions(entry, row).map((metric) => [
      metric.id,
      metric,
    ]),
  );
}

function IndexSymbolList({
  height = "100%",
  entries = LIVE_MAEX_INDEX_PERPS.filter((entry) => entry.isSelectable),
}: IndexSymbolListProps): JSX.Element {
  const navigate = useNavigate();

  const openIndex = useCallback(
    (baseAsset: string) => {
      navigate(indexDetailPath(baseAsset));
    },
    [navigate],
  );

  const handleRowKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>, baseAsset: string) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openIndex(baseAsset);
      }
    },
    [openIndex],
  );

  return (
    <div className="index-slot index-symbol-list" style={{ height }}>
      <div className="index-symbol-table-wrap">
        <div className="table-container shrinkable index-symbol-table">
          <div
            className="table-header"
            style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
          >
            <TableHeaderCellStatic left>Symbol</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Price</TableHeaderCellStatic>
            <TableHeaderCellStatic left>MC</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Turnover</TableHeaderCellStatic>
            <TableHeaderCellStatic left>24H%</TableHeaderCellStatic>
            <TableHeaderCellStatic left>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.totalMentions} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic left>Risk</TableHeaderCellStatic>
          </div>
          {entries.map((entry, index) => {
            const row = getIndexRowBySlug(entry.baseAsset);
            const metrics = metricsById(entry, row);

            return (
              <div
                key={entry.baseAsset}
                className={`table-row clickable ${index % 2 === 0 ? "even" : ""}`}
                style={{ gridTemplateColumns: GRID_TEMPLATE_COLUMNS }}
                tabIndex={0}
                role="button"
                onClick={() => openIndex(entry.baseAsset)}
                onKeyDown={(event) => handleRowKeyDown(event, entry.baseAsset)}
              >
                <div className="table-cell primary">
                  <div className="index-symbol-name-cell">
                    <span className="index-symbol-icon">
                      {row?.icon ?? "◎"}
                    </span>
                    <div>
                      <strong>{entry.displayName}</strong>
                      <span>{entry.baseAsset}</span>
                    </div>
                  </div>
                </div>
                <div className="table-cell">
                  {formatCurrency(entry.price)}
                </div>
                <div className="table-cell index-symbol-metric-cell">
                  {metrics.marketCap ? (
                    <CompactMetricCell
                      metric={metrics.marketCap}
                      showLabel={false}
                    />
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell index-symbol-metric-cell">
                  {metrics.turnover ? (
                    <CompactMetricCell
                      metric={metrics.turnover}
                      showLabel={false}
                    />
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell index-symbol-metric-cell">
                  {metrics.change24h ? (
                    <CompactMetricCell
                      metric={metrics.change24h}
                      showLabel={false}
                    />
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell index-symbol-metric-cell">
                  {metrics.totalMentions ? (
                    <CompactMetricCell
                      metric={metrics.totalMentions}
                      showLabel={false}
                    />
                  ) : (
                    "—"
                  )}
                </div>
                <div className="table-cell">{row?.risk ?? "—"}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export default IndexSymbolList;
