import React, { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { toast } from "sonner";
import { ModalTabBar, type ModalTab } from "./modal-tab-bar";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import type { WalletTransferAssetId } from "./wallet-transfer-modal";
import type { CrossChainOption } from "../../constants/crossChain";
import type { CrossChainFlowStep, CrossChainTransferRecord, SecurityStage } from "../../types/crossChainFlow";
import { CrossChainFormPanel } from "./cross-chain/CrossChainFormPanel";
import { CrossChainReviewPanel } from "./cross-chain/CrossChainReviewPanel";
import { CrossChainAuthorizePanel } from "./cross-chain/CrossChainAuthorizePanel";
import { CrossChainSubmitPanel } from "./cross-chain/CrossChainSubmitPanel";
import { CrossChainTrackingPanel } from "./cross-chain/CrossChainTrackingPanel";
import { CrossChainFailurePanel } from "./cross-chain/CrossChainFailurePanel";
import { CrossChainSuccessPanel } from "./cross-chain/CrossChainSuccessPanel";
import { CrossChainDemoHelper } from "./cross-chain/CrossChainDemoHelper";
import "../../terminal.css";
import "./layout.css";
import "./cross-chain/cross-chain.css";
import MorpheumLogo from "../ui/MorpheumLogo";

export type CrossChainMode = "deposit" | "withdraw";

const CROSS_CHAIN_MODAL_TABS = [
  { id: "deposit", label: "Deposit" },
  { id: "withdraw", label: "Withdraw" },
] as const satisfies readonly ModalTab<CrossChainMode>[];

export interface CrossChainConfirmParams {
  mode: CrossChainMode;
  assetId: WalletTransferAssetId;
  amount: number;
  chain: string;
  toAddress: string;
}

export interface CrossChainModalProps {
  isOpen: boolean;
  mode: CrossChainMode;
  flowStep: CrossChainFlowStep;
  walletAddress: string;
  assetId: WalletTransferAssetId;
  amount: number;
  chain: string;
  toAddress: string;
  availableBalance: number;
  chainOptions: CrossChainOption[];
  transferRecord: CrossChainTransferRecord | null;
  isSimulatingSignature: boolean;
  validatorCount: number;
  showDemoHelper: boolean;
  newBalance?: number | null;
  onModeChange: (mode: CrossChainMode) => void;
  onAssetChange: (value: WalletTransferAssetId) => void;
  onAmountChange: (amount: number) => void;
  onChainChange: (value: string) => void;
  onToAddressChange: (value: string) => void;
  onGoToReview: () => void;
  onBackToForm: () => void;
  onConfirmReview: (params: CrossChainConfirmParams) => void;
  onSimulateAuthorize: () => void;
  onSimulateSubmit: () => void;
  onRetryFromFailure: () => void;
  onKeepPollingFromFailure: () => void;
  onNewTransfer: () => void;
  onFundBucket: () => void;
  onPreviewFailure: (stage: SecurityStage) => void;
  onFailOnNextConfirm: (stage: SecurityStage) => void;
  onCancel: () => void;
  onOpen?: () => void;
  onOverlayClick?: () => void;
}

function demoLinkToast(): void {
  toast.message("Demo explorer link", { description: "Explorer links are disabled in demo mode." });
}

function stepTitle(
  step: CrossChainFlowStep,
  mode: CrossChainMode,
  assetId: WalletTransferAssetId,
): string {
  switch (step) {
    case "review":
      return "Review transfer";
    case "authorize":
      return `Approve ${assetId}`;
    case "submit":
      return "Sign transfer";
    case "tracking":
      return "Transfer in progress";
    case "success":
      return "Transfer complete";
    case "failure":
      return "Transfer needs attention";
    default:
      return mode === "withdraw" ? "Withdraw" : "Deposit";
  }
}

export function CrossChainModal({
  isOpen,
  mode,
  flowStep,
  walletAddress,
  assetId,
  amount,
  chain,
  toAddress,
  availableBalance,
  chainOptions,
  transferRecord,
  isSimulatingSignature,
  validatorCount,
  showDemoHelper,
  newBalance = null,
  onModeChange,
  onAssetChange,
  onAmountChange,
  onChainChange,
  onToAddressChange,
  onGoToReview,
  onBackToForm,
  onConfirmReview,
  onSimulateAuthorize,
  onSimulateSubmit,
  onRetryFromFailure,
  onKeepPollingFromFailure,
  onNewTransfer,
  onFundBucket,
  onPreviewFailure,
  onFailOnNextConfirm,
  onCancel,
  onOpen,
  onOverlayClick = () => {},
}: CrossChainModalProps): JSX.Element | null {
  const prevIsOpenRef = useRef<boolean>(false);
  const isFlowActive = flowStep !== "form";

  useEffect(() => {
    if (isOpen && !prevIsOpenRef.current && onOpen) {
      onOpen();
    }
    prevIsOpenRef.current = isOpen;
  }, [isOpen, onOpen]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onCancel);

  const destinationAddress =
    mode === "withdraw" ? toAddress.trim() : walletAddress;

  const buildConfirmParams = (): CrossChainConfirmParams => ({
    mode,
    assetId,
    amount,
    chain,
    toAddress: destinationAddress,
  });

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onOverlayClick}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content transfer-modal-content staggered-overlay-panel--scale"
        aria-label="Morpheum Bridge"
      >
        <div className="modal-header">
          <div className="cross-chain-modal-header">
            <h3 className="terminal-panel-title cross-chain-modal-header-title">
              <MorpheumLogo width={18} height={18} />
              Morpheum Bridge
            </h3>
            <div className="cross-chain-header-actions">
              <span className="cross-chain-trust-badge">🔒 Secured by Hyperlane</span>
              {showDemoHelper && (
                <CrossChainDemoHelper
                  onPreviewFailure={onPreviewFailure}
                  onFailOnNextConfirm={onFailOnNextConfirm}
                />
              )}
              <button
                type="button"
                className="btn btn-secondary btn-sm"
                onClick={onCancel}
                aria-label="Close"
              >
                ×
              </button>
            </div>
          </div>
        </div>

        {!isFlowActive && (
          <ModalTabBar
            tabs={CROSS_CHAIN_MODAL_TABS}
            activeTabId={mode}
            onTabChange={onModeChange}
          />
        )}

        <div className="modal-body">
          <p className="terminal-panel-title" style={{ marginBottom: "0.75rem" }}>
            {stepTitle(flowStep, mode, assetId)}
          </p>

          {flowStep === "form" && (
            <CrossChainFormPanel
              mode={mode}
              walletAddress={walletAddress}
              assetId={assetId}
              amount={amount}
              chain={chain}
              toAddress={toAddress}
              availableBalance={availableBalance}
              chainOptions={chainOptions}
              onAssetChange={onAssetChange}
              onAmountChange={onAmountChange}
              onChainChange={onChainChange}
              onToAddressChange={onToAddressChange}
              onReview={onGoToReview}
            />
          )}

          {flowStep === "review" && (
            <CrossChainReviewPanel
              mode={mode}
              assetId={assetId}
              amount={amount}
              chain={chain}
              destinationAddress={destinationAddress}
              onBack={onBackToForm}
              onConfirm={() => onConfirmReview(buildConfirmParams())}
            />
          )}

          {flowStep === "authorize" && (
            <CrossChainAuthorizePanel
              assetId={assetId}
              amount={amount}
              isWaiting={isSimulatingSignature}
              onSimulateSignature={onSimulateAuthorize}
            />
          )}

          {flowStep === "submit" && (
            <CrossChainSubmitPanel
              mode={mode}
              assetId={assetId}
              amount={amount}
              chain={chain}
              isWaiting={isSimulatingSignature}
              onSimulateSignature={onSimulateSubmit}
            />
          )}

          {flowStep === "tracking" && transferRecord && (
            <CrossChainTrackingPanel
              record={transferRecord}
              validatorCount={validatorCount}
              onDemoLinkClick={demoLinkToast}
            />
          )}

          {flowStep === "failure" && transferRecord && (
            <CrossChainFailurePanel
              record={transferRecord}
              onRetry={onRetryFromFailure}
              onKeepPolling={onKeepPollingFromFailure}
              onDemoLinkClick={demoLinkToast}
            />
          )}

          {flowStep === "success" && transferRecord && (
            <CrossChainSuccessPanel
              record={transferRecord}
              newBalance={newBalance}
              showBucketHandoff
              onFundBucket={onFundBucket}
              onNewTransfer={onNewTransfer}
              onDemoLinkClick={demoLinkToast}
            />
          )}
        </div>

        {flowStep === "form" && (
          <div className="modal-footer">
            <button type="button" onClick={onCancel} className="btn btn-secondary">
              Cancel
            </button>
          </div>
        )}
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return mounted && typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
