import type { ChangeEvent } from "react";
import React from "react";
import {
  ADVANCED_ORDER_TYPE_STOP_MARKET,
  ADVANCED_ORDER_TYPE_STOP_LIMIT,
  ADVANCED_ORDER_TYPE_TWAP,
  ADVANCED_ORDER_TYPE_SCALE,
  isConditionalAdvancedType,
  type AdvancedOrderParams,
  type AdvancedOrderTypeId,
} from "../../configs/advancedOrderTypes";
import { PRICE_MIN, PRICE_STEP } from "../../constants";

export interface AdvancedOrderFieldsProps {
  selectedType: AdvancedOrderTypeId;
  params: AdvancedOrderParams;
  onParamsChange: (patch: Partial<AdvancedOrderParams>) => void;
  pricePlaceholder?: string;
}

function NumberField({
  id,
  label,
  value,
  onChange,
  placeholder,
  min,
  step,
}: {
  id: string;
  label: string;
  value: number;
  onChange: (value: number) => void;
  placeholder?: string;
  min?: number;
  step?: number;
}): JSX.Element {
  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChange(parseFloat(e.target.value) || 0);
  };

  return (
    <div className="trade-op-form-row">
      <label htmlFor={id} className="trade-op-label">
        {label}
      </label>
      <input
        id={id}
        type="number"
        className="form-input trade-op-input"
        value={value || ""}
        onChange={handleChange}
        placeholder={placeholder}
        step={step ?? PRICE_STEP}
        min={min ?? PRICE_MIN}
      />
    </div>
  );
}

export function AdvancedOrderFields({
  selectedType,
  params,
  onParamsChange,
  pricePlaceholder,
}: AdvancedOrderFieldsProps): JSX.Element | null {
  const showReduceOnly = isConditionalAdvancedType(selectedType);

  const renderTypeFields = (): JSX.Element | null => {
    switch (selectedType) {
      case ADVANCED_ORDER_TYPE_STOP_MARKET:
        return (
          <NumberField
            id="advanced-trigger-price"
            label="Trigger:"
            value={params.triggerPrice}
            onChange={(triggerPrice) => onParamsChange({ triggerPrice })}
            placeholder={pricePlaceholder}
          />
        );

      case ADVANCED_ORDER_TYPE_STOP_LIMIT:
        return (
          <>
            <NumberField
              id="advanced-trigger-price"
              label="Trigger:"
              value={params.triggerPrice}
              onChange={(triggerPrice) => onParamsChange({ triggerPrice })}
              placeholder={pricePlaceholder}
            />
            <NumberField
              id="advanced-limit-price"
              label="Limit:"
              value={params.limitPrice}
              onChange={(limitPrice) => onParamsChange({ limitPrice })}
              placeholder={pricePlaceholder}
            />
          </>
        );

      case ADVANCED_ORDER_TYPE_TWAP:
        return (
          <>
            <NumberField
              id="advanced-twap-duration"
              label="Duration (min):"
              value={params.durationMinutes}
              onChange={(durationMinutes) => onParamsChange({ durationMinutes })}
              min={1}
              step={1}
            />
            <NumberField
              id="advanced-twap-interval"
              label="Slice (sec):"
              value={params.sliceIntervalSeconds}
              onChange={(sliceIntervalSeconds) =>
                onParamsChange({ sliceIntervalSeconds })
              }
              min={1}
              step={1}
            />
            <div className="trade-op-form-row">
              <label htmlFor="advanced-twap-randomize" className="trade-op-label">
                Randomize:
              </label>
              <input
                id="advanced-twap-randomize"
                type="checkbox"
                checked={params.randomizeSlices}
                onChange={(e) =>
                  onParamsChange({ randomizeSlices: e.target.checked })
                }
              />
            </div>
          </>
        );

      case ADVANCED_ORDER_TYPE_SCALE:
        return (
          <>
            <NumberField
              id="advanced-scale-from"
              label="Price From:"
              value={params.priceFrom}
              onChange={(priceFrom) => onParamsChange({ priceFrom })}
              placeholder={pricePlaceholder}
            />
            <NumberField
              id="advanced-scale-to"
              label="Price To:"
              value={params.priceTo}
              onChange={(priceTo) => onParamsChange({ priceTo })}
              placeholder={pricePlaceholder}
            />
            <NumberField
              id="advanced-scale-count"
              label="Orders:"
              value={params.orderCount}
              onChange={(orderCount) => onParamsChange({ orderCount })}
              min={2}
              step={1}
            />
          </>
        );

      default:
        return null;
    }
  };

  const typeFields = renderTypeFields();
  if (!typeFields && !showReduceOnly) return null;

  return (
    <div className="trade-op-form-group trade-op-advanced-fields">
      {typeFields}
      {showReduceOnly ? (
        <div className="trade-op-form-row">
          <label htmlFor="advanced-reduce-only" className="trade-op-label">
            Reduce Only:
          </label>
          <input
            id="advanced-reduce-only"
            type="checkbox"
            checked={params.reduceOnly}
            onChange={(e) => onParamsChange({ reduceOnly: e.target.checked })}
          />
        </div>
      ) : null}
    </div>
  );
}
