import type { TradingAgent } from "../../store/types";
import type { IntentBreakdown } from "./intentBreakdown";
import type { DirectionClass } from "./intentBreakdown";

export type ContractLineSource =
  | "you"
  | "default"
  | "bucket"
  | "agent-bounded"
  | "inferred";

export interface ExecutionContractLine {
  key: string;
  field: ContractFieldKey;
  value: string;
  source: ContractLineSource;
  editable: boolean;
  warning?: boolean;
}

export type ContractFieldKey =
  | "action"
  | "asset"
  | "size"
  | "leverage"
  | "entry"
  | "stop"
  | "takeProfit"
  | "bucket"
  | "margin"
  | "estLiq"
  | "marginRequired"
  | "agent";

export interface ExecutionContract {
  youSaid: string;
  lines: ExecutionContractLine[];
  summaryOneLine: string;
  hasDefaultedRisk: boolean;
}

export interface ContractOverrides {
  direction?: DirectionClass;
  sizePct?: number;
  leverage?: number;
  stopLoss?: number | null;
  takeProfit?: number | null;
  entryPrice?: number | null;
  reduceOnly?: boolean;
}

export interface ExecutionContractContext {
  entryPrice: number;
  bucketLabel?: string;
  marginMode?: string;
  defaultLeverage: number;
  defaultSizePct: number;
  bucketBalance?: number;
  agent?: TradingAgent | null;
  assetSymbol?: string;
}

const DEFAULT_SIZE_PCT = 20;
const DEFAULT_LEVERAGE = 5;
const TIGHT_STOP_PCT = 2;

function formatPrice(value: number): string {
  if (!Number.isFinite(value)) return "—";
  return value.toLocaleString(undefined, {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  });
}

function formatPct(value: number): string {
  const sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
}

function inferStopFromTight(
  entry: number,
  direction: DirectionClass,
): number | null {
  if (!Number.isFinite(entry) || entry <= 0) return null;
  const pct = TIGHT_STOP_PCT / 100;
  if (direction === "short") return entry * (1 + pct);
  if (direction === "long") return entry * (1 - pct);
  return null;
}

function estimateLiquidation(
  entry: number,
  leverage: number,
  direction: DirectionClass,
): number | null {
  if (!Number.isFinite(entry) || leverage <= 0) return null;
  const maintenance = 0.005;
  if (direction === "long") {
    return entry * (1 - 1 / leverage + maintenance);
  }
  if (direction === "short") {
    return entry * (1 + 1 / leverage - maintenance);
  }
  return null;
}

export function buildExecutionContract(
  breakdown: IntentBreakdown,
  ctx: ExecutionContractContext,
  overrides: ContractOverrides = {},
): ExecutionContract {
  const direction =
    overrides.direction ??
    breakdown.slots.direction.value ??
    "long";
  const risk = breakdown.slots.risk.value ?? {};
  const sizePct =
    overrides.sizePct ?? risk.sizePct ?? ctx.defaultSizePct ?? DEFAULT_SIZE_PCT;
  const leverage =
    overrides.leverage ?? risk.leverage ?? ctx.defaultLeverage ?? DEFAULT_LEVERAGE;
  const entry = overrides.entryPrice ?? ctx.entryPrice;
  const asset =
    ctx.assetSymbol ??
    breakdown.resolution.asset.label ??
    breakdown.slots.assets.label ??
    "—";

  const actionLabel =
    direction === "short"
      ? "SHORT (open)"
      : direction === "long"
        ? "LONG (open)"
        : "NEUTRAL";

  const sizeExplicit = risk.sizePct != null || overrides.sizePct != null;
  const levExplicit = risk.leverage != null || overrides.leverage != null;

  let stopPrice =
    overrides.stopLoss ??
    risk.stopLoss ??
    (breakdown.rawText.toLowerCase().includes("tight")
      ? inferStopFromTight(entry, direction)
      : null);

  const stopFromText = risk.stopLoss != null;
  const stopInferred =
    !stopFromText &&
    breakdown.rawText.toLowerCase().includes("tight") &&
    stopPrice != null;

  const notional =
    ctx.bucketBalance != null
      ? (ctx.bucketBalance * sizePct) / 100
      : null;
  const sizeAsset =
    notional != null && entry > 0
      ? `${(notional / entry).toFixed(2)} ${asset.split("-")[0] ?? asset}`
      : `${sizePct}%`;

  const stopPct =
    stopPrice != null && entry > 0
      ? ((stopPrice - entry) / entry) * 100 * (direction === "short" ? 1 : 1)
      : null;

  const liq = estimateLiquidation(entry, leverage, direction);
  const marginRequired =
    notional != null && leverage > 0 ? notional / leverage : null;

  const agentName = ctx.agent?.displayName ?? breakdown.resolution.agent.label;
  const agentWinStub = ctx.agent?.riskScore
    ? `${ctx.agent.riskScore} risk score`
    : "agent-bounded";

  const lines: ExecutionContractLine[] = [
    {
      key: "Action",
      field: "action",
      value: actionLabel,
      source: breakdown.slots.direction.confidence === "resolved" ? "you" : "inferred",
      editable: false,
    },
    {
      key: "Asset",
      field: "asset",
      value: asset,
      source:
        breakdown.resolution.asset.confidence === "resolved" ? "you" : "default",
      editable: true,
    },
    {
      key: "Size",
      field: "size",
      value: `${sizeAsset} (${sizePct}%)`,
      source: sizeExplicit ? "you" : "default",
      editable: true,
      warning: !sizeExplicit,
    },
    {
      key: "Leverage",
      field: "leverage",
      value: `${leverage}x`,
      source: levExplicit ? "you" : "bucket",
      editable: true,
      warning: !levExplicit,
    },
    {
      key: "Entry",
      field: "entry",
      value: entry > 0 ? `market ~${formatPrice(entry)}` : "market",
      source: "inferred",
      editable: true,
    },
    {
      key: "Stop",
      field: "stop",
      value:
        stopPrice != null
          ? `${formatPrice(stopPrice)}${stopPct != null ? ` (${formatPct(stopPct)})` : ""}`
          : "—",
      source: stopFromText ? "you" : stopInferred ? "inferred" : "agent-bounded",
      editable: true,
      warning: stopInferred,
    },
    {
      key: "Take-profit",
      field: "takeProfit",
      value:
        overrides.takeProfit != null || risk.takeProfit != null
          ? formatPrice(overrides.takeProfit ?? risk.takeProfit ?? 0)
          : "—",
      source:
        risk.takeProfit != null ? "you" : "agent-bounded",
      editable: true,
    },
    {
      key: "Bucket",
      field: "bucket",
      value: ctx.bucketLabel ?? "—",
      source: "bucket",
      editable: false,
    },
    {
      key: "Margin",
      field: "margin",
      value: ctx.marginMode ?? "CROSS",
      source: "bucket",
      editable: false,
    },
    {
      key: "Est. liq.",
      field: "estLiq",
      value: liq != null ? formatPrice(liq) : "—",
      source: "inferred",
      editable: false,
    },
    {
      key: "Margin req.",
      field: "marginRequired",
      value:
        marginRequired != null
          ? `${formatPrice(marginRequired)} USDC`
          : "—",
      source: "inferred",
      editable: false,
    },
    {
      key: "Agent",
      field: "agent",
      value: `${agentName} · ${agentWinStub}`,
      source:
        breakdown.resolution.agent.confidence === "resolved" ? "you" : "default",
      editable: true,
      warning: breakdown.resolution.agent.confidence === "defaulted",
    },
  ];

  const hasDefaultedRisk =
    !sizeExplicit || !levExplicit || stopInferred;

  const summaryOneLine = [
    direction.toUpperCase(),
    sizeAsset,
    `${leverage}x`,
    liq != null ? `liq ${formatPrice(liq)}` : null,
  ]
    .filter(Boolean)
    .join(" · ");

  return {
    youSaid: breakdown.rawText,
    lines,
    summaryOneLine,
    hasDefaultedRisk,
  };
}

export function serializeExecutionContract(
  contract: ExecutionContract,
): string {
  return JSON.stringify(contract);
}

export function serializeIntentBreakdown(
  breakdown: IntentBreakdown,
): string {
  return JSON.stringify({
    ...breakdown,
    resolution: breakdown.resolution,
  });
}
