import React from "react";
import KpiCard from "./KpiCard";
import QueryState from "./QueryState";
import { fmtInt, fmtNum } from "./format";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import { useLiveMetrics } from "./useLiveMetrics";
import { useRollingSeries } from "./useRollingSeries";
import type { Status } from "./StatusDot";

function upStatus(value: number | null | undefined): Status | undefined {
  if (value == null) return undefined;
  return value > 0 ? "ok" : "down";
}

export default function LiveMetricsSection(): React.JSX.Element {
  const { throughputTier, validatorCount } = useNetworkHealthDemo();
  const { data, isPending, isError, error } = useLiveMetrics();
  const seriesKey = `${throughputTier}-${validatorCount}`;
  const submitSeries = useRollingSeries(data?.submitTps, 30, seriesKey);
  const confirmedSeries = useRollingSeries(data?.confirmedTps, 30, seriesKey);

  return (
    <QueryState
      isLoading={isPending}
      isError={isError}
      error={error}
      label="live metrics"
    >
      <div className="nh-kpi-grid nh-kpi-grid-4">
        <KpiCard
          label="Submit TPS"
          value={fmtNum(data?.submitTps)}
          unit="tx/s"
          series={submitSeries}
          seriesColor="accent"
          info="Transactions submitted to the network per second, as a ~2-minute smoothed rate — so it climbs gradually after a load starts and briefly reads 0 between bursts."
        />
        <KpiCard
          label="Confirmed TPS"
          value={fmtNum(data?.confirmedTps)}
          unit="tx/s"
          series={confirmedSeries}
          seriesColor="long"
          info="Transactions reaching finality per second, also a ~2-minute smoothed rate. Tracks Submit TPS when the network keeps up; the gap shows current headroom."
        />
        <KpiCard
          label="Finality p50"
          value={fmtNum(data?.finalityP50Ms, 0)}
          unit="ms"
          info="Median time from submission to irreversible finality. This is a latency gauge (the most recent measurement), not a rate."
        />
        <KpiCard
          label="Finality p99"
          value={fmtNum(data?.finalityP99Ms, 0)}
          unit="ms"
          info="99th-percentile (worst-case) time to finality — the tail matters most for HFT."
        />
        <KpiCard
          label="Committee size"
          value={fmtInt(data?.committeeSize)}
          info="Number of validators in the active certifying committee for this height."
        />
        <KpiCard
          label="BFT quorum"
          value={fmtInt(data?.bftQuorum)}
          hint="2f + 1"
          info="Validators that must agree to certify a block (2f + 1 of n). This threshold is what makes two conflicting blocks unable to both finalise."
        />
        <KpiCard
          label="Validators up"
          value={fmtInt(data?.validatorsUp)}
          status={upStatus(data?.validatorsUp)}
          info="Validator nodes currently reporting healthy. A chaos action that takes one down appears here, then recovers as the node self-heals."
        />
        <KpiCard
          label="DVT operators up"
          value={fmtInt(data?.dvtOperatorsUp)}
          status={upStatus(data?.dvtOperatorsUp)}
          info="Distributed-validator-technology operators online. A validator's key is split across operators, so the validator keeps signing even if some operators drop."
        />
      </div>
    </QueryState>
  );
}
