import React, { useCallback, useMemo, useState } from "react";

import type { AgentTokenProfile } from "../../../offline/mock_data/agentTokenProfile";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import AgentTokenKlineChartWidget from "../finchartview/AgentTokenKlineChartWidget";
import AgentAddressField, {
  formatAgentMetadataDate,
} from "./AgentAddressField";
import { shortWalletAddress } from "./agentHeroFocus";
import "./agent.css";

export interface AgentTokenTabProps {
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  tokenProfile: AgentTokenProfile;
}

function AgentTokenKvRow({
  label,
  value,
  mono = false,
}: {
  label: string;
  value: React.ReactNode;
  mono?: boolean;
}): JSX.Element {
  return (
    <div className="agent-token-kv-row">
      <span className="agent-token-kv-label">{label}</span>
      <span
        className={`agent-token-kv-value${mono ? " agent-token-kv-value--mono" : ""}`}
      >
        {value}
      </span>
    </div>
  );
}

function deriveSparklineRange(sparkline: number[]): {
  low: number;
  high: number;
  markerPct: number;
} {
  const clean = sparkline.filter((value) => Number.isFinite(value));
  if (clean.length === 0) {
    return { low: 0, high: 0, markerPct: 50 };
  }
  const low = Math.min(...clean);
  const high = Math.max(...clean);
  const last = clean.at(-1) ?? low;
  const markerPct =
    high === low ? 50 : ((last - low) / (high - low)) * 100;
  return { low, high, markerPct };
}

function AgentTokenTab({
  profile,
  fleet,
  tokenProfile,
}: AgentTokenTabProps): JSX.Element {
  const [copied, setCopied] = useState(false);
  const changeTone =
    profile.change24h >= 0 ? "positive" : "negative";
  const changePrefix = profile.change24h >= 0 ? "+" : "";

  const range = useMemo(
    () => deriveSparklineRange(profile.sparkline),
    [profile.sparkline],
  );

  const { rangeLow, rangeHigh } = useMemo(() => {
    const clean = profile.sparkline.filter((v) => Number.isFinite(v));
    if (clean.length < 2) {
      return {
        rangeLow: profile.price * 0.95,
        rangeHigh: profile.price * 1.05,
      };
    }
    const min = Math.min(...clean);
    const max = Math.max(...clean);
    const last = clean.at(-1) ?? profile.price;
    if (last === 0) {
      return { rangeLow: profile.price, rangeHigh: profile.price };
    }
    return {
      rangeLow: profile.price * (min / last),
      rangeHigh: profile.price * (max / last),
    };
  }, [profile.price, profile.sparkline]);

  const priceDecimals = profile.price < 1 ? 4 : 2;

  const handleCopyContract = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(fleet.tokenAddress);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      setCopied(false);
    }
  }, [fleet.tokenAddress]);

  return (
    <div className="agent-token-tab">
      <div className="agent-token-price-header">
        <span className="agent-token-price-label">
          {profile.ticker} Price
          {tokenProfile.rank != null ? (
            <span className="agent-token-rank">#{tokenProfile.rank}</span>
          ) : null}
        </span>
        <strong className="agent-token-price-value">
          ${profile.price.toFixed(priceDecimals)}
        </strong>
        <span
          className={`agent-token-change agent-token-change--${changeTone}`}
        >
          {changePrefix}
          {profile.change24h.toFixed(1)}% (24h)
        </span>
      </div>

      <div className="agent-token-range">
        <div className="agent-token-range-labels">
          <span>Low: ${rangeLow.toFixed(priceDecimals)}</span>
          <span>High: ${rangeHigh.toFixed(priceDecimals)}</span>
        </div>
        <div className="agent-token-range-bar" aria-hidden>
          <div
            className="agent-token-range-bar-fill"
            style={{ width: `${range.markerPct}%` }}
          />
          <div
            className="agent-token-range-bar-marker"
            style={{ left: `${range.markerPct}%` }}
          />
        </div>
        <span className="agent-token-range-caption">24h range</span>
      </div>

      <div className="agent-token-chart-wrap">
        <AgentTokenKlineChartWidget
          catalogAgentId={profile.id}
          height="280px"
          interval="5m"
        />
      </div>

      <div className="agent-token-kv-list">
        <AgentTokenKvRow label="Market cap" value={profile.marketCap} />
        <AgentTokenKvRow
          label="Fully diluted valuation"
          value={tokenProfile.fullyDilutedValuation}
        />
        <AgentTokenKvRow label="24h volume" value={profile.volume24h} />
        {profile.openInterest != null ? (
          <AgentTokenKvRow
            label="Open interest"
            value={`$${(profile.openInterest / 1_000_000).toFixed(1)}M`}
          />
        ) : null}
        {profile.annFunding != null ? (
          <AgentTokenKvRow
            label="Ann. funding"
            value={`${profile.annFunding.toFixed(1)}%`}
          />
        ) : null}
      </div>

      <div className="agent-token-kv-list">
        <AgentTokenKvRow
          label="Circulating supply"
          value={tokenProfile.circulatingSupply}
        />
        <AgentTokenKvRow label="Total supply" value={tokenProfile.totalSupply} />
        <AgentTokenKvRow label="Max supply" value={tokenProfile.maxSupply} />
      </div>

      <div className="agent-token-kv-list">
        <AgentTokenKvRow
          label="Contract"
          mono
          value={
            <span className="agent-token-contract-row">
              <span>{shortWalletAddress(fleet.tokenAddress)}</span>
              <button
                type="button"
                className="agent-token-copy-btn"
                onClick={handleCopyContract}
                aria-label="Copy contract address"
              >
                {copied ? "Copied" : "Copy"}
              </button>
            </span>
          }
        />
        {tokenProfile.tokenIssuedAt ? (
          <AgentTokenKvRow
            label="Token issue date"
            value={formatAgentMetadataDate(tokenProfile.tokenIssuedAt)}
          />
        ) : null}
        {tokenProfile.feeRecipient ? (
          <AgentAddressField
            label="Fee recipient"
            address={tokenProfile.feeRecipient}
            layout="token"
          />
        ) : null}
        <AgentTokenKvRow label="Chain" value={tokenProfile.chain} />
        <AgentTokenKvRow label="Catalog id" value={profile.id} mono />
        <div className="agent-token-kv-row agent-token-kv-row--categories">
          <span className="agent-token-kv-label">Categories</span>
          <div className="agent-token-categories">
            {tokenProfile.categories.map((category) => (
              <span key={category} className="agent-wallet-badge">
                {category}
              </span>
            ))}
          </div>
        </div>
        <AgentTokenKvRow
          label="Explorer"
          value={
            <button
              type="button"
              className="agent-token-link-btn"
              disabled
              title="Demo explorer"
            >
              {tokenProfile.explorerLabel}
            </button>
          }
        />
      </div>

      {profile.links.length > 0 ? (
        <div className="agent-token-links">
          {profile.links.map((link) => (
            <button
              key={link}
              type="button"
              className="agent-secondary-btn agent-secondary-btn--block"
              disabled
              title="Demo link"
            >
              {link}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export default AgentTokenTab;
