import { useState, useEffect } from "react";

const DEFAULT_FUNDING_INTERVAL_SECONDS = 28800;

function resolveNextFundingTimeUnix(
  nextFromFeed: number | null | undefined,
  intervalSeconds: number,
): number | null {
  if (nextFromFeed != null && nextFromFeed > 0) {
    return nextFromFeed > 1e12 ? nextFromFeed / 1000 : nextFromFeed;
  }

  if (intervalSeconds <= 0) return null;

  const nowMs = Date.now();
  const periodMs = intervalSeconds * 1000;
  return (Math.ceil(nowMs / periodMs) * periodMs) / 1000;
}

function formatCountdown(secondsRemaining: number): string {
  const total = Math.max(0, Math.floor(secondsRemaining));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

/**
 * Live HH:MM:SS countdown to the next funding event.
 */
export function useFundingCountdown(
  nextFundingTimeUnix: number | null | undefined,
  fundingIntervalSeconds: number = DEFAULT_FUNDING_INTERVAL_SECONDS,
): string {
  const [display, setDisplay] = useState("--:--:--");

  useEffect(() => {
    const tick = () => {
      const nextUnix = resolveNextFundingTimeUnix(
        nextFundingTimeUnix,
        fundingIntervalSeconds,
      );
      if (nextUnix == null) {
        setDisplay("--:--:--");
        return;
      }
      setDisplay(formatCountdown(nextUnix - Date.now() / 1000));
    };

    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [nextFundingTimeUnix, fundingIntervalSeconds]);

  return display;
}
