import type { JSX } from "react";
import { Link } from "react-router-dom";
import { BubbleTip } from "./BubbleTip";
import { BUBBLE_TIP_SECTIONS, type BubbleTipId } from "./bubbleTipIds";
import { getBubbleTipContent } from "./bubbleTipContent";
import { guideTriggerNeedsLabel, renderGuideTrigger } from "./guideDemoTriggers";

function GuideDemo({ tipId }: { tipId: BubbleTipId }): JSX.Element {
  const entry = getBubbleTipContent(tipId);
  const showLabel = guideTriggerNeedsLabel(tipId);

  return (
    <div className="bubble-tip-guide__demo">
      {showLabel ? <span className="terminal-label">{entry.label}</span> : null}
      <BubbleTip id={tipId} hideLabel forceShow>
        <div className="bubble-tip-guide__demo-trigger" tabIndex={0}>
          {renderGuideTrigger(tipId)}
        </div>
      </BubbleTip>
    </div>
  );
}

export function BubbleTipGuide(): JSX.Element {
  return (
    <div className="bubble-tip-guide">
      <Link to="/trade" className="bubble-tip-guide__back">
        ← Back to Trade
      </Link>

      <header className="bubble-tip-guide__header">
        <p className="bubble-tip-guide__eyebrow">Tutorials</p>
        <h1 className="bubble-tip-guide__title">Hover Bubble Guide</h1>
        <p className="bubble-tip-guide__intro">
          Preview Morpheum&apos;s agent-first bubble tooltips used across the trade
          terminal. Registry source:{" "}
          <code>packages/mormv1/tutorials/bubble-tip/bubbleTipContent.ts</code>.
          Full inventory: <code>packages/rules/tooltips.md</code>.
        </p>
        <p className="bubble-tip-guide__hint">
          Hover or focus each element below to preview its tooltip copy.
        </p>
      </header>

      {BUBBLE_TIP_SECTIONS.map((section) => (
        <section key={section.id} className="bubble-tip-guide__section">
          <h2 className="bubble-tip-guide__section-title terminal-panel-title">{section.title}</h2>
          <div className="bubble-tip-guide__grid">
            {section.tipIds.map((tipId) => (
              <GuideDemo key={tipId} tipId={tipId} />
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}
