import { compressToUTF16, decompressFromUTF16 } from "lz-string";
import type { OfflinePortfolio } from "./offlinePortfolio";

export const OFFLINE_PORTFOLIO_STORAGE_VERSION = 1;
export const OFFLINE_PORTFOLIO_STORAGE_PREFIX = "offline_pf:v1";

export const PORTFOLIO_SHARDS = [
  "meta",
  "buckets",
  "positions",
  "openOrders",
  "orderHistory",
  "fundingHistory",
  "agentTasks",
] as const;

export type PortfolioShard = (typeof PORTFOLIO_SHARDS)[number];

export type PortfolioMetaShard = {
  bucketIds: string[];
};

export type OfflinePortfolioManifest = {
  version: number;
  walletAddress: string;
  savedAt: string;
  compressed: Partial<Record<PortfolioShard, boolean>>;
  shards: Record<PortfolioShard, boolean>;
  counts: {
    bucketIds: number;
    buckets: number;
    positions: number;
    openOrders: number;
    orderHistory: number;
    fundingHistory: number;
    agentTasks: number;
  };
  totalBytes: number;
};

const COMPRESS_THRESHOLD_BYTES = 8 * 1024;

type StorageLike = Pick<Storage, "getItem" | "setItem" | "removeItem" | "key" | "length">;

let storageAdapter: StorageLike | null =
  typeof localStorage !== "undefined" ? localStorage : null;

function resolveStoredWallet(address?: string | null): string | null {
  const trimmed = address?.trim();
  if (!trimmed) return null;
  return trimmed.toLowerCase();
}

export function setOfflinePortfolioStorageAdapter(adapter: StorageLike | null): void {
  storageAdapter = adapter;
}

function getStorage(): StorageLike | null {
  return storageAdapter;
}

function walletPrefix(wallet: string): string {
  return `${OFFLINE_PORTFOLIO_STORAGE_PREFIX}:${resolveStoredWallet(wallet) ?? wallet}`;
}

function shardKey(wallet: string, shard: PortfolioShard): string {
  return `${walletPrefix(wallet)}:${shard}`;
}

function manifestKey(wallet: string): string {
  return `${walletPrefix(wallet)}:manifest`;
}

function encodeShardValue(json: string): { payload: string; compressed: boolean } {
  if (json.length >= COMPRESS_THRESHOLD_BYTES) {
    return { payload: compressToUTF16(json), compressed: true };
  }
  return { payload: json, compressed: false };
}

function decodeShardValue(payload: string, compressed: boolean): string {
  if (!compressed) return payload;
  const decoded = decompressFromUTF16(payload);
  if (decoded == null) {
    throw new Error("Failed to decompress offline portfolio shard");
  }
  return decoded;
}

function parseStoredShard<T>(raw: string): T {
  const parsed = JSON.parse(raw) as { compressed?: boolean; data?: T } | T;
  if (parsed != null && typeof parsed === "object" && "data" in parsed) {
    const envelope = parsed as { compressed?: boolean; data: T };
    if (typeof envelope.data === "string") {
      return JSON.parse(
        decodeShardValue(envelope.data, envelope.compressed === true),
      ) as T;
    }
    return envelope.data;
  }
  return parsed as T;
}

function writeStoredShard<T>(value: T): string {
  const json = JSON.stringify(value);
  const { payload, compressed } = encodeShardValue(json);
  if (!compressed) return json;
  return JSON.stringify({ compressed: true, data: payload });
}

export function clearOfflinePortfolioStorage(wallet?: string | null): void {
  const storage = getStorage();
  if (!storage) return;

  if (wallet) {
    const prefix = walletPrefix(wallet);
    const keysToRemove: string[] = [];
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      if (key?.startsWith(`${prefix}:`)) keysToRemove.push(key);
    }
    for (const key of keysToRemove) storage.removeItem(key);
    return;
  }

  clearAllOfflinePortfolioStorage();
}

export function clearAllOfflinePortfolioStorage(): void {
  const storage = getStorage();
  if (!storage) return;
  const keysToRemove: string[] = [];
  for (let i = 0; i < storage.length; i++) {
    const key = storage.key(i);
    if (key?.startsWith(`${OFFLINE_PORTFOLIO_STORAGE_PREFIX}:`)) {
      keysToRemove.push(key);
    }
  }
  for (const key of keysToRemove) storage.removeItem(key);
}

/** Keep a single demo wallet snapshot — remove other wallet prefixes. */
export function clearOtherOfflinePortfolioWallets(activeWallet: string): void {
  const storage = getStorage();
  if (!storage) return;
  const activePrefix = walletPrefix(activeWallet);
  const keysToRemove: string[] = [];
  for (let i = 0; i < storage.length; i++) {
    const key = storage.key(i);
    if (
      key?.startsWith(`${OFFLINE_PORTFOLIO_STORAGE_PREFIX}:`) &&
      !key.startsWith(`${activePrefix}:`)
    ) {
      keysToRemove.push(key);
    }
  }
  for (const key of keysToRemove) storage.removeItem(key);
}

export function savePortfolioShard(
  wallet: string,
  shard: PortfolioShard,
  data: unknown,
): { bytes: number; compressed: boolean } {
  const storage = getStorage();
  if (!storage) {
    throw new Error("localStorage is not available");
  }
  const json = JSON.stringify(data);
  const { payload, compressed } = encodeShardValue(json);
  const stored =
    compressed ? JSON.stringify({ compressed: true, data: payload }) : json;
  try {
    storage.setItem(shardKey(wallet, shard), stored);
  } catch (error) {
    throw new Error(
      `Failed to save offline portfolio shard "${shard}": ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  return { bytes: stored.length, compressed };
}

export function loadPortfolioShard<T>(
  wallet: string,
  shard: PortfolioShard,
): T | null {
  const storage = getStorage();
  if (!storage) return null;
  const raw = storage.getItem(shardKey(wallet, shard));
  if (!raw) return null;
  try {
    return parseStoredShard<T>(raw);
  } catch {
    return null;
  }
}

export function savePortfolioManifest(
  wallet: string,
  manifest: OfflinePortfolioManifest,
): void {
  const storage = getStorage();
  if (!storage) {
    throw new Error("localStorage is not available");
  }
  storage.setItem(manifestKey(wallet), JSON.stringify(manifest));
}

export function loadPortfolioManifest(
  wallet: string,
): OfflinePortfolioManifest | null {
  const storage = getStorage();
  if (!storage) return null;
  const raw = storage.getItem(manifestKey(wallet));
  if (!raw) return null;
  try {
    return JSON.parse(raw) as OfflinePortfolioManifest;
  } catch {
    return null;
  }
}

export function hasOfflinePortfolioInStorage(wallet?: string | null): boolean {
  const normalized = resolveStoredWallet(wallet);
  if (!normalized) return false;
  const manifest = loadPortfolioManifest(normalized);
  if (!manifest) return false;
  return PORTFOLIO_SHARDS.every((shard) => loadPortfolioShard(normalized, shard) != null);
}

export function saveOfflinePortfolioToStorage(portfolio: OfflinePortfolio): OfflinePortfolioManifest {
  const wallet = resolveStoredWallet(portfolio.walletAddress);
  if (!wallet) {
    throw new Error("Cannot save offline portfolio without walletAddress");
  }
  clearOtherOfflinePortfolioWallets(wallet);

  let totalBytes = 0;
  const compressed: Partial<Record<PortfolioShard, boolean>> = {};

  const shardWrites: Array<{ shard: PortfolioShard; data: unknown }> = [
    { shard: "meta", data: { bucketIds: portfolio.bucketIds } satisfies PortfolioMetaShard },
    { shard: "buckets", data: portfolio.buckets },
    { shard: "positions", data: portfolio.positions },
    { shard: "openOrders", data: portfolio.openOrders },
    { shard: "orderHistory", data: portfolio.orderHistory },
    { shard: "fundingHistory", data: portfolio.fundingHistory },
    { shard: "agentTasks", data: portfolio.agentTasks },
  ];

  try {
    for (const { shard, data } of shardWrites) {
      const result = savePortfolioShard(wallet, shard, data);
      totalBytes += result.bytes;
      if (result.compressed) compressed[shard] = true;
    }

    const manifest: OfflinePortfolioManifest = {
      version: OFFLINE_PORTFOLIO_STORAGE_VERSION,
      walletAddress: wallet,
      savedAt: new Date().toISOString(),
      compressed,
      shards: Object.fromEntries(PORTFOLIO_SHARDS.map((s) => [s, true])) as Record<
        PortfolioShard,
        boolean
      >,
      counts: {
        bucketIds: portfolio.bucketIds.length,
        buckets: portfolio.buckets.length,
        positions: portfolio.positions.length,
        openOrders: portfolio.openOrders.length,
        orderHistory: portfolio.orderHistory.length,
        fundingHistory: portfolio.fundingHistory.length,
        agentTasks: portfolio.agentTasks.length,
      },
      totalBytes,
    };
    savePortfolioManifest(wallet, manifest);
    return manifest;
  } catch (error) {
    clearOfflinePortfolioStorage(wallet);
    throw error;
  }
}

export function loadOfflinePortfolioFromStorage(
  wallet?: string | null,
): OfflinePortfolio | null {
  const normalized = resolveStoredWallet(wallet);
  if (!normalized) return null;
  const manifest = loadPortfolioManifest(normalized);
  if (!manifest) return null;

  const meta = loadPortfolioShard<PortfolioMetaShard>(normalized, "meta");
  const buckets = loadPortfolioShard<OfflinePortfolio["buckets"]>(normalized, "buckets");
  const positions = loadPortfolioShard<OfflinePortfolio["positions"]>(normalized, "positions");
  const openOrders = loadPortfolioShard<OfflinePortfolio["openOrders"]>(normalized, "openOrders");
  const orderHistory = loadPortfolioShard<OfflinePortfolio["orderHistory"]>(normalized, "orderHistory");
  const fundingHistory = loadPortfolioShard<OfflinePortfolio["fundingHistory"]>(
    normalized,
    "fundingHistory",
  );
  const agentTasks = loadPortfolioShard<OfflinePortfolio["agentTasks"]>(normalized, "agentTasks");

  if (
    !meta ||
    !buckets ||
    !positions ||
    !openOrders ||
    !orderHistory ||
    !fundingHistory ||
    !agentTasks
  ) {
    clearOfflinePortfolioStorage(normalized);
    return null;
  }

  if (
    meta.bucketIds.length !== manifest.counts.bucketIds ||
    buckets.length !== manifest.counts.buckets ||
    positions.length !== manifest.counts.positions ||
    openOrders.length !== manifest.counts.openOrders ||
    orderHistory.length !== manifest.counts.orderHistory ||
    fundingHistory.length !== manifest.counts.fundingHistory ||
    agentTasks.length !== manifest.counts.agentTasks
  ) {
    clearOfflinePortfolioStorage(normalized);
    return null;
  }

  return {
    walletAddress: normalized,
    bucketIds: meta.bucketIds,
    buckets,
    positions,
    openOrders,
    orderHistory,
    fundingHistory,
    agentTasks,
    allOrders: [...openOrders, ...orderHistory, ...fundingHistory],
  };
}

export function getOfflinePortfolioManifestCounts(
  wallet?: string | null,
): OfflinePortfolioManifest["counts"] | null {
  const normalized = resolveStoredWallet(wallet);
  if (!normalized) return null;
  return loadPortfolioManifest(normalized)?.counts ?? null;
}
