import React from "react";
import { useSubscription } from "../../../context/SubscriptionContext";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";

export type FeedHealthStatus = "ok" | "degraded" | "offline";

function deriveStatus(isConnected: boolean): FeedHealthStatus {
  if (isConnected) return "ok";
  return "offline";
}

const STATUS_LABEL: Record<FeedHealthStatus, string> = {
  ok: "Feed connected",
  degraded: "Feed degraded",
  offline: "Feed disconnected",
};

function FeedHealthDot(): JSX.Element {
  const { isConnected } = useSubscription();
  const status = deriveStatus(isConnected);

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.highAFeedHealth}>
      <span
        className={`high-a-feed-health high-a-feed-health--${status}`}
        role="status"
        aria-label={STATUS_LABEL[status]}
      >
        <span className="high-a-feed-health-dot" aria-hidden />
      </span>
    </BubbleTip>
  );
}

export default React.memo(FeedHealthDot);
