import { mainnet, sepolia } from "viem/chains";
import "../mormv1/index.css";
import "../mormv1/terminal.css";
import "../mormv1/chip.css";
import "./App.css";
import TradeTerminalPage from "../mormv1/pages/TradeTerminalPage";
import { useCopyMirrorOrchestrator } from "../mormv1/hooks/useCopyMirrorOrchestrator";
import MarketsPage from "../mormv1/pages/MarketsPage";
import IndexListPage from "../mormv1/pages/IndexListPage";
import IndexDetailPage from "../mormv1/pages/IndexDetailPage";
import PortfolioPage from "../mormv1/pages/PortfolioPage";
import AgentPage from "../mormv1/pages/AgentPage";
import AgentComparePage from "../mormv1/pages/AgentComparePage";
import MenuBar from "../mormv1/components/MenuBar";
import { OnboardModal } from "../mormv1/components/OnboardModal";
import { JellyIntroModal } from "../mormv1/components/jelly/JellyIntroModal";
import { JellyReplaySync } from "../mormv1/components/jelly/JellyReplaySync";
import { JellyReplayGuide } from "../mormv1/components/jelly/JellyReplayGuide";
import { Toaster } from "../mormv1/components/ui/Toaster";
import { useOnboard, OnboardProvider } from "../mormv1/hooks/useOnboard";
import { WalletConnectHostProvider } from "../mormv1/context/WalletConnectHostContext";
import { getAppRoute } from "../mormv1/routes";
import {
  dispatchPreNavigateCleanup,
  getBrowserLocationKey,
  needsChartTeardownBeforeNavigate,
  subscribeBrowserPathname,
} from "../mormv1/utils/preNavigateCleanup";
import { SubscriptionProvider } from "../mormv1/context/SubscriptionContext";
import { JellyModeProvider, useJellyMode } from "../mormv1/context/JellyModeContext";
import {
  TransferModalsProvider,
  useTransferModals,
} from "../mormv1/context/TransferModalsContext";
import { SettingsProvider } from "../mormv1/context/SettingsContext";
import { AgentTokenManifestProvider } from "../mormv1/context/AgentTokenManifestContext";
import { AgentKpiManifestProvider } from "../mormv1/context/AgentKpiManifestContext";
import { SettingsHost, useSettingsHost } from "../mormv1/context/SettingsHostContext";
import QuorumIntersectionPage from "./explainations/quorum-intersection/QuorumIntersectionPage";
import NetworkHealthPage from "./explainations/networkhealth/NetworkHealthPage";
import {
  OfflinePortfolioProvider,
  useOfflinePortfolio,
} from "./context/OfflinePortfolioContext";
import {
  WelcomeTourProvider,
  WelcomeTourShell,
  useWelcomeTour,
} from "../mormv1/tutorials/welcome-tour";
import {
  DepositTourProvider,
  DepositTourJoyride,
  useDepositTour,
} from "../mormv1/tutorials/deposit-tour";
import {
  CopyTourJoyride,
  CopyTourPreflightModal,
  CopyTourProvider,
  useCopyTour,
} from "../mormv1/tutorials/copy-tour";
import { useBucketCollections } from "../mormv1/hooks/useBucketCollections";
import {
  DemoGuideActionsProvider,
  type DemoGuideActions,
} from "../mormv1/tutorials/demo-guide/DemoGuideActionsContext";
import { useWelcomeTourOrchestration } from "./tutorials/useWelcomeTourOrchestration";
import {
  clearWelcomeSeen,
  hasSeenWelcome,
  markWelcomeSeen,
} from "./tutorials/welcomeTourStorage";
import {
  clearDepositTourSeen,
  markDepositTourSeen,
} from "./tutorials/depositTourStorage";
import {
  clearCopyTourSeen,
  markCopyTourSeen,
} from "./tutorials/copyTourStorage";
import { BubbleTipProvider } from "../mormv1/tutorials/bubble-tip";
import BubbleTipGuidePage from "./tutorials/BubbleTipGuidePage";
import { KeyboardShortcutsModal } from "../mormv1/tutorials/keyboard-shortcuts";
import { toast } from "sonner";

const OFFLINE_BASE_URL = "offline://local";
const ONBOARD_COMPLETED_KEY = "onboard_completed";

const wagmiConfig = createConfig({
  chains: [mainnet, sepolia],
  connectors: [injected()],
  transports: {
    [mainnet.id]: http(),
    [sepolia.id]: http(),
  },
});

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: Infinity,
      gcTime: Infinity,
      refetchOnWindowFocus: false,
      refetchOnReconnect: false,
      retry: false,
    },
    mutations: {
      retry: false,
    },
  },
});

function OfflineShellInner(): JSX.Element {
  const [keyboardShortcutsOpen, setKeyboardShortcutsOpen] = useState(false);

  const openKeyboardShortcuts = useCallback(() => {
    setKeyboardShortcutsOpen(true);
  }, []);

  return (
    <SettingsHost onOpenKeyboardShortcuts={openKeyboardShortcuts}>
      <OfflineShellContent
        keyboardShortcutsOpen={keyboardShortcutsOpen}
        openKeyboardShortcuts={openKeyboardShortcuts}
        onCloseKeyboardShortcuts={() => setKeyboardShortcutsOpen(false)}
      />
    </SettingsHost>
  );
}

interface OfflineShellContentProps {
  keyboardShortcutsOpen: boolean;
  openKeyboardShortcuts: () => void;
  onCloseKeyboardShortcuts: () => void;
}

function OfflineShellContent({
  keyboardShortcutsOpen,
  openKeyboardShortcuts,
  onCloseKeyboardShortcuts,
}: OfflineShellContentProps): JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const browserLocationKey = useSyncExternalStore(
    subscribeBrowserPathname,
    getBrowserLocationKey,
    getBrowserLocationKey,
  );

  const routeLocation = useMemo(() => {
    if (typeof window === "undefined") return location;
    const { pathname, search, hash } = window.location;
    if (
      pathname === location.pathname &&
      search === location.search &&
      hash === location.hash
    ) {
      return location;
    }
    return {
      ...location,
      pathname,
      search,
      hash,
      key: `browser-${pathname}${search}${hash}`,
    };
  }, [location, browserLocationKey]);

  // Keep React Router internal state aligned when the browser URL advances first.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const { pathname, search, hash } = window.location;
    const browserTarget = `${pathname}${search}${hash}`;
    const routerTarget = `${location.pathname}${location.search}${location.hash}`;
    if (browserTarget !== routerTarget) {
      navigate(browserTarget, { replace: true });
    }
  }, [browserLocationKey, location, navigate]);

  const {
    isJellyMode,
    enterJellyMode,
    toggleJellyMode,
    showIntroModal,
    startReplay,
    dismissIntroAndStart,
    openIntroModal,
    replayPhase,
  } = useJellyMode();
  const { openBucketTransfer, openCoinTransfer, openCrossChainFlow } = useTransferModals();
  const {
    walletAddress,
    mnemonic,
    authToken,
    setAccountData,
    onboard,
    resetAll,
  } = useOnboard(OFFLINE_BASE_URL);
  useCopyMirrorOrchestrator(walletAddress);
  const { initializeForMnemonicConnect, resetPortfolio, portfolioReady } =
    useOfflinePortfolio();
  const { openWelcomeModal, closeWelcomeModal, isTradeUiReady, stopTour: stopWelcomeTour } = useWelcomeTour();
  const { startDepositTour, registerTourMutex, stopTour: stopDepositTour } =
    useDepositTour();
  const copyTour = useCopyTour();
  const { startCopyTour, stopTour: stopCopyTour } = copyTour;
  const { openSettings } = useSettingsHost();
  const [showConnectModal, setShowConnectModal] = useState(false);

  useEffect(() => {
    return registerTourMutex(() => {
      stopWelcomeTour();
      stopCopyTour();
    });
  }, [registerTourMutex, stopCopyTour, stopWelcomeTour]);

  const handleOpenNetworkHealth = useCallback(() => {
    closeWelcomeModal();
    navigate(getAppRoute("networkHealth"));
  }, [closeWelcomeModal, navigate]);

  const handleStartJellyIncident = useCallback(() => {
    closeWelcomeModal();
    markWelcomeSeen();
    if (location.pathname !== "/trade") {
      navigate("/trade");
    }
    if (!isJellyMode) {
      enterJellyMode();
    }
  }, [
    closeWelcomeModal,
    enterJellyMode,
    isJellyMode,
    location.pathname,
    navigate,
  ]);

  const handleOpenWelcomeHub = useCallback(() => {
    openWelcomeModal();
  }, [openWelcomeModal]);

  const handleStartCopyTour = useCallback(() => {
    closeWelcomeModal();
    if (!walletAddress?.trim()) {
      toast.error("Connect wallet first", {
        description: "Connect your wallet before starting the copy tour.",
      });
      return;
    }
    if (isJellyMode) {
      toast.info("Exit JELLY mode to run the copy tour.");
      return;
    }
    startCopyTour();
  }, [closeWelcomeModal, isJellyMode, startCopyTour, walletAddress]);

  const handleStartDepositTour = useCallback(() => {
    closeWelcomeModal();
    if (!walletAddress?.trim()) {
      toast.error("Connect wallet first", {
        description: "Connect your wallet before starting the deposit tour.",
      });
      return;
    }
    if (isJellyMode) {
      toast.info("Exit JELLY mode to run the deposit tour.");
      return;
    }
    startDepositTour({ entry: "wallet-menu" });
  }, [closeWelcomeModal, isJellyMode, startDepositTour, walletAddress]);

  const demoGuideActions = useMemo<DemoGuideActions>(
    () => ({
      startJellyIncident: handleStartJellyIncident,
      openNetworkHealth: handleOpenNetworkHealth,
      openWelcomeHub: handleOpenWelcomeHub,
    }),
    [handleOpenNetworkHealth, handleOpenWelcomeHub, handleStartJellyIncident],
  );

  const handleSettingsClick = useCallback(() => {
    openSettings();
  }, [openSettings]);

  const handleConnectClick = useCallback(() => {
    setShowConnectModal(true);
  }, []);

  const walletConnectHostValue = useMemo(
    () => ({ requestConnect: handleConnectClick }),
    [handleConnectClick],
  );

  const handleMnemonicConnect = useCallback(
    async (mnemonicPhrase: string, address: string) => {
      await onboard(mnemonicPhrase, OFFLINE_BASE_URL);
      localStorage.setItem(ONBOARD_COMPLETED_KEY, "1");
      setShowConnectModal(false);
      await initializeForMnemonicConnect(address);
    },
    [onboard, initializeForMnemonicConnect],
  );

  const handleWalletExtensionConnect = useCallback(
    (address: string) => {
      resetPortfolio();
      setAccountData("", address);
      localStorage.setItem(ONBOARD_COMPLETED_KEY, "1");
      setShowConnectModal(false);
    },
    [resetPortfolio, setAccountData],
  );

  const handleDisconnect = useCallback(() => {
    resetPortfolio(walletAddress);
    resetAll();
    localStorage.removeItem(ONBOARD_COMPLETED_KEY);
    clearWelcomeSeen();
    clearDepositTourSeen();
    clearCopyTourSeen();
  }, [resetAll, resetPortfolio, walletAddress]);

  useWelcomeTourOrchestration({
    portfolioReady,
    walletAddress,
    isJellyMode,
  });

  const { spotWalletBalance } = useBucketCollections({
    baseURL: OFFLINE_BASE_URL,
    walletAddress: walletAddress ?? "",
    refreshInterval: 5000,
  });

  useEffect(
    () => copyTour.registerWallet(() => walletAddress ?? null),
    [copyTour, walletAddress],
  );

  useEffect(
    () => copyTour.registerSpotBalance(() => spotWalletBalance),
    [copyTour, spotWalletBalance],
  );

  useEffect(
    () =>
      copyTour.registerTourMutex(() => {
        stopWelcomeTour();
        stopDepositTour();
      }),
    [copyTour, stopDepositTour, stopWelcomeTour],
  );

  // Only block the trade page while its grid/markets hydrate — never overlay agent,
  // markets, or portfolio routes (that trapped menu navigation on first connect).
  const showTourBootstrapLoading =
    !hasSeenWelcome() &&
    portfolioReady &&
    Boolean(walletAddress?.trim()) &&
    !isJellyMode &&
    !isTradeUiReady &&
    location.pathname === "/trade";

  return (
    <DemoGuideActionsProvider value={demoGuideActions}>
      <WalletConnectHostProvider value={walletConnectHostValue}>
      <MenuBar
        brandName="Morpheum"
        networkChainName="Morpheum Network"
        walletAddress={walletAddress}
        onSettingsClick={handleSettingsClick}
        onConnectClick={handleConnectClick}
        jellyModeActive={isJellyMode}
        jellyReplayActive={replayPhase === "replaying"}
        onJellyModeToggle={isJellyMode ? toggleJellyMode : undefined}
        onJellyIntroClick={isJellyMode ? openIntroModal : undefined}
        showWelcomeTourHelp={Boolean(walletAddress?.trim())}
        onWelcomeTourClick={openWelcomeModal}
        onBucketTransfer={openBucketTransfer}
        onCoinTransfer={openCoinTransfer}
        onDeposit={() => openCrossChainFlow("deposit")}
        onWithdraw={() => openCrossChainFlow("withdraw")}
        onDisconnect={handleDisconnect}
        deferMenuNavigation={needsChartTeardownBeforeNavigate(location.pathname)}
        onPreNavigateCleanup={dispatchPreNavigateCleanup}
      />
      <Routes location={routeLocation}>
        <Route path="/" element={<MarketsPage />} />
        <Route
          path="/trade"
          element={
            <TradeTerminalPage
              onOpenKeyboardShortcuts={openKeyboardShortcuts}
              onOpenNetworkHealth={handleOpenNetworkHealth}
              shellManagesOnboard
              shellWalletAddress={walletAddress}
              shellMnemonic={mnemonic}
              shellAuthToken={authToken}
            />
          }
        />
        <Route path="/markets" element={<MarketsPage />} />
        <Route
          path="/portfolio"
          element={
            <PortfolioPage
              shellManagesOnboard
              shellWalletAddress={walletAddress}
              shellMnemonic={mnemonic}
              shellAuthToken={authToken}
            />
          }
        />
        <Route path="/agents/compare" element={<AgentComparePage />} />
        <Route path="/agents/:id" element={<AgentPage />} />
        <Route path="/cindex" element={<IndexListPage />} />
        <Route path="/cindex/:baseAsset" element={<IndexDetailPage />} />
        <Route path="/explainations/quorum-intersection" element={<QuorumIntersectionPage />} />
        <Route path="/explainations/networkhealth" element={<NetworkHealthPage />} />
        <Route path="/tutorials/bubble-tip" element={<BubbleTipGuidePage />} />
      </Routes>
      <JellyIntroModal
        isOpen={isJellyMode && showIntroModal}
        onStartReplay={startReplay}
        onDismissAndStart={dismissIntroAndStart}
      />
      <JellyReplaySync />
      <JellyReplayGuide />
      <OnboardModal
        isOpen={showConnectModal}
        onClose={() => setShowConnectModal(false)}
        onMnemonicConnect={handleMnemonicConnect}
        onWalletExtensionConnect={handleWalletExtensionConnect}
        baseURL={OFFLINE_BASE_URL}
      />
      <WelcomeTourShell
        showBootstrapLoading={showTourBootstrapLoading}
        onOpenKeyboardShortcuts={openKeyboardShortcuts}
        onStartJellyIncident={handleStartJellyIncident}
        onOpenNetworkHealth={handleOpenNetworkHealth}
        onStartDepositTour={handleStartDepositTour}
        onStartCopyTour={handleStartCopyTour}
      />
      <DepositTourJoyride />
      <CopyTourPreflightModal />
      <CopyTourJoyride />
      <KeyboardShortcutsModal
        isOpen={keyboardShortcutsOpen}
        onClose={onCloseKeyboardShortcuts}
      />
      <Toaster position="bottom-right" />
      </WalletConnectHostProvider>
    </DemoGuideActionsProvider>
  );
}

function OfflineShell() {
  const { walletAddress } = useOnboard(OFFLINE_BASE_URL);
  return (
    <OfflinePortfolioProvider walletAddress={walletAddress}>
      <BubbleTipProvider>
        <WelcomeTourProvider onWelcomeSeen={markWelcomeSeen}>
          <OfflineShellInner />
        </WelcomeTourProvider>
      </BubbleTipProvider>
    </OfflinePortfolioProvider>
  );
}

export default function OfflineApp() {
  return (
    <WagmiProvider config={wagmiConfig}>
      <QueryClientProvider client={queryClient}>
        <BrowserRouter>
          <OnboardProvider>
          <SubscriptionProvider
            defaultWsURL=""
            defaultBaseURL={OFFLINE_BASE_URL}
          >
            <DepositTourProvider onDepositTourSeen={markDepositTourSeen}>
            <CopyTourProvider onCopyTourSeen={markCopyTourSeen}>
            <TransferModalsProvider baseURL={OFFLINE_BASE_URL}>
                <SettingsProvider>
                <AgentTokenManifestProvider>
                  <AgentKpiManifestProvider>
                    <JellyModeProvider>
                      <OfflineShell />
                    </JellyModeProvider>
                  </AgentKpiManifestProvider>
                </AgentTokenManifestProvider>
              </SettingsProvider>
            </TransferModalsProvider>
            </CopyTourProvider>
            </DepositTourProvider>
          </SubscriptionProvider>
          </OnboardProvider>
        </BrowserRouter>
      </QueryClientProvider>
    </WagmiProvider>
  );
}
