import React, { useCallback, useState } from "react";
import { formatCurrency } from "../../sdk/utils/display";
import type { Bucket } from "../../sdk";
import { getDisplayMarginType } from "../../sdk";
import { NestedConfirmDialog } from "../ui/NestedConfirmDialog";

function shortBucketId(bucketId: string): string {
  return bucketId.length > 8 ? `${bucketId.slice(0, 6)}…` : bucketId;
}

export function bucketCloseConfirmLabel(bucket: Bucket): string {
  const margin = getDisplayMarginType(bucket).toUpperCase();
  return `${margin} · ${shortBucketId(bucket.bucketId)}`;
}

export interface BucketCloseConfirmModalProps {
  isOpen: boolean;
  bucket: Bucket;
  withdrawable: number;
  activeTaskCount: number;
  pendingTaskCount: number;
  onCancel: () => void;
  onConfirm: () => void;
  disabled?: boolean;
}

function BucketCloseConfirmModal({
  isOpen,
  bucket,
  withdrawable,
  activeTaskCount,
  pendingTaskCount,
  onCancel,
  onConfirm,
  disabled = false,
}: BucketCloseConfirmModalProps): JSX.Element | null {
  const confirmLabel = bucketCloseConfirmLabel(bucket);
  const [typed, setTyped] = useState("");

  const handleCancel = useCallback(() => {
    setTyped("");
    onCancel();
  }, [onCancel]);

  const handleConfirm = useCallback(() => {
    if (typed.trim() !== confirmLabel) return;
    setTyped("");
    onConfirm();
  }, [typed, confirmLabel, onConfirm]);

  const matches = typed.trim() === confirmLabel;

  return (
    <NestedConfirmDialog
      isOpen={isOpen}
      title="Close this bucket and withdraw everything?"
      titleId="bucket-close-confirm-title"
      confirmLabel="Close bucket"
      confirmClassName="bucket-close-confirm-btn"
      confirmDisabled={!matches}
      disabled={disabled}
      autoFocusCancel={false}
      onCancel={handleCancel}
      onConfirm={handleConfirm}
    >
      <p className="nested-confirm-body">We will:</p>
      <ul className="nested-confirm-list">
        <li>turn off all agents for this bucket ({activeTaskCount} active)</li>
        <li>reject {pendingTaskCount} pending intent{pendingTaskCount === 1 ? "" : "s"}</li>
        <li>
          send ≈ {formatCurrency(withdrawable + (bucket.usedMargin || 0))} to your
          spot account (free balance now: {formatCurrency(withdrawable)})
        </li>
      </ul>
      <p className="nested-confirm-body">
        This cannot be undone. Type the bucket label to confirm:
      </p>
      <input
        type="text"
        className="nested-confirm-input"
        value={typed}
        onChange={(e) => setTyped(e.target.value)}
        placeholder={confirmLabel}
        aria-label="Type bucket label to confirm close"
        disabled={disabled}
        autoFocus
      />
    </NestedConfirmDialog>
  );
}

export default React.memo(BucketCloseConfirmModal);
