import type { AgentCompareFocus } from "../agentCompareFocus";
import { AGENT_COMPARE_FOCUS_OPTIONS } from "../agentCompareFocus";
import { resolveAgentAvatarSvgUrl } from "../../../utils/agentAvatarSvg";
import {
  buildCompareMatrixSections,
  loadCompareAgents,
  resolveActiveSection,
  resolveCompareMatrixColumnCount,
} from "../../../utils/agentCompareMatrix";
import { buildComparePath } from "../../../utils/agentCompareIds";
import {
  formatShareTimestamp,
  SHARE_CARD_WIDTH_PX,
} from "../../index/share/indexShareData";

export { formatShareTimestamp, SHARE_CARD_WIDTH_PX };
export {
  buildTelegramShareUrl,
  buildTwitterShareUrl,
} from "../../index/share/indexShareData";

export const MAX_COMPARE_SHARE_METRIC_ROWS = 5;

export interface AgentCompareShareAgent {
  id: string;
  name: string;
  ticker: string;
  strategy: string;
  avatarSrc: string;
}

export interface AgentCompareShareMetricRow {
  label: string;
  cells: Array<{
    value: string;
    tone?: "positive" | "negative" | "neutral";
    isBest?: boolean;
    listItems?: string[];
  } | null>;
}

export interface AgentCompareSharePayload {
  compareIds: string[];
  focus: AgentCompareFocus;
  focusLabel: string;
  focusHint: string;
  highlightBest: boolean;
  agents: AgentCompareShareAgent[];
  metricRows: AgentCompareShareMetricRow[];
  timestamp: string;
}

export function buildCompareShareUrl(compareIds: string[]): string {
  const path = buildComparePath(compareIds);
  if (typeof window === "undefined") {
    return path;
  }
  return `${window.location.origin}${path}`;
}

export function buildCompareShareText(payload: AgentCompareSharePayload): string {
  const names = payload.agents.map((agent) => agent.name);
  const agentList =
    names.length <= 1
      ? names[0] ?? "agents"
      : names.length === 2
        ? `${names[0]} vs ${names[1]}`
        : `${names.slice(0, -1).join(", ")} vs ${names[names.length - 1]}`;
  return `Compare ${agentList} on Morpheum — ${payload.focusLabel}`;
}

export interface BuildAgentCompareSharePayloadOptions {
  highlightBest?: boolean;
  timestamp?: string;
}

export function buildAgentCompareSharePayload(
  compareIds: string[],
  compareFocus: AgentCompareFocus,
  options: BuildAgentCompareSharePayloadOptions = {},
): AgentCompareSharePayload {
  const highlightBest = options.highlightBest ?? true;
  const timestamp = options.timestamp ?? formatShareTimestamp();
  const agents = loadCompareAgents(compareIds);
  const columnCount = resolveCompareMatrixColumnCount(compareIds.length);
  const sections = buildCompareMatrixSections(agents, columnCount);
  const activeSection = resolveActiveSection(sections, compareFocus);
  const focusMeta =
    AGENT_COMPARE_FOCUS_OPTIONS.find((option) => option.value === compareFocus) ??
    AGENT_COMPARE_FOCUS_OPTIONS[0]!;

  const metricRows: AgentCompareShareMetricRow[] = (activeSection?.rows ?? [])
    .filter(
      (row) => row.kind !== "dailyPnlCalendar" && row.kind !== "list",
    )
    .slice(0, MAX_COMPARE_SHARE_METRIC_ROWS)
    .map((row) => ({
      label: row.label,
      cells: row.cells.map((cell) =>
        cell
          ? {
              value: cell.value,
              tone: cell.tone,
              isBest: highlightBest ? cell.isBest : undefined,
              listItems: cell.listItems,
            }
          : null,
      ),
    }));

  return {
    compareIds,
    focus: compareFocus,
    focusLabel: focusMeta.label,
    focusHint: focusMeta.hint,
    highlightBest,
    agents: agents.map((agent) => ({
      id: agent.id,
      name: agent.profile.name,
      ticker: agent.profile.ticker,
      strategy: agent.profile.strategy,
      avatarSrc: resolveAgentAvatarSvgUrl(agent.id),
    })),
    metricRows,
    timestamp,
  };
}
