import { type JSX } from "react";
import type {
  IntentBlockingSlot,
  IntentResolution,
  ResolvedAgent,
  ResolvedAsset,
} from "./intentResolution";

export interface IntentAmbiguityPromptProps {
  resolution: IntentResolution;
  onSelectAgent: (agent: ResolvedAgent) => void;
  onSelectAsset: (asset: ResolvedAsset) => void;
}

function promptLabel(slot: IntentBlockingSlot): string {
  if (slot === "agent") return "Which agent should run this intent?";
  if (slot === "asset") return "Which market should this intent target?";
  return "";
}

export function IntentAmbiguityPrompt({
  resolution,
  onSelectAgent,
  onSelectAsset,
}: IntentAmbiguityPromptProps): JSX.Element | null {
  const { blockingSlot, agent, asset } = resolution;
  if (!blockingSlot) return null;

  const candidates =
    blockingSlot === "agent" ? agent.candidates ?? [] : asset.candidates ?? [];

  if (candidates.length === 0) {
    return (
      <div className="intent-ambiguity-prompt" role="status">
        <div className="intent-ambiguity-prompt-label">
          {promptLabel(blockingSlot)}
        </div>
        <p className="intent-ambiguity-prompt-empty">
          {blockingSlot === "agent"
            ? "Type @agent in the composer or pick from suggestions."
            : "Type $TICKER in the composer or name the asset in natural language."}
        </p>
      </div>
    );
  }

  return (
    <div className="intent-ambiguity-prompt" role="status" aria-live="polite">
      <div className="intent-ambiguity-prompt-label">
        {promptLabel(blockingSlot)}
      </div>
      <div className="intent-ambiguity-prompt-options">
        {blockingSlot === "agent"
          ? (candidates as ResolvedAgent[]).map((candidate) => (
              <button
                key={candidate.id}
                type="button"
                className="intent-ambiguity-option"
                onClick={() => onSelectAgent(candidate)}
              >
                {candidate.displayName}
              </button>
            ))
          : (candidates as ResolvedAsset[]).map((candidate) => (
              <button
                key={candidate.marketId}
                type="button"
                className="intent-ambiguity-option"
                onClick={() => onSelectAsset(candidate)}
              >
                {candidate.baseAsset}
                {candidate.symbol ? (
                  <span className="intent-ambiguity-option-meta">
                    {candidate.symbol}
                  </span>
                ) : null}
              </button>
            ))}
      </div>
    </div>
  );
}
