import type { JSX } from "react";
import { getBubbleTipContent } from "../../tutorials/bubble-tip/bubbleTipContent";
import {
  getTradeTooltipInventory,
  isTooltipGroupEnabled,
  LAYOUT_LABELS,
  type LayoutStyle,
  type TooltipGroupId,
  type TooltipGroupPrefs,
} from "./settingsRegistry";

export interface TooltipInventorySettingsProps {
  layout: LayoutStyle;
  tooltipsEnabled: boolean;
  tooltipGroups: TooltipGroupPrefs;
  onTooltipGroupToggle: (groupId: TooltipGroupId, enabled: boolean) => void;
}

function TooltipInventorySettings({
  layout,
  tooltipsEnabled,
  tooltipGroups,
  onTooltipGroupToggle,
}: TooltipInventorySettingsProps): JSX.Element {
  const groups = getTradeTooltipInventory(layout);

  return (
    <div className="tooltip-inventory-settings">
      <p className="settings-chart-overlay-hint tooltip-inventory-settings-layout">
        Hover tooltips for {LAYOUT_LABELS[layout]} layout
      </p>

      {groups.map((group) => {
        const groupId = group.component as TooltipGroupId;
        const groupEnabled = isTooltipGroupEnabled(tooltipGroups, groupId);

        return (
          <div key={group.component} className="tooltip-inventory-component">
            <label className="settings-toggle tooltip-inventory-component-header">
              <input
                type="checkbox"
                checked={groupEnabled}
                disabled={!tooltipsEnabled}
                onChange={(e) => onTooltipGroupToggle(groupId, e.target.checked)}
              />
              <span>{group.component}</span>
            </label>
            {group.note ? (
              <p className="settings-chart-overlay-hint tooltip-inventory-component-note">
                {group.note}
              </p>
            ) : null}
            <ul
              className={`tooltip-inventory-tip-list${groupEnabled && tooltipsEnabled ? "" : " tooltip-inventory-tip-list--muted"}`}
            >
              {group.tipIds.map((tipId) => (
                <li key={tipId} className="tooltip-inventory-tip">
                  {getBubbleTipContent(tipId).label}
                </li>
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

export default TooltipInventorySettings;
