export type DayGroup<T extends { at: string }> = {
  day: string;
  label: string;
  events: T[];
};

function dayKey(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "invalid";
  return date.toISOString().slice(0, 10);
}

function dayLabel(day: string, now = new Date()): string {
  const todayKey = dayKey(now.toISOString());
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayKey = dayKey(yesterday.toISOString());

  if (day === todayKey) return "Today";
  if (day === yesterdayKey) return "Yesterday";

  const parsed = new Date(`${day}T12:00:00`);
  if (Number.isNaN(parsed.getTime())) return day;

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: parsed.getFullYear() !== now.getFullYear() ? "numeric" : undefined,
  }).format(parsed);
}

/** Groups events (newest-first) into day buckets preserving order. */
export function groupEventsByDay<T extends { at: string }>(
  events: T[],
  now = new Date(),
): DayGroup<T>[] {
  const groups: DayGroup<T>[] = [];
  let current: DayGroup<T> | null = null;

  for (const event of events) {
    const day = dayKey(event.at);
    if (!current || current.day !== day) {
      current = { day, label: dayLabel(day, now), events: [] };
      groups.push(current);
    }
    current.events.push(event);
  }

  return groups;
}
