import { useCallback, useRef, useState } from "react";
import {
  FEED_INSERT_DURATION_MS,
  FEED_PUSH_PHASE_MS,
  type FeedEnterState,
} from "./feedAnimation";

export interface UseFeedEnterResult {
  enterState: FeedEnterState | null;
  markEntering: (instanceId: string) => void;
  clearEnter: () => void;
}

export function useFeedEnter(): UseFeedEnterResult {
  const [enterState, setEnterState] = useState<FeedEnterState | null>(null);
  const enterTimersRef = useRef<ReturnType<typeof setTimeout>[]>([]);

  const clearEnterTimers = useCallback(() => {
    enterTimersRef.current.forEach(clearTimeout);
    enterTimersRef.current = [];
  }, []);

  const clearEnter = useCallback(() => {
    clearEnterTimers();
    setEnterState(null);
  }, [clearEnterTimers]);

  const markEntering = useCallback(
    (instanceId: string) => {
      clearEnterTimers();
      setEnterState({ instanceId, phase: "push" });

      const revealTimer = setTimeout(() => {
        setEnterState((prev) =>
          prev?.instanceId === instanceId ? { instanceId, phase: "reveal" } : prev,
        );
      }, FEED_PUSH_PHASE_MS);
      enterTimersRef.current.push(revealTimer);

      const finishTimer = setTimeout(() => {
        setEnterState((prev) =>
          prev?.instanceId === instanceId ? null : prev,
        );
      }, FEED_INSERT_DURATION_MS);
      enterTimersRef.current.push(finishTimer);
    },
    [clearEnterTimers],
  );

  return { enterState, markEntering, clearEnter };
}
