import type { AgentTask } from "../store/types";

/** Maps agentTaskId → agentId for attribution joins. */
export function buildTaskAgentMap(tasks: AgentTask[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const task of tasks) {
    if (task.id && task.agentId) {
      map.set(task.id, task.agentId);
    }
  }
  return map;
}

/** Bucket IDs linked to at least one task for the given agent. */
export function buildAgentBucketIds(
  tasks: AgentTask[],
  filterAgentId: string,
): Set<string> {
  const ids = new Set<string>();
  for (const task of tasks) {
    if (task.agentId !== filterAgentId || !task.bucketId) continue;
    ids.add(String(task.bucketId));
  }
  return ids;
}

/** Bucket IDs linked to tasks for any agent in the fleet selection. */
export function buildFleetBucketIds(
  tasks: AgentTask[],
  filterAgentIds: string[],
): Set<string> {
  if (filterAgentIds.length === 0) return new Set();
  const fleet = new Set(filterAgentIds);
  const ids = new Set<string>();
  for (const task of tasks) {
    if (!task.agentId || !task.bucketId || !fleet.has(task.agentId)) continue;
    ids.add(String(task.bucketId));
  }
  return ids;
}

/** True when agentId passes the fleet filter (empty fleet = all pass). */
export function agentMatchesFleetFilter(
  agentId: string | null | undefined,
  filterAgentIds: string[],
): boolean {
  if (filterAgentIds.length === 0) return true;
  if (!agentId) return false;
  return filterAgentIds.includes(agentId);
}

/**
 * Returns true when a row should be shown under the current agent filter.
 * When filterAgentId is unset, all rows pass. Manual rows (no agentTaskId) are
 * excluded when a filter is active.
 */
export function rowMatchesAgentFilter(
  agentTaskId: string | null | undefined,
  filterAgentId: string | null | undefined,
  taskAgentMap: Map<string, string>,
): boolean {
  if (!filterAgentId) return true;
  if (!agentTaskId) return false;
  return taskAgentMap.get(agentTaskId) === filterAgentId;
}

/**
 * Fleet-aware row filter. Empty filterAgentIds = show all rows.
 * Manual rows excluded when any fleet filter is active.
 */
export function rowMatchesFleetFilter(
  agentTaskId: string | null | undefined,
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
): boolean {
  if (filterAgentIds.length === 0) return true;
  if (!agentTaskId) return false;
  const agentId = taskAgentMap.get(agentTaskId);
  if (!agentId) return false;
  return filterAgentIds.includes(agentId);
}

/** Unified filter: accepts legacy single id or fleet array. */
export function rowMatchesPortfolioFilter(
  agentTaskId: string | null | undefined,
  filterAgentIds: string[],
  taskAgentMap: Map<string, string>,
): boolean {
  return rowMatchesFleetFilter(agentTaskId, filterAgentIds, taskAgentMap);
}
