import { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";

import type { CopyRelation } from "../../offline/mock_data/fleetCopyRelations";
import type { AutonomyPreset } from "../components/tradeagent/autonomyPolicy";
import { autonomyPolicyForPreset } from "../components/tradeagent/autonomyPolicy";
import { createErrorCopyAction } from "../components/ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
} from "../components/ui/toastTask";
import { useOnboard } from "../hooks/useOnboard";
import { useBucketCollections } from "../hooks/useBucketCollections";
import { useFiClient } from "../hooks/useFiClient";
import { formatCurrency } from "../sdk/utils/display";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { getDisplayMarginType, isDisplayableBucket, type Bucket } from "../sdk";
import { scheduleCopyMirrorReplay } from "../services/copyMirrorOrchestrator";
import { useBucketPolicyStore } from "../store/bucketPolicyStore";
import { useFleetCopyStore } from "../store/fleetCopyStore";
import { COPY_TOUR_TIMING } from "../tutorials/copy-tour/constants";
import { useOptionalCopyTour } from "../tutorials/copy-tour";
import { executeBucketCreateAndFund } from "../utils/executeBucketCreateAndFund";
import { executeOfflineCopySetup } from "../utils/executeOfflineCopySetup";
import type { CopyAgentConfirmParams } from "../components/agent/copyAgentModalValidation";

const COPY_COLLATERAL_ASSET = "USDC";

export function filterCrossDisplayableBuckets(collections: Bucket[]): Bucket[] {
  return collections.filter(
    (bucket) =>
      isDisplayableBucket(bucket) &&
      getDisplayMarginType(bucket).toLowerCase() === "cross",
  );
}

export function useCopyAgentConfirm(baseURL: string): {
  crossBuckets: Bucket[];
  spotWalletBalance: number;
  isReady: boolean;
  isPending: boolean;
  confirmCopy: (params: CopyAgentConfirmParams) => Promise<CopyRelation | null>;
} {
  const offline = isOfflineMode(baseURL);
  const { walletAddress, mnemonic } = useOnboard(baseURL);
  const { client: exchangeClient, isReady: exchangeReady } = useFiClient({
    baseURL,
    mnemonic,
  });
  const { collections, spotWalletBalance, refreshBucketBalance } =
    useBucketCollections({
      baseURL,
      walletAddress: walletAddress ?? "",
      refreshInterval: 5000,
    });
  const addCopyRelation = useFleetCopyStore((state) => state.addCopyRelation);
  const setPolicy = useBucketPolicyStore((state) => state.setPolicy);
  const copyTour = useOptionalCopyTour();
  const [isPending, setIsPending] = useState(false);

  const crossBuckets = useMemo(
    () => filterCrossDisplayableBuckets(collections),
    [collections],
  );

  const confirmCopy = useCallback(
    async (params: CopyAgentConfirmParams): Promise<CopyRelation | null> => {
      const copierWallet = walletAddress?.trim();
      if (!copierWallet) {
        toast.error("Connect wallet first", {
          description: "Connect your wallet before copying an agent.",
        });
        return null;
      }
      if (!offline) {
        if (!mnemonic) {
          toast.error("Mnemonic required", {
            description: "Mnemonic is required to set up copy trading.",
            action: createErrorCopyAction("Mnemonic required"),
          });
          return null;
        }
        if (!exchangeClient || !exchangeReady) {
          toast.error("Exchange client not ready", {
            description: "Please wait for the exchange client to initialize.",
            action: createErrorCopyAction("Exchange client not ready"),
          });
          return null;
        }
      }

      setIsPending(true);
      const loadingId = toastLoading("Setting up copy…", {
        description: `Copy ${params.profileName}`,
      });

      try {
        let bucketId: string;
        let bucketMode: "new" | "existing";
        let startingMargin: number | undefined;

        if (offline) {
          const tourMode = Boolean(copyTour?.runTour);
          const setup = await executeOfflineCopySetup({
            wallet: copierWallet,
            destination: params.destination,
            targetCatalogAgentId: params.targetCatalogAgentId,
            profileName: params.profileName,
            perpBaseAsset: params.perpBaseAsset,
            copySizePct: params.copySizePct,
            autonomyPreset: params.autonomyPreset,
          }, tourMode ? { setupDelayMs: COPY_TOUR_TIMING.setupDelayMs } : undefined);
          bucketId = setup.bucketId;
          bucketMode = setup.bucketMode;
          startingMargin = setup.startingMargin;
        } else if (params.destination.mode === "existing") {
          bucketId = params.destination.bucketId;
          bucketMode = "existing";
        } else {
          bucketId = await executeBucketCreateAndFund({
            exchangeClient: exchangeClient!,
            marginType: "cross",
            collateralAsset: COPY_COLLATERAL_ASSET,
            amount: params.destination.startingMargin,
            fundFrom: "spot-wallet",
          });
          bucketMode = "new";
          startingMargin = params.destination.startingMargin;
        }

        setPolicy(bucketId, autonomyPolicyForPreset(params.autonomyPreset as AutonomyPreset));

        const relation = addCopyRelation(copierWallet, params.targetCatalogAgentId, {
          bucketId,
          bucketMode,
          startingMargin,
          copySizePct: params.copySizePct,
          autonomyPreset: params.autonomyPreset,
        });

        if (offline) {
          scheduleCopyMirrorReplay(
            relation,
            params.profileName,
            copyTour?.runTour
              ? {
                  intervalMs: COPY_TOUR_TIMING.replayIntervalMs,
                  maxSteps: COPY_TOUR_TIMING.replayMaxSteps,
                }
              : undefined,
          );
          if (copyTour?.runTour) {
            copyTour.notifyConfirmComplete(relation.copySettings.bucketId);
          }
        }

        toastCompleteSuccess(loadingId, "Copy started", {
          description: `${params.profileName} · ${params.copySizePct}% mirror · ${formatCurrency(
            bucketMode === "new" ? (startingMargin ?? 0) : 0,
          )} in bucket ${bucketId.slice(0, 8)}…`,
        });

        if (!offline) {
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
        refreshBucketBalance();
        return relation;
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : "Failed to set up copy";
        toastCompleteError(loadingId, "Copy setup failed", {
          description: errorMessage,
          action: createErrorCopyAction(errorMessage),
        });
        return null;
      } finally {
        setIsPending(false);
      }
    },
    [
      walletAddress,
      mnemonic,
      exchangeClient,
      exchangeReady,
      offline,
      addCopyRelation,
      setPolicy,
      copyTour,
      refreshBucketBalance,
    ],
  );

  return {
    crossBuckets,
    spotWalletBalance,
    isReady: offline ? Boolean(walletAddress?.trim()) : Boolean(walletAddress && exchangeReady),
    isPending,
    confirmCopy,
  };
}
