import { useLayoutEffect, useRef, useState, type RefObject } from "react";

export function computeShowBottomFade(
  el: HTMLElement,
  overflowCount: number,
): boolean {
  if (overflowCount > 0) return true;
  const hasOverflow = el.scrollHeight > el.clientHeight + 1;
  if (!hasOverflow) return false;
  const scrollBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
  return scrollBottom > 4;
}

export function useDeckBottomFade(
  cardsViewportRef: RefObject<HTMLDivElement>,
  overflowCount: number,
  contentKey: string | number,
): boolean {
  const [showBottomFade, setShowBottomFade] = useState(false);
  const overflowCountRef = useRef(overflowCount);

  overflowCountRef.current = overflowCount;

  useLayoutEffect(() => {
    const el = cardsViewportRef.current;
    if (!el) return;

    const measure = () => {
      setShowBottomFade(
        computeShowBottomFade(el, overflowCountRef.current),
      );
    };

    measure();

    const observer = new ResizeObserver(measure);
    observer.observe(el);
    el.addEventListener("scroll", measure, { passive: true });

    return () => {
      observer.disconnect();
      el.removeEventListener("scroll", measure);
    };
  }, [cardsViewportRef, overflowCount, contentKey]);

  return showBottomFade;
}
