import React from "react";
import type { TradingMode } from "../../configs/tradeLayoutMode";

export interface RawProDataToggleProps {
  active: boolean;
  onChange: (active: boolean) => void;
  tradingMode: TradingMode;
}

function RawProDataToggle({
  active,
  onChange,
  tradingMode,
}: RawProDataToggleProps): JSX.Element {
  const defaultLabel = tradingMode === "humanInLoop" ? "Safety" : "Agent";

  return (
    <div
      className="raw-pro-data-toggle"
      role="tablist"
      aria-label="Tab data mode"
    >
      <button
        type="button"
        role="tab"
        aria-selected={!active}
        className={`raw-pro-data-toggle-segment${
          !active ? " is-active" : ""
        }`}
        onClick={() => onChange(false)}
      >
        {defaultLabel}
      </button>
      <button
        type="button"
        role="tab"
        aria-selected={active}
        className={`raw-pro-data-toggle-segment${active ? " is-active" : ""}`}
        onClick={() => onChange(true)}
      >
        Raw Pro
      </button>
    </div>
  );
}

export default React.memo(RawProDataToggle);
