import { INTENT_TEMPLATES, resolveDisplaySymbol } from "../tradeops/intentExamples";
import { extractAgentMentions, extractTickerMentions } from "./intentMentions";
import type { Market, TradingAgent } from "../../store/types";

export type SlotConfidence = "resolved" | "defaulted" | "ambiguous" | "missing";

export type ResolutionSource = "mention" | "nl" | "context";

export interface ResolvedAgent {
  id: string;
  displayName: string;
}

export interface ResolvedAsset {
  marketId: string;
  baseAsset: string;
  symbol: string;
}

export interface ResolvedSlot<T> {
  confidence: SlotConfidence;
  value: T | null;
  label: string;
  source: ResolutionSource;
  candidates?: T[];
}

export type IntentDeployState = "deploy" | "review" | "resolve";

export type IntentBlockingSlot = "agent" | "asset" | null;

export interface IntentResolution {
  agent: ResolvedSlot<ResolvedAgent>;
  asset: ResolvedSlot<ResolvedAsset>;
  deployState: IntentDeployState;
  blockingSlot: IntentBlockingSlot;
  assetDiffersFromChart: boolean;
}

export interface IntentResolutionContext {
  defaultAgentId: string | null;
  defaultMarketId: string | null;
  chartMarketId: string | null;
}

export interface ResolveIntentInput {
  text: string;
  agents: TradingAgent[];
  markets: Market[];
  context: IntentResolutionContext;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function wordBoundaryMatch(text: string, term: string): boolean {
  const pattern = new RegExp(
    `(?:^|[\\s,.;:!?'"([{])${escapeRegExp(term.toLowerCase())}(?:$|[\\s,.;:!?'")\\]}])`,
    "i",
  );
  return pattern.test(text.toLowerCase());
}

function getMarketId(market: Market): string {
  return market.index ?? market.marketIndex ?? "";
}

function getMarketSymbol(market: Market): string {
  return market.moniker || market.symbol || market.baseAsset || "";
}

function findMarketsByBaseAsset(
  markets: Market[],
  baseAsset: string,
): Market[] {
  const upper = baseAsset.toUpperCase();
  return markets.filter(
    (m) =>
      m.baseAsset?.toUpperCase() === upper ||
      m.moniker?.toUpperCase() === upper ||
      m.symbol?.split(/[-/]/)[0]?.toUpperCase() === upper,
  );
}

function resolveAgentByMention(
  agents: TradingAgent[],
  mention: string,
): TradingAgent[] {
  const q = mention.toLowerCase();
  return agents.filter(
    (a) =>
      a.displayName.toLowerCase() === q ||
      a.displayName.toLowerCase().startsWith(q) ||
      a.id.toLowerCase().startsWith(q),
  );
}

function resolveAgentsByNl(
  agents: TradingAgent[],
  text: string,
): TradingAgent[] {
  const normalized = text.toLowerCase();
  const matches = new Set<TradingAgent>();

  for (const agent of agents) {
    const name = agent.displayName.toLowerCase();
    if (wordBoundaryMatch(normalized, name)) {
      matches.add(agent);
    }
    const spaced = name.replace(/_/g, " ");
    if (spaced !== name && wordBoundaryMatch(normalized, spaced)) {
      matches.add(agent);
    }
  }

  for (const template of INTENT_TEMPLATES) {
    const actor = template.actorType.toLowerCase();
    if (wordBoundaryMatch(normalized, actor)) {
      const actorTokens = actor.split(/\s+/).filter(Boolean);
      const primary = actorTokens[0] ?? actor;
      for (const agent of agents) {
        if (agent.displayName.toLowerCase().includes(primary)) {
          matches.add(agent);
        }
      }
    }
  }

  if (normalized.includes("momentum agent") || normalized.includes("momentum")) {
    for (const agent of agents) {
      if (agent.displayName.toLowerCase().includes("momentum")) {
        matches.add(agent);
      }
    }
  }

  return [...matches];
}

function resolveAssetByMention(
  markets: Market[],
  mention: string,
): Market[] {
  return findMarketsByBaseAsset(markets, mention);
}

const ASSET_NL_ALIASES: Record<string, string[]> = {
  BTC: ["bitcoin"],
  ETH: ["ethereum", "ether"],
  SOL: ["solana"],
  XAU: ["gold"],
  XAG: ["silver"],
};

function resolveAssetsByNl(
  markets: Market[],
  text: string,
): Market[] {
  const normalized = text.toLowerCase();
  const matches = new Set<Market>();

  for (const market of markets) {
    const base = market.baseAsset?.toUpperCase() ?? "";
    const display = resolveDisplaySymbol(base).toLowerCase();
    const aliases = [
      base.toLowerCase(),
      display,
      ...(ASSET_NL_ALIASES[base] ?? []),
    ];

    for (const alias of aliases) {
      if (alias && wordBoundaryMatch(normalized, alias)) {
        matches.add(market);
      }
    }
  }

  return [...matches];
}

function toAgentSlot(
  matches: TradingAgent[],
  source: ResolutionSource,
): ResolvedSlot<ResolvedAgent> {
  if (matches.length === 1) {
    const agent = matches[0]!;
    return {
      confidence: "resolved",
      value: { id: agent.id, displayName: agent.displayName },
      label: agent.displayName,
      source,
    };
  }
  if (matches.length > 1) {
    const candidates = matches.map((a) => ({
      id: a.id,
      displayName: a.displayName,
    }));
    return {
      confidence: "ambiguous",
      value: null,
      label: "Multiple agents",
      source,
      candidates,
    };
  }
  return {
    confidence: "missing",
    value: null,
    label: "—",
    source,
  };
}

function toAssetSlot(
  matches: Market[],
  source: ResolutionSource,
): ResolvedSlot<ResolvedAsset> {
  if (matches.length === 1) {
    const market = matches[0]!;
    const baseAsset = market.baseAsset?.toUpperCase() ?? "";
    return {
      confidence: "resolved",
      value: {
        marketId: getMarketId(market),
        baseAsset,
        symbol: getMarketSymbol(market),
      },
      label: baseAsset,
      source,
    };
  }
  if (matches.length > 1) {
    const candidates = matches.map((m) => ({
      marketId: getMarketId(m),
      baseAsset: m.baseAsset?.toUpperCase() ?? "",
      symbol: getMarketSymbol(m),
    }));
    return {
      confidence: "ambiguous",
      value: null,
      label: "Multiple markets",
      source,
      candidates,
    };
  }
  return {
    confidence: "missing",
    value: null,
    label: "—",
    source,
  };
}

function applyContextDefaultAgent(
  slot: ResolvedSlot<ResolvedAgent>,
  agents: TradingAgent[],
  defaultAgentId: string | null,
): ResolvedSlot<ResolvedAgent> {
  if (slot.confidence === "resolved" || slot.confidence === "ambiguous") {
    return slot;
  }
  if (!defaultAgentId) return slot;
  const agent = agents.find((a) => a.id === defaultAgentId);
  if (!agent) return slot;
  return {
    confidence: "defaulted",
    value: { id: agent.id, displayName: agent.displayName },
    label: agent.displayName,
    source: "context",
  };
}

function applyContextDefaultAsset(
  slot: ResolvedSlot<ResolvedAsset>,
  markets: Market[],
  defaultMarketId: string | null,
): ResolvedSlot<ResolvedAsset> {
  if (slot.confidence === "resolved" || slot.confidence === "ambiguous") {
    return slot;
  }
  if (!defaultMarketId) return slot;
  const market = markets.find((m) => getMarketId(m) === defaultMarketId);
  if (!market) return slot;
  const baseAsset = market.baseAsset?.toUpperCase() ?? "";
  return {
    confidence: "defaulted",
    value: {
      marketId: getMarketId(market),
      baseAsset,
      symbol: getMarketSymbol(market),
    },
    label: baseAsset,
    source: "context",
  };
}

export function computeDeployState(
  agent: ResolvedSlot<ResolvedAgent>,
  asset: ResolvedSlot<ResolvedAsset>,
): { deployState: IntentDeployState; blockingSlot: IntentBlockingSlot } {
  const agentBlocks =
    agent.confidence === "ambiguous" || agent.confidence === "missing";
  const assetBlocks =
    asset.confidence === "ambiguous" || asset.confidence === "missing";

  if (agentBlocks) {
    return { deployState: "resolve", blockingSlot: "agent" };
  }
  if (assetBlocks) {
    return { deployState: "resolve", blockingSlot: "asset" };
  }

  const hasDefaulted =
    agent.confidence === "defaulted" || asset.confidence === "defaulted";
  if (hasDefaulted) {
    return { deployState: "review", blockingSlot: null };
  }

  return { deployState: "deploy", blockingSlot: null };
}

export function resolveIntent(input: ResolveIntentInput): IntentResolution {
  const { text, agents, markets, context } = input;
  const trimmed = text.trim();

  const agentMentions = extractAgentMentions(trimmed);
  const tickerMentions = extractTickerMentions(trimmed);

  let agentSlot: ResolvedSlot<ResolvedAgent>;
  if (agentMentions.length > 0) {
    const lastMention = agentMentions[agentMentions.length - 1]!;
    const matches = resolveAgentByMention(agents, lastMention);
    agentSlot = toAgentSlot(matches, "mention");
    if (agentMentions.length > 1 && matches.length === 0) {
      agentSlot = {
        confidence: "ambiguous",
        value: null,
        label: "Unknown agent",
        source: "mention",
        candidates: [],
      };
    }
  } else {
    const nlMatches = resolveAgentsByNl(agents, trimmed);
    agentSlot = toAgentSlot(nlMatches, "nl");
  }

  let assetSlot: ResolvedSlot<ResolvedAsset>;
  if (tickerMentions.length > 0) {
    const lastMention = tickerMentions[tickerMentions.length - 1]!;
    const matches = resolveAssetByMention(markets, lastMention);
    if (matches.length === 0) {
      assetSlot = {
        confidence: "ambiguous",
        value: null,
        label: lastMention.toUpperCase(),
        source: "mention",
        candidates: [],
      };
    } else {
      assetSlot = toAssetSlot(matches, "mention");
    }
  } else {
    const nlMatches = resolveAssetsByNl(markets, trimmed);
    assetSlot = toAssetSlot(nlMatches, "nl");
  }

  agentSlot = applyContextDefaultAgent(
    agentSlot,
    agents,
    context.defaultAgentId,
  );
  assetSlot = applyContextDefaultAsset(
    assetSlot,
    markets,
    context.defaultMarketId,
  );

  const { deployState, blockingSlot } = computeDeployState(agentSlot, assetSlot);

  const assetDiffersFromChart =
    assetSlot.value != null &&
    context.chartMarketId != null &&
    assetSlot.value.marketId !== context.chartMarketId;

  return {
    agent: agentSlot,
    asset: assetSlot,
    deployState,
    blockingSlot,
    assetDiffersFromChart,
  };
}

export function applyAgentToResolution(
  resolution: IntentResolution,
  agent: ResolvedAgent,
): IntentResolution {
  const next: IntentResolution = {
    ...resolution,
    agent: {
      confidence: "resolved",
      value: agent,
      label: agent.displayName,
      source: "mention",
    },
  };
  const { deployState, blockingSlot } = computeDeployState(
    next.agent,
    next.asset,
  );
  return { ...next, deployState, blockingSlot };
}

export function applyAssetToResolution(
  resolution: IntentResolution,
  asset: ResolvedAsset,
  chartMarketId: string | null,
): IntentResolution {
  const next: IntentResolution = {
    ...resolution,
    asset: {
      confidence: "resolved",
      value: asset,
      label: asset.baseAsset,
      source: "mention",
    },
    assetDiffersFromChart:
      chartMarketId != null && asset.marketId !== chartMarketId,
  };
  const { deployState, blockingSlot } = computeDeployState(
    next.agent,
    next.asset,
  );
  return { ...next, deployState, blockingSlot };
}

export function getDeployButtonLabel(deployState: IntentDeployState): string {
  switch (deployState) {
    case "deploy":
      return "Deploy to Autonomous Agent";
    case "review":
      return "Review & Deploy";
    case "resolve":
      return "Resolve to deploy";
    default:
      return "Deploy to Autonomous Agent";
  }
}

export function canDeploy(resolution: IntentResolution | null): boolean {
  return resolution != null && resolution.deployState !== "resolve";
}

export function getResolutionSummary(resolution: IntentResolution): string {
  return `Agent: ${resolution.agent.label} · Asset: ${resolution.asset.label}`;
}
