import React from "react";
import {
  formatDeployerLabel,
  formatLargeNumber,
  formatPriceFlexible,
} from "../../sdk/utils/display";
import { getAssetIcon } from "./assetIcon";
import type { TickerSelectionRow as RowData } from "./types";

interface TickerSelectionRowMobileProps {
  row: RowData;
  isSelected: boolean;
  onSelect: (marketId: string) => void;
  onFavoriteToggle: (marketId: string) => void;
}

export function TickerSelectionRowMobile({
  row,
  isSelected,
  onSelect,
  onFavoriteToggle,
}: TickerSelectionRowMobileProps): JSX.Element {
  const changePositive = row.change24h >= 0;
  const isSoon = row.comingSoon || !row.isSelectable;
  const icon = getAssetIcon(row.symbol, row.displayName);
  const hasTags = Boolean(row.deployer || row.isBeta || isSoon || row.leverage);

  return (
    <div
      className={`ticker-selection-row ticker-selection-row--mobile ${isSelected ? "selected" : ""} ${isSoon ? "ticker-selection-row--soon" : ""}`}
      role={isSoon ? undefined : "button"}
      tabIndex={isSoon ? undefined : 0}
      onClick={isSoon ? undefined : () => onSelect(row.marketId)}
      onKeyDown={
        isSoon
          ? undefined
          : (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onSelect(row.marketId);
              }
            }
      }
    >
      <div className="ticker-selection-cell ticker-selection-cell-asset ticker-selection-cell-asset--mobile">
        <div className="ticker-selection-asset-primary">
          {!isSoon ? (
            <button
              type="button"
              className={`ticker-selection-star ${row.isFavorite ? "active" : ""}`}
              aria-label={row.isFavorite ? "Remove favorite" : "Add favorite"}
              onClick={(e) => {
                e.stopPropagation();
                onFavoriteToggle(row.marketId);
              }}
            >
              ★
            </button>
          ) : (
            <span className="ticker-selection-star-spacer" aria-hidden />
          )}
          <span className="ticker-selection-asset-icon">{icon}</span>
          <span className="ticker-selection-asset-names">
            {row.category === "agent" ? (
              <>
                <span className="ticker-selection-asset-display">{row.displayName}</span>
                <span className="ticker-selection-asset-symbol">{row.tickerLabel}</span>
              </>
            ) : (
              <span className="ticker-selection-asset-symbol">
                {row.tickerLabel || row.symbol}
              </span>
            )}
          </span>
        </div>
        {hasTags ? (
          <div className="ticker-selection-asset-tags">
            <span className="ticker-selection-leverage-pill ticker-selection-leverage-pill--mobile">
              {row.leverage}x
            </span>
            {row.deployer ? (
              <span className="ticker-selection-deployer-pill" title={row.deployer}>
                {formatDeployerLabel(row.deployer)}
              </span>
            ) : null}
            {row.isBeta ? (
              <span className="ticker-selection-beta-pill">Beta</span>
            ) : null}
            {isSoon ? (
              <span className="ticker-selection-soon-pill">soon</span>
            ) : null}
          </div>
        ) : null}
      </div>
      <div className="ticker-selection-cell ticker-selection-cell-num">
        <div className="ticker-selection-price-stack">
          <span className="ticker-selection-price-value">
            {isSoon ? "--" : formatPriceFlexible(row.price)}
          </span>
          {!isSoon ? (
            <span
              className={`ticker-selection-change-inline ${
                changePositive ? "positive" : "negative"
              }`}
            >
              {changePositive ? "" : "-"}
              {Math.abs(row.change24h).toFixed(2)}%
            </span>
          ) : null}
        </div>
      </div>
      <div className="ticker-selection-cell ticker-selection-cell-num">
        {isSoon ? "--" : `$${formatLargeNumber(row.volume24h)}`}
      </div>
      <div className="ticker-selection-cell ticker-selection-cell-num">
        {isSoon ? "--" : `$${formatLargeNumber(row.openInterest)}`}
      </div>
    </div>
  );
}
