export function getAgentHeroFocusCatalogEntry(
  focus: AgentHeroFocus,
): AgentHeroFocusCatalogEntry {
  return (
    AGENT_HERO_FOCUS_CATALOG.find((entry) => entry.value === focus) ??
    AGENT_HERO_FOCUS_CATALOG[0]
  );
}

function catalogSearchText(entry: AgentHeroFocusCatalogEntry): string {
  return [
    entry.value,
    entry.label,
    entry.intent,
    entry.primarySignal,
    entry.description,
    entry.defaultTabLabel,
    entry.eyebrowExample,
    ...entry.metricLabels,
  ]
    .join(" ")
    .toLowerCase();
}

export function filterAgentHeroFocusCatalog(
  query: string,
): AgentHeroFocusCatalogEntry[] {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return [...AGENT_HERO_FOCUS_CATALOG];
  }

  return AGENT_HERO_FOCUS_CATALOG.filter((entry) =>
    catalogSearchText(entry).includes(normalized),
  );
}

/** Ensures catalog order matches VALID_AGENT_HERO_FOCUSES at module load. */
export function assertCatalogOrder(): void {
  for (let index = 0; index < VALID_AGENT_HERO_FOCUSES.length; index += 1) {
    const expected = VALID_AGENT_HERO_FOCUSES[index];
    const actual = AGENT_HERO_FOCUS_CATALOG[index]?.value;
    if (expected !== actual) {
      throw new Error(
        `AGENT_HERO_FOCUS_CATALOG order mismatch at index ${index}: expected ${expected}, got ${actual}`,
      );
    }
  }
}

assertCatalogOrder();
