import { useCallback, useEffect, useRef, useState } from "react";
import { toBlob, toPng } from "html-to-image";
import { toast } from "sonner";

import {
  buildShareText,
  buildShareUrl,
  buildTelegramShareUrl,
  buildTwitterShareUrl,
  type IndexSharePayload,
} from "./indexShareData";

export interface UseIndexShareActionsResult {
  cardRef: React.RefObject<HTMLDivElement>;
  isCardReady: boolean;
  shareUrl: string;
  shareText: string;
  onCopyImage: () => Promise<void>;
  onDownloadImage: () => Promise<void>;
  onCopyLink: () => Promise<void>;
  onShareX: () => void;
  onShareTelegram: () => void;
}

export function useIndexShareActions(
  isOpen: boolean,
  payload: IndexSharePayload,
): UseIndexShareActionsResult {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isCardReady, setIsCardReady] = useState(false);

  const shareUrl = buildShareUrl(payload.profile.ticker);
  const shareText = buildShareText(payload.profile, payload.performanceMetrics);

  useEffect(() => {
    if (!isOpen) {
      setIsCardReady(false);
      return;
    }

    let cancelled = false;
    const frameId = window.requestAnimationFrame(() => {
      window.setTimeout(() => {
        if (!cancelled) setIsCardReady(true);
      }, 120);
    });

    return () => {
      cancelled = true;
      window.cancelAnimationFrame(frameId);
    };
  }, [isOpen, payload.profile.ticker, payload.modeLabel]);

  const captureOptions = {
    pixelRatio: 2,
    cacheBust: true,
    backgroundColor: "#05070d",
  };

  const onCopyImage = useCallback(async () => {
    if (!cardRef.current) return;
    try {
      const blob = await toBlob(cardRef.current, captureOptions);
      if (!blob) throw new Error("Failed to capture image");
      await navigator.clipboard.write([
        new ClipboardItem({ "image/png": blob }),
      ]);
      toast.success("Image copied to clipboard");
    } catch {
      toast.error("Failed to copy image");
    }
  }, []);

  const onDownloadImage = useCallback(async () => {
    if (!cardRef.current) return;
    try {
      const dataUrl = await toPng(cardRef.current, captureOptions);
      const link = document.createElement("a");
      link.download = `${payload.profile.ticker}-share.png`;
      link.href = dataUrl;
      link.click();
      toast.success("Image downloaded");
    } catch {
      toast.error("Failed to download image");
    }
  }, [payload.profile.ticker]);

  const onCopyLink = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      toast.success("Link copied to clipboard");
    } catch {
      toast.error("Failed to copy link");
    }
  }, [shareUrl]);

  const onShareX = useCallback(() => {
    window.open(buildTwitterShareUrl(shareText, shareUrl), "_blank", "noopener,noreferrer");
  }, [shareText, shareUrl]);

  const onShareTelegram = useCallback(() => {
    window.open(
      buildTelegramShareUrl(shareText, shareUrl),
      "_blank",
      "noopener,noreferrer",
    );
  }, [shareText, shareUrl]);

  return {
    cardRef,
    isCardReady,
    shareUrl,
    shareText,
    onCopyImage,
    onDownloadImage,
    onCopyLink,
    onShareX,
    onShareTelegram,
  };
}
