import React, { createContext, useContext, type ReactNode } from "react";

export interface WalletConnectHostContextValue {
  requestConnect: () => void;
}

const WalletConnectHostContext = createContext<
  WalletConnectHostContextValue | undefined
>(undefined);

export interface WalletConnectHostProviderProps {
  value: WalletConnectHostContextValue;
  children: ReactNode;
}

export function WalletConnectHostProvider({
  value,
  children,
}: WalletConnectHostProviderProps): JSX.Element {
  return (
    <WalletConnectHostContext.Provider value={value}>
      {children}
    </WalletConnectHostContext.Provider>
  );
}

export function useWalletConnectRequest():
  | WalletConnectHostContextValue["requestConnect"]
  | undefined {
  return useContext(WalletConnectHostContext)?.requestConnect;
}
