import React from "react";

import type { CopyAutonomyPreset } from "../../../offline/mock_data/fleetCopyRelations";
import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import { formatCurrency } from "../../sdk/utils/display";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { AnimatedCollapse } from "../ui/AnimatedCollapse";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { PresetCardGrid } from "../ui/PresetCardGrid";
import type { PresetCardOption } from "../ui/PresetCardGrid";
import { AUTONOMY_PRESET_TONE } from "../tradeagent/autonomyPolicy";
import {
  buildCopyAgentLeaderChips,
  buildCopyAgentRiskPreview,
  formatCopyAgentAutonomySummary,
  type CopyAgentRiskPreview,
} from "./copyAgentRiskPreview";

function shortWallet(address: string): string {
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

export function CopyAgentLeaderHeader({
  profile,
  fleet,
  onClose,
  closeDisabled = false,
}: {
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  onClose: () => void;
  closeDisabled?: boolean;
}): JSX.Element {
  const avatarSrc = resolveAgentAvatarSvgUrl(profile.id);
  const chips = buildCopyAgentLeaderChips(profile, fleet);

  return (
    <div className="agent-copy-modal-header">
      <div className="agent-copy-modal-header-content">
        <div className="agent-copy-modal-header-identity">
          <span className="copied-agents-avatar copied-agents-avatar--modal" aria-hidden>
            {avatarSrc ? (
              <span
                className="copied-agents-avatar-image"
                style={{
                  maskImage: `url(${avatarSrc})`,
                  WebkitMaskImage: `url(${avatarSrc})`,
                }}
              />
            ) : null}
          </span>
          <div className="agent-copy-modal-header-text">
            <h3 className="terminal-panel-title">Copy {profile.name}</h3>
            <span className="copied-agent-status-ticker">{profile.ticker}</span>
          </div>
        </div>
        <div className="agent-copy-leader-chips" aria-label="Leader stats">
          {chips.map((chip) => (
            <span
              key={chip.label}
              className={`agent-copy-leader-chip${
                chip.tone === "positive"
                  ? " agent-copy-leader-chip--positive"
                  : chip.tone === "negative"
                    ? " agent-copy-leader-chip--negative"
                    : ""
              }`}
            >
              {chip.label === "30d PnL" ? chip.value : `${chip.label} ${chip.value}`}
            </span>
          ))}
        </div>
      </div>
      <button
        type="button"
        className="agent-copy-modal-close"
        onClick={onClose}
        disabled={closeDisabled}
        aria-label="Close"
      >
        ×
      </button>
    </div>
  );
}

export function CopyAgentSummaryRail({
  copySizePct,
  autonomyPreset,
  preview,
  fleet,
  compact = false,
}: {
  copySizePct: number;
  autonomyPreset: CopyAutonomyPreset;
  preview: CopyAgentRiskPreview;
  fleet: FleetAgentRecord;
  compact?: boolean;
}): JSX.Element {
  const autonomy = formatCopyAgentAutonomySummary(autonomyPreset);

  return (
    <aside
      className={`agent-copy-summary-rail${compact ? " agent-copy-summary-rail--compact" : ""}`}
      aria-label="Summary and risk"
    >
      <h4 className="agent-copy-summary-rail-title">Summary &amp; risk</h4>
      <div className="agent-copy-summary-mirror">
        <span className="agent-copy-summary-mirror-label">You will mirror at</span>
        <strong className="agent-copy-summary-mirror-pct">{copySizePct}%</strong>
        <span className="agent-copy-summary-mirror-sub">of each leader trade</span>
      </div>
      <dl className="agent-copy-summary-metrics">
        <div className="agent-copy-summary-metric">
          <dt>Capital at risk</dt>
          <dd>{formatCurrency(preview.capitalAtRisk)}</dd>
        </div>
        <div className="agent-copy-summary-metric">
          <dt>Est. per-trade</dt>
          <dd>~{formatCurrency(preview.estPerTrade)}</dd>
        </div>
        <div className="agent-copy-summary-metric">
          <dt>Max loss (this bucket)</dt>
          <dd className="agent-copy-summary-metric--negative">
            {formatCurrency(preview.maxLoss)}
          </dd>
        </div>
        <div className="agent-copy-summary-metric">
          <dt>Est. liquidation</dt>
          <dd>~{preview.estLiquidationMovePct}% move</dd>
        </div>
      </dl>
      <div className={`agent-copy-summary-autonomy ${autonomy.toneClass}`}>
        <strong>{autonomy.label}</strong>
        <span>{autonomy.description}</span>
      </div>
      <div className="agent-copy-summary-costs">
        <h5>Costs</h5>
        <dl className="agent-copy-summary-metrics">
          <div className="agent-copy-summary-metric">
            <dt>Performance fee</dt>
            <dd>{preview.costs.performanceFeePct}%</dd>
          </div>
          <div className="agent-copy-summary-metric">
            <dt>Est. spread/slip</dt>
            <dd>~{preview.costs.estSpreadPct}%</dd>
          </div>
          <div className="agent-copy-summary-metric">
            <dt>Funding</dt>
            <dd>{preview.costs.fundingLabel}</dd>
          </div>
        </dl>
      </div>
      {!compact ? (
        <p className="agent-copy-summary-wallet">
          Leader wallet{" "}
          <code title={fleet.agentWallet}>{shortWallet(fleet.agentWallet)}</code>
          <span className="agent-copy-summary-wallet-note">
            (disclosed for transparency only)
          </span>
        </p>
      ) : null}
    </aside>
  );
}

export function CopyAgentMiniSummary({
  copySizePct,
  capitalAtRisk,
  autonomyPreset,
  expanded,
  onToggleExpand,
}: {
  copySizePct: number;
  capitalAtRisk: number;
  autonomyPreset: CopyAutonomyPreset;
  expanded: boolean;
  onToggleExpand: () => void;
}): JSX.Element {
  const autonomy = formatCopyAgentAutonomySummary(autonomyPreset);

  return (
    <div className="agent-copy-mini-summary">
      <span className="agent-copy-mini-summary-text">
        {copySizePct}% · {formatCurrency(capitalAtRisk)} at risk · {autonomy.label}
      </span>
      <button
        type="button"
        className="agent-copy-mini-summary-expand"
        onClick={onToggleExpand}
        aria-expanded={expanded}
        aria-label={expanded ? "Collapse risk summary" : "Expand risk summary"}
      >
        <ExpandCollapseIcon expanded={expanded} size={14} />
      </button>
    </div>
  );
}

export function CopyAgentMdSummaryCard({
  open,
  onToggle,
  copySizePct,
  capitalAtRisk,
  autonomyPreset,
  children,
}: {
  open: boolean;
  onToggle: () => void;
  copySizePct: number;
  capitalAtRisk: number;
  autonomyPreset: CopyAutonomyPreset;
  children: React.ReactNode;
}): JSX.Element {
  const autonomy = formatCopyAgentAutonomySummary(autonomyPreset);

  return (
    <div className="agent-copy-md-summary-card">
      <button
        type="button"
        className="agent-copy-md-summary-toggle"
        onClick={onToggle}
        aria-expanded={open}
      >
        <span className="agent-copy-md-summary-toggle-label">
          <ExpandCollapseIcon expanded={open} size={14} /> Summary &amp; risk
        </span>
        <span className="agent-copy-md-summary-toggle-meta">
          {copySizePct}% · {formatCurrency(capitalAtRisk)} risk · {autonomy.label}
        </span>
      </button>
      <AnimatedCollapse open={open}>{children}</AnimatedCollapse>
    </div>
  );
}


export function CopyAgentDestinationCards({
  destinationMode,
  onSelect,
  hasExistingBuckets,
}: {
  destinationMode: "new" | "existing";
  onSelect: (mode: "new" | "existing") => void;
  hasExistingBuckets: boolean;
}): JSX.Element {
  const options: PresetCardOption<"new" | "existing">[] = [
    {
      value: "new",
      label: "New copy bucket",
      description: "Dedicated cross margin bucket funded from spot.",
    },
    {
      value: "existing",
      label: "Existing cross bucket",
      description: hasExistingBuckets
        ? "Mirror into a bucket you already use; trades share margin."
        : "No cross buckets available yet.",
      disabled: !hasExistingBuckets,
    },
  ];

  const hint =
    destinationMode === "new"
      ? "Creates an isolated bucket for this mirror."
      : "Copied trades share the destination bucket's margin pool.";

  return (
    <section className="agent-copy-autonomy-cards">
      <h4 className="agent-copy-autonomy-section-title">Bucket destination</h4>
      <PresetCardGrid
        options={options}
        selected={destinationMode}
        onSelect={onSelect}
        columns={2}
        hint={hint}
        aria-label="Bucket destination"
      />
    </section>
  );
}

export function CopyAgentAutonomyCards({
  autonomyPreset,
  onSelect,
}: {
  autonomyPreset: CopyAutonomyPreset;
  onSelect: (preset: CopyAutonomyPreset) => void;
}): JSX.Element {
  const options: PresetCardOption<CopyAutonomyPreset>[] = [
    {
      value: "guarded",
      label: "Guarded",
      description:
        "More copied trades surface for approval; longer gate window.",
      tone: AUTONOMY_PRESET_TONE.guarded,
    },
    {
      value: "highAgency",
      label: "High-Agency",
      description: "Silent execution when confidence and risk stay in band.",
      tone: AUTONOMY_PRESET_TONE.highAgency,
      warn: true,
    },
    {
      value: "manual",
      label: "Manual",
      description:
        "Mirror signals; copied intents wait for you. Hand-placed orders still work.",
      tone: AUTONOMY_PRESET_TONE.manual,
    },
  ];

  const activeHint = formatCopyAgentAutonomySummary(autonomyPreset).description;

  return (
    <section className="agent-copy-autonomy-cards">
      <h4 className="agent-copy-autonomy-section-title">Agentic protection</h4>
      <PresetCardGrid
        options={options}
        selected={autonomyPreset}
        onSelect={onSelect}
        columns={3}
        hint={activeHint}
        aria-label="Agentic protection preset"
      />
    </section>
  );
}
