import type { MockOrder } from "./orders";
import { cloneOfflineOrders } from "./offlinePortfolio";
import { getJellyOrderHistory, type JellyDemoConfig, type JellyReplayPhase } from "./jellyevent";

const SATOSHI = 100_000_000;
const ONBOARD_WALLET_KEY = "onboard_wallet_address";

const cancelledOrderIds = new Set<string>();
const priceOverrides = new Map<string, number>();
const orderListeners = new Set<() => void>();

function notifyOrderListeners(): void {
  orderListeners.forEach((listener) => listener());
}

export interface MockOrdersSourceOptions {
  walletAddress?: string;
  jellyActive: boolean;
  jellyDemoConfig?: JellyDemoConfig;
  jellyFrameIndex?: number;
  jellyReplayPhase?: JellyReplayPhase;
}

export function resolveMockOrdersWallet(
  options?: Pick<MockOrdersSourceOptions, "walletAddress">,
): string | null {
  const fromOptions = options?.walletAddress?.trim();
  if (fromOptions) return fromOptions.toLowerCase();
  if (typeof localStorage !== "undefined") {
    const stored = localStorage.getItem(ONBOARD_WALLET_KEY)?.trim();
    if (stored) return stored.toLowerCase();
  }
  return null;
}

function buildRawSource(options: MockOrdersSourceOptions): MockOrder[] {
  if (options.jellyActive) {
    return getJellyOrderHistory(
      options.jellyDemoConfig,
      options.jellyFrameIndex,
      options.jellyReplayPhase,
    );
  }
  const wallet = resolveMockOrdersWallet(options);
  if (!wallet) return [];
  return cloneOfflineOrders(wallet);
}

function toSatoshiStr(value: number): string {
  return String(Math.round(value * SATOSHI));
}

function applyPriceOverrides(orders: MockOrder[]): MockOrder[] {
  if (priceOverrides.size === 0) return orders;
  return orders.map((order) => {
    const parentOverride = priceOverrides.get(order.orderId);
    let next = order;
    if (parentOverride != null) {
      next = { ...next, price: toSatoshiStr(parentOverride) };
    }
    const legs = next.childOrders;
    if (!legs || legs.length === 0) return next;
    let legsChanged = false;
    const nextLegs = legs.map((leg) => {
      const legOverride = priceOverrides.get(leg.orderId);
      if (legOverride == null) return leg;
      legsChanged = true;
      return { ...leg, price: legOverride };
    });
    return legsChanged ? { ...next, childOrders: nextLegs } : next;
  });
}

/** Offline demo order list with session cancellations applied. */
export function getMockOrdersSource(options: MockOrdersSourceOptions): MockOrder[] {
  return applyPriceOverrides(
    buildRawSource(options).filter(
      (order) => !cancelledOrderIds.has(order.orderId),
    ),
  );
}

function orderExistsInMockSources(
  orderId: string,
  walletAddress?: string,
): boolean {
  return (
    buildRawSource({ jellyActive: false, walletAddress }).some(
      (order) => order.orderId === orderId,
    ) ||
    buildRawSource({ jellyActive: true }).some((order) => order.orderId === orderId)
  );
}

/** Mark an order cancelled for the current demo session. Returns true if newly cancelled. */
export function cancelMockOrder(orderId: string, walletAddress?: string): boolean {
  if (
    !orderId ||
    cancelledOrderIds.has(orderId) ||
    !orderExistsInMockSources(orderId, walletAddress)
  ) {
    return false;
  }
  cancelledOrderIds.add(orderId);
  notifyOrderListeners();
  return true;
}

function orderOrLegExists(orderId: string, walletAddress?: string): boolean {
  if (orderExistsInMockSources(orderId, walletAddress)) return true;
  const sources = [
    buildRawSource({ jellyActive: false, walletAddress }),
    buildRawSource({ jellyActive: true }),
  ];
  return sources.some((orders) =>
    orders.some((order) =>
      order.childOrders?.some((leg) => leg.orderId === orderId),
    ),
  );
}

/** Update resting price for an offline demo order (parent or scale leg). */
export function modifyMockOrderPrice(
  orderId: string,
  newPrice: number,
  walletAddress?: string,
): boolean {
  if (!orderId || !Number.isFinite(newPrice) || newPrice <= 0) return false;
  if (!orderOrLegExists(orderId, walletAddress)) return false;
  priceOverrides.set(orderId, newPrice);
  notifyOrderListeners();
  return true;
}

export function subscribeMockOrders(listener: () => void): () => void {
  orderListeners.add(listener);
  return () => orderListeners.delete(listener);
}

export function resetMockOrderState(): void {
  cancelledOrderIds.clear();
  priceOverrides.clear();
  notifyOrderListeners();
}

/** Test helper: whether an order id is in the cancelled set. */
export function isMockOrderCancelled(orderId: string): boolean {
  return cancelledOrderIds.has(orderId);
}
