import { BUBBLE_TIP_IDS, type BubbleTipId } from "./bubbleTipIds";

const INTENT_TEMPLATE_BUBBLE_MAP: Record<string, BubbleTipId> = {
  "news-event": BUBBLE_TIP_IDS.newsEvent,
  scalping: BUBBLE_TIP_IDS.scalping,
  "portfolio-allocation": BUBBLE_TIP_IDS.portfolioAllocation,
  "stat-arb": BUBBLE_TIP_IDS.statArb,
  "momentum-risk-guard": BUBBLE_TIP_IDS.momentumRiskGuard,
  "mean-reversion": BUBBLE_TIP_IDS.meanReversion,
  "sentiment-macro": BUBBLE_TIP_IDS.sentimentMacro,
  "polymarket-event": BUBBLE_TIP_IDS.polymarketEvent,
};

export function resolveIntentBubbleId(templateId: string): BubbleTipId {
  return INTENT_TEMPLATE_BUBBLE_MAP[templateId] ?? BUBBLE_TIP_IDS.manualIntent;
}
