import {
  bucketAmount,
  scaleTimelineAmount,
  type JellyDemoConfig,
} from "./jellyDemoConfig";

export const TIMELINE_OFFSETS = {
  ATTACK: 0,
  HEALTH_CHECK: 12,
  LIQUIDATION: 28,
  WIND_DOWN: 35,
  POST_MORTEM: 47,
} as const;

export const TIMELINE_AMOUNTS = {
  SAFE_TO_MEME_TRANSFER: 150_000,
  MEME_LIQUIDATION_LOSS: 87_000,
  INSURANCE_FEE_RATE: 0.005,
  HEDGE_PROFIT: 41_000,
  MEME_TOP_UP_FROM_SAFE: 5_000,
} as const;

export type OperatorBucketKey = "OP_SAFE" | "OP_MEME" | "OP_HEDGE" | "OP_INSURANCE";

export type BucketTimelineState = {
  baseEquity: number;
  realizedLoss: number;
  feeCredit: number;
  hedgeRealizedPnl: number;
  status: string;
};

function initialTimelineState(config: JellyDemoConfig): Record<OperatorBucketKey, BucketTimelineState> {
  return {
    OP_SAFE: {
      baseEquity: bucketAmount(config, config.safePct),
      realizedLoss: 0,
      feeCredit: 0,
      hedgeRealizedPnl: 0,
      status: "active",
    },
    OP_MEME: {
      baseEquity: bucketAmount(config, config.memePct),
      realizedLoss: 0,
      feeCredit: 0,
      hedgeRealizedPnl: 0,
      status: "active",
    },
    OP_HEDGE: {
      baseEquity: bucketAmount(config, config.hedgePct),
      realizedLoss: 0,
      feeCredit: 0,
      hedgeRealizedPnl: 0,
      status: "active",
    },
    OP_INSURANCE: {
      baseEquity: bucketAmount(config, config.insurancePct),
      realizedLoss: 0,
      feeCredit: 0,
      hedgeRealizedPnl: 0,
      status: "active",
    },
  };
}

export function getTimelineFrameOffset(frameIndex: number, anchorIndex: number): number {
  return Math.max(0, frameIndex - anchorIndex);
}

export function isTimelineLiquidated(frameIndex: number, anchorIndex: number): boolean {
  return getTimelineFrameOffset(frameIndex, anchorIndex) >= TIMELINE_OFFSETS.LIQUIDATION;
}

export function applyBucketTimeline(
  config: JellyDemoConfig,
  frameIndex: number,
  anchorIndex: number,
): Record<OperatorBucketKey, BucketTimelineState> {
  const state = initialTimelineState(config);
  const offset = getTimelineFrameOffset(frameIndex, anchorIndex);

  if (offset >= TIMELINE_OFFSETS.ATTACK) {
    state.OP_MEME.status = "isolated";
  }

  if (offset >= TIMELINE_OFFSETS.HEALTH_CHECK) {
    const transfer = scaleTimelineAmount(config, TIMELINE_AMOUNTS.SAFE_TO_MEME_TRANSFER);
    state.OP_SAFE.baseEquity -= transfer;
    state.OP_MEME.baseEquity += transfer;
    state.OP_MEME.status = "circuit_breaker_lite";
  }

  if (offset >= TIMELINE_OFFSETS.LIQUIDATION) {
    const loss = scaleTimelineAmount(config, TIMELINE_AMOUNTS.MEME_LIQUIDATION_LOSS);
    const fee = loss * TIMELINE_AMOUNTS.INSURANCE_FEE_RATE;
    const cappedLoss = Math.min(loss, state.OP_MEME.baseEquity);
    state.OP_MEME.baseEquity -= cappedLoss;
    state.OP_MEME.realizedLoss = cappedLoss;
    state.OP_INSURANCE.feeCredit = fee;
    state.OP_INSURANCE.baseEquity += fee;
    state.OP_MEME.status = "liquidated";
  }

  if (offset >= TIMELINE_OFFSETS.WIND_DOWN) {
    const hedgeProfit = scaleTimelineAmount(config, TIMELINE_AMOUNTS.HEDGE_PROFIT);
    state.OP_HEDGE.hedgeRealizedPnl = hedgeProfit;
    state.OP_HEDGE.baseEquity += hedgeProfit;

    const initialMemeSlice = bucketAmount(config, config.memePct);
    const memeDeficit = Math.max(0, initialMemeSlice - state.OP_MEME.baseEquity);
    if (memeDeficit > 0) {
      const topUp = Math.min(
        memeDeficit,
        scaleTimelineAmount(config, TIMELINE_AMOUNTS.MEME_TOP_UP_FROM_SAFE),
        state.OP_SAFE.baseEquity,
      );
      state.OP_SAFE.baseEquity -= topUp;
      state.OP_MEME.baseEquity += topUp;
    }
    state.OP_MEME.status = "wind_down";
  }

  if (offset >= TIMELINE_OFFSETS.POST_MORTEM) {
    state.OP_MEME.status = "active";
  }

  return state;
}
