import { useLayoutEffect, useMemo, useRef, useState, type RefObject } from "react";

import {
  computeMarkerBubblePosition,
  type MarkerBubbleLayoutResult,
} from "./markerBubbleLayout";

const FALLBACK_BUBBLE_WIDTH = 160;
const FALLBACK_BUBBLE_HEIGHT = 80;

export interface UseMarkerBubbleLayoutResult {
  bubbleRef: RefObject<HTMLDivElement>;
  layout: MarkerBubbleLayoutResult;
}

export function useMarkerBubbleLayout(
  x: number,
  y: number,
  containerWidth: number,
  containerHeight: number,
  measureDeps: readonly unknown[],
): UseMarkerBubbleLayoutResult {
  const bubbleRef = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const bubble = bubbleRef.current;
    if (!bubble) return;

    const width = bubble.offsetWidth;
    const height = bubble.offsetHeight;
    setSize((current) =>
      current.width === width && current.height === height
        ? current
        : { width, height },
    );
  }, [x, y, containerWidth, containerHeight, ...measureDeps]);

  const layout = useMemo(
    () =>
      computeMarkerBubblePosition({
        markerX: x,
        markerY: y,
        bubbleWidth: size.width > 0 ? size.width : FALLBACK_BUBBLE_WIDTH,
        bubbleHeight: size.height > 0 ? size.height : FALLBACK_BUBBLE_HEIGHT,
        containerWidth,
        containerHeight,
      }),
    [x, y, size.width, size.height, containerWidth, containerHeight],
  );

  return { bubbleRef, layout };
}
