import React, { useEffect, useRef, useState } from "react";
import {
  loadTradingViewScript,
  createTradingViewWidget,
  generateContainerId,
  removeExistingScript,
  type TradingViewWidgetConfig,
} from "./util";
import { TRADINGVIEW_DEFAULT_SYMBOL, TRADINGVIEW_DEFAULT_INTERVAL } from "../../constants";
import "./styles.css";

interface TradingViewWidgetProps {
  symbol?: string;
  interval?: string;
  isCollapsed?: boolean;
  className?: string;
  height?: string;
}

function TradingViewWidget({
  symbol = TRADINGVIEW_DEFAULT_SYMBOL,
  interval = TRADINGVIEW_DEFAULT_INTERVAL,
  isCollapsed = false,
  className = "",
  height,
}: TradingViewWidgetProps): JSX.Element {
  const containerRef = useRef<HTMLDivElement>(null);
  const widgetRef = useRef<any>(null);
  const containerIdRef = useRef<string>(generateContainerId());
  const [loading, setLoading] = useState(!isCollapsed);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Don't initialize if collapsed
    if (isCollapsed || !containerRef.current) {
      setLoading(false);
      return;
    }

    // Set container ID
    if (containerRef.current) {
      containerRef.current.id = containerIdRef.current;
    }

    let isMounted = true;
    setLoading(true);
    setError(null);

    // Load script and create widget
    loadTradingViewScript()
      .then(() => {
        if (!isMounted || !containerRef.current) {
          return;
        }

        const config: TradingViewWidgetConfig = {
          symbol,
          interval,
          containerId: containerIdRef.current,
        };

        widgetRef.current = createTradingViewWidget(config);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to load TradingView widget:", err);
        if (isMounted) {
          setError(err instanceof Error ? err.message : "Failed to load chart");
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
      if (widgetRef.current) {
        widgetRef.current = null;
      }
    };
  }, [symbol, interval, isCollapsed]);

  useEffect(() => {
    if (!height || !widgetRef.current) {
      return;
    }
    const frame = requestAnimationFrame(() => {
      widgetRef.current?.resize?.();
    });
    return () => cancelAnimationFrame(frame);
  }, [height]);

  // Cleanup script on unmount
  useEffect(() => {
    return () => {
      removeExistingScript();
    };
  }, []);

  if (isCollapsed) {
    return (
      <div className={`tradingview-widget-container chart-panel ${className}`.trim()} />
    );
  }

  return (
    <div
      className={`tradingview-widget-wrapper chart-panel ${className}`.trim()}
      style={height ? { height } : undefined}
    >
      {loading ? (
        <div className="tradingview-chart-status terminal-label">Loading chart...</div>
      ) : null}
      {!loading && error ? (
        <div className="tradingview-chart-status terminal-label tradingview-chart-status--error">
          {error}
        </div>
      ) : null}
      <div
        ref={containerRef}
        id={containerIdRef.current}
        className="tradingview-widget-container"
      />
    </div>
  );
}

export default TradingViewWidget;
