import React, { useId, useState } from "react";

interface InfoTipProps {
  label: string;
  children: React.ReactNode;
}

export default function InfoTip({ label, children }: InfoTipProps): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const tipId = useId();

  return (
    <span className="nh-info-tip">
      <button
        type="button"
        className="nh-info-tip-trigger"
        aria-label={`What is ${label}?`}
        aria-expanded={open}
        aria-describedby={open ? tipId : undefined}
        onClick={() => setOpen((prev) => !prev)}
        onBlur={() => setOpen(false)}
      >
        i
      </button>
      {open ? (
        <span id={tipId} role="tooltip" className="nh-info-tip-content">
          {children}
        </span>
      ) : null}
    </span>
  );
}
