import React from "react";
import TabSection, {
  type TabSectionProps,
  type TabSectionTabId,
} from "../tables/TabSection";

export const PORTFOLIO_TAB_ORDER: TabSectionTabId[] = [
  "agentTasks",
  "buckets",
  "positions",
  "openOrders",
  "tradeHistory",
  "history",
  "fundingHistory",
  "memoryAudit",
];

export type PortfolioTabSectionProps = Omit<
  TabSectionProps,
  "tabOrder" | "defaultTab"
>;

function PortfolioTabSection(props: PortfolioTabSectionProps): JSX.Element {
  return (
    <TabSection
      {...props}
      tabOrder={PORTFOLIO_TAB_ORDER}
      defaultTab="agentTasks"
    />
  );
}

export default React.memo(PortfolioTabSection);
