import {
  ORDER_TYPE_STOP_MARKET,
  ORDER_TYPE_STOP_LIMIT,
  ORDER_TYPE_TWAP,
  ORDER_TYPE_SCALE,
} from "../constants";

export const ADVANCED_ORDER_GROUP_CONDITIONAL = "conditional" as const;
export const ADVANCED_ORDER_GROUP_ALGORITHMIC = "algorithmic" as const;
export const ADVANCED_ORDER_GROUP_SMART_LIMIT = "smart_limit" as const;
export const ADVANCED_ORDER_GROUP_RISK = "risk" as const;

export type AdvancedOrderGroupId =
  | typeof ADVANCED_ORDER_GROUP_CONDITIONAL
  | typeof ADVANCED_ORDER_GROUP_ALGORITHMIC
  | typeof ADVANCED_ORDER_GROUP_SMART_LIMIT
  | typeof ADVANCED_ORDER_GROUP_RISK;

export const ADVANCED_ORDER_TYPE_STOP_MARKET = ORDER_TYPE_STOP_MARKET;
export const ADVANCED_ORDER_TYPE_STOP_LIMIT = ORDER_TYPE_STOP_LIMIT;
export const ADVANCED_ORDER_TYPE_TAKE_PROFIT_MARKET = "take_profit_market" as const;
export const ADVANCED_ORDER_TYPE_TAKE_PROFIT_LIMIT = "take_profit_limit" as const;
export const ADVANCED_ORDER_TYPE_TWAP = ORDER_TYPE_TWAP;
export const ADVANCED_ORDER_TYPE_SCALE = ORDER_TYPE_SCALE;
export const ADVANCED_ORDER_TYPE_CHASE_LIMIT = "chase_limit" as const;
export const ADVANCED_ORDER_TYPE_POST_ONLY = "post_only" as const;
export const ADVANCED_ORDER_TYPE_BRACKET = "bracket" as const;

export type AdvancedOrderTypeId =
  | typeof ADVANCED_ORDER_TYPE_STOP_MARKET
  | typeof ADVANCED_ORDER_TYPE_STOP_LIMIT
  | typeof ADVANCED_ORDER_TYPE_TAKE_PROFIT_MARKET
  | typeof ADVANCED_ORDER_TYPE_TAKE_PROFIT_LIMIT
  | typeof ADVANCED_ORDER_TYPE_TWAP
  | typeof ADVANCED_ORDER_TYPE_SCALE
  | typeof ADVANCED_ORDER_TYPE_CHASE_LIMIT
  | typeof ADVANCED_ORDER_TYPE_POST_ONLY
  | typeof ADVANCED_ORDER_TYPE_BRACKET;

export interface AdvancedOrderTypeEntry {
  id: AdvancedOrderTypeId;
  label: string;
  enabled: boolean;
}

export interface AdvancedOrderGroup {
  id: AdvancedOrderGroupId;
  label: string;
  items: AdvancedOrderTypeEntry[];
}

export interface AdvancedOrderParams {
  triggerPrice: number;
  limitPrice: number;
  durationMinutes: number;
  sliceIntervalSeconds: number;
  randomizeSlices: boolean;
  priceFrom: number;
  priceTo: number;
  orderCount: number;
  reduceOnly: boolean;
}

export const DEFAULT_ADVANCED_ORDER_PARAMS: AdvancedOrderParams = {
  triggerPrice: 0,
  limitPrice: 0,
  durationMinutes: 30,
  sliceIntervalSeconds: 30,
  randomizeSlices: false,
  priceFrom: 0,
  priceTo: 0,
  orderCount: 5,
  reduceOnly: false,
};

export const ADVANCED_ORDER_GROUPS: AdvancedOrderGroup[] = [
  {
    id: ADVANCED_ORDER_GROUP_CONDITIONAL,
    label: "Conditional",
    items: [
      {
        id: ADVANCED_ORDER_TYPE_STOP_MARKET,
        label: "Stop Market",
        enabled: true,
      },
      {
        id: ADVANCED_ORDER_TYPE_STOP_LIMIT,
        label: "Stop Limit",
        enabled: true,
      },
      {
        id: ADVANCED_ORDER_TYPE_TAKE_PROFIT_MARKET,
        label: "Take Profit (Market)",
        enabled: false,
      },
      {
        id: ADVANCED_ORDER_TYPE_TAKE_PROFIT_LIMIT,
        label: "Take Profit (Limit)",
        enabled: false,
      },
    ],
  },
  {
    id: ADVANCED_ORDER_GROUP_ALGORITHMIC,
    label: "Algorithmic",
    items: [
      { id: ADVANCED_ORDER_TYPE_TWAP, label: "TWAP", enabled: true },
      { id: ADVANCED_ORDER_TYPE_SCALE, label: "Scale", enabled: true },
    ],
  },
  {
    id: ADVANCED_ORDER_GROUP_SMART_LIMIT,
    label: "Smart Limit",
    items: [
      { id: ADVANCED_ORDER_TYPE_CHASE_LIMIT, label: "Chase Limit", enabled: false },
      { id: ADVANCED_ORDER_TYPE_POST_ONLY, label: "Post-Only", enabled: false },
    ],
  },
  {
    id: ADVANCED_ORDER_GROUP_RISK,
    label: "Risk",
    items: [
      { id: ADVANCED_ORDER_TYPE_BRACKET, label: "Bracket / Multi TP-SL", enabled: false },
    ],
  },
];

export function isConditionalAdvancedType(
  type: AdvancedOrderTypeId | null,
): boolean {
  if (!type) return false;
  return (
    type === ADVANCED_ORDER_TYPE_STOP_MARKET ||
    type === ADVANCED_ORDER_TYPE_STOP_LIMIT ||
    type === ADVANCED_ORDER_TYPE_TAKE_PROFIT_MARKET ||
    type === ADVANCED_ORDER_TYPE_TAKE_PROFIT_LIMIT
  );
}

export function getAdvancedOrderEntry(
  type: AdvancedOrderTypeId,
): AdvancedOrderTypeEntry | undefined {
  for (const group of ADVANCED_ORDER_GROUPS) {
    const entry = group.items.find((item) => item.id === type);
    if (entry) return entry;
  }
  return undefined;
}

export function isAdvancedOrderEnabled(type: AdvancedOrderTypeId): boolean {
  return getAdvancedOrderEntry(type)?.enabled ?? false;
}
