/** Cumulative chain-truth KPIs sourced from the SDK (status-page grade). */
export interface NetworkKpis {
  activeValidators: number;
  totalValidators: number;
  totalBlocks: number;
  confirmedBlocks: number;
  averageTps: number;
  finalityRate: number;
  roundsFinalised: number;
  roundsFailed: number;
  frostyFallbacks: number;
  latestTips: number;
  timestampMs: number | null;
}

/** Live, metric-derived KPIs sourced from Prometheus (`null` = no sample yet). */
export interface LiveMetrics {
  submitTps: number | null;
  confirmedTps: number | null;
  finalityP50Ms: number | null;
  finalityP99Ms: number | null;
  committeeSize: number | null;
  bftQuorum: number | null;
  validatorsUp: number | null;
  dvtOperatorsUp: number | null;
}

export interface TelemetryPanel {
  id: string;
  title: string;
  series: number[];
  unit?: string;
  colorToken?: TelemetryColorToken;
}

export type TelemetryColorToken =
  | "accent"
  | "secondary"
  | "long"
  | "premium"
  | "short"
  | "info";

/** 0 = demo, 1 = benchmark, 2 = production architectural target */
export type ThroughputTier = 0 | 1 | 2;

export interface DemoContext {
  throughputTier: ThroughputTier;
  validatorCount: number;
}

export const VALIDATOR_MIN = 4;
export const VALIDATOR_MAX = 64;
export const DEFAULT_VALIDATOR_COUNT = 4;
export const DEFAULT_THROUGHPUT_TIER: ThroughputTier = 0;

export function bftQuorumFor(n: number): number {
  return Math.floor((2 * n) / 3) + 1;
}

export function dvtOperatorsFor(n: number): number {
  return n * 5;
}
