import React from "react";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";

export interface NeedsYouBadgeProps {
  count: number;
  escalated: boolean;
  onFocus?: () => void;
}

function NeedsYouBadge({
  count,
  escalated,
  onFocus,
}: NeedsYouBadgeProps): JSX.Element {
  const interactive = escalated && count > 0 && onFocus;

  if (count === 0) {
    return (
      <BubbleTip id={BUBBLE_TIP_IDS.highANeedsYou}>
        <span className="high-a-needs-you high-a-needs-you--calm">
          Needs you 0
        </span>
      </BubbleTip>
    );
  }

  const className = [
    "high-a-needs-you",
    "high-a-needs-you--active",
    escalated ? "high-a-needs-you--pulse" : "",
    interactive ? "high-a-needs-you--clickable" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const label = `Needs you ${count}`;

  if (interactive) {
    return (
      <BubbleTip id={BUBBLE_TIP_IDS.highANeedsYou}>
        <button
          type="button"
          className={className}
          onClick={onFocus}
          aria-label={`${label}, focus exception spotlight`}
        >
          <span className="high-a-needs-you-dot" aria-hidden>
            ●
          </span>
          {label}
        </button>
      </BubbleTip>
    );
  }

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.highANeedsYou}>
      <span className={className}>
        <span className="high-a-needs-you-dot" aria-hidden>
          ●
        </span>
        {label}
      </span>
    </BubbleTip>
  );
}

export default React.memo(NeedsYouBadge);
