import React, {
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import type { AgentTask } from "../../store/types";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import "./agentTasks.css";

const DROPDOWN_GAP_PX = 6;

export interface AgentTaskActionFlags {
  isPaused: boolean;
  isTerminal: boolean;
  canPauseResume: boolean;
  canForceExecute: boolean;
  canReject: boolean;
}

export interface AgentTaskRowActionsMenuProps {
  task: AgentTask;
  actionFlags: AgentTaskActionFlags;
  isMobile?: boolean;
  onEdit: (task: AgentTask) => void;
  onPauseResume: (task: AgentTask) => void;
  onForceExecute: (task: AgentTask) => void;
  onReject: (task: AgentTask) => void;
  onViewOnChart: (task: AgentTask) => void;
}

interface DropdownPosition {
  top: number;
  right: number;
}

function AgentTaskRowActionsMenu({
  task,
  actionFlags,
  isMobile = false,
  onEdit,
  onPauseResume,
  onForceExecute,
  onReject,
  onViewOnChart,
}: AgentTaskRowActionsMenuProps): JSX.Element {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [dropdownPosition, setDropdownPosition] = useState<DropdownPosition | null>(
    null,
  );

  const close = useCallback(() => setIsOpen(false), []);

  const handleAfterUnmount = useCallback(() => {
    setDropdownPosition(null);
  }, []);

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: isMobile ? OVERLAY_TIMING.mobileSheetMs : 0,
    enableBackdrop: isMobile,
    onAfterUnmount: handleAfterUnmount,
  });

  useOverlayEscapeKey(isOpen, close);
  useOverlayScrollLock(isOpen && mounted && isMobile);

  const updateDropdownPosition = useCallback(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;

    const rect = trigger.getBoundingClientRect();
    setDropdownPosition({
      top: rect.bottom + DROPDOWN_GAP_PX,
      right: window.innerWidth - rect.right,
    });
  }, []);

  useLayoutEffect(() => {
    if (!isOpen || isMobile) return;

    updateDropdownPosition();

    const onReposition = () => updateDropdownPosition();
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);

    return () => {
      window.removeEventListener("resize", onReposition);
      window.removeEventListener("scroll", onReposition, true);
    };
  }, [isOpen, isMobile, updateDropdownPosition]);

  const handleToggle = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!isOpen && !isMobile) {
      updateDropdownPosition();
    }
    setIsOpen((open) => !open);
  };

  const handleAction = (action: () => void) => (e: React.MouseEvent) => {
    e.stopPropagation();
    close();
    action();
  };

  const menuItems = (
    <>
      <button
        type="button"
        className="agent-task-row-actions-menu-item"
        role="menuitem"
        onClick={handleAction(() => onEdit(task))}
      >
        Edit
      </button>
      {actionFlags.canPauseResume ? (
        <button
          type="button"
          className="agent-task-row-actions-menu-item"
          role="menuitem"
          onClick={handleAction(() => onPauseResume(task))}
        >
          {actionFlags.isPaused ? "Resume" : "Pause"}
        </button>
      ) : null}
      {actionFlags.canForceExecute ? (
        <button
          type="button"
          className="agent-task-row-actions-menu-item agent-task-row-actions-menu-item--success"
          role="menuitem"
          onClick={handleAction(() => onForceExecute(task))}
        >
          Execute
        </button>
      ) : null}
      {actionFlags.canReject ? (
        <button
          type="button"
          className="agent-task-row-actions-menu-item agent-task-row-actions-menu-item--danger"
          role="menuitem"
          onClick={handleAction(() => onReject(task))}
        >
          Reject
        </button>
      ) : null}
      {task.marketId ? (
        <button
          type="button"
          className="agent-task-row-actions-menu-item"
          role="menuitem"
          onClick={handleAction(() => onViewOnChart(task))}
        >
          Chart
        </button>
      ) : null}
    </>
  );

  const portalContent =
    mounted && isOpen
      ? isMobile
        ? (
            <StaggeredOverlayRoot className="agent-task-row-actions-menu-overlay agent-task-row-actions-menu-overlay--mobile">
              <StaggeredOverlayBackdrop
                visible={backdropVisible}
                onClose={close}
                style={backdropStyle}
                className="staggered-overlay-backdrop--deep"
              />
              <StaggeredOverlayPanel
                open={panelOpen}
                className="agent-task-row-actions-menu-panel agent-task-row-actions-menu-panel--mobile"
                aria-label="Task actions"
              >
                <header className="agent-task-row-actions-menu-panel-header">
                  <h2 className="terminal-panel-title agent-task-row-actions-menu-panel-title">
                    Task actions
                  </h2>
                  <button
                    type="button"
                    className="agent-task-row-actions-menu-panel-close"
                    onClick={(e) => {
                      e.stopPropagation();
                      close();
                    }}
                    aria-label="Close task actions"
                  >
                    ×
                  </button>
                </header>
                <div className="agent-task-row-actions-menu-panel-body" role="menu">
                  {menuItems}
                </div>
              </StaggeredOverlayPanel>
            </StaggeredOverlayRoot>
          )
        : dropdownPosition
          ? (
              <>
                <div
                  className="agent-task-row-actions-menu-overlay"
                  onClick={(e) => {
                    e.stopPropagation();
                    close();
                  }}
                  role="presentation"
                />
                <div
                  className="agent-task-row-actions-menu-panel agent-task-row-actions-menu-panel--desktop"
                  style={{
                    top: dropdownPosition.top,
                    right: dropdownPosition.right,
                  }}
                  onClick={(e) => e.stopPropagation()}
                  role="menu"
                  aria-label="Task actions"
                >
                  {menuItems}
                </div>
              </>
            )
          : null
      : null;

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        className="agent-task-row-actions-menu-trigger"
        aria-label="Task actions"
        aria-haspopup="menu"
        aria-expanded={isOpen}
        onClick={handleToggle}
      >
        ⋯
      </button>
      {typeof document !== "undefined" && portalContent
        ? createPortal(portalContent, document.body)
        : null}
    </>
  );
}

export default AgentTaskRowActionsMenu;
