import React, { useEffect, useMemo } from "react";
import { useTradingAgents } from "../../../hooks/useTradingAgents";
import { useAgentTasks } from "../../../hooks/useAgentTasks";
import AgentCommandCenterRail from "../AgentCommandCenterRail";
import AgentMemoryDetailPane from "../AgentMemoryDetailPane";
import type { TradingAgent } from "../../../store/types";

function resolveDefaultAgentId(agents: TradingAgent[]): string | null {
  if (agents.length === 0) return null;
  const active = agents.find((a) => a.status === "active");
  return active?.id ?? agents[0]!.id;
}

function AgentCommandCenterTab(): JSX.Element {
  const {
    agents,
    selectedAgentId,
    setSelectedAgentId,
    getAgentById,
    appendMemoryNote,
  } = useTradingAgents();
  const { tasks } = useAgentTasks();

  const taskCountByAgent = useMemo(() => {
    const counts = new Map<string, number>();
    for (const task of tasks) {
      if (!task.agentId) continue;
      counts.set(task.agentId, (counts.get(task.agentId) ?? 0) + 1);
    }
    return counts;
  }, [tasks]);

  useEffect(() => {
    if (agents.length === 0) return;
    if (selectedAgentId && getAgentById(selectedAgentId)) return;
    setSelectedAgentId(resolveDefaultAgentId(agents));
  }, [agents, selectedAgentId, getAgentById, setSelectedAgentId]);

  const selectedAgent = selectedAgentId
    ? getAgentById(selectedAgentId) ?? null
    : null;
  const selectedTaskCount = selectedAgentId
    ? (taskCountByAgent.get(selectedAgentId) ?? 0)
    : 0;

  if (agents.length === 0) {
    return (
      <p className="agent-console-empty terminal-text-muted">
        No agents deployed yet. Create a task from the trade panel to get started.
      </p>
    );
  }

  return (
    <div className="agent-console-command-layout">
      <AgentCommandCenterRail
        agents={agents}
        selectedAgentId={selectedAgentId}
        onSelectAgent={setSelectedAgentId}
      />
      <AgentMemoryDetailPane
        agent={selectedAgent}
        taskCount={selectedTaskCount}
        onAddNote={
          selectedAgentId
            ? (text) => appendMemoryNote(selectedAgentId, text)
            : undefined
        }
      />
    </div>
  );
}

export default React.memo(AgentCommandCenterTab);
