import type { HistogramData, LineData, UTCTimestamp } from "lightweight-charts";

import type { AgentKpiHistoryFile } from "../../offline/mock_data/agentKpiHistory.types";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import {
  buildFleetCharts,
  getAgentProfileById,
} from "../../offline/mock_data";
import { SHARE_CONSTITUENT_COLORS } from "../components/index/share/indexShareData";
import type { AgentCompareFocus } from "../components/agent/agentCompareFocus";
import {
  buildIndexNavPriceChartSeries,
  INDEX_CHART_HISTORY_DAYS,
} from "./indexChartData";
import {
  buildEquityCurveData,
  filterLineDataByRange,
  sanitizeLineDataForChart,
  type PortfolioTimeRange,
} from "./portfolioChartData";

export type AgentCompareChartMode = "price" | "performance";
export type AgentCompareTimeRange = PortfolioTimeRange;

const DAY_MS = 24 * 60 * 60 * 1000;

export interface AgentCompareChartSeries {
  id: string;
  label: string;
  ticker: string;
  color: string;
  data: LineData<UTCTimestamp>[];
}

export interface AgentCompareChartPayload {
  series: AgentCompareChartSeries[];
  volume: HistogramData<UTCTimestamp>[];
}

function toUtcTimestamp(ms: number): UTCTimestamp {
  return Math.floor(ms / 1000) as UTCTimestamp;
}

function interpolateSeries(values: number[], pointCount: number): number[] {
  if (values.length === 0) return [];
  if (pointCount <= 1) return [values[values.length - 1] ?? 0];
  if (values.length === 1) {
    return Array.from({ length: pointCount }, () => values[0]!);
  }

  return Array.from({ length: pointCount }, (_, index) => {
    const t = (index / (pointCount - 1)) * (values.length - 1);
    const lo = Math.floor(t);
    const hi = Math.min(Math.ceil(t), values.length - 1);
    const frac = t - lo;
    return values[lo]! * (1 - frac) + values[hi]! * frac;
  });
}

function dayBucket(timeMs: number): UTCTimestamp {
  const dayStart = Math.floor(timeMs / DAY_MS) * DAY_MS;
  return toUtcTimestamp(dayStart);
}

export function getCompareAgentColor(index: number): string {
  return SHARE_CONSTITUENT_COLORS[index % SHARE_CONSTITUENT_COLORS.length]!;
}

export function resolveDefaultChartMode(
  focus: AgentCompareFocus,
): AgentCompareChartMode {
  return focus === "scale" ? "price" : "performance";
}

function buildPriceLineData(
  sparkline: number[],
  price: number,
): LineData<UTCTimestamp>[] {
  const { priceData } = buildIndexNavPriceChartSeries(sparkline, price, price);
  return priceData;
}

function buildPerformanceLineData(pnlCurve: number[]): LineData<UTCTimestamp>[] {
  const pointCount = INDEX_CHART_HISTORY_DAYS + 1;
  const expanded =
    pnlCurve.length >= pointCount
      ? pnlCurve.slice(-pointCount)
      : interpolateSeries(pnlCurve, pointCount);

  const now = Date.now();
  const data: LineData<UTCTimestamp>[] = expanded.map((value, index) => ({
    time: toUtcTimestamp(now - (pointCount - 1 - index) * DAY_MS),
    value: Number(value.toFixed(4)),
  }));

  return sanitizeLineDataForChart(data);
}

function buildFallbackVolumeFromProfile(
  profileVolume: number | undefined,
  times: UTCTimestamp[],
): HistogramData<UTCTimestamp>[] {
  const dailyVolume =
    profileVolume != null && profileVolume > 0
      ? profileVolume / Math.max(times.length, 1)
      : 0;

  return times.map((time) => ({
    time,
    value: Number(dailyVolume.toFixed(2)),
    color: undefined,
  }));
}

function aggregateTradeVolumeByDay(
  events: FleetTradeEvent[],
): Map<number, number> {
  const buckets = new Map<number, number>();
  for (const event of events) {
    const bucket = dayBucket(Date.parse(event.timestamp)) as number;
    buckets.set(bucket, (buckets.get(bucket) ?? 0) + event.amountUsd);
  }
  return buckets;
}

function buildAggregatedVolume(
  compareIds: string[],
  referenceTimes: UTCTimestamp[],
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
): HistogramData<UTCTimestamp>[] {
  const totals = new Map<number, number>();

  for (const agentId of compareIds) {
    const trades = tradesByAgentId.get(agentId) ?? [];
    const buckets = aggregateTradeVolumeByDay(trades);
    for (const [time, amount] of buckets) {
      totals.set(time, (totals.get(time) ?? 0) + amount);
    }
  }

  if (totals.size === 0) {
    const profile = getAgentProfileById(compareIds[0] ?? "");
    return buildFallbackVolumeFromProfile(
      profile?.volume24hNumeric,
      referenceTimes,
    );
  }

  return referenceTimes.map((time) => ({
    time,
    value: Number((totals.get(time as number) ?? 0).toFixed(2)),
  }));
}

function buildPerformanceLineDataFromKpi(
  kpi: AgentKpiHistoryFile,
): LineData<UTCTimestamp>[] {
  const data = kpi.series.equityUsd.map((point) => ({
    time: toUtcTimestamp(Date.parse(point.time)),
    value: Number(point.value.toFixed(4)),
  }));
  return sanitizeLineDataForChart(data);
}

function buildSeriesForAgent(
  agentId: string,
  index: number,
  mode: AgentCompareChartMode,
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
  kpiByAgentId?: Map<string, AgentKpiHistoryFile>,
): AgentCompareChartSeries | null {
  const profile = getAgentProfileById(agentId);
  if (!profile) return null;

  const trades = tradesByAgentId.get(agentId) ?? [];
  const kpi = kpiByAgentId?.get(agentId);
  const charts = buildFleetCharts(trades, agentId, kpi);

  const rawData =
    mode === "price"
      ? buildPriceLineData(profile.sparkline, profile.price)
      : kpi
        ? buildPerformanceLineDataFromKpi(kpi)
        : buildPerformanceLineData(charts.pnlCurve);

  if (rawData.length === 0) return null;

  return {
    id: agentId,
    label: profile.name,
    ticker: profile.ticker,
    color: getCompareAgentColor(index),
    data: rawData,
  };
}

export function buildAgentCompareChartPayload(
  compareIds: string[],
  mode: AgentCompareChartMode,
  range: AgentCompareTimeRange,
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
  kpiByAgentId?: Map<string, AgentKpiHistoryFile>,
): AgentCompareChartPayload {
  const series = compareIds
    .map((id, index) =>
      buildSeriesForAgent(id, index, mode, tradesByAgentId, kpiByAgentId),
    )
    .filter((entry): entry is AgentCompareChartSeries => entry != null)
    .map((entry) => ({
      ...entry,
      data: filterLineDataByRange(entry.data, range),
    }));

  const referenceTimes =
    series[0]?.data.map((point) => point.time) ??
    buildEquityCurveData([100]).map((point) => point.time);

  const volume = filterLineDataByRange(
    buildAggregatedVolume(compareIds, referenceTimes, tradesByAgentId),
    range,
  ).map((point) => ({
    time: point.time,
    value: point.value,
  }));

  return { series, volume };
}

export function formatCompareChartValue(
  value: number,
  mode: AgentCompareChartMode,
): string {
  if (mode === "performance") {
    const sign = value >= 0 ? "+" : "";
    return `${sign}${value.toFixed(2)}%`;
  }
  if (Math.abs(value) >= 1000) {
    return `$${(value / 1000).toFixed(2)}k`;
  }
  if (Math.abs(value) >= 1) {
    return `$${value.toFixed(2)}`;
  }
  return `$${value.toFixed(4)}`;
}

export function computePercentChangeAtPoint(
  data: LineData<UTCTimestamp>[],
  time: UTCTimestamp,
): number | null {
  if (data.length === 0) return null;
  const base = data[0]!.value;
  if (base === 0) return null;

  const point = data.find((entry) => entry.time === time);
  if (!point) return null;

  return ((point.value - base) / base) * 100;
}
