import React, { useMemo } from "react";
import { useOptionalSettings } from "../../context/SettingsContext";
import {
  formatKeyboardBindingLabel,
  getDefaultBindingForAction,
} from "../../utils/keyboardShortcuts";
import type { TickerCategory } from "./types";

const CATEGORY_HELP: Record<TickerCategory, string> = {
  all: "Click a row to load market in terminal",
  agent: "Click an agent perp to load it in terminal",
  index: "Click a row to trade index perp in terminal",
  crypto: "Click a row to load market in terminal",
  tradfi: "Click a row to load market in terminal",
};

interface TickerSelectionTableFooterProps {
  category: TickerCategory;
  onBuySpotAtNav?: () => void;
}

export function TickerSelectionTableFooter({
  category,
  onBuySpotAtNav,
}: TickerSelectionTableFooterProps): JSX.Element {
  const settingsContext = useOptionalSettings();
  const tickerShortcutLabel = useMemo(() => {
    const binding =
      settingsContext?.settings.keyboardShortcuts.toggleTickerSelection ??
      getDefaultBindingForAction("toggleTickerSelection");
    return `${formatKeyboardBindingLabel(binding)} toggle · Esc close`;
  }, [settingsContext?.settings.keyboardShortcuts.toggleTickerSelection]);

  return (
    <div className="ticker-selection-table-footer">
      <div className="ticker-selection-table-footer-help">
        <span>{CATEGORY_HELP[category]}</span>
        <span className="ticker-selection-table-footer-keys">
          {tickerShortcutLabel}
        </span>
      </div>
      {category === "index" && onBuySpotAtNav ? (
        <button
          type="button"
          className="ticker-selection-table-footer-link"
          onClick={onBuySpotAtNav}
        >
          Buy spot at NAV →
        </button>
      ) : null}
    </div>
  );
}
