import React, { useState } from "react";
import { Link } from "react-router-dom";
import { ExpandCollapseIcon } from "../../../mormv1/components/ui/ExpandCollapseIcon";
import InfoTip from "./InfoTip";
import KpiCard from "./KpiCard";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import { FV_PROPERTIES, REPRODUCE_COMMANDS, TLA_EXCERPTS, VERIFIED_STATS } from "./proof";
import TrackSlider from "./TrackSlider";
import { bftQuorumFor, dvtOperatorsFor, VALIDATOR_MAX, VALIDATOR_MIN } from "./types";
import "./NetworkHealthPanel.css";

export default function ProofConsensusSection(): React.JSX.Element {
  const { validatorCount, setValidatorCount } = useNetworkHealthDemo();
  const [proofOpen, setProofOpen] = useState(false);
  const quorum = bftQuorumFor(validatorCount);
  const dvtOps = dvtOperatorsFor(validatorCount);

  return (
    <section aria-labelledby="proof-heading" className="nh nh-proof">
      <header className="nh-header">
        <h2 id="proof-heading" className="text-h2">Formally Verified Consensus</h2>
        <p className="nh-sub text-body-secondary">
          Morpheum&apos;s consensus core is machine-checked in TLA+ and discharged by
          TLAPS — mathematically proven, not hand-waved. Adjust validator set size to
          see how consensus telemetry scales (proof holds for all counts).
        </p>
      </header>

      <TrackSlider
        id="validator-count-slider"
        label="Validator set size (simulated)"
        min={VALIDATOR_MIN}
        max={VALIDATOR_MAX}
        step={1}
        value={validatorCount}
        onChange={setValidatorCount}
        valueDisplay={
          <>
            <span>n = {validatorCount} validators</span>
            <span className="nh-track-slider-meta">BFT quorum = {quorum}</span>
            <span className="nh-track-slider-meta">DVT operators = {dvtOps}</span>
          </>
        }
      />

      <div className="nh-kpi-grid nh-kpi-grid-4">
        {VERIFIED_STATS.map((stat) => (
          <KpiCard
            key={stat.label}
            label={stat.label}
            value={stat.value}
            info={stat.tooltip}
          />
        ))}
      </div>

      <div className="nh-property-grid">
        {FV_PROPERTIES.map((property) => (
          <article key={property.title} className="nh-property-card">
            <h3 className="nh-property-title text-h3">
              {property.title}
              {property.info ? <InfoTip label={property.title}>{property.info}</InfoTip> : null}
            </h3>
            <p className="nh-property-detail">{property.detail}</p>
          </article>
        ))}
      </div>

      <div className="nh-telemetry">
        <button
          type="button"
          className="nh-telemetry-toggle"
          aria-expanded={proofOpen}
          onClick={() => setProofOpen((prev) => !prev)}
        >
          <ExpandCollapseIcon expanded={proofOpen} className="nh-telemetry-chevron" size={16} />
          The proof (TLA+ excerpts)
        </button>
        {proofOpen ? (
          <div className="nh-proof-walkthrough">
            <p className="nh-section-note text-small">
              The specification language is TLA+ (created by Turing Award winner Leslie
              Lamport); TLAPS is its machine proof checker. These are the actual
              checked-in definitions.
            </p>
            {TLA_EXCERPTS.map((excerpt) => (
              <figure key={excerpt.caption} className="nh-tla-excerpt">
                <figcaption>{excerpt.caption}</figcaption>
                <pre className="nh-tla-code">
                  <code>{excerpt.code}</code>
                </pre>
                <p className="nh-tla-plain">{excerpt.plain}</p>
              </figure>
            ))}
            <figure className="nh-tla-excerpt">
              <figcaption>Reproducible from a version-pinned toolchain</figcaption>
              <pre className="nh-tla-code">
                <code>{REPRODUCE_COMMANDS}</code>
              </pre>
            </figure>
          </div>
        ) : null}
      </div>

      <article className="nh-quorum-link-card">
        <div className="nh-quorum-link-header">
          <h3 className="text-h3">Interactive: quorum intersection</h3>
          <Link to="/explainations/quorum-intersection" className="nh-quorum-link">
            Open standalone →
          </Link>
        </div>
          <p className="nh-section-note text-small">
            Explore why any two certifying quorums must share an honest validator —
            the crypto-economic heart of the safety proof.
          </p>
      </article>
    </section>
  );
}
