import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import type { TabSectionTabId } from "./TabSection";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import "./TabHeaderActionsMenu.css";

const DROPDOWN_GAP_PX = 6;

export interface TabHeaderActionsMenuProps {
  children: React.ReactNode;
  isMobile: boolean;
  activeTabId: TabSectionTabId;
}

interface DropdownPosition {
  top: number;
  right: number;
}

function hasActionContent(children: React.ReactNode): boolean {
  return children != null && children !== false;
}

export function TabHeaderActionsMenu({
  children,
  isMobile,
  activeTabId,
}: TabHeaderActionsMenuProps): JSX.Element | null {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [dropdownPosition, setDropdownPosition] = useState<DropdownPosition | null>(
    null,
  );

  const close = useCallback(() => setIsOpen(false), []);

  const handleAfterUnmount = useCallback(() => {
    setDropdownPosition(null);
  }, []);

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: isMobile ? OVERLAY_TIMING.mobileSheetMs : 0,
    enableBackdrop: isMobile,
    onAfterUnmount: handleAfterUnmount,
  });

  useOverlayEscapeKey(isOpen, close);
  useOverlayScrollLock(isOpen && mounted && isMobile);

  const updateDropdownPosition = useCallback(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;

    const rect = trigger.getBoundingClientRect();
    setDropdownPosition({
      top: rect.bottom + DROPDOWN_GAP_PX,
      right: window.innerWidth - rect.right,
    });
  }, []);

  useEffect(() => {
    close();
  }, [activeTabId, isMobile, close]);

  useLayoutEffect(() => {
    if (!isOpen || isMobile) return;

    updateDropdownPosition();

    const onReposition = () => updateDropdownPosition();
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);

    return () => {
      window.removeEventListener("resize", onReposition);
      window.removeEventListener("scroll", onReposition, true);
    };
  }, [isOpen, isMobile, updateDropdownPosition]);

  const handlePanelBodyClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isMobile) return;
    const target = e.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".btn-tab")) close();
  };

  const handleToggle = () => {
    if (!isOpen && !isMobile) {
      updateDropdownPosition();
    }
    setIsOpen((open) => !open);
  };

  if (!hasActionContent(children)) return null;

  const panelBody = (
    <div
      className="tab-header-actions-menu-panel-body"
      role="menu"
      onClick={handlePanelBodyClick}
    >
      {children}
    </div>
  );

  const portalContent =
    mounted && isOpen
      ? isMobile
        ? (
            <StaggeredOverlayRoot className="tab-header-actions-menu-overlay tab-header-actions-menu-overlay--mobile">
              <StaggeredOverlayBackdrop
                visible={backdropVisible}
                onClose={close}
                style={backdropStyle}
                className="staggered-overlay-backdrop--deep"
              />
              <StaggeredOverlayPanel
                open={panelOpen}
                className="tab-header-actions-menu-panel tab-header-actions-menu-panel--mobile"
                aria-label="Tab actions"
              >
                <header className="tab-header-actions-menu-panel-header">
                  <h2 className="terminal-panel-title tab-header-actions-menu-panel-title">
                    Actions
                  </h2>
                  <button
                    type="button"
                    className="tab-header-actions-menu-panel-close"
                    onClick={close}
                    aria-label="Close actions menu"
                  >
                    ×
                  </button>
                </header>
                {panelBody}
              </StaggeredOverlayPanel>
            </StaggeredOverlayRoot>
          )
        : (
            <>
              <div
                className="tab-header-actions-menu-overlay"
                onClick={close}
                role="presentation"
              />
              <div
                className="tab-header-actions-menu-panel tab-header-actions-menu-panel--desktop"
                style={
                  dropdownPosition
                    ? {
                        top: dropdownPosition.top,
                        right: dropdownPosition.right,
                      }
                    : undefined
                }
                onClick={(e) => e.stopPropagation()}
                aria-label="Tab actions"
              >
                {panelBody}
              </div>
            </>
          )
      : null;

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        className="tab-header-actions-menu-trigger"
        aria-label="Tab actions"
        aria-haspopup="menu"
        aria-expanded={isOpen}
        onClick={handleToggle}
      >
        ⋮
      </button>
      {typeof document !== "undefined" && portalContent
        ? createPortal(portalContent, document.body)
        : null}
    </>
  );
}
