import type { CrossChainFlowStep } from "../../types/crossChainFlow";

const FLOW_STEP_ORDER: CrossChainFlowStep[] = [
  "form",
  "review",
  "authorize",
  "submit",
  "tracking",
  "success",
  "failure",
];

/** True while the bridge flow has not yet reached the required step (e.g. tracking → success). */
export function isDepositTourNextGated(
  gateNextUntilFlowStep: CrossChainFlowStep | undefined,
  currentFlowStep: CrossChainFlowStep | null | undefined,
): boolean {
  if (!gateNextUntilFlowStep || !currentFlowStep) return false;
  const requiredIdx = FLOW_STEP_ORDER.indexOf(gateNextUntilFlowStep);
  const currentIdx = FLOW_STEP_ORDER.indexOf(currentFlowStep);
  if (requiredIdx < 0 || currentIdx < 0) return false;
  return currentIdx < requiredIdx;
}

/** flowStep → target step id; only sync when current step is in allowedFrom. */
export const DEPOSIT_FLOW_SYNC_RULES: Partial<
  Record<
    CrossChainFlowStep,
    { targetStepId: string; allowedFrom: readonly string[] }
  >
> = {
  review: { targetStepId: "review-verify", allowedFrom: ["form-review"] },
  authorize: { targetStepId: "authorize-btn", allowedFrom: ["review-confirm"] },
  submit: { targetStepId: "submit-btn", allowedFrom: ["authorize-btn"] },
  tracking: { targetStepId: "tracking", allowedFrom: ["submit-btn", "tracking"] },
  success: { targetStepId: "success", allowedFrom: ["tracking", "success"] },
};

export function inferTourBreakpointFromWidth(width: number): string {
  if (width >= 1200) return "lg";
  if (width >= 992) return "md";
  if (width >= 768) return "sm";
  return "xs";
}
