import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import type {
  AgentTokenPriceHistoryManifest,
  AgentTokenPriceHistoryManifestAgent,
} from "../../offline/mock_data/agentTokenPriceHistory.types";
import {
  AGENT_TOKEN_PRICE_DATA_BASE_URL,
  fetchAgentTokenManifest,
  getCachedAgentTokenManifest,
  getManifestAgentByBaseAsset,
  getManifestAgentByCatalogId,
  getManifestAgentByTicker,
  resolveCatalogAgentId,
  type ResolveCatalogAgentIdInput,
} from "../sdk/api/agentTokenPrice/agentTokenPriceClient";

type AgentTokenManifestContextValue = {
  manifest: AgentTokenPriceHistoryManifest | null;
  agents: AgentTokenPriceHistoryManifestAgent[];
  loading: boolean;
  error: string | null;
  baseUrl: string;
  refresh: () => Promise<void>;
  getAgentByCatalogId: (catalogAgentId: string) => AgentTokenPriceHistoryManifestAgent | undefined;
  getAgentByTicker: (ticker: string) => AgentTokenPriceHistoryManifestAgent | undefined;
  getAgentByBaseAsset: (baseAsset: string) => AgentTokenPriceHistoryManifestAgent | undefined;
  resolveCatalogAgentId: (input: ResolveCatalogAgentIdInput) => string | null;
};

const AgentTokenManifestContext = createContext<AgentTokenManifestContextValue | null>(
  null,
);

export function AgentTokenManifestProvider({
  children,
  enabled = true,
  baseUrl = AGENT_TOKEN_PRICE_DATA_BASE_URL,
}: {
  children: ReactNode;
  enabled?: boolean;
  baseUrl?: string;
}): JSX.Element {
  const [manifest, setManifest] = useState<AgentTokenPriceHistoryManifest | null>(
    () => getCachedAgentTokenManifest(),
  );
  const [loading, setLoading] = useState(enabled && !getCachedAgentTokenManifest());
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!enabled) {
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const next = await fetchAgentTokenManifest(baseUrl);
      setManifest(next);
    } catch (err: unknown) {
      setError(
        err instanceof Error ? err.message : "Failed to load agent token manifest",
      );
    } finally {
      setLoading(false);
    }
  }, [baseUrl, enabled]);

  useEffect(() => {
    void load();
  }, [load]);

  const value = useMemo<AgentTokenManifestContextValue>(() => ({
    manifest,
    agents: manifest?.agents ?? [],
    loading,
    error,
    baseUrl,
    refresh: load,
    getAgentByCatalogId: (catalogAgentId) =>
      manifest ? getManifestAgentByCatalogId(manifest, catalogAgentId) : undefined,
    getAgentByTicker: (ticker) =>
      manifest ? getManifestAgentByTicker(manifest, ticker) : undefined,
    getAgentByBaseAsset: (baseAsset) =>
      manifest ? getManifestAgentByBaseAsset(manifest, baseAsset) : undefined,
    resolveCatalogAgentId: (input) => resolveCatalogAgentId(manifest, input),
  }), [manifest, loading, error, baseUrl, load]);

  return (
    <AgentTokenManifestContext.Provider value={value}>
      {children}
    </AgentTokenManifestContext.Provider>
  );
}

export function useAgentTokenManifest(): AgentTokenManifestContextValue {
  const context = useContext(AgentTokenManifestContext);
  if (!context) {
    return {
      manifest: getCachedAgentTokenManifest(),
      agents: getCachedAgentTokenManifest()?.agents ?? [],
      loading: false,
      error: null,
      baseUrl: AGENT_TOKEN_PRICE_DATA_BASE_URL,
      refresh: async () => {},
      getAgentByCatalogId: (catalogAgentId) => {
        const cached = getCachedAgentTokenManifest();
        return cached ? getManifestAgentByCatalogId(cached, catalogAgentId) : undefined;
      },
      getAgentByTicker: (ticker) => {
        const cached = getCachedAgentTokenManifest();
        return cached ? getManifestAgentByTicker(cached, ticker) : undefined;
      },
      getAgentByBaseAsset: (baseAsset) => {
        const cached = getCachedAgentTokenManifest();
        return cached ? getManifestAgentByBaseAsset(cached, baseAsset) : undefined;
      },
      resolveCatalogAgentId: (input) =>
        resolveCatalogAgentId(getCachedAgentTokenManifest(), input),
    };
  }
  return context;
}
