import { type ReactNode, createElement, Fragment } from "react";

/** Highlights the first case-insensitive query substring in yellow via `.intent-mention-match`. */
export function highlightQueryMatch(text: string, query: string): ReactNode {
  const q = query.trim();
  if (!q) return text;

  const upperText = text.toUpperCase();
  const upperQuery = q.toUpperCase();
  const start = upperText.indexOf(upperQuery);
  if (start < 0) return text;

  const end = start + q.length;
  return createElement(
    Fragment,
    null,
    text.slice(0, start),
    createElement(
      "mark",
      { className: "intent-mention-match" },
      text.slice(start, end),
    ),
    text.slice(end),
  );
}
