import React from "react";
import { formatRelativeSeconds } from "./useHighATickerMetrics";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";

export interface FleetHeartbeatProps {
  lastActionMs: number | null;
  isConnected: boolean;
}

function FleetHeartbeat({
  lastActionMs,
  isConnected,
}: FleetHeartbeatProps): JSX.Element {
  const ago = formatRelativeSeconds(lastActionMs);
  const live = isConnected && lastActionMs != null;

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.highAFleetHeartbeat}>
      <span
        className={`high-a-heartbeat${live ? " high-a-heartbeat--live" : ""}`}
      >
        <span className="high-a-heartbeat-icon" aria-hidden>
          ♥
        </span>
        <span className="high-a-heartbeat-label">
          {live ? "swarm live" : "swarm idle"}
        </span>
        {lastActionMs != null ? (
          <span className="high-a-heartbeat-ago">· {ago}</span>
        ) : null}
      </span>
    </BubbleTip>
  );
}

export default React.memo(FleetHeartbeat);
