import {
  useImperativeHandle,
  forwardRef,
  useMemo,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
} from "react";
import { toast } from "sonner";
import { createErrorCopyAction } from "../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  type ToastId,
} from "../ui/toastTask";
import { useTradeOperation } from "../../hooks";
import { useMarkets } from "../../hooks/useMarkets";
import { useTradePrice } from "../../hooks/useTradePrice";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { fromSatoshi } from "../../sdk";
import { formatSizeInputValue } from "../../sdk/utils/math";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import { TradeOperationInfoPanel } from "./TradeOperationInfoPanel";
import { AgentIntentSection } from "./AgentIntentSection";
import { resolveBaseAsset } from "./intentExamples";
import {
  IntentWindowModal,
  useIntentWindowShortcut,
} from "../intentwindow";
import {
  applyAgentToResolution,
  applyAssetToResolution,
  canDeploy,
  getDeployButtonLabel,
  getResolutionSummary,
  resolveIntent,
  type IntentResolution,
  type ResolvedAgent,
  type ResolvedAsset,
} from "../intentwindow/intentResolution";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import { getDisplayMarginType } from "../../sdk/types/data";
import {
  DEFAULT_BASE_URL,
  DEFAULT_MNEMONIC,
  LEVERAGE_MIN,
  LEVERAGE_MAX,
  SIZE_PERCENT_MIN,
  SIZE_PERCENT_MAX,
  SIZE_PERCENT_STEP,
  PRICE_STEP,
  PRICE_MIN,
  CURRENCY_MIN_FRACTION_DIGITS,
  SIZE_DISPLAY_DECIMALS,
  ORDER_TYPE_MARKET,
  ORDER_TYPE_LIMIT,
  ORDER_TYPE_SCALE,
  ORDER_TYPE_TWAP,
  ORDER_TYPE_STOP_LIMIT,
  ORDER_TYPE_STOP_MARKET,
  MARGIN_MODE_CROSS,
  MARGIN_MODE_ISOLATED,
  
} from "../../constants";
import { useSubscription } from "../../context/SubscriptionContext";
import { useAgentTaskStore } from "../../store/agentTaskStore";
import { useTradingAgentStore } from "../../store/tradingAgentStore";
import "./tradepanel.css";

export interface TradeOpClassicRef {
  leverage: number;
  setLeverage: (leverage: number) => void;
  calculateMaxRatio: (tempLeverage: number) => string;
  changeLeverage: (
    newLeverage: number,
    options?: {
      bucketId?: string;
      leverageType?: string;
      reason?: string;
    },
  ) => Promise<void>;
  setPrice: (price: number | string) => void;
  setSizeInput: (size: number) => void;
  getSizeInput: () => number;
  getAvailableTradeAmount: () => number;
}

type TradeMode = "manual" | "agent";

interface TradeOpClassicProps {
  baseURL?: string;
  mnemonic?: string;
  marketId?: string;
  marketSymbol?: string; // Optional - will be auto-derived from selected market if not provided
  selectedBucketBalance?: number; // Balance from selected bucket (nominalValue)
  selectedBucketId?: string | null; // Bucket ID for display in label
  onLeverageClick?: () => void; // Callback when leverage badge is clicked
  onNumberCalculatorClick?: () => void; // Callback when number calculator icon is clicked
  authToken?: string; // Auth token for API calls
  walletAddress?: string; // Wallet address for fetching bucket data
}

const TradeOpClassic = forwardRef<TradeOpClassicRef, TradeOpClassicProps>(
  function TradeOpClassic(
    {
      baseURL = DEFAULT_BASE_URL,
      mnemonic = DEFAULT_MNEMONIC,
      marketId,
      marketSymbol,
      selectedBucketBalance,
      selectedBucketId,
      onLeverageClick,
      onNumberCalculatorClick,
      authToken,
      walletAddress,
    },
    ref,
  ): JSX.Element {
    const { client: subscriptionClient } = useSubscription();
    // Get selected market info from useMarkets hook
    const { selectedMarketId, selectedMarketSymbol, selectedMarket, markets } = useMarkets({
      baseURL,
      autoFetchMarkets: true,
    });
    const { agents } = useTradingAgents();

    // Determine the market ID to use (prop takes precedence, then selectedMarketId)
    const effectiveMarketId = marketId || selectedMarketId || "";

    // Derive market symbol: prop > selectedMarketSymbol > fallback
    const effectiveMarketSymbol = marketSymbol || selectedMarketSymbol || "";

    // Get trade price from useTradePrice hook for market orders
    const { lastPrice: tradePriceData } = useTradePrice({
      subscriptionClient,
      baseURL,
      marketId: effectiveMarketId,
    });

    // Extract trade price for market orders
    const tradePrice = tradePriceData?.price || 0;
    // Ref to store the loading toast ID so we can dismiss it later
    const loadingToastIdRef = useRef<ToastId | null>(null);
    // Ref to store the leverage change loading toast ID
    const leverageLoadingToastIdRef = useRef<ToastId | null>(null);
    // Ref to track if we're currently changing leverage (to distinguish from order results)
    const isChangingLeverageRef = useRef<boolean>(false);

    const [tradeMode, setTradeMode] = useState<TradeMode>("agent");
    const [agentIntentText, setAgentIntentText] = useState("");
    const [agentIntentValidated, setAgentIntentValidated] = useState(false);
    const [intentResolution, setIntentResolution] =
      useState<IntentResolution | null>(null);
    const [intentWindowOpen, setIntentWindowOpen] = useState(false);
    const pendingEdit = useAgentTaskStore((s) => s.pendingEdit);
    const setPendingEdit = useAgentTaskStore((s) => s.setPendingEdit);
    const addAgentTask = useAgentTaskStore((s) => s.addTask);
    const resolveDefaultAgentId = useTradingAgentStore(
      (s) => s.resolveDefaultAgentId,
    );

    useEffect(() => {
      if (!pendingEdit) return;
      setTradeMode("agent");
      setAgentIntentText(pendingEdit.description);
      const resolution = resolveIntent({
        text: pendingEdit.description,
        agents,
        markets,
        context: {
          defaultAgentId: resolveDefaultAgentId(),
          defaultMarketId: effectiveMarketId || null,
          chartMarketId: effectiveMarketId || null,
        },
      });
      setIntentResolution(resolution);
      setAgentIntentValidated(resolution.deployState !== "resolve");
      setPendingEdit(null);
    }, [
      pendingEdit,
      setPendingEdit,
      agents,
      markets,
      resolveDefaultAgentId,
      effectiveMarketId,
    ]);

    const baseAsset = resolveBaseAsset(
      selectedMarket,
      effectiveMarketSymbol || selectedMarketSymbol,
    );

    const runIntentResolution = useCallback(
      (text: string): IntentResolution =>
        resolveIntent({
          text,
          agents,
          markets,
          context: {
            defaultAgentId: resolveDefaultAgentId(),
            defaultMarketId: effectiveMarketId || null,
            chartMarketId: effectiveMarketId || null,
          },
        }),
      [agents, markets, resolveDefaultAgentId, effectiveMarketId],
    );

    const handleAgentIntentTextChange = useCallback((value: string) => {
      setAgentIntentText(value);
      setAgentIntentValidated(false);
      setIntentResolution(null);
    }, []);

    const handleAgentIntentValidate = useCallback(() => {
      const trimmed = agentIntentText.trim();
      if (!trimmed) {
        toast.error("Intent required", {
          description: "Enter a trade intent before parsing.",
        });
        return;
      }
      setAgentIntentText(trimmed);
      const resolution = runIntentResolution(trimmed);
      setIntentResolution(resolution);
      setAgentIntentValidated(resolution.deployState !== "resolve");
      if (resolution.deployState === "resolve") {
        const slot =
          resolution.blockingSlot === "agent" ? "agent" : "market";
        toast.error(`Resolve ${slot}`, {
          description: `Pick a ${slot} before deploying.`,
        });
        return;
      }
      toast.success("Intent validated", {
        description: getResolutionSummary(resolution),
      });
    }, [agentIntentText, runIntentResolution]);

    const handleValidateIntentText = useCallback(
      (text: string, instanceId?: string | null) => {
        const trimmed = text.trim();
        if (!trimmed) {
          toast.error("Intent required", {
            description: "Enter a trade intent before parsing.",
          });
          return;
        }
        setAgentIntentText(trimmed);
        const resolution = runIntentResolution(trimmed);
        setIntentResolution(resolution);
        setAgentIntentValidated(resolution.deployState !== "resolve");
        if (resolution.deployState !== "resolve") {
          toast.success("Intent validated", {
            description: getResolutionSummary(resolution),
          });
        }
        return instanceId;
      },
      [runIntentResolution],
    );

    const openIntentWindow = useCallback(() => {
      setTradeMode("agent");
      setIntentWindowOpen(true);
    }, []);

    const openIntentWindowIfClosed = useCallback(() => {
      if (!intentWindowOpen) openIntentWindow();
    }, [intentWindowOpen, openIntentWindow]);

    useIntentWindowShortcut({
      enabled: true,
      isOpen: intentWindowOpen,
      onOpen: openIntentWindow,
    });

    const handleResolveAgent = useCallback((agent: ResolvedAgent) => {
      setIntentResolution((prev) => {
        if (!prev) return prev;
        const next = applyAgentToResolution(prev, agent);
        setAgentIntentValidated(next.deployState !== "resolve");
        return next;
      });
    }, []);

    const handleResolveAsset = useCallback(
      (asset: ResolvedAsset) => {
        setIntentResolution((prev) => {
          if (!prev) return prev;
          const next = applyAssetToResolution(
            prev,
            asset,
            effectiveMarketId || null,
          );
          setAgentIntentValidated(next.deployState !== "resolve");
          return next;
        });
      },
      [effectiveMarketId],
    );

    const deployButtonLabel = intentResolution
      ? getDeployButtonLabel(intentResolution.deployState)
      : getDeployButtonLabel("review");

    const deployDisabled = !agentIntentText.trim() || !canDeploy(intentResolution);

    // Get bucket collections data if walletAddress and authToken are provided
    const { collections, spotWalletBalance } = useBucketCollections({
      subscriptionClient,
      baseURL,
      walletAddress: walletAddress || "",
      authToken: authToken || "",
      useWebSocket: !!walletAddress && !!authToken, // Only use WebSocket if we have both
    });

    // Find the selected bucket from collections
    const selectedBucket = useMemo(() => {
      if (!selectedBucketId || !collections.length) return null;
      return (
        collections.find(
          (collection) => collection.bucketId === selectedBucketId,
        ) || null
      );
    }, [collections, selectedBucketId]);

    const {
      orderType,
      setOrderType,
      fundPercent,
      sizeInput,
      price,
      leverage,
      marginMode,
      availableBalance,
      currentPrice,
      isReady,
      loading,
      result,
      setFundPercent,
      setSizeInput,
      setPrice,
      setMarginMode,
      setLeverage,
      placeBuyOrder,
      placeSellOrder,
      changeLeverage: changeLeverageAPI,
      calculateValue,
      calculateMargin,
      calculateSizeUSD,
      getOrderPrice,
      getAvailableTradeAmount,
    } = useTradeOperation({
      baseURL,
      mnemonic,
      marketId: effectiveMarketId,
      marketSymbol: effectiveMarketSymbol,
      selectedBucketBalance,
      selectedBucketId: selectedBucketId || undefined, // Pass bucket ID for order placement
      tradePrice, // Pass trade price for market orders
    });

    // Memoize calculations from hook - depend on actual state values for proper updates
    const orderPrice = useMemo(
      () => getOrderPrice(),
      [getOrderPrice, orderType, price, currentPrice],
    );
    const availableTradeAmount = useMemo(
      () => getAvailableTradeAmount(),
      [getAvailableTradeAmount, availableBalance, leverage],
    );
    const value = useMemo(
      () => calculateValue(),
      [
        calculateValue,
        sizeInput,
        fundPercent,
        availableBalance,
        orderPrice,
        leverage,
      ],
    );
    const margin = useMemo(
      () => calculateMargin(),
      [calculateMargin, leverage, value],
    );

    // Convert value and margin from satoshi to decimal for display
    const valueDecimal = useMemo(() => {
      return fromSatoshi(String(value));
    }, [value]);

    const marginDecimal = useMemo(() => {
      return fromSatoshi(String(margin));
    }, [margin]);

    // Memoize current price display
    const currentPriceDisplay = useMemo(
      () => currentPrice.toFixed(CURRENCY_MIN_FRACTION_DIGITS),
      [currentPrice],
    );

    // Automatically switch margin mode based on selected bucket
    useEffect(() => {
      if (selectedBucket) {
        const bucketMarginType = getDisplayMarginType(selectedBucket);
        if (
          bucketMarginType === MARGIN_MODE_CROSS ||
          bucketMarginType === MARGIN_MODE_ISOLATED
        ) {
          setMarginMode(bucketMarginType);
        }
      }
    }, [selectedBucket, setMarginMode]);



    const handleOrderTypeMarket = useCallback(() => {
      setOrderType(ORDER_TYPE_MARKET);
    }, [setOrderType]);

    const handleOrderTypeLimit = useCallback(() => {
      setOrderType(ORDER_TYPE_LIMIT);
    }, [setOrderType]);

    const handleFundPercentIncrease = useCallback(() => {
      setFundPercent(
        Math.min(SIZE_PERCENT_MAX, fundPercent + SIZE_PERCENT_STEP),
      );
    }, [fundPercent, setFundPercent]);

    const handleFundPercentDecrease = useCallback(() => {
      setFundPercent(
        Math.max(SIZE_PERCENT_MIN, fundPercent - SIZE_PERCENT_STEP),
      );
    }, [fundPercent, setFundPercent]);

    const handlePriceChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        setPrice(parseFloat(e.target.value));
      },
      [setPrice],
    );

    // Track if size input is focused and the value while user is typing
    const [isSizeInputFocused, setIsSizeInputFocused] = useState(false);
    const [sizeInputDisplayValue, setSizeInputDisplayValue] =
      useState<string>("");

    const handleSizeInputChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        const inputValue = e.target.value;
        // Store what user is typing (allows partial input like "1." or "1.12")
        setSizeInputDisplayValue(inputValue);
        // Update the actual sizeInput value (for calculations)
        const val = parseFloat(inputValue);
        const roundedVal = isNaN(val) ? 0 : Math.round(val * 1000000) / 1000000;
        setSizeInput(roundedVal); // This will update fundPercent via the hook
      },
      [setSizeInput],
    );

    const handleSizeInputFocus = useCallback(() => {
      setIsSizeInputFocused(true);
      // When focusing, initialize with current formatted value
      setSizeInputDisplayValue(formatSizeInputValue(sizeInput));
    }, [sizeInput]);

    const handleSizeInputBlur = useCallback(() => {
      setIsSizeInputFocused(false);
      // When blurring, parse and format the final value
      const val = parseFloat(sizeInputDisplayValue);
      //const roundedVal = isNaN(val) ? 0 : Math.round(val * 1000000) / 1000000;
      setSizeInput(val);
      // Clear display value so it will use formatted sizeInput when not focused
      setSizeInputDisplayValue("");
    }, [sizeInputDisplayValue, setSizeInput]);

    // Handle buy order with immediate toast notification
    const handleBuyOrder = useCallback(() => {
      const loadingId = toastLoading("Submit transaction...", {
        description: "Placing buy order",
      });
      loadingToastIdRef.current = loadingId;
      placeBuyOrder();
    }, [placeBuyOrder]);

    // Handle sell order with immediate toast notification
    const handleSellOrder = useCallback(() => {
      const loadingId = toastLoading("Submit transaction...", {
        description: "Placing sell order",
      });
      loadingToastIdRef.current = loadingId;
      placeSellOrder();
    }, [placeSellOrder]);

    const handleDeployToAgent = useCallback(() => {
      const trimmed = agentIntentText.trim();
      if (!trimmed) {
        toast.error("Intent required", {
          description: "Enter a trade intent before deploying.",
        });
        return;
      }

      if (!canDeploy(intentResolution)) {
        toast.error("Resolve before deploy", {
          description: "Parse & validate, then resolve any ambiguous slots.",
        });
        return;
      }

      const agentId =
        intentResolution?.agent.value?.id ?? resolveDefaultAgentId();
      const marketId =
        intentResolution?.asset.value?.marketId ??
        (effectiveMarketId || null);

      addAgentTask({
        agentId,
        description: trimmed,
        status: "pending",
        marketId,
        bucketId:
          selectedBucketId && selectedBucketId !== "--"
            ? selectedBucketId
            : null,
        trigger: "Awaiting agent evaluation",
        eta: null,
      });

      setAgentIntentText("");
      setAgentIntentValidated(false);
      setIntentResolution(null);
      toast.success("Deployed to autonomous agent", {
        description: "Task added to Agent Tasks tab.",
      });
    }, [
      agentIntentText,
      intentResolution,
      addAgentTask,
      resolveDefaultAgentId,
      effectiveMarketId,
      selectedBucketId,
    ]);

    // Handle leverage change with API call
    const handleChangeLeverage = useCallback(
      async (
        newLeverage: number,
        options?: {
          bucketId?: string;
          leverageType?: string;
          reason?: string;
        },
      ) => {
        // Set flag to indicate we're changing leverage
        isChangingLeverageRef.current = true;

        // Show loading toast
        const loadingId = toastLoading("Changing leverage...", {
          description: `Updating leverage to ${newLeverage}x`,
        });
        leverageLoadingToastIdRef.current = loadingId;

        try {
          // Determine leverage type from margin mode if not provided
          const leverageType =
            options?.leverageType ||
            (marginMode === MARGIN_MODE_CROSS ? "cross" : "isolated");

          // Use selectedBucketId if bucketId is not provided
          const bucketId = options?.bucketId || selectedBucketId || "";

          await changeLeverageAPI(newLeverage, {
            ...options,
            bucketId,
            leverageType,
          });

          // The result will be handled by the useEffect below
        } catch (error) {
          // Reset flag on error
          isChangingLeverageRef.current = false;

          const errorMessage =
            error instanceof Error ? error.message : "Unknown error";
          toastCompleteError(loadingId, "Leverage Change Failed", {
            description: errorMessage,
            action: createErrorCopyAction(errorMessage),
          });
          leverageLoadingToastIdRef.current = null;
        }
      },
      [changeLeverageAPI, marginMode, selectedBucketId],
    );

    // Expose leverage and setLeverage via ref
    useImperativeHandle(
      ref,
      () => ({
        leverage,
        setLeverage,
        calculateMaxRatio: (tempLeverage: number) => {
          const sizeUSD = calculateSizeUSD();
          const orderValueAtLeverage = sizeUSD;
          return availableBalance > 0 && orderValueAtLeverage > 0
            ? (orderValueAtLeverage / availableBalance).toFixed(
                CURRENCY_MIN_FRACTION_DIGITS,
              )
            : tempLeverage.toFixed(CURRENCY_MIN_FRACTION_DIGITS);
        },
        changeLeverage: handleChangeLeverage,
        setPrice: (price: number | string) => {
          const numPrice =
            typeof price === "number" ? price : parseFloat(price);
          if (!isNaN(numPrice)) {
            setPrice(numPrice);
          }
        },
        setSizeInput: (size: number) => {
          setSizeInput(size);
        },
        getSizeInput: () => sizeInput,
        getAvailableTradeAmount: () => availableTradeAmount,
      }),
      [
        leverage,
        setLeverage,
        calculateSizeUSD,
        getOrderPrice,
        availableBalance,
        handleChangeLeverage,
        setPrice,
        setSizeInput,
        sizeInput,
        availableTradeAmount,
      ],
    );

    // Show toast notifications when result changes (handles both orders and leverage changes)
    useEffect(() => {
      if (!result) return;

      // Check if this is a leverage change result
      if (isChangingLeverageRef.current) {
        // Reset flag
        isChangingLeverageRef.current = false;

        const leverageId = leverageLoadingToastIdRef.current;
        leverageLoadingToastIdRef.current = null;

        if (leverageId != null) {
          if (result.success) {
            const description = result.orderId
              ? `Transaction: ${result.orderId}`
              : result.message || "Leverage changed successfully";
            toastCompleteSuccess(leverageId, "Leverage Changed Successfully", {
              description,
            });
          } else if (result.error) {
            toastCompleteError(leverageId, "Leverage Change Failed", {
              description: result.error,
              action: createErrorCopyAction(result.error || ""),
            });
          }
        }
      } else {
        const orderId = loadingToastIdRef.current;
        loadingToastIdRef.current = null;

        if (orderId != null) {
          if (result.success) {
            const description = result.orderId
              ? `Order ID: ${result.orderId}`
              : result.message || "Order placed successfully";
            toastCompleteSuccess(orderId, "Order Placed Successfully", {
              description,
            });
          } else if (result.error) {
            toastCompleteError(orderId, "Order Failed", {
              description: result.error,
              action: createErrorCopyAction(result.error || ""),
            });
          }
        }
      }
    }, [result]);

    return (
      <div className="component">
        <div className="trade-op-mode-selector">
          <button
            type="button"
            onClick={() => setTradeMode("manual")}
            className={`btn-toggle ${tradeMode === "manual" ? "active" : ""}`}
          >
            Manual
          </button>
          <button
            type="button"
            onClick={() => setTradeMode("agent")}
            className={`btn-toggle ${tradeMode === "agent" ? "active" : ""}`}
          >
            Intent
          </button>
        </div>
        {tradeMode === "manual" && (
          <>
        {/* Trade Configuration Panel */}
        <div className="trade-op-config">
          <div className="trade-op-badge">
            <span className="trade-op-badge-label">{marginMode}</span>
            <span className="trade-op-info-icon">i</span>
          </div>
          <div
            className="trade-op-badge"
            onClick={onLeverageClick}
            style={{ cursor: "pointer" }}
          >
            <span className="trade-op-badge-label">{leverage}x</span>
            <span className="trade-op-info-icon">i</span>
          </div>
        </div>
        {/* Order Type Selection */}
        <div className="trade-op-order-type-selector">
          <button
            onClick={handleOrderTypeMarket}
            className={`btn-toggle ${orderType === ORDER_TYPE_MARKET ? "active" : ""}`}
          >
            MARKET
          </button>
          <button
            onClick={handleOrderTypeLimit}
            className={`btn-toggle ${orderType === ORDER_TYPE_LIMIT ? "active" : ""}`}
          >
            LIMIT
          </button>

          <button
            onClick={handleOrderTypeLimit}
            className={`btn-toggle ${orderType === "menu-more" ? "active" : ""}`}
          >
            ADV.
          </button>

        </div>
        {/* Limit Price Input (only for limit orders) */}
        {orderType === ORDER_TYPE_LIMIT && (
          <div className="trade-op-form-group">
            <div className="trade-op-form-row">
              <label htmlFor="price" className="trade-op-label">
                Price:
              </label>
              <input
                id="price"
                type="number"
                className="form-input trade-op-input"
                value={price}
                onChange={handlePriceChange}
                placeholder={currentPriceDisplay}
                step={PRICE_STEP}
                min={PRICE_MIN}
              />
            </div>
          </div>
        )}

        {/* Order Size Input and Slider */}
        <div className="trade-op-form-group">
          {/* Size controls - on a new row */}
          <div className="trade-op-form-row" style={{ marginBottom: "0.5rem" }}>
            <label htmlFor="size" className="trade-op-label">
              Size:
            </label>
            <span className="trade-op-icon" onClick={onNumberCalculatorClick}>
              <img src="cal.svg" />
            </span>
            <div className="trade-op-size-controls">
              <input
                id="size"
                type="number"
                step="0.000001"
                value={isSizeInputFocused ? sizeInputDisplayValue : sizeInput}
                onChange={handleSizeInputChange}
                onFocus={handleSizeInputFocus}
                onBlur={handleSizeInputBlur}
                placeholder="0"
                min={PRICE_MIN}
                max={availableTradeAmount}
                className="form-input trade-op-input"
              />
              <div className="trade-op-size-buttons">
                <button
                  onClick={handleFundPercentIncrease}
                  className="btn-small"
                >
                  ▲
                </button>
                <button
                  onClick={handleFundPercentDecrease}
                  className="btn-small"
                >
                  ▼
                </button>
              </div>
            </div>
          </div>
          <FilledRangeSlider
            variant="brand"
            min={SIZE_PERCENT_MIN}
            max={SIZE_PERCENT_MAX}
            value={fundPercent}
            onChange={setFundPercent}
            step={SIZE_PERCENT_STEP}
          />
          <div className="trade-op-slider-labels">
            <span>0</span>
            <span>20</span>
            <span>40</span>
            <span>60</span>
            <span>80</span>
            <span>100</span>
          </div>
        </div>

        {/* Buy/Sell Action Panels */}
        <div className="trade-op-action-panel">
          {/* Buy Panel */}
          <div>
            <div className="trade-op-panel-title buy">LONG</div>
            <div className="trade-op-panel-size">
              {sizeInput.toFixed(3)}/100.000
            </div>
            <button
              onClick={handleBuyOrder}
              disabled={loading || !isReady || value <= 0}
              className="btn-buy terminal-execution-button button-buy-long"
            >
              {loading ? "PLACING..." : "BUY LONG"}
            </button>
            <div className="trade-op-panel-details">
              <div>Value {valueDecimal.toFixed(2)}</div>
              <div>Margin {marginDecimal.toFixed(2)}</div>
            </div>
          </div>

          {/* Sell Panel */}
          <div>
            <div className="trade-op-panel-title sell">SHORT</div>
            <div className="trade-op-panel-size">
              {sizeInput.toFixed(3)}/100.000
            </div>
            <button
              onClick={handleSellOrder}
              disabled={loading || !isReady || value <= 0}
              className="btn-sell terminal-execution-button button-sell-short"
            >
              {loading ? "PLACING..." : "SELL SHORT"}
            </button>
            <div className="trade-op-panel-details">
              <div>
                Value {valueDecimal.toFixed(CURRENCY_MIN_FRACTION_DIGITS)}
              </div>
              <div>
                Margin {marginDecimal.toFixed(CURRENCY_MIN_FRACTION_DIGITS)}
              </div>
            </div>
          </div>
        </div>
        <TradeOperationInfoPanel
          spotWalletBalance={spotWalletBalance}
          collections={collections}
          selectedBucketId={selectedBucketId}
          selectedBucket={selectedBucket}
        />
          </>
        )}
        {tradeMode === "agent" && (
          <AgentIntentSection
            selectedMarket={selectedMarket}
            selectedMarketSymbol={effectiveMarketSymbol || selectedMarketSymbol}
            spotWalletBalance={spotWalletBalance}
            collections={collections}
            selectedBucketId={selectedBucketId}
            selectedBucket={selectedBucket}
            agentIntentText={agentIntentText}
            agentIntentValidated={agentIntentValidated}
            onAgentIntentTextChange={handleAgentIntentTextChange}
            onParseValidate={handleAgentIntentValidate}
            onValidateIntentText={handleValidateIntentText}
            onDeployToAgent={handleDeployToAgent}
            isDesktop
            agents={agents}
            markets={markets}
            intentResolution={intentResolution}
            deployButtonLabel={deployButtonLabel}
            deployDisabled={deployDisabled}
            onResolveAgent={handleResolveAgent}
            onResolveAsset={handleResolveAsset}
            onOpenIntentWindow={openIntentWindowIfClosed}
          />
        )}
        <IntentWindowModal
          isOpen={intentWindowOpen}
          onClose={() => setIntentWindowOpen(false)}
          text={agentIntentText}
          onTextChange={handleAgentIntentTextChange}
          validated={agentIntentValidated}
          onValidate={handleAgentIntentValidate}
          onDeploy={handleDeployToAgent}
          baseAsset={baseAsset}
          marketSymbol={effectiveMarketSymbol || selectedMarketSymbol || undefined}
          marginMode={marginMode}
          agents={agents}
          markets={markets}
          intentResolution={intentResolution}
          deployButtonLabel={deployButtonLabel}
          deployDisabled={deployDisabled}
          onResolveAgent={handleResolveAgent}
          onResolveAsset={handleResolveAsset}
        />
      </div>
    );
  },
);

export type TradeOpClassicComponent = typeof TradeOpClassic;

export default TradeOpClassic;
