import { DEPOSIT_TOUR_STORAGE_KEY } from "../../mormv1/tutorials/deposit-tour/constants";

export function hasSeenDepositTour(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(DEPOSIT_TOUR_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markDepositTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(DEPOSIT_TOUR_STORAGE_KEY, "1");
  } catch {
    // ignore
  }
}

export function clearDepositTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(DEPOSIT_TOUR_STORAGE_KEY);
  } catch {
    // ignore
  }
}
