import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AreaSeries,
  createChart,
  type IChartApi,
  type ISeriesApi,
  type LineData,
  type MouseEventParams,
  type UTCTimestamp,
} from "lightweight-charts";

import { formatPercent } from "../index/indexFormat";
import { sanitizeLineDataForChart } from "../../utils/portfolioChartData";
import {
  COMPACT_CHART_HEIGHT,
  COMPACT_CHART_NEGATIVE,
  COMPACT_CHART_POSITIVE,
  COMPACT_CHART_WIDTH,
  createCompactSparklineAreaOptions,
  createCompactSparklineChartOptions,
} from "./compactChartTheme";
import type { CompactMetricTone } from "./types";
import { metricToneClassName } from "./types";

export interface CompactMiniLineChartProps {
  data: LineData<UTCTimestamp>[];
  tone?: CompactMetricTone;
  color?: string;
  className?: string;
  formatValue?: (value: number) => string;
}

interface ChartTooltipState {
  x: number;
  y: number;
  text: string;
  tone: CompactMetricTone;
}

function resolveLineColor(
  tone: CompactMetricTone,
  color?: string,
): string {
  if (color) return color;
  if (tone === "positive") return COMPACT_CHART_POSITIVE;
  if (tone === "negative") return COMPACT_CHART_NEGATIVE;
  return COMPACT_CHART_POSITIVE;
}

function CompactMiniLineChart({
  data,
  tone = "neutral",
  color,
  className = "",
  formatValue = formatPercent,
}: CompactMiniLineChartProps): JSX.Element {
  const wrapRef = useRef<HTMLDivElement>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Area"> | null>(null);
  const formatValueRef = useRef(formatValue);
  const toneRef = useRef(tone);

  const [tooltip, setTooltip] = useState<ChartTooltipState | null>(null);

  const sanitizedData = useMemo(
    () => sanitizeLineDataForChart(data),
    [data],
  );
  const hasData = sanitizedData.length > 0;
  const lineColor = resolveLineColor(tone, color);

  formatValueRef.current = formatValue;
  toneRef.current = tone;

  useEffect(() => {
    if (!chartContainerRef.current || !hasData) return;

    let chart: IChartApi | null = null;
    let animationFrameId: number | null = null;
    let initAttempts = 0;
    const maxInitAttempts = 60;
    let resizeObserver: ResizeObserver | null = null;

    const resizeChart = () => {
      if (!chartContainerRef.current || !chartRef.current) return;
      const { clientWidth, clientHeight } = chartContainerRef.current;
      if (clientWidth > 0 && clientHeight > 0) {
        chartRef.current.resize(clientWidth, clientHeight);
      }
    };

    const handleCrosshairMove = (param: MouseEventParams) => {
      if (
        !param.point ||
        param.time === undefined ||
        param.point.x < 0 ||
        param.point.y < 0
      ) {
        setTooltip(null);
        return;
      }

      const series = seriesRef.current;
      if (!series) {
        setTooltip(null);
        return;
      }

      const pointData = param.seriesData.get(series);
      if (!pointData || !("value" in pointData)) {
        setTooltip(null);
        return;
      }

      const value = pointData.value;
      if (!Number.isFinite(value)) {
        setTooltip(null);
        return;
      }

      setTooltip({
        x: param.point.x,
        y: param.point.y,
        text: formatValueRef.current(value),
        tone: toneRef.current,
      });
    };

    const initializeChart = () => {
      if (!chartContainerRef.current) return;

      const container = chartContainerRef.current;
      const containerWidth = container.clientWidth || COMPACT_CHART_WIDTH;
      const containerHeight = container.clientHeight || COMPACT_CHART_HEIGHT;

      if (
        (!containerWidth || !containerHeight) &&
        initAttempts < maxInitAttempts
      ) {
        initAttempts += 1;
        animationFrameId = requestAnimationFrame(initializeChart);
        return;
      }

      try {
        chart = createChart(container, createCompactSparklineChartOptions());
        const areaSeries = chart.addSeries(
          AreaSeries,
          createCompactSparklineAreaOptions(lineColor),
        );
        areaSeries.setData(sanitizedData);
        chart.timeScale().fitContent();
        chart.subscribeCrosshairMove(handleCrosshairMove);
        chartRef.current = chart;
        seriesRef.current = areaSeries;
        chart.resize(containerWidth, containerHeight);

        if (typeof ResizeObserver !== "undefined") {
          resizeObserver = new ResizeObserver(resizeChart);
          resizeObserver.observe(container);
        }
      } catch (error) {
        console.error("[CompactMiniLineChart] Error creating chart:", error);
      }
    };

    initializeChart();

    return () => {
      setTooltip(null);
      if (animationFrameId !== null) {
        cancelAnimationFrame(animationFrameId);
      }
      resizeObserver?.disconnect();
      if (chart) {
        try {
          chart.unsubscribeCrosshairMove(handleCrosshairMove);
          chart.remove();
        } catch {
          // ignore
        }
      }
      chartRef.current = null;
      seriesRef.current = null;
    };
  }, [hasData, lineColor]);

  useEffect(() => {
    if (!seriesRef.current || !hasData) return;

    try {
      seriesRef.current.applyOptions(
        createCompactSparklineAreaOptions(lineColor),
      );
      seriesRef.current.setData(sanitizedData);
      chartRef.current?.timeScale().fitContent();
      if (chartContainerRef.current && chartRef.current) {
        const { clientWidth, clientHeight } = chartContainerRef.current;
        if (clientWidth > 0 && clientHeight > 0) {
          chartRef.current.resize(clientWidth, clientHeight);
        }
      }
    } catch (error) {
      console.error("[CompactMiniLineChart] Error updating series:", error);
    }
  }, [hasData, lineColor, sanitizedData]);

  if (!hasData) {
    return (
      <div
        className={`compact-metric-line-chart-wrap ${className}`.trim()}
        aria-hidden
      >
        <div className="compact-metric-line-chart compact-metric-line-chart--empty" />
      </div>
    );
  }

  return (
    <div
      ref={wrapRef}
      className={`compact-metric-line-chart-wrap ${className}`.trim()}
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <div ref={chartContainerRef} className="compact-metric-line-chart" />
      {tooltip ? (
        <div
          className={`compact-metric-line-chart-tooltip ${metricToneClassName(tooltip.tone)}`.trim()}
          style={{ left: tooltip.x, top: tooltip.y }}
          role="tooltip"
        >
          {tooltip.text}
        </div>
      ) : null}
    </div>
  );
}

export default React.memo(CompactMiniLineChart);
