import type { AgentSkill, SkillFile } from "./agentSettingsTypes";

export function parseSkillNameFromFrontmatter(content: string): string | null {
  const match = content.match(/^---[\s\S]*?\nname:\s*(.+?)\s*(?:\n|$)/m);
  if (!match?.[1]) return null;
  const name = match[1].trim().replace(/^["']|["']$/g, "");
  return name.length > 0 ? name : null;
}

export function parseSkillDescriptionFromFrontmatter(content: string): string {
  const match = content.match(/^---[\s\S]*?\ndescription:\s*(.+?)\s*(?:\n|$)/m);
  if (!match?.[1]) return "";
  return match[1].trim().replace(/^["']|["']$/g, "");
}

export function isValidCreateSkillDraft(files: SkillFile[]): boolean {
  const skillMd = files.find((file) => file.path === "SKILL.md" && file.kind === "skill");
  if (!skillMd?.content.trim()) return false;
  const name = parseSkillNameFromFrontmatter(skillMd.content);
  return Boolean(name);
}

export function buildCustomSkillFromFiles(files: SkillFile[]): Omit<AgentSkill, "id" | "installedAt"> | null {
  if (!isValidCreateSkillDraft(files)) return null;
  const skillMd = files.find((file) => file.path === "SKILL.md")!;
  const name = parseSkillNameFromFrontmatter(skillMd.content) ?? "my-skill";
  const description =
    parseSkillDescriptionFromFrontmatter(skillMd.content) || "Custom agent skill";
  return {
    name,
    description,
    files: files.map((file) => ({ ...file })),
    source: "custom",
  };
}

export function isValidMcpServerDraft(input: {
  name: string;
  url: string;
}): boolean {
  return input.name.trim().length > 0 && input.url.trim().length > 0;
}
