import React, { useMemo, useState } from "react";

import type { AgentSettingsState, EnvVarScope } from "./agentSettingsTypes";

export interface AgentEnvVarsTabProps {
  settings: AgentSettingsState;
  onUpsertEnvVar: (
    scope: EnvVarScope,
    key: string,
    value: string,
    existingId?: string,
  ) => boolean;
  onRemoveEnvVar: (envVarId: string) => void;
}

const SCOPE_COPY: Record<
  EnvVarScope,
  { title: string; description: string }
> = {
  agentTools: {
    title: "Agent tool environment",
    description:
      "Available to CLI commands, browser tools, skills, HTTP calls, and MCP config. Not injected into x402 endpoints.",
  },
  x402Endpoints: {
    title: "x402 endpoint environment",
    description:
      "Injected into x402 micropayment endpoints only. Not available to CLI, browser tools, or MCP config.",
  },
};

function AgentEnvVarsTab({
  settings,
  onUpsertEnvVar,
  onRemoveEnvVar,
}: AgentEnvVarsTabProps): JSX.Element {
  const [scope, setScope] = useState<EnvVarScope>("agentTools");
  const [draftKey, setDraftKey] = useState("");
  const [draftValue, setDraftValue] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);

  const scopedVars = useMemo(
    () => settings.envVars.filter((envVar) => envVar.scope === scope),
    [settings.envVars, scope],
  );

  const copy = SCOPE_COPY[scope];

  const handleAdd = () => {
    const ok = onUpsertEnvVar(scope, draftKey, draftValue);
    if (!ok) {
      setFormError("Enter a unique key name.");
      return;
    }
    setDraftKey("");
    setDraftValue("");
    setFormError(null);
    setShowAddForm(false);
  };

  return (
    <>
      <div
        className="agent-settings-inset-toggle"
        role="tablist"
        aria-label="Env var scope"
      >
        <button
          type="button"
          role="tab"
          aria-selected={scope === "agentTools"}
          className={`agent-settings-inset-btn${
            scope === "agentTools" ? " agent-settings-inset-btn--active" : ""
          }`}
          onClick={() => {
            setScope("agentTools");
            setFormError(null);
          }}
        >
          Agent tools
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={scope === "x402Endpoints"}
          className={`agent-settings-inset-btn${
            scope === "x402Endpoints" ? " agent-settings-inset-btn--active" : ""
          }`}
          onClick={() => {
            setScope("x402Endpoints");
            setFormError(null);
          }}
        >
          x402 endpoints
        </button>
      </div>

      <div className="agent-settings-section-header">
        <div>
          <h4 className="agent-settings-section-title">{copy.title}</h4>
          <p className="agent-settings-section-desc">{copy.description}</p>
        </div>
        <button
          type="button"
          className="agent-secondary-btn"
          onClick={() => setShowAddForm((open) => !open)}
        >
          + Add
        </button>
      </div>

      {showAddForm ? (
        <div className="agent-settings-env-add-form">
          <div className="transfer-field-group">
            <label className="terminal-label transfer-field-label">Key</label>
            <input
              type="text"
              className="form-input transfer-select transfer-input"
              placeholder="API_KEY"
              value={draftKey}
              onChange={(e) => setDraftKey(e.target.value)}
            />
          </div>
          <div className="transfer-field-group">
            <label className="terminal-label transfer-field-label">Value</label>
            <input
              type="password"
              className="form-input transfer-select transfer-input"
              placeholder="secret"
              value={draftValue}
              onChange={(e) => setDraftValue(e.target.value)}
              autoComplete="off"
            />
          </div>
          {formError ? (
            <div className="transfer-field-hint transfer-field-error">{formError}</div>
          ) : null}
          <div className="agent-settings-env-add-actions">
            <button
              type="button"
              className="agent-secondary-btn agent-secondary-btn--primary"
              onClick={handleAdd}
              disabled={!draftKey.trim()}
            >
              Add variable
            </button>
            <button
              type="button"
              className="agent-secondary-btn"
              onClick={() => {
                setShowAddForm(false);
                setFormError(null);
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      ) : null}

      {scopedVars.length === 0 ? (
        <div className="agent-settings-empty">
          <p className="agent-settings-empty-title">No environment variables set</p>
          <p className="agent-settings-empty-desc">
            Add API keys and secrets for your agent tools.
          </p>
        </div>
      ) : (
        <div className="agent-settings-env-list">
          {scopedVars.map((envVar) => (
            <div key={envVar.id} className="agent-settings-env-row">
              <span className="agent-settings-env-key">{envVar.key}</span>
              <span className="agent-settings-env-value">
                {envVar.value ? "••••••••" : "(empty)"}
              </span>
              <button
                type="button"
                className="agent-secondary-btn"
                onClick={() => onRemoveEnvVar(envVar.id)}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </>
  );
}

export default AgentEnvVarsTab;
