import type { TradeHistoryRow } from "../sdk/types/data";
import type { PortfolioTimeRange } from "./portfolioChartData";
import { filterPerformanceTrades } from "./portfolioPerformanceMetrics";

export type AgentCompetitivenessTier = "elite" | "strong" | "core" | "lagging";

export interface AgentCompetitivenessRow {
  id: string;
  label: string;
  icon?: string;
  color: string;
  sharpe: number;
  zScore: number;
  percentile: number;
  tier: AgentCompetitivenessTier;
  revenue30d: number;
}

export interface FleetEdgeSummary {
  fleetMedianSharpe: number;
  fleetMeanSharpe: number;
  fleetStdSharpe: number;
  aboveAveragePct: number;
  topAgent: AgentCompetitivenessRow | null;
  tierCounts: Record<AgentCompetitivenessTier, number>;
  agents: AgentCompetitivenessRow[];
}

export const FLEET_EDGE_TIER_COLORS: Record<AgentCompetitivenessTier, string> = {
  elite: "#00ff88",
  strong: "#c8f5a8",
  core: "rgba(255, 255, 255, 0.42)",
  lagging: "#ff4757",
};

export const FLEET_EDGE_TIER_LABELS: Record<AgentCompetitivenessTier, string> = {
  elite: "Elite",
  strong: "Strong",
  core: "Core",
  lagging: "Lagging",
};

const TRADING_DAYS_PER_YEAR = 252;
const MIN_STD = 1e-6;

function dateKey(ms: number): string {
  const date = new Date(ms);
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${date.getUTCFullYear()}-${month}-${day}`;
}

function computeSharpeFromDailyPnl(
  dailyPnls: number[],
  equityBaseline: number,
): number | null {
  if (dailyPnls.length < 2 || equityBaseline <= 0) return null;

  const returns = dailyPnls.map((pnl) => pnl / equityBaseline);
  const mean = returns.reduce((sum, value) => sum + value, 0) / returns.length;
  const variance =
    returns.reduce((sum, value) => sum + (value - mean) ** 2, 0) /
    (returns.length - 1);
  const std = Math.sqrt(variance);

  if (std < MIN_STD) {
    if (mean > 0) return 2;
    if (mean < 0) return -1;
    return 0;
  }

  return (mean / std) * Math.sqrt(TRADING_DAYS_PER_YEAR);
}

function fallbackSharpeFromRevenue(
  revenue30d: number,
  revenues: number[],
): number {
  if (revenues.length === 0) return 1;

  const sorted = [...revenues].sort((a, b) => a - b);
  const min = sorted[0]!;
  const max = sorted[sorted.length - 1]!;
  const range = max - min;
  if (range <= 0) return 1.2;

  const normalized = (revenue30d - min) / range;
  if (revenue30d < 0) {
    return -0.5 + normalized * 0.8;
  }
  return 0.8 + normalized * 1.6;
}

function assignTier(zScore: number): AgentCompetitivenessTier {
  if (zScore >= 1) return "elite";
  if (zScore >= 0.25) return "strong";
  if (zScore >= -0.25) return "core";
  return "lagging";
}

function percentileRank(value: number, values: number[]): number {
  if (values.length <= 1) return 50;
  const below = values.filter((entry) => entry < value).length;
  const equal = values.filter((entry) => entry === value).length;
  return ((below + equal * 0.5) / values.length) * 100;
}

export interface BuildFleetEdgeInput {
  agents: Array<{
    id: string;
    displayName: string;
    icon?: string;
    revenue30d?: number;
  }>;
  trades: TradeHistoryRow[];
  taskAgentMap: Map<string, string>;
  filterAgentIds: string[];
  timeRange: PortfolioTimeRange;
  accountEquity: number;
  agentColor: (index: number) => string;
}

export function buildFleetEdgeMetrics(input: BuildFleetEdgeInput): FleetEdgeSummary {
  const filteredTrades = filterPerformanceTrades(
    input.trades,
    "perps",
    input.timeRange,
    input.filterAgentIds,
    input.taskAgentMap,
  );

  const revenues = input.agents.map((agent) => agent.revenue30d ?? 0);
  const equityPerAgent = Math.max(
    input.accountEquity / Math.max(input.agents.length, 1),
    1,
  );

  const dailyByAgent = new Map<string, Map<string, number>>();
  for (const trade of filteredTrades) {
    if (trade.closedPnl == null) continue;

    const agentId = trade.agentTaskId
      ? input.taskAgentMap.get(trade.agentTaskId)
      : undefined;
    if (!agentId) continue;

    const day = dateKey(trade.time);
    const days = dailyByAgent.get(agentId) ?? new Map<string, number>();
    days.set(day, (days.get(day) ?? 0) + trade.closedPnl);
    dailyByAgent.set(agentId, days);
  }

  const rawSharpes: number[] = [];
  const agentRows = input.agents.map((agent, index) => {
    const dailyMap = dailyByAgent.get(agent.id);
    const dailyPnls = dailyMap ? [...dailyMap.values()] : [];
    const sharpe =
      computeSharpeFromDailyPnl(dailyPnls, equityPerAgent) ??
      fallbackSharpeFromRevenue(agent.revenue30d ?? 0, revenues);
    rawSharpes.push(sharpe);
    return { agent, index, sharpe };
  });

  const mean =
    rawSharpes.reduce((sum, value) => sum + value, 0) /
    Math.max(rawSharpes.length, 1);
  const variance =
    rawSharpes.length > 1
      ? rawSharpes.reduce((sum, value) => sum + (value - mean) ** 2, 0) /
        (rawSharpes.length - 1)
      : 0;
  const std = Math.sqrt(variance);
  const useStd = std < MIN_STD ? 1 : std;

  const sortedForMedian = [...rawSharpes].sort((a, b) => a - b);
  const mid = Math.floor(sortedForMedian.length / 2);
  const fleetMedianSharpe =
    sortedForMedian.length === 0
      ? 0
      : sortedForMedian.length % 2 === 0
        ? (sortedForMedian[mid - 1]! + sortedForMedian[mid]!) / 2
        : sortedForMedian[mid]!;

  const tierCounts: Record<AgentCompetitivenessTier, number> = {
    elite: 0,
    strong: 0,
    core: 0,
    lagging: 0,
  };

  const agents: AgentCompetitivenessRow[] = agentRows.map(
    ({ agent, index, sharpe }) => {
      const zScore = (sharpe - mean) / useStd;
      const tier = assignTier(zScore);
      tierCounts[tier] += 1;
      return {
        id: agent.id,
        label: agent.displayName,
        icon: agent.icon,
        color: input.agentColor(index),
        sharpe,
        zScore,
        percentile: percentileRank(sharpe, rawSharpes),
        tier,
        revenue30d: agent.revenue30d ?? 0,
      };
    },
  );

  agents.sort((a, b) => b.sharpe - a.sharpe);

  const aboveAverage = agents.filter((agent) => agent.sharpe >= mean).length;
  const aboveAveragePct =
    agents.length > 0 ? (aboveAverage / agents.length) * 100 : 0;

  return {
    fleetMedianSharpe,
    fleetMeanSharpe: mean,
    fleetStdSharpe: useStd,
    aboveAveragePct,
    topAgent: agents[0] ?? null,
    tierCounts,
    agents,
  };
}
