import React from "react";

import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import {
  getCompareFocusLoadingRows,
  getCompareFocusMeta,
  type AgentCompareFocus,
} from "./agentCompareFocus";
import "./agent.css";

const COMPARE_LOADING_MESSAGE = "Loading compare data…";

export interface AgentCompareMatrixTableLoadingProps {
  compareFocus: AgentCompareFocus;
  columnCount: number;
  showAddSlot: boolean;
}

function AgentCompareMatrixAddSpacer(): JSX.Element {
  return (
    <th scope="col" className="agent-compare-matrix-add-spacer" aria-hidden />
  );
}

function AgentCompareMatrixAddSpacerCell(): JSX.Element {
  return <td className="agent-compare-matrix-add-spacer" aria-hidden />;
}

function AgentCompareMatrixLoadingCell({
  isCalendar,
}: {
  isCalendar: boolean;
}): JSX.Element {
  return (
    <td
      className={[
        "agent-compare-matrix-value-cell",
        "agent-compare-matrix-value-cell--loading",
        isCalendar ? "agent-compare-matrix-value-cell--calendar" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <div className="agent-compare-matrix-cell-loading">
        <MorpheumInlineLoading message={COMPARE_LOADING_MESSAGE} />
      </div>
    </td>
  );
}

function AgentCompareMatrixTableLoading({
  compareFocus,
  columnCount,
  showAddSlot,
}: AgentCompareMatrixTableLoadingProps): JSX.Element {
  const { label, hint } = getCompareFocusMeta(compareFocus);
  const rows = getCompareFocusLoadingRows(compareFocus);

  return (
    <div className="agent-compare-matrix-scroll">
      <table className="agent-compare-matrix-table">
        <caption className="agent-compare-matrix-section-label">
          <span className="agent-compare-matrix-section-name">{label}</span>
          <span className="agent-compare-matrix-section-hint">{hint}</span>
        </caption>
        <colgroup>
          <col className="agent-compare-matrix-col-label" />
          {showAddSlot ? <col className="agent-compare-matrix-col-add" /> : null}
          {Array.from({ length: columnCount }, (_, index) => (
            <col key={`col-${index}`} className="agent-compare-matrix-col-agent" />
          ))}
        </colgroup>
        <thead>
          <tr className="agent-compare-matrix-row agent-compare-matrix-row--header">
            <th scope="col" className="agent-compare-matrix-label-cell">
              Metric
            </th>
            {showAddSlot ? <AgentCompareMatrixAddSpacer /> : null}
            {Array.from({ length: columnCount }, (_, index) => (
              <th
                key={`header-col-${index}`}
                scope="col"
                className="agent-compare-matrix-value-cell"
              >
                Agent {index + 1}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => {
            const isCalendarRow = row.kind === "dailyPnlCalendar";
            return (
              <tr
                key={row.label}
                className={`agent-compare-matrix-row${
                  isCalendarRow ? " agent-compare-matrix-row--calendar" : ""
                }${!isCalendarRow && rowIndex % 2 === 1 ? " agent-compare-matrix-row--alt" : ""}`}
              >
                <th scope="row" className="agent-compare-matrix-label-cell">
                  {row.label}
                </th>
                {showAddSlot ? <AgentCompareMatrixAddSpacerCell /> : null}
                {Array.from({ length: columnCount }, (_, cellIndex) => (
                  <AgentCompareMatrixLoadingCell
                    key={`${row.label}-${cellIndex}`}
                    isCalendar={isCalendarRow}
                  />
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default AgentCompareMatrixTableLoading;
