import { bindingsAreEqual } from "./matchKeyboardBinding";
import type { KeyboardBinding, KeyboardShortcutPrefs, ShortcutActionId } from "./types";

export function findBindingConflicts(
  prefs: KeyboardShortcutPrefs,
  candidate: KeyboardBinding,
  excludeActionId?: ShortcutActionId,
): ShortcutActionId[] {
  const conflicts: ShortcutActionId[] = [];

  for (const [actionId, binding] of Object.entries(prefs) as [ShortcutActionId, KeyboardBinding][]) {
    if (excludeActionId && actionId === excludeActionId) continue;
    if (bindingsAreEqual(binding, candidate)) {
      conflicts.push(actionId);
    }
  }

  return conflicts;
}
