import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  HistogramSeries,
  LineSeries,
  PriceScaleMode,
  createChart,
  type HistogramData,
  type IChartApi,
  type ISeriesApi,
  type LineData,
  type MouseEventParams,
  type Time,
  type UTCTimestamp,
} from "lightweight-charts";

import { TERMINAL_COLORS } from "../../constants/terminalColors";
import {
  computePercentChangeAtPoint,
  formatCompareChartValue,
  type AgentCompareChartMode,
  type AgentCompareChartSeries,
} from "../../utils/agentCompareChartData";
import { sanitizeLineDataForChart } from "../../utils/portfolioChartData";
import {
  agentCompareLineSeriesOptions,
  createAgentCompareBrushChartOptions,
  createAgentCompareMainChartOptions,
} from "./agentCompareChartTheme";
import "./agent.css";

const DAY_SEC = 24 * 60 * 60;
const DEFAULT_VISIBLE_DAYS = 7;
const BRUSH_HEIGHT = 48;

export interface AgentCompareTooltipEntry {
  id: string;
  label: string;
  ticker: string;
  color: string;
  value: number;
  percentChange: number | null;
}

export interface AgentCompareTooltipState {
  x: number;
  y: number;
  timeLabel: string;
  entries: AgentCompareTooltipEntry[];
}

export interface AgentCompareChartProps {
  series: AgentCompareChartSeries[];
  volume: HistogramData<UTCTimestamp>[];
  mode: AgentCompareChartMode;
}

function formatTimeLabel(time: Time): string {
  if (typeof time !== "number") return "";
  return new Date(time * 1000).toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function applyDefaultVisibleRange(
  chart: IChartApi,
  data: LineData<UTCTimestamp>[],
): void {
  if (data.length === 0) return;
  const lastTime = data[data.length - 1]!.time as number;
  const firstTime = data[0]!.time as number;
  const visibleSpanSec = Math.min(
    DEFAULT_VISIBLE_DAYS * DAY_SEC,
    lastTime - firstTime,
  );
  chart.timeScale().setVisibleRange({
    from: (lastTime - visibleSpanSec) as UTCTimestamp,
    to: lastTime as UTCTimestamp,
  });
}

function AgentCompareChart({
  series,
  volume,
  mode,
}: AgentCompareChartProps): JSX.Element {
  const wrapRef = useRef<HTMLDivElement>(null);
  const mainContainerRef = useRef<HTMLDivElement>(null);
  const brushContainerRef = useRef<HTMLDivElement>(null);
  const brushOverlayRef = useRef<HTMLDivElement>(null);

  const mainChartRef = useRef<IChartApi | null>(null);
  const brushChartRef = useRef<IChartApi | null>(null);
  const lineSeriesRefs = useRef<Map<string, ISeriesApi<"Line">>>(new Map());
  const brushSeriesRefs = useRef<Map<string, ISeriesApi<"Line">>>(new Map());
  const volumeSeriesRef = useRef<ISeriesApi<"Histogram"> | null>(null);

  const modeRef = useRef(mode);
  const seriesRef = useRef(series);
  const [tooltip, setTooltip] = useState<AgentCompareTooltipState | null>(null);
  const [brushSelection, setBrushSelection] = useState<{
    left: number;
    width: number;
  } | null>(null);

  modeRef.current = mode;
  seriesRef.current = series;

  const hasData = series.some((entry) => entry.data.length > 0);
  const primaryData = series[0]?.data ?? [];

  const seriesKey = useMemo(
    () =>
      `${mode}|${series.map((entry) => `${entry.id}:${entry.data.length}`).join("|")}|${volume.length}`,
    [mode, series, volume.length],
  );

  const syncBrushOverlay = useCallback(() => {
    const mainChart = mainChartRef.current;
    const brushChart = brushChartRef.current;
    const brushContainer = brushContainerRef.current;
    if (!mainChart || !brushChart || !brushContainer) return;

    const visibleRange = mainChart.timeScale().getVisibleRange();
    if (!visibleRange) return;

    const fromX = brushChart.timeScale().timeToCoordinate(visibleRange.from);
    const toX = brushChart.timeScale().timeToCoordinate(visibleRange.to);
    if (fromX == null || toX == null) return;

    const width = brushContainer.clientWidth;
    if (width <= 0) return;

    const left = Math.max(0, Math.min(fromX, width));
    const right = Math.max(0, Math.min(toX, width));
    setBrushSelection({
      left: (left / width) * 100,
      width: Math.max(((right - left) / width) * 100, 1),
    });
  }, []);

  const handleCrosshairMove = useCallback((param: MouseEventParams) => {
    if (
      !param.point ||
      param.time === undefined ||
      param.point.x < 0 ||
      param.point.y < 0
    ) {
      setTooltip(null);
      return;
    }

    const entries: AgentCompareTooltipEntry[] = [];
    for (const config of seriesRef.current) {
      const chartSeries = lineSeriesRefs.current.get(config.id);
      if (!chartSeries) continue;

      const pointData = param.seriesData.get(chartSeries);
      if (!pointData || !("value" in pointData)) continue;

      const value = pointData.value;
      if (!Number.isFinite(value)) continue;

      entries.push({
        id: config.id,
        label: config.label,
        ticker: config.ticker,
        color: config.color,
        value,
        percentChange: computePercentChangeAtPoint(
          config.data,
          param.time as UTCTimestamp,
        ),
      });
    }

    if (entries.length === 0) {
      setTooltip(null);
      return;
    }

    setTooltip({
      x: param.point.x,
      y: param.point.y,
      timeLabel: formatTimeLabel(param.time),
      entries,
    });
  }, []);

  useEffect(() => {
    if (!mainContainerRef.current || !brushContainerRef.current || !hasData) {
      return;
    }

    let mainChart: IChartApi | null = null;
    let brushChart: IChartApi | null = null;
    let animationFrameId: number | null = null;
    let initAttempts = 0;
    const maxInitAttempts = 120;
    let resizeObserver: ResizeObserver | null = null;

    const cleanupCharts = () => {
      if (mainChart) {
        try {
          mainChart.remove();
        } catch {
          // ignore
        }
      }
      if (brushChart) {
        try {
          brushChart.remove();
        } catch {
          // ignore
        }
      }
      mainChartRef.current = null;
      brushChartRef.current = null;
      lineSeriesRefs.current.clear();
      brushSeriesRefs.current.clear();
      volumeSeriesRef.current = null;
    };

    cleanupCharts();

    const handleVisibleRangeChange = () => {
      syncBrushOverlay();
    };

    const initializeCharts = () => {
      const mainContainer = mainContainerRef.current;
      const brushContainer = brushContainerRef.current;
      if (!mainContainer || !brushContainer) return;

      const mainWidth = mainContainer.clientWidth || mainContainer.offsetWidth;
      const mainHeight = mainContainer.clientHeight || mainContainer.offsetHeight;
      const brushWidth = brushContainer.clientWidth || brushContainer.offsetWidth;

      if (
        (!mainWidth || mainHeight < 60 || !brushWidth) &&
        initAttempts < maxInitAttempts
      ) {
        initAttempts += 1;
        animationFrameId = requestAnimationFrame(initializeCharts);
        return;
      }

      try {
        mainChart = createChart(mainContainer, createAgentCompareMainChartOptions());
        brushChart = createChart(
          brushContainer,
          createAgentCompareBrushChartOptions(),
        );

        const lineRefs = new Map<string, ISeriesApi<"Line">>();
        const brushRefs = new Map<string, ISeriesApi<"Line">>();

        for (const config of seriesRef.current) {
          if (config.data.length === 0) continue;

          const lineSeries = mainChart.addSeries(
            LineSeries,
            agentCompareLineSeriesOptions(config.color),
          );
          lineSeries.setData(sanitizeLineDataForChart(config.data));
          lineRefs.set(config.id, lineSeries);

          const brushLine = brushChart.addSeries(
            LineSeries,
            agentCompareLineSeriesOptions(config.color, true),
          );
          brushLine.setData(sanitizeLineDataForChart(config.data));
          brushRefs.set(config.id, brushLine);
        }

        let volumeSeries: ISeriesApi<"Histogram"> | null = null;
        if (volume.length > 0) {
          volumeSeries = mainChart.addSeries(HistogramSeries, {
            color: TERMINAL_COLORS.muted,
            priceFormat: { type: "volume" },
            priceScaleId: "volume",
          });
          volumeSeries.setData(volume);
          mainChart.priceScale("volume").applyOptions({
            scaleMargins: { top: 0.75, bottom: 0.05 },
          });
        }

        const priceScaleMode =
          modeRef.current === "performance"
            ? PriceScaleMode.Percentage
            : PriceScaleMode.Normal;
        mainChart.priceScale("right").applyOptions({ mode: priceScaleMode });

        applyDefaultVisibleRange(mainChart, primaryData);
        brushChart.timeScale().fitContent();

        mainChart.subscribeCrosshairMove(handleCrosshairMove);
        mainChart
          .timeScale()
          .subscribeVisibleTimeRangeChange(handleVisibleRangeChange);

        mainChartRef.current = mainChart;
        brushChartRef.current = brushChart;
        lineSeriesRefs.current = lineRefs;
        brushSeriesRefs.current = brushRefs;
        volumeSeriesRef.current = volumeSeries;

        mainChart.resize(mainWidth, mainHeight);
        brushChart.resize(brushWidth, BRUSH_HEIGHT);
        syncBrushOverlay();
      } catch (error) {
        console.error("[AgentCompareChart] Error creating chart:", error);
      }
    };

    initializeCharts();

    const resizeCharts = () => {
      const mainContainer = mainContainerRef.current;
      const brushContainer = brushContainerRef.current;
      if (!mainContainer || !brushContainer) return;

      const mainWidth = mainContainer.clientWidth;
      const mainHeight = mainContainer.clientHeight;
      const brushWidth = brushContainer.clientWidth;

      if (mainWidth > 0 && mainHeight > 0) {
        mainChartRef.current?.resize(mainWidth, mainHeight);
      }
      if (brushWidth > 0) {
        brushChartRef.current?.resize(brushWidth, BRUSH_HEIGHT);
      }
      syncBrushOverlay();
    };

    if (typeof ResizeObserver !== "undefined" && wrapRef.current) {
      resizeObserver = new ResizeObserver(resizeCharts);
      resizeObserver.observe(wrapRef.current);
    }

    return () => {
      setTooltip(null);
      if (animationFrameId != null) {
        cancelAnimationFrame(animationFrameId);
      }
      resizeObserver?.disconnect();
      if (mainChart) {
        try {
          mainChart.unsubscribeCrosshairMove(handleCrosshairMove);
          mainChart
            .timeScale()
            .unsubscribeVisibleTimeRangeChange(handleVisibleRangeChange);
          mainChart.remove();
        } catch {
          // ignore
        }
      }
      if (brushChart) {
        try {
          brushChart.remove();
        } catch {
          // ignore
        }
      }
      mainChartRef.current = null;
      brushChartRef.current = null;
      lineSeriesRefs.current.clear();
      brushSeriesRefs.current.clear();
      volumeSeriesRef.current = null;
    };
  }, [hasData, seriesKey, handleCrosshairMove, syncBrushOverlay, volume]);

  useEffect(() => {
    const mainChart = mainChartRef.current;
    if (!mainChart || !hasData) return;

    const priceScaleMode =
      mode === "performance" ? PriceScaleMode.Percentage : PriceScaleMode.Normal;
    mainChart.priceScale("right").applyOptions({ mode: priceScaleMode });

    for (const config of series) {
      const chartSeries = lineSeriesRefs.current.get(config.id);
      if (chartSeries && config.data.length > 0) {
        chartSeries.setData(sanitizeLineDataForChart(config.data));
      }
      const brushSeries = brushSeriesRefs.current.get(config.id);
      if (brushSeries && config.data.length > 0) {
        brushSeries.setData(sanitizeLineDataForChart(config.data));
      }
    }

    if (volumeSeriesRef.current && volume.length > 0) {
      volumeSeriesRef.current.setData(volume);
    }

    applyDefaultVisibleRange(mainChart, primaryData);
    brushChartRef.current?.timeScale().fitContent();
    syncBrushOverlay();
  }, [series, volume, mode, hasData, primaryData, syncBrushOverlay]);

  const handleBrushPointerDown = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const brushChart = brushChartRef.current;
      const mainChart = mainChartRef.current;
      const brushContainer = brushContainerRef.current;
      if (!brushChart || !mainChart || !brushContainer) return;

      const rect = brushContainer.getBoundingClientRect();
      const startX = event.clientX - rect.left;
      const target = event.target as HTMLElement;
      const isLeftHandle = target.dataset.handle === "left";
      const isRightHandle = target.dataset.handle === "right";

      const applyRangeFromX = (fromX: number, toX: number) => {
        const lo = Math.max(0, Math.min(fromX, toX));
        const hi = Math.min(rect.width, Math.max(fromX, toX));
        const fromTime = brushChart.timeScale().coordinateToTime(lo);
        const toTime = brushChart.timeScale().coordinateToTime(hi);
        if (fromTime == null || toTime == null) return;
        mainChart.timeScale().setVisibleRange({ from: fromTime, to: toTime });
      };

      if (isLeftHandle || isRightHandle) {
        const visibleRange = mainChart.timeScale().getVisibleRange();
        if (!visibleRange) return;

        const anchorX = isLeftHandle
          ? brushChart.timeScale().timeToCoordinate(visibleRange.to)
          : brushChart.timeScale().timeToCoordinate(visibleRange.from);
        if (anchorX == null) return;

        const onMove = (moveEvent: PointerEvent) => {
          const currentX = moveEvent.clientX - rect.left;
          if (isLeftHandle) {
            applyRangeFromX(currentX, anchorX);
          } else {
            applyRangeFromX(anchorX, currentX);
          }
        };

        const onUp = () => {
          window.removeEventListener("pointermove", onMove);
          window.removeEventListener("pointerup", onUp);
        };

        window.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", onUp);
        return;
      }

      const onMove = (moveEvent: PointerEvent) => {
        const currentX = moveEvent.clientX - rect.left;
        applyRangeFromX(startX, currentX);
      };

      const onUp = () => {
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
      };

      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
    },
    [],
  );

  if (!hasData) {
    return (
      <div className="agent-compare-chart-empty terminal-text-muted">
        No chart data for selected agents
      </div>
    );
  }

  return (
    <div ref={wrapRef} className="agent-compare-chart-body">
      <div className="agent-compare-chart-main-wrap">
        <div ref={mainContainerRef} className="agent-compare-chart-canvas" />
        {tooltip ? (
          <div
            className="agent-compare-chart-tooltip"
            style={{
              left: Math.min(tooltip.x + 12, (wrapRef.current?.clientWidth ?? 300) - 220),
              top: Math.max(tooltip.y - 12, 8),
            }}
          >
            <div className="agent-compare-chart-tooltip-time">{tooltip.timeLabel}</div>
            <ul className="agent-compare-chart-tooltip-list">
              {tooltip.entries.map((entry) => (
                <li key={entry.id} className="agent-compare-chart-tooltip-row">
                  <span
                    className="agent-compare-chart-tooltip-dot"
                    style={{ backgroundColor: entry.color }}
                  />
                  <span className="agent-compare-chart-tooltip-label">
                    {entry.ticker}
                  </span>
                  <span className="agent-compare-chart-tooltip-value">
                    {formatCompareChartValue(entry.value, mode)}
                    {entry.percentChange != null && mode === "price" ? (
                      <span
                        className={
                          entry.percentChange >= 0 ? "positive" : "negative"
                        }
                      >
                        {" "}
                        ({entry.percentChange >= 0 ? "+" : ""}
                        {entry.percentChange.toFixed(2)}%)
                      </span>
                    ) : null}
                  </span>
                </li>
              ))}
            </ul>
          </div>
        ) : null}
      </div>
      <div className="agent-compare-chart-brush-wrap">
        <div ref={brushContainerRef} className="agent-compare-chart-brush" />
        {brushSelection ? (
          <div
            ref={brushOverlayRef}
            className="agent-compare-chart-brush-overlay"
            onPointerDown={handleBrushPointerDown}
          >
            <div
              className="agent-compare-chart-brush-selection"
              style={{
                left: `${brushSelection.left}%`,
                width: `${brushSelection.width}%`,
              }}
            >
              <span
                className="agent-compare-chart-brush-handle agent-compare-chart-brush-handle--left"
                data-handle="left"
              />
              <span
                className="agent-compare-chart-brush-handle agent-compare-chart-brush-handle--right"
                data-handle="right"
              />
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default AgentCompareChart;
