import { getTickerPickerMeta } from "../../../offline/mock_data";
import type { AgentTask, Market } from "../../store/types";
import { resolveBinanceKlineSymbol } from "../tradingview/symbols";

export type ReviewChartMarket = {
  marketId: string;
  baseAsset: string;
  displayLabel: string;
  binanceSymbol: string | null;
};

function getMarketDisplayLabel(market: Market): string {
  if (market.moniker) return market.moniker;
  if (market.symbol) return market.symbol;
  if (market.baseAsset && market.quoteAsset) {
    return `${market.baseAsset}/${market.quoteAsset}`;
  }
  return market.baseAsset ?? "Unknown";
}

function resolveBaseAsset(market: Market): string {
  return (market.baseAsset || market.symbol?.split(/[-/]/)[0] || "")
    .trim()
    .toUpperCase();
}

function isSelectableMarket(market: Market): boolean {
  const baseAsset = resolveBaseAsset(market);
  if (!baseAsset) return false;
  const meta = getTickerPickerMeta(baseAsset);
  if (meta.showInPicker === false) return false;
  if (meta.isSelectable === false) return false;
  return true;
}

function escapeRegex(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function buildSelectableMarkets(
  markets: Market[],
): Array<{ market: Market; baseAsset: string }> {
  const seen = new Set<string>();
  const entries: Array<{ market: Market; baseAsset: string }> = [];

  for (const market of markets) {
    if (!isSelectableMarket(market)) continue;
    const baseAsset = resolveBaseAsset(market);
    if (!baseAsset || seen.has(baseAsset)) continue;
    seen.add(baseAsset);
    entries.push({ market, baseAsset });
  }

  entries.sort((a, b) => b.baseAsset.length - a.baseAsset.length);
  return entries;
}

function toReviewChartMarket(market: Market, baseAsset: string): ReviewChartMarket {
  const marketId = market.marketIndex || market.index;
  return {
    marketId,
    baseAsset,
    displayLabel: getMarketDisplayLabel(market),
    binanceSymbol: resolveBinanceKlineSymbol(baseAsset),
  };
}

function findMarketById(
  markets: Market[],
  marketId: string,
): Market | undefined {
  return markets.find(
    (m) => m.index === marketId || m.marketIndex === marketId,
  );
}

function findAssetInIntentText(
  text: string,
  selectable: Array<{ market: Market; baseAsset: string }>,
): { market: Market; baseAsset: string } | null {
  for (const entry of selectable) {
    const pattern = new RegExp(`\\b${escapeRegex(entry.baseAsset)}\\b`, "i");
    if (pattern.test(text)) return entry;
  }
  return null;
}

export function resolveReviewChartMarket(
  task: AgentTask,
  markets: Market[],
): ReviewChartMarket | null {
  const selectable = buildSelectableMarkets(markets);

  if (task.marketId) {
    const market = findMarketById(markets, task.marketId);
    if (market) {
      if (!isSelectableMarket(market)) return null;
      return toReviewChartMarket(market, resolveBaseAsset(market));
    }
  }

  const intentText = `${task.trigger ?? ""} ${task.description ?? ""}`.trim();
  if (!intentText) return null;

  const fromText = findAssetInIntentText(intentText, selectable);
  if (fromText) {
    return toReviewChartMarket(fromText.market, fromText.baseAsset);
  }

  return null;
}
