import React from "react";

export type Status = "ok" | "warn" | "down" | "unknown";

const STATUS_LABELS: Record<Status, string> = {
  ok: "healthy",
  warn: "degraded",
  down: "down",
  unknown: "unknown",
};

interface StatusDotProps {
  status: Status;
}

export default function StatusDot({ status }: StatusDotProps): React.JSX.Element {
  return (
    <span
      className={`nh-status-dot nh-status-${status}`}
      role="img"
      aria-label={STATUS_LABELS[status]}
    />
  );
}
