import { useCallback, useEffect, useRef, useState } from "react";
import type { GateIntentTimeoutAction } from "./gateIntentTimerPrefs";

export const GATE_TIMEOUT_ANIMATION_MS = 320;

export interface UseIntentGateTimerOptions {
  enabled: boolean;
  waitSeconds: number;
  onTimeout: GateIntentTimeoutAction;
  taskId: string;
  sizePct: number;
  onApprove: (taskId: string, sizePct: number) => void;
  onReject: (taskId: string) => void;
}

export interface UseIntentGateTimerResult {
  isComplete: boolean;
  manualOverride: boolean;
  pauseForManual: () => void;
}

export function useIntentGateTimer({
  enabled,
  waitSeconds,
  onTimeout,
  taskId,
  sizePct,
  onApprove,
  onReject,
}: UseIntentGateTimerOptions): UseIntentGateTimerResult {
  const [isComplete, setIsComplete] = useState(false);
  const [manualOverride, setManualOverride] = useState(false);
  const firedRef = useRef(false);
  const sizePctRef = useRef(sizePct);
  const onApproveRef = useRef(onApprove);
  const onRejectRef = useRef(onReject);
  const onTimeoutRef = useRef(onTimeout);

  sizePctRef.current = sizePct;
  onApproveRef.current = onApprove;
  onRejectRef.current = onReject;
  onTimeoutRef.current = onTimeout;

  useEffect(() => {
    setIsComplete(false);
    setManualOverride(false);
    firedRef.current = false;
  }, [taskId, waitSeconds, enabled]);

  const pauseForManual = useCallback(() => {
    setManualOverride(true);
    firedRef.current = true;
  }, []);

  useEffect(() => {
    if (!enabled || manualOverride || isComplete || waitSeconds <= 0) return;

    const timeoutId = window.setTimeout(() => {
      setIsComplete(true);
    }, waitSeconds * 1000);

    return () => window.clearTimeout(timeoutId);
  }, [enabled, manualOverride, isComplete, waitSeconds, taskId]);

  useEffect(() => {
    if (!enabled || !isComplete || manualOverride || firedRef.current) return;

    const timer = window.setTimeout(() => {
      if (firedRef.current) return;
      firedRef.current = true;
      if (onTimeoutRef.current === "approve") {
        onApproveRef.current(taskId, sizePctRef.current);
      } else {
        onRejectRef.current(taskId);
      }
    }, GATE_TIMEOUT_ANIMATION_MS);

    return () => window.clearTimeout(timer);
  }, [enabled, isComplete, manualOverride, taskId]);

  return {
    isComplete,
    manualOverride,
    pauseForManual,
  };
}
