import type { Bucket } from "../sdk/types/data";
import {
  addDemoCreatedBucket,
  getOfflineCreateBucketSteps,
  type DemoCreateBucketResult,
  type OfflineCreateBucketStep,
} from "../../offline/mock_data";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineBucketCreateParams = {
  wallet: string;
  marginType: "cross" | "isolated";
  collateralAsset: string;
  amount: number;
  fundFrom: string;
  /** Base equity for fundFrom bucket when not spot-wallet. */
  sourceBucketBaseEquity?: number;
  reuseEmptyBucket?: (
    marginType: "cross" | "isolated",
    collateralAsset: string,
  ) => Bucket | null;
};

export type OfflineCreateBucketProgressCallbacks = {
  onStepStart?: (step: OfflineCreateBucketStep) => void;
};

export async function executeOfflineBucketCreate(
  params: ExecuteOfflineBucketCreateParams,
  callbacks?: OfflineCreateBucketProgressCallbacks,
): Promise<DemoCreateBucketResult> {
  const wallet = params.wallet.trim();
  if (!wallet) {
    throw new Error("Wallet address is required");
  }

  const existingBucket =
    params.reuseEmptyBucket?.(params.marginType, params.collateralAsset) ??
    null;

  const steps = getOfflineCreateBucketSteps({
    amount: params.amount,
    collateralAsset: params.collateralAsset,
    fundFrom: params.fundFrom,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  return addDemoCreatedBucket(wallet, {
    marginType: params.marginType,
    collateralAsset: params.collateralAsset,
    amount: params.amount,
    fundFrom: params.fundFrom,
    ...(existingBucket?.bucketId
      ? { reuseBucketId: existingBucket.bucketId }
      : {}),
    ...(params.fundFrom !== "spot-wallet" &&
    params.sourceBucketBaseEquity != null
      ? { sourceBucketBaseEquity: params.sourceBucketBaseEquity }
      : {}),
  });
}
