import React, { useMemo, useState } from "react";
import { useAgentTasks } from "../../../hooks/useAgentTasks";
import { useTradingAgents } from "../../../hooks/useTradingAgents";
import { AGENT_TASK_STATUS_CONFIG } from "../../../constants";
import { shortHashId } from "../../../utils/hashId";
import type { AgentTask } from "../../../store/types";
import AgentTaskTimeline from "../../tables/AgentTaskTimeline";
import { ExpandCollapseIcon } from "../../ui/ExpandCollapseIcon";

export interface AgentExecutionTraceTabProps {
  highlightAgentId?: string | null;
}

function AgentExecutionTraceTab({
  highlightAgentId,
}: AgentExecutionTraceTabProps): JSX.Element {
  const { tasks } = useAgentTasks();
  const { getAgentById } = useTradingAgents();
  const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

  const sortedTasks = useMemo(() => {
    let list = [...tasks].filter(
      (t) => (t.statusHistory?.length ?? 0) > 0 || t.description,
    );
    if (highlightAgentId) {
      list = list.filter((t) => t.agentId === highlightAgentId);
    }
    return list.sort(
      (a, b) =>
        new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
    );
  }, [tasks, highlightAgentId]);

  if (sortedTasks.length === 0) {
    return (
      <p className="agent-console-empty terminal-text-muted">
        No execution traces yet. Agent tasks will appear here as they run.
      </p>
    );
  }

  return (
    <ul className="agent-console-trace-list">
      {sortedTasks.map((task) => (
        <TraceRow
          key={task.id}
          task={task}
          agentName={
            task.agentId
              ? getAgentById(task.agentId)?.displayName ?? shortHashId(task.agentId)
              : null
          }
          expanded={expandedTaskId === task.id}
          onToggle={() =>
            setExpandedTaskId((prev) => (prev === task.id ? null : task.id))
          }
        />
      ))}
    </ul>
  );
}

function TraceRow({
  task,
  agentName,
  expanded,
  onToggle,
}: {
  task: AgentTask;
  agentName: string | null;
  expanded: boolean;
  onToggle: () => void;
}): JSX.Element {
  const statusCfg =
    AGENT_TASK_STATUS_CONFIG[task.status] ?? {
      label: task.status,
      tone: "muted" as const,
    };
  const history = task.statusHistory ?? [];

  return (
    <li className="agent-console-trace-item">
      <button
        type="button"
        className="agent-console-trace-item-header"
        onClick={onToggle}
        aria-expanded={expanded}
      >
        <span className="task-id-chip" title={task.id}>
          {shortHashId(task.id)}
        </span>
        <span
          className={`agent-task-status-pill agent-task-status-pill--${statusCfg.tone}`}
        >
          {statusCfg.label}
        </span>
        {agentName ? (
          <span className="agent-console-trace-agent">{agentName}</span>
        ) : null}
        <ExpandCollapseIcon
          expanded={expanded}
          className="agent-console-trace-chevron"
          size={14}
        />
      </button>
      <p className="agent-console-trace-description">{task.description}</p>
      {expanded && history.length > 0 ? (
        <AgentTaskTimeline history={history} />
      ) : null}
    </li>
  );
}

export default React.memo(AgentExecutionTraceTab);
