import React, { useCallback, useState } from "react";
import { useAgentTasks } from "../../../hooks/useAgentTasks";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../../tutorials/bubble-tip";

export interface PauseAllButtonProps {
  disabled?: boolean;
}

function PauseAllButton({ disabled }: PauseAllButtonProps): JSX.Element {
  const { pauseActiveTasks, activeCount } = useAgentTasks();
  const [confirming, setConfirming] = useState(false);

  const handleClick = useCallback(() => {
    if (activeCount === 0) return;
    if (!confirming) {
      setConfirming(true);
      return;
    }
    pauseActiveTasks();
    setConfirming(false);
  }, [activeCount, confirming, pauseActiveTasks]);

  const handleBlur = useCallback(() => {
    setConfirming(false);
  }, []);

  const isDisabled = disabled || activeCount === 0;

  return (
    <BubbleTip id={BUBBLE_TIP_IDS.highAPauseAll}>
      <span className="high-a-pause-all-trigger">
        <button
          type="button"
          className={`high-a-pause-all${confirming ? " high-a-pause-all--confirm" : ""}`}
          onClick={handleClick}
          onBlur={handleBlur}
          disabled={isDisabled}
          aria-label={confirming ? "Confirm pause all" : "Pause all"}
        >
          <span className="high-a-pause-icon" aria-hidden>
            ⏸
          </span>
          {confirming ? "Confirm pause" : "Pause all"}
        </button>
      </span>
    </BubbleTip>
  );
}

export default React.memo(PauseAllButton);
