import React, { useCallback, useEffect, useMemo, useState } from "react";
import type {
  AgentTask,
  FleetSupervisor,
  TradingAgent,
} from "../../store/types";
import type { TradingMode } from "../../configs/tradeLayoutMode";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { shortHashId } from "../../utils/hashId";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import AgentMemoryDetailPane from "../agentconsole/AgentMemoryDetailPane";
import { ModalTabBar, type ModalTab } from "../smartlayout/modal-tab-bar";
import {
  countNeedsYouResolved,
  isNeedsYouTaskResolved,
  type TaskPolicyResolver,
} from "../tradeagent/reportTier";
import "./agentTasks.css";

export type AgentMemoryPanelView =
  | "supervisorList"
  | "agentList"
  | "detail";
export type AgentPanelEntrySource = "row" | "agentList" | "memoryLink";
export type AgentPanelTab = "memory" | "intents";

interface AgentMemorySidePanelProps {
  isOpen: boolean;
  isMobile: boolean;
  view: AgentMemoryPanelView;
  supervisorId: string | null;
  agentId: string | null;
  supervisors: FleetSupervisor[];
  agents: TradingAgent[];
  listAgents: TradingAgent[];
  tasks: AgentTask[];
  highlightedTaskId: string | null;
  filterObjectiveId?: string | null;
  memorySectionRef?: React.RefObject<HTMLDivElement>;
  tradingMode?: TradingMode;
  panelEntrySource?: AgentPanelEntrySource;
  resolvePolicyForTask?: TaskPolicyResolver;
  onClose: () => void;
  onBackToSupervisorList: () => void;
  onBackToAgentList: () => void;
  onSelectSupervisor: (supervisorId: string) => void;
  onSelectAgent: (agentId: string) => void;
  onSelectTask: (taskId: string) => void;
  onActiveTabChange?: (tab: AgentPanelTab) => void;
  onForceExecute?: (task: AgentTask) => void;
  onReject?: (task: AgentTask) => void;
  onPause?: (task: AgentTask) => void;
}

function canRejectTaskStatus(status: AgentTask["status"]): boolean {
  return status === "pending" || status === "watching";
}

function canForceExecuteTaskStatus(status: AgentTask["status"]): boolean {
  return (
    status !== "completed" &&
    status !== "rejected" &&
    status !== "executing"
  );
}

function canPauseTaskStatus(status: AgentTask["status"]): boolean {
  return status !== "completed" && status !== "rejected";
}

function agentStatusLabel(agent: TradingAgent): string {
  return agent.status === "active"
    ? "Active"
    : agent.status === "paused"
      ? "Paused"
      : "Idle";
}

function supervisorStatusLabel(supervisor: FleetSupervisor): string {
  return supervisor.status === "active"
    ? "Active"
    : supervisor.status === "paused"
      ? "Paused"
      : "Idle";
}

function defaultTabForEntry(
  entrySource: AgentPanelEntrySource,
  tradingMode: TradingMode,
): AgentPanelTab {
  if (entrySource === "row") return "intents";
  if (entrySource === "memoryLink") return "memory";
  return tradingMode === "humanInLoop" ? "memory" : "intents";
}

function sortAgentIntents(
  agentTasks: AgentTask[],
  highlightedTaskId: string | null,
  resolvePolicyForTask: TaskPolicyResolver,
): AgentTask[] {
  return [...agentTasks].sort((a, b) => {
    const aNeed = isNeedsYouTaskResolved(a, resolvePolicyForTask) ? 0 : 1;
    const bNeed = isNeedsYouTaskResolved(b, resolvePolicyForTask) ? 0 : 1;
    if (aNeed !== bNeed) return aNeed - bNeed;

    const aPin = a.id === highlightedTaskId ? 0 : 1;
    const bPin = b.id === highlightedTaskId ? 0 : 1;
    if (aPin !== bPin) return aPin - bPin;

    return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
  });
}

function AgentMemorySidePanel({
  isOpen,
  isMobile,
  view,
  supervisorId,
  agentId,
  supervisors,
  agents,
  listAgents,
  tasks,
  highlightedTaskId,
  filterObjectiveId = null,
  memorySectionRef,
  tradingMode = "proTerminal",
  panelEntrySource = "row",
  resolvePolicyForTask,
  onClose,
  onBackToSupervisorList,
  onBackToAgentList,
  onSelectSupervisor,
  onSelectAgent,
  onSelectTask,
  onActiveTabChange,
  onForceExecute,
  onReject,
  onPause,
}: AgentMemorySidePanelProps): JSX.Element {
  const resolvedAgent = agentId
    ? agents.find((a) => a.id === agentId) ?? null
    : null;

  const supervisor = supervisorId
    ? supervisors.find((s) => s.id === supervisorId)
    : null;

  const agentTasks = useMemo(() => {
    if (filterObjectiveId) {
      return tasks.filter((t) => t.objectiveId === filterObjectiveId);
    }
    if (!agentId) return [];
    return tasks.filter((t) => t.agentId === agentId);
  }, [agentId, filterObjectiveId, tasks]);

  const [activeTab, setActiveTab] = useState<AgentPanelTab>("memory");

  const handleTabChange = useCallback(
    (tab: AgentPanelTab) => {
      setActiveTab(tab);
      onActiveTabChange?.(tab);
    },
    [onActiveTabChange],
  );

  useEffect(() => {
    if (!isOpen || view !== "detail" || !agentId) return;
    setActiveTab(defaultTabForEntry(panelEntrySource, tradingMode));
  }, [isOpen, view, agentId, panelEntrySource, tradingMode]);

  useEffect(() => {
    if (!isOpen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen, onClose]);

  const needsYouCount = useMemo(() => {
    if (!resolvePolicyForTask) return 0;
    return countNeedsYouResolved(agentTasks, resolvePolicyForTask);
  }, [agentTasks, resolvePolicyForTask]);

  const sortedIntents = useMemo(() => {
    if (!resolvePolicyForTask) return agentTasks;
    return sortAgentIntents(
      agentTasks,
      highlightedTaskId,
      resolvePolicyForTask,
    );
  }, [agentTasks, highlightedTaskId, resolvePolicyForTask]);

  const panelTabs = useMemo(
    (): ModalTab<AgentPanelTab>[] => [
      { id: "memory", label: "Memory" },
      {
        id: "intents",
        label: filterObjectiveId
          ? `Intents (${agentTasks.length})`
          : `Intents (${agentTasks.length})`,
      },
    ],
    [agentTasks.length, filterObjectiveId],
  );

  const handleNeedsYouClick = useCallback(() => {
    handleTabChange("intents");
  }, [handleTabChange]);

  const isHil = tradingMode === "humanInLoop";

  const panelClass = [
    "agent-memory-side-panel",
    isOpen ? "is-open" : "",
    isMobile ? "agent-memory-side-panel--mobile" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const title =
    view === "supervisorList"
      ? "Fleet · Supervisor"
      : view === "agentList"
        ? supervisor
          ? `Agents — ${supervisor.displayName}`
          : "Agents"
        : resolvedAgent
          ? `Agent · Memory & Intents — ${resolvedAgent.displayName}`
          : "Agent · Memory & Intents";

  const relationalAnchorId = highlightedTaskId ?? agentId ?? undefined;

  const renderIntentCard = (task: AgentTask) => {
    const statusCfg = AGENT_TASK_STATUS_CONFIG[task.status] ?? {
      label: task.status,
      tone: "muted" as const,
    };
    const needsYou =
      resolvePolicyForTask != null &&
      isNeedsYouTaskResolved(task, resolvePolicyForTask);
    const showGateActions =
      isHil && needsYou && (onForceExecute || onReject || onPause);

    return (
      <li key={task.id}>
        <div
          className={`agent-memory-side-panel-task-item${highlightedTaskId === task.id ? " is-highlighted" : ""}`}
          data-task-id={task.id}
          data-objective-anchor={
            filterObjectiveId && task.objectiveId === filterObjectiveId
              ? filterObjectiveId
              : undefined
          }
        >
          <button
            type="button"
            className="agent-memory-side-panel-task-item-main"
            onClick={() => onSelectTask(task.id)}
          >
            <div className="agent-memory-side-panel-task-item-header">
              <span className="task-id-chip">{shortHashId(task.id)}</span>
              <span
                className={`agent-task-status-pill agent-task-status-pill--${statusCfg.tone}`}
              >
                {statusCfg.label}
              </span>
            </div>
            <div className="agent-task-intent-cell">{task.description}</div>
          </button>
          {showGateActions ? (
            <div
              className="agent-memory-side-panel-task-gate-actions"
              onClick={(e) => e.stopPropagation()}
            >
              {onForceExecute && canForceExecuteTaskStatus(task.status) ? (
                <button
                  type="button"
                  className="btn btn-success"
                  onClick={() => onForceExecute(task)}
                >
                  Approve
                </button>
              ) : null}
              {onReject && canRejectTaskStatus(task.status) ? (
                <button
                  type="button"
                  className="btn btn-danger"
                  onClick={() => onReject(task)}
                >
                  Reject
                </button>
              ) : null}
              {onPause && canPauseTaskStatus(task.status) ? (
                <button
                  type="button"
                  className="btn"
                  onClick={() => onPause(task)}
                >
                  Hold
                </button>
              ) : null}
            </div>
          ) : null}
        </div>
      </li>
    );
  };

  return (
    <>
      {isMobile ? (
        <div
          className={`agent-memory-side-panel-backdrop${isOpen ? " is-open" : ""}`}
          onClick={onClose}
          aria-hidden={!isOpen}
        />
      ) : null}
      <aside
        className={panelClass}
        aria-hidden={!isOpen}
        data-agent-panel-id={agentId ?? undefined}
      >
        <div className="agent-memory-side-panel-header">
          <div className="agent-memory-side-panel-header-start">
            {view === "detail" ? (
              <button
                type="button"
                className="btn btn-secondary agent-memory-side-panel-back"
                onClick={onBackToAgentList}
              >
                ← Agents
              </button>
            ) : view === "agentList" ? (
              <button
                type="button"
                className="btn btn-secondary agent-memory-side-panel-back"
                onClick={onBackToSupervisorList}
              >
                ← Supervisor
              </button>
            ) : null}
            <h3 className="agent-memory-side-panel-title">{title}</h3>
          </div>
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Close
          </button>
        </div>

        {view === "detail" && resolvedAgent ? (
          <>
            <div className="agent-memory-side-panel-context">
              <div
                className="agent-memory-side-panel-relational-anchor"
                data-panel-relational-anchor={relationalAnchorId}
                aria-hidden
              />
              <div className="agent-memory-side-panel-context-row">
                <span>{agentStatusLabel(resolvedAgent)}</span>
                <span aria-hidden>·</span>
                <span>Updated {formatRelativeTime(resolvedAgent.updatedAt)}</span>
              </div>
              {filterObjectiveId ? (
                <div className="agent-memory-side-panel-context-row terminal-text-muted">
                  Objective filter · {agentTasks.length} intent
                  {agentTasks.length === 1 ? "" : "s"}
                </div>
              ) : null}
              {highlightedTaskId ? (
                <div className="agent-memory-side-panel-context-row terminal-text-muted">
                  Linked to #{shortHashId(highlightedTaskId)} in table
                </div>
              ) : null}
              {needsYouCount > 0 ? (
                <button
                  type="button"
                  className="agent-memory-side-panel-needs-you"
                  onClick={handleNeedsYouClick}
                >
                  Needs you: {needsYouCount} →
                </button>
              ) : null}
            </div>

            <div className="agent-memory-side-panel-tabs">
              <ModalTabBar
                tabs={panelTabs}
                activeTabId={activeTab}
                onTabChange={handleTabChange}
                aria-label="Agent memory and intents"
              />
            </div>

            <div className="agent-memory-side-panel-tab-body">
              {activeTab === "memory" ? (
                <AgentMemoryDetailPane
                  agent={resolvedAgent}
                  taskCount={agentTasks.length}
                  showAddNote={false}
                  memorySectionRef={memorySectionRef}
                  className="agent-memory-side-panel-detail-pane"
                  previewLimit={3}
                />
              ) : (
                <ul className="agent-memory-side-panel-task-list">
                  {sortedIntents.length === 0 ? (
                    <li className="terminal-text-muted">
                      No intents for this agent.
                    </li>
                  ) : (
                    sortedIntents.map(renderIntentCard)
                  )}
                </ul>
              )}
            </div>
          </>
        ) : (
          <div className="agent-memory-side-panel-list-body">
            {view === "supervisorList" ? (
              supervisors.map((entry) => {
                const agentCount = agents.filter(
                  (a) => a.supervisorId === entry.id,
                ).length;
                return (
                  <button
                    key={entry.id}
                    type="button"
                    className="agent-memory-side-panel-agent-card agent-memory-side-panel-supervisor-card"
                    onClick={() => onSelectSupervisor(entry.id)}
                  >
                    <div className="agent-memory-side-panel-item-header">
                      <span className="agent-parent-chip">
                        {entry.icon ? (
                          <span className="agent-parent-chip-icon">
                            {entry.icon}
                          </span>
                        ) : null}
                        {entry.displayName}
                      </span>
                      <span className="agent-task-status-pill agent-task-status-pill--info">
                        {supervisorStatusLabel(entry)}
                      </span>
                    </div>
                    <div
                      className="terminal-text-muted"
                      style={{
                        fontSize: "var(--terminal-text-xs)",
                        marginTop: "0.35rem",
                      }}
                    >
                      {agentCount} agent{agentCount === 1 ? "" : "s"}
                    </div>
                  </button>
                );
              })
            ) : view === "agentList" ? (
              listAgents.map((entry) => {
                const intentCount = tasks.filter(
                  (t) => t.agentId === entry.id,
                ).length;
                const preview =
                  entry.memory[entry.memory.length - 1]?.text ??
                  "No memory yet.";
                return (
                  <button
                    key={entry.id}
                    type="button"
                    className="agent-memory-side-panel-agent-card"
                    onClick={() => onSelectAgent(entry.id)}
                  >
                    <div className="agent-memory-side-panel-item-header">
                      <span className="agent-parent-chip">
                        {entry.icon ? (
                          <span className="agent-parent-chip-icon">
                            {entry.icon}
                          </span>
                        ) : null}
                        {entry.displayName}
                      </span>
                      <span className="agent-task-status-pill agent-task-status-pill--info">
                        {entry.status}
                      </span>
                    </div>
                    <div
                      className="agent-memory-preview"
                      style={{ marginTop: "0.35rem" }}
                    >
                      <span
                        className="agent-memory-preview-text"
                        title={preview}
                      >
                        {preview}
                      </span>
                    </div>
                    <div
                      className="terminal-text-muted"
                      style={{
                        fontSize: "var(--terminal-text-xs)",
                        marginTop: "0.25rem",
                      }}
                    >
                      {intentCount} intent{intentCount === 1 ? "" : "s"}
                    </div>
                  </button>
                );
              })
            ) : (
              <p className="terminal-text-muted">
                Select a supervisor to view agents.
              </p>
            )}
          </div>
        )}
      </aside>
    </>
  );
}

export default React.memo(AgentMemorySidePanel);
