import React from "react";

import {
  formatCurrency,
  type MarketKind,
  type MarketRow,
  type SortKey,
} from "../../hooks/useMarketsPageData";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import { buildIndexTrendMetric } from "../../utils/marketsTableMetrics";
import CompactMetricCell from "../metrics/CompactMetricCell";
import CompactSparkline from "../metrics/CompactSparkline";
import {
  TABLE_HEADER_LABELS,
  TableHeaderCell,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import "../smartlayout/layout.css";
import "./markets.css";

const MARKETS_GRID_TEMPLATE_COLUMNS =
  "minmax(220px, 2.2fr) minmax(80px, 1fr) minmax(72px, 0.8fr) minmax(110px, 1fr) minmax(64px, 0.7fr) minmax(100px, 1fr) minmax(80px, 0.9fr)";

function MarketsMetricCell({
  row,
  showSparklines,
}: {
  row: MarketRow;
  showSparklines: boolean;
}): JSX.Element {
  if (row.kind === "agent") {
    if (row.copyCount == null) {
      return <>—</>;
    }

    return (
      <div className="markets-copy-cell">
        <div className="markets-copy-line">
          <span className="markets-copy-count">
            {row.copyCount.toLocaleString()}
          </span>
          {row.isPopular ? (
            <span className="markets-copy-popular-badge">popular</span>
          ) : null}
        </div>
        {showSparklines && row.sparkline.length >= 2 ? (
          <CompactSparkline
            values={row.sparkline}
            className="markets-copy-sparkline"
          />
        ) : null}
      </div>
    );
  }

  return (
    <CompactMetricCell
      metric={buildIndexTrendMetric(row, showSparklines)}
      showLabel={false}
      className="markets-trend-metric"
    />
  );
}

export interface MarketsDataTableProps {
  height?: string;
  activeTab: MarketKind;
  rows: MarketRow[];
  sortKey: SortKey;
  sortDir: "asc" | "desc";
  showSparklines?: boolean;
  onSort: (key: SortKey) => void;
  onRowNavigate: (row: MarketRow) => void;
}

export default function MarketsDataTable({
  height = "100%",
  activeTab,
  rows,
  sortKey,
  sortDir,
  showSparklines = true,
  onSort,
  onRowNavigate,
}: MarketsDataTableProps): JSX.Element {
  const handleRowKeyDown = (
    event: React.KeyboardEvent<HTMLDivElement>,
    row: MarketRow,
  ) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onRowNavigate(row);
    }
  };

  const metricColumnLabel = activeTab === "agent" ? "Copying" : "Trend";
  const gridStyle = { gridTemplateColumns: MARKETS_GRID_TEMPLATE_COLUMNS };

  return (
    <section className="markets-slot markets-table-wrap" style={{ height }}>
      <div className="markets-table-scroll">
        <div className="table-container shrinkable markets-table-container">
          <div className="table-header" style={gridStyle}>
            <TableHeaderCell
              field="name"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              Name
            </TableHeaderCell>
            <TableHeaderCell
              field="price"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              Price
            </TableHeaderCell>
            <TableHeaderCell
              field="change24h"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              <TableHeaderLabel {...TABLE_HEADER_LABELS.change24h} />
            </TableHeaderCell>
            <TableHeaderCell
              field="revenue30d"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              <TableHeaderLabel {...TABLE_HEADER_LABELS.revenue30d} />
            </TableHeaderCell>
            <TableHeaderCell
              field="risk"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              Risk
            </TableHeaderCell>
            {activeTab === "agent" ? (
              <TableHeaderCell
                field="copyCount"
                currentSortField={sortKey}
                sortDirection={sortDir}
                onSort={onSort}
                left
              >
                {metricColumnLabel}
              </TableHeaderCell>
            ) : (
              <TableHeaderCellStatic left>{metricColumnLabel}</TableHeaderCellStatic>
            )}
            <TableHeaderCellStatic left>Product</TableHeaderCellStatic>
          </div>

          {rows.map((row, index) => {
            const isAgent = row.kind === "agent";
            const instrumentLabel = isAgent ? "Agent Perp" : "MAEX Index";
            const agentAvatarSrc = isAgent
              ? resolveAgentAvatarSvgUrl(row.id)
              : null;

            return (
              <div
                key={row.id}
                className={`table-row clickable markets-table-row markets-table-row--${row.kind} ${index % 2 === 0 ? "even" : ""}`}
                style={gridStyle}
                tabIndex={0}
                role="button"
                onClick={() => onRowNavigate(row)}
                onKeyDown={(event) => handleRowKeyDown(event, row)}
              >
                <div className="table-cell primary">
                  <div className="markets-name-cell">
                    <span
                      className={`markets-icon markets-icon--${row.kind}`}
                      aria-hidden
                    >
                      {agentAvatarSrc ? (
                        <span
                          className="markets-icon-image"
                          style={{
                            maskImage: `url(${agentAvatarSrc})`,
                            WebkitMaskImage: `url(${agentAvatarSrc})`,
                          }}
                        />
                      ) : (
                        row.icon
                      )}
                    </span>
                    <div className="markets-name-meta">
                      <div className="markets-name-title-row">
                        <strong>{row.name}</strong>
                        <span
                          className={`markets-instrument-badge markets-instrument-badge--${row.kind}`}
                        >
                          {instrumentLabel}
                        </span>
                      </div>
                      <span className="markets-name-sector">{row.sector}</span>
                      {isAgent && row.agentWallet ? (
                        <span className="markets-agent-wallet" title={row.agentWallet}>
                          Agent {row.agentWallet.slice(0, 6)}…{row.agentWallet.slice(-4)}
                        </span>
                      ) : null}
                    </div>
                  </div>
                </div>
                <div className="table-cell monospace">
                  {formatCurrency(row.price)}
                </div>
                <div
                  className={`table-cell monospace ${
                    row.change24h >= 0 ? "markets-positive" : "markets-negative"
                  }`}
                >
                  {row.change24h >= 0 ? "+" : ""}
                  {row.change24h.toFixed(1)}%
                </div>
                <div className="table-cell monospace">
                  {typeof row.revenue30d === "number"
                    ? formatCurrency(row.revenue30d)
                    : "basket"}
                </div>
                <div className="table-cell">
                  <span
                    className={`markets-risk-badge markets-risk-badge--${row.risk.toLowerCase()}`}
                  >
                    {row.risk}
                  </span>
                </div>
                <div className="table-cell markets-metric-cell">
                  <MarketsMetricCell row={row} showSparklines={showSparklines} />
                </div>
                <div className="table-cell">{row.product}</div>
              </div>
            );
          })}
        </div>
      </div>
      <div className="markets-footer">
        <span className="markets-footer-count">
          {rows.length} tradable instrument{rows.length === 1 ? "" : "s"}
        </span>
        <span className="markets-footer-hint">Select a row to open details</span>
      </div>
    </section>
  );
}
