import React from "react";
import {
  SECURITY_STAGES,
  type SecurityStage,
} from "../../../types/crossChainFlow";
import "./cross-chain.css";

const STAGE_SHORT: Record<SecurityStage, string> = {
  authorize: "Auth",
  submit: "Sub",
  locked: "Lock",
  attested: "Att",
  delivered: "Del",
};

export interface CrossChainSecurityStepperProps {
  activeStage: SecurityStage | "complete";
  failedStage?: SecurityStage;
  completedStages?: SecurityStage[];
}

function stageIndex(stage: SecurityStage): number {
  return SECURITY_STAGES.indexOf(stage);
}

export function CrossChainSecurityStepper({
  activeStage,
  failedStage,
  completedStages = [],
}: CrossChainSecurityStepperProps): JSX.Element {
  const activeIdx =
    activeStage === "complete"
      ? SECURITY_STAGES.length
      : stageIndex(activeStage);
  const failedIdx = failedStage ? stageIndex(failedStage) : -1;

  return (
    <div className="cross-chain-stepper" role="list" aria-label="Transfer security stages">
      {SECURITY_STAGES.map((stage, idx) => {
        const isFailed = failedIdx === idx;
        const isComplete =
          activeStage === "complete" ||
          completedStages.includes(stage) ||
          idx < activeIdx;
        const isActive = activeStage !== "complete" && idx === activeIdx && !isFailed;

        return (
          <div
            key={stage}
            role="listitem"
            className={[
              "cross-chain-stepper-step",
              isComplete ? "is-complete" : "",
              isActive ? "is-active" : "",
              isFailed ? "is-failed" : "",
            ]
              .filter(Boolean)
              .join(" ")}
          >
            <div className="cross-chain-stepper-dot" aria-hidden />
            <span className="cross-chain-stepper-label">{STAGE_SHORT[stage]}</span>
          </div>
        );
      })}
    </div>
  );
}
