import React, { type JSX, useCallback, useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { useNavigate } from "react-router-dom";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../../components/ui/overlay";
import { WELCOME_DEEP_DIVES, WELCOME_MODAL, WELCOME_SLIDES } from "./content";
import { WELCOME_MODAL_Z_INDEX } from "./constants";
import type { WelcomeHubMode } from "./WelcomeTourContext";
import { WelcomeStoryRail, type WelcomeStoryRailHandle } from "./WelcomeStoryRail";
import "./WelcomeModal.css";

export interface WelcomeModalProps {
  isOpen: boolean;
  onStartTour: () => void;
  onExploreOwn: () => void;
  onClose?: () => void;
  onOpenKeyboardShortcuts?: () => void;
  onStartJellyIncident?: () => void;
  onOpenNetworkHealth?: () => void;
  onStartDepositTour?: () => void;
  onStartCopyTour?: () => void;
  welcomeHubMode?: WelcomeHubMode;
  highlightDeepDive?: boolean;
}

export function WelcomeModal({
  isOpen,
  onStartTour,
  onExploreOwn,
  onClose,
  onOpenKeyboardShortcuts,
  onStartJellyIncident,
  onOpenNetworkHealth,
  onStartDepositTour,
  onStartCopyTour,
  welcomeHubMode = "default",
  highlightDeepDive = false,
}: WelcomeModalProps): JSX.Element | null {
  const navigate = useNavigate();
  const deepDiveRef = useRef<HTMLDivElement>(null);
  const storyRailRef = useRef<WelcomeStoryRailHandle>(null);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  const handleClose = useCallback(() => {
    onClose?.();
  }, [onClose]);

  useOverlayEscapeKey(isOpen, handleClose);

  const handleDeepDiveAction = useCallback(
    (id: (typeof WELCOME_DEEP_DIVES)[number]["id"]) => {
      onClose?.();
      if (id === "jelly-incident") {
        onStartJellyIncident?.();
        return;
      }
      if (id === "network-health") {
        onOpenNetworkHealth?.();
        return;
      }
      if (id === "deposit-tour") {
        onStartDepositTour?.();
        return;
      }
      if (id === "copy-tour") {
        onStartCopyTour?.();
        return;
      }
      if (id === "bubble-guide") {
        navigate("/tutorials/bubble-tip");
        return;
      }
      if (id === "keyboard-shortcuts") {
        onOpenKeyboardShortcuts?.();
      }
    },
    [navigate, onClose, onOpenKeyboardShortcuts, onOpenNetworkHealth, onStartCopyTour, onStartDepositTour, onStartJellyIncident],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose?.();
        return;
      }
      if (welcomeHubMode === "postTour") return;
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        storyRailRef.current?.goToPrev();
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        storyRailRef.current?.goToNext();
      }
    },
    [onClose, welcomeHubMode],
  );

  useEffect(() => {
    if (!isOpen) return;
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, handleKeyDown]);

  useEffect(() => {
    if (!isOpen || !highlightDeepDive) return;
    const frame = requestAnimationFrame(() => {
      deepDiveRef.current?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    });
    return () => cancelAnimationFrame(frame);
  }, [isOpen, highlightDeepDive]);

  if (!mounted) return null;

  const isPostTour = welcomeHubMode === "postTour";
  const showDeepDive = (id: (typeof WELCOME_DEEP_DIVES)[number]["id"]) => {
    if (id === "jelly-incident") return Boolean(onStartJellyIncident);
    if (id === "network-health") return Boolean(onOpenNetworkHealth);
    if (id === "deposit-tour") return Boolean(onStartDepositTour);
    if (id === "keyboard-shortcuts") return Boolean(onOpenKeyboardShortcuts);
    return true;
  };

  const modalContent = (
    <StaggeredOverlayRoot
      passThrough={!isOpen}
      className="welcome-modal-overlay"
      style={{ zIndex: WELCOME_MODAL_Z_INDEX }}
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={handleClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--onboard"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="welcome-modal-panel staggered-overlay-panel--scale"
        aria-label="Welcome to Morpheum"
      >
        <button
          type="button"
          className="welcome-modal-close"
          onClick={handleClose}
          aria-label="Close welcome dialog"
        >
          ×
        </button>

        {isPostTour ? (
          <p className="welcome-modal-post-tour-banner">{WELCOME_MODAL.postTourBanner}</p>
        ) : null}

        {!isPostTour ? (
          <header className="welcome-modal-header">
            <p className="terminal-label welcome-modal-eyebrow">Morpheum</p>
            <h2 id="welcome-modal-title" className="welcome-modal-title">
              {WELCOME_MODAL.title}
            </h2>
            <p className="welcome-modal-subtitle">{WELCOME_MODAL.subtitle}</p>
          </header>
        ) : null}

        {!isPostTour ? (
          <>
            <WelcomeStoryRail ref={storyRailRef} slides={WELCOME_SLIDES} />
            <div className="welcome-modal-actions">
              <button
                type="button"
                className="welcome-modal-btn welcome-modal-btn--primary"
                onClick={onStartTour}
              >
                {WELCOME_MODAL.primaryCta}
              </button>
              <button
                type="button"
                className="welcome-modal-btn welcome-modal-btn--secondary"
                onClick={onExploreOwn}
              >
                {WELCOME_MODAL.secondaryCta}
              </button>
            </div>
          </>
        ) : null}

        <div
          ref={deepDiveRef}
          className={`welcome-modal-deep-dives${highlightDeepDive ? " welcome-modal-deep-dives--highlight" : ""}`}
        >
          <h3 className="terminal-panel-title welcome-modal-deep-dives-heading">{WELCOME_MODAL.deepDiveHeading}</h3>
          <div className="welcome-modal-deep-dives-strip">
            {WELCOME_DEEP_DIVES.filter((dive) => showDeepDive(dive.id)).map((dive) => (
              <button
                key={dive.id}
                type="button"
                className="welcome-modal-deep-dive-tile"
                onClick={() => handleDeepDiveAction(dive.id)}
                aria-label={`${dive.title}${"durationHint" in dive && dive.durationHint ? `, ${dive.durationHint}` : ""}`}
              >
                <span className="welcome-modal-deep-dive-tile-icon" aria-hidden>
                  {dive.tileIcon}
                </span>
                <span className="welcome-modal-deep-dive-tile-label">{dive.tileLabel}</span>
              </button>
            ))}
          </div>
        </div>

        <p className="welcome-modal-footer-hint">{WELCOME_MODAL.footerHint}</p>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
