import React, { useCallback, useMemo, useState } from "react";
import {
  ANCHOR,
  createInitialValidators,
  MEMBERSHIP_CYCLE,
  N,
  Q,
  VALID_QUORUM_LAYOUT,
} from "./constants";
import {
  cluster,
  computeStats,
  getVerdictKind,
  groupValidators,
  isSharedHonest,
} from "./logic";
import type { Membership, Validator } from "./types";
import "./QuorumIntersectionWidget.css";

function VerdictPanel({
  kind,
  stats,
  honestInter,
  interCount,
}: {
  kind: ReturnType<typeof getVerdictKind>;
  stats: ReturnType<typeof computeStats>;
  honestInter: Validator[];
  interCount: number;
}) {
  if (!stats.aValid || !stats.bValid) {
    return (
      <div className={`qi-verdict ${kind}`}>
        Build two <b>valid</b> certificates: each quorum needs ≥ {Q} of {N} validators (now |A|=
        {stats.sizeA}, |B|={stats.sizeB}).
      </div>
    );
  }

  if (!stats.faultOk) {
    return (
      <div className={`qi-verdict ${kind}`}>
        ⚠ Fault bound exceeded: {stats.byzCount} Byzantine ≥ ⅓ of {N}. The safety assumption{" "}
        <code>3f &lt; n</code> is violated — no guarantee outside the model&apos;s hypothesis.
      </div>
    );
  }

  const names = honestInter.map((v) => `V${v.id}`).join(", ");

  return (
    <div className={`qi-verdict ${kind}`}>
      ✓ <b>FORK IMPOSSIBLE.</b> Quorum A and Quorum B share honest validator(s) <b>{names}</b>.
      An honest validator never signs two conflicting blocks, so Block X and Block Y cannot both
      finalize.{" "}
      <span className="qi-verdict-muted">
        (|A∩B| = {interCount} ≥ 3 is forced once both quorums are valid.)
      </span>
    </div>
  );
}

export default function QuorumIntersectionWidget(): React.JSX.Element {
  const [validators, setValidators] = useState<Validator[]>(createInitialValidators);

  const groups = useMemo(() => groupValidators(validators), [validators]);
  const stats = useMemo(() => computeStats(validators, groups), [validators, groups]);
  const verdictKind = useMemo(() => getVerdictKind(stats), [stats]);
  const honestInter = useMemo(() => groups.both.filter((v) => !v.byz), [groups.both]);

  const cycleMembership = useCallback((id: number) => {
    setValidators((prev) =>
      prev.map((v) => (v.id === id ? { ...v, m: MEMBERSHIP_CYCLE[v.m] } : v)),
    );
  }, []);

  const toggleByzantine = useCallback((id: number) => {
    setValidators((prev) =>
      prev.map((v) => (v.id === id ? { ...v, byz: !v.byz } : v)),
    );
  }, []);

  const handleReset = useCallback(() => {
    setValidators(createInitialValidators());
  }, []);

  const handleFill = useCallback(() => {
    setValidators((prev) =>
      prev.map((v, i) => ({
        ...v,
        m: VALID_QUORUM_LAYOUT[i],
        byz: false,
      })),
    );
  }, []);

  const handleFork = useCallback(() => {
    setValidators((prev) =>
      prev.map((v, i) => ({
        ...v,
        m: VALID_QUORUM_LAYOUT[i],
        byz: VALID_QUORUM_LAYOUT[i] === "both",
      })),
    );
  }, []);

  const regions: Membership[] = ["a", "both", "b", "none"];

  return (
    <div className="qi">
      <h2 className="text-h2">Why two conflicting blocks can never both finalize</h2>
      <div className="sub text-body-secondary">
        Click a validator to move it: <b className="qi-label-a">Quorum A</b> →{" "}
        <b className="qi-label-b">Quorum B</b> → <b className="qi-label-both">both</b> →
        unassigned. Click the small badge to flip a validator Byzantine.{" "}
        <b>n = 7, quorum ≥ 5, fault bound 3f &lt; n.</b>
      </div>

      <div className="qi-stage">
        <div className="qi-circle a" />
        <div className="qi-circle b" />
        <div className="qi-clabel a">Quorum A → certifies Block X</div>
        <div className="qi-clabel b">Quorum B → certifies Block Y</div>
        <div className="qi-pool-label">unassigned validators</div>

        {regions.flatMap((region) =>
          groups[region].map((v, i) => {
            const anchor = ANCHOR[region];
            const offset = cluster(i, groups[region].length);
            const classNames = [
              "qi-dot",
              v.byz ? "byz" : "",
              isSharedHonest(region, v, stats) ? "shared-honest" : "",
            ]
              .filter(Boolean)
              .join(" ");

            return (
              <div
                key={v.id}
                className={classNames}
                style={{
                  left: `calc(${anchor.x}% + ${offset.dx}px - 15px)`,
                  top: `calc(${anchor.y}% + ${offset.dy}px - 15px)`,
                }}
                onClick={() => cycleMembership(v.id)}
              >
                V{v.id}
                <span
                  className="b"
                  title="toggle Byzantine"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleByzantine(v.id);
                  }}
                >
                  {v.byz ? "✗" : "·"}
                </span>
              </div>
            );
          }),
        )}
      </div>

      <VerdictPanel
        kind={verdictKind}
        stats={stats}
        honestInter={honestInter}
        interCount={stats.interCount}
      />

      <div className="qi-stats">
        <div className="qi-stat">
          <div className="k terminal-label">|Quorum A|</div>
          <div className="v text-data">{stats.sizeA}</div>
        </div>
        <div className="qi-stat">
          <div className="k terminal-label">|Quorum B|</div>
          <div className="v text-data">{stats.sizeB}</div>
        </div>
        <div className="qi-stat">
          <div className="k terminal-label">|A ∩ B|</div>
          <div className="v text-data">{stats.interCount}</div>
        </div>
        <div className="qi-stat">
          <div className="k terminal-label">honest in A ∩ B</div>
          <div className="v text-data">{stats.honestInterCount}</div>
        </div>
      </div>

      <div className="qi-controls">
        <button type="button" className="qi-btn button-secondary" onClick={handleFill}>
          Auto-fill two valid quorums
        </button>
        <button type="button" className="qi-btn button-secondary" onClick={handleFork}>
          Try to force a fork
        </button>
        <button type="button" className="qi-btn button-secondary" onClick={handleReset}>
          Reset
        </button>
      </div>

      <div className="qi-help">
        This is the live image of the proven axiom <code>QuorumIntersect</code> from{" "}
        <code>Fv4Agreement.tla</code>: any two certifying quorums share an honest validator.
        Notice you <i>cannot</i> certify two conflicting blocks while keeping both quorums valid
        and staying under the ⅓ fault bound — that is exactly what TLAPS proves for all chain
        lengths.
        <br />
        <br />
        Here a <b>fork</b> means two <i>conflicting</i> blocks both finalizing — a consensus
        safety failure. That is different from an intentional protocol <i>hard fork</i> (a
        deliberate upgrade or chain split, e.g. Bitcoin Cash); Morpheum makes the safety failure
        mathematically impossible.
      </div>
    </div>
  );
}
