import { AnimatedCollapse } from "../ui/AnimatedCollapse";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import { ORDER_TYPE_MARKET, ORDER_TYPE_LIMIT } from "../../constants";
import type { AdvancedOrderTypeId } from "../../configs/advancedOrderTypes";
import { AdvancedOrderPanel } from "./AdvancedOrderPanel";

export interface OrderTypeSelectorProps {
  orderType: typeof ORDER_TYPE_MARKET | typeof ORDER_TYPE_LIMIT;
  selectedAdvancedType: AdvancedOrderTypeId | null;
  advancedPanelOpen: boolean;
  onSelectMarket: () => void;
  onSelectLimit: () => void;
  onToggleAdvancedPanel: () => void;
  onSelectAdvancedType: (type: AdvancedOrderTypeId) => void;
}

export function OrderTypeSelector({
  orderType,
  selectedAdvancedType,
  advancedPanelOpen,
  onSelectMarket,
  onSelectLimit,
  onToggleAdvancedPanel,
  onSelectAdvancedType,
}: OrderTypeSelectorProps): JSX.Element {
  const isAdvancedActive = selectedAdvancedType !== null;

  return (
    <div className="trade-op-order-type-block">
      <div className="trade-op-order-type-selector">
        <BubbleTip id={BUBBLE_TIP_IDS.orderTypeSelector}>
          <div className="trade-op-order-type-primary">
            <button
              type="button"
              onClick={onSelectMarket}
              className={`btn-toggle ${!isAdvancedActive && orderType === ORDER_TYPE_MARKET ? "active" : ""}`}
            >
              MARKET
            </button>
            <button
              type="button"
              onClick={onSelectLimit}
              className={`btn-toggle ${!isAdvancedActive && orderType === ORDER_TYPE_LIMIT ? "active" : ""}`}
            >
              LIMIT
            </button>
          </div>
        </BubbleTip>
        <BubbleTip id={BUBBLE_TIP_IDS.advancedOrderTypes}>
          <button
            type="button"
            onClick={onToggleAdvancedPanel}
            aria-expanded={advancedPanelOpen}
            className={[
              "btn-toggle",
              "trade-op-order-type-adv",
              isAdvancedActive || advancedPanelOpen ? "active" : "",
            ]
              .filter(Boolean)
              .join(" ")}
          >
            ADV.
            <ExpandCollapseIcon
              expanded={advancedPanelOpen}
              className="trade-op-order-type-chevron"
              size={12}
            />
          </button>
        </BubbleTip>
      </div>
      <AnimatedCollapse open={advancedPanelOpen} timing="normal">
        <AdvancedOrderPanel
          selected={selectedAdvancedType}
          onSelect={onSelectAdvancedType}
        />
      </AnimatedCollapse>
    </div>
  );
}
