import React, { useCallback, type CSSProperties } from "react";
import {
  CONNECT_WALLET_COPY,
  CONNECT_WALLET_PRIMARY_LABEL,
  type ConnectWalletVariant,
} from "./connectWalletCopy";
import { useWalletConnectRequest } from "../../context/WalletConnectHostContext";
import "../smartlayout/layout.css";
import "./connectWalletPanel.css";

export type ConnectWalletPanelLayout = "panel" | "inline";
export type ConnectWalletPanelAlign = "center" | "top";

export interface ConnectWalletPanelProps {
  variant: ConnectWalletVariant;
  layout?: ConnectWalletPanelLayout;
  /** Vertical alignment within tall panel slots (TabSection uses top). */
  align?: ConnectWalletPanelAlign;
  height?: string;
  className?: string;
  /** Override host context when provided (e.g. tests, modals). */
  onConnect?: () => void;
}

function ConnectWalletPanel({
  variant,
  layout = "panel",
  align = "center",
  height = "100%",
  className,
  onConnect: onConnectProp,
}: ConnectWalletPanelProps): JSX.Element {
  const requestConnectFromHost = useWalletConnectRequest();
  const copy = CONNECT_WALLET_COPY[variant];

  const handleConnect = useCallback(() => {
    if (onConnectProp) {
      onConnectProp();
      return;
    }
    requestConnectFromHost?.();
  }, [onConnectProp, requestConnectFromHost]);

  const style: CSSProperties | undefined =
    layout === "panel" ? { height } : undefined;

  const rootClass = [
    "connect-wallet-panel",
    layout === "inline" ? "connect-wallet-panel--inline" : "",
    layout === "panel" && align === "top" ? "connect-wallet-panel--top" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={rootClass} style={style} role="status">
      <h3 className="connect-wallet-panel-title">{copy.title}</h3>
      <p className="connect-wallet-panel-description">{copy.description}</p>
      <div className="connect-wallet-panel-actions">
        <button
          type="button"
          className="btn btn-primary"
          onClick={handleConnect}
        >
          {CONNECT_WALLET_PRIMARY_LABEL}
        </button>
      </div>
    </div>
  );
}

export default React.memo(ConnectWalletPanel);
