import React from "react";

import type {
  PropertyIndexMode,
  PropertyIndexProfile,
} from "../../../offline/mock_data/types";
import { useTickerFavorites } from "../../hooks/useTickerFavorites";
import { formatCurrency, formatPercent } from "./indexFormat";
import "./index.css";

export interface IndexOverviewPanelProps {
  height?: string;
  profile: PropertyIndexProfile;
  icon?: string;
  price: number;
  change24h: number;
  activeModeMeta?: PropertyIndexMode;
  onShareClick?: () => void;
}

function StarIcon({ filled }: { filled: boolean }): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill={filled ? "currentColor" : "none"}
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
    </svg>
  );
}

function BellIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
      <path d="M13.73 21a2 2 0 0 1-3.46 0" />
    </svg>
  );
}

function ShareIcon(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <circle cx="18" cy="5" r="3" />
      <circle cx="6" cy="12" r="3" />
      <circle cx="18" cy="19" r="3" />
      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
    </svg>
  );
}

function ChartIcon(): JSX.Element {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
    </svg>
  );
}

function IndexOverviewPanel({
  height = "100%",
  profile,
  icon,
  price,
  change24h,
  activeModeMeta,
  onShareClick,
}: IndexOverviewPanelProps): JSX.Element {
  const { favorites, toggleFavorite } = useTickerFavorites();
  const isFavorite = favorites.includes(profile.ticker);
  const changeClass = change24h >= 0 ? "terminal-long" : "terminal-short";

  const keyParameters = [
    {
      label: "Weighting Rule",
      value: activeModeMeta?.weightingMethod ?? profile.weightingMethod,
    },
    {
      label: "Rebalancing Frequency",
      value: activeModeMeta?.rebalanceFrequency ?? profile.schedule.rebalanceWindow,
    },
    { label: "Launch Date", value: profile.launchDate },
    { label: "Base Date", value: profile.baseDate },
    { label: "Base Value", value: String(profile.baseValue) },
  ];

  return (
    <div className="index-slot index-overview-panel" style={{ height }}>
      <div className="index-overview-body">
        <div className="index-overview-identity">
          <span className="index-overview-icon" aria-hidden>
            {icon ? (
              <span className="index-overview-icon-glyph">{icon}</span>
            ) : (
              <ChartIcon />
            )}
          </span>
          <span className="terminal-market-title">{profile.ticker}</span>
        </div>

        <div className="index-overview-actions">
          <button
            type="button"
            className={`index-secondary-btn${isFavorite ? " active" : ""}`}
            onClick={() => toggleFavorite(profile.ticker)}
            aria-pressed={isFavorite}
            aria-label={isFavorite ? "Remove from favorites" : "Add to favorites"}
          >
            <StarIcon filled={isFavorite} />
            Add
          </button>
          <button
            type="button"
            className="index-secondary-btn"
            disabled
            aria-label="Set price alert (coming soon)"
          >
            <BellIcon />
            Alert
          </button>
          <button
            type="button"
            className="index-secondary-btn"
            onClick={onShareClick}
            aria-label={`Share ${profile.name}`}
          >
            <ShareIcon />
            Share
          </button>
        </div>

        <div className="index-overview-price-row">
          <span className="terminal-price">{formatCurrency(price)}</span>
          <span className={`terminal-value ${changeClass}`}>
            {formatPercent(change24h)}
          </span>
        </div>

        <section className="index-overview-section">
          <h3 className="terminal-panel-title">Key Parameters</h3>
          <dl className="index-overview-kv-list">
            {keyParameters.map(({ label, value }) => (
              <div key={label} className="index-overview-kv-row">
                <dt className="terminal-label">{label}</dt>
                <dd className="terminal-value">{value}</dd>
              </div>
            ))}
          </dl>
        </section>

        <section className="index-overview-section">
          <h3 className="terminal-panel-title">Introduction</h3>
          <p className="index-overview-intro">{profile.introduction}</p>
          <div className="index-overview-footer-links">
            {profile.docsUrl ? (
              <a
                href={profile.docsUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="index-overview-link"
              >
                Docs
              </a>
            ) : (
              <span className="index-overview-link index-overview-link--muted">
                Docs
              </span>
            )}
            <a
              href={profile.detailUrl ?? "#index-modes"}
              className="index-overview-link index-overview-link--detail"
            >
              View Detail
            </a>
          </div>
        </section>
      </div>
    </div>
  );
}

export default IndexOverviewPanel;
