import { useCallback, useEffect, useRef, useState } from "react";
import type { FeedEnterState } from "./feedAnimation";
import { useFeedEnter } from "./useFeedEnter";
import { generateIntent, type GeneratedIntent } from "./intentExamples";

export const MAX_INTENTS = 20;
export const MIN_INTERVAL_MS = 5_000;
export const MAX_INTERVAL_MS = 20_000;
export const SEED_COUNT = 3;
export const SEED_STAGGER_MS = 80;
export const EXIT_ANIMATION_MS = 220;

function randomIntervalMs(): number {
  return MIN_INTERVAL_MS + Math.random() * (MAX_INTERVAL_MS - MIN_INTERVAL_MS);
}

export interface UseIntentStreamResult {
  intents: GeneratedIntent[];
  enterState: FeedEnterState | null;
  exitingId: string | null;
  onExitAnimationEnd: (instanceId: string) => void;
}

export function useIntentStream(
  baseAsset: string,
  enabled: boolean,
): UseIntentStreamResult {
  const [intents, setIntents] = useState<GeneratedIntent[]>([]);
  const { enterState, markEntering, clearEnter } = useFeedEnter();
  const [exitingId, setExitingId] = useState<string | null>(null);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const seedTimeoutsRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const exitFallbackRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const baseAssetRef = useRef(baseAsset);
  const exitingIdRef = useRef<string | null>(null);

  const clearTimers = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    seedTimeoutsRef.current.forEach(clearTimeout);
    seedTimeoutsRef.current = [];
    if (exitFallbackRef.current) {
      clearTimeout(exitFallbackRef.current);
      exitFallbackRef.current = null;
    }
    clearEnter();
  }, [clearEnter]);

  const finishExit = useCallback((instanceId: string) => {
    if (exitingIdRef.current !== instanceId) return;
    setIntents((prev) => prev.filter((item) => item.instanceId !== instanceId));
    exitingIdRef.current = null;
    setExitingId(null);
    if (exitFallbackRef.current) {
      clearTimeout(exitFallbackRef.current);
      exitFallbackRef.current = null;
    }
  }, []);

  const startExit = useCallback(
    (instanceId: string) => {
      exitingIdRef.current = instanceId;
      setExitingId(instanceId);
      if (exitFallbackRef.current) {
        clearTimeout(exitFallbackRef.current);
      }
      exitFallbackRef.current = setTimeout(() => {
        finishExit(instanceId);
      }, EXIT_ANIMATION_MS);
    },
    [finishExit],
  );

  const prependIntent = useCallback(
    (asset: string) => {
      const next = generateIntent(asset);
      markEntering(next.instanceId);

      setIntents((prev) => {
        const merged = [next, ...prev];
        if (merged.length > MAX_INTENTS && !exitingIdRef.current) {
          const oldest = merged[merged.length - 1];
          if (oldest) {
            startExit(oldest.instanceId);
          }
        }
        return merged;
      });
    },
    [markEntering, startExit],
  );

  const scheduleNext = useCallback(
    (asset: string) => {
      if (!asset || !enabled) return;
      timeoutRef.current = setTimeout(() => {
        if (baseAssetRef.current !== asset) return;
        prependIntent(asset);
        scheduleNext(asset);
      }, randomIntervalMs());
    },
    [enabled, prependIntent],
  );

  const onExitAnimationEnd = useCallback(
    (instanceId: string) => {
      finishExit(instanceId);
    },
    [finishExit],
  );

  useEffect(() => {
    baseAssetRef.current = baseAsset;
    clearTimers();
    exitingIdRef.current = null;
    setExitingId(null);

    if (!baseAsset || !enabled) {
      setIntents([]);
      return clearTimers;
    }

    setIntents([]);

    for (let i = 0; i < SEED_COUNT; i++) {
      const seedTimeout = setTimeout(() => {
        if (baseAssetRef.current !== baseAsset) return;
        prependIntent(baseAsset);
      }, i * SEED_STAGGER_MS);
      seedTimeoutsRef.current.push(seedTimeout);
    }

    const startStreamTimeout = setTimeout(() => {
      if (baseAssetRef.current === baseAsset) {
        scheduleNext(baseAsset);
      }
    }, SEED_COUNT * SEED_STAGGER_MS + 500);
    seedTimeoutsRef.current.push(startStreamTimeout);

    return clearTimers;
  }, [baseAsset, enabled, clearTimers, prependIntent, scheduleNext]);

  return {
    intents,
    enterState,
    exitingId,
    onExitAnimationEnd,
  };
}
