import { useState, useEffect, useCallback, useRef } from "react";
import { InfoClient } from "../sdk";
import { executeWithRetry, DefaultRetryConfigs } from "../sdk/utils/retry";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import {
  cloneMockTradeHistory,
  getCopyMirrorFills,
  getJellyTrades,
  isJellyOverrideActive,
  subscribeCopyMirrorListeners,
} from "../../offline/mock_data";
import { useOptionalJellyMode } from "../context/JellyModeContext";
import { RawTrade } from "../sdk/types/api";
import {
  TradeHistoryConfig,
  TradeHistoryRow,
  transformRawTradeToTradeHistoryRow,
} from "../sdk/types/data";

export function useTradeHistory(config: TradeHistoryConfig) {
  const jellyCtx = useOptionalJellyMode();
  const isJellyMode = jellyCtx?.isJellyMode ?? false;
  const jellyFrameIndex = jellyCtx?.frameIndex;
  const [trades, setTrades] = useState<TradeHistoryRow[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const infoClientRef = useRef<InfoClient | null>(null);
  const configRef = useRef(config);
  configRef.current = config;

  const fetchTrades = useCallback(async () => {
    const currentConfig = configRef.current;

    if (isOfflineMode(currentConfig.baseURL)) {
      setError(null);
      const jellyActive = isJellyOverrideActive(
        currentConfig.baseURL,
        isJellyMode,
      );
      const wallet = currentConfig.walletAddress ?? "";
      const source: RawTrade[] = jellyActive
        ? getJellyTrades(jellyFrameIndex)
        : [
            ...cloneMockTradeHistory(),
            ...getCopyMirrorFills(wallet),
          ];
      const rows = source
        .map((trade) =>
          transformRawTradeToTradeHistoryRow(trade, wallet),
        )
        .sort((a, b) => b.time - a.time);
      setTrades(rows);
      setLoading(false);
      return;
    }

    if (!infoClientRef.current) return;

    if (
      !currentConfig.walletAddress ||
      currentConfig.walletAddress.trim() === ""
    ) {
      setError(null);
      setTrades([]);
      setLoading(false);
      return;
    }

    setError(null);

    try {
      const rawTrades = await executeWithRetry(
        DefaultRetryConfigs.http,
        () =>
          infoClientRef.current!.getTradeHistory(currentConfig.walletAddress!),
      );

      const rows = (rawTrades ?? [])
        .map((trade) =>
          transformRawTradeToTradeHistoryRow(
            trade,
            currentConfig.walletAddress!,
          ),
        )
        .sort((a, b) => b.time - a.time);

      setTrades((prev) => {
        const prevStr = JSON.stringify(prev);
        const newStr = JSON.stringify(rows);
        return prevStr === newStr ? prev : rows;
      });
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "Failed to load trade history";
      setError(errorMessage);
      console.error("Failed to fetch trade history after retries:", err);
    } finally {
      setLoading(false);
    }
  }, [isJellyMode, jellyFrameIndex]);

  useEffect(() => {
    if (isOfflineMode(configRef.current.baseURL)) return;
    infoClientRef.current = new InfoClient({
      baseURL: configRef.current.baseURL,
      sessionToken: configRef.current.authToken,
    });
  }, [config.baseURL, config.authToken]);

  useEffect(() => {
    void fetchTrades();
  }, [fetchTrades, config.walletAddress, config.baseURL]);

  useEffect(() => {
    if (!isOfflineMode(configRef.current.baseURL)) return;
    if (!isJellyOverrideActive(configRef.current.baseURL, isJellyMode)) return;
    void fetchTrades();
  }, [isJellyMode, jellyFrameIndex, fetchTrades]);

  useEffect(() => {
    if (!isOfflineMode(configRef.current.baseURL)) return;
    return subscribeCopyMirrorListeners(() => {
      void fetchTrades();
    });
  }, [fetchTrades]);

  useEffect(() => {
    const interval = configRef.current.refreshInterval;
    if (!interval || interval <= 0) return;
    const id = setInterval(() => {
      void fetchTrades();
    }, interval);
    return () => clearInterval(id);
  }, [fetchTrades, config.refreshInterval]);

  return {
    trades,
    loading,
    error,
    refresh: fetchTrades,
  };
}
