import type {
  FleetTradeEvent,
  FleetTradeHistoryFile,
  FleetTradeHistoryManifest,
} from "../../../../offline/mock_data/fleetTradeHistory.types";

export const FLEET_TRADE_HISTORY_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_FLEET_TRADE_HISTORY_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/fleet-trade-history";

let manifestCache: FleetTradeHistoryManifest | null = null;
let manifestPromise: Promise<FleetTradeHistoryManifest> | null = null;
const historyCache = new Map<string, FleetTradeEvent[]>();
const historyPromises = new Map<string, Promise<FleetTradeEvent[]>>();

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearFleetTradeHistoryCache(): void {
  manifestCache = null;
  manifestPromise = null;
  historyCache.clear();
  historyPromises.clear();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export async function fetchFleetTradeManifest(
  baseUrl: string = FLEET_TRADE_HISTORY_DATA_BASE_URL,
): Promise<FleetTradeHistoryManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<FleetTradeHistoryManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  ).then((manifest) => {
    manifestCache = manifest;
    return manifest;
  }).finally(() => {
    manifestPromise = null;
  });

  return manifestPromise;
}

export function getCachedFleetTradeManifest(): FleetTradeHistoryManifest | null {
  return manifestCache;
}

export function getManifestFleetAgentByCatalogId(
  manifest: FleetTradeHistoryManifest,
  catalogAgentId: string,
): FleetTradeHistoryManifest["agents"][number] | undefined {
  const normalized = catalogAgentId.trim().toLowerCase();
  return manifest.agents.find(
    (agent) => agent.catalogAgentId.toLowerCase() === normalized,
  );
}

export async function fetchFleetTradesByCatalogId(
  catalogAgentId: string,
  baseUrl: string = FLEET_TRADE_HISTORY_DATA_BASE_URL,
): Promise<FleetTradeEvent[]> {
  const normalizedId = catalogAgentId.trim();
  const cached = historyCache.get(normalizedId.toLowerCase());
  if (cached) return cached;

  const inflight = historyPromises.get(normalizedId.toLowerCase());
  if (inflight) return inflight;

  const promise = (async () => {
    const manifest = await fetchFleetTradeManifest(baseUrl);
    const agent = getManifestFleetAgentByCatalogId(manifest, normalizedId);
    if (!agent) {
      throw new Error(`Unknown fleet catalog agent id: ${normalizedId}`);
    }

    const payload = await fetchJson<FleetTradeHistoryFile>(
      joinBaseUrl(baseUrl, agent.file),
    );
    historyCache.set(normalizedId.toLowerCase(), payload.events);
    return payload.events;
  })().finally(() => {
    historyPromises.delete(normalizedId.toLowerCase());
  });

  historyPromises.set(normalizedId.toLowerCase(), promise);
  return promise;
}

export async function fetchFleetTradesForAgents(
  catalogAgentIds: readonly string[],
  baseUrl: string = FLEET_TRADE_HISTORY_DATA_BASE_URL,
): Promise<Map<string, FleetTradeEvent[]>> {
  const uniqueIds = [...new Set(catalogAgentIds.map((id) => id.trim()).filter(Boolean))];
  const entries = await Promise.all(
    uniqueIds.map(async (id) => [id, await fetchFleetTradesByCatalogId(id, baseUrl)] as const),
  );
  return new Map(entries);
}

export function getCachedFleetTradesByCatalogId(
  catalogAgentId: string,
): FleetTradeEvent[] | null {
  return historyCache.get(catalogAgentId.trim().toLowerCase()) ?? null;
}
