import React from "react";
import { CONTEXT_NOTES, THROUGHPUT_TIERS } from "./capability";
import { useNetworkHealthDemo } from "./NetworkHealthDemoContext";
import TrackSlider from "./TrackSlider";
import type { ThroughputTier } from "./types";
import "./NetworkHealthPanel.css";

export default function ThroughputContextSection(): React.JSX.Element {
  const { throughputTier, setThroughputTier } = useNetworkHealthDemo();

  return (
    <section aria-labelledby="capability-heading" className="nh nh-throughput">
      <header className="nh-header">
        <h2 id="capability-heading" className="text-h2">Throughput in context</h2>
        <p className="nh-sub text-body-secondary">
          The live rate above is intentionally throttled for a stable laptop demo.
          Drag the scale to see how telemetry shifts across what this same hardware
          benchmarks at, and the production architectural target.
        </p>
      </header>

      <TrackSlider
        id="throughput-tier-slider"
        label="Environment scale"
        min={0}
        max={2}
        step={1}
        value={throughputTier}
        onChange={(v) => setThroughputTier(v as ThroughputTier)}
        stops={THROUGHPUT_TIERS.map((tier, index) => ({
          value: index,
          label: tier.label,
        }))}
      />

      <ol className="nh-tier-grid">
        {THROUGHPUT_TIERS.map((tier, index) => (
          <li key={tier.label}>
            <article
              className={`nh-tier-card nh-tier-accent-${tier.accent}${
                throughputTier === index ? " nh-tier-active" : ""
              }`}
            >
              <div className="nh-tier-value-row">
                <span className="nh-tier-value">{tier.value}</span>
                <span className="nh-tier-unit">{tier.unit}</span>
              </div>
              <h3 className="nh-tier-label text-h3">
                <span className="nh-tier-index">{index + 1}.</span>
                {tier.label}
              </h3>
              <p className="nh-tier-detail">{tier.detail}</p>
            </article>
          </li>
        ))}
      </ol>

      <article className="nh-notes-card">
        <h3 className="nh-notes-title text-h3">Why the live number understates the system</h3>
        <p className="nh-notes-sub">Environment, not architecture.</p>
        <ul className="nh-notes-list">
          {CONTEXT_NOTES.map((note) => (
            <li key={note}>{note}</li>
          ))}
        </ul>
      </article>
    </section>
  );
}
