import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
  type JSX,
  type KeyboardEvent,
} from "react";
import type { Bucket } from "../../sdk/types/data";
import type { Market, TradingAgent } from "../../store/types";
import { TradeOperationInfoPanel } from "./TradeOperationInfoPanel";
import { AgentIntentExampleCards } from "./AgentIntentExampleCards";
import { TickerXNewsCards } from "./TickerXNewsCards";
import {
  resolveBaseAsset,
  type GeneratedIntent,
} from "./intentExamples";
import { useIntentStream } from "./useIntentStream";
import {
  DEFAULT_X_NEWS_CAPACITY,
  useXNewsStream,
} from "./useXNewsStream";
import {
  IntentWindowInlineHints,
  IntentMentionAutocomplete,
  IntentResolutionChips,
  useIntentMentionKeyDown,
} from "../intentwindow";
import { IntentExecutionContract } from "../intentwindow/IntentExecutionContract";
import {
  IntentAdaptiveRegion,
  IntentClarifyPrompt,
  IntentControlDepthToggle,
  useIntentMorph,
  type ControlDepth,
} from "../intentwindow/adaptive";
import { replaceTokenAtCaret } from "../intentwindow/intentKeywords";
import type { IntentBreakdown } from "../intentwindow/intentBreakdown";
import type {
  ContractOverrides,
  ExecutionContract,
} from "../intentwindow/executionContract";
import type {
  IntentResolution,
  ResolvedAgent,
  ResolvedAsset,
} from "../intentwindow/intentResolution";
import { canDeployBreakdown } from "../intentwindow/resolveIntentBreakdown";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";

const INTENT_PLACEHOLDER =
  "Describe your intent — use @ for an agent, $ for a market";

export interface AgentIntentSectionProps {
  selectedMarket: Pick<Market, "baseAsset" | "moniker" | "symbol"> | null | undefined;
  selectedMarketSymbol: string | null | undefined;
  spotWalletBalance: number;
  collections: Bucket[];
  selectedBucketId?: string | null;
  selectedBucket: Bucket | null;
  agentIntentText: string;
  agentIntentValidated: boolean;
  onAgentIntentTextChange: (value: string) => void;
  onParseValidate: () => void;
  onValidateIntentText: (
    text: string,
    instanceId?: string | null,
  ) => string | null | undefined | Promise<string | null | undefined>;
  onDeployToAgent: () => void;
  onBlurValidate?: () => void;
  isDesktop?: boolean;
  agents: TradingAgent[];
  markets: Market[];
  intentResolution: IntentResolution | null;
  intentBreakdown: IntentBreakdown | null;
  executionContract: ExecutionContract | null;
  contractOverrides: ContractOverrides;
  controlDepth: ControlDepth;
  stickyArchetype?: IntentBreakdown["stickyArchetype"];
  onArchetypeOverride: (archetype: IntentBreakdown["archetype"]) => void;
  onContractOverride: (patch: ContractOverrides) => void;
  onControlDepthChange: (depth: ControlDepth) => void;
  onOpenManual?: () => void;
  deployButtonLabel: string;
  deployDisabled: boolean;
  onResolveAgent: (agent: ResolvedAgent) => void;
  onResolveAsset: (asset: ResolvedAsset) => void;
  onOpenIntentWindow?: () => void;
}

export function AgentIntentSection({
  selectedMarket,
  selectedMarketSymbol,
  spotWalletBalance,
  collections,
  selectedBucketId,
  selectedBucket,
  agentIntentText,
  agentIntentValidated,
  onAgentIntentTextChange,
  onParseValidate,
  onValidateIntentText,
  onDeployToAgent,
  onBlurValidate,
  isDesktop = true,
  agents,
  markets,
  intentResolution,
  intentBreakdown,
  executionContract,
  contractOverrides,
  controlDepth,
  stickyArchetype,
  onArchetypeOverride,
  onContractOverride,
  onControlDepthChange,
  onOpenManual,
  deployButtonLabel,
  deployDisabled,
  onResolveAgent,
  onResolveAsset,
  onOpenIntentWindow,
}: AgentIntentSectionProps): JSX.Element {
  const baseAsset = resolveBaseAsset(selectedMarket, selectedMarketSymbol);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [caret, setCaret] = useState(0);

  const { displayedArchetype } = useIntentMorph({
    wireframe: intentBreakdown?.wireframe ?? null,
    validated: agentIntentValidated,
    stickyArchetype,
  });

  const inlineFits =
    displayedArchetype === "directional" &&
    controlDepth === "simple" &&
    !intentBreakdown?.isParked;

  const showConfigure =
    agentIntentValidated &&
    intentBreakdown != null &&
    (!inlineFits ||
      (executionContract?.hasDefaultedRisk && controlDepth === "simple"));

  const showDeploy =
    agentIntentValidated &&
    intentBreakdown != null &&
    canDeployBreakdown(intentBreakdown) &&
    inlineFits;

  const [selectedInstanceId, setSelectedInstanceId] = useState<string | null>(
    null,
  );
  const [xNewsCapacity, setXNewsCapacity] = useState(DEFAULT_X_NEWS_CAPACITY);

  const { intents, enterState, exitingId, onExitAnimationEnd } =
    useIntentStream(baseAsset, true);

  const { items: xNewsItems, enterState: xNewsEnterState } = useXNewsStream(
    baseAsset,
    isDesktop && !!baseAsset,
    xNewsCapacity,
  );

  useEffect(() => {
    if (!agentIntentText) {
      setSelectedInstanceId(null);
    }
  }, [agentIntentText]);

  const applyTextAtCaret = useCallback(
    (nextText: string, nextCaret: number) => {
      onAgentIntentTextChange(nextText);
      requestAnimationFrame(() => {
        const el = textareaRef.current;
        el?.focus();
        el?.setSelectionRange(nextCaret, nextCaret);
        setCaret(nextCaret);
      });
    },
    [onAgentIntentTextChange],
  );

  const handleMentionKeyDown = useIntentMentionKeyDown(
    agentIntentText,
    caret,
    agents,
    markets,
    textareaRef,
    applyTextAtCaret,
  );

  const handleAgentIntentTextChange = useCallback(
    (e: ChangeEvent<HTMLTextAreaElement>) => {
      setSelectedInstanceId(null);
      onAgentIntentTextChange(e.target.value);
      setCaret(e.target.selectionStart ?? e.target.value.length);
    },
    [onAgentIntentTextChange],
  );

  const handleComposerActivate = useCallback(() => {
    if (!isDesktop || !onOpenIntentWindow) return;
    onOpenIntentWindow();
    requestAnimationFrame(() => textareaRef.current?.blur());
  }, [isDesktop, onOpenIntentWindow]);

  const handleSelectIntent = useCallback(
    (intent: GeneratedIntent) => {
      void onValidateIntentText(intent.intentText, intent.instanceId);
      setSelectedInstanceId(intent.instanceId);
      onOpenIntentWindow?.();
    },
    [onOpenIntentWindow, onValidateIntentText],
  );

  const handleInsertKeyword = useCallback(
    (keyword: string) => {
      const el = textareaRef.current;
      if (!el) {
        onAgentIntentTextChange(
          agentIntentText ? `${agentIntentText} ${keyword}` : keyword,
        );
        return;
      }
      const caretPos = el.selectionStart ?? agentIntentText.length;
      const { nextText, nextCaret } = replaceTokenAtCaret(
        agentIntentText,
        caretPos,
        keyword,
      );
      applyTextAtCaret(nextText, nextCaret);
    },
    [agentIntentText, applyTextAtCaret, onAgentIntentTextChange],
  );

  const handleTextareaKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (handleMentionKeyDown(e)) return;
    },
    [handleMentionKeyDown],
  );

  return (
    <div className="trade-op-agent-intent agent-intent-panel">
      <div className="trade-op-agent-intent-controls">
        {!isDesktop ? (
          <IntentControlDepthToggle
            depth={controlDepth}
            onChange={onControlDepthChange}
          />
        ) : null}
        <BubbleTip id={BUBBLE_TIP_IDS.manualIntent}>
          <div className="intent-composer-field">
            <textarea
              ref={textareaRef}
              className="trade-op-agent-intent-textarea"
              value={agentIntentText}
              onChange={handleAgentIntentTextChange}
              onFocus={handleComposerActivate}
              onClick={handleComposerActivate}
              onBlur={onBlurValidate}
              onSelect={(e) =>
                setCaret(
                  e.currentTarget.selectionStart ?? agentIntentText.length,
                )
              }
              onKeyUp={(e) =>
                setCaret(
                  e.currentTarget.selectionStart ?? agentIntentText.length,
                )
              }
              onKeyDown={handleTextareaKeyDown}
              placeholder={INTENT_PLACEHOLDER}
              rows={2}
            />
            {!isDesktop ? (
              <IntentMentionAutocomplete
                text={agentIntentText}
                caret={caret}
                agents={agents}
                markets={markets}
                textareaRef={textareaRef}
                onTextChange={applyTextAtCaret}
              />
            ) : null}
          </div>
        </BubbleTip>
        {!isDesktop ? (
          <IntentWindowInlineHints
            text={agentIntentText}
            baseAsset={baseAsset}
            caret={caret}
            onSelectSuggestion={(intentText) => {
              void onValidateIntentText(intentText, null);
            }}
            onInsertKeyword={handleInsertKeyword}
          />
        ) : null}
        {intentResolution && agentIntentValidated ? (
          <IntentResolutionChips
            resolution={intentResolution}
            onEditAgent={onOpenIntentWindow}
            onEditAsset={onOpenIntentWindow}
          />
        ) : null}
        {agentIntentValidated && executionContract ? (
          <IntentExecutionContract contract={executionContract} compact />
        ) : null}
        {agentIntentValidated && intentBreakdown && !inlineFits ? (
          <IntentAdaptiveRegion
            breakdown={intentBreakdown}
            displayedArchetype={displayedArchetype}
            depth={controlDepth}
            contractOverrides={contractOverrides}
            onArchetypeOverride={onArchetypeOverride}
            onContractOverride={onContractOverride}
            onOpenManual={onOpenManual}
            compactSummary={executionContract?.summaryOneLine}
          />
        ) : null}
        {intentBreakdown ? (
          <IntentClarifyPrompt
            breakdown={intentBreakdown}
            onSelectAgent={onResolveAgent}
            onSelectAsset={onResolveAsset}
          />
        ) : null}
        <div className="intent-inline-actions">
          <BubbleTip id={BUBBLE_TIP_IDS.parseValidate}>
            <button
              type="button"
              className="trade-op-agent-parse-btn intent-reparse-btn"
              onClick={onParseValidate}
              disabled={!agentIntentText.trim()}
            >
              Re-parse
            </button>
          </BubbleTip>
          {showConfigure && onOpenIntentWindow ? (
            <button
              type="button"
              className="trade-op-agent-configure-btn"
              onClick={onOpenIntentWindow}
            >
              Configure →
            </button>
          ) : null}
          {showDeploy ? (
            <BubbleTip id={BUBBLE_TIP_IDS.deployToAgent}>
              <button
                type="button"
                className="trade-op-agent-deploy-btn"
                onClick={onDeployToAgent}
                disabled={deployDisabled}
              >
                {deployButtonLabel} ▸
              </button>
            </BubbleTip>
          ) : null}
        </div>
      </div>

      <TradeOperationInfoPanel
        spotWalletBalance={spotWalletBalance}
        collections={collections}
        selectedBucketId={selectedBucketId}
        selectedBucket={selectedBucket}
      />

      <div className="agent-intent-feeds">
        <AgentIntentExampleCards
          baseAsset={baseAsset}
          intents={intents}
          enterState={enterState}
          exitingId={exitingId}
          onSelect={handleSelectIntent}
          onExitAnimationEnd={onExitAnimationEnd}
          selectedInstanceId={selectedInstanceId}
        />
        {isDesktop ? (
          <TickerXNewsCards
            baseAsset={baseAsset}
            items={xNewsItems}
            enterState={xNewsEnterState}
            onVisibleCapacityChange={setXNewsCapacity}
          />
        ) : null}
      </div>
    </div>
  );
}
