import { useMemo } from "react";
import { useAgentTasks } from "./useAgentTasks";
import {
  deriveSelectedAgentId,
  useTradingAgentStore,
} from "../store/tradingAgentStore";
import type { AgentTask, TradingAgent } from "../store/types";
import {
  agentMatchesFleetFilter,
  buildFleetBucketIds,
} from "../utils/agentFilter";

export interface UsePortfolioFleetFilterResult {
  agents: TradingAgent[];
  selectedAgentIds: string[];
  /** Convenience: set when exactly one fleet member is selected (sidebar detail). */
  selectedAgentId: string | null;
  isFleetFilterActive: boolean;
  toggleFleetAgent: (id: string) => void;
  selectAllAgents: () => void;
  clearFleetSelection: () => void;
  setSelectedAgentId: (id: string | null) => void;
  filterAgents: (list: TradingAgent[]) => TradingAgent[];
  filterTasks: (list: AgentTask[]) => AgentTask[];
  fleetBucketIds: Set<string> | null;
  agentMatchesFleet: (agentId: string | null | undefined) => boolean;
}

export function usePortfolioFleetFilter(): UsePortfolioFleetFilterResult {
  const agents = useTradingAgentStore((s) => s.agents);
  const selectedAgentIds = useTradingAgentStore((s) => s.selectedAgentIds);
  const toggleFleetAgent = useTradingAgentStore((s) => s.toggleFleetAgent);
  const selectAllAgents = useTradingAgentStore((s) => s.selectAllAgents);
  const clearFleetSelection = useTradingAgentStore((s) => s.clearFleetSelection);
  const setSelectedAgentId = useTradingAgentStore((s) => s.setSelectedAgentId);
  const { tasks } = useAgentTasks();

  const selectedAgentId = useMemo(
    () => deriveSelectedAgentId(selectedAgentIds),
    [selectedAgentIds],
  );

  const isFleetFilterActive = selectedAgentIds.length > 0;

  const filterAgents = useMemo(
    () => (list: TradingAgent[]) => {
      if (!isFleetFilterActive) return list;
      const fleet = new Set(selectedAgentIds);
      return list.filter((agent) => fleet.has(agent.id));
    },
    [isFleetFilterActive, selectedAgentIds],
  );

  const filterTasks = useMemo(
    () => (list: AgentTask[]) => {
      if (!isFleetFilterActive) return list;
      const fleet = new Set(selectedAgentIds);
      return list.filter((task) => fleet.has(task.agentId));
    },
    [isFleetFilterActive, selectedAgentIds],
  );

  const fleetBucketIds = useMemo(
    () =>
      isFleetFilterActive
        ? buildFleetBucketIds(tasks, selectedAgentIds)
        : null,
    [isFleetFilterActive, selectedAgentIds, tasks],
  );

  const agentMatchesFleet = useMemo(
    () => (agentId: string | null | undefined) =>
      agentMatchesFleetFilter(agentId, selectedAgentIds),
    [selectedAgentIds],
  );

  return {
    agents,
    selectedAgentIds,
    selectedAgentId,
    isFleetFilterActive,
    toggleFleetAgent,
    selectAllAgents,
    clearFleetSelection,
    setSelectedAgentId,
    filterAgents,
    filterTasks,
    fleetBucketIds,
    agentMatchesFleet,
  };
}
