import React from "react";

export type SafetyAuditViewMode = "intents" | "memory";

export interface SafetyAuditLogViewToggleProps {
  value: SafetyAuditViewMode;
  onChange: (mode: SafetyAuditViewMode) => void;
}

function SafetyAuditLogViewToggle({
  value,
  onChange,
}: SafetyAuditLogViewToggleProps): JSX.Element {
  return (
    <div
      className="safety-audit-log-segmented"
      role="tablist"
      aria-label="Safety log view"
    >
      {(["intents", "memory"] as const).map((mode) => (
        <button
          key={mode}
          type="button"
          role="tab"
          aria-selected={value === mode}
          className={`safety-audit-log-segmented-btn${
            value === mode ? " is-active" : ""
          }`}
          onClick={() => onChange(mode)}
        >
          {mode === "intents" ? "Intents" : "Memory"}
        </button>
      ))}
    </div>
  );
}

export default React.memo(SafetyAuditLogViewToggle);
