import React, { useMemo } from "react";
import { createPortal } from "react-dom";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import { useAgentTasks } from "../../hooks/useAgentTasks";
import { useTradeHistory } from "../../hooks/useTradeHistory";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { formatPrice, formatSize } from "../../sdk/utils/display";
import type { TradeHistoryRow } from "../../sdk/types/data";
import { shortHashId } from "../../utils/hashId";
import AgentTaskTimeline from "./AgentTaskTimeline";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./agentTasks.css";

export interface ExplainActionModalProps {
  isOpen: boolean;
  agentTaskId: string | null;
  baseURL: string;
  walletAddress: string;
  onClose: () => void;
}

function statusPillClassName(tone: string): string {
  return `agent-task-status-pill agent-task-status-pill--${tone}`;
}

function fillSideClassName(side: TradeHistoryRow["side"]): string {
  return side === "Buy" ? "terminal-long" : "terminal-short";
}

function ExplainActionModal({
  isOpen,
  agentTaskId,
  baseURL,
  walletAddress,
  onClose,
}: ExplainActionModalProps): JSX.Element | null {
  const { getAgentById } = useTradingAgents();
  const { tasks } = useAgentTasks();
  const { trades } = useTradeHistory({ baseURL, walletAddress });

  const task = useMemo(
    () => (agentTaskId ? tasks.find((t) => t.id === agentTaskId) ?? null : null),
    [tasks, agentTaskId],
  );

  const agent = task ? getAgentById(task.agentId) : undefined;
  const linkedTrades = useMemo(
    () =>
      agentTaskId
        ? trades.filter((t) => t.agentTaskId === agentTaskId).slice(0, 5)
        : [],
    [trades, agentTaskId],
  );

  const latestMemory = agent?.memory[agent?.memory.length - 1];
  const overlayOpen = isOpen && Boolean(task);
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(overlayOpen);

  useOverlayEscapeKey(overlayOpen, onClose);

  if (!mounted || !task) return null;

  const statusCfg =
    AGENT_TASK_STATUS_CONFIG[task.status] ?? {
      label: task.status,
      tone: "muted" as const,
    };

  const modalContent = (
    <StaggeredOverlayRoot>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content agent-task-detail-modal-content explain-action-modal staggered-overlay-panel--scale terminal-overlay-panel-shell"
        aria-label="Explain agent action"
      >
        <div className="modal-header">
          <h3 className="terminal-panel-title">Why did this happen?</h3>
        </div>
        <div className="modal-body explain-action-modal-body">
          <section className="explain-action-section">
            <div className="terminal-label explain-action-section-label">Intent</div>
            <p className="explain-action-section-text">
              {task.description}
            </p>
          </section>
          {agent ? (
            <section className="explain-action-section">
              <div className="terminal-label explain-action-section-label">Agent</div>
              <p className="explain-action-section-text">
                {agent.icon ? `${agent.icon} ` : ""}
                <span className="terminal-value">{agent.displayName}</span>
              </p>
            </section>
          ) : null}
          {latestMemory ? (
            <section className="explain-action-section">
              <div className="terminal-label explain-action-section-label">
                Memory at decision time
              </div>
              <p className="explain-action-section-text explain-action-section-text--muted">
                {latestMemory.text}
              </p>
            </section>
          ) : null}
          <section className="explain-action-section">
            <div className="terminal-label explain-action-section-label">Task lineage</div>
            <div className="explain-action-lineage">
              <span className="task-id-chip" title={task.id}>
                {shortHashId(task.id)}
              </span>
              <span className={statusPillClassName(statusCfg.tone)}>
                {statusCfg.label}
              </span>
            </div>
          </section>
          {(task.statusHistory?.length ?? 0) > 0 ? (
            <section className="explain-action-section">
              <div className="terminal-label explain-action-section-label">
                Execution trace
              </div>
              <AgentTaskTimeline history={task.statusHistory ?? []} />
            </section>
          ) : null}
          {linkedTrades.length > 0 ? (
            <section className="explain-action-section">
              <div className="terminal-label explain-action-section-label">Linked fills</div>
              <ul className="explain-action-fills">
                {linkedTrades.map((fill) => (
                  <li key={fill.tradeId} className="explain-action-fill-row">
                    <span className={fillSideClassName(fill.side)}>
                      {fill.side}
                    </span>
                    <span className="terminal-value">
                      {formatSize(fill.size)} @ {formatPrice(fill.price)}
                    </span>
                    <span className="explain-action-fill-meta">
                      {fill.direction} · fee {formatPrice(fill.fee)}
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}
        </div>
        <div className="modal-footer">
          <button type="button" onClick={onClose} className="btn btn-secondary">
            Close
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(ExplainActionModal);
