import React, { useMemo } from "react";

import type {
  AgentMetricsByFocus,
  AgentPageMetric,
} from "../../hooks/useAgentPageData";
import {
  AGENT_METRIC_BUBBLE_MAP,
  BubbleTip,
  type BubbleTipId,
} from "../../tutorials/bubble-tip";
import type { AgentHeroFocus } from "./agentHeroFocus";
import { VALID_AGENT_HERO_FOCUSES } from "./agentHeroFocus";
import { AgentFocusTransition } from "./AgentFocusTransition";
import "./agent.css";

export interface AgentMetricsBarProps {
  height?: string;
  metricsByFocus: AgentMetricsByFocus;
  focusKey?: AgentHeroFocus;
  announceChanges?: boolean;
}

function MetricLabel({ label }: { label: string }): JSX.Element {
  const tipId: BubbleTipId | undefined = AGENT_METRIC_BUBBLE_MAP[label];
  const className = tipId
    ? "agent-performance-metric-label agent-performance-metric-label--tip"
    : "agent-performance-metric-label";

  if (tipId) {
    return (
      <BubbleTip id={tipId}>
        <span className={className}>{label}</span>
      </BubbleTip>
    );
  }

  return <span className={className}>{label}</span>;
}

function AgentMetricsStack({
  metrics,
}: {
  metrics: AgentPageMetric[];
}): JSX.Element {
  return (
    <div className="agent-performance-metrics-bar-inner">
      {metrics.map((metric) => (
        <div key={metric.label} className="agent-performance-metric">
          <MetricLabel label={metric.label} />
          <span
            className={`agent-performance-metric-value${metric.tone ? ` ${metric.tone}` : ""}`}
          >
            {metric.value}
          </span>
        </div>
      ))}
    </div>
  );
}

function AgentMetricsBar({
  height = "100%",
  metricsByFocus,
  focusKey = "copy",
  announceChanges = false,
}: AgentMetricsBarProps): JSX.Element {
  const stacks = useMemo(() => {
    const result = {} as Record<AgentHeroFocus, React.ReactNode>;
    for (const focus of VALID_AGENT_HERO_FOCUSES) {
      result[focus] = (
        <AgentMetricsStack key={focus} metrics={metricsByFocus[focus]} />
      );
    }
    return result;
  }, [metricsByFocus]);

  return (
    <div
      className="agent-slot agent-header-band agent-header-band--metrics agent-performance-metrics-bar"
      style={{ height }}
      aria-label="Agent performance metrics"
    >
      <AgentFocusTransition
        focusKey={focusKey}
        stacks={stacks}
        announceChanges={announceChanges}
      />
    </div>
  );
}

export default AgentMetricsBar;
