import React from "react";
import { formatCurrency } from "../../../sdk/utils/display";
import type { CrossChainTransferRecord } from "../../../types/crossChainFlow";
import { getFailureScenario } from "../../../utils/crossChainFailureScenarios";
import { CrossChainSecurityStepper } from "./CrossChainSecurityStepper";
import "./cross-chain.css";

export interface CrossChainFailurePanelProps {
  record: CrossChainTransferRecord;
  onRetry: () => void;
  onKeepPolling: () => void;
  onDemoLinkClick?: () => void;
}

function shortHash(hash?: string): string {
  if (!hash) return "—";
  return `${hash.slice(0, 8)}…${hash.slice(-4)}`;
}

export function CrossChainFailurePanel({
  record,
  onRetry,
  onKeepPolling,
  onDemoLinkClick,
}: CrossChainFailurePanelProps): JSX.Element {
  const failedStage = record.failedStage ?? "attested";
  const scenario = getFailureScenario(
    failedStage,
    record.mode,
    record.assetId,
    record.amount,
    record.chain,
  );

  return (
    <>
      <CrossChainSecurityStepper
        activeStage={failedStage}
        failedStage={failedStage}
        completedStages={
          failedStage === "authorize"
            ? []
            : failedStage === "submit"
              ? ["authorize"]
              : failedStage === "locked"
                ? ["authorize", "submit"]
                : failedStage === "attested"
                  ? ["authorize", "submit", "locked"]
                  : ["authorize", "submit", "locked", "attested"]
        }
      />
      <p className="cross-chain-failure-highlight">
        Stalled at: {scenario.title}
      </p>
      <div className="cross-chain-failure-body">
        <p className="terminal-label">What happened</p>
        <p>{scenario.whatHappened}</p>
        <p className="terminal-label cross-chain-failure-section-gap">
          Fund state
        </p>
        <p>{scenario.fundState}</p>
        {record.originTxHash && (
          <p className="cross-chain-failure-tx">
            Origin tx{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={onDemoLinkClick}
            >
              {shortHash(record.originTxHash)} ↗
            </button>
          </p>
        )}
        {record.messageId && (
          <p className="cross-chain-failure-tx">
            Message id{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={() => {
                void navigator.clipboard?.writeText(record.messageId ?? "");
              }}
            >
              {shortHash(record.messageId)} ↗
            </button>
          </p>
        )}
      </div>
      <div className="cross-chain-success-actions">
        <button type="button" className="btn btn-secondary" onClick={onKeepPolling}>
          {scenario.primaryAction}
        </button>
        <button type="button" className="btn btn-primary" onClick={onRetry}>
          {scenario.secondaryAction}
        </button>
      </div>
    </>
  );
}
