import type {
  CandlestickData,
  IChartApiBase,
  ISeriesApi,
  Time,
} from "lightweight-charts";
import { MismatchDirection } from "lightweight-charts";

/**
 * Resolve the candlestick bar for a marker time, mirroring lightweight-charts
 * SeriesMarkersPrimitive._recalculateMarkers bar lookup.
 */
export function resolveBarAtMarkerTime(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  markerTime: Time,
): CandlestickData | null {
  const timeScale = chart.timeScale();
  const seriesData = series.data();
  if (seriesData.length === 0) return null;

  const timePointIndex = timeScale.timeToIndex(markerTime, true);
  if (timePointIndex === null) return null;

  const firstDataIndex = timeScale.timeToIndex(seriesData[0].time, true);
  if (firstDataIndex === null) return null;

  const searchMode =
    timePointIndex < firstDataIndex
      ? MismatchDirection.NearestRight
      : MismatchDirection.NearestLeft;

  const bar = series.dataByIndex(timePointIndex, searchMode) as CandlestickData | null;
  if (!bar || bar.high === undefined || bar.low === undefined) return null;

  return bar;
}

/** Logical index of the resolved bar (matches native indexed marker.time). */
export function resolveMarkerLogicalIndex(
  chart: IChartApiBase<Time>,
  bar: CandlestickData,
): number | null {
  return chart.timeScale().timeToIndex(bar.time, false);
}
