import React, { useMemo } from "react";

import {
  COMPACT_CHART_HEIGHT,
  COMPACT_CHART_NEGATIVE,
  COMPACT_CHART_POSITIVE,
  COMPACT_CHART_WIDTH,
} from "./compactChartTheme";
import type { CompactMetricTone } from "./types";
import { metricToneClassName } from "./types";

export interface CompactSparklineProps {
  values?: number[];
  tone?: CompactMetricTone;
  className?: string;
}

function CompactSparkline({
  values,
  tone = "neutral",
  className = "",
}: CompactSparklineProps): JSX.Element {
  const points = useMemo(() => {
    const cleanValues = Array.isArray(values)
      ? values.filter((value) => Number.isFinite(value))
      : [];

    if (cleanValues.length < 2) {
      return `0,${COMPACT_CHART_HEIGHT / 2} ${COMPACT_CHART_WIDTH},${COMPACT_CHART_HEIGHT / 2}`;
    }

    const min = Math.min(...cleanValues);
    const max = Math.max(...cleanValues);

    return cleanValues
      .map((value, index) => {
        const x = (index / (cleanValues.length - 1)) * COMPACT_CHART_WIDTH;
        const normalized = max === min ? 0.5 : (value - min) / (max - min);
        const y = COMPACT_CHART_HEIGHT - normalized * COMPACT_CHART_HEIGHT;
        return `${x},${y}`;
      })
      .join(" ");
  }, [values]);

  const toneClass = metricToneClassName(tone);
  const strokeColor =
    tone === "positive"
      ? COMPACT_CHART_POSITIVE
      : tone === "negative"
        ? COMPACT_CHART_NEGATIVE
        : undefined;

  return (
    <svg
      viewBox={`0 0 ${COMPACT_CHART_WIDTH} ${COMPACT_CHART_HEIGHT}`}
      aria-hidden
      className={`compact-metric-sparkline ${toneClass} ${className}`.trim()}
      style={strokeColor ? { color: strokeColor } : undefined}
    >
      <polyline
        points={points}
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export default React.memo(CompactSparkline);
