import {
  getAgentProfileById,
  getFleetAgentByCatalogId,
} from "../../offline/mock_data";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import type { FleetAgentRecord } from "../../offline/mock_data/fleetCatalog";
import type { PropertyProfile } from "../../offline/mock_data/types";
import {
  AGENT_COMPARE_FOCUS_OPTIONS,
  type AgentCompareFocus,
} from "../components/agent/agentCompareFocus";
import {
  buildCompareFocusMetrics,
  type AgentCompareMetricEntry,
} from "../components/agent/agentCompareFocusMetrics";
import { markBestCompareCells } from "./agentCompareMetricRank";
import { buildFleetDailyPnlByDay } from "./agentCompareDailyPnl";
import { MAX_AGENT_COMPARE } from "./agentCompareIds";
import type { DailyPnlDay } from "./portfolioChartData";

export interface CompareAgentColumn {
  id: string;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
}

export interface CompareMatrixCell {
  value: string;
  tone?: "positive" | "negative" | "neutral";
  isBest?: boolean;
  listItems?: string[];
}

export type CompareMatrixRowKind = "metric" | "dailyPnlCalendar" | "list";

export interface CompareMatrixRow {
  label: string;
  kind?: CompareMatrixRowKind;
  cells: Array<CompareMatrixCell | null>;
  calendarCells?: Array<DailyPnlDay[] | null>;
}

export interface CompareMatrixSection {
  focus: AgentCompareFocus;
  label: string;
  hint: string;
  rows: CompareMatrixRow[];
}

function resolveSectionEntries(
  focus: AgentCompareFocus,
  profile: PropertyProfile,
  fleet: FleetAgentRecord,
  catalogAgentId: string,
): AgentCompareMetricEntry[] {
  return buildCompareFocusMetrics(focus, profile, fleet, catalogAgentId);
}

function entryToCell(entry: AgentCompareMetricEntry): CompareMatrixCell | null {
  if (entry.kind === "list") {
    return {
      value: entry.items.join(" · "),
      listItems: entry.items,
      tone: "neutral",
    };
  }
  if (entry.value == null) return null;
  return {
    value: entry.value,
    tone: entry.tone,
  };
}

function resolveRowKind(
  label: string,
  entriesByAgent: AgentCompareMetricEntry[][],
): CompareMatrixRowKind {
  for (const entries of entriesByAgent) {
    const entry = entries.find((item) => item.label === label);
    if (entry?.kind === "list") return "list";
  }
  return "metric";
}

function buildSectionRows(
  focus: AgentCompareFocus,
  agents: CompareAgentColumn[],
  columnCount: number,
): CompareMatrixRow[] {
  const entriesByAgent = agents.map((agent) =>
    resolveSectionEntries(focus, agent.profile, agent.fleet, agent.id),
  );

  const labelOrder: string[] = [];
  for (const entries of entriesByAgent) {
    for (const entry of entries) {
      if (!labelOrder.includes(entry.label)) {
        labelOrder.push(entry.label);
      }
    }
  }

  return labelOrder.map((label) => {
    const kind = resolveRowKind(label, entriesByAgent);
    const cells = Array.from({ length: columnCount }, (_, columnIndex) => {
      if (columnIndex >= agents.length) return null;
      const entry = entriesByAgent[columnIndex]?.find((item) => item.label === label);
      if (!entry) return null;
      return entryToCell(entry);
    });

    const rankedCells =
      kind === "metric" ? markBestCompareCells(label, cells) : cells;

    return {
      label,
      kind,
      cells: rankedCells,
    };
  });
}

function buildPerformanceCalendarRow(
  agents: CompareAgentColumn[],
  columnCount: number,
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
): CompareMatrixRow {
  return {
    label: "Daily PnL",
    kind: "dailyPnlCalendar",
    cells: Array.from({ length: columnCount }, () => null),
    calendarCells: Array.from({ length: columnCount }, (_, columnIndex) => {
      if (columnIndex >= agents.length) return null;
      const agentId = agents[columnIndex]!.id;
      const trades = tradesByAgentId.get(agentId) ?? [];
      return buildFleetDailyPnlByDay(trades);
    }),
  };
}

function insertPerformanceCalendarRow(
  rows: CompareMatrixRow[],
  agents: CompareAgentColumn[],
  columnCount: number,
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
): CompareMatrixRow[] {
  const calendarRow = buildPerformanceCalendarRow(agents, columnCount, tradesByAgentId);
  const pnl30Index = rows.findIndex((row) => row.label === "30d PnL");
  if (pnl30Index >= 0) {
    return [...rows.slice(0, pnl30Index), calendarRow, ...rows.slice(pnl30Index)];
  }
  return [calendarRow, ...rows];
}

function buildSectionRowsWithFocus(
  focus: AgentCompareFocus,
  agents: CompareAgentColumn[],
  columnCount: number,
  tradesByAgentId: Map<string, FleetTradeEvent[]>,
): CompareMatrixRow[] {
  const rows = buildSectionRows(focus, agents, columnCount);
  if (focus !== "performance") return rows;
  return insertPerformanceCalendarRow(rows, agents, columnCount, tradesByAgentId);
}

export function loadCompareAgents(ids: string[]): CompareAgentColumn[] {
  const agents: CompareAgentColumn[] = [];
  for (const id of ids) {
    const profile = getAgentProfileById(id);
    const fleet = getFleetAgentByCatalogId(id);
    if (!profile || !fleet) continue;
    agents.push({ id, profile, fleet });
  }
  return agents;
}

export function resolveCompareMatrixColumnCount(compareIdsLength: number): number {
  return Math.min(Math.max(compareIdsLength, 2), MAX_AGENT_COMPARE);
}

export function buildCompareMatrixGridColumns(
  columnCount: number,
  showAddSlot: boolean,
): string {
  const add = showAddSlot ? "var(--agent-compare-matrix-add-width) " : "";
  return `var(--agent-compare-matrix-label-width) ${add}repeat(${columnCount}, minmax(0, 1fr))`;
}

export function buildCompareMatrixSections(
  agents: CompareAgentColumn[],
  columnCount = resolveCompareMatrixColumnCount(agents.length),
  tradesByAgentId: Map<string, FleetTradeEvent[]> = new Map(),
): CompareMatrixSection[] {
  return AGENT_COMPARE_FOCUS_OPTIONS.map((option) => ({
    focus: option.value,
    label: option.label,
    hint: option.hint,
    rows: buildSectionRowsWithFocus(option.value, agents, columnCount, tradesByAgentId),
  }));
}

export function resolveActiveSection(
  sections: CompareMatrixSection[],
  compareFocus: AgentCompareFocus,
): CompareMatrixSection | undefined {
  return sections.find((section) => section.focus === compareFocus);
}
