import React from "react";
import { toast } from "sonner";
import { formatCurrency } from "../../../sdk/utils/display";
import type { DemoCreateBucketResult } from "../../../../offline/mock_data";
import "../cross-chain/cross-chain.css";

export interface CreateBucketSuccessPanelProps {
  result: DemoCreateBucketResult;
  postCreateSpotBalance?: number | null;
  onDone: () => void;
  onCreateAnother: () => void;
  onDemoLinkClick?: () => void;
}

function shortHash(hash?: string): string {
  if (!hash) return "—";
  return `${hash.slice(0, 8)}…${hash.slice(-4)}`;
}

function demoLinkToast(): void {
  toast.message("Demo explorer link", {
    description: "Explorer links are disabled in demo mode.",
  });
}

export function CreateBucketSuccessPanel({
  result,
  postCreateSpotBalance = null,
  onDone,
  onCreateAnother,
  onDemoLinkClick = demoLinkToast,
}: CreateBucketSuccessPanelProps): JSX.Element {
  const marginLabel =
    result.marginType === "isolated" ? "Isolated" : "Cross";
  const fundedLabel =
    result.amount > 0
      ? `${formatCurrency(result.amount)} ${result.collateralAsset}`
      : "No initial funding";

  return (
    <>
      <div className="cross-chain-success-amount">
        {result.bucketMode === "reused" ? "Reused" : "Created"} {marginLabel}{" "}
        margin bucket
        {result.amount > 0 ? (
          <>
            {" "}
            with {fundedLabel}
          </>
        ) : null}
      </div>
      <p className="cross-chain-success-balance">
        Bucket ID: {result.bucketId}
      </p>
      {postCreateSpotBalance != null && result.fundFrom === "spot-wallet" ? (
        <p className="cross-chain-success-balance">
          Spot balance: {formatCurrency(postCreateSpotBalance)}{" "}
          {result.collateralAsset}
        </p>
      ) : null}
      <div className="cross-chain-tx-links">
        <p>
          Create tx{" "}
          <button
            type="button"
            className="cross-chain-explorer-link"
            onClick={onDemoLinkClick}
          >
            {shortHash(result.txHash)} ↗
          </button>
        </p>
        {result.fundTxHash ? (
          <p>
            Fund tx{" "}
            <button
              type="button"
              className="cross-chain-explorer-link"
              onClick={onDemoLinkClick}
            >
              {shortHash(result.fundTxHash)} ↗
            </button>
          </p>
        ) : null}
      </div>
      <div className="cross-chain-success-actions">
        <button type="button" className="btn btn-primary" onClick={onDone}>
          Done
        </button>
        <button
          type="button"
          className="btn btn-secondary"
          onClick={onCreateAnother}
        >
          Create another
        </button>
      </div>
    </>
  );
}
