import React from "react";
import KpiCard from "./KpiCard";
import QueryState from "./QueryState";
import { fmtInt } from "./format";
import { useNetworkKpis } from "./useNetworkKpis";
import type { Status } from "./StatusDot";

export default function NetworkKpisSection(): React.JSX.Element {
  const { data, isPending, isError, error } = useNetworkKpis();

  const validatorStatus: Status | undefined =
    data === undefined
      ? undefined
      : data.activeValidators > 0 && data.activeValidators === data.totalValidators
        ? "ok"
        : data.activeValidators > 0
          ? "warn"
          : "down";

  return (
    <QueryState
      isLoading={isPending}
      isError={isError}
      error={error}
      label="chain KPIs"
    >
      <div className="nh-kpi-grid nh-kpi-grid-4">
        <KpiCard
          label="Active validators"
          value={fmtInt(data?.activeValidators)}
          unit={data ? `/ ${fmtInt(data.totalValidators)}` : undefined}
          status={validatorStatus}
          info="Validators currently producing and certifying blocks, out of the full registered set. Consensus stays safe while more than two-thirds are honest and online."
        />
        <KpiCard
          label="Confirmed blocks"
          value={fmtInt(data?.confirmedBlocks)}
          unit={data ? `/ ${fmtInt(data.totalBlocks)}` : undefined}
          info="Blocks that have reached finality, out of all blocks produced in the DAG. Confirmed blocks are settled and irreversible."
        />
        <KpiCard
          label="Finality rate"
          value={fmtInt(data?.finalityRate)}
          unit="%"
          info="Share of produced blocks that have reached finality (confirmed / total). The chain self-heals from faults, so this trends back toward full health after any disruption."
        />
        <KpiCard
          label="Latest tips"
          value={fmtInt(data?.latestTips)}
          info="Number of current frontier blocks (tips) at the edge of the DAG awaiting extension. Morpheum's DAG admits multiple concurrent tips, unlike a single-chain head."
        />
      </div>
    </QueryState>
  );
}
