import { useMemo } from "react";
import type { TradingMode } from "../configs/tradeLayoutMode";
import { useAgentTasks } from "./useAgentTasks";
import {
  autonomyPolicyForTradingMode,
  type AutonomyPolicy,
} from "../components/tradeagent/autonomyPolicy";
import {
  countByReportTierResolved,
  countNeedsYouResolved,
  getTaskReportingMetaResolved,
  isNeedsYouTaskResolved,
  selectSpotlightIntentResolved,
  sortByReportTierResolved,
  type TierCounts,
} from "../components/tradeagent/reportTier";
import type { AgentTask } from "../store/types";
import {
  createTaskPolicyResolver,
  useBucketPolicyStore,
} from "../store/bucketPolicyStore";

export type { TierCounts } from "../components/tradeagent/reportTier";
export { reportTierLabel } from "../components/tradeagent/reportTier";

export interface TaskWithReporting extends AgentTask {
  reporting: ReturnType<typeof getTaskReportingMetaResolved>;
}

export interface UseReportTierTasksResult {
  policy: AutonomyPolicy;
  tierCounts: TierCounts;
  needsYouCount: number;
  escalated: boolean;
  spotlight: AgentTask | null;
  queuedGated: AgentTask[];
  liveTasks: TaskWithReporting[];
  silentCount: number;
  fyiCount: number;
  watchingCount: number;
  liveExecutingCount: number;
  resolvePolicyForTask: (task: AgentTask) => AutonomyPolicy;
}

export function useReportTierTasks(
  tradingMode: TradingMode = "highAgency",
  activeBucketId?: string | null,
): UseReportTierTasksResult {
  const { tasks } = useAgentTasks();
  const policies = useBucketPolicyStore((s) => s.policies);

  const defaultPolicy = useMemo(
    () => autonomyPolicyForTradingMode(tradingMode),
    [tradingMode],
  );

  const resolvePolicyForTask = useMemo(
    () => createTaskPolicyResolver(tradingMode),
    [tradingMode, policies],
  );

  const policy = useMemo(() => {
    if (activeBucketId && activeBucketId !== "--") {
      return useBucketPolicyStore
        .getState()
        .getPolicy(activeBucketId, defaultPolicy);
    }
    return defaultPolicy;
  }, [activeBucketId, defaultPolicy, policies]);

  const liveTasks = useMemo(() => {
    const active = tasks.filter(
      (t) => t.status !== "completed" && t.status !== "rejected",
    );
    return sortByReportTierResolved(active, resolvePolicyForTask).map(
      (task) => ({
        ...task,
        reporting: getTaskReportingMetaResolved(task, resolvePolicyForTask),
      }),
    );
  }, [tasks, resolvePolicyForTask]);

  const tierCounts = useMemo(
    () => countByReportTierResolved(tasks, resolvePolicyForTask),
    [tasks, resolvePolicyForTask],
  );

  const needsYouCount = useMemo(
    () => countNeedsYouResolved(tasks, resolvePolicyForTask),
    [tasks, resolvePolicyForTask],
  );

  const spotlight = useMemo(
    () => selectSpotlightIntentResolved(tasks, resolvePolicyForTask),
    [tasks, resolvePolicyForTask],
  );

  const queuedGated = useMemo(() => {
    if (!spotlight) {
      return tasks.filter((t) =>
        isNeedsYouTaskResolved(t, resolvePolicyForTask),
      );
    }
    return tasks.filter(
      (t) =>
        t.id !== spotlight.id &&
        isNeedsYouTaskResolved(t, resolvePolicyForTask),
    );
  }, [tasks, resolvePolicyForTask, spotlight]);

  const silentCount = tierCounts.T0;
  const fyiCount = tierCounts.T2;
  const watchingCount = tasks.filter((t) => t.status === "watching").length;
  const liveExecutingCount = tasks.filter((t) => t.status === "executing").length;

  const escalated =
    tradingMode === "highAgency" && needsYouCount > 0;

  return {
    policy,
    tierCounts,
    needsYouCount,
    escalated,
    spotlight,
    queuedGated,
    liveTasks,
    silentCount,
    fyiCount,
    watchingCount,
    liveExecutingCount,
    resolvePolicyForTask,
  };
}
