import React, { useMemo, useState } from "react";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { usePositions } from "../../hooks/usePositions";
import { buildPerformanceMetricRows } from "../../utils/portfolioPerformanceMetrics";
import PortfolioLedgerRow from "./PortfolioLedgerRow";
import {
  PERFORMANCE_MARKET_OPTIONS,
  PERFORMANCE_TIME_RANGE_OPTIONS,
  type PerformanceMarket,
  type PerformanceTimeRange,
} from "./portfolioPerformanceMock";
import "./portfolio.css";

export interface PortfolioPerformanceMetricsPanelProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  refreshInterval?: number;
}

function PortfolioPerformanceMetricsPanel({
  height = "100%",
  baseURL,
  walletAddress,
  filterAgentIds = [],
  refreshInterval,
}: PortfolioPerformanceMetricsPanelProps): JSX.Element {
  const [market, setMarket] = useState<PerformanceMarket>("perps");
  const [timeRange, setTimeRange] = useState<PerformanceTimeRange>("all");

  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds,
    refreshInterval,
  });
  const { collections, spotWalletBalance } = useBucketCollections({
    baseURL,
    walletAddress,
  });
  const { positions } = usePositions({ baseURL, walletAddress });

  const rows = useMemo(
    () =>
      buildPerformanceMetricRows({
        trades: analytics.trades,
        taskAgentMap: analytics.taskAgentMap,
        filterAgentIds,
        accountEquity: analytics.accountEquity,
        spotWalletBalance,
        collections,
        positions,
        market,
        timeRange,
      }),
    [
      analytics.trades,
      analytics.taskAgentMap,
      analytics.accountEquity,
      spotWalletBalance,
      collections,
      positions,
      filterAgentIds,
      market,
      timeRange,
    ],
  );

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section
        className="portfolio-ledger-panel"
        aria-label="Performance metrics"
      >
        <div className="portfolio-ledger-panel-toolbar">
          <select
            className="portfolio-hero-time-range"
            value={market}
            onChange={(event) =>
              setMarket(event.target.value as PerformanceMarket)
            }
            aria-label="Market type"
          >
            {PERFORMANCE_MARKET_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
          <select
            className="portfolio-hero-time-range"
            value={timeRange}
            onChange={(event) =>
              setTimeRange(event.target.value as PerformanceTimeRange)
            }
            aria-label="Time range"
          >
            {PERFORMANCE_TIME_RANGE_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>
        <div className="portfolio-ledger-panel-body">
          {rows.map((row) => (
            <PortfolioLedgerRow
              key={row.label}
              label={row.label}
              value={row.value}
              valueClassName={row.valueClassName}
            />
          ))}
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioPerformanceMetricsPanel);
