import { getAgentProfileById } from "../../offline/mock_data";
import type { FleetTradeEvent } from "../../offline/mock_data/fleetTradeHistory.types";
import type { DailyPnlDay } from "./portfolioChartData";

function toDateKey(ms: number): string {
  const d = new Date(ms);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function startOfDayMs(ms: number): number {
  const d = new Date(ms);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

function parseFleetTradeTimeMs(trade: FleetTradeEvent): number {
  return new Date(trade.timestamp).getTime();
}

export function buildFleetDailyPnlByDay(
  trades: FleetTradeEvent[],
  referenceDate = new Date(),
): DailyPnlDay[] {
  const year = referenceDate.getFullYear();
  const month = referenceDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const buckets = new Map<string, number>();

  for (const trade of trades) {
    const pnl = trade.closedPnl;
    if (pnl == null) continue;

    const tradeMs = parseFleetTradeTimeMs(trade);
    const tradeDate = new Date(tradeMs);
    if (tradeDate.getFullYear() !== year || tradeDate.getMonth() !== month) {
      continue;
    }

    const key = toDateKey(tradeMs);
    buckets.set(key, (buckets.get(key) ?? 0) + pnl);
  }

  const todayStart = startOfDayMs(referenceDate.getTime());
  const result: DailyPnlDay[] = [];

  for (let day = 1; day <= daysInMonth; day += 1) {
    const dateKey = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const dayStart = startOfDayMs(new Date(year, month, day).getTime());

    if (dayStart > todayStart) {
      result.push({ dateKey, dayOfMonth: day, pnl: null, isEmpty: true });
      continue;
    }

    const pnl = buckets.get(dateKey);
    if (pnl === undefined) {
      result.push({ dateKey, dayOfMonth: day, pnl: null, isEmpty: true });
    } else {
      result.push({ dateKey, dayOfMonth: day, pnl, isEmpty: false });
    }
  }

  return result;
}

export function sumFleetDailyPnl(days: DailyPnlDay[]): number {
  return days.reduce((sum, day) => sum + (day.pnl ?? 0), 0);
}
