import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the markets page layout */
export const MARKETS_SLOT_INDICES = {
  hero: 0,
  toolbar: 1,
  filters: 2,
  table: 3,
  metrics: 5,
} as const;

export const MARKETS_TABLE_SLOT_INDEX = MARKETS_SLOT_INDICES.table;

/** Slots collapsed on all breakpoints */
export const MARKETS_COLLAPSED_SLOTS = [4, 6, 7, 8] as const;

export const MARKETS_ROW_HEIGHT = 30;
export const MARKETS_MENUBAR_HEIGHT = 54;
export const MARKETS_LAYOUT_MARGIN = 10;
export const MARKETS_VIEWPORT_FUDGE_PX = 4;

export const MARKETS_TITLE_ROWS = 2;
export const MARKETS_METRICS_ROWS = 2;
export const MARKETS_TOOLBAR_ROWS = 2;
export const MARKETS_FILTERS_ROWS_STACKED = 8;
export const MARKETS_BASE_TABLE_ROWS = 12;
export const MARKETS_SCROLL_TABLE_ROWS = 20;

export const MARKETS_TITLE_COLS_LG = 4;
export const MARKETS_METRICS_COLS_LG = 8;
export const MARKETS_FILTERS_COLS_LG = 3;
export const MARKETS_TABLE_COLS_LG = 9;

export const MARKETS_TOOLBAR_START_ROW = MARKETS_TITLE_ROWS;
export const MARKETS_BODY_START_ROW =
  MARKETS_TOOLBAR_START_ROW + MARKETS_TOOLBAR_ROWS;

export const MARKETS_STACKED_METRICS_START_ROW = MARKETS_TITLE_ROWS;
export const MARKETS_STACKED_TOOLBAR_START_ROW =
  MARKETS_STACKED_METRICS_START_ROW + MARKETS_METRICS_ROWS;
export const MARKETS_STACKED_FILTERS_START_ROW =
  MARKETS_STACKED_TOOLBAR_START_ROW + MARKETS_TOOLBAR_ROWS;
export const MARKETS_STACKED_TABLE_START_ROW =
  MARKETS_BODY_START_ROW + MARKETS_FILTERS_ROWS_STACKED;
export const MARKETS_MOBILE_TABLE_START_ROW =
  MARKETS_STACKED_FILTERS_START_ROW + MARKETS_FILTERS_ROWS_STACKED;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_MID: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function splitTitleMetricsCols(cols: number): {
  titleW: number;
  metricsW: number;
  metricsX: number;
} {
  const titleW = Math.round(cols / 3);
  const metricsW = cols - titleW;
  return { titleW, metricsW, metricsX: titleW };
}

function titleMetricsSlot5(
  cols: number,
  stacked: boolean,
): [LayoutDefinition, LayoutDefinition] {
  if (stacked) {
    return [
      [0, 0, cols, MARKETS_TITLE_ROWS],
      [0, MARKETS_STACKED_METRICS_START_ROW, cols, MARKETS_METRICS_ROWS],
    ];
  }

  if (cols === 12) {
    return [
      [0, 0, MARKETS_TITLE_COLS_LG, MARKETS_TITLE_ROWS],
      [MARKETS_TITLE_COLS_LG, 0, MARKETS_METRICS_COLS_LG, MARKETS_METRICS_ROWS],
    ];
  }

  const { titleW, metricsW, metricsX } = splitTitleMetricsCols(cols);
  return [
    [0, 0, titleW, MARKETS_TITLE_ROWS],
    [metricsX, 0, metricsW, MARKETS_METRICS_ROWS],
  ];
}

function desktopMarketsLayout(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, MARKETS_TOOLBAR_START_ROW, cols, MARKETS_TOOLBAR_ROWS],
    [
      0,
      MARKETS_BODY_START_ROW,
      MARKETS_FILTERS_COLS_LG,
      MARKETS_BASE_TABLE_ROWS,
    ],
    [
      MARKETS_FILTERS_COLS_LG,
      MARKETS_BODY_START_ROW,
      MARKETS_TABLE_COLS_LG,
      MARKETS_BASE_TABLE_ROWS,
    ],
    COLLAPSED_MID,
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

function stackedMarketsLayout(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, MARKETS_TOOLBAR_START_ROW, cols, MARKETS_TOOLBAR_ROWS],
    [0, MARKETS_BODY_START_ROW, cols, MARKETS_FILTERS_ROWS_STACKED],
    [0, MARKETS_STACKED_TABLE_START_ROW, cols, MARKETS_BASE_TABLE_ROWS],
    COLLAPSED_MID,
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

function mobileMarketsLayout(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, true);
  return [
    titleSlot,
    [0, MARKETS_STACKED_TOOLBAR_START_ROW, cols, MARKETS_TOOLBAR_ROWS],
    [0, MARKETS_STACKED_FILTERS_START_ROW, cols, MARKETS_FILTERS_ROWS_STACKED],
    [0, MARKETS_MOBILE_TABLE_START_ROW, cols, MARKETS_BASE_TABLE_ROWS],
    COLLAPSED_MID,
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

export const marketsLayoutLg: LayoutConfigLest = desktopMarketsLayout(12);
export const marketsLayoutMd: LayoutConfigLest = stackedMarketsLayout(10);
export const marketsLayoutSm: LayoutConfigLest = stackedMarketsLayout(6);
export const marketsLayoutXs: LayoutConfigLest = mobileMarketsLayout(4);
export const marketsLayoutXxs: LayoutConfigLest = mobileMarketsLayout(2);

export function buildMarketsResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, MARKETS_COLLAPSED_SLOTS);

  return {
    lg: collapseAll(marketsLayoutLg),
    md: collapseAll(marketsLayoutMd),
    sm: collapseAll(marketsLayoutSm),
    xs: collapseAll(marketsLayoutXs),
    xxs: collapseAll(marketsLayoutXxs),
  };
}

export function generateMarketsResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

function patchTableSlotHeight(
  layout: LayoutConfigLest,
  tableRows: number,
): LayoutConfigLest {
  const tableSlot = layout[MARKETS_TABLE_SLOT_INDEX];
  const filtersSlot = layout[MARKETS_SLOT_INDICES.filters];
  if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) return layout;

  const tableStart = tableSlot[1];
  const nextTable: LayoutDefinition = [
    tableSlot[0],
    tableStart,
    tableSlot[2],
    tableRows,
  ];

  let nextFilters = filtersSlot;
  if (
    filtersSlot &&
    filtersSlot[2] !== 0 &&
    filtersSlot[3] !== 0 &&
    filtersSlot[1] === tableStart &&
    filtersSlot[0] !== tableSlot[0]
  ) {
    nextFilters = [filtersSlot[0], tableStart, filtersSlot[2], tableRows];
  }

  return layout.map((item, index) => {
    if (index === MARKETS_TABLE_SLOT_INDEX) return nextTable;
    if (index === MARKETS_SLOT_INDICES.filters && nextFilters) return nextFilters;
    return item;
  });
}

export function patchMarketsScrollTableHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTableSlotHeight(layout, MARKETS_SCROLL_TABLE_ROWS);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/** Fixed table rows on all breakpoints; page scrolls vertically. */
export function applyMarketsLayoutSizing(
  config: ResponsiveLayoutConfig,
  _viewportHeight?: number,
): ResponsiveLayoutConfig {
  return patchMarketsScrollTableHeights(config);
}

export function assertMarketsLayoutValid(config: ResponsiveLayoutConfig): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `markets ${bp}`);
  }
}
