export const OFFLINE_CREATE_BUCKET_STABLE_TOAST_ID = "offline:create-bucket";

export type OfflineCreateBucketStepId =
  | "sign"
  | "submit"
  | "consensus"
  | "fund";

export type OfflineCreateBucketStep = {
  id: OfflineCreateBucketStepId;
  loadingMessage: string;
  loadingDescription: string;
  delayMs: number;
};

export type OfflineCreateBucketStepParams = {
  amount: number;
  collateralAsset: string;
  fundFrom: string;
};

const BASE_STEPS: OfflineCreateBucketStep[] = [
  {
    id: "sign",
    loadingMessage: "Signing transaction…",
    loadingDescription: "Building EIP-712 payload",
    delayMs: 400,
  },
  {
    id: "submit",
    loadingMessage: "Submitting to morphcore…",
    loadingDescription: "Broadcasting /tx/v1/submit",
    delayMs: 500,
  },
  {
    id: "consensus",
    loadingMessage: "Awaiting consensus…",
    loadingDescription: "Creating margin bucket",
    delayMs: 600,
  },
];

function formatFundFrom(fundFrom: string): string {
  return fundFrom === "spot-wallet" ? "Spot Wallet" : fundFrom;
}

/** Staged on-chain steps for offline create-bucket demo toasts. */
export function getOfflineCreateBucketSteps(
  params: OfflineCreateBucketStepParams,
): OfflineCreateBucketStep[] {
  const steps = [...BASE_STEPS];

  if (params.amount > 0) {
    steps.push({
      id: "fund",
      loadingMessage: "Transferring collateral…",
      loadingDescription: `${params.amount} ${params.collateralAsset} from ${formatFundFrom(params.fundFrom)}`,
      delayMs: 500,
    });
  }

  return steps;
}
