import type {
  IndexPerformanceMetrics,
  PropertyIndexProfile,
} from "../../../../offline/mock_data/types";
import { APP_ROUTES } from "../../../routes";
import type { ResolvedIndexConstituent } from "../../../utils/indexConstituents";
import { formatPercent } from "../indexFormat";

export const SHARE_CARD_WIDTH_PX = 480;
export const SHARE_CONSTITUENT_COLORS = [
  "#06b6d4",
  "#34d399",
  "#60a5fa",
  "#fbbf24",
  "#a78bfa",
] as const;

export interface IndexShareChartPoint {
  indexPct: number;
  btcPct: number;
}

export interface IndexShareConstituentSlice {
  name: string;
  ticker: string;
  icon: string;
  weight: number;
  color: string;
}

export interface IndexSharePayload {
  profile: PropertyIndexProfile;
  modeLabel?: string;
  constituents: ResolvedIndexConstituent[];
  performanceMetrics: IndexPerformanceMetrics;
}

function expandSeriesToYear(values: number[]): number[] {
  if (values.length === 0) return [];
  if (values.length >= 52) return values.slice(-52);

  const targetLength = 52;
  const result: number[] = [];
  for (let i = 0; i < targetLength; i++) {
    const sourceIndex = (i / (targetLength - 1)) * (values.length - 1);
    const lower = Math.floor(sourceIndex);
    const upper = Math.ceil(sourceIndex);
    const fraction = sourceIndex - lower;
    const lowerValue = values[lower] ?? values[0]!;
    const upperValue = values[upper] ?? values[values.length - 1]!;
    result.push(lowerValue + (upperValue - lowerValue) * fraction);
  }
  return result;
}

function normalizeToPercentRoi(values: number[]): number[] {
  if (values.length === 0) return [];
  const base = values[0]!;
  if (base === 0) return values.map(() => 0);
  return values.map((value) => ((value - base) / base) * 100);
}

export function buildShareChartSeries(
  chartSeries: number[],
  roi1yVsBtc: number,
): IndexShareChartPoint[] {
  const expanded = expandSeriesToYear(chartSeries);
  const indexPct = normalizeToPercentRoi(expanded);
  const indexEnd = indexPct[indexPct.length - 1] ?? 0;
  const btcEnd = indexEnd - roi1yVsBtc;

  return indexPct.map((value, index) => {
    const progress = indexPct.length <= 1 ? 1 : index / (indexPct.length - 1);
    const btcPct = progress * btcEnd;
    return { indexPct: value, btcPct };
  });
}

export function getTopShareConstituents(
  constituents: ResolvedIndexConstituent[],
  limit = 5,
): IndexShareConstituentSlice[] {
  return [...constituents]
    .sort((a, b) => b.weight - a.weight)
    .slice(0, limit)
    .map((item, index) => ({
      name: item.name,
      ticker: item.ticker,
      icon: item.icon,
      weight: item.weight,
      color: SHARE_CONSTITUENT_COLORS[index % SHARE_CONSTITUENT_COLORS.length]!,
    }));
}

export function buildShareUrl(ticker: string): string {
  if (typeof window === "undefined") {
    return `${APP_ROUTES.index}/${ticker}`;
  }
  return `${window.location.origin}${APP_ROUTES.index}/${ticker}`;
}

export function buildShareText(
  profile: PropertyIndexProfile,
  metrics: IndexPerformanceMetrics,
): string {
  return `${profile.name} (${profile.ticker}) on Morpheum — ${formatPercent(metrics.change24h)} 24H`;
}

export function formatShareTimestamp(date = new Date()): string {
  return date.toLocaleString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function buildTwitterShareUrl(text: string, url: string): string {
  const params = new URLSearchParams({ text, url });
  return `https://twitter.com/intent/tweet?${params.toString()}`;
}

export function buildTelegramShareUrl(text: string, url: string): string {
  const params = new URLSearchParams({ url, text });
  return `https://t.me/share/url?${params.toString()}`;
}
