import { useCallback, useEffect, useRef, useState } from "react";
import type { FeedEnterState } from "./feedAnimation";
import { useFeedEnter } from "./useFeedEnter";
import {
  generateXNews,
  MIN_X_NEWS_SEED_COUNT,
  type GeneratedXNews,
} from "./xNewsExamples";

export const DEFAULT_X_NEWS_CAPACITY = 4;
export const MIN_INTERVAL_MS = 8_000;
export const MAX_INTERVAL_MS = 25_000;
export const SEED_STAGGER_MS = 120;

function randomIntervalMs(): number {
  return MIN_INTERVAL_MS + Math.random() * (MAX_INTERVAL_MS - MIN_INTERVAL_MS);
}

export interface UseXNewsStreamResult {
  items: GeneratedXNews[];
  enterState: FeedEnterState | null;
}

export function useXNewsStream(
  baseAsset: string,
  enabled: boolean,
  maxVisibleItems = DEFAULT_X_NEWS_CAPACITY,
): UseXNewsStreamResult {
  const [items, setItems] = useState<GeneratedXNews[]>([]);
  const { enterState, markEntering, clearEnter } = useFeedEnter();

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const seedTimeoutsRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const baseAssetRef = useRef(baseAsset);
  const maxVisibleRef = useRef(maxVisibleItems);

  const clearTimers = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    seedTimeoutsRef.current.forEach(clearTimeout);
    seedTimeoutsRef.current = [];
    clearEnter();
  }, [clearEnter]);

  const trimToCapacity = useCallback((list: GeneratedXNews[]) => {
    const cap = Math.max(1, maxVisibleRef.current);
    return list.slice(0, cap);
  }, []);

  const prependItem = useCallback(
    (asset: string) => {
      const next = generateXNews(asset);
      markEntering(next.instanceId);
      setItems((prev) => trimToCapacity([next, ...prev]));
    },
    [markEntering, trimToCapacity],
  );

  const scheduleNext = useCallback(
    (asset: string) => {
      if (!asset || !enabled) return;
      timeoutRef.current = setTimeout(() => {
        if (baseAssetRef.current !== asset) return;
        prependItem(asset);
        scheduleNext(asset);
      }, randomIntervalMs());
    },
    [enabled, prependItem],
  );

  useEffect(() => {
    maxVisibleRef.current = Math.max(1, maxVisibleItems);
    setItems((prev) => trimToCapacity(prev));
  }, [maxVisibleItems, trimToCapacity]);

  useEffect(() => {
    baseAssetRef.current = baseAsset;
    clearTimers();

    if (!baseAsset || !enabled) {
      setItems([]);
      return clearTimers;
    }

    setItems([]);

    for (let i = 0; i < MIN_X_NEWS_SEED_COUNT; i++) {
      const seedTimeout = setTimeout(() => {
        if (baseAssetRef.current !== baseAsset) return;
        prependItem(baseAsset);
      }, i * SEED_STAGGER_MS);
      seedTimeoutsRef.current.push(seedTimeout);
    }

    const startStreamTimeout = setTimeout(() => {
      if (baseAssetRef.current === baseAsset) {
        scheduleNext(baseAsset);
      }
    }, MIN_X_NEWS_SEED_COUNT * SEED_STAGGER_MS + 500);
    seedTimeoutsRef.current.push(startStreamTimeout);

    return clearTimers;
  }, [baseAsset, enabled, clearTimers, prependItem, scheduleNext]);

  return {
    items,
    enterState,
  };
}
