import { type JSX } from "react";
import type { IntentResolution } from "./intentResolution";

export interface IntentResolutionChipsProps {
  resolution: IntentResolution;
  onEditAgent?: () => void;
  onEditAsset?: () => void;
}

export function IntentResolutionChips({
  resolution,
  onEditAgent,
  onEditAsset,
}: IntentResolutionChipsProps): JSX.Element {
  const { agent, asset, assetDiffersFromChart } = resolution;

  return (
    <div className="intent-resolution-chips" aria-label="Intent interpretation">
      <button
        type="button"
        className={`intent-resolution-chip${agent.confidence === "defaulted" ? " is-defaulted" : ""}`}
        onClick={onEditAgent}
        title="Resolved agent"
      >
        <span className="intent-resolution-chip-key">Agent</span>
        <span className="intent-resolution-chip-value">{agent.label}</span>
        {agent.confidence === "defaulted" ? (
          <span className="intent-resolution-chip-tag">default</span>
        ) : null}
      </button>
      <button
        type="button"
        className={`intent-resolution-chip${asset.confidence === "defaulted" ? " is-defaulted" : ""}`}
        onClick={onEditAsset}
        title="Resolved asset"
      >
        <span className="intent-resolution-chip-key">Asset</span>
        <span className="intent-resolution-chip-value">{asset.label}</span>
        {asset.confidence === "defaulted" ? (
          <span className="intent-resolution-chip-tag">default</span>
        ) : null}
      </button>
      {assetDiffersFromChart ? (
        <span className="intent-resolution-chart-note">
          Intent asset differs from chart
        </span>
      ) : null}
    </div>
  );
}
