import React, { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { formatCurrency } from "../../sdk/utils/display";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "../../terminal.css";
import "./layout.css";

export interface NumberPadProps {
  isOpen: boolean;
  value: number;
  min: number;
  max: number;
  onConfirm: (value: number) => void;
  onCancel: () => void;
}

/**
 * Number Pad Component for entering numeric values
 */
export function NumberPad({
  isOpen,
  value,
  min,
  max,
  onConfirm,
  onCancel,
}: NumberPadProps): JSX.Element | null {
  const [displayValue, setDisplayValue] = useState<string>("");

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, onCancel);

  // Initialize display value when modal opens
  useEffect(() => {
    if (isOpen) {
      setDisplayValue(value.toString());
    }
  }, [isOpen, value]);

  const handleNumberClick = (num: string) => {
    const newValue = displayValue === "0" ? num : displayValue + num;
    const numValue = parseFloat(newValue);

    // Validate against min/max
    if (numValue <= max) {
      setDisplayValue(newValue);
    }
  };

  const handleDecimalClick = () => {
    if (!displayValue.includes(".")) {
      setDisplayValue(displayValue + ".");
    }
  };

  const handleBackspace = () => {
    if (displayValue.length > 1) {
      setDisplayValue(displayValue.slice(0, -1));
    } else {
      setDisplayValue("0");
    }
  };

  const handleClear = () => {
    setDisplayValue("0");
  };

  const handleConfirm = () => {
    const numValue = parseFloat(displayValue) || 0;
    const clampedValue = Math.max(min, Math.min(max, numValue));
    onConfirm(clampedValue);
  };

  if (!mounted) return null;

  const currentValue = parseFloat(displayValue) || 0;
  const isValid = currentValue >= min && currentValue <= max;

  const numberPadContent = (
    <StaggeredOverlayRoot
      passThrough={!isOpen}
      className="modal-overlay modal-overlay--stacked"
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onCancel}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content number-pad-content staggered-overlay-panel--scale"
        aria-label="Enter amount"
      >
        <div className="modal-header">
          <h3 className="terminal-panel-title">Enter Amount</h3>
        </div>
        <div className="modal-body">
          {/* Display at top */}
          <div className="number-pad-display">
            <div className="terminal-price number-pad-display-value">
              {formatCurrency(currentValue)}
            </div>
            <div className="number-pad-display-range">
              <span className="terminal-label">Min</span>
              <span className="terminal-value">{formatCurrency(min)}</span>
              <span className="terminal-label">Max</span>
              <span className="terminal-value">{formatCurrency(max)}</span>
            </div>
            {!isValid && currentValue > 0 && (
              <div className="number-pad-display-error terminal-label">
                Value must be between {formatCurrency(min)} and{" "}
                {formatCurrency(max)}
              </div>
            )}
          </div>

          {/* Number Pad Grid */}
          <div className="number-pad-grid">
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "1")}
            >
              1
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "2")}
            >
              2
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "3")}
            >
              3
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "4")}
            >
              4
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "5")}
            >
              5
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "6")}
            >
              6
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "7")}
            >
              7
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "8")}
            >
              8
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "9")}
            >
              9
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleDecimalClick}
            >
              .
            </button>
            <button
              type="button"
              className="number-pad-button terminal-interactive"
              onClick={handleNumberClick.bind(null, "0")}
            >
              0
            </button>
            <button
              type="button"
              className="number-pad-button number-pad-button-action terminal-interactive"
              onClick={handleBackspace}
            >
              ⌫
            </button>
          </div>

          {/* Action Buttons */}
          <div className="number-pad-actions">
            <button
              type="button"
              className="number-pad-action-button terminal-interactive"
              onClick={handleClear}
            >
              Clear
            </button>
            <button
              type="button"
              className="number-pad-action-button number-pad-action-button-max terminal-interactive"
              onClick={() => {
                setDisplayValue(max.toString());
              }}
            >
              Max
            </button>
          </div>
        </div>
        <div className="modal-footer">
          <button onClick={onCancel} className="btn btn-secondary">
            Cancel
          </button>
          <button
            onClick={handleConfirm}
            className="btn btn-primary"
            disabled={!isValid}
          >
            Confirm
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(numberPadContent, document.body)
    : null;
}
