import React, { useEffect, useMemo, useState } from "react";

import type { FleetAgentRecord } from "../../../offline/mock_data/fleetCatalog";
import type { CopyRelation } from "../../../offline/mock_data/fleetCopyRelations";
import type { PropertyProfile } from "../../../offline/mock_data/types";
import type { Bucket } from "../../sdk";
import { formatCurrency } from "../../sdk/utils/display";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import CopyAgentModalShell, {
  useCopyAgentModalShell,
} from "../agent/CopyAgentModalShell";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import { useOverlayContentLatch } from "../tables/useBucketModalOverlay";
import {
  buildCopyAgentLeaderChips,
  buildCopyAgentRiskPreview,
  deriveCopierBucketPnl,
  formatCopyAgentAutonomySummary,
} from "../agent/copyAgentRiskPreview";
import { COPY_TOUR_TARGETS } from "../../tutorials/copy-tour/constants";
import { useOptionalCopyTour } from "../../tutorials/copy-tour";
import "../smartlayout/layout.css";
import "../agent/agent.css";

const AUTONOMY_BADGE_LABELS: Record<
  CopyRelation["copySettings"]["autonomyPreset"],
  string
> = {
  guarded: "Guarded",
  highAgency: "High-Agency",
  manual: "Manual",
};

function shortWallet(address: string): string {
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

function shortBucketId(bucketId: string): string {
  if (!bucketId) return "—";
  return bucketId.length <= 12 ? bucketId : `${bucketId.slice(0, 8)}…`;
}

function pnlValueClass(
  tone: "positive" | "negative" | "neutral" | undefined,
): string | undefined {
  if (tone === "positive") return "copied-agents-pnl--positive";
  if (tone === "negative") return "copied-agents-pnl--negative";
  return undefined;
}

function StatusRow({
  label,
  children,
  action,
  valueKind = "metric",
}: {
  label: string;
  children: React.ReactNode;
  action?: React.ReactNode;
  valueKind?: "metric" | "text";
}): JSX.Element {
  return (
    <div className="copied-agent-status-row">
      <span className="copied-agent-status-label">{label}</span>
      <span
        className={
          valueKind === "metric"
            ? "copied-agent-status-value"
            : "copied-agent-status-value copied-agent-status-value--text"
        }
      >
        {children}
      </span>
      {action ? (
        <span className="copied-agent-status-row-action">{action}</span>
      ) : null}
    </div>
  );
}

function CollapsibleSection({
  title,
  defaultOpen = false,
  children,
}: {
  title: string;
  defaultOpen?: boolean;
  children: React.ReactNode;
}): JSX.Element {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className="copied-agent-status-collapse">
      <button
        type="button"
        className="copied-agent-status-collapse-toggle"
        onClick={() => setOpen((value) => !value)}
        aria-expanded={open}
      >
        <ExpandCollapseIcon expanded={open} size={14} /> {title}
      </button>
      {open ? (
        <div className="copied-agent-status-collapse-body">{children}</div>
      ) : null}
    </div>
  );
}

export interface CopiedAgentStatusModalProps {
  open: boolean;
  relation: CopyRelation | null;
  profile: PropertyProfile | null;
  fleet: FleetAgentRecord | null;
  bucket?: Bucket | null;
  onClose: () => void;
  onViewAgent?: (catalogAgentId: string) => void;
  onManageBucket?: (bucketId: string) => void;
  onStopCopy?: (relationId: string) => void;
  onAdjustSettings?: (bucketId: string) => void;
}

function CopiedAgentStatusFooter({
  bucketId,
  relationId,
  profileId,
  onClose,
  onViewAgent,
  onManageBucket,
  onStopCopy,
}: {
  bucketId: string;
  relationId: string;
  profileId: string;
  onClose: () => void;
  onViewAgent?: (catalogAgentId: string) => void;
  onManageBucket?: (bucketId: string) => void;
  onStopCopy?: (relationId: string) => void;
}): JSX.Element {
  const { isSheet, overlay } = useCopyAgentModalShell();
  const isClosing = overlay.isClosing;

  const closeButton = (
    <button
      type="button"
      className="agent-secondary-btn"
      onClick={onClose}
      disabled={isClosing}
    >
      Close
    </button>
  );

  const manageButton =
    onManageBucket != null ? (
      <button
        type="button"
        className="agent-secondary-btn"
        onClick={() => onManageBucket(bucketId)}
        disabled={isClosing}
      >
        Manage bucket
      </button>
    ) : null;

  const viewButton =
    onViewAgent != null ? (
      <button
        type="button"
        className="agent-secondary-btn"
        onClick={() => onViewAgent(profileId)}
        disabled={isClosing}
      >
        View agent
      </button>
    ) : null;

  const stopButton =
    onStopCopy != null ? (
      <button
        type="button"
        className="agent-secondary-btn"
        onClick={() => onStopCopy(relationId)}
        disabled={isClosing}
      >
        Stop mirroring
      </button>
    ) : null;

  return (
    <div
      className={`modal-footer agent-copy-modal-footer${
        isSheet ? " copied-agent-status-footer--sheet" : ""
      }`}
    >
      <div className="agent-copy-modal-footer-actions">
        {closeButton}
        {manageButton}
        {stopButton}
        {viewButton}
      </div>
    </div>
  );
}

function CopiedAgentStatusBody({
  relation,
  profile,
  fleet,
  bucket,
  onClose,
  onViewAgent,
  onManageBucket,
  onStopCopy,
  onAdjustSettings,
}: {
  relation: CopyRelation;
  profile: PropertyProfile;
  fleet: FleetAgentRecord;
  bucket?: Bucket | null;
  onClose: () => void;
  onViewAgent?: (catalogAgentId: string) => void;
  onManageBucket?: (bucketId: string) => void;
  onStopCopy?: (relationId: string) => void;
  onAdjustSettings?: (bucketId: string) => void;
}): JSX.Element {
  const settings = relation.copySettings;
  const avatarSrc = resolveAgentAvatarSvgUrl(profile.id);
  const autonomy = formatCopyAgentAutonomySummary(settings.autonomyPreset);
  const copierPnl = deriveCopierBucketPnl(bucket);
  const copyTour = useOptionalCopyTour();

  useEffect(() => {
    if (!copyTour?.runTour || copierPnl.value <= 0) return;
    copyTour.notifyPnlVisible();
  }, [copierPnl.value, copyTour]);
  const leaderChips = buildCopyAgentLeaderChips(profile, fleet);
  const preview = buildCopyAgentRiskPreview(
    {
      destinationMode: settings.bucketMode,
      startingMargin: settings.startingMargin ?? 0,
      existingBucket: bucket,
      copySizePct: settings.copySizePct,
      autonomyPreset: settings.autonomyPreset,
    },
    profile,
  );

  const allocatedCapital =
    settings.bucketMode === "new"
      ? settings.startingMargin ?? preview.capitalAtRisk
      : preview.capitalAtRisk;

  const pnl30d = profile.stats.find((stat) => stat.label === "30d PnL");

  return (
    <>
      <div className="modal-header copied-agent-status-header">
        <div className="copied-agent-status-identity">
          <span className="copied-agents-avatar copied-agents-avatar--modal" aria-hidden>
            {avatarSrc ? (
              <span
                className="copied-agents-avatar-image"
                style={{
                  maskImage: `url(${avatarSrc})`,
                  WebkitMaskImage: `url(${avatarSrc})`,
                }}
              />
            ) : null}
          </span>
          <div className="agent-copy-modal-header-text">
            <h3 className="terminal-panel-title">{profile.name}</h3>
            <span className="copied-agent-status-ticker">{profile.ticker}</span>
          </div>
        </div>
        <div className="copied-agent-status-header-actions">
          <span className="copied-agent-status-badge">Active · mirroring</span>
          <button
            type="button"
            className="agent-copy-modal-close"
            onClick={onClose}
            aria-label="Close"
          >
            ×
          </button>
        </div>
      </div>

      <div className="modal-body copied-agent-status-body">
        <h4 className="agent-copy-summary-rail-title">Your mirror</h4>
        <StatusRow
          label="Mirror size"
          action={
            onAdjustSettings ? (
              <button
                type="button"
                className="agent-secondary-btn copied-agent-status-inline-btn"
                onClick={() => onAdjustSettings(settings.bucketId)}
              >
                Adjust
              </button>
            ) : undefined
          }
        >
          {settings.copySizePct}%
        </StatusRow>
        <StatusRow label="Allocated capital">
          {formatCurrency(allocatedCapital)}
        </StatusRow>
        <StatusRow label="Your 30d PnL (this bucket)">
          <span
            className={pnlValueClass(copierPnl.tone)}
            data-tour={COPY_TOUR_TARGETS.bucketPnl}
          >
            {copierPnl.formatted}
          </span>
        </StatusRow>
        <StatusRow label="Since" valueKind="text">
          {formatRelativeTime(settings.startedAt)}
        </StatusRow>
        <StatusRow label="Autonomy" valueKind="text">
        {AUTONOMY_BADGE_LABELS[settings.autonomyPreset]}
        </StatusRow>

        <CollapsibleSection title="Leader stats">
          <div className="agent-copy-leader-chips" aria-label="Leader stats">
            {leaderChips.map((chip) => (
              <span
                key={chip.label}
                className={`agent-copy-leader-chip${
                  chip.tone === "positive"
                    ? " agent-copy-leader-chip--positive"
                    : chip.tone === "negative"
                      ? " agent-copy-leader-chip--negative"
                      : ""
                }`}
              >
                {chip.label === "30d PnL" ? chip.value : `${chip.label} ${chip.value}`}
              </span>
            ))}
          </div>
          {pnl30d ? (
            <StatusRow label="Leader 30d PnL">
              <span className={pnlValueClass(pnl30d.tone)}>{pnl30d.value}</span>
            </StatusRow>
          ) : null}
        </CollapsibleSection>

        <CollapsibleSection title="Costs">
          <StatusRow label="Performance fee">
            {preview.costs.performanceFeePct}%
          </StatusRow>
          <StatusRow label="Est. spread/slip">
            ~{preview.costs.estSpreadPct}%
          </StatusRow>
          <StatusRow label="Funding" valueKind="text">
            {preview.costs.fundingLabel}
          </StatusRow>
        </CollapsibleSection>

        <CollapsibleSection title="Details">
          <StatusRow label="Bucket">
            {onManageBucket ? (
              <button
                type="button"
                className="copied-agent-status-link-btn"
                onClick={() => onManageBucket(settings.bucketId)}
                title={settings.bucketId}
              >
                {shortBucketId(settings.bucketId)}
              </button>
            ) : (
              <span title={settings.bucketId}>{shortBucketId(settings.bucketId)}</span>
            )}
          </StatusRow>
          <StatusRow label="Bucket mode" valueKind="text">
            {settings.bucketMode === "new"
              ? "New copy bucket"
              : "Existing cross bucket"}
          </StatusRow>
          <StatusRow label="Strategy" valueKind="text">
            {profile.strategySummary}
          </StatusRow>
          <StatusRow label="Agent wallet">
            <code className="terminal-value" title={fleet.agentWallet}>
              {shortWallet(fleet.agentWallet)}
            </code>
          </StatusRow>
        </CollapsibleSection>
      </div>

      <CopiedAgentStatusFooter
        bucketId={settings.bucketId}
        relationId={relation.id}
        profileId={profile.id}
        onClose={onClose}
        onViewAgent={onViewAgent}
        onManageBucket={onManageBucket}
        onStopCopy={onStopCopy}
      />
    </>
  );
}

export default function CopiedAgentStatusModal({
  open,
  relation,
  profile,
  fleet,
  bucket,
  onClose,
  onViewAgent,
  onManageBucket,
  onStopCopy,
  onAdjustSettings,
}: CopiedAgentStatusModalProps): JSX.Element {
  const latchValue = useMemo(() => {
    if (!relation || !profile || !fleet) return null;
    return { relation, profile, fleet };
  }, [relation, profile, fleet]);

  const { latched, clearLatch } = useOverlayContentLatch(open, latchValue);

  return (
    <CopyAgentModalShell
      open={open}
      onClose={onClose}
      onAfterUnmount={clearLatch}
      ariaLabel={
        latched ? `Copy status for ${latched.profile.name}` : "Copy status"
      }
      variant="status"
    >
      {latched ? (
        <CopiedAgentStatusBody
          relation={latched.relation}
          profile={latched.profile}
          fleet={latched.fleet}
          bucket={bucket}
          onClose={onClose}
          onViewAgent={onViewAgent}
          onManageBucket={onManageBucket}
          onStopCopy={onStopCopy}
          onAdjustSettings={onAdjustSettings}
        />
      ) : null}
    </CopyAgentModalShell>
  );
}
