import React, { useMemo } from "react";
import type { TradingAgent } from "../../store/types";
import { shortHashId } from "../../utils/hashId";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import "./agentConsole.css";

export interface AgentCommandCenterRailProps {
  agents: TradingAgent[];
  selectedAgentId: string | null;
  onSelectAgent: (agentId: string) => void;
}

function memoryPreview(agent: TradingAgent): string {
  const last = agent.memory[agent.memory.length - 1];
  return last?.text ?? "No memory yet.";
}

function latestMemoryAt(agent: TradingAgent): string | null {
  const last = agent.memory[agent.memory.length - 1];
  return last?.at ?? agent.updatedAt;
}

function sortAgents(agents: TradingAgent[]): TradingAgent[] {
  return [...agents].sort((a, b) => {
    const aActive = a.status === "active" ? 1 : 0;
    const bActive = b.status === "active" ? 1 : 0;
    if (aActive !== bActive) return bActive - aActive;
    return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
  });
}

function AgentCommandCenterRail({
  agents,
  selectedAgentId,
  onSelectAgent,
}: AgentCommandCenterRailProps): JSX.Element {
  const sortedAgents = useMemo(() => sortAgents(agents), [agents]);

  return (
    <nav className="agent-console-command-rail" aria-label="Agents">
      <div className="agent-console-rail-heading">Agents</div>
      <ul className="agent-console-rail-list">
        {sortedAgents.map((agent) => {
          const isSelected = selectedAgentId === agent.id;
          const preview = memoryPreview(agent);
          const isActive = agent.status === "active";

          return (
            <li key={agent.id}>
              <button
                type="button"
                className={`agent-console-rail-item${isSelected ? " is-selected" : ""}`}
                onClick={() => onSelectAgent(agent.id)}
                aria-current={isSelected ? "true" : undefined}
              >
                <div className="agent-console-rail-item-top">
                  <span
                    className={`agent-console-rail-status-dot${isActive ? " is-active" : ""}`}
                    aria-hidden
                  />
                  <span className="task-id-chip" title={agent.id}>
                    {shortHashId(agent.id)}
                  </span>
                </div>
                <div className="agent-console-rail-item-name">
                  {agent.icon ? (
                    <span className="agent-parent-chip-icon">{agent.icon}</span>
                  ) : null}
                  <span title={agent.displayName}>{agent.displayName}</span>
                </div>
                <div className="agent-console-rail-item-preview" title={preview}>
                  {preview}
                </div>
                <div className="agent-console-rail-item-time terminal-text-muted">
                  {formatRelativeTime(latestMemoryAt(agent))}
                </div>
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

export default React.memo(AgentCommandCenterRail);
