import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { Market } from "../../store/types";
import { useMarkets } from "../../hooks/useMarkets";
import { TickerSelectionToolbar } from "./TickerSelectionToolbar";
import { TickerSelectionTable } from "./TickerSelectionTable";
import { useTickerSelectionRows } from "./useTickerSelectionRows";
import { useTickerSelectionLayout } from "./useTickerSelectionLayout";
import type { TickerCategory, TickerSortField, SortDirection } from "./types";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import "../smartlayout/layout.css";
import "./tickerSelection.css";

const DESKTOP_ANCHOR_GAP_PX = 4;
const DESKTOP_PANEL_BOTTOM_INSET_PX = 24;

type DesktopAnchorStyle = {
  paddingTop: number;
  paddingLeft: number;
  paddingRight: number;
  width: number;
  maxHeight: number;
  transformOrigin: string;
};

export interface TickerSelectionOverlayProps {
  isOpen: boolean;
  focusSearchOnOpen?: boolean;
  onClose: () => void;
  onSelect: (marketId: string) => void;
  markets: Market[];
  selectedMarketId: string;
  baseURL: string;
  favorites?: string[];
  onFavoriteToggle?: (marketId: string) => void;
  tickerBarRef?: React.RefObject<HTMLElement | null>;
  chartSlotRef?: React.RefObject<HTMLElement | null>;
  isMobile?: boolean;
}

export function TickerSelectionOverlay({
  isOpen,
  focusSearchOnOpen = false,
  onClose,
  onSelect,
  markets,
  selectedMarketId,
  baseURL,
  favorites = [],
  onFavoriteToggle,
  tickerBarRef,
  chartSlotRef,
  isMobile: isMobileProp,
}: TickerSelectionOverlayProps): JSX.Element | null {
  const { isMobile: hookIsMobile } = useTickerSelectionLayout();
  const isMobile = isMobileProp ?? hookIsMobile;
  const { tickers } = useMarkets({ baseURL, sessionToken: "", autoFetchMarkets: false });
  const [category, setCategory] = useState<TickerCategory>("all");
  const [search, setSearch] = useState("");
  const [sortField, setSortField] = useState<TickerSortField>(
    () => (typeof window !== "undefined" && window.matchMedia("(max-width: 767px)").matches ? "openInterest" : "volume"),
  );
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");
  const [desktopAnchorStyle, setDesktopAnchorStyle] = useState<DesktopAnchorStyle | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const handleAfterUnmount = useCallback(() => {
    setSearch("");
    setCategory("all");
  }, []);

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: isMobile
      ? OVERLAY_TIMING.mobileSheetMs
      : OVERLAY_TIMING.desktopScaleMs,
    onAfterUnmount: handleAfterUnmount,
  });

  useOverlayEscapeKey(isOpen, onClose);
  useOverlayScrollLock(isOpen && mounted && isMobile);

  const updateDesktopAnchorPosition = useCallback(() => {
    if (isMobile || !tickerBarRef?.current || !chartSlotRef?.current) {
      setDesktopAnchorStyle(null);
      return;
    }

    const tickerRect = tickerBarRef.current.getBoundingClientRect();
    const chartRect = chartSlotRef.current.getBoundingClientRect();
    const top = tickerRect.bottom + DESKTOP_ANCHOR_GAP_PX;
    const originX = chartRect.width / 2;
    const originY = window.innerHeight * 0.4 - top;
    setDesktopAnchorStyle({
      paddingTop: top,
      paddingLeft: chartRect.left,
      paddingRight: Math.max(0, window.innerWidth - chartRect.right),
      width: chartRect.width,
      maxHeight: Math.max(
        200,
        window.innerHeight - top - DESKTOP_PANEL_BOTTOM_INSET_PX,
      ),
      transformOrigin: `${originX}px ${originY}px`,
    });
  }, [tickerBarRef, chartSlotRef, isMobile]);

  const favoritesSet = useMemo(() => new Set(favorites), [favorites]);

  const rows = useTickerSelectionRows({
    markets,
    tickers,
    favorites: favoritesSet,
    category,
    search,
    sortField,
    sortDirection,
    baseURL,
  });

  const handleSort = useCallback(
    (field: TickerSortField) => {
      if (sortField === field) {
        setSortDirection((d) => (d === "asc" ? "desc" : "asc"));
      } else {
        setSortField(field);
        setSortDirection("desc");
      }
    },
    [sortField],
  );

  const handleFavoriteToggle = useCallback(
    (marketId: string) => {
      onFavoriteToggle?.(marketId);
    },
    [onFavoriteToggle],
  );

  useEffect(() => {
    if (!isOpen || !mounted || !focusSearchOnOpen) return;
    const frame = requestAnimationFrame(() => {
      searchInputRef.current?.focus({ preventScroll: true });
    });
    return () => cancelAnimationFrame(frame);
  }, [isOpen, mounted, focusSearchOnOpen]);

  useEffect(() => {
    if (!isOpen) return;
    setSortField(isMobile ? "openInterest" : "volume");
    setSortDirection("desc");
  }, [isOpen, isMobile]);

  useEffect(() => {
    if (!isOpen || isMobile) return;

    const measure = () => updateDesktopAnchorPosition();
    measure();
    const frame = requestAnimationFrame(measure);

    window.addEventListener("resize", measure);
    window.addEventListener("scroll", measure, true);

    const observedElements = [
      tickerBarRef?.current,
      chartSlotRef?.current,
    ].filter((el): el is HTMLElement => el !== null && el !== undefined);

    const resizeObserver =
      observedElements.length > 0 && typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(measure)
        : null;
    if (resizeObserver) {
      for (const el of observedElements) {
        resizeObserver.observe(el);
      }
    }

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", measure);
      window.removeEventListener("scroll", measure, true);
      resizeObserver?.disconnect();
    };
  }, [isOpen, isMobile, updateDesktopAnchorPosition, tickerBarRef, chartSlotRef]);

  useEffect(() => {
    if (!isOpen || !mounted || !isMobile) return;

    const preventBackgroundScroll = (e: TouchEvent) => {
      const target = e.target;
      if (!(target instanceof Element)) return;
      if (target.closest(".ticker-selection-table-body")) return;
      e.preventDefault();
    };

    document.addEventListener("touchmove", preventBackgroundScroll, { passive: false });

    return () => {
      document.removeEventListener("touchmove", preventBackgroundScroll);
    };
  }, [isOpen, mounted, isMobile]);

  if (!mounted) return null;

  const isDesktopAnchored = !isMobile && desktopAnchorStyle !== null;

  const overlayClassName = [
    "ticker-selection-overlay",
    isMobile ? "ticker-selection-overlay--mobile" : "",
    isDesktopAnchored ? "ticker-selection-overlay--anchored" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const panelClassName = [
    "modal-content",
    "ticker-selection-panel",
    isMobile ? "ticker-selection-panel--mobile" : "",
    isDesktopAnchored ? "ticker-selection-panel--anchored" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const overlayStyle =
    isDesktopAnchored && desktopAnchorStyle
      ? {
          paddingTop: desktopAnchorStyle.paddingTop,
          paddingLeft: desktopAnchorStyle.paddingLeft,
          paddingRight: desktopAnchorStyle.paddingRight,
          paddingBottom: DESKTOP_PANEL_BOTTOM_INSET_PX,
        }
      : undefined;

  const panelStyle =
    isDesktopAnchored && desktopAnchorStyle
      ? {
          width: desktopAnchorStyle.width,
          maxHeight: desktopAnchorStyle.maxHeight,
          transformOrigin: desktopAnchorStyle.transformOrigin,
        }
      : undefined;

  const modalContent = (
    <StaggeredOverlayRoot className={overlayClassName} style={overlayStyle}>
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={panelClassName}
        style={panelStyle}
        aria-label={isMobile ? "Markets" : "Select an Asset"}
      >
       
        <TickerSelectionToolbar
          category={category}
          onCategoryChange={setCategory}
          search={search}
          onSearchChange={setSearch}
          isMobile={isMobile}
          searchInputRef={searchInputRef}
        />
        <div className="ticker-selection-body">
          <TickerSelectionTable
            rows={rows}
            category={category}
            selectedMarketId={selectedMarketId}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            onSelect={onSelect}
            onFavoriteToggle={handleFavoriteToggle}
            isMobile={isMobile}
          />
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
