import type { RefObject } from "react";
import type {
  DrawingUtils,
  IChartApiBase,
  ISeriesApi,
  ISeriesPrimitive,
  IPrimitivePaneRenderer,
  IPrimitivePaneView,
  Logical,
  PrimitiveHoveredItem,
  SeriesAttachedParameter,
  Time,
} from "lightweight-charts";
import { LineStyle } from "lightweight-charts";
import type { ChartPendingOrderLine } from "./chartOrderLines";
import { pendingOrderLinePriceRange } from "./chartOrderLines";
import { resolveSideColor } from "./chartMarkers";
import { resolveLinePrice } from "./pendingOrderLineAnchor";
import type { ExecutionMarkerKind } from "./chartMarkers";
import {
  subscribeSeriesPrimitiveInvalidation,
  type SeriesPrimitiveInvalidationHandle,
} from "./seriesPrimitiveInvalidation";

const LABEL_MIN_GAP_PX = 7;
const HIT_BAND_PX = 10;
const LINE_OPACITY = 0.75;

interface LabelLayout {
  lineId: string;
  price: number;
  y: number;
  labelY: number;
  labelText: string;
  color: string;
  kind: ExecutionMarkerKind;
  labelWidth: number;
  labelHeight: number;
}

interface RendererData {
  labels: LabelLayout[];
  visibleFrom: number;
  visibleTo: number;
}

function withOpacity(hexColor: string, opacity: number): string {
  const hex = hexColor.replace("#", "");
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${opacity})`;
}

function lineStyleForKind(kind: ExecutionMarkerKind): LineStyle {
  return kind === "agent" ? LineStyle.LargeDashed : LineStyle.Dashed;
}

/** Main plot pane size — not timeScale().width() (0 when native time axis is hidden). */
function resolveChartPaneSize(
  chart: IChartApiBase<Time> | null,
  series: ISeriesApi<"Candlestick"> | null,
): { width: number; height: number } {
  if (!chart || !series) return { width: 0, height: 0 };
  const pane = chart.paneSize(series.getPane().paneIndex());
  return { width: pane.width, height: pane.height };
}

function decollideLabels(labels: LabelLayout[], paneHeight: number): LabelLayout[] {
  if (labels.length === 0) return labels;
  const sorted = [...labels].sort((a, b) => a.labelY - b.labelY);
  let prevBottom = -Infinity;

  for (const item of sorted) {
    const halfHeight = item.labelHeight / 2;
    let top = item.labelY - halfHeight;
    if (top < prevBottom + LABEL_MIN_GAP_PX) {
      item.labelY = prevBottom + LABEL_MIN_GAP_PX + halfHeight;
      top = item.labelY - halfHeight;
    }
    if (item.labelY + halfHeight > paneHeight - 2) {
      item.labelY = Math.max(halfHeight + 2, paneHeight - halfHeight - 2);
    }
    prevBottom = item.labelY + halfHeight;
  }

  return sorted;
}

class PendingOrderLinesRenderer implements IPrimitivePaneRenderer {
  private _data: RendererData | null = null;
  private _font = "";
  private _chart: IChartApiBase<Time> | null = null;
  private _series: ISeriesApi<"Candlestick"> | null = null;

  setContext(chart: IChartApiBase<Time> | null, series: ISeriesApi<"Candlestick"> | null): void {
    this._chart = chart;
    this._series = series;
  }

  setData(data: RendererData): void {
    this._data = data;
  }

  setFont(font: string): void {
    this._font = font;
  }

  private resolveLineY(item: LabelLayout): number | null {
    const y = this._series?.priceToCoordinate(item.price);
    return y ?? null;
  }

  private resolvePaneWidth(): number {
    return resolveChartPaneSize(this._chart, this._series).width;
  }

  private resolveLabelX(): number {
    const paneWidth = this.resolvePaneWidth();
    return paneWidth > 0 ? paneWidth - 6 : 0;
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    if (!this._data) return null;
    for (let i = this._data.visibleFrom; i < this._data.visibleTo; i++) {
      const item = this._data.labels[i];
      if (!item) continue;

      const lineY = this.resolveLineY(item);
      if (lineY === null) continue;

      if (Math.abs(y - lineY) <= HIT_BAND_PX) {
        return {
          zOrder: "normal",
          externalId: item.lineId,
          itemType: "primitive",
          hitTestPriority: 1,
        };
      }

      const labelX = this.resolveLabelX();
      const halfW = item.labelWidth / 2;
      const halfH = item.labelHeight / 2;
      if (
        x >= labelX - halfW &&
        x <= labelX + halfW &&
        y >= item.labelY - halfH &&
        y <= item.labelY + halfH
      ) {
        return {
          zOrder: "normal",
          externalId: item.lineId,
          itemType: "primitive",
          hitTestPriority: 1,
        };
      }
    }
    return null;
  }

  draw(
    target: import("fancy-canvas").CanvasRenderingTarget2D,
    utils?: DrawingUtils,
  ): void {
    target.useBitmapCoordinateSpace((scope) => {
      if (!this._data) return;
      const { context: ctx, horizontalPixelRatio, verticalPixelRatio, bitmapSize } = scope;
      const paneWidth = bitmapSize.width / horizontalPixelRatio;
      if (paneWidth <= 0) return;

      const paneWidthBitmap = bitmapSize.width;
      const labelX = paneWidth - 6;
      ctx.font = this._font;

      for (let i = this._data.visibleFrom; i < this._data.visibleTo; i++) {
        const item = this._data.labels[i];
        if (!item) continue;

        const lineY = this.resolveLineY(item);
        if (lineY === null) continue;

        const yBitmap = lineY * verticalPixelRatio;
        const color = withOpacity(item.color, LINE_OPACITY);
        const lineWidth = Math.max(1, horizontalPixelRatio);
        const yOffset = lineWidth % 2 === 1 ? 0.5 : 0;
        const strokeY = yBitmap + yOffset;

        ctx.save();
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.globalAlpha = 1;
        ctx.lineWidth = lineWidth;
        if (utils) {
          utils.setLineStyle(ctx, lineStyleForKind(item.kind));
        } else {
          ctx.setLineDash(
            (item.kind === "agent" ? [6, 4] : [3, 3]).map((v) => v * horizontalPixelRatio),
          );
        }
        ctx.beginPath();
        ctx.moveTo(0, strokeY);
        ctx.lineTo(paneWidthBitmap, strokeY);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.restore();

        ctx.fillStyle = color;
        ctx.textBaseline = "middle";
        ctx.textAlign = "right";
        ctx.save();
        ctx.scale(horizontalPixelRatio, verticalPixelRatio);
        ctx.fillText(item.labelText, labelX, item.labelY);
        ctx.restore();
      }
    });
  }
}

class PendingOrderLinesPaneView implements IPrimitivePaneView {
  private _chart: IChartApiBase<Time> | null = null;
  private _series: ISeriesApi<"Candlestick"> | null = null;
  private _lines: ChartPendingOrderLine[] = [];
  private _priceOverrides = new Map<string, number>();
  private _renderer = new PendingOrderLinesRenderer();
  private _data: RendererData = { labels: [], visibleFrom: 0, visibleTo: 0 };
  private _invalidated = true;

  setContext(chart: IChartApiBase<Time>, series: ISeriesApi<"Candlestick">): void {
    this._chart = chart;
    this._series = series;
    this._renderer.setContext(chart, series);
    this._invalidated = true;
  }

  setLines(lines: ChartPendingOrderLine[]): void {
    this._lines = lines;
    this._invalidated = true;
  }

  setPriceOverrides(overrides: ReadonlyMap<string, number>): void {
    this._priceOverrides = new Map(overrides);
    this._invalidated = true;
  }

  lines(): readonly ChartPendingOrderLine[] {
    return this._lines;
  }

  invalidate(): void {
    this._invalidated = true;
  }

  /** Main pane layer — horizontal price lines render here (not the crosshair top canvas). */
  zOrder(): "normal" {
    return "normal";
  }

  renderer(): IPrimitivePaneRenderer | null {
    if (!this._series?.options().visible) return null;
    if (this._invalidated) {
      this._rebuild();
    }
    return this._renderer;
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    if (!this._series?.options().visible) return null;
    if (this._invalidated) {
      this._rebuild();
    }
    return this._renderer.hitTest(x, y);
  }

  private _rebuild(): void {
    const chart = this._chart;
    const series = this._series;
    if (!chart || !series) {
      this._data = { labels: [], visibleFrom: 0, visibleTo: 0 };
      this._renderer.setData(this._data);
      this._invalidated = false;
      return;
    }

    this._renderer.setContext(chart, series);

    const fontSize = chart.options().layout.fontSize;
    const fontFamily = chart.options().layout.fontFamily;
    this._renderer.setFont(`${fontSize}px ${fontFamily}`);

    const { height: paneHeight } = resolveChartPaneSize(chart, series);

    const rawLabels: LabelLayout[] = [];
    for (const line of this._lines) {
      const price = resolveLinePrice(line, this._priceOverrides);
      const y = series.priceToCoordinate(price);
      if (y === null) continue;

      const labelText = `${line.label} · ${formatQty(line.remainingQuantity)}`;
      rawLabels.push({
        lineId: line.lineId,
        price,
        y,
        labelY: y,
        labelText,
        color: resolveSideColor(line.side),
        kind: line.kind,
        labelWidth: 0,
        labelHeight: fontSize,
      });
    }

    const canvas = document.createElement("canvas");
    const measureCtx = canvas.getContext("2d");
    if (measureCtx) {
      measureCtx.font = `${fontSize}px ${fontFamily}`;
      for (const item of rawLabels) {
        item.labelWidth = measureCtx.measureText(item.labelText).width;
      }
    }

    const labels = decollideLabels(rawLabels, paneHeight);
    this._data = {
      labels,
      visibleFrom: 0,
      visibleTo: labels.length,
    };
    this._renderer.setData(this._data);
    this._invalidated = false;
  }
}

function formatQty(value: number): string {
  if (!Number.isFinite(value)) return "0";
  if (value >= 1) return value.toFixed(2);
  if (value >= 0.01) return value.toFixed(4);
  return value.toFixed(6);
}

export class PendingOrderLinesPrimitive implements ISeriesPrimitive<Time> {
  private _paneView = new PendingOrderLinesPaneView();
  private _requestUpdate: (() => void) | null = null;
  private _invalidationHandle: SeriesPrimitiveInvalidationHandle | null = null;

  constructor(private _isPanningRef?: RefObject<boolean>) {}

  attached(param: SeriesAttachedParameter<Time, "Candlestick">): void {
    this._requestUpdate = param.requestUpdate;
    this._paneView.setContext(param.chart, param.series);
    this._invalidationHandle = subscribeSeriesPrimitiveInvalidation(
      param.chart,
      param.series,
      () => this._paneView.invalidate(),
      () => this._requestUpdate?.(),
      this._isPanningRef,
    );
    this._paneView.invalidate();
    this._requestUpdate?.();
  }

  flushPanInvalidation(): void {
    this._invalidationHandle?.flush();
  }

  detached(): void {
    this._invalidationHandle?.unsubscribe();
    this._invalidationHandle = null;
    this._requestUpdate = null;
  }

  setLines(lines: ChartPendingOrderLine[]): void {
    this._paneView.setLines(lines);
    this._requestUpdate?.();
    requestAnimationFrame(() => {
      this._requestUpdate?.();
      requestAnimationFrame(() => this._requestUpdate?.());
    });
  }

  setPriceOverrides(overrides: ReadonlyMap<string, number>): void {
    this._paneView.setPriceOverrides(overrides);
    this._requestUpdate?.();
  }

  paneViews(): readonly IPrimitivePaneView[] {
    return [this._paneView];
  }

  updateAllViews(): void {
    this._paneView.invalidate();
    this._requestUpdate?.();
  }

  hitTest(x: number, y: number): PrimitiveHoveredItem | null {
    return this._paneView.hitTest(x, y);
  }

  autoscaleInfo(_startTimePoint: Logical, _endTimePoint: Logical) {
    const lines = this._paneView.lines();
    if (lines.length === 0) return null;
    const range = pendingOrderLinePriceRange(lines, 0.02);
    if (!range) return null;
    return {
      priceRange: {
        minValue: range.from,
        maxValue: range.to,
      },
    };
  }
}

/** Resolve screen anchor for a pending order line (center-right of chart at price Y). */
export function resolveOrderLineAnchorPoint(
  chart: IChartApiBase<Time>,
  series: ISeriesApi<"Candlestick">,
  lineId: string,
  lines: ChartPendingOrderLine[],
  priceOverrides?: ReadonlyMap<string, number>,
): { x: number; y: number } | null {
  const line = lines.find((entry) => entry.lineId === lineId);
  if (!line) return null;
  const price = resolveLinePrice(line, priceOverrides);
  const y = series.priceToCoordinate(price);
  if (y === null) return null;
  const { width: paneWidth } = resolveChartPaneSize(chart, series);
  if (paneWidth <= 0) return null;
  const x = paneWidth * 0.75;
  return { x, y };
}
