import React, { useState } from "react";
import { FilledRangeSlider } from "../../ui/FilledRangeSlider";
import { ExpandCollapseIcon } from "../../ui/ExpandCollapseIcon";
import { formatCurrency } from "../../../sdk/utils/display";
import { NumberPad } from "../number-pad";
import {
  getChainsForAsset,
  isAllowedAssetChainPair,
} from "../../../constants/crossChain";
import type { CrossChainMode } from "../cross-chain-modal";
import type { WalletTransferAssetId } from "../wallet-transfer-modal";
import type { CrossChainOption } from "../../../constants/crossChain";
import {
  getAddressPlaceholder,
  isKnownWithdrawAddress,
  validateWithdrawAddress,
} from "../../../utils/crossChainAddressValidation";
import "./cross-chain.css";

const ASSET_OPTIONS: { value: WalletTransferAssetId; label: string }[] = [
  { value: "USDC", label: "USDC" },
  { value: "USDT", label: "USDT" },
  { value: "MORM", label: "MORM" },
  { value: "BTC", label: "BTC" },
];

const MIN_AMOUNT = 0.01;
const ESTIMATED_FEE_USD = 0.42;

export interface CrossChainFormPanelProps {
  mode: CrossChainMode;
  walletAddress: string;
  assetId: WalletTransferAssetId;
  amount: number;
  chain: string;
  toAddress: string;
  availableBalance: number;
  chainOptions: CrossChainOption[];
  disabled?: boolean;
  onAssetChange: (value: WalletTransferAssetId) => void;
  onAmountChange: (amount: number) => void;
  onChainChange: (value: string) => void;
  onToAddressChange: (value: string) => void;
  onReview: () => void;
}

export function CrossChainFormPanel({
  mode,
  walletAddress,
  assetId,
  amount,
  chain,
  toAddress,
  availableBalance,
  chainOptions,
  disabled = false,
  onAssetChange,
  onAmountChange,
  onChainChange,
  onToAddressChange,
  onReview,
}: CrossChainFormPanelProps): JSX.Element {
  const [isNumberPadOpen, setIsNumberPadOpen] = useState(false);
  const [showFullAddress, setShowFullAddress] = useState(false);
  const [feeExpanded, setFeeExpanded] = useState(false);

  const isWithdraw = mode === "withdraw";
  const maxAmount = isWithdraw
    ? Math.max(MIN_AMOUNT, availableBalance)
    : Math.max(MIN_AMOUNT, 1_000_000);

  const displayChainOptions = assetId
    ? chainOptions.length > 0
      ? chainOptions
      : getChainsForAsset(assetId)
    : [];

  const addressValidation = isWithdraw
    ? validateWithdrawAddress(chain, toAddress)
    : { valid: true, format: "evm" as const };

  const isAmountValid = isWithdraw
    ? amount >= MIN_AMOUNT && amount <= maxAmount && availableBalance >= MIN_AMOUNT
    : amount >= MIN_AMOUNT;
  const isChainValid = Boolean(assetId) && isAllowedAssetChainPair(assetId, chain);
  const isFormValid =
    addressValidation.valid && isAmountValid && isChainValid && Boolean(assetId);

  const chainLabel = isWithdraw ? "Destination Chain" : "Source Chain";
  const knownAddress =
    isWithdraw && addressValidation.valid
      ? isKnownWithdrawAddress(chain, toAddress)
      : true;

  const handleMax = () => {
    if (!isWithdraw) return;
    const reserved = ESTIMATED_FEE_USD + 0.01;
    onAmountChange(Math.max(MIN_AMOUNT, availableBalance - reserved));
  };

  return (
    <>
      <div
        className="transfer-field-group"
        data-tour="deposit-tour-form-asset"
      >
        <label className="terminal-label transfer-field-label">Asset</label>
        <select
          value={assetId}
          onChange={(e) => onAssetChange(e.target.value as WalletTransferAssetId)}
          className="form-input transfer-select"
          disabled={disabled}
        >
          <option value="">Select asset</option>
          {ASSET_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <div
        className="transfer-field-group"
        data-tour="deposit-tour-form-chain"
      >
        <label className="terminal-label transfer-field-label">{chainLabel}</label>
        <select
          value={chain}
          onChange={(e) => onChainChange(e.target.value)}
          className="form-input transfer-select"
          disabled={disabled || !assetId}
        >
          <option value="">
            {assetId ? "Select chain" : "Select asset first"}
          </option>
          {displayChainOptions.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      {assetId && (
        <div className="transfer-field-group" data-tour="deposit-tour-form-amount">
          <div className="transfer-amount-header">
            <label className="terminal-label transfer-field-label">Amount</label>
            {isWithdraw && (
              <div className="transfer-available-balance">
                <span className="terminal-label">Bal</span>
                <span className="terminal-value">
                  {formatCurrency(availableBalance)}
                </span>
              </div>
            )}
          </div>
          {(!isWithdraw || maxAmount >= MIN_AMOUNT) ? (
            <>
              <div className="transfer-amount-header">
                <div
                  className="transfer-amount-display transfer-amount-display--interactive"
                  onClick={() => setIsNumberPadOpen(true)}
                  style={{ flex: 1 }}
                >
                  <span className="terminal-price transfer-amount-value">
                    {formatCurrency(amount)}
                  </span>
                </div>
                {isWithdraw && (
                  <button
                    type="button"
                    className="btn btn-secondary cross-chain-max-btn"
                    onClick={handleMax}
                    disabled={disabled}
                  >
                    MAX
                  </button>
                )}
              </div>
              <div className="transfer-amount-container">
                <FilledRangeSlider
                  variant="info"
                  min={MIN_AMOUNT}
                  max={maxAmount}
                  step={0.01}
                  value={amount}
                  onChange={onAmountChange}
                  disabled={disabled}
                />
              </div>
            </>
          ) : (
            <div className="transfer-insufficient-funds">
              Insufficient funds. Minimum required: {formatCurrency(MIN_AMOUNT)}
            </div>
          )}
        </div>
      )}

      {isWithdraw ? (
        <div className="transfer-field-group">
          <label className="terminal-label transfer-field-label">
            To (external address)
          </label>
          <input
            type="text"
            value={toAddress}
            onChange={(e) => onToAddressChange(e.target.value)}
            placeholder={getAddressPlaceholder(chain)}
            className="form-input transfer-select transfer-input"
            disabled={disabled}
          />
          {toAddress.trim() && !addressValidation.valid && (
            <div className="transfer-field-hint transfer-field-error">
              {addressValidation.hint}
            </div>
          )}
          {toAddress.trim() && addressValidation.valid && (
            <div className="cross-chain-address-flags">
              {showFullAddress ? toAddress : `${toAddress.slice(0, 8)}…${toAddress.slice(-6)}`}
              {" · "}
              <button
                type="button"
                className="btn btn-link"
                style={{ fontSize: "0.75rem", padding: 0 }}
                onClick={() => setShowFullAddress((v) => !v)}
              >
                {showFullAddress ? "hide full" : "show full"}
              </button>
              {!knownAddress && (
                <div className="cross-chain-address-flags--warn">
                  First-time address — verify chain and destination carefully.
                </div>
              )}
            </div>
          )}
        </div>
      ) : (
        <div className="transfer-field-group">
          <label className="terminal-label transfer-field-label">
            To (Morpheum spot)
          </label>
          <input
            type="text"
            value={walletAddress}
            readOnly
            className="form-input transfer-select transfer-input"
          />
          <div className="transfer-field-hint">self ✓</div>
        </div>
      )}

      <button
        type="button"
        className="cross-chain-fee-preview"
        onClick={() => setFeeExpanded((v) => !v)}
      >
        <span>
          ≈ ${ESTIMATED_FEE_USD.toFixed(2)} network fee · arrives ~1–3 min
        </span>
        <ExpandCollapseIcon expanded={feeExpanded} size={14} />
      </button>
      {feeExpanded && (
        <div className="cross-chain-security-panel-body" style={{ marginBottom: "0.75rem" }}>
          Route: Collateral → Synthetic ({assetId || "—"}) · Validators 6-of-9 ·
          Demo estimate only.
        </div>
      )}

      <button
        type="button"
        className="btn btn-primary"
        style={{ width: "100%", marginTop: "0.5rem" }}
        disabled={disabled || !isFormValid}
        onClick={onReview}
        data-tour="deposit-tour-form-review"
      >
        Review
      </button>

      <NumberPad
        isOpen={isNumberPadOpen}
        value={amount}
        min={MIN_AMOUNT}
        max={maxAmount}
        onConfirm={(value) => {
          onAmountChange(value);
          setIsNumberPadOpen(false);
        }}
        onCancel={() => setIsNumberPadOpen(false)}
      />
    </>
  );
}
