import type { JSX } from "react";
import type { IntentArchetype } from "../intentBreakdown";

const ARCHETYPE_OPTIONS: { id: IntentArchetype; label: string }[] = [
  { id: "directional", label: "Directional" },
  { id: "relational", label: "Relational" },
  { id: "portfolio", label: "Portfolio" },
  { id: "conditional", label: "Cond." },
];

export interface IntentArchetypeOverrideProps {
  active: IntentArchetype;
  onSelect: (archetype: IntentArchetype) => void;
}

export function IntentArchetypeOverride({
  active,
  onSelect,
}: IntentArchetypeOverrideProps): JSX.Element {
  return (
    <div className="intent-archetype-override" role="group" aria-label="Intent type override">
      {ARCHETYPE_OPTIONS.map((opt) => (
        <button
          key={opt.id}
          type="button"
          className={`intent-archetype-chip${active === opt.id ? " is-active" : ""}`}
          onClick={() => onSelect(opt.id)}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}
