import React, { useEffect } from "react";
import { SubscriptionClient } from "../../sdk";
import { shortHashId } from "../../utils/hashId";
import BucketPositions from "./Position";
import { POSITION_VIEW_MODE_BY_BUCKET } from "../../constants";
import "./bucketCollection.css";

export interface BucketPositionsSidePanelProps {
  isOpen: boolean;
  bucketId: string | null;
  baseURL: string;
  subscriptionClient?: SubscriptionClient;
  authToken?: string;
  walletAddress: string;
  mnemonic?: string;
  refreshInterval?: number;
  filterAgentIds?: string[];
  onClose: () => void;
}

function BucketPositionsSidePanel({
  isOpen,
  bucketId,
  baseURL,
  subscriptionClient,
  authToken,
  walletAddress,
  mnemonic,
  refreshInterval,
  filterAgentIds = [],
  onClose,
}: BucketPositionsSidePanelProps): JSX.Element {
  useEffect(() => {
    if (!isOpen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen, onClose]);

  const panelClass = [
    "bucket-positions-side-panel",
    isOpen ? "is-open" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const title = bucketId
    ? `Positions — ${shortHashId(bucketId)}`
    : "Positions";

  return (
    <aside
      className={panelClass}
      aria-hidden={!isOpen}
      data-bucket-extract-id={bucketId ?? undefined}
    >
    
      <div className="bucket-positions-side-panel-body">
        {isOpen && bucketId ? (
          <BucketPositions
            baseURL={baseURL}
            subscriptionClient={subscriptionClient}
            authToken={authToken}
            walletAddress={walletAddress}
            mnemonic={mnemonic}
            height="100%"
            refreshInterval={refreshInterval}
            selectedBucketId={bucketId}
            viewMode={POSITION_VIEW_MODE_BY_BUCKET}
            hide_header
            embedMode
            filterAgentIds={filterAgentIds}
          />
        ) : null}
      </div>
    </aside>
  );
}

export default React.memo(BucketPositionsSidePanel);
