import React from "react";

import { buildCompareMatrixGridColumns } from "../../utils/agentCompareMatrix";
import { resolveAgentAvatarSvgUrl } from "../../utils/agentAvatarSvg";
import type { CompareAgentColumn } from "../../utils/agentCompareMatrix";
import "./agent.css";

export interface AgentCompareMatrixHeaderProps {
  agents: CompareAgentColumn[];
  columnCount: number;
  showAddSlot: boolean;
  onRequestAddAgent: () => void;
  onRemoveAgent: (agentId: string) => void;
}

function AgentCompareMatrixHeaderCell({
  agent,
  onOpenSelector,
  onRemoveAgent,
}: {
  agent: CompareAgentColumn;
  onOpenSelector: () => void;
  onRemoveAgent: (agentId: string) => void;
}): JSX.Element {
  const avatarSrc = resolveAgentAvatarSvgUrl(agent.id);
  const { profile } = agent;

  const handleRemove = (event: React.MouseEvent<HTMLButtonElement>): void => {
    event.preventDefault();
    event.stopPropagation();
    onRemoveAgent(agent.id);
  };

  return (
    <div className="agent-compare-hero agent-compare-matrix-header-cell agent-compare-matrix-header-cell--filled">
      <button
        type="button"
        className="agent-compare-matrix-header-cell--selectable"
        aria-label={`Change ${profile.name} in compare`}
        onClick={onOpenSelector}
      >
        <span
          className="terminal-label agent-compare-hero-strategy"
          title={profile.strategy}
        >
          {profile.strategy}
        </span>
        <div className="agent-compare-hero-title-row">
          <span className="agent-hero-avatar agent-compare-hero-avatar" aria-hidden>
            <span
              className="agent-hero-avatar-image"
              style={{
                maskImage: `url(${avatarSrc})`,
                WebkitMaskImage: `url(${avatarSrc})`,
              }}
            />
          </span>
          <span
            className="terminal-market-title agent-compare-hero-name"
            title={profile.name}
          >
            {profile.name}
          </span>
          <span className="agent-ticker">{profile.ticker}</span>
        </div>
      </button>
      <button
        type="button"
        className="agent-compare-matrix-header-remove"
        aria-label={`Remove ${profile.name} from compare`}
        onClick={handleRemove}
      >
        ×
      </button>
    </div>
  );
}

function AgentCompareMatrixPlaceholderCell({
  onRequestAddAgent,
}: {
  onRequestAddAgent: () => void;
}): JSX.Element {
  return (
    <button
      type="button"
      className="agent-compare-matrix-header-cell agent-compare-matrix-placeholder-cell"
      aria-label="Add agent to compare"
      onClick={onRequestAddAgent}
    >
      <div className="agent-compare-placeholder-inner">
        <p className="agent-compare-placeholder-title">Add an agent</p>
        <p className="agent-compare-placeholder-body">Click to choose from catalog</p>
      </div>
    </button>
  );
}

function AgentCompareMatrixAddCell({
  onRequestAddAgent,
}: {
  onRequestAddAgent: () => void;
}): JSX.Element {
  return (
    <button
      type="button"
      className="agent-compare-matrix-add-cell"
      aria-label="Add agent to compare"
      onClick={onRequestAddAgent}
    >
      <span className="agent-compare-matrix-add-icon" aria-hidden>
        +
      </span>
      <span className="agent-compare-matrix-add-label">Add</span>
    </button>
  );
}

const AgentCompareMatrixHeader = React.forwardRef<
  HTMLDivElement,
  AgentCompareMatrixHeaderProps
>(function AgentCompareMatrixHeader(
  { agents, columnCount, showAddSlot, onRequestAddAgent, onRemoveAgent },
  ref,
): JSX.Element {
  return (
    <div
      ref={ref}
      className="agent-compare-matrix-header"
      style={{
        gridTemplateColumns: buildCompareMatrixGridColumns(columnCount, showAddSlot),
      }}
    >
      <div className="agent-compare-matrix-header-gutter" aria-hidden />
      {showAddSlot ? (
        <AgentCompareMatrixAddCell onRequestAddAgent={onRequestAddAgent} />
      ) : null}
      {Array.from({ length: columnCount }, (_, index) => {
        const agent = agents[index];
        if (!agent) {
          return (
            <AgentCompareMatrixPlaceholderCell
              key={`placeholder-${index}`}
              onRequestAddAgent={onRequestAddAgent}
            />
          );
        }
        return (
          <AgentCompareMatrixHeaderCell
            key={agent.id}
            agent={agent}
            onOpenSelector={onRequestAddAgent}
            onRemoveAgent={onRemoveAgent}
          />
        );
      })}
    </div>
  );
});

export default AgentCompareMatrixHeader;
