import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  Joyride,
  type CallBackProps,
  type Step,
  type TooltipRenderProps,
  EVENTS,
  STATUS,
} from "react-joyride";
import { toast } from "sonner";
import { isDesktopTourBreakpoint } from "../welcome-tour/constants";
import { welcomeTourLocale, welcomeTourStyles } from "../welcome-tour/welcomeTourStyles";
import { useDepositTour } from "./DepositTourContext";
import {
  buildDepositTourSteps,
  type DepositTourStepMeta,
} from "./depositTourSteps";
import { prepareDepositTourTarget } from "./depositTourDom";
import { DEPOSIT_FLOW_SYNC_RULES, isDepositTourNextGated } from "./depositTourFlowSync";
import { depositTourDefaultOptions } from "./depositTourStyles";
import "../welcome-tour/WelcomeModal.css";

interface DepositTourTooltipActions {
  advanceFromTooltip: (index: number, isLastStep: boolean) => void;
  isNextDisabled: (meta: DepositTourStepMeta | undefined) => boolean;
}

const DepositTourTooltipActionsContext =
  createContext<DepositTourTooltipActions | null>(null);

function DepositTourTooltip({
  continuous,
  index,
  isLastStep,
  skipProps,
  step,
  tooltipProps,
  size,
}: TooltipRenderProps): JSX.Element {
  const actions = useContext(DepositTourTooltipActionsContext);
  const meta = step.data as DepositTourStepMeta | undefined;
  const stepNumber = meta?.stepNumber ?? index + 1;
  const requiresClick = meta?.requiresClick ?? false;
  const nextDisabled = actions?.isNextDisabled(meta) ?? false;

  return (
    <div {...tooltipProps} className="welcome-tour-tooltip">
      <div className="welcome-tour-tooltip-header">
        <span className="welcome-tour-step-badge">
          {stepNumber} / {size}
        </span>
        {step.title ? (
          <h4 className="welcome-tour-tooltip-title">{step.title}</h4>
        ) : null}
      </div>
      <div className="welcome-tour-tooltip-body">{step.content}</div>
      <div className="welcome-tour-tooltip-footer">
        <button type="button" className="welcome-tour-skip" {...skipProps}>
          {skipProps.title}
        </button>
        {!requiresClick && continuous ? (
          <div className="welcome-tour-tooltip-nav">
            {nextDisabled ? (
              <p
                className="welcome-tour-wait-hint"
                style={{
                  margin: 0,
                  fontSize: "0.75rem",
                  color: "var(--terminal-text-muted)",
                }}
              >
                Wait for delivery to complete
              </p>
            ) : null}
            <button
              type="button"
              className="welcome-tour-next"
              disabled={nextDisabled}
              aria-disabled={nextDisabled}
              onClick={() => actions?.advanceFromTooltip(index, isLastStep)}
            >
              {isLastStep ? "Finish" : "Next"}
            </button>
          </div>
        ) : requiresClick ? (
          <p
            className="welcome-tour-click-hint"
            style={{
              margin: 0,
              fontSize: "0.75rem",
              color: "var(--terminal-text-muted)",
            }}
          >
            Click the highlighted control to continue
          </p>
        ) : null}
      </div>
    </div>
  );
}

function findStepIndexById(steps: Step[], stepId: string): number {
  return steps.findIndex(
    (s) => (s.data as DepositTourStepMeta | undefined)?.stepId === stepId,
  );
}

function getStepId(steps: Step[], index: number): string | undefined {
  return (steps[index]?.data as DepositTourStepMeta | undefined)?.stepId;
}

export function DepositTourJoyride(): JSX.Element {
  const {
    runTour,
    entryPath,
    stepIndex,
    setStepIndex,
    currentBreakpoint,
    flowState,
    stopTour,
    onTourComplete,
  } = useDepositTour();

  const isDesktop = isDesktopTourBreakpoint(currentBreakpoint);
  const shouldRun = runTour && isDesktop && entryPath !== null;
  const [tourSession, setTourSession] = useState(0);
  const prevRunRef = useRef(false);
  const stepIndexRef = useRef(stepIndex);
  const setStepIndexRef = useRef(setStepIndex);
  const onTourCompleteRef = useRef(onTourComplete);
  stepIndexRef.current = stepIndex;
  setStepIndexRef.current = setStepIndex;
  onTourCompleteRef.current = onTourComplete;

  const steps = useMemo(
    () => (entryPath ? buildDepositTourSteps(entryPath) : []),
    [entryPath],
  );

  const stepCount = steps.length;

  const scheduleStepIndex = useCallback((index: number) => {
    window.setTimeout(() => {
      setStepIndexRef.current(index);
      stepIndexRef.current = index;
    }, 120);
  }, []);

  const advanceFromTooltip = useCallback(
    (index: number, isLastStep: boolean) => {
      const meta = steps[index]?.data as DepositTourStepMeta | undefined;
      if (isDepositTourNextGated(meta?.gateNextUntilFlowStep, flowState?.flowStep)) {
        return;
      }
      if (isLastStep) {
        onTourCompleteRef.current();
        return;
      }
      scheduleStepIndex(index + 1);
    },
    [flowState?.flowStep, scheduleStepIndex, steps],
  );

  const isNextDisabled = useCallback(
    (meta: DepositTourStepMeta | undefined) =>
      isDepositTourNextGated(meta?.gateNextUntilFlowStep, flowState?.flowStep),
    [flowState?.flowStep],
  );

  const tooltipActions = useMemo(
    (): DepositTourTooltipActions => ({ advanceFromTooltip, isNextDisabled }),
    [advanceFromTooltip, isNextDisabled],
  );

  useEffect(() => {
    if (shouldRun && !prevRunRef.current) {
      setTourSession((s) => s + 1);
    }
    prevRunRef.current = shouldRun;
  }, [shouldRun]);

  useEffect(() => {
    if (shouldRun) {
      document.body.setAttribute("data-deposit-tour-active", "true");
    } else {
      document.body.removeAttribute("data-deposit-tour-active");
    }
    return () => {
      document.body.removeAttribute("data-deposit-tour-active");
    };
  }, [shouldRun]);

  useEffect(() => {
    if (runTour && !isDesktop) {
      stopTour();
      toast.info(
        "Deposit tour is available on desktop and tablet view. Widen your window to explore step-by-step.",
      );
    }
  }, [runTour, isDesktop, stopTour]);

  const stepsWithBefore = useMemo((): Step[] => {
    return steps.map((step) => {
      const meta = step.data as DepositTourStepMeta | undefined;
      const targetSelector = meta?.targetSelector;
      if (!targetSelector) return step;

      return {
        ...step,
        before: async () => {
          const ready = await prepareDepositTourTarget(targetSelector, 4000);
          if (!ready) {
            toast.error("Tour spotlight could not find this step", {
              description:
                "Keep the Morpheum Bridge modal open, or use Skip tour to exit.",
            });
          }
        },
      };
    });
  }, [steps]);

  useEffect(() => {
    if (!shouldRun || steps.length === 0) return;
    const meta = steps[stepIndex]?.data as DepositTourStepMeta | undefined;
    if (!meta?.requiresClick || !meta.targetSelector) return;

    const el = document.querySelector(meta.targetSelector);
    if (!el) return;

    const capturedIndex = stepIndex;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const onClick = () => {
      timer = window.setTimeout(() => {
        if (stepIndexRef.current !== capturedIndex) return;
        if (capturedIndex >= stepCount - 1) return;
        scheduleStepIndex(capturedIndex + 1);
      }, 120);
    };

    el.addEventListener("click", onClick, true);
    return () => {
      el.removeEventListener("click", onClick, true);
      if (timer !== undefined) {
        window.clearTimeout(timer);
      }
    };
  }, [shouldRun, stepIndex, steps, stepCount, scheduleStepIndex]);

  useEffect(() => {
    if (!shouldRun || !flowState) return;

    if (flowState.mode !== "deposit") {
      stopTour();
      toast.info("Deposit tour ended — switch back to Deposit to continue the guided flow.");
      return;
    }

    if (flowState.flowStep === "failure") {
      stopTour();
      toast.error("Deposit tour stopped", {
        description:
          "The bridge flow failed. Retry from the wallet menu when ready.",
      });
      return;
    }

    const rule = DEPOSIT_FLOW_SYNC_RULES[flowState.flowStep];
    if (!rule) return;

    const currentStepId = getStepId(steps, stepIndexRef.current);
    if (!currentStepId || !rule.allowedFrom.includes(currentStepId)) {
      return;
    }

    const targetIdx = findStepIndexById(steps, rule.targetStepId);
    if (targetIdx < 0 || stepIndexRef.current === targetIdx) return;

    scheduleStepIndex(targetIdx);
  }, [
    shouldRun,
    flowState?.flowStep,
    flowState?.mode,
    flowState?.isCrossChainModalOpen,
    steps,
    scheduleStepIndex,
    stopTour,
  ]);

  const handleCallback = useCallback(
    (data: CallBackProps) => {
      const { status, type, index } = data;

      if (status === STATUS.SKIPPED) {
        stopTour();
        onTourComplete();
        return;
      }

      if (type === EVENTS.TARGET_NOT_FOUND) {
        toast.error("Tour step target not found", {
          description:
            "Ensure the bridge modal is open on the Deposit tab, or skip the tour.",
        });
        if (index > 0) {
          scheduleStepIndex(index - 1);
        } else {
          stopTour();
        }
        return;
      }

      if (type === EVENTS.TOUR_END && status === STATUS.FINISHED) {
        onTourComplete();
      }
    },
    [stopTour, onTourComplete, scheduleStepIndex],
  );

  return (
    <DepositTourTooltipActionsContext.Provider value={tooltipActions}>
      <Joyride
        key={tourSession}
        steps={stepsWithBefore}
        run={shouldRun}
        stepIndex={stepIndex}
        continuous
        scrollToFirstStep={false}
        disableScrolling
        disableOverlayClose
        callback={handleCallback}
        locale={welcomeTourLocale}
        options={depositTourDefaultOptions}
        styles={welcomeTourStyles}
        loaderComponent={null}
        tooltipComponent={(props) => (
          <DepositTourTooltip {...props} size={stepCount} />
        )}
      />
    </DepositTourTooltipActionsContext.Provider>
  );
}
