import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type JSX,
} from "react";
import { createPortal } from "react-dom";
import { ExpandCollapseIcon } from "../ui/ExpandCollapseIcon";
import type { PendingOrderLineFilters } from "./chartOrderLines";

const HOVER_CLOSE_DELAY_MS = 150;
const MENU_GAP_PX = 6;

type FilterKey = keyof PendingOrderLineFilters;

const FILTER_ROWS: Array<{ key: FilterKey; label: string; swatchClass: string }> = [
  { key: "agent", label: "Agent", swatchClass: "kline-chart-marker-legend-swatch--agent" },
  { key: "manual", label: "Manual", swatchClass: "kline-chart-marker-legend-swatch--manual" },
  { key: "scale", label: "Scale", swatchClass: "kline-chart-marker-legend-swatch--scale" },
  { key: "limit", label: "Limit", swatchClass: "kline-chart-marker-legend-swatch--limit" },
  { key: "stopLimit", label: "Stop-limit", swatchClass: "kline-chart-marker-legend-swatch--stop-limit" },
];

export interface PendingLegendFilterMenuProps {
  filters: PendingOrderLineFilters;
  masterOn: boolean;
  onFilterChange: (key: FilterKey, value: boolean) => void;
  onMasterToggle: () => void;
}

function useCoarsePointer(): boolean {
  const [coarse, setCoarse] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const query = window.matchMedia("(pointer: coarse)");
    const update = () => setCoarse(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return coarse;
}

function PendingLegendFilterMenu({
  filters,
  masterOn,
  onFilterChange,
  onMasterToggle,
}: PendingLegendFilterMenuProps): JSX.Element {
  const containerRef = useRef<HTMLSpanElement>(null);
  const closeTimerRef = useRef<number | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState<{ top: number; left: number } | null>(
    null,
  );
  const isCoarsePointer = useCoarsePointer();

  const clearCloseTimer = useCallback(() => {
    if (closeTimerRef.current != null) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, []);

  const closeMenu = useCallback(() => {
    clearCloseTimer();
    setMenuOpen(false);
  }, [clearCloseTimer]);

  const openMenu = useCallback(() => {
    clearCloseTimer();
    setMenuOpen(true);
  }, [clearCloseTimer]);

  const scheduleClose = useCallback(() => {
    clearCloseTimer();
    closeTimerRef.current = window.setTimeout(() => {
      setMenuOpen(false);
      closeTimerRef.current = null;
    }, HOVER_CLOSE_DELAY_MS);
  }, [clearCloseTimer]);

  const updateMenuPosition = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    setMenuPosition({
      top: rect.bottom + MENU_GAP_PX,
      left: rect.left,
    });
  }, []);

  useLayoutEffect(() => {
    if (!menuOpen) {
      setMenuPosition(null);
      return;
    }
    updateMenuPosition();
    const onReposition = () => updateMenuPosition();
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);
    return () => {
      window.removeEventListener("resize", onReposition);
      window.removeEventListener("scroll", onReposition, true);
    };
  }, [menuOpen, updateMenuPosition]);

  useEffect(() => {
    if (!menuOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeMenu();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [menuOpen, closeMenu]);

  useEffect(() => () => clearCloseTimer(), [clearCloseTimer]);

  const handleContainerMouseEnter = () => {
    if (isCoarsePointer) return;
    openMenu();
  };

  const handleContainerMouseLeave = () => {
    if (isCoarsePointer) return;
    scheduleClose();
  };

  const handleMenuMouseEnter = () => {
    if (isCoarsePointer) return;
    clearCloseTimer();
  };

  const handleMenuMouseLeave = () => {
    if (isCoarsePointer) return;
    scheduleClose();
  };

  const handleMenuTriggerClick = (event: React.MouseEvent) => {
    event.stopPropagation();
    if (menuOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  };

  const menuPanel =
    menuOpen && menuPosition ? (
      <>
        {isCoarsePointer ? (
          <div
            className="pending-legend-filter-overlay"
            onClick={closeMenu}
            role="presentation"
          />
        ) : null}
        <div
          className="pending-legend-filter-menu"
          style={{
            top: menuPosition.top,
            left: menuPosition.left,
          }}
          role="menu"
          aria-label="Filter pending order lines"
          onMouseEnter={handleMenuMouseEnter}
          onMouseLeave={handleMenuMouseLeave}
          onClick={(event) => event.stopPropagation()}
        >
          {FILTER_ROWS.map(({ key, label, swatchClass }) => (
            <label key={key} className="pending-legend-filter-menu-item" role="none">
              <input
                type="checkbox"
                className="pending-legend-filter-menu-checkbox"
                checked={filters[key]}
                onChange={(event) => onFilterChange(key, event.target.checked)}
              />
              <span
                className={`kline-chart-marker-legend-swatch ${swatchClass}`}
                aria-hidden
              />
              <span className="pending-legend-filter-menu-label">{label}</span>
            </label>
          ))}
        </div>
      </>
    ) : null;

  return (
    <span
      ref={containerRef}
      className="pending-legend-filter"
      onMouseEnter={handleContainerMouseEnter}
      onMouseLeave={handleContainerMouseLeave}
    >
      <button
        type="button"
        className={`kline-chart-marker-legend-item kline-chart-marker-legend-toggle${
          masterOn
            ? " kline-chart-marker-legend-item--active"
            : " kline-chart-marker-legend-item--inactive"
        }`}
        aria-pressed={masterOn}
        aria-haspopup="menu"
        aria-expanded={menuOpen}
        onClick={onMasterToggle}
      >
        <span
          className="kline-chart-marker-legend-swatch kline-chart-marker-legend-swatch--pending"
          aria-hidden
        />
        open order
      </button>
      {isCoarsePointer ? (
        <button
          type="button"
          className="pending-legend-filter-menu-trigger"
          aria-label="Filter pending order lines"
          aria-haspopup="menu"
          aria-expanded={menuOpen}
          onClick={handleMenuTriggerClick}
        >
          <ExpandCollapseIcon expanded={menuOpen} size={14} />
        </button>
      ) : null}
      {typeof document !== "undefined" && menuPanel
        ? createPortal(menuPanel, document.body)
        : null}
    </span>
  );
}

export default PendingLegendFilterMenu;
