/** Nearest bubble edge → marker (px). */
export const MARKER_BUBBLE_BODY_GAP_PX = 20;

/** Arrow tip → marker (px). */
export const MARKER_BUBBLE_TIP_GAP_PX = 10;

/** Triangle base height (px); matches `--marker-bubble-arrow-height` in finchart.css. */
export const MARKER_BUBBLE_ARROW_HEIGHT_PX = 14;

/** @deprecated Use MARKER_BUBBLE_ARROW_HEIGHT_PX */
export const MARKER_BUBBLE_ARROW_SIZE_PX = MARKER_BUBBLE_ARROW_HEIGHT_PX;

/** How far the tail protrudes past the bubble edge toward the marker. */
export const MARKER_BUBBLE_ARROW_PROTRUSION_PX =
  MARKER_BUBBLE_BODY_GAP_PX - MARKER_BUBBLE_TIP_GAP_PX;

/** @deprecated Use MARKER_BUBBLE_BODY_GAP_PX */
export const MARKER_BUBBLE_HORIZONTAL_GAP = MARKER_BUBBLE_BODY_GAP_PX;

/** Marker x within this distance from viewport left → bubble on the right. */
export const MARKER_BUBBLE_LEFT_THRESHOLD_PX = 200;

const CONTAINER_MARGIN = 8;

export type MarkerBubbleSide = "left" | "right";

export interface MarkerBubbleLayoutInput {
  markerX: number;
  markerY: number;
  bubbleWidth: number;
  bubbleHeight: number;
  containerWidth: number;
  containerHeight: number;
}

export interface MarkerBubbleLayoutResult {
  left: number;
  top: number;
  side: MarkerBubbleSide;
  /** Vertical offset from bubble center so the tail points at markerY when top is clamped. */
  arrowOffsetY: number;
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(value, max));
}

export function computeMarkerBubblePosition(
  input: MarkerBubbleLayoutInput,
): MarkerBubbleLayoutResult {
  const {
    markerX,
    markerY,
    bubbleWidth,
    bubbleHeight,
    containerWidth,
    containerHeight,
  } = input;

  const side: MarkerBubbleSide =
    markerX <= MARKER_BUBBLE_LEFT_THRESHOLD_PX ? "right" : "left";

  let left =
    side === "right"
      ? markerX + MARKER_BUBBLE_BODY_GAP_PX
      : markerX - bubbleWidth - MARKER_BUBBLE_BODY_GAP_PX;

  const maxLeft = Math.max(CONTAINER_MARGIN, containerWidth - bubbleWidth - CONTAINER_MARGIN);
  const maxTop = Math.max(CONTAINER_MARGIN, containerHeight - bubbleHeight - CONTAINER_MARGIN);

  left = clamp(left, CONTAINER_MARGIN, maxLeft);
  const top = clamp(markerY - bubbleHeight / 2, CONTAINER_MARGIN, maxTop);

  const bubbleCenterY = top + bubbleHeight / 2;
  const maxArrowOffset = Math.max(
    0,
    bubbleHeight / 2 - MARKER_BUBBLE_ARROW_HEIGHT_PX / 2 - 4,
  );
  const arrowOffsetY = clamp(markerY - bubbleCenterY, -maxArrowOffset, maxArrowOffset);

  return { left, top, side, arrowOffsetY };
}
