import React, { type JSX, useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import {
  bucketAmount,
  DEFAULT_JELLY_DEMO_CONFIG,
  REFERENCE_DEPOSIT,
  type JellyDemoConfig,
} from "../../../offline/mock_data/jellyevent";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "./JellyIntroModal.css";
import "../smartlayout/layout.css";

const REKT_URL = "https://rekt.news/hyperliquidate2";
const SLIDE_COUNT = 3;
const MIN_BUCKET_PCT = 5;
const DEPOSIT_MIN = 500_000;
const DEPOSIT_MAX = 2_000_000;
const DEPOSIT_STEP = 50_000;

export interface JellyIntroModalProps {
  isOpen: boolean;
  onStartReplay: (config: JellyDemoConfig) => void;
  onDismissAndStart: () => void;
}

function clampOperatorBuckets(
  safe: number,
  meme: number,
  hedge: number,
): Pick<JellyDemoConfig, "safePct" | "memePct" | "hedgePct" | "insurancePct"> {
  let s = Math.min(70, Math.max(MIN_BUCKET_PCT, safe));
  let m = Math.min(50, Math.max(MIN_BUCKET_PCT, meme));
  let h = Math.min(40, Math.max(MIN_BUCKET_PCT, hedge));
  let ins = 100 - s - m - h;

  while (ins < MIN_BUCKET_PCT && h > MIN_BUCKET_PCT) {
    h -= 1;
    ins = 100 - s - m - h;
  }
  while (ins < MIN_BUCKET_PCT && m > MIN_BUCKET_PCT) {
    m -= 1;
    ins = 100 - s - m - h;
  }
  while (ins < MIN_BUCKET_PCT && s > MIN_BUCKET_PCT) {
    s -= 1;
    ins = 100 - s - m - h;
  }

  return {
    safePct: s,
    memePct: m,
    hedgePct: h,
    insurancePct: Math.max(MIN_BUCKET_PCT, ins),
  };
}

function formatUsd(value: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(value);
}

export function JellyIntroModal({
  isOpen,
  onStartReplay,
  onDismissAndStart,
}: JellyIntroModalProps): JSX.Element | null {
  const [slideIndex, setSlideIndex] = useState(0);
  const [depositUsd, setDepositUsd] = useState(DEFAULT_JELLY_DEMO_CONFIG.depositUsd);
  const [safePct, setSafePct] = useState(DEFAULT_JELLY_DEMO_CONFIG.safePct);
  const [memePct, setMemePct] = useState(DEFAULT_JELLY_DEMO_CONFIG.memePct);
  const [hedgePct, setHedgePct] = useState(DEFAULT_JELLY_DEMO_CONFIG.hedgePct);

  const insurancePct = 100 - safePct - memePct - hedgePct;

  const draftConfig = useMemo<JellyDemoConfig>(
    () => ({
      depositUsd,
      safePct,
      memePct,
      hedgePct,
      insurancePct,
    }),
    [depositUsd, safePct, memePct, hedgePct, insurancePct],
  );

  useEffect(() => {
    if (isOpen) {
      setSlideIndex(0);
      setDepositUsd(DEFAULT_JELLY_DEMO_CONFIG.depositUsd);
      setSafePct(DEFAULT_JELLY_DEMO_CONFIG.safePct);
      setMemePct(DEFAULT_JELLY_DEMO_CONFIG.memePct);
      setHedgePct(DEFAULT_JELLY_DEMO_CONFIG.hedgePct);
    }
  }, [isOpen]);

  const handleDismiss = useCallback(() => {
    onDismissAndStart();
  }, [onDismissAndStart]);

  useEffect(() => {
    if (!isOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") handleDismiss();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [isOpen, handleDismiss]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);

  useOverlayEscapeKey(isOpen, handleDismiss);

  const applyBucketChange = (nextSafe: number, nextMeme: number, nextHedge: number) => {
    const next = clampOperatorBuckets(nextSafe, nextMeme, nextHedge);
    setSafePct(next.safePct);
    setMemePct(next.memePct);
    setHedgePct(next.hedgePct);
  };

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot
      passThrough={!isOpen}
      className="jelly-intro-overlay"
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={handleDismiss}
        style={backdropStyle}
        className="staggered-overlay-backdrop--onboard"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="jelly-intro-panel staggered-overlay-panel--scale"
        aria-labelledby="jelly-intro-title"
        aria-label="Jelly incident intro"
      >
        <button
          type="button"
          className="jelly-intro-close"
          onClick={handleDismiss}
          aria-label="Dismiss and start replay"
        >
          ×
        </button>

        <div className="jelly-intro-steps" aria-hidden>
          {Array.from({ length: SLIDE_COUNT }, (_, i) => (
            <span
              key={i}
              className={`jelly-intro-step${i === slideIndex ? " jelly-intro-step--active" : ""}`}
            />
          ))}
        </div>

        {slideIndex === 0 && (
          <div className="jelly-intro-slide">
            <span className="jelly-intro-chip">Mar 25, 2025 · Hyperliquid · $JELLY</span>
            <h2 id="jelly-intro-title" className="jelly-intro-title">
              Hyperliquidate II — The $JELLY Incident
            </h2>
            <ul className="jelly-intro-list">
              <li>
                A trader <strong>weaponized Hyperliquid&apos;s liquidation engine</strong> using
                JellyJelly (<code>$JELLY</code>), a thin ~$20M market-cap token.
              </li>
              <li>
                Attack pattern: open a <strong>~$6M perp short</strong> while accumulating{" "}
                <strong>spot longs</strong>, then pump spot prices — forcing liquidation of the
                short into <strong>HLP</strong> (Hyperliquid Liquidity Pool).
              </li>
              <li>
                <code>$JELLY</code> surged <strong>~429% in one hour</strong>; HLP inherited the
                toxic short and faced <strong>~$12M in paper losses</strong>.
              </li>
              <li>
                Hyperliquid&apos;s response: <strong>emergency validator quorum in ~2 minutes</strong>{" "}
                to delist <code>$JELLY</code> perps — settlement at <strong>$0.0095</strong> vs
                market near <strong>~$0.50</strong> (~98% haircut).
              </li>
              <li>
                Systemic gaps: no position limits on illiquid assets, weak oracle protection,
                automated toxic position inheritance, no circuit breakers.
              </li>
              <li>
                Rival CEXs listed <code>$JELLY</code> perps at the peak; concentrated validator
                stake raised decentralization questions.
              </li>
            </ul>
            <a
              className="jelly-intro-link"
              href={REKT_URL}
              target="_blank"
              rel="noopener noreferrer"
            >
              Read the full story on Rekt →
            </a>
          </div>
        )}

        {slideIndex === 1 && (
          <div className="jelly-intro-slide">
            <h2 className="jelly-intro-title">Operator vault replay</h2>
            <p className="jelly-intro-body">
              Step in as <strong>Morpheum Operator / Risk Vault Manager</strong>. This replay uses
              archived Hyperliquid market data (anchor <strong>21:00 UTC</strong>) while a
              scripted timeline moves capital across four isolated buckets.
            </p>
            <div className="jelly-intro-stats">
              <div className="jelly-intro-stat">
                <span className="jelly-intro-stat-label">T+12</span>
                <span className="jelly-intro-stat-value">SAFE → MEME health transfer</span>
              </div>
              <div className="jelly-intro-stat">
                <span className="jelly-intro-stat-label">T+28</span>
                <span className="jelly-intro-stat-value">Scoped OP-MEME liquidation only</span>
              </div>
              <div className="jelly-intro-stat">
                <span className="jelly-intro-stat-label">T+35</span>
                <span className="jelly-intro-stat-value">Hedge profit + bucket wind-down</span>
              </div>
            </div>
            <p className="jelly-intro-thesis">
              On Hyperliquid, HLP and traders absorbed catastrophic loss. On Morpheum, operator
              buckets isolate toxic flow — loss stays in OP-MEME while OP-SAFE, OP-HEDGE, and
              OP-INSURANCE remain protected.
            </p>
            <p className="jelly-intro-body jelly-intro-body--muted">
              Next, configure your operator vault, then replay the incident.
            </p>
          </div>
        )}

        {slideIndex === 2 && (
          <div className="jelly-intro-slide">
            <h2 className="jelly-intro-title">Configure operator vault</h2>
            <p className="jelly-intro-body jelly-intro-body--muted">
              Set vault deposit and bucket split before the replay begins. Timeline amounts scale
              from {formatUsd(REFERENCE_DEPOSIT)} reference.
            </p>

            <div className="jelly-intro-slider-row">
              <div className="jelly-intro-slider-header">
                <span>Vault deposit (USDC)</span>
                <span className="jelly-intro-slider-value">{formatUsd(depositUsd)}</span>
              </div>
              <FilledRangeSlider
                variant="info"
                className="jelly-intro-slider"
                min={DEPOSIT_MIN}
                max={DEPOSIT_MAX}
                step={DEPOSIT_STEP}
                value={depositUsd}
                onChange={setDepositUsd}
              />
            </div>

            <div className="jelly-intro-slider-row">
              <div className="jelly-intro-slider-header">
                <span>OP-SAFE (cross · majors)</span>
                <span className="jelly-intro-slider-value">
                  {safePct}% · {formatUsd(bucketAmount(draftConfig, safePct))}
                </span>
              </div>
              <FilledRangeSlider
                variant="info"
                className="jelly-intro-slider"
                min={MIN_BUCKET_PCT}
                max={70}
                step={1}
                value={safePct}
                onChange={(value) => applyBucketChange(value, memePct, hedgePct)}
              />
            </div>

            <div className="jelly-intro-slider-row">
              <div className="jelly-intro-slider-header">
                <span>OP-MEME (isolated · JELLY silo)</span>
                <span className="jelly-intro-slider-value">
                  {memePct}% · {formatUsd(bucketAmount(draftConfig, memePct))}
                </span>
              </div>
              <FilledRangeSlider
                variant="info"
                className="jelly-intro-slider"
                min={MIN_BUCKET_PCT}
                max={50}
                step={1}
                value={memePct}
                onChange={(value) => applyBucketChange(safePct, value, hedgePct)}
              />
            </div>

            <div className="jelly-intro-slider-row">
              <div className="jelly-intro-slider-header">
                <span>OP-HEDGE (cross · pair trades)</span>
                <span className="jelly-intro-slider-value">
                  {hedgePct}% · {formatUsd(bucketAmount(draftConfig, hedgePct))}
                </span>
              </div>
              <FilledRangeSlider
                variant="info"
                className="jelly-intro-slider"
                min={MIN_BUCKET_PCT}
                max={40}
                step={1}
                value={hedgePct}
                onChange={(value) => applyBucketChange(safePct, memePct, value)}
              />
            </div>

            <div className="jelly-intro-slider-row jelly-intro-slider-row--readonly">
              <div className="jelly-intro-slider-header">
                <span>OP-INSURANCE (isolated · 0x leverage)</span>
                <span className="jelly-intro-slider-value">
                  {insurancePct.toFixed(2)}% · {formatUsd(bucketAmount(draftConfig, insurancePct))}
                </span>
              </div>
            </div>
          </div>
        )}

        <div className="jelly-intro-footer">
          {slideIndex > 0 ? (
            <button
              type="button"
              className="jelly-intro-btn jelly-intro-btn--ghost"
              onClick={() => setSlideIndex((s) => s - 1)}
            >
              Back
            </button>
          ) : (
            <span />
          )}
          {slideIndex < SLIDE_COUNT - 1 ? (
            <button
              type="button"
              className="jelly-intro-btn jelly-intro-btn--primary"
              onClick={() => setSlideIndex((s) => s + 1)}
            >
              Next
            </button>
          ) : (
            <button
              type="button"
              className="jelly-intro-btn jelly-intro-btn--primary"
              onClick={() => onStartReplay(draftConfig)}
            >
              Start Replay
            </button>
          )}
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return createPortal(modalContent, document.body);
}

export default JellyIntroModal;
