import React, { useLayoutEffect, useRef, useState, type JSX, type PointerEvent } from "react";
import { formatPrice } from "../../sdk/utils/display";
import { resolveSideColor } from "./chartMarkers";

export interface PendingOrderPriceTagProps {
  price: number;
  side: "Buy" | "Sell";
  draggable: boolean;
  dragging?: boolean;
  canceling?: boolean;
  left: number;
  top: number;
  width: number;
  onDragStart?: (event: PointerEvent<HTMLButtonElement>) => void;
  onCancel?: () => void;
  onPointerEnter?: () => void;
  onPointerLeave?: () => void;
}

function PendingOrderPriceTag({
  price,
  side,
  draggable,
  dragging = false,
  canceling = false,
  left,
  top,
  width,
  onDragStart,
  onCancel,
  onPointerEnter,
  onPointerLeave,
}: PendingOrderPriceTagProps): JSX.Element {
  const tagRef = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ left, top: top });

  useLayoutEffect(() => {
    const tag = tagRef.current;
    if (!tag) return;
    const tagHeight = tag.offsetHeight;
    setPosition({ left, top: top - tagHeight / 2 });
  }, [left, top, width, price, draggable, dragging, canceling]);

  const classNames = [
    "pending-order-price-tag",
    "pending-order-price-tag--interactive",
    draggable ? "pending-order-price-tag--draggable" : "",
    dragging ? "pending-order-price-tag--dragging" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const disabled = dragging || canceling;

  return (
    <div
      ref={tagRef}
      className={classNames}
      style={{ left: position.left, top: position.top, width }}
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      role="group"
      aria-label="Pending order price"
    >
      {draggable ? (
        <button
          type="button"
          className="pending-order-price-tag__grip"
          aria-label="Drag to change price"
          disabled={disabled}
          onPointerDown={onDragStart}
        >
          <svg
            className="pending-order-price-tag__grip-icon"
            width="8"
            height="12"
            viewBox="0 0 8 12"
            aria-hidden
          >
            <circle cx="2" cy="2" r="1" fill="currentColor" />
            <circle cx="6" cy="2" r="1" fill="currentColor" />
            <circle cx="2" cy="6" r="1" fill="currentColor" />
            <circle cx="6" cy="6" r="1" fill="currentColor" />
            <circle cx="2" cy="10" r="1" fill="currentColor" />
            <circle cx="6" cy="10" r="1" fill="currentColor" />
          </svg>
        </button>
      ) : null}
      <span
        className="pending-order-price-tag__price"
        style={{ color: resolveSideColor(side) }}
      >
        {formatPrice(price)}
      </span>
      <button
        type="button"
        className="pending-order-price-tag__cancel"
        aria-label="Cancel order"
        disabled={disabled}
        onClick={(event) => {
          event.stopPropagation();
          onCancel?.();
        }}
      >
        ×
      </button>
    </div>
  );
}

export default PendingOrderPriceTag;
