import React, { createContext, useContext, useMemo, useState } from "react";
import {
  DEFAULT_THROUGHPUT_TIER,
  DEFAULT_VALIDATOR_COUNT,
  type DemoContext,
  type ThroughputTier,
  VALIDATOR_MAX,
  VALIDATOR_MIN,
} from "./types";

interface NetworkHealthDemoState extends DemoContext {
  setThroughputTier: (tier: ThroughputTier) => void;
  setValidatorCount: (count: number) => void;
}

const NetworkHealthDemoContext = createContext<NetworkHealthDemoState | null>(null);

export function NetworkHealthDemoProvider({
  children,
}: {
  children: React.ReactNode;
}): React.JSX.Element {
  const [throughputTier, setThroughputTierState] = useState<ThroughputTier>(DEFAULT_THROUGHPUT_TIER);
  const [validatorCount, setValidatorCountState] = useState(DEFAULT_VALIDATOR_COUNT);

  const setThroughputTier = (tier: ThroughputTier) => {
    setThroughputTierState(tier);
  };

  const setValidatorCount = (count: number) => {
    const clamped = Math.min(VALIDATOR_MAX, Math.max(VALIDATOR_MIN, Math.round(count)));
    setValidatorCountState(clamped);
  };

  const value = useMemo(
    () => ({
      throughputTier,
      validatorCount,
      setThroughputTier,
      setValidatorCount,
    }),
    [throughputTier, validatorCount],
  );

  return (
    <NetworkHealthDemoContext.Provider value={value}>
      {children}
    </NetworkHealthDemoContext.Provider>
  );
}

export function useNetworkHealthDemo(): NetworkHealthDemoState {
  const ctx = useContext(NetworkHealthDemoContext);
  if (!ctx) {
    throw new Error("useNetworkHealthDemo must be used within NetworkHealthDemoProvider");
  }
  return ctx;
}
