import React from "react";
import { usePortfolioAnalytics } from "../../hooks/usePortfolioAnalytics";
import { useTradingAgents } from "../../hooks/useTradingAgents";
import {
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import "../smartlayout/layout.css";
import "./portfolio.css";

export interface PortfolioLeaderboardPanelProps {
  height?: string;
  baseURL: string;
  walletAddress: string;
  filterAgentIds?: string[];
  refreshInterval?: number;
}

const LEADERBOARD_GRID_COLUMNS =
  "minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr)";

function formatCurrency(value: number): string {
  const sign = value < 0 ? "-" : "";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000) return `${sign}$${(abs / 1_000).toFixed(1)}k`;
  return `${sign}$${abs.toFixed(2)}`;
}

function formatPct(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`;
}

function PortfolioLeaderboardPanel({
  height = "100%",
  baseURL,
  walletAddress,
  refreshInterval,
}: PortfolioLeaderboardPanelProps): JSX.Element {
  const { selectedAgentId, setSelectedAgentId } = useTradingAgents();
  const analytics = usePortfolioAnalytics({
    baseURL,
    walletAddress,
    filterAgentIds: [],
    refreshInterval,
  });

  return (
    <div className="portfolio-slot portfolio-slot--flush" style={{ height }}>
      <section className="portfolio-ledger-panel" aria-label="Agent leaderboard">
        <div className="portfolio-ledger-panel-body">
          <div className="portfolio-leaderboard-table table-container shrinkable">
            {analytics.leaderboard.length === 0 ? (
              <p className="terminal-text-muted">No agent performance data.</p>
            ) : (
              <>
                <div
                  className="table-header portfolio-leaderboard-header"
                  style={{ gridTemplateColumns: LEADERBOARD_GRID_COLUMNS }}
                  role="row"
                >
                  <TableHeaderCellStatic left>Agent</TableHeaderCellStatic>
                  <TableHeaderCellStatic left>
                    <TableHeaderLabel {...TABLE_HEADER_LABELS.revenue30d} />
                  </TableHeaderCellStatic>
                  <TableHeaderCellStatic left>ROI</TableHeaderCellStatic>
                  <TableHeaderCellStatic left>
                    <TableHeaderLabel {...TABLE_HEADER_LABELS.winRate} />
                  </TableHeaderCellStatic>
                </div>
                {analytics.leaderboard.map((row) => {
                  const isFocused = selectedAgentId === row.id;
                  return (
                    <button
                      key={row.id}
                      type="button"
                      className={`portfolio-leaderboard-row${isFocused ? " is-focused" : ""}`}
                      style={{ gridTemplateColumns: LEADERBOARD_GRID_COLUMNS }}
                      aria-pressed={isFocused}
                      onClick={() =>
                        setSelectedAgentId(isFocused ? null : row.id)
                      }
                    >
                      <span className="portfolio-leaderboard-name">
                        {row.icon ? `${row.icon} ` : ""}
                        {row.label}
                      </span>
                      <span>{formatCurrency(row.revenue30d)}</span>
                      <span
                        className={row.roiPct >= 0 ? "positive" : "negative"}
                      >
                        {formatPct(row.roiPct)}
                      </span>
                      <span>{row.winRate.toFixed(0)}%</span>
                    </button>
                  );
                })}
              </>
            )}
          </div>
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioLeaderboardPanel);
