import { isMobileBreakpoint } from "../../configs/terminalLayoutConfig";

export type SafetyLogLayout = "table" | "tableCompact" | "cards" | "cardsReview";

export const SAFETY_LOG_CARD_PREVIEW_COUNT = 4;

export function getSafetyLogLayout(breakpoint: string): SafetyLogLayout {
  if (breakpoint === "sm") return "cards";
  if (isMobileBreakpoint(breakpoint)) return "cardsReview";
  if (breakpoint === "md") return "tableCompact";
  return "table";
}

export type GuardedHeroVariant = "lg" | "md" | "sm" | "xs";

export function getGuardedHeroVariant(breakpoint: string): GuardedHeroVariant {
  if (isMobileBreakpoint(breakpoint)) return "xs";
  if (breakpoint === "sm") return "sm";
  if (breakpoint === "md") return "md";
  return "lg";
}

export function shouldGuardedHeroCollapse(breakpoint: string): boolean {
  return breakpoint !== "lg";
}

/** HIL SafetyHeader shell — drives tier visibility and CSS grid placement */
export type SafetyHeaderLayoutMode = "lg" | "collapsed" | "expanded";

export function getSafetyHeaderLayoutMode(
  layoutBreakpoint: string,
  guardedHeroExpanded: boolean,
  hilPolishActive: boolean,
): SafetyHeaderLayoutMode {
  if (!hilPolishActive || layoutBreakpoint === "lg") return "lg";
  if (guardedHeroExpanded) return "expanded";
  return "collapsed";
}
