import React from "react";
import type { AgentTask } from "../../store/types";
import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import { formatRelativeTime } from "../../utils/formatRelativeTime";
import SafetyAuditLogMetricCell from "./SafetyAuditLogMetricCell";
import SafetyAuditLogRowActions from "./SafetyAuditLogRowActions";
import { getGuardrailMeta } from "./guardrailMeta";
import type { SafetyLogLayout } from "./safetyAuditLogLayout";

export interface SafetyAuditLogIntentCardProps {
  task: AgentTask;
  agentLabel: string;
  layout: SafetyLogLayout;
  sizePct: number;
  onSizePctChange: (value: number) => void;
  onApprove: () => void;
  onReject: () => void;
  onReview?: () => void;
  onRequestViewOnChart?: () => void;
}

function SafetyAuditLogIntentCard({
  task,
  agentLabel,
  layout,
  sizePct,
  onSizePctChange,
  onApprove,
  onReject,
  onReview,
  onRequestViewOnChart,
}: SafetyAuditLogIntentCardProps): JSX.Element {
  const meta = getGuardrailMeta(task);
  const summary = task.trigger || task.description;
  const isReviewMode = layout === "cardsReview";
  const statusLabel =
    AGENT_TASK_STATUS_CONFIG[task.status]?.label ?? task.status;
  const chartInteractive = Boolean(onRequestViewOnChart);

  const handleSummaryKeyDown = (e: React.KeyboardEvent) => {
    if (!onRequestViewOnChart) return;
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      onRequestViewOnChart();
    }
  };

  return (
    <article
      className={[
        "safety-audit-log-card",
        task.status === "pending" ? "safety-audit-log-card--pending" : "",
        task.status === "watching" ? "safety-audit-log-card--watching" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <div className="safety-audit-log-card-head">
        {task.status === "pending" ? (
          <span className="safety-audit-log-pending-badge">Pending</span>
        ) : task.status === "watching" ? (
          <span className="safety-audit-log-watching-badge">{statusLabel}</span>
        ) : null}
        <span className="safety-audit-log-card-agent">{agentLabel}</span>
        <time
          className="terminal-value safety-audit-log-card-time"
          dateTime={new Date(task.updatedAt).toISOString()}
        >
          {formatRelativeTime(task.updatedAt)}
        </time>
      </div>
      <button
        type="button"
        className={[
          "safety-audit-log-card-summary",
          chartInteractive ? "safety-audit-log-card-summary--interactive" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        title={summary}
        aria-label={chartInteractive ? `View ${summary} on chart` : undefined}
        disabled={!chartInteractive}
        onClick={onRequestViewOnChart}
        onKeyDown={chartInteractive ? handleSummaryKeyDown : undefined}
      >
        {summary}
      </button>
      <SafetyAuditLogMetricCell
        riskImpact={meta.riskImpact}
        confidencePct={meta.confidencePct}
        variant="card"
      />
      <p className="safety-audit-log-card-fill-impact">
        Est. +{meta.expectedFillImpactBps.toFixed(1)} bps slippage
      </p>
      {isReviewMode ? (
        <button
          type="button"
          className="safety-audit-log-btn safety-audit-log-btn--review"
          aria-label={`Review intent from ${agentLabel}`}
          onClick={onReview}
        >
          Review
        </button>
      ) : (
        <SafetyAuditLogRowActions
          taskId={task.id}
          sizePct={sizePct}
          onSizePctChange={onSizePctChange}
          onApprove={onApprove}
          onReject={onReject}
        />
      )}
    </article>
  );
}

export default React.memo(SafetyAuditLogIntentCard);
