/** Dispatched before in-app route changes so heavy views (e.g. agent kline) can tear down first. */
export const PRE_NAVIGATE_CLEANUP_EVENT = "morpheum:pre-navigate-cleanup";

/** Notifies the app shell that the browser URL changed (for route-location reconciliation). */
export const ROUTE_PUSH_EVENT = "morpheum:route-push";

export function dispatchRoutePush(): void {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new Event(ROUTE_PUSH_EVENT));
}

export function dispatchPreNavigateCleanup(): void {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new Event(PRE_NAVIGATE_CLEANUP_EVENT));
}

let historyPatchInstalled = false;

function installHistoryPathnameNotify(): void {
  if (typeof window === "undefined" || historyPatchInstalled) return;
  historyPatchInstalled = true;

  const notify = () => dispatchRoutePush();
  const { pushState, replaceState } = window.history;

  window.history.pushState = function patchedPushState(...args) {
    pushState.apply(this, args);
    notify();
  };
  window.history.replaceState = function patchedReplaceState(...args) {
    replaceState.apply(this, args);
    notify();
  };
}

/** Subscribe to browser pathname changes (pushState via router + back/forward). */
export function subscribeBrowserPathname(onStoreChange: () => void): () => void {
  if (typeof window === "undefined") return () => {};
  installHistoryPathnameNotify();
  const notify = () => onStoreChange();
  window.addEventListener(ROUTE_PUSH_EVENT, notify);
  window.addEventListener("popstate", notify);
  return () => {
    window.removeEventListener(ROUTE_PUSH_EVENT, notify);
    window.removeEventListener("popstate", notify);
  };
}

export function getBrowserPathname(): string {
  if (typeof window === "undefined") return "/";
  return window.location.pathname;
}

/** Pathname + search + hash — used to reconcile Routes when the router stalls. */
export function getBrowserLocationKey(): string {
  if (typeof window === "undefined") return "/";
  const { pathname, search, hash } = window.location;
  return `${pathname}${search}${hash}`;
}

/** Routes with heavy kline/chart views that need deferred navigation after teardown. */
export function needsChartTeardownBeforeNavigate(pathname: string): boolean {
  return pathname === "/trade" || /^\/agents\/[^/]+$/.test(pathname);
}

function deferNavigate(navigate: () => void): void {
  requestAnimationFrame(() => {
    requestAnimationFrame(navigate);
  });
}

/** Tear down blocking UI, then run navigation after chart unmount can commit. */
export function runAfterPreNavigateCleanup(navigate: () => void): void {
  dispatchPreNavigateCleanup();
  deferNavigate(navigate);
}
