/**
 * Agent compare terminal — matrix body in a single full-width slot.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { Navigate, useNavigate, useSearchParams } from "react-router-dom";

import {
  AgentCompareBody,
  AgentCompareFocusBar,
  AgentCompareSavedListsModal,
  AgentCompareSelector,
  AgentCompareShareModal,
  AgentDiscoveryRail,
} from "../components/agent";
import { buildAgentCompareSharePayload } from "../components/agent/share/agentCompareShareData";
import {
  DEFAULT_AGENT_COMPARE_FOCUS,
  type AgentCompareFocus,
} from "../components/agent/agentCompareFocus";
import { GridViewerLayout, GRID_COLS } from "../components";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  AGENT_COMPARE_SLOT_INDICES,
  AGENT_LAYOUT_MARGIN,
  AGENT_ROW_HEIGHT,
  buildAgentCompareResponsiveLayoutConfig,
  generateAgentCompareResponsiveLayouts,
} from "../configs/agentCompareLayoutConfig";
import { useCompareAgentsData } from "../hooks/useCompareAgentsData";
import { APP_ROUTES } from "../routes";
import { parseCompareIds, toggleCompareId, MAX_AGENT_COMPARE, buildComparePath } from "../utils/agentCompareIds";
import { useAgentCompareSavedLists } from "../hooks/useAgentCompareSavedLists";
import "./AgentComparePage.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [AGENT_LAYOUT_MARGIN, AGENT_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = AGENT_ROW_HEIGHT;

function buildLayouts(viewportHeight?: number) {
  void viewportHeight;
  const base = buildAgentCompareResponsiveLayoutConfig();
  return generateAgentCompareResponsiveLayouts(base, 0);
}

export default function AgentComparePage(): JSX.Element {
  const [searchParams, setSearchParams] = useSearchParams();
  const compareIds = useMemo(
    () => parseCompareIds(searchParams.get("ids")),
    [searchParams],
  );

  if (compareIds.length === 0) {
    return <Navigate to={APP_ROUTES.markets} replace />;
  }

  const handleCompareIdsChange = (ids: string[]) => {
    if (ids.length === 0) {
      setSearchParams({}, { replace: true });
      return;
    }
    setSearchParams({ ids: ids.join(",") }, { replace: true });
  };

  return (
    <AgentComparePageContent
      key={compareIds.join(",")}
      compareIds={compareIds}
      onCompareIdsChange={handleCompareIdsChange}
    />
  );
}

function AgentComparePageContent({
  compareIds,
  onCompareIdsChange,
}: {
  compareIds: string[];
  onCompareIdsChange: (ids: string[]) => void;
}): JSX.Element {
  const compareData = useCompareAgentsData(compareIds);
  const [compareFocus, setCompareFocus] = useState<AgentCompareFocus>(
    DEFAULT_AGENT_COMPARE_FOCUS,
  );
  const [highlightBest, setHighlightBest] = useState(true);
  const [compareSelectorOpen, setCompareSelectorOpen] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [savedListsOpen, setSavedListsOpen] = useState(false);
  const navigate = useNavigate();
  const { savedLists, isCurrentSaved, addCurrentList, removeList } =
    useAgentCompareSavedLists(compareIds);
  const showAddSlot =
    compareIds.length >= 2 && compareIds.length < MAX_AGENT_COMPARE;
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);
  const matrixHeaderRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(window.innerHeight);
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };

    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, []);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex += 1) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const sharePayload = useMemo(
    () =>
      compareData.loading
        ? null
        : buildAgentCompareSharePayload(compareIds, compareFocus, { highlightBest }),
    [compareIds, compareFocus, highlightBest, compareData.loading],
  );

  const handleCompareAgentSelect = useCallback(
    (id: string) => {
      onCompareIdsChange(toggleCompareId(compareIds, id));
    },
    [compareIds, onCompareIdsChange],
  );

  const handleListClick = useCallback(() => {
    if (isCurrentSaved) {
      setSavedListsOpen(true);
      return;
    }
    if (compareIds.length < 2) return;
    addCurrentList(compareIds);
  }, [addCurrentList, compareIds, isCurrentSaved]);

  const handleSavedListView = useCallback(
    (agentIds: string[]) => {
      navigate(buildComparePath(agentIds));
      setSavedListsOpen(false);
    },
    [navigate],
  );

  const handleShareClick = useCallback(() => {
    if (compareData.loading || !sharePayload) return;
    setShareOpen(true);
  }, [compareData.loading, sharePayload]);

  const columnSlots = useMemo(() => {
    const slots: React.ReactNode[] = [null, null, null, null, null, null, null, null, null];

    slots[AGENT_COMPARE_SLOT_INDICES.body] = (
      <AgentCompareBody
        key="compare-body"
        compareIds={compareIds}
        compareData={compareData}
        compareFocus={compareFocus}
        highlightBest={highlightBest}
        height={slotDimensions[AGENT_COMPARE_SLOT_INDICES.body]?.height}
        showAddSlot={showAddSlot}
        matrixHeaderRef={matrixHeaderRef}
        onRequestAddAgent={() => setCompareSelectorOpen(true)}
        onRemoveAgent={handleCompareAgentSelect}
      />
    );

    slots[AGENT_COMPARE_SLOT_INDICES.focusHero] = (
      <AgentCompareFocusBar
        key="focus-hero"
        height={slotDimensions[AGENT_COMPARE_SLOT_INDICES.focusHero]?.height}
        focus={compareFocus}
        onFocusChange={setCompareFocus}
        onShareClick={handleShareClick}
        shareDisabled={compareData.loading}
        listAddDisabled={compareIds.length < 2}
        isCurrentSaved={isCurrentSaved}
        onListClick={handleListClick}
        highlightBest={highlightBest}
        onHighlightBestChange={setHighlightBest}
      />
    );

    slots[AGENT_COMPARE_SLOT_INDICES.discovery] = (
      <AgentDiscoveryRail
        key="discovery"
        variant="compare"
        height={slotDimensions[6]?.height}
        compareIds={compareIds}
        onCompareIdsChange={onCompareIdsChange}
      />
    );

    return slots;
  }, [
    compareData,
    compareFocus,
    compareIds,
    handleCompareAgentSelect,
    handleListClick,
    handleShareClick,
    highlightBest,
    isCurrentSaved,
    onCompareIdsChange,
    showAddSlot,
    slotDimensions,
  ]);

  return (
    <div className="App-dex-content App-dex-content--agent-compare">
      <AgentCompareSelector
        isOpen={compareSelectorOpen}
        onClose={() => setCompareSelectorOpen(false)}
        compareIds={compareIds}
        onSelect={handleCompareAgentSelect}
        anchorRef={matrixHeaderRef}
      />
      {sharePayload ? (
        <AgentCompareShareModal
          isOpen={shareOpen}
          onClose={() => setShareOpen(false)}
          payload={sharePayload}
        />
      ) : null}
      <AgentCompareSavedListsModal
        isOpen={savedListsOpen}
        onClose={() => setSavedListsOpen(false)}
        savedLists={savedLists}
        currentCompareIds={compareIds}
        onRemove={removeList}
        onView={handleSavedListView}
      />
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={columnSlots}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
    </div>
  );
}
