import TradingViewWidget from "../tradingview/TradingViewWidget";
import type { ChartProvider } from "../preference/SettingsModal";
import type { TradingMode } from "../../configs/tradeLayoutMode";
import KlineChartWidget from "./KlineChartWidget";
import AgentTokenKlineChartWidget from "./AgentTokenKlineChartWidget";
import type { ChartTradeFocusRequest } from "./chartMarkers";
import type { AgentTokenTakerTradeEvent } from "../../../offline/mock_data/agentTokenTakerHistory.types";
import React, { lazy, Suspense, type JSX } from "react";

const JellyKlineChartWidget = lazy(() => import("./JellyKlineChartWidget"));
export interface ChartSlotProps {
  provider: ChartProvider;
  symbol?: string;
  interval?: string;
  tradingViewSymbol?: string;
  tradingViewInterval?: string;
  height?: string;
  isCollapsed?: boolean;
  className?: string;
  jellyMode?: boolean;
  marketId?: string;
  baseAsset?: string;
  walletAddress?: string;
  baseURL?: string;
  authToken?: string;
  mnemonic?: string;
  showExecutionMarkers?: boolean;
  showPendingOrderLines?: boolean;
  tradeFocus?: ChartTradeFocusRequest | null;
  containerRef?: React.RefObject<HTMLDivElement | null>;
  /** Agent layout mode — reserved for intent marker overlays */
  tradingMode?: TradingMode;
  agentTokenCatalogId?: string;
  showTokenTakerMarkers?: boolean;
  tokenTakerEvents?: AgentTokenTakerTradeEvent[];
  tokenTakerEventsLoading?: boolean;
  focusEventId?: string | null;
  focusTimeMs?: number;
}

function ChartSlot({
  provider,
  symbol,
  interval,
  tradingViewSymbol,
  tradingViewInterval,
  height,
  isCollapsed = false,
  className = "",
  jellyMode = false,
  marketId,
  baseAsset,
  walletAddress,
  baseURL,
  authToken,
  mnemonic,
  showExecutionMarkers = true,
  showPendingOrderLines = true,
  tradeFocus = null,
  containerRef,
  tradingMode = "proTerminal",
  agentTokenCatalogId,
  showTokenTakerMarkers = false,
  tokenTakerEvents = [],
  tokenTakerEventsLoading = false,
  focusEventId = null,
  focusTimeMs = 0,
}: ChartSlotProps): JSX.Element {
  const chartDataTour = { "data-tour": "welcome-chart" as const };
  const agentOverlayClass =
    tradingMode !== "proTerminal" ? " chart-slot--agent-overlay" : "";

  if (jellyMode) {
    return (
      <div ref={containerRef} {...chartDataTour} style={{ height, width: "100%" }}>
        <Suspense fallback={null}>
          <JellyKlineChartWidget height={height} className={className} />
        </Suspense>
      </div>
    );
  }

  if (agentTokenCatalogId) {
    return (
      <div
        ref={containerRef}
        {...chartDataTour}
        className={agentOverlayClass.trim() || undefined}
        style={{ height, width: "100%" }}
        data-trading-mode={tradingMode}
      >
        <AgentTokenKlineChartWidget
          catalogAgentId={agentTokenCatalogId}
          interval={interval ?? tradingViewInterval ?? "5m"}
          height={height}
          className={className}
          showTokenTakerMarkers={showTokenTakerMarkers}
          tokenTakerEvents={tokenTakerEvents}
          tokenTakerEventsLoading={tokenTakerEventsLoading}
          focusEventId={focusEventId}
          focusTimeMs={focusTimeMs}
        />
      </div>
    );
  }

  if (provider === "kline") {
    return (
      <div
        ref={containerRef}
        {...chartDataTour}
        className={agentOverlayClass.trim() || undefined}
        style={{ height, width: "100%" }}
        data-trading-mode={tradingMode}
      >
        <KlineChartWidget
        symbol={symbol ?? tradingViewSymbol}
        interval={interval ?? tradingViewInterval ?? "5m"}
        height={height}
        className={className}
        marketId={marketId}
        baseAsset={baseAsset}
        walletAddress={walletAddress}
        baseURL={baseURL}
        authToken={authToken}
        mnemonic={mnemonic}
        showExecutionMarkers={showExecutionMarkers}
        showPendingOrderLines={showPendingOrderLines}
        tradeFocus={tradeFocus}
        />
      </div>
    );
  }

  // TradingView free embed cannot render custom execution markers (Charting Library required).
  return (
    <div ref={containerRef} {...chartDataTour} style={{ height, width: "100%" }}>
      <TradingViewWidget
        symbol={tradingViewSymbol}
        interval={tradingViewInterval}
        isCollapsed={isCollapsed}
        height={height}
        className={className}
      />
    </div>
  );
}

export default ChartSlot;
