import React, { useEffect, useRef, useState } from "react";
import type { SecurityStage } from "../../../types/crossChainFlow";
import "./cross-chain.css";

const FAILURE_STAGES: SecurityStage[] = [
  "authorize",
  "submit",
  "locked",
  "attested",
  "delivered",
];

export interface CrossChainDemoHelperProps {
  onPreviewFailure: (stage: SecurityStage) => void;
  onFailOnNextConfirm: (stage: SecurityStage) => void;
}

export function CrossChainDemoHelper({
  onPreviewFailure,
  onFailOnNextConfirm,
}: CrossChainDemoHelperProps): JSX.Element {
  const [open, setOpen] = useState(false);
  const [stage, setStage] = useState<SecurityStage>("attested");
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  return (
    <div className="cross-chain-demo-helper" ref={ref}>
      <button
        type="button"
        className="btn btn-secondary btn-sm"
        onClick={() => setOpen((v) => !v)}
        title="Demo: preview failure flows"
        aria-label="Demo helper"
      >
        Demo ⓘ
      </button>
      {open && (
        <div className="cross-chain-demo-helper-menu">
          <label htmlFor="demo-fail-stage">Failure stage</label>
          <select
            id="demo-fail-stage"
            value={stage}
            onChange={(e) => setStage(e.target.value as SecurityStage)}
          >
            {FAILURE_STAGES.map((s) => (
              <option key={s} value={s}>
                {s.charAt(0).toUpperCase() + s.slice(1)}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={() => {
              onPreviewFailure(stage);
              setOpen(false);
            }}
          >
            Preview failure now
          </button>
          <button
            type="button"
            onClick={() => {
              onFailOnNextConfirm(stage);
              setOpen(false);
            }}
          >
            Fail on next confirm
          </button>
        </div>
      )}
    </div>
  );
}
