/**
 * Transform API/WS response to Position format
 * Converts Satoshi strings to decimal numbers for display
 * Handles both RawPosition (from HTTP API) and MultiFeedPositionsData (from WebSocket)
 * This is a pure function with no dependencies, suitable for use outside React hooks
 */
export function transformPosition(
  pos: RawPosition | MultiFeedPositionsData,
): Position {
  // Normalize position data - handle both RawPosition and MultiFeedPositionsData (proto camelCase)
  let positionId: string;
  if ("positionId" in pos && pos.positionId) {
    positionId = pos.positionId;
  } else {
    // Generate fallback ID if missing (for WebSocket updates without positionId)
    positionId = `${pos.marketIndex}-${pos.bucketId || "default"}-${pos.address}`;
  }

  // Get entry price - RawPosition uses averageEntryPrice, MultiFeedPositionsData uses entryPrice
  const entryPriceStr =
    "averageEntryPrice" in pos
      ? pos.averageEntryPrice
      : pos.entryPrice;

  // Get side - RawPosition uses side (string), MultiFeedPositionsData uses positionSide
  let side: "LONG" | "SHORT";
  if ("positionSide" in pos && pos.positionSide) {
    side = pos.positionSide;
  } else if ("side" in pos && pos.side) {
    // RawPosition format: "SIDE_BUY" (long) or "SIDE_SELL" (short)
    side =
      pos.side === "SIDE_BUY" || pos.side.toUpperCase().includes("BUY")
        ? ORDER_SIDE_LONG
        : ORDER_SIDE_SHORT;
  } else {
    // Fallback: infer from size sign
    const size = toNumberFromSatoshi(pos.size);
    side = size >= 0 ? ORDER_SIDE_LONG : ORDER_SIDE_SHORT;
  }

  // Convert size
  const size = toNumberFromSatoshi(pos.size);

  // Convert numeric fields from Satoshi strings to decimals (proto camelCase)
  const entryPrice = toNumberFromSatoshi(entryPriceStr);
  const markPrice = toNumberFromSatoshi(pos.markPrice);
  const leverage = pos.leverage
    ? toNumberFromSatoshi(pos.leverage)
    : 0;

  // Calculate unrealized PnL from API format (unrealizedProfit - unrealizedLoss) or legacy unrealizedPnl
  let unrealizedPnL = 0;
  if (
    pos.unrealizedProfit !== undefined ||
    pos.unrealizedLoss !== undefined
  ) {
    const profitBigInt = toBigInt(pos.unrealizedProfit);
    const lossBigInt = toBigInt(pos.unrealizedLoss);
    const pnlBigInt = profitBigInt - lossBigInt;
    unrealizedPnL = toNumberFromSatoshi(pnlBigInt.toString());
  } else if ("unrealizedPnl" in pos && pos.unrealizedPnl !== undefined) {
    unrealizedPnL = toNumberFromSatoshi(pos.unrealizedPnl);
  }

  const marginBalance = toNumberFromSatoshi(pos.marginBalance);
  const margin =
    marginBalance ||
    (leverage && entryPrice && size !== 0
      ? Math.abs((Math.abs(size) * entryPrice) / leverage)
      : 0);

  const marginMode =
    ("marginMode" in pos && pos.marginMode) ||
    ("marginType" in pos && pos.marginType) ||
    MARGIN_MODE_CROSS;

  return {
    positionId,
    marketId: String(pos.marketIndex),
    symbol: pos.symbol || `m-${pos.marketIndex}`,
    size: Math.abs(size),
    entryPrice,
    markPrice,
    liquidationPrice: pos.liquidationPrice
      ? toNumberFromSatoshi(pos.liquidationPrice)
      : 0,
    unrealizedPnL,
    leverage,
    margin,
    side,
    marginMode,
    bucketId: pos.bucketId ? String(pos.bucketId) : "",
    agentTaskId:
      "agentTaskId" in pos && pos.agentTaskId != null && pos.agentTaskId !== ""
        ? String(pos.agentTaskId)
        : null,
    raw: pos,
  };
}

/**
 * Transform RawOrder from API/WS response to PendingOrder format
 * Handles RawOrder structure from API (snake_case with enum values and string numbers)
 * Based on RawOrder interface from src/sdk/types/api.ts
 * Requires orderId to be set for display; marketIndex is required (proto camelCase).
 * This is a pure function with no dependencies, suitable for use outside React hooks
 */
export function transformRawOrderToPendingOrder(order: RawOrder): PendingOrder {
  const normalizedSide = order.side === "SIDE_BUY" ? "BUY" : "SELL";

  let normalizedStatus: string = order.status || "ORDER_STATUS_PENDING";
  if (normalizedStatus.includes("ORDER_STATUS_")) {
    normalizedStatus = normalizedStatus.replace("ORDER_STATUS_", "");
  }
  const rawTimeInForce = order.timeInForce;
  let normalizedTimeInForce: string | undefined = rawTimeInForce;
  if (rawTimeInForce && rawTimeInForce.includes("TIME_IN_FORCE_")) {
    normalizedTimeInForce = rawTimeInForce.replace("TIME_IN_FORCE_", "");
  }

  const parseNumber = (value: string | number | undefined): number =>
    toNumberFromSatoshi(value);

  const quantity = parseNumber(order.quantity);
  const price = parseNumber(order.price);
  const filledQuantity = parseNumber(order.filledQuantity);
  const remainingQuantity = quantity - filledQuantity;

  const orderId = order.orderId ?? "";
  const marketId = order.marketIndex ?? "";

  // Convert timestamp to number (milliseconds)
  // RawOrder.timestamp can be Timestamp object (with seconds/nanos) or string/number
  // PendingOrder requires createdAt and updatedAt as numbers (not undefined)
  // Use normalizeProtobufTimestamp utility which handles all timestamp formats
  const timestamp = normalizeProtobufTimestamp(order.timestamp, Date.now());
  return {
    id: orderId,
    orderId,
    marketId,
    side: normalizedSide,
    type: order.type,
    quantity,
    price,
    filledQuantity,
    remainingQuantity,
    status: normalizedStatus,
    timeInForce: normalizedTimeInForce ?? "",
    createdAt: timestamp,
    updatedAt: timestamp,
    agentTaskId:
      "agentTaskId" in order &&
      order.agentTaskId != null &&
      order.agentTaskId !== ""
        ? String(order.agentTaskId)
        : null,
    raw: order,
  };
}

