import { timestampToISOString } from "../utils/time";

const PLACEHOLDER_BUCKET_IDS = new Set(["---", "--", ""]);

/**
 * Coerce API/wire bucket id to a non-empty string, or null when missing/placeholder.
 */
export function coerceBucketId(value: unknown): string | null {
  if (value === undefined || value === null) return null;
  const id = String(value).trim();
  if (!id || PLACEHOLDER_BUCKET_IDS.has(id)) return null;
  return id;
}

function rawBucketStringField(
  raw: Record<string, unknown>,
  key: string,
  fallback = "0",
): string {
  const v = raw[key];
  if (v === undefined || v === null || v === "") return fallback;
  return String(v);
}

/**
 * Normalize partial or wire-format bucket payloads into RawBucket.
 * Returns null when bucket id is missing or invalid.
 */
export function normalizeRawBucketInput(input: unknown): RawBucket | null {
  if (!input || typeof input !== "object") return null;
  const raw = input as Record<string, unknown>;
  const bucketId = coerceBucketId(raw.bucketId ?? raw.id);
  if (!bucketId) return null;

  const marginTypeRaw = raw.bucketType ?? raw.marginType ?? raw.type ?? "cross";
  const now = new Date().toISOString();

  return {
    bucketId,
    address: String(raw.address ?? ""),
    bucketType: String(marginTypeRaw),
    collateralAssetIndex: String(raw.collateralAssetIndex ?? "1"),
    depositedMargin: rawBucketStringField(raw, "depositedMargin"),
    totalEquity: rawBucketStringField(raw, "totalEquity"),
    availableMargin: rawBucketStringField(raw, "availableMargin"),
    usedMargin: rawBucketStringField(raw, "usedMargin"),
    unrealizedProfit: rawBucketStringField(raw, "unrealizedProfit"),
    unrealizedLoss: rawBucketStringField(raw, "unrealizedLoss"),
    realizedProfit: rawBucketStringField(raw, "realizedProfit"),
    realizedLoss: rawBucketStringField(raw, "realizedLoss"),
    marginRatio: rawBucketStringField(raw, "marginRatio"),
    imr: rawBucketStringField(raw, "imr"),
    totalNotionalValue: rawBucketStringField(raw, "totalNotionalValue"),
    riskLevel: String(raw.riskLevel ?? ""),
    maxLeverage: rawBucketStringField(raw, "maxLeverage", "0"),
    correlationOffset:
      typeof raw.correlationOffset === "number" ? raw.correlationOffset : 0,
    status: String(raw.status ?? ""),
    createdAt: String(raw.createdAt ?? now),
    updatedAt: String(raw.updatedAt ?? now),
    sequenceId: String(raw.sequenceId ?? "0"),
  };
}

/** Whether a transformed bucket has a valid id for display and downstream actions. */
export function isDisplayableBucket(
  bucket: Bucket | null | undefined,
): bucket is Bucket {
  return bucket != null && coerceBucketId(bucket.bucketId) != null;
}

/**
 * Transform unknown API/WS bucket payload to Bucket, or null when invalid.
 */
export function rawInputToBucket(input: unknown): Bucket | null {
  if (input == null || typeof input !== "object") return null;
  const normalized = isRawBucket(input as RawBucket | MultiFeedBucketData)
    ? normalizeRawBucketInput(input)
    : normalizeRawBucketInput(
        convertMultiFeedToRawBucket(input as MultiFeedBucketData),
      );
  if (!normalized) return null;
  return transformRawBucketToBucket(normalized);
}

/** Transform and validate a list of bucket payloads; drops invalid entries. */
export function rawInputsToBuckets(inputs: unknown[]): Bucket[] {
  return inputs
    .map(rawInputToBucket)
    .filter((bucket): bucket is Bucket => isDisplayableBucket(bucket));
}

/** User-facing empty-state copy for the bucket collections table. */
export function getBucketCollectionEmptyMessage(
  collections: Bucket[],
  visibleCount: number,
  filterMode: "all" | "non-zero" | "dormant" | "active",
): string {
  const displayable = collections.filter(isDisplayableBucket);
  if (displayable.length === 0) {
    return collections.length === 0
      ? "No bucket collections found. Make sure your wallet address is correct and has buckets."
      : `${collections.length} bucket(s) received but none had a valid bucket ID.`;
  }
  if (visibleCount > 0) return "";
  switch (filterMode) {
    case "non-zero":
      return `All ${displayable.length} bucket(s) have zero equity. Switch to All to view them.`;
    case "active":
      return `No active buckets (${displayable.length} total). Try All or Dormant.`;
    case "dormant":
      return `No dormant buckets (${displayable.length} total). Try All or Active.`;
    default:
      return "No buckets match the current filter.";
  }
}

/**
 * Convert MultiFeedBucketData to RawBucket format
 * MultiFeedBucketData has fewer fields, so we provide defaults for missing fields
 * This is a pure function with no dependencies, suitable for use outside React hooks
 * @param multiFeedBucket - MultiFeedBucketData from WebSocket subscription
 * @returns RawBucket object with all required fields
 */
export function convertMultiFeedToRawBucket(
  multiFeedBucket: MultiFeedBucketData,
): RawBucket {
  const now = new Date().toISOString();
  const bucketId = coerceBucketId(multiFeedBucket.bucketId) ?? "";
  return {
    bucketId,
    address: multiFeedBucket.address,
    bucketType: multiFeedBucket.marginType,
    collateralAssetIndex: "1",
    depositedMargin: "0",
    totalEquity: multiFeedBucket.totalEquity,
    availableMargin: multiFeedBucket.availableMargin,
    usedMargin: multiFeedBucket.usedMargin,
    unrealizedProfit: multiFeedBucket.unrealizedProfit,
    unrealizedLoss: multiFeedBucket.unrealizedLoss,
    realizedProfit: "0",
    realizedLoss: "0",
    marginRatio: "0",
    imr: "0",
    totalNotionalValue: "0",
    riskLevel: "low",
    maxLeverage: "0",
    correlationOffset: 0,
    status: "active",
    createdAt: now,
    updatedAt: now,
    sequenceId: "0",
  };
}

/**
 * Convert raw API bucket data (camelCase) to Bucket type.
 */
export function transformRawBucketToBucket(rawBucket: RawBucket): Bucket {
  const bucketId = coerceBucketId(rawBucket.bucketId) ?? "";
  const unrealizedProfitBigInt = toBigInt(rawBucket.unrealizedProfit ?? "0");
  const unrealizedLossBigInt = toBigInt(rawBucket.unrealizedLoss ?? "0");
  const unrealizedPnLBigInt = unrealizedProfitBigInt - unrealizedLossBigInt;
  const unrealizedPnL = fromSatoshi(unrealizedPnLBigInt.toString());
  const unrealizedProfit = toNumberFromSatoshi(rawBucket.unrealizedProfit ?? "0");
  const unrealizedLoss = toNumberFromSatoshi(rawBucket.unrealizedLoss ?? "0");
  const maxLeverage = parseNumericValue(rawBucket.maxLeverage);
  const marginType = rawBucket.bucketType ?? "cross";
  const collateralAssetIndex = rawBucket.collateralAssetIndex ?? "1";
  const collateralAsset =
    COLLATERAL_INDEX_TO_TICKER[collateralAssetIndex] ?? "USDC";
  return {
    bucketId,
    address: rawBucket.address || "",
    marginType: marginType.toLowerCase().includes("isolated") ? "isolated" : "cross",
    collateralAssetIndex,
    collateralAsset,
    depositedMargin: toNumberFromSatoshi(rawBucket.depositedMargin ?? "0"),
    totalEquity: toNumberFromSatoshi(rawBucket.totalEquity ?? "0"),
    availableMargin: toNumberFromSatoshi(rawBucket.availableMargin ?? "0"),
    usedMargin: toNumberFromSatoshi(rawBucket.usedMargin ?? "0"),
    unrealizedProfit,
    unrealizedLoss,
    realizedProfit: toNumberFromSatoshi(rawBucket.realizedProfit ?? "0"),
    realizedLoss: toNumberFromSatoshi(rawBucket.realizedLoss ?? "0"),
    unrealizedPnL,
    marginRatio: toNumberFromSatoshi(rawBucket.marginRatio ?? "0"),
    imr: toNumberFromSatoshi(rawBucket.imr ?? "0"),
    totalNotionalValue: toNumberFromSatoshi(rawBucket.totalNotionalValue ?? "0"),
    riskLevel: rawBucket.riskLevel || "",
    maxLeverage,
    correlationOffset: rawBucket.correlationOffset ?? 0,
    status: rawBucket.status || "",
    createdAt: timestampToISOString(rawBucket.createdAt),
    updatedAt: timestampToISOString(rawBucket.updatedAt),
    leverage: maxLeverage,
    marginMode: marginType,
    raw: rawBucket,
  };
}

/**
 * Calculate risk ratio for a bucket (used margin / total equity)
 * Returns a value between 0 and 1
 */
export function calculateRiskRatio(bucket: Bucket): number {
  return bucket.totalEquity > 0
    ? Math.min(Math.max(bucket.usedMargin / bucket.totalEquity, 0), 1)
    : 0;
}

/**
 * Calculate cross margin ratio for a bucket (used margin / total equity)
 */
export function calculateCrossMarginRatio(bucket: Bucket): number {
  return bucket.totalEquity > 0 ? bucket.usedMargin / bucket.totalEquity : 0;
}

/**
 * Get display margin type name from bucket
 */
export function getDisplayMarginType(bucket: Bucket): string {
  const marginTypeValue = bucket.marginMode || bucket.marginType || "cross";
  return marginTypeValue === "ISOLATED" || marginTypeValue === "isolated"
    ? "ISOLATED"
    : "CROSS";
}

// ============================================================================
// TYPE GUARDS
// ============================================================================

/**
 * Type guard to check if a bucket is RawBucket
 */
export function isRawBucket(
  bucket: RawBucket | MultiFeedBucketData,
): bucket is RawBucket {
  return "collateralAssetIndex" in bucket;
}

/**
 * Type guard for LastPriceData
 */
export function isLastPriceData(value: any): value is LastPriceData {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.price === "number" &&
    typeof value.marketIndex === "string" &&
    typeof value.quantity === "number" &&
    typeof value.timestamp === "number" &&
    typeof value.isBuyerMaker === "boolean" &&
    typeof value.tradeId === "string"
  );
}

/**
 * Type guard for MarkPriceData
 */
export function isMarkPriceData(value: any): value is MarkPriceData {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.symbol === "string" &&
    typeof value.markPrice === "number" &&
    typeof value.timestamp === "number"
  );
}
