import { useMemo } from "react";
import {
  deriveSelectedAgentId,
  useTradingAgentStore,
  selectAgentCount,
  selectMemoryPreview,
} from "../store/tradingAgentStore";
import type { TradingAgent } from "../store/types";

export interface UseTradingAgentsResult {
  agents: TradingAgent[];
  selectedAgentIds: string[];
  selectedAgentId: string | null;
  agentCount: number;
  addAgent: ReturnType<typeof useTradingAgentStore.getState>["addAgent"];
  updateAgentMemory: ReturnType<
    typeof useTradingAgentStore.getState
  >["updateAgentMemory"];
  appendMemoryNote: ReturnType<
    typeof useTradingAgentStore.getState
  >["appendMemoryNote"];
  setSelectedAgentId: ReturnType<
    typeof useTradingAgentStore.getState
  >["setSelectedAgentId"];
  toggleFleetAgent: ReturnType<
    typeof useTradingAgentStore.getState
  >["toggleFleetAgent"];
  selectAllAgents: ReturnType<
    typeof useTradingAgentStore.getState
  >["selectAllAgents"];
  clearFleetSelection: ReturnType<
    typeof useTradingAgentStore.getState
  >["clearFleetSelection"];
  getAgentById: ReturnType<typeof useTradingAgentStore.getState>["getAgentById"];
  supervisors: ReturnType<typeof useTradingAgentStore.getState>["supervisors"];
  getSupervisorById: ReturnType<
    typeof useTradingAgentStore.getState
  >["getSupervisorById"];
  getAgentsBySupervisor: ReturnType<
    typeof useTradingAgentStore.getState
  >["getAgentsBySupervisor"];
  getAgentsByFleet: ReturnType<
    typeof useTradingAgentStore.getState
  >["getAgentsByFleet"];
  resolveDefaultAgentId: ReturnType<
    typeof useTradingAgentStore.getState
  >["resolveDefaultAgentId"];
  getMemoryPreview: (agentId: string) => string;
}

export function useTradingAgents(): UseTradingAgentsResult {
  const agents = useTradingAgentStore((s) => s.agents);
  const supervisors = useTradingAgentStore((s) => s.supervisors);
  const selectedAgentIds = useTradingAgentStore((s) => s.selectedAgentIds);
  const addAgent = useTradingAgentStore((s) => s.addAgent);
  const updateAgentMemory = useTradingAgentStore((s) => s.updateAgentMemory);
  const appendMemoryNote = useTradingAgentStore((s) => s.appendMemoryNote);
  const setSelectedAgentId = useTradingAgentStore((s) => s.setSelectedAgentId);
  const toggleFleetAgent = useTradingAgentStore((s) => s.toggleFleetAgent);
  const selectAllAgents = useTradingAgentStore((s) => s.selectAllAgents);
  const clearFleetSelection = useTradingAgentStore((s) => s.clearFleetSelection);
  const getAgentById = useTradingAgentStore((s) => s.getAgentById);
  const getSupervisorById = useTradingAgentStore((s) => s.getSupervisorById);
  const getAgentsBySupervisor = useTradingAgentStore((s) => s.getAgentsBySupervisor);
  const getAgentsByFleet = useTradingAgentStore((s) => s.getAgentsByFleet);
  const resolveDefaultAgentId = useTradingAgentStore(
    (s) => s.resolveDefaultAgentId,
  );

  const selectedAgentId = useMemo(
    () => deriveSelectedAgentId(selectedAgentIds),
    [selectedAgentIds],
  );

  const agentCount = useMemo(() => selectAgentCount(agents), [agents]);

  const getMemoryPreview = useMemo(
    () => (agentId: string) =>
      selectMemoryPreview(getAgentById(agentId)),
    [getAgentById],
  );

  return {
    agents,
    selectedAgentIds,
    selectedAgentId,
    agentCount,
    addAgent,
    updateAgentMemory,
    appendMemoryNote,
    setSelectedAgentId,
    toggleFleetAgent,
    selectAllAgents,
    clearFleetSelection,
    getAgentById,
    supervisors,
    getSupervisorById,
    getAgentsBySupervisor,
    getAgentsByFleet,
    resolveDefaultAgentId,
    getMemoryPreview,
  };
}
