import { useMemo } from "react";
import type { LineData, UTCTimestamp } from "lightweight-charts";
import type { TradeHistoryRow } from "../sdk/types/data";
import { mockPortfolioAccount } from "../../offline/mock_data";
import { getMockDailyPnlData } from "../components/portfolio/portfolioDailyPnlMock";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { useBucketCollections } from "./useBucketCollections";
import { usePositions } from "./usePositions";
import { useTradeHistory } from "./useTradeHistory";
import { useTradingAgents } from "./useTradingAgents";
import { useAgentTasks } from "./useAgentTasks";
import { buildTaskAgentMap, buildAgentBucketIds } from "../utils/agentFilter";
import {
  buildCumulativePnlSeries,
  buildDailyPnlByDay,
  buildAnchoredEquityCurveData,
  buildFocusEquityBreakdown,
  buildFocusEquityComparisonSeries,
  buildFocusVsFleetEquity,
  buildFocusVolume14d,
  computeDailyPnlSummary,
  scaleDailyPnlByDay,
  scaleDailyPnlSummary,
  type DailyPnlDay,
  type DailyPnlSummary,
  type PortfolioPnlSeries,
} from "../utils/portfolioChartData";
import {
  perpsRateToDisplayPct,
  resolvePerpsFeeTier,
} from "../utils/portfolioFeeSchedule";
import {
  buildFleetEdgeMetrics,
  type FleetEdgeSummary,
} from "../utils/portfolioFleetEdgeMetrics";
import {
  buildAgentRankMetrics,
  type AgentRankSummary,
} from "../utils/portfolioAgentRankMetrics";
import type { PortfolioTimeRange } from "../utils/portfolioChartData";
import type { TradingAgent } from "../store/types";

const ATTRIBUTION_COLORS = [
  "#38bdf8",
  "#34d399",
  "#a78bfa",
  "#fbbf24",
  "#fb7185",
  "#94a3b8",
  "#f472b6",
  "#2dd4bf",
  "#818cf8",
];

const FOURTEEN_DAYS_MS = 14 * 24 * 60 * 60 * 1000;

export interface EquityBreakdownSegment {
  id: string;
  label: string;
  value: number;
  color: string;
}

export interface AgentLeaderboardRow {
  id: string;
  label: string;
  icon?: string;
  revenue30d: number;
  roiPct: number;
  winRate: number;
  closedPnl: number;
}

export interface FocusVolume14d {
  focus: number;
  otherAgents: number;
}

export interface PortfolioAnalytics {
  accountEquity: number;
  agentManagedEquityPct: number;
  netAgentPnl30d: number;
  roiPct: number;
  successRatePct: number;
  pendingTasks: number;
  activeTasks: number;
  equityCurveData: LineData<UTCTimestamp>[];
  cumulativePnlSeries: PortfolioPnlSeries[];
  equityBreakdown: EquityBreakdownSegment[];
  volume14d: { agent: number; manual: number };
  feeTier: { tier: number; takerRatePct: number; makerRatePct: number };
  leaderboard: AgentLeaderboardRow[];
  unrealizedByAgent: { id: string; label: string; value: number; color: string }[];
  dailyPnlSummary: DailyPnlSummary;
  dailyPnlByDay: DailyPnlDay[];
  trades: TradeHistoryRow[];
  taskAgentMap: Map<string, string>;
  fleetEdgeByRange: Record<PortfolioTimeRange, FleetEdgeSummary>;
  agentRankByRange: Record<PortfolioTimeRange, AgentRankSummary>;
  focusVolume14d: FocusVolume14d | null;
  focusEquityBreakdown: EquityBreakdownSegment[] | null;
  focusVsFleetEquity: EquityBreakdownSegment[] | null;
  focusEquityCurveSeries: PortfolioPnlSeries[] | null;
  focusDailyPnlSummary: DailyPnlSummary | null;
  focusDailyPnlByDay: DailyPnlDay[] | null;
  focusAgentBucketEquity: number;
}

export interface UsePortfolioAnalyticsConfig {
  baseURL: string;
  walletAddress: string;
  filterAgentIds: string[];
  focusAgentId?: string | null;
  refreshInterval?: number;
}

function filterAgentsByFleet(
  agents: TradingAgent[],
  filterAgentIds: string[],
): TradingAgent[] {
  if (filterAgentIds.length === 0) return agents;
  const fleet = new Set(filterAgentIds);
  return agents.filter((a) => fleet.has(a.id));
}

function agentColor(index: number): string {
  return ATTRIBUTION_COLORS[index % ATTRIBUTION_COLORS.length]!;
}

export function usePortfolioAnalytics({
  baseURL,
  walletAddress,
  filterAgentIds,
  focusAgentId = null,
  refreshInterval = 5000,
}: UsePortfolioAnalyticsConfig): PortfolioAnalytics {
  const { collections, spotWalletBalance } = useBucketCollections({
    baseURL,
    walletAddress,
  });
  const { positions } = usePositions({ baseURL, walletAddress });
  const { trades } = useTradeHistory({
    baseURL,
    walletAddress,
    refreshInterval,
  });
  const { agents, getAgentById } = useTradingAgents();
  const { tasks } = useAgentTasks();

  const taskAgentMap = useMemo(() => buildTaskAgentMap(tasks), [tasks]);
  const scopedAgents = useMemo(
    () => filterAgentsByFleet(agents, filterAgentIds),
    [agents, filterAgentIds],
  );

  const accountEquity = useMemo(() => {
    const bucketEquity = collections.reduce(
      (sum, bucket) => sum + bucket.totalEquity,
      0,
    );
    return spotWalletBalance + bucketEquity;
  }, [collections, spotWalletBalance]);

  const agentManagedEquityPct = useMemo(() => {
    if (accountEquity <= 0) return 0;
    let agentNotional = 0;
    for (const position of positions) {
      const taskId = position.agentTaskId;
      const agentId = taskId ? taskAgentMap.get(taskId) : undefined;
      if (!agentId) continue;
      if (
        filterAgentIds.length > 0 &&
        !filterAgentIds.includes(agentId)
      ) {
        continue;
      }
      agentNotional += Math.abs(position.size ?? 0) * (position.entryPrice ?? 0);
    }
    return Math.min(100, (agentNotional / accountEquity) * 100);
  }, [positions, taskAgentMap, accountEquity, filterAgentIds]);

  const netAgentPnl30d = useMemo(
    () =>
      scopedAgents.reduce((sum, agent) => sum + (agent.revenue30d ?? 0), 0),
    [scopedAgents],
  );

  const roiPct = useMemo(() => {
    const baseline = Math.max(accountEquity - netAgentPnl30d, 1);
    return (netAgentPnl30d / baseline) * 100;
  }, [accountEquity, netAgentPnl30d]);

  const taskStats = useMemo(() => {
    const scopedTasks =
      filterAgentIds.length === 0
        ? tasks
        : tasks.filter((t) => filterAgentIds.includes(t.agentId));
    const active = scopedTasks.filter(
      (t) => t.status === "executing" || t.status === "watching",
    ).length;
    const pending = scopedTasks.filter((t) => t.status === "pending").length;
    const completed = scopedTasks.filter((t) => t.status === "completed").length;
    const total = scopedTasks.length;
    const successRatePct = total > 0 ? (completed / total) * 100 : 0;
    return { active, pending, successRatePct };
  }, [tasks, filterAgentIds]);

  const equityCurveData = useMemo(() => {
    const seed = mockPortfolioAccount.equityCurve;
    const shaped =
      filterAgentIds.length === 0
        ? seed
        : seed.map(
            (v) =>
              v *
              Math.max(0.4, scopedAgents.length / Math.max(agents.length, 1)),
          );
    return buildAnchoredEquityCurveData(shaped, accountEquity);
  }, [
    filterAgentIds,
    scopedAgents.length,
    agents.length,
    accountEquity,
  ]);

  const cutoff = useMemo(() => Date.now() - FOURTEEN_DAYS_MS, []);

  const trades14d = useMemo(
    () => trades.filter((t) => t.time >= cutoff),
    [trades, cutoff],
  );

  const volume14d = useMemo(() => {
    let agentVol = 0;
    let manualVol = 0;
    for (const trade of trades14d) {
      const notional = trade.size * trade.price;
      const agentId = trade.agentTaskId
        ? taskAgentMap.get(trade.agentTaskId)
        : undefined;
      const inFleet =
        filterAgentIds.length === 0 ||
        (agentId != null && filterAgentIds.includes(agentId));
      if (!inFleet && filterAgentIds.length > 0) continue;

      if (trade.agentTaskId) agentVol += notional;
      else manualVol += notional;
    }
    return { agent: agentVol, manual: manualVol };
  }, [trades14d, taskAgentMap, filterAgentIds]);

  const feeTier = useMemo(() => {
    const volTotal = volume14d.agent + volume14d.manual;
    const tier = resolvePerpsFeeTier(volTotal);
    return {
      tier: tier.tier,
      takerRatePct: perpsRateToDisplayPct(tier.takerRate),
      makerRatePct: perpsRateToDisplayPct(tier.makerRate),
    };
  }, [volume14d]);

  const cumulativePnlSeries = useMemo(
    () =>
      buildCumulativePnlSeries(
        trades,
        taskAgentMap,
        filterAgentIds,
        (agentId) => getAgentById(agentId)?.displayName ?? agentId.slice(0, 8),
        agentColor,
      ),
    [trades, taskAgentMap, filterAgentIds, getAgentById],
  );

  const equityBreakdown = useMemo(() => {
    const segments: EquityBreakdownSegment[] = [
      {
        id: "spot",
        label: "Spot wallet",
        value: spotWalletBalance,
        color: "#64748b",
      },
    ];
    let colorIdx = 0;
    for (const bucket of collections) {
      segments.push({
        id: bucket.bucketId,
        label: `${bucket.marginType ?? "Cross"} · ${bucket.bucketId.slice(0, 6)}…`,
        value: bucket.totalEquity,
        color: agentColor(colorIdx++),
      });
    }
    return segments.filter((s) => s.value > 0);
  }, [collections, spotWalletBalance]);

  const unrealizedByAgent = useMemo(() => {
    const totals = new Map<string, number>();
    let manual = 0;
    for (const position of positions) {
      const pnl = position.unrealizedPnL ?? 0;
      const agentId = position.agentTaskId
        ? taskAgentMap.get(position.agentTaskId)
        : undefined;
      if (
        filterAgentIds.length > 0 &&
        agentId &&
        !filterAgentIds.includes(agentId)
      ) {
        continue;
      }
      if (!agentId) {
        manual += pnl;
        continue;
      }
      totals.set(agentId, (totals.get(agentId) ?? 0) + pnl);
    }
    const rows = [...totals.entries()]
      .map(([id, value], index) => ({
        id,
        label: getAgentById(id)?.displayName ?? id.slice(0, 8),
        value,
        color: agentColor(index),
      }))
      .sort((a, b) => Math.abs(b.value) - Math.abs(a.value));
    if (manual !== 0 && filterAgentIds.length === 0) {
      rows.push({
        id: "manual",
        label: "Manual (M)",
        value: manual,
        color: "#94a3b8",
      });
    }
    return rows;
  }, [positions, taskAgentMap, filterAgentIds, getAgentById]);

  const leaderboard = useMemo(() => {
    const closedByAgent = new Map<string, { pnl: number; wins: number; total: number }>();
    for (const trade of trades14d) {
      const agentId = trade.agentTaskId
        ? taskAgentMap.get(trade.agentTaskId)
        : undefined;
      if (!agentId) continue;
      if (filterAgentIds.length > 0 && !filterAgentIds.includes(agentId)) {
        continue;
      }
      const entry = closedByAgent.get(agentId) ?? { pnl: 0, wins: 0, total: 0 };
      const pnl = trade.closedPnl ?? 0;
      entry.pnl += pnl;
      entry.total += 1;
      if (pnl > 0) entry.wins += 1;
      closedByAgent.set(agentId, entry);
    }

    return scopedAgents
      .map((agent) => {
        const closed = closedByAgent.get(agent.id);
        const revenue = agent.revenue30d ?? 0;
        const baseline = Math.max(accountEquity / Math.max(scopedAgents.length, 1), 1);
        return {
          id: agent.id,
          label: agent.displayName,
          icon: agent.icon,
          revenue30d: revenue,
          roiPct: (revenue / baseline) * 100,
          winRate: closed ? (closed.wins / closed.total) * 100 : 0,
          closedPnl: closed?.pnl ?? 0,
        };
      })
      .sort((a, b) => b.revenue30d - a.revenue30d);
  }, [
    scopedAgents,
    trades14d,
    taskAgentMap,
    filterAgentIds,
    accountEquity,
  ]);

  const totalUnrealized = useMemo(
    () =>
      unrealizedByAgent.reduce((sum, row) => sum + row.value, 0),
    [unrealizedByAgent],
  );

  const dailyPnlMock = useMemo(() => getMockDailyPnlData(), []);

  const dailyPnlSummary = useMemo(() => {
    if (isOfflineMode(baseURL)) return dailyPnlMock.summary;
    return computeDailyPnlSummary(
      trades,
      filterAgentIds,
      taskAgentMap,
      accountEquity,
      totalUnrealized,
    );
  }, [
    baseURL,
    dailyPnlMock.summary,
    trades,
    filterAgentIds,
    taskAgentMap,
    accountEquity,
    totalUnrealized,
  ]);

  const dailyPnlByDay = useMemo(() => {
    if (isOfflineMode(baseURL)) return dailyPnlMock.days;
    const now = new Date();
    return buildDailyPnlByDay(
      trades,
      filterAgentIds,
      taskAgentMap,
      now.getFullYear(),
      now.getMonth(),
    );
  }, [baseURL, dailyPnlMock.days, trades, filterAgentIds, taskAgentMap]);

  const fleetEdgeByRange = useMemo(() => {
    const ranges: PortfolioTimeRange[] = ["all", "30d", "7d", "24h"];
    const byRange = {} as Record<PortfolioTimeRange, FleetEdgeSummary>;
    for (const timeRange of ranges) {
      byRange[timeRange] = buildFleetEdgeMetrics({
        agents: scopedAgents,
        trades,
        taskAgentMap,
        filterAgentIds,
        timeRange,
        accountEquity,
        agentColor,
      });
    }
    return byRange;
  }, [
    scopedAgents,
    trades,
    taskAgentMap,
    filterAgentIds,
    accountEquity,
  ]);

  const agentRankByRange = useMemo(() => {
    const ranges: PortfolioTimeRange[] = ["all", "30d", "7d", "24h"];
    const byRange = {} as Record<PortfolioTimeRange, AgentRankSummary>;
    for (const timeRange of ranges) {
      byRange[timeRange] = buildAgentRankMetrics({
        agents: scopedAgents,
        trades,
        taskAgentMap,
        filterAgentIds,
        timeRange,
        accountEquity,
        agentColor,
      });
    }
    return byRange;
  }, [
    scopedAgents,
    trades,
    taskAgentMap,
    filterAgentIds,
    accountEquity,
  ]);

  const focusAgentBucketIds = useMemo(() => {
    if (!focusAgentId) return null;
    return buildAgentBucketIds(tasks, focusAgentId);
  }, [tasks, focusAgentId]);

  const focusAgentBucketEquity = useMemo(() => {
    if (!focusAgentBucketIds) return 0;
    return collections
      .filter((bucket) => focusAgentBucketIds.has(String(bucket.bucketId)))
      .reduce((sum, bucket) => sum + bucket.totalEquity, 0);
  }, [collections, focusAgentBucketIds]);

  const focusVolume14d = useMemo(() => {
    if (!focusAgentId) return null;
    return buildFocusVolume14d(trades14d, taskAgentMap, focusAgentId, cutoff);
  }, [focusAgentId, trades14d, taskAgentMap, cutoff]);

  const focusEquityBreakdown = useMemo(() => {
    if (!focusAgentId || !focusAgentBucketIds) return null;
    return buildFocusEquityBreakdown(
      focusAgentId,
      focusAgentBucketIds,
      collections,
      spotWalletBalance,
    );
  }, [
    focusAgentId,
    focusAgentBucketIds,
    collections,
    spotWalletBalance,
  ]);

  const focusVsFleetEquity = useMemo(() => {
    if (!focusAgentId) return null;
    const agentLabel =
      getAgentById(focusAgentId)?.displayName ?? focusAgentId.slice(0, 8);
    return buildFocusVsFleetEquity(
      focusAgentId,
      agentLabel,
      focusAgentBucketEquity,
      accountEquity,
    );
  }, [
    focusAgentId,
    focusAgentBucketEquity,
    accountEquity,
    getAgentById,
  ]);

  const focusEquityCurveSeries = useMemo(() => {
    if (!focusAgentId) return null;
    const offlineSeed = isOfflineMode(baseURL)
      ? mockPortfolioAccount.equityCurve
      : undefined;
    return buildFocusEquityComparisonSeries(
      trades,
      taskAgentMap,
      focusAgentId,
      accountEquity,
      focusAgentBucketEquity,
      (agentId) => getAgentById(agentId)?.displayName ?? agentId.slice(0, 8),
      offlineSeed,
    );
  }, [
    focusAgentId,
    trades,
    taskAgentMap,
    accountEquity,
    focusAgentBucketEquity,
    getAgentById,
    baseURL,
  ]);

  const focusAgentUnrealized = useMemo(() => {
    if (!focusAgentId) return 0;
    return (
      unrealizedByAgent.find((row) => row.id === focusAgentId)?.value ?? 0
    );
  }, [focusAgentId, unrealizedByAgent]);

  const focusDailyPnlSummary = useMemo(() => {
    if (!focusAgentId) return null;

    if (isOfflineMode(baseURL)) {
      const scale =
        accountEquity > 0
          ? focusAgentBucketEquity / accountEquity
          : 1 / Math.max(agents.length, 1);
      return scaleDailyPnlSummary(
        dailyPnlMock.summary,
        scale,
        dailyPnlMock.summary,
      );
    }

    const agentSummary = computeDailyPnlSummary(
      trades,
      [focusAgentId],
      taskAgentMap,
      focusAgentBucketEquity || accountEquity,
      focusAgentUnrealized,
    );
    return {
      ...agentSummary,
      fleetTotalPnl: dailyPnlSummary.totalPnl,
      agentPctOfFleetTotal:
        dailyPnlSummary.totalPnl !== 0
          ? (agentSummary.totalPnl / dailyPnlSummary.totalPnl) * 100
          : 0,
    };
  }, [
    focusAgentId,
    baseURL,
    accountEquity,
    focusAgentBucketEquity,
    agents.length,
    dailyPnlMock.summary,
    trades,
    taskAgentMap,
    focusAgentUnrealized,
    dailyPnlSummary.totalPnl,
  ]);

  const focusDailyPnlByDay = useMemo(() => {
    if (!focusAgentId) return null;

    if (isOfflineMode(baseURL)) {
      const scale =
        accountEquity > 0
          ? focusAgentBucketEquity / accountEquity
          : 1 / Math.max(agents.length, 1);
      return scaleDailyPnlByDay(dailyPnlMock.days, scale);
    }

    const now = new Date();
    return buildDailyPnlByDay(
      trades,
      [focusAgentId],
      taskAgentMap,
      now.getFullYear(),
      now.getMonth(),
    );
  }, [
    focusAgentId,
    baseURL,
    accountEquity,
    focusAgentBucketEquity,
    agents.length,
    dailyPnlMock.days,
    trades,
    taskAgentMap,
  ]);

  return {
    accountEquity,
    agentManagedEquityPct,
    netAgentPnl30d,
    roiPct,
    successRatePct: taskStats.successRatePct,
    pendingTasks: taskStats.pending,
    activeTasks: taskStats.active,
    equityCurveData,
    cumulativePnlSeries,
    equityBreakdown,
    volume14d,
    feeTier,
    leaderboard,
    unrealizedByAgent,
    dailyPnlSummary,
    dailyPnlByDay,
    trades,
    taskAgentMap,
    fleetEdgeByRange,
    agentRankByRange,
    focusVolume14d,
    focusEquityBreakdown,
    focusVsFleetEquity,
    focusEquityCurveSeries,
    focusDailyPnlSummary,
    focusDailyPnlByDay,
    focusAgentBucketEquity,
  };
}
