/** Minimum intent cards shown in the command/guardrail deck. */
export const DECK_MIN_VISIBLE_INTENTS = 4;

/** Fallback before first layout measure. */
export const DECK_DEFAULT_VISIBLE_INTENTS = 5;

/** Hard cap — deck is a summary surface; full list lives in console/tabs. */
export const DECK_MAX_VISIBLE_INTENTS = 10;

/** Guardrail cards include extras row — taller estimate when HIL polish active. */
export const DECK_GUARDRAIL_ESTIMATED_CARD_HEIGHT_PX = 168;

/** Vertical gap between deck cards — matches var(--terminal-space-3). */
export const DECK_CARD_GAP_PX = 8;

/** Fallback card height before first layout measure. */
export const DECK_ESTIMATED_CARD_HEIGHT_PX = 88;

export type DeckCapacityOptions = {
  min?: number;
  max?: number;
  fallback?: number;
  estimatedCardHeightPx?: number;
};

export function computeEstimatedDeckCapacity(
  availableHeightPx: number,
  estimatedCardHeightPx = DECK_ESTIMATED_CARD_HEIGHT_PX,
  options: DeckCapacityOptions = {},
): number {
  const min = options.min ?? DECK_MIN_VISIBLE_INTENTS;
  const max = options.max ?? DECK_MAX_VISIBLE_INTENTS;
  const fallback = options.fallback ?? DECK_DEFAULT_VISIBLE_INTENTS;

  if (availableHeightPx <= 0) return fallback;

  const unit = estimatedCardHeightPx + DECK_CARD_GAP_PX;
  const estimated = Math.floor((availableHeightPx + DECK_CARD_GAP_PX) / unit);
  return Math.min(max, Math.max(min, estimated));
}

/**
 * How many intent cards fit in the cards viewport (newest-first order).
 * Only counts measured card heights — no extrapolation beyond rendered cards
 * (avoids capacity ↔ render feedback loops).
 */
export function computeDeckVisibleCapacity(
  availableHeightPx: number,
  cardHeightsPx: number[],
  options: DeckCapacityOptions = {},
): number {
  const min = options.min ?? DECK_MIN_VISIBLE_INTENTS;
  const max = options.max ?? DECK_MAX_VISIBLE_INTENTS;
  const fallback = options.fallback ?? DECK_DEFAULT_VISIBLE_INTENTS;
  const estimatedCardHeightPx =
    options.estimatedCardHeightPx ?? DECK_ESTIMATED_CARD_HEIGHT_PX;

  if (availableHeightPx <= 0) return fallback;

  if (cardHeightsPx.length === 0) {
    return computeEstimatedDeckCapacity(
      availableHeightPx,
      estimatedCardHeightPx,
      options,
    );
  }

  let used = 0;
  let fit = 0;

  for (const height of cardHeightsPx) {
    const gap = fit > 0 ? DECK_CARD_GAP_PX : 0;
    if (used + gap + height > availableHeightPx + 0.5) break;
    used += gap + height;
    fit += 1;
  }

  if (fit === 0) {
    return Math.min(max, min);
  }

  return Math.min(max, Math.max(min, fit));
}
