import React from "react";
import { createPortal } from "react-dom";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
} from "../ui/overlay";
import type { UseBucketModalOverlayResult } from "./useBucketModalOverlay";

export interface BucketModalShellProps {
  overlayOpen: boolean;
  onClose: () => void;
  overlay: UseBucketModalOverlayResult;
  ariaLabel: string;
  panelClassName: string;
  children: React.ReactNode;
}

function BucketModalShell({
  overlayOpen,
  onClose,
  overlay,
  ariaLabel,
  panelClassName,
  children,
}: BucketModalShellProps): JSX.Element | null {
  const { isMobile, mounted, panelOpen, backdropVisible, backdropStyle, isClosing } =
    overlay;

  useOverlayEscapeKey(overlayOpen, onClose);

  if (!mounted) return null;

  const panelClassNames = [
    "modal-content",
    "terminal-overlay-panel-shell",
    panelClassName,
    isMobile ? "bucket-modal-panel--sheet" : "staggered-overlay-panel--scale",
    isClosing ? "bucket-modal-panel--closing" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const modalContent = (
    <StaggeredOverlayRoot
      passThrough={!overlayOpen}
      className={
        isMobile ? "bucket-modal-overlay bucket-modal-overlay--sheet" : undefined
      }
    >
      <StaggeredOverlayBackdrop
        visible={backdropVisible && overlayOpen}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={panelClassNames}
        aria-label={ariaLabel}
      >
        {children}
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(BucketModalShell);
