import type { UTCTimestamp } from "lightweight-charts";
import React, { useCallback, useEffect, useMemo, useRef, useState, type JSX, type PointerEvent } from "react";
import { useSettings } from "../../context/SettingsContext";
import KlineChart, {
  type ChartOverlayLayout,
  type KlineChartRef,
  type MarkerInteractionPoint,
} from "./KlineChart";
import KlineChartLoadingOverlay from "./KlineChartLoadingOverlay";
import ExecutionMarkerBubble from "./ExecutionMarkerBubble";
import ChartOrderBubble from "./ChartOrderBubble";
import PendingOrderPriceTag from "./PendingOrderPriceTag";
import { parseHeightPx, toBinanceInterval } from "./klineUtil";
import { canStepChartInterval, stepChartInterval } from "./chartIntervalScale";
import { useBinanceKline } from "../../hooks/useBinanceKline";
import { useChartExecutionMarkers } from "../../hooks/useChartExecutionMarkers";
import { useChartPendingOrderLines } from "../../hooks/useChartPendingOrderLines";
import { usePendingOrderCancel } from "../../hooks/usePendingOrderCancel";
import { usePendingOrderPriceDrag } from "../../hooks/usePendingOrderPriceDrag";
import AgentTaskDetailModal from "../tables/AgentTaskDetailModal";
import { DEFAULT_REFRESH_INTERVAL } from "../../constants";
import type { AgentTask } from "../../store/types";
import {
  type ChartTradeFocusRequest,
  intervalToSeconds,
  snapTimeToCandleInterval,
} from "./chartMarkers";
import PendingLegendFilterMenu from "./PendingLegendFilterMenu";
import { matchesPendingOrderLineFilters, type PendingOrderLineFilters } from "./chartOrderLines";
import { isDraggablePendingLine } from "./pendingOrderLineAnchor";
import "./finchart.css";
import "../tables/agentTasks.css";

const KLINE_FETCH_LIMIT = 500;

export interface KlineChartWidgetProps {
  symbol?: string;
  interval?: string;
  height?: string;
  className?: string;
  restBaseUrl?: string;
  limit?: number;
  marketId?: string;
  baseAsset?: string;
  walletAddress?: string;
  baseURL?: string;
  authToken?: string;
  mnemonic?: string;
  showExecutionMarkers?: boolean;
  showPendingOrderLines?: boolean;
  tradeFocus?: ChartTradeFocusRequest | null;
}

interface ActiveMarker {
  tradeId: string;
  x: number;
  y: number;
}

interface ActiveOrderLine {
  lineId: string;
  x: number;
  y: number;
}

function KlineChartWidget({
  symbol = "BINANCE:BTCUSDT",
  interval = "5m",
  height,
  className = "",
  restBaseUrl,
  limit,
  marketId = "",
  baseAsset = "",
  walletAddress,
  baseURL = "",
  authToken,
  mnemonic,
  showExecutionMarkers = true,
  showPendingOrderLines = true,
  tradeFocus = null,
}: KlineChartWidgetProps): JSX.Element {
  const chartRef = useRef<KlineChartRef>(null);
  const overlayHostRef = useRef<HTMLDivElement>(null);
  const layoutRootRef = useRef<HTMLDivElement>(null);
  const lastBarSignatureRef = useRef<string | null>(null);
  const pinToLatestMarkerRef = useRef(false);
  const tagPointerInsideRef = useRef(false);
  const { settings, setSettings } = useSettings();
  const [selectedAgentTask, setSelectedAgentTask] = useState<AgentTask | null>(null);
  const [hoveredMarker, setHoveredMarker] = useState<ActiveMarker | null>(null);
  const [pinnedMarker, setPinnedMarker] = useState<ActiveMarker | null>(null);
  const [hoveredOrderLine, setHoveredOrderLine] = useState<ActiveOrderLine | null>(null);
  const [pinnedOrderLine, setPinnedOrderLine] = useState<ActiveOrderLine | null>(null);
  const [overlayLayout, setOverlayLayout] = useState<ChartOverlayLayout | null>(null);
  const [chartReady, setChartReady] = useState(false);
  /** True after first successful chart paint; overlay legend toggles must not remount or show loading. */
  const [initialLoadDone, setInitialLoadDone] = useState(false);
  /** Opens after trade history resolves; 1s settle when fills exist. */
  const [markerHydrationGateOpen, setMarkerHydrationGateOpen] = useState(true);
  const [chartInterval, setChartInterval] = useState(() => toBinanceInterval(interval));

  useEffect(() => {
    setChartInterval(toBinanceInterval(interval));
  }, [interval]);

  const { candles, volumeByTime, loading, error, isConnected, symbol: binanceSymbol, interval: binanceInterval } =
    useBinanceKline({
      symbol,
      interval: chartInterval,
      limit: limit ?? KLINE_FETCH_LIMIT,
      restBaseUrl,
    });

  const currentPrice =
    candles.length > 0 ? candles[candles.length - 1]!.close : null;

  const executionMarkersEnabled =
    showExecutionMarkers && Boolean(marketId) && Boolean(baseURL);
  const pendingOrderLinesEnabled =
    showPendingOrderLines && Boolean(marketId) && Boolean(baseURL);
  const chartOverlaysEnabled = executionMarkersEnabled || pendingOrderLinesEnabled;

  const { markers, metaByTradeId, loading: tradesLoading } = useChartExecutionMarkers({
    baseURL,
    walletAddress,
    authToken,
    marketId,
    baseAsset,
    interval: chartInterval,
    enabled: executionMarkersEnabled,
    refreshInterval: DEFAULT_REFRESH_INTERVAL,
  });

  const MARKER_HYDRATION_SETTLE_MS = 1000;

  useEffect(() => {
    if (!executionMarkersEnabled) {
      if (!initialLoadDone) {
        setMarkerHydrationGateOpen(true);
      }
      return;
    }

    // Overlay re-enabled after first paint — markers hydrate in place, no remount/settle wait.
    if (initialLoadDone) {
      setMarkerHydrationGateOpen(true);
      return;
    }

    if (tradesLoading) {
      setMarkerHydrationGateOpen(false);
      return;
    }

    // Trade history confirmed empty for this market — skip marker settle wait.
    if (markers.length === 0) {
      setMarkerHydrationGateOpen(true);
      return;
    }

    setMarkerHydrationGateOpen(false);
    const settleTimer = window.setTimeout(() => {
      setMarkerHydrationGateOpen(true);
    }, MARKER_HYDRATION_SETTLE_MS);

    return () => {
      window.clearTimeout(settleTimer);
    };
  }, [
    executionMarkersEnabled,
    initialLoadDone,
    tradesLoading,
    markers.length,
    marketId,
    baseAsset,
    symbol,
    chartInterval,
  ]);

  const pendingOrderLineFilters = settings.chartOverlays.pendingOrderLineFilters;

  const { lines: orderLines, metaByLineId, overflowCount } = useChartPendingOrderLines({
    baseURL,
    walletAddress,
    authToken,
    marketId,
    currentPrice,
    enabled: pendingOrderLinesEnabled,
    refreshInterval: DEFAULT_REFRESH_INTERVAL,
    filters: pendingOrderLineFilters,
  });

  const { draggingLineId, draftPrices, startDrag } = usePendingOrderPriceDrag({
    chartRef,
    baseURL,
    mnemonic,
    walletAddress,
    marketId,
  });

  const { cancelingLineId, cancelLine } = usePendingOrderCancel({
    baseURL,
    mnemonic,
    walletAddress,
    marketId,
    metaByLineId,
  });

  const handleMarkerHover = useCallback(
    (tradeId: string | null, point: MarkerInteractionPoint | null) => {
      if (!tradeId || !point) {
        setHoveredMarker(null);
        return;
      }
      setHoveredMarker({ tradeId, x: point.x, y: point.y });
    },
    [],
  );

  const handleMarkerClick = useCallback(
    (tradeId: string | null, point: MarkerInteractionPoint | null) => {
      if (!tradeId || !point) {
        setPinnedMarker(null);
        return;
      }
      setPinnedMarker((current) =>
        current?.tradeId === tradeId ? null : { tradeId, x: point.x, y: point.y },
      );
    },
    [],
  );

  const handleOrderLineHover = useCallback(
    (lineId: string | null, point: MarkerInteractionPoint | null) => {
      if (draggingLineId) return;
      if (!lineId || !point) {
        if (!tagPointerInsideRef.current) {
          setHoveredOrderLine(null);
        }
        return;
      }
      setHoveredOrderLine({ lineId, x: point.x, y: point.y });
    },
    [draggingLineId],
  );

  const handleOrderLineClick = useCallback(
    (lineId: string | null, point: MarkerInteractionPoint | null) => {
      if (!lineId || !point) {
        setPinnedOrderLine(null);
        return;
      }
      setPinnedOrderLine((current) =>
        current?.lineId === lineId ? null : { lineId, x: point.x, y: point.y },
      );
    },
    [],
  );

  const handleViewTaskFromTrade = useCallback(
    (tradeId: string) => {
      const meta = metaByTradeId.get(tradeId);
      if (meta?.kind === "agent" && meta.task) {
        setSelectedAgentTask(meta.task);
      }
    },
    [metaByTradeId],
  );

  const handleViewTaskFromLine = useCallback(
    (lineId: string) => {
      const meta = metaByLineId.get(lineId);
      if (meta?.kind === "agent" && meta.task) {
        setSelectedAgentTask(meta.task);
      }
    },
    [metaByLineId],
  );

  const handleOverlayLayout = useCallback((layout: ChartOverlayLayout) => {
    setOverlayLayout(layout);
  }, []);

  const handleActiveAnchorMove = useCallback((tradeId: string, point: MarkerInteractionPoint) => {
    setHoveredMarker((current) =>
      current?.tradeId === tradeId ? { tradeId, x: point.x, y: point.y } : current,
    );
    setPinnedMarker((current) =>
      current?.tradeId === tradeId ? { tradeId, x: point.x, y: point.y } : current,
    );
  }, []);

  const handleActiveOrderLineAnchorMove = useCallback(
    (lineId: string, point: MarkerInteractionPoint) => {
      setHoveredOrderLine((current) =>
        current?.lineId === lineId ? { lineId, x: point.x, y: point.y } : current,
      );
      setPinnedOrderLine((current) =>
        current?.lineId === lineId ? { lineId, x: point.x, y: point.y } : current,
      );
    },
    [],
  );

  useEffect(() => {
    if (!draggingLineId || !chartRef.current) return;
    const meta = metaByLineId.get(draggingLineId);
    if (!meta) return;
    const price = draftPrices.get(draggingLineId) ?? meta.price;
    const y = chartRef.current.priceToCoordinate(price);
    if (y == null) return;
    setHoveredOrderLine((current) =>
      current?.lineId === draggingLineId ? { ...current, y } : current,
    );
  }, [draftPrices, draggingLineId, metaByLineId]);

  useEffect(() => {
    lastBarSignatureRef.current = null;
    setHoveredMarker(null);
    setPinnedMarker(null);
    setHoveredOrderLine(null);
    setPinnedOrderLine(null);
    setOverlayLayout(null);
    setChartReady(false);
    setInitialLoadDone(false);
    setMarkerHydrationGateOpen(!executionMarkersEnabled);
    pinToLatestMarkerRef.current = executionMarkersEnabled;
  }, [symbol, marketId, baseAsset]);

  useEffect(() => {
    lastBarSignatureRef.current = null;
    setChartReady(false);
    pinToLatestMarkerRef.current = false;
  }, [chartInterval]);

  useEffect(() => {
    if (chartReady) {
      setInitialLoadDone(true);
    }
  }, [chartReady]);

  useEffect(() => {
    if (loading) return;
    if (!tradeFocus || !executionMarkersEnabled || tradeFocus.marketId !== marketId) return;
    if (candles.length === 0 || !chartRef.current) return;

    const snappedTime = snapTimeToCandleInterval(tradeFocus.time, chartInterval);
    const halfWindowSec = 30 * intervalToSeconds(chartInterval);
    const chart = chartRef.current;
    const applyFocus = () => {
      chart.scrollToTime(snappedTime, halfWindowSec);
      chart.repushOverlays?.();
    };
    applyFocus();
    requestAnimationFrame(() => {
      requestAnimationFrame(applyFocus);
    });
    setHoveredMarker(null);
    setPinnedMarker({ tradeId: tradeFocus.tradeId, x: 0, y: 0 });
  }, [tradeFocus, marketId, candles.length, chartInterval, executionMarkersEnabled, loading]);

  useEffect(() => {
    if (loading || !chartReady || candles.length === 0 || !chartRef.current) return;

    const latest = candles[candles.length - 1]!;
    const openTimeMs = (latest.time as number) * 1000;
    const volume = volumeByTime.get(latest.time as number);
    const signature = `${openTimeMs}:${latest.open}:${latest.high}:${latest.low}:${latest.close}:${volume ?? ""}`;
    if (lastBarSignatureRef.current === signature) return;

    lastBarSignatureRef.current = signature;
    chartRef.current.updateChart({
      openTime: openTimeMs,
      open: latest.open,
      high: latest.high,
      low: latest.low,
      close: latest.close,
      volume,
    });
  }, [candles, loading, volumeByTime, chartReady]);

  const handleChartReady = useCallback(() => {
    setChartReady(true);
  }, []);

  useEffect(() => {
    if (!chartReady || !pendingOrderLinesEnabled || orderLines.length === 0) return;
    const applyOrderLineOverlays = () => chartRef.current?.repushOverlays?.();
    applyOrderLineOverlays();
    requestAnimationFrame(() => {
      requestAnimationFrame(applyOrderLineOverlays);
    });
  }, [chartReady, pendingOrderLinesEnabled, orderLines]);

  useEffect(() => {
    if (!pinToLatestMarkerRef.current) return;
    if (!chartReady || loading || !executionMarkersEnabled || markers.length === 0) return;
    if (!chartRef.current) return;

    pinToLatestMarkerRef.current = false;
    const maxMarkerTime = markers.reduce(
      (max, marker) => Math.max(max, marker.time as number),
      0,
    ) as UTCTimestamp;
    const halfWindowSec = 30 * intervalToSeconds(chartInterval);
    const applyMarkerViewport = () => {
      chartRef.current?.scrollToTime(maxMarkerTime, halfWindowSec);
      chartRef.current?.repushOverlays?.();
    };
    applyMarkerViewport();
    requestAnimationFrame(() => {
      requestAnimationFrame(applyMarkerViewport);
    });
  }, [chartReady, loading, executionMarkersEnabled, markers.length, chartInterval]);

  const toggleExecutionMarkers = useCallback(() => {
    setSettings((prev) => {
      const next = !prev.chartOverlays.showExecutionMarkers;
      if (!next) {
        setHoveredMarker(null);
        setPinnedMarker(null);
      }
      return {
        ...prev,
        chartOverlays: { ...prev.chartOverlays, showExecutionMarkers: next },
      };
    });
  }, [setSettings]);

  const togglePendingOrderLines = useCallback(() => {
    setSettings((prev) => {
      const next = !prev.chartOverlays.showPendingOrderLines;
      if (!next) {
        setHoveredOrderLine(null);
        setPinnedOrderLine(null);
      }
      return {
        ...prev,
        chartOverlays: { ...prev.chartOverlays, showPendingOrderLines: next },
      };
    });
  }, [setSettings]);

  const handlePendingOrderFilterChange = useCallback(
    (key: keyof PendingOrderLineFilters, value: boolean) => {
      setSettings((prev) => ({
        ...prev,
        chartOverlays: {
          ...prev.chartOverlays,
          pendingOrderLineFilters: {
            ...prev.chartOverlays.pendingOrderLineFilters,
            [key]: value,
          },
        },
      }));
    },
    [setSettings],
  );

  useEffect(() => {
    const activeLineId = pinnedOrderLine?.lineId ?? hoveredOrderLine?.lineId;
    if (!activeLineId) return;
    const meta = metaByLineId.get(activeLineId);
    if (meta && matchesPendingOrderLineFilters(meta, pendingOrderLineFilters)) return;
    setHoveredOrderLine(null);
    setPinnedOrderLine(null);
  }, [pendingOrderLineFilters, metaByLineId, pinnedOrderLine?.lineId, hoveredOrderLine?.lineId]);

  const tradesHistoryPending =
    !initialLoadDone && executionMarkersEnabled && tradesLoading;
  const markersSettlePending =
    !initialLoadDone &&
    executionMarkersEnabled &&
    !tradesLoading &&
    markers.length > 0 &&
    !markerHydrationGateOpen;
  const chartMountReady =
    !loading && (initialLoadDone || (!tradesHistoryPending && markerHydrationGateOpen));

  const isLoading = loading || tradesHistoryPending || markersSettlePending;
  const showLoadingOverlay = !error && (isLoading || !chartReady);
  const displaySymbol = symbol.includes(":") ? symbol : `BINANCE:${binanceSymbol}`;
  const legendControlsEligible =
    Boolean(marketId) && Boolean(baseURL) && !isLoading && isConnected && candles.length > 0;
  const executionMarkersLegendOn = settings.chartOverlays.showExecutionMarkers;
  const pendingOrderLinesLegendOn = settings.chartOverlays.showPendingOrderLines;

  const activeMarker = pinnedMarker ?? hoveredMarker;
  const activeMeta = activeMarker ? metaByTradeId.get(activeMarker.tradeId) : undefined;

  const activeOrderLine = pinnedOrderLine ?? hoveredOrderLine;
  const activeOrderLineMeta = activeOrderLine
    ? metaByLineId.get(activeOrderLine.lineId)
    : undefined;

  const handleTagPointerEnter = useCallback(() => {
    tagPointerInsideRef.current = true;
  }, []);

  const handleTagPointerLeave = useCallback(() => {
    tagPointerInsideRef.current = false;
    if (!draggingLineId) {
      setHoveredOrderLine(null);
    }
  }, [draggingLineId]);

  const handlePriceTagDragStart = useCallback(
    (
      lineId: string,
      meta: NonNullable<typeof activeOrderLineMeta>,
      event: PointerEvent<HTMLButtonElement>,
    ) => {
      const y = chartRef.current?.priceToCoordinate(
        draftPrices.get(lineId) ?? meta.price,
      );
      setHoveredOrderLine((current) =>
        current?.lineId === lineId
          ? current
          : {
              lineId,
              x: overlayLayout ? overlayLayout.paneWidth * 0.75 : 0,
              y: y ?? 0,
            },
      );
      startDrag(lineId, meta, event);
    },
    [draftPrices, overlayLayout, startDrag],
  );

  const handleCoarserInterval = useCallback(() => {
    setChartInterval((prev) => stepChartInterval(prev, 1) ?? prev);
  }, []);

  const handleFinerInterval = useCallback(() => {
    setChartInterval((prev) => stepChartInterval(prev, -1) ?? prev);
  }, []);

  const canCoarserInterval = canStepChartInterval(chartInterval, 1);
  const canFinerInterval = canStepChartInterval(chartInterval, -1);

  const chartOverlay = useMemo(() => {
    if (!chartOverlaysEnabled || !overlayLayout || overlayLayout.widgetWidth === 0) return null;

    const {
      canvasOffsetLeft,
      canvasOffsetTop,
      widgetWidth,
      widgetHeight,
      paneWidth,
      priceScaleWidth,
    } = overlayLayout;

    if (pendingOrderLinesEnabled && activeOrderLine && activeOrderLineMeta) {
      const displayPrice =
        draftPrices.get(activeOrderLine.lineId) ??
        activeOrderLineMeta.price;
      const tagY = activeOrderLine.y;
      const draggable = isDraggablePendingLine(activeOrderLineMeta);
      const isDragging = draggingLineId === activeOrderLine.lineId;
      const isCanceling = cancelingLineId === activeOrderLine.lineId;

      return (
        <>
          <ChartOrderBubble
            kind={activeOrderLineMeta.kind}
            title={activeOrderLineMeta.isScaleLeg ? "Scale leg" : "Limit"}
            side={activeOrderLineMeta.side}
            size={activeOrderLineMeta.remainingQuantity}
            price={displayPrice}
            badge="Pending"
            footer={
              activeOrderLineMeta.isScaleLeg && activeOrderLineMeta.parentOrderId
                ? `Parent ${activeOrderLineMeta.parentOrderId.slice(0, 8)}…`
                : undefined
            }
            x={activeOrderLine.x + canvasOffsetLeft}
            y={tagY + canvasOffsetTop}
            containerWidth={widgetWidth}
            containerHeight={widgetHeight}
            onViewTask={
              activeOrderLineMeta.kind === "agent" && activeOrderLineMeta.task
                ? () => handleViewTaskFromLine(activeOrderLine.lineId)
                : undefined
            }
          />
          <PendingOrderPriceTag
            price={displayPrice}
            side={activeOrderLineMeta.side}
            draggable={draggable}
            dragging={isDragging}
            canceling={isCanceling}
            left={canvasOffsetLeft + paneWidth}
            top={canvasOffsetTop + tagY}
            width={Math.max(priceScaleWidth, 72)}
            onDragStart={(event) =>
              handlePriceTagDragStart(activeOrderLine.lineId, activeOrderLineMeta, event)
            }
            onCancel={() => void cancelLine(activeOrderLine.lineId, activeOrderLineMeta)}
            onPointerEnter={handleTagPointerEnter}
            onPointerLeave={handleTagPointerLeave}
          />
        </>
      );
    }

    if (executionMarkersEnabled && activeMarker && activeMeta) {
      return (
        <ExecutionMarkerBubble
          meta={activeMeta}
          x={activeMarker.x + canvasOffsetLeft}
          y={activeMarker.y + canvasOffsetTop}
          containerWidth={widgetWidth}
          containerHeight={widgetHeight}
          onViewTask={
            activeMeta.kind === "agent" && activeMeta.task
              ? () => handleViewTaskFromTrade(activeMarker.tradeId)
              : undefined
          }
        />
      );
    }

    return null;
  }, [
    activeMarker,
    activeMeta,
    activeOrderLine,
    activeOrderLineMeta,
    cancelLine,
    cancelingLineId,
    draftPrices,
    draggingLineId,
    handlePriceTagDragStart,
    handleTagPointerEnter,
    handleTagPointerLeave,
    overlayLayout,
    handleViewTaskFromLine,
    handleViewTaskFromTrade,
    chartOverlaysEnabled,
    executionMarkersEnabled,
    pendingOrderLinesEnabled,
  ]);

  return (
    <div
      className={`kline-chart-widget ${className}`.trim()}
      style={{
        width: "100%",
        height: "100%",
        minHeight: height ? parseHeightPx(height) : 0,
      }}
    >
      <div ref={overlayHostRef} className="kline-chart-widget-overlay">
        {showLoadingOverlay ? <KlineChartLoadingOverlay /> : null}
      </div>
      <div ref={layoutRootRef} className="kline-chart-widget-body">
        {chartMountReady ? (
          <KlineChart
            ref={chartRef}
            initialData={candles}
            volumeByTime={volumeByTime}
            symbol={displaySymbol}
            interval={binanceInterval}
            showVolume
            markers={markers}
            orderLines={orderLines}
            orderLinePriceOverrides={draftPrices}
            resetScrollKey={`${symbol}-${chartInterval}`}
            onCoarserInterval={handleCoarserInterval}
            onFinerInterval={handleFinerInterval}
            canCoarserInterval={canCoarserInterval}
            canFinerInterval={canFinerInterval}
            showPendingViewButton={pendingOrderLinesEnabled}
            onMarkerHover={executionMarkersEnabled ? handleMarkerHover : undefined}
            onMarkerClick={executionMarkersEnabled ? handleMarkerClick : undefined}
            onOrderLineHover={pendingOrderLinesEnabled ? handleOrderLineHover : undefined}
            onOrderLineClick={pendingOrderLinesEnabled ? handleOrderLineClick : undefined}
            overlayHostRef={overlayHostRef}
            layoutRootRef={layoutRootRef}
            onOverlayLayout={chartOverlaysEnabled ? handleOverlayLayout : undefined}
            activeTradeId={executionMarkersEnabled ? activeMarker?.tradeId ?? null : null}
            activeOrderLineId={
              pendingOrderLinesEnabled
                ? activeOrderLine?.lineId ?? draggingLineId ?? null
                : null
            }
            onActiveAnchorMove={executionMarkersEnabled ? handleActiveAnchorMove : undefined}
            onActiveOrderLineAnchorMove={
              pendingOrderLinesEnabled ? handleActiveOrderLineAnchorMove : undefined
            }
            onReady={handleChartReady}
            overlay={chartOverlay}
          />
        ) : null}
      </div>
      {!error ? (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--compact">
          {isLoading ? (
            <>Loading · {binanceInterval}</>
          ) : candles.length === 0 ? (
            <>No kline data available</>
          ) : (
            <>
              Live · {binanceInterval}
              {legendControlsEligible ? (
                <span className="kline-chart-marker-legend">
                  <button
                    type="button"
                    className={`kline-chart-marker-legend-item kline-chart-marker-legend-toggle${
                      executionMarkersLegendOn
                        ? " kline-chart-marker-legend-item--active"
                        : " kline-chart-marker-legend-item--inactive"
                    }`}
                    aria-pressed={executionMarkersLegendOn}
                    onClick={toggleExecutionMarkers}
                  >
                    <span className="kline-chart-marker-legend-swatch kline-chart-marker-legend-swatch--agent" aria-hidden />
                    Agent
                  </button>
                  <button
                    type="button"
                    className={`kline-chart-marker-legend-item kline-chart-marker-legend-toggle${
                      executionMarkersLegendOn
                        ? " kline-chart-marker-legend-item--active"
                        : " kline-chart-marker-legend-item--inactive"
                    }`}
                    aria-pressed={executionMarkersLegendOn}
                    onClick={toggleExecutionMarkers}
                  >
                    <span className="kline-chart-marker-legend-swatch kline-chart-marker-legend-swatch--manual" aria-hidden />
                    Manual
                  </button>
                  <PendingLegendFilterMenu
                    filters={pendingOrderLineFilters}
                    masterOn={pendingOrderLinesLegendOn}
                    onFilterChange={handlePendingOrderFilterChange}
                    onMasterToggle={togglePendingOrderLines}
                  />
                  {pendingOrderLinesEnabled && overflowCount > 0 ? (
                    <span className="kline-chart-marker-legend-overflow">
                      +{overflowCount} pending
                    </span>
                  ) : null}
                </span>
              ) : null}
            </>
          )}
        </div>
      ) : (
        <div className="kline-chart-status kline-chart-status--overlay terminal-label kline-chart-status--error">{error}</div>
      )}
      <AgentTaskDetailModal
        isOpen={selectedAgentTask != null}
        task={selectedAgentTask}
        baseURL={baseURL}
        authToken={authToken}
        onClose={() => setSelectedAgentTask(null)}
      />
    </div>
  );
}

export default KlineChartWidget;
