import React, { useMemo } from "react";
import type { AgentTask } from "../../store/types";
import { getGuardrailMeta } from "./guardrailMeta";
import { sortGuardrailIntents } from "./deckIntents";

export interface GuardrailSimulationPreviewProps {
  tasks: AgentTask[];
}

function GuardrailSimulationPreview({
  tasks,
}: GuardrailSimulationPreviewProps): JSX.Element {
  const pendingIntents = useMemo(
    () => sortGuardrailIntents(tasks),
    [tasks],
  );

  const aggregate = useMemo(() => {
    if (pendingIntents.length === 0) {
      return {
        avgConfidence: 0,
        maxFillBps: 0,
        highRiskCount: 0,
        note: "No pending intents in queue.",
      };
    }
    let confidenceSum = 0;
    let maxFillBps = 0;
    let highRiskCount = 0;
    for (const task of pendingIntents) {
      const meta = getGuardrailMeta(task);
      confidenceSum += meta.confidencePct;
      maxFillBps = Math.max(maxFillBps, meta.expectedFillImpactBps);
      if (meta.riskImpact === "high") highRiskCount += 1;
    }
    const avgConfidence = Math.round(confidenceSum / pendingIntents.length);
    const note =
      highRiskCount > 0
        ? `${highRiskCount} high-risk intent${highRiskCount === 1 ? "" : "s"} — review before bulk approve.`
        : "Queue looks within normal guardrail thresholds.";
    return { avgConfidence, maxFillBps, highRiskCount, note };
  }, [pendingIntents]);

  const approvedCount = useMemo(
    () =>
      tasks.filter(
        (t) =>
          t.status === "executing" ||
          t.status === "completed" ||
          (t.status === "watching" &&
            !pendingIntents.some((p) => p.id === t.id)),
      ).length,
    [tasks, pendingIntents],
  );

  const awaitingCount = pendingIntents.length;
  const totalReviewed = approvedCount + awaitingCount;
  const approvedPct =
    totalReviewed > 0 ? Math.round((approvedCount / totalReviewed) * 100) : 51;
  const awaitingPct = totalReviewed > 0 ? 100 - approvedPct : 49;

  return (
    <div className="guardrail-simulation-preview">
      <div className="guardrail-simulation-preview-head">
        <span className="guardrail-simulation-preview-title">
          Simulation preview
        </span>
        <span className="guardrail-simulation-preview-stat">
          {pendingIntents.length} pending · avg conf {aggregate.avgConfidence}%
        </span>
      </div>
      <div
        className="guardrail-simulation-preview-bar"
        role="img"
        aria-label={`Approval split ${approvedPct}% reviewed, ${awaitingPct}% awaiting`}
      >
        <div
          className="guardrail-simulation-preview-bar-segment guardrail-simulation-preview-bar-segment--approved"
          style={{ width: `${approvedPct}%` }}
        />
        <div
          className="guardrail-simulation-preview-bar-segment guardrail-simulation-preview-bar-segment--awaiting"
          style={{ width: `${awaitingPct}%` }}
        />
      </div>
      <div className="guardrail-simulation-preview-labels">
        <span>Reviewed {approvedPct}%</span>
        <span>Awaiting {awaitingPct}%</span>
      </div>
      <p className="guardrail-simulation-preview-note">
        Max est. fill {aggregate.maxFillBps.toFixed(1)} bps · {aggregate.note}
      </p>
    </div>
  );
}

export default React.memo(GuardrailSimulationPreview);
