import type { FleetTradeEvent } from "../../../offline/mock_data/fleetTradeHistory.types";

export type AgentAssetChartFocus = {
  coin: string;
  marketId: string;
  tradeId: string;
  tradeTimeMs: number;
};

export function agentAssetChartFocusFromEvent(
  event: FleetTradeEvent,
): AgentAssetChartFocus {
  return {
    coin: event.coin,
    marketId: event.marketId,
    tradeId: event.id,
    tradeTimeMs: Date.parse(event.timestamp),
  };
}
